INSERT INTO "categories" VALUES(24,'ghazal','غزلیات');
INSERT INTO "categories" VALUES(25,'qete','قطعات');
INSERT INTO "categories" VALUES(26,'robaei','رباعیات');
INSERT INTO "categories" VALUES(27,'qaside','قصاید');
INSERT INTO "categories" VALUES(674,'montasab','اشعار منتسب');
INSERT INTO "poems" VALUES(2051,26,1,'رباعی شمارهٔ ۱','جز نقش تو در نظر نیامد ما را
INSERT INTO "poems" VALUES(2052,26,2,'رباعی شمارهٔ ۲','بر گیر شراب طرب انگیز و بیا
INSERT INTO "poems" VALUES(2053,26,3,'رباعی شمارهٔ ۳','گفتم که لبت گفت لبم آب حیات
INSERT INTO "poems" VALUES(2054,26,4,'رباعی شمارهٔ ۴','ماهی که قدش به سرو می ماند راست
INSERT INTO "poems" VALUES(2055,26,5,'رباعی شمارهٔ ۵','من با کمر تو در میان کردم دست
INSERT INTO "poems" VALUES(2056,26,6,'رباعی شمارهٔ ۶','تو بدری و خورشید تو را بنده شده ست
INSERT INTO "poems" VALUES(2057,26,7,'رباعی شمارهٔ ۷','هر روز دلم به زیر باری دگر است
INSERT INTO "poems" VALUES(2058,26,8,'رباعی شمارهٔ ۸','ماهم که رخش روشنی خور بگرفت
INSERT INTO "poems" VALUES(2059,26,9,'رباعی شمارهٔ ۹','امشب ز غمت میان خون خواهم خفت
INSERT INTO "poems" VALUES(2060,26,10,'رباعی شمارهٔ ۱۰','نی قصه آن شمع چگل بتوان گفت
INSERT INTO "poems" VALUES(2061,26,11,'رباعی شمارهٔ ۱۱','اول به وفا می وصالم درداد
INSERT INTO "poems" VALUES(2062,26,12,'رباعی شمارهٔ ۱۲','نی دولت دنیا به ستم می ارزد
INSERT INTO "poems" VALUES(2063,26,13,'رباعی شمارهٔ ۱۳','هر دوست که دم زد ز وفا دشمن شد
INSERT INTO "poems" VALUES(2064,26,14,'رباعی شمارهٔ ۱۴','چون غنچه گل قرابه پرداز شود
INSERT INTO "poems" VALUES(2065,26,15,'رباعی شمارهٔ ۱۵','با می به کنار جوی می باید بود
INSERT INTO "poems" VALUES(2066,26,16,'رباعی شمارهٔ ۱۶','این گل ز بر هم نفسی می آید
INSERT INTO "poems" VALUES(2067,26,17,'رباعی شمارهٔ ۱۷','از چرخ به هر گونه همی دار امید
INSERT INTO "poems" VALUES(2068,26,18,'رباعی شمارهٔ ۱۸','ایام شباب ست شراب اولاتر
INSERT INTO "poems" VALUES(2069,26,19,'رباعی شمارهٔ ۱۹','خوبان جهان صید توان کرد به زر
INSERT INTO "poems" VALUES(2070,26,20,'رباعی شمارهٔ ۲۰','سیلاب گرفت گرد ویرانه عمر
INSERT INTO "poems" VALUES(2071,26,21,'رباعی شمارهٔ ۲۱','عشق رخ یار بر من زار مگیر
INSERT INTO "poems" VALUES(2072,26,22,'رباعی شمارهٔ ۲۲','در سنبلش آویختم از روی نیاز
INSERT INTO "poems" VALUES(2073,26,23,'رباعی شمارهٔ ۲۳','مردی ز کننده در خیبر پرس
INSERT INTO "poems" VALUES(2074,26,24,'رباعی شمارهٔ ۲۴','چشم تو که سحر بابل است استادش
INSERT INTO "poems" VALUES(2075,26,25,'رباعی شمارهٔ ۲۵','ای دوست دل از جفای دشمن درکش
INSERT INTO "poems" VALUES(2076,26,26,'رباعی شمارهٔ ۲۶','ماهی که نظیر خود ندارد به جمال
INSERT INTO "poems" VALUES(2077,26,27,'رباعی شمارهٔ ۲۷','در باغ چو شد باد صبا دایه گل
INSERT INTO "poems" VALUES(2078,26,28,'رباعی شمارهٔ ۲۸','لب باز مگیر یک زمان از لب جام
INSERT INTO "poems" VALUES(2079,26,29,'رباعی شمارهٔ ۲۹','در آرزوی بوس و کنارت مردم
INSERT INTO "poems" VALUES(2080,26,30,'رباعی شمارهٔ ۳۰','عمری ز پی مراد ضایع دارم
INSERT INTO "poems" VALUES(2081,26,31,'رباعی شمارهٔ ۳۱','من حاصل عمر خود ندارم جز غم
INSERT INTO "poems" VALUES(2082,26,32,'رباعی شمارهٔ ۳۲','چون باده ز غم چه بایدت جوشیدن
INSERT INTO "poems" VALUES(2083,26,33,'رباعی شمارهٔ ۳۳','ای شرم زده غنچه ی مستور از تو
INSERT INTO "poems" VALUES(2084,26,34,'رباعی شمارهٔ ۳۴','چشمت که فسون و رنگ می بارد از او
INSERT INTO "poems" VALUES(2085,26,35,'رباعی شمارهٔ ۳۵','ای باد حدیث من نهانش می گو
INSERT INTO "poems" VALUES(2086,26,36,'رباعی شمارهٔ ۳۶','ای سایه سنبلت سمن پرورده
INSERT INTO "poems" VALUES(2087,26,37,'رباعی شمارهٔ ۳۷','گفتی که تو را شوم مدار اندیشه
INSERT INTO "poems" VALUES(2088,26,38,'رباعی شمارهٔ ۳۸','آن جام طرب شکار بر دستم نه
INSERT INTO "poems" VALUES(2089,26,39,'رباعی شمارهٔ ۳۹','با شاهد شوخ شنگ و با بربط و نی
INSERT INTO "poems" VALUES(2090,26,40,'رباعی شمارهٔ ۴۰','قسام بهشت و دوزخ آن عقده گشای
INSERT INTO "poems" VALUES(2091,26,41,'رباعی شمارهٔ ۴۱','ای کاش که بخت سازگاری کردی
INSERT INTO "poems" VALUES(2092,26,42,'رباعی شمارهٔ ۴۲','گر همچو من افتاده این دام شوی
INSERT INTO "poems" VALUES(2093,25,1,'قطعه شمارهٔ ۱','تو نیک و بد خود هم از خود بپرس
INSERT INTO "poems" VALUES(2094,25,2,'قطعه شمارهٔ ۲','سرای مدرسه و بحث علم و طاق و رواق
INSERT INTO "poems" VALUES(2095,25,3,'قطعه شمارهٔ ۳ - ماده تاریخ وفات تورانشاه (میل بهشت = ۷۸۷)','ماده تاریخ وفات تورانشاه میل بهشت = ۷۸۷
INSERT INTO "poems" VALUES(2096,25,4,'قطعه شمارهٔ ۴ - ماده تاریخ وفات (قرب طاعت = ۷۸۲) ','ماده تاریخ وفات قرب طاعت = ۷۸۲
INSERT INTO "poems" VALUES(2097,25,5,'قطعه شمارهٔ ۵','قوت شاعره من سحر از فرط ملال
INSERT INTO "poems" VALUES(2098,25,6,'قطعه شمارهٔ ۶ - ماده تاریخ (رحمان لایموت = ۷۸۶)','ماده تاریخ رحمان لایموت = ۷۸۶
INSERT INTO "poems" VALUES(2099,25,7,'قطعه شمارهٔ ۷','به عهد سلطنت شاه شیخ ابواسحاق
INSERT INTO "poems" VALUES(2100,25,8,'قطعه شمارهٔ ۸','خسروا گوی فلک در خم چوگان تو شد
INSERT INTO "poems" VALUES(2101,25,9,'قطعه شمارهٔ ۹','دادگرا تو را فلک جرعه کش پیاله باد
INSERT INTO "poems" VALUES(2102,25,10,'قطعه شمارهٔ ۱۰','روح القدس آن سروش فرخ
INSERT INTO "poems" VALUES(2103,25,11,'قطعه شمارهٔ ۱۱','به سمع خواجه رسان ای ندیم وقت شناس
INSERT INTO "poems" VALUES(2104,25,12,'قطعه شمارهٔ ۱۲','شمه ای از داستان عشق شورانگیز ماست
INSERT INTO "poems" VALUES(2105,25,13,'قطعه شمارهٔ ۱۳ - ماده تاریخ وفات (امیذ جود)','ماده تاریخ وفات امیذ جود
INSERT INTO "poems" VALUES(2106,25,14,'قطعه شمارهٔ ۱۴','دل منه بر دنیی و اسباب او
INSERT INTO "poems" VALUES(2107,25,15,'قطعه شمارهٔ ۱۵','بر سر بازار جانبازان منادی می زنند
INSERT INTO "poems" VALUES(2108,25,16,'قطعه شمارهٔ ۱۶ - ماده تاریخ وفات (خلیل عادل = ۷۷۵)','ماده تاریخ وفات خلیل عادل = ۷۷۵
INSERT INTO "poems" VALUES(2109,25,17,'قطعه شمارهٔ ۱۷','بر تو خوانم ز دفتر اخلاق
INSERT INTO "poems" VALUES(2110,25,18,'قطعه شمارهٔ ۱۸','زآن حبه ی خضراخور کز روی سبک روحی
INSERT INTO "poems" VALUES(2111,25,19,'قطعه شمارهٔ ۱۹ - ماده تاریخ وفات (رحمت حق = ۷۵۶)','ماده تاریخ وفات رحمت حق = ۷۵۶
INSERT INTO "poems" VALUES(2112,25,20,'قطعه شمارهٔ ۲۰ - ماده تاریخ وفات (بلبل، سرو، سمن، یاسمن، لاله، گل = ۷۵۷)','ماده تاریخ وفات بلبل سرو سمن یاسمن لاله گل = ۷۵۷
INSERT INTO "poems" VALUES(2113,25,21,'قطعه شمارهٔ ۲۱','سال و فال و مال و حال و اصل و نسل و تخت و بخت
INSERT INTO "poems" VALUES(2114,25,22,'قطعه شمارهٔ ۲۲','سرور اهل عمایم شمع جمع انجمن
INSERT INTO "poems" VALUES(2115,25,23,'قطعه شمارهٔ ۲۳','دلا دیدی که آن فرزانه فرزند
INSERT INTO "poems" VALUES(2116,25,24,'قطعه شمارهٔ ۲۴','در این ظلمت سرا تا کی به بوی دوست بنشینم
INSERT INTO "poems" VALUES(2117,25,25,'قطعه شمارهٔ ۲۵','ای معرا اصل عالی جوهرت از حرص و آز
INSERT INTO "poems" VALUES(2118,25,26,'قطعه شمارهٔ ۲۶','ساقیا پیمانه پر کن زانکه صاحب مجلست
INSERT INTO "poems" VALUES(2119,25,27,'قطعه شمارهٔ ۲۷','به گوش جان رهی منهیی ندا در داد
INSERT INTO "poems" VALUES(2120,25,28,'قطعه شمارهٔ ۲۸','به روز شنبه سادس ز ماه ذی الحجه
INSERT INTO "poems" VALUES(2121,25,29,'قطعه شمارهٔ ۲۹','به من سلام فرستاد دوستی امروز
INSERT INTO "poems" VALUES(2122,25,30,'قطعه شمارهٔ ۳۰','گدا اگر گهر پاک داشتی در اصل
INSERT INTO "poems" VALUES(2123,25,31,'قطعه شمارهٔ ۳۱ - ماده تاریخ (میوهٔ بهشتی = ۷۷۸)','ماده تاریخ میوه بهشتی = ۷۷۸
INSERT INTO "poems" VALUES(2124,25,32,'قطعه شمارهٔ ۳۲','خسروا دادگرا شیردلا بحرکفا
INSERT INTO "poems" VALUES(2125,25,33,'قطعه شمارهٔ ۳۳','ساقیا باده که اکسیر حیات است بیار
INSERT INTO "poems" VALUES(2126,25,34,'قطعه شمارهٔ ۳۴','پادشاها لشکر توفیق همراه تواند
INSERT INTO "poems" VALUES(2127,27,1,'قصیدهٔ شمارهٔ ۱ - در مدح شاه شجاع','در مدح شاه شجاع
INSERT INTO "poems" VALUES(2128,27,2,'قصیدهٔ شمارهٔ ۲ - قصیدهٔ در مدح قوام الدین محمد صاحب عیار وزیر شاه شجاع','قصیده در مدح قوام الدین محمد صاحب عیار وزیر شاه شجاع
INSERT INTO "poems" VALUES(2129,27,3,'قصیدهٔ شمارهٔ ۳ - قصیدهٔ در مدح شاه شیخ ابواسحاق','قصیده در مدح شاه شیخ ابواسحاق
INSERT INTO "poems" VALUES(2130,24,1,'غزل شمارهٔ ۱','الا یا ایها الساقی ادر کأسا و ناولها
INSERT INTO "poems" VALUES(2131,24,2,'غزل شمارهٔ ۲','صلاح کار کجا و من خراب کجا
INSERT INTO "poems" VALUES(2132,24,3,'غزل شمارهٔ ۳','اگر آن ترک شیرازی به   دست  آرد دل ما را
INSERT INTO "poems" VALUES(2133,24,4,'غزل شمارهٔ ۴','صبا به لطف بگو آن غزال رعنا را
INSERT INTO "poems" VALUES(2134,24,5,'غزل شمارهٔ ۵','دل می رود ز دستم صاحب دلان خدا را
INSERT INTO "poems" VALUES(2135,24,6,'غزل شمارهٔ ۶','به ملازمان سلطان که رساند این دعا را
INSERT INTO "poems" VALUES(2136,24,7,'غزل شمارهٔ ۷','صوفی بیا که آینه صافی ست جام را
INSERT INTO "poems" VALUES(2137,24,8,'غزل شمارهٔ ۸','ساقیا برخیز و درده جام را
INSERT INTO "poems" VALUES(2138,24,9,'غزل شمارهٔ ۹','رونق عهد شباب است دگر بستان را
INSERT INTO "poems" VALUES(2139,24,10,'غزل شمارهٔ ۱۰','دوش از مسجد سوی میخانه آمد پیر ما
INSERT INTO "poems" VALUES(2140,24,11,'غزل شمارهٔ ۱۱','ساقی به نور باده برافروز جام ما
INSERT INTO "poems" VALUES(2141,24,12,'غزل شمارهٔ ۱۲','ای فروغ ماه حسن  از روی رخشان شما
INSERT INTO "poems" VALUES(2142,24,13,'غزل شمارهٔ ۱۳','می دمد صبح و کله بست سحاب
INSERT INTO "poems" VALUES(2143,24,14,'غزل شمارهٔ ۱۴','گفتم ای سلطان خوبان رحم کن بر این غریب
INSERT INTO "poems" VALUES(2144,24,15,'غزل شمارهٔ ۱۵','ای شاهد قدسی که کشد بند نقابت
INSERT INTO "poems" VALUES(2145,24,16,'غزل شمارهٔ ۱۶','خمی که ابروی شوخ تو در کمان انداخت
INSERT INTO "poems" VALUES(2146,24,17,'غزل شمارهٔ ۱۷','سینه از آتش دل در غم جانانه بسوخت
INSERT INTO "poems" VALUES(2147,24,18,'غزل شمارهٔ ۱۸','ساقیا آمدن عید مبارک بادت
INSERT INTO "poems" VALUES(2148,24,19,'غزل شمارهٔ ۱۹','ای نسیم سحر آرامگه یار کجاست
INSERT INTO "poems" VALUES(2149,24,20,'غزل شمارهٔ ۲۰','روزه یک سو شد و عید آمد و دل ها برخاست
INSERT INTO "poems" VALUES(2150,24,21,'غزل شمارهٔ ۲۱','دل و دینم شد و دلبر به ملامت برخاست
INSERT INTO "poems" VALUES(2151,24,22,'غزل شمارهٔ ۲۲','چو بشنوی سخن اهل دل مگو که خطاست
INSERT INTO "poems" VALUES(2152,24,23,'غزل شمارهٔ ۲۳','خیال روی تو در هر طریق همره ماست
INSERT INTO "poems" VALUES(2153,24,24,'غزل شمارهٔ ۲۴','مطلب طاعت و پیمان و صلاح از من مست
INSERT INTO "poems" VALUES(2154,24,25,'غزل شمارهٔ ۲۵','شکفته شد گل حمرا و گشت بلبل مست
INSERT INTO "poems" VALUES(2155,24,26,'غزل شمارهٔ ۲۶','زلف آشفته و خوی کرده و خندان لب و مست
INSERT INTO "poems" VALUES(2156,24,27,'غزل شمارهٔ ۲۷','در دیر مغان آمد یارم قدحی در دست
INSERT INTO "poems" VALUES(2157,24,28,'غزل شمارهٔ ۲۸','به جان خواجه و حق قدیم و عهد درست
INSERT INTO "poems" VALUES(2158,24,29,'غزل شمارهٔ ۲۹','ما را ز خیال تو چه پروای شراب است
INSERT INTO "poems" VALUES(2159,24,30,'غزل شمارهٔ ۳۰','زلفت هزار دل به یکی تار مو ببست
INSERT INTO "poems" VALUES(2160,24,31,'غزل شمارهٔ ۳۱','آن شب قدری که گویند اهل خلوت امشب است
INSERT INTO "poems" VALUES(2161,24,32,'غزل شمارهٔ ۳۲','خدا چو صورت ابروی دلگشای تو بست
INSERT INTO "poems" VALUES(2162,24,33,'غزل شمارهٔ ۳۳','خلوت گزیده را به تماشا چه حاجت است
INSERT INTO "poems" VALUES(2163,24,34,'غزل شمارهٔ ۳۴','رواق منظر چشم من آشیانه توست
INSERT INTO "poems" VALUES(2164,24,35,'غزل شمارهٔ ۳۵','برو به کار خود ای واعظ این چه فریادست
INSERT INTO "poems" VALUES(2165,24,36,'غزل شمارهٔ ۳۶','تا سر زلف تو در دست نسیم افتادست
INSERT INTO "poems" VALUES(2166,24,37,'غزل شمارهٔ ۳۷','بیا که قصر امل سخت سست بنیادست
INSERT INTO "poems" VALUES(2167,24,38,'غزل شمارهٔ ۳۸','بی مهر رخت روز مرا نور نماندست
INSERT INTO "poems" VALUES(2168,24,39,'غزل شمارهٔ ۳۹','باغ مرا چه حاجت سرو و صنوبر است
INSERT INTO "poems" VALUES(2169,24,40,'غزل شمارهٔ ۴۰','المنة لله که در میکده باز است
INSERT INTO "poems" VALUES(2170,24,41,'غزل شمارهٔ ۴۱','اگر چه باده فرح بخش و باد گل بیز است
INSERT INTO "poems" VALUES(2171,24,42,'غزل شمارهٔ ۴۲','حال دل با تو گفتنم هوس است
INSERT INTO "poems" VALUES(2172,24,43,'غزل شمارهٔ ۴۳','صحن بستان ذوق بخش و صحبت یاران خوش است
INSERT INTO "poems" VALUES(2173,24,44,'غزل شمارهٔ ۴۴','کنون که بر کف گل جام باده صاف است
INSERT INTO "poems" VALUES(2174,24,45,'غزل شمارهٔ ۴۵','در این زمانه رفیقی که خالی از خلل است
INSERT INTO "poems" VALUES(2175,24,46,'غزل شمارهٔ ۴۶','گل در بر و می در کف و معشوق به کام است
INSERT INTO "poems" VALUES(2176,24,47,'غزل شمارهٔ ۴۷','به کوی میکده هر سالکی که ره دانست
INSERT INTO "poems" VALUES(2177,24,48,'غزل شمارهٔ ۴۸','صوفی از پرتو می راز نهانی دانست
INSERT INTO "poems" VALUES(2178,24,49,'غزل شمارهٔ ۴۹','روضه خلد برین خلوت درویشان است
INSERT INTO "poems" VALUES(2179,24,50,'غزل شمارهٔ ۵۰','به دام زلف تو دل مبتلای خویشتن است
INSERT INTO "poems" VALUES(2180,24,51,'غزل شمارهٔ ۵۱','لعل سیراب به خون تشنه  لب یار من است
INSERT INTO "poems" VALUES(2181,24,52,'غزل شمارهٔ ۵۲','روزگاری ست که سودای بتان دین من است
INSERT INTO "poems" VALUES(2182,24,53,'غزل شمارهٔ ۵۳','منم که گوشه میخانه خانقاه من است
INSERT INTO "poems" VALUES(2183,24,54,'غزل شمارهٔ ۵۴','ز گریه مردم چشمم نشسته در خون است
INSERT INTO "poems" VALUES(2184,24,55,'غزل شمارهٔ ۵۵','خم زلف تو دام کفر و دین است
INSERT INTO "poems" VALUES(2185,24,56,'غزل شمارهٔ ۵۶','دل سراپرده محبت اوست
INSERT INTO "poems" VALUES(2186,24,57,'غزل شمارهٔ ۵۷','آن سیه چرده که شیرینی عالم با اوست
INSERT INTO "poems" VALUES(2187,24,58,'غزل شمارهٔ ۵۸','سر ارادت ما و آستان حضرت دوست
INSERT INTO "poems" VALUES(2188,24,59,'غزل شمارهٔ ۵۹','دارم امید عاطفتی از جناب دوست
INSERT INTO "poems" VALUES(2189,24,60,'غزل شمارهٔ ۶۰','آن پیک نامور که رسید از دیار دوست
INSERT INTO "poems" VALUES(2190,24,61,'غزل شمارهٔ ۶۱','صبا اگر گذری افتدت به کشور دوست
INSERT INTO "poems" VALUES(2191,24,62,'غزل شمارهٔ ۶۲','مرحبا ای پیک مشتاقان بده پیغام دوست
INSERT INTO "poems" VALUES(2192,24,63,'غزل شمارهٔ ۶۳','روی تو کس ندید و هزارت رقیب هست
INSERT INTO "poems" VALUES(2193,24,64,'غزل شمارهٔ ۶۴','اگر چه عرض هنر پیش یار بی ادبی ست
INSERT INTO "poems" VALUES(2194,24,65,'غزل شمارهٔ ۶۵','خوش تر ز عیش و صحبت و باغ و بهار چیست
INSERT INTO "poems" VALUES(2195,24,66,'غزل شمارهٔ ۶۶','بنال بلبل اگر با منت سر یاری ست
INSERT INTO "poems" VALUES(2196,24,67,'غزل شمارهٔ ۶۷','یا رب این شمع دل افروز ز کاشانه کیست
INSERT INTO "poems" VALUES(2197,24,68,'غزل شمارهٔ ۶۸','ماهم این هفته برون رفت و به چشمم سالی ست
INSERT INTO "poems" VALUES(2198,24,69,'غزل شمارهٔ ۶۹','کس نیست که افتاده آن زلف دوتا نیست
INSERT INTO "poems" VALUES(2199,24,70,'غزل شمارهٔ ۷۰','مردم دیده ما جز به رخت ناظر نیست
INSERT INTO "poems" VALUES(2200,24,71,'غزل شمارهٔ ۷۱','زاهد ظاهرپرست از حال ما آگاه نیست
INSERT INTO "poems" VALUES(2201,24,72,'غزل شمارهٔ ۷۲','راهی ست راه عشق که هیچش کناره نیست
INSERT INTO "poems" VALUES(2202,24,73,'غزل شمارهٔ ۷۳','روشن از پرتو رویت نظری نیست که نیست
INSERT INTO "poems" VALUES(2203,24,74,'غزل شمارهٔ ۷۴','حاصل کارگه کون و مکان این همه نیست
INSERT INTO "poems" VALUES(2204,24,75,'غزل شمارهٔ ۷۵','خواب آن نرگس فتان تو بی چیزی نیست
INSERT INTO "poems" VALUES(2205,24,76,'غزل شمارهٔ ۷۶','جز آستان توام در جهان پناهی نیست
INSERT INTO "poems" VALUES(2206,24,77,'غزل شمارهٔ ۷۷','بلبلی برگ گلی خوش رنگ در منقار داشت
INSERT INTO "poems" VALUES(2207,24,78,'غزل شمارهٔ ۷۸','دیدی که یار جز سر جور و ستم نداشت
INSERT INTO "poems" VALUES(2208,24,79,'غزل شمارهٔ ۷۹','کنون که می دمد از بوستان نسیم بهشت
INSERT INTO "poems" VALUES(2209,24,80,'غزل شمارهٔ ۸۰','عیب رندان مکن ای زاهد پاکیزه سرشت
INSERT INTO "poems" VALUES(2210,24,81,'غزل شمارهٔ ۸۱','صبحدم مرغ چمن با گل نوخاسته گفت
INSERT INTO "poems" VALUES(2211,24,82,'غزل شمارهٔ ۸۲','آن ترک پری چهره که دوش از بر ما رفت
INSERT INTO "poems" VALUES(2212,24,83,'غزل شمارهٔ ۸۳','گر ز دست زلف مشکینت خطایی رفت رفت
INSERT INTO "poems" VALUES(2213,24,84,'غزل شمارهٔ ۸۴','ساقی بیار باده که ماه صیام رفت
INSERT INTO "poems" VALUES(2214,24,85,'غزل شمارهٔ ۸۵','شربتی از لب لعلش نچشیدیم و برفت
INSERT INTO "poems" VALUES(2215,24,86,'غزل شمارهٔ ۸۶','ساقی بیا که یار ز رخ پرده برگرفت
INSERT INTO "poems" VALUES(2216,24,87,'غزل شمارهٔ ۸۷','حسنت به اتفاق ملاحت جهان گرفت
INSERT INTO "poems" VALUES(2217,24,88,'غزل شمارهٔ ۸۸','شنیده ام سخنی خوش که پیر کنعان گفت
INSERT INTO "poems" VALUES(2218,24,89,'غزل شمارهٔ ۸۹','یا رب سببی ساز که یارم به سلامت
INSERT INTO "poems" VALUES(2219,24,90,'غزل شمارهٔ ۹۰','ای هدهد صبا به سبا می فرستمت
INSERT INTO "poems" VALUES(2220,24,91,'غزل شمارهٔ ۹۱','ای غایب از نظر به خدا می سپارمت
INSERT INTO "poems" VALUES(2221,24,92,'غزل شمارهٔ ۹۲','میر من خوش می روی کاندر سر و پا میرمت
INSERT INTO "poems" VALUES(2222,24,93,'غزل شمارهٔ ۹۳','چه لطف بود که ناگاه رشحه قلمت
INSERT INTO "poems" VALUES(2223,24,94,'غزل شمارهٔ ۹۴','زان یار دل نوازم شکری است با شکایت
INSERT INTO "poems" VALUES(2224,24,95,'غزل شمارهٔ ۹۵','مدامم مست می دارد نسیم جعد گیسویت
INSERT INTO "poems" VALUES(2225,24,96,'غزل شمارهٔ ۹۶','درد ما را نیست درمان الغیاث
INSERT INTO "poems" VALUES(2226,24,97,'غزل شمارهٔ ۹۷','تویی که بر سر خوبان کشوری چون تاج
INSERT INTO "poems" VALUES(2227,24,98,'غزل شمارهٔ ۹۸','اگر به مذهب تو خون عاشق است مباح
INSERT INTO "poems" VALUES(2228,24,99,'غزل شمارهٔ ۹۹','دل من در هوای روی فرخ
INSERT INTO "poems" VALUES(2229,24,100,'غزل شمارهٔ ۱۰۰','دی پیر می فروش که ذکرش به خیر باد
INSERT INTO "poems" VALUES(2230,24,101,'غزل شمارهٔ ۱۰۱','شراب و عیش نهان چیست کار بی بنیاد
INSERT INTO "poems" VALUES(2231,24,102,'غزل شمارهٔ ۱۰۲','دوش آگهی ز یار سفر کرده داد باد
INSERT INTO "poems" VALUES(2232,24,103,'غزل شمارهٔ ۱۰۳','روز وصل دوستداران یاد باد
INSERT INTO "poems" VALUES(2233,24,104,'غزل شمارهٔ ۱۰۴','جمالت آفتاب هر نظر باد
INSERT INTO "poems" VALUES(2234,24,105,'غزل شمارهٔ ۱۰۵','صوفی ار باده به اندازه خورد نوشش باد
INSERT INTO "poems" VALUES(2235,24,106,'غزل شمارهٔ ۱۰۶','تنت به ناز طبیبان نیازمند مباد
INSERT INTO "poems" VALUES(2236,24,107,'غزل شمارهٔ ۱۰۷','حسن تو همیشه در فزون باد
INSERT INTO "poems" VALUES(2237,24,108,'غزل شمارهٔ ۱۰۸','خسروا گوی فلک در خم چوگان تو باد
INSERT INTO "poems" VALUES(2238,24,109,'غزل شمارهٔ ۱۰۹','دیر است که دل دار پیامی نفرستاد
INSERT INTO "poems" VALUES(2239,24,110,'غزل شمارهٔ ۱۱۰','پیرانه سرم عشق جوانی به سر افتاد
INSERT INTO "poems" VALUES(2240,24,111,'غزل شمارهٔ ۱۱۱','عکس روی تو چو در آینه جام افتاد
INSERT INTO "poems" VALUES(2241,24,112,'غزل شمارهٔ ۱۱۲','آن که رخسار تو را رنگ گل و نسرین داد
INSERT INTO "poems" VALUES(2242,24,113,'غزل شمارهٔ ۱۱۳','بنفشه دوش به گل گفت و خوش نشانی داد
INSERT INTO "poems" VALUES(2243,24,114,'غزل شمارهٔ ۱۱۴','همای اوج سعادت به دام ما افتد
INSERT INTO "poems" VALUES(2244,24,115,'غزل شمارهٔ ۱۱۵','درخت دوستی بنشان که کام دل به بار آرد
INSERT INTO "poems" VALUES(2245,24,116,'غزل شمارهٔ ۱۱۶','کسی که حسن و خط دوست در نظر دارد
INSERT INTO "poems" VALUES(2246,24,117,'غزل شمارهٔ ۱۱۷','دل ما به دور رویت ز چمن فراغ دارد
INSERT INTO "poems" VALUES(2247,24,118,'غزل شمارهٔ ۱۱۸','آن کس که به دست جام دارد
INSERT INTO "poems" VALUES(2248,24,119,'غزل شمارهٔ ۱۱۹','دلی که غیب نمای است و جام جم دارد
INSERT INTO "poems" VALUES(2249,24,120,'غزل شمارهٔ ۱۲۰','بتی دارم که گرد گل ز سنبل سایه بان دارد
INSERT INTO "poems" VALUES(2250,24,121,'غزل شمارهٔ ۱۲۱','هر آن کاو خاطر مجموع و یار نازنین دارد
INSERT INTO "poems" VALUES(2251,24,122,'غزل شمارهٔ ۱۲۲','هر آن که جانب اهل خدا نگه دارد
INSERT INTO "poems" VALUES(2252,24,123,'غزل شمارهٔ ۱۲۳','مطرب عشق عجب ساز و نوایی دارد
INSERT INTO "poems" VALUES(2253,24,124,'غزل شمارهٔ ۱۲۴','آن که از سنبل او غالیه تابی دارد
INSERT INTO "poems" VALUES(2254,24,125,'غزل شمارهٔ ۱۲۵','شاهد آن نیست که مویی و میانی دارد
INSERT INTO "poems" VALUES(2255,24,126,'غزل شمارهٔ ۱۲۶','جان بی جمال جانان میل جهان ندارد
INSERT INTO "poems" VALUES(2256,24,127,'غزل شمارهٔ ۱۲۷','روشنی طلعت تو ماه ندارد
INSERT INTO "poems" VALUES(2257,24,128,'غزل شمارهٔ ۱۲۸','نیست در شهر نگاری که دل ما ببرد
INSERT INTO "poems" VALUES(2258,24,129,'غزل شمارهٔ ۱۲۹','اگر نه باده غم دل ز یاد ما ببرد
INSERT INTO "poems" VALUES(2259,24,130,'غزل شمارهٔ ۱۳۰','سحر بلبل حکایت با صبا کرد
INSERT INTO "poems" VALUES(2260,24,131,'غزل شمارهٔ ۱۳۱','بیا که ترک فلک خوان روزه غارت کرد
INSERT INTO "poems" VALUES(2261,24,132,'غزل شمارهٔ ۱۳۲','به آب روشن می عارفی طهارت کرد
INSERT INTO "poems" VALUES(2262,24,133,'غزل شمارهٔ ۱۳۳','صوفی نهاد دام و سر حقه باز کرد
INSERT INTO "poems" VALUES(2263,24,134,'غزل شمارهٔ ۱۳۴','بلبلی خون دلی خورد و گلی حاصل کرد
INSERT INTO "poems" VALUES(2264,24,135,'غزل شمارهٔ ۱۳۵','چو باد عزم سر کوی یار خواهم کرد
INSERT INTO "poems" VALUES(2265,24,136,'غزل شمارهٔ ۱۳۶','دست در حلقه آن زلف دوتا نتوان کرد
INSERT INTO "poems" VALUES(2266,24,137,'غزل شمارهٔ ۱۳۷','دل از من برد و روی از من نهان کرد
INSERT INTO "poems" VALUES(2267,24,138,'غزل شمارهٔ ۱۳۸','یاد باد آن که ز ما وقت سفر یاد نکرد
INSERT INTO "poems" VALUES(2268,24,139,'غزل شمارهٔ ۱۳۹','رو بر رهش نهادم و بر من گذر نکرد
INSERT INTO "poems" VALUES(2269,24,140,'غزل شمارهٔ ۱۴۰','دلبر برفت و دلشدگان را خبر نکرد
INSERT INTO "poems" VALUES(2270,24,141,'غزل شمارهٔ ۱۴۱','دیدی ای دل که غم عشق دگربار چه کرد
INSERT INTO "poems" VALUES(2271,24,142,'غزل شمارهٔ ۱۴۲','دوستان دختر رز توبه ز مستوری کرد
INSERT INTO "poems" VALUES(2272,24,143,'غزل شمارهٔ ۱۴۳','سال ها دل طلب جام جم از ما می کرد
INSERT INTO "poems" VALUES(2273,24,144,'غزل شمارهٔ ۱۴۴','به سر جام جم آنگه نظر توانی کرد
INSERT INTO "poems" VALUES(2274,24,145,'غزل شمارهٔ ۱۴۵','چه مستی است ندانم که رو به ما آورد
INSERT INTO "poems" VALUES(2275,24,146,'غزل شمارهٔ ۱۴۶','صبا وقت سحر بویی ز زلف یار می آورد
INSERT INTO "poems" VALUES(2276,24,147,'غزل شمارهٔ ۱۴۷','برید باد صبا دوشم آگهی آورد
INSERT INTO "poems" VALUES(2277,24,148,'غزل شمارهٔ ۱۴۸','یارم چو قدح به دست گیرد
INSERT INTO "poems" VALUES(2278,24,149,'غزل شمارهٔ ۱۴۹','دلم جز مهر مه رویان طریقی بر نمی گیرد
INSERT INTO "poems" VALUES(2279,24,150,'غزل شمارهٔ ۱۵۰','ساقی ار باده از این دست به جام اندازد
INSERT INTO "poems" VALUES(2280,24,151,'غزل شمارهٔ ۱۵۱','دمی با غم به سر بردن جهان یک سر نمی ارزد
INSERT INTO "poems" VALUES(2281,24,152,'غزل شمارهٔ ۱۵۲','در ازل پرتو حسنت ز تجلی دم زد
INSERT INTO "poems" VALUES(2282,24,153,'غزل شمارهٔ ۱۵۳','سحر چون خسرو خاور علم بر کوهساران زد
INSERT INTO "poems" VALUES(2283,24,154,'غزل شمارهٔ ۱۵۴','راهی بزن که آهی بر ساز آن توان زد
INSERT INTO "poems" VALUES(2284,24,155,'غزل شمارهٔ ۱۵۵','اگر روم ز پی اش فتنه ها برانگیزد
INSERT INTO "poems" VALUES(2285,24,156,'غزل شمارهٔ ۱۵۶','به حسن و خلق و وفا کس به یار ما نرسد
INSERT INTO "poems" VALUES(2286,24,157,'غزل شمارهٔ ۱۵۷','هر که را با خط سبزت سر سودا باشد
INSERT INTO "poems" VALUES(2287,24,158,'غزل شمارهٔ ۱۵۸','من و انکار شراب این چه حکایت باشد
INSERT INTO "poems" VALUES(2288,24,159,'غزل شمارهٔ ۱۵۹','نقد صوفی نه همه صافی بی غش باشد
INSERT INTO "poems" VALUES(2289,24,160,'غزل شمارهٔ ۱۶۰','خوش است خلوت اگر یار یار من باشد
INSERT INTO "poems" VALUES(2290,24,161,'غزل شمارهٔ ۱۶۱','کی شعر تر انگیزد خاطر که حزین باشد
INSERT INTO "poems" VALUES(2291,24,162,'غزل شمارهٔ ۱۶۲','خوش آمد گل وز آن خوش تر نباشد
INSERT INTO "poems" VALUES(2292,24,163,'غزل شمارهٔ ۱۶۳','گل بی رخ یار خوش نباشد
INSERT INTO "poems" VALUES(2293,24,164,'غزل شمارهٔ ۱۶۴','نفس باد صبا مشک فشان خواهد شد
INSERT INTO "poems" VALUES(2294,24,165,'غزل شمارهٔ ۱۶۵','مرا مهر سیه چشمان ز سر بیرون نخواهد شد
INSERT INTO "poems" VALUES(2295,24,166,'غزل شمارهٔ ۱۶۶','روز هجران و شب فرقت یار آخر شد
INSERT INTO "poems" VALUES(2296,24,167,'غزل شمارهٔ ۱۶۷','ستاره ای بدرخشید و ماه مجلس شد
INSERT INTO "poems" VALUES(2297,24,168,'غزل شمارهٔ ۱۶۸','گداخت جان که شود کار دل تمام و نشد
INSERT INTO "poems" VALUES(2298,24,169,'غزل شمارهٔ ۱۶۹','یاری اندر کس نمی بینیم یاران را چه شد
INSERT INTO "poems" VALUES(2299,24,170,'غزل شمارهٔ ۱۷۰','زاهد خلوت نشین دوش به میخانه شد
INSERT INTO "poems" VALUES(2300,24,171,'غزل شمارهٔ ۱۷۱','دوش از جناب آصف پیک بشارت آمد
INSERT INTO "poems" VALUES(2301,24,172,'غزل شمارهٔ ۱۷۲','عشق تو نهال حیرت آمد
INSERT INTO "poems" VALUES(2302,24,173,'غزل شمارهٔ ۱۷۳','در نمازم خم ابروی تو با یاد آمد
INSERT INTO "poems" VALUES(2303,24,174,'غزل شمارهٔ ۱۷۴','مژده ای دل که دگر باد صبا بازآمد
INSERT INTO "poems" VALUES(2304,24,175,'غزل شمارهٔ ۱۷۵','صبا به تهنیت پیر می فروش آمد
INSERT INTO "poems" VALUES(2305,24,176,'غزل شمارهٔ ۱۷۶','سحرم دولت بیدار به بالین آمد
INSERT INTO "poems" VALUES(2306,24,177,'غزل شمارهٔ ۱۷۷','نه هر که چهره برافروخت دلبری داند
INSERT INTO "poems" VALUES(2307,24,178,'غزل شمارهٔ ۱۷۸','هر که شد محرم دل در حرم یار بماند
INSERT INTO "poems" VALUES(2308,24,179,'غزل شمارهٔ ۱۷۹','رسید مژده که ایام غم نخواهد ماند
INSERT INTO "poems" VALUES(2309,24,180,'غزل شمارهٔ ۱۸۰','ای پسته تو خنده زده بر حدیث قند
INSERT INTO "poems" VALUES(2310,24,181,'غزل شمارهٔ ۱۸۱','بعد از این دست من و دامن آن سرو بلند
INSERT INTO "poems" VALUES(2311,24,182,'غزل شمارهٔ ۱۸۲','حسب حالی ننوشتی و شد ایامی چند
INSERT INTO "poems" VALUES(2312,24,183,'غزل شمارهٔ ۱۸۳','دوش وقت سحر از غصه نجاتم دادند
INSERT INTO "poems" VALUES(2313,24,184,'غزل شمارهٔ ۱۸۴','دوش دیدم که ملایک در میخانه زدند
INSERT INTO "poems" VALUES(2314,24,185,'غزل شمارهٔ ۱۸۵','نقدها را بود آیا که عیاری گیرند
INSERT INTO "poems" VALUES(2315,24,186,'غزل شمارهٔ ۱۸۶','گر می فروش حاجت رندان روا کند
INSERT INTO "poems" VALUES(2316,24,187,'غزل شمارهٔ ۱۸۷','دلا بسوز که سوز تو کارها بکند
INSERT INTO "poems" VALUES(2317,24,188,'غزل شمارهٔ ۱۸۸','مرا به رندی و عشق آن فضول عیب کند
INSERT INTO "poems" VALUES(2318,24,189,'غزل شمارهٔ ۱۸۹','طایر دولت اگر باز گذاری بکند
INSERT INTO "poems" VALUES(2319,24,190,'غزل شمارهٔ ۱۹۰','کلک مشکین تو روزی که ز ما یاد کند
INSERT INTO "poems" VALUES(2320,24,191,'غزل شمارهٔ ۱۹۱','آن کیست کز روی
INSERT INTO "poems" VALUES(2321,24,192,'غزل شمارهٔ ۱۹۲','سرو چمان من چرا میل چمن نمی کند
INSERT INTO "poems" VALUES(2322,24,193,'غزل شمارهٔ ۱۹۳','در نظربازی ما بی خبران حیران اند
INSERT INTO "poems" VALUES(2323,24,194,'غزل شمارهٔ ۱۹۴','سمن بویان غبار غم چو بنشینند بنشانند
INSERT INTO "poems" VALUES(2324,24,195,'غزل شمارهٔ ۱۹۵','غلام نرگس مست تو تاجداران اند
INSERT INTO "poems" VALUES(2325,24,196,'غزل شمارهٔ ۱۹۶','آنان که خاک را به نظر کیمیا کنند
INSERT INTO "poems" VALUES(2326,24,197,'غزل شمارهٔ ۱۹۷','شاهدان گر دلبری زین سان کنند
INSERT INTO "poems" VALUES(2327,24,198,'غزل شمارهٔ ۱۹۸','گفتم کی ام دهان و لبت کامران کنند
INSERT INTO "poems" VALUES(2328,24,199,'غزل شمارهٔ ۱۹۹','واعظان کاین جلوه در محراب و منبر می کنند
INSERT INTO "poems" VALUES(2329,24,200,'غزل شمارهٔ ۲۰۰','دانی که چنگ و عود چه تقریر می کنند
INSERT INTO "poems" VALUES(2330,24,201,'غزل شمارهٔ ۲۰۱','شراب بی غش و ساقی خوش دو دام رهند
INSERT INTO "poems" VALUES(2331,24,202,'غزل شمارهٔ ۲۰۲','بود آیا که در میکده ها بگشایند
INSERT INTO "poems" VALUES(2332,24,203,'غزل شمارهٔ ۲۰۳','سال ها دفتر ما در گرو صهبا بود
INSERT INTO "poems" VALUES(2333,24,204,'غزل شمارهٔ ۲۰۴','یاد باد آن که نهانت نظری با ما بود
INSERT INTO "poems" VALUES(2334,24,205,'غزل شمارهٔ ۲۰۵','تا ز میخانه و می نام و نشان خواهد بود
INSERT INTO "poems" VALUES(2335,24,206,'غزل شمارهٔ ۲۰۶','پیش از اینت بیش از این اندیشه عشاق بود
INSERT INTO "poems" VALUES(2336,24,207,'غزل شمارهٔ ۲۰۷','یاد باد آن که سر کوی توام منزل بود
INSERT INTO "poems" VALUES(2337,24,208,'غزل شمارهٔ ۲۰۸','خستگان را چو طلب باشد و قوت نبود
INSERT INTO "poems" VALUES(2338,24,209,'غزل شمارهٔ ۲۰۹','قتل این خسته به شمشیر تو تقدیر نبود
INSERT INTO "poems" VALUES(2339,24,210,'غزل شمارهٔ ۲۱۰','دوش در حلقه ما قصه گیسوی تو بود
INSERT INTO "poems" VALUES(2340,24,211,'غزل شمارهٔ ۲۱۱','دوش می آمد و رخساره برافروخته بود
INSERT INTO "poems" VALUES(2341,24,212,'غزل شمارهٔ ۲۱۲','یک دو جامم دی سحرگه اتفاق افتاده بود
INSERT INTO "poems" VALUES(2342,24,213,'غزل شمارهٔ ۲۱۳','گوهر مخزن اسرار همان است که بود
INSERT INTO "poems" VALUES(2343,24,214,'غزل شمارهٔ ۲۱۴','دیدم به خواب خوش که به دستم پیاله بود
INSERT INTO "poems" VALUES(2344,24,215,'غزل شمارهٔ ۲۱۵','به کوی میکده یا رب سحر چه مشغله بود
INSERT INTO "poems" VALUES(2345,24,216,'غزل شمارهٔ ۲۱۶','آن یار کز او خانه ما جای پری بود
INSERT INTO "poems" VALUES(2346,24,217,'غزل شمارهٔ ۲۱۷','مسلمانان مرا وقتی دلی بود
INSERT INTO "poems" VALUES(2347,24,218,'غزل شمارهٔ ۲۱۸','در ازل هر کو به فیض دولت ارزانی بود
INSERT INTO "poems" VALUES(2348,24,219,'غزل شمارهٔ ۲۱۹','کنون که در چمن آمد گل از عدم به وجود
INSERT INTO "poems" VALUES(2349,24,220,'غزل شمارهٔ ۲۲۰','از دیده خون دل همه بر روی ما رود
INSERT INTO "poems" VALUES(2350,24,221,'غزل شمارهٔ ۲۲۱','چو دست بر سر زلفش زنم به تاب رود
INSERT INTO "poems" VALUES(2351,24,222,'غزل شمارهٔ ۲۲۲','از سر کوی تو هر کو به ملالت برود
INSERT INTO "poems" VALUES(2352,24,223,'غزل شمارهٔ ۲۲۳','هرگزم نقش تو از لوح دل و جان نرود
INSERT INTO "poems" VALUES(2353,24,224,'غزل شمارهٔ ۲۲۴','خوشا دلی که مدام از پی نظر نرود
INSERT INTO "poems" VALUES(2354,24,225,'غزل شمارهٔ ۲۲۵','ساقی حدیث سرو و گل و لاله می رود
INSERT INTO "poems" VALUES(2355,24,226,'غزل شمارهٔ ۲۲۶','ترسم که اشک در غم ما پرده در شود
INSERT INTO "poems" VALUES(2356,24,227,'غزل شمارهٔ ۲۲۷','گر چه بر واعظ شهر این سخن آسان نشود
INSERT INTO "poems" VALUES(2357,24,228,'غزل شمارهٔ ۲۲۸','گر من از باغ تو یک میوه بچینم چه شود
INSERT INTO "poems" VALUES(2358,24,229,'غزل شمارهٔ ۲۲۹','بخت از دهان دوست نشانم نمی دهد
INSERT INTO "poems" VALUES(2359,24,230,'غزل شمارهٔ ۲۳۰','اگر به باده مشکین دلم کشد شاید
INSERT INTO "poems" VALUES(2360,24,231,'غزل شمارهٔ ۲۳۱','گفتم غم تو دارم گفتا غمت سرآید
INSERT INTO "poems" VALUES(2361,24,232,'غزل شمارهٔ ۲۳۲','بر سر آنم که گر ز دست برآید
INSERT INTO "poems" VALUES(2362,24,233,'غزل شمارهٔ ۲۳۳','دست از طلب ندارم تا کام من برآید
INSERT INTO "poems" VALUES(2363,24,234,'غزل شمارهٔ ۲۳۴','چو آفتاب می از مشرق پیاله برآید
INSERT INTO "poems" VALUES(2364,24,235,'غزل شمارهٔ ۲۳۵','زهی خجسته زمانی که یار بازآید
INSERT INTO "poems" VALUES(2365,24,236,'غزل شمارهٔ ۲۳۶','اگر آن طایر قدسی ز درم بازآید
INSERT INTO "poems" VALUES(2366,24,237,'غزل شمارهٔ ۲۳۷','نفس برآمد و کام از تو بر نمی آید
INSERT INTO "poems" VALUES(2367,24,238,'غزل شمارهٔ ۲۳۸','جهان بر ابروی عید از هلال وسمه کشید
INSERT INTO "poems" VALUES(2368,24,239,'غزل شمارهٔ ۲۳۹','رسید مژده که آمد بهار و سبزه دمید
INSERT INTO "poems" VALUES(2369,24,240,'غزل شمارهٔ ۲۴۰','ابر آذاری برآمد باد نوروزی وزید
INSERT INTO "poems" VALUES(2370,24,241,'غزل شمارهٔ ۲۴۱','معاشران ز حریف شبانه یاد آرید
INSERT INTO "poems" VALUES(2371,24,242,'غزل شمارهٔ ۲۴۲','بیا که رایت منصور پادشاه رسید
INSERT INTO "poems" VALUES(2372,24,243,'غزل شمارهٔ ۲۴۳','بوی خوش تو هر که ز باد صبا شنید
INSERT INTO "poems" VALUES(2373,24,244,'غزل شمارهٔ ۲۴۴','معاشران گره از زلف یار باز کنید
INSERT INTO "poems" VALUES(2374,24,245,'غزل شمارهٔ ۲۴۵','الا ای طوطی گویا ی اسرار
INSERT INTO "poems" VALUES(2375,24,246,'غزل شمارهٔ ۲۴۶','عید است و آخر گل و یاران در انتظار
INSERT INTO "poems" VALUES(2376,24,247,'غزل شمارهٔ ۲۴۷','صبا ز منزل جانان گذر دریغ مدار
INSERT INTO "poems" VALUES(2377,24,248,'غزل شمارهٔ ۲۴۸','ای صبا نکهتی از کوی فلانی به من آر
INSERT INTO "poems" VALUES(2378,24,249,'غزل شمارهٔ ۲۴۹','ای صبا نکهتی از خاک ره یار بیار
INSERT INTO "poems" VALUES(2379,24,250,'غزل شمارهٔ ۲۵۰','روی بنمای و وجود خودم از یاد ببر
INSERT INTO "poems" VALUES(2380,24,251,'غزل شمارهٔ ۲۵۱','شب وصل است و طی شد نامه هجر
INSERT INTO "poems" VALUES(2381,24,252,'غزل شمارهٔ ۲۵۲','گر بود عمر به میخانه رسم بار دگر
INSERT INTO "poems" VALUES(2382,24,253,'غزل شمارهٔ ۲۵۳','ای خرم از فروغ رخت لاله زار عمر
INSERT INTO "poems" VALUES(2383,24,254,'غزل شمارهٔ ۲۵۴','دیگر ز شاخ سرو سهی بلبل صبور
INSERT INTO "poems" VALUES(2384,24,255,'غزل شمارهٔ ۲۵۵','یوسف گم گشته بازآید به کنعان غم مخور
INSERT INTO "poems" VALUES(2385,24,256,'غزل شمارهٔ ۲۵۶','نصیحتی کنمت بشنو و بهانه مگیر
INSERT INTO "poems" VALUES(2386,24,257,'غزل شمارهٔ ۲۵۷','روی بنما و مرا گو که ز جان دل برگیر
INSERT INTO "poems" VALUES(2387,24,258,'غزل شمارهٔ ۲۵۸','هزار شکر که دیدم به کام خویشت باز
INSERT INTO "poems" VALUES(2388,24,259,'غزل شمارهٔ ۲۵۹','منم که دیده به دیدار دوست کردم باز
INSERT INTO "poems" VALUES(2389,24,260,'غزل شمارهٔ ۲۶۰','ای سرو ناز حسن که خوش می روی به ناز
INSERT INTO "poems" VALUES(2390,24,261,'غزل شمارهٔ ۲۶۱','درآ که در دل خسته توان درآید باز
INSERT INTO "poems" VALUES(2391,24,262,'غزل شمارهٔ ۲۶۲','حال خونین دلان که گوید باز
INSERT INTO "poems" VALUES(2392,24,263,'غزل شمارهٔ ۲۶۳','بیا و کشتی ما در شط شراب انداز
INSERT INTO "poems" VALUES(2393,24,264,'غزل شمارهٔ ۲۶۴','خیز و در کاسه زر آب طربناک انداز
INSERT INTO "poems" VALUES(2394,24,265,'غزل شمارهٔ ۲۶۵','برنیامد از تمنای لبت کامم هنوز
INSERT INTO "poems" VALUES(2395,24,266,'غزل شمارهٔ ۲۶۶','دلم رمیده لولی وشیست شورانگیز
INSERT INTO "poems" VALUES(2396,24,267,'غزل شمارهٔ ۲۶۷','ای صبا گر بگذری بر ساحل رود ارس
INSERT INTO "poems" VALUES(2397,24,268,'غزل شمارهٔ ۲۶۸','گلعذاری ز گلستان جهان ما را بس
INSERT INTO "poems" VALUES(2398,24,269,'غزل شمارهٔ ۲۶۹','دلا رفیق سفر بخت نیکخواهت بس
INSERT INTO "poems" VALUES(2399,24,270,'غزل شمارهٔ ۲۷۰','درد عشقی کشیده ام که مپرس
INSERT INTO "poems" VALUES(2400,24,271,'غزل شمارهٔ ۲۷۱','دارم از زلف سیاهش گله چندان که مپرس
INSERT INTO "poems" VALUES(2401,24,272,'غزل شمارهٔ ۲۷۲','باز آی و دل تنگ مرا مونس جان باش
INSERT INTO "poems" VALUES(2402,24,273,'غزل شمارهٔ ۲۷۳','اگر رفیق شفیقی درست پیمان باش
INSERT INTO "poems" VALUES(2403,24,274,'غزل شمارهٔ ۲۷۴','به دور لاله قدح گیر و بی ریا می باش
INSERT INTO "poems" VALUES(2404,24,275,'غزل شمارهٔ ۲۷۵','صوفی گلی بچین و مرقع به خار بخش
INSERT INTO "poems" VALUES(2405,24,276,'غزل شمارهٔ ۲۷۶','باغبان گر پنج روزی صحبت گل بایدش
INSERT INTO "poems" VALUES(2406,24,277,'غزل شمارهٔ ۲۷۷','فکر بلبل همه آن است که گل شد یارش
INSERT INTO "poems" VALUES(2407,24,278,'غزل شمارهٔ ۲۷۸','شراب تلخ می خواهم که مردافکن بود زورش
INSERT INTO "poems" VALUES(2408,24,279,'غزل شمارهٔ ۲۷۹','خوشا شیراز و وضع بی مثالش
INSERT INTO "poems" VALUES(2409,24,280,'غزل شمارهٔ ۲۸۰','چو بر شکست صبا زلف عنبرافشانش
INSERT INTO "poems" VALUES(2410,24,281,'غزل شمارهٔ ۲۸۱','یا رب این نوگل خندان که سپردی به منش
INSERT INTO "poems" VALUES(2411,24,282,'غزل شمارهٔ ۲۸۲','ببرد از من قرار و طاقت و هوش
INSERT INTO "poems" VALUES(2412,24,283,'غزل شمارهٔ ۲۸۳','سحر ز هاتف غیبم رسید مژده به گوش
INSERT INTO "poems" VALUES(2413,24,284,'غزل شمارهٔ ۲۸۴','هاتفی از گوشه میخانه دوش
INSERT INTO "poems" VALUES(2414,24,285,'غزل شمارهٔ ۲۸۵','در عهد پادشاه خطابخش جرم پوش
INSERT INTO "poems" VALUES(2415,24,286,'غزل شمارهٔ ۲۸۶','دوش با من گفت پنهان کاردانی تیزهوش
INSERT INTO "poems" VALUES(2416,24,287,'غزل شمارهٔ ۲۸۷','ای همه شکل تو مطبوع و همه جای تو خوش
INSERT INTO "poems" VALUES(2417,24,288,'غزل شمارهٔ ۲۸۸','کنار آب و پای بید و طبع شعر و یاری خوش
INSERT INTO "poems" VALUES(2418,24,289,'غزل شمارهٔ ۲۸۹','مجمع خوبی و لطف است عذار چو مهش
INSERT INTO "poems" VALUES(2419,24,290,'غزل شمارهٔ ۲۹۰','دلم رمیده شد و غافلم من درویش
INSERT INTO "poems" VALUES(2420,24,291,'غزل شمارهٔ ۲۹۱','ما آزموده ایم در این شهر بخت خویش
INSERT INTO "poems" VALUES(2421,24,292,'غزل شمارهٔ ۲۹۲','قسم به حشمت و جاه و جلال شاه شجاع
INSERT INTO "poems" VALUES(2422,24,293,'غزل شمارهٔ ۲۹۳','بامدادان که ز خلوتگه کاخ ابداع
INSERT INTO "poems" VALUES(2423,24,294,'غزل شمارهٔ ۲۹۴','در وفای عشق تو مشهور خوبانم چو شمع
INSERT INTO "poems" VALUES(2424,24,295,'غزل شمارهٔ ۲۹۵','سحر به بوی گلستان دمی شدم در باغ
INSERT INTO "poems" VALUES(2425,24,296,'غزل شمارهٔ ۲۹۶','طالع اگر مدد دهد دامنش آورم به کف
INSERT INTO "poems" VALUES(2426,24,297,'غزل شمارهٔ ۲۹۷','زبان خامه ندارد سر بیان فراق
INSERT INTO "poems" VALUES(2427,24,298,'غزل شمارهٔ ۲۹۸','مقام امن و می بی غش و رفیق شفیق
INSERT INTO "poems" VALUES(2428,24,299,'غزل شمارهٔ ۲۹۹','اگر شراب خوری جرعه ای فشان بر خاک
INSERT INTO "poems" VALUES(2429,24,300,'غزل شمارهٔ ۳۰۰','هزار دشمنم ار می کنند قصد هلاک
INSERT INTO "poems" VALUES(2430,24,301,'غزل شمارهٔ ۳۰۱','ای دل ریش مرا با لب تو حق نمک
INSERT INTO "poems" VALUES(2431,24,302,'غزل شمارهٔ ۳۰۲','خوش خبر باشی ای نسیم شمال
INSERT INTO "poems" VALUES(2432,24,303,'غزل شمارهٔ ۳۰۳','شممت روح وداد و شمت برق وصال
INSERT INTO "poems" VALUES(2433,24,304,'غزل شمارهٔ ۳۰۴','دارای جهان نصرت دین خسرو کامل
INSERT INTO "poems" VALUES(2434,24,305,'غزل شمارهٔ ۳۰۵','به وقت گل شدم از توبه شراب خجل
INSERT INTO "poems" VALUES(2435,24,306,'غزل شمارهٔ ۳۰۶','اگر به کوی تو باشد مرا مجال وصول
INSERT INTO "poems" VALUES(2436,24,307,'غزل شمارهٔ ۳۰۷','هر نکته ای که گفتم در وصف آن شمایل
INSERT INTO "poems" VALUES(2437,24,308,'غزل شمارهٔ ۳۰۸','ای رخت چون خلد و لعلت سلسبیل
INSERT INTO "poems" VALUES(2438,24,309,'غزل شمارهٔ ۳۰۹','عشقبازی و جوانی و شراب لعل فام
INSERT INTO "poems" VALUES(2439,24,310,'غزل شمارهٔ ۳۱۰','مرحبا طایر فرخ پی فرخنده پیام
INSERT INTO "poems" VALUES(2440,24,311,'غزل شمارهٔ ۳۱۱','عاشق روی جوانی خوش نوخاسته ام
INSERT INTO "poems" VALUES(2441,24,312,'غزل شمارهٔ ۳۱۲','بشری اذ السلامة حلت بذی سلم
INSERT INTO "poems" VALUES(2442,24,313,'غزل شمارهٔ ۳۱۳','بازآی ساقیا که هواخواه خدمتم
INSERT INTO "poems" VALUES(2443,24,314,'غزل شمارهٔ ۳۱۴','دوش بیماری چشم تو ببرد از دستم
INSERT INTO "poems" VALUES(2444,24,315,'غزل شمارهٔ ۳۱۵','به غیر از آن که بشد دین و دانش از دستم
INSERT INTO "poems" VALUES(2445,24,316,'غزل شمارهٔ ۳۱۶','زلف بر باد مده تا ندهی بر بادم
INSERT INTO "poems" VALUES(2446,24,317,'غزل شمارهٔ ۳۱۷','فاش می گویم و از گفته خود دلشادم
INSERT INTO "poems" VALUES(2447,24,318,'غزل شمارهٔ ۳۱۸','مرا می بینی و هر دم زیادت می کنی دردم
INSERT INTO "poems" VALUES(2448,24,319,'غزل شمارهٔ ۳۱۹','سال ها پیروی مذهب رندان کردم
INSERT INTO "poems" VALUES(2449,24,320,'غزل شمارهٔ ۳۲۰','دیشب به سیل اشک ره خواب می زدم
INSERT INTO "poems" VALUES(2450,24,321,'غزل شمارهٔ ۳۲۱','هر چند پیر و خسته دل و ناتوان شدم
INSERT INTO "poems" VALUES(2451,24,322,'غزل شمارهٔ ۳۲۲','خیال نقش تو در کارگاه دیده کشیدم
INSERT INTO "poems" VALUES(2452,24,323,'غزل شمارهٔ ۳۲۳','ز دست کوته خود زیر بارم
INSERT INTO "poems" VALUES(2453,24,324,'غزل شمارهٔ ۳۲۴','گرچه افتاد ز زلفش گرهی در کارم
INSERT INTO "poems" VALUES(2454,24,325,'غزل شمارهٔ ۳۲۵','گر دست دهد خاک کف پای نگارم
INSERT INTO "poems" VALUES(2455,24,326,'غزل شمارهٔ ۳۲۶','در نهانخانه عشرت صنمی خوش دارم
INSERT INTO "poems" VALUES(2456,24,327,'غزل شمارهٔ ۳۲۷','مرا عهدی ست با جانان که تا جان در بدن دارم
INSERT INTO "poems" VALUES(2457,24,328,'غزل شمارهٔ ۳۲۸','من که باشم که بر آن خاطر عاطر گذرم
INSERT INTO "poems" VALUES(2458,24,329,'غزل شمارهٔ ۳۲۹','جوزا سحر نهاد حمایل برابرم
INSERT INTO "poems" VALUES(2459,24,330,'غزل شمارهٔ ۳۳۰','تو همچو صبحی و من شمع خلوت سحرم
INSERT INTO "poems" VALUES(2460,24,331,'غزل شمارهٔ ۳۳۱','به تیغم گر کشد دستش نگیرم
INSERT INTO "poems" VALUES(2461,24,332,'غزل شمارهٔ ۳۳۲','مزن بر دل ز نوک غمزه تیرم
INSERT INTO "poems" VALUES(2462,24,333,'غزل شمارهٔ ۳۳۳','نماز شام غریبان چو گریه آغازم
INSERT INTO "poems" VALUES(2463,24,334,'غزل شمارهٔ ۳۳۴','گر دست رسد در سر زلفین تو بازم
INSERT INTO "poems" VALUES(2464,24,335,'غزل شمارهٔ ۳۳۵','در خرابات مغان گر گذر افتد بازم
INSERT INTO "poems" VALUES(2465,24,336,'غزل شمارهٔ ۳۳۶','مژده وصل تو کو کز سر جان برخیزم
INSERT INTO "poems" VALUES(2466,24,337,'غزل شمارهٔ ۳۳۷','چرا نه در پی عزم دیار خود باشم
INSERT INTO "poems" VALUES(2467,24,338,'غزل شمارهٔ ۳۳۸','من دوستدار روی خوش و موی دلکشم
INSERT INTO "poems" VALUES(2468,24,339,'غزل شمارهٔ ۳۳۹','خیال روی تو چون بگذرد به گلشن چشم
INSERT INTO "poems" VALUES(2469,24,340,'غزل شمارهٔ ۳۴۰','من که از آتش دل چون خم می در جوشم
INSERT INTO "poems" VALUES(2470,24,341,'غزل شمارهٔ ۳۴۱','گر من از سرزنش مدعیان اندیشم
INSERT INTO "poems" VALUES(2471,24,342,'غزل شمارهٔ ۳۴۲','حجاب چهره جان می شود غبار تنم
INSERT INTO "poems" VALUES(2472,24,343,'غزل شمارهٔ ۳۴۳','چل سال بیش رفت که من لاف می زنم
INSERT INTO "poems" VALUES(2473,24,344,'غزل شمارهٔ ۳۴۴','عمریست تا من در طلب هر روز گامی می زنم
INSERT INTO "poems" VALUES(2474,24,345,'غزل شمارهٔ ۳۴۵','بی تو ای سرو روان با گل و گلشن چه کنم
INSERT INTO "poems" VALUES(2475,24,346,'غزل شمارهٔ ۳۴۶','من نه آن رندم که ترک شاهد و ساغر کنم
INSERT INTO "poems" VALUES(2476,24,347,'غزل شمارهٔ ۳۴۷','صنما با غم عشق تو چه تدبیر کنم
INSERT INTO "poems" VALUES(2477,24,348,'غزل شمارهٔ ۳۴۸','دیده دریا کنم و صبر به صحرا فکنم
INSERT INTO "poems" VALUES(2478,24,349,'غزل شمارهٔ ۳۴۹','دوش سودای رخش گفتم ز سر بیرون کنم
INSERT INTO "poems" VALUES(2479,24,350,'غزل شمارهٔ ۳۵۰','به عزم توبه سحر گفتم استخاره کنم
INSERT INTO "poems" VALUES(2480,24,351,'غزل شمارهٔ ۳۵۱','حاشا که من به موسم گل ترک می کنم
INSERT INTO "poems" VALUES(2481,24,352,'غزل شمارهٔ ۳۵۲','روزگاری شد که در میخانه خدمت می کنم
INSERT INTO "poems" VALUES(2482,24,353,'غزل شمارهٔ ۳۵۳','من ترک عشق شاهد و ساغر نمی کنم
INSERT INTO "poems" VALUES(2483,24,354,'غزل شمارهٔ ۳۵۴','به مژگان سیه کردی هزاران رخنه در دینم
INSERT INTO "poems" VALUES(2484,24,355,'غزل شمارهٔ ۳۵۵','حالیا مصلحت وقت در آن می بینم
INSERT INTO "poems" VALUES(2485,24,356,'غزل شمارهٔ ۳۵۶','گرم از دست برخیزد که با دلدار بنشینم
INSERT INTO "poems" VALUES(2486,24,357,'غزل شمارهٔ ۳۵۷','در خرابات مغان نور خدا می بینم
INSERT INTO "poems" VALUES(2487,24,358,'غزل شمارهٔ ۳۵۸','غم زمانه که هیچش کران نمی بینم
INSERT INTO "poems" VALUES(2488,24,359,'غزل شمارهٔ ۳۵۹','خرم آن روز کز این منزل ویران بروم
INSERT INTO "poems" VALUES(2489,24,360,'غزل شمارهٔ ۳۶۰','گر از این منزل ویران به سوی خانه روم
INSERT INTO "poems" VALUES(2490,24,361,'غزل شمارهٔ ۳۶۱','آن که پامال جفا کرد چو خاک راهم
INSERT INTO "poems" VALUES(2491,24,362,'غزل شمارهٔ ۳۶۲','دیدار شد میسر و بوس و کنار هم
INSERT INTO "poems" VALUES(2492,24,363,'غزل شمارهٔ ۳۶۳','دردم از یار است و درمان نیز هم
INSERT INTO "poems" VALUES(2493,24,364,'غزل شمارهٔ ۳۶۴','ما بی غمان مست دل از دست داده ایم
INSERT INTO "poems" VALUES(2494,24,365,'غزل شمارهٔ ۳۶۵','عمریست تا به راه غمت رو نهاده ایم
INSERT INTO "poems" VALUES(2495,24,366,'غزل شمارهٔ ۳۶۶','ما بدین در نه پی حشمت و جاه آمده ایم
INSERT INTO "poems" VALUES(2496,24,367,'غزل شمارهٔ ۳۶۷','فتوی پیر مغان دارم و قولی ست قدیم
INSERT INTO "poems" VALUES(2497,24,368,'غزل شمارهٔ ۳۶۸','خیز تا از در میخانه گشادی طلبیم
INSERT INTO "poems" VALUES(2498,24,369,'غزل شمارهٔ ۳۶۹','ما ز یاران چشم یاری داشتیم
INSERT INTO "poems" VALUES(2499,24,370,'غزل شمارهٔ ۳۷۰','صلاح از ما چه می جویی که مستان را صلا گفتیم
INSERT INTO "poems" VALUES(2500,24,371,'غزل شمارهٔ ۳۷۱','ما درس سحر در ره میخانه نهادیم
INSERT INTO "poems" VALUES(2501,24,372,'غزل شمارهٔ ۳۷۲','بگذار تا ز شارع میخانه بگذریم
INSERT INTO "poems" VALUES(2502,24,373,'غزل شمارهٔ ۳۷۳','خیز تا خرقه صوفی به خرابات بریم
INSERT INTO "poems" VALUES(2503,24,374,'غزل شمارهٔ ۳۷۴','بیا تا گل برافشانیم و می در ساغر اندازیم
INSERT INTO "poems" VALUES(2504,24,375,'غزل شمارهٔ ۳۷۵','صوفی بیا که خرقه سالوس برکشیم
INSERT INTO "poems" VALUES(2505,24,376,'غزل شمارهٔ ۳۷۶','دوستان وقت گل آن به که به عشرت کوشیم
INSERT INTO "poems" VALUES(2506,24,377,'غزل شمارهٔ ۳۷۷','ما شبی دست برآریم و دعایی بکنیم
INSERT INTO "poems" VALUES(2507,24,378,'غزل شمارهٔ ۳۷۸','ما نگوییم بد و میل به ناحق نکنیم
INSERT INTO "poems" VALUES(2508,24,379,'غزل شمارهٔ ۳۷۹','سرم خوش است و به بانگ بلند می گویم
INSERT INTO "poems" VALUES(2509,24,380,'غزل شمارهٔ ۳۸۰','بارها گفته ام و بار دگر می گویم
INSERT INTO "poems" VALUES(2510,24,381,'غزل شمارهٔ ۳۸۱','گرچه ما بندگان پادشهیم
INSERT INTO "poems" VALUES(2511,24,382,'غزل شمارهٔ ۳۸۲','فاتحه ای چو آمدی بر سر خسته ای بخوان
INSERT INTO "poems" VALUES(2512,24,383,'غزل شمارهٔ ۳۸۳','چندان که گفتم غم با طبیبان
INSERT INTO "poems" VALUES(2513,24,384,'غزل شمارهٔ ۳۸۴','می سوزم از فراقت روی از جفا بگردان
INSERT INTO "poems" VALUES(2514,24,385,'غزل شمارهٔ ۳۸۵','یا رب آن آهوی مشکین به ختن باز رسان
INSERT INTO "poems" VALUES(2515,24,386,'غزل شمارهٔ ۳۸۶','خدا را کم نشین با خرقه پوشان
INSERT INTO "poems" VALUES(2516,24,387,'غزل شمارهٔ ۳۸۷','شاه شمشادقدان خسرو شیرین دهنان
INSERT INTO "poems" VALUES(2517,24,388,'غزل شمارهٔ ۳۸۸','بهار و گل طرب انگیز گشت و توبه شکن
INSERT INTO "poems" VALUES(2518,24,389,'غزل شمارهٔ ۳۸۹','چو گل هر دم به بویت جامه در تن
INSERT INTO "poems" VALUES(2519,24,390,'غزل شمارهٔ ۳۹۰','افسر سلطان گل پیدا شد از طرف چمن
INSERT INTO "poems" VALUES(2520,24,391,'غزل شمارهٔ ۳۹۱','خوش تر از فکر می و جام چه خواهد بودن
INSERT INTO "poems" VALUES(2521,24,392,'غزل شمارهٔ ۳۹۲','دانی که چیست دولت دیدار یار دیدن
INSERT INTO "poems" VALUES(2522,24,393,'غزل شمارهٔ ۳۹۳','منم که شهره شهرم به عشق ورزیدن
INSERT INTO "poems" VALUES(2523,24,394,'غزل شمارهٔ ۳۹۴','ای روی ماه منظر تو نوبهار حسن
INSERT INTO "poems" VALUES(2524,24,395,'غزل شمارهٔ ۳۹۵','گلبرگ را ز سنبل مشکین نقاب کن
INSERT INTO "poems" VALUES(2525,24,396,'غزل شمارهٔ ۳۹۶','صبح است ساقیا قدحی پرشراب کن
INSERT INTO "poems" VALUES(2526,24,397,'غزل شمارهٔ ۳۹۷','ز در در آ و شبستان ما منور کن
INSERT INTO "poems" VALUES(2527,24,398,'غزل شمارهٔ ۳۹۸','ای نور چشم من سخنی هست گوش کن
INSERT INTO "poems" VALUES(2528,24,399,'غزل شمارهٔ ۳۹۹','کرشمه ای کن و بازار ساحری بشکن
INSERT INTO "poems" VALUES(2529,24,400,'غزل شمارهٔ ۴۰۰','بالابلند عشوه گر نقش باز من
INSERT INTO "poems" VALUES(2530,24,401,'غزل شمارهٔ ۴۰۱','چون شوم خاک رهش دامن بیفشاند ز من
INSERT INTO "poems" VALUES(2531,24,402,'غزل شمارهٔ ۴۰۲','نکته ای دلکش بگویم خال آن مه رو ببین
INSERT INTO "poems" VALUES(2532,24,403,'غزل شمارهٔ ۴۰۳','شراب لعل کش و روی مه جبینان بین
INSERT INTO "poems" VALUES(2533,24,404,'غزل شمارهٔ ۴۰۴','می فکن بر صف رندان نظری بهتر از این
INSERT INTO "poems" VALUES(2534,24,405,'غزل شمارهٔ ۴۰۵','به جان پیر خرابات و حق صحبت او
INSERT INTO "poems" VALUES(2535,24,406,'غزل شمارهٔ ۴۰۶','گفتا برون شدی به تماشای ماه نو
INSERT INTO "poems" VALUES(2536,24,407,'غزل شمارهٔ ۴۰۷','مزرع سبز فلک دیدم و داس مه نو
INSERT INTO "poems" VALUES(2537,24,408,'غزل شمارهٔ ۴۰۸','ای آفتاب آینه دار جمال تو
INSERT INTO "poems" VALUES(2538,24,409,'غزل شمارهٔ ۴۰۹','ای خونبهای نافه چین خاک راه تو
INSERT INTO "poems" VALUES(2539,24,410,'غزل شمارهٔ ۴۱۰','ای قبای پادشاهی راست بر بالای تو
INSERT INTO "poems" VALUES(2540,24,411,'غزل شمارهٔ ۴۱۱','تاب بنفشه می دهد طره مشک سای تو
INSERT INTO "poems" VALUES(2541,24,412,'غزل شمارهٔ ۴۱۲','مرا چشمی ست خون افشان ز دست آن کمان ابرو
INSERT INTO "poems" VALUES(2542,24,413,'غزل شمارهٔ ۴۱۳','خط عذار یار که بگرفت ماه از او
INSERT INTO "poems" VALUES(2543,24,414,'غزل شمارهٔ ۴۱۴','گلبن عیش می دمد ساقی گل عذار کو
INSERT INTO "poems" VALUES(2544,24,415,'غزل شمارهٔ ۴۱۵','ای پیک راستان خبر یار ما بگو
INSERT INTO "poems" VALUES(2545,24,416,'غزل شمارهٔ ۴۱۶','خنک نسیم معنبر شمامه ای دل خواه
INSERT INTO "poems" VALUES(2546,24,417,'غزل شمارهٔ ۴۱۷','عیشم مدام است از لعل دل خواه
INSERT INTO "poems" VALUES(2547,24,418,'غزل شمارهٔ ۴۱۸','گر تیغ بارد در کوی آن ماه
INSERT INTO "poems" VALUES(2548,24,419,'غزل شمارهٔ ۴۱۹','وصال او ز عمر جاودان به
INSERT INTO "poems" VALUES(2549,24,420,'غزل شمارهٔ ۴۲۰','ناگهان پرده برانداخته ای یعنی چه
INSERT INTO "poems" VALUES(2550,24,421,'غزل شمارهٔ ۴۲۱','در سرای مغان رفته بود و آب زده
INSERT INTO "poems" VALUES(2551,24,422,'غزل شمارهٔ ۴۲۲','ای که با سلسله زلف دراز آمده ای
INSERT INTO "poems" VALUES(2552,24,423,'غزل شمارهٔ ۴۲۳','دوش رفتم به در میکده خواب آلوده
INSERT INTO "poems" VALUES(2553,24,424,'غزل شمارهٔ ۴۲۴','از من جدا مشو که توام نور دیده ای
INSERT INTO "poems" VALUES(2554,24,425,'غزل شمارهٔ ۴۲۵','دامن کشان همی شد در شرب زرکشیده
INSERT INTO "poems" VALUES(2555,24,426,'غزل شمارهٔ ۴۲۶','از خون دل نوشتم نزدیک دوست نامه
INSERT INTO "poems" VALUES(2556,24,427,'غزل شمارهٔ ۴۲۷','چراغ روی تو را شمع گشت پروانه
INSERT INTO "poems" VALUES(2557,24,428,'غزل شمارهٔ ۴۲۸','سحرگاهان که مخمور شبانه
INSERT INTO "poems" VALUES(2558,24,429,'غزل شمارهٔ ۴۲۹','ساقی بیا که شد قدح لاله پر ز می
INSERT INTO "poems" VALUES(2559,24,430,'غزل شمارهٔ ۴۳۰','به صوت بلبل و قمری اگر ننوشی می
INSERT INTO "poems" VALUES(2560,24,431,'غزل شمارهٔ ۴۳۱','لبش می بوسم و در می کشم می
INSERT INTO "poems" VALUES(2561,24,432,'غزل شمارهٔ ۴۳۲','مخمور جام عشقم ساقی بده شرابی
INSERT INTO "poems" VALUES(2562,24,433,'غزل شمارهٔ ۴۳۳','ای که بر ماه از خط مشکین نقاب انداختی
INSERT INTO "poems" VALUES(2563,24,434,'غزل شمارهٔ ۴۳۴','ای دل مباش یک دم خالی ز عشق و مستی
INSERT INTO "poems" VALUES(2564,24,435,'غزل شمارهٔ ۴۳۵','با مدعی مگویید اسرار عشق و مستی
INSERT INTO "poems" VALUES(2565,24,436,'غزل شمارهٔ ۴۳۶','آن غالیه خط گر سوی ما نامه نوشتی
INSERT INTO "poems" VALUES(2566,24,437,'غزل شمارهٔ ۴۳۷','ای قصه بهشت ز کویت حکایتی
INSERT INTO "poems" VALUES(2567,24,438,'غزل شمارهٔ ۴۳۸','سبت سلمیٰ بصدغیها فؤادي
INSERT INTO "poems" VALUES(2568,24,439,'غزل شمارهٔ ۴۳۹','دیدم به خواب دوش که ماهی برآمدی
INSERT INTO "poems" VALUES(2569,24,440,'غزل شمارهٔ ۴۴۰','سحر با باد می گفتم حدیث آرزومندی
INSERT INTO "poems" VALUES(2570,24,441,'غزل شمارهٔ ۴۴۱','چه بودی ار دل آن ماه مهربان بودی
INSERT INTO "poems" VALUES(2571,24,442,'غزل شمارهٔ ۴۴۲','به جان او که گرم دسترس به جان بودی
INSERT INTO "poems" VALUES(2572,24,443,'غزل شمارهٔ ۴۴۳','چو سرو اگر بخرامی دمی به گلزاری
INSERT INTO "poems" VALUES(2573,24,444,'غزل شمارهٔ ۴۴۴','شهری ست پر ظریفان وز هر طرف نگاری
INSERT INTO "poems" VALUES(2574,24,445,'غزل شمارهٔ ۴۴۵','تو را که هر چه مراد است در جهان داری
INSERT INTO "poems" VALUES(2575,24,446,'غزل شمارهٔ ۴۴۶','صبا تو نکهت آن زلف مشک بو داری
INSERT INTO "poems" VALUES(2576,24,447,'غزل شمارهٔ ۴۴۷','بیا با ما مورز این کینه داری
INSERT INTO "poems" VALUES(2577,24,448,'غزل شمارهٔ ۴۴۸','ای که در کوی خرابات مقامی داری
INSERT INTO "poems" VALUES(2578,24,449,'غزل شمارهٔ ۴۴۹','ای که مهجوری عشاق روا می داری
INSERT INTO "poems" VALUES(2579,24,450,'غزل شمارهٔ ۴۵۰','روزگاری ست که ما را نگران می داری
INSERT INTO "poems" VALUES(2580,24,451,'غزل شمارهٔ ۴۵۱','خوش کرد یاوری فلکت روز داوری
INSERT INTO "poems" VALUES(2581,24,452,'غزل شمارهٔ ۴۵۲','طفیل هستی عشقند آدمی و پری
INSERT INTO "poems" VALUES(2582,24,453,'غزل شمارهٔ ۴۵۳','ای که دایم به خویش مغروری
INSERT INTO "poems" VALUES(2583,24,454,'غزل شمارهٔ ۴۵۴','ز کوی یار می آید نسیم باد نوروزی
INSERT INTO "poems" VALUES(2584,24,455,'غزل شمارهٔ ۴۵۵','عمر بگذشت به بی حاصلی و بوالهوسی
INSERT INTO "poems" VALUES(2585,24,456,'غزل شمارهٔ ۴۵۶','نوبهار است در آن کوش که خوش دل باشی
INSERT INTO "poems" VALUES(2586,24,457,'غزل شمارهٔ ۴۵۷','هزار جهد بکردم که یار من باشی
INSERT INTO "poems" VALUES(2587,24,458,'غزل شمارهٔ ۴۵۸','ای دل آن دم که خراب از می گلگون باشی
INSERT INTO "poems" VALUES(2588,24,459,'غزل شمارهٔ ۴۵۹','زین خوش رقم که بر گل رخسار می کشی
INSERT INTO "poems" VALUES(2589,24,460,'غزل شمارهٔ ۴۶۰','سلیمیٰ منذ حلت بالعراق
INSERT INTO "poems" VALUES(2590,24,461,'غزل شمارهٔ ۴۶۱','کتبت قصة شوقی و مدمعی باکی
INSERT INTO "poems" VALUES(2591,24,462,'غزل شمارهٔ ۴۶۲','یا مبسما یحاکي درجا من اللآلي
INSERT INTO "poems" VALUES(2592,24,463,'غزل شمارهٔ ۴۶۳','سلام الله ما کر اللیالي
INSERT INTO "poems" VALUES(2593,24,464,'غزل شمارهٔ ۴۶۴','بگرفت کار حسنت چون عشق من کمالی
INSERT INTO "poems" VALUES(2594,24,465,'غزل شمارهٔ ۴۶۵','رفتم به باغ صبحدمی تا چنم گلی
INSERT INTO "poems" VALUES(2595,24,466,'غزل شمارهٔ ۴۶۶','این خرقه که من دارم در رهن شراب اولی
INSERT INTO "poems" VALUES(2596,24,467,'غزل شمارهٔ ۴۶۷','زان می عشق کز او پخته شود هر خامی
INSERT INTO "poems" VALUES(2597,24,468,'غزل شمارهٔ ۴۶۸','که برد به نزد شاهان ز من گدا پیامی
INSERT INTO "poems" VALUES(2598,24,469,'غزل شمارهٔ ۴۶۹','أتت روایح رند الحمیٰ و زاد غرامی
INSERT INTO "poems" VALUES(2599,24,470,'غزل شمارهٔ ۴۷۰','سینه مالامال درد است ای دریغا مرهمی
INSERT INTO "poems" VALUES(2600,24,471,'غزل شمارهٔ ۴۷۱','ز دلبرم که رساند نوازش قلمی
INSERT INTO "poems" VALUES(2601,24,472,'غزل شمارهٔ ۴۷۲','احمد الله علی معدلة السلطان
INSERT INTO "poems" VALUES(2602,24,473,'غزل شمارهٔ ۴۷۳','وقت را غنیمت دان آن قدر که بتوانی
INSERT INTO "poems" VALUES(2603,24,474,'غزل شمارهٔ ۴۷۴','هواخواه توام جانا و می دانم که می دانی
INSERT INTO "poems" VALUES(2604,24,475,'غزل شمارهٔ ۴۷۵','گفتند خلایق که تویی یوسف ثانی
INSERT INTO "poems" VALUES(2605,24,476,'غزل شمارهٔ ۴۷۶','نسیم صبح سعادت بدان نشان که تو دانی
INSERT INTO "poems" VALUES(2606,24,477,'غزل شمارهٔ ۴۷۷','دو یار زیرک و از باده کهن دو منی
INSERT INTO "poems" VALUES(2607,24,478,'غزل شمارهٔ ۴۷۸','نوش کن جام شراب یک منی
INSERT INTO "poems" VALUES(2608,24,479,'غزل شمارهٔ ۴۷۹','صبح است و ژاله می چکد از ابر بهمنی
INSERT INTO "poems" VALUES(2609,24,480,'غزل شمارهٔ ۴۸۰','ای که در کشتن ما هیچ مدارا نکنی
INSERT INTO "poems" VALUES(2610,24,481,'غزل شمارهٔ ۴۸۱','بشنو این نکته که خود را ز غم آزاده کنی
INSERT INTO "poems" VALUES(2611,24,482,'غزل شمارهٔ ۴۸۲','ای دل به کوی عشق گذاری نمی کنی
INSERT INTO "poems" VALUES(2612,24,483,'غزل شمارهٔ ۴۸۳','سحرگه ره ‎روی در سرزمینی
INSERT INTO "poems" VALUES(2613,24,484,'غزل شمارهٔ ۴۸۴','تو مگر بر لب آبی به هوس بنشینی
INSERT INTO "poems" VALUES(2614,24,485,'غزل شمارهٔ ۴۸۵','ساقیا سایه ابر است و بهار و لب جوی
INSERT INTO "poems" VALUES(2615,24,486,'غزل شمارهٔ ۴۸۶','بلبل ز شاخ سرو به گلبانگ پهلوی
INSERT INTO "poems" VALUES(2616,24,487,'غزل شمارهٔ ۴۸۷','ای بی خبر بکوش که صاحب خبر شوی
INSERT INTO "poems" VALUES(2617,24,488,'غزل شمارهٔ ۴۸۸','سحرم هاتف میخانه به دولت خواهی
INSERT INTO "poems" VALUES(2618,24,489,'غزل شمارهٔ ۴۸۹','ای در رخ تو پیدا انوار پادشاهی
INSERT INTO "poems" VALUES(2619,24,490,'غزل شمارهٔ ۴۹۰','در همه دیر مغان نیست چو من شیدایی
INSERT INTO "poems" VALUES(2620,24,491,'غزل شمارهٔ ۴۹۱','به چشم کرده ام ابروی ماه سیمایی
INSERT INTO "poems" VALUES(2621,24,492,'غزل شمارهٔ ۴۹۲','سلامی چو بوی خوش آشنایی
INSERT INTO "poems" VALUES(2622,24,493,'غزل شمارهٔ ۴۹۳','ای پادشه خوبان داد از غم تنهایی
INSERT INTO "poems" VALUES(2623,24,494,'غزل شمارهٔ ۴۹۴','ای دل گر از آن چاه زنخدان به درآیی
INSERT INTO "poems" VALUES(2624,24,495,'غزل شمارهٔ ۴۹۵','می خواه و گل افشان کن از دهر چه می جویی
INSERT INTO "poems" VALUES(33169,674,1,'شمارهٔ ۱','ما برفتیم تو دانی و دل غمخور ما
INSERT INTO "poems" VALUES(33170,674,2,'شمارهٔ ۲','صبح دولت می دمد کو جام همچون آفتاب
INSERT INTO "poems" VALUES(33171,674,3,'شمارهٔ ۳','اگر به لطف بخوانی مزید الطاف است
INSERT INTO "poems" VALUES(33172,674,4,'شمارهٔ ۴','غمش تا در دلم مأوا گرفته است
