INSERT INTO "poems" VALUES(145726,674,118,'شمارهٔ ۱۱۸ - در اصل از آن عبدالمجید تبریزی شاعر پیشکسوت حافظ','در اصل از آن عبدالمجید تبریزی شاعر پیشکسوت حافظ
INSERT INTO "verses" VALUES(1930932,2051,0,0,'جز نقش تو در نظر نیامد ما را','هوش مصنوعی: جز تصویر تو برای ما چیزی دیده نشد و جز مسیر تو، کسی به چشم ما نیامد.',NULL);
INSERT INTO "verses" VALUES(1930933,2077,1,1,'خورشیدرُخی طلب کن و سایهٔ گل',NULL,NULL);
INSERT INTO "verses" VALUES(1930934,2078,0,0,'لب باز مگیر یک زمان از لب جام','شادی و مستی را یک لحظه ترک مکن تا لذت دنیا را نصیب خود کنی.',NULL);
INSERT INTO "verses" VALUES(1930935,2078,0,1,'تا بستانی کام جهان از لب جام',NULL,NULL);
INSERT INTO "verses" VALUES(1930936,2078,1,0,'در جام جهان چو تلخ و شیرین به هم است','در زندگی وقتی که تلخی و شیرینی وجود دارد پس تلخی را از جام می بستان و شیرینی را از لب یار.',NULL);
INSERT INTO "verses" VALUES(1930937,2078,1,1,'این از لب یار خواه و آن از لب جام',NULL,NULL);
INSERT INTO "verses" VALUES(1930938,2079,0,0,'در آرزوی بوس و کنارت مُردم','هوش مصنوعی: در آرزوی بوسیدن تو چنان دلتنگ شدم که جانم را از دست دادم و به خاطر حسرت زیبایی لب‌هایت از دنیا رفتم.',NULL);
INSERT INTO "verses" VALUES(1930939,2079,0,1,'وز حسرت لعل آبدارت مُردم',NULL,NULL);
INSERT INTO "verses" VALUES(1930940,2079,1,0,'قصّه نکنم دراز، کوتاه کنم','هوش مصنوعی: دوست عزیز، می‌گویم که داستان را طولانی نکنم و به خلاصه بگویم که دوباره برگرد. من از بس که منتظرت مانده‌ام، حالا به شدت دلتنگ و ناامید شده‌ام.',NULL);
INSERT INTO "verses" VALUES(1930941,2079,1,1,'بازآ بازآ کز انتظارت مُردم',NULL,NULL);
INSERT INTO "verses" VALUES(1930942,2080,0,0,'عمری ز پی مراد ضایع دارم','هوش مصنوعی: من عمرم را در جست‌وجوی آرزوها سپری کرده‌ام و نمی‌دانم از دوری زمان چه چیزی برایم سودمند بوده است.',NULL);
INSERT INTO "verses" VALUES(1930943,2080,0,1,'وز دور فلک چیست که نافع دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1930944,2080,1,0,'با هر که بگفتم که تو را دوست شدم','هوش مصنوعی: هر کسی که با او درباره علاقه‌ام به تو صحبت کردم، به دشمن من تبدیل شد و ای وای که چقدر بدشانس هستم.',NULL);
INSERT INTO "verses" VALUES(1930945,2080,1,1,'شد دشمن من وه که چه طالع دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1930946,2081,0,0,'من حاصل عمر خود ندارم جز غم','هوش مصنوعی: من در طول عمرم تنها چیزی که به دست آورده‌ام، غم و اندوهی در عشق است و هیچ چیز دیگری، نه خوب و نه بد، ندارم جز همین غم.',NULL);
INSERT INTO "verses" VALUES(1930947,2081,0,1,'در عشق، ز نیک و بد ندارم جز غم',NULL,NULL);
INSERT INTO "verses" VALUES(1930948,2081,1,0,'یک همدم باوفا ندیدم جز درد','هوش مصنوعی: هیچ دوست وفاداری جز درد نمی‌شناسم و هیچ همراهی ندارم جز غم و اندوه.',NULL);
INSERT INTO "verses" VALUES(1930949,2081,1,1,'یک مونس نامزد ندارم جز غم',NULL,NULL);
INSERT INTO "verses" VALUES(1930950,2077,1,0,'از سایه به خورشید اگرت هست امان','هوش مصنوعی: اگر می‌خواهی از تیرگی و مشکلات رها شوی، به سوی روشنی و خوشبختی برو و از زیبایی‌ها و نعمت‌ها بهره‌مند شو.',NULL);
INSERT INTO "verses" VALUES(1930951,2082,0,0,'چون باده ز غم چه بایَدَت جوشیدن','هوش مصنوعی: وقتی که از غم احساس خوشحالی می‌کنی، دیگر چه نیازی به یادآوری غم‌ها داری؟ وقتی که شادی به قلبت می‌آید، کوشش برای مقابله با غم‌ها چه فایده‌ای دارد؟',NULL);
INSERT INTO "verses" VALUES(1930952,2077,0,1,'بربست مشاطه‌وار پیرایهٔ گل',NULL,NULL);
INSERT INTO "verses" VALUES(1930953,2076,1,1,'مانندهٔ سنگ خاره در آب زلال',NULL,NULL);
INSERT INTO "verses" VALUES(1930954,2072,1,0,'گفتا که «لبم بگیر و زلفم بگذار»','هوش مصنوعی: او گفت که لبانم را بگیر و موهایم را در لذت و شادی آویزان کن، نه در طول عمر طولانی.',NULL);
INSERT INTO "verses" VALUES(1930955,2072,1,1,'در عیش خوش‌ آویز، نه در عمر دراز',NULL,NULL);
INSERT INTO "verses" VALUES(1930956,2073,0,0,'مَردی ز کَنندهٔ دَرِ خیبر پرس','هوش مصنوعی: مردی از کسی که درب خیبر را باز کرده، درباره‌ی اسرار بخشش و سخاوتمندی سوال می‌کند و از خواجه قنبر، که معروف به بزرگی و کرامت است، می‌پرسد.',NULL);
INSERT INTO "verses" VALUES(1930957,2073,0,1,'اسرار کرَم ز خواجهٔ قنبر پرس',NULL,NULL);
INSERT INTO "verses" VALUES(1930958,2073,1,0,'گر طالب فیض حقّ به صدقی حافظ','هوش مصنوعی: اگر به دنبال بهره‌مندی از نعمت‌های الهی هستی، با صداقت از ساقی کوثر بپرس که سرچشمه‌ی آن کجاست.',NULL);
INSERT INTO "verses" VALUES(1930959,2073,1,1,'سر چشمهٔ آن ز ساقی کوثر پرس',NULL,NULL);
INSERT INTO "verses" VALUES(1930960,2074,0,0,'چشم تو که سِحرِ بابِل است استادش','چشم تو که افسون‌گری را از جادوی بابِل آموخته‌است؛ یا رب که فسون‌ها برواد از یادش',NULL);
INSERT INTO "verses" VALUES(1930961,2074,0,1,'یا رب که فسون‌ها برواد از یادش',NULL,NULL);
INSERT INTO "verses" VALUES(1930962,2074,1,0,'آن گوش که حلقه کرد در گوش جمال','گوش تو که زیبایی را بنده و حلقه‌به‌گوش خود کرده‌است؛ گوشواره‌اش از در و مروارید (اشعار‌) حافظ بادا!',NULL);
INSERT INTO "verses" VALUES(1930963,2074,1,1,'آویزهٔ دُرّ ز نظم حافظ بادش',NULL,NULL);
INSERT INTO "verses" VALUES(1930964,2075,0,0,'ای دوست دل از جفای دشمن درکش','هوش مصنوعی: ای دوست، دل خود را از رنج و سختی‌هایی که از دشمن می‌کشی، رها کن و با روی زیبا و دلپذیر، نوشیدنی روشن و خوشمزه‌ای بنوش.',NULL);
INSERT INTO "verses" VALUES(1930965,2075,0,1,'با روی نکو شراب روشن درکش',NULL,NULL);
INSERT INTO "verses" VALUES(1930966,2075,1,0,'با اهل هنر گوی گریبان بگشای','هوش مصنوعی: با هنرمندان در ارتباط باشید و از آنها پشتیبانی کنید، ولی از افرادی که استعداد ندارند دوری کنید و به آنها اهمیتی ندهید.',NULL);
INSERT INTO "verses" VALUES(1930967,2075,1,1,'وز نااهلان تمام دامن درکش',NULL,NULL);
INSERT INTO "verses" VALUES(1930968,2076,0,0,'ماهی که نظیر خود ندارد به جمال','آن ماه که در زیبایی نظیر ندارد، وقتی که ‌آن مشکی‌خال عریان می‌شود.',NULL);
INSERT INTO "verses" VALUES(1930969,2076,0,1,'چون جامه ز تن برکشد آن مشکین‌خال',NULL,NULL);
INSERT INTO "verses" VALUES(1930970,2076,1,0,'در سینه دلش ز نازکی بتوان دید','در وسط سینه او از لطیفی پیداست که سنگ سختی هست در آب زلال.',NULL);
INSERT INTO "verses" VALUES(1930971,2077,0,0,'در باغ چو شد باد صبا دایهٔ گل','هوش مصنوعی: وقتی نسیم صبحگاهی به باغ وزید، پرستار گل‌ها کار خود را آغاز کرد و مانند آرایشگری، زیبایی‌های گل را آراست.',NULL);
INSERT INTO "verses" VALUES(1930972,2072,0,1,'گفتم «من سودازده را کار بساز»',NULL,NULL);
INSERT INTO "verses" VALUES(1930973,2082,0,1,'با لشگر غم چه بایدت کوشیدن',NULL,NULL);
INSERT INTO "verses" VALUES(1930974,2082,1,1,'می بر لب سبزه، خوش بوَد نوشیدن',NULL,NULL);
INSERT INTO "verses" VALUES(1930975,2088,0,1,'وان ساغر چون نگار بر دستم نه',NULL,NULL);
INSERT INTO "verses" VALUES(1930976,2088,1,0,'آن می که چو زنجیر بپیچد بر خود','هوش مصنوعی: آن نوشیدنی که همچون زنجیری دور من می‌پیچد، مرا دیوانه کرده است. بیا و آن را به دست من بده.',NULL);
INSERT INTO "verses" VALUES(1930977,2088,1,1,'دیوانه شدم بیار بر دستم نه',NULL,NULL);
INSERT INTO "verses" VALUES(1930978,2089,0,0,'با شاهد شوخ شنگ و با بربط و نی','هوش مصنوعی: با نوجوانی جذاب و بازیگوش، در گوشه‌ای بنشین و با ساز و نی به آهنگ‌سازی بپرداز. وقتی که آرامش و راحتی داری، یک شیشه شراب هم کنارت باشد تا خوش بگذرانید.',NULL);
INSERT INTO "verses" VALUES(1930979,2089,0,1,'کنجی و فراغتی و یک شیشهٔ می',NULL,NULL);
INSERT INTO "verses" VALUES(1930980,2089,1,0,'چون گرم شود ز باده ما را رگ و پی','هوش مصنوعی: زمانی که از شراب سرمست می‌شویم، آن‌قدر خوشحال و شاداب می‌شویم که هیچ چیز دیگر نمی‌توانیم از کسی انتظار داشته باشیم؛ حتی کوچک‌ترین کمک یا لطفی از حاتم طائی، که به بزرگ‌منشی‌اش معروف است، نمی‌خواهیم.',NULL);
INSERT INTO "verses" VALUES(1930981,2089,1,1,'منّت نبریم یک جو از حاتم طی',NULL,NULL);
INSERT INTO "verses" VALUES(1930982,2090,0,0,'قسّام بهشت و دوزخ آن عقده‌گشای','تعیین‌کننده یا تقسیم‌کننده یعنی آن گره‌گشای مشکلات، نمی‌گذارد و اجازه نمی‌دهد که ما از پا در آییم و از ما محافظت خواهد کرد.',NULL);
INSERT INTO "verses" VALUES(1930983,2090,0,1,'ما را نگذارد که درآییم ز پای',NULL,NULL);
INSERT INTO "verses" VALUES(1930984,2090,1,0,'تا کی بوَد این گرگ ربایی، بنمای','این گرگ‌ربایی و غارت تا کی ادامه خواهد داشت؟ قدرتت را بنما و ما را نجات ده ای شیر خدا!',NULL);
INSERT INTO "verses" VALUES(1930985,2090,1,1,'سرپنجهٔ دشمن افکن ای شیر خدای',NULL,NULL);
INSERT INTO "verses" VALUES(1930986,2091,0,0,'ای کاش که بخت، سازگاری کردی','ای کاش قضاو قدر همراهی می‌کرد! و یار در سختی روزگار یاری می‌کرد!',NULL);
INSERT INTO "verses" VALUES(1930987,2091,0,1,'با جور زمانه یار، یاری کردی',NULL,NULL);
INSERT INTO "verses" VALUES(1930988,2091,1,0,'از دست جوانی‌ام چو بِرْبود عنان','وقتی‌که جوانی را از من گرفت لااقل پیری، پایداری و کمک می‌کرد! (رکاب در اینجا منظور رکاب اسب است که برای سوار شدن به اسب و حفظ تعادل در حین سواری بکار می‌رود)',NULL);
INSERT INTO "verses" VALUES(1930989,2091,1,1,'پیری چو رکاب، پایداری کردی',NULL,NULL);
INSERT INTO "verses" VALUES(1930990,2092,0,0,'گر همچو من افتادهٔ این دام شوی','هوش مصنوعی: اگر تو هم به دام عاشقانه من بیفتی، مثل من دچار زحمت و دردسر عشق و می‌شوی.',NULL);
INSERT INTO "verses" VALUES(1930991,2092,0,1,'ای بس که خراب باده و جام شوی',NULL,NULL);
INSERT INTO "verses" VALUES(1930992,2088,0,0,'آن جام طرب شکار بر دستم نه','هوش مصنوعی: آن جام شادی که در دست من است، مانند ساغر زیبایی نیست که به خاطر آن دلربا در دست بگیرم.',NULL);
INSERT INTO "verses" VALUES(1930993,2082,1,0,'سبز است لبت، ساغر از او دور مدار','هوش مصنوعی: لبان تو سبز و شاداب هستند، پس دور ساغر را از آن‌ها برندار. نوشیدن از این سبزینگی روی لبان خوشبو، لذت‌بخش است.',NULL);
INSERT INTO "verses" VALUES(1930994,2087,1,1,'یک قطرهٔ خون است و هزار اندیشه',NULL,NULL);
INSERT INTO "verses" VALUES(1930995,2087,0,1,'دل خوش کن و بر صبر گمار اندیشه',NULL,NULL);
INSERT INTO "verses" VALUES(1930996,2083,0,0,'ای شَرم‌زده غنچه‌ی مَستور از تو','هوش مصنوعی: ای غنچه‌ی خجالت‌زده که پنهان هستی، نرگس مست از زیبایی تو حیران و شرمنده است.',NULL);
INSERT INTO "verses" VALUES(1930997,2083,0,1,'حیران و خِجِل، نرگسِ مَخمور از تو',NULL,NULL);
INSERT INTO "verses" VALUES(1930998,2083,1,0,'گُل با تو برابری کجا یارَد کرد؟','هوش مصنوعی: گل چگونه می‌تواند با تو برابری کند؟ زیرا او نورش را از ماه می‌گیرد و ماه این نور را از تو دریافت کرده است!',NULL);
INSERT INTO "verses" VALUES(1930999,2083,1,1,'کـ‌او نور زِ مَه دارد و مَه نور از تو!',NULL,NULL);
INSERT INTO "verses" VALUES(1931000,2084,0,0,'چشمت که فسون و رنگ می‌بارد از او','هوش مصنوعی: چشمانت زیبایی و جاذبه خاصی دارند، اما افسوس که این جذابیت مانند تیری به سمت من می‌آید و برایم خطرناک است.',NULL);
INSERT INTO "verses" VALUES(1931001,2084,0,1,'افسوس که تیر جنگ می‌بارد از او',NULL,NULL);
INSERT INTO "verses" VALUES(1931002,2084,1,0,'بس زود ملول گشتی از هم‌نفَسان','هوش مصنوعی: بسیار زود از همراهان خود خسته شدی، ای کاش می‌دانستی که دل تو چقدر پر از درد و رنج است.',NULL);
INSERT INTO "verses" VALUES(1931003,2084,1,1,'آه از دل تو که سنگ می‌بارد از او',NULL,NULL);
INSERT INTO "verses" VALUES(1931004,2085,0,0,'ای باد! حدیثِ من نهانش می‌گو','هوش مصنوعی: ای باد! غم‌ و راز من را پنهانی بگو و از دل من با هزار زبان سخن بگو.',NULL);
INSERT INTO "verses" VALUES(1931005,2085,0,1,'سِرّ دل من به صد زبانش می‌گو',NULL,NULL);
INSERT INTO "verses" VALUES(1931006,2085,1,0,'می‌گو نه بِدان‌سان که ملالش گیرد','هوش مصنوعی: بگو که به این شیوه حرف بزند تا خسته نشود، بگو چیزی بگوید و در میانهٔ حرفش نیز صحبت کند.',NULL);
INSERT INTO "verses" VALUES(1931007,2085,1,1,'می‌گو سخنی و در میانش می‌گو',NULL,NULL);
INSERT INTO "verses" VALUES(1931008,2086,0,0,'ای سایهٔ سنبلت سمن پرورده','هوش مصنوعی: ای سایهٔ گل سنبل تو، گلی که در کنار آن عطر و جمال یاقوت لبان تو همچون مرواریدی از خوشبویی و زیبایی پرورش یافته است.',NULL);
INSERT INTO "verses" VALUES(1931009,2086,0,1,'یاقوت لبت درّ عدَن پرورده',NULL,NULL);
INSERT INTO "verses" VALUES(1931010,2086,1,0,'همچون لب خود مدام جان می‌پرور','هوش مصنوعی: همچون لب خود همیشه جان را تغذیه می‌کند، زیرا که روحی در تن پرورش یافته است.',NULL);
INSERT INTO "verses" VALUES(1931011,2086,1,1,'زان راح که روحیست به تن پرورده',NULL,NULL);
INSERT INTO "verses" VALUES(1931012,2087,0,0,'گفتی که تو را شوم مدار اندیشه','هوش مصنوعی: تو گفتی که من نباید به افکار و نگرانی‌هایم بیفتم، پس بهتر است که دل را شاد کنم و به صبر متوسل شوم.',NULL);
INSERT INTO "verses" VALUES(1931013,2087,1,0,'کو صبر و چه دل، کآنچه دلش می‌خوانند','هوش مصنوعی: صبر و دلچه‌ای باقی نمانده است، زیرا آنچه که انسان آن را دل می‌نامد، تنها یک قطرهٔ خون است و هزاران افکاری که در سر دارد.',NULL);
INSERT INTO "verses" VALUES(1931014,2072,0,0,'در سنبلش آویختم از روی نیاز','هوش مصنوعی: من به گل سنبل او آویختم و از روی نیاز به او گفتم که من که دچار عشق و شوق هستم، به کمک احتیاج دارم.',NULL);
INSERT INTO "verses" VALUES(1931015,2071,1,1,'بر مَردمِ رند، نکته بسیار مگیر',NULL,NULL);
INSERT INTO "verses" VALUES(1931016,2071,1,0,'صوفی چو تو رسمِ رهروان می‌دانی','هوش مصنوعی: ای صوفی، تو که خود را پیرو راه و روش رهروان می‌دانی، در مورد مردان رند و آزاداندیش نکته‌سنجی‌های زیادی نکن.',NULL);
INSERT INTO "verses" VALUES(1931017,2056,1,0,'زان روی که از شعاع نور رخ تو','هوش مصنوعی: به خاطر زیبایی و درخشندگی چهره‌ات، خورشید روشن و ماه درخشان شده‌اند.',NULL);
INSERT INTO "verses" VALUES(1931018,2056,1,1,'خورشید منیر و ماه تابنده شده‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1931019,2057,0,0,'هر روز دلم به زیر باری دگر است','هوش مصنوعی: هر روز قلبم تحت فشار مشکلات جدیدی است و در چشمانم به خاطر دوری از تو، حسرت و درد دیگری وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1931020,2057,0,1,'در دیدهٔ من ز هجر خاری دگر است',NULL,NULL);
INSERT INTO "verses" VALUES(1931021,2057,1,0,'من جهد همی‌کنم قضا می‌گوید','حورا: من تلاش زیادی میکنم اما قضا میگه/ خارج از حیطه ی اختیارات تو(توانایی تو) اتفاقات دیگری در جریانه',NULL);
INSERT INTO "verses" VALUES(1931022,2057,1,1,'بیرون ز کفایت تو کاری دگر است',NULL,NULL);
INSERT INTO "verses" VALUES(1931023,2058,0,0,'ماهم که رخش روشنی خور بگرفت','هوش مصنوعی: ما که همچون ماه، نور و روشنی‌اش را از خورشید می‌گیریم، با خط و نشان او، چشمه‌ای از برکت و طراوت را به دست می‌آوریم.',NULL);
INSERT INTO "verses" VALUES(1931024,2058,0,1,'گرد خط او چشمهٔ کوثر بگرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1931025,2058,1,0,'دل‌ها همه در چاه زنخدان انداخت','هوش مصنوعی: دل‌ها همه در چاه زیبایی تو گرفتار شده‌اند و سپس چاه را به عطر خوش عنبر پوشانده‌اند.',NULL);
INSERT INTO "verses" VALUES(1931026,2058,1,1,'وآنگه سر چاه را به عنبر بگرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1931027,2059,0,0,'امشب ز غمت میان خون خواهم خفت','هوش مصنوعی: امشب به خاطر غم‌هایم در میان اشک‌های خود می‌خوابم و از جای راحت و آسایشم بیرون می‌آیم.',NULL);
INSERT INTO "verses" VALUES(1931028,2059,0,1,'وز بستر عافیت برون خواهم خفت',NULL,NULL);
INSERT INTO "verses" VALUES(1931029,2059,1,0,'باور نکنی خیال خود را بفرست','هوش مصنوعی: اگر به حرف‌های من ایمان نیاوری، تنها تصویری از خودت را به جای من بفرست تا بازنگردم، زیرا بدون تو نمی‌توانم بخوابم.',NULL);
INSERT INTO "verses" VALUES(1931030,2059,1,1,'تا دَرنگرد که بی‌ تو چون خواهم خفت',NULL,NULL);
INSERT INTO "verses" VALUES(1931031,2060,0,0,'نی قصهٔ آن شمع چگل بتوان گفت','هوش مصنوعی: نمیتوان داستان شمعی را که به آرامی می‌سوزد بازگو کرد و نمی‌توان حال دل کسی را که در درونش می‌سوزد توضیح داد.',NULL);
INSERT INTO "verses" VALUES(1931032,2060,0,1,'نی حالِ دلِ سوخته‌دل بتوان گفت',NULL,NULL);
INSERT INTO "verses" VALUES(1931033,2060,1,0,'غم در دلِ تنگِ من از آن است که نیست','هوش مصنوعی: غم و اندوه در دل من به خاطر این است که هیچ دوستی ندارم که بتوانم با او از غم‌هایم صحبت کنم.',NULL);
INSERT INTO "verses" VALUES(1931034,2056,0,1,'تا بندهٔ تو شده‌ست تابنده شده‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1931035,2060,1,1,'یک دوست که با او غمِ دل بتوان گفت',NULL,NULL);
INSERT INTO "verses" VALUES(1931036,2056,0,0,'تو بدری و خورشید تو را بنده شده‌ست','هوش مصنوعی: تو همچون ماه درخشان و نورانی هستی و خورشید به خاطر روشناییت به تو وابسته شده است، چون به خاطر تو نورش را می‌تاباند.',NULL);
INSERT INTO "verses" VALUES(1931037,2055,1,0,'پیداست از آن میان چو بربست کمر','هوش مصنوعی: از آنجا که کمر را محکم بسته‌اند، مشخص است که من به کمر چه نوع تکیه‌گاه یا حمایتی نیاز دارم.',NULL);
INSERT INTO "verses" VALUES(1931038,2051,0,1,'جز کوی تو رهگذر نیامد ما را',NULL,NULL);
INSERT INTO "verses" VALUES(1931039,2051,1,0,'خواب ار چه خوش آمد همه را در عهدت','هوش مصنوعی: اگر خواب هم خوب و زیبا باشد، اما در زمان حضور تو، واقعاً برای ما قابل مشاهده نبوده است.',NULL);
INSERT INTO "verses" VALUES(1931040,2051,1,1,'حقّا که به چشم دَر نیامد ما را',NULL,NULL);
INSERT INTO "verses" VALUES(1931041,2052,0,0,'بر گیر شراب طرب‌انگیز و بیا','شراب فرح‌افزا را برگیر و بیاور و به‌دور از چشم رقیبان فرومایه شتاب کن و بیا. (بستیز در اینجا یعنی شتاب کن)',NULL);
INSERT INTO "verses" VALUES(1931042,2052,0,1,'پنهان ز رقیب سفله بستیز و بیا',NULL,NULL);
INSERT INTO "verses" VALUES(1931043,2052,1,0,'مشنو سخن خصم که بنشین و مرو','هوش مصنوعی: به حرف دشمن توجه نکن و سرجایت نمان. به من گوش کن و این نکته را درک کن که باید برخیزی و به جلو بیایی.',NULL);
INSERT INTO "verses" VALUES(1931044,2052,1,1,'بشنو ز من این نکته که برخیز و بیا',NULL,NULL);
INSERT INTO "verses" VALUES(1931045,2053,0,0,'گفتم که لبت، گفت لبم آب حیات','هوش مصنوعی: گفتم که لب تو زیباست، او جواب داد که لب من مایه حیات است. گفتم دهانت چقدر دلنشین است، او گفت خوشا به حال گیاهانی که از عشق تو می‌رویند.',NULL);
INSERT INTO "verses" VALUES(1931046,2053,0,1,'گفتم دهنت، گفت زهی حَبّ نبات',NULL,NULL);
INSERT INTO "verses" VALUES(1931047,2053,1,0,'گفتم سخن تو، گفت حافظ گفتا','هوش مصنوعی: گفتم حرف تو را، او جواب داد که حافظ می‌گوید خوشحالی تمام سخن‌گذاران برکت است.',NULL);
INSERT INTO "verses" VALUES(1931048,2053,1,1,'شادیِ همه لطیفه‌گویان صلوات',NULL,NULL);
INSERT INTO "verses" VALUES(1931049,2054,0,0,'ماهی که قدش به سرو می‌ماند راست','هوش مصنوعی: ماهی که قدش به درخت سرو می‌رسید، با آینه در دست، به زیبایی خود می‌رسید.',NULL);
INSERT INTO "verses" VALUES(1931050,2054,0,1,'آیینه به دست و روی خود می‌آراست',NULL,NULL);
INSERT INTO "verses" VALUES(1931051,2054,1,0,'دستارچه‌ای پیشکشش کردم، گفت','هوش مصنوعی: دستارچه‌ای برایش تقدیم کردم، اما او گفت که این وصال فقط یک آرزو است و تو در خیال خود هستی.',NULL);
INSERT INTO "verses" VALUES(1931052,2054,1,1,'وصلم طلبی زهی خیالی که تو راست',NULL,NULL);
INSERT INTO "verses" VALUES(1931053,2055,0,0,'من با کمر تو در میان کردم دست','هوش مصنوعی: من به کمر تو دست زدم و فکر کردم که چیزی در میانش وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1931054,2055,0,1,'پنداشتمش که در میان چیزی هست',NULL,NULL);
INSERT INTO "verses" VALUES(1931055,2055,1,1,'تا من ز کمر چه طرْف خواهم بربست',NULL,NULL);
INSERT INTO "verses" VALUES(1931056,2061,0,0,'اوّل به وفا میِ وصالم درداد','هوش مصنوعی: نخست مرا با وفا به وصال رساند و زمانی که مست شدم، جامی از جفا به من داد.',NULL);
INSERT INTO "verses" VALUES(1931057,2061,0,1,'چون مست شدم جام جفا را سرداد',NULL,NULL);
INSERT INTO "verses" VALUES(1931058,2061,1,0,'پر آب دو دیده و پر از آتش، دل','هوش مصنوعی: چشمانم پر از اشک و دل در آتش است، من به خاطر او به بی‌هویتی و نابودی دچار شدم.',NULL);
INSERT INTO "verses" VALUES(1931059,2067,0,1,'وز گردش روزگار می‌لرز چو بید',NULL,NULL);
INSERT INTO "verses" VALUES(1931060,2067,1,0,'گفتی که «پس از سیاه رنگی نبُوَد»','هوش مصنوعی: تو گفتی بعد از رنگ سیاه، رنگی نخواهد بود، پس چرا موی سیاه من سفید شد؟',NULL);
INSERT INTO "verses" VALUES(1931061,2067,1,1,'پس موی سیاه من چرا گشت سفید؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931062,2068,0,0,'ایّام شباب‌ست، شراب اولاتر','هوش مصنوعی: در روزهای جوانی، نوشیدن شراب بهتر است و باده خالص و ناب نیز انتخابی مناسب‌تر است.',NULL);
INSERT INTO "verses" VALUES(1931063,2068,0,1,'با سبزخَطان، بادهٔ ناب اولاتر',NULL,NULL);
INSERT INTO "verses" VALUES(1931064,2068,1,0,'عالم همه سر به سر رباطی‌ست خراب','هوش مصنوعی: این دنیا مانند یک خوابگاه ویران است و در این ویرانی نیز، هیچ چیزی برتر از ویرانی وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1931065,2068,1,1,'در جای خراب هم، خراب اولاتر',NULL,NULL);
INSERT INTO "verses" VALUES(1931066,2069,0,0,'خوبانِ جهان، صید توان کرد به زَر','هوش مصنوعی: زیبایان دنیا را می‌توان با ثروت به دام انداخت و از آن‌ها لذت برد.',NULL);
INSERT INTO "verses" VALUES(1931067,2069,0,1,'خوش خوش بَر از ایشان بتوان خورد به زَر',NULL,NULL);
INSERT INTO "verses" VALUES(1931068,2069,1,0,'نرگس که کُلَه‌دارِ جهان است، ببین','هوش مصنوعی: نرگس، که زیباترین گل در دنیا به شمار می‌رود، توجه کن که او هم به طریقی از دل خاک روییده و خود را نشان داده است.',NULL);
INSERT INTO "verses" VALUES(1931069,2069,1,1,'کاو نیز، چگونه سَر درآورد به زَر',NULL,NULL);
INSERT INTO "verses" VALUES(1931070,2070,0,0,'سیلاب گرفت گِرد ویرانهٔ عمر','هوش مصنوعی: در اطراف ویرانه‌های عمر، سیلابی به وجود آمده و شروع به پُر کردن پیمانه عمر کرده است.',NULL);
INSERT INTO "verses" VALUES(1931071,2070,0,1,'و‌آغاز پُری نهاد پیمانهٔ عمر',NULL,NULL);
INSERT INTO "verses" VALUES(1931072,2070,1,0,'بیدار شو ای خواجه که خوش‌خوش بکِشد','هوش مصنوعی: بیدار شو ای بزرگوار، زیرا روزگار به آرامی تو را از خانه عمرت دور می‌کند.',NULL);
INSERT INTO "verses" VALUES(1931073,2070,1,1,'حمّال زمانه رخت از خانهٔ عمر',NULL,NULL);
INSERT INTO "verses" VALUES(1931074,2071,0,0,'عشقِ رخِ یار، بر منِ زار مگیر','هوش مصنوعی: عشق به چهره‌ی محبوب، بر منِ رنجیده تأثیر نگذار و بر دل‌های خسته و شیدای دلدادگان سختگیری نکن.',NULL);
INSERT INTO "verses" VALUES(1931075,2071,0,1,'بر خسته‌دلانِ رندِ خَمّار مگیر',NULL,NULL);
INSERT INTO "verses" VALUES(1931076,2067,0,0,'از چرخ به هر گونه همی دار امید','هوش مصنوعی: از چرخ فلک به هر شکلی امید دارم و از نوسانات و تحولات زندگی مانند بید می‌لرزم.',NULL);
INSERT INTO "verses" VALUES(1931077,2066,1,1,'کز رنگ وی‌ام بوی کسی می‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(1931078,2066,1,0,'پیوسته از آن روی کنم همدمی‌اش','هوش مصنوعی: من همیشه به سمت آن شخص می‌روم که وقتی به او نگاه می‌کنم، بوی کسی دیگر را حس می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1931079,2066,0,1,'شادی به دلم از او بسی می‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(1931080,2061,1,1,'خاک ره او شدم به بادم برداد',NULL,NULL);
INSERT INTO "verses" VALUES(1931081,2062,0,0,'نی دولت دنیا به ستم می‌ارزد','هوش مصنوعی: دولت و خوشی‌های دنیوی که به زور و ستم به دست آمده، ارزشی ندارد و حتی کیف و لذتی که از مستی به دست می‌آید، به درد و رنجی که به همراه دارد نمی‌ارزد.',NULL);
INSERT INTO "verses" VALUES(1931082,2062,0,1,'نی لذّت مستی‌اش الم می‌ارزد',NULL,NULL);
INSERT INTO "verses" VALUES(1931083,2062,1,0,'نه هفت هزار ساله شادی جهان','هوش مصنوعی: شادی هفت هزار ساله جهان ارزش ندارد به اندازه‌ی غم و رنج هفت روزه.',NULL);
INSERT INTO "verses" VALUES(1931084,2062,1,1,'این محنت هفت روزه غم می‌ارزد',NULL,NULL);
INSERT INTO "verses" VALUES(1931085,2063,0,0,'هر دوست که دَم زد زِ وفا، دشمن شد','هوش مصنوعی: هر دوستی که از وفا صحبت کند، در واقع دشمنی می‌شود. هر کسی که از پاکی و بی‌گناهی حرف بزند، به نوعی به بدی متهم می‌شود.',NULL);
INSERT INTO "verses" VALUES(1931086,2063,0,1,'هر پاک‌رُوی که بود، تَردامن شد',NULL,NULL);
INSERT INTO "verses" VALUES(1931087,2063,1,0,'گویند شب آبِستَن و این است عجب','هوش مصنوعی: می‌گویند شب آبستن است و این موضوع عجیب است که او هیچ مردی را ندیده، پس چطور آبستن شده است؟',NULL);
INSERT INTO "verses" VALUES(1931088,2092,1,0,'ما عاشق و رند و مست و عالَم‌سوزیم','ما به عشق و شور و حال زندگی می‌کنیم. اگر با ما هم نشینی کنی ، ممکن است به سمتی بروی که در نظر جامعه مورد قضاوت و بدنامی قرار بگیری.',NULL);
INSERT INTO "verses" VALUES(1931089,2063,1,1,'کـ‌او مَرد ندید، از چه آبستن شد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931090,2064,0,1,'نرگس به هوای می قدح‌ساز شود',NULL,NULL);
INSERT INTO "verses" VALUES(1931091,2064,1,0,'فارغ دل آن کسی که مانند حباب','خوشبخت کسی است که مانند حباب که بادش خالی می‌شود، غرور را با باده و مستی از سر خالی کند و در میخانه به‌رقص درآید. (سراندازی یعنی عمل سر انداختن که در پایکوبی و رقص و در اوج شادی انجام می‌دهند)',NULL);
INSERT INTO "verses" VALUES(1931092,2064,1,1,'هم در سر میخانه سرانداز شود',NULL,NULL);
INSERT INTO "verses" VALUES(1931093,2065,0,0,'با می به کنار جوی می‌باید بود','هوش مصنوعی: در کنار جوی باید با شراب و شادی بود و از غم‌ها باید دوری جست.',NULL);
INSERT INTO "verses" VALUES(1931094,2065,0,1,'وز غصّه کناره‌جوی می‌باید بود',NULL,NULL);
INSERT INTO "verses" VALUES(1931095,2065,1,0,'این مدّت عمر ما چو گل ده روز است','هوش مصنوعی: عمر ما مانند گلی است که ده روز بیشتر نمی‌ماند، پس باید با لبخند و تازگی زندگی کنیم.',NULL);
INSERT INTO "verses" VALUES(1931096,2065,1,1,'خندان لب و تازه‌روی می‌باید بود',NULL,NULL);
INSERT INTO "verses" VALUES(1931097,2066,0,0,'این گل ز بر هم‌نفسی می‌آید','هوش مصنوعی: این گل به خاطر هم‌نفسم رشد کرده و از او شادی زیادی به دلم می‌ریزد.',NULL);
INSERT INTO "verses" VALUES(1931098,2064,0,0,'چون غنچهٔ گل قرابه‌پرداز شود','وقتی که غنچه گل می‌شکفد و همچون ساقی جام در دست می‌گیرد و نرگس نیز به‌قصد باده‌نوشی پیاله در دست می‌گیرد',NULL);
INSERT INTO "verses" VALUES(1931099,2092,1,1,'با ما منشین اگر نه بدنام شوی',NULL,NULL);
INSERT INTO "verses" VALUES(1931100,2116,0,0,'در این ظلمت‌سرا تا کی، به بوی دوست بنشینم','هوش مصنوعی: در این تاریکی، چه مدت باید به یاد دوست نشسته و گاهی انگشت به دندان بزنم و گاهی سرم را بر زانو بگذارم؟',NULL);
INSERT INTO "verses" VALUES(1931101,2096,1,0,'چو می‌رفت از جهان این بیت می‌خواند','هوش مصنوعی: وقتی از دنیا می‌رفت، این شعر را برای اهل علم و صاحب‌نظران می‌خواند.',NULL);
INSERT INTO "verses" VALUES(1931102,2096,0,1,'امام سنت و شیخ جماعت',NULL,NULL);
INSERT INTO "verses" VALUES(1931103,2096,0,0,'بهاء الحق و الدین طاب مثواه','هوش مصنوعی: بهاء الحق و الدین نشان‌دهنده ارزش و مقام والای حقیقت و دین است که در کنار امام سنت و شیخ جماعت قرار دارد و این اشخاص جایگاه بسیار خوبی در دل‌ها دارند.',NULL);
INSERT INTO "verses" VALUES(1931104,2095,2,1,'سال تاریخ وفاتش طلب از میل بهشت',NULL,NULL);
INSERT INTO "verses" VALUES(1931105,2095,2,0,'آنکه میلش سوی حق‌بینی و حق‌گویی بود','هوش مصنوعی: کسی که در درونش تمایل به درک حقیقت و بیان آن وجود دارد، می‌تواند برایش مهم باشد که زمان مرگش را با عشق به بهشت طلب کند.',NULL);
INSERT INTO "verses" VALUES(1931106,2095,1,1,'که به گلشن شد و این گلخن پر دود بهشت',NULL,NULL);
INSERT INTO "verses" VALUES(1931107,2095,1,0,'ناف هفته بد و از ماه صفر کاف و الف','هوش مصنوعی: در آغاز هفته بد، از ماه صفر که به باغی زیبا تبدیل شد و این آتشکده پر از دود بهشتی است.',NULL);
INSERT INTO "verses" VALUES(1931108,2095,0,1,'که در این مزرعه جز دانهٔ خیرات نکشت',NULL,NULL);
INSERT INTO "verses" VALUES(1931109,2095,0,0,'آصف عهد زمان جان جهان تورانشاه','هوش مصنوعی: آصف در زمان خود، جان جهان تورانشاه، در این زمین تنها دانه‌های خیر و نیکی را کاشت.',NULL);
INSERT INTO "verses" VALUES(1931114,2093,1,1,'وَ یَرْزُقْهُ مِنْ حَیْثُ لا یَحْتَسِب',NULL,NULL);
INSERT INTO "verses" VALUES(1931115,2096,1,1,'بر اهل فضل و ارباب براعت',NULL,NULL);
INSERT INTO "verses" VALUES(1931116,2093,1,0,'وَ مَنْ یَتَّقِ اللهَ یَجْعَلْ لَهُ','و هرکس پرهیزکاریِ خدایی کند، [خدا] برایش [راه خروج از گرفتاری] قرار می‌دهد و از جایی که فکر نمی‌کند روزی‌اش می‌دهد',NULL);
INSERT INTO "verses" VALUES(1931117,2093,0,0,'تو نیک و بد خود هم از خود بپرس','هوش مصنوعی: خودت درباره خوبی و بدی‌ات فکر کن و از خود بپرس که چرا باید کسی دیگر درباره‌ات قضاوت کند.',NULL);
INSERT INTO "verses" VALUES(1931118,2117,0,0,'ای معرا اصل عالی جوهرت از حرص و آز','هوش مصنوعی: ای معشوق من، اصل و ریشه‌ی زیبا و باارزش تو از هر گونه حرص و طمع خالی است. ذات تو که به خوشبختی و نیکی مشهور است، از زرق و برق و فریبندگی دور است.',NULL);
INSERT INTO "verses" VALUES(1931119,2117,0,1,'وی مبرا ذات میمون اخترت از زرق و ریو',NULL,NULL);
INSERT INTO "verses" VALUES(1931120,2117,1,0,'در بزرگی کی روا باشد که تشریفات را','هوش مصنوعی: در عظمت و بزرگی، نشاید که مقام و احترام را از فرشتگان بگیری و آن را به دیوان بخشیدی.',NULL);
INSERT INTO "verses" VALUES(1931121,2117,1,1,'از فرشته بازگیری آنگهی بخشی به دیو',NULL,NULL);
INSERT INTO "verses" VALUES(1931122,2118,0,0,'ساقیا پیمانه پر کن زانکه صاحب مجلست','هوش مصنوعی: ای ساقی، جام را پر کن چون صاحب این مجلس آرزوها را به ما می‌دهد و رازها را پنهان نگاه می‌دارد.',NULL);
INSERT INTO "verses" VALUES(1931123,2118,0,1,'آرزو می‌بخشد و اسرار می‌دارد نگاه',NULL,NULL);
INSERT INTO "verses" VALUES(1931124,2118,1,0,'جنّت نقد است اینجا عیش و عشرت تازه کن','هوش مصنوعی: این دنیا مانند بهشت است، لذا از زندگی و لذت‌های آن بهره‌مند شو؛ زیرا در بهشت واقعی، خداوند بر بندگان خطای آنها را نمی‌نویسد.',NULL);
INSERT INTO "verses" VALUES(1931125,2118,1,1,'زانکه در جنّت خدا بر بنده ننویسد گناه',NULL,NULL);
INSERT INTO "verses" VALUES(1931126,2118,2,0,'دوستداران دوستکامند و حریفان باادب','هوش مصنوعی: دوستداران، افرادی هستند که به خاطر محبت و دوستی با یکدیگر ارتباط برقرار می‌کنند و به دنبال نزدیک‌تر شدن به هم هستند. حریفان هم با مهربانی و ادب با یکدیگر رفتار می‌کنند و در کنار هم قرار می‌گیرند. پیشکاران نیکنام، کسانی هستند که در خدمت دیگران هستند و نام نیکی دارند، در حالی که صف‌نشینان نیکخواه، افرادی هستند که در تلاشند تا به یکدیگر کمک کنند و خیرخواه همدیگر باشند.',NULL);
INSERT INTO "verses" VALUES(1931127,2118,2,1,'پیشکاران نیکنام و صف‌نشینان نیکخواه',NULL,NULL);
INSERT INTO "verses" VALUES(1931128,2118,3,0,'ساز چنگ، آهنگِ عشرت، صحن مجلس، جایِ رقص','هوش مصنوعی: ساز چنگ خوش‌نوا در حال نواختن آهنگی شاد است، در این مجلس فضایی برای رقص وجود دارد. در کنار محبوب، دانه‌ای از دل و زلف‌های ساقی به عنوان دام‌هایی در مسیر لذت و شادابی قرار دارند.',NULL);
INSERT INTO "verses" VALUES(1931129,2118,3,1,'خالِ جانان، دانهٔ دل، زلفِ ساقی، دام راه',NULL,NULL);
INSERT INTO "verses" VALUES(1931130,2118,4,0,'دور از این بهتر نباشد ساقیا عشرت گزین','هوش مصنوعی: ای ساقی، دور از این خوشی‌ها و لذت‌ها بهتر نیست، حال که این حال خوش را داریم، پس بهتر است ساغر را بیاوری و از این لحظات بیشتر بهره‌مند شویم.',NULL);
INSERT INTO "verses" VALUES(1931131,2093,0,1,'چرا بایدت دیگری محتسب',NULL,NULL);
INSERT INTO "verses" VALUES(1931132,2118,4,1,'حال از این خوشتر نباشد حافظا ساغر بخواه',NULL,NULL);
INSERT INTO "verses" VALUES(1931133,2096,2,0,'به طاعت قرب ایزد می‌توان یافت','هوش مصنوعی: برای رسیدن به رضایت خداوند، اگر توانایی این کار را داری، می‌توانی به جلو بروی و قدم برداری.',NULL);
INSERT INTO "verses" VALUES(1931134,2096,3,0,'بدین دستور تاریخ وفاتش','هوش مصنوعی: با این شیوه تاریخ مرگ او را از حروف نزدیک به بندگی بیرون بیاور.',NULL);
INSERT INTO "verses" VALUES(1931135,2099,5,0,'دگر کریم چو حاجی قوام دریادل','هوش مصنوعی: کریم، همچون حاجی قوام، دل بزرگی دارد و به خاطر بخشش و انصافش، نام نیک او در سراسر جهان شناخته شده است.',NULL);
INSERT INTO "verses" VALUES(1931136,2099,4,1,'بنای کار مواقف به نام شاه نهاد',NULL,NULL);
INSERT INTO "verses" VALUES(1931137,2099,4,0,'دگر شهنشه دانش عضد که در تصنیف','هوش مصنوعی: به زودی یک پادشاه دانشمند دیگر به وجود خواهد آمد که در نظم و ترتیب کارها، به نام شاه، پایه‌گذاری خواهد کرد.',NULL);
INSERT INTO "verses" VALUES(1931138,2099,3,1,'که یمن همت او کارهای بسته گشاد',NULL,NULL);
INSERT INTO "verses" VALUES(1931139,2099,3,0,'دگر بقیهٔ ابدال شیخ امین الدین','هوش مصنوعی: دیگر باقی مانده‌های بهترین افراد، شیخ امین‌الدین است که با اراده و تلاش خود توانسته مشکلات را حل کند و کارهای دشوار را آسان کند.',NULL);
INSERT INTO "verses" VALUES(1931140,2099,2,1,'که قاضی‌ای بِه از او آسمان ندارد یاد',NULL,NULL);
INSERT INTO "verses" VALUES(1931141,2099,2,0,'دگر مربی اسلام شیخ مجدالدین','هوش مصنوعی: دیگر معلم دین اسلام، شیخ مجدالدین، قاضی‌ای است که هیچ چیز در آسمان به اندازه او ارزش نداشته باشد.',NULL);
INSERT INTO "verses" VALUES(1931142,2099,1,1,'که جان خویش بپرورد و دادِ عیش بداد',NULL,NULL);
INSERT INTO "verses" VALUES(1931143,2099,1,0,'نخست پادشهی همچو او ولایت‌بخش','هوش مصنوعی: در ابتدا، شاهی وجود دارد که مانند او سرزمین را اداره می‌کند، کسی که جان خود را پرورش می‌دهد و لذت زندگی را فراهم می‌کند.',NULL);
INSERT INTO "verses" VALUES(1931144,2099,0,1,'به پنج شخص عجب ملک فارس بود آباد',NULL,NULL);
INSERT INTO "verses" VALUES(1931145,2099,0,0,'به عهد سلطنت شاه شیخ ابواسحاق','هوش مصنوعی: در دوران سلطنت شاه شیخ ابواسحاق، پنج شخصیت برجسته و تاثیرگذار در سرزمین فارس وجود داشتند که هر یک به نوعی در آبادانی و شکوفایی این منطقه نقش داشتند.',NULL);
INSERT INTO "verses" VALUES(1931146,2098,1,1,'تاریخ این معامله رحمان لایموت',NULL,NULL);
INSERT INTO "verses" VALUES(1931147,2098,1,0,'جانش غریق رحمت خود کرد تا بود','هوش مصنوعی: در این بیت شاعر از رحمت و لطف الهی صحبت می‌کند و بیان می‌کند که در طول زمان، افرادی که در مسیر محبت و رحمت قرار دارند، تحت حمایت و رحمت خداوند قرار می‌گیرند. این حمایت و رحمت همچنان ادامه دارد و برای کسانی که به این امر اهتمام می‌ورزند، دستاوردهای معنوی و آخرتی در پی خواهد داشت.',NULL);
INSERT INTO "verses" VALUES(1931148,2098,0,1,'دید آن چنان کز او عمل الخیر لایفوت',NULL,NULL);
INSERT INTO "verses" VALUES(1931149,2096,2,1,'قدم در نه گرت هست استطاعت',NULL,NULL);
INSERT INTO "verses" VALUES(1931150,2098,0,0,'رحمان لایموت چو آن پادشاه را','هوش مصنوعی: رحمان جاودان است و نمی‌میرد. وقتی آن پادشاه را دید، به گونه‌ای بود که هیچ کار نیکی از او ضایع نمی‌شود.',NULL);
INSERT INTO "verses" VALUES(1931151,2097,6,0,'پادشاها ز سر لطف و کرم بازش خوان','هوش مصنوعی: ای پادشاه، با لطف و محبت خود او را دعوت کن، چرا که او به شدت تحت تاثیر درد و ناامیدی قرار دارد و در حال رفتن است.',NULL);
INSERT INTO "verses" VALUES(1931152,2097,5,0,'لابه بسیار نمودم که مرو سود نداشت','هوش مصنوعی: من بارها درخواست کردم که بروی، اما فایده‌ای نداشت، چون همه چیز به رحمت و نگاه سلطان بستگی داشت.',NULL);
INSERT INTO "verses" VALUES(1931153,2097,5,1,'زانکه کار از نظر رحمت سلطان می‌رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1931154,2097,4,0,'گفتم: اکنون، سخنِ خوش، که بگوید با من؟','هوش مصنوعی: در حال حاضر، از خودم پرسیدم: چه کسی می‌تواند با من سخن دلنشینی بگوید؟ در این حال، صدای شیرین و خوش‌نوا به دور می‌رفت.',NULL);
INSERT INTO "verses" VALUES(1931155,2097,4,1,'کـ‌آن شکرلَهجه‌ی خوش‌خوانِ خوش‌الحان می‌رَفت',NULL,NULL);
INSERT INTO "verses" VALUES(1931156,2097,3,0,'چون همی‌گفتمش ای مونس دیرینهٔ من','هوش مصنوعی: وقتی که به او می‌گفتم: ای دوست قدیمی من، او به شدت جواب می‌داد و با دل‌زدگی و اشک می‌رفت.',NULL);
INSERT INTO "verses" VALUES(1931157,2097,3,1,'سخت می‌گفت و دل‌آزرده و گریان می‌رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1931158,2097,2,0,'می‌شد آن کس که جز او جان سخن کس نشناخت','هوش مصنوعی: آن شخصی که هیچ‌کس به جز او سخن جان را نمی‌شناخت، را می‌توانستم ببینم و در این حالت احساس می‌کردم که جانم در حال جدا شدن از بدنم است.',NULL);
INSERT INTO "verses" VALUES(1931159,2097,2,1,'من همی‌دیدم و از کالبدم جان می‌رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1931160,2097,1,0,'نقش خوارزم و خیال لب جیحون می‌بست','هوش مصنوعی: در اینجا به تصویر کشیده می‌شود که سرزمین خوارزم و دل‌باختگی به لب‌های جیحون، به همراه هزاران گله که از سرزمین سلیمان می‌گذرد، اتفاق می‌افتد. این تصویر نشان‌دهنده‌ی زیبایی و عظمت این سرزمین و همچنین خاطرخواهی و آرزوهای افراد در آنجا است.',NULL);
INSERT INTO "verses" VALUES(1931161,2097,1,1,'با هزاران گله از ملک سلیمان می‌رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1931162,2097,0,0,'قوت شاعرهٔ من سحر از فرط ملال','هوش مصنوعی: شاعر من که منبع الهام و قدرتش سحر و جادوست، به خاطر خستگی و دل‌زدگی از من فراری شده و به دور می‌رود.',NULL);
INSERT INTO "verses" VALUES(1931163,2097,0,1,'متنفر شده از بنده گریزان می‌رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1931164,2096,3,1,'برون آر از حروف قرب طاعت',NULL,NULL);
INSERT INTO "verses" VALUES(1931165,2097,6,1,'چه کند سوخته از غایت حرمان می‌رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1931166,2119,0,0,'به گوش جان رهی منهیی ندا در داد','هوش مصنوعی: به صدای درونی خود گوش فرا ده و به آن پاسخ بده؛ این ندا از جانب خداوند یگانه است که فقط اوست و هیچ معبودی جز او وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1931167,2119,0,1,'ز حضرت احدی لا اله الّا الله',NULL,NULL);
INSERT INTO "verses" VALUES(1931168,2119,1,0,'که ای عزیز! کسی را که خواری‌ست نصیب','ای عزیز، بدان که کسی که نصیبش از زندگی‌ ذلت و خواری باشد، حقیقت این است که هرگز نمی‌تواند با تکیه بر زور، به مقام و منصب دست یابد.',NULL);
INSERT INTO "verses" VALUES(1931169,2123,1,0,'تاریخ این حکایت گر از تو باز پرسند','هوش مصنوعی: اگر روزی کسی از تو دربارهٔ این داستان بپرسد، سرتاسر آن را با شیرینی و زیبایی میوه‌های بهشتی بیان کن.',NULL);
INSERT INTO "verses" VALUES(1931170,2123,1,1,'سرجمله‌اش فروخوان از میوهٔ بهشتی',NULL,NULL);
INSERT INTO "verses" VALUES(1931171,2124,0,0,'خسروا دادگرا شیردلا بحرکفا','هوش مصنوعی: ای بزرگوار دادگر و دلیر، تو همچون دریاآورنده‌ی کمالات و هنرهای گوناگون هستی. جلال تو به واقع برتر از هر چیزی است.',NULL);
INSERT INTO "verses" VALUES(1931172,2124,0,1,'ای جلال تو به انواع هنر ارزانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931173,2124,1,0,'همه آفاق گرفت و همه اطراف گشاد','هوش مصنوعی: همه جا را فرا گرفت و در همه سوی‌ها گشایش پیدا کرد نام نیک مسعود و آوازهٔ پادشاهی او.',NULL);
INSERT INTO "verses" VALUES(1931174,2124,1,1,'صیت مسعودی و آوازهٔ شه سلطانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931175,2124,2,0,'گفته باشد مگرت ملهم غیب احوالم','هوش مصنوعی: شاید بگوید که حال و روز من را کسی از عالم غیب می‌داند، چرا که روزهای روشن من به اندازه شب‌های تاریکم نبود.',NULL);
INSERT INTO "verses" VALUES(1931176,2124,2,1,'این که شد روز سفیدم چو شب ظلمانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931177,2124,3,0,'در سه سال آنچه بیندوختم از شاه و وزیر','هوش مصنوعی: در سه سال، همه چیزهایی که جمع کردم، از مقام و ثروت، به یک لحظه از من گرفته شد، مثل این که سرنوشت همه را در یک حرکت نابود کرد.',NULL);
INSERT INTO "verses" VALUES(1931178,2124,3,1,'همه بربود به یک دم فلک چوگانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931179,2124,4,0,'دوش در خواب چنان دید خیالم که سحر','هوش مصنوعی: شب گذشته در خواب دیدم که صبحگاه، به تازگی به اصطبل اسب شجاعی رسیده‌ام و در اینجا چیزی پنهان وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1931180,2124,4,1,'گذر افتاد بر اصطبل شهم پنهانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931181,2124,5,0,'بسته بر آخور او استر من جو می‌خورد','هوش مصنوعی: گوشه‌ای از صبح، اسب من در کنار علف می‌خورد و به من می‌گوید که آیا مرا می‌شناسی؟',NULL);
INSERT INTO "verses" VALUES(1931182,2124,5,1,'تیزه افشاند به من گفت مرا می‌دانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931183,2123,0,1,'در دل چرا نکشتی از دست چون بهشتی',NULL,NULL);
INSERT INTO "verses" VALUES(1931184,2124,6,0,'هیچ تعبیر نمی‌دانمش این خواب که چیست','هوش مصنوعی: من نمی‌دانم این خواب چیست و چه معنایی دارد. تو بگو که من در درک این موضوع بی‌خبرم.',NULL);
INSERT INTO "verses" VALUES(1931185,2125,0,0,'ساقیا باده که اکسیر حیات است بیار','ای ساقی از آن باده که اکسیر زندگانی است بیاور تا تن خاکی مرا جاودان کنی.',NULL);
INSERT INTO "verses" VALUES(1931186,2125,0,1,'تا تن خاکی من عین بقا گردانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931187,2125,1,0,'چشم بر دور قدح دارم و جان بر کف دست','به گردش جام باده چشم دوخته‌ام‌ و برای گرفتن جام، جان بر کف دست گذاشته‌ام زیرا تا جان بر کف نگذاری جامی از آن باده نمی‌گیری؛ به سر خواجه قسم!',NULL);
INSERT INTO "verses" VALUES(1931188,2125,1,1,'به سر خواجه که تا آن ندهی نستانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931189,2125,2,0,'همچو گل بر چمن از باد میفشان دامن','از نسیم و بادی که در چمن می‌وزد همچون گل دامن‌افشانی مکن زیرا قصد جان‌بازی در پای تو را دارم.',NULL);
INSERT INTO "verses" VALUES(1931190,2125,2,1,'زانکه در پای تو دارم سر جان‌افشانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931191,2125,3,0,'بر مثانی و مثالث بنواز ای مطرب','ای نوازنده، با آهنگ‌های زیبا به وصف آن ماه بپرداز که در زیبایی رقیب و هم‌تا ندارد. (مثانی و مثالث اصطلاحات موسیقی هستند)',NULL);
INSERT INTO "verses" VALUES(1931192,2125,3,1,'وصف آن ماه که در حُسن ندارد ثانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931193,2126,0,0,'پادشاها لشکر توفیق همراه تواند','هوش مصنوعی: اگر می‌خواهی بر جهان تسلط یابی، بدان که همراهی و حمایت توفیق همیشه با تو خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1931194,2126,0,1,'خیز اگر بر عزم تسخیر جهان ره می‌کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1931195,2126,1,0,'با چنین جاه و جلال از پیشگاه سلطنت','هوش مصنوعی: با این شکوه و عظمت، از درگاه سلطنت خبر می‌دهی و به دل‌های آگاه خدمت می‌کنی.',NULL);
INSERT INTO "verses" VALUES(1931196,2126,1,1,'آگهی و خدمت دل‌های آگه می‌کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1931197,2126,2,0,'با فریب رنگ این نیلی خم زنگارفام','هوش مصنوعی: با استفاده از زیبایی و فریبندگی رنگ آبی، تو به طور ماهرانه‌ای کارها را به دلخواه خود تنظيم می‌کنی، گویی که در اندازه‌گیری رنگ خداوند دخالت داری.',NULL);
INSERT INTO "verses" VALUES(1931198,2126,2,1,'کار بر وفق مراد صبغة الله می‌کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1931199,2124,6,1,'تو بفرمای که در فهم نداری ثانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931200,2123,0,0,'آن میوهٔ بهشتی کآمد به دستت ای جان','هوش مصنوعی: ای جان، آن میوهٔ بهشتی که به دستت رسید، چرا آن را در دل خود نکشتی و از دست ندادیش مانند یک فرد بهشتی؟',NULL);
INSERT INTO "verses" VALUES(1931201,2122,4,1,'به عمر مهلتی از روزگار بایستی',NULL,NULL);
INSERT INTO "verses" VALUES(1931202,2122,4,0,'چو روزگار جز این یک عزیز بیش نداشت','هوش مصنوعی: وقتی که روزگار تنها یک دوست گرانقدر برای من نداشت، باید از زندگی یک فرصت کافی داشته باشم.',NULL);
INSERT INTO "verses" VALUES(1931203,2119,1,1,'حقیقت آن که نیابد به زور منصب و جاه',NULL,NULL);
INSERT INTO "verses" VALUES(1931204,2119,2,0,'به آب زمزم و کوثر سفید نتوان کرد','بخت سیاه یک فرد را حتی با پاک ترین و پاک کننده ترین آب هم نمیتوان شست و پاک کرد',NULL);
INSERT INTO "verses" VALUES(1931205,2119,2,1,'گلیم بخت کسی را که بافتند سیاه',NULL,NULL);
INSERT INTO "verses" VALUES(1931206,2120,0,0,'به روز شنبهٔ سادس ز ماه ذی الحجّه','هوش مصنوعی: در روز شنبه ششم ماه ذی الحجه در سال 760 هجری، ناگهان از دنیا رفت.',NULL);
INSERT INTO "verses" VALUES(1931207,2120,0,1,'به سال هفتصد و شصت از جهان بشد ناگاه',NULL,NULL);
INSERT INTO "verses" VALUES(1931208,2120,1,0,'ز شاهراه سعادت به باغ رضوان رفت','هوش مصنوعی: وزیر کامل، ابونصر خواجه فتح‌الله، از مسیر اصلی خوشبختی و موفقیت به باغ بهشت رفت.',NULL);
INSERT INTO "verses" VALUES(1931209,2120,1,1,'وزیر کامل ابونصر خواجه فتح الله',NULL,NULL);
INSERT INTO "verses" VALUES(1931210,2121,0,0,'به من سلام فرستاد دوستی امروز','هوش مصنوعی: امروز دوستی به من پیام سلامی فرستاد و گفت: ای حاصل نهایی علم و دانش، از بینایی خود بهره ببر.',NULL);
INSERT INTO "verses" VALUES(1931211,2121,0,1,'که ای نتیجهٔ کلکت سواد بینایی',NULL,NULL);
INSERT INTO "verses" VALUES(1931212,2121,1,0,'پس از دو سال که بختت به خانه باز آورد','هوش مصنوعی: پس از دو سال که شانس به سراغت آمده، چرا از خانهٔ صاحبخانه بیرون نمی‌روی؟',NULL);
INSERT INTO "verses" VALUES(1931213,2121,1,1,'چرا ز خانهٔ خواجه به در نمی‌آیی',NULL,NULL);
INSERT INTO "verses" VALUES(1931214,2121,2,0,'جواب دادم و گفتم بدار معذورم','هوش مصنوعی: من پاسخ دادم و گفتم مرا ببخشید، زیرا این رفتار نه به معنای خودخواهی و نه به معنای اعمال سلیقه شخصی است.',NULL);
INSERT INTO "verses" VALUES(1931215,2121,2,1,'که این طریقه نه خودکامیست و خودرایی',NULL,NULL);
INSERT INTO "verses" VALUES(1931216,2121,3,0,'وکیل قاضی‌ام اندر گذر کمین کرده‌ست','هوش مصنوعی: وکیل من در راه، به طور پنهانی منتظر نشسته است و مانند ماری که به طعمه‌ای نزدیک شده، در دست خود مدارک دعوی را دارد.',NULL);
INSERT INTO "verses" VALUES(1931217,2121,3,1,'به کف قبالهٔ دعوی چو مار شیدایی',NULL,NULL);
INSERT INTO "verses" VALUES(1931218,2121,4,0,'که گر برون نهم از آستان خواجه قدم','هوش مصنوعی: اگر از درگاه آقای خود بیرون بروم، ممکن است قدم به زندان بگذارم و با رسوایی روبه‌رو شوم.',NULL);
INSERT INTO "verses" VALUES(1931219,2121,4,1,'بگیردم سوی زندان برد به رسوایی',NULL,NULL);
INSERT INTO "verses" VALUES(1931220,2122,3,1,'به دست آصف صاحب عیار بایستی',NULL,NULL);
INSERT INTO "verses" VALUES(1931221,2122,3,0,'زمانه گر نه زر قلب داشتی کارش','هوش مصنوعی: اگر در این دنیا دل ثروتمند و با ارزش نداشتی، باید به دست کسی که قدرت و توانایی دارد، تسلیم می‌شدی.',NULL);
INSERT INTO "verses" VALUES(1931222,2122,2,1,'اساس او به از این استوار بایستی',NULL,NULL);
INSERT INTO "verses" VALUES(1931223,2122,2,0,'وگر سرای جهان را سر خرابی نیست','هوش مصنوعی: اگر بنا به سرنوشت جهان، در این دنیا هیچ چیز پایدار نیست، پس باید بر اساس چیزهایی استوار باشیم که حقیقتاً ماندگار هستند.',NULL);
INSERT INTO "verses" VALUES(1931224,2122,1,1,'چرا تهی ز می خوشگوار بایستی',NULL,NULL);
INSERT INTO "verses" VALUES(1931225,2122,1,0,'ور آفتاب نکردی فسوس جام زرش','هوش مصنوعی: اگر خورشید بر تو تأثیری نگذارد، چرا این ظرف طلا از نوشیدنی خوشمزه خالی مانده است؟',NULL);
INSERT INTO "verses" VALUES(1931226,2099,5,1,'که نام نیک ببرد از جهان به بخشش و داد',NULL,NULL);
INSERT INTO "verses" VALUES(1931227,2122,0,1,'بر آب نقطهٔ شرمش مدار بایستی',NULL,NULL);
INSERT INTO "verses" VALUES(1931228,2121,7,1,'کمر به بندگی‌اش بسته چرخ مینایی',NULL,NULL);
INSERT INTO "verses" VALUES(1931229,2121,7,0,'همیشه باد جهانش به کام وز سر صدق','هوش مصنوعی: همیشه بادی که در دنیا هست به خوبی و خوشی‌اش می‌وزد و او با صداقت و ایمان، خود را به خدمت و بندگی او درآورده است.',NULL);
INSERT INTO "verses" VALUES(1931230,2121,6,1,'به سیلی‌اش بشکافم دماغ سودایی',NULL,NULL);
INSERT INTO "verses" VALUES(1931231,2121,6,0,'به عون قوت بازوی بندگان وزیر','هوش مصنوعی: من با کمک نیروی بازوهای بندگان، دمی حواس‌پرت را با قدرت می‌شکافم.',NULL);
INSERT INTO "verses" VALUES(1931232,2121,5,1,'کسی نفس زند از حجت تقاضایی',NULL,NULL);
INSERT INTO "verses" VALUES(1931233,2121,5,0,'جناب خواجه حصار من است گر اینجا','هوش مصنوعی: جناب خواجه، محفل من تحت حفاظت شماست. اگر کسی در اینجا نفس بکشد، از شواهد و دلایل شما درخواست می‌کند.',NULL);
INSERT INTO "verses" VALUES(1931234,2122,0,0,'گدا اگر گهر پاک داشتی در اصل','هوش مصنوعی: اگر تو در وجودت گوهر پاک و باارزشی داری، جایز نیست که به خاطر جایگاه مادی و ظاهری خودت را کوچک و خجل کنی.',NULL);
INSERT INTO "verses" VALUES(1931235,2099,6,0,'نظیر خویش بنگذاشتند و بگذشتند','هوش مصنوعی: انسان‌ها همگی از دنیا رفته و به یادگار از خود چیزی باقی نگذاشتند. اما خداوند، با عظمت و بزرگی‌اش، همه آن‌ها را مورد بخشش قرار دهد.',NULL);
INSERT INTO "verses" VALUES(1931236,2099,6,1,'خدای عز و جل جمله را بیامرزاد',NULL,NULL);
INSERT INTO "verses" VALUES(1931237,2100,0,0,'خسروا گوی فلک در خم چوگان تو شد','هوش مصنوعی: ایران زمین و جهان در دستان توست و به خاطر مهارت‌ها و قدرت تو به میدان بازی تبدیل شده است. تو بر همه‌چیز تسلط داری و میدان زندگی تحت تاثیر اراده و هنر تو قرار گرفته.',NULL);
INSERT INTO "verses" VALUES(1931238,2109,3,1,'هرکه بُرَّد سَرَت، گُهَر بخشش',NULL,NULL);
INSERT INTO "verses" VALUES(1931239,2109,3,0,'از صدف یاددار، نکته‌ی حِلم','هوش مصنوعی: از صدف، یادآوری کن که هر که بر تو تسلط پیدا کند، می‌تواند جواهری از بخشش را به دست آورد.',NULL);
INSERT INTO "verses" VALUES(1931240,2109,2,1,'هرکه سَنگَت زَنَد، ثمر بخشش',NULL,NULL);
INSERT INTO "verses" VALUES(1931241,2109,2,0,'کم مباش از درختِ سایه‌فکن','هوش مصنوعی: اگر درختی سایه‌افکن باشی، هر کسی که به تو سنگی پرتاب کند، میوه‌ات را می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1931242,2109,1,1,'هم‌چو کانِ کریم، زَر بخشش',NULL,NULL);
INSERT INTO "verses" VALUES(1931243,2109,1,0,'هرکه بِخْراشَدَت جگر به جفا','هوش مصنوعی: هر کسی که با جفا و رفتار ناپسند تو را آسیب بزند، مانند معدن با ارزشی است که می‌تواند طلا و زیورآلات ببخشد.',NULL);
INSERT INTO "verses" VALUES(1931244,2109,0,1,'آیتی در وفا و در بخشش',NULL,NULL);
INSERT INTO "verses" VALUES(1931245,2109,0,0,'بر تو خوانم، زِ دفترِ اخلاق','هوش مصنوعی: من از کتاب آداب و رفتار، نشانه‌ای از وفا و بخشش را برای تو می‌خوانم.',NULL);
INSERT INTO "verses" VALUES(1931246,2108,2,1,'وز آنجا فهم کن سال وفاتش',NULL,NULL);
INSERT INTO "verses" VALUES(1931247,2108,2,0,'خلیل عادلش پیوسته بر خوان','هوش مصنوعی: خلیل عادل همیشه بر سفره‌ای حضور دارد و از آنجا متوجه می‌شوی که چه زمانی از دنیا رفته است.',NULL);
INSERT INTO "verses" VALUES(1931248,2108,1,1,'خدا راضی ز افعال و صفاتش',NULL,NULL);
INSERT INTO "verses" VALUES(1931249,2108,1,0,'به سوی روضهٔ رضوان سفر کرد','هوش مصنوعی: خدا به سوی بهشت رفت و از کارها و ویژگی‌های خود راضی است.',NULL);
INSERT INTO "verses" VALUES(1931250,2108,0,1,'پس از پنجاه و نه سال از حیاتش',NULL,NULL);
INSERT INTO "verses" VALUES(1931251,2108,0,0,'برادر خواجه عادل طاب مثواه','هوش مصنوعی: برادر خواجه عادل به نام طاب مثواه، پس از گذشت پنجاه و نه سال از زندگی‌اش، درگذشت.',NULL);
INSERT INTO "verses" VALUES(1931252,2110,0,0,'زآن حَبّه‌ی خَضراخور، کَز رویِ سَبُک‌روحی','هوش مصنوعی: از آن دانه‌ی سبز که به خاطر سبک‌دلی هرکسی آن را بخورد، بر روی سیخ، سی مرغ زنده است.',NULL);
INSERT INTO "verses" VALUES(1931253,2107,4,1,'گر بیابیدش به سوی خانهٔ حافظ بَرید',NULL,NULL);
INSERT INTO "verses" VALUES(1931254,2107,3,1,'ور بوُد پوشیده و پنهان به دوزخ در روید',NULL,NULL);
INSERT INTO "verses" VALUES(1931255,2107,3,0,'هر که آن تلخم دهد حلوا بها جانش دهم','هرکسی آن تلخ‌وش را به‌من بیاورد جان شیرینم را به او تقدیم می‌کنم؛ ور بوُد پوشیده و پنهان به دوزخ در روید',NULL);
INSERT INTO "verses" VALUES(1931256,2107,2,1,'عقل و دانش بُرد و شد تا ایمن از وی نغنوید',NULL,NULL);
INSERT INTO "verses" VALUES(1931257,2107,2,0,'جامه‌ای دارد ز لعل و نیمتاجی از حباب','جامه و لباسی سرخ‌رنگ پوشیده و نیم‌تاجی از حباب (درخشان) بر سر دارد عقل و دانش ما را دزدیده پس هیچکس از او در امان نیست.',NULL);
INSERT INTO "verses" VALUES(1931258,2107,1,1,'رفت تا گیرد سر خود، هان و هان حاضر شوید',NULL,NULL);
INSERT INTO "verses" VALUES(1931259,2107,1,0,'دختر رز چند روزی شد که از ما گم شده‌ست','که چند روزی است که دختر رز را گم‌کرده‌ایم رفته تا خود را پنهان کند بیایید بیایید',NULL);
INSERT INTO "verses" VALUES(1931260,2107,0,1,'بشنوید ای ساکنان کوی رندی بشنوید',NULL,NULL);
INSERT INTO "verses" VALUES(1931261,2107,0,0,'بر سر بازار جانبازان منادی می‌زنند','بر سر بازار عاشقان بانگ می‌زنند که ای ساکنان کوی رندی بشنوید',NULL);
INSERT INTO "verses" VALUES(1931262,2106,9,1,'مِیل در چَشم جهان‌بینَش کشید',NULL,NULL);
INSERT INTO "verses" VALUES(1931263,2106,9,0,'آن‌که روشن بُد جهان‌بینش بِدو','فرزند نور چشمی‌اش (شاه شجاع) چشمش را داغ نهاد و او را کور کرد. (جهان‌بین در پارهٔ نخست : چشم / جهان‌بین در پارهٔ دوم : بینا و جهان‌بیننده)',NULL);
INSERT INTO "verses" VALUES(1931264,2106,8,1,'چون مسخّر کرد، وقتش دَررسید',NULL,NULL);
INSERT INTO "verses" VALUES(1931265,2106,8,0,'عاقبت، شیراز و تبریز و عراق','به‌فرجام، آنگاه که همه جا، از شیراز و تبریز و عراق و ...، را فروگرفت، گاهِ نابودی او فرارسید.',NULL);
INSERT INTO "verses" VALUES(1931266,2106,7,1,'گَردَنان را بی‌خطر سَر می‌بُرید',NULL,NULL);
INSERT INTO "verses" VALUES(1931267,2106,7,0,'سَروَران را بی‌سبب می‌کرد حَبس','سروران را بیهوده به زندان می‌افکند و مهتران را بی‌دریغ گردن می‌زد،',NULL);
INSERT INTO "verses" VALUES(1931268,2107,4,0,'دختری شبگردِ تندِ تلخِ گلرنگ است و مست','دختری تند و بدخوست و گلرنگ و مست است؛ اگر او را بیابید به سوی خانه حافظ ببرید.',NULL);
INSERT INTO "verses" VALUES(1931269,2110,0,1,'هرکـ‌او بِخورَد یک جو، بر سیخ زَند سی مرغ',NULL,NULL);
INSERT INTO "verses" VALUES(1931270,2110,1,0,'زآن لقمه که صوفی را، در معرفت اندازد','هوش مصنوعی: از آن لقمه‌ای که می‌تواند یک ذره معرفت به صوفی بدهد، او را در دنیایی از آگاهی غرق کند، و همچنین یک دانه‌ای که قادر است صد نوع خوشحالی و نشاط را به ارمغان بیاورد.',NULL);
INSERT INTO "verses" VALUES(1931271,2110,1,1,'یک ذرّه و صد مَستی، یک دانه و صد سی‌مرغ',NULL,NULL);
INSERT INTO "verses" VALUES(1931272,2116,0,1,'گهی انگشت بر دندان، گهی سر بر سر زانو',NULL,NULL);
INSERT INTO "verses" VALUES(1931273,2116,1,0,'بیا ای طایر دولت، بیاور مژدهٔ وصلی','امیدست که روزها قومی را همان گونه که بودند برگردانند',NULL);
INSERT INTO "verses" VALUES(1931274,2116,1,1,'عَسَی الْاَیّامُ اَنْ یَرْجِعْنَ قَوْماً کَالَّذی کانوا',NULL,NULL);
INSERT INTO "verses" VALUES(1931275,2115,1,1,'فلک بر سر نهادش لوح سنگین',NULL,NULL);
INSERT INTO "verses" VALUES(1931276,2115,1,0,'به جای لوح سیمین در کنارش','این رباعی را حافظ پس از مرگ فرزندش سروده و لابه های یک پدر دل سپخته است',NULL);
INSERT INTO "verses" VALUES(1931277,2115,0,1,'چه دید اندر خم این طاق رنگین',NULL,NULL);
INSERT INTO "verses" VALUES(1931278,2115,0,0,'دلا دیدی که آن فرزانه فرزند','این رباعی را حافظ پس از مرگ فرزندش سروده و لابه های یک پدر دل سپخته است',NULL);
INSERT INTO "verses" VALUES(1931279,2114,3,1,'شد سوی باغِ بهشت، از دامِ این دارِ مِحَن',NULL,NULL);
INSERT INTO "verses" VALUES(1931280,2114,3,0,'مرغِ روحش کـ‌او هُمای آشیانِ قُدس بود','پرنده جانش که همای آشیانه‌ قدس بود، از این دنیای پررنج به‌سوی بهشت رفت.',NULL);
INSERT INTO "verses" VALUES(1931281,2114,2,1,'مِهر را، جوزا مکان و؛ ماه را، خوشه وطن',NULL,NULL);
INSERT INTO "verses" VALUES(1931282,2114,2,0,'هفت‌صد و پنجاه و چار، از هجرتِ خَیرالبَشَر','در سال هفتصد و پنجاه و چهار هجری، که از هجرت پیامبر بزرگوار اسلام می‌گذرد، و در زمانیکه خورشید در برج جوزا و و ماه در برج خوشه قرار داشت.',NULL);
INSERT INTO "verses" VALUES(1931283,2114,1,1,'روزِ آدینه، به حُکمِ کردگارِ ذوالمِنَن',NULL,NULL);
INSERT INTO "verses" VALUES(1931284,2114,1,0,'سادِسِ ماهِ ربیع‌الاخر، اندر نیم‌روز','هوش مصنوعی: در روز جمعه و در نیمه روز در ماه ربیع‌الاخر، به فرمان خداوند مهربان.',NULL);
INSERT INTO "verses" VALUES(1931285,2114,0,1,'صاحبِ صاحب‌قَران، خواجه قوام‌الدین حَسَن',NULL,NULL);
INSERT INTO "verses" VALUES(1931286,2114,0,0,'سَروَرِ اَهلِ عَمایِم، شمعِ جمعِ انجمن','هوش مصنوعی: این بیت به بزرگی و مقام والای شخصیتی اشاره دارد که در میان مردم و در محافل اجتماعی مورد احترام و توجه خاصی است. این فرد با ویژگی‌های برجسته‌اش مانند علم و دانش، به عنوان راهنمای جامعه شناخته می‌شود و به مانند شمعی روشن در میان جمع، دیگران را به سوی روشنایی و دانایی هدایت می‌کند.',NULL);
INSERT INTO "verses" VALUES(1931287,2113,1,1,'اصل ثابت، نسل باقی، تخت عالی، بخت رام',NULL,NULL);
INSERT INTO "verses" VALUES(1931288,2113,1,0,'سال خرّم، فال نیکو، مال وافر، حال خوش','هوش مصنوعی: در سالی خوش و پر برکت، با نشانه‌های خوب و ثروت فراوان، همراه با حالتی شاداب، از نسلی پایدار و میزانی عالی، با بختی بی‌نقص و آرامش زندگی می‌کنیم.',NULL);
INSERT INTO "verses" VALUES(1931289,2111,0,0,'مجد دین سروَر و سلطان قضات اسماعیل','هوش مصنوعی: اسماعیل، نابغه دین و پیشوای قضات، توانست با سخنوری و قدرت بیانش، یک کلام منطبق با اصول شرع بگوید که تأثیر زیادی داشت.',NULL);
INSERT INTO "verses" VALUES(1931290,2111,0,1,'که زدی کلک زبان آورش از شرع نطق',NULL,NULL);
INSERT INTO "verses" VALUES(1931291,2111,1,0,'ناف هفته بد و از ماه رجب کاف و الف','منظور از ناف هفته روز سه شنبه (وسط هفته) است، روز بیست و یکم (کاف و الف به ابجد) و از ماه رجب، که او از این دنیا، که مثال شده به خانه‌ای که در آن نظم و ترتیبی وجود ندارد، رفت و مرد.',NULL);
INSERT INTO "verses" VALUES(1931292,2111,1,1,'که برون رفت از این خانهٔ بی‌نظم و نسق',NULL,NULL);
INSERT INTO "verses" VALUES(1931293,2111,2,0,'کنف رحمت حق منزل او دان و آنگه','هوش مصنوعی: محل رحمت خدا را منزل او بدان و سپس سال وفاتش را از رحمت خدا طلب کن.',NULL);
INSERT INTO "verses" VALUES(1931294,2111,2,1,'سال تاریخ وفاتش طلب از رحمت حق',NULL,NULL);
INSERT INTO "verses" VALUES(1931295,2106,6,1,'در بیابان، نامِ او چون می‌شنید',NULL,NULL);
INSERT INTO "verses" VALUES(1931296,2112,0,0,'بلبل و سرو و سمن یاسمن و لاله و گل','هوش مصنوعی: در این بیت به زیبایی‌های طبیعت اشاره شده است، مانند بلبل، سرو، سمن، یاسمن، لاله و گل. همه این زیبایی‌ها در کنار هم، یادآور خاطره‌ای از شخصیتی خاص هستند که به نوعی با این زیبایی‌ها مرتبط است و مرگ او را گرامی می‌دارند.',NULL);
INSERT INTO "verses" VALUES(1931297,2112,1,0,'خسرو روی زمین غوث زمان بواسحاق','هوش مصنوعی: خسرو، که در زمین بهترین و برتر از همه است، به مانند بواسحاق، مورد توجه و ستایش قرار می‌گیرد. چهره‌اش به حدی زیباست که ماه به او می‌بالد و بر گل‌ها هم می‌خندد.',NULL);
INSERT INTO "verses" VALUES(1931298,2112,1,1,'که به مه طلعت او نازد و خندد بر گل',NULL,NULL);
INSERT INTO "verses" VALUES(1931299,2112,2,0,'جمعه بیست و دوم ماه جمادی الاول','هوش مصنوعی: بیست و دوم جمادی الاول روز جمعه بعد از ظهر بود که آنچه جزئی بود به کل متصل شد.',NULL);
INSERT INTO "verses" VALUES(1931300,2112,2,1,'در پسین بود که پیوسته شد از جزو به کل',NULL,NULL);
INSERT INTO "verses" VALUES(1931301,2113,0,0,'سال و فال و مال و حال و اصل و نسل و تخت و بخت','هوش مصنوعی: برای تو آرزو می‌کنم که در پادشاهی خود سال‌ها بگذرانی و به خوشبختی، مال و حال خوب و ریشه و نسل نیکو دست یابی. امیدوارم حکومتت پایدار و دائمی باشد.',NULL);
INSERT INTO "verses" VALUES(1931302,2113,0,1,'بادت اندر شهریاری، برقرار و بر دوام',NULL,NULL);
INSERT INTO "verses" VALUES(1931303,2112,0,1,'هست تاریخ وفات شه مشکین کاکل',NULL,NULL);
INSERT INTO "verses" VALUES(1931304,2126,3,0,'آن که ده با هفت و نیم آورد بس سودی نکرد','هوش مصنوعی: کسی که سعی کرده با تلاش کمتر و به شیوه‌ای ناقص به هدفی برسد، در حقیقت به نتیجهٔ مطلوبی نخواهد رسید. بهتر است زمان و فرصت را مغتنم بشماری و با تلاش جدی‌تری به سمت هدف‌هایت بروی.',NULL);
INSERT INTO "verses" VALUES(1931305,2106,6,0,'از نَهیبَش، پنجه می‌افکند شیر','آنگاه که شیر در بیابان نام او را می‌شنید، از ترس، ناخن‌هایش می‌ریخت،',NULL);
INSERT INTO "verses" VALUES(1931306,2106,5,0,'گَه به یک حمله، سپاهی می‌شکست','و گاهی با یک تازش، لشکری را شکست می‌داد و گاهی با یک فریاد، میانهٔ لشکر را از هم می‌درید،',NULL);
INSERT INTO "verses" VALUES(1931307,2103,1,0,'لطیفه‌ای به میان آر و خوش بخندانش','هوش مصنوعی: بخندانی و جوکی بگویی که او را خوشحال کند و دلش را شاد کند.',NULL);
INSERT INTO "verses" VALUES(1931308,2103,0,1,'به خلوتی که در او اجنبی صبا باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1931309,2103,0,0,'به سمع خواجه رسان ای ندیم وقت‌شناس','هوش مصنوعی: به دوست باوقار و باخبر بگو که به جایی برویم که تنها باشیم و بادی که غریبه است، در آنجا وزیده شود.',NULL);
INSERT INTO "verses" VALUES(1931310,2102,2,1,'منصور مظفر محمد',NULL,NULL);
INSERT INTO "verses" VALUES(1931311,2102,2,0,'بر مسند خسروی بماناد','هوش مصنوعی: منصور مظفر محمد در جایگاه سلطنت باقی مانده است.',NULL);
INSERT INTO "verses" VALUES(1931312,2102,1,1,'در دولت و حشمت مخلد',NULL,NULL);
INSERT INTO "verses" VALUES(1931313,2102,1,0,'می‌گفت سحر گهی که یا رب','هوش مصنوعی: او می‌گفت در سحرگاهانی که خداوندا، به من نعمت و عظمت دائمی عطا کن.',NULL);
INSERT INTO "verses" VALUES(1931314,2102,0,1,'بر قبهٔ طارم زبرجد',NULL,NULL);
INSERT INTO "verses" VALUES(1931315,2102,0,0,'روح القدس آن سروش فرخ','هوش مصنوعی: فرشتۀ الهی، آن پیام خوشبختی بر بالای قلهٔ بلند سبحان در آسمان می‌تابد.',NULL);
INSERT INTO "verses" VALUES(1931316,2101,5,1,'مهر چنان عروس را هم به کفت حواله باد',NULL,NULL);
INSERT INTO "verses" VALUES(1931317,2101,5,0,'دختر فکر بکر من محرم مدحت تو شد','هوش مصنوعی: دختر باهوش و خلاق من به ستایش تو پرداخت، مانند عروسی که با آرزو به دست تو سپرده شده است.',NULL);
INSERT INTO "verses" VALUES(1931318,2101,4,1,'بر لب خوان قسمتت سهلترین نواله باد',NULL,NULL);
INSERT INTO "verses" VALUES(1931319,2101,4,0,'نه طبق سپهر و آن قرصهٔ ماه و خور که هست','هوش مصنوعی: از آسمان و تابش ماه و خورشید که به تو هدیه شده، نترس و بدان که قسمت تو، راحت‌ترین و شیرین‌ترین برکت است.',NULL);
INSERT INTO "verses" VALUES(1931320,2101,3,1,'حاسدت از سماع آن محرم آه و ناله باد',NULL,NULL);
INSERT INTO "verses" VALUES(1931321,2103,1,1,'به نکته‌ای که دلش را بدان رضا باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1931322,2101,3,0,'چون به هوای مدحتت زهره شود ترانه‌ساز','هوش مصنوعی: وقتی که برای ستایشت موزیسین از شوق و عشق ترانه‌ای می‌سازد، حسادت تو از شور و حال آن، به شکل آه و ناله‌ای در باد جلوه‌گر می‌شود.',NULL);
INSERT INTO "verses" VALUES(1931323,2101,2,0,'ای مه برج منزلت چشم و چراغ عالمی','هوش مصنوعی: ای ماه، تو در اوج مقام خود مانند نور و روشنی بخش جهان هستی. همواره بادهٔ خالص در لیوان و جام تو باشد.',NULL);
INSERT INTO "verses" VALUES(1931324,2101,1,1,'راهروان وهم را راه هزار ساله باد',NULL,NULL);
INSERT INTO "verses" VALUES(1931325,2101,1,0,'ذروهٔ کاخ رتبتت راست ز فرط ارتفاع','هوش مصنوعی: بلندی کاخ مقام تو به حدی است که راهروان در برابرش، تحت تأثیر قرار گرفته و گویی برای رسیدن به آن باید هزار سال سفر کنند.',NULL);
INSERT INTO "verses" VALUES(1931326,2101,0,1,'دشمن دل سیاه تو غرقه به خون چو لاله باد',NULL,NULL);
INSERT INTO "verses" VALUES(1931327,2101,0,0,'دادگرا تو را فلک جرعه کش پیاله باد','هوش مصنوعی: ای دادگر، آسمان در حال نوشیدن است و در این حال دشمن دل سیاه تو، همانند گل لاله‌ای است که غرق در خون است.',NULL);
INSERT INTO "verses" VALUES(1931328,2100,4,1,'هر چه در عالم امر است به فرمان تو باد',NULL,NULL);
INSERT INTO "verses" VALUES(1931329,2100,4,0,'نه به تنها حیوانات و نباتات و جماد','هوش مصنوعی: در اینجا اشاره شده است که نه فقط حیوانات و گیاهان و اشیا بی‌جان، بلکه همه چیز در جهان تحت سلطه و قدرت توست.',NULL);
INSERT INTO "verses" VALUES(1931330,2100,3,1,'غیرت خلد برین ساحت ایوان تو باد',NULL,NULL);
INSERT INTO "verses" VALUES(1931331,2100,3,0,'طیرهٔ جلوهٔ طوبی قد چون سرو تو شد','هوش مصنوعی: جلوهٔ زیبای تو همچون درخت طوبی است و قامت تو مانند سرو. وجود تو باعث غیرت بهشت بر این مکان شده است. ایوان تو همیشه مورد توجه و احترام خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1931332,2100,2,1,'عقل کل چاکر طغراکش دیوان تو باد',NULL,NULL);
INSERT INTO "verses" VALUES(1931333,2100,2,0,'ای که انشاء عطارد صفت شوکت توست','هوش مصنوعی: ای کسی که زیبایی و عظمت تو مانند نازل شده از آسمان است، عقل کل همواره به شکوه و عظمت تو با کمال احترامی خاص توجه دارد.',NULL);
INSERT INTO "verses" VALUES(1931334,2100,1,1,'دیدهٔ فتح ابد عاشق جولان تو باد',NULL,NULL);
INSERT INTO "verses" VALUES(1931335,2100,1,0,'زلف خاتون ظفر شیفتهٔ پرچم توست','هوش مصنوعی: موهای معشوقه پیروزی به پرچم تو عشق می‌ورزد و چشم‌های فتح ابد، به بی‌قراری تو علاقه‌مند است.',NULL);
INSERT INTO "verses" VALUES(1931336,2100,0,1,'ساحت کون ومکان عرصهٔ میدان تو باد',NULL,NULL);
INSERT INTO "verses" VALUES(1931337,2101,2,1,'بادهٔ صاف دایمت در قدح و پیاله باد',NULL,NULL);
INSERT INTO "verses" VALUES(1931338,2103,2,0,'پس آنگهش ز کرم این قدر به لطف بپرس','هوش مصنوعی: درود بر تو، از مهربانی‌ات می‌خواهم که اگر درخواست خاصی از تو داشته باشم، آن را قبول کنی و بر من خرده نگیر.',NULL);
INSERT INTO "verses" VALUES(1931339,2103,2,1,'که گر وظیفه تقاضا کنم روا باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1931340,2104,0,0,'شمه‌ای از داستان عشق شورانگیز ماست','هوش مصنوعی: این داستان‌ها تنها بخشی از عشق پرحرارت ما را بیان می‌کنند، داستان‌هایی که درباره فرهاد و شیرین روایت شده‌اند.',NULL);
INSERT INTO "verses" VALUES(1931341,2106,4,1,'آن‌که از شمشیرِ او خون می‌چکید',NULL,NULL);
INSERT INTO "verses" VALUES(1931342,2106,4,0,'شاهِ غازی، خسروِ گیتی‌سِتان','«شاه جنگجو»، آن فرمانروای کشورگشای که از شمشیرش خون می‌چکید(«شاه غازی» باژنامی است امیر مبارزالدین محمد را که در روزگارِ حافظ پادشاهی می‌کرد)',NULL);
INSERT INTO "verses" VALUES(1931343,2106,3,1,'چون بِدیدی، خَصمِ خود می‌پَروَرید',NULL,NULL);
INSERT INTO "verses" VALUES(1931344,2106,3,0,'بی‌تکلّف هرکه دل بر وِی نهاد','ساده بگویم، اگر خوب بنگری می‌بینی که هرکس به جهان دل بست، سرگرمِ دشمن‌پروردن بود.',NULL);
INSERT INTO "verses" VALUES(1931345,2106,2,1,'چون تمام افروخت، بادش دَردَمید',NULL,NULL);
INSERT INTO "verses" VALUES(1931346,2106,2,0,'هربه ایّامی چراغی برفروخت','روزگار هر از چندگاهی چراغِ بختی را برمی‌افروزد و آنگاه که سراسر فروزان گشت، آن را به بادی فرومی‌نشاند.',NULL);
INSERT INTO "verses" VALUES(1931347,2106,1,1,'کَس رُطَب بی‌خار از این بُستان نچید',NULL,NULL);
INSERT INTO "verses" VALUES(1931348,2106,1,0,'کَس عسل بی‌نیش از این دُکّان نخورد','کسی از خوشی‌های جهان، بدون درد و زخم، بهره‌ نبرده و کسی از جهان، بی‌خار و آسیب، میوه‌ نچیده‌است.',NULL);
INSERT INTO "verses" VALUES(1931349,2106,0,1,'زآن‌که از وی، کَس وفاداری ندید',NULL,NULL);
INSERT INTO "verses" VALUES(1931350,2106,0,0,'دل مَنِه بر دُنیی و اسبابِ او','به زندگی و خواستهٔ اندکِ گیتی دل درمبند زیرا تاکنون هیچکس، از این جهان راستی و درست‌‌پیمانی ندیده است.',NULL);
INSERT INTO "verses" VALUES(1931351,2105,2,1,'آمد حروف سال وفاتش امیذ جود',NULL,NULL);
INSERT INTO "verses" VALUES(1931352,2105,2,0,'تا کس امید جود ندارد دگر ز کس','هوش مصنوعی: این بیت به این معناست که وقتی هیچ‌کس امیدی به بخشش و سخاوت ندارد، دیگر نمی‌توان از کسی انتظار داشت. اشاره به این دارد که در روزگار وفات کسی، حرف‌ها و نشانه‌ها به ما یادآوری می‌کنند که دیگر از او جود و بخشش نمی‌توان دید.',NULL);
INSERT INTO "verses" VALUES(1931353,2105,1,1,'در نصف ماه ذی‌قعد از عرصهٔ وجود',NULL,NULL);
INSERT INTO "verses" VALUES(1931354,2105,1,0,'با آن وجود و آن عظمت زیر خاک رفت','هوش مصنوعی: او با آن همه بزرگی و شکوه، در روز نیمهٔ ماه ذی‌قعد، به زیر خاک رفت و از این دنیا ناپدید شد.',NULL);
INSERT INTO "verses" VALUES(1931355,2105,0,1,'از بهر خاکبوس نمودی فلک سجود',NULL,NULL);
INSERT INTO "verses" VALUES(1931356,2105,0,0,'اعظم قوام دولت و دین آنکه بر درش','هوش مصنوعی: بزرگی و استحکام حکومت و دین به این است که آسمان برای او سجده کند و در برابر درگاه او خاک بیفتد.',NULL);
INSERT INTO "verses" VALUES(1931357,2104,7,0,'شهپر زاغ و زغن زیبای صید و قید نیست','قدیم از پر شهباز یا شاهین سوفار )باله پیکان( میساختند و برای ساختن سوفار شهباز و شاهین شکار میشدند. پس این پرندگان بخاطر خوبی خود شکار میشدند. پر زاغ و کلاغ ارزش بستن به پیکان نداشتند و شکار نمیشدند.',NULL);
INSERT INTO "verses" VALUES(1931358,2104,0,1,'این حکایت‌ها که از فرهاد و شیرین کرده‌اند',NULL,NULL);
INSERT INTO "verses" VALUES(1931359,2104,1,0,'هیچ مژگان دراز و عشوهٔ جادو نکرد','هوش مصنوعی: هیچ مژگان و ناز و عشوه‌ای نتوانسته‌اند به زیبایی و جاذبه‌ای که آن زلف بلند و خال مشکی دارد، اثر بگذارند.',NULL);
INSERT INTO "verses" VALUES(1931360,2104,1,1,'آنچه آن زلف دراز و خال مشکین کرده‌اند',NULL,NULL);
INSERT INTO "verses" VALUES(1931361,2104,2,0,'ساقیا می ده که با حکم ازل تدبیر نیست','هوش مصنوعی: ای ساقی، می بده که آنچه از ابتدا مقدر شده، دیگر قابل تغییر نیست و تدبیر انسان در آن اثری ندارد.',NULL);
INSERT INTO "verses" VALUES(1931362,2104,2,1,'قابل تغییر نبوَد آنچه تعیین کرده‌اند',NULL,NULL);
INSERT INTO "verses" VALUES(1931363,2104,3,0,'در سفالین کاسهٔ رندان به خواری منگرید','هوش مصنوعی: در کاسه‌های سفالی رندان به من به دیدهٔ تحقیر نگاه نکنید، زیرا این دوستان برای خدمت به شما از جامی که جهان را می‌بیند استفاده کرده‌اند.',NULL);
INSERT INTO "verses" VALUES(1931364,2106,5,1,'گَه به هویی، قلبه‌گاهی می‌دَرید',NULL,NULL);
INSERT INTO "verses" VALUES(1931365,2104,3,1,'کـ‌این حریفان خدمت جام جهان‌بین کرده‌اند',NULL,NULL);
INSERT INTO "verses" VALUES(1931366,2104,4,0,'نکهت جانبخش دارد خاک کوی دلبران','هوش مصنوعی: خاک مسیر عاشقان و دلبرانی که در آنجا هستند، بوی خوش و دلپذیری دارد که حس و هوش عارفان را نوازش می‌کند.',NULL);
INSERT INTO "verses" VALUES(1931367,2104,5,0,'ساقیا دیوانه‌ای چون من کجا در بر کشد','هوش مصنوعی: ای ساقی، دیوانه‌ای مانند من را کجا می‌توانی پیدا کنی که دختر گل را به آغوش بگیرد، در حالی که عقل به عنوان مهر و موم او شناخته شده است؟',NULL);
INSERT INTO "verses" VALUES(1931368,2104,5,1,'دختر رز را که نقد عقل کابین کرده‌اند',NULL,NULL);
INSERT INTO "verses" VALUES(1931369,2104,6,0,'خاکیان بی‌بهره‌اند از جرعهٔ کاس الکرام','هوش مصنوعی: آدم‌های معمولی از نعمت‌های بزرگ و ویژه بی‌بهره‌اند، در حالی که عشق و محبت به معشوق‌های بی‌نوا را به بی‌رحمی و فخرفروشی تعبیر می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1931370,2104,6,1,'این تطاوُل بین که با عشّاق مسکین کرده‌اند',NULL,NULL);
INSERT INTO "verses" VALUES(1931371,2104,7,1,'این کرامت همره شهباز و شاهین کرده‌اند',NULL,NULL);
INSERT INTO "verses" VALUES(1931372,2104,4,1,'عارفان آنجا مشامِ عقل مشکین کرده‌اند',NULL,NULL);
INSERT INTO "verses" VALUES(1931373,2126,3,1,'فرصتت بادا که هفت و نیم با ده می‌کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1931375,2128,4,0,'به همنشینی رندان سری فرود آور','هوش مصنوعی: با کنار هم نشستن با افراد با ذوق و آزاداندیش، می‌توان به ارزش‌ها و گنجینه‌های پنهان زندگی دست یافت، حتی اگر خود را بی‌ساز و سامان احساس کنیم.',NULL);
INSERT INTO "verses" VALUES(1931376,2128,4,1,'که گنج‌هاست در این بی‌سری و سامانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931377,2128,3,0,'چه گردها که برانگیختی ز هستی من','هوش مصنوعی: ای کاش هیچ چیز باعث خستگی تو نشود، چرا که تو با شتاب و قدرت بالایی به راهت ادامه می‌دهی و من نمی‌خواهم هیچ گونه ناراحتی برایت پیش بیاید.',NULL);
INSERT INTO "verses" VALUES(1931378,2128,3,1,'مباد خسته سمند‌ت که تیز می‌رانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931379,2128,2,0,'هزار سلطنت دلبری بدان نرسد','به‌هنر‌: بوسیله هنر و هنرمندانه.',NULL);
INSERT INTO "verses" VALUES(1931380,2128,2,1,'که در دلی به هنر خویش را بگنجانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931381,2128,1,0,'بجز شکردهنی مایه‌هاست خوبی را','به خاتمی‌: با یک انگشتر.',NULL);
INSERT INTO "verses" VALUES(1931382,2128,1,1,'به خاتمی نتوان زد دم سلیمانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931383,2128,0,0,'ز دلبری نتوان لاف زد به آسانی','هوش مصنوعی: از محبوبی نمی‌توان به سادگی سخن گفت، چرا که در این موضوع هزاران نکته وجود دارد که باید به آن‌ها توجه کرد.',NULL);
INSERT INTO "verses" VALUES(1931384,2128,0,1,'هزار نکته در این کار هست تا دانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931387,2128,5,0,'بیار بادهٔ رنگین که یک حکایت راست','هوش مصنوعی: می‌گوید که شراب رنگین بیاور تا داستانی را برایت بازگو کنم، بدون اینکه به اصول ایمانم خدشه‌ای وارد کنم.',NULL);
INSERT INTO "verses" VALUES(1931402,2128,5,1,'بگویم و نکنم رخنه در مسلمانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931403,2128,6,0,'به خاک پای صبوحی‌کنان که تا من مست','به خاک پای‌ِ صبوحی‌کنان‌: قسم به خاک پای می‌کشان و باده‌نوشان. (صبوحی‌: می و باده ملایمی است که در صبح برای رفع سر‌درد میگساری شب پیشین می‌نوشند)',NULL);
INSERT INTO "verses" VALUES(1931404,2128,6,1,'ستاده بر در میخانه‌ام به دربانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931405,2128,20,0,'سوابق کرمت را بیان چگونه کنم','هوش مصنوعی: چگونه می‌توانم از سابقه‌های لطف و احسان تو سخن بگویم، که واقعاً شایسته ستایش است و منبع برکت و خلاقیت الهی است.',NULL);
INSERT INTO "verses" VALUES(1931406,2128,19,0,'صواعق سخطت را چگونه شرح دهم','هوش مصنوعی: چگونه می‌توانم توفان‌های خشم خداوند را توصیف کنم؟ پناه بر خدا از آن بلاهای ویرانگر.',NULL);
INSERT INTO "verses" VALUES(1931407,2128,19,1,'نعوذ بالله از آن فتنه‌های طوفانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931408,2128,18,0,'تو را رسد شکر آویز خواجگی گه جود','هوش مصنوعی: شما شایستگی و زیبایی خاصی دارید که می‌توانی به راحتی بخشش و نیکوکاری را در بین انسان‌ها پخش کنی.',NULL);
INSERT INTO "verses" VALUES(1931409,2128,18,1,'که آستین به کریمان عالم افشانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931410,2128,17,0,'درون خلوت کروبیان عالم قدس','صریر کِلک‌: بانگ قلم وقتی‌که بر صفحه و کاغذ کشیده‌می‌شود.',NULL);
INSERT INTO "verses" VALUES(1931411,2128,17,1,'صریر کلک تو باشد سماع روحانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931412,2128,16,0,'کدام پایهٔ تعظیم نصب شاید کرد','هوش مصنوعی: کدام مقام والایی می‌تواند برای احترام و ارادت انتخاب شود که در راه‌های اندیشه از آن بالاتر نباشد؟',NULL);
INSERT INTO "verses" VALUES(1931413,2128,16,1,'که در مسالک فکرت نه برتر از آنی',NULL,NULL);
INSERT INTO "verses" VALUES(1931414,2128,15,0,'تو را که صورت جسم تو را هیولایی است','هوش مصنوعی: شما موجودی هستید که ظاهرت، جسمی مادّی و مادی به نظر می‌رسد، اما در باطن، مانند ماهیتی ملکوتی و روحانی در قالب انسانی نهفته است.',NULL);
INSERT INTO "verses" VALUES(1931415,2128,15,1,'چو جوهر ملکی در لباس انسانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931416,2128,14,0,'اگر نه گنج عطا‌ی تو دستگیر شود','بسیط زمین‌‌: سراسر زمین‌.',NULL);
INSERT INTO "verses" VALUES(1931417,2128,14,1,'همه بسیط زمین رو نهد به ویرانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931418,2128,13,0,'طراز دولت باقی تو را همی‌زیبد','لباس دولت جاویدان بر قامت تو می‌زیبد که چنان بلند‌همّتی که هیچوقت حتی اسمی از دنیا نبرده‌ای و به‌مظاهر دنیوی بی‌توجه هستی.',NULL);
INSERT INTO "verses" VALUES(1931419,2128,13,1,'که همّتت نبُرد نام‌ ِ عالم فانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931420,2128,12,0,'زهی حمیده خصالی که گاه فکر صواب','حمیده‌خصالی‌: نیک‌خویی‌. تو را رسد‌: لیاقت توست، شایسته‌ای.',NULL);
INSERT INTO "verses" VALUES(1931421,2128,12,1,'تو را رسد که کنی دعوی جهانبانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931422,2128,11,0,'قوام دولت دنیی محمد بن علی','هوش مصنوعی: ثبات و استحکام حکومت محمد بن علی باعث درخشش او می‌شود و این درخشش به مانند نوری است که از چهره‌اش ناشی می‌شود و شبیه به زیبایی‌های یزدان (خداوند) است.',NULL);
INSERT INTO "verses" VALUES(1931423,2128,11,1,'که می‌درخشدش از چهره فر یزدانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931424,2128,10,0,'وزیر شاه‌نشان خواجهٔ زمین و زمان','انسی و جانی‌: آدمی و پری.',NULL);
INSERT INTO "verses" VALUES(1931425,2128,10,1,'که خرم است بدو حال انسی و جانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931426,2128,9,0,'مگیر چشم عنایت ز حال حافظ باز','هوش مصنوعی: اگر نگا‌ه پرمهرت را از حال حافظ برنگیری، حالم را برای آصف ثانی تعریف می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1931427,2128,9,1,'وگرنه حال بگویم به آصف ثانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931428,2128,8,0,'به نام طرهٔ دلبند خویش خیری کن','به‌نام طُرّه دلبند‌ خویش: به نیت زلف دلپسند خود.',NULL);
INSERT INTO "verses" VALUES(1931429,2128,8,1,'که تا خداش نگه دارد از پریشانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931430,2128,7,0,'به هیچ زاهد ظاهر‌پرست نگذشتم','هیچ آدم زاهد ظاهر‌بینی را ندیدم که در باطن‌، کافر و بی‌دین نبود.',NULL);
INSERT INTO "verses" VALUES(1931431,2128,7,1,'که زیر خرقه نه زنار داشت پنهانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931464,2128,20,1,'تبارک‌ اللَّه از آن کارساز ربانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931495,2128,21,0,'کنون که شاهد گل را به جلوه‌گاه چمن','هوش مصنوعی: حالا که تنها نسیم صبحگاهی همدمی برای جانم است و در گلزار، هیچ کس جز گل را نمی‌بینم، می‌خواهم آن را تماشا کنم.',NULL);
INSERT INTO "verses" VALUES(1931496,2128,21,1,'به جز نسیم صبا نیست همدم جانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931497,2128,22,0,'شقایق از پی سلطان گل سپارد باز','هوش مصنوعی: شقایق‌ها به دنبال سلطانی از گل، دوباره بر بادبان نسیم صبحگاهی سرهای خود را به سمت آسمان می‌سایند.',NULL);
INSERT INTO "verses" VALUES(1931560,2128,35,0,'ز حافظان جهان کس چو بنده جمع نکرد','هوش مصنوعی: هیچ‌کس در دنیا مانند بنده نتوانسته است لطائف و نکته‌های حکمی را با کتاب قرآن به زیبایی جمع‌آوری کند.',NULL);
INSERT INTO "verses" VALUES(1931561,2128,35,1,'لطایف حکمی با کتاب قرآنی',NULL,NULL);
INSERT INTO "verses" VALUES(1931562,2128,34,0,'طلب نمی‌کنی از من سخن جفا این است','هوش مصنوعی: این جمله به گونه‌ای بیان می‌کند که اگر تو از من نخواهی که در مورد مشکلات سخن بگویم، کار بی‌انصافی است. زیرا در غیر این صورت، من با تو در گفتگو و تبادل نظر مشکلی ندارم و مایلم با تو صحبت کنم.',NULL);
INSERT INTO "verses" VALUES(1931563,2128,34,1,'وگرنه با تو چه بحث است در سخندانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931564,2128,33,0,'شنیده‌ام که ز من یاد می‌کنی گه گه','هوش مصنوعی: شنیده‌ام که گهگاه به یاد من هستی، اما هرگز مرا به مهمانی‌ات دعوت نمی‌کنی.',NULL);
INSERT INTO "verses" VALUES(1931565,2128,33,1,'ولی به مجلس خاص خودم نمی‌خوانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931566,2128,32,0,'تو بودی آن دم صبح امید کز سر مهر','هوش مصنوعی: تو در آن صبحگاه امید بودی که با محبتت به دنیا آمدی و شب تار ظلمانی به پایان رسید.',NULL);
INSERT INTO "verses" VALUES(1931567,2128,32,1,'برآمدی و سر آمد شبان ظلمانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931568,2128,31,0,'طرب‌سرای وزیر است ساقیا مگذار','هوش مصنوعی: در خانه‌ی وزیر، جشنی بر پا است، ای ساقی، نگذار که هیچ چیز دیگری جز جام می، آنجا را سنگین کند.',NULL);
INSERT INTO "verses" VALUES(1931569,2128,31,1,'که غیر جام می آنجا کند گرانجانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931570,2128,30,0,'درون پردهٔ گل غنچه بین که می‌سازد','هوش مصنوعی: در مرکز گل، غنچه‌ای وجود دارد که به خاطر دیدگاه دشمن تو، در حال شکل‌گیری و زیبایی‌اش تحت تأثیر قرار گرفته است.',NULL);
INSERT INTO "verses" VALUES(1931571,2128,30,1,'ز بهر دیدهٔ خصم تو لعل پیکانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931572,2128,29,0,'رموز سر اناالحق چه داند آن غافل','هوش مصنوعی: کسی که از جذبه‌های الهی بی‌خبر و غافل مانده، نمی‌تواند اسرار حقیقت «انا الحق» را درک کند.',NULL);
INSERT INTO "verses" VALUES(1931573,2128,29,1,'که منجذب نشد از جذبه‌های سبحانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931574,2128,28,0,'جفا نه شیوهٔ دین‌پروری بود حاشا','هوش مصنوعی: سخت‌گیری و ظلم راهی برای پرورش دین نیست و به هیچ‌وجه با محبت و بزرگواری که در دین خدا وجود دارد، سازگار نیست.',NULL);
INSERT INTO "verses" VALUES(1931575,2128,28,1,'همه کرامت و لطف است شرع یزدانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931576,2128,27,0,'به شکر تهمت تکفیر کز میان برخاست','هوش مصنوعی: به خاطر این که اتهام کفر از تو دور شده، تلاش کن تا از شادی و لذت زندگی بهره‌مند شوی، گویی از گل و نعمت‌های زیبا بهره می‌گیری.',NULL);
INSERT INTO "verses" VALUES(1931577,2128,27,1,'بکوش کز گل و مل داد عیش بستانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931578,2128,26,0,'مکن که می نخوری بر جمال گل یک ماه','هوش مصنوعی: به خاطر نیاور که به زیبایی گل ماهی تنها نگریسته‌ای و از نوشیدن شراب پرهیز کرده‌ای، چرا که ممکن است در ماه‌های بعد پشیمان شوید که چرا این لذت را از دست داده‌اید.',NULL);
INSERT INTO "verses" VALUES(1931579,2128,26,1,'که باز ماه دگر می‌خوری پشیمانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931580,2128,25,0,'که تنگدل چه نشینی ز پرده بیرون آی','هوش مصنوعی: اگر دلت تنگ است، چرا از پشت پرده بیرون نمی‌آیی؟ زیرا در اینجا، شرابی همچون لعل در خم (شراب‌خانه) وجود دارد که منتظر توست.',NULL);
INSERT INTO "verses" VALUES(1931581,2128,25,1,'که در خم است شرابی چو لعل رمانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931582,2128,24,0,'سحرگهم چه خوش آمد که بلبلی گلبانگ','هوش مصنوعی: در صبحگاهان، چه دلنشین بود زمانی که بلبل با صدای زیباش به غنچه می‌خواند و در حال صحبت کردن بود.',NULL);
INSERT INTO "verses" VALUES(1931583,2128,24,1,'به غنچه می‌زد و می‌گفت در سخنرانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931584,2128,23,0,'بدان رسید ز سعی نسیم باد بهار','هوش مصنوعی: بدان که با تلاش و کوشش نسیم بهاری، نشانه‌های نعمت و برکت حیات نمایان می‌شود، چرا که این نسیم به خاطر لطف و روح زندگی خود، از خود بسیار می‌گوید.',NULL);
INSERT INTO "verses" VALUES(1931585,2128,23,1,'که لاف می‌زند از لطف روح حیوانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931586,2128,22,1,'به بادبان صبا کله‌های نعمانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931587,2128,36,0,'هزار سال بقا بخشدت مدایح من','هوش مصنوعی: مدح‌ها و ستایش‌های من می‌تواند باعث شود که تو برای هزار سال دوام بیاوری، چون این سخنان گران‌بها برای کسی نظیر تو هدیه‌ای ارزشمند است.',NULL);
INSERT INTO "verses" VALUES(1931589,2128,36,1,'چنین نفیس متاعی به چون تو ارزانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931590,2128,37,0,'سخن دراز کشیدم ولی امیدم هست','هوش مصنوعی: من صحبت‌های زیادی کردم، اما امیدوارم که با مهربانی و بخشش، این موضوع را نادیده بگیری.',NULL);
INSERT INTO "verses" VALUES(1931614,2128,39,0,'به باغ ملک ز شاخ امل به عمر دراز','هوش مصنوعی: در باغ ملکت، از شاخه امید، گلی از خوشبختی و کامیابی به عمر طولانی شکوفا شده باشد و بر تو آسان بیفتد.',NULL);
INSERT INTO "verses" VALUES(1931615,2128,39,1,'شکفته باد گل دولتت به آسانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931616,2128,38,0,'همیشه تا به بهاران هوا به صفحهٔ باغ','هوش مصنوعی: در هر بهار، درختان و گل‌ها چهرهٔ باغ را با زیبایی‌های فراوان تزئین می‌کنند، گویی که هوا در آنجا خطوطی زیبا به سبک بوی خوش ریحان به تصویر می‌کشد.',NULL);
INSERT INTO "verses" VALUES(1931617,2128,38,1,'هزار نقش نگارد ز خط ریحانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931618,2128,37,1,'که ذیل عفو بدین ماجرا بپوشانی',NULL,NULL);
INSERT INTO "verses" VALUES(1931620,2146,0,0,'سینه از آتش دل، در غمِ جانانه بسوخت','هوش مصنوعی: دلِ سوخته از عشق، در غم محبوب به آتش درآمد. آتش‌سوزی در خانه‌ای بود که همچون یک مسکن، همه چیز را سوزاند.',NULL);
INSERT INTO "verses" VALUES(1931621,2469,7,1,'چه کنم گر سخنِ پیرِ مُغان نَنْیوشَم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931622,2469,7,0,'من که خواهم که ننوشم به جز از راوَقِ خُم','هوش مصنوعی: من آرزو دارم فقط از شراب خم بنوشم، و چه کنم اگر سخنان حکیمانه عارفان را نشنوم؟',NULL);
INSERT INTO "verses" VALUES(1931623,2469,6,1,'پرده‌ای بر سرِ صد عیبِ نهان می‌پوشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931624,2469,6,0,'خرقه‌پوشیِ من از غایتِ دین‌داری نیست','هوش مصنوعی: من به خاطر دینداری‌ام لباس خاصی بر تن نکرده‌ام، بلکه این پوشش، مانند پرده‌ای است که عیب‌ها و نقص‌های پنهانم را می‌پوشاند.',NULL);
INSERT INTO "verses" VALUES(1931625,2469,5,1,'من چرا مُلکِ جهان را به جوی نفروشم؟!',NULL,NULL);
INSERT INTO "verses" VALUES(1931626,2469,5,0,'پدرم روضهٔ رضوان به دو گندم بفروخت','هوش مصنوعی: پدرم به بهای کمی مثل دو دانه گندم، بهشت را فروخت. حالا من چرا نباید برای رهایی از دنیا، مالکیت تمام جهان را به چیزی کمتر از آن بفروشم؟',NULL);
INSERT INTO "verses" VALUES(1931627,2469,4,1,'فیضِ عَفوَش نَنَهد بارِ گُنَه بر دوشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931628,2469,4,0,'هست امیدم که علیرغمِ عدو روزِ جزا','هوش مصنوعی: امید دارم که با وجود دشمنی‌ها در روز حساب، لطف و بخشش خداوند بار گناهانی که بر دوشم هست را برطرف کند.',NULL);
INSERT INTO "verses" VALUES(1931629,2469,3,1,'این قَدَر هست که گَه گَه قدحی می‌نوشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931630,2469,3,0,'حاشَ لِلَّه که نیَم معتقدِ طاعتِ خویش','هوش مصنوعی: من هرگز به خودم اجازه نمی‌دهم که به طاعت خودم مغرور شوم، زیرا گاهی اوقات قدحی می‌نوشم و از خودم دور می‌شوم.',NULL);
INSERT INTO "verses" VALUES(1931631,2469,2,1,'هندویِ زلفِ بُتی حلقه کُنَد در گوشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931632,2469,2,0,'من کِی آزاد شَوَم از غمِ دل؟ چون هر دَم','هوش مصنوعی: هر لحظه با غم دل درگیر هستم و نمی‌دانم کی از آن رها می‌شوم، چرا که هر بار که به یاد محبوب می‌افتم، گویی زلف او به دور گوشم حلقه می‌زند و نمی‌گذاردم آزاد شوم.',NULL);
INSERT INTO "verses" VALUES(1931633,2469,1,1,'تو مرا بین که در این کار به جان می‌کوشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931634,2469,1,0,'قصدِ جان است طمع در لبِ جانان کردن','هوش مصنوعی: من در تلاش هستم تا به عشق معشوقم دست یابم و این موضوع برای من بسیار جدی و حیاتی است. تو نگاه کن که چقدر برای رسیدن به این هدف جانفشانی می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1931635,2469,0,1,'مُهر بر لب زده، خون می‌خورم و خاموشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931636,2469,0,0,'من که از آتشِ دل چون خُمِ مِی در جوشم','هوش مصنوعی: من از عشق و درد قلبی به شدت می‌جوشم و مانند خُم شراب پر از می‌باشم. اما با این حال، روی لبم مهر سکوت زده‌ام و در خفا به رنج خود ادامه می‌دهم.',NULL);
INSERT INTO "verses" VALUES(1931637,2468,6,1,'مَزَن به ناوَکِ دلدوزِ مردم افکنِ چَشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931638,2468,6,0,'به مردمی که دلِ دردمندِ حافظ را','هوش مصنوعی: به کسانی که دل آزرده حافظ را جریحه‌دار می‌کنند، به یاد داشته باشید که دغدغه‌ها و دردهای دیگران را نادیده نگیرید و به چشمان پر از احساس آنها توجه کنید.',NULL);
INSERT INTO "verses" VALUES(1931639,2468,5,1,'به راهِ باد نهادم چراغِ روشنِ چَشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931640,2468,5,0,'به بویِ مژدهٔ وصلِ تو تا سَحَر، شبِ دوش','هوش مصنوعی: به عطر خوش خبر وصالت تا صبح زود، شب گذشته چراغ روشن چشمانم را به سمت باد گذاشتم.',NULL);
INSERT INTO "verses" VALUES(1931641,2468,4,1,'اگر رسَد خلَلی، خونِ من به گردنِ چَشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931642,2468,4,0,'نخست روز که دیدم رخِ تو دل می‌گفت','هوش مصنوعی: در اولین روزی که چهره‌ات را دیدم، دلم می‌گفت اگر کمترین مشکل یا نقصی در تو پیش بیاید، جانم به خاطر نگاه تو به خطر می‌افتد.',NULL);
INSERT INTO "verses" VALUES(1931643,2468,3,1,'گَرَم نه خونِ جگر می‌گرفت دامنِ چَشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931644,2468,3,0,'سَحَر سِرِشکِ رَوانم سرِ خرابی داشت','هوش مصنوعی: در سپیده‌دم، حسرت و غم من همچون اشک‌های روان است. اگرچه در دل من خون جگر می‌جوشد، اما چشمانم لبریز از درد و اندوه است.',NULL);
INSERT INTO "verses" VALUES(1931645,2468,2,1,'ز گنج‌خانه‌‌ دل می‌کشم به روزنِ چَشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931646,2468,2,0,'بیا که لَعل و گُهَر در نثارِ مَقْدَمِ تو','هوش مصنوعی: بیا که من برای تو، از دل خود زیورهای گران بها و زیبا را به تماشا می‌گذارم، گویا که آن‌ها را از گنجینه قلبم به چشم تو می‌آورم.',NULL);
INSERT INTO "verses" VALUES(1931647,2468,1,1,'منم ز عالَم و این گوشهٔ مُعَیَّنِ چَشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931648,2468,1,0,'سزایِ تکیه گَهَت مَنظَری نمی‌بینم','هوش مصنوعی: من هیچ منظره‌ای مناسب با جایگاه تو نمی‌بینم، من هم از دنیای بیرون و هم از این گوشه‌ای که در آن هستم، چشم انداز خاصی ندارم.',NULL);
INSERT INTO "verses" VALUES(1931649,2468,0,1,'دل از پِیِ نظر آید به سویِ روزنِ چَشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931650,2469,8,0,'گر از این دست زَنَد مُطربِ مجلس رَهِ عشق','هوش مصنوعی: اگر نوازنده در این مجلس نغمه‌ای از عشق بنوازد، شعر حافظ می‌تواند در زمان سماع و جشن، ذهنم را تسخیر کند.',NULL);
INSERT INTO "verses" VALUES(1931651,2468,0,0,'خیالِ رویِ تو چون بُگذَرَد به گلشنِ چَشم','هوش مصنوعی: وقتی یادِ رویِ تو در ذهنم می‌گذرد، چشمان دل بی‌اختیار به سوی روزنه‌ای که در نگاهت وجود دارد می‌نگرند.',NULL);
INSERT INTO "verses" VALUES(1931652,2469,8,1,'شعرِ حافظ بِبَرَد وقتِ سماع از هوشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931653,2470,0,1,'شیوهٔ مستی و رندی نَرَوَد از پیشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931654,2472,1,0,'هرگز به یُمنِ عاطفَتِ پیرِ مِی‌فروش','هوش مصنوعی: هرگز به خاطر محبت و دلسوزی تو، پیر می‌فروش، جام من خالی از شراب صاف و روشن نشد.',NULL);
INSERT INTO "verses" VALUES(1931655,2472,0,1,'کز چاکرانِ پیرِ مُغان کمترین منم',NULL,NULL);
INSERT INTO "verses" VALUES(1931656,2472,0,0,'چِل سال بیش رفت که من لاف می‌زنم','هوش مصنوعی: سال‌هاست که من به خود می‌بالم و می‌گویم که، از میان خدمت‌گزاران پیر و گذشتۀ مغان، من کوچک‌ترین و پست‌ترین آنها هستم.',NULL);
INSERT INTO "verses" VALUES(1931657,2471,6,1,'که با وجودِ تو کس نشنود ز من که منم',NULL,NULL);
INSERT INTO "verses" VALUES(1931658,2471,6,0,'بیا و هستیِ حافظ ز پیشِ او بردار','مصرع دوم : وقتی وجودم سرشار از تو شد ، هیچ چیز و هیچ کس ، از من رفتار و کلامی نخواهد شنید که نشان از من و منیت در آن باشد ) فارغم از هرگونه وابستگی و دلبستگی (',NULL);
INSERT INTO "verses" VALUES(1931659,2471,5,1,'که سوزهاست نهانی درونِ پیرهنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931660,2471,5,0,'طرازِ پیرهنِ زَرکشم مبین چون شمع','هوش مصنوعی: پوشش من را مانند زره‌ی زرین مبر، زیرا مانند شمعی هستم که درونش آتش‌های پنهان وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1931661,2471,4,1,'عجب مدار که هم‌دردِ نافهٔ خُتنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931662,2471,4,0,'اگر ز خونِ دلم بویِ شوق می‌آید','هوش مصنوعی: اگر از عمق جانم بوی عشق و شوق به مشام می‌رسد، جای تعجب نیست که من نیز همدرد و شریک دردِ عاشقانی هستم که به یاد محبوب خود ناله می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1931663,2471,3,1,'که در سراچهٔ ترکیب، تخته‌‌بندِ تنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931664,2471,3,0,'چگونه طوف کنم در فضایِ عالمِ قدس؟','هوش مصنوعی: چطور می‌توانم در دنیای روحانی و مقدس پرواز کنم، در حالی که بدنم همچون قفسی مرا محبوس کرده است؟',NULL);
INSERT INTO "verses" VALUES(1931665,2471,2,1,'دریغ و درد که غافل ز کارِ خویشتنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931666,2471,2,0,'عیان نشد که چرا آمدم، کجا رفتم','هوش مصنوعی: نمی‌دانم چرا به دنیا آمده‌ام و کجا باید بروم. افسوس که غافل از مسائل خودم هستم.',NULL);
INSERT INTO "verses" VALUES(1931667,2471,1,1,'رَوَم به گلشنِ رضوان، که مرغِ آن چمنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931668,2471,1,0,'چُنین قفس نه سزایِ چو من خوش‌اَلحانی‌ست','هوش مصنوعی: این قفس برای کسی مثل من که خوش‌آواز است، مناسب نیست. می‌خواهم به باغ بهشت بروم، زیرا من پرنده‌ی آن باغ هستم.',NULL);
INSERT INTO "verses" VALUES(1931669,2471,0,1,'خوشا دَمی که از آن چهره پرده برفکنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931670,2471,0,0,'حجابِ چهرهٔ جان می‌شود غبارِ تنم','هوش مصنوعی: وجود مادی و ظاهری من مانع می‌شود که نور و زیبایی واقعی روحم دیده شود، خوشا به حال لحظه‌ای که بتوانم این حجاب را کنار بزنم و حقیقت درونم را به نمایش بگذارم.',NULL);
INSERT INTO "verses" VALUES(1931671,2470,6,1,'حافظِ رازِ خود و عارفِ وقتِ خویشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931672,2470,6,0,'من اگر باده خورم ور نه چه کارم با کس؟','هوش مصنوعی: اگر من شراب نوشم یا نوشم نکرده، چه ارتباطی با دیگران دارم؟ من حافظ رازهای خودم هستم و درک‌کننده زمان خودم.',NULL);
INSERT INTO "verses" VALUES(1931673,2470,5,1,'که ز مژگانِ سیَه، بر رگِ جان زد نیشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931674,2470,5,0,'شعر خونبارِ من ای باد، بِدان یار رسان','هوش مصنوعی: ای باد، به آن یار برسان که شعر پرخونی که می‌نویسم، ناشی از درد و غم عمیقی است که از دیده‌های سیاه‌ام بر جانم می‌نشیند.',NULL);
INSERT INTO "verses" VALUES(1931675,2470,4,1,'تا در این خرقه ندانی که چه نادَرویشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931676,2470,4,0,'اعتقادی بِنُما و بِگُذَر بهرِ خدا','هوش مصنوعی: ایمانت را بروز بده و به خاطر خدا از هر چیزی بگذر تا در این لباس ریا متوجه نشوی که چه اندازه فقیر و بی‌چیز هستم.',NULL);
INSERT INTO "verses" VALUES(1931677,2470,3,1,'تا بدانند که قربانِ تو کافِرکیشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931678,2470,3,0,'بر جَبین نقش کُن از خونِ دلِ من خالی','هوش مصنوعی: بر پیشانی‌ام نشانه‌ای از عشق و محبت بگذار تا همه بدانند که من در راه تو جانم را فدای تو کرده‌ام.',NULL);
INSERT INTO "verses" VALUES(1931679,2470,2,1,'زان که در کم‌خِرَدی از همه عالم بیشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931680,2470,2,0,'شاهِ شوریده‌سران خوان، منِ بی‌سامان را','هوش مصنوعی: حاکم دیوانه‌وار یک جامعه، به من که در دنیای بی‌نظمی و بی‌تقوایی زندگی می‌کنم، اهمیت می‌دهد زیرا در نادانی و ناتوانی از دیگران برتر هستم.',NULL);
INSERT INTO "verses" VALUES(1931681,2470,1,1,'من که بدنامِ جهانم چه صلاح اندیشم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931682,2470,1,0,'زهدِ رندانِ نوآموخته راهی به دِهیست','هوش مصنوعی: رهنمودهای پارساهای تازه‌کار، راهی به دیاری است که من در آن به بدنامی شهرت دارم. در این شرایط، چه فایده‌ای در اندیشیدن به صلاح و نیکی وجود دارد؟',NULL);
INSERT INTO "verses" VALUES(1931683,2470,0,0,'گر من از سرزنشِ مدَّعیان اندیشم','هوش مصنوعی: اگر به سخنان سرزنش‌آمیز مدعیان فکر کنم، دیگر نمی‌توانم به راه و روش خوش‌گذرانی و آزادی‌خواهی ادامه دهم.',NULL);
INSERT INTO "verses" VALUES(1931684,2467,8,1,'آیینه‌ای ندارم از آن آه می‌کشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931685,2467,8,0,'حافظ عروسِ طَبعِ مرا جلوه آرزوست','هوش مصنوعی: حافظ می‌گوید که زیبایی و جذابیت عواطف و احساسات من به مانند عروسی است که آرزوهایم را به نمایش می‌گذارد، اما من از آنچه در دل دارم، هیچ نشانه‌ای ندارم و به همین دلیل در دل خود آه می‌کشم.',NULL);
INSERT INTO "verses" VALUES(1931686,2467,7,1,'گیسویِ حور گَرد فشاند ز مَفْرَشَم',NULL,NULL);
INSERT INTO "verses" VALUES(1931687,2465,4,0,'خیز و بالا بنما ای بتِ شیرین حرکات','ای معشوق زیبا و دلربا برخیز و قامت و زیبایی خود را نشان بده زیرا من از سرِ جان و جهان (از همه وابستگی‌های دنیوی و حتی جان خود) دست می‌شویم و رها می‌شوم.',NULL);
INSERT INTO "verses" VALUES(1931688,2465,3,1,'تا به بویت ز لحد رقص کُنان برخیزم',NULL,NULL);
INSERT INTO "verses" VALUES(1931689,2465,3,0,'بر سرِ تربتِ من با مِی و مُطرب بنشین','بر سر خاک من با شراب و نوازنده بنشین و شادی کن تا که من نیز با بوی وجود تو دوباره زنده شوم و رقص کنان از خاک بلند شوم',NULL);
INSERT INTO "verses" VALUES(1931690,2465,2,1,'پیشتر زان که چو گَردی ز میان برخیزم',NULL,NULL);
INSERT INTO "verses" VALUES(1931691,2465,2,0,'یا رب از ابرِ هدایت بِرَسان بارانی','پروردگارا از ابر هدایت و راهنمایی بر ما بارانی برسان (مارا راهنمایی کن) تا قبل از اینکه مهلت زندگیم به پایان رسد و بدون رستگاری چشم از این جهان فروبندم (بارش باران و بلند شدن گرد ، هنگامی که باران ببارد زمین گل شده و خاک بلند نمی شود خاک و آب < گل > عنصر وجودی انسان)',NULL);
INSERT INTO "verses" VALUES(1931692,2465,1,1,'از سرِ خواجگیِ کون و مکان برخیزم',NULL,NULL);
INSERT INTO "verses" VALUES(1931693,2465,1,0,'به ولای تو که گر بندهٔ خویشم خوانی','قسم به محبت تو که اگر مرا بنده خود بخوانی من برای بندگی تو حاضرم سروری جهان را رها کنم تا بنده‌ی تو باشم',NULL);
INSERT INTO "verses" VALUES(1931694,2465,0,1,'طایرِ قُدسم و از دامِ جهان برخیزم',NULL,NULL);
INSERT INTO "verses" VALUES(1931695,2465,0,0,'مژدهٔ وصلِ تو کو کز سرِ جان برخیزم','هنگامی که خبر رسیدن به تو (معشوق و معبود) به من داده شود من از زندگی و نیرنگ های او دست می کشم و از جان خود می گذرم تا به تو برسم',NULL);
INSERT INTO "verses" VALUES(1931696,2464,8,1,'همچو زلفت همه را در قدمت اندازم',NULL,NULL);
INSERT INTO "verses" VALUES(1931697,2464,8,0,'گر به هر موی، سری بر تنِ حافظ باشد','هوش مصنوعی: اگر به هر مویی یک سر بر تن حافظ باشد، مانند زلف تو، همه آن‌ها را در پای تو می‌ریزم.',NULL);
INSERT INTO "verses" VALUES(1931698,2464,7,1,'زان که جز تیغِ غمت نیست کسی دَمسازم',NULL,NULL);
INSERT INTO "verses" VALUES(1931699,2464,7,0,'ماجرایِ دلِ خون گشته نگویم با کس','هوش مصنوعی: من ماجرای دل شکسته و غمگینم را برای کسی نمی‌گویم، زیرا هیچ‌کس جز تیغ درد عشق تو، نمی‌تواند با من همدردی کند.',NULL);
INSERT INTO "verses" VALUES(1931700,2464,6,1,'از لبِ خویش چو نِی یک نفسی بِنْوازم',NULL,NULL);
INSERT INTO "verses" VALUES(1931701,2464,6,0,'همچو چنگ ار به کناری ندهی کامِ دلم','اگر همچون ساز چنگ مرا در آغوش نگیری و ننوازی حداقل همچون نی مرا با لبانت یک لحظه بنواز (کنار: آغوش)',NULL);
INSERT INTO "verses" VALUES(1931702,2464,5,1,'به هوایی که مگر صید کُنَد شهبازم',NULL,NULL);
INSERT INTO "verses" VALUES(1931703,2464,5,0,'مرغْ سان از قفسِ خاک هوایی گشتم','هوش مصنوعی: به مانند پرنده‌ای که از قفس خاکی خود آزاد شده‌ام، به دنیای جدیدی پا گذاشته‌ام که شاید بتواند مرا به سوی شکار شهباز راهی کند.',NULL);
INSERT INTO "verses" VALUES(1931704,2464,4,1,'چشمِ تَر دامن اگر فاش نکردی رازم',NULL,NULL);
INSERT INTO "verses" VALUES(1931705,2464,4,0,'سِرِّ سودایِ تو در سینه بماندی پنهان','هوش مصنوعی: آرزو و عشق تو در دل من مخفی مانده و اگر تو تاکنون راز مرا فاش نکرده‌ای، دلیلی بر این است که هنوز عاشقانه به یاد تو هستم.',NULL);
INSERT INTO "verses" VALUES(1931706,2464,3,1,'با خیالِ تو اگر با دِگری پردازم',NULL,NULL);
INSERT INTO "verses" VALUES(1931707,2464,3,0,'صحبتِ حور نخواهم که بُوَد عینِ قُصور','هوش مصنوعی: من نمی‌خواهم درباره‌ی زیبایی‌های حوریان صحبت کنم، چون این موضوع خود به تنهایی مانند زندگی در قصر می‌ماند. اگر با خیال تو، به کسی دیگر فکر کنم و سخن بگویم، برایم بی‌معناست.',NULL);
INSERT INTO "verses" VALUES(1931708,2464,2,1,'جز بدان عارضِ شمعی نَبُوَد پروازم',NULL,NULL);
INSERT INTO "verses" VALUES(1931709,2464,2,0,'ور چو پروانه دهد دست، فَراغِ بالی','هوش مصنوعی: اگر دست به من بدهد، پرواز من تنها به خاطر زیبایی آن شمع خواهد بود و هیچ پرواز دیگری ندارم.',NULL);
INSERT INTO "verses" VALUES(1931710,2464,1,1,'خازنِ میکده فردا نَکُنَد در، بازم',NULL,NULL);
INSERT INTO "verses" VALUES(1931711,2464,1,0,'حلقهٔ توبه گر امروز چو زُهّاد زنم','هوش مصنوعی: امروز تصمیم به توبه دارم و مانند زاهدان عمل می‌کنم، اما فردا اگر خواستم به میخانه بروم، کسی نمی‌تواند مانع ورود من شود.',NULL);
INSERT INTO "verses" VALUES(1931712,2464,0,1,'حاصلِ خرقه و سجاده، روان دربازم',NULL,NULL);
INSERT INTO "verses" VALUES(1931713,2464,0,0,'در خراباتِ مُغان گر گذر افتد بازم','هوش مصنوعی: اگر در میخانه‌ی مغان قدم بگذارم، می‌دانم که با خودم، چیزی جز دوستی و محبت نخواهم برد.',NULL);
INSERT INTO "verses" VALUES(1931714,2463,8,1,'جز جام نشاید که بُوَد محرمِ رازم',NULL,NULL);
INSERT INTO "verses" VALUES(1931715,2463,8,0,'حافظ غمِ دل با که بگویم؟ که در این دور','هوش مصنوعی: حافظ از کس نمی‌تواند درد دلش را بگوید، چرا که در این زمانه فقط شراب است که می‌تواند رازهای او را درک کند و محرم اسرارش باشد.',NULL);
INSERT INTO "verses" VALUES(1931716,2465,4,1,'کز سرِ جان و جهان دست فشان برخیزم',NULL,NULL);
INSERT INTO "verses" VALUES(1931717,2465,5,0,'گرچه پیرم تو شبی تنگ در آغوشم کَش','با اینکه پیر شده ام و دیگر جوان نیستم اگر تو مرا شبی در آغوش گیری با وجود تو صبح جوان از بستر بلند می شوم',NULL);
INSERT INTO "verses" VALUES(1931718,2465,5,1,'تا سحرگه ز کنارِ تو جوان برخیزم',NULL,NULL);
INSERT INTO "verses" VALUES(1931719,2465,6,0,'روز مرگم نفسی مهلتِ دیدار بده','در روز مرگم اگر لحظه ای به دیدن من بیایی و مرا ببینی من نیز مانند حافظ با شادی جهان را ترک بگوییم و جانم را رها می کنم',NULL);
INSERT INTO "verses" VALUES(1931720,2467,7,0,'بخت ار مدد دهد که کَشَم رَخت سویِ دوست','اگر بخت یاری‌ام کند که دار و ندارم را به سوی محبوب ببرم (به سوی دوست سفر کنم)، آنگه حوران بهشتی با گیسوان خود از فرش من (اسباب سفرم) گرد راه را پاک می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1931721,2467,6,1,'چیزیم نیست وَر نه خریدارِ هر شَشَم',NULL,NULL);
INSERT INTO "verses" VALUES(1931722,2467,6,0,'شهریست پُر کِرشمهٔ حوران ز شِش جهت','شهری است که از هر طرف پر از ناز و کرشمهٔ حوران و زیبارویان است. من از (مال و منال) دنیا چیزی ندارم وگرنه خریدار همه حوران و زیبارویان این شهر هستم.',NULL);
INSERT INTO "verses" VALUES(1931723,2467,5,1,'حقّا که مِی نمی‌خورم اکنون و سَرخوشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931724,2467,5,0,'از بس که چَشمِ مست در این شهر دیده‌ام','از بس که چشمان مستانه‌ و خمارآلود را در این شهر دیده‌ام، واقعاً این روزها دیگر شراب نمی‌خورم (نیازی به خوردن شراب با وجود این چشمان مست ندارم) و خوشحالم (چون شراب من چشمان مست زیبارویان شهر است).',NULL);
INSERT INTO "verses" VALUES(1931725,2467,4,1,'من جوهریِّ مُفلِسَم، ایرا مُشَوَّشَم',NULL,NULL);
INSERT INTO "verses" VALUES(1931726,2467,4,0,'شیراز معدنِ لبِ لَعل است و کانِ حُسن','شیراز سرشار از (دلبران با) لب های لعل گون است و معدن زیبایی. من گوهر فروش (زرگر) مفلس‌ام و بدین سبب پریشان‌ام (که ازین گهرها، یعنی لب لعل‌گون و حسن دلبران، مستفید شده نمیتوانم).',NULL);
INSERT INTO "verses" VALUES(1931727,2467,3,1,'اِسْتادِه‌ام چو شمع، مَتَرسان ز آتشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931728,2467,3,0,'در عاشقی گزیر نباشد ز ساز و سوز','در عشق، از ساز (موسیقی) و سوختن دل (شادی و غم) چاره و فراری وجود ندارد. من همچون شمع ایستاده‌ام (و میسوزم)، مرا از شعلهٔ آتش مترسان.',NULL);
INSERT INTO "verses" VALUES(1931729,2467,2,1,'حالی اسیرِ عشقِ جوانان مَهوَشَم',NULL,NULL);
INSERT INTO "verses" VALUES(1931730,2467,2,0,'من آدمِ بهشتیَم اما در این سفر','من آدم بهشتی ام، اما در این سفر (زندگی)، اسیر و گرفتار عشق جوانان زیبا هستم.',NULL);
INSERT INTO "verses" VALUES(1931731,2467,1,1,'آنگَه بگویمت که دو پیمانه دَر کَشَم',NULL,NULL);
INSERT INTO "verses" VALUES(1931732,2467,1,0,'گفتی ز سِرِّ عهدِ ازل یک سخن بگو','گفتی از راز عهد ازل (پیمانی که خدا با انسان پیش از آفرینش جهان بسته است) یک سخن بگو. بعد از آن می‌گویم که دو پیمانه می‌ نوشم.',NULL);
INSERT INTO "verses" VALUES(1931733,2467,0,1,'مَدهوشِ چَشمِ مست و مِیِ صافِ بی‌غَشَم',NULL,NULL);
INSERT INTO "verses" VALUES(1931734,2472,1,1,'ساغر تُهی نشد ز مِیِ صافِ روشنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931735,2467,0,0,'من دوستدارِ رویِ خوش و مویِ دلکَشَم','هوش مصنوعی: من عاشق چهره‌ی زیبا و موهای دل‌انگیزم و از نگاه سرمست و شراب خالصی که بی‌ریا و صاف است، شگفت‌زده و مسحور شده‌ام.',NULL);
INSERT INTO "verses" VALUES(1931736,2466,6,0,'بُوَد که لطفِ ازل رهنمون شود حافظ','امیدوارم که لطف ازلی و خدایی راهنمایی کند ای حافظ! وگرنه تا ابد شرمسار خود خواهم بود.',NULL);
INSERT INTO "verses" VALUES(1931737,2466,5,1,'دگر بکوشم و مشغولِ کارِ خود باشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931738,2466,5,0,'همیشه پیشهٔ من عاشقی و رندی بود','شغل من همیشه عاشقی و رندی بوده است، پس از این نیز به همین پیشه می‌پردازم.',NULL);
INSERT INTO "verses" VALUES(1931739,2466,4,1,'گَرَم بُوَد گِلِه‌ای، رازدارِ خود باشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931740,2466,4,0,'ز دستِ بختِ گران‌خواب و کارِ بی‌سامان','اگر هم از دست بخت بی‌خیال و زندگی بی‌سامان خود شکایتی داشته‌باشم، با خودم درد دل می‌گویم.',NULL);
INSERT INTO "verses" VALUES(1931741,2466,3,1,'که روزِ واقعه پیشِ نگارِ خود باشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931742,2466,3,0,'چو کار عمر نه پیداست باری آن اولی','وقتی که عاقبت زندگی خود را نمی‌دانم پس همان بهتر که در روز مرگ (یا سختی) در نزد یار خود باشم.',NULL);
INSERT INTO "verses" VALUES(1931743,2466,2,1,'ز بندگانِ خداوندگارِ خود باشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931744,2466,2,0,'ز مَحرمان سراپردهٔ وصال شَوَم','از نزدیکان اندرونی می‌شوم و به وصال می‌رسم؛ از بندگان محبوب خود می‌شوم.',NULL);
INSERT INTO "verses" VALUES(1931745,2466,1,1,'به شهرِ خود رَوَم و شهریارِ خود باشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931746,2466,1,0,'غمِ غریبی و غربت چو بر نمی‌تابم','وقتی‌که غم غریبی و دیار غربت را نمی‌توانم تحمل کنم؛ پس به دیار و وطن خود می‌روم و آقا و شاه خود می‌شوم..',NULL);
INSERT INTO "verses" VALUES(1931747,2466,0,1,'چرا نه خاکِ سرِ کویِ یارِ خود باشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931748,2466,0,0,'چرا نه در پِیِ عزمِ دیارِ خود باشم','چرا به دیار خود نروم؟ چرا به نزد معشوق خود نروم؟',NULL);
INSERT INTO "verses" VALUES(1931749,2465,6,1,'تا چو حافظ ز سرِ جان و جهان برخیزم',NULL,NULL);
INSERT INTO "verses" VALUES(1931750,2466,6,1,'وگرنه تا به ابد شرمسارِ خود باشم',NULL,NULL);
INSERT INTO "verses" VALUES(1931751,2472,2,0,'از جاهِ عشق و دولتِ رندانِ پاک‌باز','هوش مصنوعی: به خاطر عشق و بزرگی افرادی که پاکباز و باوفا هستند، همیشه بر بالای جایگاه‌های ناشناخته، منزل و زندگی‌ام قرار دارد.',NULL);
INSERT INTO "verses" VALUES(1931752,2472,2,1,'پیوسته صدرِ مَصطَبِه‌ها بود مَسکنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931753,2472,3,0,'در شأنِ من به دُردکِشی ظنِّ بَد مبر','هوش مصنوعی: به من گمان بد نبر، حتی اگر جامه‌ام کثیف شده باشد، چون من آدمی با پاکدامنی هستم.',NULL);
INSERT INTO "verses" VALUES(1931754,2478,1,0,'قامتش را سرو گفتم، سر کشید از من به خشم','هوش مصنوعی: گفتم که قدش مثل درخت سرو است، اما او با عصبانیت بر من نگریست. دوستانم از راست به او آسیب می‌زنند، حالا من چه باید بکنم؟',NULL);
INSERT INTO "verses" VALUES(1931755,2478,0,1,'گفت کو زنجیر؟ تا تدبیرِ این مجنون کُنَم',NULL,NULL);
INSERT INTO "verses" VALUES(1931756,2478,0,0,'دوش سودایِ رُخَش گفتم ز سر بیرون کُنَم','هوش مصنوعی: شب گذشته به خیال زیبایی‌ات فکر می‌کردم و می‌خواستم این فکر را از سرم بیرون کنم، اما گفت: کجا می‌توانم زنجیر را پیدا کنم؟ تا بتوانم برای این دیوانگی تدبیری بیندیشم.',NULL);
INSERT INTO "verses" VALUES(1931757,2477,6,1,'من چرا عِشرتِ امروز به فردا فکنم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931758,2477,5,1,'غُلغُلِ چنگ در این گنبدِ مینا فکنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931759,2477,6,0,'حافظا! تکیه بر ایّام چو سهو است و خطا','هوش مصنوعی: حافظ می‌گوید که تکیه بر روزهای آینده اشتباه و خطاست. چرا باید لذت و خوشی امروز را به فردا منتقل کنم و از آن محروم بمانم؟',NULL);
INSERT INTO "verses" VALUES(1931760,2477,4,1,'عُقده در بندِ کَمرتَرکشِ جوزا فکنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931761,2477,5,0,'جرعهٔ جام بر این تختِ روان افشانم','هوش مصنوعی: من یک جرعه از شراب را بر این تختِ روان می‌ریزم و صدای چنگ را در این گنبدِ مینا پخش می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1931762,2477,3,1,'تا چو زلفت سَرِ سودا زده در پا فکنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931763,2477,4,0,'خورده‌ام تیرِ فلک، باده بده تا سرمست','هوش مصنوعی: زندگی بر من سخت و پر از مشکلات بوده است، بگذار جرعه‌ای بنوشم تا بتوانم با شادی و مستی، تمام این زخم‌ها و عذاب‌ها را فراموش کنم و به تو نزدیک شوم.',NULL);
INSERT INTO "verses" VALUES(1931764,2477,2,1,'می‌کنم جهد که خود را مگر آن جا فکنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931765,2477,3,0,'بِگشا بندِ قبا ای مهِ خورشیدکلاه!','هوش مصنوعی: بند قبا را بگشا ای ماه مانند خورشید، تا من نیز مانند زلف‌های تو، عشق و شوق خود را به نمایش بگذارم.',NULL);
INSERT INTO "verses" VALUES(1931766,2477,1,1,'کآتش اندر گنهِ آدم و حوا فکنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931767,2477,2,0,'مایهٔ خوش‌دلی آن جاست که دل‌دار آن جاست','هوش مصنوعی: دلشاد بودن به این است که معشوق در کنار ما باشد. من تلاش می‌کنم تا خود را به آن‌جا برسانم و در کنار او باشم.',NULL);
INSERT INTO "verses" VALUES(1931768,2477,0,1,'وَاندر این کار، دلِ خویش به دریا فِکنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931769,2477,1,0,'از دلِ تنگِ گنه‌کار برآرم آهی','هوش مصنوعی: از دل پر از ناراحتی گناهکار، آهی می‌کشم که بتواند آتش را در گناه آدم و حوا بیفکند.',NULL);
INSERT INTO "verses" VALUES(1931770,2477,0,0,'دیده دریا کُنم و صبر به صحرا فِکنم','هوش مصنوعی: می‌خواهم چشمانم را مانند دریا وسیع و عمیق کنم و صبرم را به بیابان رها کنم. در این میان، دل خود را به دریا بسپارم.',NULL);
INSERT INTO "verses" VALUES(1931771,2476,7,1,'چون که تقدیر چُنین است، چه تدبیر کنم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931772,2476,7,0,'نیست امّید صَلاحی ز فسادِ حافظ','هوش مصنوعی: امید به بهبودی از بدی‌های حافظ وجود ندارد، زیرا تقدیر چنین رقم خورده است، پس من چه تدبیری می‌توانم بیندیشم؟',NULL);
INSERT INTO "verses" VALUES(1931773,2476,6,1,'من نه آنم که دگر گوش به تزویر کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931774,2476,6,0,'دور شو از برم ای واعظ و بیهوده مگوی','هوش مصنوعی: از کنارم دور شو، ای واعظ! هرگز وقت من را به بیهوده‌گویی تلف نکن. من کسی نیستم که بخواهم به فریب و دغل‌کاری گوش دهم.',NULL);
INSERT INTO "verses" VALUES(1931775,2476,5,1,'دین و دل را همه دَربازم و توفیر کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931776,2476,5,0,'گر بدانم که وصالِ تو بدین دست دهد','هوش مصنوعی: اگر بدانم که رسیدن به تو اینقدر آسان است، تمام ایمان و دل خود را برایت آماده می‌کنم و هرچیزی را برایت فدای تو می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1931777,2476,4,1,'در نظر نقشِ رخِ خوبِ تو تصویر کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931778,2476,4,0,'آن زمان کآرزویِ دیدنِ جانم باشد','هوش مصنوعی: زمانی که آرزویم دیدن تو باشد، در آن لحظه تصویر چهره‌ی زیبات را در ذهنم مجسم می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1931779,2476,3,1,'کو مجالی که سراسر همه تقریر کنم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931780,2476,3,0,'با سرِ زلفِ تو مجموعِ پریشانی خود','از آن لحظه که در پیچ‌وتاب زلف تو گم شدم، دیگر مجالی برای پرداختن به هیچ درد و پریشانیِ دیگری نماند؛ همه‌ی فکر و یادم در همان سرِ زلف تو متوقف شده است',NULL);
INSERT INTO "verses" VALUES(1931781,2476,2,1,'در یکی نامه محال است که تَحریر کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931782,2476,2,0,'آن چه در مدتِ هِجرِ تو کشیدم هیهات','هوش مصنوعی: آنچه در دوران فراق تو تجربه کرده‌ام، هرگز نمی‌توانم در یک نامه به طور مستقیم و کامل بیان کنم.',NULL);
INSERT INTO "verses" VALUES(1931783,2478,1,1,'دوستان از راست می‌رَنجَد نِگارم، چون کنم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931784,2478,2,0,'نکته ناسنجیده گفتم دلبرا معذور دار','هوش مصنوعی: من یک نکته‌ی سنجیده نگفتم، ای محبوب، لطفاً این مورد را ببخش. کمی محبت و دلربایی کن تا من بتوانم شعر خود را به نظم درآورم.',NULL);
INSERT INTO "verses" VALUES(1931785,2478,2,1,'عشوه‌ای فرمای تا من طبع را موزون کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931786,2478,3,0,'زردرویی می‌کَشَم زان طبعِ نازک، بی‌گناه','هوش مصنوعی: از سر لطافت و زیبایی که در چهره‌ام دارم، دلی آشفته و زردرنگ دارم. ای ساقی بی‌گناه، لطفاً جامی به من بده تا بتوانم رنگ و رویی زیبا و شاداب به چهره‌ام ببخشم.',NULL);
INSERT INTO "verses" VALUES(1931787,2480,2,0,'از قیل و قالِ مدرسه حالی دلم گرفت','هوش مصنوعی: از سر و صدای مدرسه دلم گرفته است و حالا می‌خواهم کمی به معشوق و شراب خدمت کنم.',NULL);
INSERT INTO "verses" VALUES(1931788,2480,1,1,'در کارِ چنگ و بَربَط و آوازِ نِی کُنَم',NULL,NULL);
INSERT INTO "verses" VALUES(1931789,2480,1,0,'مطرب کجاست تا همه محصولِ زهد و عِلم','هوش مصنوعی: کجا هستند نوازندگان تا من میوه‌های زهد و دانش خود را در نواختن چنگ و بربط و آواز نی به کار ببرم؟',NULL);
INSERT INTO "verses" VALUES(1931790,2480,0,1,'من لافِ عقل می‌زنم، این کار کِی کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931791,2480,0,0,'حاشا که من به موسمِ گُل تَرکِ مِی کُنم','هوش مصنوعی: هرگز در زمانی که گل‌ها شکوفه زده‌اند، کنار گذاشتن نوشیدنی را نمی‌پذیرم. من مدام از دانایی و خرد خود صحبت می‌کنم، اما این کار را هرگز نخواهم کرد.',NULL);
INSERT INTO "verses" VALUES(1931792,2479,8,1,'به بانگِ بَربَط و نِی، رازَش آشکاره کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931793,2479,8,0,'ز باده خوردن پنهان مَلول شد حافظ','هوش مصنوعی: حافظ به خاطر نوشیدن پنهانی شراب، دچار دلتنگی شده و با صدای ساز و نی، قصد دارد راز خود را فاش کند.',NULL);
INSERT INTO "verses" VALUES(1931794,2479,7,1,'ز سنبل و سَمَنش، سازِ طوق و یاره کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931795,2479,7,0,'به تختِ گُل بنشانم بُتی چو سلطانی','هوش مصنوعی: من مجسمه‌ای را مانند یک پادشاه روی تختی از گل می‌نشانم و با گل‌های سنبل و دیگر گل‌ها، طوق و زینت‌هایی برای او فراهم می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1931796,2479,6,1,'چرا ملامتِ رندِ شراب‌خواره کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931797,2479,6,0,'مرا که نیست رَه و رسمِ لقمه‌پرهیزی','هوش مصنوعی: من که راه و رسم تظاهر به پرهیز از دنیا را ندارم، چرا باید فردی را که به نوشیدن شراب عادت دارد سرزنش کنم؟',NULL);
INSERT INTO "verses" VALUES(1931798,2479,5,1,'که ناز بر فلک و حکم بر ستاره کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931799,2479,5,0,'گدایِ میکده‌ام، لیک وقتِ مستی بین','هوش مصنوعی: من در میکده گدایی می‌کنم، اما در لحظه‌ی مستی می‌توانم به آسمان ناز کنم و بر ستاره‌ها فرمان روا باشم.',NULL);
INSERT INTO "verses" VALUES(1931800,2479,4,1,'حوالهٔ سَرِ دشمن به سنگِ خاره کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931801,2476,1,1,'مگرش هم ز سرِ زلفِ تو زنجیر کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931802,2479,4,0,'ز رویِ دوست مرا چون گلِ مراد شِکُفت','هوش مصنوعی: از چهره‌ی معشوقم مانند گلی که به آرزو رسیده، شکوفا می‌شوم و در مقابل دشمن، ضربه‌ای محکم و سخت می‌زنم.',NULL);
INSERT INTO "verses" VALUES(1931803,2479,3,0,'به دورِ لاله دماغِ مرا عِلاج کنید','هوش مصنوعی: لطفاً به دور لاله (که نماد زیبایی است) حال و هوای درونی من را درمان کنید. اگر بخواهم از میانهٔ شادی و جشن فاصله بگیرم.',NULL);
INSERT INTO "verses" VALUES(1931804,2479,2,1,'پیاله گیرم و از شوق، جامه پاره کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931805,2479,2,0,'چو غنچه با لبِ خندان به یادِ مجلسِ شاه','هوش مصنوعی: مثل غنچه‌ای با لب‌های خندان، به خاطر یادِ آن مجلسِ باشکوه، پیاله‌ای را برمی‌دارم و از شدت شادی، لباس خود را پاره می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1931806,2479,1,1,'که مِی خورند حریفان و من نِظاره کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931807,2479,1,0,'سخن درست بگویم نمی‌توانم دید','هوش مصنوعی: من نمی‌توانم به درستی صحبت کنم و از طرفی نمی‌توانم ببینم که دوستانم در حال نوشیدن شراب هستند و فقط نظاره‌گر باشم.',NULL);
INSERT INTO "verses" VALUES(1931808,2479,0,1,'بهارِ توبه‌شکن می‌رسد چه چاره کُنم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931809,2479,0,0,'به عزمِ توبه سحر گفتم استخاره کُنم','هوش مصنوعی: در صبح زود تصمیم گرفتم توبه کنم و از خدا راهنمایی طلبیدم. اما به این فکر افتادم که با رسیدن بهار، با دل‌شکنی و لغزش‌ها چه باید بکنم؟',NULL);
INSERT INTO "verses" VALUES(1931810,2478,6,1,'تا دعایِ دولتِ آن حُسنِ روزافزون کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931811,2478,6,0,'ای مَهِ صاحب قران، از بنده حافظ یاد کن','هوش مصنوعی: ای ماهِ صاحب قران، یادِ منِ بنده را فراموش نکن تا به خاطر آن از خداوند برای تو و بخشش‌های روزافزونت دعا کنم.',NULL);
INSERT INTO "verses" VALUES(1931812,2478,5,1,'صد گدایِ همچو خود را بعد از این قارون کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931813,2478,5,0,'من که رَه بُردم به گنجِ حُسنِ بی‌پایان دوست','هوش مصنوعی: من با شجاعت و اراده به گنجینه‌ی زیبایی‌های بی‌نظیر محبوبم رسیدم و حالا تصمیم دارم که بعد از این، تمام کسانی که مانند من گدای عشق هستند را مانند قارون، ثروتمند و سرفراز کنم.',NULL);
INSERT INTO "verses" VALUES(1931814,2478,4,1,'رَبع را برهم زنم، اَطلال را جیحون کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931815,2478,4,0,'ای نسیمِ منزلِ لیلی خدا را تا به کی','هوش مصنوعی: ای نسیمِ خنک از خانه‌ی لیلی، تا چه زمانی می‌خواهی من را آشفته کنی؟ می‌خواهم یاد و خاطره‌های گذشته را همچون جیحون، جلا دهم و به زندگی بازگردم.',NULL);
INSERT INTO "verses" VALUES(1931816,2478,3,1,'ساقیا جامی بده تا چهره را گُلگون کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931817,2479,3,1,'گر از میانهٔ بزمِ طَرَب کناره کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931818,2463,7,1,'گر سر بِرَوَد در سرِ سودایِ اَیازم',NULL,NULL);
INSERT INTO "verses" VALUES(1931819,2476,1,0,'دل دیوانه از آن شد که نصیحت شِنَوَد','هوش مصنوعی: دل دیوانه از شنیدن نصیحت به تنگ آمده است، مگر اینکه بتوانم او را با زنجیر زلفت نگه‌دارم.',NULL);
INSERT INTO "verses" VALUES(1931820,2476,0,0,'صَنَما با غمِ عشقِ تو چه تدبیر کنم؟','هوش مصنوعی: با درد عشق تو چه راه حلی پیدا کنم؟ تا کی باید در غم تو شب‌ها ناله سر دهم؟',NULL);
INSERT INTO "verses" VALUES(1931821,2474,1,1,'نیست چون آینه‌ام روی ز آهن، چه کنم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931822,2474,1,0,'آه کز طعنهٔ بدخواه ندیدم رویت','هوش مصنوعی: آه، به خاطر حرف‌های طعنه‌آمیز بدخواهان، نتوانستم چهره‌ات را ببینم. چون من مانند آینه‌ای هستم که بر روی آهن قرار دارد، نمی‌دانم چه باید بکنم.',NULL);
INSERT INTO "verses" VALUES(1931823,2474,0,1,'زلفِ سنبل چه کشَم عارضِ سوسن چه کنم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931824,2474,0,0,'بی تو ای سروِ روان، با گل و گلشن چه کنم؟','هوش مصنوعی: بی تو ای زیبای دل‌انگیز، با گل و باغ چه باید کرد؟ با موهای زیبا چه کنم و چه کنم با چهره‌ی زیبا؟',NULL);
INSERT INTO "verses" VALUES(1931825,2473,6,1,'در مجلسِ روحانیان، گَه گاه جامی می‌زنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931826,2473,6,0,'با آن که از وی غایبم، وز مِی چو حافظ تایبم','هوش مصنوعی: اگرچه از او دور هستم و در مجلس اهل معرفت با می همدم هستم، گاهی اوقات جرعه‌ای می‌نوشم.',NULL);
INSERT INTO "verses" VALUES(1931827,2473,5,1,'این آهِ خون افشان که من، هر صبح و شامی می‌زنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931828,2473,5,0,'دانم سر آرد غُصِّه را، رنگین برآرد قِصِّه را','هوش مصنوعی: می‌دانم که غم و اندوه، داستانی رنگین و جذاب به همراه دارد. این آهی که من همیشه در صبح و شب می‌زنم، همچون خون از دل می‌جوشد.',NULL);
INSERT INTO "verses" VALUES(1931829,2473,4,1,'نقشِ خیالی می‌کشم، فالِ دوامی می‌زنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931830,2473,4,0,'هرچند کـ‌آن آرامِ دل، دانم نبخشد کامِ دل','هوش مصنوعی: هر چند می‌دانم که آن کسی که دل را آرام می‌کند، نمی‌تواند آرزوهایم را برآورده سازد، اما به هر حال برای خودم تصاویری زیبا می‌سازم و چشم به آینده‌ای امیدوارکننده دارم.',NULL);
INSERT INTO "verses" VALUES(1931831,2473,3,1,'گلبانگِ عشق از هر طرف، بر خوش خرامی می‌زنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931832,2473,3,0,'تا بو که یابم آگهی از سایهٔ سَروِ سَهی','هوش مصنوعی: در جستجوی خبری از زیبایی و محبت، با آهنگ عشق به هر سو می‌روم و در حالی که با ناز و elegance حرکت می‌کنم، لحظاتی را سپری می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1931833,2473,2,1,'حالی من اندر عاشقی، داوِ تمامی می‌زنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931834,2473,2,0,'اورنگ کو؟ گُلچهر کو؟ نقشِ وفا و مِهر کو؟','هوش مصنوعی: کجا است تخت و تاج؟ کجا است چهره زیبا؟ کجا است نشان عشق و دوستی؟ حالا که من در عشق هستم، تمام وجودم را در این راه صرف می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1931835,2473,1,1,'دامی به راهی می‌نهم، مرغی به دامی می‌زنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931836,2473,1,0,'بی ماهِ مِهرافروزِ خود، تا بُگذَرانَم روزِ خود','هوش مصنوعی: بی‌وجود ماهی که نورش زندگی‌بخش است، روزهای خود را سپری می‌کنم. در این مسیر، دامی می‌چینم و پرنده‌ای را به دام می‌اندازم.',NULL);
INSERT INTO "verses" VALUES(1931837,2473,0,1,'دستِ شفاعت هر زمان در نیک نامی می‌زنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931838,2473,0,0,'عمریست تا من در طلب، هر روز گامی می‌زنم','زمان زیادی به طول یک عمر است که هر روز و مداوم در جستجو هستم. هر زمان برای اینکه شفاعتم کنند به نیک نامی مراجعه می کنم .',NULL);
INSERT INTO "verses" VALUES(1931839,2472,8,1,'شد مِنَّتِ مَواهبِ او طوقِ گردنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931840,2472,8,0,'توران‌شهِ خجسته که در من یَزیدِ فضل','هوش مصنوعی: در سرزمین خوشبختی توران، فضل و علم یزید بر من سایه افکنده و نعمت‌های او مانند طوقی بر گردنم آویخته شده است.',NULL);
INSERT INTO "verses" VALUES(1931841,2472,7,1,'در بزمِ خواجه، پرده ز کارَت برافکنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931842,2472,7,0,'حافظ! به زیرِ خرقه قدح تا به کِی کشی؟','هوش مصنوعی: چرا همچنان در زیر روپوش خود مشغول نوشیدن هستی؟ من در محفل صاحب‌منصبان راز تو را فاش خواهم کرد.',NULL);
INSERT INTO "verses" VALUES(1931843,2472,6,1,'کو همرهی؟ که خیمه از این خاک بَرکَنَم',NULL,NULL);
INSERT INTO "verses" VALUES(1931844,2472,6,0,'آب و هوای فارس عجب سِفله‌پرور است','هوش مصنوعی: آب و هوای فارس به قدری تأثیرگذار و منحصر به فرد است که انسان‌های معمولی را پرورش می‌دهد. حالا به چه کسی می‌توانم تکیه کنم؟ از این سرزمین می‌خواهم جدا شوم و به جایی دیگر بروم.',NULL);
INSERT INTO "verses" VALUES(1931845,2472,5,1,'با این لسانِ عَذب، که خامُش چو سوسنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931846,2472,5,0,'حیف است بلبلی چو من اکنون در این قفس','هوش مصنوعی: حسرت است که من، به عنوان یک بلبل، در این قفس باشم و با زبان شیرینم نتوانم آواز بخوانم و باید مانند سوسن خاموش بمانم.',NULL);
INSERT INTO "verses" VALUES(1931847,2472,4,1,'کز یاد بُرده‌اند هوایِ نشیمنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931848,2472,4,0,'شهبازِ دست پادشهم، این چه حالت است؟','هوش مصنوعی: من پرنده‌ای از دست پادشاه هستم، این چه حالتی است که دیگه یادم رفته که در خانه‌ام چه خبری است؟',NULL);
INSERT INTO "verses" VALUES(1931849,2472,3,1,'کآلوده گشت جامه، ولی پاک‌دامنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931850,2474,2,0,'برو ای ناصِح و بر دردکشان خرده مگیر','ای نصیحت‌گر، رندان و باده‌نوشان را سرزنش نکن و از کار آنها ایراد نگیر، خداوند این تقدیر را برای ما رقم زده، من در برابر این شرایط چه کار می‌توانم بکنم؟',NULL);
INSERT INTO "verses" VALUES(1931851,2474,2,1,'کارفرمایِ قَدَر می‌کند این، من چه کنم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931852,2474,3,0,'برقِ غیرت چو چُنین می‌جَهَد از مَکمَنِ غیب','هوش مصنوعی: وقتی غیرت و شجاعت به شدت در دل شخصی شعله‌ور می‌شود، از او خواهش می‌کنم که به من بگوید در حالی که در دل ناتوانی و سوختگی قرار دارم، چه باید بکنم؟',NULL);
INSERT INTO "verses" VALUES(1931853,2474,3,1,'تو بفرما که منِ سوخته خرمن چه کنم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931854,2475,11,1,'من نه آنم کز وی این افسانه‌ها باور کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931855,2475,11,0,'دوش لعلش عشوه‌ای می‌داد حافظ را، ولی','هوش مصنوعی: دیشب لب لعل او ناز و عشوه‌ای به حافظ نشان داد، اما من آن کسی نیستم که از او این داستان‌ها را بپذیرم و باور کنم.',NULL);
INSERT INTO "verses" VALUES(1931856,2475,10,1,'تنگ چشمم گر نظر در چشمهٔ کوثر کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931857,2475,10,0,'عاشقان را گر در آتش می‌پسندد لطفِ دوست','هوش مصنوعی: عاشقانی که محبت دوست برایشان به گونه‌ای است که گرما و سختی آتش را می‌پذیرند، من از درد و رنج آنها ناراحت می‌شوم اگر به نعمت‌های الهی نگاه کنم.',NULL);
INSERT INTO "verses" VALUES(1931858,2475,9,1,'گر به آبِ چشمهٔ خورشید دامن تَر کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931859,2475,9,0,'گر چه گَردآلودِ فقرم، شرم باد از همتم','هوش مصنوعی: هرچند در فقر و تنگدستی به سر می‌برم، اما از اراده و تلاشم شرمنده نمی‌شوم اگر بتوانم با تلاش، به بالاترین قله‌ها و اهداف خود دست یابم.',NULL);
INSERT INTO "verses" VALUES(1931860,2475,8,1,'کِی طمع در گردشِ گردونِ دون‌پَرور کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931861,2475,8,0,'من که دارم در گدایی گنجِ سلطانی به دست','من که در عالم فقر و قناعت خزانه بی‌نیازی را مانند شاهان در اختیار دارم، هرگز از آسمان پر گسترش فرومایگان، توقع و چشم داشتی نخواهم داشت.',NULL);
INSERT INTO "verses" VALUES(1931862,2475,7,1,'عهد با پیمانه بندم، شرط با ساغَر کُنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931863,2475,7,0,'عهد و پیمانِ فلک را نیست چندان اعتبار','هوش مصنوعی: عهد و پیمان آسمان چندان ارزش ندارد که من با پیمانه به آن بسنده کنم و با لیوان شرط بگذارم.',NULL);
INSERT INTO "verses" VALUES(1931864,2475,6,1,'کج دلم خوان، گر نظر بر صفحهٔ دفتر کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931865,2475,6,0,'چون صبا مجموعهٔ گل را به آبِ لطف شست','هوش مصنوعی: وقتی نسیم ملایم گل‌ها را با آب محبت شست و شو داد، دلم از کج‌فهمی می‌خواند، اگر نگاهی به صفحات دفترم بیندازم.',NULL);
INSERT INTO "verses" VALUES(1931866,2475,5,1,'کِی نظر در فیضِ خورشیدِ بلنداختر کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931867,2475,5,0,'من که از یاقوت و لَعلِ اشک دارم گنج‌ها','هوش مصنوعی: من که گنج‌هایی از یاقوت و لعل دارم، هرگز نمی‌توانم به نعمت و فایده‌ی خورشید در آسمان بلند فکر کنم.',NULL);
INSERT INTO "verses" VALUES(1931868,2476,0,1,'تا به کِی در غمِ تو نالهٔ شبگیر کنم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931869,2475,4,1,'تا ز اشک و چهره راهت پُر زر و گوهر کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931870,2475,3,1,'داوری دارم بسی یا رب، که را داور کنم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931871,2475,3,0,'لاله ساغرگیر و نرگس مست و بر ما نامِ فِسق','هوش مصنوعی: گل لاله را در دست بگیر و نرگس را که مست و سرمست است نگاه کن. من در مورد خودم گناهان زیادی دارم. خدایا، می‌خواهم بدانم من باید چه کسی را قضاوت کنم؟',NULL);
INSERT INTO "verses" VALUES(1931872,2475,2,1,'سر فروبُردم در آن جا تا کجا سر بَرکُنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931873,2475,2,0,'عشق دردانه‌ست و من غَوّاص و دریا میکده','هوش مصنوعی: عشق مانند یک جواهر گرانبهاست و من مانند غواصی هستم که در اعماق دریا غرق شده‌ام. در مکانی که محبت و شگفتی‌ها وجود دارد، نمی‌دانم تا چه زمانی می‌توانم از آنجا سر بلند کنم.',NULL);
INSERT INTO "verses" VALUES(1931874,2475,1,1,'توبه از مِی وقتِ گُل دیوانه باشم گر کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931875,2475,1,0,'من که عیبِ توبه‌کاران کرده باشم بارها','هوش مصنوعی: من که بارها عیب توبه‌کنندگان را گفته‌ام و خودم هم در زمان گُل، به دیوانگی از شراب توبه کرده‌ام.',NULL);
INSERT INTO "verses" VALUES(1931876,2475,0,1,'محتسب داند که من این کارها کمتر کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931877,2475,0,0,'من نه آن رندم که تَرکِ شاهد و ساغر کنم','هوش مصنوعی: من اهل باده‌نوشی و میخانه نیستم و نمی‌توانم به راحتی از مشروب و تماشای محبوب چشم بپوشم. نگهبان میخانه می‌داند که من این کارها را کمتر انجام می‌دهم.',NULL);
INSERT INTO "verses" VALUES(1931878,2474,6,1,'اندر این منزلِ ویرانه نشیمن چه کنم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931879,2474,6,0,'حافظا خُلدِبَرین خانهٔ موروثِ من است','ای حافظ، بهشت برین خانه‌ای است که به ارث از گذشتگانم به من رسیده. چرا باید دل به این دنیای سست بنیاد و گذرا ببندم؟',NULL);
INSERT INTO "verses" VALUES(1931880,2474,5,1,'چارهٔ تیره‌شبِ وادی ایمن چه کنم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931881,2474,5,0,'مددی گر به چراغی نکند آتشِ طور','هوش مصنوعی: اگر روشنایی چراغی نتواند آتش کوه طور را به وجود آورد، من در تاریکی وادی امن چه کاری می‌توانم انجام دهم؟',NULL);
INSERT INTO "verses" VALUES(1931882,2474,4,1,'دستگیر ار نشود لطفِ تَهَمتَن چه کنم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931883,2474,4,0,'شاهِ تُرکان چو پسندید و به چاهم انداخت','وقتی پادشاه این سرنوشت را برای من روا داشت و مرا در چاه انداخت اگر لطف رستم یاریگر من برای بیرون آمدن از چاه نشود، من چه کاری می‌توانم بکنم؟(تلمیح به داستان بیژن و منیژه)',NULL);
INSERT INTO "verses" VALUES(1931884,2475,4,0,'بازکَش یک دَم عِنان ای تُرکِ شهرآشوبِ من','هوش مصنوعی: ای ترکِ پرآشوب من، لحظه‌ای مهار خود را کشیده و بایست تا من بتوانم با اشک و چهره‌ام، راه تو را پر از طلا و جواهر کنم.',NULL);
INSERT INTO "verses" VALUES(1931885,2480,2,1,'یک چند نیز خدمتِ معشوق و مِی کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1931886,2463,7,0,'محمود بُوَد عاقبتِ کار در این راه','هوش مصنوعی: آینده‌ی محمود بستگی به نتیجه‌ی کارش دارد و اگر به هدفش برسد، در راه آرزوهایش پیش خواهد رفت.',NULL);
INSERT INTO "verses" VALUES(1931887,2463,6,0,'گر خلوتِ ما را شبی از رخ بِفُروزی','هوش مصنوعی: اگر یک شب به تنهایی ما نگاهی بیندازی، چنان که صبح بر سراسر جهان می‌تابد، من نیز بر بلندای عالم می‌ایستم.',NULL);
INSERT INTO "verses" VALUES(1931888,2455,5,0,'ناوَک غمزه بیار و رَسَنِ زلف که من','هوش مصنوعی: نخستین بار جذبه و نشانه‌ای از تو را بیاور و تار زلفت را به من بده که من به دل مجروح خود سختی‌های زیادی را تحمل کرده‌ام.',NULL);
INSERT INTO "verses" VALUES(1931889,2455,4,1,'نُقل شعر شِکرین و مِیِ بی‌غش دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931890,2455,4,0,'گر به کاشانهٔ رندان قدمی خواهی زد','هوش مصنوعی: اگر قصد داری به خانهٔ رندها قدم بگذاری، من شعرهای شیرین و شراب خالصی دارم.',NULL);
INSERT INTO "verses" VALUES(1931891,2455,3,1,'من رخ زرد، به خونابه منقش دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931892,2455,3,0,'گر چنین چهره گشاید خطِ زنگاریِ دوست','هوش مصنوعی: اگر دوستی با چهره همچون آفتاب جلودار شود، من هم با خدشه‌های زرد و نشانه‌های درد بر چهره‌ام نقاشی می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1931893,2455,2,1,'من به آه سحرت زلف، مشوش دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931894,2455,2,0,'گر تو زین دست، مرا بی سر و سامان داری','هوش مصنوعی: اگر تو با این حال و روز مرا بی‌قرار و بی‌نظم نگه می‌داری، من هم در دل شب با آه و ناله‌های جانسوزم، موهایم را در هم و پریشان کرده‌ام.',NULL);
INSERT INTO "verses" VALUES(1931895,2455,1,1,'وین همه منصب از آن حور  پری‌وش دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931896,2455,1,0,'عاشق و رندم و می‌خواره به آواز بلند','هوش مصنوعی: من عاشق و شیدا و اهل می‌گساری هستم و به طور بی‌پروا این حرف‌ها را می‌زنم، اما همه‌ی این ویژگی‌ها و مقام‌ها را به خاطر زیبایی و جذبه‌ی آن معشوق پرنسس مانند دارم.',NULL);
INSERT INTO "verses" VALUES(1931897,2455,0,1,'کز سر زلف و رخش، نعل در آتش دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931898,2455,0,0,'در نهانخانهٔ عشرت صنمی خوش دارم','هوش مصنوعی: در خلوتگاه لذت، محبوبی زیبا دارم که با مو و چهره‌اش، دلم را در آتش عشق می‌سوزاند.',NULL);
INSERT INTO "verses" VALUES(1931899,2454,8,1,'عمری بُوَد آن لحظه که جان را به لب آرم',NULL,NULL);
INSERT INTO "verses" VALUES(1931900,2454,8,0,'حافظ لبِ لَعلَش چو مرا جانِ عزیز است','هوش مصنوعی: حافظ می‌گوید که لبِ لعل محبوبش برای او به اندازه جانش ارزشمند است و او آماده است تا تمام عمرش را تلف کند تا آن لحظه‌ای که جانش در خطر است، به لبِ معشوق نزدیک‌تر شود.',NULL);
INSERT INTO "verses" VALUES(1931901,2454,7,1,'زین در نتواند که بَرَد باد غبارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931902,2454,7,0,'دامن مَفِشان از منِ خاکی که پس از من','هوش مصنوعی: این بیت به این معناست که از من که یک انسان خاکی و فانی هستم، دامن خود را دور کن، زیرا پس از من، هیچ چیزی جز غباری از من نخواهد ماند که باد بتواند آن را ببرد. به عبارتی، او به ناپایداری زندگی و اینکه پس از مرگش چیزی از او باقی نخواهد ماند، اشاره می‌کند.',NULL);
INSERT INTO "verses" VALUES(1931903,2454,6,1,'من نقدِ روان در دَمَش از دیده شمارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931904,2454,6,0,'گر قلبِ دلم را نَنَهد دوست عیاری','هوش مصنوعی: اگر عشق واقعی به من نرسد، تمام احساسات و ثروت‌های دلم را در لحظه‌ای که دوستانم را می‌بینم، از یاد می‌برم.',NULL);
INSERT INTO "verses" VALUES(1931905,2454,5,1,'کان بویِ شفابخش بُوَد دفعِ خُمارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931906,2454,5,0,'ای باد از آن باده نسیمی به من آور','هوش مصنوعی: ای باد، از آن باده خوش مزه نسیمی برای من بیاور، زیرا بوی آن درمانگری دارد و می‌تواند خمار و حال بد مرا برطرف کند.',NULL);
INSERT INTO "verses" VALUES(1931907,2454,4,1,'دادند قراری و بِبُردَند قرارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931908,2454,4,0,'زلفین سیاهِ تو به دلداریِ عُشّاق','هوش مصنوعی: موهای سیاه تو دل عاشقان را آرامش بخشیده و برایشان تعهدی ایجاد کرده است، اما این زیبایی من را بی‌قرار کرده است.',NULL);
INSERT INTO "verses" VALUES(1931909,2454,3,1,'زان شب که من از غم به دعا دست برآرم',NULL,NULL);
INSERT INTO "verses" VALUES(1931910,2454,3,0,'امروز مَکَش سر ز وفایِ من و اندیش','هوش مصنوعی: امروز به خاطر وفای من به خودت آسیب نزن و به یاد نیاور آن شبی که به خاطر غم، دست به دعا برداشتم.',NULL);
INSERT INTO "verses" VALUES(1931911,2454,2,1,'چون شمع همان دَم به دَمی جان بِسِپارَم',NULL,NULL);
INSERT INTO "verses" VALUES(1931912,2454,2,0,'پروانهٔ او گر رسدم در طلبِ جان','هوش مصنوعی: اگر به عشق او برسم و در پی جان او باشم، مانند شمع در همان لحظه جانم را به او تقدیم می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1931913,2454,1,1,'از موجِ سرشکم که رسانَد به کنارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931914,2454,1,0,'بر بویِ کنارِ تو شدم غرق و امید است','هوش مصنوعی: من در عطر و بوی وجود تو غرق شده‌ام و امیدوارم که اشک‌های من مانند موجی، مرا به تو برساند.',NULL);
INSERT INTO "verses" VALUES(1931915,2454,0,1,'بر لوحِ بَصَر خطِّ غباری بنگارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931916,2454,0,0,'گر دست دهد خاکِ کفِ پایِ نگارم','هوش مصنوعی: اگر موقعیتی پیش آید و بتوانم، خاک کف پای محبوبم را بر لوح چشمانم به عنوان نشانی از عشق بنویسم.',NULL);
INSERT INTO "verses" VALUES(1931917,2455,5,1,'جنگ‌ها با دل مجروح بلاکش دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931918,2453,7,1,'بجز از خاکِ درش با که بُوَد بازارم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931919,2455,6,0,'حافظا چون غم و شادیِّ جهان در گذر است','هوش مصنوعی: ای حافظ، با توجه به این که غم و شادی در زندگی مداوم در حال تغییر و گذراندن هستند، بهتر است که من به فکر خوشحال کردن خودم باشم.',NULL);
INSERT INTO "verses" VALUES(1931920,2456,0,0,'مرا عهدی‌ست با جانان که تا جان در بدن دارم','هوش مصنوعی: من با محبوبم عهد کرده‌ام که تا وقتی در بدنم زندگی می‌کنم، محبت و طرفداری از او را همچون جان خودم در نظر بگیرم.',NULL);
INSERT INTO "verses" VALUES(1931921,2457,4,0,'خُرَم آن روز کز این مرحله بَربَندَم بار','هوش مصنوعی: روز خوشی خواهد بود که از این مرحله بگذرم و دوستانم از تو خبر بگیرند.',NULL);
INSERT INTO "verses" VALUES(1931922,2457,4,1,'و از سرِ کوی تو پرسند رفیقان خبرم',NULL,NULL);
INSERT INTO "verses" VALUES(1931923,2457,3,0,'ای نسیمِ سحری بندگیِ من برسان','هوش مصنوعی: ای نسیم صبحگاهی، لطفاً پیام محبت و عبادتم را به یاد داشته باش و فراموش نکن که زمان دعا کردن در سحرگاه است.',NULL);
INSERT INTO "verses" VALUES(1931924,2457,3,1,'که فراموش مکن وقتِ دعایِ سحرم',NULL,NULL);
INSERT INTO "verses" VALUES(1931925,2457,2,0,'همتم بدرقهٔ راه کن ای طایرِ قدس','هوش مصنوعی: ای پرنده‌ٔ آسمان قدس، لطفاً مرا در سفرم یاری کن و حمایت‌ام کن، زیرا راه رسیدن به مقصد بسیار طولانی است و من تازه آغاز کرده‌ام.',NULL);
INSERT INTO "verses" VALUES(1931926,2457,2,1,'که دراز است رَهِ مقصد و من نوسفرم',NULL,NULL);
INSERT INTO "verses" VALUES(1931927,2457,1,0,'دلبرا بنده نوازیت که آموخت؟ بگو','هوش مصنوعی: عزیزم، نوازش و محبت تو را چه کسی به من یاد داد؟ بگو که من هرگز این گمان را درباره رقبایت ندارم.',NULL);
INSERT INTO "verses" VALUES(1931928,2457,1,1,'که من این ظَن، به رقیبانِ تو هرگز نَبَرم',NULL,NULL);
INSERT INTO "verses" VALUES(1931929,2457,0,0,'من که باشم که بر آن خاطرِ عاطِر گذرم؟','هوش مصنوعی: من چه کسی هستم که به یاد تو بگذرم؟ ای خاک درگاه تو، مهربانی‌های تو تاج سر من است.',NULL);
INSERT INTO "verses" VALUES(1931930,2457,0,1,'لطف‌ها می‌کنی ای خاکِ دَرَت، تاجِ سرم',NULL,NULL);
INSERT INTO "verses" VALUES(1931931,2456,9,1,'چه غم دارم که در عالم قَوامُ‌الدّین حَسَن دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931932,2456,9,0,'به رندی شهره شد حافظ میانِ همدمان، لیکن','هوش مصنوعی: حافظ در جمع دوستانش به خاطر زیرکی و تیزهوشی‌اش شناخته شده است، اما برای او مهم نیست چون در این دنیا، شخصیتی به نام قوام‌الدین حسن دارد که برایش ارزشمند است.',NULL);
INSERT INTO "verses" VALUES(1931933,2456,8,1,'نه میلِ لاله و نسرین، نه برگِ نسترن دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931934,2456,8,0,'چو در گل‌زارِ اِقبالش خرامانم بِحَمْدِالله','هوش مصنوعی: وقتی در فضای خوشبختی و موفقیتش قدم می‌زنم، با شکرگزاری از این وضعیت نه به لذت‌های دنیوی فکر می‌کنم و نه به زیبایی‌های دیگر.',NULL);
INSERT INTO "verses" VALUES(1931935,2456,7,1,'که من با لَعلِ خاموشش نهانی صد سخن دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931936,2456,7,0,'خدا را ای رقیب امشب زمانی دیده بر هم نِه','هوش مصنوعی: ای رفیق، امشب وقتی که در کنارم هستی، چشمت را ببند و به خدا فکر کن، چرا که من با او در دل خود حرف‌ها و رازهای زیادی دارم که با زبان خاموش می‌گویم.',NULL);
INSERT INTO "verses" VALUES(1931937,2456,6,1,'که من در تَرکِ پیمانه دلی پیمان‌شِکن دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931938,2456,6,0,'الا ای پیرِ فرزانه، مَکُن عیبم ز میخانه','هوش مصنوعی: ای پیر دانا، لطفاً به رفتار من در میخانه ایراد نگیر، زیرا من در دل خود، کسی را دارم که به عهد و پیمان وفا نمی‌کند و از نوشیدن دست کشیده‌ام.',NULL);
INSERT INTO "verses" VALUES(1931939,2456,5,1,'چو اسمِ اعظمم باشد، چه باک از اهرِمَن دارم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931940,2456,5,0,'سِزَد کز خاتمِ لَعلَش زَنَم لافِ سلیمانی','هوش مصنوعی: نیکوست که من با انگشتری از یاقوت، ادعای قدرت سلیمانی کنم، چرا که اگر نام بزرگ خداوند به من تعلق داشته باشد، از اهریمن چه باکی دارم؟',NULL);
INSERT INTO "verses" VALUES(1931941,2456,4,1,'بِحَمْدِ الله و الْمِنَّه بُتی لشکرشِکن دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931942,2456,4,0,'گَرَم صد لشکر از خوبان به قصدِ دل کمین سازند','اگر صد لشکر از زیبارویان بخواهند به قصد دل من کمین کنند، اما به لطف و نعمت خداوند، من بتی دارم که می‌تواند تمام آن لشکرها را شکست دهد.',NULL);
INSERT INTO "verses" VALUES(1931943,2456,3,1,'فَراغ از سروِ بستانی و شمشادِ چمن دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931944,2456,3,0,'مرا در خانه سروی هست کاندر سایهٔ قَدَّش','هوش مصنوعی: در خانه‌ام درخت سرو بلند و زیبایی وجود دارد که سایه‌اش برایم آرامش و راحتی بیشتری نسبت به درختان باغ و چمن‌زارها به ارمغان می‌آورد.',NULL);
INSERT INTO "verses" VALUES(1931945,2456,2,1,'چه فکر از خُبثِ بدگویان، میانِ انجمن دارم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931946,2456,2,0,'به کام و آرزویِ دل، چو دارم خلوتی حاصل','هوش مصنوعی: وقتی که در تنهایی به آرزوها و خواسته‌های قلبم می‌پردازم، دیگر به بدگویی‌های دیگران اهمیتی نمی‌دهم و در جمع نمی‌زنم که دلم نسبت به آن‌ها نگرانی داشته باشد.',NULL);
INSERT INTO "verses" VALUES(1931947,2456,1,1,'فروغِ چشم و نورِ دل از آن ماهِ خُتَن دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931948,2456,1,0,'صفایِ خلوتِ خاطر از آن شمعِ چِگِل جویم','هوش مصنوعی: من از آن شمع کوچک در تنهایی خود، روشنی و صفای خاطر می‌جویم و نور چشم و دل را از آن ماه زیبا و دلربا دارم.',NULL);
INSERT INTO "verses" VALUES(1931949,2456,0,1,'هوادارانِ کویش را چو جانِ خویشتن دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931950,2455,6,1,'بهتر آن است که من خاطر خود خوش دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931951,2453,7,0,'دوش می‌گفت که حافظ همه روی است و ریا','هوش مصنوعی: دیروز در گفت‌وگویی شنیدم که حافظ می‌گوید همه چیز در دنیا ظاهر و ریا است، جز خاک درگاه تو. با چه کسی باید به این بازار بروم؟',NULL);
INSERT INTO "verses" VALUES(1931952,2453,6,1,'با که گویم که بگوید سخنی با یارم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931953,2453,6,0,'چون تو را در گذر ای یار نمی‌یارم دید','هوش مصنوعی: وقتی در مسیر می‌گذری و نمی‌توانم تو را ببینم، با که صحبت کنم تا بگوید چه چیزی را به تو بگویم؟',NULL);
INSERT INTO "verses" VALUES(1931954,2451,4,1,'ز غصه بر سرِ کویت چه بارها که کشیدم',NULL,NULL);
INSERT INTO "verses" VALUES(1931955,2451,4,0,'ز غمزه بر دلِ ریشم چه تیرها که گشادی','هوش مصنوعی: از نگاه طعنه‌آمیز تو، چه زخم‌ها بر دل شکسته‌ام ایجاد شده است و از غم و اندوهی که به خاطر دوری‌ات بر دوش خود حس کرده‌ام، چه بار سنگینی را تحمل کرده‌ام.',NULL);
INSERT INTO "verses" VALUES(1931956,2451,3,1,'ز لَعلِ باده‌فروشت چه عشوه‌ها که خریدم',NULL,NULL);
INSERT INTO "verses" VALUES(1931957,2451,3,0,'به شوق چشمهٔ نُوشَتْ چه قطره‌ها که فشاندم','هوش مصنوعی: به خاطر اشتیاقی که به نوشیدن متن نوشته‌ها دارم، چقدر از انگشتانم، مانند قطره‌های شفاف، مرواریدهایی نازل شد و چه جذابیت‌هایی را برای خود به دست آوردم.',NULL);
INSERT INTO "verses" VALUES(1931958,2451,2,1,'طمع به دورِ دهانت ز کامِ دل بِبُریدم',NULL,NULL);
INSERT INTO "verses" VALUES(1931959,2451,2,0,'امید در شبِ زلفت به روزِ عمر نبستم','هوش مصنوعی: در شبِ تار زلف‌های تو بر امیدم دل نبستم و از آرزوی دوری لب‌هایت، شوق و آرزو در دل را قطع کردم.',NULL);
INSERT INTO "verses" VALUES(1931960,2451,1,1,'به گَردِ سروِ خرامانِ قامتت نرسیدم',NULL,NULL);
INSERT INTO "verses" VALUES(1931961,2451,1,0,'اگرچه در طلبت هم عِنانِ باد شِمالم','هوش مصنوعی: با اینکه در جستجوی تو هستم، ولی نتوانستم به زیبایی و شکوه تو نزدیک شوم.',NULL);
INSERT INTO "verses" VALUES(1931962,2451,0,1,'به صورتِ تو نگاری ندیدم و نشنیدم',NULL,NULL);
INSERT INTO "verses" VALUES(1931963,2451,0,0,'خیالِ نقشِ تو در کارگاهِ دیده کشیدم','هوش مصنوعی: در ذهنم تصویر تو را با دقت و زیبایی زیادی تجسم کردم، اما در واقع هیچ تصویری از تو پیدا نکردم و حتی صدای تو را هم نشنیدم.',NULL);
INSERT INTO "verses" VALUES(1931964,2450,9,0,'دوشم نوید داد عنایت که حافظا','هوش مصنوعی: دیشب به من خبر خوشی رسید که نگهدارنده‌ام، حافظ، دوباره به من محبت کند، زیرا من در برابر بخشش گناهانم، قهر کردم و به او پناه بردم.',NULL);
INSERT INTO "verses" VALUES(1931965,2450,9,1,'بازآ که من به عفوِ گناهت ضمان شدم',NULL,NULL);
INSERT INTO "verses" VALUES(1931966,2450,8,0,'من پیرِ سال و ماه نیَم، یار بی‌وفاست','من پیر شدهٔ سال و ماه نیستم، بلکه عمر بی‌وفاست؛ برای آن پیر شده‌ام که عمر من می‌گذرد.',NULL);
INSERT INTO "verses" VALUES(1931967,2450,8,1,'بر من چو عمر می‌گذرد پیر از آن شدم',NULL,NULL);
INSERT INTO "verses" VALUES(1931968,2450,7,0,'از آن زمان که فتنهٔ چشمت به من رسید','هوش مصنوعی: از وقتی که اثر زیبایی چشمانت به من رسید، دیگر از شرّ فتنه‌های آخرالزمان در امان شدم.',NULL);
INSERT INTO "verses" VALUES(1931969,2450,7,1,'ایمن ز شرِّ فتنهٔ آخرزمان شدم',NULL,NULL);
INSERT INTO "verses" VALUES(1931970,2450,6,0,'در شاه‌راهِ دولتِ سرمد به تختِ بخت','هوش مصنوعی: در مسیر موفقیت و خوشبختی، با نوشیدن می و لذت بردن از آن، به خواست و دل‌خواه دوستانم رسیدم.',NULL);
INSERT INTO "verses" VALUES(1931971,2450,6,1,'با جامِ مِی به کامِ دلِ دوستان شدم',NULL,NULL);
INSERT INTO "verses" VALUES(1931972,2450,5,0,'آن روز بر دلم درِ معنی گشوده شد','هوش مصنوعی: روزی قلب من به درک عمیق و حقیقتی دست یافت که باعث شد به جمع و محفل اهل معرفت و حکمت بپیوندم.',NULL);
INSERT INTO "verses" VALUES(1931973,2450,5,1,'کز ساکنانِ درگهِ پیرِ مغان شدم',NULL,NULL);
INSERT INTO "verses" VALUES(1931974,2450,4,0,'قسمت حوالتم به خرابات می‌کند','هوش مصنوعی: قسمت من به میکده می‌رسد، هرچند که تغییرات زیادی در زندگی‌ام ایجاد شده است.',NULL);
INSERT INTO "verses" VALUES(1931975,2450,4,1,'هر چند کاینچنین شدم و آنچنان شدم',NULL,NULL);
INSERT INTO "verses" VALUES(1931976,2450,3,0,'اول ز تحت و فوقِ وجودم خبر نبود','هوش مصنوعی: در ابتدا از حال و هوای وجود خودم آگاهی نداشتم، اما در مدرسه‌ی اندوه تو، به این نکته پی بردم که چه چیزهایی را باید درک کنم.',NULL);
INSERT INTO "verses" VALUES(1931977,2450,3,1,'در مکتبِ غمِ تو، چُنین نکته‌دان شدم',NULL,NULL);
INSERT INTO "verses" VALUES(1931978,2450,2,0,'ای گُلبُن جوان! بَرِ دولت بخور که من','هوش مصنوعی: بیا و برای سعادت خودت تلاش کن، زیرا در کنار تو من هم به خوشحالی و شادی زندگی ام ادامه می‌دهم.',NULL);
INSERT INTO "verses" VALUES(1931979,2450,2,1,'در سایهٔ تو بلبلِ باغِ جهان شدم',NULL,NULL);
INSERT INTO "verses" VALUES(1931980,2450,1,0,'شکرِ خدا که هر چه طلب کردم از خدا','هوش مصنوعی: خوشحالم که هر چیزی را که از خدا خواسته‌ام، با تمام تلاشم به آن دست یافته‌ام.',NULL);
INSERT INTO "verses" VALUES(1931981,2450,1,1,'بر مُنتهایِ همتِ خود کامران شدم',NULL,NULL);
INSERT INTO "verses" VALUES(1931982,2450,0,0,'هر چند پیر و خسته‌دل و ناتوان شدم','هوش مصنوعی: با وجود اینکه سن و سالی از من گذشته و خسته و ناتوان شده‌ام، هر بار که به یاد چهره‌ات می‌افتم، احساس جوانی و شادابی می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1931983,2451,5,0,'ز کویِ یار بیار ای نسیمِ صبح غباری','هوش مصنوعی: ای نسیم صبح، از کوی معشوقه‌ام غبار و بویی را بیاور که بوی خون دل شکسته‌ای را از آن خاک شنیده‌ام.',NULL);
INSERT INTO "verses" VALUES(1931984,2451,5,1,'که بویِ خونِ دلِ ریش از آن تراب شنیدم',NULL,NULL);
INSERT INTO "verses" VALUES(1931985,2451,6,0,'گناهِ چشمِ سیاهِ تو بود و گردنِ دلخواه','هوش مصنوعی: چشم‌های سیاه تو و زیبایی‌ات باعث شد که من مانند آهوی وحشی از انسانیت فاصله بگیرم و از آن دور شوم.',NULL);
INSERT INTO "verses" VALUES(1931986,2451,6,1,'که من چو آهویِ وحشی ز آدمی بِرَمیدم',NULL,NULL);
INSERT INTO "verses" VALUES(1931987,2453,5,1,'کو نسیمی ز عنایت که کُنَد بیدارم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1931988,2453,5,0,'دیدهٔ بخت به افسانهٔ او شد در خواب','هوش مصنوعی: چشم شانس من به خیال او بسته است و در خواب به سر می‌برد. آیا نسیمی از نعمت و محبت هست که مرا بیدار کند؟',NULL);
INSERT INTO "verses" VALUES(1931989,2453,4,1,'از نِیِ کِلک، همه قند و شِکَر می‌بارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931990,2453,4,0,'منم آن شاعرِ ساحر که به افسونِ سخن','هوش مصنوعی: من شاعر ماهری هستم که با جادوگری کلمات، از قلم خود شیرینی و زیبایی را پخش می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1931991,2453,3,1,'تا در این پرده جز اندیشه او نَگْذارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931992,2453,3,0,'پاسبانِ حرمِ دل شده‌ام شب همه شب','هوش مصنوعی: من شب‌ها به‌طور مداوم مراقب دل خود هستم تا تنها فکر او در آن حضور داشته باشد و هیچ چیز دیگری را به آن راه ندهم.',NULL);
INSERT INTO "verses" VALUES(1931993,2453,2,1,'آه اگر زان که در این پرده نباشد بارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931994,2453,2,0,'پردهٔ مطربم از دست برون خواهد برد','هوش مصنوعی: اگر مطرب از پشت پرده نمایان شود، در این حالت دلم به شدت آشفته خواهد شد، چرا که در این پرده حقایق و بار سنگین وجودم پنهان است.',NULL);
INSERT INTO "verses" VALUES(1931995,2453,1,1,'خونِ دل عکس برون می‌دهد از رخسارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931996,2453,1,0,'به طَرَب حمل مَکُن سرخیِ رویم که چو جام','هوش مصنوعی: لطفاً وقتی به سرخی چهره‌ام نگاه می‌کنی، شادی نکن. زیرا این رنگ به خاطر خون دل من است که از چهره‌ام نمایان می‌شود.',NULL);
INSERT INTO "verses" VALUES(1931997,2453,0,1,'همچُنان چشمِ گشاد از کَرَمَش می‌دارم',NULL,NULL);
INSERT INTO "verses" VALUES(1931998,2453,0,0,'گرچه افتاد ز زلفش گرهی در کارم','هوش مصنوعی: با وجود اینکه در سر و کارم مشکلی از طرف زلف او پیش آمده، همچنان از لطف و مهربانی‌اش چشم‌پوشی نمی‌کنم.',NULL);
INSERT INTO "verses" VALUES(1931999,2452,6,1,'به لطف آن سری امیدوارم',NULL,NULL);
INSERT INTO "verses" VALUES(1932000,2452,6,0,'سری دارم چو حافظ مست لیکن','هوش مصنوعی: من مانند حافظ حالتی سرمست دارم، اما به لطف آن حالتی، امیدوار و خوش‌بین هستم.',NULL);
INSERT INTO "verses" VALUES(1932001,2457,5,0,'حافظا شاید اگر در طلبِ گوهرِ وصل','هوش مصنوعی: حافظ، شاید اگر در جستجوی لؤلؤ و جواهر وصال بروم و در دریا از اشک‌هایم غوطه‌ور شوم، بتوانم آن را بیابم.',NULL);
INSERT INTO "verses" VALUES(1932002,2452,5,1,'«که زورِ مردم آزاری ندارم»',NULL,NULL);
INSERT INTO "verses" VALUES(1932003,2452,4,1,'چه باشد؟ حقِّ نعمت می‌گزارم',NULL,NULL);
INSERT INTO "verses" VALUES(1932004,2452,4,0,'اگر گفتم دعایِ مِی فروشان','هوش مصنوعی: اگر از من بپرسند که دعای می‌فروشان چه معنایی دارد، من در جواب می‌گویم که باید از حق این نعمتِ می سپاسگزاری کنم.',NULL);
INSERT INTO "verses" VALUES(1932005,2452,3,1,'که کرد آگه ز رازِ روزگارم',NULL,NULL);
INSERT INTO "verses" VALUES(1932006,2452,3,0,'بدین شکرانه می‌بوسم لبِ جام','هوش مصنوعی: به خاطر این نعمت، لبه‌ی جام را می‌بوسم که مرا از اسرار زندگی آگاه کرد.',NULL);
INSERT INTO "verses" VALUES(1932007,2452,2,1,'که شب تا روز اختر می‌شمارم',NULL,NULL);
INSERT INTO "verses" VALUES(1932008,2452,2,0,'ز چشمِ من بپرس اوضاعِ گردون','هوش مصنوعی: از چشمان من بپرس درباره وضعیت دنیا، چون من شب‌ها تا صبح ستاره‌ها را می‌شمارم.',NULL);
INSERT INTO "verses" VALUES(1932009,2452,1,1,'وگر نه سر به شیدایی برآرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932010,2452,1,0,'مگر زنجیرِ مویی گیردَم دست','هوش مصنوعی: اگر موی تو زنجیری بر دستم نبندد، هیچ چیزی مانع نمی‌شود که سر به دیوانگی بلند کنم.',NULL);
INSERT INTO "verses" VALUES(1932011,2452,0,1,'که از بالابلندان شرمسارم',NULL,NULL);
INSERT INTO "verses" VALUES(1932012,2452,0,0,'ز دستِ کوتهِ خود زیرِ بارم','هوش مصنوعی: من از ناتوانی خود خجالت‌زده‌ام؛ زیر فشار مشکلاتی هستم که خودم قادر به رفع آن‌ها نیستم و این مسأله باعث شرمندگی من در برابر کسانی است که وضعیت بهتری دارند.',NULL);
INSERT INTO "verses" VALUES(1932013,2451,8,1,'که بی رخِ تو، فروغ از چراغ دیده ندیدم',NULL,NULL);
INSERT INTO "verses" VALUES(1932014,2451,8,0,'به خاکِ پایِ تو سوگند و نورِ دیدهٔ حافظ','هوش مصنوعی: به خاک پای تو قسم و به نور چشمان حافظ، که بدون چهره تو هیچ نوری از چراغ چشمانم ندیدم.',NULL);
INSERT INTO "verses" VALUES(1932015,2451,7,1,'که پرده بر دلِ خونین به بویِ او بِدَریدَم',NULL,NULL);
INSERT INTO "verses" VALUES(1932016,2451,7,0,'چو غنچه بر سرم از کویِ او گذشت نسیمی','هوش مصنوعی: نسیمی مانند غنچه بر سرم وزید که وقتی به یاد او افتادم، پرده‌های دل شکسته‌ام را با عطر او پاره کرد.',NULL);
INSERT INTO "verses" VALUES(1932017,2452,5,0,'من از بازویِ خود دارم بسی شُکر','هوش مصنوعی: من به خاطر قدرتی که دارم بسیار سپاسگزارم، زیرا توانایی آزار دادن دیگران را ندارم.',NULL);
INSERT INTO "verses" VALUES(1932018,2457,5,1,'دیده دریا کُنم از اشک و در او غوطه خورم',NULL,NULL);
INSERT INTO "verses" VALUES(1932019,2457,6,0,'پایهٔ نظم بلند است و جهان گیر بگو','هوش مصنوعی: نظم و ساختار شعر بسیار عالی و برجسته است، به گونه‌ای که می‌تواند توجه و تشویق پادشاه را جلب کند تا در مورد من به خوبی صحبت کند و من را مورد توجه قرار دهد.',NULL);
INSERT INTO "verses" VALUES(1932020,2457,6,1,'تا کُند پادشهِ بحر دهان پُر گهرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932021,2461,8,1,'فَراغت باشد از شاه و وزیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932022,2461,8,0,'خوشا آن دَم کز اِستغنایِ مستی','هوش مصنوعی: چه خوش است آن لحظه‌ای که از بی‌نیازی و شادی، از نگرانی‌های زندگی و دغدغه‌های مقام و منصب دور باشم.',NULL);
INSERT INTO "verses" VALUES(1932023,2461,7,1,'من از پیرِ مُغان منّت پذیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932024,2461,7,0,'در این غوغا که کَس کَس را نپُرسد','در این شلوغی و هرج و مرج که هیچ‌کس از حال دیگری خبر نمی‌گیرد، من شرمنده بزرگتر و اهل خرد و دانش (مرید) هستم که مرا از یاد نبرده است.',NULL);
INSERT INTO "verses" VALUES(1932025,2461,6,1,'اگر نقشی کشد کِلکِ دبیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932026,2461,6,0,'مبادا جز حسابِ مُطرب و مِی','هوش مصنوعی: مبادا جز حساب نوازنده و شراب، اگر تصویری کشیده شود، امضای نویسنده‌ام را ببینید.',NULL);
INSERT INTO "verses" VALUES(1932027,2461,5,1,'که روزِ غم به جز ساغر نگیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932028,2461,5,0,'قراری بسته‌ام با مِی فروشان','هوش مصنوعی: من تصمیم گرفته‌ام که فقط در روزهای غم و ناراحتی، به جز جام شراب، هیچ چیز دیگری نپذیرم.',NULL);
INSERT INTO "verses" VALUES(1932029,2461,4,1,'جوانبخت جهانم گرچه پیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932030,2461,4,0,'قدح پُر کن که من در دولتِ عشق','هوش مصنوعی: جام را پر کن زیرا در نعمت عشق، خوشبخت و سرشار از زندگی هستم، هرچند که سنم بالا رفته است.',NULL);
INSERT INTO "verses" VALUES(1932031,2461,3,1,'که فکرِ خویش گم شد از ضمیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932032,2461,3,0,'چُنان پُر شد فضایِ سینه از دوست','هوش مصنوعی: به قدری وجودم از محبت و حضور دوست پر شده است که دیگر نتوانستم به خودم فکر کنم و همه چیز را فراموش کرده‌ام.',NULL);
INSERT INTO "verses" VALUES(1932033,2461,2,1,'به سیبِ بوستان و شهد و شیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932034,2461,2,0,'چو طفلان تا کِی ای زاهد، فریبی','هوش مصنوعی: ای زاهد! تا کی مانند بچه‌ها فریبِ زیبایی‌های باغ و لذت‌های شیرین را می‌خوری؟',NULL);
INSERT INTO "verses" VALUES(1932035,2461,1,1,'زکاتم دِه که مسکین و فقیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932036,2461,1,0,'نِصاب حُسن در حدِّ کمال است','هوش مصنوعی: زیبایی و کمالش در نهایت است، پس لطفا مرا یاری کن، زیرا من در تنگدستی و فقر به سر می‌برم.',NULL);
INSERT INTO "verses" VALUES(1932037,2461,0,1,'که پیشِ چشمِ بیمارت بمیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932038,2461,0,0,'مزن بر دل ز نوکِ غمزه تیرم','هوش مصنوعی: نزن به دل من با تیر چشمانت، زیرا که من در برابر چشمان بیمار تو، جانم را می‌دهم.',NULL);
INSERT INTO "verses" VALUES(1932039,2460,6,1,'که گر آتش شَوَم در وی نگیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932040,2460,6,0,'بسوز این خرقهٔ تقوا تو حافظ','هوش مصنوعی: ای حافظ، این لباس تقوا را بسوزان چراکه اگر آتش بزنم، در آن نمی‌سوزم.',NULL);
INSERT INTO "verses" VALUES(1932041,2460,5,1,'که من از پایِ تو سر بر نگیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932042,2460,5,0,'به گیسویِ تو خوردم دوش سوگند','هوش مصنوعی: من در شب گذشته به موهای تو قسم خوردم که هرگز از عشق تو چشم بر نخواهم داشت.',NULL);
INSERT INTO "verses" VALUES(1932043,2460,4,1,'به یک جرعه جوانم کن که پیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932044,2460,4,0,'به فریادم رَس ای پیرِ خرابات','هوش مصنوعی: ای پیر صاحب‌نظر و اهل حق، به کمکم بیا و با یک جرعه نوشیدنی مرا جوان کن، چرا که حس می‌کنم به سمت پیری و کهنسالی پیش می‌روم.',NULL);
INSERT INTO "verses" VALUES(1932045,2460,3,1,'که در دستِ شبِ هجران اسیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932046,2460,3,0,'برآی ای آفتابِ صبحِ امّید','هوش مصنوعی: ای خورشید امید، بیدار شو و به من نور ببخش، زیرا من در تاریکی و جدایی شب گرفتار شده‌ام.',NULL);
INSERT INTO "verses" VALUES(1932047,2460,2,1,'بجز ساغر که باشد دستگیرم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1932048,2460,2,0,'غمِ گیتی گر از پایم درآرد','هوش مصنوعی: اگر غم‌های این دنیا مرا از پا درآورد، تنها چیزی که می‌تواند به من کمک کند، یک جام شراب است.',NULL);
INSERT INTO "verses" VALUES(1932049,2460,1,1,'که پیشِ دست و بازویت بمیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932050,2461,9,0,'من آن مرغم که هر شام و سحرگاه','هوش مصنوعی: من پرنده‌ای هستم که هر شب و صبح از بالای عرش به زمین می‌آیم و آواز می‌زنم.',NULL);
INSERT INTO "verses" VALUES(1932051,2461,9,1,'ز بامِ عرش می‌آید صَفیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932052,2461,10,0,'چو حافظ گنج او در سینه دارم','هوش مصنوعی: من مانند حافظ، گنجی در دل دارم، گرچه دیگران به من کم‌ارزش نگاه می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1932053,2461,10,1,'اگرچه مُدَّعی بیند حقیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932054,2463,5,1,'محراب و کمانچه ز دو ابرویِ تو سازم',NULL,NULL);
INSERT INTO "verses" VALUES(1932055,2463,5,0,'در مسجد و میخانه خیالت اگر آید','هوش مصنوعی: اگر خیال تو به مسجد یا میخانه بیفتد، من محراب و کمانچه را از دو ابروی تو درست می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1932056,2463,4,1,'در میکده زان کم نَشَوَد سوز و گُدازم',NULL,NULL);
INSERT INTO "verses" VALUES(1932057,2463,4,0,'چون نیست نمازِ منِ آلوده نمازی','هوش مصنوعی: از آنجا که نماز من با آلودگی همراه است، در میکده نیز نمازی نیست که مرا از سوز و گداز درونم بکاهد.',NULL);
INSERT INTO "verses" VALUES(1932058,2463,3,1,'مستانِ تو خواهم که گُزارَند نمازم',NULL,NULL);
INSERT INTO "verses" VALUES(1932059,2463,3,0,'آن دَم که به یک خنده دَهَم جان چو صُراحی','هوش مصنوعی: در آن لحظه که با یک خنده‌ات جانم را می‌دهم، همچون پیاله‌ای از شراب، می‌خواهم که مرا در نماز و عبادت تو پیش ببرند.',NULL);
INSERT INTO "verses" VALUES(1932060,2463,2,1,'از آتشِ دل پیش تو چون شمع گُدازم',NULL,NULL);
INSERT INTO "verses" VALUES(1932061,2463,2,0,'پروانهٔ راحت بده ای شمع که امشب','هوش مصنوعی: ای شمع، امروز شب است و من به خاطر عشق و احساسات عمیقم در کنارت به شدت می‌سوزم. کاش راحتی و آرامشی برای پروانه‌ای مانند من فراهم کنی تا از این درد و آتش دل به تو نزدیک شوم و مانند شمعی ذوب شوم.',NULL);
INSERT INTO "verses" VALUES(1932062,2463,1,1,'در دست، سرِ مویی از آن عمرِ درازم',NULL,NULL);
INSERT INTO "verses" VALUES(1932063,2463,1,0,'زلفِ تو مرا عمر دراز است ولی نیست','هوش مصنوعی: زلف تو برای من عمری طولانی است، اما هیچ چیز از آن در دسترس نیست، حتی به اندازه یک تار مو.',NULL);
INSERT INTO "verses" VALUES(1932064,2463,0,1,'چون گوی چه سرها که به چوگانِ تو بازم',NULL,NULL);
INSERT INTO "verses" VALUES(1932065,2463,0,0,'گر دست رَسَد در سرِ زُلفینِ تو بازم','هوش مصنوعی: اگر دستی به گیسوان تو برسد، مانند گوی چه سرهایی که در بازی چوگان تو به زمین خواهند افتاد.',NULL);
INSERT INTO "verses" VALUES(1932066,2462,8,1,'«غلامِ حافظِ خوش‌لهجهٔ خوش‌آوازم»',NULL,NULL);
INSERT INTO "verses" VALUES(1932067,2462,8,0,'ز چَنگِ زهره شنیدم که صبح‌دم می‌گفت','هنگام صبح، از ستاره زهره با صدای چنگ این نکته را شنیدم که می­‌گفت: من بنده و غلام حافظ خوش زبان و خوش صدا هستم.',NULL);
INSERT INTO "verses" VALUES(1932068,2460,1,0,'کمانِ ابرویت را گو بزن تیر','هوش مصنوعی: ابروی زیبایت را مایهٔ تیراندازی قرار بده، تا من به یاد دست و بازویت جان بدهم.',NULL);
INSERT INTO "verses" VALUES(1932069,2462,7,1,'شکایت از که کنم؟ خانگی‌ست غَمّازَم',NULL,NULL);
INSERT INTO "verses" VALUES(1932070,2462,6,1,'صبا بیار نسیمی ز خاکِ شیرازم',NULL,NULL);
INSERT INTO "verses" VALUES(1932071,2462,6,0,'هوایِ منزل یار، آب زندگانیِ ماست','هوای کوی یار همچون آب حیات برای ما زندگی بخش است، ای باد صبا نسیمی از خاک شیراز برای من بیاور.',NULL);
INSERT INTO "verses" VALUES(1932072,2462,5,1,'عزیز من! که بجز باد نیست دَم‌سازم',NULL,NULL);
INSERT INTO "verses" VALUES(1932073,2462,5,0,'بجز صَبا و شِمالم نمی‌شناسد کس','ای عزیز من، به جز باد هیچگونه همدم و دمسازی ندارم، از این رو به جز باد صبا و نسیم شمال هیچ­کس دیگر مرا نمی­‌شناسد.(نکته:مصراع دوم بیت را شاید بتوان به شکل دیگری نیز خواند، بدین ترتیب که خواجه با طنزی تلخ بیان می­‌کند که: چقدر عزیز و گرامی هستم من که تنها همدم و دمسازم باد هست!)',NULL);
INSERT INTO "verses" VALUES(1932074,2462,4,1,'که باز با صَنَمی طفل، عشق می‌بازم',NULL,NULL);
INSERT INTO "verses" VALUES(1932075,2462,4,0,'خِرَد ز پیریِ من کِی حساب برگیرد؟','خرد چه زمانی می‌­خواهد پیری و سال­خوردگی مرا به حساب بیاورد، چرا که هنوز من با طفلی زیبارو مشغول عشق بازی هستم.',NULL);
INSERT INTO "verses" VALUES(1932076,2462,3,1,'به کویِ میکده دیگر عَلَم برافرازم',NULL,NULL);
INSERT INTO "verses" VALUES(1932077,2462,3,0,'خدای را مددی ای رفیقِ رَه تا من','ای رفیق راه، به خاطر خدا کمکی کن تا من بتوانم بار دیگر در کوی میکده حاضر شوم.',NULL);
INSERT INTO "verses" VALUES(1932078,2462,2,1,'مُهَیمنا به رفیقانِ خود رسان بازم',NULL,NULL);
INSERT INTO "verses" VALUES(1932079,2462,2,0,'من از دیارِ حبیبم نه از بِلاد غریب','حقیقتا، من متعلق به سرزمین دوست هستم نه از سرزمین بیگانگی و بی­‌کسی، ای خدای ایمنی دهنده مرا به پیش دوستان خودم برگردان.',NULL);
INSERT INTO "verses" VALUES(1932080,2462,1,1,'که از جهان رَه و رسمِ سفر براندازم',NULL,NULL);
INSERT INTO "verses" VALUES(1932081,2462,1,0,'به یادِ یار و دیار آنچنان بِگِریَم زار','به یاد و خاطر دوست و وطن خود آن چنان درمانده خواهم گریست، تا در جهان راه و رسم سفر و مسافرت را از بین ببرم.',NULL);
INSERT INTO "verses" VALUES(1932082,2462,0,1,'به مویه‌هایِ غریبانه، قِصه پردازم',NULL,NULL);
INSERT INTO "verses" VALUES(1932083,2462,0,0,'نمازِ شامِ غریبان چو گریه آغازم','هنگامی که نماز شام تنهایی و بی­‌کسی خود را با گریه آغاز می­کنم، با ناله و زاری­‌های غریب، داستان فراق و جدایی خود را شرح می­‌دهم.',NULL);
INSERT INTO "verses" VALUES(1932084,2462,7,0,'سِرشکم آمد و عیبم بگفت روی به روی','اشکم سراریز شد و عیب من را (عاشق بودن ) آشکارا بیان کرد، هنگامی که سخن چین درون خانه خودم می­‌باشد از چه کسی شکایت کنم.',NULL);
INSERT INTO "verses" VALUES(1932085,2463,6,1,'چون صبح بر آفاقِ جهان سر بِفَرازم',NULL,NULL);
INSERT INTO "verses" VALUES(1932086,2460,0,1,'وگر تیرم زَنَد منّت پذیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932087,2459,6,1,'ز شوق در دلِ آن تنگنا کفن بِدَرَم',NULL,NULL);
INSERT INTO "verses" VALUES(1932088,2458,14,0,'بر گُلشنی اگر بگذشتم چو بادِ صبح','هوش مصنوعی: اگر در باغی بگذرم مثل باد صبح، می‌دانم که عشق به درخت سرو در وجودم است، نه فقط اشتیاق به درخت صنوبر.',NULL);
INSERT INTO "verses" VALUES(1932089,2458,13,0,'شعرم به یُمنِ مَدحِ تو صد مُلکِ دل گشاد','هوش مصنوعی: شعر من به خاطر ستایش تو، دروازه‌های بسیاری از دل‌ها را باز می‌کند، انگار که زبان سخنم به اندازه تیغ تو تیز و نافذ است.',NULL);
INSERT INTO "verses" VALUES(1932090,2458,13,1,'گویی که تیغِ توست زبانِ سُخنورم',NULL,NULL);
INSERT INTO "verses" VALUES(1932091,2458,12,0,'ای شاهِ شیرگیر چه کم گردد ار شود','هوش مصنوعی: ای پادشاهی که همچون شیر قدرت و جذبه داری، چه چیزی از ارزش‌هایت کم می‌شود اگر در سایه‌ات، سرزمین آرامش برای من فراهم گردد؟',NULL);
INSERT INTO "verses" VALUES(1932092,2458,12,1,'در سایهٔ تو مُلکِ فَراغت مُیَسَّرَم',NULL,NULL);
INSERT INTO "verses" VALUES(1932093,2458,11,0,'شاهین صفت چو طعمه چَشیدم ز دستِ شاه','هوش مصنوعی: وقتی که من به شکار طعمه‌ای بزرگ و باارزش دست پیدا کردم، دیگر توجهی به شکار کبوترهای کوچک ندارم.',NULL);
INSERT INTO "verses" VALUES(1932094,2458,11,1,'کِی باشد التفات به صیدِ کبوترم',NULL,NULL);
INSERT INTO "verses" VALUES(1932095,2458,10,0,'گردون چو کرد نظمِ ثُرَیّا به نامِ شاه','هوش مصنوعی: آسمان وقتی که ستاره‌های درخشان را در نظم و ترتیب قرار داد، چرا من نتوانم به نام شاه من، نظم و زیبایی خلق کنم؟ من از چه کسی کمتر هستم؟',NULL);
INSERT INTO "verses" VALUES(1932096,2458,10,1,'من نظمِ دُر چرا نکنم؟ از کِه کمترم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1932097,2458,9,0,'عهدِ اَلَستِ من همه با عشقِ شاه بود','هوش مصنوعی: عهد قدیمی من فقط با عشق به شاه بود و من از مسیر زندگی‌ام، با همین عهد عبور می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1932098,2458,9,1,'وَز شاهراهِ عمر، بدین عهد بگذرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932099,2458,8,0,'منصور بِنْ مُظَفَّرِ غازیست حرزِ من','هوش مصنوعی: منصور بن مظفر، قهرمان و پشتیبان من است و از اینکه به این نام نیکو شناخته می‌شوم، بر دشمنانم فخر می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1932100,2458,8,1,'و از این خجسته نام، بر اَعدا مُظَفَّرَم',NULL,NULL);
INSERT INTO "verses" VALUES(1932101,2458,7,0,'«گر بَرکَنَم دل از تو و بَردارم از تو مِهر','هوش مصنوعی: اگر من دل را از تو جدا کنم و محبتت را از خود دور سازم، محبت کدام کسی را بر دوش خواهم گرفت؟ و آن دل را به کجا ببرم؟',NULL);
INSERT INTO "verses" VALUES(1932102,2458,7,1,'آن مِهر بَر کِه افکنم؟ آن دل کجا بَرَم؟»',NULL,NULL);
INSERT INTO "verses" VALUES(1932103,2458,6,0,'ور باوَرَت نمی‌کند از بنده این حدیث','هوش مصنوعی: اگر او به این حرف من ایمان نمی‌آورد، از این بنده، حدیثی از گفتهٔ کمال بیاورم که دلیل خوبی باشد.',NULL);
INSERT INTO "verses" VALUES(1932104,2458,6,1,'از گفتهٔ کمال، دلیلی بیاورم',NULL,NULL);
INSERT INTO "verses" VALUES(1932105,2458,5,0,'من جرعه نوشِ بزمِ تو بودم هزار سال','هوش مصنوعی: من هزار سال در مهمانی تو نوشیدم، چگونه می‌توانم به راحتی از آب و نوشیدنی دل بکَند؟',NULL);
INSERT INTO "verses" VALUES(1932106,2458,5,1,'کی تَرکِ آبخورْد کُنَد طبعِ خوگرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932107,2458,4,0,'شاها اگر به عرش رسانم سریرِ فضل','هوش مصنوعی: اگر بتوانم به اوج مقام و فضیلت برسم، این افتخار متعلق به سوی مولا و آقایی است که در نزد من آمده و من در خدمت او هستم.',NULL);
INSERT INTO "verses" VALUES(1932108,2458,4,1,'مملوکِ این جِنابم و مسکین این دَرَم',NULL,NULL);
INSERT INTO "verses" VALUES(1932109,2458,3,0,'راهم مزن به وصفِ زلالِ خِضِر که من','هوش مصنوعی: به من نگو درباره‌ی زلال و پاکی خضر، زیرا من از جام پادشاه، نوشیدنی از حوض کوثر را می‌نوشم.',NULL);
INSERT INTO "verses" VALUES(1932110,2458,3,1,'از جامِ شاه جُرعه کَشِ حوضِ کوثرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932111,2458,2,0,'جامی بده که باز به شادیِّ رویِ شاه','هوش مصنوعی: به من جامی بده تا به خاطر شادی و زیبایی چهره‌ی شاه، خاطرات جوانی در ذهنم زنده شود.',NULL);
INSERT INTO "verses" VALUES(1932112,2458,2,1,'پیرانه سر، هوایِ جوانیست در سرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932113,2458,1,0,'ساقی بیا که از مددِ بختِ کارساز','هوش مصنوعی: ای ساقی، بیایید که از کمک و شانس خوبم، آنچه را که از خدا خواسته‌ام به من عطا شده و فراهم آمده است.',NULL);
INSERT INTO "verses" VALUES(1932114,2458,1,1,'کامی که خواستم ز خدا شد مُیَسَّرَم',NULL,NULL);
INSERT INTO "verses" VALUES(1932115,2458,0,0,'جوزا سَحَر نهادْ حمایل برابرم','هوش مصنوعی: در سپیده‌دم، نشانه‌های پیروزی و عظمت شاه را به دوش می‌زنم و به همه اعلام می‌کنم که من خدمتگزار و همراه او هستم و بر این وفاداری‌ام سوگند می‌خورم.',NULL);
INSERT INTO "verses" VALUES(1932116,2458,0,1,'یعنی غلامِ شاهم و سوگند می‌خورم',NULL,NULL);
INSERT INTO "verses" VALUES(1932117,2458,14,1,'نِی عشق سرو بود و نه شوقِ صنوبرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932118,2458,15,0,'بویِ تو می‌شنیدم و بر یادِ رویِ تو','هوش مصنوعی: من بوی تو را استشمام می‌کردم و یاد چهره‌ات باعث شده بود که ساقیان خوشحال، دو لیوان به من بدهند.',NULL);
INSERT INTO "verses" VALUES(1932119,2458,15,1,'دادند ساقیانِ طَرَب یک دو ساغرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932120,2458,16,0,'مستی به آبِ یک دو عِنَب وضعِ بنده نیست','هوش مصنوعی: در حالتی که بقیه افراد با نشئه‌ی اندکی از شراب غرق لذت‌اند، من که سال‌ها تجربه دارم و در این راه جوانی‌ام را صرف کرده‌ام، به این نوع شادی‌ها نیازی ندارم.',NULL);
INSERT INTO "verses" VALUES(1932121,2459,6,0,'به خاکِ حافظ اگر یار بگذرد چون باد','هوش مصنوعی: اگر محبوب به خاک حافظ بگذرد، من از شدت شوق مانند بادی که از تنگنای دل عبور می‌کند، کفن خود را کنار می‌زنم.',NULL);
INSERT INTO "verses" VALUES(1932122,2459,5,1,'کس این کرشمه نبیند که من همی‌ نِگَرَم',NULL,NULL);
INSERT INTO "verses" VALUES(1932123,2459,5,0,'به هر نظر بُت ما جلوه می‌کند، لیکن','هوش مصنوعی: در هر دیداری، محبوب من زیبایی خود را نشان می‌دهد، اما هیچ‌کس نمی‌بیند که من به طور خاص چگونه او را تماشا می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1932124,2459,4,1,'هزار قطره بِبارَد چو دردِ دل شِمُرَم',NULL,NULL);
INSERT INTO "verses" VALUES(1932125,2459,4,0,'غلامِ مردمِ چشمم، که با سیاه دلی','هوش مصنوعی: من خدمتگزار کسانی هستم که به چشمانم نظر دارند. آن‌ها که با دل‌های سیاه و غمگین، مانند قطرات باران، هر آبی را بر من جاری می‌کنند زمانی که درد دل خود را بازگو می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1932126,2459,3,1,'که روزِ بی‌کسی آخر نمی‌روی ز سرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932127,2459,3,0,'چه شُکر گویمت ای خیلِ غم، عَفاکَ الله','هوش مصنوعی: چه بگویم از تو ای گروه غم، خدا تو را از من دور کرده است که روزهای تنهایی‌ام را ترک نمی‌کنی.',NULL);
INSERT INTO "verses" VALUES(1932128,2459,2,1,'که یک نظر فِکنی، خود فِکندی از نظرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932129,2459,2,0,'بر آستانِ مرادَت گشاده‌ام درِ چشم','هوش مصنوعی: به حضورِ محبوبم آمده‌ام و چشمانم را باز کرده‌ام تا فقط یک بار به من نگاه کند، اما همین نگاهش باعث شده که از دیدگانم ناپدید شود.',NULL);
INSERT INTO "verses" VALUES(1932130,2459,1,1,'بنفشه زار شود تُربَتَم چو درگذرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932131,2459,1,0,'چُنین که در دلِ من داغِ زلفِ سرکَشِ توست','هوش مصنوعی: دل من داغ و درد زلف‌های بی‌تاب تو را دارد، بنابراین وقتی از دنیا بروم، قبرم همچون باغ بنفشه‌ای پر از غم خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1932132,2459,0,1,'تبسمی کن و جان بین که چون همی‌سِپرَم',NULL,NULL);
INSERT INTO "verses" VALUES(1932133,2459,0,0,'تو همچو صبحی و من شمعِ خلوتِ سَحَرم','هوش مصنوعی: تو مانند صبحی و من شمعی در تنهایی سحر. لبخندی بزن و ببین که چطور من از تو سود می‌برم.',NULL);
INSERT INTO "verses" VALUES(1932134,2458,24,0,'مقصود از این معامله بازارتیزی است','هوش مصنوعی: هدف من از این کار، فریب یا تظاهر نیست؛ نه من زیبایی را برای فروش به نمایش می‌گذارم و نه به دنبال جلب توجه و محبت هستم.',NULL);
INSERT INTO "verses" VALUES(1932135,2460,0,0,'به تیغم گَر کُشد، دستش نگیرم','هوش مصنوعی: اگر کسی با تیغ به سوی من حمله کند، او را نمی‌گیرم و اگر هم تیر بیندازد، با کمال میل به او خدمت می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1932136,2458,24,1,'نی جلوه می‌فروشم و نی عشوه می‌خرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932137,2458,23,0,'بر من فُتاد سایهٔ خورشیدِ سلطنت','هوش مصنوعی: سایهٔ خورشید سلطنت بر من افتاد و اکنون از نور خورشید شرق راحت شدم.',NULL);
INSERT INTO "verses" VALUES(1932138,2458,22,0,'بنما به من که مُنکِرِ حُسنِ رخِ تو کیست','هوش مصنوعی: به من نشان بده که چه کسی منکر زیبایی چهره توست تا من با غیرتم به او پاسخ دهم و او را مورد سرزنش قرار دهم.',NULL);
INSERT INTO "verses" VALUES(1932139,2458,22,1,'تا دیده‌اش به گِزلِکِ غیرت برآورم',NULL,NULL);
INSERT INTO "verses" VALUES(1932140,2458,21,0,'ای عاشقانِ رویِ تو از ذَرِّه بیشتر','هوش مصنوعی: ای عاشقان زیبایی تو، من چگونه می‌توانم به وصالت برسم در حالی که از ذره‌ای کوچک‌تر هستم؟',NULL);
INSERT INTO "verses" VALUES(1932141,2458,21,1,'من کِی رَسَم به وصلِ تو کز ذَرِّه کمترم',NULL,NULL);
INSERT INTO "verses" VALUES(1932142,2458,20,0,'شِبلُ الاَسَد به صیدِ دلم حمله کرد و من','هوش مصنوعی: شیر جنگل به قلب من حمله‌ور شد و من اگرچه زادم لاغر هستم، در غیر این صورت می‌توانستم طعمه‌ی او باشم.',NULL);
INSERT INTO "verses" VALUES(1932143,2458,20,1,'گر لاغرم وگرنه شکارِ غضنفرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932144,2458,19,0,'نامم ز کارخانهٔ عُشّاق محو باد','هوش مصنوعی: نام من در دنیای عاشقان به فراموشی سپرده شده است، اگر غیر از عشق تو شغف و شغلی داشته باشم.',NULL);
INSERT INTO "verses" VALUES(1932145,2458,19,1,'گر جز محبتِ تو بُوَد شغلِ دیگرم',NULL,NULL);
INSERT INTO "verses" VALUES(1932146,2458,18,0,'شُکرِ خدا که باز در این اوجِ بارگاه','هوش مصنوعی: خوشحالم که دوباره در این بلندی و عظمت، صدای نام من از گوشه‌های عرش به گوش می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1932147,2458,18,1,'طاووسِ عرش می‌شنود صیتِ شَهپَرَم',NULL,NULL);
INSERT INTO "verses" VALUES(1932148,2458,17,0,'با سِیرِ اخترِ فلکم داوری بَسیست','هوش مصنوعی: با تأثیر ستاره‌ها در سرنوشت من، قضاوت و انصاف شاه در این داستان به یاری من آمده است.',NULL);
INSERT INTO "verses" VALUES(1932149,2458,17,1,'انصافِ شاه باد در این قصه یاورم',NULL,NULL);
INSERT INTO "verses" VALUES(1932150,2458,16,1,'من سالخورده پیرِ خرابات پَروَرَم',NULL,NULL);
INSERT INTO "verses" VALUES(1932151,2458,23,1,'و اکنون فَراغت است ز خورشیدِ خاورم',NULL,NULL);
INSERT INTO "verses" VALUES(1932152,2480,3,0,'کِی بود در زمانه وفا؟ جامِ مِی بیار','هوش مصنوعی: چه زمانی در این دنیا وفا وجود داشته است؟ یک جام شراب بیاور تا من داستان جمشید و کاووس را نقل کنم.',NULL);
INSERT INTO "verses" VALUES(1932153,2480,3,1,'تا من حکایتِ جم و کاووسِ کِی کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932154,2480,4,0,'از نامهٔ سیاه نترسم که روزِ حشر','هوش مصنوعی: از نوشتۀ بدی که برایم فرستاده‌اند نمی‌ترسم، زیرا در روز قیامت با لطف او می‌توانم هزاران صفحه از آن را نادیده بگیرم.',NULL);
INSERT INTO "verses" VALUES(1932155,2501,6,0,'از جرعه تو خاک زمین در و لعل یافت','هوش مصنوعی: از نوشیدنی تو، خاک زمین به جواهراتی چون در و لعل تبدیل شد، اما ما غم‌انگیزیم که در مقابل تو از خاک نیز کم‌درجه‌تر هستیم.',NULL);
INSERT INTO "verses" VALUES(1932156,2501,5,1,'ما نیز هم به شعبده دستی برآوریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932157,2501,5,0,'چون صوفیان به حالت و رقصند مقتدا','هوش مصنوعی: وقتی که صوفیان در حال عبادت و رقص هستند، ما نیز به سبک خودمان و با ترفندهایی که داریم، عملی انجام می‌دهیم.',NULL);
INSERT INTO "verses" VALUES(1932158,2501,4,1,'با خاک کوی دوست به فردوس ننگریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932159,2501,4,0,'واعظ مکن نصیحت شوریدگان که ما','هوش مصنوعی: ای واعظ، نصیحت کنان به دل‌های شوریده نپرداز؛ زیرا ما با خاک آن کوی محبوب، بهشتی دیگر نمی‌نگریم.',NULL);
INSERT INTO "verses" VALUES(1932160,2501,3,1,'در خون دل نشسته چو یاقوت احمریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932161,2501,3,0,'تا بو که دست در کمر او توان زدن','هوش مصنوعی: تا زمانی که بتوانم دستم را به کمر او بزنم، در عمق دل درد و غم نشسته‌ام، مانند یاقوتی که به رنگ احمری درآمده است.',NULL);
INSERT INTO "verses" VALUES(1932162,2501,2,1,'گر غم خوریم خوش نبود به که می خوریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932163,2501,2,0,'جایی که تخت و مسند جم می‌رود به باد','هوش مصنوعی: وقتی که قدرت و جایگاه سلطنت به باد می‌رود و از بین می‌رود، اگر غم و اندوه بزنیم، این بهتر است که به شادمانی بپردازیم.',NULL);
INSERT INTO "verses" VALUES(1932164,2501,1,1,'شرط آن بود که جز ره آن شیوه نسپریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932165,2501,1,0,'روز نخست چون دم رندی زدیم و عشق','هوش مصنوعی: در روز اول وقتی که به عشق روی آوردیم، تصمیم گرفتیم که جز به راه عشق نرویم و به هیچ شیوه دیگری اعتنا نکنیم.',NULL);
INSERT INTO "verses" VALUES(1932166,2501,0,1,'کز بهر جرعه‌ای همه محتاج این دریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932167,2501,0,0,'بگذار تا ز شارع میخانه بگذریم','هوش مصنوعی: اجازه بده تا از خیابان میخانه عبور کنیم، زیرا برای یک جرعه نوشیدنی، همه ما به این در نیازمندیم.',NULL);
INSERT INTO "verses" VALUES(1932168,2500,7,1,'یا رب چه گداهمت و بیگانه نهادیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932169,2500,7,0,'قانع به خیالی ز تو بودیم چو حافظ','هوش مصنوعی: ما راضی به خیال تو بودیم، مانند حافظ، اما ای خدای من، چقدر بیچاره و بیگانه‌ایم!',NULL);
INSERT INTO "verses" VALUES(1932170,2500,6,1,'آن را که لقب عاقل و فرزانه نهادیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932171,2500,6,0,'المنة للَّه که چو ما بی‌دل و دین بود','هوش مصنوعی: سپاسگزاری خاص خداوند است که کسی را که مانند ما بی‌دل و بی‌دین است، عاقل و فرزانه نامیده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932172,2500,5,1,'جان در سر آن گوهر یک دانه نهادیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932173,2500,5,0,'چون می‌رود این کشتی سرگشته که آخر','هوش مصنوعی: وقتی این کشتی سرگردان به راه خود ادامه می‌دهد، باید بدانیم که در نهایت جان خود را برای آن الماس گرانبها گذاشته‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932174,2500,4,1,'بنیاد از این شیوه رندانه نهادیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932175,2500,4,0,'در خرقه از این بیش منافق نتوان بود','هوش مصنوعی: در این لباس نمی‌توان به دورغ و نفاق ادامه داد، ما این پایه را بر اساس روش رندانه‌ای که داریم گذاشته‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932176,2500,3,1,'مهر لب او بر در این خانه نهادیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932177,2500,3,0,'در دل ندهم ره پس از این مهر بتان را','هوش مصنوعی: بعد از این به دل خود اجازه نمی‌دهم که به محبت معشوقان فکر کنم؛ زیرا عشق به لب‌های او را در این خانه بر در قرار داده‌ام.',NULL);
INSERT INTO "verses" VALUES(1932178,2500,2,1,'تا روی در این منزل ویرانه نهادیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932179,2500,2,0,'سلطان ازل گنج غم عشق به ما داد','هوش مصنوعی: خدای ازلی ما را با درد عشق آشنا کرد تا بتوانیم در این دنیا که پر از ویرانی است، زندگی کنیم.',NULL);
INSERT INTO "verses" VALUES(1932180,2500,1,1,'این داغ که ما بر دل دیوانه نهادیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932181,2500,1,0,'در خرمن صد زاهد عاقل زند آتش','داغ آن آتش که ما بر دل انسان های شیفته و عاشق و از خود بی خود زدیم خرمن وجود صدها زاهد عاقل را می سوزاند و از بین می برد.',NULL);
INSERT INTO "verses" VALUES(1932182,2500,0,1,'محصول دعا در ره جانانه نهادیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932183,2500,0,0,'ما درس سحر در ره میخانه نهادیم','هوش مصنوعی: ما در مسیر میخانه، آموزه‌های سحر را قرار دادیم و نتیجه‌ی دعاهای خود را در راه محبوب حقیقی گذاشتیم.',NULL);
INSERT INTO "verses" VALUES(1932184,2501,6,1,'بیچاره ما که پیش تو از خاک کمتریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932185,2499,6,1,'ز بدعهدیِّ گُل گویی حکایت با صبا گفتیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932186,2501,7,0,'حافظ چو ره به کنگره کاخ وصل نیست','هوش مصنوعی: حافظ می‌فرماید: وقتی که به راهی که به آغوش محبوب نمی‌رسد، نمی‌توانیم برویم، پس با خاک درگاه این در ارتباط برقرار می‌کنیم.',NULL);
INSERT INTO "verses" VALUES(1932187,2502,0,0,'خیز تا خرقه صوفی به خرابات بریم','هوش مصنوعی: بیا بلند شویم و به مکانی برویم که صوفی‌ها در آن هستند؛ جایی که نظرات و باورهای عجیب و غریب در آن وجود دارد و مردم به خرافات و افکار نامعقول سرگرم‌اند.',NULL);
INSERT INTO "verses" VALUES(1932188,2503,2,1,'نسیمِ عِطرگردان را، شِکَر در مِجمَر اندازیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932189,2503,2,0,'شرابِ ارغوانی را گلاب اندر قَدَح ریزیم','در قدح شراب ارغوانی رنگ، گلاب بریزیم و در آتشدان نسیم که بوی عطر می‌پراکند شکر بریزیم.ریختن گلاب در شراب به‌منظور دفع مضرت سردرد به‌ویژه برای مزاج‌های گرم و انبساط خاطر بود. ریختن شکر در آتشدان به‌منظور دوام بوی خوش و رفع سردرد ناشی از بوی تند عطر و مشک بود.',NULL);
INSERT INTO "verses" VALUES(1932190,2503,1,1,'من و ساقی به هم تازیم و بنیادش براندازیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932191,2503,1,0,'اگر غم لشکر انگیزد که خون عاشقان ریزد','اگر اندوه لشکری برای ریختن خون عاشقان فراهم کند، من و ساقی به یاری هم شتافته و بنیاد غم را از جا برکنیم.',NULL);
INSERT INTO "verses" VALUES(1932192,2503,0,1,'فلک را سقف بشکافیم و طرحی نو دراندازیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932193,2503,0,0,'بیا تا گل برافشانیم و می در ساغر اندازیم','بیا تا گلریزان کنیم و شراب در پیاله بریزیم، سپس سقف سپهر گردنده را درهم شکسته و از نو، شالوده دیگری بنیان نهیم.',NULL);
INSERT INTO "verses" VALUES(1932194,2502,11,1,'حاجت آن به که بر قاضی حاجات بریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932195,2502,11,0,'حافظ آب رخ خود بر در هر سفله مریز','هوش مصنوعی: حافظ می‌گوید که نباید زیبایی و جلوه‌ی خود را برای افرادی که ارزششان پایین است فدا کنیم. بهتر است به سراغ کسی برویم که قادر به برآورده کردن نیازهایمان باشد.',NULL);
INSERT INTO "verses" VALUES(1932196,2502,10,1,'ره بپرسیم مگر پی به مهمات بریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932197,2502,10,0,'در بیابان فنا گم شدن آخر تا کی','در این زندگی فانی ، غرق شدن در لذت ها و درد و رنج که باعث اتلاف وقت ارزشمن هست تا کی؟باید راه و هدف اصلی زندگی را پیدا کنیم',NULL);
INSERT INTO "verses" VALUES(1932198,2502,9,1,'تا به میخانه پناه از همه آفات بریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932199,2502,9,0,'فتنه می‌بارد از این سقف مقرنس برخیز','هوش مصنوعی: از این سقف پرزرق و برق مشکلات و فتنه‌ها به وفور موجود است، برخیز و به میخانه برویم تا از همه خطرات و آسیب‌ها دور شویم و آرامش پیدا کنیم.',NULL);
INSERT INTO "verses" VALUES(1932200,2502,8,1,'بس خجالت که از این حاصل اوقات بریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932201,2502,8,0,'قدر وقت ار نشناسد دل و کاری نکند','هوش مصنوعی: اگر دلی ارزش وقت را نشناسد و کاری انجام ندهد، باید از این که زمان‌های بیهوده‌ای را سپری کرده‌ایم، شرمنده باشیم.',NULL);
INSERT INTO "verses" VALUES(1932202,2502,7,1,'گر بدین فضل و هنر نام کرامات بریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932203,2502,7,0,'شرممان باد ز پشمینه آلوده خویش','هوش مصنوعی: باید از آلودگی‌های داخلی و ناپسند خود خجالت بکشیم، اگر بخواهیم به واسطه‌ی فضیلت و هنری که داریم، خود را بزرگ کنیم و به نام کرامت برسانیم.',NULL);
INSERT INTO "verses" VALUES(1932204,2502,6,1,'از گلستانش به زندان مکافات بریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932205,2502,6,0,'ور نهد در ره ما خار ملامت زاهد','هوش مصنوعی: اگر در مسیر ما خاری از ملامت بیفتد، زاهد از گلستانش به زندان عذاب خواهد رفت.',NULL);
INSERT INTO "verses" VALUES(1932206,2502,5,1,'همه بر فرق سر از بهر مباهات بریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932207,2502,5,0,'خاک کوی تو به صحرای قیامت فردا','هوش مصنوعی: خاک درگاه تو در روز قیامت به عنوان نماد افتخار، بر سر ما خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1932208,2502,4,1,'علم عشق تو بر بام سماوات بریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932209,2502,4,0,'کوس ناموس تو بر کنگره عرش زنیم','هوش مصنوعی: پرچم اعتبار تو را بر قلهٔ آسمان‌ها برافراشته می‌کنیم و به بلندای عشق تو پرواز می‌کنیم.',NULL);
INSERT INTO "verses" VALUES(1932210,2502,3,1,'همچو موسی ارنی گوی به میقات بریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932211,2502,3,0,'با تو آن عهد که در وادی ایمن بستیم','هوش مصنوعی: با تو آن پیمانی که در جای امن بستیم، مانند موسی که گفت خدایا مرا ببین، ما نیز به میقات برویم.',NULL);
INSERT INTO "verses" VALUES(1932212,2502,2,1,'چنگ صبحی به در پیر مناجات بریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932213,2502,2,0,'تا همه خلوتیان جام صبوحی گیرند','هوش مصنوعی: به محض اینکه همه دلداران فرصت را غنیمت شمرده و جرعه‌ای از شراب صبحگاهی بنوشند، ما هم به سوی درگاه پیر و سالک عبادت خواهیم رفت.',NULL);
INSERT INTO "verses" VALUES(1932214,2502,1,1,'دلق بسطامی و سجاده طامات بریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932215,2502,1,0,'سوی رندان قلندر به ره آورد سفر','هوش مصنوعی: به سمت افرادی که سرشت آزاد و بی‌خیالی دارند، سفر کرده‌ایم و لباس و نذر و عبادت را رها کرده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932216,2502,0,1,'شطح و طامات به بازار خرافات بریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932217,2501,7,1,'با خاک آستانه این در به سر بریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932218,2499,6,0,'تو آتش گشتی ای حافظ ولی با یار درنگرفت','هوش مصنوعی: ای حافظ، تو به آتش تبدیل شده‌ای، ولی با یار خود ارتباط برقرار نکردی. ما از بدعهدی گل، داستانی را با باد صبا در میان گذاشتیم.',NULL);
INSERT INTO "verses" VALUES(1932219,2499,5,1,'جزای آن که با زلفت سخن از چین خطا گفتیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932220,2499,5,0,'جگر چون نافه‌ام خون گشت کم زینم نمی‌باید','هوش مصنوعی: دل من به شدت از غم و اندوه پر شده است و این احساس درد و رنج بر من چیره شده، اما من هیچ جزایی برای آنچه بر من گذشته نمی‌خواهم، جز آنکه به خاطر زلف تو، بخاطر اشتباهی که در نیاوردن کلمات درست درباره‌اش کردم، عذرخواهی کنم.',NULL);
INSERT INTO "verses" VALUES(1932221,2497,3,1,'اگر از جورِ غمِ عشقِ تو دادی طلبیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932222,2497,3,0,'لذتِ داغِ غمت بر دلِ ما باد حرام','هوش مصنوعی: اگر داغ و دردِ عشقِ تو بر دل‌مان سنگینی کند، ما را حکمی نمی‌باشد که این احساس را بپذیریم. اگر غمِ تو منجر به رنج و ستمی شده باشد، ما طالب این رنج نخواهیم بود.',NULL);
INSERT INTO "verses" VALUES(1932223,2497,2,1,'به رسالت سویِ او پاک‌نهادی طلبیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932224,2497,2,0,'اشکِ آلودهٔ ما گرچه روان است ولی','هوش مصنوعی: اگرچه اشک‌های ما آلوده و جاری هستند، اما ما به خاطر رسالت و هدفی پاک در جستجوی او هستیم.',NULL);
INSERT INTO "verses" VALUES(1932225,2497,1,1,'به گدایی ز درِ میکده زادی طلبیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932226,2497,1,0,'زادِ راهِ حَرمِ وصل نداریم مگر','هوش مصنوعی: ما هیچ راهی برای رسیدن به هدف‌های معنوی و عشق الهی نداریم، جز اینکه با فروتندی و درخواست از درگاه معشوق، از میکده و عشق واقعی طلب کنیم.',NULL);
INSERT INTO "verses" VALUES(1932227,2497,0,1,'به رَهِ دوست نشینیم و مُرادی طلبیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932228,2497,0,0,'خیز تا از درِ میخانه گُشادی طلبیم','هوش مصنوعی: بیا تا از درِ میخانه وارد شویم و به دنبال دوست بگردیم و از او بهره‌ای ببریم.',NULL);
INSERT INTO "verses" VALUES(1932229,2496,10,1,'چه به از دولتِ لطفِ سخن و طَبع سلیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932230,2496,10,0,'حافظ ار سیم و زرت نیست، چه شد؟ شاکر باش','هوش مصنوعی: اگر به زیبایی و ثروت دست نیافتی، نگران نباش. شکرگزار باش زیرا لطف کلام و طبیعت خوب، از هر ثروتی بهتر است.',NULL);
INSERT INTO "verses" VALUES(1932231,2496,9,1,'ور نه آدم نَبَرد صرفه ز شیطانِ رجیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932232,2496,9,0,'دام سخت است مگر یار شود لطفِ خدا','هوش مصنوعی: تاریکی و سختی زندگی تنها با کمک و لطف الهی قابل تحمل است، و در غیر این صورت، انسان نمی‌تواند از وسوسه‌های شیطان دور بماند.',NULL);
INSERT INTO "verses" VALUES(1932233,2496,8,1,'که نصیبِ دگران است نِصابِ زر و سیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932234,2496,8,0,'گوهرِ معرفت آموز که با خود بِبَری','هوش مصنوعی: برای کسب دانش و آگاهی، باید آن را درونی کرده و با خود به همراه داشته باشی، زیرا ثروت مادی و دارایی‌های دیگر، فقط نصیب دیگران خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1932235,2496,7,1,'درد عاشق نشود به، به مداوایِ حکیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932236,2496,7,0,'فکر بهبود خود ای دل ز دری دیگر کن','هوش مصنوعی: ای دل، سعی کن به فکر بهبودی و بهبود خودت باشی و از راهی دیگر پیش برو. درد عشق را نمی‌توان تنها با درمان‌های حکیمانه آرام کرد.',NULL);
INSERT INTO "verses" VALUES(1932237,2496,6,1,'کز دم صبح مدد یابی و انفاسِ نسیم»',NULL,NULL);
INSERT INTO "verses" VALUES(1932238,2496,6,0,'غنچه گو «تنگ‌دل از کارِ فروبسته مَباش','هوش مصنوعی: ای غنچه، دل تنگی نکن و از کارهای ناتمام ناامید نباش، زیرا با طلوع صبح می‌توانی از لطف و نسیم تازه بهره‌مند شوی.',NULL);
INSERT INTO "verses" VALUES(1932239,2496,5,1,'ظاهراً عهد فرامُش نکُند خُلقِ کریم',NULL,NULL);
INSERT INTO "verses" VALUES(1932240,2496,5,0,'دلبر از ما به صد امّید سِتد اول دل','هوش مصنوعی: معنای این بیت به این صورت است که محبوب ما با صد امید به ما نگاه می‌کند، اما اول از همه باید دلی را که داده است فراموش نکند. افرادی که سخاوتمند و نیکوکار هستند، باید به یاد داشته باشند که در این رابطه، وعده‌ها و عهدها نباید نادیده گرفته شوند.',NULL);
INSERT INTO "verses" VALUES(1932241,2496,4,1,'سر برآرد ز گِلم رقص‌کنان عَظمِ رَمیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932242,2496,4,0,'بعد صد سال اگر بر سرِ خاکم گذری','هوش مصنوعی: پس از گذشت صد سال، اگر بر سر خاک من بگذری، سنگینی خاک از روی سرم برمی‌خیزد و رقصکنان به پا می‌خیزد.',NULL);
INSERT INTO "verses" VALUES(1932243,2496,3,1,'ای نسیم سحری! یاد دَهَش عهدِ قدیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932244,2496,3,0,'مگرش خدمتِ دیرین من از یاد برفت','هوش مصنوعی: آیا فراموش کرده‌ای که من همیشه به تو خدمت کرده‌ام؟ ای نسیم صبحگاهی، یادآور عهد و پیمان قدیمی ما باش.',NULL);
INSERT INTO "verses" VALUES(1932245,2496,2,1,'سال‌ها شد که منم بر درِ میخانه مقیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932246,2496,2,0,'تا مگر جرعه فشانَد لبِ جانان بر من','هوش مصنوعی: سال‌هاست که من در درِ میخانه نشسته‌ام و امیدوارم که محبوبم قدری از شراب به سوی من بریزد.',NULL);
INSERT INTO "verses" VALUES(1932247,2496,1,1,'روح را صحبتِ ناجنس، عذابی‌ست اَلیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932248,2496,1,0,'چاک خواهم زدن این دلقِ ریایی، چه کنم؟','هوش مصنوعی: من می‌خواهم این پوشش فریبنده را پاره کنم، ولی چه کار کنم؟ صحبت با این نوع روح و نفس، برایم عذابی شدید و سخت است.',NULL);
INSERT INTO "verses" VALUES(1932249,2496,0,1,'که حرام است مِی آن جا که نه یار است ندیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932250,2497,4,0,'نقطهٔ خالِ تو بر لوحِ بصر نَتوان زد','هوش مصنوعی: نقطهٔ خالِ تو را نمی‌توان بر روی چشم‌ها کشید، مگر اینکه از شخصی که در زمینۀ دیدن ماهر است، کمک بگیریم.',NULL);
INSERT INTO "verses" VALUES(1932251,2497,4,1,'مگر از مَردُمَکِ دیده مِدادی طلبیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932252,2497,5,0,'عشوه‌ای از لبِ شیرینِ تو دل خواست به جان','هوش مصنوعی: دل به زیبایی و چهرهٔ دل‌ربای تو خوش می‌کند و از لب‌های شیرینت می‌خواهد که با لبخندت، لذتی بیشتر به او ببخشی.',NULL);
INSERT INTO "verses" VALUES(1932253,2497,5,1,'به شکرخنده لَبَت گفت مَزادی طلبیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932254,2499,4,1,'که این نسبت چرا کردیم و این بُهتان چرا گفتیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932255,2499,4,0,'قَدَت گفتم که شمشاد است؛ بس خِجلَت به بار آورد','هوش مصنوعی: می‌گویم که تو مانند شمشاد هستی، اما بعداً خجالت کشیدم که چرا این حرف را زدم و چرا به تو نسبت این ویژگی را دادم.',NULL);
INSERT INTO "verses" VALUES(1932256,2499,3,1,'به خاطر دار این معنی که در خدمت کجا گفتیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932257,2499,3,0,'اگر بر من نَبَخشایی پشیمانی خوری آخر','اگر من را نبخشی، در آینده پشیمان خواهی شد. پس به یاد داشته باش که ما در کجا و چه صحبت‌هایی درباره خدمت به هم داشتیم.',NULL);
INSERT INTO "verses" VALUES(1932258,2499,2,1,'بلایی کز حبیب آید هِزارش مَرحَبا گفتیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932259,2499,2,0,'من از چشمِ تو ای ساقی خراب افتاده‌ام لیکن','هوش مصنوعی: من از نگاه تو، ای ساقی، در حال بیهوشی و مستی هستم، اما هر دردسر و مشکل که از طرف محبوب بیاید، برای آن هزار بار خوشآمد می‌گوییم.',NULL);
INSERT INTO "verses" VALUES(1932260,2499,1,1,'گَرَت باور بُوَد ور نه سخن این بود و ما گفتیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932261,2499,1,0,'درِ میخانه‌ام بُگشا که هیچ از خانقه نَگشود','هوش مصنوعی: در میخانه را بگشایید، چون هیچ چیزی از خانقاه (محل صوفیان) به شما نخواهد داد. اگر به این موضوع ایمان دارید، که خوب است؛ وگرنه، همین نکته را گفتیم.',NULL);
INSERT INTO "verses" VALUES(1932262,2499,0,1,'به دورِ نرگسِ مستت سلامت را دعا گفتیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932263,2499,0,0,'صَلاح از ما چه می‌جویی؟ که مستان را صَلا گفتیم','هوش مصنوعی: صلاح و خوبی از ما چه می‌خواهی؟ ما برای مستان دعا کردیم و به خاطر نرگس معشوقه‌ات، همواره سلامتی آرزو کردیم.',NULL);
INSERT INTO "verses" VALUES(1932264,2498,6,0,'گفت خود دادی به ما دل حافظا','معشوق در قبال سخنانِ گله آمیز حافظ گفت:ای حافظ که اینقدر گله و شکایت می کنی،تـو خودت دل به مـا سپردی و عاشق ما شدی ، کسی برای تو دعوت نامه نفرستاده و تو خود پیش قدم شده و عشق ما را در دل نشاندی! ما که کسی را مـأمـور نـکـردیـم که دل تـو را بـگـیـرد و به مـا بـدهـد.!',NULL);
INSERT INTO "verses" VALUES(1932265,2498,6,1,'ما مُحَصِّل بر کسی نَگماشتیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932266,2498,5,0,'نکته‌ها رفت و شکایت کس نکرد','بی توجّی های تو ما را آزرده خاطر ساخت، نامهربانی های بسیـار دیدیم ، امّا بـه حُرمتِ تـو کسی گـله و شکایت نـکـرد.!',NULL);
INSERT INTO "verses" VALUES(1932267,2498,5,1,'جانبِ حُرمَت فرو نگذاشتیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932268,2503,3,0,'چو در دست است رودی خوش، بزن مطرب سرودی خوش','ای مطرب، اکنون که عودی خوش‌نوا در دسترس توست، سرودی خوش‌آهنگ بنواز تا در حالت رقص شعری بخوانیم و در حالت پایکوبی به جای دستار سر بر خاک بیندازیم',NULL);
INSERT INTO "verses" VALUES(1932269,2498,4,0,'گُلبُنِ حُسنَت نه خود شد دلفُروز','خطاب به معشوق است. یادت باشد که این بوته ی زیباییِ تو خود بخود به این حد از کمال نرسیده است! این ما بودیم که شبانه روز بی وقفه مشتاقانه دعا کردیم و انرژی های مثبت را از صمیم جان و دل مامور حفاظت و سلامتی و سرافرازی تو نمودیم.',NULL);
INSERT INTO "verses" VALUES(1932270,2498,3,0,'شیوهٔ چَشمت فریبِ جنگ داشت','غمزه ها و طرز نگاه کردن تو را از سادگی، به ناز و عشوه تعبیر کردیم! در حالی که ما عاشق بودیم و نمی دانستیم که این طرز نگاهِ تو قصد و غرضی در پی دارد و آن اعلانِ جنگ ونبرد است‌. ما اشتباه کردیم وصلح و آشتی تعبیر نمودیم.',NULL);
INSERT INTO "verses" VALUES(1932271,2498,3,1,'ما غلط کردیم و صلح انگاشتیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932272,2498,2,0,'گفت‌و‌گو آیینِ درویشی نبود','مجادله و بحث بر سر اینکه چرا تو رسم رفاقت را به جا نیاوردی و مرتکبِ خطا شدی در آئین درویشی وجوانمردی درست نیست و من هم قصد مجادله ندارم وگرنه من اگر همچنان مثلِ سابق صوفی بودم می بایست این نامهربانی و زیر پا گذاشتن رسم رفاقت از جانبِ تو در محضر پیر خانقاه مطرح می شد و تو نیز مجازات می شدی.',NULL);
INSERT INTO "verses" VALUES(1932273,2498,2,1,'ور نه با تو ماجراها داشتیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932274,2498,1,0,'تا درختِ دوستی بَر کِی دهد','ما یک بذر دوستی در مزرعه ی دلمان کاشته ایم تا بـبـیـنـیـم چه زمانی این بذر شکوفا خواهد شد و چه زمانی این درخت میوه و ثمر خواهد داشت.',NULL);
INSERT INTO "verses" VALUES(1932275,2498,1,1,'حالیا رفتیم و تخمی کاشتیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932276,2498,0,0,'ما زِ یاران چَشمِ یاری داشتیم','مـا از دوستان خویش توقّع کمک و مساعدت داشتـیـم ، امـّا دریغا که توقّع ما نابجا بوده و آنگونه که می پنداشتیم رشته ی دوستی و اُلفتِ ما محکم نبوده است. ما اشتباه می کردیم و ظاهراّ دوستی بین ما جاری نبوده است و اینک انتظارمان نیز بیهوده و بیجاست.',NULL);
INSERT INTO "verses" VALUES(1932277,2498,0,1,'خود غلط بود آنچه ما پنداشتیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932278,2497,8,1,'خیز تا از درِ میخانه گُشادی طلبیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932279,2497,8,0,'بر درِ مدرسه تا چند نشینی حافظ؟','هوش مصنوعی: به مدت طولانی درِ مدرسه نشسته‌ای؛ بهتر است بلند شوی و از درِ میخانه، یعنی مکان خوشگذرانی و آزادی، درخواست تو را طلب کنیم.',NULL);
INSERT INTO "verses" VALUES(1932280,2497,7,1,'ما به امّیدِ غمت خاطرِ شادی طلبیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932281,2497,7,0,'چون غمت را نَتَوان یافت مگر در دلِ شاد','هوش مصنوعی: چون نمی‌توان غم تو را پیدا کرد، جز در دل‌های شاد ما، به امید غم تو، شادی را جستجو می‌کنیم.',NULL);
INSERT INTO "verses" VALUES(1932282,2497,6,1,'از خطِ غالیه‌سایِ تو سوادی طلبیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932283,2497,6,0,'تا بُوَد نسخهٔ عطری دل سودازده را','هوش مصنوعی: من به دنبال این هستم که نسخه‌ای از عطری که دلِ بی‌تاب را آرام کند، از نوشته‌های تو بردارم.',NULL);
INSERT INTO "verses" VALUES(1932284,2498,4,1,'ما دَمِ همت بر او بگماشتیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932285,2503,3,1,'که دست‌افشان غزل خوانیم و پاکوبان سر اندازیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932286,2503,4,0,'صبا! خاک وجود ما، بدان عالی‌جناب انداز','ای باد صبا، تن خاکی ما را بر در آن آستانه رفیع بینداز، شاید که بتوانیم بر آن سرور زیبایان نگاهی بیندازیم.',NULL);
INSERT INTO "verses" VALUES(1932287,2503,4,1,'بُوَد کآن شاهِ خوبان را نظر بر مَنظَر اندازیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932288,2509,5,1,'می‌سرایم به شب و وقت سحر می‌مویم',NULL,NULL);
INSERT INTO "verses" VALUES(1932289,2509,5,0,'خنده و گریه عشاق ز جایی دگر است','هوش مصنوعی: عشق و احساسات عاشقان از منبعی دیگر نشأت می‌گیرد. من در شب و هنگام سحر به خواندن و سرودن مشغولم.',NULL);
INSERT INTO "verses" VALUES(1932290,2509,4,1,'مکنم عیب کَزو رنگِ ریا می‌شویم',NULL,NULL);
INSERT INTO "verses" VALUES(1932291,2509,4,0,'گر چه با دلق ملمع، مِیِ گلگون عیب است','هوش مصنوعی: هرچند که پوشیدن لباس زرق و برق‌دار با رنگ قرمز زیبا ناپسند است، اما من عیبی نمی‌بینم؛ زیرا از او رنگ و بوی ریا به ما می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1932292,2509,3,1,'گوهری دارم و صاحب نظری می‌جویم',NULL,NULL);
INSERT INTO "verses" VALUES(1932293,2509,3,0,'دوستان! عیب من بی‌دل حیران مکنید','هوش مصنوعی: دوستان، لطفاً عیب‌هایم را بی‌دلیل برملا نکنید. من ارزش و گوهری دارم و به دنبال فردی با دیدگاه و نظری مناسب هستم.',NULL);
INSERT INTO "verses" VALUES(1932294,2509,2,1,'که از آن دست که او می‌کِشدم، می‌رویم',NULL,NULL);
INSERT INTO "verses" VALUES(1932295,2509,2,0,'من اگر خارم و گر گل چمن‌آرایی هست','هوش مصنوعی: من هر چه که باشم، چه خار و چه گل زیبای چمن، چیزی هست که به خاطر آن وجودم را که او می‌سازد، می‌گذرانم.',NULL);
INSERT INTO "verses" VALUES(1932296,2509,1,1,'آن چه استاد ازل گفت بگو، می‌گویم',NULL,NULL);
INSERT INTO "verses" VALUES(1932297,2509,1,0,'در پس آینه، طوطی‌صفتم داشته‌اند','هوش مصنوعی: در پشت آینه، صفتم را مثل طوطی ترسیم کرده‌اند و هر آنچه که آموزگار ازل به من گفت، می‌گویم.',NULL);
INSERT INTO "verses" VALUES(1932298,2509,0,1,'که منِ دل‌شده این ره، نه به خود می‌پویم',NULL,NULL);
INSERT INTO "verses" VALUES(1932299,2509,0,0,'بارها گفته‌ام و بار دگر می‌گویم','هوش مصنوعی: بارها گفته‌ام و باز هم تکرار می‌کنم که من در این مسیر، دل‌سپرده‌ام و نه به خودم توجه می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1932300,2508,8,1,'غبار زرق به فیض قدح فروشویم',NULL,NULL);
INSERT INTO "verses" VALUES(1932301,2508,8,0,'بیار می که به فتوی حافظ از دل پاک','هوش مصنوعی: بیار می، زیرا به گفته حافظ، با دل پاک می‌توانیم غبار دروغ و ظاهر فریبی را از روح خود پاک کنیم و به لذت واقعی شراب دست یابیم.',NULL);
INSERT INTO "verses" VALUES(1932302,2508,7,1,'چو لاله با قدح افتاده بر لب جویم',NULL,NULL);
INSERT INTO "verses" VALUES(1932303,2508,7,0,'ز شوق نرگس مست بلندبالایی','هوش مصنوعی: از سر شوق و عشق به نرگس، قد بلند و زیبا به وجود آمده‌ام، مانند لاله‌ای که در حال سر زدن به کنار جوی و در حال نوشیدن از آن است.',NULL);
INSERT INTO "verses" VALUES(1932304,2508,6,1,'غلام دولت آن خاک عنبرین بویم',NULL,NULL);
INSERT INTO "verses" VALUES(1932305,2508,6,0,'غبار راه طلب، کیمیای بهروزی‌ست','هوش مصنوعی: غبار راه جستجوی خوشبختی همانند طلا و گرانبهاست. من که خدمتگزار آن خاک خوشبو هستم.',NULL);
INSERT INTO "verses" VALUES(1932306,2508,5,1,'خدا گواه که هر جا که هست، با اویم',NULL,NULL);
INSERT INTO "verses" VALUES(1932307,2508,5,0,'تو خانقاه و خرابات در میانه مبین','هوش مصنوعی: در میانه خانقاه و جایگاه خراباتیان نباید فراموش کرد که خداوند بر هر چیزی شاهد است و من در هر مکان که باشم، همیشه با او هستم.',NULL);
INSERT INTO "verses" VALUES(1932308,2508,4,1,'چنان که پرورشم می‌دهند، می‌رویم',NULL,NULL);
INSERT INTO "verses" VALUES(1932309,2508,4,0,'مکن در این چمنم سرزنش به خودرویی','هوش مصنوعی: در این گلزار، خود را ملامت نکن، زیرا همان‌طور که در حال رشد و پیشرفت هستیم، به آرامی به جلو می‌رویم.',NULL);
INSERT INTO "verses" VALUES(1932310,2508,3,1,'کدام در بزنم؟ چاره از کجا جویم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1932311,2508,3,0,'گرم نه پیر مغان در به روی بگشاید','هوش مصنوعی: اگر پیر مغان در را به روی من باز نکند، نمی‌دانم به کدام در باید کوبید و راه حل را از کجا پیدا کنم.',NULL);
INSERT INTO "verses" VALUES(1932312,2508,2,1,'کشید در خم چوگان خویش چون گویم',NULL,NULL);
INSERT INTO "verses" VALUES(1932313,2508,2,0,'شدم فسانه به سرگشتگی و ابروی دوست','هوش مصنوعی: در حالتی از سرگشتگی و سردرگمی قرار گرفتم که ابروی محبوبم به گونه‌ای در ذهنم نقش بسته است که نمی‌توانم آن را به خوبی بیان کنم.',NULL);
INSERT INTO "verses" VALUES(1932314,2508,1,1,'مرید خرقهٔ دردی‌کشان خوش‌خویم',NULL,NULL);
INSERT INTO "verses" VALUES(1932315,2508,1,0,'عبوس زهد به وجه خمار ننشیند','عبوس زهد یعنی این شیوخ و واعظانی که جلوه در محراب و منبر می می کنند ، هیچ وقت چهره عبوس شون نمی تواند به مانند یک فرد شراب خور که چهره حالت خاصی دارد ، تغییر کنن. اینقدر در زهد عبات گونه دروغین فرو رفته اند که به حالت یک مست میخانه نمی توانند در بیایند یا تجربه کنند. اونها عبوسند و من حافظ مرید و راهرو دردی کشان - کسانی که تا انتهای مجلس شراب خواری ، شراب می خورند - هستم. چون این دست ادم ها لااقل دو رو و دروغگو نیستند',NULL);
INSERT INTO "verses" VALUES(1932316,2508,0,1,'که من نسیم حیات از پیاله می‌جویم',NULL,NULL);
INSERT INTO "verses" VALUES(1932317,2509,6,0,'حافظم گفت که «خاک در میخانه مبوی»','هوش مصنوعی: حافظ می‌گوید که به خاطر بوی خوب مشک ختن، هیچ عیبی برای بوی خاک در میخانه مطرح نکن. یعنی وقتی در برابر زیبایی و خوبی چیزی قرار می‌گیریم، نباید به نقاط ضعف یا عیب‌های دیگر توجه کنیم.',NULL);
INSERT INTO "verses" VALUES(1932318,2509,6,1,'گو «مکن عیب که من مشک ختن می‌بویم»',NULL,NULL);
INSERT INTO "verses" VALUES(1932319,2510,0,0,'گرچه ما بندگان پادشهیم','هوش مصنوعی: هرچند ما خدمتگذاران سلطنتیم، اما در واقع ما فرمانروایان و سروران زمان خود هستیم.',NULL);
INSERT INTO "verses" VALUES(1932320,2510,0,1,'پادشاهان ملک صبحگهیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932321,2511,5,1,'نَبضِ مَرا که می‌دَهَد هیچ زِ زندگی نِشان',NULL,NULL);
INSERT INTO "verses" VALUES(1932322,2511,5,0,'بازنِشانْ حَرارَتَم ز آبِ دو دیده و ببین','هوش مصنوعی: مرا با اشک‌های چشمانم از حرارت خود بازنشانی و نگاهی به نبض من بینداز که هیچ نشانه‌ای از زندگی نمی‌دهد.',NULL);
INSERT INTO "verses" VALUES(1932323,2511,4,1,'چَشمم از آن دو چَشمِ تو خسته شُده‌ست و ناتَوان',NULL,NULL);
INSERT INTO "verses" VALUES(1932324,2511,4,0,'حالِ دِلَم زِ خالِ تو هَست دَر آتَشَش وَطن','هوش مصنوعی: احساس درونیم تحت تأثیر زیبایی توست، به طوری که چشمانم از خیره شدن به چشمان تو خسته و ناتوان شده‌اند.',NULL);
INSERT INTO "verses" VALUES(1932325,2511,3,1,'همچو تَبَم نمی‌رَوَد آتشِ مِهر از اُستُخوان',NULL,NULL);
INSERT INTO "verses" VALUES(1932326,2511,3,0,'گرچه تَبْ اُستُخوانِ مَن کرد زِ مِهرْ گرم و رَفت','هوش مصنوعی: هرچند عشق مرا به شدت عاطفی و بیمار کرده است و احساساتم داغ و پرحرارت است، اما آتش این عشق هرگز از وجودم خاموش نخواهد شد.',NULL);
INSERT INTO "verses" VALUES(1932327,2511,2,1,'کـاین دَم و دودِ سینه‌ام، بارِ دل اَست بَر زَبان',NULL,NULL);
INSERT INTO "verses" VALUES(1932328,2511,2,0,'ای که طَبیبِ خَسته‌ای، رویِ زَبان مَن بِبین','هوش مصنوعی: ای پزشک خسته، نگاهی به زبان من کن، زیرا آنچه که در این لحظه از سینه‌ام خارج می‌شود، تمام بار غم‌ها و دلخوری‌هایم بر زبان است.',NULL);
INSERT INTO "verses" VALUES(1932329,2511,1,1,'گو نَفَسی که روح را می‌کُنَم از پِیَش رَوان',NULL,NULL);
INSERT INTO "verses" VALUES(1932330,2511,1,0,'آن که به پُرسش آمَد و فاتحه خواند و می‌رَوَد','هوش مصنوعی: کسی که به سوال آمد و فاتحه‌ای خواند و در حال رفتن است، به او بگو که من روح را برای او به دنبال می‌آورم.',NULL);
INSERT INTO "verses" VALUES(1932331,2511,0,1,'لَب بُگُشا که می‌دَهَد لَعلِ لَبَت به مُرده جان',NULL,NULL);
INSERT INTO "verses" VALUES(1932332,2511,0,0,'فاتحه‌ای چو آمَدی بَر سَر خَسته‌ای بخوان','هوش مصنوعی: وقتی به سر یک انسان خسته و بیمار می‌رسی، دعا و فاتحه‌ای برای او بخوان. لب‌های خود را باز کن، چون لب‌های تو با زیبایی شگفت‌انگیز خود می‌تواند به او زندگی تازه‌ای ببخشد.',NULL);
INSERT INTO "verses" VALUES(1932333,2510,9,1,'کرده‌ای اعتراف و ما گوهیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932334,2510,9,0,'وام حافظ بگو که بازدهند','هوش مصنوعی: ای حافظ، به من بگو که باز هم برمی‌گردانند، و تو اعتراف کرده‌ای که ما در زندگی ارزشمند هستیم.',NULL);
INSERT INTO "verses" VALUES(1932335,2508,0,0,'سرم خوش است و به بانگ بلند می‌گویم','هوش مصنوعی: خوشحالم و با صدای بلند اعلام می‌کنم که به دنبال جانی تازه و سرزندگی هستم.',NULL);
INSERT INTO "verses" VALUES(1932336,2510,8,1,'شیر سرخیم و افعی سیهیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932337,2510,7,1,'دوستان را قبای فتح دهیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932338,2510,7,0,'دشمنان را ز خون کفن سازیم','هوش مصنوعی: بی‌رحمی و سختی را بر دشمنان تحمیل کنیم و به دوستان‌مان پیروزی و موفقیت ببخشیم.',NULL);
INSERT INTO "verses" VALUES(1932339,2510,6,1,'روی همّت به هر کجا که نهیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932340,2510,6,0,'شاه منصور واقف است که ما','هوش مصنوعی: شاه منصور می‌داند که هر جا که اراده کنیم، به آنجا خواهیم رفت.',NULL);
INSERT INTO "verses" VALUES(1932341,2510,5,1,'که تو در خواب و ما به دیده گهیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932342,2510,5,0,'گو غنیمت شمار صحبت ما','هوش مصنوعی: از گفت‌وگو با ما بهره‌مند باش، چرا که تو در خواب هستی و ما به وضوح در حال مشاهده‌ات هستیم.',NULL);
INSERT INTO "verses" VALUES(1932343,2510,4,1,'ما نگهبان افسر و کلهیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932344,2510,4,0,'شاه بیدار بخت را هر شب','هوش مصنوعی: ما هر شب نگهبان بختی هستیم که به خواب خوش پادشاه می‌رود.',NULL);
INSERT INTO "verses" VALUES(1932345,2510,3,1,'ماش آیینه‌ رخ چو مهیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932346,2510,3,0,'شاهد بخت چون کرشمه کند','هوش مصنوعی: وقتی که بخت و اقبال به انسان لبخند می‌زند، زیبایی او مانند ماه در آینه می‌درخشد.',NULL);
INSERT INTO "verses" VALUES(1932347,2510,2,1,'بحر توحید و غرقهٔ گنهیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932348,2510,2,0,'هوشیار حضور و مست غرور','هوش مصنوعی: بیدار و آگاه از زندگی هستیم، اما در عین حال در حالتی مست و غرق در شادی و غروریم. همزمان، در در دنیای توحید غوطه‌وریم و دچار گناه و خطا نیز هستیم.',NULL);
INSERT INTO "verses" VALUES(1932349,2510,1,1,'جام گیتی‌نما و خاک رهیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932350,2510,1,0,'گنج در آستین و کیسه تهی','هوش مصنوعی: ما به ظاهر امکانات و ثروت کافی نداریم، اما در درون خود گنجینه‌ای از ارزش‌ها و دانایی داریم. زندگی را با نگرش مثبت می‌بینیم و هر کجا که می‌رویم، به دنبال نکات زیبا و معنای عمیق هستیم.',NULL);
INSERT INTO "verses" VALUES(1932351,2510,8,0,'رنگ تزویر پیش ما نبود','هوش مصنوعی: رنگ تزویر و نیرنگ در نزد ما جایی ندارد؛ ما همانند شیر سرخ و مار سیاه هستیم، یعنی با شجاعت و قدرت ظاهری واقعی خود را نشان می‌دهیم.',NULL);
INSERT INTO "verses" VALUES(1932352,2496,0,0,'فتوی پیرِ مُغان دارم و قولی‌ست قدیم','هوش مصنوعی: من از استادان پیشین نظری دارم و اعتقادی قدیمی بر این است که نوشیدن شراب در جایی که دوستان و یاران نیستند، ممنوع است.',NULL);
INSERT INTO "verses" VALUES(1932353,2507,7,0,'حافظ ار خصم خطا گفت، نگیریم بر او','هوش مصنوعی: اگر دشمن اشتباهی کرد، ما به او چیزی نمی‌گوییم؛ و اگر سخنش حق بود، در مورد حق بحث و جدل نمی‌کنیم.',NULL);
INSERT INTO "verses" VALUES(1932354,2507,6,0,'گر بدی گفت حسودی و رفیقی رنجید','هوش مصنوعی: اگر شخص حسود یا رفیق‌ات بدی بگوید و ناراحت شود، تو خوشحال باش و به حرف‌های احمق‌ها گوش نده.',NULL);
INSERT INTO "verses" VALUES(1932355,2505,3,0,'ارغنون ساز فلک ره‌زن اهل هنر است','هوش مصنوعی: آلت موسیقی وجود، به عنوان یک مداحی ناپسند برای هنرمندان عمل می‌کند. پس چرا از این درد و رنج شکایت نکنیم و چرا سر به سر این مشکلات نگذاریم؟',NULL);
INSERT INTO "verses" VALUES(1932356,2505,2,1,'نازنینی که به رویش مِی گل‌گون نوشیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932357,2505,2,0,'خوش هوایی‌ست فرح‌بخش خدایا بفرست','هوش مصنوعی: هوای دل‌انگیزی است که مایه شادی را فراهم می‌کند، ای خدا، نازنینی را بفرست که با چهره‌اش بتوانیم خوشی و شادابی را بچشیم.',NULL);
INSERT INTO "verses" VALUES(1932358,2505,1,1,'چاره آن است که سجاده به مِی بفروشیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932359,2505,1,0,'نیست در کس کرم و وقت طرب می‌گذرد','هوش مصنوعی: در میان مردم، کسی نیست که با نیکی و محبت رفتار کند و در زمان خوشی، باید چاره‌ای اندیشید که سجاده‌امان را به شراب بفروشیم.',NULL);
INSERT INTO "verses" VALUES(1932360,2505,0,1,'سخن اهل دل است این و به جان بنیوشیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932361,2505,0,0,'دوستان وقت گل آن به که به عشرت کوشیم','هوش مصنوعی: در زمان شکوفایی و خوش‌گذرانی، بهتر است که از زندگی لذت ببریم. این پیام کسانی است که به عمق احساسات و دل‌های پاک توجه دارند.',NULL);
INSERT INTO "verses" VALUES(1932362,2504,7,1,'پای از گلیم خویش چرا بیشتر کشیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932363,2504,7,0,'حافظ نه حد ماست چنین لاف‌ها زدن','هوش مصنوعی: حافظ نمی‌گوید که ما در چه سطحی هستیم که بتوانیم این‌طور صحبت کنیم. چرا باید از اندازه خود فراتر برویم و خود را در معرض مشکلات بیشتری قرار دهیم؟',NULL);
INSERT INTO "verses" VALUES(1932364,2504,6,1,'گوی سپهر در خم چوگان زر کشیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932365,2504,6,0,'کو جلوه‌ای ز ابروی او تا چو ماه نو','هوش مصنوعی: یک زیبایی از ابروی او را نشان بده، تا مانند ماه نو، ستاره‌ها را در کمان زرینی که داریم بکشیم.',NULL);
INSERT INTO "verses" VALUES(1932366,2504,5,1,'مستانه‌اش نقاب ز رخسار برکشیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932367,2504,5,0,'سر خدا که در تتق غیب منزویست','هوش مصنوعی: خداوندی که در عوالم پنهان و دور از دسترس است، ما با شوق و عشق، نقاب از چهره‌اش برمی‌داریم.',NULL);
INSERT INTO "verses" VALUES(1932368,2504,4,1,'روزی که رخت جان به جهانی دگر کشیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932369,2504,4,0,'عشرت کنیم ور نه به حسرت کشندمان','هوش مصنوعی: بیا خوش بگذرانیم، وگرنه در روزی که جانمان را از این دنیا می‌بریم، حسرت بر دلمان می‌ماند.',NULL);
INSERT INTO "verses" VALUES(1932370,2504,3,1,'غارت کنیم باده و شاهد به بر کشیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932371,2504,3,0,'بیرون جهیم سرخوش و از بزم صوفیان','هوش مصنوعی: ما با خوشحالی از میهمانی صوفیان خارج می‌شویم و شراب و محبوب خود را به سینه می‌چسبانیم.',NULL);
INSERT INTO "verses" VALUES(1932372,2504,2,1,'غلمان ز روضه حور ز جنت به درکشیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932373,2504,2,0,'فردا اگر نه روضه رضوان به ما دهند','هوش مصنوعی: اگر فردا ما را به بهشت نبرند، از زیبایی‌های دنیای دیگر، جوانان خوش‌صورت را خواهیم گرفت و از نعمت‌های آنجا بهره‌مند خواهیم شد.',NULL);
INSERT INTO "verses" VALUES(1932374,2504,1,1,'دلق ریا به آب خرابات برکشیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932375,2504,1,0,'نذر و فتوح صومعه در وجه می نهیم','هوش مصنوعی: ما نذری و برکات صومعه را برای می‌نوشی قرار می‌دهیم و لباس ریا را در آب خرابات می‌شوییم.',NULL);
INSERT INTO "verses" VALUES(1932376,2504,0,1,'وین نقش زرق را خط بطلان به سر کشیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932377,2504,0,0,'صوفی بیا که خرقه سالوس برکشیم','هوش مصنوعی: عاشقانه به دیدار صوفی دعوت می‌کنیم تا لباس ریا و ظاهرسازی را کنار بگذاریم و برچسب تقلب و نادرستی را بر این دنیا بزنیم.',NULL);
INSERT INTO "verses" VALUES(1932378,2503,7,1,'بیا حافظ که تا خود را، به مُلکی دیگر اندازیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932379,2503,7,0,'سخن‌دانی و خوش‌خوانی نمی‌ورزند در شیراز','ای حافظ، در شیراز مردمان معنای سخنان نغز و خوش‌آواز را درک نمی‌کنند؛ بیا تا رخت خود را به سرزمینی دیگر ببریم.',NULL);
INSERT INTO "verses" VALUES(1932380,2503,6,1,'که از پای خُمَت روزی، به حوضِ کوثر اندازیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932381,2503,6,0,'بهشت عَدْن اگر خواهی، بیا با ما به میخانه','اگر بهشت جاویدان می‌طلبی با ما به میکده بیا تا تو را به یک‌باره از پای ظرف شراب به حوض کوثر در بهشت برسانیم.',NULL);
INSERT INTO "verses" VALUES(1932382,2503,5,1,'بیا کاین داوری‌ها را به پیشِ داور اندازیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932383,2503,5,0,'یکی از عقل می‌لافد، یکی طامات می‌بافد','یکی از داشتن عقل لاف زده، به خود می‌بالد و دیگری با ادعای داشتن کرامات گزافه‌گویی می‌کند؛ بیا تا قضاوت این دعوا‌ها را به قاضی عادل جهان یعنی خداوند واگذار کنیم.',NULL);
INSERT INTO "verses" VALUES(1932384,2505,3,1,'چون از این غصه ننالیم و چرا نخروشیم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1932385,2505,4,0,'گل به جوش آمد و از مِی نزدیمش آبی','هوش مصنوعی: گل به شوقی رسید و ما از شراب به او آبی ندادیم، بنابراین از آتش حسرت و آرزو به جوش و خروش آمده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932386,2505,4,1,'لاجرم زآتش حرمان و هوس می‌جوشیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932387,2505,5,0,'می‌کشیم از قدح لاله شرابی موهوم','هوش مصنوعی: ما از پیاله‌ای که انگار پر از شراب لاله است می‌نوشیم، تا چشم بد را دور کنیم و بدون موسیقی و شراب مست هستیم.',NULL);
INSERT INTO "verses" VALUES(1932388,2507,6,1,'گو «تو خوش باش که ما گوش به احمق نکنیم»',NULL,NULL);
INSERT INTO "verses" VALUES(1932389,2507,5,0,'آسمان کشتی ارباب هنر می‌شکند','هوش مصنوعی: آسمان احساسات و ایده‌های هنری را خراب می‌کند، بنابراین نباید اتکای خود را به این دنیای بی‌ثبات و ناپایدار بگذاریم.',NULL);
INSERT INTO "verses" VALUES(1932390,2507,5,1,'تکیه آن به که بر این بحر معلّق نکنیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932391,2507,4,0,'خوش برانیم جهان در نظر راهروان','در برابر مسافران و سالکان دنیا، به خوشی بر جهان که همچون اسبی است سواری کنیم ولی به تجملاتی همچون سیاه بودن اسب یا آراستگی زین بی اهمیت باشیم.',NULL);
INSERT INTO "verses" VALUES(1932392,2507,4,1,'فکر اسب سیه و زین مغرّق نکنیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932393,2507,3,0,'شاه اگر جرعهٔ رندان نه به حرمت نوشد','هوش مصنوعی: اگر شاه فقط به خاطر احترام به رندها یک جرعه بنوشد، ما نباید به می صاف و زینتی او توجه کنیم.',NULL);
INSERT INTO "verses" VALUES(1932394,2507,3,1,'التفاتش به می صاف مروّق نکنیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932395,2507,2,0,'رقم مغلطه بر دفتر دانش نزنیم','هوش مصنوعی: در کار علم و دانش، نباید به تقلب و فریبکاری پرداخته و حقایق را به روش‌های غیرصادقانه تحریف کنیم.',NULL);
INSERT INTO "verses" VALUES(1932396,2507,2,1,'سر حق بر ورق شعبده ملحق نکنیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932397,2507,1,0,'عیب درویش و توانگر به کم و بیش بد است','هوش مصنوعی: عیب و نقص در فقیر و ثروتمند باید به اندازه و نوع خود مورد بررسی قرار گیرد و نمی‌توان به طور کلی و مطلق قضاوت کرد. در واقع، باید با دقت و ملاحظه به شرایط و ویژگی‌های هر فرد نگاه کرد و از مطلق‌نگری خودداری کرد.',NULL);
INSERT INTO "verses" VALUES(1932398,2507,1,1,'کار بد مصلحت آن است که مطلق نکنیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932399,2507,0,0,'ما نگوییم بد و میل به ناحق نکنیم','ما نباید درباره دیگران بد بگوییم و نباید به سمت بی عدالتی جدب شویم. همچنین نباید لباس کسی را سیاه کنیم منظور نابود کردن دیگران که باعث شود خویشاوندان طرف سیاه پوش شوند بخاطر پر کردن جیب خود از دارایی‌های دنیوی',NULL);
INSERT INTO "verses" VALUES(1932400,2507,0,1,'جامهٔ کس سیه و دلق خود ازرق نکنیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932401,2506,6,1,'تا به قول و غزلش ساز نوایی بکنیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932402,2507,7,1,'ور به حق گفت، جدل با سخن حق نکنیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932403,2506,6,0,'دلم از پرده بشد حافظ خوش‌گوی کجاست','هوش مصنوعی: دل من از حجاب و پرده آزاد شده است. حافظ خوش‌زبان کجاست تا ما هم به خاطر اشعار و عاطفه‌اش نوا و آوایی سر بدهیم؟',NULL);
INSERT INTO "verses" VALUES(1932404,2506,5,0,'سایهٔ طایر کم حوصله کاری نکند','هوش مصنوعی: پرنده‌ای که صبوری ندارد، سایه‌اش را نمی‌توانیم طولانی کنیم؛ اما اگر خواسته‌ای داریم، باید به سایهٔ میمونِ هم‌پروازیمان توجه کنیم.',NULL);
INSERT INTO "verses" VALUES(1932405,2506,4,1,'کار صعب است مبادا که خطایی بکنیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932406,2506,4,0,'مدد از خاطر رندان طلب ای دل ور نه','هوش مصنوعی: ای دل، از یاد رندان کمک بگیر، وگرنه کار سختی در پیش است و مبادا اشتباهی انجام دهیم.',NULL);
INSERT INTO "verses" VALUES(1932407,2506,3,1,'تا در آن آب و هوا نشو و نمایی بکنیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932408,2506,3,0,'خشک شد بیخ طرب راه خرابات کجاست','هوش مصنوعی: محل شادی و خوشگذرانی خشک شده است، کجاست جایی که بتوانیم در آنجا زندگی کنیم و خوشحال باشیم؟',NULL);
INSERT INTO "verses" VALUES(1932409,2506,2,1,'بازش آرید خدا را که صفایی بکنیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932410,2506,2,0,'آن که بی‌جرم برنجید و به تیغم زد و رفت','هوش مصنوعی: کسی که بدون هیچ دلیلی ناراحت شد و به ما آسیب زد و رفت، او را دوباره بیاورید تا ما بتوانیم دل‌جویی کنیم و آشتی کنیم.',NULL);
INSERT INTO "verses" VALUES(1932411,2506,1,1,'تا طبیبش به سر آریم و دوایی بکنیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932412,2506,1,0,'دلِ بیمار شد از دست، رفیقان مددی','دل بیمارم (بیماری این دل، عشق است) از دستم برفت. رفقا مدد کنید تا طبیبش (معشوق) را بر سرش حاضر کنیم و درمانش کنیم.',NULL);
INSERT INTO "verses" VALUES(1932413,2506,0,1,'غم هجران تو را چاره ز جایی بکنیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932414,2506,0,0,'ما شبی دست برآریم و دعایی بکنیم','هوش مصنوعی: در شبی دست به دعا بلند می‌کنیم و از دل دردمندانه‌ام برای رفع غم دوری تو طلب یاری می‌کنیم.',NULL);
INSERT INTO "verses" VALUES(1932415,2505,6,1,'بلبلانیم که در مُوسم گل خاموشیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932416,2505,6,0,'حافظ این حال عجب با که توان گفت که ما','هوش مصنوعی: حافظ در اینجا به حالتی اشاره دارد که ما به عنوان بلبلان در موسم گل، به جای شوق و سر و صدا، خاموشی اختیار کرده‌ایم. این نشان‌دهنده‌ی نوعی راز و عمیق‌تر از احساسات درونی است که نمی‌توان به سادگی بیان کرد.',NULL);
INSERT INTO "verses" VALUES(1932417,2505,5,1,'چشم بد دور که بی‌مطرب و مِی مدهوشیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932418,2506,5,1,'طلب از سایهٔ میمون همایی بکنیم',NULL,NULL);
INSERT INTO "verses" VALUES(1932419,2495,6,1,'از پِیِ قافله با آتشِ آه آمده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932420,2495,6,0,'حافظ این خرقهٔ پشمینه بینداز که ما','هوش مصنوعی: حافظ، این لباس پشمی را کنار بگذار، چون ما با قلبی آتشین و از مسیر قافله در جستجوی عشق و حقیقت آمده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932421,2495,5,1,'که به دیوانِ عمل نامه‌سیاه آمده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932422,2486,3,0,'سوزِ دل، اشکِ روان، آهِ سحر، نالهٔ شب','هوش مصنوعی: عذاب دل، اشک‌های جاری، آه‌های صبحگاهی و ناله‌های شب همه در اثر مهربانی‌های شماست که می‌بینم.',NULL);
INSERT INTO "verses" VALUES(1932423,2486,2,1,'فکرِ دور است همانا که خطا می‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932424,2486,2,0,'خواهم از زلفِ بُتان نافه‌گشایی کردن','هوش مصنوعی: من می‌خواهم از زیبایی محبوبان پرده‌برداری کنم، اما این فکر دور از دسترس است چون می‌دانم که دچار اشتباه می‌شوم.',NULL);
INSERT INTO "verses" VALUES(1932425,2486,1,1,'خانه می‌بینی و من خانه‌ خدا می‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932426,2486,1,0,'جلوه بر من مفروش ای مَلِکُ‌الْحاج که تو','هوش مصنوعی: ای سرور حاجی، خود را به من نشان نده و نیا، زیرا تو فقط خانه‌های معمولی را می‌بینی، اما من خانه خدا را مشاهده می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1932427,2486,0,1,'این عجب بین که چه نوری ز کجا می‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932428,2486,0,0,'در خراباتِ مُغان نورِ خدا می‌بینم','من در پرستشگاه زرتشتیان نور خدا را می بینم و بسیار برایم شگفت‌انگیز است که این نور از کجا می آید؟',NULL);
INSERT INTO "verses" VALUES(1932429,2485,8,1,'که با جام و قَدَح هر دَم ندیمِ ماه و پروینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932430,2485,8,0,'رموزِ مستی و رندی ز من بشنو نه از واعظ','رموز و اسرار مستی و رندی را از من بشنو نه از واعظ و شیخ؛ زیرا که هردَم‌، جام باده به‌دست‌، هم‌نشین ماه و پروین هستم.',NULL);
INSERT INTO "verses" VALUES(1932431,2485,7,1,'غلامِ آصفِ ثانی جلالُ الحقِ و الدینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932432,2485,7,0,'وفاداری و حق گویی نه کارِ هر کسی باشد','وفاداری و راستگویی کار هرکسی نیست؛ بنده آصفِ ثانی جلالُ الحقِ و الدینم',NULL);
INSERT INTO "verses" VALUES(1932433,2485,6,1,'که مانی نسخه می‌خواهد ز نوکِ کِلکِ مُشکینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932434,2485,6,0,'اگر باور نمی‌داری، رو از صورتگرِ چین پُرس','اگر باور نمی‌کنی که در نقش و نقاشی همچون مانی هنرمندم، برو از صورتگران و نقاشان زُبده چین بپرس.',NULL);
INSERT INTO "verses" VALUES(1932435,2485,5,1,'تَذَروِ طُرفه من گیرم که چالاک است شاهینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932436,2485,5,0,'نه هر کو نقشِ نظمی زد کلامش دلپذیر افتد','نه هرکس که نظمی سرود کلامش دلپذیر و دلنشین شد؛ تذرو عالی و شگرف را من شکار می‌کنم که شاهینی تیزپرواز هستم. (تذرو نام پرنده‌ای است)',NULL);
INSERT INTO "verses" VALUES(1932437,2485,4,1,'ز حالِ بنده یاد آور که خدمتگارِ دیرینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932438,2485,4,0,'چو هر خاکی که باد آورد، فیضی بُرد از اِنعامت','وقتی‌که هر کمتر خاکی از تو فیض و بهره‌ای بُرد؛ از من نیز یادی کن که خدمتکار و ارادتمند دیرین هستم.',NULL);
INSERT INTO "verses" VALUES(1932439,2485,3,1,'منم کز غایتِ حِرمان نه با آنم نه با اینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932440,2485,3,0,'لبت شِکَّر به مستان داد و چَشمت مِی به مِیخواران','لب تو نُقل و شیرینی به مستان داد و چشمت باده به می‌خواران؛ منم که از نهایت بی‌بهرگی و ناامیدی نه به آن می‌رسم نه به این.',NULL);
INSERT INTO "verses" VALUES(1932441,2485,2,1,'سخن با ماه می‌گویم، پَری در خواب می‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932442,2485,2,0,'مگر دیوانه خواهم شد در این سودا که شب تا روز','شاید از این سودا و خیال دیوانه‌شوم زیرا شب و روز با ماه هم‌سخن هستم و فرشته در خواب می‌بینم!',NULL);
INSERT INTO "verses" VALUES(1932443,2485,1,1,'لبم بر لب نِه ای ساقی و بِستان جانِ شیرینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932444,2485,1,0,'شرابِ تلخِ صوفی سوز، بنیادم بخواهد برد','شراب تلخ دین‌بر‌باد‌ده، بنیادم را خواهد بُرد؛ لب را بر لبم بنه ای ساقی و جانم را بستان.',NULL);
INSERT INTO "verses" VALUES(1932445,2485,0,1,'ز جامِ وصل مِی‌ نوشم، ز باغِ عیش گل چینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932446,2485,0,0,'گَرَم از دست برخیزد که با دلدار بنشینم','اگر روزی از دستم برآید و بتوانم که با یار بنشینم؛ مست وصالش می‌شوم و از گلزار زیبای لذت، گُل خواهم چید.',NULL);
INSERT INTO "verses" VALUES(1932447,2484,8,1,'که مکدر شود آیینه مهرآیینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932448,2484,8,0,'بر دلم گرد ستم‌هاست خدایا مپسند','هوش مصنوعی: خدایا، بر دل من مشکلات و ظلم‌ها سایه افکنده است، نگذار که این مسائل باعث شود محبت و دوستی‌ام تحت‌تأثیر قرار گیرد و دلم آزرده شود.',NULL);
INSERT INTO "verses" VALUES(1932449,2484,7,1,'که اگر دَم زَنَم از چرخ بخواهد کینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932450,2484,7,0,'بندهٔ آصفِ عهدم دلم از راه مَبَر','هوش مصنوعی: من تابع و پیرو آصف (وزیر سلیمان) هستم، پس دلم را از راه مبر، چون اگر کاری کنم که از چرخ گردون بخواهم انتقام بگیرم.',NULL);
INSERT INTO "verses" VALUES(1932451,2486,3,1,'این همه از نظرِ لطفِ شما می‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932452,2486,4,0,'هر دَم از رویِ تو نقشی زَنَدَم راهِ خیال','هوش مصنوعی: هر لحظه از زیبایی تو تصویری ایجاد می‌کنم و در خیال خود با چه کسی صحبت کنم که بگویم در این پرده‌ی خیال چه چیزهایی می‌بینم؟',NULL);
INSERT INTO "verses" VALUES(1932453,2486,4,1,'با که گویم که در این پرده چه‌ها می‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932454,2486,5,0,'کس ندیده‌ست ز مُشکِ خُتَن و نافهٔ چین','هوش مصنوعی: هیچ‌کس آنچه را که من هر صبح ز باد نرم صبا مشاهده می‌کنم، از عطر مشک ختن و نافه چین ندیده است.',NULL);
INSERT INTO "verses" VALUES(1932455,2488,4,0,'در رهِ او چو قلم گر به سرم باید رفت','اگر در راه معشوق یا حق قرار است سر و جانم قربانی شود مثل قلم که روی کاغذ می‌رود و نقش می‌زند اما خود را فدا میکند، من هم آماده‌ام که مسیر را طی کنم با دلی پر از درد و زخم و چشمی اشکبار',NULL);
INSERT INTO "verses" VALUES(1932456,2488,3,0,'چون صبا با تنِ بیمار و دلِ بی‌طاقت','هوش مصنوعی: هنگامی که نسیم بهاری با جسمی ناتوان و دلِ بی‌قرار به سمت آن سرو خوش‌حرکت بروم.',NULL);
INSERT INTO "verses" VALUES(1932457,2488,3,1,'به هواداریِ آن سروِ خُرامان بروم',NULL,NULL);
INSERT INTO "verses" VALUES(1932458,2488,2,0,'دلم از وحشتِ زندانِ سِکَندَر بگِرفت','دلم از این دنیا گرفته است می خواهم بارم را ببندم از این دنیا به آن دنیا سفر کنم',NULL);
INSERT INTO "verses" VALUES(1932459,2488,2,1,'رخت بربندم و تا مُلکِ سلیمان بروم',NULL,NULL);
INSERT INTO "verses" VALUES(1932460,2488,1,0,'گر چه دانم که به جایی نَبَرد راه غریب','هر چند می‌دانم که در راه ناشناخته مقصدی مشخص نیست، من به دنبال نشانه خوشایند و دلربای معشوق میروم',NULL);
INSERT INTO "verses" VALUES(1932461,2488,1,1,'من به بویِ سرِ آن زلفِ پریشان بروم',NULL,NULL);
INSERT INTO "verses" VALUES(1932462,2488,0,0,'خُرَّم آن روز کز این منزلِ ویران بروم','خوشا روزی که این دنیای وانفسا را ترک کنم، جانم آسوده شود و به سوی معبودم بروم',NULL);
INSERT INTO "verses" VALUES(1932463,2488,0,1,'راحتِ جان طلبم و از پِیِ جانان بروم',NULL,NULL);
INSERT INTO "verses" VALUES(1932464,2487,8,1,'بضاعت سخن دُرفشان نمی‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932465,2487,8,0,'من و سفینهٔ حافظ که جز در این دریا','هوش مصنوعی: من و کشتی حافظ هرگز در این دریا چیزی از زیبایی‌های گفتاری نمی‌بینیم جز این گنجینه‌ها.',NULL);
INSERT INTO "verses" VALUES(1932466,2487,7,1,'ز من مَپرس که خود در میان نمی‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932467,2487,7,0,'نشانِ مویِ میانش که دل در او بستم','موی میان استعاره از کمر باریک یار داره که از باریکی چون مو می‌باشد ، و آنچنان دلبسته‌ی آن شدم که دیگر خود را نمیبینم',NULL);
INSERT INTO "verses" VALUES(1932468,2487,6,1,'ببین که اهل دلی در میان نمی‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932469,2484,6,1,'این مَتاعم که همی‌بینی و کمتر زینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932470,2487,6,0,'در این خُمار کَسَم جرعه‌ای نمی‌بخشد','هوش مصنوعی: در حالتی که در آن هستم، هیچ‌کس به من نخواهد داد. نگاه کن، که اهل دل و عاشقانی را در اطراف خود نمی‌بینم.',NULL);
INSERT INTO "verses" VALUES(1932471,2487,5,0,'قدِ تو تا بِشُد از جویبارِ دیدهٔ من','هوش مصنوعی: وقتی قد تو از جویبار اشک من گذشت، تنها تصویری که به جای سرو می‌بینم، آب روان است.',NULL);
INSERT INTO "verses" VALUES(1932472,2487,4,1,'که با دو آینه رویش عیان نمی‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932473,2487,4,0,'بدین دو دیدهٔ حیران من هزار افسوس','هوش مصنوعی: با این دو چشمانی که حیرت زده‌اند، خیلی افسوس می‌خورم که نمی‌توانم چهره‌اش را به وضوح در آینه‌ها ببینم.',NULL);
INSERT INTO "verses" VALUES(1932474,2487,3,1,'که در مشایخِ شهر این نشان نمی‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932475,2487,3,0,'نشانِ اهل خدا عاشقیست، با خود دار','هوش مصنوعی: نشان عشق و دلدادگی واقعی، مخصوص اهل خداست. باید توجه داشته باشی که در میان عالمان و بزرگان این شهر، این نشانه را پیدا نمی‌کنم.',NULL);
INSERT INTO "verses" VALUES(1932476,2487,2,1,'چرا که طالعِ وقت آن چُنان نمی‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932477,2487,2,0,'ز آفتابِ قَدَح ارتفاعِ عیش بگیر','هوش مصنوعی: از نور آفتابِ جام شادی بهره‌ بگیر، زیرا آینده را آن‌طور که باید نمی‌بینم.',NULL);
INSERT INTO "verses" VALUES(1932478,2487,1,1,'چرا که مصلحتِ خود در آن نمی‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932479,2487,1,0,'به تَرک خدمتِ پیرِ مُغان نخواهم گفت','هوش مصنوعی: من به پیر مغان نخواهم گفت چرا که فکر می‌کنم در آن سودی برای خودم نیست.',NULL);
INSERT INTO "verses" VALUES(1932480,2487,0,1,'دَواش جز مِیِ چون ارغوان نمی‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932481,2487,0,0,'غمِ زمانه که هیچش کَران نمی‌بینم',':غم و اندوه روزگار انتها ندارد دوای آن جز نوشیدن می، مانند رنگ ارغوانی نیست',NULL);
INSERT INTO "verses" VALUES(1932482,2486,6,1,'که من او را ز مُحِبّانِ شما می‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932483,2486,6,0,'دوستان عیبِ نظربازیِ حافظ مکنید','هوش مصنوعی: دوستان، لطفاً درباره‌ی علاقه‌ی حافظ به عشق و زیبایی قضاوت نکنید، چون من او را از دوستداران شما می‌شناسم.',NULL);
INSERT INTO "verses" VALUES(1932484,2486,5,1,'آنچه من هر سَحَر از بادِ صبا می‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932485,2487,5,1,'به جایِ سرو جز آبِ روان نمی‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932486,2488,4,1,'با دلِ زخم‌کَش و دیدهٔ گریان بروم',NULL,NULL);
INSERT INTO "verses" VALUES(1932487,2484,6,0,'من اگر رندِ خراباتم و گر زاهدِ شهر','هوش مصنوعی: من اگر شخصی اهل خوش‌گذرانیم و اگر هم زاهد و پارسا در این شهر باشم، این موجودیتی که می‌بینی، کمتر از آنی است که به نظر می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1932488,2484,5,0,'سینهٔ تَنگِ من و بارِ غمِ او، هیهات','هوش مصنوعی: دل من از شدت ناراحتی و وزن اندوه او بسیار گرفتار و تنگ شده است. من توانایی تحمل این بار سنگین را ندارم و این برایم بسیار دشوار است.',NULL);
INSERT INTO "verses" VALUES(1932489,2482,0,0,'من تَرکِ عشقِ شاهد و ساغر نمی‌کنم','مـن از عشق ومحبّت، ازدوستی و مهرورزی، ازعیش وعشرت وشادمانی، ازشاهدبازی ونظربازی، ازشادزیستن و شادکردن دلها، از پایکوبی و دست‌افشانی، دست بر نمی‌دارم. صـدبـارپ یش ازاین به توصیه‌ی نصیحتگوی، از شرابخواری و عاشقی تـوبه کرده‌ام ونتیجه ی بَدگرفته‌ام یعنی خود را بیهوده ازشادکامی و محبت و عشقبازی محروم کردم. توبه‌ها جزپشیمانی حاصلی نداشته به این نتیجه رسیدم که دیگر توبه نکنم.«از حاشیه»',NULL);
INSERT INTO "verses" VALUES(1932490,2482,0,1,'صد بار توبه کردم و دیگر نمی‌کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932491,2482,1,0,'باغِ بهشت و سایهٔ طوبی و قصر و حور','هوش مصنوعی: من بهشت، درخت طوبی، کاخ‌ها و زیبایی‌های آن世界 را با خاک جای دوست‌ام عوض نمی‌کنم.',NULL);
INSERT INTO "verses" VALUES(1932492,2482,1,1,'با خاکِ کوی دوست برابر نمی‌کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932493,2482,2,0,'تلقین و درسِ اهل نظر یک اشارت است','هوش مصنوعی: آموختن و مطالعه نظرها و اندیشه‌های اهل علم، فقط یک نشانه است. من این مطلب را به صورت غیرمستقیم بیان کردم و تکرار نخواهم کرد.',NULL);
INSERT INTO "verses" VALUES(1932494,2482,2,1,'گفتم کِنایتی و مکرر نمی‌کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932495,2482,3,0,'هرگز نمی‌شود ز سرِ خود خبر مرا','هوش مصنوعی: هرگز نمی‌توانی از حال من آگاه شوی تا زمانی که خودم در میکده، موضوع را به تو نگویم.',NULL);
INSERT INTO "verses" VALUES(1932496,2482,3,1,'تا در میانِ میکده سر بَر نمی‌کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932497,2481,7,1,'بنگر این شوخی که چون با خلق، صنعت می‌کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932498,2481,7,0,'حافظم در مجلسی دُردی‌کشم در محفلی','هوش مصنوعی: حافظ می‌گوید که در جمعی مشغول نوشیدن هستم و در محفل دیگری نیز سرگرم بازیگری هستم. به این نکته دقت کن که چطور با مردم به شکلی هنرمندانه رفتار می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1932499,2481,6,1,'زین دلیری‌ها که من در کُنجِ خلوت می‌کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932500,2481,6,0,'دیدهٔ بدبین بپوشان ای کریمِ عیب‌پوش','هوش مصنوعی: ای بخشنده‌ای که عیوب را می‌پوشانی، چشمان بدبین را ببند، زیرا من در تنهایی خود کارهایی می‌کنم که نیاز به جرات دارد.',NULL);
INSERT INTO "verses" VALUES(1932501,2481,5,1,'یاد دار ای دل که چندینت نصیحت می‌کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932502,2481,5,0,'زلفِ دلبر دامِ راه و غمزه‌اش تیرِ بلاست','هوش مصنوعی: موی معشوقه‌ام مثل دام و فریب است و نگاه‌ او مانند تیر بلا می‌زند؛ ای دل، به یاد داشته باش که چندین بار به تو نصیحت می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1932503,2481,4,1,'لطف‌ها کردی بتا، تخفیفِ زحمت می‌کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932504,2481,4,0,'خاکِ کویت زحمت ما برنتابد بیش از این','هوش مصنوعی: خاک کوی تو دیگر بیشتر از این، زحمت ما را تحمل نمی‌کند. ای بت زیبا، تو لطف‌های زیادی به من کردی، پس من تلاش و زحمت خود را کمی کاهش می‌دهم.',NULL);
INSERT INTO "verses" VALUES(1932505,2481,3,1,'و از رفیقان ره استمدادِ همت می‌کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932506,2481,3,0,'با صبا افتان و خیزان می‌روم تا کویِ دوست','هوش مصنوعی: با نسیم، آرام و بی‌خبر از خستگی، به سوی خانه‌ی دوست می‌روم و از دوستانم کمک می‌طلبم تا در این مسیر همراهی‌ام کنند.',NULL);
INSERT INTO "verses" VALUES(1932507,2481,2,1,'در حضورش نیز می‌گویم نه غیبت می‌کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932508,2481,2,0,'واعظِ ما بوی حق نشنید بشنو کاین سخن','هوش مصنوعی: واعظ ما حقیقت را درک نکرده است، اما به تو می‌گویم که این حرف را در حضور او نیز می‌زنم و به کسی پشت سرش صحبت نمی‌کنم.',NULL);
INSERT INTO "verses" VALUES(1932509,2481,1,1,'در کمینم و انتظار وقتِ فرصت می‌کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932510,2481,1,0,'تا کی اندر دام وصل آرم تَذَروی خوش‌خَرام','هوش مصنوعی: چقدر طول می‌کشد که در دام عشق بمانم و کسی که خوش‌خیال و زیباست در کمین من نشسته است، و من در انتظار فرصتی هستم که با او روبه‌رو شوم؟',NULL);
INSERT INTO "verses" VALUES(1932511,2481,0,1,'در لباسِ فقر کارِ اهلِ دولت می‌کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932512,2481,0,0,'روزگاری شد که در میخانه خدمت می‌کنم','هوش مصنوعی: در این زمانه، من در میخانه مشغول خدمت به دیگران هستم و در حالی که در فقر به سر می‌برم، کارهایی را انجام می‌دهم که مخصوص افراد ثروتمند است.',NULL);
INSERT INTO "verses" VALUES(1932513,2480,6,1,'روزی رُخش ببینم و تسلیمِ وی کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932514,2480,6,0,'این جانِ عاریت که به حافظ سپرد دوست','هوش مصنوعی: عمر موقتی من که دوست به حافظ داده است، روزی زیبایی او را می‌بینم و در مقابلش تسلیم خواهم شد.',NULL);
INSERT INTO "verses" VALUES(1932515,2480,5,1,'با آن خجسته طالعِ فرخنده پِی کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932516,2480,5,0,'کو پیک صبح؟ تا گله‌های شبِ فِراق','هوش مصنوعی: کجاست پیام‌آور صبح؟ تا من با آن روز خوش و سرشار از نیکایی، غم و اندوهِ شب جدایی را پشت سر بگذارم.',NULL);
INSERT INTO "verses" VALUES(1932517,2480,4,1,'با فیضِ لطفِ او صد از این نامه طِی کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932518,2482,4,0,'ناصِح به طَعن گفت که «رو ترکِ عشق کن»','هوش مصنوعی: دوست ناصح به طعنه گفت که برو و از عشق فاصله بگیر، برادر، نیازی به جنگ و جدال نیست؛ اما من این کار را نمی‌کنم.',NULL);
INSERT INTO "verses" VALUES(1932519,2482,4,1,'محتاجِ جنگ نیست برادر، نمی‌کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932520,2482,5,0,'این تقوی‌ام تمام، که با شاهدانِ شهر','هوش مصنوعی: من این تقوا را تمام می‌دانم که به خاطر ناز و دلفریبی جذابیت‌های دیگران، در جمع مردم و در مکان‌های مهم، خودم را زیر سوال نبرم.',NULL);
INSERT INTO "verses" VALUES(1932521,2482,5,1,'ناز و کرشمه بر سرِ منبر نمی‌کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932522,2484,4,1,'شرمسار از رخِ ساقی و مِیِ رنگینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932523,2484,4,0,'بس که در خرقهٔ آلوده زدم لافِ صَلاح','هوش مصنوعی: به خاطر اینکه خیلی در لباس آلوده‌ام به فضل و نیکی صحبت کرده‌ام، از چهره‌ی ساقی و شراب رنگینم شرمنده‌ام.',NULL);
INSERT INTO "verses" VALUES(1932524,2484,3,1,'گر دهد دست که دامن ز جهان دَرچینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932525,2484,3,0,'سر به آزادگی از خَلق برآرم چون سَرو','هوش مصنوعی: من با سربلندی و آزادگی به‌گونه‌ای چون درخت سرو، به کسانی که به من کمک کنند، می‌گویم که اگر آن‌ها دست یاری به من بدهند، می‌توانم از دنیا و وابستگی‌های آن دست بکشم.',NULL);
INSERT INTO "verses" VALUES(1932526,2484,2,1,'تا حریفانِ دَغا را به جهان کم بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932527,2484,2,0,'جز صُراحی و کتابم نَبُوَد یار و ندیم','هوش مصنوعی: جز پیاله و کتاب، یار و همصحبتی ندارم تا اینکه در این دنیا کمکی به من در برابر کسانی که فریبکارند باشد.',NULL);
INSERT INTO "verses" VALUES(1932528,2484,1,1,'یعنی از اهلِ جهان پاکدلی بُگزینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932529,2484,1,0,'جامِ مِی گیرم و از اهلِ ریا دور شَوَم','هوش مصنوعی: من جام می‌نوشم و از مردم چهره‌نما و ریاکار فاصله می‌گیرم، یعنی افرادی را انتخاب می‌کنم که پاکدل و راستگو هستند.',NULL);
INSERT INTO "verses" VALUES(1932530,2484,0,1,'که کشم رَخت به میخانه و خوش بنشینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932531,2484,0,0,'حالیا مصلحتِ وقت در آن می‌بینم','هوش مصنوعی: الان احساس می‌کنم که بهتر است به میخانه بروم و لحظاتی را با خوشی بگذرانم.',NULL);
INSERT INTO "verses" VALUES(1932532,2483,8,1,'همانا بی‌غلط باشد، که حافظ داد تلقینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932533,2483,8,0,'حدیثِ آرزومندی که در این نامه ثبت افتاد','داستان شور و شوق وصال که در این نوشتار ثبت کرده­‌ام یقین بدانید که درست و بی­‌غلط است، چرا که حافظ(ایهام) آن را به من آموخته است.(ایهام: حافظ؛ ۱. شخص حافظ، ۲. نامی است از نام­‌های خداوند.)',NULL);
INSERT INTO "verses" VALUES(1932534,2483,7,1,'اگر در وقتِ جان دادن تو باشی شمعِ بالینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932535,2483,7,0,'شبِ رحلت هم از بستر رَوَم در قصرِ حورُالعین','اگر در وقت مرگ و در هنگام جان دادن تو روشنی‌­بخش بسترم باشی، همان شب مرگ یک‌­راست از بستر مرگ به قصر حوران بهشتی خواهم رفت.',NULL);
INSERT INTO "verses" VALUES(1932536,2484,5,1,'مردِ این بارِ گران نیست دلِ مسکینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932537,2483,6,1,'که غوغا می‌کند در سر خیالِ خوابِ دوشینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932538,2483,5,1,'حرامم باد اگر من جان، به جایِ دوست بُگزینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932539,2483,5,0,'اگر بر جایِ من غیری گزیند دوست، حاکم اوست','اگر محبوب به جای من کس دیگری را انتخاب کند، صاحب اختیار است و حق دارد، اما اگر من به جای عشق به محبوب، جان خودم را برگزینم، حرامم باد.',NULL);
INSERT INTO "verses" VALUES(1932540,2483,4,1,'که سلطانیِّ عالَم را طُفیلِ عشق می‌بینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932541,2483,4,0,'جهانِ فانی و باقی فدایِ شاهد و ساقی','هر دو عالم، هم فدای معشوق زیبارو و هم فدای ساقی باد؛ چرا که می­‌بینم رسیدن به سروریِ جهان، در گرو و وابسته به عشق است.',NULL);
INSERT INTO "verses" VALUES(1932542,2483,3,1,'بیار ای بادِ شبگیری نسیمی زان عرقچینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932543,2483,3,0,'ز تابِ آتش دوری، شدم غرقِ عرق چون گُل','دوری از یار چونان آتشی است که از شدت سوز و گداز آن همچون گل غرقِ عرق شده‌­ام، ای نسیم سحرگاهی بوی خوشی از آن زلف معطر یار بیاور.',NULL);
INSERT INTO "verses" VALUES(1932544,2483,2,1,'که کرد افسون و نیرنگش ملول از جانِ شیرینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932545,2483,2,0,'جهان پیر است و بی‌بنیاد از این فرهادکُش فریاد','دنیا هم کهن و سال­خورده است و هم بی‌­اساس و بی‌­بنیاد، فغان و فریاد که به راحتی عاشقان دلداده‌­­ای چون فرهاد را می‌­کُشد، این دنیا با حیله و نیرنگ­‌هایش چنان کاری کرده است که من حتی از جان شیرین خودم نیز دل­‌زده و خسته شده­‌ام.',NULL);
INSERT INTO "verses" VALUES(1932546,2483,1,1,'مرا روزی مباد آن دَم که بی یادِ تو بنشینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932547,2483,1,0,'الا ای همنشینِ دل که یارانت بِرَفت از یاد','ای همدم دل و جانم که یاران و عاشقانت را فراموش کرده­‌ای، امیدوارم آن روزی که لحظه‌­ای از یادت غافل شوم هرگز نیاید.',NULL);
INSERT INTO "verses" VALUES(1932548,2483,0,1,'بیا کز چَشمِ بیمارت هزاران دَرد برچینم',NULL,NULL);
INSERT INTO "verses" VALUES(1932549,2483,0,0,'به مژگان سیَه کردی هزاران رِخنه در دینم','با مژه­های سیاه رنگ خود، دین و ایمانم را ویران ساختی، به پیشم بیا تا هزاران درد و بلا را از چشمان خمارت دور سازم.',NULL);
INSERT INTO "verses" VALUES(1932550,2482,6,0,'حافظ! جنابِ پیرِ مُغان جایِ دولت است','هوش مصنوعی: حافظ می‌گوید که در کنار پیر مغان، که نماد سرپرستی و هدایت است، فضایی برای دستیابی به نعمت و برکت وجود دارد. او با ابراز عشق و ارادت به این مکان، تأکید می‌کند که هرگز از با خاک در افتادن و احترام به این درگاه دست نخواهد کشید.',NULL);
INSERT INTO "verses" VALUES(1932551,2482,6,1,'من تَرکِ خاک‌بوسیِ این در نمی‌کنم',NULL,NULL);
INSERT INTO "verses" VALUES(1932552,2483,6,0,'صَباحَ الخیر زد بلبل، کجایی ساقیا؟ برخیز','بلبل، صبح به خیر را به زبان نغمه‌­خوانی سرود، ای ساقی، کجایی؟ برخیز (جام شرابی بیاور) که تصویر و خیالی که دیشب در خواب دیده‌­ام، در سرم غوغا به پا کرده است.',NULL);
INSERT INTO "verses" VALUES(1932553,2450,0,1,'هر گَه که یادِ رویِ تو کردم جوان شدم',NULL,NULL);
INSERT INTO "verses" VALUES(1932554,2488,5,0,'نذر کردم گر از این غم به درآیم روزی','هوش مصنوعی: من نذر کرده‌ام که اگر روزی از این اندوه رهایی یابم، با شادی و سرور به میکده رفته و شعر خوانی کنم.',NULL);
INSERT INTO "verses" VALUES(1932555,2488,5,1,'تا درِ میکده شادان و غزل‌خوان بروم',NULL,NULL);
INSERT INTO "verses" VALUES(1932556,2493,4,0,'کار از تو می‌رود، مددی ای دلیلِ راه','ای راهنما وراه بَلد اعتراف و اقرار می‌کنیم که ما گـمراه شده‌ایـم و کارمان گره خورده است! نجات و رستگاری ما فقط بازگشت بسوی تو و بسته به تـدبیر تو است ، به ما کمک کن تا راه درست را در پیش گیریم.',NULL);
INSERT INTO "verses" VALUES(1932557,2493,3,1,'گو باده صاف کن که به عذر ایستاده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932558,2493,3,0,'پیرِ مُغان ز توبهٔ ما گر ملول شد','اگر راهنما و سرور ما از توبه و ترکِ باده خواری مـا اندوهناک گردیده، از طرفِ ما به او بـگـو که ماهم از کرده ی خویش پشیمانیم! بنابراین شراب را صاف و آماده کـن که ما آماده‌ی ِ جبران و عـذر خواهی هستیم .',NULL);
INSERT INTO "verses" VALUES(1932559,2493,2,1,'ما آن شقایقیم که با داغ زاده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932560,2493,2,0,'ای گُل تو دوش داغِ صَبوحی کشیده‌ای','ای گل سرخ ، این‌گونه به سرخی خویش مَناز و جلوه گری مکن ، سُرخی تو از اثراتِ شراب ِ صبحگاهیست که خورده ای، تو هر روز صبح شراب می خوری و رُخسارت سرخ می شود. اگر یک روز شراب نخوری معلوم می شود که صورتت چه رنگی دارد.! سرخی صورت باید ذاتی و جاودانی باشد ، همانگونه که ما شقایق ها با سرخ رویی زاده می شوییم و داغی ِ صورت ما ذاتیست.',NULL);
INSERT INTO "verses" VALUES(1932561,2493,1,1,'تا کارِ خود ز ابرویِ جانان گشاده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932562,2493,1,0,'بر ما بسی کمانِ ملامت کشیده‌اند','ما سرزنش ها شنیده و نکوهش ها دیده ایم ما خون دلها خورده ایم از کمان ملامت ِ سایرین ، تیر طعنه بسیار بردلمان نشسته و آزار ها کشیده ایم تا اینکه در نهایت از ابروان ِیار اشاره ی رضایت دریافته ایم و مشکلمان مرتفع گردیده است. دراینجا روشن می شود که چرا حافظ و یارانش در بیتِ پیشین خوش بودند و هیچ غمی نداشتند!.',NULL);
INSERT INTO "verses" VALUES(1932563,2493,0,1,'هم‌رازِ عشق و هم‌نفسِ جامِ باده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932564,2493,0,0,'ما بی‌غمانِ مست دل از دست داده‌ایم','ما سرمست و بی غم و بی خبریم از دنیا و پیرامون خویش جز عشق چیزی نمی دانیم و نداریم. تمام وقت با عشق و جام باده سر و کار داریم با جام شراب و عشق خلوت می کنیم دردِ دل می کنیم و رفیق و هم صحبت هم هستـیـم .',NULL);
INSERT INTO "verses" VALUES(1932565,2492,8,1,'و آصفِ مُلکِ سلیمان نیز هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932566,2492,8,0,'محتسب داند که حافظ عاشق است','هوش مصنوعی: دستگاه قضاوت، مطمئن است که حافظ در عشق غرق است، و آصف که مقام و ثروت سلیمان را دارد نیز به همین حال است.',NULL);
INSERT INTO "verses" VALUES(1932567,2492,7,1,'بلکه از یَرغویِ دیوان نیز هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932568,2492,7,0,'عاشق از قاضی نترسد مِی بیار','ساقی، شراب بیاور که عاشق نه تنها از قاضی نمی‌ترسد بلکه از بازپرس محکمه هم باکی ندارد',NULL);
INSERT INTO "verses" VALUES(1932569,2492,6,1,'بلکه بر گردونِ گَردان نیز هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932570,2492,6,0,'اعتمادی نیست بر کارِ جهان','هوش مصنوعی: به زندگی و کارهای دنیا نمی‌توان اعتماد کرد، حتی به چرخش زمان نیز نمی‌توان اتکا کرد.',NULL);
INSERT INTO "verses" VALUES(1932571,2492,5,1,'گفتمت پیدا و پنهان نیز هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932572,2492,5,0,'هر دو عالم یک فروغِ رویِ اوست','هوش مصنوعی: هر دو جهان، روشنایی و جلوه‌ای از روی او هستند. به تو گفتم که این روشنایی هم در آشکار و هم در نهان وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1932573,2492,4,1,'بگذرد ایامِ هِجران نیز هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932574,2492,4,0,'چون سر آمد دولتِ شب‌هایِ وصل','هوش مصنوعی: وقتی دوره‌ی شب‌های وصال به پایان برسد، روزهای جدایی نیز به سر خواهد آمد.',NULL);
INSERT INTO "verses" VALUES(1932575,2492,3,1,'گفته خواهد شد به دَستان نیز هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932576,2492,3,0,'دوستان در پرده می‌گویم سخن','هوش مصنوعی: دوستان، در خفا و به آرامی صحبت می‌کنم، چون این سخن به گوش دیگران هم خواهد رسید.',NULL);
INSERT INTO "verses" VALUES(1932577,2492,2,1,'عهد را بشکست و پیمان نیز هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932578,2492,2,0,'یاد باد آن کاو به قصدِ خونِ ما','هوش مصنوعی: یاد آن کسی بخیر که به خاطر خون ما، عهد و پیمان را زیر پا گذاشت.',NULL);
INSERT INTO "verses" VALUES(1932579,2492,1,1,'یار ما این دارد و آن نیز هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932580,2492,1,0,'این که می‌گویند آن خوشتر ز حسن','هوش مصنوعی: آنچه گفته می‌شود که زیبایی معشوق ما از هر چیز دیگر بهتر است، در واقع این زیبایی ویژگی‌های خاص خودش را دارد و چیزهای دیگری نیز در آن وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1932581,2492,0,1,'دل فدایِ او شد و جان نیز هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932582,2492,0,0,'دَردَم از یار است و درمان نیز هم','هوش مصنوعی: درد من از طرف محبوبم است و در عین حال، درمان نیز به دست اوست. دل و جانم را به خاطر او فدای او کرده‌ام.',NULL);
INSERT INTO "verses" VALUES(1932583,2491,15,1,'و از ساقیانِ سَروقَدِ گُلعِذار هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932584,2491,15,0,'خالی مباد کاخِ جلالش ز سروران','هوش مصنوعی: کاخ باشکوه او نباید از حضور شادی‌آور و ساقیانی با قامت خوش‌چهره خالی باشد.',NULL);
INSERT INTO "verses" VALUES(1932585,2493,4,1,'کانصاف می‌دهیم و ز راه اوفتاده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932586,2493,5,0,'چون لاله، مِی مبین و قَدَح در میانِ کار','ظاهر بین مباش گرچه بنظر چنین می رسد که جام سرشار از شراب پیش رو دارم و روزگارم با نشاط و همه چیز وفق مراد است! نه من همانندِ لاله ظاهراً شاداب و چهره‌ی سرخ دارم. ما را با ظاهر لاله قیاس مکن و اگر مقایسه کردی ببین که همچون لاله داغی بر دل داریم . داغ فراق و داغ عشق است که ازاَزل بر دل مانهاده شده است.',NULL);
INSERT INTO "verses" VALUES(1932587,2493,5,1,'این داغ بین که بر دلِ خونین نهاده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932588,2493,6,0,'گفتی که «حافظ این همه رنگ و خیال چیست؟!»','خطاب به منتقدین ومخالفان است.ای که می گویی ای حافـظ تو با این زبان شعری خیال انگیز دست به ریا و فریبکاری می زنی و اعمالت با گفته هایت همخوانی ندارد. نه اینگونه که تومی پنداری نیست وما مثل ِ لوح بی رنگ هستیم. هیچ نقاب و ماسکی برصورت نمی زنم وآنچه که می گویم از سرچشمه ی باورها و اعتقاداتم برمی خیزد.',NULL);
INSERT INTO "verses" VALUES(1932589,2495,5,0,'آبرو می‌رود ای ابرِ خطاپوش ببار','هوش مصنوعی: ای ابرِ مهربان و پنهان‌کننده‌ی خطاها، ببار، زیرا ما به روز حساب رسیده‌ایم و اعمال‌مان در دفتر زندگی ثبت شده است.',NULL);
INSERT INTO "verses" VALUES(1932590,2495,4,1,'که در این بحرِ کَرَم غرقِ گناه آمده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932591,2495,4,0,'لنگرِ حِلمِ تو ای کشتیِ توفیق کجاست؟','هوش مصنوعی: کجاست نقطه‌ی اتکا و آرامش تو که کشتی موفقیت را به سوی مقصد برساند؟ ما در این دریاِ بزرگِ بخشش و رحمت، غرق گناهان خود شده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932592,2495,3,1,'به گدایی به درِ خانهٔ شاه آمده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932593,2495,3,0,'با چُنین گنج که شد خازنِ او روحِ امین','هوش مصنوعی: با چنین گنجی که روح امین، آن را نگهداری می‌کند، ما به درِ خانهٔ شاه آمده‌ایم تا از او درخواست کمک کنیم.',NULL);
INSERT INTO "verses" VALUES(1932594,2495,2,1,'به طلبکاریِ این مهرگیاه آمده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932595,2495,2,0,'سبزهٔ خطِّ تو دیدیم و زِ بُستانِ بهشت','دیدیم که خط ( مسیر ) و نیت تو ( خدا ) سبز است و خیر ، از باغ بهشت و بخاطر طلبی که از این گیاه مهر آفرین ( اشاره به گیاه هوم در اوستا ) داشتیم به این دنیا آمده ایم .',NULL);
INSERT INTO "verses" VALUES(1932596,2495,1,1,'تا به اقلیمِ وجود این همه راه آمده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932597,2495,1,0,'رهروِ منزلِ عشقیم و زِ سرحدِّ عَدَم','هوش مصنوعی: ما در سفر راه عشق هستیم و از مرز عدم تا سرزمین وجود، مسیری طولانی را پیموده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932598,2495,0,1,'از بد حادثه این جا به پناه آمده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932599,2495,0,0,'ما بدین در نه پِیِ حشمت و جاه آمده‌ایم','هوش مصنوعی: ما به این مکان نیامده‌ایم که به دنبال ثروت و مقام باشیم، بلکه از روی حوادث ناخوشایند به اینجا پناه آورده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932600,2494,8,1,'در حلقه‌هایِ آن خَمِ گیسو نهاده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932601,2494,8,0,'گفتی که حافظا دل سرگشته‌ات کجاست؟','هوش مصنوعی: تو پرسیدی که دل سرگشته‌ات کجاست؟ ما در پیچ و خم موهای تو آن را گذاشته‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932602,2494,7,1,'چَشمِ طلب بر آن خَمِ ابرو نهاده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932603,2491,14,1,'تبدیل ماه و سال و خزان و بهار هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932604,2494,7,0,'در گوشهٔ امید چو نَظّارگانِ ماه','هوش مصنوعی: در گوشه‌ای از امید، مانند ناظران ماه، چشمان خود را بر روی آن خم ابرو دوخته‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932605,2494,6,0,'بی زلفِ سرکشش سرِ سودایی از ملال','هوش مصنوعی: بدون وجود زلف‌های دلربایش، سر عاشق از اندوه مانند بنفشه‌ای خشکیده بر زانو نشسته است.',NULL);
INSERT INTO "verses" VALUES(1932606,2494,5,1,'بنیاد بر کرشمهٔ جادو نهاده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932607,2494,5,0,'تا سِحْرِ چَشم یار چه بازی کند که باز','هوش مصنوعی: چشمان معشوق چه جادویی دارند که ما دوباره بر اساس فریب و جاذبه آن‌ها بنیاد و اساس خود را ساخته‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932608,2494,4,1,'ما تختِ سلطنت نه به بازو نهاده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932609,2494,4,0,'ما مُلکِ عافیت نه به لشکر گرفته‌ایم','هوش مصنوعی: ما به زور و لشکر برای به دست آوردن راحتی و آسایش اقدام نکرده‌ایم و قدرت خود را نیز نه به کمک نیروی جسمی و بازو به دست آورده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932610,2494,3,1,'چشمی بدان دو گوشهٔ ابرو نهاده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932611,2494,3,0,'عمری گذشت تا به امیدِ اشارتی','هوش مصنوعی: سال‌ها گذشت و ما همچنان با امیدی به نشانه‌ای، به چشم‌هایتان که دو ابرو را قاب گرفته‌اند، نگاه کرده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932612,2494,2,1,'هم دل بدان دو سُنبلِ هندو نهاده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932613,2494,2,0,'هم جان بِدان دو نرگسِ جادو سپرده‌ایم','جان خود را به آن دو چشم جادویی و دل خود را به آن گیسوان سیاه سپرده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932614,2494,1,1,'در راهِ جام و ساقیِ مَه رو نهاده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932615,2494,1,0,'طاق و رواقِ مدرسه و قال و قیلِ عِلم','قال و قیل و تمام ارکان تعلیم و آموزش را در راه رسیدن به وصال معشوق خود، فدا کرده و کنار گذاشته‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932616,2494,0,1,'روی و ریایِ خَلق به یک سو نهاده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932617,2494,0,0,'عمریست تا به راهِ غَمَت رو نهاده‌ایم','هوش مصنوعی: سال‌هاست که در راه غم تو گام برمی‌داریم و ظاهر‌سازی و تظاهر به خوشحالی در برابر مردم را کنار گذاشته‌ایم.',NULL);
INSERT INTO "verses" VALUES(1932618,2493,6,1,'نقشِ غلط مَبین که همان لوحِ ساده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932619,2494,6,1,'همچون بنفشه بر سرِ زانو نهاده‌ایم',NULL,NULL);
INSERT INTO "verses" VALUES(1932620,2488,6,0,'به هواداری او ذَرِّه‌صفت، رقص‌کنان','هوش مصنوعی: با عشق و محبت او، چون ذره‌ای رقصان و شاداب، به سمت چشمه‌ی درخشان خورشید می‌روم.',NULL);
INSERT INTO "verses" VALUES(1932621,2491,14,0,'تا از نتیجه فلک و طور دور اوست','هوش مصنوعی: نتیجه‌گیری از تغییرات زمان و فصل‌ها، نشان‌دهنده‌ی دوری و بی‌توجهی به اراده‌ و خواست فلک است. این تغییرات، به‌نوعی مشهود و محسوس‌اند و بر روی زندگی انسان‌ها تأثیر می‌گذارند.',NULL);
INSERT INTO "verses" VALUES(1932622,2491,13,0,'عزمِ سَبُک عِنان تو در جنبش آورد','هوش مصنوعی: نیروی اراده و تصمیم تو، به اندازه‌ای قوی است که می‌تواند این مرکز ثابت و با ثبات را به حرکت درآورد.',NULL);
INSERT INTO "verses" VALUES(1932623,2490,4,1,'و اندر آن آینه از حُسنِ تو کرد آگاهم',NULL,NULL);
INSERT INTO "verses" VALUES(1932624,2490,4,0,'پیرِ میخانه سَحَر جامِ جهان‌بینم داد','هوش مصنوعی: پیرِ میخانه در صبح زود، به من جامی داد که جهان را به من نشان می‌دهد و در آن آینه، از زیبایی تو آگاه شدم.',NULL);
INSERT INTO "verses" VALUES(1932625,2490,3,1,'ترسم ای دوست که بادی بِبَرَد ناگاهم',NULL,NULL);
INSERT INTO "verses" VALUES(1932626,2490,3,0,'ذَرّهٔ خاکم و در کویِ توام جای خوش است','هوش مصنوعی: من تنها یک ذره خاک هستم و در کوی تو احساس آرامش و خوبی می‌کنم. اما از این می‌ترسم که ناگهانی بادی بیاید و مرا از این جا ببرد.',NULL);
INSERT INTO "verses" VALUES(1932627,2490,2,1,'آن مبادا که کُنَد دستِ طلب کوتاهم',NULL,NULL);
INSERT INTO "verses" VALUES(1932628,2490,2,0,'بسته‌ام در خَمِ گیسویِ تو امّیدِ دراز','هوش مصنوعی: من در پیچ و خم موهای تو گرفتار و امید به درازای زندگی‌ام را دارم، مبادا که درخواست من به نتیجه نرسد و دستم از طلب کوتاه بماند.',NULL);
INSERT INTO "verses" VALUES(1932629,2490,1,1,'بندهٔ معتقد و چاکرِ دولتخواهم',NULL,NULL);
INSERT INTO "verses" VALUES(1932630,2490,1,0,'من نه آنم که ز جورِ تو بِنالم، حاشا','هوش مصنوعی: من آن کسی نیستم که از ظلم تو شکایت کنم، هرگز نمی‌کنم؛ من فردی هستم که به خدمتی و وفاداری به تو اعتقاد دارم و خود را به تو می‌سپارم.',NULL);
INSERT INTO "verses" VALUES(1932631,2490,0,1,'خاک می‌بوسم و عُذرِ قَدَمَش می‌خواهم',NULL,NULL);
INSERT INTO "verses" VALUES(1932632,2490,0,0,'آن که پامالِ جفا کرد چو خاکِ راهم','هوش مصنوعی: کسی که مانند خاک راه من پایش را بر سرم گذاشت، من به او احترام می‌گذارم و از او به خاطر قدم‌هایش عذرخواهی می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1932633,2489,6,1,'سرخوش از میکده با دوست به کاشانه روم',NULL,NULL);
INSERT INTO "verses" VALUES(1932634,2489,6,0,'خُرَّم آن دَم که چو حافظ به تَوَلّای وزیر','چه لحظه‌ای خوش است زمانی که مانند حافظ، با حمایت وزیر، شاد و مست از میکده، همراه با یار به خانه بازگردم.',NULL);
INSERT INTO "verses" VALUES(1932635,2489,5,1,'سجدهٔ شُکر کنم و از پِیِ شُکرانه روم',NULL,NULL);
INSERT INTO "verses" VALUES(1932636,2489,5,0,'گر ببینم خمِ ابروی چو محرابش باز','هوش مصنوعی: اگر ابروی خمیده‌اش را مانند محراب ببینم، شکرگزاری‌ام را به جا می‌آورم و به دنبال شکرانه‌اش می‌روم.',NULL);
INSERT INTO "verses" VALUES(1932637,2489,4,1,'چند و چند از پِیِ کامِ دلِ دیوانه روم',NULL,NULL);
INSERT INTO "verses" VALUES(1932638,2489,4,0,'بعد از این دستِ من و زلفِ چو زنجیرِ نگار','هوش مصنوعی: بعد از این، من که دستم و زلف معشوق مانند زنجیر است، چند بار دیگر برای رسیدن به آرزوی دل دیوانه‌ام می‌روم.',NULL);
INSERT INTO "verses" VALUES(1932639,2489,3,1,'ناکَسَم گر به شکایت سویِ بیگانه روم',NULL,NULL);
INSERT INTO "verses" VALUES(1932640,2489,3,0,'آشنایانِ رَهِ عشق گَرَم خون بخورند','هوش مصنوعی: اگر کسانی که در مسیر عشق هستند، بر من سخت بگذرند و به من آسیب برسانند، من هم بی‌پروا به سمت بیگانگان نمی‌روم تا شکایت کنم.',NULL);
INSERT INTO "verses" VALUES(1932641,2489,2,1,'به درِ صَومَعَه با بَربَط و پیمانه روم',NULL,NULL);
INSERT INTO "verses" VALUES(1932642,2489,2,0,'تا بگویم که چه کشفم شد از این سیر و سلوک','هوش مصنوعی: می‌خواهم بگویم که در این سفر و مسیر معنوی چه چیزهایی برایم روشن شده است، به درب صومعه با موسیقی و جام شراب وارد می‌شوم.',NULL);
INSERT INTO "verses" VALUES(1932643,2489,1,1,'نَذر کردم که هم از راه به میخانه روم',NULL,NULL);
INSERT INTO "verses" VALUES(1932644,2489,1,0,'زین سفر گر به سلامت به وطن باز رَسَم','هوش مصنوعی: اگر از این سفر با سلامت به وطن برگردم، وعده داده‌ام که ابتدا از راه، به میخانه بروم.',NULL);
INSERT INTO "verses" VALUES(1932645,2489,0,1,'دگر آنجا که رَوَم عاقل و فرزانه رَوَم',NULL,NULL);
INSERT INTO "verses" VALUES(1932646,2489,0,0,'گر از این منزلِ ویران به سویِ خانه رَوَم','هوش مصنوعی: اگر از این خانه خراب به سوی خانه‌ای بروم، دیگر در جایی که می‌روم، عاقل و دانا خواهم بود.',NULL);
INSERT INTO "verses" VALUES(1932647,2488,8,0,'ور چو حافظ ز بیابان نبرم رَه بیرون','هوش مصنوعی: اگر نتوانم از بیابان راهی پیدا کنم، همانند حافظ، به همراه کوکبه‌ی آصف دوران می‌روم.',NULL);
INSERT INTO "verses" VALUES(1932648,2488,8,1,'همرهِ کوکبهٔ آصفِ دوران بروم',NULL,NULL);
INSERT INTO "verses" VALUES(1932649,2488,7,0,'تازیان را غمِ احوالِ گران‌باران نیست','کسانی که با سرعت و با تاخت‌و‌تاز سفر میکنند ، حال و غم افرادی را که بند مکانی هستند را درک نمی‌کنند . ای انسان‌های درست‌کار کمکی بدهید تا من که به این مکان دلبستگی دارم و بند هستم به خوبی و آسان از اینجا بروم',NULL);
INSERT INTO "verses" VALUES(1932650,2488,7,1,'پارسایان مددی تا خوش و آسان بروم',NULL,NULL);
INSERT INTO "verses" VALUES(1932651,2488,6,1,'تا لبِ چشمهٔ خورشیدِ درخشان بروم',NULL,NULL);
INSERT INTO "verses" VALUES(1932652,2490,5,0,'صوفیِ صومعهٔ عالَمِ قُدسَم لیکن','هوش مصنوعی: من یک صوفی در عرصهٔ معنویت و تقدس هستم، اما در حال حاضر، محلی که به آن تعلق دارم، همان میخانهٔ مغان است.',NULL);
INSERT INTO "verses" VALUES(1932653,2490,5,1,'حالیا دیرِ مُغان است حوالتگاهم',NULL,NULL);
INSERT INTO "verses" VALUES(1932654,2490,6,0,'با منِ راه‌نشین خیز و سوی میکده آی','هوش مصنوعی: با من که در مسیر نشسته‌ام، بلند شو و به سمت میکده برویم تا در آنجا ببینی که چه کسی هستم و جایگاه من چیست.',NULL);
INSERT INTO "verses" VALUES(1932655,2490,6,1,'تا در آن حلقه ببینی که چه صاحب جاهم',NULL,NULL);
INSERT INTO "verses" VALUES(1932656,2491,12,1,'وین برکشیده گنبدِ نیلی حصار هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932657,2491,12,0,'گویِ زمین ربودهٔ چوگانِ عدلِ اوست','هوش مصنوعی: این زمین در واقع به شکل گوی‌ای است که به وسیلهٔ عدالت او به حرکت درآمده است و این آسمان هم که مانند گنبدی نیلی است، به عنوان حفاظ برای زمین در نظر گرفته می‌شود.',NULL);
INSERT INTO "verses" VALUES(1932658,2491,11,1,'جان می‌کُنَد فدا و کواکب نثار هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932659,2491,11,0,'بر یادِ رایِ انورِ او آسمان به صبح','هوش مصنوعی: به خاطر یاد تصمیم خوشایند او، صبح همچون جان تازه‌ای به آسمان می‌بخشد و ستاره‌ها به او احترام می‌گذارند.',NULL);
INSERT INTO "verses" VALUES(1932660,2491,10,1,'ایام کانْ یمین شد و دریا یسار هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932661,2491,10,0,'بُرهان مُلک و دین که ز دستِ وزارتش','هوش مصنوعی: این بیت به توصیف وضعیت شخصیتی می‌پردازد که از قدرت و نفوذ خود برای حفظ و تقویت سلطنت و دین استفاده کرده است. با این توصیف، می‌توان نتیجه گرفت که دوران حاکمیت او به گونه‌ای بوده که هم قدرت مادی و هم معنوی در دستان او بوده و به این ترتیب، او به یک مقام بالا در جامعه دست یافته است.',NULL);
INSERT INTO "verses" VALUES(1932662,2491,9,1,'و از اِنتِصافِ آصفِ جم اقتدار هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932663,2491,9,0,'حافظ اسیرِ زلفِ تو شد از خدا بترس','هوش مصنوعی: حافظ در این شعر به عشق و زلف معشوق اشاره می‌کند و از کسی که در این عشق گرفتار شده، می‌خواهد که از خدا و عدالت بترسد. او به نوعی به قدرت و تاثیر عشق در زندگی انسان‌ها اشاره دارد و اشاره می‌کند که ممکن است عواقب ناخواسته‌ای در پی داشته باشد.',NULL);
INSERT INTO "verses" VALUES(1932664,2491,8,1,'ای ابرِ لطف بر منِ خاکی بِبار هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932665,2491,8,0,'چون آب روی لاله و گل، فیضِ حُسنِ توست','هوش مصنوعی: به مانند آبی که بر لاله و گل می‌ریزد، زیبایی و حسن تو بر من که در خاک زندگی می‌کنم، چنان باران رحمت ببار.',NULL);
INSERT INTO "verses" VALUES(1932666,2491,7,1,'ای آفتاب سایه ز ما برمدار هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932667,2491,7,0,'چون کائنات جمله به بویِ تو زنده‌اند','هوش مصنوعی: همه‌ی موجودات به خاطر وجود تو زنده‌اند، ای آفتاب! لطفاً سایه‌ات را از ما دور نکن.',NULL);
INSERT INTO "verses" VALUES(1932668,2491,6,1,'خصم از میان بِرَفت و سرشک از کنار هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932669,2491,6,0,'آن شد که چشمِ بد نگران بودی از کمین','هوش مصنوعی: چشم بد و دشمن از دور ناپدید شد و اشک، از کناره‌ها روان گشت.',NULL);
INSERT INTO "verses" VALUES(1932670,2491,13,1,'این پایدار مرکز عالی مدار هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932671,2491,5,1,'تا خاک لعل‌گون شود و مُشکبار هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932672,2491,4,1,'مجموعه‌ای بخواه و صُراحی بیار هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932673,2491,4,0,'خاطر به دستِ تفرقه دادن نه زیرکیست','هوش مصنوعی: اگر بخواهی به هدفی برسی، نباید به فکر ایجاد تفرقه و جدایی باشی، زیرا این کار نشانه‌ی حکمت و هوش نیست. بهتر است که به اتحاد و یکپارچگی فکر کنی و بر روی یک مسأله یا هدف مشخص تمرکز کنی.',NULL);
INSERT INTO "verses" VALUES(1932674,2491,3,1,'و از مِی جهان پُر است و بُتِ میگسار هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932675,2491,3,0,'ای دل بشارتی دَهَمَت محتسب نماند','هوش مصنوعی: ای دل، بشارتی به تو می‌دهم: دیگر خبری از محتسب نیست و جای دنیا پر از شراب است و هیچ بتی از شراب‌خواران هم باقی نمانده است.',NULL);
INSERT INTO "verses" VALUES(1932676,2491,2,1,'لعلِ بُتان خوش است و مِیِ خوشگوار هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932677,2491,2,0,'ما عیب کس به مستی و رندی نمی‌کنیم','ما بابت مستی و رندی به کسی عیب نمیگیریم چرا که می دانیم که بوسه از لب زیبا رویان و نیز می گوارا خوشایند است',NULL);
INSERT INTO "verses" VALUES(1932678,2491,1,1,'جامم به دست باشد و زلفِ نگار هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932679,2491,1,0,'زاهد برو که طالع اگر طالعِ من است','هوش مصنوعی: ای زاهد، برو که اگر سرنوشت من همان باشد که هست، جام شراب در دستانم و زلف نگار هم در کنارم خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1932680,2491,0,1,'از بَخت شُکر دارم و از روزگار هم',NULL,NULL);
INSERT INTO "verses" VALUES(1932681,2491,0,0,'دیدار شد مُیَسَّر و بوس و کنار هم','هوش مصنوعی: دیدار ما آسان شد و به بوسه و نوازش هم رسیدیم. من به خاطر بخت خوبم و همچنین به خاطر روزگار، سپاسگزارم.',NULL);
INSERT INTO "verses" VALUES(1932682,2490,8,1,'با همه پادشهی بندهٔ تورانشاهم',NULL,NULL);
INSERT INTO "verses" VALUES(1932683,2490,8,0,'خوشم آمد که سحر خسروِ خاور می‌گفت','هوش مصنوعی: خوشحال شدم که صبحگاه، شاه خاور می‌گفت که با وجود همه مقام‌هایی که دارد، من خدمتگزار شاه توران هستم.',NULL);
INSERT INTO "verses" VALUES(1932684,2490,7,1,'آه اگر دامنِ حُسنِ تو بگیرد آهم',NULL,NULL);
INSERT INTO "verses" VALUES(1932685,2490,7,0,'مست بگذشتی و از حافظت اندیشه نبود','هوش مصنوعی: تو به راحتی از کنار من رد شدی و به یاد تو نبودم. ای کاش اگر روزی به یاد من بیفتی، آن درد و آهی که از دلتنگی ایجاد می‌شود دامن زیبایی تو را بگیرد.',NULL);
INSERT INTO "verses" VALUES(1932686,2491,5,0,'بر خاکیانِ عشق فشان جرعهٔ لبش','هوش مصنوعی: بر دل‌باختگان عشق، باده‌ای از لبانش بریزد تا زمین به رنگ لعل درآید و عطر مشک بگیرد.',NULL);
INSERT INTO "verses" VALUES(1932687,2449,7,1,'بر نامِ عمر و دولتِ احباب می‌زدم',NULL,NULL);
INSERT INTO "verses" VALUES(1932688,2449,7,0,'خوش بود وقتِ حافظ و فالِ مراد و کام','هوش مصنوعی: زمانی خوش بود که حافظ را می‌خواندم و آرزوهایم را می‌دیدم، و به یاد عمر و ثروت دوستانم شادی می‌کردم.',NULL);
INSERT INTO "verses" VALUES(1932689,2449,6,1,'می‌گفتم این سرود و مِیِ ناب می‌زدم',NULL,NULL);
INSERT INTO "verses" VALUES(1932690,2407,3,0,'کمندِ صیدِ بهرامی بیفکن، جامِ جم بردار','جام جم را با دام و طناب به شیوه بهرام شکار کن؛ زیرا من با طی کردن این صحرا دانستم که نه بهرامی در کار است و نه گور او (به احتمال زیاد منظور گورخر هایی هستند که شاه بهرام به شکارشان علاقه داشته).',NULL);
INSERT INTO "verses" VALUES(1932691,2407,2,1,'به لَعبِ زهرهٔ چنگیّ و مرّیخِ سلحشورش',NULL,NULL);
INSERT INTO "verses" VALUES(1932692,2407,2,0,'بیاور مِی که نَتْوان شد ز مکرِ آسمان ایمن','شراب را بیاورید که از حیله آسمان و زمانه با بازی زهره رقاصه و مریخ جنگجو نمی توان ایمن شد.',NULL);
INSERT INTO "verses" VALUES(1932693,2407,1,1,'مَذاقِ حرص و آز ای دل، بشو از تلخ و از شورَش',NULL,NULL);
INSERT INTO "verses" VALUES(1932694,2407,1,0,'سِماطِ دَهرِ دون‌پرور ندارد شهدِ آسایش','در سفره دنیایی که همواره چیز های رذل می پروراند، شهد و شیرینی آرامشی نیست، پس ای دل! دست از طمع و حرصی که نتیجه اش در این دنیا مشکل است بردار.',NULL);
INSERT INTO "verses" VALUES(1932695,2407,0,1,'که تا یک دَم بیاسایم ز دنیا و شر و شورش',NULL,NULL);
INSERT INTO "verses" VALUES(1932696,2407,0,0,'شرابِ تلخ می‌خواهم که مردافکن بُوَد زورش','به شراب تلخی با قدرت خیلی زیاد نیاز دارم تا برای حتی یک لحظه از دنیا و مشکلاتش فارغ شوم.',NULL);
INSERT INTO "verses" VALUES(1932697,2406,8,1,'نازپروردِ وصال است، مجو آزارش',NULL,NULL);
INSERT INTO "verses" VALUES(1932698,2406,8,0,'دلِ حافظ که به دیدارِ تو خوگر شده بود','هوش مصنوعی: دل حافظ که به دیدن تو عادت کرده و به عشق تو بزرگ شده است، نازک‌سرشتِ وصال است، پس او را آزار نده.',NULL);
INSERT INTO "verses" VALUES(1932699,2406,7,1,'به دو جامِ دگر آشفته شود دستارش',NULL,NULL);
INSERT INTO "verses" VALUES(1932700,2406,7,0,'صوفیِ سرخوش از این دست که کج کرد کلاه','هوش مصنوعی: صوفی که با خوشحالی کلاهش را کج کرده، وقتی دو جام دیگر می‌نوشد، دستارش به هم می‌ریزد و نامنظم می‌شود.',NULL);
INSERT INTO "verses" VALUES(1932701,2406,6,1,'جانبِ عشق عزیز است، فرومگذارش',NULL,NULL);
INSERT INTO "verses" VALUES(1932702,2406,6,0,'صحبت عافیتت گرچه خوش افتاد ای دل','هوش مصنوعی: هرچند که گفتگو درباره سلامتی و آرامشت برای تو دلنشین است، اما باید بدانی که عشق واقعی ارزش بیشتری دارد و نباید آن را فراموش کنی.',NULL);
INSERT INTO "verses" VALUES(1932703,2406,5,1,'هر کجا هست خدایا به سلامت دارش',NULL,NULL);
INSERT INTO "verses" VALUES(1932704,2406,5,0,'آن سفرکرده که صد قافله دل همرهِ اوست','خدایا ناجی موعود را به سلامت دار.',NULL);
INSERT INTO "verses" VALUES(1932705,2406,4,1,'بر حذر باش، که سر می‌شکند دیوارش',NULL,NULL);
INSERT INTO "verses" VALUES(1932706,2406,4,0,'ای که در کوچهٔ معشوقهٔ ما می‌گُذَری','ای کسی که در کوچه‌ی محبوب ما می‌گذری( کوچه‌ای تنگ و پر پیچ و خم است) بدان که زیبایی معشوق ما چنان مسحور کننده است که چشم از او بر نخواهی گرفت و در حیرانی تماشای او دیوار را نخواهی دید و سرت را آسیب میزنی.',NULL);
INSERT INTO "verses" VALUES(1932707,2406,3,1,'این همه قول و غزل تعبیه در منقارش',NULL,NULL);
INSERT INTO "verses" VALUES(1932708,2406,3,0,'بلبل از فیضِ گل آموخت سخن، ور نه نبود','هوش مصنوعی: بلبل به خاطر زیبایی و نعمتی که از گل گرفته، سخن گفتن را یاد گرفته است. اگر این نعمت نبود، این همه شعر و نغمه‌ای که در صدایش هست، وجود نداشت.',NULL);
INSERT INTO "verses" VALUES(1932709,2406,2,1,'زین تَغابُن که خَزَف می‌شکند بازارش',NULL,NULL);
INSERT INTO "verses" VALUES(1932710,2406,2,0,'جایِ آن است که خون موج زَنَد در دلِ لعل','به جاست اگر دل خون شود از این ضرر و زیانی که بازارش را بر هم زده. (سفال شکستن کنایه است از بی ارزش کردن)',NULL);
INSERT INTO "verses" VALUES(1932711,2406,1,1,'خواجه آن است که باشد غَمِ خدمتکارش',NULL,NULL);
INSERT INTO "verses" VALUES(1932712,2406,1,0,'دلربایی همه آن نیست که عاشق بِکُشَند','دلربایی که فقط عاشق کشی نیست. بلکه مِهتر و بزرگ کسیست که به فکر کِهترش باشد.',NULL);
INSERT INTO "verses" VALUES(1932713,2406,0,1,'گُل در اندیشه که چُون عشوه کُنَد در کارش',NULL,NULL);
INSERT INTO "verses" VALUES(1932714,2406,0,0,'فکرِ بلبل همه آن است که گُل شد یارش','عاشق چون بلبل فقط به این فکر می‌کند که معشوق چون گل با او یار شده. اما معشوق در اندیشه است که حالا چگونه با او بازی و عشوه‌گری کند.',NULL);
INSERT INTO "verses" VALUES(1932715,2405,7,1,'عاشقِ مسکین چرا چندین تجمل بایدش؟',NULL,NULL);
INSERT INTO "verses" VALUES(1932716,2405,7,0,'کیست حافظ تا ننوشد باده بی‌آوازِ رود؟','چرا حافظ بی مطرب و ساز، باده نمی‌نوشد؟ چرا عاشق‌های بی‌نوا و مسکین اینقدر تجمل‌خواه هستند؟!',NULL);
INSERT INTO "verses" VALUES(1932717,2405,6,1,'دور چون با عاشقان افتد تَسَلسُل بایدش',NULL,NULL);
INSERT INTO "verses" VALUES(1932718,2405,6,0,'ساقیا در گردشِ ساغر تعلل تا به چند؟','هوش مصنوعی: ای ساقی، تا چه زمانی در نوشاندن شربت به تاخیر می‌افتی؟ وقتی که عشق و عاشقانه‌گی در میان است، باید پیوسته و مکرر این کار را انجام دهی.',NULL);
INSERT INTO "verses" VALUES(1932719,2407,3,1,'که من پیمودم این صحرا، نه بهرام است و نه گورش',NULL,NULL);
INSERT INTO "verses" VALUES(1932720,2405,5,1,'این دلِ شوریده تا آن جَعد و کاکُل بایدش',NULL,NULL);
INSERT INTO "verses" VALUES(1932721,2407,4,0,'بیا تا در مِی صافیت رازِ دَهر بِنْمایم','من اسرار این دنیا و زمانه را در شراب زلال به تو نشان می دهم؛ به این شرط که این اسرار را به کسانی که چشم دلشان کور است و طبع والایی ندارند، نشان ندهی.',NULL);
INSERT INTO "verses" VALUES(1932722,2407,5,0,'نظر کردن به درویشان مُنافیِّ بزرگی نیست','اهمیت به انسان های فقیر، باعث از بین رفتن بزرگی نمی شود و مغایر با بزرگی نیست؛ حتی سلیمان نبی با آن عظمت و جلال، به مورچه ها اهمیت می داد.',NULL);
INSERT INTO "verses" VALUES(1932723,2409,3,1,'تبارک الله از این رَه که نیست پایانش',NULL,NULL);
INSERT INTO "verses" VALUES(1932724,2409,3,0,'تو خفته‌ای و نشد عشق را کرانه پدید','هوش مصنوعی: تو در خواب به سر می‌بری و هنوز نتوانسته‌ای مرزی برای عشق پیدا کنی. چه خوب است این مسیر که هیچ‌گاه پایان ندارد.',NULL);
INSERT INTO "verses" VALUES(1932725,2409,2,1,'ولی ز شرمِ تو در غنچه کرد پنهانش',NULL,NULL);
INSERT INTO "verses" VALUES(1932726,2409,2,0,'زمانه از ورقِ گُل، مثالِ رویِ تو بست','هوش مصنوعی: دنیا به زیبایی گل ورق‌هایی از چهره تو ساخته است، اما به خاطر حیا و شرم تو آن را در غنچه پنهان کرده است.',NULL);
INSERT INTO "verses" VALUES(1932727,2409,1,1,'که دل چه می‌کشد از روزگارِ هجرانش',NULL,NULL);
INSERT INTO "verses" VALUES(1932728,2409,1,0,'کجاست همنفسی؟ تا به شرح عرضه دَهَم','هوش مصنوعی: کجاست کسی که با او صحبت کنم و بگویم دل چه دردهایی را از جدایی‌اش تحمل می‌کند؟',NULL);
INSERT INTO "verses" VALUES(1932729,2409,0,1,'به هر شکسته که پیوست، تازه شد جانش',NULL,NULL);
INSERT INTO "verses" VALUES(1932730,2409,0,0,'چو بر شکست صبا زلفِ عنبرافشانش','هوش مصنوعی: زمانی که نسیم به خورشید تابناکش وزید و زلف‌هایش را به هم ریخت، جانش دوباره جوان شد و در هر بخشی از زندگی‌اش، تازه‌تر شد.',NULL);
INSERT INTO "verses" VALUES(1932731,2408,8,1,'نکردی شُکرِ ایامِ وصالش؟',NULL,NULL);
INSERT INTO "verses" VALUES(1932732,2408,8,0,'چرا حافظ چو می‌ترسیدی از هجر','حافظ چرا وقتی از جدایی می‌ترسید، از روزهای وصال او شکر گزاری خداوند را نکرد؟',NULL);
INSERT INTO "verses" VALUES(1932733,2408,7,1,'که دارم خلوتی خوش با خیالش',NULL,NULL);
INSERT INTO "verses" VALUES(1932734,2408,7,0,'مکن از خواب بیدارم خدا را','تورا به خدا مرا از خواب بیدارم نکن، چون در خواب خلوتی خوشایند با معشوق دارم',NULL);
INSERT INTO "verses" VALUES(1932735,2408,6,1,'دلا چون شیرِ مادر کن حلالش',NULL,NULL);
INSERT INTO "verses" VALUES(1932736,2408,6,0,'گر آن شیرین پسر خونم بریزد','اگر آن شیرین‌سخن من خون من را بریزد، ای دل، او را خون من مانند شیر مادر حلال او باد',NULL);
INSERT INTO "verses" VALUES(1932737,2408,5,1,'چه داری آگهی؟ چون است حالش؟',NULL,NULL);
INSERT INTO "verses" VALUES(1932738,2408,5,0,'صبا زان لولیِ شنگولِ سرمست','نسیم صبحگاهی چه خبری از آن آوازه‌خوان شاد و سرمست دارد؟ حال و روز او چطور است؟',NULL);
INSERT INTO "verses" VALUES(1932739,2408,4,1,'که شیرینان ندادند اِنفِعالش',NULL,NULL);
INSERT INTO "verses" VALUES(1932740,2408,4,0,'که نامِ قند مصری برد آنجا؟','چه کسی نام قند مصری را در آنجا برد؟ قند مصری از شیرین سخنی مردم اینجا شرمنده شده است',NULL);
INSERT INTO "verses" VALUES(1932741,2408,3,1,'بجوی از مردمِ صاحب کمالش',NULL,NULL);
INSERT INTO "verses" VALUES(1932742,2408,3,0,'به شیراز آی و فیضِ روحِ قدسی','به شیراز بیا و از روح مقدس و معنوی را از مردم با کمال آنجا بهره‌مند شو.',NULL);
INSERT INTO "verses" VALUES(1932743,2408,2,1,'عبیرآمیز می‌آید شِمالش',NULL,NULL);
INSERT INTO "verses" VALUES(1932744,2408,2,0,'میانِ جعفرآباد و مُصَلّا','از سوی جعفرآباد(نام یک منطقه) و مصلا( نام یک پارک در زمان حافظ) ، بوی بسیار خوشی می‌آید',NULL);
INSERT INTO "verses" VALUES(1932745,2408,1,1,'که عمرِ خضر می‌بخشد زلالش',NULL,NULL);
INSERT INTO "verses" VALUES(1932746,2408,1,0,'ز رکن آباد ما صد لوحش الله','آب رکن آباد شیراز( نام یک رود) چنان زلال و زیباست که گویی مانند چشمه جاودانگی عمری به اندازه حضرت خضر به شما می‌بخشد',NULL);
INSERT INTO "verses" VALUES(1932747,2408,0,1,'خداوندا نگه دار از زَوالش',NULL,NULL);
INSERT INTO "verses" VALUES(1932748,2408,0,0,'خوشا شیراز و وضعِ بی‌مثالش','شیراز، این شهر با ویژگی‌های منحصر به فردش، بسیار زیبا و دلپذیر است. خدایا، این شهر را از زوال و نابودی حفظ کن.',NULL);
INSERT INTO "verses" VALUES(1932749,2407,6,1,'ولیکن خنده می‌آید، بدین بازویِ بی‌زورش',NULL,NULL);
INSERT INTO "verses" VALUES(1932750,2407,6,0,'کمانِ ابرویِ جانان نمی‌پیچد سر از حافظ','ابرو و زیبایی یار، روی از حافظ بر نمی گرداند و نافرمانی نمی کند، ولی به این ناتوانی او می خندد.',NULL);
INSERT INTO "verses" VALUES(1932751,2407,5,1,'سلیمان با چُنان حشمت، نظرها بود با مورش',NULL,NULL);
INSERT INTO "verses" VALUES(1932752,2407,4,1,'به شرطِ آن که نَنْمایی به کج‌طبعانِ دل‌کورش',NULL,NULL);
INSERT INTO "verses" VALUES(1932753,2405,5,0,'نازها زان نرگسِ مستانه‌اش باید کشید','هوش مصنوعی: این دل شیدا و سرگشته باید زیبایی‌های نرگسِ دل‌ربا را ببیند و از ناز او لذت ببرد، همچنین به زیبایی و جذابیت آن موی گندم‌گون نیز توجه کند.',NULL);
INSERT INTO "verses" VALUES(1932754,2405,4,1,'هر که روی یاسمین و جَعدِ سنبل بایدش',NULL,NULL);
INSERT INTO "verses" VALUES(1932755,2405,4,0,'با چُنین زلف و رُخَش بادا نظربازی حرام','هوش مصنوعی: با این زلف و چهره، کسی را که زیبایی یاسین و جعد سنبل را ببیند، نمی‌توان به تماشای دیگران ترغیب کرد.',NULL);
INSERT INTO "verses" VALUES(1932756,2403,1,1,'سه ماه مِی خور و نُه ماه پارسا می‌باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932757,2403,1,0,'نگویمت که همه ساله مِی پرستی کن','هوش مصنوعی: به من نگو که هر سال فقط سه ماه به می‌پرستی بپرداز و در باقی ماه‌ها آدم پارسا و درست‌کار باش.',NULL);
INSERT INTO "verses" VALUES(1932758,2403,0,1,'به بویِ گُل، نفسی همدمِ صبا می‌باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932759,2403,0,0,'به دورِ لاله، قدح گیر و بی‌ریا می‌باش','هوش مصنوعی: به دور لاله‌ها دور هم جمع شو و با دل صاف و بی‌غرض باشید. با عطر گل روح‌تان را تازه کنید و با نسیم صبح هم‌نشین شوید.',NULL);
INSERT INTO "verses" VALUES(1932760,2402,8,1,'تو را که گفت که در رویِ خوب، حیران باش؟',NULL,NULL);
INSERT INTO "verses" VALUES(1932761,2402,8,0,'خموش حافظ و از جورِ یار ناله مکن','هوش مصنوعی: ساکت باش حافظ و از ظلم یار شکایت نکن، او به تو گفت که باید در مقابل زیبایی‌اش حیرت زده باشی.',NULL);
INSERT INTO "verses" VALUES(1932762,2402,7,1,'به شیوهٔ نظر، از نادرانِ دوران باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932763,2402,7,0,'کمالِ دل‌بری و حُسن در نظربازی است','هوش مصنوعی: بهترین زیبایی و جذابیت در بازی‌های عاشقانه و چشمی نهفته است. سعی کن در این فن، از افرادی که در این زمینه کم‌یاب هستند، به شمار آینی.',NULL);
INSERT INTO "verses" VALUES(1932764,2402,6,1,'خیال و کوشش پروانه بین و خندان باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932765,2402,6,0,'تو شمعِ انجمنی، یک‌زبان و یک‌دل شو','هوش مصنوعی: تو در جمع دوستان مانند شمعی هستی که نور می‌افشانی. یکدل و یکزبان شو و با تلاش و عشق پروانه را ببین و خندان باش.',NULL);
INSERT INTO "verses" VALUES(1932766,2402,5,1,'وز آن که با دلِ ما کرده‌ای پشیمان باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932767,2402,5,0,'دگر به صیدِ حرم تیغ برمکش، زنهار','هوش مصنوعی: دیگر برای شکار دل‌ها با شمشیر به حرم نرو، و از کسی که با دل ما بازی کرده، پشیمان باش.',NULL);
INSERT INTO "verses" VALUES(1932768,2402,4,1,'خدای را که رها کن به ما و سلطان باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932769,2402,4,0,'طریقِ خدمت و آیینِ بندگی کردن','ترجمه دلی : خداوندا راه و روش خدمت کردن به خودت و سنت و آیین بندگی کردنت را به ما عطا کن و خودت پادشاهی کن',NULL);
INSERT INTO "verses" VALUES(1932770,2402,3,1,'بیا و نوگُلِ این بلبلِ غزل‌خوان باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932771,2402,3,0,'زبورِ عشق نوازی نه کارِ هر مرغی است','هوش مصنوعی: شعر عشق و محبت کار هر کسی نیست؛ بنابراین، بیایید و همراه با این بلبل عاشق شعر، مثل یک گل تازه باشیم.',NULL);
INSERT INTO "verses" VALUES(1932772,2402,2,1,'نهان ز چشمِ سِکَندَر چو آبِ حیوان باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932773,2402,2,0,'گَرَت هواست که با خِضْر هم‌نشین باشی','هوش مصنوعی: اگر خواهانِ همراهی با خضر هستی، باید به‌طور پنهانی از دید اسکندر فاصله بگیری، همچون آب حیاتی که در آرامش و دور از چشم است.',NULL);
INSERT INTO "verses" VALUES(1932774,2402,1,1,'مگو که خاطرِ عُشّاق، گو پریشان باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932775,2402,1,0,'شِکَنجِ زلفِ پریشان به دستِ باد مده','هوش مصنوعی: موهای آشفته‌ات را به باد نسپار، زیرا که دل عاشقان همیشه پریشان است.',NULL);
INSERT INTO "verses" VALUES(1932776,2402,0,1,'حریفِ خانه و گرمابه و گلستان باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932777,2402,0,0,'اگر رفیقِ شفیقی، درست پیمان باش','هوش مصنوعی: اگر دوستی به تو وفادار است، باید رابطه‌ات را با او حفظ کنی و در کنار هم برای بهره‌برداری از لذت‌های زندگی مانند خانه، حمام و باغ تلاش کنید.',NULL);
INSERT INTO "verses" VALUES(1932778,2401,6,0,'حافظ که هوس می‌کندش جامِ جهان‌بین','حافظ که هوس جام جهان‌بین را کرده‌است؛ به او بگویید در نظر و دید آصف جمشید‌مکان قرار بگیرد (و مورد لطف او واقع شود)',NULL);
INSERT INTO "verses" VALUES(1932779,2401,6,1,'گو «در نظرِ آصفِ جمشید‌مکان باش»',NULL,NULL);
INSERT INTO "verses" VALUES(1932780,2401,5,0,'تا بر دلش از غصه غباری نَنشیند','هوش مصنوعی: بگذار تا غم و اندوه بر دلش ننشیند، ای سیل اشک که از پشت نامه به راه افتاده‌ای.',NULL);
INSERT INTO "verses" VALUES(1932781,2401,5,1,'ای سیلِ سرشک! از عقبِ نامه روان باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932782,2401,4,0,'خون شد دلم از حسرتِ آن لعلِ روان‌بخش','هوش مصنوعی: دل من به خاطر آرزوی آن گوهر شیرین به خون آمده است، ای درِ محبت، با همان نشانه و علامت باقی بمان.',NULL);
INSERT INTO "verses" VALUES(1932783,2401,4,1,'ای دُرجِ محبّت! به همان مُهر و نشان باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932784,2401,3,0,'دلدار که گفتا به تواَم دل‌نگران است','هوش مصنوعی: دلبر گفت: من به تو خیلی دلواپس هستم. اما حالا به سلامت می‌رسم، تو هم نگران نباش.',NULL);
INSERT INTO "verses" VALUES(1932785,2403,2,0,'چو پیرِ سالِک عشقت به مِی حواله کند','هوش مصنوعی: وقتی که راهنمای پیر در مسیر عشق به تو می‌گوید که شراب بنوش، آن را بنوش و در انتظار رحمت خداوند باش.',NULL);
INSERT INTO "verses" VALUES(1932786,2403,2,1,'بنوش و منتظرِ رحمتِ خدا می‌باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932787,2403,3,0,'گَرَت هواست که چُون جَم به سِرِّ غیب رسی','هوش مصنوعی: اگر می‌خواهی به رازهای پنهان دست پیدا کنی، باید همراه و هم‌نشین جامی باشی که جهان را نشان می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1932788,2403,3,1,'بیا و همدمِ جامِ جهان‌نما می‌باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932789,2405,3,1,'راهرو گر صد هنر دارد توکل بایدش',NULL,NULL);
INSERT INTO "verses" VALUES(1932790,2405,3,0,'تکیه بر تقوی و دانش در طریقت کافری‌ست','هوش مصنوعی: تکیه کردن فقط بر تقوی و دانش در مسیری که باید طی کرد، نادرست است. حتی اگر فردی هنرهای زیادی داشته باشد، برای موفقیت در این راه باید به توکل و اعتماد هم اتکا کند.',NULL);
INSERT INTO "verses" VALUES(1932791,2405,2,1,'کار مُلک است آن که تدبیر و تأمل بایدش',NULL,NULL);
INSERT INTO "verses" VALUES(1932792,2405,2,0,'رندِ عالم‌سوز را با مصلحت‌بینی چه‌کار؟','هوش مصنوعی: کسی که دارای روحی آزادی‌خواه و منحصر به فرد است، نیازی به مصلحت‌سنجی ندارد. برای اداره امور مهم کشوری، باید به فکر دوراندیشی و تأمل باشد.',NULL);
INSERT INTO "verses" VALUES(1932793,2405,1,1,'مرغِ زیرک چون به دام افتد تحمل بایدش',NULL,NULL);
INSERT INTO "verses" VALUES(1932794,2405,1,0,'ای دل اندر بندِ زلفش از پریشانی مَنال','هوش مصنوعی: ای دل، در دام زلف او نچسب و غم نخور، چون مرغ زیرک وقتی به دام می‌افتد، باید تحمل کند.',NULL);
INSERT INTO "verses" VALUES(1932795,2405,0,1,'بر جفایِ خارِ هجران صبرِ بلبل بایدش',NULL,NULL);
INSERT INTO "verses" VALUES(1932796,2405,0,0,'باغبان گر پنج‌روزی صحبتِ گل بایدش','هوش مصنوعی: اگر باغبان می‌خواهد پنج روز با گل صحبت کند، باید در برابر زحمات و رنج‌های غیبت خارها صبر کند، مانند بلبل که صبوری می‌کند.',NULL);
INSERT INTO "verses" VALUES(1932797,2404,7,1,'گو جامِ زر به حافظِ شب زنده دار بخش',NULL,NULL);
INSERT INTO "verses" VALUES(1932798,2404,7,0,'ساقی چو شاه نوش کند بادهٔ صَبوح','هوش مصنوعی: ساقی، وقتی که شاه صبحگاهی شراب می‌نوشد، بگو که جام طلایی را به حافظ شب‌زنده‌دار بده.',NULL);
INSERT INTO "verses" VALUES(1932799,2404,6,1,'ما را به عفو و لطفِ خداوندگار بخش',NULL,NULL);
INSERT INTO "verses" VALUES(1932800,2404,6,0,'شکرانه را که چشم تو رویِ بتان ندید','هوش مصنوعی: ما به خاطر اینکه چشمان تو زیبایی بت‌ها را ندید، از خداوند بخواه که ما را ببخشد و به ما لطف کند.',NULL);
INSERT INTO "verses" VALUES(1932801,2404,5,1,'زین بحر، قطره‌ای به منِ خاکسار بخش',NULL,NULL);
INSERT INTO "verses" VALUES(1932802,2404,5,0,'ای آن که رَه به مشربِ مقصود بُرده‌ای','هوش مصنوعی: ای کسی که به مقصد و آگاهی رسیده‌ای، از آن دریای بیکران، اندکی از علم و معرفت را به من، که انسانی ناچیز و حقیر هستم، عطا کن.',NULL);
INSERT INTO "verses" VALUES(1932803,2409,4,0,'جمالِ کعبه مگر عذرِ رهروان خواهد؟','هوش مصنوعی: آیا زیبایی کعبه به گونه‌ای است که باید از مسافران عذرخواهی کند، وقتی که جان‌های عاشق در میان بیابانش جان داده‌اند؟',NULL);
INSERT INTO "verses" VALUES(1932804,2404,4,1,'وین ماجرا به سروِ لبِ جویبار بخش',NULL,NULL);
INSERT INTO "verses" VALUES(1932805,2404,3,1,'خونِ مرا به چاهِ زَنَخدانِ یار بخش',NULL,NULL);
INSERT INTO "verses" VALUES(1932806,2404,3,0,'راهم شراب لعل زد ای میرِ عاشقان','هوش مصنوعی: من به راهی می‌روم که با شراب سرخ آمیخته است، ای محبوب عاشقان، خون من را در چاه زخم‌های یار قرار بده.',NULL);
INSERT INTO "verses" VALUES(1932807,2404,2,1,'در حلقهٔ چمن به نسیمِ بهار بخش',NULL,NULL);
INSERT INTO "verses" VALUES(1932808,2404,2,0,'زُهدِ گران که شاهد و ساقی نمی‌خرند','هوش مصنوعی: می‌توان گفت که زهد و پرهیزکاری شدید دست‌کم در یک محیط شاداب و پر از زندگی، مانند بهار و فضای خوشبو و دل‌انگیز باغ‌ها، کمتر مورد توجه قرار می‌گیرد و آنچه که در این فضا اهمیت دارد، زیبایی و لذت‌هایی است که طبیعت به انسان هدیه می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1932809,2404,1,1,'تسبیح و طَیلَسان به مِی و مِیگُسار بخش',NULL,NULL);
INSERT INTO "verses" VALUES(1932810,2404,1,0,'طامات و شَطح در رَهِ آهنگِ چنگ نِه','هوش مصنوعی: در مسیر عشق و هنر، از افراط و خریدار بودن دوری کن. به جای درگیر شدن در ذکر و عبادت، از لذت شراب و عاشقی بهره ببر.',NULL);
INSERT INTO "verses" VALUES(1932811,2404,0,1,'وین زهدِ خشک را به مِی خوشگوار بخش',NULL,NULL);
INSERT INTO "verses" VALUES(1932812,2404,0,0,'صوفی گُلی بچین و مُرَقَّع به خار بخش','هوش مصنوعی: صوفی، یک گل بچین و با خارهایش آن را تزئین کن، و این زهد و سخت‌گیری بی‌روح را با شراب خوشمزه مزین کن.',NULL);
INSERT INTO "verses" VALUES(1932813,2403,6,1,'ولی معاشرِ رندانِ پارسا می‌باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932814,2403,6,0,'مریدِ طاعتِ بیگانگان مشو حافظ','هوش مصنوعی: به دیگران وابسته نشو و از آن‌ها پیروی نکن. اما با انسان‌های خوش‌خلق و با ایمان دوست و معاشر باش.',NULL);
INSERT INTO "verses" VALUES(1932815,2403,5,1,'به هرزه طالبِ سیمرغ و کیمیا می‌باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932816,2403,5,0,'وفا مجوی ز کس ور سخن نمی‌شنوی','هوش مصنوعی: به دنبال وفا از کسی نباش، اگر حرفی نمی‌شنوی، بی‌هدف به دنبال چیزهای باارزش و افسانه‌ای مثل سیمرغ و کیمیا باش.',NULL);
INSERT INTO "verses" VALUES(1932817,2403,4,1,'تو همچو بادِ بهاری گره‌گشا می‌باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932818,2403,4,0,'چو غنچه گر چه فروبستگی‌ست کارِ جهان','هوش مصنوعی: هرچند که دنیا گاهی به نظر می‌رسد که بسته و محدود است، تو باید مانند نسیم بهاری باشی که گره‌ها را باز می‌کند و حرکتی تازه به زندگی می‌بخشد.',NULL);
INSERT INTO "verses" VALUES(1932819,2404,4,0,'یا رب به وقتِ گُل، گُنَهِ بنده عفو کن','هوش مصنوعی: خداوندا، در زمان شکفتن گل‌ها، خطای بندت را ببخش و این داستان را به زیبایی سرو کنار جویبار واگذار کن.',NULL);
INSERT INTO "verses" VALUES(1932820,2409,4,1,'که جانِ زنده‌دلان سوخت در بیابانش',NULL,NULL);
INSERT INTO "verses" VALUES(1932821,2409,5,0,'بدین شکستهٔ بیت الحزن که می‌آرد','هوش مصنوعی: کسی که در این اوضاع آشفته و غم‌انگیز دلشکسته به سر می‌برد، چه کسی می‌تواند نشانه‌ای از محبت یوسف دلش را نشان دهد؟',NULL);
INSERT INTO "verses" VALUES(1932822,2409,5,1,'نشان یوسفِ دل از چَهِ زَنَخدانَش؟',NULL,NULL);
INSERT INTO "verses" VALUES(1932823,2415,3,1,'نی گَرَت زخمی رسد، آیی چو چنگ اندر خروش',NULL,NULL);
INSERT INTO "verses" VALUES(1932824,2415,3,0,'با دلِ خونین لبِ خندان بیاور همچو جام','مانند جام می با خون دل لبی خندان داشته باش نه مانند ساز چنگ که با یک زخمه مضراب، به فریاد می‌آید.',NULL);
INSERT INTO "verses" VALUES(1932825,2415,2,1,'زهره در رقص آمد و بَرْبَط زنان می‌گفت نوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932826,2415,2,0,'وان گَهَم دَر داد جامی کز فروغش بر فلک','هوش مصنوعی: در یک زمان، جامی به من دادند که شعاع نور آن باعث شد زهره، ستاره زیبا، به رقص درآید و نوازندگان هم آهنگی شاداب می‌خواندند و می‌گفتند نوش.',NULL);
INSERT INTO "verses" VALUES(1932827,2415,1,1,'سخت می‌گردد جهان بر مردمانِ سخت‌کوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932828,2415,1,0,'گفت آسان گیر بر خود کارها کز رویِ طبع','هوش مصنوعی: به خودت فشار نیاور و در کارهایت راحت‌تر عمل کن، زیرا دنیا با کسانی که بیش از حد سخت‌کوش هستند، به طرز دشواری برخورد می‌کند.',NULL);
INSERT INTO "verses" VALUES(1932829,2415,0,1,'وز شما پنهان نشاید کرد سِرِّ مِی‌فروش',NULL,NULL);
INSERT INTO "verses" VALUES(1932830,2415,0,0,'دوش با من گفت پنهان کاردانی تیزهوش','هوش مصنوعی: شب گذشته، شخصی با من به طور مخفیانه صحبت کرد و گفت که نباید رازهای مربوط به فروش شراب را از شما پنهان کرد.',NULL);
INSERT INTO "verses" VALUES(1932831,2414,8,1,'بختِ جوانَت از فلکِ پیرِ ژِنده پوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932832,2414,8,0,'چندان بمان که خرقهٔ اَزْرَق کُنَد قبول','هوش مصنوعی: به اندازه‌ای بمان که چهره‌ات زیبایی و خوشبختی جوانی‌ات را از سرنوشت قدیمی و ناکامی‌های گذشته به نمایش بگذارد.',NULL);
INSERT INTO "verses" VALUES(1932833,2414,7,1,'نادیده هیچ دیده و نشنیده هیچ گوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932834,2414,7,0,'ای پادشاهِ صورت و معنی که مثل تو','هوش مصنوعی: ای پادشاه زیبایی و معنا، که هیچ کس هیچ‌جا مانند تو را ندیده و هیچ گوشی صدای تو را نشنیده است.',NULL);
INSERT INTO "verses" VALUES(1932835,2414,6,1,'پروانهٔ مراد رسید ای مُحِب خموش',NULL,NULL);
INSERT INTO "verses" VALUES(1932836,2414,6,0,'تا چند همچو شمع زبان آوری کنی؟','هوش مصنوعی: چقدر می‌خواهی مانند شمع صحبت کنی؟ خواسته‌ات به دست آمده، ای عاشق، سکوت کن.',NULL);
INSERT INTO "verses" VALUES(1932837,2414,5,1,'عُذرم پذیر و جرم به ذیلِ کرم بپوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932838,2414,5,0,'عشق است و مفلسیّ و جوانیّ و نوبهار','هوش مصنوعی: عشق، فقر، جوانی و بهار تازه است. از تو خواهش می‌کنم که عذر من را بپذیری و گناهم را تحت پوشش کرم و لطف خود قرار دهی.',NULL);
INSERT INTO "verses" VALUES(1932839,2414,4,1,'فکری بکن که خونِ دل آمد ز غم به جوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932840,2414,4,0,'ساقی بهار می‌رسد و وجهِ مِی نماند','هوش مصنوعی: بیداری و شادابی بهار فرا می‌رسد و دیگر نشانی از زیبایی‌ها و لذایذ وجود ندارد. باید به این فکر بیفتیم که غم و اندوه، به حالتی غیرقابل تحمل رسیده و دل را به شدت می‌آزارد.',NULL);
INSERT INTO "verses" VALUES(1932841,2414,3,1,'دَرکَش زبان و پرده نگه دار و مِی بنوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932842,2414,3,0,'گفتا نه گفتنیست سخن گرچه محرمی','گفت :هرچند تو محرمی به اسرار ولی این سخن ها گفتنی نیستن و توهم حجاب این اسرار نگه دار و می بنوش',NULL);
INSERT INTO "verses" VALUES(1932843,2414,2,1,'کردم سؤال صبحدم از پیرِ مِی فروش',NULL,NULL);
INSERT INTO "verses" VALUES(1932844,2414,2,0,'احوالِ شیخ و قاضی و شُربُ الیَهودِشان','هوش مصنوعی: صبح زود از یک پیر مِی‌فروش درباره وضعیت شیخ و قاضی و شراب‌خواری یهودیان سوال کردم.',NULL);
INSERT INTO "verses" VALUES(1932845,2414,1,1,'تا دید محتسب که سَبو می‌کشد به دوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932846,2414,1,0,'صوفی ز کُنجِ صومعه با پایِ خُم نشست','هوش مصنوعی: یک صوفی در گوشه‌ی صومعه نشسته بود و هنگامی که به تماشای محتسب (محتسب، ناظر بر رفتار مردم و موازین شرعی) پرداخت، دید که او در حال حمل خمر (شراب) بر دوش خود است.',NULL);
INSERT INTO "verses" VALUES(1932847,2414,0,1,'حافظ قَرابه کَش شد و مفتی پیاله نوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932848,2414,0,0,'در عهدِ پادشاهِ خطابخشِ جُرم پوش','هوش مصنوعی: در زمان پادشاهی که به نیکی رفتار می‌کرد و تهمت‌ها را می‌پوشاند، حافظ از آنجا رفت و به شراب نوشی پرداخت.',NULL);
INSERT INTO "verses" VALUES(1932849,2413,8,1,'و از خطرِ چشمِ بَدَش دار گوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932850,2413,8,0,'ای مَلِکُ العَرش مرادش بده','ای خداوند بزرگ، آرزوهای او (شاه شجاع) را برآورده کن و او را از آسیب‌های چشم‌های بد محافظت فرما.',NULL);
INSERT INTO "verses" VALUES(1932851,2413,7,1,'روحِ قدس حلقهٔ امرش به گوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932852,2415,4,0,'تا نگردی آشْنا زین پرده رَمزی نشنوی','هوش مصنوعی: تا زمانی که با این راز آشنا نشوی، پیامی را نمی‌شنوی. تنها کسی که به این اسرار دسترسی دارد، می‌تواند آن را درک کند.',NULL);
INSERT INTO "verses" VALUES(1932853,2415,4,1,'گوشِ نامحرم نباشد جایِ پیغامِ سروش',NULL,NULL);
INSERT INTO "verses" VALUES(1932854,2415,5,0,'گوش کن پند ای پسر وز بهرِ دنیا غم مَخور','هوش مصنوعی: ای پسر، به نصیحت توجه کن و در مورد مسائل دنیوی ناراحت نباش. من به تو چیزی باارزش و زیبا می‌گویم، اگر توانایی درک و فهم آن را داری.',NULL);
INSERT INTO "verses" VALUES(1932855,2415,5,1,'گفتمت چون دُر حدیثی، گر توانی داشت هوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932856,2417,4,1,'که مهتابی دل افروز است و طَرْفِ لاله زاری خوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932857,2417,4,0,'شبِ صحبت غنیمت دان و دادِ خوشدلی بِسْتان','در شب مهتابی که روشنی‌بخش دل و جان است و در کنار چمن و لاله‌زاری باصفا، همنشینی با دوستان را قدر بدان و بهره خود را از عیش و نوش بگیر',NULL);
INSERT INTO "verses" VALUES(1932858,2417,3,1,'بُوَد کز دستِ ایّامَم به دست اُفتَد نگاری خوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932859,2417,3,0,'عروسِ طَبع را زیور ز فکرِ بِکر می‌بندم','اندام عروس طبع و قریحه خود را از اندیشه بدیع و نو آرایش می‌دهم، شاید بر اثر بازی ایام، معشوقی زیبارو به چنگ من افتد..',NULL);
INSERT INTO "verses" VALUES(1932860,2417,2,1,'سِپندی گو بر آتش نِه، که دارد کار و باری خوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932861,2417,2,0,'هر آن کس را که در خاطر ز عشقِ دلبری باریست','به آن کسی که بار عشق و محبت دلبری را بر دل دارد بگو که تا چشم نخورد، اسپند دود کند که سود و سرمایه‌ای خوب دارد.',NULL);
INSERT INTO "verses" VALUES(1932862,2417,1,1,'گوارا بادَت این عِشرت که داری روزگاری خوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932863,2417,1,0,'الا ای دولتی طالع، که قدرِ وقت می‌دانی','هان،‌ ای کسی که بخت با تو مساعد و ارزش وقت را به خوبی می‌شناسی، این عیش و عشرت و شادی برتو گوارا باد که ایام به کام توست.',NULL);
INSERT INTO "verses" VALUES(1932864,2417,0,1,'معاشر دلبری شیرین و ساقی گُلعِذاری خوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932865,2417,0,0,'کنارِ آب و پایِ بید و طبعِ شعر و یاری خوش','هوش مصنوعی: در کنار آب و در سایه درخت بید، جایی مناسب برای نوشتن شعر و داشتن یاری خوب است. دلبری شیرین و ساقی با سلیقه، فضا را زیباتر می‌کند.',NULL);
INSERT INTO "verses" VALUES(1932866,2416,6,1,'می‌رود حافظِ بی‌دل به تَوَلّایِ تو خوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932867,2416,6,0,'در بیابانِ طلب گر چه ز هر سو خطری‌ست','هوش مصنوعی: در جستجوی عشق، با اینکه خطرات زیادی از هر طرف وجود دارد، اما حافظ بی‌دل با شوق و اشتیاق به دنبال تو می‌رود و از این راه خوشحال است.',NULL);
INSERT INTO "verses" VALUES(1932868,2416,5,1,'می‌کُنَد دَردِ مرا از رخِ زیبایِ تو خوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932869,2416,5,0,'شُکرِ چشمِ تو چه گویم؟ که بِدان بیماری','هوش مصنوعی: نمی‌دانم چگونه شکرگزاری کنم برای زیبایی چشمانت، زیرا آن‌ها به گونه‌ای عجیب و دلربا هستند که درد و رنج من را فراموش می‌کنم و باعث می‌شوند دردهایم به راحتی قابل تحمل شوند.',NULL);
INSERT INTO "verses" VALUES(1932870,2413,7,0,'داورِ دین، شاه شجاع، آن که کرد','هوش مصنوعی: داور دین و شاه شجاع، آن کسی است که روح‌القدس را به ایستادگی در برابر فرمانش واداشته است.',NULL);
INSERT INTO "verses" VALUES(1932871,2416,4,1,'کرده‌ام خاطرِ خود را به تمنایِ تو خوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932872,2416,3,1,'هم مَشامِ دلم از زلفِ سَمَن سایِ تو خوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932873,2416,3,0,'هم گلستانِ خیالم ز تو پُر نقش و نگار','هوش مصنوعی: سرزمین خیال من به زیبایی تو آراسته است و بوی خوش زلف‌های تو، دل مرا شاداب و خوشبخت می‌کند.',NULL);
INSERT INTO "verses" VALUES(1932874,2416,2,1,'چشم و ابرویِ تو زیبا، قد و بالایِ تو خوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932875,2416,2,0,'شیوه و نازِ تو شیرین، خط و خالِ تو مَلیح','هوش مصنوعی: زیبایی و روش نازنین تو دل‌فریب است، نقش و نگار صورتت دلنشین، چشم و ابروی تو زیبا و قد و قامتت دلخواه و خوشایند است.',NULL);
INSERT INTO "verses" VALUES(1932876,2416,1,1,'همچو سروِ چمنِ خُلد سراپای تو خوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932877,2416,1,0,'همچو گلبرگِ طَری هست وجودِ تو لطیف','هوش مصنوعی: وجود تو مانند گلبرگ تازه‌ای است که لطافت خاصی دارد و همچون سروهای باغ بهشتی، زیبایی و خوشه‌عطر هستی تو را در بر گرفته است.',NULL);
INSERT INTO "verses" VALUES(1932878,2416,0,1,'دلم از عشوهٔ شیرینِ شِکرخایِ تو خوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932879,2416,0,0,'ای همه شکلِ تو مَطبوع و همه جایِ تو خوش','هوش مصنوعی: ای تو که همه‌ی زیبایی‌های تو دل‌چسب و هر جایی از تو خوشایند است، من از ناز و زیبایی شیرین‌زبان تو بسیار خوشحالم.',NULL);
INSERT INTO "verses" VALUES(1932880,2415,8,1,'آصِفِ صاحب‌قرانِ جرم‌بخشِ عیب‌پوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932881,2415,8,0,'ساقیا مِی ده که رندی‌هایِ حافظ فهم کرد','هوش مصنوعی: ای ساقی، به من شراب بده تا رندی‌ها و لطافت‌های حافظ را درک کنم، همان‌طور که آصف، صاحب قرآن، توانست عیب‌ها را بپوشاند و گناهان را ببخشد.',NULL);
INSERT INTO "verses" VALUES(1932882,2415,7,1,'یا سخن دانسته گو ای مردِ عاقل، یا خموش',NULL,NULL);
INSERT INTO "verses" VALUES(1932883,2415,7,0,'بر بساطِ نکته‌دانان خودفروشی شرط نیست','هوش مصنوعی: در محفل اهل علم و دانش، نیازی به خودنمایی نیست. تو یا باید با دانش خود سخن بگویی یا اگر چیزی برای گفتن نداری، بهتر است سکوت کنی.',NULL);
INSERT INTO "verses" VALUES(1932884,2415,6,1,'زان که آنجا جمله اعضا چشم باید بود و گوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932885,2415,6,0,'در حریمِ عشق نَتْوان زد دَم از گفت و شنید','هوش مصنوعی: در محیط عشق، نمی‌توان به حرف‌زدن و شنیدن اکتفا کرد؛ زیرا در آنجا فقط باید با تمام وجود و حواس به عشق توجه کرد.',NULL);
INSERT INTO "verses" VALUES(1932886,2416,4,0,'در رَهِ عشق که از سیلِ بلا نیست گذار','هوش مصنوعی: در مسیر عشق، با وجود تمام مشکلات و سختی‌ها، من به خاطر عشق تو، دلخوشی‌های خود را حفظ کرده‌ام.',NULL);
INSERT INTO "verses" VALUES(1932887,2401,3,1,'گو «می‌رسم اینک به سلامت»، نگران باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932888,2413,6,1,'با کَرَمِ پادشه عیب پوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932889,2413,5,1,'رویِ من و خاکِ درِ مِی فروش',NULL,NULL);
INSERT INTO "verses" VALUES(1932890,2411,4,0,'اگر پوسیده گردد استخوانم','هوش مصنوعی: اگرچه استخوان‌هایم به مرور زمان فرسوده و از بین بروند، اما عشق و محبت تو هرگز از وجودم فراموش نخواهد شد.',NULL);
INSERT INTO "verses" VALUES(1932891,2411,3,1,'گَرَش همچون قبا گیرم در آغوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932892,2411,3,0,'چو پیراهن شوَم آسوده‌خاطر','وقتی آرامش پیدا می‌کنم و احساس راحتی می‌کنم که مثل پیراهنش او را به آغوش کشم',NULL);
INSERT INTO "verses" VALUES(1932893,2411,2,1,'به سانِ دیگ دایم می‌زنم جوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932894,2411,2,0,'ز تابِ آتشِ سودایِ عشقش','هوش مصنوعی: از شدت شوق و عشق او، مانند دیگی که روی آتش گذاشته شده و دائم در حال جوشیدن است، من هم همیشه در حال هیجان و اضطراب هستم.',NULL);
INSERT INTO "verses" VALUES(1932895,2411,1,1,'ظریفی مَه‌وشی تُرکی قباپوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932896,2411,1,0,'نگاری چابکی شِنگی کُلَه‌دار','هوش مصنوعی: دختری چابک و زیبا با موهای بلند و صورت ماهرانه که لباسی سنتی به تن دارد.',NULL);
INSERT INTO "verses" VALUES(1932897,2411,0,1,'بتِ سنگین‌دلِ سیمین بناگوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932898,2411,0,0,'بِبُرد از من قرار و طاقت و هوش','هوش مصنوعی: شکایت از معشوقی دارم که با دل سنگین و زیبای خود، تمام آرامش، صبر و حواسم را از من گرفته است.',NULL);
INSERT INTO "verses" VALUES(1932899,2410,8,1,'آفرین بر نَفَسِ دلکَش و لطفِ سخنش',NULL,NULL);
INSERT INTO "verses" VALUES(1932900,2410,8,0,'شعرِ حافظ همه بیتُ الْغَزَلِ معرفت است','هوش مصنوعی: شعر حافظ در حقیقت ترکیبی از عشق و دانش است. باید به وجود او و زیباترین کلماتش تبریک گفت که دل را به سمت خود جذب می‌کند.',NULL);
INSERT INTO "verses" VALUES(1932901,2410,7,1,'سَرِ ما و قدمش یا لبِ ما و دهنش',NULL,NULL);
INSERT INTO "verses" VALUES(1932902,2410,7,0,'هر که ترسد ز ملال اندُهِ عشقش نه حلال','هوش مصنوعی: هر کسی که از غم و ناراحتی عشق می‌ترسد، نمی‌تواند به راحتی دل و قدم ما را بپذیرد، یا لب و زبان ما را درک کند.',NULL);
INSERT INTO "verses" VALUES(1932903,2410,6,1,'هر که این آب خورَد رَخْت به دریا فِکَنَش',NULL,NULL);
INSERT INTO "verses" VALUES(1932904,2410,6,0,'عِرض و مال از درِ میخانه نشاید اندوخت','هوش مصنوعی: هر کسی که در میخانه به فریب مشغول شود، نباید به جمع‌آوری مال و ثروت بپردازد؛ زیرا پس از نوشیدن این آب، باید تمام آمال و آرزوهای خود را بر باد بدهد.',NULL);
INSERT INTO "verses" VALUES(1932905,2410,5,1,'سِفله آن مست، که باشد خبر از خویشتنش',NULL,NULL);
INSERT INTO "verses" VALUES(1932906,2410,5,0,'در مقامی که به یادِ لبِ او مِی نوشند','هوش مصنوعی: در جایی که به خاطر یاد لب آن محبوب مشروب می‌نوشند، افرادی نادان و بی‌خبر از خودشان مست هستند.',NULL);
INSERT INTO "verses" VALUES(1932907,2410,4,1,'محترم دار در آن طُرِّهٔ عَنبرشِکَنَش',NULL,NULL);
INSERT INTO "verses" VALUES(1932908,2410,4,0,'گو دلم حقِّ وفا با خط و خالت دارد','هوش مصنوعی: دل من به خاطر زیبایی‌های تو، حق وفاداری دارد. پس باید این موهای خوش‌بو و عطرآگین تو را محترم بشماری.',NULL);
INSERT INTO "verses" VALUES(1932909,2410,3,1,'جای دل‌های عزیز است به هم بر مَزَنَش',NULL,NULL);
INSERT INTO "verses" VALUES(1932910,2410,3,0,'به ادب نافه گشایی کن از آن زلفِ سیاه','هوش مصنوعی: به خاطر ادب و نزاکت، از آن موهای سیاه که جایگاه قلب‌های عزیز است، دوری کن و به آن آسیب نزن.',NULL);
INSERT INTO "verses" VALUES(1932911,2410,2,1,'چشم دارم که سلامی برسانی ز مَنَش',NULL,NULL);
INSERT INTO "verses" VALUES(1932912,2410,2,0,'گر به سرمنزل سلمی رَسی ای بادِ صبا','هوش مصنوعی: اگر به خانه‌ی سلمی برسی، ای نسیم صبح، برایم امید دارم که پیامی از من به او برسانی.',NULL);
INSERT INTO "verses" VALUES(1932913,2410,1,1,'دور باد آفتِ دورِ فلک از جان و تَنَش',NULL,NULL);
INSERT INTO "verses" VALUES(1932914,2410,1,0,'گرچه از کویِ وفا گشت به صد مرحله دور','هوش مصنوعی: هرچند که از مسیر وفا به دوری‌های بسیاری رفته، اما باد بلا و ناپایداری‌های فلک از روح و جسم او دور است.',NULL);
INSERT INTO "verses" VALUES(1932915,2410,0,1,'می‌سپارم به تو از چشمِ حسودِ چَمَنَش',NULL,NULL);
INSERT INTO "verses" VALUES(1932916,2410,0,0,'یا رب این نوگُلِ خندان که سپردی به مَنَش','هوش مصنوعی: خداوندا، این گل ناز و خندان که به من سپردی، حالا آن را به تو می‌سپارم تا از چشم حسودان و بدخواهانی که دور و برش هستند، حفظ شود.',NULL);
INSERT INTO "verses" VALUES(1932917,2409,6,1,'که سوخت حافظِ بی‌دل ز مکر و دستانش',NULL,NULL);
INSERT INTO "verses" VALUES(1932918,2409,6,0,'بگیرم آن سرِ زلف و به دستِ خواجه دهم','هوش مصنوعی: می‌خواهم آن موی زیبای او را بگیرم و به دستش بسپارم، چرا که حافظ بی‌دل از نیرنگ و زیبایی‌های او سوخته است.',NULL);
INSERT INTO "verses" VALUES(1932919,2411,4,1,'نگردد مِهرت از جانم فراموش',NULL,NULL);
INSERT INTO "verses" VALUES(1932920,2411,5,0,'دل و دینم، دل و دینم بِبُرده‌ست','بر و روی و قد و بالایش، دل و ایمان من را گرفته',NULL);
INSERT INTO "verses" VALUES(1932921,2411,5,1,'بَر و دوشش، بَر و دوشش، بَر و دوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932922,2411,6,0,'دوایِ تو، دوایِ توست حافظ','دوا و شفای تو ای حافظ، در رسیدن به کام یار است',NULL);
INSERT INTO "verses" VALUES(1932923,2413,5,0,'گوشِ من و حلقهٔ گیسویِ یار','من برای بندگی یار هستم و سجده‌گاه من، خاک در میکده است.',NULL);
INSERT INTO "verses" VALUES(1932924,2413,4,1,'نکتهٔ سربسته چه دانی؟ خموش',NULL,NULL);
INSERT INTO "verses" VALUES(1932925,2413,4,0,'لطفِ خدا بیشتر از جرمِ ماست','لطف و مهر خدا بیشتر از گناهان ماست؛ راز سربسته را چه‌کسی می‌داند؟ پس باید خاموش گشت!',NULL);
INSERT INTO "verses" VALUES(1932926,2413,3,1,'هر قَدَر ای دل که توانی بکوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932927,2413,3,0,'گرچه وصالش نه به کوشش دهند','اگرچه وصال او را به کوشش و تلاش نمی‌دهند اما ای دوست، هرچه می‌توانی تلاش کن.',NULL);
INSERT INTO "verses" VALUES(1932928,2413,2,1,'تا مِیِ لعل آوَرَدَش خون به جوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932929,2413,2,0,'این خِرَدِ خام به میخانه بَر','این عقل نادان را به میخانه ببر تا می ناب و سرخ‌، او را گرم و زنده کند!',NULL);
INSERT INTO "verses" VALUES(1932930,2413,1,1,'مژدهٔ رحمت برساند سروش',NULL,NULL);
INSERT INTO "verses" VALUES(1932931,2413,1,0,'لطفِ الهی بِکُنَد کارِ خویش','لطف و رحمت الهی همه‌چیز را درست خواهد کرد و مژده و خبر خوش بخشش را سروش می‌رساند.',NULL);
INSERT INTO "verses" VALUES(1932932,2413,0,1,'گفت ببخشند گنه، مِی بنوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932933,2413,0,0,'هاتفی از گوشهٔ میخانه دوش','دیشب در میخانه صدایی از غیب مرا گفت که گناهان را می‌بخشند شاد باش و می بنوش!',NULL);
INSERT INTO "verses" VALUES(1932934,2412,8,1,'گدایِ گوشه‌نشینی تو حافظا مَخروش',NULL,NULL);
INSERT INTO "verses" VALUES(1932935,2412,8,0,'رموزِ مصلحتِ مُلک خسروان دانند','هوش مصنوعی: حکما و حکمرانان می‌دانند که چه کارهایی برای کشور و ملت مفید است، اما تو، حافظ، که در گوشه‌ای نشسته‌ای و به فقر و زهد خود مشغولی، نباید نگران این مسائل باشی و خود را درگیر کُن.',NULL);
INSERT INTO "verses" VALUES(1932936,2412,7,1,'که هست گوشِ دلش محرمِ پیامِ سروش',NULL,NULL);
INSERT INTO "verses" VALUES(1932937,2413,6,0,'رندیِ حافظ نه گناهیست صَعب','رندی حافظ گناهی نابخشودنی نیست؛ وقتی‌که کار او در دست پادشاه بخشش‌گر عیب‌پوش است.',NULL);
INSERT INTO "verses" VALUES(1932938,2412,7,0,'به جز ثنایِ جلالش مساز وِردِ ضمیر','هوش مصنوعی: جز ستایش عظمت او چیز دیگری نگو و نخوان، زیرا فقط دلش از رازهای پیام فرشتگان آگاه است.',NULL);
INSERT INTO "verses" VALUES(1932939,2412,6,0,'محلِ نورِ تَجَلّی‌ست رایِ انور شاه','هوش مصنوعی: جایی که نور و تجلی خداوندی وجود دارد، به شناخت و نزدیکی شاه حقیقت وابسته است. اگر به دنبال نزدیکی به او هستی، باید در پاکی نیّت و هدف خود تلاش کنی.',NULL);
INSERT INTO "verses" VALUES(1932940,2412,5,1,'مکن به فسق مباهات و زهد هم مَفُروش',NULL,NULL);
INSERT INTO "verses" VALUES(1932941,2412,5,0,'دلا! دلالتِ خیرت کنم به راهِ نجات','هوش مصنوعی: ای دل، می‌خواهم تو را به سوی نجات هدایت کنم؛ اما نه به گناه و عیاشی افتخار کن و نه زهد و تظاهر به دینداری را به دنیا بفروش.',NULL);
INSERT INTO "verses" VALUES(1932942,2412,4,1,'امامِ شهر که سجاده می‌کشید به دوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932943,2412,4,0,'ز کویِ میکده دوشش به دوش می‌بُردند','امام شهر که همواره سجاده‌اش را به نشانه زهد و پرهیزگاری همراه خود داشت دیشب چون در مصرف شراب افراط کرده بود و بدحال شده بود بر روی دوش مردم حمل می‌شد.',NULL);
INSERT INTO "verses" VALUES(1932944,2412,3,1,'به رویِ یار بنوشیم و بانگِ نوشانوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932945,2412,3,0,'شرابِ خانگیِ ترسِ محتسب‌خورده','هوش مصنوعی: بیایید در کنار معشوق، شراب خانگی بنوشیم و با صدای شاداب و خوشحالی لحظات را جشن بگیریم.',NULL);
INSERT INTO "verses" VALUES(1932946,2412,2,1,'که از نهفتنِ آن دیگِ سینه می‌زد جوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932947,2412,2,0,'به صوتِ چنگ بگوییم آن حکایت‌ها','هوش مصنوعی: با صدای چنگ، آن داستان‌ها را روایت کنیم که از درون سینه‌ام به خاطر پنهان بودنشان در حال جوشیدن است.',NULL);
INSERT INTO "verses" VALUES(1932948,2412,1,1,'هزار گونه سخن در دهان و لب خاموش',NULL,NULL);
INSERT INTO "verses" VALUES(1932949,2412,1,0,'شد آن که اهلِ نظر بر کناره می‌رفتند','هوش مصنوعی: افراد با دانش و آگاهی در حال دور شدن از می بودند و در حالی که چیزی نمی‌گفتند، هزاران حرف و نکته در ذهنشان می‌گذشت.',NULL);
INSERT INTO "verses" VALUES(1932950,2412,0,1,'که دورِ شاه‌شجاع است، مِی دلیر بنوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932951,2412,0,0,'سحر ز هاتفِ غیبم رسید مژده به گوش','هوش مصنوعی: در صبحگاهی، خبری از جانب غیب به من رسید که دورِ شاه شجاع است، پس دلیرانه می‌نوش.',NULL);
INSERT INTO "verses" VALUES(1932952,2411,6,1,'لبِ نوشش، لبِ نوشش، لبِ نوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932953,2412,6,1,'چو قربِ او طلبی در صفایِ نیّت کوش',NULL,NULL);
INSERT INTO "verses" VALUES(1932954,2401,2,0,'در خرقه، چو آتش زدی ای عارفِ سالِک!','هوش مصنوعی: اگر در لباس زهد و تقوی دلت را آتش بزنی و تغییر و تحول ایجاد کنی، باید تلاش کنی و در جمع نیکان و رندان زمانه خود را نشان دهی.',NULL);
INSERT INTO "verses" VALUES(1932955,2401,2,1,'جهدی کن و سرحلقهٔ رندانِ جهان باش',NULL,NULL);
INSERT INTO "verses" VALUES(1932956,2401,1,0,'زآن باده که در میکدهٔ عشق فروشند','هوش مصنوعی: از آن می که در میکدهٔ عشق به فروش می‌رسد، به ما دو یا سه جام بده و بگو که زمان رمضان است.',NULL);
INSERT INTO "verses" VALUES(1932957,2390,5,0,'بیا که بلبلِ مطبوعِ خاطرِ حافظ','بیا که بلبل طبع حافظ به آرزوی دیدن گلبن وصال تو شعر می‌سراید.',NULL);
INSERT INTO "verses" VALUES(1932958,2390,4,1,'ستاره می‌شِمُرَم تا که شب چه زاید باز',NULL,NULL);
INSERT INTO "verses" VALUES(1932959,2390,4,0,'بدان مَثَل که شب آبستن است روز از تو','مانند آن مثل که گفته‌اند که شب آبستن حوادث روز بعد است شب‌ها بیدار می‌مانم و ستارگان را می‌شمارم تا روز بعد چه شود.',NULL);
INSERT INTO "verses" VALUES(1932960,2390,3,1,'به جز خیالِ جمالت، نمی‌نماید باز',NULL,NULL);
INSERT INTO "verses" VALUES(1932961,2390,3,0,'به پیشِ آینهٔ دل هر آن چه می‌دارم','هر چه به دلم می‌نمایم بجز خیال روی زیبای تو را نمی‌خواهد.',NULL);
INSERT INTO "verses" VALUES(1932962,2390,2,1,'ز خیلِ شادیِ رومِ رُخَت زُدایَد باز',NULL,NULL);
INSERT INTO "verses" VALUES(1932963,2390,2,0,'غمی که چون سپهِ زنگ، مُلکِ دل بگرفت','غمی که چون سیاهی، دل را فراگرفته‌است و آن را روی روشن تو دوباره نورانی کند.',NULL);
INSERT INTO "verses" VALUES(1932964,2390,1,1,'که فتحِ بابِ وصالت مگر گشاید باز',NULL,NULL);
INSERT INTO "verses" VALUES(1932965,2390,1,0,'بیا که فُرقَتِ تو، چشمِ من چنان در بست','بیا که دوری تو چنان چشمانم را بست که امید گشایش فقط در وصال دوباره توست.',NULL);
INSERT INTO "verses" VALUES(1932966,2390,0,1,'بیا که در تنِ مُرده، رَوان درآید باز',NULL,NULL);
INSERT INTO "verses" VALUES(1932967,2390,0,0,'درآ که در دلِ خسته، توان درآید باز','بیا تا در دل دردمند من، زنده شود بیا تا تن مرده من دوباره جان بیابد',NULL);
INSERT INTO "verses" VALUES(1932968,2389,8,1,'حافظ که دوش از لبِ ساقی شنید راز',NULL,NULL);
INSERT INTO "verses" VALUES(1932969,2389,8,0,'چون باده باز بر سرِ خُم رفت کف‌زنان','هوش مصنوعی: وقتی که میگساری دوباره بر سر خمره آمد و در حال رقص و شادی بود، حافظ یادش افتاد که شب گذشته از لب ساقی رازهایی را شنیده بود.',NULL);
INSERT INTO "verses" VALUES(1932970,2389,7,1,'بی طاقِ ابروی تو، نمازِ مرا جواز',NULL,NULL);
INSERT INTO "verses" VALUES(1932971,2389,7,0,'هر دَم به خونِ دیده چه حاجت وضو؟ چو نیست','هوش مصنوعی: هر لحظه که از غم چشمانم اشک می‌ریزد، دیگر نیازی به وضو گرفتن نیست. زیرا وقتی ابروی تو بالای سرم نیست، نماز من هیچ اعتباری ندارد.',NULL);
INSERT INTO "verses" VALUES(1932972,2389,6,1,'از شوقِ آن حریم ندارد سرِ حجاز',NULL,NULL);
INSERT INTO "verses" VALUES(1932973,2389,6,0,'دل کز طوافِ کعبهٔ کویت وقوف یافت','هوش مصنوعی: دل که در پیرامون کعبهٔ زیبایی تو می‌گردد، وقتی به حقیقت این عشق و زیبایی دست می‌یابد، دیگر دلش هیچ‌گونه آرامش و سکون ندارد و به حجاز (مکه) فکر نمی‌کند.',NULL);
INSERT INTO "verses" VALUES(1932974,2389,5,1,'چون زر اگر برَند مرا در دهانِ گاز',NULL,NULL);
INSERT INTO "verses" VALUES(1932975,2389,5,0,'از طعنهٔ رقیب نگردد عیارِ من','هوش مصنوعی: هرچند دیگری به من بی‌احترامی کند، اما ارزش من کاهش نمی‌یابد؛ چرا که حتی اگر مرا به شدت مورد حمله قرار دهند، همچنان کیفیت و ارزش خود را حفظ می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1932976,2389,4,1,'بِشْکَست عهد، چون درِ میخانه دید باز',NULL,NULL);
INSERT INTO "verses" VALUES(1932977,2389,4,0,'صوفی که بی تو توبه ز مِی کرده بود، دوش','هوش مصنوعی: صوفی که مدت‌ها از نوشیدن شراب دست کشیده بود، شب گذشته وقتی دوباره درب میخانه را دید، عهد و پیمانش را شکست.',NULL);
INSERT INTO "verses" VALUES(1932978,2389,3,1,'بی شمعِ عارضِ تو دلم را بُوَد گداز',NULL,NULL);
INSERT INTO "verses" VALUES(1932979,2389,3,0,'پروانه را ز شمع بُوَد سوزِ دل، ولی','هوش مصنوعی: پروانه به خاطر شمع دلش می‌سوزد، اما بدون زیبایی تو، دل من نیز به شدت می‌سوزد و در آتش می‌گدازد.',NULL);
INSERT INTO "verses" VALUES(1932980,2389,2,1,'چون عود گو بر آتشِ سودا بسوز و ساز',NULL,NULL);
INSERT INTO "verses" VALUES(1932981,2389,2,0,'آن را که بویِ عَنبر زلفِ تو آرزوست','هوش مصنوعی: کسی که بوی خوش زلف تو را می‌خواهد، باید مانند عود باشد که وقتی بر آتش می‌افتد، بسوزد و خود را به نمایش بگذارد.',NULL);
INSERT INTO "verses" VALUES(1932982,2389,1,1,'بُبْریده‌اند بر قدِ سَرْوَت قبایِ ناز',NULL,NULL);
INSERT INTO "verses" VALUES(1932983,2389,1,0,'فرخنده باد طلعتِ خوبت که در ازل','هوش مصنوعی: خوشا به حال چهره زیبایت که از ابتدای آفرینش برای قامت بلندت، لباس زیبایی دوخته‌اند.',NULL);
INSERT INTO "verses" VALUES(1932984,2389,0,1,'عُشّاق را به نازِ تو هر لحظه صد نیاز',NULL,NULL);
INSERT INTO "verses" VALUES(1932985,2389,0,0,'ای سروِ نازِ حُسن که خوش می‌روی به ناز','هوش مصنوعی: ای سرو زیبای دلربا که با ناز و elegance خود می‌چرخانی، عاشقان به خاطر زیبایی تو هر لحظه سرشار از نیاز و تمنا هستند.',NULL);
INSERT INTO "verses" VALUES(1932986,2390,5,1,'به بویِ گُلبُنِ وصلِ تو می‌سُراید باز',NULL,NULL);
INSERT INTO "verses" VALUES(1932987,2391,0,0,'حالِ خونین دلان که گوید باز؟','چه کسی حال خونین‌دلان و دردمندان را می‌تواند شرح دهد؟ چه‌کس خون خم را از فلک و روزگار بجوید؟',NULL);
INSERT INTO "verses" VALUES(1932988,2391,0,1,'وز فلک خونِ خُم که جوید باز؟',NULL,NULL);
INSERT INTO "verses" VALUES(1932989,2391,1,0,'شرمش از چشمِ مِی پرستان باد','شرم بر نرگس باد اگر با وجود چشم مست می‌پرستان باده‌نوش، بازهم بروید',NULL);
INSERT INTO "verses" VALUES(1932990,2393,1,0,'عاقبت منزلِ ما وادیِ خاموشان است','عاقبت ما مردن و پیوستن به مردگان است پس الان به‌فکر این باش که غوغایی و شوری به‌پا کنی که در جهان بپیچد.',NULL);
INSERT INTO "verses" VALUES(1932991,2393,0,1,'پیشتر زان که شَوَد کاسهٔ سَر خاک‌ انداز',NULL,NULL);
INSERT INTO "verses" VALUES(1932992,2393,0,0,'خیز و در کاسهٔ زر آبِ طَرَبناک انداز','بیا و در کاسه زر‌، باده شادی‌بخش بریز پیش از آنکه کاسه سر ما پر از خاک گردد.',NULL);
INSERT INTO "verses" VALUES(1932993,2392,7,1,'به سویِ دیو مِحَن، ناوَکِ شهاب انداز',NULL,NULL);
INSERT INTO "verses" VALUES(1932994,2392,7,0,'ز جورِ چرخ چو حافظ به جان رسید دلت','هوش مصنوعی: چون مصیبت‌ها و سختی‌های زندگی به حافظ رسید، دل تو باید به سمت دلی پر از خشم و ناراحتی برود و مشکلات را مثل شهابی بر سر خودت بیندازی.',NULL);
INSERT INTO "verses" VALUES(1932995,2392,6,1,'مرا به میکده بَر، در خُمِ شراب انداز',NULL,NULL);
INSERT INTO "verses" VALUES(1932996,2392,6,0,'مَهِل که روزِ وفاتم به خاک بسپارند','هوش مصنوعی: به آرامی و با صبر از من خداحافظی کنید، زیرا وقتی که روز مرگ من فرا برسد، می‌خواهم در میکده و در میان شراب دفن شوم.',NULL);
INSERT INTO "verses" VALUES(1932997,2392,5,1,'ز رویِ دخترِ گُل‌چهرِ رز، نقاب انداز',NULL,NULL);
INSERT INTO "verses" VALUES(1932998,2392,5,0,'به نیم‌شب اگرت آفتاب می‌باید','هوش مصنوعی: اگر در نیمه شب بخواهی که آفتاب ظاهر شود، باید بر چهره دختر زیبای رَز پرده‌ای بگذاری.',NULL);
INSERT INTO "verses" VALUES(1932999,2392,4,1,'نظر بر این دلِ سرگشتهٔ خراب انداز',NULL,NULL);
INSERT INTO "verses" VALUES(1933000,2392,4,0,'اگر چه مست و خرابم، تو نیز لطفی کن','هوش مصنوعی: اگرچه من در حال مستی و گیجی هستم، اما تو هم لطفی کن و نظری به دل آشفته‌ام بیانداز.',NULL);
INSERT INTO "verses" VALUES(1933001,2392,3,1,'شرارِ رَشک و حسد در دلِ گلاب انداز',NULL,NULL);
INSERT INTO "verses" VALUES(1933002,2392,3,0,'بیار زآن مِی گلرنگِ مشک‌بو جامی','هوش مصنوعی: مقداری از آن شراب خوش رنگ و خوشبو بیاور و در جام بریز که آتش حسد و ناکامی را در دل گل سرخ بیفکند.',NULL);
INSERT INTO "verses" VALUES(1933003,2392,2,1,'مرا دگر ز کَرَم با رهِ صواب انداز',NULL,NULL);
INSERT INTO "verses" VALUES(1933004,2388,6,1,'نوایِ بانگِ غزل‌هایِ حافظ از شیراز',NULL,NULL);
INSERT INTO "verses" VALUES(1933005,2392,2,0,'ز کویِ میکده برگشته‌ام ز راهِ خطا','هوش مصنوعی: از محل میخانه بازگشته‌ام و از راه غلطی که رفته‌ام، تو مرا با لطف خود به راه درست هدایت کن.',NULL);
INSERT INTO "verses" VALUES(1933006,2392,1,0,'مرا به کَشتیِ باده درافکن ای ساقی!','ای ساقی، مرا غرق در شراب کن (شراب بسیار بده)، چرا که گفته‌اند کار خوب کن و در آب بیندازد (اشاره به تو نیکی کن و در دجله انداز ...).',NULL);
INSERT INTO "verses" VALUES(1933007,2392,0,1,'خروش و وِلوِله در جانِ شیخ و شاب انداز',NULL,NULL);
INSERT INTO "verses" VALUES(1933008,2392,0,0,'بیا و کَشتیِ ما در شَطِ شراب انداز','هوش مصنوعی: بیایید و کشتی ما را در آب‌های شراب به حرکت درآورید و شور و هیجان را در دل پیر و جوان ایجاد کنید.',NULL);
INSERT INTO "verses" VALUES(1933009,2391,6,1,'گر نمیرد به سَر بپوید باز',NULL,NULL);
INSERT INTO "verses" VALUES(1933010,2391,6,0,'گِردِ بیتُ الحَرامِ خُم حافظ','هوش مصنوعی: اگر حافظ در گرد خانه‌ی خدا بمیرد، بار دیگر سرش را به زمین خواهد زد و دوباره به سمت آنجا خواهد رفت.',NULL);
INSERT INTO "verses" VALUES(1933011,2391,5,1,'بِبُرَش موی تا نَمویَد باز',NULL,NULL);
INSERT INTO "verses" VALUES(1933012,2391,5,0,'بس که در پرده چنگ گفت سخن','هوش مصنوعی: بسیاری از صحبت‌ها و رازها در حین نواختن چنگ بیان می‌شود، اما برای اینکه این رازها فاش نشوند، باید موی شخصی که در حال نواختن است قطع شود تا دوباره ناپدید نشود.',NULL);
INSERT INTO "verses" VALUES(1933013,2391,4,1,'ساغری از لبش نبوید باز',NULL,NULL);
INSERT INTO "verses" VALUES(1933014,2391,4,0,'نَگُشایَد دلم چو غنچه اگر','هوش مصنوعی: دل من مانند غنچه‌ای است که تنها با بوییدن ساغری از لب او می‌تواند باز گردد و شکوفا شود. اگر این بوی خوش نیست، دل من همچنان در بسته باقی می‌ماند.',NULL);
INSERT INTO "verses" VALUES(1933015,2391,3,1,'زین جفا رُخ به خون بشوید باز',NULL,NULL);
INSERT INTO "verses" VALUES(1933016,2391,3,0,'هر که چون لاله کاسه گَردان شد','هوش مصنوعی: هر کسی که مانند لاله در برابر ظلم و بی‌عدالتی کمر خم کند، در نهایت از این درد و رنج به خود می‌آید و چهره‌اش را با خون خود شستشو می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1933017,2391,2,1,'سِرِّ حکمت به ما که گوید باز؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933018,2391,2,0,'جز فَلاطونِ خُم نشینِ شراب','بجز شراب خم‌نشین که همچون افلاطون است، چه کسی می‌تواند راز حکمت را به ما بگوید؟',NULL);
INSERT INTO "verses" VALUES(1933019,2391,1,1,'نرگسِ مست اگر بروید باز',NULL,NULL);
INSERT INTO "verses" VALUES(1933020,2392,1,1,'که گفته‌اند «نِکویی کن و در آب انداز»',NULL,NULL);
INSERT INTO "verses" VALUES(1933021,2393,1,1,'حالیا غُلغُله در گنبدِ افلاک انداز',NULL,NULL);
INSERT INTO "verses" VALUES(1933022,2388,6,0,'فِکَنْد زمزمهٔ عشق در حجاز و عراق','هوش مصنوعی: عشق در سرزمین‌های حجاز و عراق به گوش می‌رسد و صدای غزل‌های حافظ از شیراز به گوش می‌افتد.',NULL);
INSERT INTO "verses" VALUES(1933023,2388,5,0,'به نیم‌بوسه دعایی بخر ز اهلِ دلی','هوش مصنوعی: با یک نیم‌بوسه می‌توانی دعایی بگیری از اهل دل که به واسطه آن می‌توانی از آسیب‌های دشمنت و بلایای او در امان بمانی.',NULL);
INSERT INTO "verses" VALUES(1933024,2386,6,1,'بخت گو پشت مَکُن، رویِ زمین لشکر گیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933025,2386,6,0,'دوست گو یار شو و هر دو جهان دشمن باش','هوش مصنوعی: دوست به تو می‌گوید که همراه و یار شو و در عین حال باید در برابر دشمنان دو جهان متحد بایستی. خوشبختی به تو می‌گوید که پشت به او نکن و بر روی زمین آماده مقاومت و ایستادگی باش.',NULL);
INSERT INTO "verses" VALUES(1933026,2386,5,1,'سیم در باز و به زر سیمبَری در بر گیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933027,2386,5,0,'صوف بَرکَش ز سر و بادهٔ صافی دَرکَش','هوش مصنوعی: نفس خود را از دنیای مادی جدا کن و از می ناب بهره‌مند شو، در را باز کن و بگذار نور و ثروت به زندگی‌ات وارد شود.',NULL);
INSERT INTO "verses" VALUES(1933028,2386,4,1,'ور نه با گوشه رو و خرقهٔ ما در سر گیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933029,2386,4,0,'در سَماع آی و ز سر خرقه برانداز و برقص','در جمع‌های دوستانه شرکت کن و از دغدغه‌های دنیوی خود فاصله بگیر و با شادی و نشاط به رقص و پایکوبی بپرداز. در غیر این صورت، برو با خیالات ما زندگی رو سر کن.',NULL);
INSERT INTO "verses" VALUES(1933030,2386,3,1,'آتشم عشق و دلم عود و تَنَم مِجمَر گیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933031,2386,3,0,'چنگ بِنْواز و بساز ار نَبُوَد عود چه باک؟','هوش مصنوعی: اگر نیازی به عود نیست، چنگ بزن و ساز بزن. مهم نیست، چون آتش من عشق است و قلبم مانند عود می‌سوزد و بدنم همچون مجمر می‌سوزد.',NULL);
INSERT INTO "verses" VALUES(1933032,2386,2,1,'در غَمَت سیمْ شُمار اشک و رُخَش را زر گیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933033,2386,2,0,'تَرکِ درویش مگیر ار نَبُوَد سیم و زَرَش','هوش مصنوعی: اگر از درویش حمایت نکنی، حتی اگر او پول و ثروتی نداشته باشد، در غم او نگریسته و اشک‌هایش را بشمار، چون ارزش واقعی او در زیبایی و احساساتش نهفته است.',NULL);
INSERT INTO "verses" VALUES(1933034,2386,1,1,'بر سَرِ کُشتهٔ خویش آی و ز خاکَش برگیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933035,2386,1,0,'در لبِ تشنهٔ ما بین و مدار آب دریغ','هوش مصنوعی: ما به شدت تشنه‌ایم و در دور و برمان آبی نیست. ای کسی که بر خاکِ مردهٔ خود تکیه کرده‌ای، بیا و از خاک او بردار و به او توجه کن.',NULL);
INSERT INTO "verses" VALUES(1933036,2386,0,1,'پیشِ شمع آتشِ پروانه به جان گو درگیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933037,2386,0,0,'روی بِنْما و مرا گو که ز جان دل برگیر','هوش مصنوعی: به من بنما و به من بگو که از جانت دل را بگیر، پیش شمع آتش پروانه بگویید که بشود درگیر.',NULL);
INSERT INTO "verses" VALUES(1933038,2385,11,1,'که ساقیان کمان ابرویَت زَنَند به تیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933039,2385,11,0,'حدیثِ توبه در این بزمگه مگو حافظ','ای حافظ، حرف از توبه در این بزمگه مگو که ساقیان زیبارو با کمان ابرو تو را مجازات می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1933040,2385,10,1,'خبر دهید به مجنونِ خسته از زنجیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933041,2385,10,0,'دل رمیدهٔ ما را که پیش می‌گیرد؟','چه کسی زنجیر دل دیوانه ما را می‌گیرد؟ به مجنون خسته از زنجیر خبر دهید تا زنجیر خود را بر دل دیوانه ما بنهد.',NULL);
INSERT INTO "verses" VALUES(1933042,2385,9,1,'همین بس است مرا صُحبتِ صَغیر و کَبیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933043,2385,9,0,'مِی دوساله و محبوبِ چارده ساله','هوش مصنوعی: من به همین اندازه راضی‌ام که با شراب دو ساله و محبوب چهارده ساله سر و کار داشته باشم و نیاز به صحبت کردن با بزرگ‌ترها و کوچک‌ترها ندارم.',NULL);
INSERT INTO "verses" VALUES(1933044,2385,8,1,'ولی کرشمهٔ ساقی نمی‌کُنَد تقصیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933045,2385,8,0,'به عزمِ توبه نهادم قدح ز کف صد بار','تا امروز صد بار باده‌نوشی را کنار گذاشته‌ام، اما کرشمه و ناز ساقی کوتاهی نمی‌کند.',NULL);
INSERT INTO "verses" VALUES(1933046,2385,7,1,'حسود گو کَرَمِ آصفی ببین و بمیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933047,2385,7,0,'بیار ساغرِ دُرِّ خوشاب ای ساقی','ای ساقی، باده ناب بیاور، به‌حسود نیز بگویید که کرم «آصف» را ببیند و بمیرد.',NULL);
INSERT INTO "verses" VALUES(1933048,2385,6,1,'که نقشِ خالِ نگارم نمی‌رود ز ضمیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933049,2385,6,0,'چو لاله در قَدَحم ریز ساقیا مِی و مُشک','ای ساقی، همچون لاله باده خوش‌عطر در جامم بریز چون هرکاری می‌کنم خیال و زیبایی یارم از خاطرم نمی‌رود.',NULL);
INSERT INTO "verses" VALUES(1933050,2385,5,1,'گر اندکی نه به وِفقِ رضاست خرده مگیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933051,2385,5,0,'چو قسمتِ ازلی بی‌حضورِ ما کردند','چون‌که قسمت و سرنوشت ازلی را بی‌ما و بدون اجازه ما انجام دادند، اگر می‌بینی کمی برخلاف میل است، زیاد ایراد مگیر.',NULL);
INSERT INTO "verses" VALUES(1933052,2385,4,1,'اگر موافقِ تدبیرِ من شَوَد تقدیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933053,2386,7,0,'میل رفتن مَکُن ای دوست دَمی با ما باش','هوش مصنوعی: ای دوست، تمایل به رفتن نداشته باش و کمی با ما بمان. در کنار جوی، شادی را جست‌وجو کن و لیوانی بگیر در دستانت.',NULL);
INSERT INTO "verses" VALUES(1933054,2386,7,1,'بر لبِ جوی، طرب جوی و به کف ساغر گیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933055,2386,8,0,'رفته گیر از بَرَم و زآتش و آبِ دل و چشم','هوش مصنوعی: از دست رفته‌ای از من و در آتش و آب دل غمگینم. چهره‌ام زرد شده و لب‌هایم خشک هستند، در حالی که کنارم ترس و اضطراب وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1933056,2386,8,1,'گونه‌ام زرد و لبم خشک و کنارم تَر گیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933057,2388,4,1,'در این سراچهٔ بازیچه، غیرِ عشق مَباز',NULL,NULL);
INSERT INTO "verses" VALUES(1933058,2388,4,0,'در این مقامِ مجازی به جز پیاله مگیر','هوش مصنوعی: در این مکان خیالی، فقط پیاله را بگیر و در این جا که پر از ترفند و فریب است، جز عشق به سراغ چیز دیگری نرو.',NULL);
INSERT INTO "verses" VALUES(1933059,2388,3,1,'به قولِ مُفتیِ عشقش درست نیست نماز',NULL,NULL);
INSERT INTO "verses" VALUES(1933060,2388,3,0,'طهارت ار نه به خونِ جگر کُنَد عاشق','اگر عاشق با خون دل طهارت نگیرد ( کنایه از سختی کشیدن )، پس عاشق نمی‌تواند به گفته‌ی پیشوای عشق، نماز واقعی را به جا آورد.',NULL);
INSERT INTO "verses" VALUES(1933061,2388,2,1,'که مردِ راه نَیَندیشد از نَشیب و فراز',NULL,NULL);
INSERT INTO "verses" VALUES(1933062,2388,2,0,'ز مشکلاتِ طریقت عِنان مَتاب ای دل!','هوش مصنوعی: ای دل، از دشواری‌های راه معنوی ناامید نشو، چرا که کسی که در این سفر قدم می‌زند، به چالش‌ها و ناملایمات فکر نمی‌کند.',NULL);
INSERT INTO "verses" VALUES(1933063,2388,1,1,'که کیمیایِ مراد است، خاکِ کویِ نیاز',NULL,NULL);
INSERT INTO "verses" VALUES(1933064,2388,1,0,'نیازمندِ بلا گو رخ از غبار مَشوی','هوش مصنوعی: اگر به سختی و مشکل نیاز داری، از غبار و مشکلات روی برمت نگردان. زیرا آن چیزی که تو به دنبالش هستی، همان خاکی است که در آن نیاز تو برآورده می‌شود.',NULL);
INSERT INTO "verses" VALUES(1933065,2388,0,1,'چه شُکر گویَمَت ای کارسازِ بنده نواز؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933066,2388,0,0,'منم که دیده به دیدارِ دوست کردم باز','هوش مصنوعی: من کسی هستم که برای دیدن دوست دوباره چشم گشودم. حالا نمی‌دانم چطور از تو، ای یاری‌دهنده و لطف‌کار، تشکر کنم.',NULL);
INSERT INTO "verses" VALUES(1933067,2387,8,1,'در آن مَقام که حافظ برآورد آواز',NULL,NULL);
INSERT INTO "verses" VALUES(1933068,2387,8,0,'غزل سُرایی ناهید صرفه‌ای نَبَرَد','ناهید‌: ستاره خنیاگر زُهره. صَرفه‌بردن: پیشی گرفتن. مقام‌: مرتبه‌، جایگاه || پردهٔ سرود (در موسیقی).',NULL);
INSERT INTO "verses" VALUES(1933069,2387,7,1,'جمالِ دولتِ محمود را به زلفِ ایاز',NULL,NULL);
INSERT INTO "verses" VALUES(1933070,2387,7,0,'غَرَض کِرشمهٔ حُسن است ور نه حاجت نیست','هوش مصنوعی: هدف از زیبایی و جاذبه‌ی ظاهری، فقط نشان دادن حسن و زیبایی است و نیازی به زیبایی و جمال دولت محمود نیست که به زلف ایاز وابسته شود.',NULL);
INSERT INTO "verses" VALUES(1933071,2388,5,1,'که کِیدِ دشمنت از جان و جسم دارد باز',NULL,NULL);
INSERT INTO "verses" VALUES(1933072,2387,6,1,'گَرَت چو شمع جفایی رِسَد بسوز و بساز',NULL,NULL);
INSERT INTO "verses" VALUES(1933073,2387,5,1,'که کرد نرگسِ مستش سیَه به سرمهٔ ناز',NULL,NULL);
INSERT INTO "verses" VALUES(1933074,2387,5,0,'چه فتنه بود که مَشّاطِهٔ قضا انگیخت','این چه فتنه‌ای بود که دست آرایشگر تقدیر به‌پا کرد؟ چه‌کسی ناز را هم‌چون سرمه بر چشمان مستش کشید؟',NULL);
INSERT INTO "verses" VALUES(1933075,2387,4,1,'ز اشک پُرس حکایت که من نیَم غَمّاز',NULL,NULL);
INSERT INTO "verses" VALUES(1933076,2387,4,0,'چه گویَمَت که ز سوزِ درون چه می‌بینم','چطور برایت بگویم در دلم چه آتشی برپاست و چه رنجی می‌کشم؟ اگر می‌خواهی از حال و روزم باخبر شوی، از اشک‌هایم بپرس؛ چون من اهل بازگو کردن دردها و راز دلم نیستم.',NULL);
INSERT INTO "verses" VALUES(1933077,2387,3,1,'من آن نیَم که از این عشق‌بازی آیم باز',NULL,NULL);
INSERT INTO "verses" VALUES(1933078,2387,3,0,'اگر چه حُسنِ تو از عشقِ غیر مُستَغنی‌ست','هوش مصنوعی: اگرچه زیبایی تو به عشق دیگران نیاز ندارد، اما من آن کسی نیستم که از این عشق و جذابیت به راحتی کناره‌گیری کنم.',NULL);
INSERT INTO "verses" VALUES(1933079,2387,2,1,'که نیست سینهٔ اربابِ کینه‌، محرمِ راز',NULL,NULL);
INSERT INTO "verses" VALUES(1933080,2387,2,0,'غمِ حبیب نهان بِه ز گفت و گوی رقیب','ارباب کینه‌: صاحب کینه‌، کسی که دشمنی و بغض در دل دارد.',NULL);
INSERT INTO "verses" VALUES(1933081,2387,1,1,'رفیقِ عشق چه غم دارد از نَشیب و فراز',NULL,NULL);
INSERT INTO "verses" VALUES(1933082,2387,1,0,'رَوَندگانِ طریقت رَهِ بلا سِپَرَند','هوش مصنوعی: سَیر و سلوک کنندگان در راه حقیقت، به سختی‌ها و مشکلات دنیوی اجتناب‌ناپذیرند. دوستان عاشق چه نگران سختی‌ها و فراز و نشیب‌های زندگی هستند، چرا که عشق آن‌ها را در برابر این دشواری‌ها محافظت می‌کند.',NULL);
INSERT INTO "verses" VALUES(1933083,2387,0,1,'ز رویِ صدق و صفا گشته با دلم دَمساز',NULL,NULL);
INSERT INTO "verses" VALUES(1933084,2387,0,0,'هزار شُکر که دیدم به کامِ خویشت باز','هوش مصنوعی: هزار بار شکر گزارم که توانستم به آرزوی خود برسم و به خاطر صداقت و پاکی قلبم، رابطه‌ای دلنشین و صمیمی با دلم برقرار شده است.',NULL);
INSERT INTO "verses" VALUES(1933085,2386,9,1,'که ببین مجلسم و تَرکِ سَرِ منبر گیر',NULL,NULL);
INSERT INTO "verses" VALUES(1933086,2386,9,0,'حافظ آراسته کن بزم و بگو واعظ را','هوش مصنوعی: حافظ می‌گوید: مراسم شادی را زیبا و آراسته کن و به واعظ بگو که بی‌نظاره‌ام و از سخنرانی و خطابه‌اش دست بردارد.',NULL);
INSERT INTO "verses" VALUES(1933087,2387,6,0,'بدین سپاس که مجلس مُنَوَّر است به دوست','هوش مصنوعی: به خاطر این که مجلس پرنور و شاداب است، اگر دوستت مثل شمع به تو آسیب برساند، با این‌که درد می‌کشی، باید بسوزی و تحمل کنی.',NULL);
INSERT INTO "verses" VALUES(1933088,2417,5,0,'مِیی در کاسهٔ چشم است ساقی را بِنامیزد','در جام چشم‌های ساقی، شرابی موج می‌زند که با عقل از در مستی و ستیز در می‌آید و حالت بی خبری و سرخوشی به‌دست می‌دهد..',NULL);
INSERT INTO "verses" VALUES(1933089,2393,2,0,'چشمِ آلوده‌نظر، از رخِ جانان دور است','چشم‌ آلوده و ناپاک هرگز روی معشوق را نخواهد دید؛ او را در آینه زلال (دل پاک) ببین.',NULL);
INSERT INTO "verses" VALUES(1933090,2393,3,0,'به سرِ سبزِ تو ای سرو که گر خاک شَوَم','به جان سرسبز و شاد تو، ای سرو خوش‌قامت من؛ که وقتی درگذشتم و مُردم به دیدار مزار من بیایی.',NULL);
INSERT INTO "verses" VALUES(1933091,2398,8,0,'به هیچ وِردِ دگر نیست حاجت ای حافظ','هوش مصنوعی: به هیچ ذکر دیگری نیازی نیست، ای حافظ؛ دعای نیمه‌شب و آموزش‌های صبحگاهی‌ات کافی است.',NULL);
INSERT INTO "verses" VALUES(1933092,2398,7,1,'رضایِ ایزد و اِنعامِ پادشاهت بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933093,2398,7,0,'به مِنَّتِ دگران خو مَکُن که در دو جهان','هوش مصنوعی: به خودت زحمت نده که برای دیگران مدیون باشی، زیرا در این دو جهان، خشنودی خداوند و نعمت پادشاهی تو کافی است.',NULL);
INSERT INTO "verses" VALUES(1933094,2398,6,1,'ز رهروانِ سفرکرده، عذرخواهت بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933095,2398,6,0,'هوایِ مسکن مألوف و عهدِ یارِ قدیم','هوش مصنوعی: حس و هوای خانه‌ای که برایمان آشناست و یادآوری کردن عهد و قرار با دوست قدیمی، از مسافرانِ سفر کرده، بهانه‌ای مناسب برای توست.',NULL);
INSERT INTO "verses" VALUES(1933096,2398,5,1,'تو اهل فضلی و دانش، همین گناهت بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933097,2398,5,0,'فلک به مَردمِ نادان دهد زِمامِ مراد','هوش مصنوعی: آسمان تقدیر را به دست افراد نادان می‌سپارد، در حالی که تو افرادی با فضیلت و دانش هستی. همین موضوع کافی است تا متوجه شوی که این خود یک نوع اشتباه و عیب است.',NULL);
INSERT INTO "verses" VALUES(1933098,2398,4,1,'صُراحیِ مِیِ لعل و بُتی چو ماهَت بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933099,2398,4,0,'زیادتی مَطَلَب، کار بر خود آسان کن','هوش مصنوعی: بیش از حد به دنبال موضوعات مختلف نرو، کار را برای خود ساده کن. همچون جام شراب خوش‌رنگ و بت زیبایی که همچون ماه درخشان است، لذت ببر.',NULL);
INSERT INTO "verses" VALUES(1933100,2398,3,1,'که این قَدَر ز جهان، کسبِ مال و جاهَت بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933101,2398,3,0,'به صَدرِ مِصْطَبه بنشین و ساغرِ مِی‌ نوش','هوش مصنوعی: بر روی سکو نشسته و جام شراب بنوش که به این اندازه از دنیا، کسب ثروت و مقام کافی است.',NULL);
INSERT INTO "verses" VALUES(1933102,2398,2,1,'حریمِ درگهِ پیرِ مغان، پناهت بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933103,2398,2,0,'وگر کمین بِگُشایَد غمی ز گوشهٔ دل','هوش مصنوعی: اگر نگرانی‌ها و غم‌ها برطرف شوند، در دل حریم و جایگاه پیر مغان، پناهی برای تو وجود خواهد داشت.',NULL);
INSERT INTO "verses" VALUES(1933104,2398,1,1,'که سِیرِ معنوی و کُنجِ خانقاهت بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933105,2398,1,0,'دگر ز منزلِ جانان سفر مَکُن درویش','هوش مصنوعی: به مسافر عزیز توصیه می‌شود که از سفر به منزل محبوب خود خودداری کند، چرا که راه‌پیمایی معنوی و آرامش در خانقاه برای او کافی است.',NULL);
INSERT INTO "verses" VALUES(1933106,2398,0,1,'نسیمِ روضهٔ شیراز، پیکِ راهت بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933107,2398,0,0,'دلا، رَفیقِ سفر بختِ نیکخواهت بس','هوش مصنوعی: ای دل، همسفر خوشبختی و سرنوشتت باش، که نسیم دل‌انگیز باغ‌های شیراز، پیام‌آور راه توست.',NULL);
INSERT INTO "verses" VALUES(1933108,2397,7,1,'طبعِ چون آب و غزل‌هایِ روان ما را بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933109,2397,7,0,'حافظ از مَشْرَبِ قسمت گِلِه ناانصافیست','هوش مصنوعی: حافظ می‌گوید که ناعدالتی در تقسیم راحتی و نعمت‌ها باعث شده که طبع و شعر او که مانند آب روان است، مورد بی توجهی قرار بگیرد. به عبارت دیگر، او احساس می‌کند که لایق آرامش و زیبایی است، اما این حق به او داده نشده است.',NULL);
INSERT INTO "verses" VALUES(1933110,2397,6,1,'که سرِ کویِ تو از کون و مکان ما را بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933111,2397,6,0,'از درِ خویش خدا را به بهشتم مَفرست','هوش مصنوعی: از در خانه خود خدا را به بهشت نخوان، زیرا که در کوی تو برای ما از هر چیزی با ارزش‌تر است.',NULL);
INSERT INTO "verses" VALUES(1933112,2397,5,1,'دولتِ صحبتِ آن مونسِ جان ما را بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933113,2397,5,0,'یار با ماست، چه حاجت که زیادت طلبیم؟','هوش مصنوعی: دوست کنار ماست، پس چه نیازی به خواسته‌های بیشتر داریم؟ خوشی و نعمت این همراهی برای ما کافی است.',NULL);
INSERT INTO "verses" VALUES(1933114,2397,4,1,'گر شما را نه بس این سود و زیان ما را بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933115,2397,4,0,'نقدِ بازارِ جهان بِنگر و آزارِ جهان','هوش مصنوعی: به اوضاع و احوال دنیا دقت کن و مشکلاتی که در آن وجود دارد. اگر این نفع و ضرر شما را راضی نمی‌کند، برای ما همین کافی است.',NULL);
INSERT INTO "verses" VALUES(1933116,2397,3,1,'کاین اشارت ز جهانِ گذران، ما را بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933117,2397,3,0,'بنشین بر لبِ جوی و گذرِ عمر ببین','هوش مصنوعی: در کنار جوی آب بنشین و به گذر زمان نگاه کن؛ این نشانه‌ای از دنیای زودگذر است و برای ما کافی است.',NULL);
INSERT INTO "verses" VALUES(1933118,2397,2,1,'ما که رندیم و گدا، دیرِ مُغان ما را بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933119,2397,2,0,'قصرِ فردوس به پاداشِ عمل می‌بخشند','هوش مصنوعی: به خاطر کارهای خوب، به انسان‌ها قصرهای بهشتی می‌دهند، اما ما که آدم‌های بی‌پروا و نیازمندیم، برای ما همین محیط ساده و مودبانه‌ی میخانه کافی است.',NULL);
INSERT INTO "verses" VALUES(1933120,2398,8,1,'دعایِ نیمْ‌شب و درسِ صبحگاهت بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933121,2399,0,0,'دردِ عشقی کشیده‌ام که مَپُرس','هوش مصنوعی: من در عشق دچار زخم‌های عمیق شده‌ام که نیاویز بپرسی و از تلخی جدایی تجربه‌هایی داشته‌ام که باز هم نیاویز سوال کنی.',NULL);
INSERT INTO "verses" VALUES(1933122,2399,0,1,'زهرِ هجری چشیده‌ام که مَپُرس',NULL,NULL);
INSERT INTO "verses" VALUES(1933123,2399,1,0,'گشته‌ام در جهان و آخرِ کار','هوش مصنوعی: من در دنیا بسیار سفر کرده‌ام و در نهایت به دلبری دست یافته‌ام که هیچ‌کس را از آن باخبر نکن.',NULL);
INSERT INTO "verses" VALUES(1933124,2401,1,1,'ما را دو سه ساغر بده و گو «رمضان باش»',NULL,NULL);
INSERT INTO "verses" VALUES(1933125,2401,0,0,'باز آی و دلِ تنگِ مرا مونس جان باش','هوش مصنوعی: برگرد و مونس دلِ پریشان من باش و به این روح سوخته، رازی‌های پنهان را بشناسان.',NULL);
INSERT INTO "verses" VALUES(1933126,2401,0,1,'وین سوخته را مَحرَمِ اسرارِ نهان باش',NULL,NULL);
INSERT INTO "verses" VALUES(1933127,2400,7,1,'حافظ این قصه دراز است به قرآن که مپرس',NULL,NULL);
INSERT INTO "verses" VALUES(1933128,2400,7,0,'گفتمش زلف به خونِ که شکستی؟ گفتا','هوش مصنوعی: از او پرسیدم که زلف چه کسی را خونین کردی؟ او جواب داد: حافظ، این داستان خیلی طولانی است و به قرآن قسم، نپرسید.',NULL);
INSERT INTO "verses" VALUES(1933129,2400,6,1,'گفت آن می‌کشم اندر خمِ چوگان که مپرس',NULL,NULL);
INSERT INTO "verses" VALUES(1933130,2400,6,0,'گفتم از گویِ فلک صورتِ حالی پرسم','هوش مصنوعی: به ستاره‌ها گفتم که حال و روزم را بپرسم، آن‌ها پاسخ دادند که درگیر بازی و چالش زندگی هستند و بهتر است از من حال من را نپرسی.',NULL);
INSERT INTO "verses" VALUES(1933131,2400,5,1,'شیوه‌ای می‌کند آن نرگسِ فَتّان که مپرس',NULL,NULL);
INSERT INTO "verses" VALUES(1933132,2400,5,0,'پارسایی و سلامت هَوَسم بود، ولی','به زهد ورزی و ایمنی از بلای عشق میل داشتم، اما آن نرگس دیده ی فتنه‌انگیز چنان کرشمه ای میکند و دل میبرد که از حد پرسش فراتر است.',NULL);
INSERT INTO "verses" VALUES(1933133,2400,4,1,'هر کسی عربده‌ای این که مبین آن که مپرس',NULL,NULL);
INSERT INTO "verses" VALUES(1933134,2400,4,0,'گفت‌وگوهاست در این راه که جان بُگْدازد','هوش مصنوعی: این بیت به مفهوم گفت‌وگوها و بحث‌ها در مسیری اشاره دارد که ممکن است در آن، جان انسان فدای امور ظاهری و دنیوی شود. در اینجا، نوید می‌دهد که هر کس فریاد و اعتراض خود را دارد و به نوعی در حال ابراز وجود است، اما نباید به آنچه از دیگران می‌پرسند یا ادعا می‌کنند توجه کرد. در واقع، باید از درون خود پیگیر حقیقت و معنا بود و در عین حال، دقت کرد که افکار و عقاید دیگران انسان را به انحراف نبرد.',NULL);
INSERT INTO "verses" VALUES(1933135,2400,3,1,'دل و دین می‌برد از دست بدان سان که مپرس',NULL,NULL);
INSERT INTO "verses" VALUES(1933136,2400,3,0,'زاهد از ما به سلامت بگذر کـ‌این مِیِ لعل','هوش مصنوعی: ای زاهد، از ما با سلامت بگذر، زیرا این میِ سرخ رنگ جان و دین را از دست می‌برد، بنابراین نپرس که چگونه.',NULL);
INSERT INTO "verses" VALUES(1933137,2400,2,1,'زحمتی می‌کشم از مردمِ نادان که مپرس',NULL,NULL);
INSERT INTO "verses" VALUES(1933138,2397,1,1,'از گرانانِ جهان، رَطلِ گران ما را بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933139,2400,2,0,'به یکی جرعه که آزارِ کَسَش در پِی نیست','هوش مصنوعی: من برای یک جرعه‌ی خوشی که برای کسی دردسر ایجاد نمی‌کند، زحمتی می‌کشم از مردم جاهل، پس از آنها چیزی نپرس.',NULL);
INSERT INTO "verses" VALUES(1933140,2400,1,0,'کَس به امّیدِ وفا ترکِ دل و دین مَکُناد','هوش مصنوعی: هیچ‌کس به امید وفای دیگران، دل و ایمان خود را ترک نکند، زیرا من از اینکه چنین کرده‌ام، آن‌قدر پشیمانم که نپرسید.',NULL);
INSERT INTO "verses" VALUES(1933141,2400,0,1,'که چُنان ز او شده‌ام بی سر و سامان که مَپُرس',NULL,NULL);
INSERT INTO "verses" VALUES(1933142,2400,0,0,'دارم از زلفِ سیاهش گِلِه چندان که مَپُرس','هوش مصنوعی: من از زلف سیاه او چنان گلایه‌مندم که نپرس. چون به قدری از او بی‌قرار و آشفته‌ام که واقعا نمی‌توانی بپرسی.',NULL);
INSERT INTO "verses" VALUES(1933143,2399,6,1,'به مَقامی رسیده‌ام که مپرس',NULL,NULL);
INSERT INTO "verses" VALUES(1933144,2399,6,0,'همچو حافظ غریب در رَهِ عشق','هوش مصنوعی: در مسیر عشق، به مرحله‌ای رسیده‌ام که نمی‌توانی از آن بپرسی، مانند حافظ که ناگهان احساس غریبی دارد.',NULL);
INSERT INTO "verses" VALUES(1933145,2399,5,1,'رنج‌هایی کشیده‌ام که مپرس',NULL,NULL);
INSERT INTO "verses" VALUES(1933146,2399,5,0,'بی تو در کلبهٔ گداییِ خویش','هوش مصنوعی: بدون تو در خانهٔ فقیرانه‌ام دردهایی را تحمل کرده‌ام که نمی‌توانی تصور کنی.',NULL);
INSERT INTO "verses" VALUES(1933147,2399,4,1,'لبِ لعلی گَزیده‌ام که مپرس',NULL,NULL);
INSERT INTO "verses" VALUES(1933148,2399,4,0,'سویِ من لب چه می‌گَزی که مگوی','هوش مصنوعی: چرا به طرف من می‌آیی و چیزی نمی‌گویی؟ من لبان زیبا و دلنشینی را بوسیده‌ام که بهتر است از آن سوال نکنی.',NULL);
INSERT INTO "verses" VALUES(1933149,2399,3,1,'سخنانی شنیده‌ام که مپرس',NULL,NULL);
INSERT INTO "verses" VALUES(1933150,2399,3,0,'من به گوشِ خود از دهانش دوش','هوش مصنوعی: من به طور مستقیم از خودش سخنانی را شنیده‌ام که بهتر است از آنها سوال نکنی.',NULL);
INSERT INTO "verses" VALUES(1933151,2399,2,1,'می‌رود آبِ دیده‌ام که مپرس',NULL,NULL);
INSERT INTO "verses" VALUES(1933152,2399,2,0,'آن چنان در هوایِ خاکِ دَرَش','چنان اشک‌هایم به یاد آن یار جاری است که هیچ چیزی نمی‌تواند این احساس را توصیف کند.',NULL);
INSERT INTO "verses" VALUES(1933153,2399,1,1,'دلبری برگزیده‌ام که مپرس',NULL,NULL);
INSERT INTO "verses" VALUES(1933154,2400,1,1,'که چُنانم من از این کرده پشیمان که مپرس',NULL,NULL);
INSERT INTO "verses" VALUES(1933155,2393,2,1,'بر رخِ او نظر از آینهٔ پاک انداز',NULL,NULL);
INSERT INTO "verses" VALUES(1933156,2397,1,0,'من و همصحبتیِ اهلِ ریا دورَم باد','هوش مصنوعی: من و افرادی که فقط ظاهر را می‌بینند و به حقیقت توجه نمی‌کنند، فاصله داریم. برای ما، زندگی ساده و بی‌دردسر با چیزهای کم ارزش کافی است و نیازی به دنیا و زرق و برق‌های آن نداریم.',NULL);
INSERT INTO "verses" VALUES(1933157,2397,0,0,'گُلعِذاری ز گلستانِ جهان ما را بس','هوش مصنوعی: ما از گلستانی که در دنیا داریم، فقط به همین گل براق اکتفا می‌کنیم، و به تهدیدهای آن سرو بلند از چمن اکتفا داریم.',NULL);
INSERT INTO "verses" VALUES(1933158,2394,8,0,'در قلم آورد حافظ قصهٔ لَعلِ لَبَش','هوش مصنوعی: حافظ داستان گرانبهایی را نوشته است، اما هر لحظه از نوشته‌هایش، جان و حیات آغازین خود را از دست می‌دهد و به تدریج محو می‌شود.',NULL);
INSERT INTO "verses" VALUES(1933159,2394,8,1,'آب حیوان می‌رود هر دَم ز اقلامم هنوز',NULL,NULL);
INSERT INTO "verses" VALUES(1933160,2394,7,0,'ای که گفتی جان بده تا باشَدَت آرامِ جان','هوش مصنوعی: ای کسی که گفتی جانت را فدای من کن تا آرامش یابی، من جانم را به غم‌های تو سپردم، اما هنوز آرامشی ندارم.',NULL);
INSERT INTO "verses" VALUES(1933161,2394,7,1,'جان به غم‌هایش سپردم، نیست آرامم هنوز',NULL,NULL);
INSERT INTO "verses" VALUES(1933162,2394,6,0,'در ازل داده‌ست ما را ساقیِ لعلِ لبت','هوش مصنوعی: در آغاز، ساقی با لب‌های قرمز خود به ما جرعه‌ای از شراب داد که من هنوز تحت‌تأثیر آن شراب هستم و مدهوش آن لحظه‌ام.',NULL);
INSERT INTO "verses" VALUES(1933163,2394,6,1,'جرعهٔ جامی که من مَدهوشِ آن جامم هنوز',NULL,NULL);
INSERT INTO "verses" VALUES(1933164,2394,5,0,'نام من رفته‌ست روزی بر لبِ جانان به سَهو','هوش مصنوعی: روزی نام من به طور اتفاقی بر زبان محبوبم آمده است و هنوز هم بوی جان و روح را به دل‌سوزان می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1933165,2394,5,1,'اهلِ دل را بویِ جان می‌آید از نامم هنوز',NULL,NULL);
INSERT INTO "verses" VALUES(1933166,2394,4,0,'پرتوِ رویِ تو تا در خلوتم دید آفتاب','هوش مصنوعی: نور روی تو در تنهایی‌ام دیده می‌شود، هر لحظه مانند سایه‌ای که بر در و بامم می‌افتد، آفتاب می‌رود.',NULL);
INSERT INTO "verses" VALUES(1933167,2394,4,1,'می‌رود چون سایه هر دَم، بر در و بامم هنوز',NULL,NULL);
INSERT INTO "verses" VALUES(1933168,2394,3,0,'از خطا گفتم شبی زلفِ تو را مُشکِ خُتَن','هوش مصنوعی: شبی، به اشتباه گفتم که زلف تو بوی مشک را می‌دهد، اما هر لحظه تیغی از موهای تو بر بدنم می‌زند و هنوز هم احساس می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1933169,2394,3,1,'می‌زند هر لحظه تیغی مو بر اندامم هنوز',NULL,NULL);
INSERT INTO "verses" VALUES(1933170,2394,2,0,'ساقیا یک جرعه‌ای زان آبِ آتش‌گون که من','هوش مصنوعی: ای ساقی، یک جرعه از آن آبی که رنگش شبیه به آتش است به من بده، چرا که من هنوز در میان عاشقان او ناپخته و خام هستم.',NULL);
INSERT INTO "verses" VALUES(1933171,2394,2,1,'در میانِ پُختگانِ عشقِ او خامم هنوز',NULL,NULL);
INSERT INTO "verses" VALUES(1933172,2394,1,0,'روز اول رفت دینم در سرِ زلفین تو','هوش مصنوعی: در روز اول، عشق تو تمام وجودم را در بر گرفت و نمی‌دانم این داستان عشق به کجا خواهد انجامید و سرانجام من چه خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1933173,2394,1,1,'تا چه خواهد شد در این سودا سرانجامم هنوز',NULL,NULL);
INSERT INTO "verses" VALUES(1933174,2394,0,0,'برنیامد از تمنّایِ لَبَت کامم هنوز','هوش مصنوعی: هنوز از آرزوی می و خوشی تو به خواسته‌ام نرسیده‌ام و همچنان در انتظار جرعه‌ای از شراب لعل رنگ تو هستم.',NULL);
INSERT INTO "verses" VALUES(1933175,2394,0,1,'بر امید جامِ لعلت دُردی‌آشامم هنوز',NULL,NULL);
INSERT INTO "verses" VALUES(1933176,2393,8,1,'وین قبا در رَهِ آن قامتِ چالاک انداز',NULL,NULL);
INSERT INTO "verses" VALUES(1933177,2393,8,0,'چون گُل از نَکهَتِ او جامه قبا کن حافظ','همچون گل، از نسیم عطر خوش یار، گریبان چاک کن ای حافظ، و جامه را در پای آن سرو روان بینداز. (جامه قبا کردن‌: گریبان چاک کردن)',NULL);
INSERT INTO "verses" VALUES(1933178,2393,7,1,'دودِ آهیش در آیینهٔ اِدراک انداز',NULL,NULL);
INSERT INTO "verses" VALUES(1933179,2393,7,0,'یا رب آن زاهدِ خودبین که به جز عیب ندید','خدایا آن زاهد خودپرست که جز عیب‌جویی کاری نکرد ( و دل‌ها را شکست) دود یک آه (دل‌شکستگان) را در آینه ادراک او بینداز.',NULL);
INSERT INTO "verses" VALUES(1933180,2393,6,1,'پاک شو اول و پس دیده بر آن پاک انداز',NULL,NULL);
INSERT INTO "verses" VALUES(1933181,2393,6,0,'غسل در اشک زدم کَاهلِ طریقت گویند','چشمانم را با اشک‌، غسل دادم و پاک‌کردم زیرا اهل سلوک و طریقت می‌گویند اول پاک شو، سپس لایق دیدار شو.',NULL);
INSERT INTO "verses" VALUES(1933182,2393,5,1,'آتشی از جگرِ جام، در املاک انداز',NULL,NULL);
INSERT INTO "verses" VALUES(1933183,2393,5,0,'مُلکِ این مزرعه دانی که ثباتی ندهد','خود می‌دانی که این دنیا بی‌وفاست و پایدار نیست؛ پس عمر را صرف شادی و می‌گساری کن.',NULL);
INSERT INTO "verses" VALUES(1933184,2393,4,1,'از لبِ خود به شفاخانهٔ تریاک انداز',NULL,NULL);
INSERT INTO "verses" VALUES(1933185,2393,4,0,'دلِ ما را که ز مارِ سرِ زلفِ تو بِخَست','سر زلف بافته تو همچون مار، دل ما را زخمی‌کرد پس با بوسه‌ای (یا کلامی) ما را شفا ببخش.',NULL);
INSERT INTO "verses" VALUES(1933186,2393,3,1,'ناز از سَر بِنِه و سایه بر این خاک انداز',NULL,NULL);
INSERT INTO "verses" VALUES(1933187,2395,0,0,'دلم رمیدهٔ لولی‌وَشیست شورانگیز','هوش مصنوعی: دل من از شخصی که جذاب و سرمست‌کننده است و وعده‌های دروغ و رفتارهای مکارانه‌اش به شدت آشفته و نگران است.',NULL);
INSERT INTO "verses" VALUES(1933188,2395,0,1,'دروغ‌وَعده و قَتّال‌وَضع و رنگ‌آمیز',NULL,NULL);
INSERT INTO "verses" VALUES(1933189,2395,1,0,'فدایِ پیرهنِ چاکِ ماهرویان باد','هوش مصنوعی: فدای پیراهن پاره و زیبای دختران ماهرو شوم، حتی اگر برای این کار هزار لباس پرهیز و تقوا داشته باشم.',NULL);
INSERT INTO "verses" VALUES(1933190,2395,1,1,'هزار جامهٔ تقوی و خرقهٔ پرهیز',NULL,NULL);
INSERT INTO "verses" VALUES(1933191,2396,8,1,'از جنابِ حضرتِ شاهم بس است این مُلتَمَس',NULL,NULL);
INSERT INTO "verses" VALUES(1933192,2396,8,0,'نامِ حافظ گر برآید بر زبانِ کِلکِ دوست','هوش مصنوعی: اگر نام حافظ از زبان دوست بگذرد و به حضرت شاه برسد، همین برای من کافی است.',NULL);
INSERT INTO "verses" VALUES(1933193,2396,7,1,'و از تَحَسُّر دست بر سر می‌زند مسکین مگس',NULL,NULL);
INSERT INTO "verses" VALUES(1933194,2396,7,0,'طوطیان در شِکَّرِستان کامرانی می‌کنند','هوش مصنوعی: در سرزمین شیرین، طوطیان خوشحال و راضی هستند، اما مگس بیچاره از حسرت و غصه سرش را به دیوار می‌کوبد.',NULL);
INSERT INTO "verses" VALUES(1933195,2396,6,1,'گر چه هشیاران ندادند اختیارِ خود به کس',NULL,NULL);
INSERT INTO "verses" VALUES(1933196,2396,6,0,'دل به رَغبت می‌سپارد جان به چشمِ مستِ یار','هوش مصنوعی: دل با میل و اشتیاق خود را به معشوق می‌سپارد و جانش را به چشمان زیبای او می‌دهد، هرچند که افراد آگاه به این راحتی اختیار خود را به کسی نمی‌دهند.',NULL);
INSERT INTO "verses" VALUES(1933197,2396,5,1,'زان که گویِ عشق نَتْوان زد به چوگانِ هوس',NULL,NULL);
INSERT INTO "verses" VALUES(1933198,2396,5,0,'عشق‌بازی کارِ بازی نیست ای دل! سر بِباز','هوش مصنوعی: ای دل! عشق بازی کردن کار ساده‌ای نیست. باید به دقت و با آگاهی عمل کنی، چرا که عشق مثل میدانی است که نمی‌توان آن را با هوس و تمایلات سطحی بازی کرد.',NULL);
INSERT INTO "verses" VALUES(1933199,2396,4,1,'شَب‌رُوان را آشنایی‌هاست با میرِ عَسَس',NULL,NULL);
INSERT INTO "verses" VALUES(1933200,2396,4,0,'عشرتِ شب‌گیر کن، مِی نوش کاندر راهِ عشق','هوش مصنوعی: در شب‌های پرشکوه، به خوشی و شادی بپرداز و می بنوش، زیرا در مسیر عشق، شب‌زنده‌داران با حال و هوای خود، تجارب و آشنایی‌های ویژه‌ای دارند که به خوبی با آن آشنا هستند.',NULL);
INSERT INTO "verses" VALUES(1933201,2396,3,1,'گوش‌مالی دیدم از هجران که اینم پند بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933202,2396,3,0,'من که قولِ ناصحان را خواندَمی قولِ رَباب','هوش مصنوعی: من نظرات مشاوران را شنیده‌ام، اما اینقدر درد و رنج ناشی از جدایی را تجربه کرده‌ام که این خود، بزرگ‌ترین درس برای من است.',NULL);
INSERT INTO "verses" VALUES(1933203,2396,2,1,'کز فِراقت سوختم ای مهربان فریاد رس',NULL,NULL);
INSERT INTO "verses" VALUES(1933204,2396,2,0,'مَحمِلِ جانان ببوس، آن‌گه به زاری عَرضه دار','هوش مصنوعی: با عشق و محبت، آن محبوب را ببوس و سپس با دل‌تنگی و ناله بگو که از جدایی‌ات می‌سوزم و ای مهربان، به فریاد من برس.',NULL);
INSERT INTO "verses" VALUES(1933205,2397,0,1,'زین چمن سایهٔ آن سروِ روان ما را بس',NULL,NULL);
INSERT INTO "verses" VALUES(1933206,2396,1,1,'پُر صدایِ ساربانان بینی و بانگِ جرس',NULL,NULL);
INSERT INTO "verses" VALUES(1933207,2396,0,1,'بوسه زن بر خاکِ آن وادی و مُشکین کُن نَفَس',NULL,NULL);
INSERT INTO "verses" VALUES(1933208,2396,0,0,'ای صبا گر بُگذری بر ساحلِ رودِ اَرَس','ای نسیم صبا، اگر از کنار رود ارس عبور کردی، بر خاک آن سرزمین بوسه بزن و نفس خودت را از هوای آنجا عطرآگین کن',NULL);
INSERT INTO "verses" VALUES(1933209,2395,7,1,'تو خود حجابِ خودی حافظ از میان برخیز',NULL,NULL);
INSERT INTO "verses" VALUES(1933210,2395,7,0,'میانِ عاشق و معشوق هیچ حائل نیست','هوش مصنوعی: بین عاشق و محبوب هیچ مانعی وجود ندارد، اما تو خود، موانع وجودی‌ات هستی. حافظ، از این حجاب‌ها و بی‌خودیت فاصله بگیر.',NULL);
INSERT INTO "verses" VALUES(1933211,2395,6,1,'که در مَقامِ رضا باش و از قَضا مَگریز',NULL,NULL);
INSERT INTO "verses" VALUES(1933212,2395,6,0,'بیا که هاتفِ میخانه دوش با من گفت','هوش مصنوعی: بیا که دیروز صدای میخانه به من گفت که در حالت آرامش و رضا قرار بگیر و از سرنوشت فرار نکن.',NULL);
INSERT INTO "verses" VALUES(1933213,2395,5,1,'که جز وِلایِ تواَم نیستْ هیچْ دست آویز',NULL,NULL);
INSERT INTO "verses" VALUES(1933214,2395,5,0,'فقیر و خسته به درگاهت آمدم رحمی','هوش مصنوعی: من به درگاه تو آمدم، در حالی که خسته و بی‌چاره‌ام. تنها چیزی که به آن امیدوارم، محبت و ولایت توست و هیچ چیز دیگری به کمکم نمی‌آید.',NULL);
INSERT INTO "verses" VALUES(1933215,2395,4,1,'به مِی ز دل بِبَرَم هولِ روزِ رستاخیز',NULL,NULL);
INSERT INTO "verses" VALUES(1933216,2395,4,0,'پیاله بر کفنم بند، تا سحرگهِ حَشر','هوش مصنوعی: پیاله‌ای را کنار قبرم بگذارید، تا در صبح قیامت با نوشیدن شراب، از نگرانی روز رستاخیز رهایی یابم.',NULL);
INSERT INTO "verses" VALUES(1933217,2395,3,1,'بِخواه جام و گلابی به خاکِ آدم ریز',NULL,NULL);
INSERT INTO "verses" VALUES(1933218,2395,3,0,'فرشته عشق نداند که چیست، ای ساقی','هوش مصنوعی: فرشته‌ای که نماد عشق است، نمی‌داند عشق چه احساسی دارد. ای ساقی، لطفا یک جام و کمی گلاب به زمین بریز.',NULL);
INSERT INTO "verses" VALUES(1933219,2395,2,1,'که تا ز خالِ تو خاکم شود عَبیرآمیز',NULL,NULL);
INSERT INTO "verses" VALUES(1933220,2395,2,0,'خیالِ خالِ تو با خود به خاک خواهم برد','هوش مصنوعی: با خود تصویری از خال تو را به خاک می‌برم، تا اینکه به خاطر این خال، خاک من شود آمیخته به عطر و یاد تو.',NULL);
INSERT INTO "verses" VALUES(1933221,2396,1,0,'منزلِ سَلمی که بادَش هر دَم از ما صد سلام','خانه‌ی معشوق که هر لحظه از آن ما صد سلام بر آنجا باشد پرشور و به رونق است وصدای زنگ قافله ها در هر لحظه به گوش میرسد',NULL);
INSERT INTO "verses" VALUES(1933222,2511,6,0,'آن که مُدام شیشه‌ام از پِی عیش داده اَست','هوش مصنوعی: شخصی که به‌طور مداوم مرا به خوش‌گذرانی دعوت می‌کند، چرا همیشه باید برای درمان به پزشک مراجعه کنم؟',NULL);
INSERT INTO "verses" VALUES(1933223,2417,5,1,'که مستی می‌کند با عقل و می‌بخشد خُماری خوش',NULL,NULL);
INSERT INTO "verses" VALUES(1933224,2417,6,1,'که شنگولانِ خوش باشت، بیاموزند کاری خوش',NULL,NULL);
INSERT INTO "verses" VALUES(1933225,2439,5,1,'عاقبت دانهٔ خالِ تو فِکَندَش در دام',NULL,NULL);
INSERT INTO "verses" VALUES(1933226,2439,5,0,'مرغِ روحم که همی‌زد ز سرِ سِدره صَفیر','هوش مصنوعی: پرنده روح من که از درختی بلند با صدای دل‌انگیز آواز می‌خواند، در نهایت به دانه‌ای از محبت و زیبایی تو گرفتار شد.',NULL);
INSERT INTO "verses" VALUES(1933227,2439,4,1,'برو ای شیخ که شد بر تنِ ما خرقه حرام',NULL,NULL);
INSERT INTO "verses" VALUES(1933228,2439,4,0,'زلفِ دلدار چو زُنّار همی‌فرماید','هوش مصنوعی: زلف معشوق مانند زنجیری است که می‌گوید ای شیخ، برو و از ما فاصله بگیر، زیرا اکنون لباس روحانی ما به خاطر عشق تو ممنوع شده است.',NULL);
INSERT INTO "verses" VALUES(1933229,2439,3,1,'سرو می‌نازد و خوش نیست خدا را بخرام',NULL,NULL);
INSERT INTO "verses" VALUES(1933230,2439,3,0,'گل ز حَد بُرد تَنَعُّم نفسی رخ بنما','هوش مصنوعی: گل به حدی از زیبایی و لطافت رسیده است که نفس من از شگفتی بی‌خبر مانده است. سرو به خوش‌حالی خود می‌نازد و این حال خوش به خدا نیز خوش نمی‌آید، پس بگذار که در این دنیای زیبا قدم بزنم.',NULL);
INSERT INTO "verses" VALUES(1933231,2439,2,1,'هر چه آغاز ندارد نپذیرد انجام',NULL,NULL);
INSERT INTO "verses" VALUES(1933232,2439,2,0,'ماجرایِ من و معشوقِ مرا پایان نیست','هوش مصنوعی: ماجرای من و محبوبم همچنان ادامه دارد و هر چیزی که شروعی نداشته باشد، نمی‌تواند پایانی داشته باشد.',NULL);
INSERT INTO "verses" VALUES(1933233,2439,1,1,'که از او خصم به دام آمد و معشوقه به کام',NULL,NULL);
INSERT INTO "verses" VALUES(1933234,2439,1,0,'یا رب این قافله را لطفِ ازل بدرقه باد','هوش مصنوعی: پروردگارا، امیدوارم که این کاروان به لطف و رحمت تو همراه باشد، چرا که دشمنان به دام افتاده و عشق به دست آمده است.',NULL);
INSERT INTO "verses" VALUES(1933235,2439,0,1,'خیرِ مقدم چه خبر؟ دوست کجا؟ راه کدام؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933236,2439,0,0,'مرحبا طایرِ فَرُّخ پِیِ فرخنده پیام','هوش مصنوعی: سلام و درود بر پرنده‌ی خوشبختی! چه خوشحالم که به اینجا آمدی. خبرهای خوش را به همراه خود آورده‌ای. دوست کجاست؟ مسیر کدام است؟',NULL);
INSERT INTO "verses" VALUES(1933237,2438,8,1,'وان که این مجلس نجوید زندگی بر وی حرام',NULL,NULL);
INSERT INTO "verses" VALUES(1933238,2438,8,0,'هر که این عِشرت نخواهد خوش‌دلی بر وی تباه','هوش مصنوعی: هر کس که این خوشی و شادی را نخواهد، زندگی شاد و خوش‌دل بودن برای او نابود می‌شود. و آن کسی که به این مجلس و جمع‌بودن در کنار دیگران رغبت نداشته باشد، زندگی برای او حرام خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1933239,2438,7,1,'بخشش‌آموزی جهان‌افروز چون حاجی قوام',NULL,NULL);
INSERT INTO "verses" VALUES(1933240,2438,7,0,'نکته‌دانی بَذله‌گو چون حافظِ شیرین‌‌سخن','هوش مصنوعی: شخصی با دانایی و شوخ‌طبعی مانند حافظ، که سخنان دلنشینی دارد، می‌تواند چیزی را به دیگران بیاموزد. همچنین، فردی مانند حاجی قوام که روشنفکر و بخشنده است، می‌تواند به گسترش دانش و نور در دنیا کمک کند.',NULL);
INSERT INTO "verses" VALUES(1933241,2438,6,1,'زلفِ جانان از برایِ صیدِ دل گسترده‌دام',NULL,NULL);
INSERT INTO "verses" VALUES(1933242,2438,6,0,'غمزهٔ ساقی به یَغمایِ خِرَد آهِخته تیغ','هوش مصنوعی: نگاه و ناز ساقی، مانند فریبنده‌ای است که عقل و تدبیر را از انسان می‌رباید. تیغ موهای محبوب مانند دام‌گستری است که برای به دام انداختن دل‌ها پهن شده است.',NULL);
INSERT INTO "verses" VALUES(1933243,2438,5,1,'نُقلَش از لَعلِ نگار و نَقلَش از یاقوتِ خام',NULL,NULL);
INSERT INTO "verses" VALUES(1933244,2438,5,0,'بادهٔ گلرنگِ تلخِ تیزِ خوش‌خوارِ سَبُک','هوش مصنوعی: این شعر به توصیف نوشیدنی‌ای با رنگ گل مانند و طعم تلخ و تند می‌پردازد که به راحتی مصرف می‌شود. در این نوشیدنی، شباهت به زیبایی و ارزش‌های نگار و سنگ‌های قیمتی مانند یاقوت دیده می‌شود. به طور کلی، شاعر در این بیت به زیبایی و لذت‌های دنیوی اشاره می‌کند.',NULL);
INSERT INTO "verses" VALUES(1933245,2438,4,1,'دوست‌داران صاحب‌اسرار و حریفان دوست‌کام',NULL,NULL);
INSERT INTO "verses" VALUES(1933246,2438,4,0,'صف‌نشینان نیک‌خواه و پیشکاران باادب','هوش مصنوعی: در این متن به افرادی اشاره شده است که در صفوفی منظم و با نیت نیک، به خدمت مشغولند و ادب را رعایت می‌کنند. این افراد دوستانی هستند که به رازها و اسرار یکدیگر احترام می‌گذارند و همگی به دنبال خوشبختی و رسیدن به اشتراکات مثبت هستند.',NULL);
INSERT INTO "verses" VALUES(1933247,2438,3,1,'گلشنی پیرامُنَش چون روضهٔ دارُالسَّلام',NULL,NULL);
INSERT INTO "verses" VALUES(1933248,2438,3,0,'بَزم‌گاهی دل‌نِشان، چون قصرِ فردوسِ بَرین','هوش مصنوعی: محل نشستن دل، مانند کاخ بهشتی است و دور آن مانند باغی است که در آن آرامش و سلامتی وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1933249,2438,2,1,'دلبری در حُسن و خوبی غیرتِ ماهِ تمام',NULL,NULL);
INSERT INTO "verses" VALUES(1933250,2438,2,0,'شاهدی از لطف و پاکی رَشکِ آبِ زندگی','هوش مصنوعی: شاهدی که با زیبایی و پاکی‌اش دیگران را تحت تأثیر قرار می‌دهد، مانند آبی است که زندگی را به وجود می‌آورد. این معشوق در زیبایی و خوبی به قدری استثنائی است که حتی ماه کامل نیز از غیرت آن خجالت می‌کشد.',NULL);
INSERT INTO "verses" VALUES(1933251,2438,1,1,'همنشینی نیک‌کردار و ندیمی نیک‌نام',NULL,NULL);
INSERT INTO "verses" VALUES(1933252,2438,1,0,'ساقیِ شِکَّردهان و مُطربِ شیرین‌سخن','هوش مصنوعی: ای ساقی با لب‌های شکرین و ای نوازنده‌ای با سخنان دل‌نشین، همنشینی با کسی که نیکو رفتار است و دوستی که نام نیکو دارد، بسیار پسندیده است.',NULL);
INSERT INTO "verses" VALUES(1933253,2438,0,1,'مجلسِ اُنس و حریفِ همدم و شُربِ مدام',NULL,NULL);
INSERT INTO "verses" VALUES(1933254,2439,6,0,'چشمِ بیمارِ مرا خواب نه در خور باشد','هوش مصنوعی: چشم بیمار من نمی‌تواند خواب خوبی داشته باشد. چطور ممکن است کسی که به بیماری مهلک مبتلا است، بخوابد؟',NULL);
INSERT INTO "verses" VALUES(1933255,2438,0,0,'عشقبازیّ و جوانیّ و شرابِ لَعلْ‌فام','هوش مصنوعی: شادی و جوانی و نوشیدن شراب قرمز در جمع دوستان و همصحبتی و نوشیدن مداوم.',NULL);
INSERT INTO "verses" VALUES(1933256,2439,6,1,'من لَهُ یَقتُلُ داءٌ دَنَفٌ کیفَ یَنام؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933257,2439,7,1,'ذاکَ دعوایَ و ها انتَ و تِلکَ الایّام',NULL,NULL);
INSERT INTO "verses" VALUES(1933258,2442,0,0,'بازآی ساقیا که هواخواهِ خدمتم','ای ساقی، دوباره برگرد که من خیلی مشتاق خدمتم و به دیانت و دعاگوییِ تو نیاز دارم.',NULL);
INSERT INTO "verses" VALUES(1933259,2441,6,1,'حافظ بخورد باده و شیخ و فقیه هم',NULL,NULL);
INSERT INTO "verses" VALUES(1933260,2441,6,0,'ساقی چو یارِ مَه رخ و از اهلِ راز بود','چون که ساقی دوست و یار زیبا روی و از دانایان سرّ بود ، هم حافظ را شراب داد و هم شیخ و هم فقیه را',NULL);
INSERT INTO "verses" VALUES(1933261,2441,5,1,'الآنَ قَد نَدِمتَ و ما یَنفَعُ النَّدَم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933262,2441,5,0,'در نیلِ غم فُتاد؛ سپهرش به طنز گفت','وقتی در رودخانهٔ غم افتاد ، آسمان با طنز و طعنه به او گفت: اکنون که پشیمان شدی ، دیگر پشیمانی چه فایده‌ای دارد؟',NULL);
INSERT INTO "verses" VALUES(1933263,2441,4,1,'جز دیده‌اش مُعاینه بیرون نداد نَم',NULL,NULL);
INSERT INTO "verses" VALUES(1933264,2441,4,0,'می‌جست از سحابِ اَمل رحمتی ولی','از ابر رحمتِ حق ، امیدی طلب میکرد(که مثل بارانِ رحمت ببارد) ولی _ چیزی که نصیبش شد این بود که چشمهای خودش پر اشک شد(دعا کننده مورد رحمت قرار گرفت ولی خودش از این موضوع بی‌خبر بود)',NULL);
INSERT INTO "verses" VALUES(1933265,2441,3,1,'انَّ العُهودَ عِندَ مَلیکِ النُّهی ذِمَم',NULL,NULL);
INSERT INTO "verses" VALUES(1933266,2441,3,0,'پیمان شکن هرآینه گَردَد شکسته حال','پیمان‌شکن بی‌گمان هر لحظه ، شکسته‌حال و خوار می‌گردد، چرا که وفای به عهد و پیمان‌ نزد خداوندِ صاحب اختیار ، (مسئولیتی مقدس و) واجب‌ است... اشاره به آیهٔ «وَأَوْفُوا بِالْعَهْدِ إِنَّ الْعَهْدَ کَانَ مَسْئُولًا» (سوره اسراء، آیه ۳۴)',NULL);
INSERT INTO "verses" VALUES(1933267,2441,2,1,'آهنگِ خصم او به سراپردهٔ عَدَم',NULL,NULL);
INSERT INTO "verses" VALUES(1933268,2441,2,0,'از بازگشتِ شاه در این طُرفِه منزل است','از (مبارکی) قدم شاه است که تا به این منزل قدم گذاشت ؛ دشمن او به سمت نابود شدن و شکست خوردن می‌رود .',NULL);
INSERT INTO "verses" VALUES(1933269,2441,1,1,'تا جان فِشانَمَش چو زر و سیم در قَدَم',NULL,NULL);
INSERT INTO "verses" VALUES(1933270,2441,1,0,'آن خوش خبر کجاست؟ که این فتح، مژده داد','هوش مصنوعی: آن خوشخبر کجاست که پیروزی را به من خبر داد؟ من آماده‌ام جانم را در راهش فدای او کنم، چون زر و سیم در پای او می‌ریزم.',NULL);
INSERT INTO "verses" VALUES(1933271,2441,0,1,'لِلّهِ حمدُ مُعتَرِفٍ غایةَ النِّعَم',NULL,NULL);
INSERT INTO "verses" VALUES(1933272,2441,0,0,'بُشری اِذِ السَّلامةُ حَلَّت بِذی سَلَم','مژده باد (و بسی شکر) که سلامتی به شخص صاحب سلامت باز آمد _ ستایش و سپاس خدایی را سزاست که اقرار میکنیم به نهایت نعمت‌های بی‌کرانش',NULL);
INSERT INTO "verses" VALUES(1933273,2440,5,1,'بو که در بَر کَشَد آن دلبرِ نوخاسته‌ام',NULL,NULL);
INSERT INTO "verses" VALUES(1933274,2440,5,0,'همچو حافظ به خرابات رَوَم جامه قبا','هوش مصنوعی: من هم مثل حافظ به میخانه می‌روم و لباسی می‌پوشم که بوی خوشی داشته باشد، زیرا آنجا معشوق تازه‌کارم را در آغوش می‌کشم.',NULL);
INSERT INTO "verses" VALUES(1933275,2440,4,1,'در غم افزوده‌ام آنچ از دل و جان کاسته‌ام',NULL,NULL);
INSERT INTO "verses" VALUES(1933276,2440,4,0,'با چُنین حیرتم از دست بِشُد صرفهٔ کار','هوش مصنوعی: با این همه شگفتی که دارم، به درد و رنج خود افزوده‌ام و کارم به جایی رسیده که آنچه از دل و جانم کم شده، نتوانسته‌ام جبران کنم.',NULL);
INSERT INTO "verses" VALUES(1933277,2440,3,1,'هم بدین کار کمربسته و برخاسته‌ام',NULL,NULL);
INSERT INTO "verses" VALUES(1933278,2440,3,0,'خوش بسوز از غَمَش ای شمع که اینک من نیز','هوش مصنوعی: شمع عزیز، با دلی پر از غم بسوز و نگران نباش، چون من هم اکنون تصمیم گرفته‌ام که مانند تو با مشکلات کنار بیایم و آماده‌ام تا به این چالش بپردازم.',NULL);
INSERT INTO "verses" VALUES(1933279,2440,2,1,'که بر او وصله به صد شُعبده پیراسته‌ام',NULL,NULL);
INSERT INTO "verses" VALUES(1933280,2440,2,0,'شَرمَم از خرقهٔ آلودهٔ خود می‌آید','هوش مصنوعی: از لباس آلوده‌ام شرم دارم، چرا که به آن بسیار تزیینات بیهوده و زیبا داده‌ام.',NULL);
INSERT INTO "verses" VALUES(1933281,2440,1,1,'تا بدانی که به چندین هنر آراسته‌ام',NULL,NULL);
INSERT INTO "verses" VALUES(1933282,2440,1,0,'عاشق و رِند و نظربازم و می‌گویم فاش','هوش مصنوعی: من عاشق و شیفته و اهل جلوه‌گری هستم و این را به‌طور صریح می‌گویم تا بدانی که با قابلیت‌ها و هنرهای زیادی آراسته شده‌ام.',NULL);
INSERT INTO "verses" VALUES(1933283,2440,0,1,'وز خدا دولتِ این غم به دعا خواسته‌ام',NULL,NULL);
INSERT INTO "verses" VALUES(1933284,2440,0,0,'عاشقِ رویِ جوانی خوشِ نوخاسته‌ام','هوش مصنوعی: من عاشق چهره زیبای جوانی هستم که تازه به بار نشسته و از خدا خواسته‌ام که با دعا کردن، برکت و خوشبختی این غم را به من عطا کند.',NULL);
INSERT INTO "verses" VALUES(1933285,2439,8,1,'جای در گوشهٔ محراب کنند اهلِ کلام',NULL,NULL);
INSERT INTO "verses" VALUES(1933286,2439,8,0,'حافظ ار میل به ابرویِ تو دارد شاید','هوش مصنوعی: اگر حافظ به ابروی تو علاقه‌مند باشد، شاید اهل فضایل و علم در گوشه‌ای از مکانی مقدس برای او جایی بسازند.',NULL);
INSERT INTO "verses" VALUES(1933287,2439,7,0,'تو تَرَحُّم نکنی بر منِ مُخلص گفتم','هوش مصنوعی: اگر بر من که خالصانه و صادقانه به تو عشق ورزیده‌ام ترحم نداشته باشی، پس دعوا و جدال من با تو چه سودی دارد و این روزها چه اهمیتی دارند؟',NULL);
INSERT INTO "verses" VALUES(1933288,2437,7,1,'باد و هر چیزی که باشد زین قَبیل',NULL,NULL);
INSERT INTO "verses" VALUES(1933289,2437,7,0,'شاهِ عالم را بقا و عِزّ و ناز','هوش مصنوعی: ای کاش شاهِ عالم همیشه پایدار و با عزت و زیبایی زندگی کند و هر آنچه لازم است، برایش فراهم آید.',NULL);
INSERT INTO "verses" VALUES(1933290,2437,6,1,'همچو مور افتاده شد در پایِ پیل',NULL,NULL);
INSERT INTO "verses" VALUES(1933291,2435,6,0,'دل از جواهرِ مِهر‌ت چو صیقلی دارد','هوش مصنوعی: دل مانند جواهر عشق تو صاف و درخشان است، و همواره از آلودگی‌ها و سختی‌های زندگی پاک و بی‌نقص خواهد ماند.',NULL);
INSERT INTO "verses" VALUES(1933292,2435,5,1,'که ساخت در دلِ تنگم قرار‌گاهِ نزول',NULL,NULL);
INSERT INTO "verses" VALUES(1933293,2435,5,0,'خراب‌تر ز دلِ من غمِ تو جای نیافت','هوش مصنوعی: غم تو در دل من جایی ندارد و نتوانسته است قرارگاهی در دل کوچک من بیابد.',NULL);
INSERT INTO "verses" VALUES(1933294,2435,4,1,'در آن زمان که به تیغِ غَمَت شَوَم مَقتول',NULL,NULL);
INSERT INTO "verses" VALUES(1933295,2435,4,0,'منِ شکستهٔ بدحال زندگی یابم','وقتی که در اثر درد و رنج‌های زندگی کشته شوم، در آن لحظه است که خودم را به عنوان انسانی شکسته و بدحال می‌یابم.',NULL);
INSERT INTO "verses" VALUES(1933296,2435,3,1,'که گَشته‌ام ز غم و جورِ روزگار مَلول',NULL,NULL);
INSERT INTO "verses" VALUES(1933297,2435,3,0,'کجا رَوَم چه کنم چاره از کجا جویم‌؟','هوش مصنوعی: نمی‌دانم به کجا بروم یا چه تدبیری بیندیشم؛ چون از غم و ظلم زمانه به شدت ناراحت و غمگین شده‌ام.',NULL);
INSERT INTO "verses" VALUES(1933298,2435,2,1,'به هیچ باب ندارم رَهِ خروج و دُخول',NULL,NULL);
INSERT INTO "verses" VALUES(1933299,2435,2,0,'چو بر درِ تو منِ بینوا‌یِ بی زر و زور','هوش مصنوعی: وقتی که درِ تو را می‌زنم، منِ بیچاره و بی‌پول و بی‌قدرت، راهی برای رفتن به درون یا بیرون ندارم.',NULL);
INSERT INTO "verses" VALUES(1933300,2435,1,1,'فَراغ برده ز من آن دو جادو‌یِ مَکحول',NULL,NULL);
INSERT INTO "verses" VALUES(1933301,2435,1,0,'قرار برده ز من آن دو نرگسِ رَعنا','آن دو چشم زیبای سرمه کشیده و جادویی آرامش و صبر و قرار را از من گرفته‌اند',NULL);
INSERT INTO "verses" VALUES(1933302,2435,0,1,'رَسَد، به دولتِ وصلِ تو، کارِ من به اصول',NULL,NULL);
INSERT INTO "verses" VALUES(1933303,2435,0,0,'اگر به کویِ تو باشد مرا مَجالِ وصول','هوش مصنوعی: اگر بتوانم به کوی تو برسم، به هدفی بزرگ دست یافته‌ام، زیرا برای من مهم‌ترین چیز، رسیدن به وصال توست.',NULL);
INSERT INTO "verses" VALUES(1933304,2434,6,1,'ز شعرِ حافظ و آن طَبعِ همچو آب خجِل',NULL,NULL);
INSERT INTO "verses" VALUES(1933305,2434,6,0,'حجابِ ظلمت از آن بست آبِ خضر که گشت','هوش مصنوعی: حجاب تاریکی به خاطر آب خضر به وجود آمده که شعر حافظ و طبع لطیفش، مانند آب، را شرمنده کرده است.',NULL);
INSERT INTO "verses" VALUES(1933306,2434,5,1,'که نیستم ز تو در رویِ آفتاب خجِل',NULL,NULL);
INSERT INTO "verses" VALUES(1933307,2434,5,0,'تویی که خوب‌تری ز آفتاب و شُکرِ خدا','هوش مصنوعی: تو آنقدر زیبا هستی که حتی از آفتاب هم بهتر هستی و از خدا شکر می‌کنم که در برابر زیبایی‌ات خجالت‌زده نیستم.',NULL);
INSERT INTO "verses" VALUES(1933308,2434,4,1,'که شد ز شیوهٔ آن چشمِ پُر عِتاب خجِل',NULL,NULL);
INSERT INTO "verses" VALUES(1933309,2434,4,0,'رواست نرگسِ مست ار فِکند سر در پیش','هوش مصنوعی: اگر نرگس مستی سرش را پایین بیندازد، اشکالی ندارد؛ زیرا از نگاه پر عتاب او، خود را شرمنده و خجالت‌زده می‌بیند.',NULL);
INSERT INTO "verses" VALUES(1933310,2434,3,1,'شدیم در نظر رَهرُوانِ خواب خجِل',NULL,NULL);
INSERT INTO "verses" VALUES(1933311,2434,3,0,'ز خون که رفت شبِ دوش از سراچهٔ چشم','هوش مصنوعی: ما در خواب شب گذشته، از اشک‌هایی که از چشمان‌مان جاری شد به جایی رسیدیم که در آنجا، مسافران خواب شرمنده و خجل به نظر می‌رسیدند.',NULL);
INSERT INTO "verses" VALUES(1933312,2434,2,1,'که از سؤال ملولیم و از جواب خجِل',NULL,NULL);
INSERT INTO "verses" VALUES(1933313,2434,2,0,'بوَد که یار نرنجد ز ما به خُلقِ کریم','هوش مصنوعی: امیدواریم که دوست ما از برخورد نیکو و مهربانی‌امان ناراحت نشود، چون ما از پرسش خسته‌ایم و از پاسخ دادن شرمنده.',NULL);
INSERT INTO "verses" VALUES(1933314,2434,1,1,'نی‌ام ز شاهد و ساقی به هیچ باب خجِل',NULL,NULL);
INSERT INTO "verses" VALUES(1933315,2434,1,0,'صلاحِ ما همه دامِ رَه است و من زین بحث','هوش مصنوعی: ما همه در دامی از راه قرار داریم و من از این گفتگو به هیچ وجه از شواهد و ساقی خجالت‌زده نیستم.',NULL);
INSERT INTO "verses" VALUES(1933316,2434,0,1,'که کَس مباد ز کِردارِ ناصَواب خجِل',NULL,NULL);
INSERT INTO "verses" VALUES(1933317,2434,0,0,'به وقت گُل شدم از توبهٔ شراب خجِل','هوش مصنوعی: در زمان شکوفایی و زیبایی، از میگساری و اشتباهاتم شرمنده شدم، زیرا نمی‌خواهم کسی به خاطر رفتار نادرست من احساس شرمندگی کند.',NULL);
INSERT INTO "verses" VALUES(1933318,2433,8,1,'از بهرِ معیشت مَکُن اندیشهٔ باطل',NULL,NULL);
INSERT INTO "verses" VALUES(1933319,2433,8,0,'حافظ قلمِ شاه جهان مُقسِمِ رزق است','ای حافظ اندیشه ی باطل به دل راه مده و از بندگان خدا چشم داشتی نداشته باش که تقسیم کننده ی رزق و روزی شاه جهان خداوندِ رزّاق است.',NULL);
INSERT INTO "verses" VALUES(1933320,2435,6,1,'بُوَد ز زنگِ حوادث هر آینه مَصقول',NULL,NULL);
INSERT INTO "verses" VALUES(1933321,2435,7,0,'چه جرم کرده‌ام؟ ای جان و دل، به حضرتِ تو','هوش مصنوعی: من چه خطایی مرتکب شده‌ام؟ ای عشق و زندگی من، از آن‌جایی که اطاعت و عبادت من برای تو مورد قبول نیست.',NULL);
INSERT INTO "verses" VALUES(1933322,2435,7,1,'که طاعتِ منِ بیدل نمی‌شود مَقبول',NULL,NULL);
INSERT INTO "verses" VALUES(1933323,2435,8,0,'به دَردِ عشق بساز و خموش کن حافظ','هوش مصنوعی: در دل درد عاشقیت بسوز و سکوت را پیشه کن، حافظ رازهای عشق را برای اهل فکر و دانش فاش نکن.',NULL);
INSERT INTO "verses" VALUES(1933324,2437,6,0,'حافظ از سرپنجهٔ عشقِ نگار','هوش مصنوعی: حافظ به زیبایی و قدرت عشق معشوق اشاره می‌کند و می‌گوید که او مانند موری که در زیر پای فیل افتاده است، به قدری تحت تأثیر این عشق قرار گرفته که قادر به مقاومت نیست. عشق معشوق او را به شدت تحت فشار قرار داده و او را در موقعیتی ناتوان و آسیب‌پذیر قرار داده است.',NULL);
INSERT INTO "verses" VALUES(1933325,2437,5,1,'دست ما کوتاه و خرما بر نَخیل',NULL,NULL);
INSERT INTO "verses" VALUES(1933326,2437,5,0,'پای ما لَنگ است و منزل بس دراز','هوش مصنوعی: ما به مقصدی دور آمده‌ایم و به خاطر ناتوانی‌ام، نمی‌توانیم به آنجا برسیم. در حالی که شایستگی و امکاناتی برای رسیدن به آنجا نداریم.',NULL);
INSERT INTO "verses" VALUES(1933327,2437,4,1,'گرچه دارد او جمالی بس جمیل',NULL,NULL);
INSERT INTO "verses" VALUES(1933328,2437,4,0,'من نمی‌یابم مجال ای دوستان','هوش مصنوعی: من نمی‌توانم فرصتی پیدا کنم، ای دوستان، هرچند او زیبایی بسیار زیبا دارد.',NULL);
INSERT INTO "verses" VALUES(1933329,2437,3,1,'سرد کن زان سان که کردی بر خلیل',NULL,NULL);
INSERT INTO "verses" VALUES(1933330,2437,3,0,'یا رب این آتش که در جانِ من است','هوش مصنوعی: ای پروردگار، این آتش که در وجود من شعله‌ور است، همان‌طور که بر ابراهیم پیامبر نوازش کردی و او را از آتش نجات دادی، بر من نیز رحم کن و آن را خاموش ساز.',NULL);
INSERT INTO "verses" VALUES(1933331,2437,2,1,'همچو من افتاده دارد صد قَتیل',NULL,NULL);
INSERT INTO "verses" VALUES(1933332,2437,2,0,'ناوَکِ چشمِ تو در هر گوشه‌ای','هوش مصنوعی: چشمان تو در هر گوشه‌ای مانند من افرادی را به عشق و زیبایی خود مشغول کرده و دل‌های زیادی را به شدت تحت تأثیر قرار داده است.',NULL);
INSERT INTO "verses" VALUES(1933333,2437,1,1,'همچو مورانند گِردِ سَلسَبیل',NULL,NULL);
INSERT INTO "verses" VALUES(1933334,2437,1,0,'سبزپوشانِ خَطَت بر گِردِ لب','هوش مصنوعی: سبزپوشان دور لب تو مانند مورچه‌ها دور شیرینی جمع شده‌اند.',NULL);
INSERT INTO "verses" VALUES(1933335,2437,0,1,'سَلسَبیلت کرده جان و دل سَبیل',NULL,NULL);
INSERT INTO "verses" VALUES(1933336,2437,0,0,'ای رُخَت چون خُلد و لَعلَت سَلسَبیل','هوش مصنوعی: صورت زیبایت مانند بهشت است و لبت مانند سنگی قیمتی است. جان و دل از شیرینی لبت سیراب شده‌اند.',NULL);
INSERT INTO "verses" VALUES(1933337,2436,7,1,'یا رب ببینم آن را در گردنت حَمایل',NULL,NULL);
INSERT INTO "verses" VALUES(1933338,2442,0,1,'مشتاقِ بندگیّ و دعاگویِ دولتم',NULL,NULL);
INSERT INTO "verses" VALUES(1933339,2436,7,0,'ای دوست دستِ حافظ تَعویذِ چشم زخم است','هوش مصنوعی: ای دوست، آیا دست حافظ برای محافظت از چشم زخم است یا خدایا، آیا می‌توانم آن را در گردنت ببینم که آویخته شده؟',NULL);
INSERT INTO "verses" VALUES(1933340,2436,6,0,'از آبِ دیده صد رَه طوفانِ نوح دیدم','هوش مصنوعی: از چشم‌های من سیل و طوفانی به بزرگی طوفان نوح به راه افتاده است و تصویر تو هیچ‌گاه از یادم نمی‌رود و از دل من محو نخواهد شد.',NULL);
INSERT INTO "verses" VALUES(1933341,2436,5,1,'و اکنون شدم به مستان چون ابرویِ تو مایل',NULL,NULL);
INSERT INTO "verses" VALUES(1933342,2436,5,0,'در عینِ گوشه‌گیری بودم چو چشمِ مستت','هوش مصنوعی: در حالی که به تنهایی و بی‌خبر از دیگران بودم، چشمان تو مانند چشمان مستی مرا به خود جذب کرده بود و اکنون به خاطر تو، مانند دیگر مستان شاد و سرزنده شده‌ام.',NULL);
INSERT INTO "verses" VALUES(1933343,2436,4,1,'مَرضیّةُ السَجایا مَحمودَةُ الخَصائل',NULL,NULL);
INSERT INTO "verses" VALUES(1933344,2436,4,0,'دل داده‌ام به یاری، شوخی‌، کَشی، نگاری','هوش مصنوعی: دل خود را به یاری و بازیگوشی یک معشوق سپرده‌ام که ویژگی‌هایش پسندیده و خصلت‌های نیکو دارد.',NULL);
INSERT INTO "verses" VALUES(1933345,2436,3,1,'گفت «آن زمان که نَبْوَد جان در میانه حائل»',NULL,NULL);
INSERT INTO "verses" VALUES(1933346,2436,3,0,'گفتم که «کِی ببخشی بر جانِ ناتوانم؟»','هوش مصنوعی: گفتم «کی می‌خواهی به جان ضعیف من رحم کنی؟» گفت «زمانی که جان مانعی در میانه نداشته باشد.»',NULL);
INSERT INTO "verses" VALUES(1933347,2436,2,1,'«از شافعی نپرسند امثالِ این مسائل»',NULL,NULL);
INSERT INTO "verses" VALUES(1933348,2436,2,0,'حَلّاج بر سرِ دار این نکته خوش سُراید','هوش مصنوعی: حَلّاج در هنگام اعدام، این نکته را به زیبایی بیان می‌کند که در مورد مسائل پیچیده و دشوار، بهتر است از کسانی که در این زمینه تخصص ندارند، سوال نشود.',NULL);
INSERT INTO "verses" VALUES(1933349,2436,1,1,'آخر بسوخت جانم در کسبِ این فضایل',NULL,NULL);
INSERT INTO "verses" VALUES(1933350,2436,1,0,'تحصیلِ عشق و رندی آسان نمود اول','هوش مصنوعی: ابتدا به نظر می‌رسید که به دست آوردن عشق و دلدادگی و رفتارهای شیطنت‌آمیز کار ساده‌ای است، اما در پایان، جانم را در راه کسب این ویژگی‌ها سوزاندم.',NULL);
INSERT INTO "verses" VALUES(1933351,2436,0,1,'هر کو شنید گفتا «لِلّهِ دَرُّ قائل»',NULL,NULL);
INSERT INTO "verses" VALUES(1933352,2436,0,0,'هر نکته‌ای که گفتم در وصفِ آن شَمایل','هوش مصنوعی: هر چیزی که درباره آن چهره و زیبایی گفتم، هر کسی که شنید، فقط گفت: «خداوند را شکر که چنین زیبایی وجود دارد».',NULL);
INSERT INTO "verses" VALUES(1933353,2435,8,1,'رموزِ عشق مَکُن فاش پیشِ اهلِ عقول',NULL,NULL);
INSERT INTO "verses" VALUES(1933354,2436,6,1,'وز لوحِ سینه نقشت هرگز نگشت زایل',NULL,NULL);
INSERT INTO "verses" VALUES(1933355,2442,1,0,'زان جا که فیضِ جامِ سعادت فروغِ توست','از آنجایی که نور و خوشبختی من از وجود تو نشات می‌گیرد،راه برون رفتی از تاریکی و سردرگمی‌هایم نشانم بده',NULL);
INSERT INTO "verses" VALUES(1933356,2442,1,1,'بیرون شدی نُمای ز ظلماتِ حیرتم',NULL,NULL);
INSERT INTO "verses" VALUES(1933357,2442,2,0,'هرچند غرقِ بحرِ گناهم ز صد جهت','هوش مصنوعی: با وجود اینکه در دریاهای گناهان خود غرق شده‌ام و از همه‌جا به من حمله می‌شود، به عشق آشنا شدم و از اهل رحمت قرار گرفتم.',NULL);
INSERT INTO "verses" VALUES(1933358,2447,7,0,'تو خوش می‌باش با حافظ، برو گو خصم جان می‌ده','تو با حافظ خوش باش به دشمن بگو برو از حسادت بمیر، وقتی از جانب تو مهربانی و گرمی می­‌بینم دیگر ترسی از دشمنان افسرده دل و بد زبان ندارم.',NULL);
INSERT INTO "verses" VALUES(1933359,2447,6,1,'نهادم بر لبت لب را و جان و دل فِدا کردم',NULL,NULL);
INSERT INTO "verses" VALUES(1933360,2447,6,0,'کشیدم در بَرَت ناگاه و شد در تابْ گیسویت','ناگهان تو را در آغوش کشیدم و گیسویت در حرکت آمد و پیچ و تاب خورد؛ لبم را بر لبت نهادم و جان و دل خود را فدایت کردم.',NULL);
INSERT INTO "verses" VALUES(1933361,2447,5,1,'رُخَت می‌دیدم و جامی هلالی باز می‌خوردم',NULL,NULL);
INSERT INTO "verses" VALUES(1933362,2447,5,0,'شبی دل را به تاریکی ز زلفت باز می‌جُستم','شبی دلم را در تاریکی(تاریکی زلف، تاریکی شب) در میان زلفت جستجو می­‌کردم و چهره‌­ی همچون ماهِ تابناک تو را می‌­دیدم و چنان سرمست می­‌شدم که گویی ساغری از باده نوشیده­‌ام.',NULL);
INSERT INTO "verses" VALUES(1933363,2447,4,1,'دَمار از من برآوردی نمی‌گویی برآوردم',NULL,NULL);
INSERT INTO "verses" VALUES(1933364,2447,4,0,'فرو رفت از غمِ عشقت دَمَم دَم می‌دهی تا کی؟','از غم عشق تو نفسم بند آمده است، تا کی می­‌خواهی مرا فریب دهی؟ مرا شکنجه و عذاب بسیار می‌­دهی؛ حتی این مطلب را (شکنجه دادن) اقرار نمی­‌کنی و اجازه نفس کشیدن هم نمی­‌دهی.(ایهام: نمی گویی برآوردم؛ ۱. اقرار کردن، ۲. برآور دم( نفس بکش))',NULL);
INSERT INTO "verses" VALUES(1933365,2447,3,1,'که بر خاکم روان گَردی بگیرد دامنت گَردم',NULL,NULL);
INSERT INTO "verses" VALUES(1933366,2447,3,0,'ندارم دستت از دامن، به جز در خاک و آن دَم هَم','هرگز دست از تو نخواهم کشید و تو را رها نخواهم کرد مگر بعد از اینکه مرده باشم و در خاک رفته باشم، حتی در آن لحظه نیز اگر بر خاک مزارم عبور کنی، گرد و خاک مزارم دامنت را رها نخواهد کرد(گرد و خاک مزارم از تو بازخواست خواهد کرد).',NULL);
INSERT INTO "verses" VALUES(1933367,2447,2,1,'گُذاری آر و بازم پرس تا خاکِ رَهَت گردم',NULL,NULL);
INSERT INTO "verses" VALUES(1933368,2447,2,0,'نه راه است این که بُگذاری مرا بر خاک و بُگریزی','این که مرا بر خاک رها کنی و بروی، رفتار و راه درستی نیست، (برای یک بار شده) گذری کن و از حال ما جویا شو تا جانم را پیشکش قدم­‌هایت کنم.',NULL);
INSERT INTO "verses" VALUES(1933369,2447,1,1,'به درمانم نمی‌کوشی، نمی‌دانی مگر دردم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933370,2447,1,0,'به سامانم نمی‌پرسی، نمی‌دانم چه سر داری','از وضع و حالم جویا نمی­‌شوی، نمی‌دانم که چه اندیشه و قصدی در سر داری؟ هیچ کاری جهت بهبود و تسکین درد من نمی­‌کنی مگر از درد من اطلاع نداری؟',NULL);
INSERT INTO "verses" VALUES(1933371,2447,0,1,'تو را می‌بینم و میلم زیادَت می‌شود هر دَم',NULL,NULL);
INSERT INTO "verses" VALUES(1933372,2447,0,0,'مرا می‌بینی و هر دَم زیادَت می‌کنی دَردَم','مرا می­‌بینی و هر لحظه درد عشق من نسبت به تو بیشتر و افزون­‌تر می­گردد، تو را می­‌بینم و هر لحظه شور و اشتیاقم نسبت به دیدارت بیشتر می­‌شود.',NULL);
INSERT INTO "verses" VALUES(1933387,2447,7,1,'چو گرمی از تو می‌بینم، چه باک از خصمِ دَم سَردم',NULL,NULL);
INSERT INTO "verses" VALUES(1933391,2449,6,0,'ساقی به صوتِ این غزلم کاسه می‌گرفت','هوش مصنوعی: ساقی در حین خواندن این غزل، جام را به دست می‌گرفت و من می‌گفتم که این شعر و شراب خوش‌طعم را رو می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1933392,2449,5,1,'بر کارگاهِ دیدهٔ بی‌خواب می‌زدم',NULL,NULL);
INSERT INTO "verses" VALUES(1933393,2449,5,0,'نقشِ خیالِ رویِ تو تا وقتِ صبحدم','هوش مصنوعی: تا هنگام صبح، طرح و تصویر چهره‌ات را بی‌وقفه در ذهنم ترسیم می‌کردم و چشم‌هایم که خواب نمی‌برد، به این کار مشغول بود.',NULL);
INSERT INTO "verses" VALUES(1933394,2449,4,1,'فالی به چشم و گوش در این باب می‌زدم',NULL,NULL);
INSERT INTO "verses" VALUES(1933395,2449,4,0,'چشمم به رویِ ساقی و گوشم به قولِ چنگ','هوش مصنوعی: چشمانم به سمت ساقی است و گوشم به صدای چنگ، در این باره با چشم و گوشم در حال تماشا و گوش دادن هستم.',NULL);
INSERT INTO "verses" VALUES(1933396,2449,3,1,'وز دور بوسه بر رخِ مهتاب می‌زدم',NULL,NULL);
INSERT INTO "verses" VALUES(1933397,2449,3,0,'رویِ نگار در نظرم جلوه می‌نمود','هوش مصنوعی: در ذهنم چهره زیبای محبوب به تصویر آمد و از دور به صورت ماه که به مانند او بود بوسه می‌زدم.',NULL);
INSERT INTO "verses" VALUES(1933398,2449,2,1,'بازش ز طُرِّهٔ تو به مِضراب می‌زدم',NULL,NULL);
INSERT INTO "verses" VALUES(1933399,2449,2,0,'هر مرغِ فکر کز سرِ شاخِ سخن بِجَست','هوش مصنوعی: هر فکری که از سرِ گفتار و سخن به پرواز درآمد، من آن را با آوای تو جلا می‌دادم و به آن شکل می‌دادم.',NULL);
INSERT INTO "verses" VALUES(1933400,2449,1,1,'جامی به یادِ گوشهٔ محراب می‌زدم',NULL,NULL);
INSERT INTO "verses" VALUES(1933401,2449,1,0,'ابرویِ یار در نظر و خرقه سوخته','هوش مصنوعی: ابروی محبوب در چشم من و لباس خراب و سوزان، جامی را به یاد گوشهٔ محراب می‌نوشیدم.',NULL);
INSERT INTO "verses" VALUES(1933402,2449,0,1,'نقشی به یادِ خَطِّ تو بر آب می‌زدم',NULL,NULL);
INSERT INTO "verses" VALUES(1933403,2449,0,0,'دیشب به سیلِ اشک رَهِ خواب می‌زدم','هوش مصنوعی: دیشب با اشک‌های زیاد خواب را می‌شکافتم و تصویری از خط تو را بر روی آب به یاد می‌آوردم.',NULL);
INSERT INTO "verses" VALUES(1933422,2433,7,1,'خوش باش که ظالم نَبَرد راه به منزل',NULL,NULL);
INSERT INTO "verses" VALUES(1933425,2443,7,1,'آه اگر عاطِفَتِ شاه نگیرد دستم',NULL,NULL);
INSERT INTO "verses" VALUES(1933426,2443,7,0,'صنمی لشکریَم غارتِ دل کرد و بِرَفت','یک بت جنگاور، دلم را به‌غارت برد و رفت، وای بر من اگر لطف شاه به‌داد من نرسد.',NULL);
INSERT INTO "verses" VALUES(1933427,2443,6,1,'که به افسوس و جفا مُهرِ وفا نشکستم',NULL,NULL);
INSERT INTO "verses" VALUES(1933428,2443,6,0,'بوسه بر دُرجِ عقیقِ تو حلال است مرا','بوسه بر عقیق سرخ و زیبای تو بر من حلال است، زیرا با وجود غم و جفا‌ی تو، عهد و وفایم را نشکستم.',NULL);
INSERT INTO "verses" VALUES(1933429,2443,5,1,'چون به محبوبِ کمان ابرویِ خود پیوستم',NULL,NULL);
INSERT INTO "verses" VALUES(1933430,2443,5,0,'بعد از اینم چه غم از تیرِ کج اندازِ حسود','هوش مصنوعی: از این پس نگران تیر کمان حسودان نیستم، چون به معشوقی با ابروی کمان مانند پیوستم.',NULL);
INSERT INTO "verses" VALUES(1933431,2443,4,1,'تا نگویی که چو عمرم به سر آمد رَستم',NULL,NULL);
INSERT INTO "verses" VALUES(1933432,2443,4,0,'در رَهِ عشق از آن سویِ فنا صد خطر است','هوش مصنوعی: در مسیر عشق، خطرات زیادی وجود دارد و نمی‌توان گفت که وقتی عمرم به پایان رسید، آزاد شدم.',NULL);
INSERT INTO "verses" VALUES(1933433,2443,3,1,'که دَم از خدمتِ رندان زده‌ام تا هستم',NULL,NULL);
INSERT INTO "verses" VALUES(1933434,2443,3,0,'عافیتْ چشم مدار از منِ میخانه‌نشین','هوش مصنوعی: از نگاهت آسایش را از منِ کسی که در میخانه نشسته است، انتظار نداشته باش. چرا که من تا زمانی که هستم، همواره از خدمت به جمع رندان سخن گفته‌ام.',NULL);
INSERT INTO "verses" VALUES(1933435,2443,2,1,'در سرِ کویِ تو از پایِ طلب ننشَستم',NULL,NULL);
INSERT INTO "verses" VALUES(1933436,2443,2,0,'از ثباتِ خودم این نکته خوش آمد که به جور','هوش مصنوعی: از استقامت و پایداری خودم خوشحالم که به خاطر عشق و آرزو در سر کوی تو همچنان ایستاده‌ام و تسلیم مشکلات نشده‌ام.',NULL);
INSERT INTO "verses" VALUES(1933437,2443,1,1,'دیرگاه است کز این جامِ هِلالی مستم',NULL,NULL);
INSERT INTO "verses" VALUES(1933438,2443,1,0,'عشق من با خَطِ مشکین تو امروزی نیست','هوش مصنوعی: عشق من به خطوط زیبای تو، تازگی ندارد و از مدت‌ها پیش وجود دارد. من از این جام زیبا سرمست و شیدا هستم.',NULL);
INSERT INTO "verses" VALUES(1933439,2443,0,1,'لیکن از لطفِ لبت صورتِ جان می‌بستم',NULL,NULL);
INSERT INTO "verses" VALUES(1933440,2443,0,0,'دوش بیماری چشم تو بِبُرد از دستم','هوش مصنوعی: شب گذشته بیماری چشمانت مرا از پا درآورد، اما با مهربانی لبت، روح و جانم را به زندگی بازگرداندم.',NULL);
INSERT INTO "verses" VALUES(1933441,2442,8,1,'در این خیالم اَر بدهد عمر مهلتم',NULL,NULL);
INSERT INTO "verses" VALUES(1933442,2442,8,0,'حافظ به پیشِ چشم تو خواهد سِپُرد جان','حافظ برای عشق تو جان خود را فدا می‌کند. و امید دارد که عمرش برای رسیدن به این آرزو کافی باشد.',NULL);
INSERT INTO "verses" VALUES(1933443,2442,7,1,'لیکن به جان و دل ز مقیمانِ حضرتم',NULL,NULL);
INSERT INTO "verses" VALUES(1933444,2442,7,0,'دورم به صورت از درِ دولتسرایِ تو','در ظاهر من از درگاه تو دور هستم، اما از عمق جان احساس دلبستگی و نزدیکی میکنم',NULL);
INSERT INTO "verses" VALUES(1933445,2442,6,1,'ای خِضْرِ پِی خجسته مدد کن به همتم',NULL,NULL);
INSERT INTO "verses" VALUES(1933446,2442,6,0,'دریا و کوه در رَه و من خسته و ضعیف','هوش مصنوعی: دریا و کوه در مسیر راه قرار دارند و من خسته و ناتوان هستم. ای خضر خوشبخت، به من کمک کن تا بتوانم بر اراده و تلاشم سوار شوم.',NULL);
INSERT INTO "verses" VALUES(1933447,2442,5,1,'در عشقِ دیدن تو هواخواهِ غربتم',NULL,NULL);
INSERT INTO "verses" VALUES(1933448,2442,5,0,'من کز وطن سفر نَگُزیدَم به عمرِ خویش','من هیچ وقت از وطنم دور نشدم، اما عشقِ دیدن تو باعث شده است که به اختیار غربت را بخواهم.',NULL);
INSERT INTO "verses" VALUES(1933449,2442,4,1,'این موهبت رسید ز میراثِ فطرتم',NULL,NULL);
INSERT INTO "verses" VALUES(1933450,2442,4,0,'مِی خور که عاشقی نه به کسب است و اختیار','هوش مصنوعی: شراب بنوش، زیرا عشق چیزی نیست که با تلاش و انتخاب به دست آید؛ این بخشش الهی از میراث فطرت من است.',NULL);
INSERT INTO "verses" VALUES(1933451,2442,3,1,'کاین بود سرنوشت ز دیوانِ قسمتم',NULL,NULL);
INSERT INTO "verses" VALUES(1933452,2442,3,0,'عیبم مکن به رندی و بدنامی ای حکیم','هوش مصنوعی: ای حکیم، به خاطر رند بودن و بدنامی‌ام عیب‌جویی نکن، زیرا این ویژگی‌ها در تقدیرم نوشته شده است.',NULL);
INSERT INTO "verses" VALUES(1933453,2442,2,1,'تا آشِنایِ عشق شدم ز اهل رحمتم',NULL,NULL);
INSERT INTO "verses" VALUES(1933454,2443,8,0,'رُتبَتِ دانشِ حافظ به فلک بَر شده بود','هوش مصنوعی: حافظ به اوج و اعتلای دستاوردهای علمی و هنری خود رسیده بود، اما به خاطر دردی که از بلندای قامت تو دارد، خود را در مقام پایین‌تری می‌بیند.',NULL);
INSERT INTO "verses" VALUES(1933455,2443,8,1,'کرد غم‌خواریِ شمشادِ بلندت پَستم',NULL,NULL);
INSERT INTO "verses" VALUES(1933456,2444,0,0,'به غیر از آن که بِشُد دین و دانش از دستم','هوش مصنوعی: غیر از اینکه دین و علمم را از من گرفته‌اند، بگو که از عشق تو چه چیزهایی را به دست آورده‌ام.',NULL);
INSERT INTO "verses" VALUES(1933457,2444,0,1,'بیا بگو که ز عشقت چه طَرْف بَربَستَم؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933458,2445,8,0,'حافظ از جورِ تو حاشا که بِگَرداند روی','دورباد از حافظ اگر روزگاری از ظلم و جور تو روی بگرداند چرا که از آن روزی که مبتلا و اسیر تو شده است، (از تعلقات دنیوی) آزاد و رها گشته است.',NULL);
INSERT INTO "verses" VALUES(1933459,2445,8,1,'مَن اَز آن روز که دَر بَندِ توام آزادَم',NULL,NULL);
INSERT INTO "verses" VALUES(1933460,2445,7,0,'رَحم کُن بَر مَنِ مِسکین و بِه فَریادَم رَس','به من بیچاره رحم کن و به فریادم برس، تا فریاد دادخواهی من به درگاه آصف نرسد.(آصف: وزیر معروف حضرت سلیمان، در اینجا منظور خواجه جلال الدین تورانشاه است، یکی از ممدوحین حافظ.)',NULL);
INSERT INTO "verses" VALUES(1933461,2445,7,1,'تا به خاکِ دَرِ آصِف نَرِسَد فَریادَم',NULL,NULL);
INSERT INTO "verses" VALUES(1933462,2445,6,0,'شُهرهٔ شَهر مَشو تا نَنَهَم سَر دَر کوه','خود را در شهر مشهور و انگشت‌­نما نکن تا از شدت بی‌­قراری و آوارگی سر به کوه نگذارم، همچنین شور و غوغایی همچون شیرین از خود نشان مده تا مرا همچون فرهاد عاشق و سرگشته نکنی.',NULL);
INSERT INTO "verses" VALUES(1933463,2445,6,1,'شورِ شیرین مَنَما تا نَکُنی فَرهادَم',NULL,NULL);
INSERT INTO "verses" VALUES(1933464,2445,5,0,'شَمعِ هَر جَمع مَشو وَر نَه بِسوزی ما را','چشم‌­نمای هر جمعی نشو (چونان شمع در هر مجلسی درخشان نشو) وگرنه مرا خواهی سوزاند، همچنین از هر گروهی یاد نکن تا هرگز از خاطرم بیرون نروی.(نکته: شمع خود را می­‌سوزاند اما حافظ در اینجا مدعی است: هنگامی که معشوق در مجلس چون شمع می­‌درخشد، عاشق را می­‌سوزاند.نکته ۲: از یاد رفتن می­توان ایهام گرفت: ۱. از یاد من خواهی رفت. ۲. مرا از یاد ببری.)',NULL);
INSERT INTO "verses" VALUES(1933465,2445,5,1,'یادِ هَر قوم مَکُن تا نَرَوی اَز یادَم',NULL,NULL);
INSERT INTO "verses" VALUES(1933466,2445,4,0,'رُخ بَراَفروز که فارغ کُنی اَز بَرگِ گُلم','چهره­‌ی همچون گل خود را نشان بده تا دیگر احتیاجی به دیدن گل نداشته باشم، قامت بلند خود را نمایان کن تا دیگر از تماشای سرو رها شوم.',NULL);
INSERT INTO "verses" VALUES(1933467,2445,4,1,'قَد بَراَفراز که اَز سَروْ کُنی آزادَم',NULL,NULL);
INSERT INTO "verses" VALUES(1933468,2445,3,0,'یارِ بیگانه مَشو تا نَبَری از خویشم','همنشین افراد بیگانه نشو تا مرا بی­قرار و بی‌­تاب نکنی، همچنین غم‌خوار نامحرمان نشو تا مرا غمگین نگردانی.',NULL);
INSERT INTO "verses" VALUES(1933469,2445,3,1,'غَمِ اَغیار مَخور تا نَکُنی ناشادَم',NULL,NULL);
INSERT INTO "verses" VALUES(1933470,2445,2,0,'زُلف را حَلقه مَکُن تا نَکُنی دَر بَندَم','زلفت را پر پیچ و تاب نکن تا مرا اسیر و دربند نکنی، همچنین زلف آراسته­‌ات را تاب مده تا مرا نیست و نابود نکنی.',NULL);
INSERT INTO "verses" VALUES(1933471,2445,2,1,'طُرّه را تاب مَده تا نَدَهی بَر بادَم',NULL,NULL);
INSERT INTO "verses" VALUES(1933473,2445,1,0,'مِی مَخور با هَمه کَس تا نَخورَم خونِ جِگَر','با هر کس و ناکسی مشغول عیش و نوش نشو تا از شدت اندوه خون جگر نخورم، همچنین از من روی بر مگردان تا فریادم به آسمان نرسد.',NULL);
INSERT INTO "verses" VALUES(1933474,2445,0,0,'زُلف بَر باد مَده تا نَدَهی بَر بادَم','اگر می‌­خواهی مرا از شدت عشق نیست و نابود نکنی، گیسویت را در باد رها نکن، همچنین اگر می­خواهی بنیاد هستی مرا نابود نکنی، عشوه و ناز آغاز نکن.(بنیاد اول در معنای شروع و آغاز کردن، بنیاد دوم در معنای اصل و اساس.)',NULL);
INSERT INTO "verses" VALUES(1933475,2445,0,1,'ناز بُنیاد مَکُن تا نَکَنی بُنیادَم',NULL,NULL);
INSERT INTO "verses" VALUES(1933476,2444,6,1,'که مَرهمی بفرستم که خاطرش خَستم',NULL,NULL);
INSERT INTO "verses" VALUES(1933477,2444,6,0,'بسوخت حافظ و آن یارِ دلنواز نگفت','هوش مصنوعی: حافظ در این بیت به احساس درد و رنجی که از جدایی و غم عشق دارد، اشاره می‌کند. او می‌گوید که باوجود سوختن و رنج کشیدن او، محبوبش هیچ‌گاه نگران او نشده و حتی زحمت ارسال یک کلام تسکین‌دهنده یا خبری از خود را به خود نداده است. این نشان‌دهنده بی‌اعتنایی محبوب به حال دل عاشق است.',NULL);
INSERT INTO "verses" VALUES(1933478,2444,5,1,'که خدمتی بسزا برنیامد از دستم',NULL,NULL);
INSERT INTO "verses" VALUES(1933479,2444,5,0,'چگونه سر ز خجالت برآورم بَرِ دوست','هوش مصنوعی: چطور می‌توانم از خجالت سرم را بالا بگیرم در مقابل دوستم، در حالی که نتوانسته‌ام خدمتی شایسته به او ارائه دهم؟',NULL);
INSERT INTO "verses" VALUES(1933480,2444,4,1,'سخن به خاک مَیَفکَن؛ چرا که من مستم',NULL,NULL);
INSERT INTO "verses" VALUES(1933481,2444,4,0,'اگر ز مردمِ هشیاری ای نصیحت‌گو','هوش مصنوعی: اگر کسی که باهوش و دلسوز است، بخواهد به من نصیحت کند، نباید حرف‌هایش را به باد بدهد، زیرا من در حال غرق شدن در شوق و سرمستی هستم و نمی‌توانم به او گوش دهم.',NULL);
INSERT INTO "verses" VALUES(1933482,2444,3,1,'به کُنجِ عافیت از بهرِ عیش نَنشَستَم',NULL,NULL);
INSERT INTO "verses" VALUES(1933483,2444,3,0,'بیار باده که عمریست تا من از سَرِ اَمن','هوش مصنوعی: لطفا باده بیاورید، چون مدت زیادی است که من از محیط امن و آرامش به گوشه‌ای برای لذت و خوشی نرفته‌ام.',NULL);
INSERT INTO "verses" VALUES(1933484,2444,2,1,'که در هوایِ رُخَت چون به مِهر پیوستم',NULL,NULL);
INSERT INTO "verses" VALUES(1933485,2444,2,0,'چو ذَرِّه گرچه حقیرم؛ ببین به دولتِ عشق','هوش مصنوعی: اگرچه من مانند ذره‌ای کوچک و بی‌ارزش هستم، اما ببین چگونه عشق نسبت به چهره‌ات مرا به حالتی پر از نعمت و خوشحالی رسانده است. زمانی که به زیبایی تو نگاه می‌کنم، تمام وجودم پر از مهر و محبت می‌شود.',NULL);
INSERT INTO "verses" VALUES(1933486,2444,1,1,'به خاک‌پایِ عزیزت که عهد نشکستم',NULL,NULL);
INSERT INTO "verses" VALUES(1933487,2444,1,0,'اگر چه خَرمَنِ عمرم غمِ تو داد به باد','هوش مصنوعی: با وجود اینکه زندگی‌ام را برای غم تو هدر کردم، اما به خاطر محبت و ارزشت، قولی که به تو داده بودم را نشکستم.',NULL);
INSERT INTO "verses" VALUES(1933488,2445,1,1,'سَر مَکِش تا نَکِشَد سَر به فَلَک فَریادَم',NULL,NULL);
INSERT INTO "verses" VALUES(1933489,2433,7,0,'دورِ فلکی یکسَره بر مَنْهَجِ عدل است','چرخ فلک بر مدار عدالت می چرخد ( گردش چرخ فلک در مسیر روشن و راست قرار دارد) ای دل خوش باش که بار کج ِ ظالم هرگز به منزل نمی رسد.',NULL);
INSERT INTO "verses" VALUES(1933490,2433,6,1,'شد گردنِ بدخواه گرفتار سَلاسِل',NULL,NULL);
INSERT INTO "verses" VALUES(1933491,2433,6,0,'مِی نوش و جهان بخش که از زلفِ کمندت','ای پادشاه ، به باده نوشی و عشرت بپرداز و دست به بخشش های بزرگ بزن که به لطفِ زنجیر زلفت تو (به برکت خوی نیک تو) بد خواهان به بند و زنجیر کشیده شده اند.',NULL);
INSERT INTO "verses" VALUES(1933492,2423,9,1,'تا مُنور گردد از دیدارت ایوانم چو شمع',NULL,NULL);
INSERT INTO "verses" VALUES(1933493,2423,9,0,'سرفرازم کن شبی از وصلِ خود ای نازنین','هوش مصنوعی: شب را به من ببخش تا در کنار تو باشم، ای عزیز. با دیدار تو، خانه‌ام مثل شمع نورانی و روشن خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1933494,2423,8,1,'چهره بنما دلبرا تا جان برافشانم چو شمع',NULL,NULL);
INSERT INTO "verses" VALUES(1933495,2423,8,0,'همچو صبحم یک نفس باقی‌ست با دیدارِ تو','هوش مصنوعی: به مانند سپیده‌دم، یک نفس بیشتر از دیدار تو باقی نمانده است. ای عزیز، چهره ات را به من نشان بده تا مانند شمع، جانم را فدای تو کنم.',NULL);
INSERT INTO "verses" VALUES(1933496,2423,7,1,'تا در آب و آتشِ عشقت گدازانم چو شمع',NULL,NULL);
INSERT INTO "verses" VALUES(1933497,2423,7,0,'کوهِ صبرم نرم شد چون موم در دستِ غمت','هوش مصنوعی: کوه صبر من به خاطر غمت مانند موم نرم شده است، تا بتوانم به خاطر عشق تو در آتش و آب خود را ذوب کنم مانند شمع.',NULL);
INSERT INTO "verses" VALUES(1933498,2423,6,1,'با کمالِ عشقِ تو در عینِ نُقصانم چو شمع',NULL,NULL);
INSERT INTO "verses" VALUES(1933499,2423,6,0,'بی جمالِ عالم‌آرایِ تو روزم چون شب است','هوش مصنوعی: روز بدون زیبایی تو برایم مانند شب است و با آنکه عشق تو را در دل دارم، همچنان در نقص و کمبود به سر می‌برم مانند شمعی که در روشنایی خود می‌سوزد.',NULL);
INSERT INTO "verses" VALUES(1933500,2423,5,1,'ور نه از دَردَت جهانی را بسوزانم چو شمع',NULL,NULL);
INSERT INTO "verses" VALUES(1933501,2423,5,0,'در شبِ هجران، مرا پروانهٔ وصلی فرست','هوش مصنوعی: در شب جدایی، اگر معشوقی به من ندهی، مجبورم که از درد عشق، همه را به سوز و آتش بکشم مانند شمعی که در آتش می‌سوزد.',NULL);
INSERT INTO "verses" VALUES(1933502,2423,4,1,'این دلِ زارِ نزارِ اشک‌بارانم چو شمع',NULL,NULL);
INSERT INTO "verses" VALUES(1933503,2423,4,0,'در میانِ آب و آتش همچنان سرگرمِ توست','هوش مصنوعی: این دل غمگین و زخمی من، در شرایط سخت و دشوار مانند آب و آتش، همچنان به یاد و محبت تو مشغول است، همان‌طور که یک شمع در دل تاریکی می‌سوزد و روشنایی می‌بخشد.',NULL);
INSERT INTO "verses" VALUES(1933504,2423,3,1,'کِی شدی روشن به گیتی رازِ پنهانم چو شمع؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933505,2423,3,0,'گر کُمَیتِ اشکِ گُلگونم نبودیِ گرم‌رو','هوش مصنوعی: اگر اشک‌های گرم و سرخ من نبود، آیا تو که همیشه داغ و روشن هستی، می‌توانستی راز پنهان من را مانند شمع به روشنایی درآوری و در دنیا نمایان کنی؟',NULL);
INSERT INTO "verses" VALUES(1933506,2423,2,1,'همچنان در آتشِ مهرِ تو سوزانم چو شمع',NULL,NULL);
INSERT INTO "verses" VALUES(1933507,2423,2,0,'رشتهٔ صبرم به مِقراضِ غمت بُبْریده شد','هوش مصنوعی: صبر و تحمل من به خاطر غم و ناراحتی تو از هم پاشیده شده است، اما من هنوز مانند شمعی در آتش عشق تو می سوزم.',NULL);
INSERT INTO "verses" VALUES(1933508,2423,1,1,'بس که در بیماریِ هجرِ تو گریانم چو شمع',NULL,NULL);
INSERT INTO "verses" VALUES(1933509,2423,1,0,'روز و شب خوابم نمی‌آید به چشمِ غم‌پرست','هوش مصنوعی: به خاطر غم و اندوهی که از دوری تو دارم، نه روز می‌توانم بخوابم و نه شب. مانند شمعی هستم که در حال ذوب شدن است و از شدت درد و غم، همواره گریانم.',NULL);
INSERT INTO "verses" VALUES(1933510,2423,0,1,'شب‌نشینِ کویِ سربازان و رندانم چو شمع',NULL,NULL);
INSERT INTO "verses" VALUES(1933511,2423,0,0,'در وفایِ عشقِ تو، مشهورِ خوبانم چو شمع','هوش مصنوعی: در وفاداری به عشق تو، نامم به عنوان بهترین‌ها شناخته شده است. مانند شمعی که در شب در کنار سربازان و دور از رندان روشن می‌سوزد.',NULL);
INSERT INTO "verses" VALUES(1933512,2422,7,1,'جامعِ علم و عمل جانِ جهان، شاه شجاع',NULL,NULL);
INSERT INTO "verses" VALUES(1933513,2422,7,0,'مَظهَرِ لطفِ ازل، روشنی چشمِ اَمَل','هوش مصنوعی: جلوه‌ای از رحمت بی‌پایان، روشنایی بخش چشم امید، که مجموع دانش و عمل را در بر دارد و روح جهان است، پادشاهی شجاع و دلیر.',NULL);
INSERT INTO "verses" VALUES(1933514,2422,6,1,'که وجودیست عطابخشِ کریمِ نَفّاع',NULL,NULL);
INSERT INTO "verses" VALUES(1933515,2422,6,0,'عمرِ خسرو طلب ار نفعِ جهان می‌خواهی','هوش مصنوعی: اگر می‌خواهی از زندگی خسرو بهره‌ای برای بهبود وضعیت جهان ببری، باید بدان که وجود او بخشنده و نیکوکار است.',NULL);
INSERT INTO "verses" VALUES(1933516,2422,5,1,'عارفان بر سرِ این رشته نجویند نِزاع',NULL,NULL);
INSERT INTO "verses" VALUES(1933517,2422,5,0,'طُرِّهٔ شاهدِ دنیی همه بند است و فریب','هوش مصنوعی: سر و شکل زیبای دنیا تماماً فریب و گمراهی است و عارفان در این خصوص به هیچ درگیری و جدلی نمی‌پردازند.',NULL);
INSERT INTO "verses" VALUES(1933518,2422,4,1,'که به هر حالتی این است بِهینِ اوضاع',NULL,NULL);
INSERT INTO "verses" VALUES(1933519,2422,4,0,'وضعِ دوران بنگر ساغرِ عِشرت بَر گیر','هوش مصنوعی: وضعیت زمانه را بنگر و جام خوشی را بگیر، زیرا در هر شرایطی این بهترین حالت اوضاع است.',NULL);
INSERT INTO "verses" VALUES(1933520,2422,3,1,'جام در قَهقَهه آید که کجا شد مَنّاع؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933521,2423,10,0,'آتشِ مِهر تو را حافظ عجب در سر گرفت','هوش مصنوعی: حافظ از عشق و محبت تو چنان سرشار است که آتشِ عشق در دلش شعله‌ور شده است. اما مثل شمع، نمی‌تواند این آتش را با اشک‌هایش خاموش کند.',NULL);
INSERT INTO "verses" VALUES(1933522,2423,10,1,'آتشِ دل، کِی به آبِ دیده بنشانم چو شمع؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933523,2424,0,0,'سَحَر به بویِ گلستان دَمی شدم در باغ','هوش مصنوعی: در سپیده دم، به خاطر عطر خوش گلستان، لحظه‌ای در باغ نشستم تا مانند بلبل زار-زار، دلم را آرام کنم.',NULL);
INSERT INTO "verses" VALUES(1933524,2424,0,1,'که تا چو بلبلِ بیدل کُنَم عِلاجِ دِماغ',NULL,NULL);
INSERT INTO "verses" VALUES(1933525,2425,8,0,'حافظ اگر قدم زنی، در رَهِ خاندان به صِدق','ای حافظ، اگر در راهِ خاندان راستی و اخلاص گام برداری، عنایتِ شحنهٔ نجف پشتیبان و بدرقه‌گر راهت خواهد بود. (شحنه: حاکم، سلطان و صاحب‌منصب)',NULL);
INSERT INTO "verses" VALUES(1933526,2425,8,1,'بدرقهٔ رهت شود، همتِ شَحنِهٔ نجف',NULL,NULL);
INSERT INTO "verses" VALUES(1933527,2425,7,0,'صوفی شهر بین که چون لقمهٔ شُبهه می‌خورد','هوش مصنوعی: صوفی شهر را ببین که چطور لقمه‌ای مشکوک را می‌خورد و این باعث می‌شود که همانند حیوانی که علف‌های خوب می‌خورد، به طوری عجیب و بی‌نهایت دراز شود.',NULL);
INSERT INTO "verses" VALUES(1933528,2425,7,1,'پاردُمَش دراز باد، آن حَیَوانِ خوش علف',NULL,NULL);
INSERT INTO "verses" VALUES(1933529,2425,6,0,'بی‌خبرند زاهدان، نقش بخوان و لاتَقُل','هوش مصنوعی: زاهدان بی‌خبراند، به خویش نخواهید گفت که مستِ قدرت محتسب نباشید، شراب بده و نترس.',NULL);
INSERT INTO "verses" VALUES(1933530,2425,6,1,'مستِ ریاسْت محتسب، باده بده و لاتَخَف',NULL,NULL);
INSERT INTO "verses" VALUES(1933531,2425,5,0,'من به خیالِ زاهدی، گوشه‌نشین و طُرفه آنک','هوش مصنوعی: من در خیال خود به زندگی زاهدانه‌ای مشغول بودم و در گوشه‌ای نشسته بودم. اما جالب اینجاست که از هر طرف، موسیقی و آواز به گوشم می‌رسید و مرا به وجد می‌آورد.',NULL);
INSERT INTO "verses" VALUES(1933532,2425,5,1,'مُغْبَچه‌ای ز هر طرف، می‌زندم به چنگ و دف',NULL,NULL);
INSERT INTO "verses" VALUES(1933533,2425,4,0,'چند به ناز پرورم، مِهرِ بُتانِ سنگ‌دل','هوش مصنوعی: برخی از فرزندان ناپسند، به خاطر محبت و محبت من، یاد پدر را نمی‌کنند و در عوض فقط به ناز و لطافت کار می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1933534,2425,4,1,'یادِ پدر نمی‌کنند، این پسرانِ ناخلف',NULL,NULL);
INSERT INTO "verses" VALUES(1933535,2425,3,0,'ابرویِ دوست کِی شود، دست‌کشِ خیالِ من؟','هوش مصنوعی: ابروی دوست چه زمانی می‌تواند به عنوان دستکشی برای خیال من باشد؟ هیچ‌کس از این کمان، تیر آرزو را به هدف نزد.',NULL);
INSERT INTO "verses" VALUES(1933536,2425,3,1,'کس نزده‌ست از این کمان، تیرِ مراد بر هدف',NULL,NULL);
INSERT INTO "verses" VALUES(1933537,2425,2,0,'از خَمِ ابرویِ توام، هیچ گشایشی نشد','هوش مصنوعی: از حالت ابروهای تو هیچ تغییر و بهبودی به وجود نیامد و افسوس که در این فکر اشتباه، زندگی گرانبهای من هدر رفت.',NULL);
INSERT INTO "verses" VALUES(1933538,2425,2,1,'وَه که در این خیالِ کَج، عمرِ عزیز شد تلف',NULL,NULL);
INSERT INTO "verses" VALUES(1933539,2422,3,0,'چنگ در غُلغُله آید که کجا شد منکر؟','هوش مصنوعی: در هیاهو و سر و صدای زندگی، ناپدید شدن منکرها به چشم می‌آید و در خنده و شادی، مانع‌ها نیز ناپدید می‌شوند.',NULL);
INSERT INTO "verses" VALUES(1933540,2425,1,0,'طرْفِ کرَم ز کَس نبست، این دلِ پُر امیدِ من','هوش مصنوعی: طرف کرم و بخشش از هیچ‌کس نیست، هرچند دل پرامید من درباره‌اش صحبت می‌کند، داستان من به همه‌جا می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1933541,2425,0,0,'طالع اگر مدد دهد، دامنَش آوَرَم به کف','هوش مصنوعی: اگر سرنوشت مساعد باشد، من دامانش را به دست خواهم آورد. اگر او مرا به درون کشد، شادی بزرگی خواهد بود و اگر او مرا بکشد، این باعث افتخار من خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1933542,2425,0,1,'گر بکِشم زهی طرب، ور بکُشد زهی شرف',NULL,NULL);
INSERT INTO "verses" VALUES(1933543,2424,6,1,'که حافظا نَبُوَد بر رسول غیر بَلاغ',NULL,NULL);
INSERT INTO "verses" VALUES(1933544,2424,6,0,'نشاط و عیش و جوانی چو گُل غنیمت دان','هوش مصنوعی: از زندگی و جوانی لذت ببر و آنها را غنیمت بشمار، زیرا روزی می‌رسد که دیگر فرصت‌های مشابه به تو نمی‌رسند و باید از لحظات بهره‌برداری کنی.',NULL);
INSERT INTO "verses" VALUES(1933545,2424,5,1,'یکی چو ساقیِ مستان به کف گرفته اَیاغ',NULL,NULL);
INSERT INTO "verses" VALUES(1933546,2424,5,0,'یکی چو باده پرستان صُراحی اندر دست','هوش مصنوعی: انسانی همچون باده‌نوشان، در دستش پیاله‌ای دارد و فردی دیگر مانند ساقی، نوشیدنی را در کف گرفته است.',NULL);
INSERT INTO "verses" VALUES(1933547,2424,4,1,'دهان گُشاده شقایق چو مردمِ ایغاغ',NULL,NULL);
INSERT INTO "verses" VALUES(1933548,2424,4,0,'زبان کشیده چو تیغی به سرزنش سوسن','سوسن زبانش را از برای سرزنش همچو تیغ کشیده است و شقایق به مانند مردم سخن‌چین دهان گشاده است.',NULL);
INSERT INTO "verses" VALUES(1933549,2424,3,1,'نهاده لاله ز سودا به جان و دل صد داغ',NULL,NULL);
INSERT INTO "verses" VALUES(1933550,2424,3,0,'گشاده نرگسِ رعنا ز حسرت آب از چشم','هوش مصنوعی: نرگس زیبا با حسرتی بزرگ گلبرگ‌هایش را دراز کرده و لاله، از درد عشق، اشک می‌ریزد و در دلش زخم‌های زیادی دارد.',NULL);
INSERT INTO "verses" VALUES(1933551,2424,2,1,'که داشت از دلِ بلبل هزار گونه فَراغ',NULL,NULL);
INSERT INTO "verses" VALUES(1933552,2424,2,0,'چُنان به حُسن و جوانیِ خویشتن مغرور','هوش مصنوعی: آنچنان به زیبایی و جوانی خود متکبر است که دل بلبل از شوق و شادی به هزاران نوع خوشحالی مشغول است.',NULL);
INSERT INTO "verses" VALUES(1933553,2424,1,1,'که بود در شبِ تیره به روشنی چو چراغ',NULL,NULL);
INSERT INTO "verses" VALUES(1933554,2424,1,0,'به جلوهٔ گلِ سوری نگاه می‌کردم','هوش مصنوعی: به زیبایی گل سرخ خیره شده بودم که در شب تاریک مانند چراغی روشن می‌درخشید.',NULL);
INSERT INTO "verses" VALUES(1933555,2425,1,1,'گر چه سخن همی بَرَد، قصهٔ من به هر طرف',NULL,NULL);
INSERT INTO "verses" VALUES(1933556,2426,0,0,'زبانِ خامه ندارد سرِ بیان فِراق','هوش مصنوعی: خامه (قلم) زبان ندارد تا بتواند درد و جدایی را بیان کند، و اگر داشت، داستان فراق را با تو بازگو می‌کردم.',NULL);
INSERT INTO "verses" VALUES(1933557,2422,2,1,'اَرغَنون ساز کُنَد زهره به آهنگِ سَماع',NULL,NULL);
INSERT INTO "verses" VALUES(1933558,2422,1,1,'بنماید رخِ گیتی به هزاران انواع',NULL,NULL);
INSERT INTO "verses" VALUES(1933559,2419,6,0,'نه عمرِ خِضر بِمانَد، نه مُلکِ اسکندر','نه عمر جاودان با تو وفا می‌کند و نه فرمان‌روایی جهان‌؛ پس غم دنیای بی‌ارزش را مخور ای دوست!',NULL);
INSERT INTO "verses" VALUES(1933560,2419,5,1,'چرا که شرم همی آیدم ز حاصلِ خویش',NULL,NULL);
INSERT INTO "verses" VALUES(1933561,2419,5,0,'به کویِ میکده گریان و سرفِکنده رَوَم','هوش مصنوعی: به محله شرابخانه می‌روم، با اشک و سر به زمین. چون از دستاوردهای خود شرمنده‌ام.',NULL);
INSERT INTO "verses" VALUES(1933562,2419,4,1,'گَرَم به تجربه دستی نهند بر دلِ ریش',NULL,NULL);
INSERT INTO "verses" VALUES(1933563,2419,4,0,'ز آستینِ طبیبان هزار خون بچکد','اگر طبیبی بخواهد که درد دل خسته و ریش مرا بیابد و بر دلم دست نهد، هزار خون از آستین او خواهد چکید!',NULL);
INSERT INTO "verses" VALUES(1933564,2419,3,1,'که موج می‌زندش آبِ نوش، بر سرِ نیش',NULL,NULL);
INSERT INTO "verses" VALUES(1933565,2419,3,0,'بنازم آن مژهٔ شوخِ عافیت‌کُش را','فدای آن مژه بی‌رحم و سنگ‌دل شوم که در نوک آن، آب حیات و جان موج می‌زند!',NULL);
INSERT INTO "verses" VALUES(1933566,2419,2,1,'چه‌هاست در سرِ این قطرهٔ محال‌اندیش!',NULL,NULL);
INSERT INTO "verses" VALUES(1933567,2419,2,0,'خیال حوصلهٔ بحر می‌پزد هیهات','هیهات که خیال، ظرفیت دریا را می‌پزد (=می‌پروراند). چه‌ها در سر این خیال (=نقطه محال اندیش) است!',NULL);
INSERT INTO "verses" VALUES(1933568,2419,1,1,'که دل به دستِ کمان ابرویی‌ست کافِرکیش',NULL,NULL);
INSERT INTO "verses" VALUES(1933569,2419,1,0,'چو بید بر سرِ ایمانِ خویش می‌لرزم','همچون بید لرزان هستم و می‌ترسم زیرا ایمان من در خطر است و دل من در دست کمان‌ابرویی بی‌رحم است!',NULL);
INSERT INTO "verses" VALUES(1933570,2419,0,1,'که آن شِکاریِ سرگشته را چه آمد پیش',NULL,NULL);
INSERT INTO "verses" VALUES(1933571,2419,0,0,'دلم رمیده شد و غافلم منِ درویش','خوانش های آمده از سوی بسیاری‌ ، بیشتر خوانش ها یا همان تفسیرهای آلوده به یک گونه باور و نگاه چیره است که ریشه هایش از جهان دانسته های آدمی می آید ، دانسته هایی که همه چیز در آنجا پیشتر بر پایه باورها و نگاه های مورد پذیرش همگان شکل می گیرد ، اما اینجا به وارونه خوانش هوش ساختگی"مصنوعی" بیشتر با حرکت درونی و زیرین سروده حافظ کار می کنیم‌ و دیگر غزل کارساز و شگفت حافظ را با آن خوانش های چیره انجام نمی دهیم‌، پس بند به بند کار را آغاز می کنیم',NULL);
INSERT INTO "verses" VALUES(1933572,2418,7,1,'صدفِ سینهٔ حافظ بُوَد آرامگَهَش',NULL,NULL);
INSERT INTO "verses" VALUES(1933573,2418,7,0,'جان به شکرانه کنم صرف گَر آن دانهٔ دُر','هوش مصنوعی: جانم را به خاطر وجود آن دانهٔ گرانبها که در دل حافظ پنهان است، نذر می‌کنم و این دانه را آرامشگاه خود می‌دانم.',NULL);
INSERT INTO "verses" VALUES(1933574,2418,6,1,'بِبَرَد زود به جانداریِ خود پادشهَش',NULL,NULL);
INSERT INTO "verses" VALUES(1933575,2418,6,0,'یارِ دلدارِ من ار قلب بدین سان شِکَنَد','هوش مصنوعی: اگر محبوب من قلب من را به این حالت بشکند، به زودی با قدرت و انرژی خود حکومتش را به دست خواهد آورد.',NULL);
INSERT INTO "verses" VALUES(1933576,2418,5,1,'خود کجا شد که ندیدیم در این چند گَهَش؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933577,2418,5,0,'از پِی آن گُلِ نورُستِه دلِ ما یارب','هوش مصنوعی: دل ما به دنبال آن گل نورسته است، خدایا، نمی‌دانیم کجا رفته که در این مدت نتوانسته‌ایم او را ببینیم.',NULL);
INSERT INTO "verses" VALUES(1933578,2418,4,1,'که به جان حلقه به گوش است مَهِ چاردَهَش',NULL,NULL);
INSERT INTO "verses" VALUES(1933579,2418,4,0,'چارده ساله بُتی چابُکِ شیرین دارم','هوش مصنوعی: من یک بت زیبا و nimble دارم که از چهارده سال پیش در دل و جانم جا گرفته است. این بت که برایم همچون ماهی درخشان است، به طرز خاصی مورد توجه و علاقه من است.',NULL);
INSERT INTO "verses" VALUES(1933580,2418,3,1,'گرچه خون می‌چکد از شیوهٔ چشمِ سیَهَش',NULL,NULL);
INSERT INTO "verses" VALUES(1933581,2418,3,0,'بویِ شیر از لبِ همچون شِکَرَش می‌آید','هوش مصنوعی: بویی خوش و دل‌انگیز از لب‌های او به مشام می‌رسد، هرچند که اشک‌های غم از چشمان تیره‌اش سرازیر است.',NULL);
INSERT INTO "verses" VALUES(1933582,2418,2,1,'که بد و نیک ندیده‌ست و ندارد نِگَهَش',NULL,NULL);
INSERT INTO "verses" VALUES(1933583,2418,2,0,'من همان بِه که از او نیک نگه دارم دل','هوش مصنوعی: من بهتر است که دلم را از کسی که تجربه‌ی بد و خوب ندارد، مراقبت کنم.',NULL);
INSERT INTO "verses" VALUES(1933584,2418,1,1,'بِکُشد زارم و در شرع نباشد گُنَهَش',NULL,NULL);
INSERT INTO "verses" VALUES(1933585,2418,1,0,'دلبرم شاهد و طفل است و به بازی روزی','هوش مصنوعی: عشقم هم محبوب است و هم کودکی که با بازی‌هایش مرا به زحمت می‌اندازد، اما در دین چیزی بابت این کارش ناپسند نیست.',NULL);
INSERT INTO "verses" VALUES(1933586,2418,0,1,'لیکَنَش مِهر و وفا نیست خدایا بِدَهَش',NULL,NULL);
INSERT INTO "verses" VALUES(1933587,2418,0,0,'مَجمَعِ خوبی و لطف است عِذار چو مَهَش','هوش مصنوعی: چهره‌اش مانند ماه زیبا و دل‌نشین است، اما unfortunately او را محبت و وفا در بر ندارد. کاش که خدایا او را این ویژگی‌ها عطا کنی.',NULL);
INSERT INTO "verses" VALUES(1933588,2419,6,1,'نزاع بر سرِ دنیی دون مَکُن درویش',NULL,NULL);
INSERT INTO "verses" VALUES(1933589,2419,7,0,'بِدان کمر نرسد دستِ هر گدا حافظ','حافظ به آن کمر و آستان دست هر انسان گدایی نمیرسد برای رسیدن دست به ان آستان باید خزانه ای گردآوری بکنی که از گنج قارون بیشتر باشد',NULL);
INSERT INTO "verses" VALUES(1933590,2419,7,1,'خزانه‌ای به کف آور ز گنجِ قارون بیش',NULL,NULL);
INSERT INTO "verses" VALUES(1933591,2420,0,0,'ما آزموده‌ایم در این شهر بختِ خویش','اگر زندگی در این دایره ،سوختی داشته ، ما سوخت هایش را دادیم . و دوباره سوخت دادن دیگر از ما گذشته ، اول و آخر بازی ابن دایره رو گرفتیم باید از آن عبور کنیم ، کلمه باید شاه کلمه این بیت هست ، یک راه ، آن هم گذر از دایره.',NULL);
INSERT INTO "verses" VALUES(1933592,2422,1,0,'بَرکَشَد آینه از جِیبِ افق چرخ و در آن','هوش مصنوعی: آینه‌ای که از جیب آسمان پیداست، تصویر زمین را به شکل‌های گوناگون به نمایش می‌گذارد.',NULL);
INSERT INTO "verses" VALUES(1933593,2422,0,1,'شمعِ خاور فِکَنَد بر همه اطراف شُعاع',NULL,NULL);
INSERT INTO "verses" VALUES(1933594,2422,0,0,'بامدادان که ز خلوتگَهِ کاخِ اِبداع','هوش مصنوعی: صبح‌ها هنگامی که شمعی که در قصر الهام روشن است، نور خود را بر تمام اطراف پخش می‌کند.',NULL);
INSERT INTO "verses" VALUES(1933595,2421,6,1,'ز خاکِ بارگه کبریایِ شاه شجاع',NULL,NULL);
INSERT INTO "verses" VALUES(1933596,2421,6,0,'جبین و چهرهٔ حافظ خدا جدا مَکُناد','هوش مصنوعی: چهره و پیشانی حافظ را از خاک سرای بزرگی شاه شجاع جدا نکنید.',NULL);
INSERT INTO "verses" VALUES(1933597,2421,5,1,'نمی‌کنیم دلیری نمی‌دهیم صُداع',NULL,NULL);
INSERT INTO "verses" VALUES(1933598,2421,5,0,'به فیضِ جرعهٔ جامِ تو تشنه‌ایم، ولی','هوش مصنوعی: ما به خاطر نوشیدن یک جرعه از جام تو بسیار تشنه‌ایم، اما جرات نمی‌کنیم و هم‌چنین دل را به دردسر نمی‌اندازیم.',NULL);
INSERT INTO "verses" VALUES(1933599,2421,4,1,'که من غلامِ مطیعم، تو پادشاهِ مُطاع',NULL,NULL);
INSERT INTO "verses" VALUES(1933600,2421,4,0,'به عاشقان نظری کن به شُکرِ این نعمت','هوش مصنوعی: به عاشقان خود نگاهی بینداز و به خاطر این نعمت سپاسگزار باش که من به عنوان خدمتگزار و غلام تو، تو را به عنوان پادشاهی که مورد اطاعت است، می‌شناسم.',NULL);
INSERT INTO "verses" VALUES(1933601,2421,3,1,'کسی که رُخصه نفرمودی اِسْتِماعِ سَماع',NULL,NULL);
INSERT INTO "verses" VALUES(1933602,2421,3,0,'ببین که رقص‌کُنان می‌رود به نالهٔ چنگ','هوش مصنوعی: ببین که چگونه کسی که از احساساتش می‌رقصد، در حالی که به ناله‌ی چنگ گوش می‌دهد، به خاطر این که تو اجازه نداشتی به شنیدن و درک این آهنگ بپردازی.',NULL);
INSERT INTO "verses" VALUES(1933603,2421,2,1,'که من نمی‌شِنَوَم بویِ خیر از این اوضاع',NULL,NULL);
INSERT INTO "verses" VALUES(1933604,2421,2,0,'خدای را به مِی‌ام شست و شویِ خِرقه کنید','[ شما را ] به خدا سوگند [ می دهم ]، لباس پشیمنه مرا با شراب شست و شو کنید زیرا که من از اوضاع روزگار امید خیر و نیکی ندارم.',NULL);
INSERT INTO "verses" VALUES(1933605,2421,1,1,'حریفِ باده رسید ای رفیقِ توبه وِداع',NULL,NULL);
INSERT INTO "verses" VALUES(1933606,2422,2,0,'در زوایایِ طَرَبخانهٔ جمشیدِ فلک','هوش مصنوعی: در گوشه و کنار ساز و دهل کاخ جمشید، زهره به آهنگ رقص و شادی می‌رقصد.',NULL);
INSERT INTO "verses" VALUES(1933607,2421,1,0,'شرابِ خانگیم بس مِیِ مُغانِه بیار','هوش مصنوعی: شراب خانگی‌ام را بیاور؛ چون دوست و رفیق باده‌نوش من به مهمانی آمده است و دیگر نیازی به توبه و خداحافظی نیست.',NULL);
INSERT INTO "verses" VALUES(1933608,2421,0,0,'قسم به حشمت و جاه و جلالِ شاه شجاع','هوش مصنوعی: به عظمت و قدرت و شکوه شاه شجاع قسم می‌خورم که برای مال و مقام با هیچ‌کس درگیر نیستم.',NULL);
INSERT INTO "verses" VALUES(1933609,2420,6,1,'جمشید نیز دور نماندی ز تخت خویش',NULL,NULL);
INSERT INTO "verses" VALUES(1933610,2420,6,0,'ای حافظ ار مراد مُیَسَّر شدی مدام','هوش مصنوعی: ای حافظ، اگر به آرزویت رسیدی، بدان که جمشید نیز همیشه به تخت سلطنت خود دسترسی نداشت.',NULL);
INSERT INTO "verses" VALUES(1933611,2420,5,1,'آتش درافکنم به همه رَخت و پَختِ خویش',NULL,NULL);
INSERT INTO "verses" VALUES(1933612,2420,5,0,'وقت است کز فراقِ تو وز سوزِ اندرون','هوش مصنوعی: زمان آن فرا رسیده که از دوری تو و سوزی که در درونم دارم، به همه دارایی‌ها و زندگی‌ام آتش بیفکنم.',NULL);
INSERT INTO "verses" VALUES(1933613,2420,4,1,'بگذر ز عهدِ سست و سخن‌هایِ سختِ خویش',NULL,NULL);
INSERT INTO "verses" VALUES(1933614,2420,4,0,'خواهی که سخت و سست جهان بر تو بگذرد','هوش مصنوعی: اگر می‌خواهی دنیای دشوار و آسان بر تو بگذرد، از وعده‌های ناپایدار و سخنان سخت خود عبور کن.',NULL);
INSERT INTO "verses" VALUES(1933615,2420,3,1,'بسیار تند روی نشیند ز بختِ خویش',NULL,NULL);
INSERT INTO "verses" VALUES(1933616,2420,3,0,'کای دل تو شاد باش که آن یارِ تندخو','هوش مصنوعی: ای دل، شاد باش که آن دوست زودخو و تندمزاج به زودی از سرنوشت خود فرود خواهد آمد.',NULL);
INSERT INTO "verses" VALUES(1933617,2420,2,1,'گل گوش پهن کرده ز شاخِ درختِ خویش',NULL,NULL);
INSERT INTO "verses" VALUES(1933618,2420,2,0,'دوشم ز بلبلی چه خوش آمد که می‌سرود','هوش مصنوعی: شب گذشته از بلبل صدای دلنوازی به گوشم رسید که درختان در حال شکوفه دادن بودند و گل‌ها گوش به زنگ این آواز زیبا شده بودند.',NULL);
INSERT INTO "verses" VALUES(1933619,2420,1,1,'آتش زدم چو گُل به تنِ لَخت لَختِ خویش',NULL,NULL);
INSERT INTO "verses" VALUES(1933620,2420,1,0,'از بس که دست می‌گَزَم و آه می‌کشم','هوش مصنوعی: به خاطر بی‌احساسی و دردهای زیادی که تحمل می‌کنم، مانند گلی که در آتش می‌سوزد، به خودم آسیب زدم و احساساتم را تحت فشار قرار داده‌ام.',NULL);
INSERT INTO "verses" VALUES(1933621,2420,0,1,'بیرون کشید باید از این وَرطه رَختِ خویش',NULL,NULL);
INSERT INTO "verses" VALUES(1933622,2421,0,1,'که نیست با کَسَم از بهرِ مال و جاه نزاع',NULL,NULL);
INSERT INTO "verses" VALUES(1933623,2417,6,0,'به غفلت عمر شُد حافظ، بیا با ما به میخانه','ای حافظ، عمرت به بی‌خبری سپری شد، با ما به میخانه بیا تا ساقیان زیباروی خوش مشرب به تو راه زندگی خوب را بیاموزند..',NULL);
INSERT INTO "verses" VALUES(1933624,2426,0,1,'وگرنه شرح دهم با تو داستانِ فِراق',NULL,NULL);
INSERT INTO "verses" VALUES(1933625,2426,1,1,'به سر رسید و نیامد به سر زمانِ فِراق',NULL,NULL);
INSERT INTO "verses" VALUES(1933626,2431,5,1,'مرحباً مرحباً تَعال تَعال',NULL,NULL);
INSERT INTO "verses" VALUES(1933627,2431,5,0,'یا بَریدَ الْحِمی حَماکَ الله','ای نامه بر دوست، خدا حفظت کند ... مرحبا ... مرحبا، بیا ... بیا',NULL);
INSERT INTO "verses" VALUES(1933628,2431,4,1,'صَرَّفَ اللهُ عَنکَ عَینَ کمال',NULL,NULL);
INSERT INTO "verses" VALUES(1933629,2431,4,0,'فی جَمالِ الکمالِ نِلتَ مُنی','در جمال ِ کمال به آرزویت رسیده ای(در اوج هستی) ... خدا تو را ببخشد (در محاوره روزمره برای فرزندان می گوییم: خدا به تون ببخشه) ای عین کمال!',NULL);
INSERT INTO "verses" VALUES(1933630,2431,3,1,'فَاسألوا حالَها عَنِ الاَطْلال',NULL,NULL);
INSERT INTO "verses" VALUES(1933631,2431,3,0,'عَفَتِ الدارُ بَعدَ عافیةٍ','هوش مصنوعی: به دنبال روزهایی که خانه در حال آسایش بود، حال آن را از نشانه‌های باقی‌مانده‌اش بپرسید.',NULL);
INSERT INTO "verses" VALUES(1933632,2431,2,1,'أینَ جِیرانُنا و کَیفَ الْحال',NULL,NULL);
INSERT INTO "verses" VALUES(1933633,2431,2,0,'ما لِسَلمی و من بِذی سَلَمٍ','سلمی (معشوق) و سلماییان (اهل و اهالی قبیله اش) را چه شد؟ آن همسایگانمان کجاهستند و به چه حالی هستند؟',NULL);
INSERT INTO "verses" VALUES(1933634,2431,1,1,'فُصِمَت ها هُنا لسانَ القال',NULL,NULL);
INSERT INTO "verses" VALUES(1933635,2431,1,0,'قصّةُ الْعِشق لَا اِنْفِصامَ لَها','قصه ی عشق را پایانی نیست...بلکه آن چه پایان می یابد، زبان است که از گفتن باز می ماند',NULL);
INSERT INTO "verses" VALUES(1933636,2431,0,1,'که به ما می‌رسد زمانِ وصال',NULL,NULL);
INSERT INTO "verses" VALUES(1933637,2431,0,0,'خوش خبر باشی ای نسیمِ شِمال','هوش مصنوعی: ای نسیم شمال، خوش خبر باش! به زودی زمان ملاقات و وصال ما فرا می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1933638,2430,6,1,'ای رقیب از بَرِ او یک دو قدم دورتَرَک',NULL,NULL);
INSERT INTO "verses" VALUES(1933639,2430,6,0,'چون بَرِ حافظِ خویشش نگذاری باری','هوش مصنوعی: اگر به حافظ اجازه ندهی که به خود ببالد و به دستاوردهایش افتخار کند، ای رقیب، پس از او کمی فاصله بگیر.',NULL);
INSERT INTO "verses" VALUES(1933640,2430,5,1,'من نه آنم که زبونی کشَم از چرخِ فلک',NULL,NULL);
INSERT INTO "verses" VALUES(1933641,2430,5,0,'چرخ برهم زنم ار غیرِ مرادم گردد','هوش مصنوعی: اگر به خواسته‌ام نرسم، چرخ روزگار را برهم می‌زنم. من فردی نیستم که از سختی‌ها و مشکلات دنیای سرنوشت خسته شوم.',NULL);
INSERT INTO "verses" VALUES(1933642,2430,4,1,'خلق را از دهنِ خویش مَیَنداز به شک',NULL,NULL);
INSERT INTO "verses" VALUES(1933643,2430,4,0,'بگشا پستهٔ خندان و شِکَرریزی کن','هوش مصنوعی: پستهٔ خندان را باز کن و شکر را به مردم بده؛ از دهان خودت چیزی را به شک و تردید نینداز.',NULL);
INSERT INTO "verses" VALUES(1933644,2430,3,1,'وعده از حد بشد و ما نه دو دیدیم و نه یَک',NULL,NULL);
INSERT INTO "verses" VALUES(1933645,2430,3,0,'گفته بودی که شَوَم مست و دو بوست بدهم','تو وعده دادی که باید مست شوم تا به تو دو بوسه بدهم ، اما حالا وعده مستی ات از حد گذشت ولی ما دو بوسه را که هیچ حتی یک بوسه هم ندیدیم',NULL);
INSERT INTO "verses" VALUES(1933646,2430,2,1,'کس عیارِ زرِ خالص نشناسد چو محَک',NULL,NULL);
INSERT INTO "verses" VALUES(1933647,2430,2,0,'در خلوصِ مَنَت ار هست شکی، تجربه کن','هوش مصنوعی: اگر در خلوص نیت و صداقت خود تردید داری، به آزمایش بپرداز. زیرا هیچ‌کس نمی‌تواند طلاي خالص را به خوبی محک بزند.',NULL);
INSERT INTO "verses" VALUES(1933648,2430,1,1,'ذکرِ خیرِ تو بُوَد حاصلِ تسبیحِ مَلَک',NULL,NULL);
INSERT INTO "verses" VALUES(1933649,2430,1,0,'تویی آن گوهرِ پاکیزه که در عالمِ قدس','هوش مصنوعی: تو آن جواهرِ باارزش و پاکی هستی که در عالم قدس همه فرشتگان با ذکر خوبی‌هایت تسبیح و ستایش می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1933650,2430,0,1,'حق نگه دار که من می‌روم، الله مَعَک',NULL,NULL);
INSERT INTO "verses" VALUES(1933651,2430,0,0,'ای دلِ ریشِ مرا با لبِ تو حقِّ نمک','ای عزیز دلداری که دل پاره و ریش شده من با لب تو همنشین بود و به قول معروف از سفره همدیگر نمک خورده بودند. حق نگه دار تو باشد که وقت رفتن من رسیده و تو را به خدا می سپارم',NULL);
INSERT INTO "verses" VALUES(1933652,2429,8,1,'که بر درِ تو نَهد رویِ مَسکَنَت بر خاک',NULL,NULL);
INSERT INTO "verses" VALUES(1933653,2429,8,0,'به چشمِ خَلق، عزیزِ جهان شود حافظ','هوش مصنوعی: در نگاه مردم، حافظ به خاطر این‌که بر در خانه‌ات سر می‌گذارد، در دنیا شخصیتی ارزشمند و محترم می‌شود.',NULL);
INSERT INTO "verses" VALUES(1933654,2429,7,1,'به قدرِ دانشِ خود هر کسی کند ادراک',NULL,NULL);
INSERT INTO "verses" VALUES(1933655,2431,6,0,'عرصهٔ بزمگاه خالی ماند','هوش مصنوعی: محل جشن و میگساری از مهمانان خالی ماند و جام پر از نوشیدنی بی‌کس ماند.',NULL);
INSERT INTO "verses" VALUES(1933656,2431,6,1,'از حریفان و جامِ مالامال',NULL,NULL);
INSERT INTO "verses" VALUES(1933657,2431,7,0,'سایه افکند حالیا شبِ هجر','هوش مصنوعی: در حال حاضر، شب غم و جدایی بر همه جا سایه افکنده است و باید دید که خواب و خیال چه بازتابی از این وضعیت خواهند داشت.',NULL);
INSERT INTO "verses" VALUES(1933658,2431,7,1,'تا چه بازَند شبرُوانِ خیال',NULL,NULL);
INSERT INTO "verses" VALUES(1933659,2433,5,1,'دستِ طَرَب از دامنِ این زمزمه مَگسِل',NULL,NULL);
INSERT INTO "verses" VALUES(1933660,2433,5,0,'شاها فلک از بزمِ تو در رقص و سَماع است','ای پادشاه ، در سایه ی محفل عیش و عشرت تو چرخ فلک نیز به شور و شوق آمده و مشغول رقص و پای‌کوبیست تو بمان و بگذار ‌مجلس عیش تو همچنان برقرار و مستدام باشد تا همه ی کائنات غرق در شور و شادمانی باشند.',NULL);
INSERT INTO "verses" VALUES(1933661,2433,4,1,'ای کاج که من بودَمی آن هندویِ مقبل',NULL,NULL);
INSERT INTO "verses" VALUES(1933662,2433,4,0,'خورشید چو آن خالِ سیَه دید، به دل گفت','خورشید با آن همه نور و روشنایی هنگامی که مشاهده کرد آن "خال سیاه"((ماه)) مورد توجّهِ ویژه ی خداوند قرار گرفته و منشاء خیر و برکت برای مردم و سببِ حلّ مسائل آنها شده، از روی رشک و حسادت می گوید ای کاش به جای این غلام سیاه خوشبخت من بودم.',NULL);
INSERT INTO "verses" VALUES(1933663,2433,3,1,'بر رویِ مَه افتاد که شد حلِّ مسائل',NULL,NULL);
INSERT INTO "verses" VALUES(1933664,2433,3,0,'روزِ ازل از کِلکِ تو یک قطره سیاهی','اینجا حافظ با رندی تمام مضمون شعر را از مدح به سمت ستایش خداوند هدایت میکند و به پند و موعظه میپردازد ؛ خداوندا به لطف عنایت تو در آغازین روز خلقت، از قلم صُنع تو یک قطره بر روی ماه چکید(( اشاره به پر جبرئيل )) را و ‌سبب شد که همه ی مسائل و مشکلاتِ مخلوقات شامل (جدا نبودنِ روز از شب ، نامعلوم بودن زمان عبادت، کار و استراحت و....) مرتفع گردید.',NULL);
INSERT INTO "verses" VALUES(1933665,2433,2,1,'اِنعام تو بر کون و مکان فایض و شامل',NULL,NULL);
INSERT INTO "verses" VALUES(1933666,2433,2,0,'تعظیمِ تو بر جان و خِرَد واجب و لازم','ستایش و احترام تو بر عقل و جان واجب است لطف و عنایتِ فرا شمول تو تمام اجزای هستی را دربرمی گیرد همه چیز و همه کس از بخشش و سخاوت تو فیض می برند.',NULL);
INSERT INTO "verses" VALUES(1933667,2433,1,1,'بر رویِ زمین روزنهٔ جان و دَرِ دل',NULL,NULL);
INSERT INTO "verses" VALUES(1933668,2433,1,0,'ای درگهِ اسلام پناهِ تو گشاده','ای پادشاهی که حاکمیّت تو در پناه اسلام و اسلام تحت حمایت توست بارگاه تو زمین را ملکوتی کرده است. درگاه تو پنجره به روی جان و دریچه ای به روی دل در زمین خاکی گشاده است.',NULL);
INSERT INTO "verses" VALUES(1933669,2433,0,1,'یَحیَی بنِ مُظَفَّر مَلِکِ عالمِ عادل',NULL,NULL);
INSERT INTO "verses" VALUES(1933670,2433,0,0,'دارایِ جهان نصرتِ دین خسروِ کامل','یحیی فرزند مظفر حاکم مقتدر، دانا و دادگستر ، دارنده ی جهان (داریوش سوم) ، یاور دین ، پادشاهی فاضل و کامل است.',NULL);
INSERT INTO "verses" VALUES(1933671,2432,6,1,'به خاکِ ما گذری کن که خونِ مات حلال',NULL,NULL);
INSERT INTO "verses" VALUES(1933672,2432,6,0,'قَتیلِ عشقِ تو شد حافظِ غریب، ولی','هوش مصنوعی: حافظ، شاعر غریب، جانش را به خاطر عشق تو از دست داده است، اما خواهش می‌کند به زمین ما سری بزن که خون ما به حلالی ارزشمند تبدیل می‌شود.',NULL);
INSERT INTO "verses" VALUES(1933673,2429,7,0,'تو را چنان که تویی هر نظر کجا بیند؟','هوش مصنوعی: هر کسی به اندازه‌ی دانش و آگاهی‌اش تو را می‌بیند و درک می‌کند، بنابراین نمی‌توانی انتظار داشته باشی که همه تو را به طور کامل بشناسند.',NULL);
INSERT INTO "verses" VALUES(1933674,2432,5,1,'که کَس مباد چو من در پِیِ خیالِ محال',NULL,NULL);
INSERT INTO "verses" VALUES(1933675,2432,4,1,'توان گذشت ز جورِ رقیب در همه حال',NULL,NULL);
INSERT INTO "verses" VALUES(1933676,2432,4,0,'چو یار بر سرِ صلح است و عُذر می‌طلبد','هوش مصنوعی: زمانی که دوست در پی دوستی و آشتی است و از من عذرخواهی می‌کند، می‌توانم از ظلم و سختی رقیب در هر شرایطی چشم‌پوشی کنم.',NULL);
INSERT INTO "verses" VALUES(1933677,2432,3,1,'کَشیده‌ایم به تَحریرِ کارگاهِ خیال',NULL,NULL);
INSERT INTO "verses" VALUES(1933678,2432,3,0,'بیا که پردهٔ گلریزِ هفت خانهٔ چشم','هوش مصنوعی: بیا که جلوهٔ زیبای چشمانت را با دقت و هنرمندی در ذهنمان تصویرسازی کرده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1933679,2432,2,1,'به شکرِ آن که برافکند پرده روزِ وصال',NULL,NULL);
INSERT INTO "verses" VALUES(1933680,2432,2,0,'حکایتِ شبِ هجران فروگذاشته بِهْ','هوش مصنوعی: داستان شب جدایی را فراموش کرده‌ام؛ به خاطر شکرگزاری از این که پرده روز وصل را کنار زده است.',NULL);
INSERT INTO "verses" VALUES(1933681,2432,1,1,'که نیست صبرِ جمیلم ز اشتیاقِ جَمال',NULL,NULL);
INSERT INTO "verses" VALUES(1933682,2432,1,0,'أَ حادیاً بجمالِ الحبیبِ قِفْ وَ انْزِل','هوش مصنوعی: ای به زیبایی معشوق، توقف کن و فرود بیا، چرا که صبرم در برابر زیبایی تو از شدت شوق به تنگ آمده است.',NULL);
INSERT INTO "verses" VALUES(1933683,2432,0,1,'بیا که بویِ تو را میرم ای نسیمِ شِمال',NULL,NULL);
INSERT INTO "verses" VALUES(1933684,2432,0,0,'شَمَمتُ روحَ وِدادٍ و شِمتُ برقَ وِصال','هوش مصنوعی: احساس کردم روح محبت را و بوی دیدار تو را استشمام کردم. بیایید که بوی تو را می‌چشم ای نسیم شمال.',NULL);
INSERT INTO "verses" VALUES(1933685,2431,9,1,'نالهٔ عاشقان خوش است، بِنال',NULL,NULL);
INSERT INTO "verses" VALUES(1933686,2431,9,0,'حافظا عشق و صابری تا چند؟','هوش مصنوعی: ای حافظ، تا کی باید در عشق و صبر باقی بمانیم؟ ناله و گریهٔ عاشقان خوشایند است، پس بگذار ناله کنیم.',NULL);
INSERT INTO "verses" VALUES(1933687,2431,8,1,'آه از این کبریا و جاه و جلال',NULL,NULL);
INSERT INTO "verses" VALUES(1933688,2431,8,0,'تُرکِ ما سویِ کَس نمی‌نِگرد','هوش مصنوعی: ما به هیچ‌کسی غیر از خود نمی‌نگریم؛ آه از این بزرگی و مقام و عظمت!',NULL);
INSERT INTO "verses" VALUES(1933689,2432,5,0,'به جز خیالِ دهانِ تو نیست در دلِ تنگ','هوش مصنوعی: در دل من جز تصور لب‌های تو هیچ چیز دیگری وجود ندارد، و هیچ‌کس نباید مانند من در پی خیال‌های بعید و غیرممکن برود.',NULL);
INSERT INTO "verses" VALUES(1933690,2426,1,0,'دریغ مدت عمرم که بر امیدِ وصال','آه و افسوس از طول عمر من که آن را به امید وصال و رسیدن به دوست، طی کردم و به سر رسید اما زمان جدایی و فراق به پایان نرسید.',NULL);
INSERT INTO "verses" VALUES(1933691,2429,6,1,'سپر کُنم سر و دستت ندارم از فِتراک',NULL,NULL);
INSERT INTO "verses" VALUES(1933692,2429,5,1,'لِأنَّ روحیَ قَدْ طابَ اَن یَکونَ فِداک',NULL,NULL);
INSERT INTO "verses" VALUES(1933693,2427,4,0,'بیا که توبه ز لعلِ نگار و خندهٔ جام','هوش مصنوعی: بیا که در توبه از لب‌های یاقوتی معشوق و خندهٔ می، داستانی وجود دارد که عقل نمی‌تواند آن را تصدیق کند.',NULL);
INSERT INTO "verses" VALUES(1933694,2427,3,0,'به مَأمَنی رو و فرصت شمُر غنیمتِ وقت','هوش مصنوعی: به جای اینکه به سراغ مشکلات بروی، از زمان فعلی بهره‌برداری کن و به جای نگرانی درباره‌ی آینده، از فرصت‌هایی که هم‌اکنون داری استفاده کن. چرا که زمان به سرعت می‌گذرد و ممکن است کسانی که به دنبال مانع‌تراشی‌اند، فرصت‌ها را از تو بگیرند.',NULL);
INSERT INTO "verses" VALUES(1933695,2427,3,1,'که در کمینگهِ عمرند قاطعانِ طریق',NULL,NULL);
INSERT INTO "verses" VALUES(1933696,2427,2,0,'دریغ و دَرد که تا این زمان ندانستم','متاسفانه، تا به امروز متوجه نشدم که مایه خوشبختی من اینست: پذیرش رفیق بودن یار',NULL);
INSERT INTO "verses" VALUES(1933697,2427,2,1,'که کیمیایِ سعادت، رفیق بود، رفیق',NULL,NULL);
INSERT INTO "verses" VALUES(1933698,2427,1,0,'جهان و کارِ جهان جمله هیچ بَر هیچ است','یار رفیق ماست و ما که جهانیان و جمله کار جهانیم، اثرمان بر رفاقت یار هیچ است. (مثلا اگر ظاهر ما خوب یا بد باشد، یار باز هم رفیق ما می ماند). دلیل هیچ بودن اثر جهان بر رفاقت یار اینستکه جهان نیز نزد یار که خود همه چیز است، هیچ نیست. پس میشود هیچ بر هیچ. شاعر میگوید من این نکته ظریف را هزاران بار به راستی و حقیقت، متوجه شده ام (که علیرغم خوبی یا بدی من، او رفیق من ماند).',NULL);
INSERT INTO "verses" VALUES(1933699,2427,1,1,'هزار بار من این نکته کرده‌ام تحقیق',NULL,NULL);
INSERT INTO "verses" VALUES(1933700,2427,0,0,'مقامِ امن و میِ بی‌غَش و رفیقِ شفیق','اگر همواره مقام امن و می بی‌نقص و رفیق دلگشایی به آسانی در دسترست باشد، خیلی خوشا به حال تو که موفقیت همین است.',NULL);
INSERT INTO "verses" VALUES(1933701,2427,0,1,'گَرَت مدام میسّر شود، زهی توفیق',NULL,NULL);
INSERT INTO "verses" VALUES(1933702,2426,11,1,'به دستِ هجر ندادی کسی عِنانِ فِراق',NULL,NULL);
INSERT INTO "verses" VALUES(1933703,2426,11,0,'به پایِ شوق گر این رَه به سر شدی حافظ','هوش مصنوعی: اگر به خاطر شوق و علاقه‌ام به این مسیر پایان دادی، حافظ، هیچ‌کس را در جدایی به دست غم و فراق نخواهی سپرد.',NULL);
INSERT INTO "verses" VALUES(1933704,2426,10,1,'بِبَست گردنِ صبرم به ریسمانِ فِراق',NULL,NULL);
INSERT INTO "verses" VALUES(1933705,2426,10,0,'فلک چو دید سرم را اسیرِ چَنبَرِ عشق','هوش مصنوعی: وقتی آسمان دید که من به عشق گرفتار شده‌ام، گردن صبرم را به بند فراق کشید.',NULL);
INSERT INTO "verses" VALUES(1933706,2426,9,1,'مدام خونِ جگر می‌خورم ز خوانِ فِراق',NULL,NULL);
INSERT INTO "verses" VALUES(1933707,2426,9,0,'ز سوزِ شوق دلم شد کباب دور از یار','هوش مصنوعی: دل من از شدت شوق به عشق، مانند کبابی در آتش می‌سوزد. به دور از یارم همیشه در رنج و عذاب هستم و از غم فراق او خون جگر می‌خورم.',NULL);
INSERT INTO "verses" VALUES(1933708,2426,8,1,'تنم وکیلِ قَضا و دلم ضمانِ فِراق',NULL,NULL);
INSERT INTO "verses" VALUES(1933709,2426,8,0,'چگونه دَعویِ وصلت کُنَم به جان؟ که شده‌ست','هوش مصنوعی: چطور می‌توانم ادعای وصل و نزدیکی به تو را داشته باشم، در حالی که وجودم تحت قضا و تقدیر قرار گرفته و قلبم در حال جدایی است؟',NULL);
INSERT INTO "verses" VALUES(1933710,2426,7,1,'قَرینِ آتشِ هجران و هم قِرانِ فِراق',NULL,NULL);
INSERT INTO "verses" VALUES(1933711,2426,7,0,'رفیقِ خِیلِ خیالیم و همنشینِ شَکیب','هوش مصنوعی: من دوست و همراه خیال هستم و در کنار صبر قرار دارم. هم‌پیمان آتش جدایی و هم‌نشین دوری هستم.',NULL);
INSERT INTO "verses" VALUES(1933712,2426,6,1,'که روزِ هجر سیَه باد و خان و مانِ فِراق',NULL,NULL);
INSERT INTO "verses" VALUES(1933713,2426,6,0,'اگر به دستِ من اُفتَد فِراق را بِکُشَم','هوش مصنوعی: اگر فراق به دست من بیفتد، آن را نابود می‌کنم، زیرا روز جدایی، سیاه و سخت است و باعث از هم پاشیدگی زندگی و آرامش می‌شود.',NULL);
INSERT INTO "verses" VALUES(1933714,2426,5,1,'ز موجِ شوقِ تو در بحرِ بی‌کرانِ فِراق',NULL,NULL);
INSERT INTO "verses" VALUES(1933715,2426,5,0,'بسی نَمانْد که کَشتیِ عمر غرقه شود','هوش مصنوعی: مدت زیادی باقی نمانده که زندگی انسان به دلیل شدت احساسات و اشتیاق به تو، دچار غرق شدگی شود در دریای بی‌پایان جدایی.',NULL);
INSERT INTO "verses" VALUES(1933716,2426,4,1,'فُتاد زورقِ صبرم ز بادبانِ فِراق',NULL,NULL);
INSERT INTO "verses" VALUES(1933717,2426,4,0,'کنون چه چاره که در بَحرِ غم به گردابی','هوش مصنوعی: اکنون چه باید کرد وقتی که در دریای غم گرفتار شدم و کشتی صبرم به خاطر جدایی خراب شده است؟',NULL);
INSERT INTO "verses" VALUES(1933718,2426,3,1,'که ریخت مرغِ دلم پَر در آشیانِ فِراق',NULL,NULL);
INSERT INTO "verses" VALUES(1933719,2426,3,0,'چگونه باز کنم بال در هوایِ وصال','هوش مصنوعی: چگونه می‌توانم در هوای دیدار عاشقانه پرواز کنم وقتی که دلِ من در آغوش جدایی، بال و پرش را از دست داده است.',NULL);
INSERT INTO "verses" VALUES(1933720,2426,2,1,'به راستان که نهادم، بر آستانِ فِراق',NULL,NULL);
INSERT INTO "verses" VALUES(1933721,2426,2,0,'سری که بر سرِ گردون به فخر می‌سودم','هوش مصنوعی: سری که با افتخار بر گردونه هستی می‌چرخید، اکنون به خاطر جدایی و فراق در آستانه‌ای ناامید و افسرده قرار گرفته است.',NULL);
INSERT INTO "verses" VALUES(1933722,2427,4,1,'حکایتی‌ست که عقلش نمی‌کُند تصدیق',NULL,NULL);
INSERT INTO "verses" VALUES(1933723,2427,5,0,'اگر چه مویِ میانت به چون منی نرسد','هوش مصنوعی: اگرچه موهای میانت به زیبایی شواهد نمی‌رسد، اما این خیال عمیق و دقیق، خاطر من را خوشحال می‌کند.',NULL);
INSERT INTO "verses" VALUES(1933724,2427,5,1,'خوش است خاطرم از فکرِ این خیالِ دقیق',NULL,NULL);
INSERT INTO "verses" VALUES(1933725,2427,6,0,'حلاوتی که تو را در چَهِ زَنَخدان است','هوش مصنوعی: آن لذتی که تو در عمق وجودت داری، قابل مقایسه با هیچ‌یک از هزاران اندیشه عمیق نیست.',NULL);
INSERT INTO "verses" VALUES(1933726,2429,5,0,'بِضَربِ سَیْفِکَ قَتْلی حَیاتُنا اَبدا','اگر با شمشیر تو کشته شوم من به حیات جاویدان و ابدی می رسم چرا که روح من اگر فدای تو شود پاک و والا خواهد شد .',NULL);
INSERT INTO "verses" VALUES(1933727,2429,4,1,'و گر تو زهر دهی، بِهْ که دیگری تریاک',NULL,NULL);
INSERT INTO "verses" VALUES(1933728,2429,4,0,'اگر تو زخم زَنی، بِهْ که دیگری مَرهم','هوش مصنوعی: اگر تو مرا جراحتی می‌زنی، خوب است که کسی دیگر دارویی برای درمان داشته باشد و اگر تو زهر می‌کشی، باز هم خوب است که کسی دیگر antidoteی داشته باشد.',NULL);
INSERT INTO "verses" VALUES(1933729,2429,3,1,'بُوَد صبور، دل اندر فراقِ تو؟ حاشاک',NULL,NULL);
INSERT INTO "verses" VALUES(1933730,2429,3,0,'رَوَد به خواب، دو چشم از خیالِ تو؟ هیهات','هوش مصنوعی: آیا ممکن است چشم‌هایم در خواب بروند و از خیال تو دور شوند؟ هرگز! صبر کردن برای دل در جدایی تو بسیار سخت است. چنین چیزی هرگز نخواهد بود.',NULL);
INSERT INTO "verses" VALUES(1933731,2429,2,1,'زمان‌زمان چو گل از غم کُنم گریبان چاک',NULL,NULL);
INSERT INTO "verses" VALUES(1933732,2429,2,0,'نفَس‌نفَس اگر از باد نَشنوم بویش','اگر هر لحظه، بوی تو را از باد نشنوم، هر دم از غصه و غم، گریبانم را پاره می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1933733,2429,1,1,'و گر نه هر دَمم از هجرِ توست بیمِ هلاک',NULL,NULL);
INSERT INTO "verses" VALUES(1933734,2429,1,0,'مرا امیدِ وصالِ تو زنده می‌دارد','هوش مصنوعی: امید دیدارت، همچنان مرا زنده نگه می‌دارد و اگر این امید نبود، هر لحظه از دوری‌ات از درد جدایی در خطر نابودی هستم.',NULL);
INSERT INTO "verses" VALUES(1933735,2429,0,1,'گَرَم تو دوستی از دشمنان ندارم باک',NULL,NULL);
INSERT INTO "verses" VALUES(1933736,2429,0,0,'هزار دشمنم اَر می‌کنند قصدِ هلاک','هوش مصنوعی: اگر هزار نفر بخواهند به من آسیب برسانند، نگران نیستم؛ چون تو دوستم هستی و از دشمنان هیچ ترسی ندارم.',NULL);
INSERT INTO "verses" VALUES(1933737,2428,6,1,'دعایِ اهلِ دلت باد، مونسِ دلِ پاک',NULL,NULL);
INSERT INTO "verses" VALUES(1933738,2428,6,0,'به راهِ میکده، حافظ! خوش از جهان رفتی','هوش مصنوعی: به مسیر میخانه خوش بگذران، ای محبوب. از این دنیا رفته‌ای، اما دعای دوستانت همیشه همراهت باشد و دل پاکت را نیکو نگه دارد.',NULL);
INSERT INTO "verses" VALUES(1933739,2428,5,1,'مباد تا به قیامت خراب طارَمِ تاک',NULL,NULL);
INSERT INTO "verses" VALUES(1933740,2429,6,0,'عنان مَپیچ که گر می‌زنی به شمشیرم','هوش مصنوعی: عنان اسب را به زور نچرخان، چون اگر بخواهی به من حمله‌ور شوی، باید با شمشیر به مقابله بیایی و من در این مبارزه نه سر و دستی دارم، نه وسیله‌ای برای دفاع.',NULL);
INSERT INTO "verses" VALUES(1933741,2428,5,0,'فریبِ دخترِ رَز طُرفِه می‌زند رَهِ عقل','هوش مصنوعی: فریب زیبایی دختر رز می‌تواند سبب شود که آدمی به راهی نادرست برود و عقلش را برای همیشه از دست بدهد و عاقبت کارش به ویرانی و نابودی برسد.',NULL);
INSERT INTO "verses" VALUES(1933742,2428,4,0,'مهندسِ فَلَکی، راهِ دِیرِ شش جهتی','هوش مصنوعی: این بیت اشاره به این دارد که مهندسان آسمانی به گونه‌ای راهی را ایجاد کردند که دیگر راهی زیر زمین وجود ندارد. در واقع، آنها به شکلی پیچیده و استراتژیک چنین مسیری را طراحی کرده‌اند که هیچ دسترسی به منطقه‌ای تحت عنوان دیر مغاک وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1933743,2428,3,1,'به مذهبِ همه کفرِ طریقت است اِمساک',NULL,NULL);
INSERT INTO "verses" VALUES(1933744,2428,3,0,'چه دوزخی، چه بهشتی، چه آدمی، چه پَری','هوش مصنوعی: هر جایگاهی که باشد، چه جهنم، چه بهشت، چه انسان و چه پری، همه اینها در اعتقادات و طریقت‌ها به نوعی خیالی و بی‌اساس به نظر می‌رسند.',NULL);
INSERT INTO "verses" VALUES(1933745,2428,2,1,'که روزِ واقعه پا وا مَگیرم از سرِ خاک',NULL,NULL);
INSERT INTO "verses" VALUES(1933746,2428,2,0,'به خاکِ پایِ تو ای سروِ نازپرورِ من','هوش مصنوعی: به پای تو ای محبوب عزیزم، من در روز سختی هرگز از سر خاک پا نمی‌کشم و همواره به تو وفادار می‌مانم.',NULL);
INSERT INTO "verses" VALUES(1933747,2428,1,1,'که بی‌دریغ زَنَد روزگار تیغِ هَلاک',NULL,NULL);
INSERT INTO "verses" VALUES(1933748,2428,1,0,'برو به هر چه تو داری بخور، دریغ مخور','هوش مصنوعی: برو و از هر چیزی که داری لذت ببر، در استفاده از آن تردید نکن؛ چون روزگار به ناگاه می‌تواند به سختی برایت تمام شود.',NULL);
INSERT INTO "verses" VALUES(1933749,2428,0,1,'از آن گناه که نَفعی رسد به غیر، چه باک؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933750,2428,0,0,'اگر شراب خوری جُرعه‌ای فشان بر خاک','هوش مصنوعی: اگر در می‌گساری، جرعه‌ای از شراب را بر زمین بریزی، از بابت این کار نگران نباش، زیرا اگر کسی از آن بهره‌ای ببرد، تو که ضرری نکرده‌ای.',NULL);
INSERT INTO "verses" VALUES(1933751,2427,8,0,'به خنده گفت که «حافظ! غلامِ طبعِ تواَم»','هوش مصنوعی: او با خنده گفت که من تحت تاثیر حال و هوای تو هستم و ببین چگونه تا چه اندازه من را در وضعیت احمقانه‌ای قرار می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1933752,2427,8,1,'ببین که تا به چه حدَّم همی کُند تحمیق',NULL,NULL);
INSERT INTO "verses" VALUES(1933753,2427,7,0,'اگر به رنگِ عقیقی شد اشکِ من، چه عَجب؟','هوش مصنوعی: اگر اشک من به رنگ عقیق درآمد، جای تعجب نیست؛ چون نشان عشق تو مانند عقیق برجسته و زیباست.',NULL);
INSERT INTO "verses" VALUES(1933754,2427,7,1,'که مُهرِ خاتمِ لَعلِ تو هست همچو عقیق',NULL,NULL);
INSERT INTO "verses" VALUES(1933755,2427,6,1,'به کُنهِ آن نرسد صد‌ هزار فکرِ عمیق',NULL,NULL);
INSERT INTO "verses" VALUES(1933756,2428,4,1,'چنان بِبَست که رَه نیست زیرِ دیرِ مغاک',NULL,NULL);
INSERT INTO "verses" VALUES(1933757,2511,6,1,'شیشه‌ام از چه می‌بَرَد پیشِ طَبیبْ هَر زَمان؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933758,2511,7,0,'حافظ از آبِ زندگی شعرِ تو داد شَربَتَم','هوش مصنوعی: حافظ از دوغ زندگی شعر تو جرعه‌ای به من داد و حالا درخواستی دارم که ترکِ معالجه کن و بیا نسخه‌ای برای شربت من بخوان.',NULL);
INSERT INTO "verses" VALUES(1933759,2511,7,1,'تَرکِ طَبیب کُن بیا نُسخهٔ شَربَتَم بِخوان',NULL,NULL);
INSERT INTO "verses" VALUES(1933760,2596,3,1,'که نهاده‌ست به هر مجلس وعظی دامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933761,2596,3,0,'مرغ زیرک به در خانقه اکنون نپرد','هوش مصنوعی: مرغ باهوش دیگر به درِ صومعه نمی‌پرد، زیرا در هر جلسه‌ی وعظ تله‌ای گذاشته شده است.',NULL);
INSERT INTO "verses" VALUES(1933762,2596,2,1,'صحبتش موهبتی دان و شدن، انعامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933763,2596,2,0,'روزه هر چند که مهمان عزیز است ای دل','هوش مصنوعی: هرچند روزه یک مهمان ارزشمند است، اما ای دل، خود گفتگو با آن را یک نعمت بدان و به قدمت آن خوش آمد بگو.',NULL);
INSERT INTO "verses" VALUES(1933764,2596,1,1,'زلف شمشادقدی، ساعد سیم‌اندامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933765,2596,1,0,'روزها رفت که دست من مسکین نگرفت','هوش مصنوعی: روزها سپری شد و من که بیچاره‌ام، نتوانستم زلف‌های زیبای آن رقاصه‌ی خوش‌هیکل را بگیرم.',NULL);
INSERT INTO "verses" VALUES(1933766,2596,0,1,'گر چه ماه رمضان است بیاور جامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933767,2596,0,0,'زان می عشق، کز او پخته شود هر خامی','هوش مصنوعی: عشق به مانند نوشیدنی‌ای است که می‌تواند هر ناپخته و خامی را به کمال برساند. حتی اگر زمان رمضان باشد، باز هم بر این نکته تأکید می‌شود که باید جامی از این عشق بیاوری.',NULL);
INSERT INTO "verses" VALUES(1933768,2595,6,1,'رندی و هوسناکی در عهد شباب اولی',NULL,NULL);
INSERT INTO "verses" VALUES(1933769,2595,6,0,'چون پیر شدی حافظ از میکده بیرون آی','هوش مصنوعی: زمانی که به پیری رسیدی، حافظ، از میکده خارج شو و از جوانی و شوق و عشق که در زمان جوانی داشتی، یاد کن.',NULL);
INSERT INTO "verses" VALUES(1933770,2595,5,1,'چون تاب کشم باری زان زلف به تاب اولی',NULL,NULL);
INSERT INTO "verses" VALUES(1933771,2595,5,0,'از همچو تو دلداری دل برنکنم آری','هوش مصنوعی: من نمی‌توانم از تو که دلگرمی منی، دل بکنم. اگرچه در برابر مشکلات و سختی‌ها مثل تاب خوردن در برابر باری، هنوز نمی‌توانم از آن زلف زیبای تو فاصله بگیرم.',NULL);
INSERT INTO "verses" VALUES(1933772,2595,4,1,'در سر هوس ساقی در دست شراب اولی',NULL,NULL);
INSERT INTO "verses" VALUES(1933773,2595,4,0,'تا بی سر و پا باشد اوضاع فلک زین دست','هوش مصنوعی: تا زمانی که اوضاع دنیا آشفته و نابسامان باشد، بهتر است که در دل خود آرزوی نوشیدن شراب و لذت بردن از زندگی را داشته باشم.',NULL);
INSERT INTO "verses" VALUES(1933774,2595,3,1,'این قصه اگر گویم با چنگ و رباب اولی',NULL,NULL);
INSERT INTO "verses" VALUES(1933775,2595,3,0,'من حالت زاهد را با خلق نخواهم گفت','هوش مصنوعی: من هرگز نحوه زندگی زاهدانه‌ام را به دیگران نمی‌گویم. اگر بخواهم این داستان را بگویم، با موسیقی و سازهایی مثل چنگ و رباب بیان می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1933776,2595,2,1,'هم سینه پر از آتش هم دیده پرآب اولی',NULL,NULL);
INSERT INTO "verses" VALUES(1933777,2595,2,0,'چون مصلحت اندیشی دور است ز درویشی','هوش مصنوعی: وقتی که انسان در فکر مصلحت و ملاحظات دنیوی باشد، دیگر نمی‌تواند به سادگی و با روحیه‌ای آزاد زندگی کند؛ او هم در دلش آتش حسرت و درد دارد و هم در چشمش اشک.',NULL);
INSERT INTO "verses" VALUES(1933778,2595,1,1,'در کنج خراباتی افتاده خراب اولی',NULL,NULL);
INSERT INTO "verses" VALUES(1933779,2595,1,0,'چون عمر تبه کردم چندان که نگه کردم','نگاه کردم و دیدم چگونه عمرم را تباه کردم (در همان مدرسه‌ای که مورد بحث است). اگر در خراباتی (خلوتگاه رندان، پرستشگاه‌های ادیان کهنتر ویرانه یا خالی، حتی میخانه‌هایی که عملا در خرابات بوده.) مدهوش افتاده بودم سزاوارتر بود.',NULL);
INSERT INTO "verses" VALUES(1933780,2595,0,1,'وین دفتر بی‌معنی غرق می ناب اولی',NULL,NULL);
INSERT INTO "verses" VALUES(1933781,2595,0,0,'این خرقه که من دارم در رهن شراب اولی','این خرقه‌ای (جامه‌ی دراویش و اهل تصوف یک جور درجه‌ی معنوی) که من دارم سزاوارتر این که به رهن شراب ناب درآید. ( شاعر از اعتبار خودش میخواهد برای کاری هزینه کند.) و این دفتر درس هم آلوده به همان شراب سزاوارتر است. (دفتر اشعار نیست. بلکه دفتر درس و مدرسه‌ی مربوط به زمان شاعر است.)',NULL);
INSERT INTO "verses" VALUES(1933782,2594,6,1,'دارد هزار عیب و ندارد تفضلی',NULL,NULL);
INSERT INTO "verses" VALUES(1933783,2594,6,0,'حافظ مدار امید فرج از مدار چرخ','هوش مصنوعی: امید به فرج را از چرخ فلک دور نگه‌دار؛ چون چرخ فلک هزاران عیب دارد و هیچ نیکی و احسانی را نمی‌شناسد.',NULL);
INSERT INTO "verses" VALUES(1933784,2594,5,1,'کس بی بلای خار نچیده‌ست از او گلی',NULL,NULL);
INSERT INTO "verses" VALUES(1933785,2594,5,0,'بس گل شکفته می‌شود این باغ را ولی','هوش مصنوعی: باغ پر از گل‌های زیباست، اما هیچ‌کس نمی‌تواند از آن‌ها بهره‌برداری کند، زیرا همه‌جا پر از خارهایی است که دردسر می‌آورند.',NULL);
INSERT INTO "verses" VALUES(1933786,2594,4,1,'گشتم چنان که هیچ نماندم تحملی',NULL,NULL);
INSERT INTO "verses" VALUES(1933787,2594,4,0,'چون کرد در دلم اثر آواز عندلیب','هوش مصنوعی: وقتی صدای بلبل در دل من تأثیر گذاشت، طوری شدم که هیچ تحملی برایم نماند.',NULL);
INSERT INTO "verses" VALUES(1933788,2594,3,1,'آن را تفضلی نه و این را تبدلی',NULL,NULL);
INSERT INTO "verses" VALUES(1933789,2596,4,0,'گله از زاهد بدخو نکنم؛ رسم این است','هوش مصنوعی: از زاهد بدخلق شکایت نمی‌کنم؛ چون همیشه پس از سپیده‌دم، شب به همراه خود می‌آورد.',NULL);
INSERT INTO "verses" VALUES(1933790,2594,3,0,'گل یار حسن گشته و بلبل قرین عشق','هوش مصنوعی: گل، به محبوبی زیبا تبدیل شده و بلبل، عاشق آن گشته است. این عشق، لطف و عنایت خاصی می‌خواهد، نه تنها یک تغییر و دگرگونی.',NULL);
INSERT INTO "verses" VALUES(1933791,2596,4,1,'که چو صبحی بدمد، در پی‌اش افتد شامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933792,2596,5,1,'برسانش ز من ای پیک صبا پیغامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933793,2598,3,0,'إذا تَغَرَّدَ عَن ذِی الْأَراکِ طائرُ خَیرٍ','هوش مصنوعی: اگر پرنده‌ای از درختان خوشبو دور شود، آوای غم‌انگیز کبوتران در باغش تنها نخواهد ماند.',NULL);
INSERT INTO "verses" VALUES(1933794,2598,2,1,'به سان بادهٔ صافی در آبگینهٔ شامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933795,2598,2,0,'بیا به شام غریبان و آب دیدهٔ من بین','هوش مصنوعی: به مکان تنهایی و غم من بیا و اشک‌هایم را ببین که مانند شراب خالص در لیوان شفاف می‌درخشد.',NULL);
INSERT INTO "verses" VALUES(1933796,2598,1,1,'مَنِ الْمُبَلِّغُ عَنّی إلی سُعادَ سلامی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933797,2598,1,0,'پیام دوست شنیدن سعادت است و سلامت','هوش مصنوعی: شنیدن پیام دوست، نشانه‌ی خوشبختی و سلامتی است. آیا کسی هست که از طرف من به سعاد سلام برساند؟',NULL);
INSERT INTO "verses" VALUES(1933798,2598,0,1,'فدای خاک در دوست باد جان گرامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933799,2598,0,0,'أَتَتْ رَوائِحُ رَنْدِ الْحِمیٰ و زادَ غَرامی','هوش مصنوعی: بوی خوش رند حمیى به مشام می‌رسد و عشق من افزایش یافته است. جان عزیزم فدای خاک محبوبم باد.',NULL);
INSERT INTO "verses" VALUES(1933800,2597,8,1,'که چنان کشنده‌ای را نکند کس انتقامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933801,2597,8,0,'بگشای تیر مژگان و بریز خون حافظ','هوش مصنوعی: چشم‌های زیبا و کشنده‌ات را باز کن و اجازه بده خون حافظ بریزد؛ زیرا هیچ‌کس نمی‌تواند از چنین قاتلی انتقام بگیرد.',NULL);
INSERT INTO "verses" VALUES(1933802,2597,7,1,'که لبت حیات ما بود و نداشتی دوامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933803,2597,7,0,'به کجا برم شکایت؟ به که گویم این حکایت؟','هوش مصنوعی: نمی‌دانم کجا باید شکایت کنم یا این داستان را به که بگویم؛ زیرا لب تو، زندگی ما بود اما نتوانستی تا آخر دوام بیاوری.',NULL);
INSERT INTO "verses" VALUES(1933804,2597,6,1,'که چو بنده کمتر افتد به مبارکی غلامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933805,2597,6,0,'سر خدمت تو دارم بخرم به لطف و مفروش','هوش مصنوعی: من آماده‌ام تا دل و جانم را برای خدمت به تو تقدیم کنم و هیچ چیز را به قیمت بی‌مقداری نمی‌فروشم، زیرا هر چه کمتر خود را در برابر قدرت تو مطرح کنم، خوشبخت‌تر خواهم بود که در خدمت تو هستم.',NULL);
INSERT INTO "verses" VALUES(1933806,2597,5,1,'که چو مرغ، زیرک افتد نفتد به هیچ دامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933807,2597,5,0,'ز رهم میفکن ای شیخ به دانه‌های تسبیح','هوش مصنوعی: ای شیخ، بر سر راهم سنگ نینداز و مزاحم نشو، زیرا که من مانند مرغ زیرک هستم و به هیچ دام و فریبی نمی‌افتم.',NULL);
INSERT INTO "verses" VALUES(1933808,2597,4,1,'به هزار بار بهتر ز هزار پخته خامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933809,2597,4,0,'اگر این شراب خام است اگر آن حریف پخته','هوش مصنوعی: اگر این شراب تازه و ناپخته است و آن شخص باتجربه و پخته است، باز هم هزار بار بهتر است که انسان خام و ناپخته باشد تا آنچه که پخته و تجربه کرده است.',NULL);
INSERT INTO "verses" VALUES(1933810,2597,3,1,'نه به نامه‌ای پیامی نه به خامه‌ای سلامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933811,2597,3,0,'عجب از وفای جانان که عنایتی نفرمود','هوش مصنوعی: عجیب است که معشوق وفادار هیچ توجهی نکرد، نه به نامه‌ای پاسخی داد و نه با قلمی سلامی فرستاد.',NULL);
INSERT INTO "verses" VALUES(1933812,2597,2,1,'که بضاعتی نداریم و فکنده‌ایم دامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933813,2597,2,0,'تو که کیمیافروشی نظری به قلب ما کن','هوش مصنوعی: ای کسی که جواهرات گرانبها می‌فروشی، لطفاً نگاهی به دل ما بینداز که ما چیزی نداریم و در دام عشق تو افتاده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1933814,2597,1,1,'که به همت عزیزان برسم به نیک‌نامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933815,2597,1,0,'شده‌ام خراب و بدنام و هنوز امیدوارم','هوش مصنوعی: من حالا به شدت دچار مشکلات و بدنامی شده‌ام، اما همچنان امیدوارم که با کمک و تلاش عزیزانم، بتوانم به مقام و اعتبار خوبی برسم.',NULL);
INSERT INTO "verses" VALUES(1933816,2597,0,1,'که به کوی مِی‌فروشان دو هزار جم به جامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933817,2597,0,0,'که بَرَد به نزد شاهان ز من گدا پیامی؟','هوش مصنوعی: چه کسی به نزد پادشاهان از من فقیر پیامی خواهد برد؟ در حالی که در کوی می‌فروشان، دو هزار جام پر از شراب وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1933818,2596,7,1,'کام دشوار به دست آوری از خودکامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933819,2596,7,0,'حافظا گر ندهد دادِ دلت آصف عهد','هوش مصنوعی: حافظ، اگر دل تو را به خواسته‌ات نرسانند، در این صورت برای به دست آوردن آرزوی سخت و دشوار، باید از خودخواهی خود دوری کنی.',NULL);
INSERT INTO "verses" VALUES(1933820,2596,6,1,'بود آیا که کند یاد ز دردآشامی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933821,2596,6,0,'آن حریفی که شب و روز می صاف کشد','هوش مصنوعی: آیا ممکن است کسی که همیشه در حال نوشیدن شراب است، به یاد دردهای ناشی از آن بیفتد؟',NULL);
INSERT INTO "verses" VALUES(1933822,2596,5,0,'یار من چون بخرامد به تماشای چمن','هوش مصنوعی: وقتی یار من به تماشا در چمن می‌آید، ای پیک صبح، پیامم را به او برسان.',NULL);
INSERT INTO "verses" VALUES(1933823,2594,2,1,'می‌کردم اندر آن گل و بلبل تاملی',NULL,NULL);
INSERT INTO "verses" VALUES(1933824,2594,2,0,'می‌گشتم اندر آن چمن و باغ دم به دم','هوش مصنوعی: در حال قدم زدن در چمن و باغ بودم و هر لحظه در گل‌ها و آواز بلبل‌ها اندیشه می‌کردم.',NULL);
INSERT INTO "verses" VALUES(1933825,2594,1,1,'و اندر چمن فکنده ز فریاد غلغلی',NULL,NULL);
INSERT INTO "verses" VALUES(1933826,2592,3,0,'به هر منزل که رو آرد خدا را','هوش مصنوعی: هر جا که خداوند به کسی نظر کند، او را با لطف بی‌پایانش حفظ می‌کند.',NULL);
INSERT INTO "verses" VALUES(1933827,2592,2,1,'و أَدعُو بِالتَّواتُر و التَّوالي',NULL,NULL);
INSERT INTO "verses" VALUES(1933828,2592,2,0,'دعاگوی غریبان جهانم','هوش مصنوعی: من برای غریبان جهان دعا می‌کنم و این دعا را پی در پی و مداوم انجام می‌دهم.',NULL);
INSERT INTO "verses" VALUES(1933829,2592,1,1,'و دارٍ بِاللَّویٰ فوقَ الرِّمالِ',NULL,NULL);
INSERT INTO "verses" VALUES(1933830,2592,1,0,'عَلیٰ وادِي الْأَراک و مَن عَلَیها','هوش مصنوعی: علی در منطقه اراک و آنچه که بر آن است و خانه‌ای در بالای تپه‌های شنی دارد.',NULL);
INSERT INTO "verses" VALUES(1933831,2592,0,1,'و جاوَبَتِ الْمثاني و الْمِثالي',NULL,NULL);
INSERT INTO "verses" VALUES(1933832,2592,0,0,'سَلامُ اللّهِ ما کَرَّ اللَّیالي','هوش مصنوعی: درود خداوند بر شب‌هایی که به جادوی شباهت‌ها پاسخ می‌دهند و دنیای زیبایی را به نمایش می‌گذارند.',NULL);
INSERT INTO "verses" VALUES(1933833,2591,8,1,'برهان ملک و ملت بونصر بوالمعالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933834,2591,8,0,'مسندفروز دولت، کانِ شکوه و شوکت','هوش مصنوعی: این بیت به بیان عظمت و قدرت یک شخصیت重要 اشاره دارد که با مقام و منزلت خود، موجب مدافعّت و پشتیبانی از کشور و مردم شده است. او به نوعی نمایانگر شکوه و اقتدار است و توانایی‌هایش باعث ترفیع و بلندآوری دیگران نیز می‌شود.',NULL);
INSERT INTO "verses" VALUES(1933835,2591,7,1,'یا رب که جاودان باد این قدر و این معالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933836,2591,7,0,'اَلْمُلْکُ قَد تَباهیٰ مِن جِدِّهِ و جَدِّه','هر سلطنتی به تلاش و نیاکانش می‌نازد(مباهات می‌کند)، ای پروردگار، کاش این مقام و این ویژگی‌ها جاودانه بمانند.',NULL);
INSERT INTO "verses" VALUES(1933837,2591,6,1,'قُمْ فَاسْقِني رَحیقاً أَصْفیٰ مِنَ الزُّلالِ',NULL,NULL);
INSERT INTO "verses" VALUES(1933838,2591,6,0,'صافیست جام خاطر در دور آصف عهد','هوش مصنوعی: در اینجا شاعر به زیبایی و صفای دل اشاره می‌کند و می‌خواهد از جامی پر از نوشیدنی خالص و خوشمزه بهره‌مند شود. او به دقت و ظرافتی که در انتخاب و نوشیدن این نوشیدنی وجود دارد تاکید می‌کند و از دیگری درخواست می‌کند که او را با این نوشیدنی لطیف سیراب کند. این اشاره به تجربیات دلنشین و نشاط‌آور در زندگی دارد.',NULL);
INSERT INTO "verses" VALUES(1933839,2591,5,1,'حافظ مکن شکایت تا می خوریم حالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933840,2591,5,0,'چون نیست نقش دوران در هیچ حالْ ثابت','هوش مصنوعی: از آنجایی که زندگی و زمان دائماً در حال تغییر و تحول هستند و هیچ چیز ثابت نمی‌ماند، بهتر است در هنگام نوشیدن شراب شکایت و ناله نکنیم.',NULL);
INSERT INTO "verses" VALUES(1933841,2591,4,1,'امن و شرابِ بی‌غش، معشوق و جای خالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933842,2591,4,0,'از چار چیز مگذر گر عاقلی و زیرک','هوش مصنوعی: اگر عاقل و باهوش هستی، از چهار چیز دوری کن: امنیت، شراب ناب، معشوق واقعی و مکانی که خالی است.',NULL);
INSERT INTO "verses" VALUES(1933843,2591,3,1,'تا در به در بگردم قَلّاش و لااُبالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933844,2591,3,0,'ساقی بیار جامی و از خلوتم برون کش','هوش مصنوعی: ای ساقی، یک جام برایم بیاور و مرا از تنهایی‌ام بیرون ببرد تا بتوانم در کوچه‌ها بچرخم و بی‌خیال و بی‌توجه به دنیا باشم.',NULL);
INSERT INTO "verses" VALUES(1933845,2591,2,1,'نومید کی توان بود از لطف لایزالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933846,2591,2,0,'می ده که گرچه گشتم نامه‌سیاه عالم','هوش مصنوعی: در این بیت، شاعر از معانی عمیق و روحی خود سخن می‌گوید. او به رغم اینکه در دنیا با مشکلات و ناامیدی روبرو شده و در زندگی‌اش مسائلی دشوار وجود دارد، اما همچنان امیدوار است که لطف و رحمت بی‌پایان خداوند بتواند او را از این شرایط نجات دهد. در واقع، او به این باور دارد که در هر حالتی، محبت الهی می‌تواند بر دشواری‌ها غلبه کند و انسان را به سمت امید و روشنایی هدایت کند.',NULL);
INSERT INTO "verses" VALUES(1933847,2591,1,1,'تا خود چه نقش بازد این صورت خیالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933848,2591,1,0,'حالی خیال وصلت خوش می‌دهد فریبم','هوش مصنوعی: حالت خیالی وصالت خوب و دلپذیر است، بنابراین مرا فریب می‌دهد تا ببینم این تصویر خیالی چه نقشی می‌تواند بزند.',NULL);
INSERT INTO "verses" VALUES(1933849,2591,0,1,'یا رب چه درخور آمد گِردَش خط هلالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933850,2591,0,0,'یا مُبْسِماً یُحاکي دُرْجاً مِنَ اللِّآلي','هوش مصنوعی: ای زیبای خوش‌صوت، گویای دلنشین، خداوند، چه شایسته است گردش خط باریک و هلالی!',NULL);
INSERT INTO "verses" VALUES(1933851,2590,8,1,'که همچو صنع خدایی ورای ادراکی',NULL,NULL);
INSERT INTO "verses" VALUES(1933852,2590,8,0,'ز وصف حسن تو حافظ چگونه نطق زند؟','هوش مصنوعی: حافظ در اینجا می‌گوید که چگونه می‌تواند درباره‌ی زیبایی‌های تو صحبت کند، در حالی که زیبایی تو فراتر از درک و فهم انسان‌هاست و به نوعی به قدرت آفرینش خداوند نزدیک است.',NULL);
INSERT INTO "verses" VALUES(1933853,2590,7,1,'أرَی مَآثِرَ مَحیایَ مِن مُحَیّاکِ',NULL,NULL);
INSERT INTO "verses" VALUES(1933854,2590,7,0,'اثر نماند ز من، بی شمایلت، آری','هوش مصنوعی: بی تو اثری از من باقی نمانده است، آری، من آثار زندگی‌ام را فقط از وجود تو می‌بینم.',NULL);
INSERT INTO "verses" VALUES(1933855,2592,3,1,'نگه دارش به لطف لایزالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933856,2592,4,0,'منال ای دل که در زنجیر زلفش','هوش مصنوعی: ای دل، ناراحت نباش که همه در زنجیر موهای او گرفتارند و دچار سردرگمی شده‌اند.',NULL);
INSERT INTO "verses" VALUES(1933857,2592,4,1,'همه جمعیت است آشفته حالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933858,2592,5,0,'ز خطت صد جمال دیگر افزود','هوش مصنوعی: از زیبایی‌های چهره‌ات به قدری افزوده شده که امیدوارم عمرت صد سال با عظمت باشد.',NULL);
INSERT INTO "verses" VALUES(1933859,2594,1,0,'مسکین چو من به عشق گلی گشته مبتلا','هوش مصنوعی: بیچاره‌ای مثل من به خاطر عشق به یک گل دچار مشکل شده و در میان باغ به خاطر فریادش به صدا در آمده است.',NULL);
INSERT INTO "verses" VALUES(1933860,2594,0,1,'آمد به گوش ناگهم آواز بلبلی',NULL,NULL);
INSERT INTO "verses" VALUES(1933861,2594,0,0,'رفتم به باغ صبحدمی تا چنم گلی','هوش مصنوعی: به باغی صبحگاهی رفتم و در حین چیدن گل، ناگهان صدای بلبل به گوشم رسید.',NULL);
INSERT INTO "verses" VALUES(1933862,2593,6,1,'زین بیشتر بباید بر هجرت احتمالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933863,2593,6,0,'حافظ مکن شکایت گر وصل دوست خواهی','هوش مصنوعی: اگر به وصال دوست علاقه‌مندی، به شکایت و ناله کردن نپرداز. باید بیشتر از این بر غیبت احتمالی او صبر کنی.',NULL);
INSERT INTO "verses" VALUES(1933864,2593,5,1,'شد شخص ناتوانم باریک چون هلالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933865,2593,5,0,'رحم آر بر دل من کز مهر روی خوبت','هوش مصنوعی: دل من را به حال خود رحم کن که به خاطر محبت چهره زیبا و نازنین تو، حالتی ناتوان و ضعیف پیدا کرده‌ام، مثل هلالی که باریک و نحیف است.',NULL);
INSERT INTO "verses" VALUES(1933866,2593,4,1,'کز خواب می‌نبیند چشمم به جز خیالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933867,2593,4,0,'چون من خیال رویت جانا به خواب بینم','هوش مصنوعی: وقتی که به خواب فکر روی تو را می‌بینم، چشمانم در خواب چیزی جز آن خیال را نمی‌بینند.',NULL);
INSERT INTO "verses" VALUES(1933868,2593,3,1,'وان دم که بی تو باشم یک لحظه هست سالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933869,2593,3,0,'آن دم که با تو باشم یک سال هست روزی',': زمانی که در کنار تو هستم، احساس می‌کنم که يک سال همچون يک لحظه زود ميگذرد، اما زمانی که دور از تو هستم، یک لحظه هم برایم به اندازه یک سال می‌گذرد.',NULL);
INSERT INTO "verses" VALUES(1933870,2593,2,1,'هرگز به عمر روزی روزی شود وصالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933871,2593,2,0,'شد حظ عمر حاصل گر زان که با تو ما را','هوش مصنوعی: اگر عمرم در این دنیا به خوشی سپری شود، تنها به خاطر این است که هرگز روزی بدون وصال تو نگذرانده‌ام.',NULL);
INSERT INTO "verses" VALUES(1933872,2593,1,1,'آید به هیچ معنی زین خوب‌تر مثالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933873,2598,3,1,'فَلا تَفَرَّدَ عَن رَوضِها أَنینُ حَمامي',NULL,NULL);
INSERT INTO "verses" VALUES(1933874,2593,1,0,'در وهم می‌نگنجد کاندر تصور عقل','هوش مصنوعی: در خیال نمی‌گنجد که چیزی بهتر از این، در تصور عقل بیاید.',NULL);
INSERT INTO "verses" VALUES(1933875,2593,0,0,'بگرفت کار حسنت چون عشق من کمالی','هوش مصنوعی: اگر زیبایی تو به دل من افتاده، مانند عشق من همواره در کمال است، خوش باش، چرا که هیچ‌کدام از این دو هرگز کاهش نمی‌یابند.',NULL);
INSERT INTO "verses" VALUES(1933876,2592,11,1,'و عِلْمُ اللّهِ حَسْبي مِن سُؤالي',NULL,NULL);
INSERT INTO "verses" VALUES(1933877,2592,11,0,'خدا داند که حافظ را غرض چیست','هوش مصنوعی: خدا می‌داند که هدف حافظ چیست و دانش خدا برای من کافی است و نیازی به پرسش ندارم.',NULL);
INSERT INTO "verses" VALUES(1933878,2592,10,1,'من بدنامِ رندِ لااُبالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933879,2592,10,0,'کجا یابم وصال چون تو شاهی','هوش مصنوعی: کجا می‌توانم مانند تو، که شاهی بی‌نظیر هستی، به وصال برسم؟ من تنها یک رند مشهور به بی‌محلی و بدنامی هستم.',NULL);
INSERT INTO "verses" VALUES(1933880,2592,9,1,'مباد از شوق و سودای تو خالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933881,2592,9,0,'سویدای دل من تا قیامت','هوش مصنوعی: آرزو و اشتیاق من برای تو تا همیشه باقی خواهد ماند و هرگز از عشق و محبت تو خالی نخواهد شد.',NULL);
INSERT INTO "verses" VALUES(1933882,2592,8,1,'و ذِکرُک مونِسي في کُلِّ حالِ',NULL,NULL);
INSERT INTO "verses" VALUES(1933883,2592,8,0,'فَحُبُّک راحَتي في کُلِّ حینٍ','هوش مصنوعی: عشق تو همیشه برای من آرامش بخش است و یاد تو در هر شرایطی برایم تسکین‌دهنده است.',NULL);
INSERT INTO "verses" VALUES(1933884,2592,7,1,'که گرد مه کشد خط هلالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933885,2592,7,0,'بر آن نقاش قدرت آفرین باد','هوش مصنوعی: به آن هنرمند بزرگوار درود باد که با توانایی‌اش، ابرها را کنار می‌زند و هلال ماه را به نمایش می‌گذارد.',NULL);
INSERT INTO "verses" VALUES(1933886,2592,6,1,'زیانِ مایهٔ جاهی و مالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933887,2592,6,0,'تو می‌باید که باشی ور نه سهل است','هوش مصنوعی: تو باید در زندگی حضور داشته باشی، وگرنه از دست دادن موقعیت‌ها و دارایی‌ها ساده و عادی خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1933888,2592,5,1,'که عمرت باد صد سال جلالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933889,2593,0,1,'خوش باش زان که نبود این هر دو را زوالی',NULL,NULL);
INSERT INTO "verses" VALUES(1933890,2598,4,0,'بسی نماند که روز فراق یار سر آید','هوش مصنوعی: مدت زیادی نخواهد گذشت که روز جدایی از معشوق به پایان برسد، زیرا از دشت‌های سرسبز، ساختمان‌های خیمه‌سانی را مشاهده کردم.',NULL);
INSERT INTO "verses" VALUES(1933891,2598,4,1,'رَأَیْتُ مِن هَضَباتِ الْحِمیٰ قِبابَ خِیامِ',NULL,NULL);
INSERT INTO "verses" VALUES(1933892,2598,5,0,'خوشا دمی که درآیی و گویمت به سلامت','هوش مصنوعی: خوشحالم که لحظه‌ای به من سر می‌زنی و می‌توانم بگویم که خوش آمدی. تو با قدمت به اینجا آمده‌ای که بهترین و نیکوترین جا برای فرود آمدن است.',NULL);
INSERT INTO "verses" VALUES(1933893,2603,0,0,'هواخواه توام جانا و می‌دانم که می‌دانی','عزیزم من عاشق تو هستم و می‌دانم که تو هم این مطلب را می دانی؛ زیرا تو هم آنچه را که دیدنی نیست، می‌بینی و هم آنچه را که نوشته نشده است، می‌خوانی.',NULL);
INSERT INTO "verses" VALUES(1933894,2602,12,1,'حال خود بخواهم گفت پیش آصف ثانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933895,2602,12,0,'گر تو فارغی از ما ای نگار سنگین‌دل','هوش مصنوعی: اگر تو از ما بی‌خبر و غافل هستی، ای دل سنگین‌ات، می‌خواهم حال خود را برای آصف ثانی بگویم.',NULL);
INSERT INTO "verses" VALUES(1933896,2602,11,1,'ای شکنج گیسویت مجمع پریشانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933897,2602,11,0,'جمع کن به احسانی حافظ پریشان را','هوش مصنوعی: ای دلنواز، با نیکی و محبت، دل شیدای حافظ را جمع و جور کن، زیرا گیسوی تو همچون تنگنایی است که دل‌های پریشان را در خود می‌فشرد.',NULL);
INSERT INTO "verses" VALUES(1933898,2602,10,1,'ابروی کماندارت می‌برد به پیشانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933899,2602,10,0,'دل ز ناوک چشمت گوش داشتم لیکن','هوش مصنوعی: دل از تیر نگاه تو دردمند بود، اما ابروی کمانی تو چنان زیبایی دارد که توجه‌ام را به خود جلب می‌کند.',NULL);
INSERT INTO "verses" VALUES(1933900,2602,9,1,'تیز می‌روی جانا ترسمت فرومانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933901,2602,9,0,'می‌روی و مژگانت خون خلق می‌ریزد','هوش مصنوعی: تو به سرعت می‌روی و پلک‌هایت مانند تیغه‌ای تیز، قلب‌ها را می‌شکافد و خون به زمین می‌ریزد. ای محبوب، نگرانم که به ناگاه از نظرم محو شوی.',NULL);
INSERT INTO "verses" VALUES(1933902,2602,8,1,'با طبیب نامحرم حال درد پنهانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933903,2602,8,0,'پیش زاهد از رندی دم مزن که نتوان گفت','هوش مصنوعی: حرف زدن از رندی و زندگی آزاد در حضور زاهد کار درستی نیست، چون نمی‌توان در حضور کسی که شناخت کافی ندارد، به درد دل‌های پنهانی پرداخت.',NULL);
INSERT INTO "verses" VALUES(1933904,2602,7,1,'کز غمش عجب بینم حال پیر کنعانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933905,2602,7,0,'یوسف عزیزم رفت ای برادران رحمی','هوش مصنوعی: یوسف عزیزم رفته و من با دیدن غم او حال پیر کنعان را می‌بینم و از این وضعیت شگفت‌زده‌ام. ای برادران، رحم کنید!',NULL);
INSERT INTO "verses" VALUES(1933906,2602,6,1,'کاین همه نمی‌ارزد شغل عالم فانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933907,2602,6,0,'پند عاشقان بشنو و از در طرب بازآ','هوش مصنوعی: به عشق و دل‌باختگی توجه کن و از غم و اندوه رها شو، چرا که این همه سختی و تلاش در این دنیای گذرا ارزش ندارد.',NULL);
INSERT INTO "verses" VALUES(1933908,2602,5,1,'در پناه یک اسم است خاتم سلیمانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933909,2602,5,0,'با دعای شب‌خیزان ای شکردهان مستیز','هوش مصنوعی: با دعا و نیایش افرادی که در شب بیدارند و از خداوند کمک می‌خواهند، تو نمی‌توانی به راحتی بر کسی که شیرینی طعم شفای الهی را چشیده است، برتری پیدا کنی؛ چرا که در سایه یک نام مقدس، شالوده و اصل وجود او، مانند انگشتری که به سلیمان تعلق دارد، استوار است.',NULL);
INSERT INTO "verses" VALUES(1933910,2602,4,1,'جنس خانگی باشد همچو لعل رمانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933911,2602,4,0,'محتسب نمی‌داند این قدر که صوفی را','هوش مصنوعی: محتسب (نگهبان اخلاق) نمی‌داند که صوفی چه اندازه می‌تواند به عشق و شور و شوقی که در دل دارد، شبیه به نگین‌های قیمتی باشد.',NULL);
INSERT INTO "verses" VALUES(1933912,2602,3,1,'عاقلا! مکن کاری کآورد پشیمانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933913,2602,3,0,'زاهد پشیمان را ذوق باده خواهد کشت','فردی که به دلیل تظاهر به زهد از لذت باده نوشی محروم شده، به خاطر عشق به شراب دچار دردسر شده است، پس ای عاقل کاری نکن که باعث پشیمانی شود.',NULL);
INSERT INTO "verses" VALUES(1933914,2602,2,1,'گر به جای من سروی غیر دوست بنشانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933915,2602,2,0,'باغبان چو من زین جا بگذرم حرامت باد','هوش مصنوعی: اگر من از اینجا بروم، باغبان، امیدوارم که هیچ درخت دیگری جز دوست من در این مکان نروی.',NULL);
INSERT INTO "verses" VALUES(1933916,2602,1,1,'جهد کن که از دولت دادِ عیش بستانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933917,2602,1,0,'کام‌بخشیِ گردون عمر در عوض دارد','هوش مصنوعی: زندگی انسان به ما فرصتی می‌دهد، بنابراین تلاش کن تا از آن لذت ببری و خوشی‌های زندگی را به دست آوری.',NULL);
INSERT INTO "verses" VALUES(1933918,2602,0,1,'حاصل از حیات ای جان این دم است تا دانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933919,2602,0,0,'وقت را غنیمت دان آن قدر که بتْوانی','هوش مصنوعی: زمان را به خوبی و به قدر کافی استفاده کن، زیرا هر لحظه از زندگی‌ات مهم است و با ارزش. سعی کن از این لحظات بهره‌برداری کنی تا ارزش آن را درک کنی.',NULL);
INSERT INTO "verses" VALUES(1933920,2601,9,0,'ای نسیم سحری خاک در یار بیار','هوش مصنوعی: ای نسیم صبحگاهی، خاک را به یار برسان که حافظ از آن خاک برای دلش روشنی و نور می‌گیرد.',NULL);
INSERT INTO "verses" VALUES(1933921,2601,9,1,'که کند حافظ از او دیدهٔ دل نورانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933922,2603,0,1,'که هم نادیده می‌بینی و هم ننوشته می‌خوانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933923,2603,1,0,'ملامت‌گو چه دریابد میان عاشق و معشوق؟','سرزنشگر، از آنچه میان عاشق و معشوق می گذرد، چه می فهمد!؟ شخص نابینا، هیچ چیز، خصوصا اسرار پنهانی را نمی بیند.',NULL);
INSERT INTO "verses" VALUES(1933924,2603,1,1,'نبیند چشم نابینا خصوص اسرار پنهانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933925,2603,2,0,'بیفشان زلف و صوفی را به پابازی و رقص آور','موی خود را در هم بریز و [با این کار] صوفی را به پایکوبی و رقص بیاور تا [در اثر رقص] از هر تکه لباسش هزاران بت بیرون بیاندازی.',NULL);
INSERT INTO "verses" VALUES(1933926,2605,1,0,'تو پیک خلوت رازی و دیده بر سر راهت','تو در خلوت پیام‌آور اسراری و علاقمندان، چشم‌انتظارت هستند؛ امور را آنچنان که می‌دانی مهربانانه تدبیر کن نه به حکم و اجبار.',NULL);
INSERT INTO "verses" VALUES(1933927,2605,0,1,'گذر به کوی فلان کن، در آن زمان که تو دانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933928,2605,0,0,'نسیم صبح سعادت! بدان نشان که تو دانی','هوش مصنوعی: نسیم صبح خوشبختی! به یاد داشته باش که تو می‌دانی چه زمانی باید به کوی خاصی بروی.',NULL);
INSERT INTO "verses" VALUES(1933929,2604,6,1,'آن را که دمی از نظر خویش برانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933930,2604,6,0,'چون اشک بیندازیش از دیدهٔ مردم','هوش مصنوعی: وقتی که به خاطر دیگران اشک می‌ریزی، بدان که کسی که لحظه‌ای او را از جلوی چشمانت دور کنی، ممکن است دلت را به درد بیاورد.',NULL);
INSERT INTO "verses" VALUES(1933931,2604,5,1,'بیمار که دیده‌ست بدین سخت کمانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933932,2604,5,0,'چشم تو خدنگ از سپر جان گذراند','هوش مصنوعی: چشم تو مانند تیر است که به راحتی از سپر جان من عبور می‌کند. من تنها کسی هستم که چنین رنجی را دیده‌ام و این درد را درک کرده‌ام.',NULL);
INSERT INTO "verses" VALUES(1933933,2604,4,1,'ترسم ندهی کامم و جانم بستانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933934,2604,4,0,'گویی بدهم کامت و جانت بستانم','هوش مصنوعی: به نظر می‌رسد که اگر من به تو آنچه را که می‌خواهی بدهم، جانم را از من می‌گیری. اما می‌ترسم که تو هم در عوض، آنچه را که من می‌خواهم به من ندهی و جانم را بگیری.',NULL);
INSERT INTO "verses" VALUES(1933935,2604,3,1,'چون سوسن آزاده چرا جمله زبانی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933936,2604,3,0,'صد بار بگفتی که دهم زان دهنت کام','صد بار گفتى که از دهان خود کام تو را مى‌دهم؛چرا مانند سوسن آزاده سراپا زبان هستى؟[يعنى چرا فقط وعده مى‌دهى و عمل نمى‌کنى؟مقصود از سوسن آزاده،سوسن سفيد است که پنج‌برگ و پنج کاسبرگ دارد و معمولا برگ‌هاى آن را به زبان مانند مى‌کنند.از اين رو به آن سوسن ده‌زبان هم مى‌گويند.«چرا جمله زبانى»ناظر بر همين ويژگى سوسن است.گويى سراپاى سوسن زبان‌است.]',NULL);
INSERT INTO "verses" VALUES(1933937,2604,2,1,'هرگز نبود غنچه بدین تنگ دهانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933938,2604,2,0,'تشبیه دهانت نتوان کرد به غنچه','هوش مصنوعی: دهان تو به هیچ وجه قابل مقایسه با غنچه نیست، زیرا هیچ غنچه‌ای به این اندازه تنگ و کوچک نیست.',NULL);
INSERT INTO "verses" VALUES(1933939,2604,1,1,'ای خسرو خوبان که تو شیرین زمانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933940,2601,8,0,'سر عاشق که نه خاک در معشوق بود','هوش مصنوعی: اگر دل عاشق به معشوق نرسد، هرگز از درد و رنج سردرگمی رهایی نخواهد یافت.',NULL);
INSERT INTO "verses" VALUES(1933941,2604,1,0,'شیرین‌تر از آنی به شکرخنده که گویم','هوش مصنوعی: تو به قدری شیرینی که هیچ چیز نمی‌تواند با لبخند شیرین تو مقایسه شود. ای خوش‌صورت‌ترین، تو در زمان خود از همه شیرین‌تر هستی.',NULL);
INSERT INTO "verses" VALUES(1933942,2604,0,0,'گفتند خلایق که تویی یوسف ثانی','خلایق می‌گویند که تو همان یوسف دوم هستی، اما وقتی که بهتر نگاه و تفکر کردم فهمیدم که از آن هم بهتری.',NULL);
INSERT INTO "verses" VALUES(1933943,2603,8,0,'خیال چنبر زلفش فریبت می‌دهد حافظ','حافظ مراقب باش که خیال موی معشوق، موجب فریبت می شود؛ و مراقب باش که سراغ آینده ناممکن نروی.',NULL);
INSERT INTO "verses" VALUES(1933944,2603,8,1,'«نگر تا حلقهٔ اقبال ناممکن نجنبانی»',NULL,NULL);
INSERT INTO "verses" VALUES(1933945,2603,7,0,'ملول از همرهان بودن طریق کاردانی نیست','از همراهان زندگی، ملول و ناراحت بودن، منطقی و هوشمندانه نیست؛ دشواری زندگی را به امید روزهای آسانی، تحمل کن.',NULL);
INSERT INTO "verses" VALUES(1933946,2603,7,1,'بکش دشواری منزل به یاد عهد آسانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933947,2603,6,0,'دریغا عیش شب‌گیری که در خواب سحر بگذشت','حیف از لحظاتی که به جای لذت خلوت شبانه با معشوق، به خواب گذشت؛ ای دل، تو جز وقتی که فرصتها را از دست بدهی و درمانده شوی، قدر آنها را نمی دانی.',NULL);
INSERT INTO "verses" VALUES(1933948,2603,6,1,'ندانی قدر وقت ای دل مگر وقتی که درمانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933949,2603,5,0,'چراغ افروز چشم ما نسیم زلف جانان است','خدایا روشنایی بخش چشم ما عاشقان، نسیم موی معشوق است؛ بنابراین، نگران پریشانی حاصل از عشق، نیستیم.',NULL);
INSERT INTO "verses" VALUES(1933950,2603,5,1,'مباد این جمع را یا رب غم از باد پریشانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933951,2603,4,0,'ملک در سجدهٔ آدم زمین بوس تو نیت کرد','فرشتگان به هنگام سجده بر آدم، زمین بوسی تو را نیت کردند[و به انگیزه زمین بوسی تو، بر او سجده کردند]؛ زیرا در زیبایی تو، ظرافت‌های فرا انسانی مشاهده کردند.',NULL);
INSERT INTO "verses" VALUES(1933952,2603,4,1,'که در حُسن تو لطفی دید بیش از حد انسانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933953,2603,3,0,'گشادِ کار مشتاقان در آن ابروی دلبند است','باز شدن گره زندگی مشتاقانت، وابسته به ابروی دلبند توست؛ تو را به خدا، یک لحظه بنشین و گره از ابروی خود باز کن [و با این کار، گره از زندگی مشتاقانت بگشا]',NULL);
INSERT INTO "verses" VALUES(1933954,2603,3,1,'خدا را یک نفس بنشین گره بگشا ز پیشانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933955,2603,2,1,'که از هر رقعهٔ دلقش هزاران بت بیفشانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933956,2604,0,1,'چون نیک بدیدم به حقیقت به از آنی',NULL,NULL);
INSERT INTO "verses" VALUES(1933957,2590,6,1,'که زادِ راهروان چستی است و چالاکی',NULL,NULL);
INSERT INTO "verses" VALUES(1933958,2601,8,1,'کی خلاصش بود از محنت سرگردانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933959,2601,7,0,'از گل پارسیم غنچهٔ عیشی نشکفت','هوش مصنوعی: از گل پارسی ما، غنچه‌ای از لذت و شادی باز نشده است. چه خوب است که دجله بغداد و بوی خوش ریحان در اینجا وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1933960,2600,0,1,'کجاست پیک صبا گر همی کند کرمی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933961,2600,0,0,'ز دلبرم که رساند نوازش قلمی','هوش مصنوعی: دلبر من کجاست که با ناز و محبتش نزد من آمده باشد؟ ای پیک صبح، اگر تو هم به دوستی و محبت مشغولی، چه زمان خواهد رسید؟',NULL);
INSERT INTO "verses" VALUES(1933962,2599,8,1,'کاندر این دریا نماید هفت دریا شبنمی',NULL,NULL);
INSERT INTO "verses" VALUES(1933963,2599,8,0,'گریهٔ حافظ چه سنجد پیش استغنای عشق','در برابر بی­ نیازی عشق، گریه حافظ هیچ ارزش و اعتباری ندارد؛ زیرا تمام دریاهای عالم در برابر دریای عشق، به اندازه قطره شبنمی هم، ارزش و اعتبار ندارد.',NULL);
INSERT INTO "verses" VALUES(1933964,2599,7,1,'کز نسیمش بوی جوی مولیان آید همی',NULL,NULL);
INSERT INTO "verses" VALUES(1933965,2599,7,0,'خیز تا خاطر بدان تُرک سمرقندی دهیم','برخیز تا به آن زیباروی سمرقندی دل دهیم و عاشق او شویم زیرا از نسیم خوش او، بوی زندگی بخش جوی مولیان به مشام می­رسد.',NULL);
INSERT INTO "verses" VALUES(1933966,2599,6,1,'عالمی دیگر بباید ساخت وز نو آدمی',NULL,NULL);
INSERT INTO "verses" VALUES(1933967,2599,6,0,'آدمی در عالم خاکی نمی‌آید به دست','در این عالم خاک انسان واقعی پیدا نمی­شود باید جهان دیگری ساخت و دوباره انسان دیگری آفرید.(نکته: شاید بتوان بین آدم و خاک هم ارتباط معنایی پیدا کرد. با توجه به ساخته شدن آدم از خاک بنابر آیات قرآن.)',NULL);
INSERT INTO "verses" VALUES(1933968,2599,5,1,'رهروی باید جهان‌سوزی نه خامی بی‌غمی',NULL,NULL);
INSERT INTO "verses" VALUES(1933969,2599,5,0,'اهل کام و ناز را در کوی رندی راه نیست','نه صاحبان ناز و کام نه انسان های بی تجربه و بی غم،هرگز نمی‌توانند وارد محله ی رندی شوند تنها سالکانی که آشوب و غوغا در جهان به پا می‌کنند و دنیا را به آشوب میکشانند می‌توانند وارد چنین کوی و برزنی شوند (ناگفته نماند که به آشوب کشیدن دنیا در معنای مثبت آن منظور حافظ است مثل مولانا یا خود حافظ که شور و غوغایی با مفاهیم خود در دنیا به پا کرده اند )',NULL);
INSERT INTO "verses" VALUES(1933970,2599,4,1,'ریش باد آن دل که با درد تو خواهد مرهمی',NULL,NULL);
INSERT INTO "verses" VALUES(1933971,2599,4,0,'در طریق عشق‌بازی امن و آسایش بلاست','در راه زندگی عاشقانه امنیت و آسودگی بلا و مصیبت است، امیدوارم آن دلی که با داشتن درد تو به دنبال مرهم می­ گردد زخم گردد.(نکته: نکته جالب توجه و رندانه در این بیت این است که با توجه به اعتقاد حافظ که امن و آسایش را برای عشق مصیبت می­ داند در مصراع دوم دلی که به دنبال درمان عشق می گردد را زخمی می­ خواهد؛ به بیانی دیگر دعا می­ کند که دلی که عاشق شده است هر لحظه عاشق­ تر و دردمندتر گردد.)',NULL);
INSERT INTO "verses" VALUES(1933972,2599,3,1,'شاه ترکان فارغ است از حال ما، کو رستمی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1933973,2599,3,0,'سوختم در چاه صبر از بهر آن شمع چگل','صبر و شکیبایی که در راه آن معشوق زیبارو انجام می­دهم همچون چاهی است که مرا اسیر خود ساخته است، شاه ترکان (شاه زیبارویان، امیر تیمور، افراسیاب)نسبت به حال ما بی­ تفاوت است، کجاست رستمی تا ما را نجات بخشد.',NULL);
INSERT INTO "verses" VALUES(1933974,2599,2,1,'«صعب‌روزی، بوالعجب‌کاری، پریشان‌عالمی»',NULL,NULL);
INSERT INTO "verses" VALUES(1933975,2599,2,0,'زیرکی را گفتم: «این احوال بین»، خندید و گفت:','به انسان دانا و زیرکی گفتم به این اوضاع و احوال نگاه کن! با خنده­­ی تلخی گفت: چه روزگار دشواری، شگفت کاری، و عجب دنیای نابسامان و درهمی!صعب: دشوار.بوالعجب: شگفت انگیز',NULL);
INSERT INTO "verses" VALUES(1933976,2599,1,1,'ساقیا جامی به من ده تا بیاسایم دمی',NULL,NULL);
INSERT INTO "verses" VALUES(1933977,2599,1,0,'چشم آسایش که دارد از سپهر تیزرو؟','چه کسی از این روزگار زودگذر و ناپایدار انتظار آسایش دارد؟ ای ساقی جام شرابی به من ببخش تا لحظه ­ای در پرتو مستی به آرامش برسم.(نکته: حضرت خواجه اوضاع زمانه را چنان نابسامان می­ بیند که گویی تنها با مستی و عدم فکر کردن می ­توان به آرامش رسید.)',NULL);
INSERT INTO "verses" VALUES(1933978,2599,0,1,'دل ز تنهایی به جان آمد خدا را همدمی',NULL,NULL);
INSERT INTO "verses" VALUES(1933979,2599,0,0,'سینه مالامال درد است ای دریغا مرهمی','سینه سرشار از درد و غم است، ای کاش مرهم و دارویی وجود داشت. دل از شدت تنهایی و بی­ کسی به ستوه درآمد به خاطر خدا همدم و هم­ نفسی را نشان دهید.',NULL);
INSERT INTO "verses" VALUES(1933980,2598,9,1,'که گاه لطف سبق می‌برد ز نظم نظامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933981,2598,9,0,'چو سِلْک دُرّ خوشاب است شعر نغز تو حافظ','هوش مصنوعی: شعر زیبا و دلنشین تو، مانند ابریشم و گوهر ارزشمند است، حافظ. گاهی اوقات لطف و زیبایی شعر تو از نظم‌های بزرگ مانند نظامی نیز فراتر می‌رود.',NULL);
INSERT INTO "verses" VALUES(1933982,2598,8,1,'تو شاد گشته به فرماندهی و من به غلامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933983,2598,8,0,'امید هست که زودت به بخت نیک ببینم','هوش مصنوعی: امیدوارم که به زودی تو را با خوشحالی و موفقیت در مقام رهبری ببینم و خودم در جایگاه خدمتگزاری.',NULL);
INSERT INTO "verses" VALUES(1933984,2598,7,1,'فما تَطَیَّبَ نَفْسی وَ ما اسْتَطابَ مَنامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933985,2598,7,0,'وَ إِن دُعِیتُ بِخُلْدٍ وَ صِرْتُ ناقِضَ عَهْدٍ','هوش مصنوعی: اگر مرا به زندگی ابدی دعوت کنند و من به این دعوت پاسخ دهم و به عهدی که بسته‌ام خیانت کنم، هیچ چیزی از جانم لطیف نخواهد بود و خوابم هم شیرین نخواهد شد.',NULL);
INSERT INTO "verses" VALUES(1933986,2598,6,1,'اگر چه روی چو ماهت ندیده‌ام به تمامی',NULL,NULL);
INSERT INTO "verses" VALUES(1933987,2598,6,0,'بَعِدْتُ مِنْکَ وَ قَدْ صِرْتُ ذائباً کَهِلالٍ','هوش مصنوعی: من از تو دور شده‌ام و حالا مانند هلالی ذوب شدم، هرچند که هنوز به‌طور کامل چهره‌ات را ندیده‌ام.',NULL);
INSERT INTO "verses" VALUES(1933988,2598,5,1,'قَدِمْتَ خَیْرَ قُدومٍ نَزَلْتَ خَیْرَ مَقامِ',NULL,NULL);
INSERT INTO "verses" VALUES(1933989,2600,1,0,'قیاس کردم و تدبیر عقل در ره عشق','هوش مصنوعی: من مقایسه کردم و به این نتیجه رسیدم که تدبیر عقل در مسیر عشق، مانند شبنم است که بر روی دریا خطی نامشخص می‌کشد.',NULL);
INSERT INTO "verses" VALUES(1933990,2600,1,1,'چو شبنمی است که بر بحر می‌کشد رقمی',NULL,NULL);
INSERT INTO "verses" VALUES(1933991,2600,2,0,'بیا که خرقهٔ من گرچه رهن میکده‌هاست','هوش مصنوعی: بیا که لباس من هرچند در میکده ها به گروست، اما از اموال وقف نخواهد بود و به نام من نیست.',NULL);
INSERT INTO "verses" VALUES(1933992,2600,2,1,'ز مال وقف نبینی به نام من درمی',NULL,NULL);
INSERT INTO "verses" VALUES(1933993,2601,6,0,'گر چه دوریم به یاد تو قدح می‌گیریم','هوش مصنوعی: هر چند از تو دور هستیم، اما به خاطر تو هنوز هم زنده‌ایم و مشغول شادمانی هستیم. دیگر در این سفر روحانی جایی برای استراحت وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1933994,2601,6,1,'بُعد منزل نبود در سفر روحانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933995,2601,5,0,'برشکن کاکل ترکانه که در طالع توست','هوش مصنوعی: موهای زیبای ترک‌ها را بشکن، زیرا در سرنوشت تو بخشش و تلاش خاقانی و چنگزخان وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1933996,2601,5,1,'بخشش و کوشش خاقانی و چنگزخانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933997,2601,4,0,'جلوهٔ بخت تو دل می‌برد از شاه و گدا','هوش مصنوعی: خوشبختی تو چنان درخشان است که دل هر دو قشر را می‌برد، چه شاه و چه گدا. چشمان حسود از تو دور باشد، چرا که تو هم جان می‌داری و هم محبوبی.',NULL);
INSERT INTO "verses" VALUES(1933998,2601,4,1,'چشم بد دور که هم جانی و هم جانانی',NULL,NULL);
INSERT INTO "verses" VALUES(1933999,2601,3,0,'ماه اگر بی تو برآید به دو نیمش بزنند','هوش مصنوعی: اگر ماه بی حضورت طلوع کند، آن را به دو نیم کنند، چون نعمت و معجزهٔ الهی به سراغ احمدی آمده است.',NULL);
INSERT INTO "verses" VALUES(1934000,2601,3,1,'دولت احمدی و معجزهٔ سبحانی',NULL,NULL);
INSERT INTO "verses" VALUES(1934001,2601,2,0,'دیده نادیده به اقبال تو ایمان آورد','هوش مصنوعی: چشم نادیده به خوشبختی تو اعتماد کرد، آفرین بر تو که چنین رحمت خدا بر تو نازل شده است.',NULL);
INSERT INTO "verses" VALUES(1934002,2601,2,1,'مرحبا ای به چنین لطف خدا ارزانی',NULL,NULL);
INSERT INTO "verses" VALUES(1934003,2601,1,0,'خانِ بِنْ خان و شهنشاهِ شهنشاه‌نژاد','هوش مصنوعی: فرمانروای بزرگ و سرور سرزمین‌ها، کسی است که اگر جان و زندگی‌اش را به پای تو بگذارد، شایسته‌ی احترام و محبت تو خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1934004,2601,1,1,'آن که می‌زیبد اگر جان جهانش خوانی',NULL,NULL);
INSERT INTO "verses" VALUES(1934005,2601,0,0,'اَحمَدُ اللهَ عَلی مَعْدِلَةِ السُلطانِ','هوش مصنوعی: باید خرسند باشیم از وجود و حکومت سلطان احمد شیخ اویس حسن ایلخانی.',NULL);
INSERT INTO "verses" VALUES(1934006,2601,0,1,'احمدِ شیخ اُوِیسِ حسنِ ایلخانی',NULL,NULL);
INSERT INTO "verses" VALUES(1934007,2601,7,1,'حبّذا دجله بغداد و می ریحانی',NULL,NULL);
INSERT INTO "verses" VALUES(1934008,2600,10,1,'جز از دعای شبی و نیاز صبحدمی',NULL,NULL);
INSERT INTO "verses" VALUES(1934009,2600,9,1,'که کرد صد شکرافشانی از نیِ قلمی',NULL,NULL);
INSERT INTO "verses" VALUES(1934010,2600,9,0,'چرا به یک نیِ قندش نمی‌خرند آن کس','هوش مصنوعی: چرا کسی که با قلمش هزاران جلوه می‌آفریند، یک نی قند نمی‌خرد؟',NULL);
INSERT INTO "verses" VALUES(1934011,2600,8,1,'به کِشته‌زار جگرتشنگان نداد نمی',NULL,NULL);
INSERT INTO "verses" VALUES(1934012,2600,8,0,'نمی‌کنم گله‌ای لیک ابر رحمت دوست','هوش مصنوعی: من شکایتی ندارم، اما بارش رحمت دوست به مزرعه دل‌های تشنه من نیامد.',NULL);
INSERT INTO "verses" VALUES(1934013,2600,7,1,'اگر معاشرِ مایی بنوش نیش غمی',NULL,NULL);
INSERT INTO "verses" VALUES(1934014,2600,7,0,'دوام عیش و تنعم نه شیوهٔ عشق است','هوش مصنوعی: برای عشق و محبت، زندگی راحت و لذت بردن پایدار نیست. اگر با من هستی، این تلخی‌های زندگی را با هم تحمل کنیم.',NULL);
INSERT INTO "verses" VALUES(1934015,2600,6,1,'به یک پیاله میِ صاف و صحبتِ صنمی',NULL,NULL);
INSERT INTO "verses" VALUES(1934016,2600,6,0,'بیا که وقت‌شناسان دو کون بفروشند','هوش مصنوعی: بیا که افرادی که به اهمیت زمان آگاه هستند، برای یک پیاله شراب خالص و صحبت با یک دوست خوب، حتی دو دنیای خود را هم می‌فروشند.',NULL);
INSERT INTO "verses" VALUES(1934017,2600,5,1,'به آن که بر در میخانه برکشم عَلَمی',NULL,NULL);
INSERT INTO "verses" VALUES(1934018,2600,5,0,'دلم گرفت ز سالوس و طبل زیر گلیم','هوش مصنوعی: دل من از نفاق و تظاهر آدم‌ها آکنده از اندوه شده است، به‌گونه‌ای که دوست دارم پرچمی را به‌روی درِ میخانه برافرازم.',NULL);
INSERT INTO "verses" VALUES(1934019,2600,4,1,'برو به دست کن ای مرده‌دل مسیح‌دمی',NULL,NULL);
INSERT INTO "verses" VALUES(1934020,2600,4,0,'طبیبِ راه‌نشین درد عشق نشناسد','هوش مصنوعی: پزشکی که فقط در کنار راه نشسته و تجربه‌ای از عشق ندارد، نمی‌تواند به تو کمکی کند. ای کسی که دل مرده‌ای داری، باید به خودت کمک کنی.',NULL);
INSERT INTO "verses" VALUES(1934021,2600,3,1,'پیاله گیر و بیاسا ز عمرِ خویش دمی',NULL,NULL);
INSERT INTO "verses" VALUES(1934022,2600,3,0,'حدیثِ چون و چرا دردِ سر دهد ای دل','هوش مصنوعی: ای دل، از دل مشغولی و بحث و جدل درباره زندگی خود دوری کن. پیاله‌ای به دست بگیر و از لحظه‌های زندگی‌ات لذت ببر و استراحت کن.',NULL);
INSERT INTO "verses" VALUES(1934023,2600,10,0,'سزای قدر تو شاها به دست حافظ نیست','هوش مصنوعی: شایستگی و ارزش تو ای پادشاه، در دستان حافظ نیست و تنها از طریق دعا در شب و نیاز در سحرگاه به دست می‌آید.',NULL);
INSERT INTO "verses" VALUES(1934024,2590,6,0,'دَعِ التَّکاسُلَ تَغْنَمْ فَقَد جَری مَثَلٌ','هوش مصنوعی: اگر از تنبلی دست برداری، بهره‌مند می‌شوی؛ زیرا مثل معروفی وجود دارد که می‌گوید، زاد و توشهٔ راهروان، نیازمند چابکی و تلاش است.',NULL);
INSERT INTO "verses" VALUES(1934025,2590,5,1,'و هاتِ شَمسَةَ کَرْمٍ مُطَیَّبٍ زاکی',NULL,NULL);
INSERT INTO "verses" VALUES(1934026,2590,5,0,'صبا عبیرفشان گشت ساقیا برخیز','هوش مصنوعی: نسیم بهاری شاداب و خوشبو، به سراغ ساقی آمده است. ای ساقی، برخیز و می خوشگوار از انگورهای خالص و باکیفیت را به ما بده.',NULL);
INSERT INTO "verses" VALUES(1934027,2581,9,1,'که جام جم نکند سود وقت بی‌بصری',NULL,NULL);
INSERT INTO "verses" VALUES(1934028,2581,9,0,'چو مستعّد نظر نیستی وصال مجوی','هوش مصنوعی: وقتی که از نگاه کردن به حقیقت و درک واقعیت ناتوانی، به دنبال ارتباط نزدیک نباش. چرا که مانند جمشید، هیچ فایده‌ای از جامی که نمیتوانی ببینی، نخواهی برد.',NULL);
INSERT INTO "verses" VALUES(1934029,2581,8,1,'صبا به غالیه ساییّ و گل به جلوه‌گری',NULL,NULL);
INSERT INTO "verses" VALUES(1934030,2581,8,0,'به بوی زُلف و رُخت می‌روند و می‌آیند','باد صبا عطر زلف تو را می‌پراکند و چهره‌ی تو مانند گلی جلوه گری می کند.',NULL);
INSERT INTO "verses" VALUES(1934031,2581,7,1,'که زیب بخت و سزاوار ملک و تاج سری',NULL,NULL);
INSERT INTO "verses" VALUES(1934032,2581,7,0,'کلاه سروریت کج مباد بر سر حُسن','هوش مصنوعی: کلاهی که بر سر توست، نباید کج باشد، زیرا زیبایی و شایستگی تو به حدی است که لیاقت تاج و سلطنت را داری.',NULL);
INSERT INTO "verses" VALUES(1934033,2581,6,1,'گر امتحان بکنی مِی خوریّ و غم نخوری',NULL,NULL);
INSERT INTO "verses" VALUES(1934034,2581,6,0,'بیا که وضع جهان را چنان که من دیدم','اگر با دیدگاهِ من (عشق‌ورزی) به زندگی نگاه کنی، سرمست از عشق خواهی شد و همه‌ی غم‌ها فراموش می‌شوند!',NULL);
INSERT INTO "verses" VALUES(1934035,2581,5,1,'که یاد گیر دو مصرع ز من به نظم دری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934036,2581,5,0,'ز من به حضرت آصف که می‌برد پیغام','هوش مصنوعی: از من به حضرت آصف پیام می‌برد که بیاموز دو مصراع از من را در نظم دری؟ یعنی: کسی که پیام مرا به آصف می‌رساند، به او می‌گوید که از اشعار من چیزهایی را بیاموزد.',NULL);
INSERT INTO "verses" VALUES(1934037,2581,4,1,'که هر صباح و مسا شمع مجلس دگری',NULL,NULL);
INSERT INTO "verses" VALUES(1934038,2581,4,0,'هزار جان مقدّس بسوخت زین غیرت','هوش مصنوعی: هزار جان پاک و باارزش به خاطر این غیرت از بین رفت، چون هر صبح و شب شمع محفل دیگری روشن می‌شود.',NULL);
INSERT INTO "verses" VALUES(1934039,2581,3,1,'که در برابر چشمیّ و غایب از نظری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934040,2581,3,0,'تو خود چه لعبتی ای شهسوار شیرین‌کار','هوش مصنوعی: ای شیرین‌کار و دلربا، تو چقدر جالب و جذابی که در برابر دیدگانم هستی، اما انگار از نگاه‌ها دوری و ناپدید شده‌ای.',NULL);
INSERT INTO "verses" VALUES(1934041,2581,2,1,'به عذر نیم‌شبی کوش و گریهٔ سحری',NULL,NULL);
INSERT INTO "verses" VALUES(1934042,2581,2,0,'می صبوح و شکرخواب صبحدم تا چند؟','تا کی به اوقات خودت را به خوردن و خوابیدن و آسایش طلبی میگذرانی؟تلاش کن راز و نیاز شبانه و گریه و توبه صبحگاهی را به جا بیاوری',NULL);
INSERT INTO "verses" VALUES(1934043,2581,1,1,'که بنده را نخرد کس به عیب بی‌هنری',NULL,NULL);
INSERT INTO "verses" VALUES(1934044,2581,1,0,'بکوش خواجه و از عشق بی‌نصیب مباش','زندگی یعنی آموختن هنر عشق ورزیدن؛ و اوقات، بدون عشق ارزشی ندارد',NULL);
INSERT INTO "verses" VALUES(1934045,2581,0,1,'ارادتی بنما تا سعادتی بِبَری',NULL,NULL);
INSERT INTO "verses" VALUES(1934046,2581,0,0,'طُفیلِ هستیِ عشقند آدمیّ و پَری','هوش مصنوعی: دنیای وجود، تحت تاثیر عشق است و هم انسان‌ها و هم فرشتگان به عشق وابسته‌اند. اگر تمایل و اراده‌ای نشان دهی، می‌توانی به خوشبختی و سعادت دست یابی.',NULL);
INSERT INTO "verses" VALUES(1934047,2580,8,1,'کاین خاک بهتر از عمل کیمیاگری',NULL,NULL);
INSERT INTO "verses" VALUES(1934048,2580,8,0,'حافظ غبار فقر و قناعت ز رخ مشوی','هوش مصنوعی: غبار فقر و سادگی را از چهره‌ات دور نکن، زیرا این چیزی که هستی از هر عمل کیمیاگری ارزشمندتر است.',NULL);
INSERT INTO "verses" VALUES(1934049,2580,7,1,'از شاه نذر خیر و ز توفیق یاوری',NULL,NULL);
INSERT INTO "verses" VALUES(1934050,2580,7,0,'نیل مراد بر حسب فکر و همت است','هوش مصنوعی: نائل شدن به آرزوها بستگی به اندیشه و تلاش شخص دارد و این موفقیت می‌تواند از دعای شاه و همراهی و حمایت تو ناشی شود.',NULL);
INSERT INTO "verses" VALUES(1934051,2580,6,1,'ای نور دیده صلح به از جنگ و داوری',NULL,NULL);
INSERT INTO "verses" VALUES(1934052,2580,6,0,'یک حرف صوفیانه بگویم اجازت است؟','هوش مصنوعی: می‌خواهم یک سخن عارفانه بگویم، آیا اجازه می‌دهی؟ ای روشنی چشمم، صلح بهتر از جنگ و قضاوت است.',NULL);
INSERT INTO "verses" VALUES(1934053,2580,5,1,'درویش و امن خاطر و کنج قلندری',NULL,NULL);
INSERT INTO "verses" VALUES(1934054,2580,5,0,'سلطان و فکر لشکر و سودای تاج و گنج','هوش مصنوعی: سلطان در مورد فرماندهی و جنگ فکر می‌کند و به دنبال تاج و ثروت است، در حالی که درویش به آرامش و امنیت خاطر فکر می‌کند و به زندگی ساده و آزاد در کنج عزلت می‌اندیشد.',NULL);
INSERT INTO "verses" VALUES(1934055,2580,4,1,'آن به کز این گریوه سبک‌بار بگذری',NULL,NULL);
INSERT INTO "verses" VALUES(1934056,2581,10,0,'دعای گوشه‌نشینان بلا بگرداند','ذره و اندک توجه معشوق به عاشق، هم‌چون دعای افراد مستجاب‌الدعوه، همه‌ی دردها را درمان می‌کند',NULL);
INSERT INTO "verses" VALUES(1934057,2581,10,1,'چرا به گوشهٔ چشمی به ما نمی‌نگری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934058,2581,11,0,'بیا و سلطنت از ما بخر به مایهٔ حسن','هوش مصنوعی: بیایید و با زیبایی و خوبی ما، سلطنت و قدرت را به دست آورید. از این فرصت غافل نشوید چون از دست دادن آن، بد است و حیف است.',NULL);
INSERT INTO "verses" VALUES(1934059,2581,11,1,'وَزین معامله غافل مشو که حیف خوری',NULL,NULL);
INSERT INTO "verses" VALUES(1934060,2583,7,1,'مگر او نیز همچون من، غمی دارد شبان‌روزی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934061,2583,7,0,'ندانم نوحهٔ قمری، به طرْف جویباران چیست','نمی‌دانم قمری در آن‌سو و در کنار جویبار چرا ناله غم سر داده است! شاید او نیز همچون من غمی همیشگی دارد.',NULL);
INSERT INTO "verses" VALUES(1934062,2583,6,1,'که بیش از پنج روزی نیست، حکمِ میرِ نوروزی',NULL,NULL);
INSERT INTO "verses" VALUES(1934063,2583,6,0,'سخن در پرده می‌گویم، چو گل از غنچه بیرون آی','این‌ را در پرده و رمزی به‌تو می‌گویم و خود معنی آن‌را بیاب؛ ‌«همچون گل از غنچه بیرون بیا که شاهی میر نوروز‌، بسیار کوتاه است و بیش از پنج روز نیست.»',NULL);
INSERT INTO "verses" VALUES(1934064,2583,5,1,'کلاهِ سروری آن است، کز این ترک بر دوزی',NULL,NULL);
INSERT INTO "verses" VALUES(1934065,2583,5,0,'طریق کام‌بخشی چیست؟ ترکِ کامِ خود کردن','راه و مسلک شاد کردن دیگران چیست؟ آن‌است که سخاوتمند باشی و به‌آنها ببخشی و خود ترک لذت و کام کنی؛ آنچه که سروری و بزرگی نامیده‌اند‌، از این راه به‌دست می‌آید.',NULL);
INSERT INTO "verses" VALUES(1934066,2583,4,1,'مجال عیش فرصت دان، به فیروزی و بهروزی',NULL,NULL);
INSERT INTO "verses" VALUES(1934067,2583,4,0,'چو امکانِ خُلود ای دل! در این فیروزه‌ایوان نیست','وقتی که امکان رفتن به ایوان بلند آسمان نیست پس قدر عیش و خوشی را بدان و نیکبخت و بهروز باش.',NULL);
INSERT INTO "verses" VALUES(1934068,2583,3,1,'به گلزار آی کز بلبل، غزل گفتن بیاموزی',NULL,NULL);
INSERT INTO "verses" VALUES(1934069,2583,3,0,'به صحرا رو که از دامن، غبارِ غم بیَفشانی','در این فصل زیبا به صحرا رو تا غم‌هایت را فراموش کنی و به‌گلزار بیا تا بلبل عاشق‌، به‌تو شعر عاشقانه بیاموزد.',NULL);
INSERT INTO "verses" VALUES(1934070,2583,2,1,'که زد بر چرخ فیروزه صفیرِ تختِ فیروزی',NULL,NULL);
INSERT INTO "verses" VALUES(1934071,2583,2,0,'ز جام گل، دگر بلبل، چنان مستِ میِ لعل است','بلبل چنان از زیبایی گل مست گشته است که آواز شادمانه او فلک را پر کرده است. (تخت فیروزی‌: نام گوشه‌ موسیقی است و تخت فیروزه کنایه است از آسمان)',NULL);
INSERT INTO "verses" VALUES(1934072,2583,1,1,'که قارون را غلط‌ها داد، سودای زراندوزی',NULL,NULL);
INSERT INTO "verses" VALUES(1934073,2583,1,0,'چو گل گر خرده‌ای داری، خدا را صرفِ عشرت کن','اگر همچون گل چند خرده و ریزه سیم و زر داری ‌آن‌را به شادی و می‌گساری صرف کن که خیال مال‌اندوزی برای قارون‌، غلط‌ها و بلاها درست کرد.',NULL);
INSERT INTO "verses" VALUES(1934074,2580,4,0,'در شاه‌راه جاه و بزرگی خطر بسی‌ست','هوش مصنوعی: در مسیر رسیدن به مقام و احترام بسیاری از خطرات وجود دارد، بهتر است از دشواری‌ها و بار سنگین رها شوی و با آرامش و سبکی عبور کنی.',NULL);
INSERT INTO "verses" VALUES(1934075,2583,0,1,'از این باد ار مدد خواهی، چراغِ دل برافروزی',NULL,NULL);
INSERT INTO "verses" VALUES(1934076,2582,4,1,'ساغر مِی‌ طلب که مخموری',NULL,NULL);
INSERT INTO "verses" VALUES(1934077,2582,4,0,'بگذر از نام و ننگ خود حافظ','هوش مصنوعی: از شهرت و آبرویت دست بردار و به سمتی برو که جام می را از آن طلب کنی، چرا که حالت مستی و نشئگی را به یاد بسپار.',NULL);
INSERT INTO "verses" VALUES(1934078,2582,3,1,'عاشقان را دوایِ رنجوری',NULL,NULL);
INSERT INTO "verses" VALUES(1934079,2582,3,0,'روی زرد است و آه دردآلود','هوش مصنوعی: چهره‌اش زرد و غم‌انگیز است و دلیلی برای آزار و درد عاشقان، دارویی برای درمان مشکلات آنها نیست.',NULL);
INSERT INTO "verses" VALUES(1934080,2582,2,1,'رو که تو مستِ آبِ انگوری',NULL,NULL);
INSERT INTO "verses" VALUES(1934081,2582,2,0,'مستیِ عشق نیست در سرِ تو','هوش مصنوعی: عشق تو را به حالت مستی درآورده است، اما این حالتی که تو داری تنها از نشئگی شراب است.',NULL);
INSERT INTO "verses" VALUES(1934082,2582,1,1,'که به عقلِ عقیله مشهوری',NULL,NULL);
INSERT INTO "verses" VALUES(1934083,2582,1,0,'گِرد دیوانگانِ عشق مگرد','هوش مصنوعی: اینگونه نگرد دور دیوانگان عشق، زیرا که عقل عاقلان در شهرت معروف است.',NULL);
INSERT INTO "verses" VALUES(1934084,2582,0,1,'گر تو را عشق نیست معذوری',NULL,NULL);
INSERT INTO "verses" VALUES(1934085,2582,0,0,'ای که دایم به خویش مغروری','هوش مصنوعی: ای کسی که همیشه به خودت مغروری، اگر عشق در دل نداری، بهانه‌ای برای خودت نیاور.',NULL);
INSERT INTO "verses" VALUES(1934086,2581,13,1,'اَریٰ اُسامِرُ لیلایَ لَیلةَ القَمَری',NULL,NULL);
INSERT INTO "verses" VALUES(1934087,2581,13,0,'به یُمنِ همّتِ حافظ امید هست که باز','هوش مصنوعی: به لطف تلاش و همت حافظ، این امید وجود دارد که دوباره شاهد زیبایی‌های لیلی در شب‌های پر نور خواهیم بود.',NULL);
INSERT INTO "verses" VALUES(1934088,2581,12,1,'نعوذبالله اگر ره به مقصدی نبری',NULL,NULL);
INSERT INTO "verses" VALUES(1934089,2581,12,0,'طریق عشق طریقی عجب خطرناک است','هوش مصنوعی: راه عشق، مسیر شگفت‌انگیزی است که بسیار پرخطر می‌باشد؛ بترس که اگر به مقصد نرسی، چه عواقبی خواهد داشت.',NULL);
INSERT INTO "verses" VALUES(1934090,2583,0,0,'ز کوی یار می‌آید نسیمِ بادِ نوروزی','نسیم نوروزی و بهاری از سمت خانه یار می‌وزد اگر قدر این نسیم خوش‌عطر را بدانی دل تو شاد و روشن خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1934091,2583,8,0,'مِیی دارم چو جان، صافی و صوفی می‌کند عیبش','می و شرابی دارم که مانند جان‌، صاف و زلال است و صوفی از آن ایراد می‌گیرد؛ خدایا بخت بد را سهم و روزی آدم عاقل مکن!',NULL);
INSERT INTO "verses" VALUES(1934092,2580,3,1,'تا یک دم از دلم غم دنیا به در بری',NULL,NULL);
INSERT INTO "verses" VALUES(1934093,2580,2,1,'اقرار بندگی کن و اظهار چاکری',NULL,NULL);
INSERT INTO "verses" VALUES(1934094,2578,3,0,'ساغر ما که حریفان دگر می‌نوشند','هوش مصنوعی: ما از نوشیدن می را با دیگران متفاوتیم و نمی‌توانیم این درد را تحمل کنیم، اگر تو این کار را برای ما روا دارایی.',NULL);
INSERT INTO "verses" VALUES(1934095,2578,2,1,'به از این دار نگاهش که مرا می‌داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934096,2578,2,0,'دل ببردی و بحل کردمت ای جان لیکن','هوش مصنوعی: تو دل مرا بردی و من را در آغوش خودت قرار دادی، ای محبوب عزیزم، اما این نگاه تو از این دار و درخت برای من بیشتر ارزش دارد، زیرا تو مرا در این نگاه خود نگه می‌داری.',NULL);
INSERT INTO "verses" VALUES(1934097,2578,1,1,'به امیدی که در این ره به خدا می‌داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934098,2578,1,0,'تشنهٔ بادیه را هم به زلالی دریاب','هوش مصنوعی: اگر کسی در بیابان تشنه است، او را با آب زلال سیراب کن و به او امید بده که در این مسیر به خداوند نزدیک‌تر خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1934099,2578,0,1,'عاشقان را ز بر خویش جدا می‌داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934100,2578,0,0,'ای که مهجوری عشاق روا می‌داری','هوش مصنوعی: ای کسی که بی‌اعتنایی به عاشقان را عادی می‌دانی، عشق‌ورزان را از خود دور می‌کنی.',NULL);
INSERT INTO "verses" VALUES(1934101,2577,7,1,'تو که چون حافظ شب‌خیز غلامی داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934102,2577,7,0,'بس دعای سحرت مونس جان خواهد بود','هوش مصنوعی: دعای سحرگاهت همدم دل خواهد بود، تو که مثل حافظ، شب‌زنده‌دار غلامی داری.',NULL);
INSERT INTO "verses" VALUES(1934103,2577,6,1,'تویی امروز در این شهر که نامی داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934104,2577,6,0,'نام نیک ار طلبد از تو غریبی چه شود؟','هوش مصنوعی: اگر غریبه‌ای از تو نام نیک بخواهد، چه تفاوتی می‌کند؟ امروز تو در این شهر شناخته‌شده‌ای و نامی داری.',NULL);
INSERT INTO "verses" VALUES(1934105,2577,5,1,'می‌کنم شکر که بر جور دوامی داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934106,2577,5,0,'چون به هنگام وفا هیچ ثباتیت نبود','هوش مصنوعی: زمانی که در وفا هیچ پایداری وجود نداشت، من سپاسگزارم که تو در برابر ظلم پایداری می‌کنی.',NULL);
INSERT INTO "verses" VALUES(1934107,2577,4,1,'بشنو ای خواجه اگر زان که مشامی داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934108,2577,4,0,'بوی جان از لب خندان قدح می‌شنوم','هوش مصنوعی: بوی زندگی و خوشی را از لب‌های خندان جام می‌شنوم. ای آقا، اگر حس بویایی‌ات را داری، این را بشنو.',NULL);
INSERT INTO "verses" VALUES(1934109,2577,3,1,'بر کنار چمنش وه که چه دامی داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934110,2577,3,0,'خال سرسبز تو خوش دانهٔ عیشی‌ست ولی','هوش مصنوعی: خال سبز تو به مانند دانه‌ای خوشمزه از لذّت و شادی است، اما در کنار چمن آن، وای که چه دام بزرگی برای جذب دارد.',NULL);
INSERT INTO "verses" VALUES(1934111,2577,2,1,'گر از آن یار سفرکرده پیامی داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934112,2577,2,0,'ای صبا! سوختگان بر سر ره منتظرند','هوش مصنوعی: ای نسیم! عاشقانی که دل به یاد محبوبشان داده‌اند، در کنار راه منتظرند. اگر خبری از آن معشوقی که سفر کرده داری، حتماً به آن‌ها برسان.',NULL);
INSERT INTO "verses" VALUES(1934113,2577,1,1,'فرصتت باد که خوش صبحی و شامی داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934114,2577,1,0,'ای که با زلف و رخِ یار گذاری شب و روز','هوش مصنوعی: ای کسی که با زلف و چهره محبوبت شب و روز را سپری می‌کنی، آرزو دارم فرصتی برایت فراهم شود تا به زیبایی صبح و شام بگذرانید.',NULL);
INSERT INTO "verses" VALUES(1934115,2577,0,1,'جم وقت خودی ار دست به جامی داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934116,2577,0,0,'ای که در کوی خرابات مقامی داری','هوش مصنوعی: ای کسی که در محله‌ی خراباتی‌ها جایگاهی داری، اگر در لحظه‌ای به خود واقعی‌ات دسترسی پیدا کنی، این کار را می‌توانی با نوشیدن جام (شراب) انجام دهی.',NULL);
INSERT INTO "verses" VALUES(1934117,2576,6,1,'به قرآنی که اندر سینه داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934118,2576,6,0,'ندیدم خوش‌تر از شعر تو حافظ','ندیدم خوش‌تر از شعر تو حافظ‌، به قرآنی که اندر سینه داری.',NULL);
INSERT INTO "verses" VALUES(1934119,2576,5,1,'خدا را گر میِ دوشینه داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934120,2576,5,0,'به فریاد خمار مفلسان رس','به داد و کمک بی‌چیزان می‌گسار برس‌؛ با همان می دوشینه که ما را نوشاندی.',NULL);
INSERT INTO "verses" VALUES(1934121,2576,4,1,'تو دانی خرقهٔ پشمینه داری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934122,2576,4,0,'نمی‌ترسی ز آه آتشینم؟','از آه آتشینم نمی‌ترسی؟ تو که خرقه‌ای پشمین و سوزنده داری؟',NULL);
INSERT INTO "verses" VALUES(1934123,2578,3,1,'ما تحمل نکنیم ار تو روا می‌داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934124,2578,4,0,'ای مگس حضرت سیمرغ نه جولانگه توست','ای مگس جای تو در حضور سیمرغ نیست, تو فقط باعث آبروریزی خود می‌شوی و برای ما زحمت ایجاد می‌کنی.',NULL);
INSERT INTO "verses" VALUES(1934125,2578,4,1,'عرض خود می‌بری و زحمت ما می‌داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934126,2578,5,0,'تو به تقصیر خود افتادی از این در محروم','هوش مصنوعی: تو به خاطر اشتباهات خودت به این وضعیت دچار شده‌ای، پس چرا از این در محرومی و مدام با خودت می‌گویی «چرا»؟',NULL);
INSERT INTO "verses" VALUES(1934127,2580,2,0,'در کوی عشق شوکت شاهی نمی‌خرند','هوش مصنوعی: در محل عشق، مقام و رتبه‌ی سلطنت ارزش ندارد؛ باید به بندگی و خدمتگذاری اعتراف کنی و خود را فروتن نشان دهی.',NULL);
INSERT INTO "verses" VALUES(1934128,2580,1,1,'گو بر تو باد تا غم افتادگان خوری',NULL,NULL);
INSERT INTO "verses" VALUES(1934129,2580,1,0,'آن کس که اوفتاد خدایش گرفت دست','هوش مصنوعی: آن کسی که به زمین می‌افتد، خدا او را پشتیبانی می‌کند. پس بر تو باد که به حال کسانی که به بندگی و حال بد افتاده‌اند رحم کنی و غم آن‌ها را بخوری.',NULL);
INSERT INTO "verses" VALUES(1934130,2580,0,1,'تا شکر چون کنی و چه شکرانه آوری',NULL,NULL);
INSERT INTO "verses" VALUES(1934131,2580,0,0,'خوش کرد یاوری فلکت روز داوری','هوش مصنوعی: در روز قیامت، سرنوشت و یاری تو خوش به نظر می‌رسد. حال که این طور است، وقتی به شکرگزاری می‌پردازی، چگونه و با چه نوع سپاسی می‌خواهی این نعمت‌ها را به جا بیاوری؟',NULL);
INSERT INTO "verses" VALUES(1934132,2579,10,1,'چه توقع ز جهانِ گذران می‌داری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934133,2579,10,0,'مگذران روزِ سلامت به ملامت حافظ','هوش مصنوعی: روزهایی را که در سلامت و خوشی سپری می‌کنی، با ندامت و شکایت نگذران؛ حافظ به تو یادآوری می‌کند که از این دنیا که دائماً در حال تغییر و گذر است، چه انتظاری می‌توانی داشته باشی؟',NULL);
INSERT INTO "verses" VALUES(1934134,2579,9,1,'عاشقی گفت که تو بنده بر آن می‌داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934135,2579,9,0,'گر چه رندیّ و خرابیّ گنهِ ماست، ولی','هوش مصنوعی: هرچند که ما در رفتارهای خود ناپسند و خرابکاری داشته‌ایم، اما عشق به تو این را می‌گوید که تو این اشکالات ما را به عنوان یک بندۀ خود می‌پذیری.',NULL);
INSERT INTO "verses" VALUES(1934136,2579,8,1,'این طمع‌ها که تو از سیم‌بران می‌داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934137,2579,8,0,'کیسهٔ سیم و زرت پاک بباید پرداخت','هوش مصنوعی: برای دستیابی به ثروت و خواسته‌ها باید هزینه‌ها و دشواری‌هایی که نصیب تو می‌شود را بپذیری. تو باید آماده‌باشی که به خاطر طمع‌ورزی‌هایت، بهایش را بپردازی.',NULL);
INSERT INTO "verses" VALUES(1934138,2579,7,1,'طمع مهر و وفا زین پسران می‌داری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934139,2579,7,0,'پدر تجربه ای دل تویی آخر ز چه روی','هوش مصنوعی: پدر جان، تو که خودت در دل تجربه‌های بسیاری داری، چرا هنوز امیدوار هستی که این پسران، محبت و وفا را به تو بدهند؟',NULL);
INSERT INTO "verses" VALUES(1934140,2579,6,1,'تو تمنّا ز گِلِ کوزه‌گران می‌داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934141,2580,3,0,'ساقی به مژدگانی عیش از درم درآی','هوش مصنوعی: ای ساقی، برای خوشحالی و شادمانی، به درون بیایید تا لحظه‌ای غم‌های دنیا را از دل من برطرف کنید.',NULL);
INSERT INTO "verses" VALUES(1934142,2579,6,0,'گوهر جام‌جم از کانِ جهانی دگر است','هوش مصنوعی: جواهر اصلی و ارزشمند، از منبعی فراتر از این دنیا به دست می‌آید، اما تو تنها آرزوی گل‌های سفالی هنرمندان را داری.',NULL);
INSERT INTO "verses" VALUES(1934143,2579,5,0,'چون تویی نرگسِ باغ نظر ای چشم و چراغ','هوش مصنوعی: چرا وقتی تو چنین زیبایی و روشنی در زندگی‌ام هستی، هنوز بر من که دلی زخمی دارم، این‌قدر بی‌توجهی می‌کنی؟',NULL);
INSERT INTO "verses" VALUES(1934144,2579,4,1,'چشم سری عجب از بی‌خبران می‌داری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934145,2579,4,0,'ای که در دلقِ مُلَمَّع طلبی نقد حضور','هوش مصنوعی: ای کسی که در لباس رنگارنگ خود، به دنبال حقیقت هستی، تعجب نکن از اینکه بی‌خبران از این حقیقت چه می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1934146,2579,3,1,'همه را نعره‌زنان جامه‌دران می‌داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934147,2579,3,0,'نه گل از دستِ غمت رست و نه بلبل در باغ','هوش مصنوعی: در دل غم تو، نه گلی به شکوفایی رسیده و نه بلبلانی در باغ سر از شوق آواز برآورده‌اند. همه در ناامیدی و بی‌قراری زندگی می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1934148,2579,2,1,'دست در خونِ دلِ پُرهنران می‌داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934149,2579,2,0,'ساعد آن به که بپوشی تو چو از بهرِ نگار','هوش مصنوعی: بهتر است که برای خوشنود کردن معشوق، خود را به رنج و سختی بیندازی، زیرا تو توانایی نگهداری از خود را داری و می‌توانی از دل‌خوشی نسبت به هنر و زیبایی برآمده از این عشق، به خوبی دفاع کنی.',NULL);
INSERT INTO "verses" VALUES(1934150,2579,1,1,'این چنین عزت صاحب‌نظران می‌داری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934151,2579,1,0,'گوشهٔ چشمِ رضایی به مَنَتْ باز نشد','هوش مصنوعی: به نظر می‌رسد که توجه و نگاه خاص کسی که در مقام روشنفکری و دانش قرار دارد، تنها از یکی از اطرافیانش حاصل نشده است. این شخص با رفتار و نگاهش، به نوعی ارزش و احترام بیشتری به نظرات و اندیشه‌های اهل نظر و صاحب‌نظران می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1934152,2579,0,1,'مخلصان را نه به وضع دگران می‌داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934153,2579,0,0,'روزگاری‌ست که ما را نگران می‌داری','هوش مصنوعی: در این زمان، نگرانی ما را بیشتر می‌کنی و حال مخلصان و نزدیکان را به حال دیگران در نمی‌آوری.',NULL);
INSERT INTO "verses" VALUES(1934154,2578,6,1,'سعی نابرده چه امید عطا می‌داری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934155,2578,6,0,'حافظ از پادشهان پایه به خدمت طلبند','هوش مصنوعی: حافظ می‌گوید که پادشاهان از افرادی با مقام و جایگاه می‌خواهند که به خدمت آن‌ها بیایند. حالا از کسی که تلاش نکرده و زحمت نکشیده، چه امیدی به دریافت نیکی و پاداش داری؟',NULL);
INSERT INTO "verses" VALUES(1934156,2578,5,1,'از که می‌نالی و فریاد چرا می‌داری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934157,2579,5,1,'سر چرا بر من دل‌خسته گران می‌داری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934158,2605,1,1,'به مردمی نه به‌فرمان چنان بران که تو دانی',NULL,NULL);
INSERT INTO "verses" VALUES(1934159,2583,8,1,'خدایا هیچ عاقل را، مبادا بختِ بد، روزی',NULL,NULL);
INSERT INTO "verses" VALUES(1934160,2583,9,1,'که حکم آسمان این است اگر سازی و گر سوزی',NULL,NULL);
INSERT INTO "verses" VALUES(1934161,2589,1,1,'إِلی رُکبانِکُم طالَ اشْتیاقی',NULL,NULL);
INSERT INTO "verses" VALUES(1934162,2589,1,0,'الا ای ساروان منزل دوست','هوش مصنوعی: ای کاروان، به سمت منزل دوست بروید که اشتیاقم به شدت افزایش یافته است.',NULL);
INSERT INTO "verses" VALUES(1934163,2589,0,1,'أُلاقی مِن نَواها ما أُلاقی',NULL,NULL);
INSERT INTO "verses" VALUES(1934164,2589,0,0,'سُلَیمیٰ مُنذُ حَلَّت بِالْعراقِ','هوش مصنوعی: از زمانی که سُلَیمیٰ به سرزمین عراق آمده، برخورد من با نواهایش به گونه‌ای است که تجربه‌های عجیبی را پشت سر می‌گذارم.',NULL);
INSERT INTO "verses" VALUES(1934165,2588,7,1,'می می‌خوری و طرهٔ دلدار می‌کشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934166,2588,7,0,'حافظ دگر چه می‌طلبی از نعیم دهر','هوش مصنوعی: حافظ، چه چیزی دیگر از خوشی‌های دنیا می‌خواهی؟ تو که در حال نوشیدن شراب هستی و با زیبایی محبوب خود به سر می‌بری.',NULL);
INSERT INTO "verses" VALUES(1934167,2588,6,1,'ای تازه گل که دامن از این خار می‌کشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934168,2588,6,0,'بازآ که چشم بد ز رخت دفع می‌کند','هوش مصنوعی: برگرد و با حضور زیبای خود، چشم زخم را از خود دور کن. ای گل تازه، تو که دامن خود را از این خارها می‌کشی.',NULL);
INSERT INTO "verses" VALUES(1934169,2588,5,1,'وه زین کمان که بر من بیمار می‌کشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934170,2588,5,0,'با چشم و ابروی تو چه تدبیر دل کنم؟','هوش مصنوعی: با نگاه و چهره زیبای تو چگونه می‌توانم دل را تسخیر کنم؟ ای وای از این کمان که بر من تیر می‌زند و مرا دردمند می‌کند.',NULL);
INSERT INTO "verses" VALUES(1934171,2588,4,1,'سهل است اگر تو زحمت این بار می‌کشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934172,2588,4,0,'گفتی سر تو بستهٔ فتراک ما شود','هوش مصنوعی: تو گفتی که اگر سر تو به فتراک ما بسته شود، مشکلی نیست، فقط کافی است که برای این کار زحمت بکشید.',NULL);
INSERT INTO "verses" VALUES(1934173,2588,3,1,'از خلوتم به خانهٔ خمار می‌کشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934174,2588,3,0,'هر دم به یاد آن لب میگون و چشم مست','هوش مصنوعی: هر لحظه به یاد آن لبان شیرین و چشمان مست مشغول می‌شوم و از تنهایی‌ام به میخانه می‌روم.',NULL);
INSERT INTO "verses" VALUES(1934175,2588,2,1,'هر دم به قید سلسله در کار می‌کشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934176,2588,2,0,'کاهل روی چو باد صبا را به بوی زلف','هوش مصنوعی: تنبل و بی‌هواس، به مانند نسیم صبح، هر لحظه با عطر زلفت به دام محبتت گرفتار می‌شوم.',NULL);
INSERT INTO "verses" VALUES(1934177,2588,1,1,'زان سوی هفت‌پرده به بازار می‌کشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934178,2588,1,0,'اشک حرم‌نشین نهان‌خانهٔ مرا','هوش مصنوعی: اشک‌های من که در حرم نشسته‌اند، به شکلی پنهان به سوی بیرون از هفت پرده می‌روند و مرا به میدان و بازار می‌آورند.',NULL);
INSERT INTO "verses" VALUES(1934179,2588,0,1,'خط بر صحیفهٔ گل و گلزار می‌کشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934180,2588,0,0,'زین خوش رقم که بر گل رخسار می‌کشی','هوش مصنوعی: از این چهره‌ی زیبا که بر روی گل‌ها می‌کشی، آثاری بر صفحات گل و باغ گل‌ها به جا می‌گذاری.',NULL);
INSERT INTO "verses" VALUES(1934181,2587,7,1,'هیچ خوش‌دل نپسندد که تو محزون باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934182,2587,7,0,'حافظ از فقر مکن ناله که گر شعر این است','هوش مصنوعی: حافظ می‌گوید که از وضعیت مالی‌ات شکایت نکن چون اگر شعر تو به همین حالت باشد، هیچ‌کس خوشحال نخواهد شد که تو ناراحت هستی.',NULL);
INSERT INTO "verses" VALUES(1934183,2587,6,1,'چند و چند از غم ایام جگرخون باشی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934184,2587,6,0,'ساغری نوش کن و جرعه بر افلاک فشان','هوش مصنوعی: شراب بنوش و چند جرعه از آن را به آسمان بپاش، تا چه اندازه از درد و رنج روزگار رنج بکشی؟',NULL);
INSERT INTO "verses" VALUES(1934185,2587,5,1,'ور خود از تخمهٔ جمشید و فریدون باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934186,2587,5,0,'تاج شاهی طلبی، گوهر ذاتی بنمای','هوش مصنوعی: اگر خواهان تاج شاهی هستی، نشان‌دهنده‌ی حقیقت وجودی‌ات را به نمایش بگذار، وگرنه اگر خود را از نسل جمشید و فریدون می‌دانی، در عمل این را ثابت کن.',NULL);
INSERT INTO "verses" VALUES(1934187,2587,4,1,'کی روی؟ ره ز که پرسی؟ چه کنی؟ چون باشی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934188,2587,4,0,'کاروان رفت و تو در خواب و بیابان در پیش','هوش مصنوعی: کاروان به سوی مقصدش حرکت کرده و تو هنوز در خواب هستی. در این بیابان وسیع، کجا می‌خواهی بروی؟ از چه کسی باید بپرسی؟ چه کاری می‌خواهی انجام دهی؟ در چه وضعیتی به سر می‌بری؟',NULL);
INSERT INTO "verses" VALUES(1934189,2587,3,1,'ور نه چون بنگری از دایره بیرون باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934190,2589,2,0,'خِرَد در زنده‌رود انداز و می نوش','هوش مصنوعی: عقل خود را رها کن و از زندگی لذت ببر، به شادی و نشاط جوانان عراقی بپیوند.',NULL);
INSERT INTO "verses" VALUES(1934191,2589,2,1,'به گلبانگ جوانان عراقی',NULL,NULL);
INSERT INTO "verses" VALUES(1934192,2589,3,0,'رَبیعُ العُمرِ فی مَرعیٰ حِماکُم','هوش مصنوعی: عمر بهار زندگی‌ام در دشت و مرتع شما می‌گذرد، خدایا بر تو نگهبان این پیوند و ملاقات ما باشید.',NULL);
INSERT INTO "verses" VALUES(1934193,2589,3,1,'حَماکَ اللّهُ یا عَهدَ التَّلاقی',NULL,NULL);
INSERT INTO "verses" VALUES(1934194,2590,4,1,'چو کِلک صُنع رقم زد به آبی و خاکی',NULL,NULL);
INSERT INTO "verses" VALUES(1934195,2590,4,0,'ز خاک پای تو داد آب، روی لاله و گل','هوش مصنوعی: آب زلالی که از زیر پای تو جاری شده، بر روی گل‌ها و لاله‌ها همچون آثار هنری زیبا و ظریف در آب و خاک نقش بسته است.',NULL);
INSERT INTO "verses" VALUES(1934196,2590,3,1,'که همچو قطره که بر برگ گل چکد پاکی',NULL,NULL);
INSERT INTO "verses" VALUES(1934197,2590,3,0,'که را رسد که کند عیب دامن پاکت؟','هوش مصنوعی: چه کسی می‌تواند به دامن پاک تو عیب بزند؟ تو مانند قطره‌ای هستی که بر روی گل می‌افتد و از پاکی سرشار است.',NULL);
INSERT INTO "verses" VALUES(1934198,2590,2,1,'أنَا اصْطَبَرتُ قَتیلاً و قاتِلی شاکی',NULL,NULL);
INSERT INTO "verses" VALUES(1934199,2590,2,0,'عجیب واقعه‌ای و غریب حادثه‌ای','هوش مصنوعی: واقعا حادثه عجیبی است که من به عنوان کسی که کشته شده، صبر کرده‌ام و حالا قاتل من نیز شکایت می‌کند.',NULL);
INSERT INTO "verses" VALUES(1934200,2590,1,1,'أیا مَنازِلَ سَلمیٰ فَأینَ سَلماکِ؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934201,2590,1,0,'بسا که گفته‌ام از شوق با دو دیدهٔ خود','بسیاری اوقات از روی شوق و اشتیاق، با دو چشم خود از منزلگاه‌های سلما پرسیده ام که کجاست سلمایتان؟',NULL);
INSERT INTO "verses" VALUES(1934202,2590,0,1,'بیا که بی تو به جان آمدم ز غمناکی',NULL,NULL);
INSERT INTO "verses" VALUES(1934203,2590,0,0,'کَتَبتُ قِصَّةَ شَوقی و مَدمَعی باکی','هوش مصنوعی: قصه‌ی دلتنگی‌ام را نوشتم و اشک‌هایم را نیز، بیا که با نبودن تو به جانم سخت گذشته و غم‌انگیز شده است.',NULL);
INSERT INTO "verses" VALUES(1934204,2589,13,1,'بخوان حافظ غزل‌های فراقی',NULL,NULL);
INSERT INTO "verses" VALUES(1934205,2589,13,0,'وصال دوستان روزی ما نیست','هوش مصنوعی: دوستی و همراهی با یاران، برای ما در این دنیا ممکن نیست، بهتر است شعرهای حافظ را بخوانیم که در مورد جدایی است.',NULL);
INSERT INTO "verses" VALUES(1934206,2589,12,1,'که با خورشید سازد هم‌وُثاقی',NULL,NULL);
INSERT INTO "verses" VALUES(1934207,2589,12,0,'مسیحای مجرد را برازد','هوش مصنوعی: پیام‌آور تنها را در نظر بگیر که با خورشید پیمانی می‌بندد.',NULL);
INSERT INTO "verses" VALUES(1934208,2587,3,0,'نقطهٔ عشق نمودم به تو هان سهو مکن','هوش مصنوعی: من نشانهٔ عشق را به تو نشان دادم، پس مراقب باش که اشتباه نکنی. وگرنه وقتی به آن نگاه کنی، ممکن است از دایرهٔ عشق خارج شوی.',NULL);
INSERT INTO "verses" VALUES(1934209,2589,11,1,'ولی گه گه سزاوار طلاقی',NULL,NULL);
INSERT INTO "verses" VALUES(1934210,2589,10,1,'به شعر فارسی، صوت عراقی',NULL,NULL);
INSERT INTO "verses" VALUES(1934211,2589,10,0,'بساز ای مطرب خوشخوان خوشگو','هوش مصنوعی: ای خواننده خوشصدا و خوش‌گوی، با هنرت از شعر فارسی و موسیقی عراقی لذت ببخش و بساز.',NULL);
INSERT INTO "verses" VALUES(1934212,2589,9,1,'غنیمت دان امور اتفاقی',NULL,NULL);
INSERT INTO "verses" VALUES(1934213,2589,9,0,'دمی با نیکخواهان متفق باش','هوش مصنوعی: لحظه‌ای با افرادی که نیکوخواه و خیرند همراه باش و این را فرصتی گرانbبه حساب بیاور.',NULL);
INSERT INTO "verses" VALUES(1934214,2589,8,1,'فَکَم بحرٍ عَمیقٍ مِن سَواقِ',NULL,NULL);
INSERT INTO "verses" VALUES(1934215,2589,8,0,'دُموعی بَعدَکُم لا تَحْقِروها','هوش مصنوعی: اشک‌ها و غم‌هایی که بعد از شما جاری می‌شود را دست‌کم نگیرید، زیرا ممکن است مانند دریاهای عمیق و بی‌پایانی باشند.',NULL);
INSERT INTO "verses" VALUES(1934216,2589,7,1,'أَلا تَعْساً لِأیّامِ الفِراقِ',NULL,NULL);
INSERT INTO "verses" VALUES(1934217,2589,7,0,'درونم خون شد از نادیدن دوست','هوش مصنوعی: درونم پر از غم و درد شده است به خاطر دوری از دوستی عزیز. ای کاش ایام جدایی هیچ‌گاه نمی‌بود.',NULL);
INSERT INTO "verses" VALUES(1934218,2589,6,1,'به یاران برفَشانم عمر باقی',NULL,NULL);
INSERT INTO "verses" VALUES(1934219,2589,6,0,'می باقی بده تا مست و خوشدل','هوش مصنوعی: به من می بده تا همراه دوستانم شاد و سرمست باشم و زمان باقی مانده را با آن‌ها سپری کنم.',NULL);
INSERT INTO "verses" VALUES(1934220,2589,5,1,'سماع چنگ و دست افشان ساقی',NULL,NULL);
INSERT INTO "verses" VALUES(1934221,2589,5,0,'جوانی باز می‌آرد به یادم','هوش مصنوعی: در دوران جوانی، یادمان می‌آید که چگونه ساز و آواز و شادی ناشی از نوشیدن باده، ما را به نشئگی و رقص وادار می‌کرد.',NULL);
INSERT INTO "verses" VALUES(1934222,2589,4,1,'سَقاکَ اللّهُ مِن کَأسٍ دِهاقِ',NULL,NULL);
INSERT INTO "verses" VALUES(1934223,2589,4,0,'بیا ساقی بده رَطْل گرانم','بیا ای ساقی، به من می در پیاله ای بزرگ بده که دل سنگین و غمگینم را شاد کند. خداوند تو را از می خوشگوار سیراب کند.',NULL);
INSERT INTO "verses" VALUES(1934224,2589,11,0,'عروسی بس خوشی ای دختر رَز','هوش مصنوعی: دختر زیبای رَز، در عروسی شادابی و خوشحالی فراوان است، اما گاهی اوقات به جدایی هم نیاز خواهد داشت.',NULL);
INSERT INTO "verses" VALUES(1934225,2583,9,0,'جدا شد یار شیرینت، کنون تنها نشین ای شمع!','ای شمع سوزان و عاشق‌‌، یار زیبا و شیرین تو رفت و تو را ترک کرد؛ تقدیر آسمانی این است‌، می‌خواهی با آن بساز و می‌خواهی بسوز! (یار شیرین شمع، عسل است که از موم او جدا شده است)',NULL);
INSERT INTO "verses" VALUES(1934226,2587,2,1,'شرط اول قدم آن است که مجنون باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934227,2587,1,1,'چشم دارم که به جاه از همه افزون باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934228,2585,1,0,'من نگویم که کنون با که نشین و چه بنوش','هوش مصنوعی: من نمی‌گویم که الآن با چه کسی باشی و چه چیزی بنوشی، زیرا تو خود می‌دانی که اگر هوشیار و با فکر باشی، چه کارهایی باید انجام بدهی.',NULL);
INSERT INTO "verses" VALUES(1934229,2585,0,1,'که بسی گُل بدمد باز و تو در گِل باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934230,2585,0,0,'نوبهار است در آن کوش که خوش‌دل باشی','هوش مصنوعی: بهار فرا رسیده است، از این فرصت استفاده کن و خوشحال و شاداب باش. زیرا ممکن است گل‌های زیادی در این فصل شکوفا شوند، اما اگر تو غمگین و دلگیر باشی، از زیبایی‌های زندگی بی‌بهره خواهی ماند.',NULL);
INSERT INTO "verses" VALUES(1934231,2584,8,1,'یَسَر الله طریقاً بکَ یا ملتمِسی',NULL,NULL);
INSERT INTO "verses" VALUES(1934232,2584,8,0,'چند پوید به هوای تو ز هر سو حافظ','هوش مصنوعی: چند بار به خاطر تو از هر طرف حرکت می‌کنم، حافظ، خداوند راهی را برای تو فراهم کند، ای کسی که طلب کرده‌ای.',NULL);
INSERT INTO "verses" VALUES(1934233,2584,7,1,'جان نهادیم بر آتش ز پی خوش‌نفسی',NULL,NULL);
INSERT INTO "verses" VALUES(1934234,2584,7,0,'تا چو مجمر نفسی دامن جانان گیرم','هوش مصنوعی: من همچون آتشدان، نفس جانان را در آغوش می‌گیرم؛ زیرا جانم را در راه خوش‌نفسی و آرامش قربانی کرده‌ام.',NULL);
INSERT INTO "verses" VALUES(1934235,2584,6,1,'حیف باشد چو تو مرغی که اسیر قفسی',NULL,NULL);
INSERT INTO "verses" VALUES(1934236,2584,6,0,'بال بگشا و صفیر از شجر طوبی زن','هوش مصنوعی: پرهایت را بگشا و صدای زیبایی از درخت طوبی برآور، چون تو مرغی هستی که در قفس اسیر شده‌ای و این بسیار حیف است.',NULL);
INSERT INTO "verses" VALUES(1934237,2584,5,1,'وه که بس بی‌خبر از غلغل چندین جرسی',NULL,NULL);
INSERT INTO "verses" VALUES(1934238,2584,5,0,'کاروان رفت و تو در خواب و بیابان در پیش','هوش مصنوعی: کاروان رفت و تو هنوز در خواب هستی، در حالی که بیابان و مسیر جلویت قرار دارد. وای بر تو که بی‌خبر از صدای شاد و پرشور این سفر هستی.',NULL);
INSERT INTO "verses" VALUES(1934239,2584,4,1,'فلَعَلّی لک آتٍ بشهابٍ قبسِ',NULL,NULL);
INSERT INTO "verses" VALUES(1934240,2584,4,0,'لمع البرق مِن الطّور و آنَستُ بهِ','هوش مصنوعی: درخششLightning در کوه طور را دیدم و با آن آشنا شدم. شاید به خاطر آن نشانه، در آینده شهابی از نور و روشنایی برای تو بیاورم.',NULL);
INSERT INTO "verses" VALUES(1934241,2584,3,1,'هر که مشهور جهان گشت به مشکین‌نفسی',NULL,NULL);
INSERT INTO "verses" VALUES(1934242,2584,3,0,'با دل خون‌شده چون نافه خوشش باید بود','هوش مصنوعی: هر کس که در دنیا به شهرت و معروفیت رسیده، باید مثل نافه‌ای خوشبو و دلنشین باشد، حتی اگر دلش پر از غصه و خون باشد.',NULL);
INSERT INTO "verses" VALUES(1934243,2584,2,1,'گفت: «ای عاشق بیچاره تو باری چه کسی؟»',NULL,NULL);
INSERT INTO "verses" VALUES(1934244,2584,2,0,'دوش در خیل غلامان درش می‌رفتم','هوش مصنوعی: دیشب در جمع یاران و خدمتگزاران دروازه وارد می‌شدم که ناگهان کسی گفت: «ای عاشق بیچاره، تو که هستی؟»',NULL);
INSERT INTO "verses" VALUES(1934245,2584,1,1,'شاه‌بازانِ طریقت به مقامِ مگسی',NULL,NULL);
INSERT INTO "verses" VALUES(1934246,2584,1,0,'چه شکرهاست در این شهر که قانع شده‌اند','هوش مصنوعی: در این شهر چه خوشحالی‌هایی وجود دارد که بزرگ‌ترین و برتر‌ترین افراد و مقام‌ها از پیروان راه و حقیقت، به سطحی پایین‌تر و جایی شبیه مگس راضی شده‌اند.',NULL);
INSERT INTO "verses" VALUES(1934247,2584,0,1,'ای پسر جام مِی‌ام ده که به پیری برسی',NULL,NULL);
INSERT INTO "verses" VALUES(1934248,2584,0,0,'عمر بگذشت به بی‌حاصلی و بوالهوسی','هوش مصنوعی: عمر به سرعت سپری شد و در دلش هیچ دستاوردی نداشت. ای پسر، به من شراب بده تا این لذت‌ها را بچشم، چون با پیری دیگر وقتی برای خوشی نخواهد بود.',NULL);
INSERT INTO "verses" VALUES(1934249,2583,13,1,'جبینش صبح‌خیزان راست، روز فتح و فیروزی',NULL,NULL);
INSERT INTO "verses" VALUES(1934250,2583,13,0,'جنابش پارسایان راست، محراب دل و دیده','جناب او‌، محراب دل و چشم پاکان و پارسایان است، و دیدن روی او برای صبح‌خیزان عابد‌، روز پیروزی و گشایش است.',NULL);
INSERT INTO "verses" VALUES(1934251,2583,12,1,'ز مدح آصفی خواهد، جهان عیدی و نوروزی',NULL,NULL);
INSERT INTO "verses" VALUES(1934252,2583,12,0,'نه حافظ می‌کند تنها دعای خواجه توران‌شاه','فقط حافظ دعاگوی خواجه توران‌شاه نیست بلکه جهانیان او را مدح می‌گویند تا عیدی و نوروزی خود را بگیرند.',NULL);
INSERT INTO "verses" VALUES(1934253,2583,11,1,'که بخشد جرعهٔ جامت، جهان را سازِ نوروزی',NULL,NULL);
INSERT INTO "verses" VALUES(1934254,2583,11,0,'مِی اندر مجلسِ آصف، به نوروزِ جلالی نوش','می را در بزم و مهمانی آصف و در نوروز جلالی بنوش، زیرا جرعه جام تو جهان را نوای نوروز و زندگی تازه خواهد بخشید.',NULL);
INSERT INTO "verses" VALUES(1934255,2583,10,1,'بیا ساقی که جاهل را هنی‌تر می‌رسد روزی',NULL,NULL);
INSERT INTO "verses" VALUES(1934256,2583,10,0,'به عُجْبِ علم نتوان شد، ز اسباب طرب محروم','شایسته نیست که آدمی به‌جهت غرور علم و دانایی‌، خود را از شادی محروم کند، ساقی می بریز و شاد کن که آدم نادان روزی‌اش را آسان‌تر به دست می‌آورد.',NULL);
INSERT INTO "verses" VALUES(1934257,2585,1,1,'که تو خود دانی اگر زیرک و عاقل باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934258,2585,2,0,'چنگ در پرده همین می‌دهدت پند ولی','هوش مصنوعی: اگر به خوبی گوش کنی و از موسیقی زندگی و صداهای اطراف درس بگیری، آنگاه می‌توانی از نصیحت‌ها و سخنان آموزنده بهره‌مند شوی؛ اما این نصیحت‌ها تنها زمانی مؤثرند که خودت آمادگی پذیرش آن‌ها را داشته باشی.',NULL);
INSERT INTO "verses" VALUES(1934259,2585,2,1,'وعظت آن گاه کند سود که قابل باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934260,2585,3,0,'در چمن هر ورقی دفتر حالی دگر است','هوش مصنوعی: در میان چمن، هر برگ داستانی تازه دارد. کاش افسوس که از همه این زیبایی‌ها غافل باشی.',NULL);
INSERT INTO "verses" VALUES(1934261,2587,1,0,'در مقامی که صدارت به فقیران بخشند','هوش مصنوعی: در جایی که مقام و قدرت به افراد بی‌پول داده می‌شود، من امید دارم که تو از نظر مقام و جایگاه برتر از همه باشی.',NULL);
INSERT INTO "verses" VALUES(1934262,2587,0,1,'بی زر و گنج به صد حشمت قارون باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934263,2587,0,0,'ای دل آن دم که خراب از می گلگون باشی','ای دل، وقتی که مست از شراب سرخ رنگ (عشق) باشی، بدون آن که ثروت و گنجی داشته باشی، صد ها بار بیشتر از قارون جایگاه و بزرگی پادشاه را داری',NULL);
INSERT INTO "verses" VALUES(1934264,2586,9,1,'مگر تو از کرم خویش، یار من باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934265,2586,9,0,'من ار چه حافظ شهرم، جویی نمی‌ارزم','باید توجه کرد که جَو در قدیم واحد پول و کم‌ارزش بوده است. « از نقد تو هر یک جو، دینار شود روزی » سیف فرغانی',NULL);
INSERT INTO "verses" VALUES(1934266,2586,8,1,'به جای اشک روان، در کنار من باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934267,2586,8,0,'من این مراد ببینم به خود که نیم‌شبی','هوش مصنوعی: من آرزو دارم که تو را در کنار خود ببینم، که در نیمۀ شب به جای اشک و غم، در کنارم باشی.',NULL);
INSERT INTO "verses" VALUES(1934268,2586,7,1,'اگر ادا نکنی، قرض‌دار من باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934269,2586,7,0,'سه بوسه کز دو لبت، کرده‌ای وظیفهٔ من','هوش مصنوعی: اگر سه بوسه از لب‌هایت به من داده‌ای و این کار را به‌عنوان وظیفه‌ام انجام نداده‌ای، خوب است که بدانی در این صورت، تو نسبت به من دین‌دار خواهی بود.',NULL);
INSERT INTO "verses" VALUES(1934270,2586,6,1,'گر آهویی چو تو یک دم، شکار من باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934271,2586,6,0,'شود غزالهٔ خورشید، صید لاغر من','هوش مصنوعی: اگر تو مانند بزی زیبا و دلربا یک لحظه به من توجه کنی، خورشید من به شکار تو خواهد آمد و من هم به شوق تو و زیبایی‌ات در پی تو می‌دویدم.',NULL);
INSERT INTO "verses" VALUES(1934272,2586,5,1,'دمی انیسِ دلِ سوگوارِ من باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934273,2586,5,0,'شبی به کلبهٔ احزانِ عاشقان آیی','هوش مصنوعی: شبی به خانهٔ دل‌شکستگان بیا، و کمی همراه من باش تا تنهایی و غم‌های من را تسکین دهی.',NULL);
INSERT INTO "verses" VALUES(1934274,2586,4,1,'گرت ز دست برآید، نگار من باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934275,2587,2,0,'در ره منزل لیلی که خطرهاست در آن','هوش مصنوعی: برای رسیدن به عشقی همچون لیلی، که در راه آن خطرات زیادی وجود دارد، اولین شرط این است که مثل مجنون عاشق و دیوانه باشی.',NULL);
INSERT INTO "verses" VALUES(1934276,2586,4,0,'در آن چمن که بتان، دست عاشقان گیرند','هوش مصنوعی: در چمنی که معشوق‌ها دل عاشقان را به تسخیر می‌آورند، اگر بتوانی از چنگال آنها فرار کنی، به معشوق من بدل خواهی شد.',NULL);
INSERT INTO "verses" VALUES(1934277,2586,3,0,'از آن عقیق که خونین‌دلم ز عشوهٔ او','اگر از عشوه روی لب های تو که دل من را خونین کرده گله کنم، تو باید به من غم‌ها را تسکین دهی‌ و درک نشان بدی.',NULL);
INSERT INTO "verses" VALUES(1934278,2586,2,1,'تو در میانه، خداوندگار من باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934279,2586,2,0,'چو خسروانِ ملاحت، به بندگان نازند','هوش مصنوعی: مانند خسروان زیبا که بر بندگان خود ناز می‌کنند، تو در میان آنها، سرور من باش.',NULL);
INSERT INTO "verses" VALUES(1934280,2586,1,1,'انیسِ خاطر امّیدوار من باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934281,2586,1,0,'چراغِ دیدهٔ شب‌زنده‌دار من گردی','هوش مصنوعی: چشمان من در تاریکی شب زندگی‌ام، مانند نوری است که به من امید می‌دهد؛ امیدوارم تو همواره همدم و همراه من باشی.',NULL);
INSERT INTO "verses" VALUES(1934282,2586,0,1,'مرادبخش دل بی‌قرار من باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934283,2586,0,0,'هزار جهد بکردم که یار من باشی','هوش مصنوعی: من هزار بار تلاش کردم که تو همراه و یار من باشی و آرزوی قلبی بی‌قرارم را برآورده کنی.',NULL);
INSERT INTO "verses" VALUES(1934284,2585,6,1,'صید آن شاهد مطبوع‌شمایل باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934285,2585,6,0,'حافظا گر مدد از بخت بلندت باشد','هوش مصنوعی: ای حافظ، اگر بخت نیکو به تو کمک کند، تو هم خواهی توانست آن معشوق زیبا و دلنشین را به دست بیاوری.',NULL);
INSERT INTO "verses" VALUES(1934286,2585,5,1,'رفتن آسان بود ار واقف منزل باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934287,2585,5,0,'گر چه راهی‌ست پر از بیم ز ما تا بر دوست','هوش مصنوعی: هر چند که مسیر رسیدن به محبوب پر از خطر است، اما اگر به منزلت و مقام او آگاه باشی، این سفر آسان‌تر به نظر می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1934288,2585,4,1,'گر شب و روز در این قصهٔ مشکل باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934289,2585,4,0,'نقد عمرت ببرد غصهٔ دنیا به گزاف','هوش مصنوعی: غصه‌ها و دغدغه‌های دنیوی باعث می‌شود عمرت به راحتی هدر رود، پس اگر شب و روز خود را در مشکلات این قصه سپری کنی، در واقع عمرت را بی‌دلیل از دست می‌دهی.',NULL);
INSERT INTO "verses" VALUES(1934290,2585,3,1,'حیف باشد که ز کار همه غافل باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934291,2586,3,1,'اگر کنم گله‌ای غم‌گسار من باشی',NULL,NULL);
INSERT INTO "verses" VALUES(1934292,2576,3,1,'که با حکم خدایی کینه داری',NULL,NULL);
INSERT INTO "verses" VALUES(1934293,2605,2,0,'بگو که جان عزیزم ز دست رفت، خدا را','هوش مصنوعی: بگو که جان گرامی‌ام از دست رفت و از خداوند بخواه که به خاطر لب‌های زیبایت، روح من را شاداب کند، آن کس که تو او را بهتر می‌شناسی.',NULL);
INSERT INTO "verses" VALUES(1934294,2605,3,0,'من این حروف نوشتم، چنان که غیر ندانست','هوش مصنوعی: من این کلمات را نوشتم جوری که دیگران نتوانند بفهمند، تو هم بر اساس مهرت، به طریقی که خودت می‌دانی، بخوان.',NULL);
INSERT INTO "verses" VALUES(1934300,2624,7,1,'بلبل به نواسازی، حافظ به غزل‌گویی',NULL,NULL);
INSERT INTO "verses" VALUES(1934301,2624,7,0,'هر مُرغ به دستانی در گلشنِ شاه آمد','در باغِ پادشاه، هر پرنده ای با هنر (نغمه‌ی) خاصی آمده است؛ بلبل با نوای دل‌انگیزش و حافظ با غزل سرایی اش.',NULL);
INSERT INTO "verses" VALUES(1934302,2624,6,1,'خوش بودی اگر بودی بوییش ز خوش‌خویی',NULL,NULL);
INSERT INTO "verses" VALUES(1934303,2624,6,0,'آن طُرِّه که هر جَعْدَش، صد نافهٔ چین اَرْزَد','آن موی زیبا که هر حلقه‌اش به اندازه‌ صد نافه‌ی (عطر) چین خوش‌بو هست، اگر بوی خوش‌اخلاقی را از آن احساس می‌کردیم، بسیار زیباتر می‌بود.',NULL);
INSERT INTO "verses" VALUES(1934304,2624,5,1,'طرْفِ هنری بَربَند از شمعِ نکورویی',NULL,NULL);
INSERT INTO "verses" VALUES(1934305,2624,5,0,'چون شمع، نکورویی در رهگذرِ باد است','هوش مصنوعی: انسانی که دارای زیبایی و هنری است، مثل شمعی در معرض باد قرار دارد. بنابراین، از او و هنر او بهره‌مند شو و استفاده کن.',NULL);
INSERT INTO "verses" VALUES(1934306,2624,4,1,'دریاب و بِنِه گنجی از مایهٔ نیکویی',NULL,NULL);
INSERT INTO "verses" VALUES(1934307,2624,4,0,'امروز که بازارت، پرجوش خریدار است','هوش مصنوعی: امروز که بازار شلوغ و پر از خریدار است، از این فرصت استفاده کن و چیزی باارزش و خوب به دیگران بده.',NULL);
INSERT INTO "verses" VALUES(1934308,2624,3,1,'ای شاخِ گُلِ رعنا، از بهرِ که می‌رویی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934309,2624,3,0,'تا غنچهٔ خندانت، دولت به که خواهد داد','تو که مثل غنچه‌ای خندان و شکفته‌ای، این زیبایی رو به چه کسی خواهی بخشید؟ای شاخهٔ زیبای گل، برای چه کسی در حال شکفتنی؟',NULL);
INSERT INTO "verses" VALUES(1934310,2624,2,1,'تا سَرو بیآموزد از قَدِّ تو، دل‌جویی',NULL,NULL);
INSERT INTO "verses" VALUES(1934311,2624,2,0,'شمشاد، خُرامان کُن وآهنگِ گُلِسْتان کُن','شمشاد، با ناز قدم بردار و بسوی گلستان بیا. تا سرو، از قامت زیبای تو دل‌ربایی را یاد بگیرد.',NULL);
INSERT INTO "verses" VALUES(1934312,2624,1,1,'لَب گیری و رُخ بوسی، مِی نوشی و گُل بویی',NULL,NULL);
INSERT INTO "verses" VALUES(1934313,2624,1,0,'مَسْنَد به گُلستان بَر، تا شاهد و ساقی را','هوش مصنوعی: بنشین و در فضای زیبا و دلنشین گلستان، از زیبایی شاهد و ساقی لذت ببر. با آنها صحبت کن، می‌نوشی و عطر گل‌ها را استشمام می‌کنی.',NULL);
INSERT INTO "verses" VALUES(1934314,2624,0,1,'این گفت سَحرگَه گُل، بلبل! تو چه می‌گویی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934315,2624,0,0,'مِی خواه و گُل‌اَفشان کن، از دَهر چه می‌جویی؟','شراب بنوش و گل بپاش (شاد باش). از زندگی به دنبال چه می‌گردی؟ این را گل در صبح زود به بلبل گفت، «تو چه نظری داری؟»',NULL);
INSERT INTO "verses" VALUES(1934316,2623,7,1,'بازآیَد و از کُلْبِهٔ اَحْزان به دَرآیی!',NULL,NULL);
INSERT INTO "verses" VALUES(1934317,2623,7,0,'حافِظ! مَکُن اَنْدیشِه که آن یوسُفِ مَه‌رو','هوش مصنوعی: نگران نباش که آن معشوق زیبا از راه برسد و تو بتوانی از اندوه و درد خود خارج شوی.',NULL);
INSERT INTO "verses" VALUES(1934318,2623,6,1,'تا بو که تو چون سَرْوِ خُرامان به دَرآیی',NULL,NULL);
INSERT INTO "verses" VALUES(1934319,2623,6,0,'بَر رَهْگُذَرَت بَسْتِه‌ام از دیده، دو صَد جوی','هوش مصنوعی: من با دوصد اشک و حسرت، راه را برای تو بسته‌ام تا ببینم که چطور مثل سروانی زیبا و بلندبالا، به سوی من می‌آیی.',NULL);
INSERT INTO "verses" VALUES(1934320,2623,5,1,'وَقْت است که همچون مَهِ تابان به دَرآیی',NULL,NULL);
INSERT INTO "verses" VALUES(1934321,2623,5,0,'در تیره‌شَبِ هِجْرِ تو، جانَم به لَب آمَد','هوش مصنوعی: در شب تاریک و غم‌انگیز دوری تو، جانم به ته کشیده و به نهایت رسیده است. وقت آن رسیده که مانند ماه روشن و درخشان، وارد زندگی‌ام شوی.',NULL);
INSERT INTO "verses" VALUES(1934322,2623,4,1,'کز غُنْچِه چو گُل، خُرَّم و خَنْدان به دَرآیی',NULL,NULL);
INSERT INTO "verses" VALUES(1934323,2623,4,0,'چَنْدان، چو صَبا بَر تو گُمارم دَمِ هِمَّت','هوش مصنوعی: هر چه قدر که من تلاش کنم و بر تو بخواهم، باید به مانند گل خوشبو و شاداب از غنچه بیرون بیایی.',NULL);
INSERT INTO "verses" VALUES(1934325,2623,3,1,'باشَد که چو خورشید درخشان به دَرآیی',NULL,NULL);
INSERT INTO "verses" VALUES(1934358,2623,3,0,'جان می‌دَهم از حَسْرَتِ دیدارِ تو، چون صُبْح','از شوق و حسرت دیدار تو جان خودم را مانند صبح تسلیم میکنم تا آنکه مانند خورشید درخشان طلوع کنی و بیرون بیایی',NULL);
INSERT INTO "verses" VALUES(1934359,2623,2,1,'گر تِشْنِه‌لَب از چَشْمِهٔ حِیوان به دَرآیی',NULL,NULL);
INSERT INTO "verses" VALUES(1934360,2623,2,0,'شایَد که به آبی، فَلَکَت، دَسْت نَگیرد','اگر به چشمه طبیعی و زنده حیوان برسی و از آن ننوشی و تشنه بیرون شوی جا دارد که آبی از آسمان و روزگار اندکی تو را یاری نکند',NULL);
INSERT INTO "verses" VALUES(1934361,2621,7,1,'کِه گویی نَبوده‌ست خود، آشْنایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934362,2621,7,0,'رَفیقان، چُنان، عَهْدِ صُحْبَت شِکَسْتَنْد','هوش مصنوعی: دوستان به گونه‌ای عهد و پیمان دوستی را شکستند که انگار هیچ‌گاه با یکدیگر آشنا نبوده‌اند.',NULL);
INSERT INTO "verses" VALUES(1934363,2621,6,1,'کِه دَر تابم اَز دَسْتِ زُهْدِ ریایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934364,2621,6,0,'مِیِ صوفی‌اَفْکَن، کُجا می‌فُروشَنْد؟','هوش مصنوعی: می‌پرسم از آن کسی که به می‌نوشی ویژ‌ه است، کجا می‌توانم می پیدا کنم؟ چرا که از ریاکاری و زهد ظاهری خسته‌ام و نیاز به آرامش دارم.',NULL);
INSERT INTO "verses" VALUES(1934365,2621,5,1,'نَخواهَد زِ سَنْگین‌دِلان، مومیایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934366,2621,5,0,'دِلِ خَسْتِهٔ مَن گَرَش هِمَّتی هَسْت','هوش مصنوعی: دل خسته‌ام اگر اراده‌ای داشته باشد، نمی‌خواهد از دل‌های سنگین و غمگین کمکی بگیرد.',NULL);
INSERT INTO "verses" VALUES(1934367,2621,4,1,'زِ حَد می‌بَرَد شیوِهٔ بی‌وَفایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934368,2621,4,0,'عَروسِ جَهان گَرچِه دَر حَدِّ حُسْن است','جهان هرچند مانند عروس، در زیبایی بی‌نظیر است، اما روش بی‌وفایی را از حد می گذراند',NULL);
INSERT INTO "verses" VALUES(1934369,2621,3,1,'فُروشَنْد مِفْتاحِ مُشْکِل‌گُشایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934370,2621,3,0,'زِ کویِ مُغان، رُخ مَگَرْدان! کِه آنجا','از محله‌ی می فروشان روی خود را بر نگردان، چون در آن‌جا کلید حل مسائل و مشکلات را به مردم می‌فروشند.',NULL);
INSERT INTO "verses" VALUES(1934371,2621,2,1,'دِلَم، خون شد از غُصِّه؛ ساقی! کُجایی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934372,2621,2,0,'نِمی‌بینَم از هَمْدَمان، هیچ بَر جای','هوش مصنوعی: من هیچ یک از دوستانم را نمی‌بینم و دلم پر از غصه و ناکامی است. ای ساقی، کجا هستی که مرا از این حال نجات دهی؟',NULL);
INSERT INTO "verses" VALUES(1934373,2621,1,1,'بِدان شَمْعِ خَلْوَتْگَهِ پارسایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934374,2621,1,0,'درودی چو نورِ دِلِ پارسایان','هوش مصنوعی: سلامی که به دل پارسایان می‌رسد همچون نوری است که در محفل عبادت و پرهیزگاری تابیده می‌شود.',NULL);
INSERT INTO "verses" VALUES(1934375,2621,0,1,'بِدان مَرْدُمِ دیدِهٔ روشَنایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934376,2621,0,0,'سَلامی چو بویِ خوشِ آشنایی','هوش مصنوعی: سلامی که به خوبی بوی آشنایی می‌دهد، به مردم با چشمان روشن و باهوش می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1934377,2620,9,1,'اگر سفینهٔ حافظ رسد به دریایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934378,2620,9,0,'دُرَر ز شوق برآرند ماهیان به نثار','هوش مصنوعی: ماهی‌ها از شادی و عشق مرواریدهایی را بیرون می‌آورند، اگر که کشتی حافظ به دریا برسد.',NULL);
INSERT INTO "verses" VALUES(1934379,2620,8,1,'که حیف باشد از او، غیرِ او، تمنایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934380,2620,8,0,'فراق و وصل چه باشد؟ رضایِ دوست طلب','هوش مصنوعی: فراق و وصال چیست؟ تنها برآورده کردن رضایت دوست را بجویید، چرا که درخواست غیر از او از او بی‌فایده است.',NULL);
INSERT INTO "verses" VALUES(1934381,2620,7,1,'کجا بود به فروغِ ستاره، پروایی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934382,2620,7,0,'مرا که از رخِ او، ماه در شبستان است','هوش مصنوعی: مرا که زیبایی او مانند ماه در دنیای شب است، چگونه می‌توانم به روشنایی ستاره‌ها فکر کنم؟',NULL);
INSERT INTO "verses" VALUES(1934383,2620,6,1,'عجب مدار سَری اوفتاده در پایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934384,2620,6,0,'در آن مَقام که خوبان ز غَمزه، تیغ زنند','هوش مصنوعی: در جایی که زیبایی‌ها با نگاهی نافذ و جذاب خود به دل‌ها حمله می‌کنند، عجیب نیست که کسی ناخواسته و به طور غافلگیرانه در دام عشق بیفتد.',NULL);
INSERT INTO "verses" VALUES(1934385,2620,5,1,'که نیستش به کس از تاج و تخت، پروایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934386,2620,5,0,'زمامِ دِل به کسی دادِه‌ام منِ دَرویش','هوش مصنوعی: دل‌باخته‌ام به کسی که هیچ توجهی به قدرت و ثروت ندارد و من نیز به عنوان یک درویش، از این دنیا بی‌نیازم.',NULL);
INSERT INTO "verses" VALUES(1934387,2620,4,1,'که می‌رَویم به داغِ بلندبالایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934388,2620,4,0,'به روزِ واقعه، تابوتِ ما زِ سرو کنید','هوش مصنوعی: در روزی که سرنوشت محتوم فرا می‌رسد، به یاد ما که در دل غم‌های بزرگ رفته‌ایم، تابوت ما را از درختان سرو بسازید.',NULL);
INSERT INTO "verses" VALUES(1934389,2620,3,1,'بیا! ببین! که کِرا می‌کُند تماشایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934390,2621,8,0,'مَرا گَر تو بُگْذاری، اِی نَفْس طامِع!','هوش مصنوعی: اگر تو مرا آزاد بگذاری، ای نفس حریص، می‌توانم در حیطه‌ای که در آن تنها به گدایی مشغولم، سلطنت و فرمانروایی کنم.',NULL);
INSERT INTO "verses" VALUES(1934391,2621,8,1,'بَسی پادْشایی کُنَم دَر گِدایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934392,2621,9,0,'بیاموزَمت کیمیایِ سَعادَت','هوش مصنوعی: برای رسیدن به خوشبختی و سعادت، باید از کنار افرادی که تأثیر منفی دارند دوری کنی و در کنار انسان‌های خوب و مثبت قرار بگیری.',NULL);
INSERT INTO "verses" VALUES(1934393,2621,9,1,'زِ هَم‌صُحْبَتِ بَد، جُدایی! جُدایی!',NULL,NULL);
INSERT INTO "verses" VALUES(1934394,2623,1,1,'آدَم‌صِفَت از روضِهٔ رِضْوان به دَرآیی',NULL,NULL);
INSERT INTO "verses" VALUES(1934395,2623,1,0,'هُش دار که گَر وَسْوَسِهٔ عَقْل کُنی گوش','مواظب و به هوش باش که اگر به وسوسه های عقل گوش بدهی مانند آدم از بهشت بیرون و دور میشوی',NULL);
INSERT INTO "verses" VALUES(1934396,2623,0,1,'هر جا که رَوی، زود، پَشیمان به دَرآیی',NULL,NULL);
INSERT INTO "verses" VALUES(1934397,2623,0,0,'اِی دِل! گَر از آن چاهِ زَنَخْدان به دَرآیی','ای دل اگر از آن گودی چانه معشوق بیرون آیی هر جای دیگری که بروی پشیمان و زود بر میگردی',NULL);
INSERT INTO "verses" VALUES(1934398,2622,11,1,'شادیْت، مُبارَک باد! اِی عاشِقِ شِیدایی!',NULL,NULL);
INSERT INTO "verses" VALUES(1934399,2622,11,0,'«حافِظ»! شَبِ هِجْران شُد، بویِ خوشِ وَصْل آمَد','هوش مصنوعی: شب جدایی به پایان رسید و عطر خوش وصال در فضا پخش شده است. امیدوارم این لحظه خوشی و شادی تو، ای عاشق دلی شیدا، مملو از خوشحالی باشد.',NULL);
INSERT INTO "verses" VALUES(1934400,2622,10,1,'تا حَل کنم این مُشْکِل دَر ساغَرِ مینایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934401,2622,10,0,'زین دایِرِهٔ مینا، خونین‌جِگَرَم، مِی دِه!','هوش مصنوعی: خون دل من از این دایرهٔ مینا ریخته شده، بیا و به من شراب بده تا بتوانم این مشکل را در جام مینا حل کنم.',NULL);
INSERT INTO "verses" VALUES(1934402,2622,9,1,'کُفْر است در این مَذْهَب، خودبینی و خودرایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934403,2622,9,0,'فِکْرِ خود و رایِ خود در عالَم رِنْدی نیست','هوش مصنوعی: اگر کسی فقط به فکر خود و نظر خودش باشد، در دنیای فریب و نیرنگ، این عمل نشانه‌ی کفر است و نشان‌دهنده‌ی خودخواهی و خودپرستی است.',NULL);
INSERT INTO "verses" VALUES(1934404,2622,8,1,'لُطْف، آن‌چه تو اَنْدیشی؛ حُکْم، آن‌چه تو فَرمایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934405,2622,8,0,'دَر دایِرِهٔ قِسْمَت، ما، نُقْطِهٔ تَسْلیمیم','هوش مصنوعی: ما در دایرهٔ سرنوشت خود پذیرفته‌ایم که تسلیم خواسته‌هایمان باشیم و فقط به آنچه تو فکر می‌کنی و آنچه تو دستور می‌دهی، عمل کنیم.',NULL);
INSERT INTO "verses" VALUES(1934406,2622,7,1,'وِی یادِ تواَم مونِس در گوشِهٔ تَنهایی!',NULL,NULL);
INSERT INTO "verses" VALUES(1934407,2622,7,0,'اِی دَرْدِ تواَم دَرْمان در بَسْتَرِ ناکامی!','هوش مصنوعی: ای دردی که تو باعث درمانم هستی در زمانی که به ناامیدی دچارم و یاد تو هم به من آرامش می‌دهد در ساعات تنهایی‌ام.',NULL);
INSERT INTO "verses" VALUES(1934409,2622,6,1,'شِمْشاد، خُرامان کُن! تا باغ بیارایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934410,2622,5,1,'رُخْساره به کَس نَنْمود آن شاهِدِ هَرجایی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934411,2622,5,0,'یا رَب! بِه‌ کِه شایَد گُفْت این نُکْتِه که در عالَم','هوش مصنوعی: پروردگارا، چه کسی می‌تواند بگوید که این راز را که در جهان، تنها بر چهره کسی ظاهر نمی‌شود، آن شاهد میهمان هر جا است؟',NULL);
INSERT INTO "verses" VALUES(1934412,2622,4,1,'کَز دَسْت بِخواهَد شُد پایابِ شَکیبایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934413,2622,4,0,'مُشْتاقی و مَهْجوری، دور از تو چُنانم کَرْد','هوش مصنوعی: عاشق و غمگین بودن و فاصله‌ای که از تو دارم، به قدری حال مرا بد کرده که دیگر نشانه‌ای از صبر و تحمل در من نمانده است.',NULL);
INSERT INTO "verses" VALUES(1934414,2622,3,1,'این است حَریف ای دِل! تا باد نَپِیمایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934415,2622,3,0,'صَد بادِ صَبا، این‌جا، با سِلْسِلِه می‌رَقْصَنْد','هوش مصنوعی: در اینجا صدای نسیم‌های لطیف و دلپذیر در حال رقصدن است. ای دل، این زیبایی‌ها را تجربه کن و تا زمانی که فرصت داری از آن لذت ببر.',NULL);
INSERT INTO "verses" VALUES(1934416,2622,2,1,'گُفْتا: «غَلَطی! بُگْذَر زین فِکْرَتِ سودایی!»',NULL,NULL);
INSERT INTO "verses" VALUES(1934417,2622,2,0,'دیشَب، گِلِهٔ زُلْفَش با باد، هَمی کَرْدَم','هوش مصنوعی: شب گذشته به زلف او در کنار باد شکایت کردم. او گفت: «غلط می‌کنی، از این فکر دیوانه‌وار بگذر!»',NULL);
INSERT INTO "verses" VALUES(1934418,2622,1,1,'دَریاب ضَعیفان را دَر وَقْتِ تَوانایی!',NULL,NULL);
INSERT INTO "verses" VALUES(1934419,2622,1,0,'دائم، گُلِ این بُسْتان، شاداب نمی‌مانَد','هوش مصنوعی: این باغ همیشه سرسبز و شاداب نمی‌ماند، پس در زمانی که قدرت و توانایی داری، به کمک و حمایت افراد ضعیف و نیازمند بپرداز.',NULL);
INSERT INTO "verses" VALUES(1934420,2622,0,1,'دِل، بی‌‌تو، به جان آمَد؛ وَقْت است کِه بازآیی',NULL,NULL);
INSERT INTO "verses" VALUES(1934421,2622,0,0,'اِی پادِشَهِ خوبان! داد از غَمِ تَنْهایی','هوش مصنوعی: ای پادشاه زیبا رویان، دل من از غم تنهایی به شدت رنج می‌کشد و جانم به لب رسیده است. اکنون وقت آن است که دوباره به نزد من بازگردی.',NULL);
INSERT INTO "verses" VALUES(1934422,2621,10,1,'چِه دانی تو، اِی بَنْدِه! کارِ خُدایی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934423,2621,10,0,'مَکُن «حافِظ» اَز جورِ دوران، شِکایَت!','هوش مصنوعی: ای حافظ، از ظلم و سختی‌های زمانه گلایه نکن، زیرا تو که بنده‌ای، نمی‌دانی که کارهای خداوند چگونه‌اند.',NULL);
INSERT INTO "verses" VALUES(1934424,2622,6,0,'ساقی! چَمَنِ گُل را بی‌‌رویِ تو، رَنْگی نیست','هوش مصنوعی: ای ساقی! بدون وجود تو، چمن و گل هیچ رنگ و زیبایی ندارند. بیا با خمیدگی و زیبایی خود، باغ را زینت بدهی.',NULL);
INSERT INTO "verses" VALUES(1934492,2620,3,0,'مُکدّر است دِل، آتش به خرقه خواهم زد','هوش مصنوعی: دل من به خاطر غم‌ها و ناراحتی‌ها مکدر شده است. می‌خواهم با شعله‌ای از آتش در این لباس خود، حالتی جدید بسازم. بیا و ببین که چه کسی را در این حالت جذاب و تماشایی می‌توان یافت!',NULL);
INSERT INTO "verses" VALUES(1934559,2620,2,1,'در آرزویِ سر و چشمِ مجلس‌آرایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934560,2620,2,0,'سَرم زِ دست بشد، چشم از انتظار بسوخت','هوش مصنوعی: سرم از دست رفته و چشمم در انتظار سوخته است، در حسرت زیبایی و تماشای چهره‌ای که مجلس را زینت می‌بخشد.',NULL);
INSERT INTO "verses" VALUES(1934561,2620,1,1,'از آن کمانچهٔ ابرو رسد به طُغرایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934562,2612,0,0,'سحرگه ره ‎روی در سرزمینی','هوش مصنوعی: صبح زود، کسی که در سفر بود در سرزمینی به راز و رمزهایی اشاره می‌کرد و با یک همراه درباره آن صحبت می‌کرد.',NULL);
INSERT INTO "verses" VALUES(1934563,2611,7,1,'گر جمله می‌کنند، تو باری نمی‌کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934564,2611,7,0,'حافظ برو که بندگیِ پادشاهِ وقت','هوش مصنوعی: حافظ، برو و از خدمت به حاکم زمانه دور شو، زیرا اگر همه مردم در این خدمت باشند، تو نیازی به آن نداری و نمی‌خواهی خود را درگیر کنی.',NULL);
INSERT INTO "verses" VALUES(1934565,2611,6,1,'واندیشه از بلای خماری نمی‌کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934566,2611,6,0,'ساغر لطیف و دلکش و مِی، افکنی به خاک','هوش مصنوعی: این بیت به زیبایی و جذابیت یک فنجان نوشیدنی اشاره دارد و بیان می‌کند که شخص آن را به زمین می‌ریزد، اما به جای اینکه نگران حال خود و عوارض ناشی از مستی باشد، به فکر و اندیشه‌های دیگر مشغول است. به طور کلی، نوعی بی‌توجهی به عواقب و حالتی از بی‌خیالی را به تصویر می‌کشد.',NULL);
INSERT INTO "verses" VALUES(1934567,2611,5,1,'وآن را فدای طرهٔ یاری نمی‌کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934568,2611,5,0,'در آستینِ جان تو صد نافه مدرج است','هوش مصنوعی: در درون جان تو زیبایی‌ها و لطافت‌های زیادی نهفته است، اما تو برای جلب توجه محبوب خود حاضر نیستی به آن‌ها بها دهی.',NULL);
INSERT INTO "verses" VALUES(1934569,2611,4,1,'کز گلشنش تحملِ خاری نمی‌کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934570,2611,4,0,'ترسم کز این چمن نبری آستینِ گل','هوش مصنوعی: هراسم این است که اگر از این باغ گل برگزینی، ممکن است نتوانی سختی‌ها و مشکلات مرتبط با آن را تحمل کنی.',NULL);
INSERT INTO "verses" VALUES(1934571,2611,3,1,'بر خاک کوی دوست گذاری نمی‌کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934572,2611,3,0,'مشکین از آن نشد دمِ خُلقت که چون صبا','هوش مصنوعی: تو زمانی که در حال زندگی هستی، باید همانند نسیم صبحگاهی در کوی محبوب، با لطافت و مهربانی رفتار کنی و به دنبال جلب رضایت او باشی. این کار از آنجا نشأت می‌گیرد که تو باید در مسیر خلقت خود، به زیبایی و نیکی توجه کنی و این توجه را در رفتار و کردار خود نشان دهی.',NULL);
INSERT INTO "verses" VALUES(1934573,2611,2,1,'در کار رنگ و بویِ نگاری نمی‌کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934574,2611,2,0,'این خون که موج می‌زند اندر جگر تو را','هوش مصنوعی: این خون که در درون تو به تپش درآمده، باعث نمی‌شود که به زیبایی و جلوه‌های آن توجه کنی و به نقاشی و آفرینش بپردازی.',NULL);
INSERT INTO "verses" VALUES(1934575,2611,1,1,'بازِ ظفر به دست و شکاری نمی‌کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934576,2611,1,0,'چوگان حکم در کف و گویی نمی‌زنی','هوش مصنوعی: وقتی چوگان را در دست داری، انگار که گویی هیچ تلاشی برای پیروزی نمی‌کنی و به شکار نمی‌روی.',NULL);
INSERT INTO "verses" VALUES(1934577,2611,0,1,'اسباب جمع داری و کاری نمی‌کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934578,2611,0,0,'ای دل! به کوی عشق گذاری نمی‌کنی','هوش مصنوعی: ای دل، چرا به مسیر عشق نمی‌روی؟ تمام وسایل لازم را برای رسیدن به آن داری، اما هیچ تلاشی نمی‌کنی.',NULL);
INSERT INTO "verses" VALUES(1934579,2610,7,1,'که جهان پُر سمن و سوسنِ آزاده کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934580,2610,7,0,'ای صبا بندگی خواجه جلال‌الدین کن','هوش مصنوعی: ای نسیم، به خدمت آقای جلال‌الدین بشتاب و او را خوشحال کن، زیرا که با این کارت می‌توانی دنیایی پر از گل و گیاه آزاد و زیبا بسازی.',NULL);
INSERT INTO "verses" VALUES(1934581,2610,6,1,'ای بسا عیش که با بخت خداداده کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934582,2610,6,0,'کار خود گر به کرم بازگذاری حافظ','هوش مصنوعی: اگر بتوانی کار خود را به لطف خدا واگذار کنی، حافظ، چه بسیار لذت‌هایی که با سرنوشت خوبی که خداوند برایت تعیین کرده، می‌توانی تجربه کنی.',NULL);
INSERT INTO "verses" VALUES(1934583,2610,5,1,'مگر از نقش پراگنده ورق ساده کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934584,2610,5,0,'خاطرت کی رقم فیض پذیرد، هیهات!','هوش مصنوعی: یاد تو چه زمانی از شادی و نعمت پر خواهد شد؟ مگر اینکه از طرحی که در هم ریخته است، ورق ساده‌ای درست کنی.',NULL);
INSERT INTO "verses" VALUES(1934585,2610,4,1,'گر نگاهی سوی فرهاد دل‌افتاده کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934586,2610,4,0,'اجرها باشدت ای خسرو شیرین‌دهنان','هوش مصنوعی: ای پادشاه با سخن‌های شیرین، اگر به فرهاد که دلی پر از عشق و انتظار دارد، نگاهی بیندازی، پاداش تو بسیار خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1934587,2610,3,1,'مگر اسباب بزرگی همه آماده کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934588,2610,3,0,'تکیه بر جای بزرگان نتوان زد به گزاف','هوش مصنوعی: برای این که بتوانی در جایگاه بزرگانی قرار بگیری، نمی‌توان به سادگی و بدون دلیل مناسب به آن تکیه کرد. باید همه امکانات و شرایط لازم برای رسیدن به بزرگی را فراهم کنی.',NULL);
INSERT INTO "verses" VALUES(1934589,2610,2,1,'عیش با آدمی‌یی چند پری‌زاده کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934590,2610,2,0,'گر از آن آدمیانی که بهشتت هوس است','هوش مصنوعی: اگر تو با افرادی که آرزوی بهشت را در سر دارند، معاشرت کنی و خوش بگذرانی، به شادی و لذت برسی.',NULL);
INSERT INTO "verses" VALUES(1934591,2612,0,1,'همی گفت این معما با قرینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934592,2612,1,0,'که ای صوفی شراب آن گه شود صاف','ای صوفی! شراب (حکمت و معرفت تو) آن زمان صاف و خالص می‌شود که پس از ۴۰ روز (یا ۴۰ مرحله) ریاضت، در دل تو روشن و زلال شود.',NULL);
INSERT INTO "verses" VALUES(1934593,2612,1,1,'که در شیشه برآرد اربعینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934594,2612,2,0,'خدا زان خرقه بیزار است صد بار','خدا صد بار از آن خرقه (لباس صوفیانه) بیزار است، اگر در آستینش (درونش، پشت این ظاهرِ زاهدانه) صد بت پنهان باشد.',NULL);
INSERT INTO "verses" VALUES(1934595,2613,6,0,'باد صبحی به هوایت ز گلستان برخاست','هوش مصنوعی: باد صبحگاهی به یاد تو از گلستان می‌وزد، زیرا که تو زیباتر از گل و شاداب‌تر از گل نسرین هستی.',NULL);
INSERT INTO "verses" VALUES(1934596,2613,5,1,'عاشقان را نبود چاره به جز مسکینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934597,2613,5,0,'صبر بر جور رقیبت چه کنم گر نکنم؟','هوش مصنوعی: اگر بر ظلم رقیبم صبر نکنم، چه باید بکنم؟ عاشقان چاره‌ای جز پذیرش فقر و بی‌نیازی ندارند.',NULL);
INSERT INTO "verses" VALUES(1934598,2613,4,1,'ظاهراً مصلحت وقت در آن می‌بینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934599,2613,4,0,'عجب از لطف تو ای گل که نشستی با خار','هوش مصنوعی: عجب است که تو، ای گل، با وجود اینکه خارهایی در کنارت هستند، در این وضعیت به نظر می‌رسد که مصلحتی برای این زمان می‌بینی.',NULL);
INSERT INTO "verses" VALUES(1934600,2613,3,1,'آفرین بر تو که شایستهٔ صد چندینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934601,2613,3,0,'ادب و شرم تو را خسرو مه‌رویان کرد','هوش مصنوعی: ادب و حیا تو باعث شده که مانند شاهزاده‌های زیبا به نظر بیایی. بر تو آفرین باد که شایستهٔ این همه زیبایی و احترام هستی.',NULL);
INSERT INTO "verses" VALUES(1934602,2613,2,1,'بی‌دلی سهل بود گر نَبُوَد بی‌دینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934603,2613,2,0,'گر امانت به سلامت ببرم باکی نیست','هوش مصنوعی: اگر من امانتی را به درستی و با امانت‌داری به مقصد برسانم، نگرانی‌ای نخواهم داشت، چرا که بی‌دلی و بی‌احساسی کار ساده‌ای است، اما بی‌دینی و نداشتن ایمان مسئله‌ای جدی و نگران‌کننده است.',NULL);
INSERT INTO "verses" VALUES(1934604,2613,1,1,'که بر این چاکر دیرینه کسی نگزینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934605,2613,1,0,'به خدایی که تویی بندهٔ بگزیدهٔ او','هوش مصنوعی: خدایی که تو باشی، من بنده‌ی خاص او هستم و هیچ‌کس دیگری را بر این خادم قدیمی انتخاب نکرده است.',NULL);
INSERT INTO "verses" VALUES(1934606,2613,0,1,'ور نه هر فتنه که بینی همه از خود بینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934607,2613,0,0,'تو مگر بر لب آبی به هوس بنشینی','هوش مصنوعی: اگر به دنبال آرامش و زیبایی هستی، باید در کنار آب و صفای آن باشی؛ وگرنه هر مشکلی که ببیند، در واقع نشانه‌ای از خودت است.',NULL);
INSERT INTO "verses" VALUES(1934608,2612,10,1,'نه دانشمند را علم‌ الیقینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934609,2610,1,1,'حالیا فکر سبو کن که پر از باده کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934610,2612,10,0,'نه حافظ را حضور درس خلوت','هوش مصنوعی: حتی حافظ در محفل خلوت نمی‌تواند به طور کامل حضور داشته باشد و همچنین دانشمند نیز نمی‌تواند به علم واقعی و یقین دست یابد.',NULL);
INSERT INTO "verses" VALUES(1934611,2612,9,0,'ره میخانه بنما تا بپرسم','هوش مصنوعی: به من نشان بده که چگونه می‌توانم به میخانه بروم تا بتوانم عنایت و سرنوشت خود را از پیش بدانم.',NULL);
INSERT INTO "verses" VALUES(1934612,2612,8,1,'چه باشد گر بسازد با غمینی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934613,2612,8,0,'اگر چه رسم خوبان تندخویی‌ست','با این که شیوه‌ی زیبارویان، بدرفتاری و تندخویی با هواداران و عاشقان است، اگر زیبارویی با عاشق دل شکسته‌ به نرمی رفتار کند، چه اتفاقی می افتد؟',NULL);
INSERT INTO "verses" VALUES(1934614,2612,7,1,'چه خاصیت دهد نقش نگینی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934615,2612,7,0,'گر انگشت سلیمانی نباشد','اگر چه بهترین علم ها دست کسی بیافتد، اگر انسان بزرگی نباشد هیچ سودی برای انسان ها و انسانیت ندارد',NULL);
INSERT INTO "verses" VALUES(1934616,2612,6,1,'چراغی برکند خلوت‌نشینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934617,2612,6,0,'درون‌ها تیره شد باشد که از غیب','دل های جهانیان تیره شده ، کاش یک آدم درست پیدا بشود و جهان را به نوری روشنا کند',NULL);
INSERT INTO "verses" VALUES(1934618,2612,5,1,'نه درمان دلی نه درد دینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934619,2612,5,0,'نمی‌بینم نشاط عیش در کس','هوش مصنوعی: در هیچ‌کس شادی و سرور زندگی را نمی‌بینم؛ نه دوایی برای دل شکاسته‌ای هست و نه دردی از دین و ایمان وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1934620,2612,4,1,'اگر رحمی کنی بر خوشه‌چینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934621,2612,4,0,'ثوابت باشد ای دارای خرمن','در روزگاران پیشین، شغلی بنام خوشه‌چینی وجود داشت. آنها که دستشان تنگ بود و خرمن و مزرعه‌ای نداشتند، پشت سر دِروگر‌ها راه می‌رفتند و خوشه‌های جامانده را از زمین بر می‌داشتند و گاه صاحب مزرعه به دروگران دستور میداد که شلخته درو کنند تا چیزی هم گیر خوشه‌چین‌ها بیاید. حافظ نيز در اين بیت به این موضوع اشاره دارد.ثوابت باشد ای دارای خرمن اگر رحمی کنی بر خوشه‌چینی',NULL);
INSERT INTO "verses" VALUES(1934622,2612,3,1,'نیازی عرضه کن بر نازنینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934623,2612,3,0,'مروت گر چه نامی بی‌نشان است','هوش مصنوعی: رفتار مردانه و جوانمردی اگرچه ممکن است که در عالم نام و نشان خاصی نداشته باشد، اما با این حال لازم است که نیازهای کسی که در موقعیت حساسی قرار دارد را برآورده کنیم.',NULL);
INSERT INTO "verses" VALUES(1934624,2612,2,1,'که صد بت باشدش در آستینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934625,2612,9,1,'مَآل خویش را از پیش‌بینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934626,2613,6,1,'که تو خوش‌تر ز گل و تازه‌تر از نسرینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934627,2610,1,0,'آخرالامر گِل کوزه‌گران خواهی شد','هوش مصنوعی: در نهایت تو به خاک و گِل تبدیل خواهی شد، بنابراین اکنون به فکر پر کردن سبو از شراب باش.',NULL);
INSERT INTO "verses" VALUES(1934628,2610,0,0,'بشنو این نکته که خود را ز غم آزاده کنی','هوش مصنوعی: به این نکته توجه کن که برای رهایی از غم و اندوه، باید درون خود را آزاد کنی. اگر برای بدست آوردن روزی تلاش کنی و بر مشکلات غلبه کنی، دیگر غم و ناراحتی تو را نخواهد آزرد.',NULL);
INSERT INTO "verses" VALUES(1934629,2607,1,1,'سر گرفته چند چون خُمّ دَنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934630,2607,1,0,'دل، گشاده دار چون جامِ شراب','هوش مصنوعی: دل خود را باز و آزاد قرار بده، مانند جامی که پر از شراب است. چرا که باید زندگی را پر از شادی و سرزندگی بگذرانی، نه مانند خُم که ظرفیتش محدود است.',NULL);
INSERT INTO "verses" VALUES(1934631,2607,0,1,'تا بِدان بیخِ غم از دل برکَنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934632,2607,0,0,'نوش کن جامِ شرابِ یک منی','با تجربه کردن تمام عیار عشق الهی، از بند غصه ها و تعلقات دنیایی خلاص خواهی شد.',NULL);
INSERT INTO "verses" VALUES(1934633,2606,8,1,'کجاست فکر حکیمی و رای برهمنی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934634,2606,8,0,'مزاجِ دَهر تَبَه شد در این بلا حافظ','هوش مصنوعی: دوران زندگی با این مشکل و بلای بزرگ دچار به هم ریختگی و تنش شده است. حافظ، کجاست که فکر و نظر یک حکیم یا یک اندیشمند را در این شرایط به کار گیرد؟',NULL);
INSERT INTO "verses" VALUES(1934635,2606,7,1,'چنین عزیز نگینی به دست اهرمنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934636,2606,7,0,'به صبر کوش تو ای دل که حق رها نکند','هوش مصنوعی: ای دل، سعی کن صبر را پیشه کنی، زیرا خداوند هرگز چنین جواهر ارزشمندی را به دست شیطان رها نخواهد کرد.',NULL);
INSERT INTO "verses" VALUES(1934637,2606,6,1,'عجب که بوی گلی هست و رنگ نسترنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934638,2606,6,0,'از این سَموم که بر طَرْف بوستان بگذشت','هوش مصنوعی: از این هوای آلوده‌ای که بر باغ می‌گذرد، عجیب است که هنوز عطری از گل‌ها و رنگ نسترنی به مشام می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1934639,2606,5,1,'که کس به یاد ندارد چنین عجب زَمنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934640,2606,5,0,'ببین در آینهٔ جام، نقش‌بندیِ غیب','هوش مصنوعی: به آینه جام نگاه کن و ببین که چه تصاویری از عالم غیب در آن نقش بسته است، که هیچ‌کس یادش نمی‌آید چنین زمان شگفت‌انگیزی وجود داشته باشد.',NULL);
INSERT INTO "verses" VALUES(1934641,2606,4,1,'در این چمن که گلی بوده است یا سَمنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934642,2606,4,0,'ز تندباد حوادث نمی‌توان دیدن','هوش مصنوعی: در این دنیای پرفراز و نشیب، نمی‌توان به آسانی تشخیص داد که آیا در گذشته از گل‌ها و زیبایی‌ها بوده یا از علف‌های خشک و بی‌ارزش.',NULL);
INSERT INTO "verses" VALUES(1934643,2606,3,1,'به زهدِ همچو تویی، یا به فسق همچو منی',NULL,NULL);
INSERT INTO "verses" VALUES(1934644,2606,3,0,'بیا که رونق این کارخانه کم نشود','هوش مصنوعی: بیا تا این کارخانه همیشه پررونق باقی بماند، نه به زهد و تقوای تو که شاید فشار زیادی به ما بیاورد، و نه به فسق و نافرمانی من که می‌تواند مشکلاتی ایجاد کند.',NULL);
INSERT INTO "verses" VALUES(1934645,2606,2,1,'فروخت یوسف مصری به کمترین ثمنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934646,2606,2,0,'هر آن که کنج قناعت به گنج دنیا داد','هر کسی که به رضایت و قناعت از زندگی را به خاطر مال دنیا از دست داد، مانند کسی است که ارزش‌های بزرگ را به خاطر چیزهای کم و ناچیز از دست می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1934647,2606,1,1,'اگر چه در پِی‌ام افتند هر دم انجمنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934648,2606,1,0,'من این مقام به دنیا و آخرت ندهم','هوش مصنوعی: من هیچ‌گاه این جایگاه را به دنیا و آخرت نخواهم داد، حتی اگر هر لحظه گروهی به دنبال من بیفتند.',NULL);
INSERT INTO "verses" VALUES(1934649,2606,0,1,'فراغتی و کتابی و گوشهٔ چمنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934650,2606,0,0,'دو یار زیرک و از بادهٔ کهن دو منی','هوش مصنوعی: دو دوست عاقل داریم و بادهٔ قدیمی، در کنار هم آرامش و مطالعهٔ کتابی و نشستن در گوشه‌ای از چمن را تجربه می‌کنیم.',NULL);
INSERT INTO "verses" VALUES(1934651,2605,6,1,'حدیث عشق بیان کن، بدان زبان که تو دانی',NULL,NULL);
INSERT INTO "verses" VALUES(1934652,2605,6,0,'یکی است تُرکی و تازی، در این معامله حافظ','هوش مصنوعی: یک زبان و دو فرهنگ وجود دارد، پس در این زمینه حافظ داستان عشق را روایت کن، به زبانی که تو به خوبی می‌فهمی.',NULL);
INSERT INTO "verses" VALUES(1934653,2605,5,1,'دقیقه‌ای است نگارا در آن میان که تو دانی',NULL,NULL);
INSERT INTO "verses" VALUES(1934654,2605,5,0,'امید در کمرِ زَرکِشَت چگونه ببندم؟','هوش مصنوعی: چگونه می‌توانم به امیدواری‌ام در قابِ زرین تو ادامه دهم؟ لحظه‌ای است، ای محبوب، که تو به خوبی از آن آگاهی داری.',NULL);
INSERT INTO "verses" VALUES(1934655,2605,4,1,'اسیر خویش گرفتی، بکُش چنان که تو دانی',NULL,NULL);
INSERT INTO "verses" VALUES(1934656,2605,4,0,'خیال تیغ تو با ما، حدیث تشنه و آب است','هوش مصنوعی: خاطره و تصور از تیغ تو در ذهن ما مانند داستان تشنگی و آب است. تو ما را در بند خودت گرفته‌ای، بکش ما را به همان صورتی که خودت می‌دانی.',NULL);
INSERT INTO "verses" VALUES(1934657,2605,3,1,'تو هم ز روی کرامت، چنان بخوان که تو دانی',NULL,NULL);
INSERT INTO "verses" VALUES(1934658,2607,2,0,'چون ز جام بی‌خودی رطلی کشی','هوش مصنوعی: وقتی از می‌خانه به شوق و حال خوب مشغول نوشیدن می‌شوی، کمتر به خودت می‌نازی و به خودبالا بردن متوسل نمی‌شوی.',NULL);
INSERT INTO "verses" VALUES(1934659,2607,2,1,'کم زنی از خویشتن لافِ منی',NULL,NULL);
INSERT INTO "verses" VALUES(1934660,2607,3,0,'سنگسان شو، در قدم نی همچو آب','هوش مصنوعی: خود را مانند سنگ محکم و استوار کن، نه مانند آب نرم و بی‌ثبات. در زندگی باید رنگین و متنوع باشی، اما در عین حال پایدار و مطمئن.',NULL);
INSERT INTO "verses" VALUES(1934661,2607,3,1,'جمله رنگ‌آمیزی و تَردامنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934662,2609,6,1,'که دعایی ز سر صدق جز آن جا نکنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934663,2609,6,0,'حافظا سجده به ابروی چو محرابش بر','ای حافظ دعاهایت را به ابروی یار که شبیه محراب است ببر که تو هیچ جا به جز نزد یار از سر صداقت دعا نمی کنی',NULL);
INSERT INTO "verses" VALUES(1934664,2609,5,1,'از خدا جز می و معشوق تمنا نکنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934665,2609,5,0,'بر تو گر جلوه کند شاهد ما ای زاهد','هوش مصنوعی: اگر معشوق و زیبایی به تو نمایش خود را نشان دهد، ای زاهد، دیگر نباید از خدا چیزی جز شراب و محبوب بخواهی.',NULL);
INSERT INTO "verses" VALUES(1934666,2609,4,1,'قول صاحب غرضان است تو آن‌ها نکنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934667,2609,4,0,'نقل هر جور که از خلق کریمت کردند','هوش مصنوعی: هرکس به نحوی درباره تو سخن گفته و نظراتی بیان کرده، این نظرات بیشتر بر اساس منافع خودشان است. تو باید به این گفته‌ها توجه نکنید و به آنها اهمیت ندهی.',NULL);
INSERT INTO "verses" VALUES(1934668,2609,3,1,'به تفرج گذری بر لب دریا نکنی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934669,2609,3,0,'دیدهٔ ما چو به امید تو دریاست، چرا','هوش مصنوعی: چشم ما به انتظار تو مانند دریا وسیع و عمیق است، پس چرا تو برای کمی آرامش و گشت و گذار کنار دریا نمی‌آیی؟',NULL);
INSERT INTO "verses" VALUES(1934670,2609,2,1,'شرط انصاف نباشد که مداوا نکنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934671,2609,2,0,'رنج ما را که توان برد به یک گوشهٔ چشم','درد هایم را میتوانی با گوشه چشمی پایان دهی، این شرط انصاف نیست ک این درمان را از من دریغ کنی و من را مداوا نکنی',NULL);
INSERT INTO "verses" VALUES(1934672,2609,1,1,'قصد این قوم خطا باشد هان تا نکنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934673,2609,1,0,'دردمندان بلا زهر هلاهل دارند','هوش مصنوعی: دردمندان در خطر و مشکلاتی قرار دارند و این قوم ممکن است دچار اشتباهاتی شوند. پس مراقب باش که خودت را درگیر نکنی.',NULL);
INSERT INTO "verses" VALUES(1934674,2609,0,1,'سود و سرمایه بسوزی و محابا نکنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934675,2609,0,0,'ای که در کشتن ما هیچ مدارا نکنی','هوش مصنوعی: ای کسی که در به قتل رساندن ما هیچ رحم و ملاحظه‌ای نداری و برای رسیدن به سود و سرمایه‌ات، هیچ تردیدی نمی‌کنی.',NULL);
INSERT INTO "verses" VALUES(1934676,2610,0,1,'خون خوری گر طلب روزی ننهاده کنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934677,2608,5,1,'تا بشنوی ز صوت مغنی «هو الغنی»',NULL,NULL);
INSERT INTO "verses" VALUES(1934678,2608,4,1,'«خوش بگذران و بشنو از این پیرِ منحنی»',NULL,NULL);
INSERT INTO "verses" VALUES(1934679,2608,4,0,'مِی ده که سر به گوش من آورد چنگ و گفت','هوش مصنوعی: مشروب بنوش که صدای چنگ در گوشم طنین‌انداز شد و به من گفت: «خوب زندگی کن و از این پیر با تجربه حرف‌هایت را بشنو».',NULL);
INSERT INTO "verses" VALUES(1934680,2608,3,1,'مطرب نگاه دار همین ره که می‌زنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934681,2608,3,0,'ساقی به دست باش که غم در کمین ماست','هوش مصنوعی: ای ساقی، مراقب باش که غم به ما نزدیک است، مطرب هم همچنان این نغمه را ادامه بده و راهی که در پیش گرفته‌ای را حفظ کن.',NULL);
INSERT INTO "verses" VALUES(1934682,2608,2,1,'در کار یار باش که کاری‌ست کردنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934683,2608,2,0,'خونِ پیاله خور که حلال است خون او','هوش مصنوعی: برای دلخوشی معشوق، به خاطر او پیاله‌ای پر از شراب بنوش، که این امر جایز است. با عشق و وفاداری نسبت به او، به کارهایی بپرداز که باید انجام شوند.',NULL);
INSERT INTO "verses" VALUES(1934684,2608,1,1,'می تا خلاص بخشدم از مایی و منی',NULL,NULL);
INSERT INTO "verses" VALUES(1934685,2608,1,0,'در بحر مایی و منی افتاده‌ام، بیار','هوش مصنوعی: من در دریاى وجود تو و خودم غرق شده‌ام، بیا شراب بیاور تا از این حالت رها شوم.',NULL);
INSERT INTO "verses" VALUES(1934686,2608,0,1,'برگ صبوح ساز و بده جام یک منی',NULL,NULL);
INSERT INTO "verses" VALUES(1934687,2608,0,0,'صبح است و ژاله می‌چکد از ابر بهمنی','هوش مصنوعی: صبح شده و شبنم از ابرهای سنگین می‌چکد. بیایید حال و هوای خوشی درست کنیم و یک کاسه نوشیدنی به من بدهید.',NULL);
INSERT INTO "verses" VALUES(1934688,2607,5,1,'خویشتن در پای معشوق افکنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934689,2607,5,0,'خیز و جهدی کن چو حافظ تا مگر','هوش مصنوعی: برخیز و تلاشی کن مانند حافظ تا خود را در راه معشوق تقدیم کنی.',NULL);
INSERT INTO "verses" VALUES(1934690,2607,4,1,'گردن سالوس و تقوا بشکنی',NULL,NULL);
INSERT INTO "verses" VALUES(1934691,2607,4,0,'دل به مِی دربند تا مردانه‌وار','هوش مصنوعی: دل خود را به عشق مشغول کن تا بتوانی به طور قاطع و شجاعانه از ظاهرسازی و ریاکاری دوری کنی و حقیقت را در آغوش بگیری.',NULL);
INSERT INTO "verses" VALUES(1934692,2608,5,0,'ساقی به بی‌نیازی رندان که می بده','هوش مصنوعی: ای ساقی، برای آنکه رندها به نیازی نیفتند، شراب بده تا صدای خواننده را بشنوند که می‌گوید او بی‌نیاز است.',NULL);
INSERT INTO "verses" VALUES(1934693,2605,2,1,'ز لعل روح‌فزایش ببخش آن که تو دانی',NULL,NULL);
INSERT INTO "verses" VALUES(1934694,2613,7,0,'شیشه‌بازیِ سِرشکم نگری از چپ و راست','اشک های چشمم که همچون شیشه می‌درخشند را از چپ و راست می‌بینی اگر در این منظری که چشمانم عاشقانه چشم بسته لحظه‌ای بنشینی',NULL);
INSERT INTO "verses" VALUES(1934695,2613,8,0,'سخنی بی‌غرض از بندهٔ مخلص بشنو','هوش مصنوعی: ای کسی که توجه به حقیقت‌های بزرگ داری، سخنی ساده و بدون نیت خاص از من، کسی که کاملاً مخلص هستم، بشنو.',NULL);
INSERT INTO "verses" VALUES(1934696,2618,8,0,'ساقی بیار آبی از چشمهٔ خرابات','هوش مصنوعی: ای ساقی، آب از چشمهٔ خرابات بیاور تا از خودپسندی و تکبر خانقاهی خود را پاک کنیم.',NULL);
INSERT INTO "verses" VALUES(1934697,2618,7,1,'و ای دولت تو ایمن از وَصمت تباهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934698,2618,7,0,'ای عنصر تو مخلوق از کیمیای عزّت','هوش مصنوعی: ای وجود تو به واسطه‌ی کیمیای عظمت خلق شده‌ای و ای کشور (حاکمیت) تو از عیب و نقص ایمن است.',NULL);
INSERT INTO "verses" VALUES(1934699,2618,6,1,'تعویذ جان‌فزایی افسون عمرکاهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934700,2618,6,0,'کلک تو خوش نویسد در شأن یار و اغیار','هوش مصنوعی: نقش و نگار تو به طرز زیبایی نوشته می‌شود، هم برای یارت و هم برای دیگران. این هنر تو مانند یک تعویذ است که جان را زنده می‌کند و عمر را به تأخیر می‌اندازد.',NULL);
INSERT INTO "verses" VALUES(1934701,2618,5,1,'تنها جهان بگیرد بی منّت سپاهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934702,2618,5,0,'تیغی که آسمانش از فیض خود دهد آب','شمشیری که بخت و تقدیرو اراده‌ی آسمانی آن را آبدیده کند (آبکاری فلزات برای استحکام آن) به دلیل اینکه مقدر شده پیروزمند باشد به تنهایی می‌تواند دنیا را بگیرد. یعنی آنچه اصل و شرط کار است فیض و مدد الهی است نه تلاش فردی، هرچند تلاش شخصی هم لازم است',NULL);
INSERT INTO "verses" VALUES(1934703,2618,4,1,'مرغان قاف دانند آیین پادشاهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934704,2618,4,0,'باز ار چه گاه گاهی بر سر نهد کلاهی','هوش مصنوعی: اگرچه گاهی اوقات بر سر کسی کلاهی می‌گذارد، اما پرندگان قاف می‌دانند که این کار نشانه‌ای از پادشاهی و قدرت است.',NULL);
INSERT INTO "verses" VALUES(1934705,2618,3,1,'بر عقل و دانش او خندند مرغ و ماهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934706,2618,3,0,'در حکمت سلیمان هر کس که شک نماید','هوش مصنوعی: در حکمت سلیمان، اگر کسی به عقل و دانایی خود شک کند، ماهی‌ها و مرغ‌ها به او می‌خندند.',NULL);
INSERT INTO "verses" VALUES(1934707,2618,2,1,'ملک آن توست و خاتم فرمای هر چه خواهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934708,2618,2,0,'بر اهرمن نتابد انوار اسم اعظم','هوش مصنوعی: نور اسم اعظم بر روی موجودات پلید تابیده نمی‌شود. پادشاهی و اقتدار، متعلق به توست و تو می‌توانی هر آنچه که می‌خواهی را فرمان دهی.',NULL);
INSERT INTO "verses" VALUES(1934709,2618,1,1,'صد چشمه آب حیوان از قطرهٔ سیاهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934710,2618,1,0,'کلک تو بارک الله بر ملک و دین گشاده','هوش مصنوعی: شما با هنر و زیبایی خود بر عالم و مذهب تاثیر مثبت گذاشته‌اید، به‌طوری‌که از یک نقطه کوچک، منابع و نعمت‌های فراوانی برای زندگی و حیات به وجود آمده است.',NULL);
INSERT INTO "verses" VALUES(1934711,2618,0,1,'در فکرت تو پنهان صد حکمت الهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934712,2618,0,0,'ای در رخ تو پیدا انوار پادشاهی','هوش مصنوعی: ای نور سلطنت در چهره تو نمایان است و در اندیشه‌ات هزاران حکمت الهی نهفته است.',NULL);
INSERT INTO "verses" VALUES(1934713,2617,8,1,'عملت چیست که فردوس بَرین می‌خواهی‌؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934714,2617,8,0,'حافظِ خام‌طمع! شرمی از این قصّه بدار','ای حافظ خام‌طمع و خوش‌خیال، دست از این آرزوهای بزرگ بردار؛ چه کرده‌ای که بهشت برین را توقع داری؟',NULL);
INSERT INTO "verses" VALUES(1934715,2617,7,1,'مسند خواجگی و مجلس تورانشاهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934716,2617,7,0,'تو دم فقر ندانی زدن از دست مده','تو افسون و دم فقر را نمی‌دانی و به‌آن مقام نرسیده‌ای پس بجای آن مسند و مجلس توران‌شاهی را دریاب.',NULL);
INSERT INTO "verses" VALUES(1934717,2617,6,1,'کمترین ملک تو از ماه بود تا ماهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934718,2617,6,0,'اگرت سلطنت فقر ببخشند، ای دل!','اگر به‌تو مقام بلندمرتبه فقر را ببخشند و بدهند؛ کمترین فرمان‌روایی تو و کمترین مُلک تو از اوج آسمان تا قعر دریاست.',NULL);
INSERT INTO "verses" VALUES(1934719,2617,5,1,'ظلمات است، بترس از خطر گمراهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934720,2617,5,0,'قطع این مرحله بی‌همرهی خضر مکن','این راه را بی‌خضر مپیما که راهی است تاریک و ظلمات؛ و از گمراهی بیم داشته باش.',NULL);
INSERT INTO "verses" VALUES(1934721,2617,4,1,'به فلک بَر شد و دیوار بدین کوتاهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934722,2617,4,0,'سَر ما و در میخانه که طرف بامش','سر نیاز ما بر در میخانه است که با دیوار بدان کوتاهی از فلک بلند‌تر است.',NULL);
INSERT INTO "verses" VALUES(1934723,2617,3,1,'دست قدرت نگر و منصب صاحب‌جاهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934724,2617,3,0,'خشت، زیر سر و بر تارَک هفت‌اختر پای','در زیر سر خشتی گِلین دارند و اما قدم‌شان بر هفت فلک است؛ مقام و قدرت‌شان را بنگر و ارزش آنها را.',NULL);
INSERT INTO "verses" VALUES(1934725,2618,8,1,'تا خرقه‌ها بشوییم از عُجب خانقاهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934726,2618,9,0,'عمری‌ست پادشاها کز می تهی‌ست جامم','هوش مصنوعی: سال‌هاست که من از شراب خالی‌ام و اکنون به خاطر درخواست بنده‌ای، نزد قاضی شهادت می‌دهم.',NULL);
INSERT INTO "verses" VALUES(1934727,2618,9,1,'اینک زِ بنده دعوی، وَز محتسب گواهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934728,2618,10,0,'گَر پرتوی زِ تیغت، بر کان و معدن افتد','هوش مصنوعی: اگر پرتو تیغ تو بر سنگ و معدن تابیده شود، یاقوت سرخ نیز رنگ کاهی به خود می‌گیرد.',NULL);
INSERT INTO "verses" VALUES(1934729,2620,1,0,'امید هست که منشورِ عشق‌بازیِ من','هوش مصنوعی: امید دارم که سبک و سیاق عشق ورزی من به قدری زیبا باشد که از زیبایی ابروان تو الهام بگیرد و به اوج کمال و معروفیت برسد.',NULL);
INSERT INTO "verses" VALUES(1934730,2620,0,1,'خیالِ سبزخطی، نقش بسته‌ام جایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934731,2620,0,0,'به چشم کرده‌ام ابرویِ ماه‌سیمایی','هوش مصنوعی: در نگاه من، ابروی زیبای ماه نقش بسته است و خیالی سبز و دلپذیر را در ذهنم مجسم کرده‌ام.',NULL);
INSERT INTO "verses" VALUES(1934732,2619,9,1,'آه اگر از پی امروز بُوَد فردایی»',NULL,NULL);
INSERT INTO "verses" VALUES(1934733,2619,9,0,'«گر مسلمانی از این است که حافظ دارد','این گونه که حافظ و دیگران خود را مسلمان می‌پندارند، فردا اگر قیامتی باشد وای به حال همه آن هاست',NULL);
INSERT INTO "verses" VALUES(1934734,2619,8,1,'بر درِ میکده‌ای، با دَف و نِی، ترسایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934735,2619,8,0,'این حدیثم چه خوش آمد که سحرگه می‌گفت','از این حدیث خیلی‌خوشم آمد که سحرگاه ترسایی بر در میکده‌ای با دف و نی می‌خواند:',NULL);
INSERT INTO "verses" VALUES(1934736,2619,7,1,'کَز وِی و جامِ مِی‌ام نیست به کَس پروایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934737,2619,7,0,'سخن غیر مگو با منِ معشوقه‌پرست','هوش مصنوعی: با من که عاشق معشوقه‌ام، سخن بیهوده نگو. من نسبت به کسی غیر از او و جام می‌ام هیچ اهمیتی قائل نیستم.',NULL);
INSERT INTO "verses" VALUES(1934738,2619,6,1,'گشت هر گوشه چشم از غمِ دل، دریایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934739,2619,6,0,'کشتی باده بیاور که مرا بی‌ رخِ دوست','هوش مصنوعی: کشتی شراب بیاور، زیرا بدون دیدن چهره دوست، هر گوشه از چشمم از درد دلی به اندازه یک دریا پر شده است.',NULL);
INSERT INTO "verses" VALUES(1934740,2619,5,1,'در کنارم بنشانند سَهی‌بالایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934741,2619,5,0,'جوی‌ها بسته‌ام از دیده به دامان که مگر','هوش مصنوعی: چشم‌هایم را از دیدن دیگران فروبسته‌ام و در آرزوی آنم که شاید مرا در کنار خود بنشانند.',NULL);
INSERT INTO "verses" VALUES(1934742,2619,4,1,'وَرنَه پروانه ندارد به سخن، پروایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934743,2617,2,1,'که سِتانند و دهند افسر شاهنشاهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934744,2619,4,0,'شرحِ این قصه مگر شمع بَرآرَد به زبان','هوش مصنوعی: این داستان را فقط شمع می‌تواند با کلامش توضیح دهد، وگرنه پروانه‌ای که به شمع عشق می‌ورزد، نمی‌تواند به هنگام سخن گفتن، حس خود را بیان کند.',NULL);
INSERT INTO "verses" VALUES(1934745,2619,3,0,'نرگس اَر لاف زد از شیوه چشمِ تو مَرَنج','هوش مصنوعی: اگر نرگس دربارهٔ زیبایی چشمان تو لاف و ادعا کند، نگران نباش، چون اهل دقت و نظر هیچ‌گاه از پی کسی که نابیناست، نخواهند رفت.',NULL);
INSERT INTO "verses" VALUES(1934746,2619,2,1,'که دگَر مِی نخورم بی‌ رخِ بزم‌آرایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934747,2619,2,0,'کرده‌ام توبه به دست صنم باده‌فروش','هوش مصنوعی: من به خاطر زیبایی محبوبم از نوشیدن شراب توبه کرده‌ام و دیگر بدون حضور او به می‌گساری نخواهم پرداخت.',NULL);
INSERT INTO "verses" VALUES(1934748,2619,1,1,'از خدا می‌طلبم صحبت روشن‌رایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934749,2619,1,0,'دل که آیینه شاهی‌ست غباری دارد','هوش مصنوعی: دل مانند آینه‌ای استکه به خوبی نمی‌تواند حقیقت را نشان دهد و در حقیقت تحت تاثیر غبارهای دنیا قرار دارد. من از خدا می‌خواهم که روشنایی و آگاهی به من ببخشد تا بتوانم حقیقت را بهتر ببینم.',NULL);
INSERT INTO "verses" VALUES(1934750,2619,0,1,'خرقه جایی گرو باده و دفْتر جایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934751,2619,0,0,'در همه دِیر مغان نیست چو من شیدایی','در تمام میخانه‌ها و دیر‌های مغان عاشق و شیدایی مثل من یافت نمی‌شود در یکی خرقه‌ام را گرو گذاشته‌ام و در دیگری کتابم را.',NULL);
INSERT INTO "verses" VALUES(1934752,2618,13,1,'رنجش ز بخت منما بازآ به عذرخواهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934753,2618,13,0,'حافظ چو پادشاهت گهگاه می‌برد نام','هوش مصنوعی: حافظ می‌گوید: وقتی که پادشاه تو گاهی از من نام می‌برد و مرا به زحمت می‌اندازد، لطفاً دوباره به خاطر من عذرخواهی کن و گذشته‌ها را فراموش کن.',NULL);
INSERT INTO "verses" VALUES(1934754,2618,12,1,'ما را چگونه زیبد دعویِ بی‌گناهی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934755,2618,12,0,'جایی که برق عصیان بر آدم صفی زد','هوش مصنوعی: در جایی که نافرمانی و عصیان بر انسان خوب و پاک‌نهاد عارض شد، چگونه می‌توانیم ادعای بی‌گناهی کنیم؟',NULL);
INSERT INTO "verses" VALUES(1934756,2618,11,1,'گر حال بنده پرسی از باد صبحگاهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934757,2618,11,0,'دانم دلت ببخشد بر عجز شب‌نشینان','هوش مصنوعی: می‌دانم که قلبت به راحتی می‌تواند بر ضعف و ناتوانی کسانی که شب‌زنده‌داری می‌کنند، رحم کند؛ اما اگر حال من را از نسیم صبح بپرسی، چه خواهد شد؟',NULL);
INSERT INTO "verses" VALUES(1934758,2618,10,1,'یاقوت سرخ‌رو را بخشند رنگ کاهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934759,2619,3,1,'نروند اهل نظر از پی نابینایی',NULL,NULL);
INSERT INTO "verses" VALUES(1934760,2613,7,1,'گر بر این منظر بینش نفسی بنشینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934761,2617,2,0,'بر در میکده، رندان قلندر باشند','درگاه میکده جای رندان قلندر و زیرکان پاک‌باز است که در آنجا تاج شاهی می‌گیرند و می‌بخشند.',NULL);
INSERT INTO "verses" VALUES(1934762,2617,1,0,'همچو جَم جرعهٔ ما کَش که ز سِرّ دو جهان','همچون جمشید از باده ما بنوش تا جام جهان‌بین سرّ دو جهان را بر تو آشکار کند.',NULL);
INSERT INTO "verses" VALUES(1934763,2615,2,1,'تا خواجه مِی خورَد، به غزل‌های پهلوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934764,2615,2,0,'مرغان باغ، قافیه‌سنجند و بذله‌گوی','هوش مصنوعی: پرندگان در باغ، شعر و سرود می‌سرایند و شوخ‌طبعی می‌کنند، تا وقتی که صاحب مجلس شراب می‌نوشد و غزل‌های زیبایی می‌خواند.',NULL);
INSERT INTO "verses" VALUES(1934765,2615,1,1,'تا از درخت، نکتهٔ توحید بشنوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934766,2615,1,0,'یعنی بیا، که آتشِ موسی، نمودْ گُل','هوش مصنوعی: بیا تا مثل شعله‌های آتش موسی، گل زیبایی نمایان شود و از درخت هستی، حقیقت یکتایی را بشنوی.',NULL);
INSERT INTO "verses" VALUES(1934767,2615,0,1,'می‌خوانْد دوش، درسِ مقاماتِ معنوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934768,2615,0,0,'بلبل، ز شاخِ سرو، به گلبانگِ پهلوی','هوش مصنوعی: بلبل دیشب از درخت سرو با صدای بلند و زیبا می‌خواند و درس‌های معنوی را آموزش می‌داد.',NULL);
INSERT INTO "verses" VALUES(1934769,2614,7,1,'آفرین بر نفست باد که خوش بردی بوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934770,2614,7,0,'گفتی از حافظِ ما بوی ریا می‌آید','هوش مصنوعی: گفتی که از حافظ ما بوی نفاق و تزویر به مشام می‌رسد، اما درود بر تو که با هوش و زکاوتت این بوی تلخ را به خوبی تشخیص دادی.',NULL);
INSERT INTO "verses" VALUES(1934771,2614,6,1,'خواجه تقصیر مفرما گل توفیق ببوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934772,2614,6,0,'گوش بگشای که بلبل به فغان می‌گوید','هوش مصنوعی: گوش کن که بلبل در حال گلایه است و از تو می‌خواهد که تقصیرات را نپذیری، چرا که گل توفیق از بوی خوش توست.',NULL);
INSERT INTO "verses" VALUES(1934773,2614,5,1,'ور نه هرگز گل و نسرین ندمد ز آهن و روی',NULL,NULL);
INSERT INTO "verses" VALUES(1934774,2614,5,0,'روی جانان طلبی، آینه را قابل ساز','هوش مصنوعی: اگر به دنبال زیبایی و حقیقت هستی، باید خودت را شایسته‌اش کنی. در غیر این صورت، هرگز نمی‌توانی از زیبایی‌ها و لطافت‌های زندگی بهره‌مند شوی.',NULL);
INSERT INTO "verses" VALUES(1934775,2614,4,1,'بیخ نیکی بنشان و ره تحقیق بجوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934776,2614,4,0,'شکر آن را که دگربار رسیدی به بهار','هوش مصنوعی: خوشحالی از این که دوباره بهاری را تجربه کردی، خوب است. حالا باید کارهای نیکو را آغاز کنی و در پی حقیقت و دانش باشی.',NULL);
INSERT INTO "verses" VALUES(1934777,2614,3,1,'«از در عیش درآ و به ره عیب مپوی»',NULL,NULL);
INSERT INTO "verses" VALUES(1934778,2614,3,0,'دو نصیحت کنمت بشنو و صد گنج ببر','هوش مصنوعی: دو نکته را به تو توصیه می‌کنم که گوش کن و از آن بهره‌مند شو: اول اینکه از در شادمانی وارد شو و دوم اینکه به دنبال عیب‌جویی نرو.',NULL);
INSERT INTO "verses" VALUES(1934779,2614,2,1,'ای جهان‌دیده! ثباتِ قدم از سفله مجوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934780,2614,2,0,'سفله‌طبع است جهان، بر کَرَمَش تکیه مکن','هوش مصنوعی: دنیا افرادی بی‌ارزش و پست دارد، بنابراین به سخاوت و بزرگواری آن تکیه نکن. از افراد پست و بی‌مقدار نباید انتظار ثبات و استقامت داشته باشی.',NULL);
INSERT INTO "verses" VALUES(1934781,2614,1,1,'دلق آلودهٔ صوفی به می ناب بشوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934782,2614,1,0,'بوی یک‌رنگی از این نقش نمی‌آید خیز','هوش مصنوعی: اگر در این تصویر، رنگ وحدت و یکدلی حس نمی‌شود، پس بهتر است لباس ناپاک درویش را کنار بگذاری و با شراب خالص و ناب، خود را پاکسازی کنی.',NULL);
INSERT INTO "verses" VALUES(1934783,2614,0,1,'من نگویم چه کن ار اهل دلی خود تو بگوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934784,2614,0,0,'ساقیا سایهٔ ابر است و بهار و لب جوی','هوش مصنوعی: ای ساقی، سایه‌ی ابر، بهار و کناره‌ی جوی را می‌بینم، اما از من نپرس چه کار کنم؛ خودت بگو که اهل دل چه باید بکند.',NULL);
INSERT INTO "verses" VALUES(1934785,2613,11,1,'لایق بندگی خواجه جلال‌الدینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934786,2613,11,0,'تو بدین نازکی و سرکشی ای شمع چگل','هوش مصنوعی: تو ای شمع زیبای نازک و سرکش، شایسته‌ترین فرد برای خدمت به آقای جلال‌الدین هستی.',NULL);
INSERT INTO "verses" VALUES(1934787,2613,10,1,'بَلَغَ الطّاقَةَ یا مُقلَةَ عَینی بِیني',NULL,NULL);
INSERT INTO "verses" VALUES(1934788,2613,10,0,'سیل این اشک روان صبر و دل حافظ برد','این اشک‌های روان که همچون سیل هستند، ای نور دیده‌ام جدایی، توانم را رد کرده است. (از توانم خارج شده)',NULL);
INSERT INTO "verses" VALUES(1934789,2613,9,1,'بهتر آن است که با مردمِ بد ننشینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934790,2613,9,0,'نازنینی چو تو پاکیزه‌دل و پاک‌نهاد','هوش مصنوعی: بهتر است کسی که دل پاک و نیت خوبی دارد، با افراد بد و ناپاک هم‌نشینی نکند.',NULL);
INSERT INTO "verses" VALUES(1934791,2613,8,1,'ای که منظور بزرگان حقیقت بینی',NULL,NULL);
INSERT INTO "verses" VALUES(1934792,2615,3,0,'جمشید، جز حکایتِ جام، از جهان نَبُرد','برای جمشید (که شاه جهان بود) جز حکایت جام از این زندگی و دنیا چیزی نماند، پس تو نیز عبرت بگیر و بیاموز که به اسباب دنیا دل نبندی.',NULL);
INSERT INTO "verses" VALUES(1934793,2615,3,1,'زنهار! دل مَبَند، بر اسبابِ دنیوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934794,2615,4,0,'این قصّهٔ عجب شِنو از بختِ واژگون','هوش مصنوعی: این داستان عجیب را بشنو که بختِ نامساعد ما باعث شد یار ما را با نفس‌های عیسوی‌اش به شدت تحت تاثیر قرار دهد.',NULL);
INSERT INTO "verses" VALUES(1934795,2615,4,1,'ما را بِکُشت یار، به انفاسِ عیسَوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934796,2617,0,1,'گفت: باز آی که دیرینهٔ این درگاهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934797,2617,0,0,'سَحرم هاتف میخانه به دولت‌خواهی','سحرگاه که میخواران میخانه را ترک می‌کنند هاتف میخانه به‌قصد دولت‌خواهی و نیکی به من گفت بازآ که تو دیرینه و پیشکسوت این درگاه هستی.',NULL);
INSERT INTO "verses" VALUES(1934798,2616,9,1,'باید که خاک درگه اهل هنر شوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934799,2616,9,0,'گر در سرت هوای وصال است حافظا','هوش مصنوعی: اگر در دل‌ات آرزوی رسیدن به معشوق است، ای حافظ، باید humble و فروتن باشی و خود را به خاک پای اهل هنر بسازی.',NULL);
INSERT INTO "verses" VALUES(1934800,2616,8,1,'در دل مدار هیچ که زیر و زبر شوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934801,2616,8,0,'بنیاد هستی تو چو زیر و زبر شود','هوش مصنوعی: اگر پایه و اساس وجودت دستخوش تغییر و تزلزل شود، در دل خود ناراحت نباش که ممکن است زیر و زبر شوی.',NULL);
INSERT INTO "verses" VALUES(1934802,2616,7,1,'زین پس شکی نماند که صاحب‌نظر شوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934803,2616,7,0,'وجه خدا اگر شودت منظر نظر','هوش مصنوعی: اگر چهره خداوند بر تو نمایان شود، دیگر هیچ شکی نخواهد بود که تو به دیدگاه‌های عمیق و عالمانه‌ای دست پیدا خواهی کرد.',NULL);
INSERT INTO "verses" VALUES(1934804,2616,6,1,'در راه ذوالجلال چو بی پا و سر شوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934805,2616,6,0,'از پای تا سرت همه نور خدا شود','هوش مصنوعی: از سر تا پای تو باید سرشار از نور الهی باشد، چنانچه در مسیر عظمت و بزرگی خداوند حرکت کنی، حتی اگر بدون پا و سر باشی.',NULL);
INSERT INTO "verses" VALUES(1934806,2616,5,1,'کز آب هفت بحر به یک موی تر شوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934807,2616,5,0,'یک دم غریق بحر خدا شو گمان مبر','هوش مصنوعی: لحظه‌ای در عمق وجود و رحمت خداوند غوطه‌ور شو. فکر نکن که از آب دریاهای فراوان می‌توانی با یک قطره کوچک سیراب شوی.',NULL);
INSERT INTO "verses" VALUES(1934808,2616,4,1,'بالله کز آفتاب فلک خوب‌تر شوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934809,2616,4,0,'گر نور عشق حق به دل و جانت اوفتد','هوش مصنوعی: اگر نور عشق خداوند به دل و جانت بتابد، به خدا قسم از آفتاب آسمان زیباتر خواهی شد.',NULL);
INSERT INTO "verses" VALUES(1934810,2617,1,1,'پرتو جام جهان‌بین دهدَت آگاهی',NULL,NULL);
INSERT INTO "verses" VALUES(1934811,2616,3,1,'آن گه رسی به خویش که بی خواب و خور شوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934812,2616,2,1,'تا کیمیای عشق بیابی و زر شوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934813,2616,2,0,'دست از مسِ وجود چو مردان ره بشوی','هوش مصنوعی: از خودخواهی و تعلقات دنیوی دست بردار، تا به بهشتی از عشق برسی و به ارزش واقعی خود پی ببری.',NULL);
INSERT INTO "verses" VALUES(1934814,2616,1,1,'هان ای پسر بکوش که روزی پدر شوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934815,2616,1,0,'در مکتب حقایق پیش ادیب عشق','هوش مصنوعی: در دنیای حقایق و دانش، ای پسر، تلاش کن تا به مقام و شناختی دست یابی که روزی بتوانی به عنوان پدر و راهنما به دیگران آموزش بدهی.',NULL);
INSERT INTO "verses" VALUES(1934816,2616,0,1,'تا راهرو نباشی کی راهبر شوی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934817,2616,0,0,'ای بی‌خبر بکوش که صاحب‌خبر شوی','هوش مصنوعی: اگر بی‌خبر هستی، تلاش کن که آگاهی به دست آوری و از حال و روز دیگران باخبر شوی. چون اگر فقط مسافر هستی و راه را نمی‌شناسی، چگونه می‌توانی یک راهنما باشی؟',NULL);
INSERT INTO "verses" VALUES(1934818,2615,8,1,'کآشفته گَشت، طُرّهٔ دَستارِ مولوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934819,2615,8,0,'ساقی، مگر وظیفهٔ حافظ، زیاده داد','هوش مصنوعی: ای ساقی، آیا وظیفهٔ حافظ این است که بیش از حد بدهد و باعث آشفته شدن پیچ و تاب دستار مولوی شود؟',NULL);
INSERT INTO "verses" VALUES(1934820,2615,7,1,'کای نورِ چشمِ من! به جز از کِشته، نَدرَوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934821,2615,7,0,'دهقان سال‌خورده، چه خوش گفت با پسر','هوش مصنوعی: کشاورز سالخورده با پسرش صحبت می‌کند و می‌گوید: ای نور چشمان من! به جز محصولی که خودت به دست می‌آوری، هیچ چیز دیگری برای تو مفید نیست.',NULL);
INSERT INTO "verses" VALUES(1934822,2615,6,1,'مَخموریـَت مَباد، که خوش مَست می‌رَوی',NULL,NULL);
INSERT INTO "verses" VALUES(1934823,2615,6,0,'چَشمت، به غَمزه، خانهٔ مردم، خراب کرد','هوش مصنوعی: چشم تو با ناز و اشاره‌ات باعث ویرانی دل‌های مردم شده است. امیدوارم که مستی تو ادامه پیدا نکند و خوشحالی‌ات از این وضعیت باعث نشود که به راهت ادامه دهی.',NULL);
INSERT INTO "verses" VALUES(1934824,2615,5,1,'کاین عیش، نیست درخورِ اُورَنگِ خسروی',NULL,NULL);
INSERT INTO "verses" VALUES(1934825,2615,5,0,'خوش، وقتِ بوریا و گدایی و خوابِ امن','هوش مصنوعی: خوشا به حال کسانی که در زمان فقر و بی‌پناهی و خواب آرام زندگی می‌کنند، زیرا این لذت و خوشی برای زندگی پادشاهی و پرزرق و برق مناسب نیست.',NULL);
INSERT INTO "verses" VALUES(1934826,2616,3,0,'خواب و خورت ز مرتبهٔ خویش دور کرد','هوش مصنوعی: خواب و خوراک تو را از مقام واقعی‌ات دور کرده است، وقتی به خودت می‌رسی که دیگر نیازی به خواب و خوراک نداشته باشی.',NULL);
INSERT INTO "verses" VALUES(1934827,2385,4,0,'بر آن سَرَم که نَنوشَم مِی و گُنَه نکنم','قصد دارم باده‌نوشی را کنار بگذارم و از این پس گناه نکنم، اگر تقدیر و بخت با من بسازد!',NULL);
INSERT INTO "verses" VALUES(1934828,2576,3,0,'بدِ رندان مگو ای شیخ و هُش دار','ای شیخ، از رندان و رندی مثل من بد مگوی که این کار دشمنی با حکم و فرمان خداست.',NULL);
INSERT INTO "verses" VALUES(1934829,2576,2,0,'ولیکن کی نمایی رخ به رندان؟','اما توقع مهر و رخ نمودن به رندی مانند من از تو توقع بی‌جایی است زیرا خورشید و ما آیینه تو هستند.',NULL);
INSERT INTO "verses" VALUES(1934830,2534,5,1,'که نیست معصیت و زهد بی مشیت او',NULL,NULL);
INSERT INTO "verses" VALUES(1934831,2534,5,0,'مکن به چشم حقارت نگاه در من مست','هوش مصنوعی: به من که مستم، با نگاهی تحقیرآمیز ننگر، زیرا نه معصیتی در کارم است و نه زهدی بدون اراده او وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1934832,2534,4,1,'نوید داد که عام است فیض رحمت او',NULL,NULL);
INSERT INTO "verses" VALUES(1934833,2534,4,0,'بیا که دوش به مستی سروش عالم غیب','هوش مصنوعی: بیا که شب گذشته صدای سمفونی عالم غیب به ما خبر داد که رحمت او به همگان تعلق دارد.',NULL);
INSERT INTO "verses" VALUES(1934834,2534,3,1,'مزن به پای که معلوم نیست نیت او',NULL,NULL);
INSERT INTO "verses" VALUES(1934835,2534,3,0,'بر آستانه میخانه گر سری بینی','هوش مصنوعی: اگر به در ورودی میخانه رسیدی و کسی را دیدی، قدم به آنجا نگذار و خودت را درگیر نکن، زیرا نیت و مقصد او مشخص نیست.',NULL);
INSERT INTO "verses" VALUES(1934836,2534,2,1,'که زد به خرمن ما آتش محبت او',NULL,NULL);
INSERT INTO "verses" VALUES(1934837,2534,2,0,'چراغ صاعقه آن سحاب روشن باد','هوش مصنوعی: نور و روشنایی ناشی از صاعقه، بر کیفیت ابر به ما می‌افزاید و نیرویی که منجر به آتش‌زدن خرمن عشق او شد، نشان‌دهنده شدت جذبه و محبت اوست.',NULL);
INSERT INTO "verses" VALUES(1934838,2534,1,1,'بیار باده که مستظهرم به همت او',NULL,NULL);
INSERT INTO "verses" VALUES(1934839,2534,1,0,'بهشت اگر چه نه جای گناهکاران است','هوش مصنوعی: اگرچه بهشت جای کسانی که خطا کرده‌اند نیست، ولی بیا و شراب بیاور که به لطف او از خود بی‌خود شده‌ام.',NULL);
INSERT INTO "verses" VALUES(1934840,2534,0,1,'که نیست در سر من جز هوای خدمت او',NULL,NULL);
INSERT INTO "verses" VALUES(1934841,2534,0,0,'به جان پیر خرابات و حق صحبت او','هوش مصنوعی: زندگی و عشق به شخصی که در محفل خوش‌گذرانی‌ها مشهور است، برایم بسیار ارزشمند است و جز خدمت به او چیزی در خیالم نیست.',NULL);
INSERT INTO "verses" VALUES(1934842,2533,6,1,'که در این باغ نبینی ثمری بهتر از این',NULL,NULL);
INSERT INTO "verses" VALUES(1934843,2533,6,0,'کِلْکِ حافظ شکرین میوه نباتی‌ست، بچین','هوش مصنوعی: دست نوشته‌های حافظ شیرینی چون میوه‌های خوشمزه‌اند. از آن‌ها بهره ببر، چون در این باغ میوه‌ای بهتر از این پیدا نمی‌کنی.',NULL);
INSERT INTO "verses" VALUES(1934844,2533,5,1,'بشنو از من که نگوید دگری بهتر از این',NULL,NULL);
INSERT INTO "verses" VALUES(1934845,2533,5,0,'من چو گویم که قَدَح نوش و لب ساقی بوس','هوش مصنوعی: وقتی من می‌گویم که جام را بنوش و لب‌های ساقی را ببوس، بدان که هیچ‌کس نمی‌تواند بهتر از این را بگوید.',NULL);
INSERT INTO "verses" VALUES(1934846,2533,4,1,'مادر دهر ندارد پسری بهتر از این',NULL,NULL);
INSERT INTO "verses" VALUES(1934847,2533,4,0,'دل بدان رود گرامی چه کنم گر ندهم؟','اگر عاشق آن فرزند عزیز نشوم، چکار کنم؟ مادر روزگار پسری بهتر از این ندارد!',NULL);
INSERT INTO "verses" VALUES(1934848,2533,3,1,'برو ای خواجهٔ عاقل هنری بهتر از این؟!',NULL,NULL);
INSERT INTO "verses" VALUES(1934849,2533,3,0,'ناصحم گفت که جز غم چه هنر دارد عشق','هوش مصنوعی: دوست من گفت که عشق جز غم و درد هیچ هنری ندارد. به تو، ای مرد خردمند، می‌گویم که آیا هنر و زیبایی دیگری بهتر از این وجود دارد؟',NULL);
INSERT INTO "verses" VALUES(1934850,2533,2,1,'گو در این کار بفرما، نظری بهتر از این؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934851,2533,2,0,'آن که فکرش گره از کار جهان بگْشاید','هوش مصنوعی: کسی که بتواند از مشکلات زندگی و جهان راه حلی بیابد، باید با نگاهی عمیق‌تر و بهتر به این موضوع بپردازد.',NULL);
INSERT INTO "verses" VALUES(1934852,2533,1,1,'سخت خوب است ولیکن قَدَری بهتر از این',NULL,NULL);
INSERT INTO "verses" VALUES(1934853,2533,1,0,'در حق من لبت این لطف که می‌فرماید','هوش مصنوعی: لبت که در مورد من سخن می‌گوید، خیلی محبت‌آمیز است و من این را می‌پسندم، اما امیدوارم که کمی بیشتر از این محبت را احساس کنم.',NULL);
INSERT INTO "verses" VALUES(1934854,2533,0,1,'بر در میکده می‌کن گذری بهتر از این',NULL,NULL);
INSERT INTO "verses" VALUES(1934855,2533,0,0,'می‌فکن بر صف رندان نظری بهتر از این','هوش مصنوعی: بر صدای خوب رندان نگاهی افکن و از در میکده، عبوری کن که از این بهتر باشد.',NULL);
INSERT INTO "verses" VALUES(1934856,2532,6,1,'صفای همّت پاکان و پاک‌دینان بین',NULL,NULL);
INSERT INTO "verses" VALUES(1934857,2532,6,0,'کدورت از دل حافظ ببرد صحبت دوست','هوش مصنوعی: دل حافظ از کدورت‌ها خالی می‌شود زمانی که با دوست صحبت می‌کند. این ارتباط نشان‌دهنده‌ی خلوص نیت و پاکی دل افرادی است که به صداقت و نیکی مشهورند.',NULL);
INSERT INTO "verses" VALUES(1934858,2532,5,1,'ضمیر عاقبت‌اندیش پیش‌بینان بین',NULL,NULL);
INSERT INTO "verses" VALUES(1934859,2534,6,0,'نمی‌کند دل من میل زهد و توبه ولی','هوش مصنوعی: دل من تمایل به زهد و توبه ندارد، اما به خاطر نام خداوند تلاش می‌کنیم و به دنبال خوشبختی او هستیم.',NULL);
INSERT INTO "verses" VALUES(1934860,2532,5,0,'اسیر عشق شدن چارهٔ خلاص من است','هوش مصنوعی: افتادن در چنگال عشق، تنها راه نجات من است و عقل و گیرایی کسانی که آینده را می‌بینند، این را نشان می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1934861,2534,6,1,'به نام خواجه بکوشیم و فر دولت او',NULL,NULL);
INSERT INTO "verses" VALUES(1934862,2534,7,1,'مگر ز خاک خرابات بود فطرت او',NULL,NULL);
INSERT INTO "verses" VALUES(1934863,2536,7,0,'آتشِ زهد و ریا خرمنِ دین خواهد سوخت','هوش مصنوعی: زهد و ریا همچون آتشی خطرناک می‌تواند اصول دین را بسوزاند. حافظ از تو می‌خواهد که این لباس پشمی و ظاهری را کنار بگذاری و به راهی راست بروی.',NULL);
INSERT INTO "verses" VALUES(1934864,2536,6,1,'خرمنِ مه به جُوی خوشهٔ پروین به دو جو',NULL,NULL);
INSERT INTO "verses" VALUES(1934865,2536,6,0,'آسمان گو مفروش این عظمت کاندر عشق','به فلک و آسمان بگو که عظمت تو در برابر شکوه عشق هیچ است‌؛ در بازار عشق‌، خرمن ماه را به یک جو و خوشهٔ پروین را به دو جو نمی‌خرند! (‌«خرمن ماه‌» یا خیمهٔ ماه یعنی هاله‌ای که بر دور ماه در بعضی شب‌ها وقتی که ماه در نهایت درخشش است‌، گرد آید. جو علاوه بر معنی دانه جو، در گذشته مقداری پول ناچیز از جنس مس بوده است.)',NULL);
INSERT INTO "verses" VALUES(1934866,2536,5,1,'بیدقی راند که برد از مه و خورشید گرو',NULL,NULL);
INSERT INTO "verses" VALUES(1934867,2536,5,0,'چشمِ بد دور ز خالِ تو که در عرصهٔ حسن','هوش مصنوعی: چشمِ بد از اثر زیبایی‌ات دور باشد، زیرا که تو در دنیای زیبایی همچون شطرنج‌بازی هستی که مه و خورشید را به بازی می‌گیرد و بر آن‌ها تسلط دارد.',NULL);
INSERT INTO "verses" VALUES(1934868,2536,4,1,'دورِ خوبی گذران است نصیحت بشنو',NULL,NULL);
INSERT INTO "verses" VALUES(1934869,2536,4,0,'گوشوارِ زر و لعل ار چه گران دارد گوش','این نصیحت را همانند گوشواره‌ی ارزشمندی آویزه‌ی گوش کن. هرچند که به گوشت گران می‌آید (مانند گوشواره‌ی‌ طلا و عقیق واقعی که سنگین و مایه‌ی آزار است ولی باز به گوش می‌آویزی) که روز و روزگار خوب نیز هم می‌گذرد.',NULL);
INSERT INTO "verses" VALUES(1934870,2536,3,1,'تاجِ کاووس ببرد و کمرِ کیخسرو',NULL,NULL);
INSERT INTO "verses" VALUES(1934871,2536,3,0,'تکیه بر اخترِ شب‌دزد مکن کاین عیار','به یک امروز و روزگار تکیه نکن، چراکه این دزد به ترفند خود تاج کاووس و کمربند کیخسرو را ربود.',NULL);
INSERT INTO "verses" VALUES(1934872,2536,2,1,'از چراغِ تو به خورشید رسد صد پرتو',NULL,NULL);
INSERT INTO "verses" VALUES(1934873,2536,2,0,'گر رَوی پاک و مجرد چو مسیحا به فلک','هوش مصنوعی: اگر به مانند مسیحا خالص و بی‌آلایش باشی، نور تو می‌تواند به آسمان برود و از چراغ‌ات برای خورشید صدها پرتو بفرستد.',NULL);
INSERT INTO "verses" VALUES(1934874,2536,1,1,'گفت با این همه از سابقه نومید مشو',NULL,NULL);
INSERT INTO "verses" VALUES(1934875,2536,1,0,'گفتم ای بخت بخفتیدی و خورشید دمید','گفتم ای عمر گذشتی و فرصت از دست رفت. روز قیامت آمد. گفت با این همه از سبقت و لطف پروردگار نا امید نباش.',NULL);
INSERT INTO "verses" VALUES(1934876,2536,0,1,'یادم از کِشتهٔ خویش آمد و هنگامِ درو',NULL,NULL);
INSERT INTO "verses" VALUES(1934877,2536,0,0,'مزرعِ سبزِ فلک دیدم و داسِ مه نو','در آسمان، زمین سرسبزی را دیدم و هلال ماه نو به یادم آورد که وقت برداشت محصول خود رسیده است.',NULL);
INSERT INTO "verses" VALUES(1934878,2535,6,1,'درسِ حدیثِ عشق بر او خوان و زو شنو',NULL,NULL);
INSERT INTO "verses" VALUES(1934879,2535,6,0,'حافظ جنابِ پیرِ مغان مأمنِ وفاست','هوش مصنوعی: عزیز ما، پیر مغان، پناهگاهی برای وفاداری و عشق است. از او درسی درباره عشق بیاموز و از سخنانش بشنو.',NULL);
INSERT INTO "verses" VALUES(1934880,2535,5,1,'از افسرِ سیامک و ترکِ کلاهِ زو',NULL,NULL);
INSERT INTO "verses" VALUES(1934881,2535,5,0,'شکلِ هلالِ هر سرِ مه می‌دهد نشان','هوش مصنوعی: هلال که شکلش شبیه سر ماه است، نشانه‌ای از زیبایی و جذابیت کسی است که مانند افسر سیامک با کلاهی زیبا و برجسته درخشیده است.',NULL);
INSERT INTO "verses" VALUES(1934882,2535,4,1,'از سرّ‌ِ اخترانِ کهن‌سیر و ماهِ نو',NULL,NULL);
INSERT INTO "verses" VALUES(1934883,2535,4,0,'ساقی بیار باده که رمزی بگویمت','هوش مصنوعی: ای ساقی، برایم نوشیدنی بیاور تا رازی را برایت بگویم که از دوران ستاره‌های باستانی و ماه نو سرچشمه می‌گیرد.',NULL);
INSERT INTO "verses" VALUES(1934884,2535,3,1,'آن‌گه عیان شود که بود موسمِ درو',NULL,NULL);
INSERT INTO "verses" VALUES(1934885,2535,3,0,'تخمِ وفا و مهر در این کهنه کشته‌زار','هوش مصنوعی: در این زمین خشک و قدیمی، تنها در فصل برداشت، نشانه‌های وفا و محبت به بار می نشیند.',NULL);
INSERT INTO "verses" VALUES(1934886,2535,2,1,'کان‌جا هزار نافهٔ مُشکین به نیم‌جو',NULL,NULL);
INSERT INTO "verses" VALUES(1934887,2535,2,0,'مَفروش عطرِ عقل به هِندوی زلفِ ما','هوش مصنوعی: عطر عقل خود را به موهای زیبای ما نفروش، چرا که آنجا هزاران عطر خوشبو با هزینه‌ای ناچیز موجود است.',NULL);
INSERT INTO "verses" VALUES(1934888,2535,1,1,'غافل ز حفظِ جانبِ یارانِ خود مشو',NULL,NULL);
INSERT INTO "verses" VALUES(1934889,2535,1,0,'عمری‌ست تا دلت ز اسیرانِ زلفِ ماست','هوش مصنوعی: مدت زیادی است که دل تو از عشق ما آزاد نیست. مراقب باش که نسبت به دوستانت غافل نشوی.',NULL);
INSERT INTO "verses" VALUES(1934890,2535,0,1,'از ماهِ ابروانِ مَنت شرم باد رو',NULL,NULL);
INSERT INTO "verses" VALUES(1934891,2535,0,0,'گفتا برون شدی به تماشای ماهِ نو','هوش مصنوعی: او گفت: تو به تماشای ماه نو بیرون رفته‌ای، ولی از خاطر نشان کردن ابروان زیبا و دلربایت شرم کن.',NULL);
INSERT INTO "verses" VALUES(1934892,2534,7,0,'مدام خرقه حافظ به باده در گرو است','هوش مصنوعی: حافظ همواره با عشق و دل‌باختگی در ارتباط است و این وابستگی او چندان عمیق است که تنها از دل خاکی که در جشنوارۀ عشق و میگساری وجود دارد، به‌دست می‌آید.',NULL);
INSERT INTO "verses" VALUES(1934893,2532,4,1,'وفای صحبت یاران و همنشینان بین',NULL,NULL);
INSERT INTO "verses" VALUES(1934894,2532,4,0,'حقوق صحبت ما را به باد داد و برفت','هوش مصنوعی: حقوق ما را نادیده گرفت و رفت، وفاداری دوستان و همراهان را ببینید که چطور از بین رفته است.',NULL);
INSERT INTO "verses" VALUES(1934895,2532,3,1,'نیاز اهل دل و ناز نازنینان بین',NULL,NULL);
INSERT INTO "verses" VALUES(1934896,2530,2,0,'چشم خود را گفتم آخر یک نظر سیرش ببین','هوش مصنوعی: به چشمم گفتم که یک بار خوب مرا تماشا کند. او پاسخ داد که آیا می‌خواهی تا زمانی که جوی خون از من راه بیندازد، این کار را بکند؟',NULL);
INSERT INTO "verses" VALUES(1934897,2530,1,1,'ور بگویم بازپوشان بازپوشاند ز من',NULL,NULL);
INSERT INTO "verses" VALUES(1934898,2530,1,0,'روی رنگین را به هر کس می‌نماید همچو گل','هوش مصنوعی: هر کسی می‌تواند زیبایی و دلربایی را ببیند و بشناسد، مانند گل که زیبایی‌اش را به همه نشان می‌دهد. اما اگر بگویم که کسی می‌تواند این زیبایی را از من بپوشاند و پنهان کند، این امکان برای دیگران وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1934899,2530,0,1,'ور بگویم دل بگردان رو بگرداند ز من',NULL,NULL);
INSERT INTO "verses" VALUES(1934900,2530,0,0,'چون شوم خاک رهش دامن بیفشاند ز من','هوش مصنوعی: وقتی که من به خاک پای او تبدیل شوم، او دامنش را از من کنار می‌زند. و اگر بگویم که دل از او برگردان، او هم دلش را از من برمی‌گرداند.',NULL);
INSERT INTO "verses" VALUES(1934901,2529,9,1,'با شاهِ دوست‌پرورِ دشمن‌گُدازِ من',NULL,NULL);
INSERT INTO "verses" VALUES(1934902,2529,9,0,'«حافظ»، زِ گریه سوخت بگو حالش ای صبا','هوش مصنوعی: حافظ از شدت غم و گریه به حالت سوختگی درآمده است. ای نسیم، حال او را به پادشاهی که دوستش دارد و دشمنانش را نابود می‌کند، بگو.',NULL);
INSERT INTO "verses" VALUES(1934903,2529,8,1,'هم مستیِ شبانه و راز و نیازِ من',NULL,NULL);
INSERT INTO "verses" VALUES(1934904,2529,8,0,'زاهد؛ چو از نمازِ تو کاری نمی‌رود','هوش مصنوعی: ای زاهد، اگر نمازی که می‌خوانی نتیجه‌ای برایت ندارد، پس خُب، من شب‌ها در مستی و راز و نیازم غرق می‌شوم.',NULL);
INSERT INTO "verses" VALUES(1934905,2529,7,1,'تا با تو سنگ‌دل چه کُنَد سوز و سازِ من؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934906,2529,7,0,'بر خود، چو شمع، خنده‌زنان، گریه می‌کنم','هوش مصنوعی: من مانند شمع، با لبخند بر چهره، در دل خود گریه می‌کنم تا ببینم که دل سنگی تو چه تاثیری بر احساسات و دردهای من می‌گذارد.',NULL);
INSERT INTO "verses" VALUES(1934907,2529,6,1,'تا کی شود قرینِ حقیقت، مجازِ من',NULL,NULL);
INSERT INTO "verses" VALUES(1934908,2529,6,0,'نقشی بر آب می‌زنم از گریه، حالیا','هوش مصنوعی: من از شدت گریه‌ام به کنار آب می‌روم و نقشی بر آن می‌زنم تا ببینم کی واقعیت‌های زندگی‌ام با خیال‌هایم یکی می‌شوند.',NULL);
INSERT INTO "verses" VALUES(1934909,2529,5,1,'گَرْدَد شمامهٔ کَرَمَش، کارسازِ من؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934910,2529,5,0,'یا رب کی آن صبا بِوَزَد کز نسیمِ آن','هوش مصنوعی: خدایا، کی می‌رسد روزی که نسیم صبا بوزد و با خود بویی بیاورد که باعث بیداری و نشاط من شود؟',NULL);
INSERT INTO "verses" VALUES(1934911,2529,4,1,'ذکرش به خیر‌، ساقیِ مِسْکین‌نوازِ من',NULL,NULL);
INSERT INTO "verses" VALUES(1934912,2529,4,0,'مست است یار و یادِ حریفان نمی‌کُنَد','یار مست است و به یاد دوستانش نیست، یادش به خیر، آن یار چون شراب من',NULL);
INSERT INTO "verses" VALUES(1934913,2529,3,1,'غَمّاز بود اَشْک و عَیان کرد رازِ من',NULL,NULL);
INSERT INTO "verses" VALUES(1934914,2529,3,0,'گفتم به دَلْقِ زَرْق بپوشم نشانِ عشق','هوش مصنوعی: گفتم که با لباس دروغین، نشانه عشق را پنهان کنم، اما اشک‌هایم آشکارا راز دلم را به نمایش گذاشتند.',NULL);
INSERT INTO "verses" VALUES(1934915,2529,2,1,'مِحْرابِ ابرویِ تو، حُضورِ نمازِ من',NULL,NULL);
INSERT INTO "verses" VALUES(1934916,2529,2,0,'می‌ترسم از خرابیِ ایمان که می‌بَرَد','هوش مصنوعی: من نگران از دست دادن ایمان خودم هستم، چرا که ممکن است زیبایی و جذبه ابروی تو باعث شود که نتوانم در عبادت واقعی خود حاضر شوم.',NULL);
INSERT INTO "verses" VALUES(1934917,2529,1,1,'با من چه کَرْد دیدهٔ معشوقه‌بازِ من؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934918,2529,1,0,'دیدی دلا که آخرِ پیری و زُهْد و عِلْم','آیا متوجه شدی که چطور این روحیه ی (دلْ سپارِ) من، در نهایت، با وجود تمام سالخوردگی، خودداری از هوس ها و بار دانشی که اندوخته ام، مرا دل باخته و داغ دارم کرد؟',NULL);
INSERT INTO "verses" VALUES(1934919,2529,0,1,'کوتاه کرد قصّهٔ زُهْدِ درازِ من',NULL,NULL);
INSERT INTO "verses" VALUES(1934920,2529,0,0,'بالابلندِ عِشْوِه‌گرِ نقش‌بازِ من','هوش مصنوعی: داستان طولانی زهد و خودسازی من را معشوقه‌ی سرکش و دلربا به راحتی با جلوه‌های خود کوتاه و کم‌رنگ کرد.',NULL);
INSERT INTO "verses" VALUES(1934921,2528,6,1,'تو قدر او به سخن گفتن دری بشکن',NULL,NULL);
INSERT INTO "verses" VALUES(1934922,2528,6,0,'چو عندلیب فصاحت فروشد ای حافظ','هوش مصنوعی: اگر بلبل زیبا سخن بگوید، ای حافظ، تو باید ارزش او را در فن بیان بدان و در بیان خودت مرزی را بشکنی.',NULL);
INSERT INTO "verses" VALUES(1934923,2528,5,1,'تو قیمتش به سر زلف عنبری بشکن',NULL,NULL);
INSERT INTO "verses" VALUES(1934924,2528,5,0,'چو عطرسای شود زلف سنبل از دم باد','هوش مصنوعی: وقتی که بوی خوش زلف گل سنبل در اثر نسیم به مشام می‌رسد، ارزش آن به اندازه‌ای می‌شود که می‌توان با آن زلف عنبرین را شکست.',NULL);
INSERT INTO "verses" VALUES(1934925,2530,2,1,'گفت می‌خواهی مگر تا جوی خون راند ز من؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934926,2530,3,0,'او به خونم تشنه و من بر لبش تا چون شود','هوش مصنوعی: او به خون من تشنه است و من بر لبش ایستاده‌ام. حالا باید ببینم آیا من می‌توانم از او چیزی بگیرم یا او از من چیزی درخواست خواهد کرد.',NULL);
INSERT INTO "verses" VALUES(1934927,2530,3,1,'کام بستانم از او یا داد بستاند ز من',NULL,NULL);
INSERT INTO "verses" VALUES(1934928,2530,4,0,'گر چو فرهادم به تلخی جان برآید باک نیست','هوش مصنوعی: اگر مثل فرهاد، با سختی و تلخی جان را به دوش ببرم، اشکالی ندارد؛ چرا که هنوز داستان‌های شیرینی از من باقی مانده است.',NULL);
INSERT INTO "verses" VALUES(1934929,2532,3,0,'بهای نیم کرشمه هزار جان طلبند','هوش مصنوعی: بهای یک نگاه نرم و دل‌ربا هزاران جان را می‌خواهد؛ این نیاز را اهل دل دارند و زیبایی‌های نازنینان را می‌بینند.',NULL);
INSERT INTO "verses" VALUES(1934930,2532,2,1,'دماغ و کبر گدایان و خوشه‌چینان بین',NULL,NULL);
INSERT INTO "verses" VALUES(1934931,2532,2,0,'به خرمن دو جهان سر فرونمی‌آرند','هوش مصنوعی: افرادی که از کبر و غرور پر هستند، در برابر نعمت‌ها و شیرینی‌های زندگی، تواضع نمی‌کنند و نمی‌توانند زیبایی‌ها را از دید خود ببینند. آنها در خوشه‌چینی و برداشت از ثروت‌های دنیا ناتوانند.',NULL);
INSERT INTO "verses" VALUES(1934932,2532,1,1,'درازدستی این کوته‌آستینان بین',NULL,NULL);
INSERT INTO "verses" VALUES(1934933,2532,1,0,'به زیر دلق ملمّع کمندها دارند','هوش مصنوعی: این بیت به نوعی به افرادی اشاره دارد که در ظاهر زیبا و جذاب به نظر می‌رسند، اما در باطن، دسیسه‌ها و نیت‌های پنهانی دارند. آن‌ها در پشت ظواهر خود، ابزارهایی برای فریب و دام‌گذاری آماده کرده‌اند، و در واقع به سراغ کسانی می‌روند که کوتاه‌دست و بی‌خبر از نیات آن‌ها هستند.',NULL);
INSERT INTO "verses" VALUES(1934934,2532,0,1,'خلاف مذهب آنان جمال اینان بین',NULL,NULL);
INSERT INTO "verses" VALUES(1934935,2532,0,0,'شراب لعل‌کش و روی مه‌جبینان بین','هوش مصنوعی: شراب قرمز و زیبایی صورت‌های دلربا را ببین، در حالی که زیبایی این افراد با آموزه‌های مذهبی آن‌ها در تضاد است.',NULL);
INSERT INTO "verses" VALUES(1934936,2531,7,1,'تیزیِ شمشیر بنگر قوّتِ بازو ببین',NULL,NULL);
INSERT INTO "verses" VALUES(1934937,2531,7,0,'از مرادِ شاه منصور ای فلک سر برمتاب','هوش مصنوعی: ای آسمان، از خواسته‌ی شاه منصور دور شو و تیزی شمشیر او را ببین و قدرت بازوهایش را نظاره کن.',NULL);
INSERT INTO "verses" VALUES(1934938,2531,6,1,'ای نصیحت‌گو خدا را آن خمِ ابرو ببین',NULL,NULL);
INSERT INTO "verses" VALUES(1934939,2531,6,0,'حافظ ار در گوشهٔ محراب می‌نالد رواست','هوش مصنوعی: اگر حافظ در گوشهٔ عبادتگاه ناله می‌کند، جالب است. ای کسی که نصیحت می‌کنی، به آن خم ابروی معشوق نگاه کن.',NULL);
INSERT INTO "verses" VALUES(1934940,2531,5,1,'کس ندیده‌ست و نبیند مثلش از هر سو ببین',NULL,NULL);
INSERT INTO "verses" VALUES(1934941,2531,5,0,'این‌که من در جست‌وجوی او ز خود فارغ شدم','هوش مصنوعی: این‌که من در پی یافتن او آن‌قدر غرق شده‌ام که از خودم بی‌خبر شده‌ام، چیزی است که هیچ‌کس ندیده و نخواهد دید؛ هر جا را که نگاه کنی، چنین حالتی نخواهی یافت.',NULL);
INSERT INTO "verses" VALUES(1934942,2531,4,1,'با هوادارانِ ره رو حیلهٔ هندو ببین',NULL,NULL);
INSERT INTO "verses" VALUES(1934943,2536,7,1,'حافظ این خرقهٔ پشمینه بینداز و برو',NULL,NULL);
INSERT INTO "verses" VALUES(1934944,2531,4,0,'زلفِ دل‌دزدش صبا را بند بر گردن نهاد','هوش مصنوعی: زلف دل‌فریب او را نسیم صبح بر گردن خود بسته است و با پیروانش نیرنگ هندو را تماشا کنید.',NULL);
INSERT INTO "verses" VALUES(1934945,2531,3,0,'عابدانِ آفتاب از دلبرِ ما غافل‌اند','هوش مصنوعی: بندگان خدا در خشوع و عبادت، از دلبر ما غافل‌اند. ای کسی که عیب‌جویی می‌کنی، خدا را فراموش نکن و به چهره زیبا و معشوق ما توجه کن.',NULL);
INSERT INTO "verses" VALUES(1934946,2531,2,1,'جانِ صد صاحب‌دل آن جا بستهٔ یک مو ببین',NULL,NULL);
INSERT INTO "verses" VALUES(1934947,2531,2,0,'حلقهٔ زلفش تماشاخانهٔ باد صباست','هوش مصنوعی: زن مویش به مانند نمایشگاهی است که باد صبا در آن می‌چرخد و جان صد دل‌سوخته به خاطر یک رشته مو در آنجا گرفتار شده است.',NULL);
INSERT INTO "verses" VALUES(1934948,2531,1,1,'گفت چشمِ شیرگیر و غنجِ آن آهو ببین',NULL,NULL);
INSERT INTO "verses" VALUES(1934949,2531,1,0,'عیبِ دل کردم که وحشی‌وضع و هرجایی مباش','از دلم عیب گرفتم که این قدر انس ناپذیر و هرجایی نباش. گفت: به چشم‌های شیر گیر و کرشمه‌های آهوانه آن یار بنگر',NULL);
INSERT INTO "verses" VALUES(1934950,2531,0,1,'عقل و جان را بستهٔ زنجیرِ آن گیسو ببین',NULL,NULL);
INSERT INTO "verses" VALUES(1934951,2531,0,0,'نکته‌ای دلکَش بگویم خالِ آن مَه‌رو ببین','هوش مصنوعی: می‌خواهم نکته‌ای جذاب دربارهٔ زیبایی آن معشوق بگویم؛ ببین که چطور زیبایی او باعث می‌شود عقل و جان انسان در زنجیر آن موهای بلندش اسیر شوند.',NULL);
INSERT INTO "verses" VALUES(1934952,2530,7,1,'عشق در هر گوشه‌ای افسانه‌ای خواند ز من',NULL,NULL);
INSERT INTO "verses" VALUES(1934953,2530,7,0,'صبر کن حافظ که گر زین دست باشد درس غم','هوش مصنوعی: صبر کن حافظ، چرا که اگر اوضاع به همین صورت ادامه پیدا کند، در هر کجا داستانی از غم عشق خواهد شنید که من آن را روایت کرده‌ام.',NULL);
INSERT INTO "verses" VALUES(1934954,2530,6,1,'کو به چیزی مختصر چون باز می‌ماند ز من',NULL,NULL);
INSERT INTO "verses" VALUES(1934955,2530,6,0,'دوستان جان داده‌ام بهر دهانش بنگرید','هوش مصنوعی: دوستانم را برای رضای او فدای سخن‌اش کرده‌ام؛ به او نگاه کنید که چطور به چیزهای ساده و کوچک دلبسته است و از من دوری می‌کند.',NULL);
INSERT INTO "verses" VALUES(1934956,2530,5,1,'ور برنجم خاطر نازک برنجاند ز من',NULL,NULL);
INSERT INTO "verses" VALUES(1934957,2530,5,0,'گر چو شمعش پیش میرم بر غمم خندان شود','هوش مصنوعی: اگر من مانند شمع در کنار او باشم، غم و اندوه من شاد می‌شود و اگر هم به خاطر رنجش من ناراحت شود، دلش از من می‌گیرد.',NULL);
INSERT INTO "verses" VALUES(1934958,2530,4,1,'بس حکایت‌های شیرین باز می‌ماند ز من',NULL,NULL);
INSERT INTO "verses" VALUES(1934959,2531,3,1,'ای ملامت‌گو خدا را رو مبین آن رو ببین',NULL,NULL);
INSERT INTO "verses" VALUES(1934960,2537,0,0,'ای آفتاب آینه دار جمال تو','هوش مصنوعی: ای خورشید که زیبایی‌ات در آینه منعکس می‌شود، همانند مشک سیاهی که گرد و غبار خال تو را در بر می‌گیرد.',NULL);
INSERT INTO "verses" VALUES(1934961,2537,0,1,'مشک سیاه مجمره گردان خال تو',NULL,NULL);
INSERT INTO "verses" VALUES(1934962,2537,1,0,'صحن سرای دیده بشستم ولی چه سود','هوش مصنوعی: نگاه و دلم را برای تو پاک کردم، اما چه فایده دارد که هنوز هم هیچ چیز در اینجا نیست که به اندازه تو زیبا باشد.',NULL);
INSERT INTO "verses" VALUES(1934963,2542,6,0,'آبی به روزنامهٔ اعمال ما فشان','هوش مصنوعی: از پروردگار بخواهیم که در روزنامهٔ اعمال ما، آبی بریزد تا بتوانیم گناهان خود را از بین ببریم و آنها را پاک کنیم.',NULL);
INSERT INTO "verses" VALUES(1934964,2542,5,1,'گو بر فروز مشعلهٔ صبحگاه از او',NULL,NULL);
INSERT INTO "verses" VALUES(1934965,2542,5,0,'ساقی چراغ می به ره آفتاب دار','هوش مصنوعی: ای ساقی، چراغ شراب را چون آفتاب در مسیر زندگی روشن کن و به من بگو که شعلهٔ صبحگاهی از آن نور منور بر افروز.',NULL);
INSERT INTO "verses" VALUES(1934966,2542,4,1,'من بُرده‌ام به باده‌فروشان پناه از او',NULL,NULL);
INSERT INTO "verses" VALUES(1934967,2542,4,0,'سلطان غم هر آن چه تواند بگو بکن','هوش مصنوعی: غم و غصه، هر کاری که می‌خواهد بکند، من به باده‌فروشان پناه برده‌ام تا از شر او رها شوم.',NULL);
INSERT INTO "verses" VALUES(1934968,2542,3,1,'این دود بین که نامهٔ من شد سیاه از او',NULL,NULL);
INSERT INTO "verses" VALUES(1934969,2542,3,0,'کردار اهل صومعه‌ام کرد مِی‌پرست','هوش مصنوعی: رفتار و اعمال کسانی که در صومعه زندگی می‌کنند، مرا به می‌پرستی کشانده است. به این دود نگاه کن که به خاطر آن، آینده من تیره و سیاه شده است.',NULL);
INSERT INTO "verses" VALUES(1934970,2542,2,1,'کآیینه‌ای‌ست جام جهان‌بین که آه از او',NULL,NULL);
INSERT INTO "verses" VALUES(1934971,2542,2,0,'ای جرعه‌نوش مجلس جم! سینه پاک دار','هوش مصنوعی: ای کسی که سرمست شادی‌های مجلس جمت هستی! دل و جانت را از هر آلودگی پاک نگه‌دار، زیرا که دل همچون آینه‌ای است که جهان را به وضوح می‌بیند و آهی که در دل داری، نشانه‌ای از عمق احساساتت است.',NULL);
INSERT INTO "verses" VALUES(1934972,2542,1,1,'آن جا بمال چهره و حاجت بخواه از او',NULL,NULL);
INSERT INTO "verses" VALUES(1934973,2542,1,0,'ابروی دوست گوشهٔ محراب دولت است','هوش مصنوعی: ابروی محبوب مانند نشانه‌ای از خوشبختی و نعمت است؛ در آنجا به دعا و درخواست از او بپرداز و حاجات خود را از او بخواه.',NULL);
INSERT INTO "verses" VALUES(1934974,2542,0,1,'خوش حلقه‌ای‌ست لیک به دَر نیست راه از او',NULL,NULL);
INSERT INTO "verses" VALUES(1934975,2542,0,0,'خط عذار یار که بگرفت ماه از او','خط زیبای صورت یار که ماه از آن الهام گرفته، مانند یک حلقه زیباست؛ اما به نظر می‌رسد نمی‌توان از آن گریخت.',NULL);
INSERT INTO "verses" VALUES(1934976,2541,7,1,'به تیر غمزه صیدش کرد چشم آن کمان‌ابرو',NULL,NULL);
INSERT INTO "verses" VALUES(1934977,2541,7,0,'اگر چه مرغ زیرک بود حافظ در هوادار‌ی','هر چند حافظ در عاشقی و خاطرخواهی چونان پرنده‌ای زیرک رفتار می‌کرد اما، چشم دل‌فریب آن معشوق کمان ابرو با تیر ناز و عشوه او را شکار کرد.',NULL);
INSERT INTO "verses" VALUES(1934978,2541,6,1,'که محرابم بگرداند خم آن دل‌ستان ابرو',NULL,NULL);
INSERT INTO "verses" VALUES(1934979,2541,6,0,'تو کافر‌دل نمی‌بندی نقاب زلف و می‌ترسم','تو ای معشوق سنگ‌دل و بی‌رحم، نقاب گیسوی زیبای خود را بر چهره‌ات نمی‌اندازی و می‌ترسم که ابروی کمانی زیبای تو، محراب من را تغییر دهد.',NULL);
INSERT INTO "verses" VALUES(1934980,2541,5,1,'که این را این چنین چشم است و آن را آن چنان ابرو',NULL,NULL);
INSERT INTO "verses" VALUES(1934981,2541,5,0,'دگر حور و پری را کس نگوید با چنین حسنی','بعد از دیدن زیبایی معشوق من، دیگر هیچ‌کس از زیبایی حور و پری صحبت نخواهد کرد و نخواهد گفت که حوریان چشمانی سیاه و زیبا دارند و پریان ابروان آن چنانی.(رونق بازار حور و پری از بین خواهد رفت).',NULL);
INSERT INTO "verses" VALUES(1934982,2541,4,1,'که بر طرْف سمن‌زارش همی گردد چمان ابرو',NULL,NULL);
INSERT INTO "verses" VALUES(1934983,2541,4,0,'روانِ گوشه‌گیران را جبینش طرفه گلزار‌ی‌ست','پیشانی معشوق برای روح و جان گوشه‌نشینان مانند گل‌زاری شگفت و زیباست که در کنار صورت سفید همچون سمن‌زارش، ابروان کمانی زیبای او در حال خرامیدن و عشوه‌گری هستند.',NULL);
INSERT INTO "verses" VALUES(1934984,2541,3,1,'هزاران گونه پیغام است و حاجب در میان، ابرو',NULL,NULL);
INSERT INTO "verses" VALUES(1934985,2541,3,0,'رقیبان غافل و ما را از آن چشم و جبین هر دم','رقیبان و نگهبانان یار بی‌خبرند که از چشم و پیشانی معشوق هر لحظه هزاران گونه پیغام به ما می‌رسد و ابرو همچون پرده‌داری در این میان است.',NULL);
INSERT INTO "verses" VALUES(1934986,2541,2,1,'که باشد مه که بنماید ز طاق آسمان ابرو؟',NULL,NULL);
INSERT INTO "verses" VALUES(1934987,2541,2,0,'هلالی شد تنم زین غم که با طغرا‌ی ابرو‌یش','به سبب این غصه تنم همچون ماه خمیده و نحیف شد، که با وجود ابروی هلالی یار من، ماه چگونه جرات می‌کند که از طاق آسمان ابرو نشان دهد و جلوه‌گری کند؟',NULL);
INSERT INTO "verses" VALUES(1934988,2541,1,1,'نگارین گلشنش روی است و مشکین سایبان ابرو',NULL,NULL);
INSERT INTO "verses" VALUES(1934989,2541,1,0,'غلام چشم آن ترکم که در خوابِ خوشِ مستی','من بنده‌ی چشم آن زیبارویی هستم که در خواب ناز مستی، چهره‌ای چون باغ پر نقش و نگار دارد و ابرویی همچون سایبانی سیاه که بر روی آن باغ قرار گرفته است.',NULL);
INSERT INTO "verses" VALUES(1934990,2541,0,1,'جهان بس فتنه خواهد دید از آن چشم و از آن ابرو',NULL,NULL);
INSERT INTO "verses" VALUES(1934991,2541,0,0,'مرا چشمی‌ست خون‌افشان ز دست آن کمان‌ابرو','از دست آن محبوبی که ابرویی همچون کمان دارد، چشمانم اشک خونین می‌بارد؛ مردم دنیا نیز از دست آن چشم و ابرو بلاهای بسیاری خواهند دید.',NULL);
INSERT INTO "verses" VALUES(1934992,2542,6,1,'باشد توان سترد حروف گناه از او',NULL,NULL);
INSERT INTO "verses" VALUES(1934993,2542,7,0,'حافظ که ساز مطرب عشاق ساز کرد','هوش مصنوعی: از حافظ خواسته می‌شود که همیشه در مجالس عاشقانه حضور داشته باشد و این مجالس هیچ‌گاه از حضور او خالی نماند. این ابراز آرزو برای ماندگاری عشق و شادی در زندگی است.',NULL);
INSERT INTO "verses" VALUES(1934994,2542,7,1,'خالی مباد عرصهٔ این بزمگاه از او',NULL,NULL);
INSERT INTO "verses" VALUES(1934995,2542,8,0,'آیا در این خیال که دارد گدای شهر','هوش مصنوعی: آیا در این فکر هستی که یک روز گدای شهر به یادش بیفتد پادشاه؟',NULL);
INSERT INTO "verses" VALUES(1934996,2544,7,0,'بر این فقیر، نامهٔ آن محتشم بخوان','هوش مصنوعی: برای این مردم ناتوان، نامهٔ آن بزرگوار را بخوان و داستان آن پادشاه را برای این گدای بی‌نوا روایت کن.',NULL);
INSERT INTO "verses" VALUES(1934997,2544,6,1,'شاهانه ماجرای گناه گدا بگو',NULL,NULL);
INSERT INTO "verses" VALUES(1934998,2544,6,0,'هر چند ما بَدیم تو ما را بِدان مگیر','هوش مصنوعی: هرچند که ما افراد بدی هستیم، ولی تو نباید ما را به این صورت قضاوت کنی. از تو می‌خواهم که داستان گناه و شرافتمندانه‌ی ما را بشنوی و در نظر بگیری.',NULL);
INSERT INTO "verses" VALUES(1934999,2544,5,1,'بعد از ادای خدمت و عرض دعا بگو',NULL,NULL);
INSERT INTO "verses" VALUES(1935000,2544,5,0,'گر دیگرت بر آن در دولت گذر بود','هوش مصنوعی: اگر روزی بر در خانه‌ات کسی دیگر گذر کند، بعد از اینکه خدمتش را انجام دادی و دعای خیر برایش کردی، به او بگو.',NULL);
INSERT INTO "verses" VALUES(1935001,2544,4,1,'گو «در حضور پیر من این ماجرا بگو»',NULL,NULL);
INSERT INTO "verses" VALUES(1935002,2544,4,0,'آن کس که منع ما ز خرابات می‌کند','هوش مصنوعی: کسی که ما را از رفتن به میخانه منع می‌کند، بهتر است در حضور استاد من این حرف را بزند.',NULL);
INSERT INTO "verses" VALUES(1935003,2544,3,1,'گو «این سخن معاینه در چشم ما بگو»',NULL,NULL);
INSERT INTO "verses" VALUES(1935004,2544,3,0,'هر کس که گفت «خاک در دوست توتیاست»','هرکسی که بگوید "خاک در دوست مانند توتیا سرمه‌ایست بر چشم"، به او بگو "این سخن را بر اساس دیده‌ها و تجربیات ما بگو".',NULL);
INSERT INTO "verses" VALUES(1935005,2544,2,1,'با ما سر چه داشت؟ ز بهر خدا بگو',NULL,NULL);
INSERT INTO "verses" VALUES(1935006,2544,2,0,'بر هم چو می‌زد آن سر زلفین مشک‌بار','هوش مصنوعی: زن با کجای گیسوان مشکین خود، بر هم می‌زد، با ما چه کار داشت؟ برای خدا بگو.',NULL);
INSERT INTO "verses" VALUES(1935007,2544,1,1,'با یار آشنا سخن آشنا بگو',NULL,NULL);
INSERT INTO "verses" VALUES(1935008,2544,1,0,'ما محرمان خلوت انسیم غم مخور','هوش مصنوعی: ما دوستانی نزدیک در محفل انس و صمیمیت هستیم، نگران نباش و با یار آشنای خود صحبت‌های صمیمی و آشنا را به زبان بیاور.',NULL);
INSERT INTO "verses" VALUES(1935009,2544,0,1,'احوال گل به بلبل دستان‌سرا بگو',NULL,NULL);
INSERT INTO "verses" VALUES(1935011,2544,0,0,'ای پیک راستان خبر یار ما بگو','هوش مصنوعی: ای پیام‌آور راستین، به ما از حال و احوال یارمان بگو و هم چنین به بلبل داستان‌سرا از سرگذشت گل اطلاع بده.',NULL);
INSERT INTO "verses" VALUES(1935012,2543,6,0,'حافظ اگر چه در سخن خازن گنج حکمت است','هوش مصنوعی: حافظ اگرچه در شعرش به گنجینه‌ای پرارزش از حکمت دست یافته، اما در برابر غم روزگار پست، کجا می‌تواند قدرت و ذوق شاعرانه‌اش را نشان دهد؟',NULL);
INSERT INTO "verses" VALUES(1935013,2543,5,1,'مُردم از این هوس ولی قدرت و اختیار کو؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935014,2543,5,0,'گفت «مگر ز لعل من بوسه نداری آرزو؟»','هوش مصنوعی: گفت: «آیا از زیبایی من آرزوی بوسه نداری؟» من از این میل دچار مرگ شدم، اما کجاست آن قدرت و اختیار که مرا از این خواسته بازدارد؟',NULL);
INSERT INTO "verses" VALUES(1935015,2543,4,1,'خصم زبان دراز شد خنجر آبدار کو؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935016,2543,4,0,'شمع سحرگهی اگر لاف ز عارض تو زد','هوش مصنوعی: اگر شمع سحرگاهی (که به زیبایی تو می‌نازد) زبان به ناز و خودستایی بگشاید، دشمن هم در آن لحظه زبانش دراز خواهد شد. اما کجاست آن خنجر تیز و برنده که به خاطر زیبایی تو برانگیخته می‌شود؟',NULL);
INSERT INTO "verses" VALUES(1935017,2543,3,1,'دست زدم به خون دل بهر خدا نگار کو؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935018,2543,3,0,'حُسن‌فروشیِ گلم نیست تحمل ای صبا','هوش مصنوعی: ای نسیم، زیبایی من را نمی‌توانی تحمل کنی. با دل شکسته‌ام به یادت اشاره کردم. ای کاش برای خدا، تصاویر محبوبم را به من نشان بدهی.',NULL);
INSERT INTO "verses" VALUES(1935019,2543,2,1,'ای دمِ صبحِ خوش‌نفس نافهٔ زلف یار کو؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935020,2543,2,0,'مجلس بزم عیش را غالیهٔ مراد نیست','هوش مصنوعی: در این مجلس خوشی و شادی، آرزویم محقق نمی‌شود. ای صبح زیبای خوش‌بو، کجاست آن گل عطرآگین که از زلف یار بیرون آمده است؟',NULL);
INSERT INTO "verses" VALUES(1935021,2543,1,1,'گوش سخن‌شنو کجا؟ دیدهٔ اعتبار کو؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935022,2543,1,0,'هر گل نو ز گل‌رخی یاد همی کند ولی','هوش مصنوعی: هر گلی از گل‌های زیبا یاد می‌کند، اما چه کسی به صحبت‌ها گوش می‌دهد؟ دیدهٔ پر ارزش کجاست؟',NULL);
INSERT INTO "verses" VALUES(1935023,2543,0,1,'باد بهار می‌وزد بادهٔ خوش‌گوار کو؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935024,2543,0,0,'گلبن عیش می‌دمد ساقی گل‌عذار کو؟','هوش مصنوعی: بهشتی که در آن لذت و شادی برپا می‌شود، کجاست؟ ای نوشنده، دختر زیبا کجا است؟ نسیم بهاری می‌وزد، ولی شراب خوش‌گوار کجاست؟',NULL);
INSERT INTO "verses" VALUES(1935025,2542,8,1,'روزی بود که یاد کند پادشاه از او؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935026,2543,6,1,'از غم روزگارِ دون، طبعِ سخن‌گزار کو؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935027,2528,4,1,'به ابروان دوتا قوس مشتری بشکن',NULL,NULL);
INSERT INTO "verses" VALUES(1935030,2538,4,1,'از حسرت فروغ رخ همچو ماه تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935031,2538,4,0,'با هر ستاره‌ای سر و کار است هر شبم','هوش مصنوعی: هر شب با تمام ستاره‌ها در ارتباط هستم، اما حسرت نوری که در چهره‌ی مثل ماه تو وجود دارد، مرا از درون می‌سوزاند.',NULL);
INSERT INTO "verses" VALUES(1935032,2538,3,1,'زان شد کنار دیده و دل تکیه‌گاه تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935033,2538,3,0,'آرام و خواب خلق جهان را سبب تویی','هوش مصنوعی: آرامش و خواب برای موجودات جهان به خاطر توست و به همین دلیل، چشمان و دل من به تو اتکا دارد.',NULL);
INSERT INTO "verses" VALUES(1935034,2538,2,1,'از دل نیایدش که نویسد گناه تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935035,2538,2,0,'خونم بخور که هیچ مَلَک با چنان جمال','هوش مصنوعی: به خاطر زیبایی تو، خون من را به خاطر معصیتت بخور، چرا که هیچ فرشتهای نمی‌تواند زیبایی تو را از دلش بنویسد.',NULL);
INSERT INTO "verses" VALUES(1935036,2538,1,1,'ای من فدای شیوه چشم سیاه تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935037,2538,1,0,'نرگس کرشمه می‌برد از حد برون خرام','هوش مصنوعی: نرگس با زیبایی و جذبه‌اش فراتر از حد و مرز می‌رود. ای کاش فدای آن شیوه نگاه زیبا و دانای تو بشوم.',NULL);
INSERT INTO "verses" VALUES(1935038,2538,0,1,'خورشید سایه‌پرور طرف کلاه تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935039,2538,0,0,'ای خونبهای نافه چین خاک راه تو','هوش مصنوعی: ای کسی که بهای خون تو برای خوبی‌های ناب و زیباییت در زمین، مانند نوری است که سایه‌سار بر کلاه و سر تو می‌افکند.',NULL);
INSERT INTO "verses" VALUES(1935040,2537,10,1,'سودای کج مپز که نباشد مجال تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935041,2537,10,0,'حافظ در این کمند سر سرکشان بسیست','هوش مصنوعی: حافظ در اینجا اشاره دارد به اینکه او در دام جوانان فریبنده و سرکش افتاده است. از آن‌ها می‌خواهد که به خاطر نادرست‌کاری‌ها و خیالات باطل خود، خود را به زحمت نیندازند، زیرا فرصتی برای آن‌ها وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1935042,2537,9,1,'شرح نیازمندی خود یا ملال تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935043,2537,9,0,'در پیش شاه عرض کدامین جفا کنم','هوش مصنوعی: نمی‌دانم چگونه باید در حضور شاه از سختی‌های خود بگویم؛ آیا باید درد دل خودم را بیان کنم یا از غم تو بگویم؟',NULL);
INSERT INTO "verses" VALUES(1935044,2537,8,1,'عکسیست در حدیقه بینش ز خال تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935045,2537,8,0,'این نقطه سیاه که آمد مدار نور','هوش مصنوعی: این نقطه سیاه که در نور ظاهر شده، نمادی است از تأثیر عمیق و زیبایی چهره‌ات در دنیای فکر و احساس من.',NULL);
INSERT INTO "verses" VALUES(1935046,2537,7,1,'کو مژده‌ای ز مقدم عید وصال تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935047,2537,7,0,'تا پیش بخت بازروم تهنیت کنان','هوش مصنوعی: باید با خوشحالی و شکرگذاری به سراغ شانس خود برویم و خبر خوشی از آمدن عید وصل تو را بشنویم.',NULL);
INSERT INTO "verses" VALUES(1935048,2537,6,1,'کو عشوه‌ای ز ابروی همچون هلال تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935049,2537,6,0,'تا آسمان ز حلقه به گوشان ما شود','هوش مصنوعی: به آسمان خواهیم رسید، چون زیبایی و جذابیت ابروی تو، همچون هلال، دل‌انگیز است.',NULL);
INSERT INTO "verses" VALUES(1935050,2537,5,1,'ای نوبهار ما رخ فرخنده فال تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935051,2537,5,0,'برخاست بوی گل ز در آشتی درآی','هوش مصنوعی: عطر گل به مشام می‌رسد، بیا و وارد شایستگی بهاری جدید شو، صورت خوش یمنی که مقدر شده برای تو.',NULL);
INSERT INTO "verses" VALUES(1935052,2537,4,1,'کآشفته گفت باد صبا شرح حال تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935053,2537,4,0,'در چین زلفش ای دل مسکین چگونه‌ای','هوش مصنوعی: در چین‌های زلف او ای دل بی‌چاره چه حالی داری، که باد صبا آشفته و پریشان، داستان تو را برایش روایت کرده است.',NULL);
INSERT INTO "verses" VALUES(1935054,2537,3,1,'طغرانویس ابروی مشکین مثال تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935055,2537,3,0,'مطبوعتر ز نقش تو صورت نبست باز','هوش مصنوعی: هیچ تصویری به زیبایی چهره تو ایجاد نشده است، حتی طغرانویس (خط زیبای فارسی) با ابروهای مشکی تو قابل مقایسه نیست.',NULL);
INSERT INTO "verses" VALUES(1935056,2537,2,1,'یا رب مباد تا به قیامت زوال تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935057,2537,2,0,'در اوج ناز و نعمتی ای پادشاه حسن','هوش مصنوعی: ای پادشاه زیبایی، در اوج زیبایی و نعمت خود هستی، ای کاش تا ابد و همیشه چنین بمانی و از بین نروی.',NULL);
INSERT INTO "verses" VALUES(1935058,2537,1,1,'کـ‌این گوشه نیست درخور خیل خیال تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935059,2538,5,0,'یاران همنشین همه از هم جدا شدند','هوش مصنوعی: دوستان و همراهان همه از یکدیگر جدا شده‌اند و تنها ما مانده‌ایم که به درگاه حمایت و بخشش تو پناه می‌بریم.',NULL);
INSERT INTO "verses" VALUES(1935060,2538,5,1,'ماییم و آستانه دولت پناه تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935061,2538,6,0,'حافظ طمع مبُر ز عنایت که عاقبت','حافظ، از رحمت و لطف خداوند ناامید مشو، زیرا در نهایت درد و اندوه تو مانند آتشی می‌سوزاند و خرمن غم‌هایت را خواهد زد.',NULL);
INSERT INTO "verses" VALUES(1935062,2538,6,1,'آتش زند به خرمن غم دود آه تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935075,2539,8,1,'بر امیدِ عفوِ جان‌بخشِ گنه‌فرسایِ تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935076,2539,8,0,'خسروا ! پیرانه‌سر، حافظ جوانی می‌کند','هوش مصنوعی: خسروا، پیرمردی همچون حافظ به یاد جوانی‌اش می‌زند و امیدوار است که تو گناهانش را ببخشی و جانش را نجات دهی.',NULL);
INSERT INTO "verses" VALUES(1935078,2539,7,1,'راز کس مخفی نمانَد با فروغِ رایِ تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935079,2539,6,1,'جرعه‌ای بود از زلالِ جام جان‌افزای تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935080,2539,6,0,'آن چه اسکندر طلب کرد و ندادش روزگار','هوش مصنوعی: آن چه اسکندر در جستجویش بود و نتوانست به دست آورد، تنها یک قطره از آب زلال و زندگی‌بخش وجود تو بود.',NULL);
INSERT INTO "verses" VALUES(1935081,2539,5,1,'روشنایی‌بخشِ چشم اوست خاک پای تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935082,2539,5,0,'گرچه خورشیدِ فلک چشم و چراغ عالم است','هوش مصنوعی: هرچند خورشید آسمان روشنی و روشنایی دنیا است، اما نور چشمان او از خاک پای تو ناشی می‌شود.',NULL);
INSERT INTO "verses" VALUES(1935083,2539,4,1,'طوطیِ خوش‌لهجه یعنی کلک شکّرخای تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935084,2539,4,0,'آب حیوانش ز منقارِ بلاغت می‌چکد','هوش مصنوعی: طوطی خوش‌سخن به گونه‌ای صحبت می‌کند که از منقار او آب حیات نشت می‌کند، و این نشان از هنر و زیبایی کلام تو دارد که همچون شکر شیرین و دلپذیر است.',NULL);
INSERT INTO "verses" VALUES(1935085,2539,3,1,'نکته‌ای هرگز نشد فوت از دلِ دانای تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935086,2539,3,0,'از رسومِ شرع و حکمت با هزاران اختلاف','هوش مصنوعی: با وجود اینکه در بین قوانین دین و حکمت هزاران نکته‌ی متفاوت وجود دارد، اما هیچ نکته‌ای از ذهن و دلِ انسانِ باهوش تو فراموش نشده است.',NULL);
INSERT INTO "verses" VALUES(1935087,2539,2,1,'سایه‌ اندازد همایِ چترِ گردون‌سایِ تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935088,2539,2,0,'جلوه‌گاهِ طایرِ اقبال باشد هر کجا','هوش مصنوعی: هر کجا که سایه‌ی خوشبختی بر افکند، نشانه‌ای از وجود توست.',NULL);
INSERT INTO "verses" VALUES(1935089,2539,1,1,'از کلاهِ خسروی رخسارِ مه‌سیمایِ تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935090,2539,1,0,'آفتاب فتح را هر دم طلوعی می‌دهد','هوش مصنوعی: خورشید پیروزی هر لحظه بر بام سرمستی تو می‌تابد و چهره‌ی آن ماه سیمی را روشن می‌کند.',NULL);
INSERT INTO "verses" VALUES(1935091,2539,0,1,'زینتِ تاج و نگین از گوهرِ والای تو',NULL,NULL);
INSERT INTO "verses" VALUES(1935092,2539,0,0,'ای قبای پادشاهی، راست بر بالای تو','هوش مصنوعی: ای لباس سلطنت به زیبایی بر تن تو است و تاج و نگین زینت بخش تو از جواهرات گرانبهاست.',NULL);
INSERT INTO "verses" VALUES(1935093,2539,7,0,'عرضِ حاجت در حریم حضرتت محتاج نیست','هوش مصنوعی: در پیشگاه تو نیاز به بیان درخواست نیست، زیرا هیچ رازی نمی‌تواند پنهان بماند؛ روشنگری تفکر تو همه چیز را روشن می‌کند.',NULL);
INSERT INTO "verses" VALUES(1935094,2528,4,0,'به آهوان نظر شیر آفتاب بگیر','هوش مصنوعی: به آهوهایی که مانند زیبایی خورشید هستند، نگاهی بینداز و با ابروان خوش‌فرم و قوسی‌شکل خود، جادوگری کن.',NULL);
INSERT INTO "verses" VALUES(1935095,2528,3,1,'سزای حور بده رونق پری بشکن',NULL,NULL);
INSERT INTO "verses" VALUES(1935096,2528,3,0,'برون خرام و ببر گوی خوبی از همه کس','هوش مصنوعی: جان خود را به جلو بیاور و زیبایی‌های خوب را از دیگران بگیر. سزاوار حوری‌ها را به دیگران ببخش و شکوه پریان را بشکن.',NULL);
INSERT INTO "verses" VALUES(1935097,2518,4,1,'دلت در سینه چون در سیم آهن',NULL,NULL);
INSERT INTO "verses" VALUES(1935098,2518,4,0,'تنت در جامه چون در جام باده','هوش مصنوعی: بدنت در لباس مانند جامی است که حاوی باده و دل‌ات در سینه مانند آهنی است که درون آن سیم وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1935099,2518,3,1,'نگردد هیچ کس با دوست دشمن',NULL,NULL);
INSERT INTO "verses" VALUES(1935100,2518,3,0,'به قول دشمنان برگشتی از دوست','هوش مصنوعی: به گفته‌ی دشمنان، هیچ‌کس نمی‌تواند برگردد و با دوستش دشمنی کند.',NULL);
INSERT INTO "verses" VALUES(1935101,2518,2,1,'ولی دل را تو آسان بردی از من',NULL,NULL);
INSERT INTO "verses" VALUES(1935102,2518,2,0,'من از دست غمت مشکل برم جان','هوش مصنوعی: من از غم تو جانم در درد و رنج است، اما تو به راحتی دل مرا از من گرفتی.',NULL);
INSERT INTO "verses" VALUES(1935103,2518,1,1,'چو مستان جامه را بدرید بر تن',NULL,NULL);
INSERT INTO "verses" VALUES(1935104,2518,1,0,'تنت را دید گل گویی که در باغ','هوش مصنوعی: تن تو را مانند گلی می‌بینم که مانند میخی در باغ، جامه‌اش را از تن درآورده است.',NULL);
INSERT INTO "verses" VALUES(1935105,2518,0,1,'کنم چاک از گریبان تا به دامن',NULL,NULL);
INSERT INTO "verses" VALUES(1935106,2518,0,0,'چو گل هر دم به بویت جامه در تن','هوش مصنوعی: هر لحظه به عطر تو، لباس خود را می‌پوشم و دلم را چاک‌چاک می‌کنم تا به دامن تو برسم.',NULL);
INSERT INTO "verses" VALUES(1935107,2517,6,1,'به قول حافظ و فتوی پیر صاحب فن',NULL,NULL);
INSERT INTO "verses" VALUES(1935108,2517,6,0,'حدیث صحبت خوبان و جام باده بگو','هوش مصنوعی: از سخنانی که درباره خوبی‌ها و زیبایی‌هاست بگو، و درباره پیمانه‌ی شراب بگو، به قول حافظ و بر اساس نظر someone که در این زمینه صاحب‌نظر است.',NULL);
INSERT INTO "verses" VALUES(1935109,2517,5,1,'برای وصل گل آمد برون ز بیت حزن',NULL,NULL);
INSERT INTO "verses" VALUES(1935110,2517,5,0,'صفیر بلبل شوریده و نفیر هزار','هوش مصنوعی: صدای زیبای بلبل عاشق و فریاد هزاران عاشق برای رسیدن به گل، از دنیای غم و اندوه بیرون آمده است.',NULL);
INSERT INTO "verses" VALUES(1935111,2517,4,1,'بعینه دل و دین می‌برد به وجه حسن',NULL,NULL);
INSERT INTO "verses" VALUES(1935112,2517,4,0,'عروس غنچه رسید از حرم به طالع سعد','هوش مصنوعی: عروسی که از حرم خارج شده، به خوشی و خوشبختی می‌رسد و با زیبایی و چهره جذابش، دل و ایمان را تحت تأثیر قرار می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1935113,2517,3,1,'شکنج گیسوی سنبل ببین به روی سمن',NULL,NULL);
INSERT INTO "verses" VALUES(1935114,2517,3,0,'ز دستبرد صبا گرد گل کلاله نگر','هوش مصنوعی: به دقت به زیبایی گل‌ها و گیسوان پنبه‌ای نگاه کن، که نسیم لطیف بر آنها می‌وزد و آنها را در هم می‌پیچد.',NULL);
INSERT INTO "verses" VALUES(1935115,2517,2,1,'به راستی طلب آزادگی ز سرو چمن',NULL,NULL);
INSERT INTO "verses" VALUES(1935116,2517,2,0,'طریق صدق بیاموز از آب صافیِ دل','هوش مصنوعی: آموختن صداقت را از آب زلال یاد بگیر و برای دستیابی به آزادی به راستی تلاش کن، مانند سروهایی که در چمن رشد می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1935117,2517,1,1,'ز خود برون شد و بر خود درید پیراهن',NULL,NULL);
INSERT INTO "verses" VALUES(1935118,2517,1,0,'رسید باد صبا غنچه در هواداری','هوش مصنوعی: یک نسیم خوشبو به سمت غنچه‌ای آمد و آن را از پس خود رها کرد و پیراهنش را که به آن بسته بود، درید.',NULL);
INSERT INTO "verses" VALUES(1935119,2517,0,1,'به شادی رخِ گل بیخ غم ز دل بر کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935120,2517,0,0,'بهار و گل طرب‌انگیز گشت و توبه‌شکن','هوش مصنوعی: بهار فرا رسیده و گل‌ها زیبا و شاداب شده‌اند. در این زمان شادمانی، با ترک غم و اندوه، از دل خود غم را دور کن و به شادی بپرداز.',NULL);
INSERT INTO "verses" VALUES(1935121,2516,8,1,'از می لعل حکایت کن و شیرین‌دهنان',NULL,NULL);
INSERT INTO "verses" VALUES(1935122,2516,8,0,'گفت: حافظ! من و تو محرم این راز نه‌ایم','هوش مصنوعی: حافظ می‌گوید که من و تو به اندازه‌ای نزدیک به هم نیستیم که بخواهیم به این راز عمیق پی ببریم. بهتر است از شراب قرمز بگوییم و درباره افرادی با زبان شیرین صحبت کنیم.',NULL);
INSERT INTO "verses" VALUES(1935123,2516,7,1,'که شهیدانِ که‌اند این همه خونین‌کفنان',NULL,NULL);
INSERT INTO "verses" VALUES(1935124,2516,7,0,'با صبا در چمن لاله سحر می‌گفتم','هوش مصنوعی: با نسیم صبحگاهی در باغ گل، به لاله‌ها می‌گفتم که این همه کسانی که در خون خود غوطه‌ورند، چه افرادی هستند و چه داستانی دارند.',NULL);
INSERT INTO "verses" VALUES(1935125,2516,6,1,'مرد یزدان شو و فارغ گذر از اهرمنان',NULL,NULL);
INSERT INTO "verses" VALUES(1935126,2518,5,0,'ببار ای شمع اشک از چشم خونین','هوش مصنوعی: ای شمع، اشک‌هایت را بریز و ببار، چون قلبت به خاطر others به شدت می‌سوزد.',NULL);
INSERT INTO "verses" VALUES(1935127,2518,5,1,'که شد سوز دلت بر خلق روشن',NULL,NULL);
INSERT INTO "verses" VALUES(1935128,2518,6,0,'مکن کز سینه‌ام آه جگرسوز','هوش مصنوعی: ناhopeی کن که از دلم آهی جانسوز بلند می‌شود، مانند دودی که از پنجره بیرون می‌آید.',NULL);
INSERT INTO "verses" VALUES(1935129,2518,6,1,'برآید همچو دود از راه روزن',NULL,NULL);
INSERT INTO "verses" VALUES(1935130,2520,1,1,'گو نه دل باش و نه ایام چه خواهد بودن؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935131,2520,1,0,'غم دل چند توان خورد؟ که ایام نماند','هوش مصنوعی: چقدر می‌توان غم دل را تحمل کرد؟ مگر نه اینکه روزها و زمان‌ها پایدار نمی‌مانند، پس نه دل را دلتنگ کن و نه به ایام فکر کن که چه خواهند شد.',NULL);
INSERT INTO "verses" VALUES(1935132,2520,0,1,'تا ببینم که سرانجام چه خواهد بودن',NULL,NULL);
INSERT INTO "verses" VALUES(1935133,2520,0,0,'خوش‌تر از فکر می و جام چه خواهد بودن؟','هوش مصنوعی: چیزی خوش‌تر از اندیشیدن به شراب و جام نیست؛ منتظرم ببینم که سرانجام چه رخ خواهد داد.',NULL);
INSERT INTO "verses" VALUES(1935134,2519,10,1,'تا از آن جام زرافشان جرعه‌ای بخشد به من',NULL,NULL);
INSERT INTO "verses" VALUES(1935135,2519,10,0,'ای صبا بر ساقی بزم اتابک عرضه دار','هوش مصنوعی: ای نسیم، به ساقی میخانه اتابک بگو تا از آن جام پرنور و زیبا جرعه‌ای به من بدهد.',NULL);
INSERT INTO "verses" VALUES(1935136,2519,9,1,'ساقیا می ده به قول مستشار مؤتمن',NULL,NULL);
INSERT INTO "verses" VALUES(1935137,2519,9,0,'مشورت با عقل کردم گفت حافظ می بنوش','هوش مصنوعی: با عقل مشورت کردم و او گفت که حافظ، ساقی، شراب را بنوش و به وعده‌ات وفا کن، همان‌طور که مشاور معتبر گفته است.',NULL);
INSERT INTO "verses" VALUES(1935138,2519,8,1,'برشکن طرف کلاه و برقع از رخ برفکن',NULL,NULL);
INSERT INTO "verses" VALUES(1935139,2519,8,0,'گوشه گیران انتظار جلوهٔ خوش می‌کنند','هوش مصنوعی: منتظران در گوشه‌ها به تماشای زیبایی‌ها نشسته‌اند. ای کسی که در دل زیبایی‌ات را پنهان کرده‌ای، حجاب و کلاه را از چهره‌ات بردار تا دیگران زیبایی‌ات را ببینند.',NULL);
INSERT INTO "verses" VALUES(1935140,2519,7,1,'خیزد از صحرای اِیذَج نافهٔ مُشک خُتن',NULL,NULL);
INSERT INTO "verses" VALUES(1935141,2519,7,0,'بعد از این نَشگِفت اگر با نکهتِ خُلقِ خوشت','هوش مصنوعی: دیگر تعجب نکن اگر بوی خوش انسان‌ها تو را به وجد آورد، چون از دشت ایذج، بوی دلپذیر مشک ختن به مشام می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1935142,2519,6,1,'تو درخت عدل بنشان بیخ بدخواهان بکن',NULL,NULL);
INSERT INTO "verses" VALUES(1935143,2519,6,0,'جویبار ملک را آب روان شمشیر توست','هوش مصنوعی: آب روان جویبار حکومت تو از شمشیر تو سرچشمه می‌گیرد. تو باید درخت عدالت را بکاری و ریشه بدخواهی‌ها را از بین ببری.',NULL);
INSERT INTO "verses" VALUES(1935144,2516,6,0,'دامن دوست به دست آر و ز دشمن بگسل','خدا را عبادت کن و دل دوست را به دست آر (منظور خدا است)و رابطه‌ات را با دشمن قطع کن. به مردی از سوی خداوند تبدیل شو . تا بر شیطان‌ها و اهریمنان پیروز شوی و به سلامت عبور کنی.',NULL);
INSERT INTO "verses" VALUES(1935145,2519,5,1,'شهسوارا چون به میدان آمدی گویی بزن',NULL,NULL);
INSERT INTO "verses" VALUES(1935146,2519,4,1,'در همه شهنامه‌ها شد داستان انجمن',NULL,NULL);
INSERT INTO "verses" VALUES(1935147,2519,4,0,'شوکت پور پشنگ و تیغ عالمگیر او','هوش مصنوعی: شوکت پسر پشنگ و شمشیر قدرتمند او، داستانش در تمام داستان‌های شاهنامه به عنوان یک موضوع مهم مطرح شده است.',NULL);
INSERT INTO "verses" VALUES(1935148,2519,3,1,'هر نفس با بوی رحمان می‌وزد باد یمن',NULL,NULL);
INSERT INTO "verses" VALUES(1935149,2519,3,0,'تا ابد معمور باد این خانه کز خاک درش','هوش مصنوعی: این خانه تا ابد آباد و پر رونق باشد، چرا که هر دم بوی خوشی از خاک در آن به مشام می‌رسد که نشانه‌ای از رحمت الهی و برکت است.',NULL);
INSERT INTO "verses" VALUES(1935150,2519,2,1,'کاسم اعظم کرد از او کوتاه دست اهرمن',NULL,NULL);
INSERT INTO "verses" VALUES(1935151,2519,2,0,'خاتم جم را بشارت ده به حسن خاتمت','هوش مصنوعی: به خاتم جم خبر خوشی بده که حسن کارهای پایانی را به او نوید می‌دهد. او با قدرت و عظمت خود، اهرمن را از نزدیکیش دور کرده است.',NULL);
INSERT INTO "verses" VALUES(1935152,2519,1,1,'تا نشیند هر کسی اکنون به جای خویشتن',NULL,NULL);
INSERT INTO "verses" VALUES(1935153,2519,1,0,'خوش به جای خویشتن بود این نشست خسروی','هوش مصنوعی: خوش به حال کسی که چنین مقامی دارد و در آنجا نشسته است؛ چرا که اکنون هر کسی می‌تواند در جای خود، احساس شادمانی کند.',NULL);
INSERT INTO "verses" VALUES(1935154,2519,0,1,'مقدمش یا رب مبارک باد بر سرو و سمن',NULL,NULL);
INSERT INTO "verses" VALUES(1935155,2519,0,0,'افسر سلطان گل پیدا شد از طرف چمن','هوش مصنوعی: افسر سلطان گل، به معنی پیشوای زیبایی و لطافت، از طرف باغ پیدا شده است. ای کاش به سرو و سمن، که نمادهای زیبایی و طراوت هستند، خوشا بختی و شادی برساند.',NULL);
INSERT INTO "verses" VALUES(1935156,2518,8,1,'بدین سان کار او در پا میفکن',NULL,NULL);
INSERT INTO "verses" VALUES(1935157,2518,8,0,'چو دل در زلف تو بسته‌ست حافظ','هوش مصنوعی: وقتی دل من در زلف تو گرفتار شده است، حافظ، تو نیز با این کار نکن که او را به زحمت بیندازی.',NULL);
INSERT INTO "verses" VALUES(1935158,2518,7,1,'که دارد در سر زلف تو مسکن',NULL,NULL);
INSERT INTO "verses" VALUES(1935159,2518,7,0,'دلم را مشکن و در پا مینداز','هوش مصنوعی: دل من را نشکن و آن را زیر پا نگذار، چرا که این دل در سایه‌ی موهای تو آرامش دارد.',NULL);
INSERT INTO "verses" VALUES(1935160,2519,5,0,'خنگ چوگانی چرخت رام شد در زیر زین','هوش مصنوعی: وقتی اسب نادان و بی‌خبر از خود را زیر زین سوارکاری قرار می‌دهی و او را به میدان می‌بری، انگار که آماده به جنگ و نبرد شده است.',NULL);
INSERT INTO "verses" VALUES(1935161,2520,2,0,'مرغ کم‌حوصله را گو غم خود خور که بر او','هوش مصنوعی: به پرنده‌ای که کم‌حوصله است بگو غم و غصه‌اش را بخورد، زیرا رحم کسی که دام می‌گذارد بر او نخواهد بود، پس او چه خواهد شد؟',NULL);
INSERT INTO "verses" VALUES(1935162,2516,5,1,'گفت: پرهیز کن از صحبت پیمان‌شکنان',NULL,NULL);
INSERT INTO "verses" VALUES(1935163,2516,4,1,'شادی زهره‌جبینان خور و نازک‌بدنان',NULL,NULL);
INSERT INTO "verses" VALUES(1935164,2514,1,0,'دل آزردهٔ ما را به نسیمی بنواز','هوش مصنوعی: دل دلbroken ما را با یک نسیم آرامش بده، به گونه‌ای که آن روحی که از بدن رفته را دوباره به وجود بیاوری.',NULL);
INSERT INTO "verses" VALUES(1935165,2514,0,1,'وان سهی سروِ خرامان به چمن باز رسان',NULL,NULL);
INSERT INTO "verses" VALUES(1935166,2514,0,0,'یا رب آن آهوی مشکین به خُتَن باز رسان','هوش مصنوعی: خداوندا، آن آهوی خوشبو را که در کابل (حتی) می‌رقصد، و آن سروهای باریک و زیبا را که در باغ می‌چرخند، بگذار تا بنگرند.',NULL);
INSERT INTO "verses" VALUES(1935167,2513,6,1,'گر نیستت رضایی حُکمِ قضا بگردان',NULL,NULL);
INSERT INTO "verses" VALUES(1935168,2513,6,0,'حافظ ز خوبرویان بختت جز این قَدَر نیست','هوش مصنوعی: اگر از سوی خدای خوبان بر تو خوشبختی و سعادت نرسد، پس به دنبال رضایت و خوشنودی نباش، چرا که حکم تقدیر و سرنوشت غیر از این نیست.',NULL);
INSERT INTO "verses" VALUES(1935169,2513,5,1,'یا رب نوشتهٔ بد از یارِ ما بگردان',NULL,NULL);
INSERT INTO "verses" VALUES(1935170,2513,5,0,'دوران همی‌نویسد بر عارضش خطی خوش','هوش مصنوعی: زمان بر چهره‌اش نقشی زیبا می‌زند، ای کاش نوشته‌های بد از معشوق ما را دور کنی.',NULL);
INSERT INTO "verses" VALUES(1935171,2513,4,1,'چنگِ حزین و جامی بِنواز یا بگردان',NULL,NULL);
INSERT INTO "verses" VALUES(1935172,2513,4,0,'ای نورِ چشمِ مستان در عینِ انتظارم','هوش مصنوعی: ای نورِ چشمِ مستان، در حالی که منتظرم، ساز غمگینی بنواز و یا جامی را برایم بچرخان.',NULL);
INSERT INTO "verses" VALUES(1935173,2513,3,1,'در سر کلاه بِشکن در بَر قَبا بگردان',NULL,NULL);
INSERT INTO "verses" VALUES(1935174,2513,3,0,'یغمایِ عقل و دین را بیرون خرام سرمست','هوش مصنوعی: به خود بیا و از قید و بندهای عقل و دین رها شو، با اعتماد به نفس و شادی به جلو برو و کلاهی که به سر داری را در هم بشکن و لباسی که بر تن داری را زیباتر کن.',NULL);
INSERT INTO "verses" VALUES(1935175,2513,2,1,'گِردِ چمن بُخوری همچون صبا بگردان',NULL,NULL);
INSERT INTO "verses" VALUES(1935176,2513,2,0,'مَرغول را بَرافشان یعنی به رَغمِ سنبل','هوش مصنوعی: پرنده‌ای را که می‌خواهی آزاد کن، یعنی حتی اگر عشق و زیبایی در اطرافت هست، باید با آن‌ها به آرامی و لطافت رفتار کنی و همچون نسیم صبح، دور و بر آن زیبایی‌ها بچرخ.',NULL);
INSERT INTO "verses" VALUES(1935177,2513,1,1,'تا او به سر درآید، بر رَخش پا بگردان',NULL,NULL);
INSERT INTO "verses" VALUES(1935178,2513,1,0,'مَه جلوه می‌نماید بر سبز خِنگِ گَردون','هوش مصنوعی: ماه در آسمان بر سطح آبی رنگ گیتی نمایان می‌شود. وقتی او در آسمان ظاهر می‌شود، باید بر چهره‌اش نگاهی دقیق بیندازید.',NULL);
INSERT INTO "verses" VALUES(1935179,2513,0,1,'هجران بلایِ ما شد، یا رب بلا بگردان',NULL,NULL);
INSERT INTO "verses" VALUES(1935180,2513,0,0,'می‌سوزم از فِراقت روی از جَفا بگردان','هوش مصنوعی: من از دوری تو می‌سوزم، لطفاً از ظلم خود روی برگردان. جدایی، بلای من شده است، ای خدا، این بلا را دور کن.',NULL);
INSERT INTO "verses" VALUES(1935181,2512,5,1,'گر می‌شنیدی پند ادیبان',NULL,NULL);
INSERT INTO "verses" VALUES(1935182,2512,5,0,'حافظ نگشتی شیدای گیتی','ای حافظ اگر به اندرز ادیبان گوش می‌دادی، دلبسته‌ی جهان نمی‌شدی.',NULL);
INSERT INTO "verses" VALUES(1935183,2512,4,1,'تا چند باشیم از بی نصیبان',NULL,NULL);
INSERT INTO "verses" VALUES(1935184,2512,4,0,'ای منعم آخر بر خوان جودت','ای بخشنده تا کی ما بر سفره‌ی بخشش تو از بی‌نصیبان باشیم؟',NULL);
INSERT INTO "verses" VALUES(1935185,2512,3,1,'یا رب مبادا کام رقیبان',NULL,NULL);
INSERT INTO "verses" VALUES(1935186,2512,3,0,'درج محبت بر مهر خود نیست','مهر و موم صندوقچه‌‌ی محبت بر جای خود نیست. خداوندا مبادا که به دست رقیبان باشد.',NULL);
INSERT INTO "verses" VALUES(1935187,2512,2,1,'چشم محبان روی حبیبان',NULL,NULL);
INSERT INTO "verses" VALUES(1935188,2512,2,0,'یا رب امان ده تا بازبیند','خداوندا، اجازه بده چشم دوست‌داران دوباره چهره معشوقان را ببیند.',NULL);
INSERT INTO "verses" VALUES(1935189,2512,1,1,'گو شرم بادش از عندلیبان',NULL,NULL);
INSERT INTO "verses" VALUES(1935190,2512,1,0,'آن گل که هر دم در دست بادیست','به آن گلی که هر لحظه در دست بادی است، بگو که بلبلان خجالت بکشد.',NULL);
INSERT INTO "verses" VALUES(1935191,2512,0,1,'درمان نکردند مسکین غریبان',NULL,NULL);
INSERT INTO "verses" VALUES(1935192,2512,0,0,'چندان که گفتم غم با طبیبان','هر چه غم خود را به طبیبان گفتم، نتوانستند بی‌کسان و بیچارگان را درمان کنند.',NULL);
INSERT INTO "verses" VALUES(1935193,2514,1,1,'یعنی آن جانِ ز تن رفته به تن باز رسان',NULL,NULL);
INSERT INTO "verses" VALUES(1935194,2514,2,0,'ماه و خورشید به منزل چو به امرِ تو رسند','هوش مصنوعی: وقتی که ماه و خورشید به خواسته تو به منزل می‌رسند، یار زیبا روی من هم به نزد من می‌آید.',NULL);
INSERT INTO "verses" VALUES(1935195,2514,2,1,'یارِ مه‌روی مرا نیز به من باز رسان',NULL,NULL);
INSERT INTO "verses" VALUES(1935196,2514,3,0,'دیده‌ها در طلبِ لعلِ یَمانی خون شد','هوش مصنوعی: چشم‌هایم به دنبال جواهر یمنی خون گریه کردند. ای پروردگار، آیا آن ستاره درخشان که در یمن به دنبال آن بودیم، پیدا خواهد شد؟',NULL);
INSERT INTO "verses" VALUES(1935197,2516,4,0,'بر جهان تکیه مکن ور قدحی مِی‌ داری','بر حال دنیا اعتماد مکن و اگر یک پیاله شراب داری به سلامتی ماهرویان و نازک‌اندامان بنوش.',NULL);
INSERT INTO "verses" VALUES(1935198,2516,3,1,'تا به خلوتگه خورشید رسی چرخ‌زنان',NULL,NULL);
INSERT INTO "verses" VALUES(1935199,2516,3,0,'کمتر از ذره نه‌ای، پست مشو، مهر بورز','یک ذره گرد و غبار کمتر نیستی که خود را به خورشید می‌رساند. خود را فرومگذار و عاشق باش تا در حال رقص و چرخش به سراپرده خورشید برسی.',NULL);
INSERT INTO "verses" VALUES(1935200,2516,2,1,'بندهٔ من شو و برخور ز همه سیم‌تنان',NULL,NULL);
INSERT INTO "verses" VALUES(1935201,2516,2,0,'تا کی از سیم و زرت کیسه تهی خواهد بود؟','تا چه زمانی می‌خواهی که جیب تو از طلا و نقره خالی باشد؟ بندگی مرا بپذیر تا از همه دلبران سیمین‌بدن بهره‌برداری کنی.',NULL);
INSERT INTO "verses" VALUES(1935202,2516,1,1,'گفت: ای چشم و چراغ همه شیرین‌سخنان',NULL,NULL);
INSERT INTO "verses" VALUES(1935203,2516,1,0,'مست بگذشت و نظر بر من درویش انداخت','در حال مستی بر من گذار کرد، نگاهی به من فقیر انداخت و گفت: ای سرآمد همه خوش‌کلامان‌…',NULL);
INSERT INTO "verses" VALUES(1935204,2516,0,1,'که به مژگان شکند قلب همه صف‌شکنان',NULL,NULL);
INSERT INTO "verses" VALUES(1935205,2516,0,0,'شاه شمشادقدان، خسرو شیرین‌دهنان','پادشاه بلندبالایان و شهریار شیرین‌بیانان که با مژه‌هایش دل همه شجاعان شورش‌آور را می‌شکند‌…',NULL);
INSERT INTO "verses" VALUES(1935206,2515,6,1,'که دارد سینه‌ای چون دیگ جوشان',NULL,NULL);
INSERT INTO "verses" VALUES(1935207,2515,6,0,'ز دلگرمی حافظ بر حذر باش','هوش مصنوعی: به احساسات و عواطف حافظ توجه کن، زیرا او در درون خود احساسی پرآشوب و طوفانی دارد.',NULL);
INSERT INTO "verses" VALUES(1935208,2515,5,1,'صُراحی خون‌دل و بربط خروشان',NULL,NULL);
INSERT INTO "verses" VALUES(1935209,2515,5,0,'بیا وز غَبْن این سالوسیان بین','هوش مصنوعی: بیایید و از این فریب‌کاری سالوس‌ها آگاه شویم، جایی که ظرفی پر از خون دل و یک ساز شاداب را می‌بینیم.',NULL);
INSERT INTO "verses" VALUES(1935210,2515,4,1,'چو نوشم داده‌ای زهرم منوشان',NULL,NULL);
INSERT INTO "verses" VALUES(1935211,2516,5,0,'پیر پیمانه‌کش من که روانش خوش باد','روانشاد پیر عارف باده‌نوش من گفت که از بدقولان و عهدشکنان دوری گزین‌…',NULL);
INSERT INTO "verses" VALUES(1935212,2515,4,0,'چو مستم کرده‌ای مستور منشین','هوش مصنوعی: وقتی تو مرا مست کرده‌ای، لطفاً زندگی‌ام را پنهان نکن. زمانی که زهر را به من می‌دهی، نگذار که از آن بنوشم.',NULL);
INSERT INTO "verses" VALUES(1935213,2515,3,0,'تو نازک‌طبعی و طاقت نیاری','هوش مصنوعی: تو دل-sensitive هستی و نمی‌توانی بار سنگین رفتارهای عده‌ای ظاهرنما را تحمل کنی.',NULL);
INSERT INTO "verses" VALUES(1935214,2515,2,1,'که صافی باد عیش دُردنوشان',NULL,NULL);
INSERT INTO "verses" VALUES(1935215,2515,2,0,'در این صوفی‌وشان دَردی ندیدم','هوش مصنوعی: در این مردم صوفی‌نما، دردی ندیدم که پاک‌کننده لذت برای دردآوران باشد.',NULL);
INSERT INTO "verses" VALUES(1935216,2515,1,1,'خوشا وقت قبای می فروشان',NULL,NULL);
INSERT INTO "verses" VALUES(1935217,2515,1,0,'در این خرقه بسی آلودگی هست','هوش مصنوعی: در این پوشش، آلودگی‌های زیادی وجود دارد، اما خوشا به حال کسانی که در لباس می‌فروشان هستند.',NULL);
INSERT INTO "verses" VALUES(1935218,2515,0,1,'رخ از رندان بی‌سامان مپوشان',NULL,NULL);
INSERT INTO "verses" VALUES(1935219,2515,0,0,'خدا را کم نشین با خرقه پوشان','تو را به خدا قسم میدهم که با افراد با اسم و رسم و مقام کمتر نشست و برخاست کن و چهره ات را از مستمندان و رندان پوشیده نگاه ندار',NULL);
INSERT INTO "verses" VALUES(1935220,2514,6,1,'به مرادش ز غریبی به وطن باز رسان',NULL,NULL);
INSERT INTO "verses" VALUES(1935221,2514,6,0,'آن که بودی وطنش دیدهٔ حافظ یا رب','هوش مصنوعی: آن کسی که وطنش چشم حافظ بود، ای خدا! به آرزویش برسد تا از غریب‌واژه به وطن خود بازگردد.',NULL);
INSERT INTO "verses" VALUES(1935222,2514,5,1,'بشنو ای پیکِ خبرگیر و سخن باز رسان',NULL,NULL);
INSERT INTO "verses" VALUES(1935223,2514,5,0,'سخن این است که ما بی تو نخواهیم حیات','هوش مصنوعی: پیام این است که بدون تو زندگی برای ما ممکن نیست. ای پیام‌آور، به ما بگو و خبر ببر.',NULL);
INSERT INTO "verses" VALUES(1935224,2514,4,1,'پیش عنقا سخنِ زاغ و زَغَن باز رسان',NULL,NULL);
INSERT INTO "verses" VALUES(1935225,2514,4,0,'برو ای طایرِ میمونِ همایون آثار','هوش مصنوعی: برو ای پرنده خوشبخت و خوش‌علامت، به جستجوی نشان‌ها و نشانه‌های ارزشمند، چون حقیقت زنگ‌های زاغ و زغن را نمی‌فهمی و نمی‌توانی به درستی قضاوت کنی.',NULL);
INSERT INTO "verses" VALUES(1935226,2514,3,1,'یا رب آن کوکبِ رخشان به یَمَن باز رسان',NULL,NULL);
INSERT INTO "verses" VALUES(1935227,2515,3,1,'گرانی‌های مشتی دلق‌پوشان',NULL,NULL);
INSERT INTO "verses" VALUES(1935228,2544,7,1,'با این گدا حکایت آن پادشا بگو',NULL,NULL);
INSERT INTO "verses" VALUES(1935229,2520,2,1,'رحمِ آن کس که نهد دام چه خواهد بودن؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935230,2520,3,1,'اعتبار سخن عام چه خواهد بودن؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935231,2526,6,1,'کرشمه بر سمن و جلوه بر صنوبر کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935232,2526,6,0,'چو شاهدان چمن زیردست حسن تواَند','هوش مصنوعی: وقتی زیبایی‌های چمن زیر چشم‌های حسن می‌رقصند، می‌توانی به گل‌ها زیبایی ببخشی و به درختان جلوه‌گری کنی.',NULL);
INSERT INTO "verses" VALUES(1935233,2526,5,1,'به یک کرشمه صوفی‌وشم قلندر کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935234,2526,5,0,'از این مزوجه و خرقه نیک در تنگم','هوش مصنوعی: در اینجا سخن از آن است که از این لباس ساده و فقر خود در تنگنای زندگی به یک حرکت و جذبه عارفانه، می‌خواهم به حالتی دلخواه و آزاد تبدیل شوم.',NULL);
INSERT INTO "verses" VALUES(1935235,2526,4,1,'به تحفه بر سوی فردوس و عود مجمر کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935236,2526,4,0,'بگو به خازن جنت که خاک این مجلس','هوش مصنوعی: به خازن بهشت بگو که خاک این مجلس را به عنوان هدیه به سوی بهشت بفرستد و عود را هم بسوزاند.',NULL);
INSERT INTO "verses" VALUES(1935237,2526,3,1,'به بام قصر برآ و چراغ مه بر کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935238,2526,3,0,'ستاره شب هجران نمی‌فشاند نور','هوش مصنوعی: در شب درد و جدایی، ستاره‌ها نور خود را بر بام قصر نمی‌تابانند، پس چراغ مه را خاموش کن.',NULL);
INSERT INTO "verses" VALUES(1935239,2526,2,1,'بیا بیا و تماشای طاق و منظر کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935240,2526,2,0,'به چشم و ابروی جانان سپرده‌ام دل و جان','هوش مصنوعی: دل و جانم را به زیبایی‌ها و جذابیت‌های محبوبم سپرده‌ام. بیایید و تماشا کنید که چگونه در دل من جای دارید و چه زیبایی‌هایی در این منظر وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1935241,2526,1,1,'پیاله‌ای بدهش گو دماغ را تر کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935242,2526,1,0,'اگر فقیه نصیحت کند که عشق مباز','«فقیه نصیحت کند که عشق مباز»یعنی اگر عالمِ ظاهرگرا تو را از عشق ورزیدن بازداشت و توصیه کرد از راه عشق دوری کنی.«پیاله‌ای بدهش گو دماغ را تر کن»یعنی جامی به او بده و بگو ابتدا حال و هوای خشک و ذهنِ گرفتارِ جمودت را تر کن؛ کنایه از این‌که کسی که طعم عشق و شور را نچشیده، صلاحیت داوری و نصیحت درباره عشق را ندارد.',NULL);
INSERT INTO "verses" VALUES(1935243,2526,0,1,'هوای مجلس روحانیان معطر کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935244,2526,0,0,'ز در در آ و شبستان ما منور کن','هوش مصنوعی: از درِ ما وارد شو و شبستان ما را روشن کن، و هوای مجلس روحانیان را خوشبو کن.',NULL);
INSERT INTO "verses" VALUES(1935245,2525,5,1,'برخیز و عزم جزم به کار صواب کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935246,2525,5,0,'کار صواب، باده پرستی‌ست حافظا','ای حافظ، کار درست، علاقه شدید به سرمستی است؛ پس برخیز و برای انجام کار درست تصمیم محکمی بگیر.',NULL);
INSERT INTO "verses" VALUES(1935247,2525,4,1,'با ما به جام باده صافی خطاب کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935248,2525,4,0,'ما مرد زهد و توبه و طامات نیستیم','من اهل پرهیزکاری و توبه و ادعاهای پوچ و بی‌معنی نیستم، اگر می‌خواهی با من صحبت کنی در مورد جام شراب ناب صحبت کن(نکته: نکته قابل توجه و رندانه حافظ در این بیت قرار دادن و مترادف دانستن طامات، با زهد و توبه هست)',NULL);
INSERT INTO "verses" VALUES(1935249,2525,3,1,'زنهار کاسهٔ سر ما پرشراب کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935250,2525,3,0,'روزی که چرخ از گل ما کوزه‌ها کند','یعنی وقتی روزگار ما را به خاک تبدیل کرد و کوزه‌گر از آن خاک، روی چرخ کوزه‌گری ظرف و کوزه ساخت، از خاکِ سرِ ما نیز کاسه‌ای بساز و آن را از شراب پر کن.',NULL);
INSERT INTO "verses" VALUES(1935251,2525,2,1,'گر برگ عیش می‌طلبی ترک خواب کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935252,2525,2,0,'خورشید می ز مشرق ساغر طلوع کرد','شراب همچون خورشیدی از مشرق ساغر برآمد و ظاهر شد، اگر به دنبال توشه‌ای برای عیش و خوشگذرانی هستی، خواب را رها کن',NULL);
INSERT INTO "verses" VALUES(1935253,2525,1,1,'ما را ز جام بادهٔ گلگون خراب کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935254,2525,1,0,'زان پیش‌تر که عالم فانی شود خراب','ای ساقی قبل از آنکه این دنیای ناپایدار و زودگذر ، خراب و ویران شود، ما را از شراب سرخرنگ مست و مدهوش کن',NULL);
INSERT INTO "verses" VALUES(1935255,2525,0,1,'دور فلک درنگ ندارد شتاب کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935256,2525,0,0,'صبح است ساقیا قدحی پرشراب کن','ای ساقی، صبح شده است، ظرفِ شراب را پر کن؛ زمان برای لحظه‌ای نمی‌ایستد، پس تو نیز عجله کن! و جام شراب را به ما بده',NULL);
INSERT INTO "verses" VALUES(1935260,2526,7,0,'فضول نفس حکایت بسی کند ساقی','هوش مصنوعی: نفس انسان داستان‌های زیادی را بازگو می‌کند، بنابراین ای ساقی، کار خود را رها نکن و شراب را در جام بریز.',NULL);
INSERT INTO "verses" VALUES(1935261,2526,7,1,'تو کار خود مده از دست و می به ساغر کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935262,2526,8,0,'حجاب دیده ادراک شد شعاع جمال','هوش مصنوعی: حجاب چشمان باعث شده تا زیبایی را نتوانیم به خوبی ببینیم. بیایید و این تاریکی را با نور خود روشن کنیم.',NULL);
INSERT INTO "verses" VALUES(1935263,2526,8,1,'بیا و خرگه خورشید را منور کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935264,2528,2,1,'به غمزه گوی که قلب ستمگری بشکن',NULL,NULL);
INSERT INTO "verses" VALUES(1935265,2528,2,0,'به زلف گوی که آیین دلبری بگذار','هوش مصنوعی: به موهای خود بگویید که زیبایی را فراموش کنند و به طرز نگاه کردن بگویید که قلب ظالم را بشکند.',NULL);
INSERT INTO "verses" VALUES(1935266,2528,1,1,'کلاه گوشه به آیین سروری بشکن',NULL,NULL);
INSERT INTO "verses" VALUES(1935267,2528,1,0,'به باد ده سر و دستار عالمی یعنی','هوش مصنوعی: به باد دادن سر و دستار یعنی رها کردن زینت‌ها و نشانه‌های مقام و جاه، تا نشان دهنده‌ی سروری و بزرگی باشد. این جمله به نوعی دعوت به سادگی و دوری از تظاهر کردن در مقام‌ها و شور و شعف زندگی است.',NULL);
INSERT INTO "verses" VALUES(1935268,2528,0,1,'به غمزه رونق و ناموس سامری بشکن',NULL,NULL);
INSERT INTO "verses" VALUES(1935269,2528,0,0,'کرشمه‌ای کن و بازار ساحری بشکن','هوش مصنوعی: با ظرافت و ناز خود توجه مردم را جلب کن و با ناز و غمزه‌ات زندگی و جذابیت را به هم بزن.',NULL);
INSERT INTO "verses" VALUES(1935270,2527,8,1,'یک بوسه نذر حافظ پشمینه‌پوش کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935271,2527,8,0,'سرمست در قبای زرافشان چو بگذری','آن روز که خرسند و شاداب از نصیحت حافظ بهره بردی، او را به نیکی یاد کن',NULL);
INSERT INTO "verses" VALUES(1935272,2527,7,1,'چشم عنایتی به من دردنوش کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935273,2527,7,0,'ساقی که جامت از می صافی تهی مباد','هوش مصنوعی: ای ساقی، امیدوارم همیشه جامت پر از شراب خالص باشد؛ لطفی بکن و با نگاهی مهربانانه به من، که دردم را می‌چشمو، توجه کن.',NULL);
INSERT INTO "verses" VALUES(1935274,2527,6,1,'صد جان فدای یار نصیحت نیوش کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935275,2527,6,0,'با دوستان مضایقه در عمر و مال نیست','هوش مصنوعی: با دوستان در مورد عمر و ثروت هیچ کم و کسری نباید باشد، صد بار جانم را فدای دوستی خواهم کرد. به نصیحت‌ها توجه کن.',NULL);
INSERT INTO "verses" VALUES(1935276,2527,5,1,'خواهی که زلف یار کشی ترک هوش کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935277,2527,5,0,'بر هوشمند سلسله ننهاد دست عشق','هوش مصنوعی: اگر عشق بر دل هوشمند تأثیر بگذارد، دیگر نباید به فکر زلف یار باشی و عقل را کنار بگذاری.',NULL);
INSERT INTO "verses" VALUES(1935279,2527,4,1,'هان ای پسر که پیر شوی پند گوش کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935280,2527,3,1,'همّت در این عمل طلب از می‌فروش کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935281,2527,3,0,'تسبیح و خرقه لذّت مستی نبخشدت','هوش مصنوعی: کارهای ظاهری مانند تسبیح گرداندن و پوشیدن لباس‌های مخصوص نمی‌تواند تو را به لذت و حال خوب برساند. برای رسیدن به این حال، باید از دل و با نیت خالص، به سراغ می‌فروش و اصل مستی بروی.',NULL);
INSERT INTO "verses" VALUES(1935282,2527,2,1,'ای چنگ ناله برکش و ای دف خروش کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935283,2527,2,0,'برگ نوا تبه شد و ساز طرب نماند','هوش مصنوعی: برگ نوا که به نوعی نشان‌دهنده شادی و سروری است، دیگر وجود ندارد و ساز و آواز خوشی هم باقی نمانده است. ای چنگ، شروع به نواختن کن و ای دف، صدای خود را بلند کن.',NULL);
INSERT INTO "verses" VALUES(1935284,2527,1,1,'پیش آی و گوشِ دل به پیام سروش کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935285,2527,1,0,'در راه عشق وسوسهٔ اهرمن بسیست','هوش مصنوعی: در مسیر عشق، وسوسه‌های شیطانی زیادی وجود دارد. جلو بیا و با گوش جان به پیام الهی توجه کن.',NULL);
INSERT INTO "verses" VALUES(1935286,2527,0,1,'چون ساغرت پُر است بنوشان و نوش کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935287,2527,0,0,'ای نور چشم من سخنی هست گوش کن','هوش مصنوعی: ای روشنایی چشم من، حرفی برایت دارم، گوش کن. وقتی که جام تو پر است، بنوش و لذت ببر.',NULL);
INSERT INTO "verses" VALUES(1935288,2526,11,1,'ز کارها که کنی شعر حافظ از بر کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935289,2526,11,0,'پس از ملازمت عیش و عشق مه‌رویان','هوش مصنوعی: پس از اینکه در لذت‌ها و عشق مه‌ترین چهره‌ها غرق شدی، دیگر به کارها فکر نکن و شعر حافظ را از حفظ کن.',NULL);
INSERT INTO "verses" VALUES(1935290,2526,10,1,'بدین دقیقه دماغ معاشران تر کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935291,2526,10,0,'لب پیاله ببوس آنگهی به مستان ده','هوش مصنوعی: لب پیاله را ببوس و سپس به می‌نوشیدگان ببخش تا در این لحظه، فضای دوستی و خوشی را برای همراهان خود شاداب‌تر کنی.',NULL);
INSERT INTO "verses" VALUES(1935292,2526,9,1,'حوالتم به لب لعل همچو شکر کن',NULL,NULL);
INSERT INTO "verses" VALUES(1935293,2526,9,0,'طمع به قند وصال تو حد ما نبود','هوش مصنوعی: من به امید شیرینی وصال تو انتظار می‌کشیدم، اما حالا با این حال، به لب‌های زیبای تو که مانند شکر می‌باشند، ارجاع می‌دهم.',NULL);
INSERT INTO "verses" VALUES(1935294,2527,4,0,'پیران سخن ز تجربه گویند گفتمت','هوش مصنوعی: سالمندان به واسطه تجربیاتشان سخن می‌گویند. به تو، پسر، هشدار می‌دهم که وقتی پیر شدی، به نصیحت‌ها گوش بده.',NULL);
INSERT INTO "verses" VALUES(1935295,2520,3,0,'باده خور غم مخور و پند مقلد منیوش','هوش مصنوعی: نوشیدنی بنوش و نگران نباش و به نصیحت دیگران توجه نکن، زیرا ارزش صحبت‌های عامیانه چیست؟',NULL);
INSERT INTO "verses" VALUES(1935298,2522,4,0,'به مِیْ پرستی از آن نقشِ خود زدم بر آب','هوش مصنوعی: من به باده‌پرستی مشغول شدم و از روی نقشم بر آب نوشتم تا اینکه بتوانم تصویری که از خودم در ذهن دارم را ویران کنم.',NULL);
INSERT INTO "verses" VALUES(1935299,2522,3,1,'به دستِ مردمِ چشم از رخِ تو گل چیدن',NULL,NULL);
INSERT INTO "verses" VALUES(1935300,2522,3,0,'مرادِ دل ز تماشای باغِ عالم چیست؟','هوش مصنوعی: نیت دل از زیبایی‌های دنیا چه می‌تواند باشد، وقتی که مردم فقط برای برداشت زیبایی از چهره تو زمان می‌گذرانند؟',NULL);
INSERT INTO "verses" VALUES(1935301,2522,2,1,'بخواست جامِ می و گفت عیب پوشیدن',NULL,NULL);
INSERT INTO "verses" VALUES(1935302,2522,2,0,'به پیرِ میکده گفتم که چیست راه نجات','هوش مصنوعی: به پیر میکده پرسیدم که چگونه می‌توانم نجات پیدا کنم؟ او خواست تا جام شراب را بنوشم و گفت که عیب‌ها را باید پنهان کرد.',NULL);
INSERT INTO "verses" VALUES(1935303,2522,1,1,'که در طریقتِ ما کافریست رنجیدن',NULL,NULL);
INSERT INTO "verses" VALUES(1935304,2522,1,0,'وفا کنیم و ملامت کشیم و خوش باشیم','وفادار بمانیم و اگر دیگران ما را سرزنش کردند، باز هم خوشحال باشیم، چون در راه ما، غمگین بودن و رنجیدن کفر است',NULL);
INSERT INTO "verses" VALUES(1935305,2522,0,1,'منم که دیده نیالوده‌ام به بد دیدن',NULL,NULL);
INSERT INTO "verses" VALUES(1935306,2522,0,0,'منم که شهره شهرم به عشق ورزیدن','هوش مصنوعی: من در عشق ورزیدن مشهور و شناخته‌شده هستم. هرگز چشمم به بدی و ناپاکی گشوده نشده است.',NULL);
INSERT INTO "verses" VALUES(1935307,2521,6,1,'یا رب به یادش آور، درویش پروریدن',NULL,NULL);
INSERT INTO "verses" VALUES(1935308,2521,6,0,'گویی برفت حافظ، از یاد شاه‌ یحیی','هوش مصنوعی: به نظر می‌رسد که حافظ از یاد شاه یحیی رفته است. ای خدا، او را به یادش بیاور که درویشان را پرورش دهد.',NULL);
INSERT INTO "verses" VALUES(1935309,2521,5,1,'چون بگذریم دیگر، نتوان به هم رسیدن',NULL,NULL);
INSERT INTO "verses" VALUES(1935310,2521,5,0,'فرصت شمار صحبت، کز این دوراهه منزل','همدمی و صحبت و دوستی را غنیمت بشمار زیرا زندگی کوتاه است و دیگر همدیگر را نخواهیم دید. ( دوراهه منزل یعنی یک مسافت کوتاه. راه اصطلاح مسافرتی قدیم بوده است که پس از آن یک توقف و استراحت کوتاه انجام می‌شده‌است)',NULL);
INSERT INTO "verses" VALUES(1935311,2521,4,1,'کآخر ملول گردی، از دست و لب گزیدن',NULL,NULL);
INSERT INTO "verses" VALUES(1935312,2521,4,0,'بوسیدن لب یار، اول ز دست مگذار','هوش مصنوعی: بوسیدن لب معشوق را هرگز فراموش نکن، چرا که در نهایت اگر از این لذت‌ها دور بمانی، از زندگی و عشق خسته و دلزده می‌شوی.',NULL);
INSERT INTO "verses" VALUES(1935313,2521,3,1,'گه سِرّ عشق‌بازی، از بلبلان شنیدن',NULL,NULL);
INSERT INTO "verses" VALUES(1935314,2521,3,0,'گه چون نسیم با گل، راز نهفته گفتن','هوش مصنوعی: گاهی همچون نسیم با گل راز و رمزهایی را در میان می‌گذاریم و از بلبلان آواز عشق را می‌شنویم.',NULL);
INSERT INTO "verses" VALUES(1935315,2521,2,1,'وآنجا به نیک‌نامی، پیراهنی دریدن',NULL,NULL);
INSERT INTO "verses" VALUES(1935316,2521,2,0,'خواهم شدن به بستان، چون غنچه با دلِ تنگ','هوش مصنوعی: می‌خواهم به باغ بروم مثل غنچه‌ای که دلش پر از غم است و آنجا با نام نیک، پیراهنی را پاره کنم.',NULL);
INSERT INTO "verses" VALUES(1935317,2521,1,1,'از دوستان جانی، مشکل توان بریدن',NULL,NULL);
INSERT INTO "verses" VALUES(1935318,2521,1,0,'از جان طمع بریدن آسان بود ولیکن','هوش مصنوعی: بریدن امید از جان کار راحتی است، اما قطع رابطه با دوستانی که برایت عزیزند، بسیار دشوار است.',NULL);
INSERT INTO "verses" VALUES(1935319,2521,0,1,'در کوی او گدایی، بر خسروی گزیدن',NULL,NULL);
INSERT INTO "verses" VALUES(1935320,2521,0,0,'دانی که چیست دولت؟ دیدار یار دیدن','هوش مصنوعی: می‌دانی خوشبختی چیست؟ دیدن محبوب و عزیز خود در کوی او و انتخاب زندگی در دارایی اوست.',NULL);
INSERT INTO "verses" VALUES(1935321,2520,6,1,'تا جزای من بدنام چه خواهد بودن',NULL,NULL);
INSERT INTO "verses" VALUES(1935322,2520,6,0,'بردم از ره دل حافظ به دف و چنگ و غزل','هوش مصنوعی: با خوشی و شادی از طریق موسیقی و شعر دل مرا به سوی حافظ بردم تا ببینم عاقبت سرنوشت بدنامی من چه خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1935323,2520,5,1,'از خط جام، که فرجام چه خواهد بودن؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935324,2520,5,0,'پیر میخانه همی‌خواند معمایی دوش','هوش مصنوعی: روز گذشته، پیر میخانه از راز و رمز زندگی سخن می‌گفت و از نشان‌هایی که در جام شراب وجود داشت، پرسش می‌کرد که سرنوشت نهایی انسان چه خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1935325,2520,4,1,'دانی آخر که به ناکام چه خواهد بودن؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935326,2520,4,0,'دست‌رنج تو همان به که شود صرف به کام','هوش مصنوعی: بهتر است نتیجه زحمات خود را صرف لذت و خوشی‌ات کنی، زیرا می‌دانی در نهایت، اگر تلاش‌هایت بی‌نتیجه بماند، چه سرنوشتی خواهی داشت.',NULL);
INSERT INTO "verses" VALUES(1935327,2522,4,1,'که تا خراب کنم نقشِ خود پرستیدن',NULL,NULL);
INSERT INTO "verses" VALUES(1935328,2522,5,0,'به رحمتِ سرِ زلفِ تو واثقم ورنه','هوش مصنوعی: من به رحمت و زیبایی موی تو امیدوارم، وگرنه اگر جذبه‌ای از سوی تو نباشد، تلاش کردن چه فایده‌ای دارد؟',NULL);
INSERT INTO "verses" VALUES(1935329,2522,5,1,'کشش چو نَبوَد از آن سو چه سود کوشیدن؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935330,2522,6,0,'عنان به میکده خواهیم تافت زین مجلس','هوش مصنوعی: ما تصمیم داریم که در میکده حضور پیدا کنیم، زیرا در این محفل، شنیدن نصیحت‌های بی‌عمل، ضرورتی ندارد.',NULL);
INSERT INTO "verses" VALUES(1935340,2523,7,1,'دیّار نیست جز رُخَت اندر دیار حُسن',NULL,NULL);
INSERT INTO "verses" VALUES(1935341,2523,7,0,'حافظ طمع برید که بیند نظیر تو','هوش مصنوعی: حافظ از امید فرار می‌کند، زیرا می‌بیند که در دنیا مانند تو وجود ندارد و زیبایی‌ات تنها در سرزمین زیبایی‌ها می‌درخشد.',NULL);
INSERT INTO "verses" VALUES(1935342,2523,6,1,'کآب حیات می‌خورَد از جویبار حُسن',NULL,NULL);
INSERT INTO "verses" VALUES(1935343,2523,6,0,'گِرد لبَت بنفشه از آن تازه و تر است','هوش مصنوعی: گل‌های بنفشه اطراف لب‌های تو به قدری تازه و شاداب هستند که گویی از جویبار زیبایی زندگی می‌نوشند.',NULL);
INSERT INTO "verses" VALUES(1935344,2523,5,1,'می‌پرورَد به ناز، تو را در کنار حُسن',NULL,NULL);
INSERT INTO "verses" VALUES(1935346,2523,5,0,'دائم به لطف دایهٔ طبع از میانِ جان','هوش مصنوعی: همیشه به کمک و لطف طبیعت، تو را با عشق و ناز در کنار زیبایی می‌پرورانم و به زندگی می‌آورم.',NULL);
INSERT INTO "verses" VALUES(1935347,2523,4,0,'از دام زلف و دانهٔ خال تو در جهان','هوش مصنوعی: هیچ دل‌پروری در این دنیا باقی نمانده است که به دام زلف و درخشش خال تو نیفتاده باشد و در برابر زیبایی‌ات شکار نشده باشد.',NULL);
INSERT INTO "verses" VALUES(1935348,2523,3,1,'فرّخ شد از لطافت تو روزگار حُسن',NULL,NULL);
INSERT INTO "verses" VALUES(1935349,2523,3,0,'خرّم شد از ملاحت تو عهد دلبری','هوش مصنوعی: با زیبایی و دلربایی تو، زندگی خوش و خرم شده است و روزهای خوشی به خاطر لطافت و نرمی تو به وجود آمده است.',NULL);
INSERT INTO "verses" VALUES(1935350,2523,2,1,'سروی نخاست چون قَدَت از جویبار حُسن',NULL,NULL);
INSERT INTO "verses" VALUES(1935351,2523,2,0,'ماهی نتافت همچو تو از برج نیکویی','هوش مصنوعی: ماهی به آزادی و زیبایی تو نمی‌رسد، چون هیچ درختی به خوش‌اهمی به قامت تو نمی‌رسد.',NULL);
INSERT INTO "verses" VALUES(1935352,2523,1,1,'در زلف بی‌قرار تو پیدا قرار حُسن',NULL,NULL);
INSERT INTO "verses" VALUES(1935353,2523,1,0,'در چشم پرخمار تو پنهان فسون سِحر','هوش مصنوعی: چشم‌های خواب‌آلود تو دارای جادو و سحر است و در زلف‌های بی‌قرار تو زیبایی و آرامش مشاهده می‌شود.',NULL);
INSERT INTO "verses" VALUES(1935354,2523,0,1,'خال و خط تو مرکز حُسن و مدار حُسن',NULL,NULL);
INSERT INTO "verses" VALUES(1935355,2523,0,0,'ای روی ماه‌منظر تو نوبهار حُسن','هوش مصنوعی: ای چهره‌ات مانند ماه، بهار زیبایی توست و نشانه‌ها و خط‌های چهره‌ات مرکز و محور زیبایی هستند.',NULL);
INSERT INTO "verses" VALUES(1935356,2522,8,1,'که دستِ زهد فروشان خطاست بوسیدن',NULL,NULL);
INSERT INTO "verses" VALUES(1935357,2522,8,0,'مبوس جز لبِ ساقی و جامِ می حافظ','هوش مصنوعی: فقط لبِ ساقی و جامِ شراب ارزش بوسیدن دارند، زیرا بوسیدن چیزهایی که به غیر از این هستند، نادرست و بی‌معنی است.',NULL);
INSERT INTO "verses" VALUES(1935358,2522,7,1,'که گرد عارضِ خوبان خوش است گردیدن',NULL,NULL);
INSERT INTO "verses" VALUES(1935359,2522,7,0,'ز خطّ یار بیاموز مِهر با رخِ خوب','هوش مصنوعی: از خط یار بیاموز که چگونه عشق ورزیدن را، زیرا که گلابی بودن دور عارض زیبایان، دل‌انگیز است.',NULL);
INSERT INTO "verses" VALUES(1935360,2522,6,1,'که وعظ بی‌عملان واجب است نشنیدن',NULL,NULL);
INSERT INTO "verses" VALUES(1935361,2523,4,1,'یک مرغِ دل نماند نگشته شکار حُسن',NULL,NULL);
INSERT INTO "verses" VALUES(1935362,2576,2,1,'تو کز خورشید و مه آیینه داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935363,2544,8,0,'جان‌ها ز دام زلف چو بر خاک می‌فشاند','هوش مصنوعی: جان‌ها وقتی به زلف محبوب گرفتار می‌شوند، به زمین می‌افتند. اما بر آن غریبی که در این میان است، چه می‌گذرد؟ ای نسیم، آن را برای ما بگو.',NULL);
INSERT INTO "verses" VALUES(1935364,2544,9,0,'جان‌پرور است قصّهٔ ارباب معرفت','هوش مصنوعی: قصهٔ بزرگان علم و معرفت بسیار الهام‌بخش و روح‌نواز است. به آن‌ها رجوع کن و از رازهایشان بپرس، تا داستانی جدید از آن‌ها بشنوی.',NULL);
INSERT INTO "verses" VALUES(1935365,2566,1,0,'انفاس عیسی از لب لعلت لطیفه‌ای','نفَس حیات‌بخش عیسی‌، تنها کمی از سخنانی است که بر لب‌های سرخ تو جاری می‌شود و آب حیات خضر‌، جرعه‌ای از چشمه شیرین لب‌های توست.',NULL);
INSERT INTO "verses" VALUES(1935366,2566,0,1,'شرح جمال حور ز رویت روایتی',NULL,NULL);
INSERT INTO "verses" VALUES(1935367,2566,0,0,'ای قصهٔ بهشت ز کویت حکایتی','ای کسی که بهشت‌، تنها گوشه‌ای از کوچه توست و زیبایی حور بهشت‌‌، فقط چند کلمه از وصف زیبایی توست.',NULL);
INSERT INTO "verses" VALUES(1935368,2565,7,1,'تقدیر چنین بود، چه کردی که نهِشتی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935369,2565,7,0,'از دست چرا هِشت سرِ زلف تو حافظ؟','ای محبوب، حافظ چرا زلف تو را رها کرد و به وصال تو نرسید؟ تقدیر این چنین رقم زد وگرنه چه می توانست بکند اگر رها نمی کرد؟',NULL);
INSERT INTO "verses" VALUES(1935370,2565,6,1,'کو راهروی، اهلِ دلی، پاک‌سرشتی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935371,2565,6,0,'آلودگی خرقه، خرابی جهان است','اگر زاهدان و عابدان آلوده شوند، نه تنها خود را بلکه جهانی را آلوده می کنند؛ کجاست راهروی حقیقی؟ کجاست صاحب معرفتی؟ کجاست شخص پاک طینتی؟',NULL);
INSERT INTO "verses" VALUES(1935372,2565,5,1,'حیف است ز خوبی که شود عاشق زشتی',NULL,NULL);
INSERT INTO "verses" VALUES(1935373,2565,5,0,'تا کی غم دنیای دنی ای دل دانا؟','ای صاحب معرفت تا کی میخواهی غم دنیای پست و زبون را بخوری؟ حیف است که زیبا و پاکی چون تو عاشق و اسیر زشت و ناپاکی مانند دنیا شود.',NULL);
INSERT INTO "verses" VALUES(1935374,2565,4,1,'یک شیشه می و نوش‌لبی و لبِ کِشتی',NULL,NULL);
INSERT INTO "verses" VALUES(1935375,2565,4,0,'مفروش به باغ ارم و نخوت شداد','به خاطر باغ ارم و تکبر شداد بن عاد (وعده و وعید های زاهدان فریبکار) یک شیشه شراب نقد و یار شیرین لب و کنار کشتزار را از دست مده.',NULL);
INSERT INTO "verses" VALUES(1935376,2565,3,1,'چون بالش زر نیست، بسازیم به خشتی',NULL,NULL);
INSERT INTO "verses" VALUES(1935377,2565,3,0,'در مصطبهٔ عشق تنعم نتوان کرد','ایوانِ عشق جای تن‌آسانی و راحتی نیست ، اما حالا که بالش نرم و زر بافت نیست با خشتِ (زیر سر) می سازیم.',NULL);
INSERT INTO "verses" VALUES(1935378,2565,2,1,'یاری‌ست چو حوری و سرایی چو بهشتی',NULL,NULL);
INSERT INTO "verses" VALUES(1935379,2565,2,0,'آمرزش نقد است کسی را که در این جا','هرکس که در این دنیا یاری به زیبایی حوریان بهشتی و سرایی مانند خانه های بهشتی داشته باشد پیش از آنکه از دنیا برود آمرزیده شده است.',NULL);
INSERT INTO "verses" VALUES(1935380,2565,1,1,'دهقان جهان! کاش که این تخم نکِشتی',NULL,NULL);
INSERT INTO "verses" VALUES(1935381,2565,1,0,'هر چند که هجران ثمر وصل برآرد','هرچند که فراق باعث به ثمر رسیدن میوه ی وصال می شود اما ای کاش خالق هستی هیچوقت تخم هجران را در جهان نمی کاشت.',NULL);
INSERT INTO "verses" VALUES(1935382,2565,0,1,'گردون ورق هستی ما درننوشتی',NULL,NULL);
INSERT INTO "verses" VALUES(1935383,2565,0,0,'آن غالیه‌خط گر سوی ما نامه نوشتی','اگر آن یار خوش خط و خوش بو برای ما نامه ای می‌نوشت ، روزگار هم طومار وجود ما را در هم نمی‌پیچید.',NULL);
INSERT INTO "verses" VALUES(1935384,2564,6,1,'چون برق، از این کشاکش، پنداشتی که جستی',NULL,NULL);
INSERT INTO "verses" VALUES(1935385,2564,6,0,'عشقت، به دستِ طوفان، خواهد سپرد حافظ','عشق تو حافظ را به دست طوفان خواهد سپرد. حافظا فکر می‌کنی که از این کشاکش می‌توانی بمانند برق بجهی؟',NULL);
INSERT INTO "verses" VALUES(1935386,2564,5,1,'کز سرکشی، زمانی، با ما نمی‌نشستی',NULL,NULL);
INSERT INTO "verses" VALUES(1935387,2564,5,0,'آن روز دیده بودم، این فتنه‌ها که برخاست','سلطان من، در مراقبه/رویا دیده بودم، همان روز که [با نگاه به چشمانم] فتنه برانگیختی، سرکشی خواهی کرد و با ما همنشین نخواهی شد.',NULL);
INSERT INTO "verses" VALUES(1935388,2564,4,1,'تا نرگسِ تو با ما، گوید رموزِ مستی',NULL,NULL);
INSERT INTO "verses" VALUES(1935389,2564,4,0,'در گوشهٔ سلامت، مستور چون توان بود','آنجایی که چشم تو، بدون استفاده از کلام، رموز هستی را به ما می‌گوید، چگونه می‌توان در گوشه‌ای خود را پنهان کرد تا در امنیت بود؟',NULL);
INSERT INTO "verses" VALUES(1935390,2564,3,1,'تا کِی کُنَد سیاهی، چندین درازدستی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935391,2564,3,0,'سلطانِ من خدا را، زُلفَت شکست ما را','ای سلطان من، ترا به خدا سوگند می‌دهم [رحمی کن]، آخر زلف سیاه تو ما (بتان/داشته‌ها) را شکست! تا کی باید شب فراق تو (زلف سیاه، سیاهی) به داشته‌های پندارگونهٔ ما بتازد؟',NULL);
INSERT INTO "verses" VALUES(1935392,2564,2,1,'«با کافران چه کارت؟ گر بت نمی‌پرستی»',NULL,NULL);
INSERT INTO "verses" VALUES(1935393,2564,2,0,'دوش آن صنم چه خوش گفت، در مجلسِ مُغانَم','دیروز آن بت در جمع مغان، چه زیبا گفت: «با کافران چه کار داری اگر بتی را نمی‌پرستی؟»',NULL);
INSERT INTO "verses" VALUES(1935394,2566,1,1,'آب خضر ز نوش لبانت کنایتی',NULL,NULL);
INSERT INTO "verses" VALUES(1935395,2564,1,1,'ناخوانده نقشِ مقصود، از کارگاهِ هستی',NULL,NULL);
INSERT INTO "verses" VALUES(1935396,2566,2,0,'هر پاره از دل من و از غصه قصه‌ای','هوش مصنوعی: هر قسمت از دل من داستانی پر از غم و اندوه دارد و هر خط از ویژگی‌های تو نشانه‌ای از رحمت و لطف است.',NULL);
INSERT INTO "verses" VALUES(1935397,2566,3,0,'کی عطرسای مجلس روحانیان شدی؟','هوش مصنوعی: کی بودی که در مجالس روحانیان مثل عطر پخش شوی؟ اگر گل را بوی خوش تو نرسد، چه ارزشی خواهد داشت؟',NULL);
INSERT INTO "verses" VALUES(1935398,2568,0,1,'کز عکس روی او شب هجران سر آمدی',NULL,NULL);
INSERT INTO "verses" VALUES(1935399,2568,0,0,'دیدم به خواب دوش که ماهی برآمدی','دیشب در خواب دیدم که ماهی (کنایه از معشوق زیبارو) طلوع کرد،که با درخشش چهره‌اش شبِ هجران پایان یافت.',NULL);
INSERT INTO "verses" VALUES(1935400,2567,7,1,'بِلَیلٍ مُظْلِمٍ وَ اللّهُ هادي',NULL,NULL);
INSERT INTO "verses" VALUES(1935401,2567,7,0,'دل حافظ شد اندر چین زلفت','عارف:(معنی تحت لفظی)دلِ حافظ شد در چینِ زلفِ تو، همچون شبِ تاریک، و خدا راهنمای است./(معنی مفهومی)دلِ حافظ در پیچ‌و‌تابِ زلفِ یار گرفتار آمد، مانند شبِ ظلمانی، و تنها خدا راهنمایِ ماست.',NULL);
INSERT INTO "verses" VALUES(1935402,2567,6,1,'و غَر نه او بِنی آنچَت نَشادی',NULL,NULL);
INSERT INTO "verses" VALUES(1935403,2567,6,0,'غم این دل بِواتَت خورد ناچار','عارف:(معنی تحت لفظی)غم این دل باید بر تو وارد شود ناچار، وگرنه او بازبینی آنچه تو را نپسندیدی./(معنی مفهومی)این غمِ دل ناگزیر باید بر تو وارد شود، وگرنه آنچه شایسته تو نیست، خواهی دید.',NULL);
INSERT INTO "verses" VALUES(1935404,2567,5,1,'غَرَت یک وی رَوِشتی از اَما دی',NULL,NULL);
INSERT INTO "verses" VALUES(1935405,2567,5,0,'به پی‌ماچان غَرامت بِسپُریمَن','عارف:(معنی تحت لفظی)به دنبالِ «ماچان» غرامت می‌سپاریم، اگر تو یک روز (وی = یک بار) بی‌روشی از ما دیدی/(معنی مفهومی) در پیِ کارِ «ماچان» (صفِ کفش‌ کنِ درویشان) غرامتی می‌دهیم، اگر که یک‌بار عملِ ناشایستی از ما سر زَد.',NULL);
INSERT INTO "verses" VALUES(1935406,2567,4,1,'غَریقُ الْعِشقِ في بَحْرِ الْوِدادِ',NULL,NULL);
INSERT INTO "verses" VALUES(1935407,2567,4,0,'که همچون مُت به بوتَن دل وَ اِی رَه','عارف:(معنی تحت لفظی)ایکه همچون «متّ» در بودنِ دل و ای راه، غریقِ عشق در دریاچه‌ی محبت است./(معنی مفهومی). چنان‌که منم در حالِ غرق‌شدن در عشق، دل همچون قایقی در دریای مهربانی غوطه‌ور است.',NULL);
INSERT INTO "verses" VALUES(1935408,2567,3,1,'تُزَاوَّل آن روی نِهْکو بِوادی',NULL,NULL);
INSERT INTO "verses" VALUES(1935409,2567,3,0,'أَ مَنْ اَنْکَرْتَني عَن عشق سَلْمیٰ','عارف:(معنی تحت لفظی)آیا کسی که من را از عشق «سلمی» انکار کردی؟ تو از اول، آن رخِ نیکو را در بادیه (در صحرا) تظاهر کردی./(معنی مفهومی)آیا تو مرا از عشق «سلمی» انکار کردی؟ از ابتدا روی آن رخِ نیکو را در بادیه نمایاندی (ظاهراً به‌ظاهر دوست بودی). به غیر',NULL);
INSERT INTO "verses" VALUES(1935410,2567,2,1,'تَوَکَّلْنا علی رَبِّ الْعِبادِ',NULL,NULL);
INSERT INTO "verses" VALUES(1935411,2567,2,0,'حبیبا در غم سودای عشقت','عارف:(معنی تحت لفظی). ای محبوب در غمِ سودای عشقت، ما بر خداوندِ بندگان تکیه کردیم./(معنی مفهومی)ای محبوبِ عزیز، در غمِ هجران تو ما تسلیم و توکّل به خدای بندگان کردیم.',NULL);
INSERT INTO "verses" VALUES(1935412,2567,1,1,'و واصِلْني علی رَغْمِ الْأَعادي',NULL,NULL);
INSERT INTO "verses" VALUES(1935413,2567,1,0,'نگارا بر من بی‌دل ببخشای','عارف:(معنی تحت لفظی)ای نگارا بر منِ بی‌دل ببخشای و مرا به وصال برسان علی‌رغمِ دشمنان./(معنی مفهومی)ای زیبارو، بر این دلِ بی‌پناه منت بگذار و مرا با وجود دشمنان به وصلِ خویش رسان',NULL);
INSERT INTO "verses" VALUES(1935414,2567,0,1,'و رُوحي کُلَّ یَومٍ لي یُنادي',NULL,NULL);
INSERT INTO "verses" VALUES(1935415,2567,0,0,'سَبَتْ سَلْمیٰ بِصُدْغَیها فُؤادي','عارف:(معنی تحت و لفظی)معشوقه «سلمی» با آن دو زلفش، دلِ من را اسیر کرد و روحِ من هر روز مرا ندا می‌دهد/(معنای مفهومی),. معشوقه با زلفان خویش دل مرا به اسارت کشید و اکنون روح من هر لحظه مرا به سوی او دعوت می‌کند.',NULL);
INSERT INTO "verses" VALUES(1935416,2566,8,1,'از تو کرشمه‌ای و ز خسرو عنایتی',NULL,NULL);
INSERT INTO "verses" VALUES(1935417,2566,8,0,'دانی مراد حافظ از این درد و غصه چیست؟','هوش مصنوعی: می‌دانی حافظ از این غم و اندوه چه هدفی دارد؟ او به یک اشاره از تو و به توجهی از خسرو نیازمند است.',NULL);
INSERT INTO "verses" VALUES(1935418,2566,7,1,'ساقی بیا که نیست ز دوزخ شکایتی',NULL,NULL);
INSERT INTO "verses" VALUES(1935419,2566,7,0,'در آتش ار خیال رخش دست می‌دهد','هوش مصنوعی: اگر خیال چهره‌اش در دلم شعله‌ور شود، ای ساقی، بیا که از جهنم هیچ شکایتی ندارم.',NULL);
INSERT INTO "verses" VALUES(1935420,2566,6,1,'این آتش درون بکند هم سرایتی',NULL,NULL);
INSERT INTO "verses" VALUES(1935421,2566,6,0,'بوی دل کباب من آفاق را گرفت','هوش مصنوعی: بوی دل سوخته‌ام تا دوردست‌ها پیچید و این آتش درونم به زودی همه جا را در بر خواهد گرفت.',NULL);
INSERT INTO "verses" VALUES(1935422,2566,5,1,'صد مایه داشتی و نکردی کفایتی',NULL,NULL);
INSERT INTO "verses" VALUES(1935423,2566,5,0,'ای دل به هرزه دانش و عمرت به باد رفت','ای عزیز، عمر گرانبهای تو و دانایی تو بیهوده تلف شد؛ صد مایه و امکان داشتی اما شایستگی و کفایت نشان ندادی.',NULL);
INSERT INTO "verses" VALUES(1935424,2566,4,1,'یاد آور ای صبا که نکردی حمایتی',NULL,NULL);
INSERT INTO "verses" VALUES(1935425,2566,4,0,'در آرزوی خاک در یار سوختیم','هوش مصنوعی: ما در حسرت حضور یارمان سوختیم، ای نسیم! یادآوری کن که تو هیچ حمایتی از ما نکردی.',NULL);
INSERT INTO "verses" VALUES(1935426,2566,3,1,'گل را اگر نه بوی تو کردی رعایتی',NULL,NULL);
INSERT INTO "verses" VALUES(1935427,2566,2,1,'هر سطری از خصال تو و از رحمت آیتی',NULL,NULL);
INSERT INTO "verses" VALUES(1935428,2564,1,0,'عاشق شو اَر نَهْ روزی، کارِ جهان سرآید','عاشق شو، چون اگر عاشق نشوی، روزی خواهد رسید که کار دنیا به پایان می‌رسد و پیش از کشف هدف و مقصود زندگی‌ات بدون اینکه متوجه شوی، از جهان می‌روی.',NULL);
INSERT INTO "verses" VALUES(1935429,2564,0,1,'تا بی‌خبر بمیرد، در دردِ خودپرستی',NULL,NULL);
INSERT INTO "verses" VALUES(1935430,2564,0,0,'با مدّعی مگویید، اسرارِ عشق و مستی','با مدعیان؛ از عشق و رازهای آن صحبت نکنید، تا به خاطر خودخواهی و خودپرستی خود از عشق دور بمانند.',NULL);
INSERT INTO "verses" VALUES(1935431,2562,3,1,'زان میان پروانه را در اضطراب انداختی',NULL,NULL);
INSERT INTO "verses" VALUES(1935432,2562,3,0,'هرکسی با شمع رخسارت به وجهی عشق باخت','هوش مصنوعی: هر کسی که با زیبایی صورت تو آشنا شد، به عشق تو دل باخت و این امر باعث شد پروانه‌ای که به دور شمع می‌چرخید، در اضطراب و دو دلی بیفتد.',NULL);
INSERT INTO "verses" VALUES(1935433,2562,2,1,'جام کیخسرو طلب، کافراسیاب انداختی',NULL,NULL);
INSERT INTO "verses" VALUES(1935434,2562,2,0,'گویِ خوبی بردی از خوبانِ خَلَّخ شاد باش','شاد باش که از تمام خوبرویان خلخی، زیباتر هستی؛ جام کیخسروی بر دست بگیر که افراسیاب را شکست‌دادی.',NULL);
INSERT INTO "verses" VALUES(1935435,2562,1,1,'حالیا نیرنگ نقشی خوش بر آب انداختی',NULL,NULL);
INSERT INTO "verses" VALUES(1935436,2562,1,0,'تا چه خواهد کرد با ما آب و رنگ عارضت','هوش مصنوعی: در مورد زیبایی و جذابیت چهره‌ات، نمی‌دانیم که سرنوشت با ما چه خواهد کرد. در حال حاضر، با ترفند و نیرنگ، تصویری زیبا بر روی آب ایجاد کرده‌ای.',NULL);
INSERT INTO "verses" VALUES(1935437,2562,0,1,'لطف کردی سایه‌ای بر آفتاب انداختی',NULL,NULL);
INSERT INTO "verses" VALUES(1935438,2562,0,0,'ای که بر ماه از خط مشکین نقاب انداختی','هوش مصنوعی: ای کسی که با خط مشکی‌ات بر روی ماه پرده‌ای کشیدی، به ما لطف کردی و سایه‌ای بر خورشید افکندی.',NULL);
INSERT INTO "verses" VALUES(1935439,2561,5,1,'کی تشنه سیر گردد، از لمعهٔ سرابی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935440,2561,5,0,'حافظ چه می‌نهی دل، تو در خیال خوبان','حافظ [تو که می‌دانی که به وصال معشوق پس] چرا دل به خیال و رویای [وصال] خوب‌رویان (معشوقان) می‌دهی! [این مثل این است که بپرسی] کی تشنگی یک انسان تشنه از درخشش (لعمه) یک سراب رفع شده است؟',NULL);
INSERT INTO "verses" VALUES(1935441,2561,4,1,'بیمار آن دو لعلم، آخر کم از جوابی',NULL,NULL);
INSERT INTO "verses" VALUES(1935442,2561,4,0,'مخمور آن دو چشمم، آیا کجاست جامی؟','تشنهٔ دیدارآن دو چشم [فریبنده چون شراب] هستم. جامی از شراب [چشمانت] کجاست تا بنوشم؟ از بس که از آن دو لب زیبا (دهان) جوابی نگرفتم، بیمار و خراب شده‌ام.',NULL);
INSERT INTO "verses" VALUES(1935443,2561,3,1,'در عشوهٔ وصالت، ما و خیال و خوابی',NULL,NULL);
INSERT INTO "verses" VALUES(1935444,2561,3,0,'در انتظار رویت، ما و امیدواری','در انتظار دیدار رخسار تو همچنان امیدوار هستیم. در حسرت شیرینی وصال تو، ما [هر شب] در رویاهای خیال‌انگیز فرو می‌رویم.',NULL);
INSERT INTO "verses" VALUES(1935445,2561,2,1,'زین در دگر نراند، ما را به هیچ بابی',NULL,NULL);
INSERT INTO "verses" VALUES(1935446,2561,2,0,'شد حلقه، قامت من، تا بعد از این رقیبت','قامت من [از دیدن جفا و بی‌مهری خمیده شده و] به شکل حلقهٔ در [معشوق] چسبیده تا نگاهبان معشوق نتواند مرا از این درگاه جدا کرده و به درگاه دیگری براند.',NULL);
INSERT INTO "verses" VALUES(1935447,2561,1,1,'مطرب بزن نوایی، ساقی بده شرابی',NULL,NULL);
INSERT INTO "verses" VALUES(1935448,2561,1,0,'وصف رخ چو ماهش، در پرده راست نآید','نمی‌توان زیبایی‌های صورت چون قرص ماه یار (معشوق) با در خفا و درگوشی گفتن (با ایما و اشاره گفتن) شرح و توصیف کرد. مطرب آهنگی بزن، ساقی شرابی بیاور [تا مجلس گرم شود و من بتوانم در عالم مستی و بی‌ریایی به توصیف زیبایی‌های یار بپردازم].',NULL);
INSERT INTO "verses" VALUES(1935449,2561,0,1,'پُر کن قدح که بی مِی، مجلس ندارد آبی',NULL,NULL);
INSERT INTO "verses" VALUES(1935450,2561,0,0,'مخمور جام عشقم، ساقی بده شرابی','ساقی شراب بیاور که خمارآلود جام عشق هستم (تشنهٔ محبت و توجه یار هستم). جام شراب را پر کن که مجلس بدون شراب، صفایی ندارد.',NULL);
INSERT INTO "verses" VALUES(1935451,2560,8,1,'حدیث بی‌زبانان بشنو از نی',NULL,NULL);
INSERT INTO "verses" VALUES(1935452,2560,8,0,'زبانت درکِش ای حافظ زمانی','هوش مصنوعی: ای حافظ، زبان تو را سرزنش کن و لحظه‌ای به سخنان بی‌زبانان گوش بده تا مثل نی درک و احساس آنها را دریابی.',NULL);
INSERT INTO "verses" VALUES(1935453,2560,7,1,'که باشد خونِ جامش در رگ و پی',NULL,NULL);
INSERT INTO "verses" VALUES(1935454,2560,7,0,'نجوید جان از آن قالب جدایی','هوش مصنوعی: روح خود را از آن قالب جدا نکن که خونش در رگ و پی وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1935455,2560,6,1,'به یاد لعلش ای ساقی بده می',NULL,NULL);
INSERT INTO "verses" VALUES(1935456,2560,6,0,'چو چشمش مست را مخمور مگذار','هوش مصنوعی: چشمانش را مانند کسی که مست و مدهوش است، بی‌خود نکن. ای ساقی، به یاد زیبایی لبهایش، می بده.',NULL);
INSERT INTO "verses" VALUES(1935457,2560,5,1,'بساط زهد همچون غنچه کن طی',NULL,NULL);
INSERT INTO "verses" VALUES(1935458,2560,5,0,'گل از خلوت به باغ آورد مسند','هوش مصنوعی: گل از تنهایی و دوری به باغ آورده می‌شود و فضای زهد را همانند غنچه‌ای تازه و زیبا آماده می‌کند.',NULL);
INSERT INTO "verses" VALUES(1935459,2560,4,1,'رگش بخراش تا بخروشم از وی',NULL,NULL);
INSERT INTO "verses" VALUES(1935460,2562,4,0,'گنج عشق خود نهادی در دل ویران ما','هوش مصنوعی: عشق تو را در دل خالی و ویران ما قرار دادی و سایه خوشبختی‌ات را بر این مکان خراب انداختی.',NULL);
INSERT INTO "verses" VALUES(1935461,2562,4,1,'سایهٔ دولت بر این کنج خراب انداختی',NULL,NULL);
INSERT INTO "verses" VALUES(1935462,2562,5,0,'زینهار از آب آن عارض که شیران را از آن','هوش مصنوعی: هرگز به آب آن چهره زیبا نزدیک نشو که شیران را از آن تشنه کرده و دشمنان را در آب غرق کرده است.',NULL);
INSERT INTO "verses" VALUES(1935463,2562,5,1,'تشنه‌لب کردی و گردان را در آب انداختی',NULL,NULL);
INSERT INTO "verses" VALUES(1935464,2563,7,1,'ای کوته‌آستینان تا کی درازدستی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935465,2563,7,0,'صوفی پیاله‌پیما حافظ قرابه‌‌پرهیز','آیا صوفی باده‌نوش باشد و حافظ از باده بپرهیزد؟! ای کوته‌آستینان (کنایه از صوفیان) تا کی ظلم و جور می‌کنید و مردم را از آنچه خودتان انجام می‌دهید‌، منع می‌کنید؟',NULL);
INSERT INTO "verses" VALUES(1935466,2563,6,1,'سهل است تلخی می در جنب ذوق مستی',NULL,NULL);
INSERT INTO "verses" VALUES(1935467,2563,6,0,'خار ارچه جان بکاهد گل عذر آن بخواهد','گر چه خار با آزار و اذیت است، ولی گل از طرف او عذر‌خواهی می‌کند (زیبایی گل‌، تیزی و اذیت خار را محو می‌کند) این مسأله اصلاً سخت نیست چون تلخی شراب کنار لذت و شور مستی به راحتی قابل تحمل است.',NULL);
INSERT INTO "verses" VALUES(1935468,2563,5,1,'کز اوج سربلندی افتی به خاک پستی',NULL,NULL);
INSERT INTO "verses" VALUES(1935469,2563,5,0,'در آستان جانان از آسمان میندیش','وقتی به آستان یار (و خاک کوی یار) رسیدی از فلک و آسمان میندیش و هراس‌نداشته باش زیرا (در غیر اینصورت) از اوج سربلندی و افتخار بر خاک پستی میفتی.',NULL);
INSERT INTO "verses" VALUES(1935470,2563,4,1,'یک نکته‌ات بگویم خود را مبین که رستی',NULL,NULL);
INSERT INTO "verses" VALUES(1935471,2563,4,0,'تا فضل و عقل بینی بی‌معرفت نشینی','تا وقتی فضل و عقل خود را ببینی و به‌آن مغرور باشی، بی‌معرفت خواهی ماند؛ یک پند به‌تو می‌گویم که تو را نجات خواهد داد «خود را مبین»',NULL);
INSERT INTO "verses" VALUES(1935472,2563,3,1,'آری طریقِ دولت چالاکی است و چستی',NULL,NULL);
INSERT INTO "verses" VALUES(1935473,2563,3,0,'در مذهب طریقت خامی نشان کفر است','در مذهب سیر و سلوک، ناپختگی نشانه‌ای از بی‌ایمانی است. بله، مسیر دستیابی به موفقیت، نیازمند تیزهوشی و سرعت عمل است.',NULL);
INSERT INTO "verses" VALUES(1935474,2563,2,1,'بیماری اندر این ره بهتر ز تندرستی',NULL,NULL);
INSERT INTO "verses" VALUES(1935475,2563,2,0,'با ضعف و ناتوانی همچون نسیم خوش باش','حافظ حرکت نسیم را ضعیف و ناتوان ولی شاد تصور کرده و می گوید:« همچون نسیم در عین ضعف و ناتوانی شادمان و خوش باش زیرا که در راه عشق ناتوانی بهتر از تندرستی و سلامت است».',NULL);
INSERT INTO "verses" VALUES(1935476,2563,1,1,'هر قبله‌ای که بینی بهتر ز خودپرستی',NULL,NULL);
INSERT INTO "verses" VALUES(1935477,2563,1,0,'گر جان به تن ببینی مشغول کار او شو','گر جان به تن ببینی مشغول کار او شو زیرا به هر جانبی که روی آوری و به هر‌چه عشق بورزی‌، نکوتر و بهتر از خودپرستی است.',NULL);
INSERT INTO "verses" VALUES(1935478,2568,1,0,'تعبیر رفت «یار سفرکرده می‌رسد»','تعبیر خواب این بود که یار سفرکرده بازخواهد گشت،ای کاش هرچه زودتر از در خانه‌ام وارد می‌شدی',NULL);
INSERT INTO "verses" VALUES(1935479,2563,0,1,'وآنگه برو که رستی از نیستی و هستی',NULL,NULL);
INSERT INTO "verses" VALUES(1935480,2562,12,1,'از دم شمشیر چون آتش در آب انداختی',NULL,NULL);
INSERT INTO "verses" VALUES(1935481,2562,12,0,'نصرة الدّین شاه یحیی آن که خصم ملک را','هوش مصنوعی: یاری دین شاه یحیی، کسی که دشمنان پادشاهی را با شمشیرش مانند آتش در آب خنثی کرد.',NULL);
INSERT INTO "verses" VALUES(1935482,2562,11,1,'از سر تعظیم بر خاک جناب انداختی',NULL,NULL);
INSERT INTO "verses" VALUES(1935483,2562,11,0,'داور داراشکوه‌ ای آن که تاج آفتاب','هوش مصنوعی: داور با بزرگی و شکوه، تو که تاج افتخار را به احترام بر خاک گذاشتی.',NULL);
INSERT INTO "verses" VALUES(1935484,2562,10,1,'چون کمند خسرو مالک رقاب انداختی',NULL,NULL);
INSERT INTO "verses" VALUES(1935485,2562,10,0,'وز برای صید دل در گردنم زنجیر زلف','هوش مصنوعی: برای به دام انداختن دل من، زنجیری از موهایت را به گردنم انداختی، مانند کمندی که خسرو بر گردن شکارش می‌اندازد.',NULL);
INSERT INTO "verses" VALUES(1935486,2562,9,1,'حافظ خلوت‌نشین را در شراب انداختی',NULL,NULL);
INSERT INTO "verses" VALUES(1935487,2562,9,0,'از فریب نرگس مخمور و لعل مِی‌پرست','هوش مصنوعی: چشم‌های seductive و دلربای و زیبای نرگس و همچنین عشق به شراب، حافظ را که عاشق خلوت و تنهایی است، در دام خوشی و نوشیدن شراب انداختی.',NULL);
INSERT INTO "verses" VALUES(1935488,2562,8,1,'شاهد مقصود را از رخ نقاب انداختی',NULL,NULL);
INSERT INTO "verses" VALUES(1935489,2562,8,0,'باده نوش از جام عالم بین که بر اورنگ جم','هوش مصنوعی: از جام عالم بنوش و به تماشای زیبایی‌های آن بپرداز، چون بر تخت جمشید، حقیقت را از پس پرده‌ای که بر چهره‌اش بود، کنار زده‌ای.',NULL);
INSERT INTO "verses" VALUES(1935490,2562,7,1,'وز حیا حور و پری را در حجاب انداختی',NULL,NULL);
INSERT INTO "verses" VALUES(1935491,2562,7,0,'پرده از رخ برفکندی یک نظر در جلوه‌گاه','هوش مصنوعی: چهره‌ات را بلند کردی و از زیبایی‌ات یک نگاه به دیگران کردی، و با حیا، فرشتگان و زیبارویان را در پوشش و حجاب قرار دادی.',NULL);
INSERT INTO "verses" VALUES(1935492,2562,6,1,'تهمتی بر شب‌روان خیل خواب انداختی',NULL,NULL);
INSERT INTO "verses" VALUES(1935493,2562,6,0,'خواب بیداران ببستی وآن گه از نقش خیال','هوش مصنوعی: تو خواب بینندگان را می‌پوشانی و سپس با خیال‌پردازی‌ات، اتهامی به شب‌زنده‌داران می‌زنی که خواب را بر آن‌ها غالب می‌کنی.',NULL);
INSERT INTO "verses" VALUES(1935494,2563,0,0,'ای دل مباش یک دم خالی ز عشق و مستی','ای دل، هرگز بدون عشق و سرمستی نباش، و زمانی که به این حال دست یافتی، نجات یافته‌ای زیرا که از بودن و نبودن و تعلقات مادی رسته‌ای و رهایی یافته‌ای.',NULL);
INSERT INTO "verses" VALUES(1935495,2568,1,1,'ای کاج هر چه زودتر از در درآمدی',NULL,NULL);
INSERT INTO "verses" VALUES(1935496,2568,2,0,'ذکرش به خیر ساقی فرخنده‌فال من','یادش به‌خیر باد آن ساقی خوش‌اقبال منکه همیشه با جام و ساغر شراب وارد می‌شد.',NULL);
INSERT INTO "verses" VALUES(1935497,2568,2,1,'کز در مدام با قدح و ساغر آمدی',NULL,NULL);
INSERT INTO "verses" VALUES(1935498,2574,3,1,'سوادی از خط مشکین بر ارغوان داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935499,2574,3,0,'بیاضِ رویِ تو را، نیست نقشِ دَرخور از آنک','هوش مصنوعی: رنگ روشنی که روی توست، هیچ تصویری نمی‌تواند زیبایی آن را نشان دهد؛ چرا که تو در کنار آن، نوشته‌ای سیاه بر زمینه‌ای ارغوانی داری که توجه همه را جلب می‌کند.',NULL);
INSERT INTO "verses" VALUES(1935500,2574,2,1,'میان مجمع خوبان کنی میان‌داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935501,2574,2,0,'میان نداری و دارم عجب که هر ساعت','هوش مصنوعی: در حالتی که من چیزی ندارم و تو داری، جای تعجب این است که تو هر ساعت در جمع آدم‌های خوب، من را به عنوان کسی که دارای جایگاه ویژه‌ای هستم، معرفی می‌کنی.',NULL);
INSERT INTO "verses" VALUES(1935502,2574,1,1,'که حکم بر سر آزادگان روان داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935503,2574,1,0,'بخواه جان و دل از بنده و روان بستان','هوش مصنوعی: از من بخواه که جان و دل را به تو بسپارم و روحم را بگیر، زیرا تو بر سر سرنوشت آزادگان حکم می‌کنی.',NULL);
INSERT INTO "verses" VALUES(1935504,2574,0,1,'چه غم ز حال ضعیفان ناتوان داری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935505,2574,0,0,'تو را که هر چه مراد است در جهان داری','هوش مصنوعی: تو که تمام آرزوهایت را در زندگی داری، چرا نگران حال کسانی هستی که توانایی ندارند و ضعیف هستند؟',NULL);
INSERT INTO "verses" VALUES(1935506,2573,7,1,'مشکل توان نشستن در این چنین دیاری',NULL,NULL);
INSERT INTO "verses" VALUES(1935507,2573,7,0,'هر تار موی حافظ در دست زلفِ شوخی','هوش مصنوعی: هر رشته از موی حافظ در دست زلف معشوقی است که نمی‌توان در چنین جایی آرامش یافت.',NULL);
INSERT INTO "verses" VALUES(1935508,2573,6,1,'دردی و سخت دردی، کاری و صعب کاری',NULL,NULL);
INSERT INTO "verses" VALUES(1935509,2573,6,0,'چون این گره گشایم؟ وین راز چون نمایم؟','هوش مصنوعی: زمانی که این مشکل را حل کنم و این راز را افشا کنم، دردی عمیق و کار دشواری را تجربه خواهم کرد.',NULL);
INSERT INTO "verses" VALUES(1935510,2573,5,1,'هر یک گرفته جامی بر یادِ رویِ یاری',NULL,NULL);
INSERT INTO "verses" VALUES(1935511,2573,5,0,'در بوستان حریفان مانند لاله و گل','هوش مصنوعی: در باغ دوستان، هر یک از آنها مانند لاله و گل هستند و هر کدام جامی در دست دارند که به یاد چهره محبوبشان سر می‌کشند.',NULL);
INSERT INTO "verses" VALUES(1935512,2573,4,1,'سال دگر که دارد امّید نوبهاری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935513,2573,4,0,'مِی بی‌غش است دریاب، وقتی خوش است بشتاب','هوش مصنوعی: شراب خالصی وجود دارد، آن را در لحظات خوش ببر، چون سال آینده ممکن است فرصتی برای شادمانی نداشته باشی.',NULL);
INSERT INTO "verses" VALUES(1935514,2573,3,1,'کم غایت توقع بوسی‌ست یا کناری',NULL,NULL);
INSERT INTO "verses" VALUES(1935515,2573,3,0,'چون من شکسته‌ای را از پیش خود چه رانی؟','هوش مصنوعی: وقتی که من کسی را که در دلش شکسته است، از خود دور می‌کنی، چرا این کار را می‌کنی؟ آیا انتظاراتت از او کم است یا فقط در پی فاصله گرفتن هستی؟',NULL);
INSERT INTO "verses" VALUES(1935516,2573,2,1,'بر دامنش مبادا زین خاکیان غباری',NULL,NULL);
INSERT INTO "verses" VALUES(1935517,2573,2,0,'هرگز که دیده باشد جسمی ز جان مُرَکَّب؟','هوش مصنوعی: هرگز نباید جسمی که از روح تشکیل شده، تحت تأثیر و آلودگی دنیوی قرار بگیرد. نباید اجازه دهیم که این موجودات مادی بر وجود او تأثیری منفی بگذارند.',NULL);
INSERT INTO "verses" VALUES(1935518,2573,1,1,'در دست کس نیفتد زین خوب‌تر نگاری',NULL,NULL);
INSERT INTO "verses" VALUES(1935519,2573,1,0,'چشم فلک نبیند زین طُرفه‌تر جوانی','هوش مصنوعی: چشم آسمان چنین جوانی را نمی‌بیند که در دست کسی نیفتد، و همچنین هیچ نگاری به این زیبایی پیدا نمی‌شود.',NULL);
INSERT INTO "verses" VALUES(1935520,2573,0,1,'یاران! صلای عشق است گر می‌کنید کاری',NULL,NULL);
INSERT INTO "verses" VALUES(1935521,2573,0,0,'شهری‌ست پُر ظریفان وز هر طرف نگاری','هوش مصنوعی: شهری است پر از انسان‌های با ذوق و زیبا، و از هر سو اشخاصی دوست‌داشتنی دیده می‌شوند! اگر در این فضا کاری برای عشق انجام می‌دهید، بس نیکوست.',NULL);
INSERT INTO "verses" VALUES(1935522,2572,6,1,'به خنده گفت که «ای حافظ! این چه پرگاری»',NULL,NULL);
INSERT INTO "verses" VALUES(1935523,2572,6,0,'چو نقطه گفتمش «اندر میان دایره آی»','هوش مصنوعی: وقتی به او گفتم که مانند یک نقطه در وسط دایره باش، با خنده پاسخ داد: ای حافظ، این چه حرف عجیبی است!',NULL);
INSERT INTO "verses" VALUES(1935524,2572,5,1,'دلم گرفت و نبودت غم گرفتاری',NULL,NULL);
INSERT INTO "verses" VALUES(1935525,2572,5,0,'سرم برفت و زمانی به سر نرفت این کار','هوش مصنوعی: سرم به درد آمد و مدت‌ها این درد برطرف نشد، دل من به خاطر این وضعیت آشفته شد و نبودنت، غم و اندوه دیگری به مشکلاتم اضافه کرد.',NULL);
INSERT INTO "verses" VALUES(1935526,2572,4,1,'چو تیره‌رأی شوی کی گشایدت کاری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935527,2574,4,0,'بنوش می که سبک‌روحی و لطیف مدام','هوش مصنوعی: نوشیدنی را بیاشام که باعث سبکی روح و لطافت می‌شود، به ویژه در زمان‌هایی که بار سنگینی بر دوش داری.',NULL);
INSERT INTO "verses" VALUES(1935528,2574,4,1,'علی الخصوص در آن دم که سر گران داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935529,2574,5,0,'مکن عتاب از این بیش و جور بر دل ما','هوش مصنوعی: دیگر بر دل ما خشم نیاور و از این بیشتر سختی نکن. هر کاری که از دستت برمی‌آید بکن، اما برای آنچه در توان داری، نه بیشتر.',NULL);
INSERT INTO "verses" VALUES(1935530,2574,5,1,'مکن هر آن چه توانی که جای آن داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935531,2576,1,1,'از آن گوهر که در گنجینه داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935532,2576,1,0,'نصیحت گوش کن کاین در بسی به','پندی که می‌دهم را گوش کن که این از همه ثروت‌هایی که داری باارزش‌تر است.',NULL);
INSERT INTO "verses" VALUES(1935533,2576,0,1,'که حق صحبت دیرینه داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935534,2576,0,0,'بیا با ما مَوَرز این کینه‌داری','هوش مصنوعی: بیایید از این کینه کنار بکشیم، چرا که شما ارتباط و دوستی دیرینه‌ای با ما دارید.',NULL);
INSERT INTO "verses" VALUES(1935535,2575,8,1,'قدم برون نه اگر میل جست و جو داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935536,2575,8,0,'ز کنج صومعه حافظ مجوی گوهر عشق','هوش مصنوعی: از گوشه‌ی صومعه به دنبال گوهری به نام عشق نباش؛ اگر به جست‌وجو و گشت و گذار علاقه‌داری، باید قدم از آنجا بیرون بگذاری.',NULL);
INSERT INTO "verses" VALUES(1935537,2575,7,1,'که همچو گل همه آیین رنگ و بو داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935538,2575,7,0,'قبای حسن فروشی تو را برازد و بس','هوش مصنوعی: لباسی که زیبایی تو به تن کرده است، به قدری جذاب و دلرباست که مانند گل، هر نوع زیبایی و عطر و طراوتی را در خود دارد.',NULL);
INSERT INTO "verses" VALUES(1935539,2575,6,1,'تو را رسد که غلامان ماه رو داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935540,2575,6,0,'دم از ممالک خوبی چو آفتاب زدن','هوش مصنوعی: اگر بخواهی از زیبایی‌ها و فضیلت‌ها سخن بگویی، باید همچون آفتاب درخشید و این شایستگی را داری که با افرادی با جمال و دلربا محشور باشی.',NULL);
INSERT INTO "verses" VALUES(1935541,2575,5,1,'که گر بدو رسی از شرم سر فروداری',NULL,NULL);
INSERT INTO "verses" VALUES(1935542,2575,5,0,'به سرکشی خود ای سرو جویبار مناز','هوش مصنوعی: ای سرو زیبای من، به خودسری و لجبازی‌ات ادامه نده، زیرا اگر به من نزدیک شوی، از شرم سرم را پایین می‌اندازم.',NULL);
INSERT INTO "verses" VALUES(1935543,2575,4,1,'خود از کدام خم است این که در سبو داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935544,2575,4,0,'به جرعه تو سرم مست گشت نوشت باد','هوش مصنوعی: با جرعه‌ای از تو، سرم به شدت مست شد. بگو هوای من از کدام خم است، که این نوشیدنی را در سبو نگه‌داشتی؟',NULL);
INSERT INTO "verses" VALUES(1935545,2572,4,0,'دلا! همیشه مزن لاف زلف دلبندان','هوش مصنوعی: دل عزیز، همیشه در مورد زلف‌های دلبند‌ها نگو؛ چون اگر نظری بد یا تیره داشته باشی، چه کارهایی برایت باز خواهد شد؟',NULL);
INSERT INTO "verses" VALUES(1935546,2575,3,1,'که گوش و هوش به مرغان هرزه گو داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935547,2575,2,1,'جز این قدر که رقیبان تندخو داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935548,2575,2,0,'در آن شمایل مطبوع هیچ نتوان گفت','هوش مصنوعی: در آن زیبایی دلنشین، تنها می‌توان گفت که تو حریفانی سختگیر و تندخو داری.',NULL);
INSERT INTO "verses" VALUES(1935549,2575,1,1,'توان به دست تو دادن گرش نکو داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935550,2575,1,0,'دلم که گوهر اسرار حسن و عشق در اوست','هوش مصنوعی: دل من پر از رازهای عشق و زیبایی است، اگر تو به آن احترام بگذاری و خوب از آن نگهداری کنی، می‌توانم آن را به تو بسپارم.',NULL);
INSERT INTO "verses" VALUES(1935551,2575,0,1,'به یادگار بمانی که بوی او داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935552,2575,0,0,'صبا تو نکهت آن زلف مشک بو داری','ای نسیم صبا، تو بوی خوش آن گیسوی سیاه خوشبو را به همراه داری...امیدوارم وزش تو پیوسته برقرار بماند، چرا که نشانه و اثر اورا با خود آورده ای',NULL);
INSERT INTO "verses" VALUES(1935553,2574,9,1,'چه غم ز ناله و فریاد باغبان داری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935554,2574,9,0,'چو گل به دامن از این باغ می‌بری حافظ','هوش مصنوعی: مثل گل که از این باغ چیده می‌شوی، حافظ، چرا نگران افسوس و ناله‌ی باغبان هستی؟',NULL);
INSERT INTO "verses" VALUES(1935555,2574,8,1,'برو که هر چه مراد است در جهان داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935556,2574,8,0,'به وصل دوست گرت دست می‌دهد یک دم','هوش مصنوعی: اگر فرصتی برای رسیدن به عشق و دوستی پیدا کردی، از آن لحظه استفاده کن، زیرا در آن زمان می‌توانی تمام خواسته‌ها و آرزوهایت را در دنیا به دست آوری.',NULL);
INSERT INTO "verses" VALUES(1935557,2574,7,1,'که سهل باشد اگر یارِ مهربان داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935558,2574,7,0,'بکِش جفای رقیبان مدام و جور حسود','هوش مصنوعی: اگر تو با ظلم و بدخواهی رقبایت روبه‌رو هستی و از حسادت دیگران رنج می‌بری، نگران نباش. این مشکلات به آسانی قابل حل است، اگر کسی را در کنار خود داشته باشی که دوستت دارد و با تو مهربان است.',NULL);
INSERT INTO "verses" VALUES(1935559,2574,6,1,'به قصد جانِ منِ خسته در کمان داری',NULL,NULL);
INSERT INTO "verses" VALUES(1935560,2574,6,0,'به اختیارت اگر صد هزار تیر جفاست','هوش مصنوعی: اگر هزار تیر زهرآلود هم در دست داشته باشی، هدف تو فقط منِ خسته‌ای هستم که قصد جانم را کرده‌ای.',NULL);
INSERT INTO "verses" VALUES(1935561,2575,3,0,'نوای بلبلت ای گل کجا پسند افتد','هوش مصنوعی: ای گل، صدای نغمه‌ساز تو کجا به دل می‌نشیند، در حالی که تو توجه و تمرکزت به سخنان پرندگان بی‌فایده معطوف است؟',NULL);
INSERT INTO "verses" VALUES(1935562,2560,4,0,'بزن در پرده چنگ ای ماه مطرب!','مصرع دوم‌: تار و سیم چنگ را بزن و بخراش، تا از آن به جوش و خروش بیایم.',NULL);
INSERT INTO "verses" VALUES(1935563,2572,3,1,'که نیست نقد روان را بر تو مقداری',NULL,NULL);
INSERT INTO "verses" VALUES(1935564,2572,2,1,'که در پی است ز هر سویت آه بیداری',NULL,NULL);
INSERT INTO "verses" VALUES(1935565,2569,7,0,'به شعر حافظِ شیراز می‌رقصند و می‌نازند','هوش مصنوعی: سیه‌چشمان کشمیری و دختران سمرقند با شعر حافظ از شادی می‌رقصند و به زیبایی خود می‌بالند.',NULL);
INSERT INTO "verses" VALUES(1935566,2569,6,1,'خدایا منعَمم گردان به درویشی و خرسندی',NULL,NULL);
INSERT INTO "verses" VALUES(1935567,2569,6,0,'در این بازار اگر سودی‌ست، با درویش خرسند است','هوش مصنوعی: در این دنیا اگر چیزی برای بدست آوردن باشد، درویش از آن راضی و خرسند است. ای خدا، مرا به حال درویشی و رضایت از شرایط زندگی‌ام برسان.',NULL);
INSERT INTO "verses" VALUES(1935568,2569,5,1,'دریغ آن سایهٔ همّت، که بر نااهل افکندی',NULL,NULL);
INSERT INTO "verses" VALUES(1935569,2569,5,0,'همایی چون تو عالی‌قدر، حرص استخوان تا کی؟','همایی عالی‌مقام مثل تو چرا باید کرکس مردارخوار شود؟ حیف است که سایهٔ فر و شکوه و امیدت را بر چیزی حقیر افکنده‌ای.',NULL);
INSERT INTO "verses" VALUES(1935570,2569,4,1,'ز مِهر او چه می‌پرسی؟ در او همّت چه می‌بندی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935571,2569,4,0,'جهانِ پیرِ رعنا را، ترحّم در جِبِلَّت نیست','جبلت: یعنی سیرت و ذات:در ذات جهان پیر ولی جوان نما هیچگونه لطف و ترحمی نیست/////پس برای چه به آن دل می بندی و برای رسیدن به آن تلاش می کنی',NULL);
INSERT INTO "verses" VALUES(1935572,2569,3,1,'پدر را باز پرس آخر، کجا شد مِهرِ فرزندی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935573,2569,3,0,'الا ای یوسف مصری که کردت سلطنت مغرور!','ا‌ی یوسف مصری، که سلطنت و حکومت تو را مغرور و فریفته کرد. آخر از حال پدرت بپرس. مهر و محبت فرزند کجا رفت؟',NULL);
INSERT INTO "verses" VALUES(1935574,2569,2,1,'ورای حدّ تقریر است، شرح آرزومندی',NULL,NULL);
INSERT INTO "verses" VALUES(1935575,2569,2,0,'قلم را آن زبان نَبوَد، که سرِّ عشق گوید باز','قلم، زبان و بیانِ راز عشق را ندارد. (نمی‌تواند راز عشق را بیان کند.) شرح عشق و آرزومندی فراتر از این است که به نوشتن درآید.',NULL);
INSERT INTO "verses" VALUES(1935576,2569,1,1,'بدین راه و روش می‌رو، که با دلدار پیوندی',NULL,NULL);
INSERT INTO "verses" VALUES(1935577,2569,1,0,'دعای صبح و آهِ شب، کلید گنج مقصود است','دعای صبح و آه نیمه شب، کلید گشایش گنج مقصود و رسیدن به هدف است. به همین شیوه برو تا بتوانی به معشوق برسی.',NULL);
INSERT INTO "verses" VALUES(1935578,2569,0,1,'خطاب آمد که «واثق شو، به الطاف خداوندی»',NULL,NULL);
INSERT INTO "verses" VALUES(1935579,2569,0,0,'سحر با باد می‌گفتم حدیث آرزومندی','هوش مصنوعی: در صبح زود به باد گفتم داستان آرزوهایم را. به من پاسخ داد که «به لطف‌های خداوند امیدوار باش».',NULL);
INSERT INTO "verses" VALUES(1935580,2568,9,1,'مقبول طبع شاه هنرپرور آمدی',NULL,NULL);
INSERT INTO "verses" VALUES(1935581,2568,9,0,'گر دیگری به شیوهٔ حافظ زدی رقم','هوش مصنوعی: اگر کسی مانند حافظ به زیبایی و هنرمندی شعر بسراید، مورد توجه و پسند پادشاه هنرپرور قرار خواهد گرفت.',NULL);
INSERT INTO "verses" VALUES(1935582,2568,8,1,'ای کاشکی که پاش به سنگی برآمدی',NULL,NULL);
INSERT INTO "verses" VALUES(1935583,2568,8,0,'آن کو تو را به سنگ‌دلی کرد رهنمون','آن کسی که تو را با بی‌رحمی و سنگدلی هدایت کرد، ای کاش که پای او به سنگی برخورد می‌کرد.( و مکافات کارش را می‌دید)',NULL);
INSERT INTO "verses" VALUES(1935584,2568,7,1,'دریادلی بجوی دلیری سرآمدی',NULL,NULL);
INSERT INTO "verses" VALUES(1935585,2568,7,0,'خامان ره نرفته چه دانند ذوق عشق','آنانی که در این راه خام‌اند، چه می‌دانند از شور و لذت عشق؟دلیر و دریا‌دلی را بِجوی که در دلیری بی‌همتا باشد.',NULL);
INSERT INTO "verses" VALUES(1935586,2568,6,1,'مظلومی ار شبی به در داور آمدی',NULL,NULL);
INSERT INTO "verses" VALUES(1935587,2568,6,0,'کی یافتی رقیب تو چندین مجال ظلم؟','هوش مصنوعی: کی رقیبی پیدا کردی که اینقدر زمان ظلم را در اختیار داشته باشد؟ اگر کسی مظلوم باشد، تنها در شب می‌تواند به درگاه داور بیاید و فریاد کند.',NULL);
INSERT INTO "verses" VALUES(1935588,2568,5,1,'هر دم پیام یار و خط دلبر آمدی',NULL,NULL);
INSERT INTO "verses" VALUES(1935589,2568,5,0,'آن عهد یاد باد که از بام و در مرا','هوش مصنوعی: یادآوری می‌کنم که روزهایی بود که از هر طرف به من خبر عشق و پیام محبوب می‌رسید.',NULL);
INSERT INTO "verses" VALUES(1935590,2568,4,1,'آب خضر نصیبه اسکندر آمدی',NULL,NULL);
INSERT INTO "verses" VALUES(1935591,2568,4,0,'فیض ازل به زور و زر ار آمدی به دست','اگر فیض الهی از ازل با زور و زر به‌دست می‌آمد،پس آب حیات (آب خضر) باید نصیب اسکندر می‌شد.',NULL);
INSERT INTO "verses" VALUES(1935592,2568,3,1,'تا یاد صحبتش سوی ما رهبر آمدی',NULL,NULL);
INSERT INTO "verses" VALUES(1935593,2568,3,0,'خوش بودی ار به خواب بدیدی دیار خویش','هوش مصنوعی: اگر در خواب دیار خود را می‌دیدی، خوشحال می‌شدی، چرا که یاد آن گفتگوها و لحظات مشترک، تو را به سوی ما می‌کشاند.',NULL);
INSERT INTO "verses" VALUES(1935594,2569,7,1,'سیه‌چشمان کشمیری و تُرکان سمرقندی',NULL,NULL);
INSERT INTO "verses" VALUES(1935595,2570,0,0,'چه بودی ار دل آن ماه مهربان بودی؟','هوش مصنوعی: اگر دل آن ماه مهربان می‌بود، حال و روز ما اینگونه نبود. اگر او به ما محبت می‌کرد، زندگی‌مان بهتر و متفاوت می‌شد.',NULL);
INSERT INTO "verses" VALUES(1935596,2570,0,1,'که حال ما نه چنین بودی ار چنان بودی',NULL,NULL);
INSERT INTO "verses" VALUES(1935597,2570,1,0,'بگفتمی که «چه ارزد نسیم طرهٔ دوست؟»','هوش مصنوعی: گفتم باد ملایم موهای محبوب چه ارزشی دارد؟ اما او در پاسخ گفت که هر رشته موی او هزار جان ارزش دارد.',NULL);
INSERT INTO "verses" VALUES(1935598,2572,2,0,'مرو چو بخت من ای چشم مست یار به خواب','هوش مصنوعی: ای چشم مست و شگفت‌انگیز یار، مانند بخت بد من، به خواب نرو؛ زیرا در هر جا که بروی، ناله و غم بیداری در پی‌ات خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1935599,2572,1,1,'ز سحر چشم تو، هر گوشه‌ای و بیماری',NULL,NULL);
INSERT INTO "verses" VALUES(1935600,2572,1,0,'ز کفر زلف تو، هر حلقه‌ای و آشوبی','هوش مصنوعی: زلف تو باعث کفر و بی‌تابی شده و چشم تو در هر گوشه‌ای سحر و بیماری را می‌افریند.',NULL);
INSERT INTO "verses" VALUES(1935601,2572,0,1,'خورد ز غیرت روی تو هر گلی خاری',NULL,NULL);
INSERT INTO "verses" VALUES(1935602,2572,0,0,'چو سرو اگر بخرامی دمی به گلزاری','هوش مصنوعی: اگر تو مانند سروی در میان گل‌ها درخشان و زیبا باشی، هر گلی در آن گلزار از عشق و غیرت تو، تبدیل به خار خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1935603,2571,7,1,'اگر نه همدم مرغان صبح خوان بودی',NULL,NULL);
INSERT INTO "verses" VALUES(1935604,2571,7,0,'ز پرده نالهٔ حافظ برون کی افتادی؟','هوش مصنوعی: کی از پرده‌ی ناله‌های حافظ خارج شده‌ای؟ اگر نه، باید همسفر پرندگان صبح‌خوان بوده باشی.',NULL);
INSERT INTO "verses" VALUES(1935605,2571,6,1,'که بر دو دیدهٔ ما حکم او روان بودی',NULL,NULL);
INSERT INTO "verses" VALUES(1935606,2571,6,0,'درآمدی ز درم کاشکی چو لمعهٔ نور','هوش مصنوعی: ای کاش از مال و ثروتم چون پرتو نوری به چشمان ما می‌تابید و به ما حکم می‌کرد.',NULL);
INSERT INTO "verses" VALUES(1935607,2571,5,1,'به دل دریغ که یک ذره مهربان بودی',NULL,NULL);
INSERT INTO "verses" VALUES(1935608,2571,5,0,'به رخ چو مهرِ فلک بی‌نظیرِ آفاق است','هوش مصنوعی: به مانند ماهی که در آسمان می‌درخشد، زیبایی و استثنایی در دنیا وجود دارد، ولی افسوس که در دلِ ما حتی یک ذره از محبت و مهربانی وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1935609,2571,4,1,'کی‌اش قرار در این تیره‌خاکدان بودی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935610,2571,4,0,'اگر دلم نشدی پایبند طرهٔ او','هوش مصنوعی: اگر دل من به داشتن موهای او وابسته نشده باشد، پس او چگونه می‌تواند در این دنیا که پر از ناراحتی و غم است آرامش پیدا کند؟',NULL);
INSERT INTO "verses" VALUES(1935611,2571,3,1,'چو این نبود و ندیدیم باری آن بودی',NULL,NULL);
INSERT INTO "verses" VALUES(1935612,2572,3,0,'نثار خاک رهت نقد جان من هر چند','هوش مصنوعی: خاک راه تو را با جانم نثار می‌کنم، هرچند که جانم ارزش زیادی ندارد و نمی‌توانم بهای قابل توجهی برای تو داشته باشم.',NULL);
INSERT INTO "verses" VALUES(1935613,2571,3,0,'به خواب نیز نمی‌بینمش چه جای وصال','هوش مصنوعی: من حتی در خواب هم او را نمی‌بینم، چه رسد به اینکه بتوانم با او به وصال برسم، چون تاکنون این امکان را نداشته‌ام.',NULL);
INSERT INTO "verses" VALUES(1935614,2571,2,0,'به بندگی قدش سرو معترف گشتی','هوش مصنوعی: اگر به قد و قامت او مانند سرو اعتراف کرده‌ای، باید بگویی که او مانند سوسن آزاده، زیبا و باوقار است و اگر زبان داشت، می‌توانست این زیبایی را بیان کند.',NULL);
INSERT INTO "verses" VALUES(1935615,2571,1,1,'اگر حیات گران مایه جاودان بودی',NULL,NULL);
INSERT INTO "verses" VALUES(1935616,2571,1,0,'بگفتمی که «بها چیست خاک پایش را؟»','هوش مصنوعی: گفتم که ارزش خاک پای او چه ارزشی دارد؟ اگر زندگی ارزشمند و جاودانی بود.',NULL);
INSERT INTO "verses" VALUES(1935617,2571,0,1,'کمینه پیشکش بندگانش آن بودی',NULL,NULL);
INSERT INTO "verses" VALUES(1935618,2571,0,0,'به جان او که گرم دسترس به جان بودی','هوش مصنوعی: به جان او که به شدت به جان نزدیک است، کمترین چیزی که بندگانش پیشکش می‌کردند، همین بود.',NULL);
INSERT INTO "verses" VALUES(1935619,2570,5,1,'چو نقطه حافظ سرگشته در میان بودی',NULL,NULL);
INSERT INTO "verses" VALUES(1935620,2570,5,0,'اگر نه دایرهٔ عشق راه بربستی','هوش مصنوعی: اگر در عشق راه را نبسته بودی، مثل نقطه‌ای که حافظ در گمراهی قرار دارد، در مرکز دایره‌ای از عشق می‌بودی.',NULL);
INSERT INTO "verses" VALUES(1935621,2570,4,1,'که بر دو دیدهٔ ما حکم او روان بودی',NULL,NULL);
INSERT INTO "verses" VALUES(1935622,2570,4,0,'ز پرده کاش برون آمدی چو قطرهٔ اشک','هوش مصنوعی: کاش تو از پشت پرده بیرون می‌آمدی مثل قطره اشکی که بر روی چشم‌های ما جاری است.',NULL);
INSERT INTO "verses" VALUES(1935623,2570,3,1,'سریر عزتم آن خاک آستان بودی',NULL,NULL);
INSERT INTO "verses" VALUES(1935624,2570,3,0,'گرَم زمانه سرافراز داشتی و عزیز','هوش مصنوعی: اگر در روزگار خود مقام و منزلت بلندی داشتی، باید بدانی که ریشه‌ی عزت و آبرویت در خاک این آستان است.',NULL);
INSERT INTO "verses" VALUES(1935625,2570,2,1,'گرش نشان امان از بد زمان بودی',NULL,NULL);
INSERT INTO "verses" VALUES(1935626,2570,2,0,'برات خوش‌دلی ما چه کم شدی یا رب','هوش مصنوعی: ای کاش خوش‌دل بودن ما صدای کم‌رنگی از خوشی‌های زندگی‌مان بود، خداوندا! اگر او با ما بود، نمی‌دانیم که تا چه اندازه می‌توانستیم در برابر روزگار سخت مقاومت کنیم.',NULL);
INSERT INTO "verses" VALUES(1935627,2570,1,1,'گرم به هر سر مویی هزار جان بودی',NULL,NULL);
INSERT INTO "verses" VALUES(1935628,2571,2,1,'گرش چو سوسن آزاده ده زبان بودی',NULL,NULL);
INSERT INTO "verses" VALUES(1935629,2560,3,1,'که می‌داند که جم کی بود و کی کی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935630,2560,3,0,'بده جام می و از جم مکن یاد','هوش مصنوعی: به تو جام می بده و دیگر به یاد جم نیفت، چرا که نوشیدنی می‌داند که جم کی بوده و چه زمانی وجود داشته است.',NULL);
INSERT INTO "verses" VALUES(1935631,2560,2,1,'رخش می‌بیند و گل می‌کند خوی',NULL,NULL);
INSERT INTO "verses" VALUES(1935632,2550,0,0,'درِ سرایِ مغان رُفته بود و آب‌زده','درب منزل پیر روحانی آب و جاروب کرده بود و به انتظار نشسته بود و دعوتش از پیر و جوانان اهل عشق بود تا در کار شراب و مستی خدمت رساند',NULL);
INSERT INTO "verses" VALUES(1935633,2550,0,1,'نشسته پیر و صلایی به شیخ و شاب زده',NULL,NULL);
INSERT INTO "verses" VALUES(1935634,2550,1,0,'سبوکشان همه در بندگیش بسته کمر','تمام کسانی که مدعی فهم و درک هستند ، کمر به خدمت این پیر فرزانه بسته اند درحالی که به سبب دست شستن از عقل و عروج و پیوستن به کمال هستی ، بر ابر نیز سایه می افکنند',NULL);
INSERT INTO "verses" VALUES(1935635,2550,1,1,'ولی ز تَرک کُله چتر بر سحاب زده',NULL,NULL);
INSERT INTO "verses" VALUES(1935636,2550,2,0,'شعاع جام و قدح نور ماه پوشیده','هوش مصنوعی: نور جام و لیوان، مانند نور ماه، چهره‌های زیبا را می‌پوشاند و به نوعی زیبایی آنها را تحت تأثیر قرار می‌دهد. این مانند این است که آفتاب با طمانینه و ملایمت بر صورت این دختران می‌تابد.',NULL);
INSERT INTO "verses" VALUES(1935637,2550,2,1,'عذار مغ‌بچگان راه آفتاب زده',NULL,NULL);
INSERT INTO "verses" VALUES(1935638,2550,3,0,'عروس بخت در آن حجله با هزاران ناز','هوش مصنوعی: عروس خوشبختی در آن اتاق زیبا با هزاران ناز و افسون، یک دستمال ابریشمی را روی برگ گل عطرآلود گذاشته است.',NULL);
INSERT INTO "verses" VALUES(1935639,2550,3,1,'شکسته کسمه و بر برگ گل، گلاب زده',NULL,NULL);
INSERT INTO "verses" VALUES(1935640,2550,4,0,'گرفته ساغر عشرت فرشتهٔ رحمت','هوش مصنوعی: فرشتهٔ رحمت با گیلاس شادی در دست، قطره‌ای شراب را بر چهرهٔ حور و پری پاشیده است.',NULL);
INSERT INTO "verses" VALUES(1935641,2550,4,1,'ز جرعه بر رخ حور و پری گلاب زده',NULL,NULL);
INSERT INTO "verses" VALUES(1935642,2550,5,0,'ز شور و عربدهٔ شاهدان شیرین‌کار','هوش مصنوعی: از هیاهو و انرژی حاضران خوش‌گذرانی که شیرینی و شگفتی را به نمایش گذاشته‌اند، شکر و گلبرگ‌ها بر زمین ریخته و نغمه‌ای هم در حال نواختن است.',NULL);
INSERT INTO "verses" VALUES(1935643,2550,5,1,'شکر شکسته، سمن ریخته، رباب زده',NULL,NULL);
INSERT INTO "verses" VALUES(1935644,2550,6,0,'سلام کردم و با من به روی خندان گفت','هوش مصنوعی: سلام کردم و او با لبخندی به من پاسخ داد که ای دوست، تو که به خاطر خماریت بی‌پول و بی‌نوا هستی!',NULL);
INSERT INTO "verses" VALUES(1935645,2550,6,1,'که ای خمارکشِ مفلسِ شراب‌زده',NULL,NULL);
INSERT INTO "verses" VALUES(1935646,2550,7,0,'که این کند که تو کردی به ضعف همت و رای؟','هوش مصنوعی: چرا آنچه را که تو به خاطر کمبود تلاش و اندیشه‌ات انجام دادی، اینگونه رها کرده‌ای؟ مانند اینکه خیمه‌ای بر ویرانه‌ای از گنجینه‌ات برپا کرده‌ای.',NULL);
INSERT INTO "verses" VALUES(1935647,2549,6,1,'خانه از غیر نپرداخته‌ای، یعنی چه؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935648,2549,6,0,'حافظا در دلِ تنگت چو فرود آمد یار','هوش مصنوعی: ای حافظ، وقتی یارت در دل تنگ تو وارد می‌شود، چطور می‌توانی از دیگران بی‌تفاوت باشی؟ این نشان‌دهنده چه حالتی است؟',NULL);
INSERT INTO "verses" VALUES(1935649,2549,5,1,'عاقبت با همه کج باخته‌ای، یعنی چه؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935650,2549,5,0,'هر کس از مُهرهٔ مِهر تو به نقشی مشغول','هوش مصنوعی: هر کسی که تحت تأثیر محبت و جاذبه‌ی تو قرار گیرد و در کارها و روابطش مشغول به نقش‌ بازی باشد، در نهایت همگی به نوعی دچار شکست یا ناکامی می‌شوند.',NULL);
INSERT INTO "verses" VALUES(1935651,2549,4,1,'وز میان، تیغ به ما آخته‌ای، یعنی چه؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935652,2549,4,0,'سخنت رمزِ دهان گفت و کمر سِرّ‌ِ میان','هوش مصنوعی: سخن تو مانند رمز و راز است که در دهان گفته می‌شود و به طور خاص، اسراری که در میان ما وجود دارد، به شکل یک تیغ تیز آماده زخم زدن است. این جمله به این معنی اشاره دارد که با گفتن این کلمات، تو به ما چیزی مهم و پنهان را منتقل می‌کنی که می‌تواند تأثیر عمیقی بر ما بگذارد.',NULL);
INSERT INTO "verses" VALUES(1935653,2549,3,1,'بازم از پای درانداخته‌ای، یعنی چه؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935654,2549,3,0,'نه سرِ زلفِ خود اول تو به دستم دادی','هوش مصنوعی: تو ابتدا با زلف خود به من اشاره کردی و مرا به خود جذب کردی، اما اکنون چطور می‌توانی مرا ناامید کنی و از خود دور کنی؟ این رفتار تو چه معنایی دارد؟',NULL);
INSERT INTO "verses" VALUES(1935655,2549,2,1,'قدرِ این مرتبه نشناخته‌ای، یعنی چه؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935656,2549,2,0,'شاهِ خوبانی و منظورِ گدایان شده‌ای','هوش مصنوعی: تو بهترین و نیکوترین پادشاهان هستی و به حاجتمندان و گدایان توجه کرده‌ای، اما نمی‌دانی که این مقام و مرتبه چقدر ارزشمند و بزرگ است.',NULL);
INSERT INTO "verses" VALUES(1935657,2549,1,1,'این چنین با همه درساخته‌ای، یعنی چه؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935658,2549,1,0,'زلف در دستِ صبا، گوش به فرمان رقیب','هوش مصنوعی: موهای تو در دست نسیم است و تو با این حال، به خواسته‌های رقیب تن داده‌ای؛ این نشان‌دهنده‌ی آن است که تو چقدر با تمام وجودت و بر اساس شرایطی که داری، در تلاش برای سازگاری هستی.',NULL);
INSERT INTO "verses" VALUES(1935659,2549,0,1,'مست از خانه برون تاخته‌ای، یعنی چه؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935660,2549,0,0,'ناگهان پرده برانداخته‌ای، یعنی چه؟','هوش مصنوعی: ناگهان پرده را کنار زده‌ای، یعنی چه؟ چرا به‌طور ناگهانی از خانه بیرون رفته‌ای و گرفتار سرود و شوق شده‌ای؟',NULL);
INSERT INTO "verses" VALUES(1935661,2550,7,1,'ز گنج‌خانه شده خیمه بر خراب زده',NULL,NULL);
INSERT INTO "verses" VALUES(1935662,2550,8,0,'وصال دولت بیدار ترسمت ندهند','هوش مصنوعی: ترس دارم که برای رسیدن به خوشبختی، از خواب بیدارم نکنند؛ چرا که تو در آغوش شانس خود بی‌خبر از خواب هستی.',NULL);
INSERT INTO "verses" VALUES(1935663,2550,8,1,'که خفته‌ای تو در آغوش بختِ خواب‌زده',NULL,NULL);
INSERT INTO "verses" VALUES(1935664,2550,9,0,'بیا به میکده حافظ که بر تو عرضه کنم','هوش مصنوعی: بیایید به میکده‌ی حافظ، جایی که بتوانم هزاران دعا و آرزوی برآورده شده را برای شما به نمایش بگذارم.',NULL);
INSERT INTO "verses" VALUES(1935665,2552,0,0,'دوش رفتم به در میکده خواب‌آلوده','دیشب دلزده و درمانده، به میخانه رجوع کردم دلزده از اینکه دامن خرقه ی پرهیزگاری اَم از فراوانی گناه تر شده و سجّاده ی عبادت اَم آلوده به شراب است.',NULL);
INSERT INTO "verses" VALUES(1935666,2552,0,1,'خرقه تر دامن و سجّاده شراب‌آلوده',NULL,NULL);
INSERT INTO "verses" VALUES(1935667,2552,1,0,'آمد افسوس‌کنان مغبچهٔ باده‌فروش','(وقتی با خرقه و سجّاده ی آلوده به میکده رجوع کردم( ساقی گلچهره درحالی که به حال و روز من تاسّف می خورد به استقبالم آمد و از روی دلجویی و دلسوزی گفت: ای سالک و ای رهرو، ای که به ظاهر وانمود به سیر و سلوک می‌کنی امّا در باطن به آن کار دیگر مشغولی از خواب غفلت بیدارشو!! تا کی می خواهی خود و دیگران را بفریبی؟ با خود رو راست باش و تکلیف خویش را معیّن کن. از یک سو ادّعای سیر و سلوک و تهذیب نفس می کنی از سوی دیگر در زیر خرقه چه کار ها که نمی کنی! سجّاده ی زهد بر دوش داری و در آستین خرقه شراب حمل می کنی!',NULL);
INSERT INTO "verses" VALUES(1935668,2552,1,1,'گفت بیدار شو ای رهرو خواب‌آلوده',NULL,NULL);
INSERT INTO "verses" VALUES(1935669,2552,2,0,'شست و شویی کن و آن‌گه به خرابات خِرام','( مُغبچه درادامه ی سخن گفت): برای رسیدن به بیداری و آگاهی باید اوّل دل و جانت را از آلودگیها شستشو دهی سپس پاک و بی ریا گام به میکده بگذاری اگر با آلودگیها وارد شوی ممکن است میکده را نیز آلوده کنی.',NULL);
INSERT INTO "verses" VALUES(1935670,2552,2,1,'تا نگردد ز تو این دیر خراب آلوده',NULL,NULL);
INSERT INTO "verses" VALUES(1935671,2552,3,0,'به هوای لب شیرین پسران چند کنی','ای خرقه پوش متظاهر، تاکی می خواهی در هوس کامگیری از لبهای نوشین پسرانِ زیبا روی، ذات واصلِ روح خویش را آلوده کنی؟ روح تو خود الماسی اصیل، حقیقی و گرانبهاست در حالی که لب سرخ پسران (یاشراب آتشین) یاقوت مجازی و فرعیست چرا ازروی هوسرانی، اصل و حقیقت(روح) را که ارزش والایی دارد با جنس فرعی و مجازی که هیچ ارزشی ندارد قرین و هم نشین می کنی و روح خویش را می‌آزاری؟!',NULL);
INSERT INTO "verses" VALUES(1935672,2552,3,1,'جوهر روح به یاقوت مذاب آلوده',NULL,NULL);
INSERT INTO "verses" VALUES(1935673,2552,4,0,'به طهارت گذران منزل پیری و مکن','(درادامه ی سخن) ..... حال که به دوران کهنسالی رسیده ای سعی کن این خلعتی که از طرف خداوند به تو هدیه شده پاک نگاه داری و پاکیزه زندگی کنی کاری مکن که خلعتِ پیری هم مانند خلعتِ جوانی به ناپاکیها آلوده گردد.',NULL);
INSERT INTO "verses" VALUES(1935674,2552,4,1,'خلعت شیب چو تشریف شباب آلوده',NULL,NULL);
INSERT INTO "verses" VALUES(1935675,2552,5,0,'پاک و صافی شو و از چاه طبیعت به در آی','دل و جانت را از آلودگی ها پاک کن صاف و بی غش همچون آب زلال باش که از چاه به در می‌آید خود را از تعلّقات دنیوی آزاد کن که آب گل الود هیچ لطف و صفایی ندارد زلال و بی رنگ و بی ریا می‌باش تا بتوانی علاوه بر خود به پیرامونت نیز طراوت و تازگی و فیض ببخشی.',NULL);
INSERT INTO "verses" VALUES(1935676,2551,6,1,'مگر از مذهب این طایفه باز آمده‌ای',NULL,NULL);
INSERT INTO "verses" VALUES(1935677,2551,6,0,'گفت حافظ دگرت خرقه شراب آلوده‌ست','هوش مصنوعی: حافظ می‌گوید که این بار که آمده‌ای، لباس مقدس تو به شراب آغشته شده است. آیا هنوز از مسیر اصلی این گروه منحرف نشده‌ای؟',NULL);
INSERT INTO "verses" VALUES(1935678,2551,5,1,'مست و آشفته به خلوتگه راز آمده‌ای',NULL,NULL);
INSERT INTO "verses" VALUES(1935679,2548,10,1,'ولیکِن گفتهٔ حافظ از آن به',NULL,NULL);
INSERT INTO "verses" VALUES(1935680,2551,5,0,'زهد من با تو چه سنجد که به یغمای دلم','هوش مصنوعی: زهد و ریاضت من در مقابل تو چه ارزشی دارد، وقتی که تو با قلبی پر از خلسه و بی‌نظمی به مکانی خاص برای فاش کردن اسرار دلم آمده‌ای؟',NULL);
INSERT INTO "verses" VALUES(1935681,2551,4,0,'آفرین بر دل نرم تو که از بهر ثواب','آفرین بر دل نرم خوی تو که به خاطر ثواب الهی - آمده ای بر جنازه کسی که از تیر غمزه تو کشته شده است، نماز بخوانی',NULL);
INSERT INTO "verses" VALUES(1935682,2551,3,1,'چشم بد دور که بس شَعبده‌باز آمده‌ای',NULL,NULL);
INSERT INTO "verses" VALUES(1935683,2551,3,0,'آب و آتش به هم آمیخته‌ای از لب لعل','لب های سرخ فام (لعل ماند) تو ماند ترکیبی از آب و آتش است - چشم بد از تو دور باد که مانند شعبده بازان ماهر آمده ای',NULL);
INSERT INTO "verses" VALUES(1935684,2551,2,1,'چون به هر حال برازندهٔ ناز آمده‌ای',NULL,NULL);
INSERT INTO "verses" VALUES(1935685,2551,2,0,'پیش بالای تو میرم چه به صلح و چه به جنگ','در مقابل قد و بالای تو می میرم چه با صلح و چه با جنگ - چرا که در هر حال شایسته ناز کردن هستی',NULL);
INSERT INTO "verses" VALUES(1935686,2551,1,1,'چون به پرسیدن ارباب نیاز آمده‌ای',NULL,NULL);
INSERT INTO "verses" VALUES(1935687,2551,1,0,'ساعتی ناز مفرما و بگردان عادت','برای ساعاتی عادت ناز کردن خودت را کنار بگذار - چرا که به دلجوئی نیازمندان آمده ای',NULL);
INSERT INTO "verses" VALUES(1935688,2551,0,1,'فرصتت باد که دیوانه‌نواز آمده‌ای',NULL,NULL);
INSERT INTO "verses" VALUES(1935689,2551,0,0,'ای که با سلسلهٔ زلف دراز آمده‌ای','ای کسی که با موهای بلند به نزد من آمده ای - امیدوارم فرصت و فراغتی داشته باشی که برای نوازش من دیوانه آمده ای',NULL);
INSERT INTO "verses" VALUES(1935690,2550,9,1,'هزار صف ز دعاهای مستجاب‌ زده',NULL,NULL);
INSERT INTO "verses" VALUES(1935691,2550,10,0,'فلک جنیبه‌کش شاه نصرت‌الدین است','هوش مصنوعی: آسمان به خاطر نصرت‌الدین، شاه، در حال گردش است. بیا و ببین که چگونه سلطنتش در حال پیشرفت و موفقیت است.',NULL);
INSERT INTO "verses" VALUES(1935692,2550,10,1,'بیا ببین ملکش دست در رکاب زده',NULL,NULL);
INSERT INTO "verses" VALUES(1935693,2550,11,0,'خرد که ملهم غیب است بهر کسب شرف','هوش مصنوعی: خرد، که الهاماتی از عالم غیب دارد، برای به دست آوردن مقام و شرافت، صد بار بر جلال و عظمت الهی احترام می‌گذارد.',NULL);
INSERT INTO "verses" VALUES(1935694,2550,11,1,'ز بام عرش صدش بوسه بر جناب زده',NULL,NULL);
INSERT INTO "verses" VALUES(1935695,2551,4,1,'کشتهٔ غمزهٔ خود را به نماز آمده‌ای',NULL,NULL);
INSERT INTO "verses" VALUES(1935696,2552,5,1,'که صفایی ندهد آب تراب‌آلوده',NULL,NULL);
INSERT INTO "verses" VALUES(1935697,2548,10,0,'سخن اندر دهانِ دوست شکَّر','سخنی که از دهان دوست شنیده شود مانند شکر است اما گفتهٔ حافظ از آن نیز، بهتر.',NULL);
INSERT INTO "verses" VALUES(1935698,2548,9,0,'اگر چه زنده‌رود آب حیات است','اگرچه زنده‌رود آب حیات به شمار می‌آید، ولی اجالتاً شیراز ما از اصفهان بهتر است.',NULL);
INSERT INTO "verses" VALUES(1935699,2546,5,1,'از قامتت سرو، از عارضت ماه',NULL,NULL);
INSERT INTO "verses" VALUES(1935700,2546,5,0,'کافر مبیناد، این غم که دیده‌ست','هوش مصنوعی: کافر نباش، این اندوهی که به خاطر قامت زیبا و چهره دلربای تو دارم، از شدت زیبایی‌ات است.',NULL);
INSERT INTO "verses" VALUES(1935701,2546,4,1,'چشمی و صد نم، جانی و صد آه',NULL,NULL);
INSERT INTO "verses" VALUES(1935702,2546,4,0,'جانا چه گویم؟ شرح فراقت','هوش مصنوعی: عزیزم، چگونه احساسات خود را درباره دوری‌ات بیان کنم؟ چشمانم پر از اشک است و از دل آزرده‌ام، آه‌های زیادی از دل برمی‌آید.',NULL);
INSERT INTO "verses" VALUES(1935703,2546,3,1,'و از فعل عابد، استغفرالله',NULL,NULL);
INSERT INTO "verses" VALUES(1935704,2546,3,0,'از دست زاهد، کردیم توبه','هوش مصنوعی: از رفتار ریاضت‌کش‌ها توبه کردیم و از اعمال عبادت‌ کنندگان استغفار می‌طلبیم.',NULL);
INSERT INTO "verses" VALUES(1935705,2546,2,1,'پیران جاهل، شیخان گمراه',NULL,NULL);
INSERT INTO "verses" VALUES(1935706,2546,2,0,'ما را به رندی، افسانه کردند','هوش مصنوعی: ما را به دلیل رفتار خاص و غیرمعمول‌مان، به داستان‌سرایی مشغول کردند، کسانی که سن و سال زیادی دارند اما دانش کافی ندارند و پیشوایانی که مسیر درست را گم کرده‌اند.',NULL);
INSERT INTO "verses" VALUES(1935707,2546,1,1,'گه جام زرکش، گه لعل دل‌خواه',NULL,NULL);
INSERT INTO "verses" VALUES(1935708,2546,1,0,'ای بخت سرکش! تنگش به بَر کش','هوش مصنوعی: ای شانس سرکش! گاهی به انسان خوشی و ثروت می‌رسی و گاهی هم نعمت‌هایی زیبا و دلربا.',NULL);
INSERT INTO "verses" VALUES(1935709,2546,0,1,'کارم به کام است، الحمدلله',NULL,NULL);
INSERT INTO "verses" VALUES(1935710,2546,0,0,'عیشم مدام است، از لعل دل‌خواه','هوش مصنوعی: زندگی‌ام همواره شادی‌بخش است و از عشق محبوبم، کارهایم همیشه به خیر و خوشی پیش می‌رود. شکر خدا.',NULL);
INSERT INTO "verses" VALUES(1935711,2545,6,1,'که حافظ تو خود این لحظه گفت «بسم الله»',NULL,NULL);
INSERT INTO "verses" VALUES(1935712,2545,6,0,'مده به خاطر نازک ملالت از من زود','به خاطر نازک و لطیف خود رنجش راه مده و از من زود مرنج؛ زیرا حافظ و نگهبان تو این لحظه گفت «بسم الله»',NULL);
INSERT INTO "verses" VALUES(1935713,2545,5,1,'ز تربتم بدمد سرخ‌گل به جای گیاه',NULL,NULL);
INSERT INTO "verses" VALUES(1935714,2545,5,0,'به عشق روی تو روزی که از جهان بروم','هوش مصنوعی: زمانی که از این دنیا بروم، با عشق تو، از خاک من گل‌های سرخ جوانه می‌زنند و جای گیاهان را خواهند گرفت.',NULL);
INSERT INTO "verses" VALUES(1935715,2545,4,1,'سپیده دم که صبا چاک زد شعار سیاه',NULL,NULL);
INSERT INTO "verses" VALUES(1935716,2545,4,0,'ز دوستان تو آموخت در طریقت مهر','سپیده‌دم از عاشقان تو راه عاشقی را آموخت که با دست صبا، پیراهن سیاه خود را چاک زد.',NULL);
INSERT INTO "verses" VALUES(1935717,2545,3,1,'مگر تو عفو کنی ور نه چیست عذر گناه؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935718,2545,3,0,'منم که بی تو نفس می‌کشم، زهی خجلت','هوش مصنوعی: من هستم که بدون تو زندگی می‌کنم و این برایم شرم‌آور است. اگر تو مرا ببخشی، خیلی خوب است، وگرنه دلیل و عذری برای گناهم وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1935719,2545,2,1,'هلال را ز کنار افق کنید نگاه',NULL,NULL);
INSERT INTO "verses" VALUES(1935720,2545,2,0,'به یاد شخصِ نزارم که غرقِ خونِ دل است','هوش مصنوعی: به یاد کسی که در درد و غم غرق شده است، لطفاً هلال ماه را از کنار افق ببینید و به آن نگاه کنید.',NULL);
INSERT INTO "verses" VALUES(1935721,2545,1,1,'که دیده آب شد از شوق خاک آن درگاه',NULL,NULL);
INSERT INTO "verses" VALUES(1935722,2545,1,0,'دلیل راه شو ای طایر خجسته‌لقا','هوش مصنوعی: ای پرنده خوشبخت، دلیل و راه خودت را پیدا کن، زیرا چشمان من از شوق و عشق به خاک آن درگاه، مانند آب شده است.',NULL);
INSERT INTO "verses" VALUES(1935723,2545,0,1,'که در هوای تو برخاست بامداد پگاه',NULL,NULL);
INSERT INTO "verses" VALUES(1935724,2545,0,0,'خنک نسیم معنبر شمامه‌ای دل‌خواه','هوش مصنوعی: باد ملایم و خوشایندی که در صبح زود وزیدن گرفت، مانند عطر خوش گل شمام، باعث شادابی و سرزندگی است.',NULL);
INSERT INTO "verses" VALUES(1935725,2544,10,1,'می نوش و ترک زرق ز بهر خدا بگو',NULL,NULL);
INSERT INTO "verses" VALUES(1935726,2544,10,0,'حافظ گرت به مجلس او راه می‌دهند','هوش مصنوعی: اگر به محفل محبوب راهت دهند، از شراب بنوش و برای خدا از زرق و برق و نشان‌های فریبنده دنیا بگذر.',NULL);
INSERT INTO "verses" VALUES(1935727,2544,9,1,'رمزی برو بپرس، حدیثی بیا بگو',NULL,NULL);
INSERT INTO "verses" VALUES(1935728,2546,6,0,'شوق لبت برد، از یاد حافظ','شوق لب‌ های تو باعث شد که حافظ راز و نیاز سحرگاهی و درس خلوت شبانه را از یاد ببرد .',NULL);
INSERT INTO "verses" VALUES(1935729,2546,6,1,'درس شبانه، ورد سحرگاه',NULL,NULL);
INSERT INTO "verses" VALUES(1935730,2547,0,0,'گر تیغ بارد در کوی آن ماه','اگر در کوی آن زیبارو شمشیر ببارد ما گردن بر سر راه آن می‌گذاریم و از آنجا نمی‌رویم تا خدا چه بخواهد.',NULL);
INSERT INTO "verses" VALUES(1935731,2547,0,1,'گردن نهادیم الحکمُ لِلّه',NULL,NULL);
INSERT INTO "verses" VALUES(1935732,2548,8,1,'ز مرواریدِ گوشم در جهان به',NULL,NULL);
INSERT INTO "verses" VALUES(1935733,2548,8,0,'شبی می‌گفت چشمِ کَس ندیده‌ست','شبی کسی به من می‌گفت که چشم هیچکس از مرواید و گوشوارهٔ بندگی‌ای که در گوش من است، زیباتر و بهتر ندیده است (شنیدن این نکته را با وجود تاریکیِ شب هم بسنجید)',NULL);
INSERT INTO "verses" VALUES(1935734,2548,7,1,'که رأی پیر از بختِ جوان به',NULL,NULL);
INSERT INTO "verses" VALUES(1935735,2548,7,0,'جوانا! سَر متاب از پندِ پیران','ای جوان، از نصیحت‌های پیران سرپیچی نکن. چرا که رأی و نظر پیران از بخت جوانی تو بهتر است.',NULL);
INSERT INTO "verses" VALUES(1935736,2548,6,1,'به حکم آن که دولت جاودان به',NULL,NULL);
INSERT INTO "verses" VALUES(1935737,2548,6,0,'دلا! دائم گدای کوی او باش','ای دل، همیشه از درگاه او طلبکار و نیازمند باش، چرا که او دولتی جاودانه دارد و نعمت و خوشبختی جاودان در انتظار توست.',NULL);
INSERT INTO "verses" VALUES(1935738,2548,5,1,'که این سیب زَنَخ، زآن بوستان به',NULL,NULL);
INSERT INTO "verses" VALUES(1935739,2548,5,0,'به خلدم دعوت ای زاهد! مفرما','ای زاهد، مرا به بهشت دعوت نکن؛ که این رخساره و زیبایی از تمام آن بوستان بهتر است (نکتهٔ گفتنی این است که در معنی کردن شیرینی تناسب و بلاغت شعریِ انتخاب کردن یک سیب و رها کردن یک باغ از بین می‌رود).',NULL);
INSERT INTO "verses" VALUES(1935740,2548,4,1,'بود خاکش ز خونِ ارغوان به',NULL,NULL);
INSERT INTO "verses" VALUES(1935741,2548,4,0,'گُلی کآن پایمالِ سروِ ما گشت','گلی که زیر پای سرو ما (معشوق و محبوب) خاکسار شد، فکر نکن خاک شد و بی‌مقدار شد، خاکش حتی بهتر از خون ارغوان است.',NULL);
INSERT INTO "verses" VALUES(1935742,2548,3,1,'که آخِر کِی شود این ناتوان به؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935743,2548,3,0,'خدا را از طبیبِ من بپرسید','شما را به خدا قسم می‌دهم، از طبیب من بپرسید که بالأخره کِی این ناتوان بهتر خواهد شد؟',NULL);
INSERT INTO "verses" VALUES(1935744,2548,2,1,'به جان او که از مُلکِ جهان به',NULL,NULL);
INSERT INTO "verses" VALUES(1935745,2548,2,0,'به داغ بندگی مردن بر این در','با حسرت بندگی کردن اگر بر این آستانه و درگاه بمیری، به جان او قسم که از پادشاهی بر جهان بهتر است.',NULL);
INSERT INTO "verses" VALUES(1935746,2548,9,1,'ولی شیرازِ ما از اصفهان به',NULL,NULL);
INSERT INTO "verses" VALUES(1935747,2548,1,1,'که راز دوست از دشمن نهان به',NULL,NULL);
INSERT INTO "verses" VALUES(1935748,2548,0,1,'خداوندا مرا آن ده که آن به',NULL,NULL);
INSERT INTO "verses" VALUES(1935749,2548,0,0,'وصال او ز عمر جاودان به','وصال او (معشوقه) از عمر جاودانه بهتر است. خداوندا به من «آن» را بده که من خودم می‌دانم «آن» بهتر است... یا... خداوندا به من آن‌چیزی را عطا کن که تو می‌دانی همان بهتر است... یا ... وصال خداوند از عمر جاودانه بهتر است. خداوندا به من مرگ را ببخش که مرگ بهتر است.',NULL);
INSERT INTO "verses" VALUES(1935750,2547,6,1,'خون بایدت خورد در گاه و بی‌گاه',NULL,NULL);
INSERT INTO "verses" VALUES(1935751,2547,6,0,'حافظ چه نالی گر وصل خواهی؟','حافظ! چرا آه و ناله می‌کنی؟ اگر می‌خواهی به آن که عاشقش هستی برسی باید وقت و بی‌وقت زخم بخوری و رنج بکشی. آه و ناله ندارد.',NULL);
INSERT INTO "verses" VALUES(1935752,2547,5,1,'یا لَیتَ شِعري حَتّامَ أَلْقاه',NULL,NULL);
INSERT INTO "verses" VALUES(1935753,2547,5,0,'اَلصَبرُ مُرٌّ و العُمرُ فانٍ','هوش مصنوعی: صبر کردن سخت و تلخ است و زندگی کوتاه می‌گذرد، ای کاش می‌دانستم که در پایان چه چیزی در انتظار من است.',NULL);
INSERT INTO "verses" VALUES(1935754,2547,4,1,'آیینه‌رویا! آه از دلت آه',NULL,NULL);
INSERT INTO "verses" VALUES(1935755,2547,4,0,'مهر تو عکسی بر ما نیفکند','هوش مصنوعی: عشق تو هیچ نشانه‌ای از خود بر ما نمی‌گذارد، ای کسی که چهره‌ات چون آینه است! آه از دل تو، آه!',NULL);
INSERT INTO "verses" VALUES(1935756,2547,3,1,'آن گاه توبه؟ استغفرالله',NULL,NULL);
INSERT INTO "verses" VALUES(1935757,2547,3,0,'من رند و عاشق در موسم گل','به من رند و عاشق می‌گویی که وقت بهار و موسم گل توبه کنم؟! دهانت را آب بکش!',NULL);
INSERT INTO "verses" VALUES(1935758,2547,2,1,'یا جام باده یا قصه کوتاه',NULL,NULL);
INSERT INTO "verses" VALUES(1935759,2547,2,0,'ما شیخ و واعظ کمتر شناسیم','ما آخوندها و شیخها را نمی‌شناسیم، اگر می‌خواهی با ما همصحبت شوی از شراب صحبت کن یا هیچ حرفی نزن.',NULL);
INSERT INTO "verses" VALUES(1935760,2547,1,1,'لیکن چه چاره با بخت گمراه؟ ',NULL,NULL);
INSERT INTO "verses" VALUES(1935761,2547,1,0,'آیین تقوا ما نیز دانیم','ما هم از اصول تقوا باخبر هستیم، اما چه کنیم با تقدیر',NULL);
INSERT INTO "verses" VALUES(1935762,2548,1,0,'به شمشیرم زد و با کَس نگفتم','او به من زخم زد و به هیچ‌کس نگفتم که بهتر است راز دوست را از دشمنی پنهان کنی (باز با اینکه زخم بر من زد که کار دشمنان است، همچنان دوست‌تر از خیلی‌ها می‌دانمش).',NULL);
INSERT INTO "verses" VALUES(1935763,2544,8,1,'بر آن غریب ما چه گذشت؟ ای صبا بگو',NULL,NULL);
INSERT INTO "verses" VALUES(1935764,2552,6,0,'گفتم ای جان جهان دفتر گل عیبی نیست','(در پاسخ به مُغبچه ای که مرا سرزنش و نصیحت می کرد) گفتم: ای عزیزتر از همه ی جهانیان، اینها که گفتی و شنیدم درست، امّا ایرادی هم ندارد که در موسم بهار باده ی ناب بنوشی جرعه ای نیز به گلها بپاشی و اوراق گل را با شراب خیس کنی تا طرب انگیزتر و شاداب تر گردند.',NULL);
INSERT INTO "verses" VALUES(1935765,2552,6,1,'که شود فصل بهار از می ناب آلوده',NULL,NULL);
INSERT INTO "verses" VALUES(1935766,2558,6,0,'بادِ صبا ز عهدِ صبی یاد می‌دهد','هوش مصنوعی: باد صبا یادآور دوران کودکی است و مانند دارویی عمل می‌کند که می‌تواند درد و غم را از جان انسان بزداید. ای کودک، این یادآوری به تو کمک می‌کند تا از غم‌ها رها شوی.',NULL);
INSERT INTO "verses" VALUES(1935767,2558,5,1,'و امروز نیز ساقیِ مه‌روی و جام می',NULL,NULL);
INSERT INTO "verses" VALUES(1935768,2558,5,0,'فردا شرابِ کوثر و حور از برای ماست','هوش مصنوعی: فردا بهشتیان و نعمت‌های بهشتی برای ما فراهم خواهند بود، اما امروز هم نوشیدن شراب و لذت بردن از زیبایی‌های دنیا هست.',NULL);
INSERT INTO "verses" VALUES(1935769,2558,4,1,'ای وای بر کسی که شد ایمن ز مکرِ وی',NULL,NULL);
INSERT INTO "verses" VALUES(1935770,2558,4,0,'بر مِهرِ چرخ و شیوهٔ او اعتماد نیست','هوش مصنوعی: بر روی چرخ فلک و روش‌های آن نمی‌توان اعتماد کرد. وای بر کسی که فریب نیرنگ‌های آن را خورده و خود را در امان می‌بیند.',NULL);
INSERT INTO "verses" VALUES(1935771,2558,3,1,'کآشفتگی مبادت از آشوبِ بادِ دی',NULL,NULL);
INSERT INTO "verses" VALUES(1935772,2558,3,0,'خوش‌نازکانه می‌چمی ای شاخ نوبهار!','هوش مصنوعی: ای شاخه‌ی بهار، با ناز و لطافت می‌رقصی، ولی مواظب باش که از بادهای طوفانی و آشفته به هم نریزی.',NULL);
INSERT INTO "verses" VALUES(1935773,2558,2,1,'بیدار شو که خوابِ عدم در پی است، هی',NULL,NULL);
INSERT INTO "verses" VALUES(1935774,2558,2,0,'هشیار شو که مرغِ چمن مست گشت، هان','هوش مصنوعی: هشیار باش که پرندهٔ باغ شاد و سرحال شده است. بیدار شو زیرا خواب نابودی در کمین است.',NULL);
INSERT INTO "verses" VALUES(1935775,2558,1,1,'چینِ قبای قیصر و طرْفِ کلاهِ کی',NULL,NULL);
INSERT INTO "verses" VALUES(1935776,2558,1,0,'بگذر ز کبر و ناز که دیده‌ست روزگار','هوش مصنوعی: از خودپسندی و فخر بیرون بیا، چون زمانه دگرگونی‌های بسیاری را دیده است؛ روزگاری که حتی شکوه و مقام قیصر و زیبایی‌های تاج او نیز پایدار نبوده‌اند.',NULL);
INSERT INTO "verses" VALUES(1935777,2558,0,1,'طامات تا به چند و خرافات تا به کی؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935778,2558,0,0,'ساقی بیا که شد قدحِ لاله پر ز می','ساقی بیا دیگر کاسه وظرف گل لاله پرشد از می تاکی باید درگیر خرافات و حرف های بی محتوا باشیم',NULL);
INSERT INTO "verses" VALUES(1935779,2557,9,1,'که تحقیقش، فُسون است و فِسانه',NULL,NULL);
INSERT INTO "verses" VALUES(1935780,2557,9,0,'وجودِ ما معمایی‌ست، حافظ؛','هوش مصنوعی: وجود ما همچون معماست، و فهمیدن آن جادو و افسانه‌ای دارد.',NULL);
INSERT INTO "verses" VALUES(1935781,2557,8,1,'از این دریایِ ناپیداکرانه',NULL,NULL);
INSERT INTO "verses" VALUES(1935782,2557,8,0,'بِده کشتیِ مِی تا خوش برانیم،','هوش مصنوعی: به ما نوشیدنی بده تا با آن از این دریای نامشخص و بی‌کران عبور کنیم و به آرامش برسیم.',NULL);
INSERT INTO "verses" VALUES(1935783,2557,7,1,'خیالِ آب و گل در رَه، بهانه',NULL,NULL);
INSERT INTO "verses" VALUES(1935784,2557,7,0,'ندیم و مطرب و ساقی، همه اوست؛','هوش مصنوعی: دوست و نوازنده و شراب‌فروش همه یکی هستند. تصور کردن آب و گل تنها بهانه‌ای است در مسیر زندگی.',NULL);
INSERT INTO "verses" VALUES(1935785,2557,6,1,'کِه با خود عشق بازد جاودانه‌؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935786,2557,6,0,'کِه بَندد طرفِ وصل ازْ حُسنِ شاهی؟','هوش مصنوعی: کیست که بتواند به زیبایی شاهی، ارتباطی پایدار ایجاد کند؟ چون عشق همیشه با اوست و تا ابد ادامه دارد.',NULL);
INSERT INTO "verses" VALUES(1935787,2557,5,1,'که عَنقا را بلند است آشیانه!',NULL,NULL);
INSERT INTO "verses" VALUES(1935788,2557,5,0,'برو، این دام بر مرغی دگر نِه','هوش مصنوعی: برو این دام را برای پرنده‌ای دیگر بگذار، چرا که پرنده‌ای همچون عنقا آشیانه‌اش در بلندی‌هاست و به دام تو نمی‌افتد.',NULL);
INSERT INTO "verses" VALUES(1935789,2557,4,1,'اگر خود را ببینی در میانه',NULL,NULL);
INSERT INTO "verses" VALUES(1935790,2557,4,0,'نبندی زان میان طرفی، کمروار،','از آن معشوقِ کمر‌باریک چیزی نصیبت نمی‌شود، اگر خودت را در میانه ببینی.',NULL);
INSERT INTO "verses" VALUES(1935791,2557,3,1,'که ای تیرِ ملامت را نشانه!',NULL,NULL);
INSERT INTO "verses" VALUES(1935792,2557,3,0,'زِ ساقیِ کمان ‌ابرو شنیدم؛','هوش مصنوعی: از ساقی با کمان ابروی خوش‌نما شنیدم که ای تیر ملامت، به ما هدف بزن.',NULL);
INSERT INTO "verses" VALUES(1935793,2557,2,1,'که ایمن گشتمَ از مکرِ زمانه',NULL,NULL);
INSERT INTO "verses" VALUES(1935794,2557,2,0,'نگارِ مِی‌فروشم عشوه‌ای داد،','هوش مصنوعی: دلبر زیبایی به من نگاهی کرد که در آن نگاه، من از فریب و نیرنگ‌های دنیا در امان شدم.',NULL);
INSERT INTO "verses" VALUES(1935795,2558,6,1,'جان‌دارویی که غم ببرد درده ای صبی!',NULL,NULL);
INSERT INTO "verses" VALUES(1935796,2558,7,0,'حشمت مبین و سلطنتِ گل، که بسپرد','فراش‌: فرش‌گستر، جاروب‌کش. پی‌: پا‌.',NULL);
INSERT INTO "verses" VALUES(1935797,2558,7,1,'فراشِ باد هر ورقش را به زیر پی',NULL,NULL);
INSERT INTO "verses" VALUES(1935798,2558,8,0,'درده به یاد حاتمِ طی جام یک منی','هوش مصنوعی: دردی که از یاد حاتم طایی داری، چون یک جام شراب است که می‌تواند ما را یاری کند تا نامه‌های بد و حسادت دیگران را پاک کنیم.',NULL);
INSERT INTO "verses" VALUES(1935799,2560,2,0,'لبش می‌بوسد و خون می‌خورد جام','هوش مصنوعی: او لبانش را می‌بوسد و احساس شوق و لذت می‌کند، وقتی اسبش را می‌بیند، همچون گل از شادی می‌شکفد.',NULL);
INSERT INTO "verses" VALUES(1935800,2560,1,1,'نه کس را می‌توانم دید با وی',NULL,NULL);
INSERT INTO "verses" VALUES(1935801,2560,1,0,'نه رازش می‌توانم گفت با کس',': نه می‌توانم رازهای خود را با کسی در میان بگذارم و نه می‌توانم ببینم او کسی را ملاقات میکند .',NULL);
INSERT INTO "verses" VALUES(1935802,2560,0,1,'به آب زندگانی برده‌ام پی',NULL,NULL);
INSERT INTO "verses" VALUES(1935803,2560,0,0,'لبش می‌بوسم و در می‌کشم می','هوش مصنوعی: من لب‌هایش را می‌بوسم و در عمیق می‌کشم. انگار که شرابی از زندگی به دست آورده‌ام.',NULL);
INSERT INTO "verses" VALUES(1935804,2559,8,1,'پیاله گیر و کَرَم وَرز، وَ الضَّمانُ عَلَيّ',NULL,NULL);
INSERT INTO "verses" VALUES(1935805,2559,8,0,'بخیل، بوی خدا نشنود بیا حافظ','هوش مصنوعی: آن که بخیل و تنگ‌نظر است، هرگز نمی‌تواند عطر وجود خداوند را حس کند. بنابراین، ای حافظ، باده بنوش و با دیگران نیکوکاری کن؛ زیرا در نهایت، هر کس به دیگران کمک کند، مورد حمایت و رحمت قرار می‌گیرد.',NULL);
INSERT INTO "verses" VALUES(1935806,2559,7,1,'بده به شادیِ روح و روانِ حاتمِ طَی',NULL,NULL);
INSERT INTO "verses" VALUES(1935807,2559,7,0,'سَخا نمانْد، سخن طی کنم، شراب کجاست؟','هوش مصنوعی: سخاوت و بخشش دیگر وجود ندارد، من می‌خواهم صحبت کنم، ولی کجا می‌توانم شراب پیدا کنم؟ بیا تا به روح و روان حاتم طائی شادی ببخشیم.',NULL);
INSERT INTO "verses" VALUES(1935808,2559,6,1,'که هر که عشوهٔ دُنییِ خرید، وای به وی',NULL,NULL);
INSERT INTO "verses" VALUES(1935809,2559,6,0,'نوشته‌اند بر اِیوانِ جَنةُ المَأویٰ','عشوه دنیی خرید‌: فریب دنیا را خورد.',NULL);
INSERT INTO "verses" VALUES(1935810,2559,5,1,'مجو ز سفله مروَّت، که شَیئُهُ لا شَی',NULL,NULL);
INSERT INTO "verses" VALUES(1935811,2559,5,0,'زمانه هیچ نبَخشد که باز نستانَد','هوش مصنوعی: دنیا هیچ وقت چیزی را نمی‌بخشد، پس به دنبال محبت و صداقت از افرادی که ارزششان پایین است، نروید؛ زیرا در حقیقت آنها چیزی برای ارائه ندارند.',NULL);
INSERT INTO "verses" VALUES(1935812,2559,4,1,'به قولِ مطرب و ساقی، به فَتویِ دَف و نِی',NULL,NULL);
INSERT INTO "verses" VALUES(1935813,2557,1,1,'زِ شهرِ هستی‌اش کردم روانه',NULL,NULL);
INSERT INTO "verses" VALUES(1935814,2559,4,0,'خزینه‌داری میراث‌خوارگان کفر است','هوش مصنوعی: نگهداری از ثروت و دارایی‌های به ارث رسیده، در نظر برخی، مشتی کفر و گناه محسوب می‌شود، همان‌طور که موسیقی‌دان و نوشیدن‌کننده می‌گویند.',NULL);
INSERT INTO "verses" VALUES(1935815,2559,3,0,'شُکوهِ سلطنت و حُسن، کِی ثَباتی داد؟','هوش مصنوعی: سلطنت و زیبایی هرگز پایدار نمی‌مانند. تنها خاطره‌ای از تخت جمشید و تاج کیانی باقی مانده است.',NULL);
INSERT INTO "verses" VALUES(1935816,2559,2,1,'مَنهْ ز دست پیاله، چه می‌کُنی؟ هِی‌هِی',NULL,NULL);
INSERT INTO "verses" VALUES(1935817,2559,2,0,'چو گُل نقاب برافکنْد و مرغ زد هوهو','هوش مصنوعی: زمانی که گل زیبایی‌اش را نمایان می‌کند و پرنده‌ای آوازش را سر می‌دهد، چرا در حالی که پیاله را در دستت داری، به فکر دیگری هستی؟ چرا نگران هستی؟',NULL);
INSERT INTO "verses" VALUES(1935818,2559,1,1,'که می‌رسند ز پی، رهزنانِ بهمن و دی',NULL,NULL);
INSERT INTO "verses" VALUES(1935819,2559,1,0,'ذخیره‌ای بنهْ ار رنگ و بویِ فصل بهار','هوش مصنوعی: از زیبایی‌ها و لذت‌های فصل بهار بهره‌برداری کن، زیرا زمستان و سردی آن به زودی فرا می‌رسند و بهار گذرا خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1935820,2559,0,1,'علاج کِی کُنمت؟ آخَرالدَواءِ الْکَیْ',NULL,NULL);
INSERT INTO "verses" VALUES(1935821,2559,0,0,'به صوتِ بلبل و قمری اگر ننوشی مِی','هوش مصنوعی: اگر به صدای بلبل و قمری گوش ندهی و از این زیبایی‌ها بهره‌ای نبری، چطور می‌خواهی درمانی برای دلخوشی‌ات پیدا کنی؟ در نهایت، تنها تسلایت می‌تواند تو را آرام کند.',NULL);
INSERT INTO "verses" VALUES(1935822,2558,11,1,'تا حدِ مصر و چین و به اطرافِ روم و ری',NULL,NULL);
INSERT INTO "verses" VALUES(1935823,2558,11,0,'حافظ حدیثِ سحرفریبِ خوشت رسید','حد‌: مرز‌.',NULL);
INSERT INTO "verses" VALUES(1935824,2558,10,1,'استاده است سرو و کمر بسته است نی',NULL,NULL);
INSERT INTO "verses" VALUES(1935825,2558,10,0,'مسند به باغ بر که به خدمت چو بندگان','هوش مصنوعی: در باغی زیبا، درخت سرو به خاطر شخصی که در آنجا ایستاده، خود را آراسته و آماده خدمت کرده است. این درخت به گونه‌ای خود را مرتب کرده که نشان‌دهنده احترام و خدمت‌گزاری است.',NULL);
INSERT INTO "verses" VALUES(1935826,2558,9,1,'بیرون فکند لطف مزاج از رخش به خوی',NULL,NULL);
INSERT INTO "verses" VALUES(1935827,2558,9,0,'زآن می که داد حُسن و لطافت به ارغوان','هوش مصنوعی: از آن می که زیبایی و نرمی را به رنگ ارغوان هدیه داد، لطف و خوبی در طبع او از چهره‌اش نمایان شده است.',NULL);
INSERT INTO "verses" VALUES(1935828,2558,8,1,'تا نامهٔ سیاه بخیلان کنیم طی',NULL,NULL);
INSERT INTO "verses" VALUES(1935829,2559,3,1,'ز تختِ جَم سخنی مانده است و افسرِ کَی',NULL,NULL);
INSERT INTO "verses" VALUES(1935830,2552,7,0,'آشنایانِ رهِ عشق در این بحر عمیق','آنها که عشق را می شناسند و در طریق عشق قدم بر می‌دارند با عجایب و شگفتیهای عشق آشنایی دارند آنها به رغم آنکه در دریای بیکران علایق و وابستگیهای دنیوی فرو می روند لیکن به لطف قدرت عشق حتّا به اندازه ی مویی آلوده نمی‌شوند!',NULL);
INSERT INTO "verses" VALUES(1935831,2557,1,0,'نهادم عقل را ره ‌توشه از مِی،','عقل را غذای سفر و زادراه از باده دادم و او را از شهر هستی بیرون فرستادم.',NULL);
INSERT INTO "verses" VALUES(1935832,2557,0,0,'سحرگاهان، که مخمورِ شبانه','چَغانه‌: نوعی ساز.',NULL);
INSERT INTO "verses" VALUES(1935833,2554,7,1,'روزی کرشمه‌ای کن، ای یار برگزیده!',NULL,NULL);
INSERT INTO "verses" VALUES(1935834,2554,7,0,'تا کی کِشم عتیبت؟ از چشم دل‌فریبت','عتیب‌: عتاب‌، خشم.',NULL);
INSERT INTO "verses" VALUES(1935835,2554,6,1,'دنیا وفا ندارد ای نور هر دو دیده',NULL,NULL);
INSERT INTO "verses" VALUES(1935836,2554,6,0,'زنهار تا توانی اهل نظر میآزار','زنهار و دوری کن از آنکه اهل نظر را بیازاری؛ دنیا زودگذر و بی‌وفاست ای عزیز جان!',NULL);
INSERT INTO "verses" VALUES(1935837,2554,5,1,'یاران چه چاره سازم با این دل رمیده؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935838,2554,5,0,'آن آهوی سیه‌چشم از دام ما برون شد','دریغ که به آن آهوی خرامنده سیاه‌چشم نرسیدیم، ای دوستان، با این دل عاشق و رمیده چه کنم؟',NULL);
INSERT INTO "verses" VALUES(1935839,2554,4,1,'وآن رفتن خوشش بین، وآن گام آرمیده',NULL,NULL);
INSERT INTO "verses" VALUES(1935840,2554,4,0,'آن لعل دلکشش بین، وآن خندهٔ دل‌آشوب','لب دلربای او را ببین و آن خنده عاشق‌کش را و آن راه رفتن زیبا و آن گام‌های باوقارش را.',NULL);
INSERT INTO "verses" VALUES(1935841,2554,3,1,'شمشاد خوش‌خرامش در ناز پروریده',NULL,NULL);
INSERT INTO "verses" VALUES(1935842,2554,3,0,'یاقوت جان‌فزایش از آب لطف زاده','یاقوت لبش از آب لطافت و نرمی‌، ساخته شده و بالای خوش‌خرام او همچون شمشادی بود که با ناز بپرورند.',NULL);
INSERT INTO "verses" VALUES(1935843,2554,2,1,'رویی لطیف، زیبا، چشمی، خوش کشیده',NULL,NULL);
INSERT INTO "verses" VALUES(1935844,2554,2,0,'لفظی فصیح، شیرین، قدی بلند، چابک','زبانی شیرین و خوش‌سخن و قدی بلند و چابک رو و چشمانی کشیده و صورتی لطیف.',NULL);
INSERT INTO "verses" VALUES(1935845,2554,1,1,'چون قطره‌های شبنم بر برگ گل چکیده',NULL,NULL);
INSERT INTO "verses" VALUES(1935846,2554,1,0,'از تاب آتش مِی، بر گِرد عارضش خوی','از گرمی آتش باده‌، دانه‌های عرق همچون شبنم که بر برگ گل است بر رخسار او بود.',NULL);
INSERT INTO "verses" VALUES(1935847,2554,0,1,'صد ماهرو ز رشکش جَیب قصب دریده',NULL,NULL);
INSERT INTO "verses" VALUES(1935848,2554,0,0,'دامن‌کشان همی شد در شرب زرکشیده','شَرب‌: جامه از کتان لطیف‌.',NULL);
INSERT INTO "verses" VALUES(1935849,2553,4,1,'بیش از گلیم خویش مگر پا کشیده‌ای',NULL,NULL);
INSERT INTO "verses" VALUES(1935850,2553,4,0,'آن سرزنش که کرد تو را دوست حافظا','هوش مصنوعی: دوست تو، حافظ جان، اگر از تو انتقادی کرد، باید بدانی که او بیشتر از آنچه خود دارد به تو توجه کرده است. آیا خود را در مشکلات دیگران نمی‌بیند که اینقدر سرزنشت می‌کند؟',NULL);
INSERT INTO "verses" VALUES(1935851,2553,3,1,'معذور دارمت که تو او را ندیده‌ای',NULL,NULL);
INSERT INTO "verses" VALUES(1935852,2553,3,0,'منعم مکن ز عشق وی ای مفتی زمان','هوش مصنوعی: ای مفتی زمان، محبت او را از من دریغ نکن، چون تو هرگز او را ندیده‌ای و در این باره از تو معذورم.',NULL);
INSERT INTO "verses" VALUES(1935853,2553,2,1,'در دلبری، به غایتِ خوبی رسیده‌ای',NULL,NULL);
INSERT INTO "verses" VALUES(1935854,2553,2,0,'از چشم بخت خویش، مبادت گزند از آنک','هوش مصنوعی: مبادا به سرنوشت خود آسیب برسانی، زیرا در هنر دلربایی به اوج زیبایی دست یافته‌ای.',NULL);
INSERT INTO "verses" VALUES(1935855,2553,1,1,'پیراهن صبوری ایشان دریده‌ای',NULL,NULL);
INSERT INTO "verses" VALUES(1935856,2553,1,0,'از دامن تو دست ندارند عاشقان','هوش مصنوعی: عاشقان از محبت تو با هیچ چیز دیگری سر و کار ندارند و صبر و استقامت آنها در برابر مشکلات به کلی از بین رفته است.',NULL);
INSERT INTO "verses" VALUES(1935857,2553,0,1,'آرام جان و مونس قلب رمیده‌ای',NULL,NULL);
INSERT INTO "verses" VALUES(1935858,2553,0,0,'از من جدا مشو که توام نور دیده‌ای','هوش مصنوعی: از من دور نشو، زیرا تو روشنایی چشمان من و آرامش دل و همراه من هستی.',NULL);
INSERT INTO "verses" VALUES(1935859,2552,7,1,'غرقه گشتند و نگشتند به آب آلوده',NULL,NULL);
INSERT INTO "verses" VALUES(1935860,2552,8,0,'گفت حافظ لغز و نکته به یاران مفروش','مغبچه گفت: ای حافظ ختم کن اینقدر معمّا و نکات معنادار و کنایه آمیز به رخ دوستان خودمکش!حافظ دوباره به کنایه آهی از سر درد می‌کشد(البته به مزاح وشوخی) و می فرماید:سخنانت سرشار از لطایف و ظرایف است فریاد از لطف و محبّتِ کنایه دار و ملامت بار! امان از لطف و محبّت هایی که به سرزنش های مکدّر کننده آلوده هستند!',NULL);
INSERT INTO "verses" VALUES(1935861,2552,8,1,'آه از این لطف به انواع عتاب آلوده',NULL,NULL);
INSERT INTO "verses" VALUES(1935862,2554,8,0,'گر خاطر شریفت رنجیده شد ز حافظ','اگر خاطر عزیز و محترم تو از حافظ رنجیده گشت؛ باز آ که از هرچه گفتیم و شنیدیم پشیمان شدیم و عذر می‌خواهیم.',NULL);
INSERT INTO "verses" VALUES(1935863,2554,8,1,'بازآ که توبه کردیم از گفته و شنیده',NULL,NULL);
INSERT INTO "verses" VALUES(1935864,2554,9,0,'بس شکر بازگویم در بندگیِ خواجه','باز در خدمت‌گزاری خواجه بسیار شکر خواهم گفت اگر آن میوه رسیده به‌دستم برسد.',NULL);
INSERT INTO "verses" VALUES(1935865,2554,9,1,'گر اوفتد به دستم آن میوهٔ رسیده',NULL,NULL);
INSERT INTO "verses" VALUES(1935866,2556,8,1,'فتاد در سر حافظ هوای میخانه',NULL,NULL);
INSERT INTO "verses" VALUES(1935867,2556,8,0,'حدیث مدرسه و خانقه مگوی که باز','از مدرسه و خانقاه سخن مگو که باز هوای می‌خانه در سر حافظ افتاد.',NULL);
INSERT INTO "verses" VALUES(1935868,2556,7,1,'که بر زبان نبرم جز حدیث پیمانه',NULL,NULL);
INSERT INTO "verses" VALUES(1935869,2556,7,0,'مرا به دور لب دوست هست پیمانی','با لب دوست و یار خود پیمان بسته‌ام که جز سخن مستی و عشق‌، چیزی نگویم.',NULL);
INSERT INTO "verses" VALUES(1935870,2556,6,1,'ز شمع روی تواَش چون رسید پروانه',NULL,NULL);
INSERT INTO "verses" VALUES(1935871,2556,6,0,'به مژده، جان به صبا داد شمع در نفسی','در نفَسی‌: در یک آن‌، فورا. پروانه: مجازا به معنی نور و پرتو چراغ و شمع || و نیز به معنی اجازه و برات.',NULL);
INSERT INTO "verses" VALUES(1935872,2556,5,1,'به غیر خال سیاهش که دید به دانه؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935873,2556,5,0,'بر آتش رخ زیبای او به جای سپند','بر رخ پر‌حرارت و گرم او به غیر از خال سیاهش که همچون سپند (او را از چشم بد نگه‌می‌دارد) چه کسی دانه‌ای زیباتر دیده است؟',NULL);
INSERT INTO "verses" VALUES(1935874,2556,4,1,'فسون ما بر او گشته است افسانه',NULL,NULL);
INSERT INTO "verses" VALUES(1935875,2556,4,0,'چه نقش‌ها که برانگیختیم و سود نداشت','چه ترفند‌ها و حیله‌ها کردیم اما سود نکرد؛ فسون و حیله‌های ما برای او همچون داستانی قدیمی است.',NULL);
INSERT INTO "verses" VALUES(1935876,2556,3,1,'نگار خویش چو دیدم به دست بیگانه',NULL,NULL);
INSERT INTO "verses" VALUES(1935877,2556,3,0,'من‌ِ رمیده ز غیرت ز پا فتادم دوش','من رمیده‌غیرت که به هیچ‌کس غیرت نورزیده‌ام وقتی که نگار و محبوب خود را در دست بیگانه دیدم از فرط غیرت و غم از پای در‌افتادم.',NULL);
INSERT INTO "verses" VALUES(1935878,2556,2,1,'هزار جان گرامی فدای جانانه',NULL,NULL);
INSERT INTO "verses" VALUES(1935879,2556,2,0,'به بوی زلف تو گر جان به باد رفت‌، چه شد؟','در آرزوی وصال زلف تو هر جان که کشته گشت، همه فدای تو باد ای جان‌ِ جان!',NULL);
INSERT INTO "verses" VALUES(1935880,2557,0,1,'گرفتم باده با چنگ و چَغانه',NULL,NULL);
INSERT INTO "verses" VALUES(1935881,2556,1,1,'به بوی سنبل زلف تو گشت دیوانه',NULL,NULL);
INSERT INTO "verses" VALUES(1935882,2556,0,1,'مرا ز حال تو با حال خویش پروا، نه',NULL,NULL);
INSERT INTO "verses" VALUES(1935883,2556,0,0,'چراغ روی تو را شمع گشت پروانه','از نور رخسار تو چنان بر شمع رفت که خود همچون پروانه عاشق تو شد، من در عشقت چنانم که از خود بی‌خبرم.',NULL);
INSERT INTO "verses" VALUES(1935884,2555,5,1,'حَتّیٰ یَذوقَ مِنهُ، کأساً مِن الکرامه',NULL,NULL);
INSERT INTO "verses" VALUES(1935885,2555,5,0,'حافظ چو طالب آمد، جامی به جان شیرین','حافظ خواهان آن شد که در بهای نوشیدن جام شرابی، جان شیرین خود را فدا کند تا از آن جام، باده ای از کرامت و محبت معشوق بنوشد.',NULL);
INSERT INTO "verses" VALUES(1935886,2555,4,1,'و اللهِ ما رَأینا، حُباً بِلا ملامه',NULL,NULL);
INSERT INTO "verses" VALUES(1935887,2555,4,0,'گفتم «ملامت آید، گر گِرد دوست گردم»','گفتم: اگر در اطراف معشوق بگردم، مورد سرزنش و مؤاخذه قرار می گیرم. سوگند به خدا که ما هیچ عشقی را بدون ملامت ندیده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1935888,2555,3,1,'«فی بُعدها عذابٌ، فی قُربها السلامه»',NULL,NULL);
INSERT INTO "verses" VALUES(1935889,2555,3,0,'پرسیدم از طبیبی، احوال دوست گفتا','از طبیب (انسان دل آگاهی) احوال دوست داشتن (عشق) را سؤال کردم. در پاسخ گفت: اگر تو از او دور باشی، عذاب است و اگر به او نزدیک باشی، برای تو سلامت و آرامش است.',NULL);
INSERT INTO "verses" VALUES(1935890,2555,2,1,'مَن جَرَّبَ المُجَرَّب، حَلَّت به الندامه',NULL,NULL);
INSERT INTO "verses" VALUES(1935891,2555,2,0,'هر چند کآزمودم، از وی نبود سودم','هر چه توانستم او را آزمودم، ولی وصال او ممکن نشد و سودی برایم نداشت. کسی که آزموده را بار دیگر بیازماید، پشیمانی برای او رواست.',NULL);
INSERT INTO "verses" VALUES(1935892,2555,1,1,'لَیسَت دُموعُ عَینی، هٰذا لَنا العلامه؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935893,2555,1,0,'دارم من از فراقش، در دیده صد علامت','از دوری معشوق در چشمم صد نشانه و علامت وجود دارد. آیا این اشک های چشم من برای درد فراق، علامتی نیست؟',NULL);
INSERT INTO "verses" VALUES(1935894,2555,0,1,'«اِنّی رَأیتُ دَهراً، مِن هَجْرِکَ القیامه»',NULL,NULL);
INSERT INTO "verses" VALUES(1935895,2555,0,0,'از خون دل نوشتم، نزدیک دوست نامه','نامه‌ای به معشوق خود نوشتم؛ چنان نامهٔ غمزده ای که انگار آن را با خون دل نوشته‌ام [که] من در فراق تو دنیا را چون روز قیامت سخت و طولانی می‌بینم.',NULL);
INSERT INTO "verses" VALUES(1935896,2556,1,0,'خِرد که قید مجانین عشق می‌فرمود','خرَد که حُکم زنجیرِ دیوانگان عشق را صادر می‌کرد، خود به عطر خوش زلفِ تو دیوانه شد. («بوی» معنی آرزو هم می‌دهد؛ در آرزوی رسیدن به زنجیر زلفت، دیوانه گشت.)',NULL);
INSERT INTO "verses" VALUES(1935897,2385,3,1,'که دردِ خویش بگویم به نالهٔ بَم و زیر',NULL,NULL);
INSERT INTO "verses" VALUES(1935898,2385,3,0,'معاشری خوش و رودی بساز می‌خواهم','همدمی نیکو و ساز (عودی) هم‌نوا می‌خواهم که با ناله زیر و بم آن، دردهای خود را بگویم.',NULL);
INSERT INTO "verses" VALUES(1935899,2385,2,1,'که این متاعِ قلیل است و آن عَطایِ کثیر',NULL,NULL);
INSERT INTO "verses" VALUES(1935900,2215,2,0,'آن عشوه داد عشق که مفتی ز ره برفت','عشق، چنان عشوه و نازی نمود که مفتی و فقیه از راه به‌در شد، دوست چنان لطفی کرد که دشمن، حساب کار خود را کرد.',NULL);
INSERT INTO "verses" VALUES(1935901,2215,1,0,'آن شمعِ سرگرفته دگر چهره برفروخت','آن شمع خاموش دوباره روشن شد؛ و این پیر ناتوان و ضعیف دوباره جوان و توانا شد.',NULL);
INSERT INTO "verses" VALUES(1935902,2215,1,1,'وین پیرِ سال‌خورده جوانی ز سر گرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935903,2215,0,0,'ساقی بیا که یار ز رخ پرده برگرفت','ساقی بیا و باده بریز که یار چهره نمایاند و رخ او مجلس خلوتیان را روشن کرد.',NULL);
INSERT INTO "verses" VALUES(1935904,2215,0,1,'کارِ چراغ خلوتیان باز درگرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935905,2214,0,0,'شربتی از لبِ لعلش نچشیدیم و بِرَفت','هوش مصنوعی: ما هرگز از لب‌های شیرین او جرعه‌ای ننوشیدیم و وقتی که او رفت، نتوانستیم چهره‌اش را به‌خوبی ببینیم و دیگر نیز به یادش نخواهیم بود.',NULL);
INSERT INTO "verses" VALUES(1935906,2214,0,1,'رویِ مَه پیکرِ او سیر ندیدیم و برفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935907,2214,1,0,'گویی از صحبتِ ما نیک به تنگ آمده بود','هوش مصنوعی: او به نظر می‌رسید که از گفت‌وگوهای ما خسته شده و در نهایت به سفرش ادامه داد و ما نتوانستیم به او برسیم.',NULL);
INSERT INTO "verses" VALUES(1935908,2214,1,1,'بار بربست و به گَردش نرسیدیم و برفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935909,2214,2,0,'بس که ما فاتحه و حرزِ یمانی خواندیم','هوش مصنوعی: ما آنقدر فاتحه و دعا خواندیم که به یاد آوردن آنها هم برایمان سخت شده است؛ به دنبال آن سوره اخلاص را نیز بر زبان راندیم و سپس از همه چیز گذشتیم.',NULL);
INSERT INTO "verses" VALUES(1935910,2214,2,1,'وز پی‌اش سوره اخلاص دمیدیم و برفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935911,2214,3,0,'عشوه دادند که بر ما گذری خواهی کرد','هوش مصنوعی: به ما ناز و کرشمه کردند و وعده دادند که یک بار از کنار ما بگذری، اما حالا دیدی که در نهایت با همین ناز و کرشمه‌ها از پیش ما رفتی.',NULL);
INSERT INTO "verses" VALUES(1935912,2214,3,1,'دیدی آخر که چنین عشوه خریدیم و برفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935913,2214,4,0,'شد چمان در چمنِ حسن و لطافت لیکن','هوش مصنوعی: در زیباگردی و خوشحالی در میان زیبایی و لطافت می‌گذرانیدم، اما در باغ وصال او از شادکامی بازماندم و از آنجا دور شدم.',NULL);
INSERT INTO "verses" VALUES(1935914,2214,4,1,'در گلستانِ وصالش نَچَمیدیم و برفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935915,2214,5,0,'همچو حافظ همه شب ناله و زاری کردیم','هوش مصنوعی: ما مانند حافظ تمام شب گریه و زاری کردیم و افسوس که نتوانستیم به وداعش برسیم و او رفت.',NULL);
INSERT INTO "verses" VALUES(1935916,2214,5,1,'کای دریغا به وداعش نرسیدیم و برفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935917,2213,0,0,'ساقی بیار باده که ماهِ صیام رفت','هوش مصنوعی: ای ساقی! باده بیاور که ماه روزه به پایان رسید. اینک جام را پر کن که زمان عشق و محبت فرارسیده است.',NULL);
INSERT INTO "verses" VALUES(1935918,2213,0,1,'دَردِه قدح که موسمِ ناموس و نام رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935919,2213,1,0,'وقتِ عزیز رفت بیا تا قضا کنیم','هوش مصنوعی: زمان با ارزش ما سپری شده است، بیایید تا بگذرانیم مدت عمری را که بدون حضور شراب و مینا گذشته است.',NULL);
INSERT INTO "verses" VALUES(1935920,2213,1,1,'عمری که بی حضور صُراحی و جام رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935921,2213,2,0,'مستم کن آن چنان که ندانم ز بی‌خودی','هوش مصنوعی: مرا به حالتی بینداز که در دنیای خیالم ندانم چه بر سرم آمده، کدام اندیشه یا احساس در این حالت به من دست داده و کدام یک از آنها رفته است.',NULL);
INSERT INTO "verses" VALUES(1935922,2213,2,1,'در عرصهٔ خیال که آمد، کدام رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935923,2213,3,0,'بر بوی آن که جرعهٔ جامت به ما رسد','هوش مصنوعی: به خاطر بوی خوشی که از جام تو به ما می‌رسد، دعا و آرزوی تو هر روز و هر شب ادامه دارد.',NULL);
INSERT INTO "verses" VALUES(1935924,2213,3,1,'در مَصطَبِه دعایِ تو هر صبح و شام رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935925,2213,4,0,'دل را که مرده بود حیاتی به جان رسید','هوش مصنوعی: دل که به خواب رفته بود، دوباره زنده شد و با نسیم عطر می، خوشبو گردید.',NULL);
INSERT INTO "verses" VALUES(1935926,2213,4,1,'تا بویی از نسیمِ می‌اش در مشام رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935927,2213,5,0,'زاهد غرور داشت، سلامت نبرد راه','هوش مصنوعی: زاهد با غرور خود نتوانست به درستی مسیر زندگی را انتخاب کند و به دنبال نیازها و حقیقت‌ها نرفت، بلکه از مسیر رندی و آگاهی به سوی آرامش و امنیت واقعی هدایت شد.',NULL);
INSERT INTO "verses" VALUES(1935928,2213,5,1,'رند از رهِ نیاز به دارالسلام رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935929,2215,2,1,'وان لطف کرد دوست که دشمن حذر گرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935930,2213,6,0,'نقدِ دلی که بود مرا صرف باده شد','هوش مصنوعی: دل شاد و گرانبهایی که در دست داشتم، به خاطر نوشیدن شراب از بین رفت. قلبی که زمانی پر از نور و خوبی بود، به خاطر آن باده به تباهی رفت.',NULL);
INSERT INTO "verses" VALUES(1935931,2215,3,0,'زنهار از آن عبارتِ شیرینِ دل‌فریب','هوش مصنوعی: مواظب باش که به کلام شیرینی که دل را فریب می‌دهد، اعتماد نکنی؛ چرا که ممکن است این سخن ظاهراً خوشمزه، در واقع تلخی‌هایی را در خود پنهان کرده باشد.',NULL);
INSERT INTO "verses" VALUES(1935932,2215,4,0,'بارِ غمی که خاطرِ ما خسته کرده بود','هوش مصنوعی: غم و اندوهی که دل ما را آزرده بود، در لحظه‌ای خداوند عیسی را فرستاد و آن غم را از ما برداشت.',NULL);
INSERT INTO "verses" VALUES(1935933,2217,0,0,'شنیده‌ام سخنی خوش که پیرِ کنعان گفت','از حضرت یعقوب _ پیر کنعان _ سخنی شیرین و دلپذیر شنیده ­ام: جدایی و دوری از یار چنان کاری می­ کند که نمی­ توان آن را بیان کرد',NULL);
INSERT INTO "verses" VALUES(1935934,2217,0,1,'«فِراق یار، نه آن می‌کند که بتوان گفت»',NULL,NULL);
INSERT INTO "verses" VALUES(1935935,2216,9,0,'حافظ چو آبِ لطف ز نظمِ تو می‌چِکد','حافظا وقتی که آب لطافت از نظم تو می‌چکد، حسود کی می‌تواند بر شعرت خرده بگیرد؟',NULL);
INSERT INTO "verses" VALUES(1935936,2216,9,1,'حاسِد چگونه نکته تواند بر آن گرفت؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935937,2216,8,0,'بر برگِ گُل به خونِ شقایق نوشته‌اند','از گل سرخ تا خون شقایق به تو می‌گویند: کسی پخته‌ و داناست که می زلال و ناب ارغوانی گرفت.',NULL);
INSERT INTO "verses" VALUES(1935938,2216,8,1,'«کآن کس که پخته شد، مِیِ چون اَرغَوان گرفت»',NULL,NULL);
INSERT INTO "verses" VALUES(1935939,2216,7,0,'مِی خور که هر که آخرِ کارِ جهان بِدید','هرکه دانا است و آخر کار جهان را دید پر از شادی شد و جام‌های می پر و سنگین را تهی کرد.',NULL);
INSERT INTO "verses" VALUES(1935940,2216,7,1,'از غم سبک برآمد و رَطلِ گران گرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935941,2216,6,0,'خواهم شدن به کویِ مُغان آستین‌فشان','شاد و فارغ از همه‌چیز دارم به‌سوی کوی می‌فروشان می‌روم از دست این فتنه‌های فراوان که (امروز) گویی آخرالزمان است.',NULL);
INSERT INTO "verses" VALUES(1935942,2216,6,1,'زین فتنه‌ها که دامنِ آخرزمان گرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935943,2216,5,0,'آن روز شوقِ ساغرِ مِی، خرمنم بسوخت','می نوش و می‌گسار نبودم تا روزی که زیبایی ساقی (که عکسش در جام افتاد یا آتشی که در می بود) آتش در خرمنم زد.',NULL);
INSERT INTO "verses" VALUES(1935944,2216,5,1,'کآتش زِ عکسِ عارضِ ساقی در آن گرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935945,2216,4,0,'آسوده بر کنار چُو پرگار می‌شدم','چون پرگار (دور از بلای عشق یا دور از حوادث) بر کناره می‌رفتم‌، اما دست روزگار مرا همچون نقطه (پرگار) به میانه کشید.',NULL);
INSERT INTO "verses" VALUES(1935946,2216,4,1,'دوران، چو نقطه، عاقبتم در میان گرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935947,2216,3,0,'می‌خواست گُل که دَم زند از رنگ و بویِ دوست','گل نیز خواست که با حال و زیبایی خود وصفی از یار من گوید، صبا از غیرت‌، او را خموش کرد.',NULL);
INSERT INTO "verses" VALUES(1935948,2216,3,1,'از غیرتِ صبا، نفسَش در دهان گرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935949,2216,2,0,'زین آتشِ نهفته که در سینهٔ من است','خورشید عالم‌تاب‌، شراره‌ای از آتش پنهانی است که از سینه من در آسمان زد.',NULL);
INSERT INTO "verses" VALUES(1935950,2216,2,1,'خورشید، شعله‌ای‌ست که در آسمان گرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935951,2216,1,0,'افشایِ رازِ خلوتیان خواست کرد شمع','شمع قصد کرد که راز خلوت‌نشینان را فاش کند‌، خدای را سپاس که راز دل‌، زبانش را آتش زد.',NULL);
INSERT INTO "verses" VALUES(1935952,2216,1,1,'شُکرِ خدا، که سِرِ دلش در زبان گرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935953,2216,0,0,'حُسنت به اتفاقِ ملاحت جهان گرفت','نمک و ملاحت تو همراه با زیبایی و تناسبت عالم گیر شده،این قضیه روشن کرد که می‌توان با اتحاد جهان را گرفت.',NULL);
INSERT INTO "verses" VALUES(1935954,2216,0,1,'آری، به اتفاق، جهان می‌توان گرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935955,2215,7,0,'حافظ تو این سخن ز که آموختی؟ که بخت','هوش مصنوعی: حافظ، از چه کسی این هنر را یاد گرفته‌ای؟ که شانس تو، شعر تو را مثل تعویذی ساخته و آن را با طلا ارزشمند کرده است.',NULL);
INSERT INTO "verses" VALUES(1935956,2215,7,1,'تعویذ کرد شعرِ تو را و به زر گرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935957,2215,6,0,'زین قصه هفت گنبدِ افلاک پرصداست','این ماجرا در همه‌جا پیچیده، آدم دون‌نظر را ببین که این‌را دست‌کم گرفته‌است.',NULL);
INSERT INTO "verses" VALUES(1935958,2215,6,1,'کوته‌نظر ببین که سخن مختصر گرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935959,2215,5,0,'هر سروقد که بر مَه و خور حسن می‌فروخت','هر خوش اندام و ماهرویی که در زیبایی از ماه و خورشید خودش را برتر می‌دانست، وقتی که تو آمدی، مشغول کاری دیگر شد و نتوانست فخرفروشی را ادامه دهد.',NULL);
INSERT INTO "verses" VALUES(1935960,2215,5,1,'چون تو درآمدی پیِ کاری دگر گرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935961,2215,4,1,'عیسی‌دمی خدا بفرستاد و برگرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935962,2215,3,1,'گویی که پستهٔ تو سخن در شکر گرفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935963,2213,6,1,'قلبِ سیاه بود از آن در حرام رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935964,2213,7,0,'در تابِ توبه چند توان سوخت همچو عود؟','هوش مصنوعی: در لحظات ناامیدی، چه مدتی می‌توان با توبه و پشیمانی مانند بخاری از جان خود سوزانید؟ به من بده که عمرم در آرزوی پوچ و بیهوده گذشته است.',NULL);
INSERT INTO "verses" VALUES(1935965,2213,7,1,'می ده که عمر در سرِ سودای خام رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935966,2210,0,0,'صبحدم مرغ چمن با گل نوخاسته گفت','صبح‌گاه بلبل با گل تازه‌شکفته گفت که با من کم ناز کن زیرا در این باغ‌، گل‌‌‌های همچون تو بسیارند.',NULL);
INSERT INTO "verses" VALUES(1935967,2210,0,1,'ناز کم کن که در این باغ بسی چون تو شکفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935968,2210,1,0,'گل بخندید که از راست نرنجیم ولی','گل خندید و به او پاسخ داد: از سخن راست نمی‌رنجیم ولی کسی که عاشق است اینگونه با معشوق و محبوب‌، سخن نمی‌گوید.',NULL);
INSERT INTO "verses" VALUES(1935969,2210,1,1,'هیچ عاشق سخن سخت به معشوق نگفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935970,2210,2,0,'گر طمع داری از آن جام مرصع میِ لعل','اگر امید داری که از آن‌جام یگانه و مرصّع‌، باده بنوشی‌، بسیار مروارید‌های اشک باید از نوک مژگان بریزی.',NULL);
INSERT INTO "verses" VALUES(1935971,2210,2,1,'ای بسا دُر که به نوک مژه‌ات باید سفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935972,2210,3,0,'تا ابد بوی محبت به مشامش نرسد','تا ابد و هرگز بوی عشق را نشنود و نخواهد دانست که عشق و محبت چیست، آن‌کس که چهره و رخسار بر خاک در میخانه ننهد.',NULL);
INSERT INTO "verses" VALUES(1935973,2210,3,1,'هر که خاک در میخانه به رخسار نرُفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935974,2210,4,0,'در گلستان ارم دوش چو از لطف هوا','دیشب در گلستان بهشت وقتی که نسیم ملایم‌ سحری، زلف سنبل را آشفته می‌کرد.',NULL);
INSERT INTO "verses" VALUES(1935975,2210,4,1,'زلف سنبل به نسیم سحری می‌آشفت،',NULL,NULL);
INSERT INTO "verses" VALUES(1935976,2210,5,0,'گفتم: «ای مسند جم! جام جهان‌بینت کو؟»','از او پرسیدم که ای تکیه‌گاه جمشید، جام جهان‌بین تو کجاست (که مرا نصیب دهی) گفت افسوس که آن دولت نیک و سعادت خفت.',NULL);
INSERT INTO "verses" VALUES(1935977,2210,5,1,'گفت: «افسوس که آن دولت بیدار بخفت!»',NULL,NULL);
INSERT INTO "verses" VALUES(1935978,2210,6,0,'سخن عشق نه آن است که آید به زبان','هرچه که بیان شود سخن عشق نیست، ای ساقی باده بده و این گفتگو را کوتاه کن.',NULL);
INSERT INTO "verses" VALUES(1935979,2210,6,1,'ساقیا می ده و کوتاه کُن این گفت و شنفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935980,2210,7,0,'اشک حافظ، خرد و صبر، به دریا انداخت','اشک و گریه حافظ‌، عقل و صبر را به دریا انداخت، چه می‌توانست کرد زیرا سوز و درد عشق را نمی‌توانست نهان کند.',NULL);
INSERT INTO "verses" VALUES(1935981,2210,7,1,'چه کند؟ سوز غم عشق نیارست نهفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935982,2209,6,0,'حافظا! روز اجل گر به کف آری جامی','حافظ، اگر در روز مرگت بتوانی حرکتی بکنی و پویا و فعال باشی ،مستقیم به بهشت خواهی رفت.',NULL);
INSERT INTO "verses" VALUES(1935983,2209,6,1,'یک‌سر از کویِ خرابات بَرَنْدَت به بهشت',NULL,NULL);
INSERT INTO "verses" VALUES(1935984,2209,5,0,'نه من از پردهٔ تقوا به درافتادم و بس','من نه تنها خودم از پردهٔ تقوا و پرهیزکاری خارج شدم، بلکه پدرم نیز بهشت جاویدش را از دست داده است.',NULL);
INSERT INTO "verses" VALUES(1935985,2209,5,1,'پِدرم نیز بهِشتِ ابد از دست، بِهِشت',NULL,NULL);
INSERT INTO "verses" VALUES(1935986,2209,4,0,'ناامیدم مکن از سابقهٔ لطفِ اَزَل','مرا از رحمت و لطف بی‌نهایت ناامید نکن؛ تو که در پس پردهٔ واقعیت‌ها جهان، نمی‌دانی چه چیز خوب است و چه چیز بد.',NULL);
INSERT INTO "verses" VALUES(1935987,2209,4,1,'تو پسِ پرده چه دانی که که خوب است و که زشت؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935988,2209,3,0,'سر تسلیمِ من و خشتِ درِ مِیکده‌ها','من سر تسلیم بر دیوار میخانه‌ها فرود آورده‌ام ، اگر مدعی نتواند مفهوم کلام را درک کند، می‌تواند سرش را به سنگ بزند.',NULL);
INSERT INTO "verses" VALUES(1935989,2209,3,1,'مُدَّعی گر نکند فهمِ سخن، گو سر و خشت',NULL,NULL);
INSERT INTO "verses" VALUES(1935990,2209,2,0,'همه‌کس، طالبِ یارند؛ چه هُشیار و چه مست','همه افراد، چه هشیار و چه مست، خواهان معشوق هستند. در هر مکان، عشق حضور دارد؛ چه در مسجد و چه در کنیسه و میخانه.',NULL);
INSERT INTO "verses" VALUES(1935991,2209,2,1,'همه‌جا، خانهٔ عشق است؛ چه مسجد چه کِنِشت',NULL,NULL);
INSERT INTO "verses" VALUES(1935992,2209,1,0,'من اگر نیکم و گر بَد، تو برو خود را باش!','اگر من خوب باشم یا بد، تو به خودت برس و خودت را بساز. هر کسی در نهایت نتیجه کارهایش را درو می‌کند، چه خوب و چه بد.',NULL);
INSERT INTO "verses" VALUES(1935993,2209,1,1,'هر کسی آن دِرَوَد عاقبتِ کار، که کِشت',NULL,NULL);
INSERT INTO "verses" VALUES(1935994,2209,0,0,'عِیبِ رِندان مَکُن ای زاهدِ پاکیزه‌سِرِشت!','ای زاهد پاکدامن، به عیب‌ها و ناپاکی‌های زیرکان نپرداز و آنها را نکوب، زیرا گناهان دیگران به تو ارتباطی ندارد و در روز قیامت به پای تو نمی‌نویسند.',NULL);
INSERT INTO "verses" VALUES(1935995,2211,0,0,'آن تُرکِ پَری چِهره که دوش اَز بَرِ ما رَفت','آن تُرک خوش سیما که دیشب از پیش ما رفت آیا از ما خطا و اشتباهی دید که مارا ترک کرد و به مقصد دوری(ختای ولایتی از ترکان) رفت.',NULL);
INSERT INTO "verses" VALUES(1935996,2211,0,1,'آیا چه خطا دید که اَز راهِ خطا رَفت؟',NULL,NULL);
INSERT INTO "verses" VALUES(1935997,2211,1,0,'تا رَفت مَرا اَز نَظَر آن چَشمِ جَهان‌بین','از زمانی که از نظرگاه من آن نورچشمی عزیز رفت آن کسی که مثل چشمان من بود و به واسطه ی آن بصیرت و بینایی پیدا می‌کردم،هیچکس نمی داند که چه حال و روزی دارم و چه چیز ارزشمندی از چشمان من رفته است.',NULL);
INSERT INTO "verses" VALUES(1935998,2211,1,1,'کَس واقفِ ما نیست که اَز دیده چه‌ها رَفت',NULL,NULL);
INSERT INTO "verses" VALUES(1935999,2213,8,0,'دیگر مکن نصیحتِ حافظ که ره نیافت','هوش مصنوعی: دیگر به من نصیحت نکن، چون گم‌شده‌ای که راه خود را پیدا نکرد. نشانه‌اش این است که لذت از شراب خوب را چشیده است.',NULL);
INSERT INTO "verses" VALUES(1936000,2213,8,1,'گمگشته‌ای که بادهٔ نابش به کام رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936001,2212,0,0,'گر ز دستِ زلفِ مُشکینت خطایی رفت رفت','از جانبِ زلف سیاه و معطّر تو اگر خطا و اشتباهی سر زد و از چشمان و خال و خطِ سیاه تو، ستمی به ما رسید،اشکالی ندارد زیاد مهم نمی باشد و می‌گذرم.',NULL);
INSERT INTO "verses" VALUES(1936002,2212,0,1,'ور ز هندویِ شما بر ما جفایی رفت رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936003,2212,1,0,'برقِ عشق ار خرمنِ پشمینه پوشی سوخت سوخت','اگر خرقه ی درویشیِ من به آتش برق عشق سوخت و خاکستر شد اشکالی ندارد هرچه دارم فدای عشق باد. و اگر از طرف پادشاهی کامروا جفایی برگدایی همچون من رفت هیچ اهمیّتی ندارد.',NULL);
INSERT INTO "verses" VALUES(1936004,2212,1,1,'جورِ شاه کامران گر بر گدایی رفت رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936005,2212,2,0,'در طریقت رنجشِ خاطر نباشد می بیار','در مسلکِ ما که در حال سیر و سلوک هستیم رنجیدن معنایی ندارد ما از هیچکس کینه به دل نمی گیریم و نمی رنجیم باده بیاور خوش باشیم اگر کدورتی هم باشد همانگونه که خوشی و خرّمی در گذرند این نیزمی گذرد وبه فراموشی سپرده می شود.',NULL);
INSERT INTO "verses" VALUES(1936006,2212,2,1,'هر کدورت را که بینی چون صفایی رفت رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936007,2212,3,0,'عشقبازی را تحمل باید ای دل، پای دار','ای دل در عشقبازی باید صبور و شکیبا باشی، بی تابی مکن اگر هم در عشقبازی رفتاری ملالت انگیز رخ نمود و یا خطایی از جانبِ معشوق صورت گرفت اشکالی ندارد تحمّل کن و مقاوم باش.',NULL);
INSERT INTO "verses" VALUES(1936008,2212,3,1,'گر ملالی بود بود و گر خطایی رفت رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936009,2212,4,0,'گر دلی از غمزهٔ دلدار باری برد برد','اگر از حرکاتِ دلبرانه ی معشوق، دلِ عاشق زیر بار اندوه و حسرت به تنگ آمد مهم نیست و اگر میان عاشق و معشوق هر اتّفاقی رُخ داد خیر است و ملالی نیست.',NULL);
INSERT INTO "verses" VALUES(1936010,2212,4,1,'ور میان جان و جانان ماجرایی رفت رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936011,2212,5,0,'از سخن چینان ملالت‌ها پدید آمد ولی','درست است که از دشمنی سخن چینان این وضعیّتِ ملالت بار رقم خورده است لیکن من از حق خود می‌گذرم چرا که در میان همنشینان رخداد های این چنین غیر معمول نیست و من هیچ شکایتی از آنها ندارم .',NULL);
INSERT INTO "verses" VALUES(1936012,2212,5,1,'گر میانِ همنشینان ناسزایی رفت رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936013,2217,1,0,'حدیثِ هولِ قیامت که گفت واعظِ شهر','واعظ شهر که داستان ترسناک روز قیامت را بیان کرد؛ در اصل اشاره­ ای است کوتاه و سربسته از روزگار دوری از معشوق',NULL);
INSERT INTO "verses" VALUES(1936014,2212,6,0,'عیبِ حافظ گو مکن واعظ که رفت از خانقاه','ای واعظ سخن چین که پشت سر حافظ بدگویی می‌کنی و از خانقاه رفتن او را دستآویز قرار داده و با بوق و کرنا در مجالس عمومی اعلام می کنی، آری من از خانقاه که مکان ریا و تزویر است رویگردان شدم و خود را خلاص کردم تو نمی توانی پای آزاد اندیش و آزاد مردی چون مرا به بندی ، کسی که از تمام قید و بند تعلّقات رها گشته ، هرجا که بخواهد می رود.',NULL);
INSERT INTO "verses" VALUES(1936015,2211,2,0,'بَر شَمع نرفت اَز گُذرِ آتشِ دل، دوش','از داغ رفتنِ محبوب، آن دودی که از سوز و گداز جگر، بالای سر ما بلند شد بر سر شمع که دلش آتش گرفته و می‌سوزد نرفت. (یعنی داغ رفتن تو از شعله ی آتش نیز سوزنده تر است.)',NULL);
INSERT INTO "verses" VALUES(1936016,2211,2,1,'آن دود که اَز سوزِ جِگر بَر سَر ما رَفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936017,2211,3,0,'دور اَز رُخِ تو دَم به دَم از گوشهٔ چَشمَم','آن یار سفر کرده الهی که بلا و بدی از رخسار او دور باد، در فراق رویش، از گوشه ی چشمانِ اشکبارم سیلاب جاری شد و بلاهای زیادی بسان طوفان به سرم آمد.',NULL);
INSERT INTO "verses" VALUES(1936018,2211,3,1,'سیلابِ سِرشک آمَد و طوفانِ بَلا رَفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936019,2211,4,0,'از پای فُتادیم چو آمَد غَمِ هجران','غم هجران و نبودِ تو ما را از پای انداخت در درد فروماندیم و مرگ را به چشم خود دیدیم زمانی که نوش‌داروی جان از دست رفت.',NULL);
INSERT INTO "verses" VALUES(1936020,2211,4,1,'دَر دَرد بِمُردیم چو اَز دَست دَوا رَفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936021,2211,5,0,'دل گفت وِصالَش به دُعا باز تَوان یافت','دل مشتاقانه امیدوار بود که از طریق توسّل به دعا می توان دوباره به وصل معشوق نایل شد، تمام عمرم در دعا و طلب سپری شد ولیکن توفیقی حاصل نگشت.',NULL);
INSERT INTO "verses" VALUES(1936022,2211,5,1,'عُمریست که عُمرَم همه دَر کارِ دُعا رَفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936023,2211,6,0,'اِحرام چه بَندیم؟ چو آن قبله نه این جاست','حال که قبله و کعبه ی ما(معشوق) از اینجا عزم سفر کرده و رفته است احرام بستن ما چه سودی دارد ؟ عمل سعی نیز بیهوده می‌باشد چرا وقتی که قبله(معشوق) رفته و حضور ندارد کوشش کنیم ؟ بنابراین در مروه به سبب نبود معشوق هیچ صفا (خوشی و خرمی) نمانده و سعی ما هیچ نتیجه ای ندارد. (صفا و مروه: دو نقطه که حجّاج می بایست هفت مرتبه این فاصله را بصورت رفت وبرگشت طی کنند تامراسم حج کامل گردد این عمل را سعی می‌نامند.)',NULL);
INSERT INTO "verses" VALUES(1936024,2211,6,1,'دَر سَعی چه کوشیم؟ چو از مَروه صَفا رَفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936025,2211,7,0,'دی گفت طبیب اَز سَرِ حَسرت چو مَرا دید','دیشب که طبیب وضعیّتِ نامساعد مرا دید از سرحسرت گفت: افسوس که امکان مداوای تو میسّر نیست دور از ذهن است که تو شفا پیدا کنی.(قانون و شفا از کتاب‌های حکیم و پزشک معروف ابن‌سینا هستند کتاب قانون به فلسفه و شفا به علوم طبابت پرداخته‌)',NULL);
INSERT INTO "verses" VALUES(1936026,2211,7,1,'هِیهات که رَنجِ تو زِ قانونِ شَفا رَفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936027,2211,8,0,'ای دوست به پُرسیدنِ حافظ قَدَمی نِه','ای دوست از حافظ که بیمار عشق است عیادت کن و از احوالات او پرسشی کن پیش از آنکه از دیگران بشنوی حافظ از این دنیا رفت.',NULL);
INSERT INTO "verses" VALUES(1936028,2211,8,1,'زان پیش که گویند که اَز دارِ فَنا رَفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936029,2212,6,1,'پای آزادی چه بندی؟ گر به جایی رفت رفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936030,2217,1,1,'کنایتی‌ست که از روزگارِ هجران گفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936031,2217,2,0,'نشانِ یارِ سفرکرده از کِه پُرسم باز؟','پیک صبا که از حرم معشوق خبر دارد و از جانب حرم او می ­آید، هرمطلبی در مورد معشوق گفت پریشان و نامعلوم بود، نشان و خبر از یار سفر کرده را باید از چه کسی بپرسم؟',NULL);
INSERT INTO "verses" VALUES(1936032,2217,2,1,'که هر چه گفت بَریدِ صبا، پریشان گفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936033,2222,4,0,'بیا که با سرِ زلفت قرار خواهم کرد','هوش مصنوعی: بیا تا با زیبایی موهایت عهد و پیمان ببندم، چرا که حتی اگر جانم را بگیرند، از عشق تو دست نخواهم کشید.',NULL);
INSERT INTO "verses" VALUES(1936034,2222,4,1,'که گر سَرَم برود برندارم از قدمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936035,2222,3,0,'مرا ذلیل مگردان به شکرِ این نعمت','هوش مصنوعی: مرا خوار و کوچک نکن به خاطر این نعمت که موقعیت و مقام باارزشی داشتی و عزیز و محترم هستی.',NULL);
INSERT INTO "verses" VALUES(1936036,2222,3,1,'که داشت دولتِ سرمد عزیز و محترمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936037,2222,2,0,'نگویم از منِ بی‌دل به سهو کردی یاد','هوش مصنوعی: من نمی‌گویم که تو به‌طور ناخواسته از منِ بی‌دل یاد کردی، زیرا در محاسبات کوچک، اشتباه بر در نوشتار تو نمی‌خورد.',NULL);
INSERT INTO "verses" VALUES(1936038,2222,2,1,'که در حسابِ خرد نیست سهو بر قَلَمَت',NULL,NULL);
INSERT INTO "verses" VALUES(1936039,2222,1,0,'به نوکِ خامه رقم کرده‌ای سلامِ مرا','هوش مصنوعی: تو با نوک قلم، سلام مرا نوشته‌ای، گویی که در این زمانه، بدون وجود تو هیچ چیز ارزشمند نیست.',NULL);
INSERT INTO "verses" VALUES(1936040,2222,1,1,'که کارخانهٔ دوران مباد بی رَقَمَت',NULL,NULL);
INSERT INTO "verses" VALUES(1936041,2222,0,0,'چه لطف بود که ناگاه رَشحِهٔ قَلَمَت','هوش مصنوعی: چه خوب است که ناگهان نوشته‌ای از تو به ما نشان داد که خدمات ما را در مقابل بزرگواری تو یادآور شده است.',NULL);
INSERT INTO "verses" VALUES(1936042,2222,0,1,'حقوقِ خدمتِ ما عرضه کرد بر کرمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936043,2221,6,0,'گرچه جایِ حافظ اندر خلوتِ وصلِ تو نیست','اگرچه حافظ لیاقت و شایستگی و بودن در خلوت و وصال تو را ندارد، ای کسی که تمام وجودت نیکو و دوست داشتنی است، پیش هر جا که متعلق به تو است جان میدهم.',NULL);
INSERT INTO "verses" VALUES(1936044,2221,6,1,'ای همه جایِ تو خوَش، پیشِ همه جا میرمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936045,2221,5,0,'خوش خِرامان می‌روی چشمِ بد از رویِ تو دور','ای جان من، چقدر زیبا و با ناز راه میروی، چشم بد از تو دور باد. در سر خیال و آرزوی آن را دارم که از عشق جانم را پیش پایت فدا کنم',NULL);
INSERT INTO "verses" VALUES(1936046,2221,5,1,'دارم اندر سر خیالِ آن که در پا میرمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936047,2221,4,0,'گفته‌ای لعلِ لبم هم درد بخشد هم دوا','ای معشوق زیبای روی من، گفته ای که لبان سرخ و شیرین من هم درد ‌و زجر میدهد و هم درمان میکند. گاهی پیش دردی که لبانت میدهد و گاهی پیش درمان آن ( بوسه و وصال ) جان میدهم ( عاشق هم شیفته وصال و هم شیفته فراق یار است )',NULL);
INSERT INTO "verses" VALUES(1936048,2221,4,1,'گاه پیش درد و گَه پیش مداوا میرمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936049,2221,3,0,'آن که عمری شد که تا بیمارم از سودایِ او','آن کسی که عمری است از سودای عشق او بیمارم، به او بگویید که نگاهی به من بیندازد تا من پیش چشمان زیبای او جان فدا کنم',NULL);
INSERT INTO "verses" VALUES(1936050,2221,3,1,'گو نگاهی کن که پیشِ چشمِ شهلا میرمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936051,2221,2,0,'عاشق و مخمور و مهجورم بتِ ساقی کجاست؟','عاشق و مست ( از عشق ) و دور افتاده ( از وصال معشوق ) آن معشوق زیبا روی ما کجاست؟ به او بگویید با ناز و خرام بیایید که من پیش قد و بالای سرو مانندش جان نثار کنم',NULL);
INSERT INTO "verses" VALUES(1936052,2221,2,1,'گو که بِخرامَد که پیشِ سرو بالا میرمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936053,2221,1,0,'گفته بودی کی بمیری پیشِ من، تعجیل چیست؟','ای جانان من، پرسیده بودی که چه زمانی جانت را فدای من میکنی؟ عجله برای چیست؟ چه تقاضای خوب و شیرینی داری. جانم فدای تقاضای تو شود ( یا قبل از اینکه تقاضا کنی جانم را فدایت میکنم )',NULL);
INSERT INTO "verses" VALUES(1936054,2221,1,1,'خوش تقاضا می‌کنی پیشِ تقاضا میرمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936055,2221,0,0,'میرِ من خوش می‌روی کاندر سر و پا میرمت','ای فرمانروای من ( در اینجا حضرت حافظ معشوق را فرمانروای قلب خود خطاب میکند) چقدر زیبا و با ناز راه میروی که من از فرط عشق جانم را فدای سر و پای تو میکنم. باز هم با همان ناز و زیبایی قدم بردار که جانم را پیش قد و قامت رعنای تو فدا کنم',NULL);
INSERT INTO "verses" VALUES(1936056,2221,0,1,'خوش خرامان شو که پیشِ قدِ رعنا میرمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936057,2220,0,0,'ای غایب از نظر به خدا می‌سپارمت','با تو نیستم و تو نزد من نیستی اما تو را به‌خدا می‌سپارم؛ (با رفتنت) دل مرا سوختی؛ با جان و دل تو را دوست دارم.',NULL);
INSERT INTO "verses" VALUES(1936058,2220,0,1,'جانم بسوختی و به دل دوست دارمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936059,2220,1,0,'تا دامنِ کفن نکشم زیرِ پایِ خاک','تا روزی که به زیر خاک نروم و تا وقتی که جان دارم، باور مکن که تو را فراموش کنم و دست از دامن تو بردارم.',NULL);
INSERT INTO "verses" VALUES(1936060,2220,1,1,'باور مکن که دست ز دامن بدارمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936061,2220,2,0,'محرابِ ابرویت بنما تا سحرگهی','روزی سپیده‌دم به دیدار من بیا تا در محراب ابرویت خواسته‌ها و دعاهای خود را به‌تو بگویم و تو را در آغوش بگیرم.',NULL);
INSERT INTO "verses" VALUES(1936062,2222,5,0,'ز حالِ ما دلت آگه شود مگر وقتی','هوش مصنوعی: آیا دل تو از حال ما باخبر می‌شود؟ تنها زمانی که لاله‌ها از خاک کسانی که به خاطر غمت مرده‌اند، رویش کنند.',NULL);
INSERT INTO "verses" VALUES(1936063,2222,5,1,'که لاله بردمد از خاکِ کشتگانِ غمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936064,2222,6,0,'روانِ تشنهٔ ما را به جرعه‌ای دریاب','هوش مصنوعی: دل تشنهٔ ما را با یک جرعه سیراب کن؛ مانند اینکه وقتی از جام جمشید، زلال و شفاف به ما می‌نوشانند.',NULL);
INSERT INTO "verses" VALUES(1936065,2222,6,1,'چو می‌دهند زُلالِ خِضِر ز جامِ جَمَت',NULL,NULL);
INSERT INTO "verses" VALUES(1936066,2224,2,0,'سوادِ لوح بینش را عزیز از بهر آن دارم','سیاهی نوشته‌های کتاب‌های بینش و دانایی را از بهر آن دوست دارم که شبیه خال تو مشکی است.',NULL);
INSERT INTO "verses" VALUES(1936067,2224,2,1,'که جان را نسخه‌ای باشد ز لوحِ خالِ هندویت',NULL,NULL);
INSERT INTO "verses" VALUES(1936068,2224,1,0,'پس از چندین شکیبایی، شبی، یا رب! توان دیدن','آیا می‌شود که پس از مدت‌ها صبر، دیدگانم به دیدن ابروی زیبای تو روشن شود همچون شمعی که در محراب بیفروزند.',NULL);
INSERT INTO "verses" VALUES(1936069,2224,1,1,'که شمعِ دیده افروزیم در محرابِ ابرویت؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936070,2224,0,0,'مدامم مست می‌دارد، نسیمِ جَعدِ گیسویت','هر لحظه عطر خوشی از گیسوی تو به‌من می‌رسد و از آن مست و خوش می‌شوم؛ هر لحظه چشم زیبای تو مرا مست‌تر می‌کند!',NULL);
INSERT INTO "verses" VALUES(1936071,2224,0,1,'خرابم می‌کند هر دَم، فریبِ چشمِ جادویت',NULL,NULL);
INSERT INTO "verses" VALUES(1936072,2223,10,0,'عشقت رِسَد به فریاد، ار خود به سانِ حافظ','اگر بتوانی مانند حافظ قرآن را در چارده روایت از حفظ بخوانی، و با قران مانوس باشی آنگاه عشق به فریادت خواهد رسید یعنی لازمه بهره مندی از عشق واقعی انس با قران هست.(چارده روایت: بنا بر نظر دکتر قاسم غنی برای قراءت قرآن هفت قاری (قراء سبعه) بودند که قراءت هر یک به واسطه دو راوی به ما رسیده است.)',NULL);
INSERT INTO "verses" VALUES(1936073,2223,10,1,'قرآن ز بَر بخوانی، در چاردَه روایت',NULL,NULL);
INSERT INTO "verses" VALUES(1936074,2223,9,0,'هر چند بردی آبم روی از درت نتابم','هر چند آبروی مرا بردی، اما هرگز، از در خانه­‌ی تو باز نخواهم گشت؛ چرا که تحمل جور و ستم از معشوق بسیار بهتر از رعایت و جانب‌داری مدعیان لاف‌­زن و دروغگوست.',NULL);
INSERT INTO "verses" VALUES(1936075,2223,9,1,'جور از حبیب خوش‌تر، کز مُدَّعی رعایت',NULL,NULL);
INSERT INTO "verses" VALUES(1936076,2223,8,0,'این راه را نهایت، صورت کجا توان بست؟','راهی که بیش از صدها هزار منزل در ابتدای آن قرار دارد، چگونه می­‌توان برای آن پایانی تصور کرد.',NULL);
INSERT INTO "verses" VALUES(1936077,2223,8,1,'کِش صد هزار منزل، بیش است در بِدایت',NULL,NULL);
INSERT INTO "verses" VALUES(1936078,2223,7,0,'ای آفتابِ خوبان، می‌جوشد اندرونم','ای خورشید زیبارویان! سراپای وجودم در سوز و گداز عشق تو می­‌جوشد، برای لحظه‌­ای مرا در پناه عنایتت که همچون سایه است قرار بده.',NULL);
INSERT INTO "verses" VALUES(1936079,2223,7,1,'یک ساعتم بِگُنجان، در سایهٔ عنایت',NULL,NULL);
INSERT INTO "verses" VALUES(1936080,2220,2,1,'دستِ دعا برآرم و در گردن آرمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936081,2223,6,0,'از هر طرف که رفتم، جز وحشتم نَیَفزود','از هر طرفی که رفتم چیزی جز تنهایی و بی­کسی، حاصلم نشد! از این بیابان و از این راهی که هیچ پایانی ندارد، بر حذر باشید.',NULL);
INSERT INTO "verses" VALUES(1936082,2223,5,0,'در این شبِ سیاهم، گم گشت راهِ مقصود','در این شب سیاه و ظلمانی، راه رسیدن به مقصود را گم کرده‌­ام، ای ستاره هدایتگر از گوشه‌­ای بیرون بیا(کوکب هدایت: تلمیح به آیه ۱۶ سوره نحل: وَعَلَامَاتٍ وَبِالنَّجْمِ هُمْ یَهْتَدُونَ.)',NULL);
INSERT INTO "verses" VALUES(1936083,2223,5,1,'از گوشه‌ای برون آی، ای کوکبِ هدایت',NULL,NULL);
INSERT INTO "verses" VALUES(1936084,2223,4,0,'چشمت به غمزه ما را، خون خورد و می‌پسندی','چشمان تو با غمزه­‌های مستانه­‌اش خون ما را ریخت، تو نیز آن را پسندیدی، دلبندم، مگر نمی­دانی که از خونریز و قاتل حمایت کردن، امری شایسته نیست!(نکته: نکته قابل توجه در این بیت کارکرد غمزه است که هرچند به طور معمول جهت دلبری استفاده می­شود اما حافظ بیان می‌­کند که غمزه­‌ی یار جهت خون ریختن و کشتن اوست؛ از این رو از معشوق می­‌خواهد که از چشمانش که در واقع خونریز و قتال وضع می­‌باشند، حمایت نکند!همچنین می­توان منظور از حمایت کردن معشوق از چشمانش را اشاره به مژگان معشوق دانست، گویی مژگان معشوق نیزه دارانی صف بسته هستند که از چشمانش مراقبت می­‌کنند.)',NULL);
INSERT INTO "verses" VALUES(1936085,2223,4,1,'جانا روا نباشد، خون‌ریز را حمایت',NULL,NULL);
INSERT INTO "verses" VALUES(1936086,2223,3,0,'در زلفِ چون کمندش، ای دل مپیچ کآن جا','ای دل، خود را در گیسوی همچون کمند دلدار، گرفتار نکن! چرا که سرهای بسیاری را در آنجا خواهی یافت که بدون هیچ جرم و جنایتی بریده، رها شده است.(نکته: شایان ذکر است که منزل و مأوای دل در ادبیات فارسی، زلف معشوق است.)',NULL);
INSERT INTO "verses" VALUES(1936087,2223,3,1,'سرها بریده بینی، بی‌جرم و بی‌جنایت',NULL,NULL);
INSERT INTO "verses" VALUES(1936088,2223,2,0,'رندانِ تشنه‌لب را، آبی نمی‌دهد کس','هیچ کس به رندان تشنه لب دیگر جرعه­‌ی آبی نمی­‌بخشد، گویا کسانی که قدر و ارزش اولیاء الله را می­‌دانستند از این سرزمین رفته­‌اند.(نکته: حافظ بسیار رندانه، رند را همان اولیاء الله می­‌داند.)',NULL);
INSERT INTO "verses" VALUES(1936089,2223,2,1,'گویی ولی‌شناسان، رفتند از این ولایت',NULL,NULL);
INSERT INTO "verses" VALUES(1936090,2223,1,0,'بی‌مزد بود و مِنَّت، هر خدمتی که کردم','هر خدمتی که انجام دادم، بدون پاداش و احسان ماند، خداوندا، هیچ کس سرور و مولایی نداشته باشد که به او توجه نکند.',NULL);
INSERT INTO "verses" VALUES(1936091,2223,1,1,'یا رب مباد کس را، مخدومِ بی‌عنایت',NULL,NULL);
INSERT INTO "verses" VALUES(1936092,2223,0,0,'زان یارِ دل‌نوازم، شُکری است با شکایت','از آن یار مهربان و دلنشینم شکری همراه با گله و شکایت دارم؛ اگر به دنبال فهم مفاهیم باریک عشق هستی، این داستان مرا بشنو.',NULL);
INSERT INTO "verses" VALUES(1936093,2223,0,1,'گر نکته‌دانِ عشقی، بشنو تو این حکایت',NULL,NULL);
INSERT INTO "verses" VALUES(1936094,2222,7,0,'همیشه وقتِ تو ای عیسیِ صبا خوش باد','هوش مصنوعی: همیشه برای تو، ای عیسی بهار، لحظات خوشی باشد، چرا که نفس تو باعث زنده شدن جان خسته حافظ شد.',NULL);
INSERT INTO "verses" VALUES(1936095,2222,7,1,'که جانِ حافظِ دلخسته زنده شد به دَمَت',NULL,NULL);
INSERT INTO "verses" VALUES(1936096,2223,6,1,'زِنهار از این بیابان، وین راهِ بی‌نهایت',NULL,NULL);
INSERT INTO "verses" VALUES(1936097,2209,0,1,'که گناهِ دِگَران بَر تو نخواهند نوشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936098,2220,3,0,'گر بایدم شدن سویِ هاروتِ بابلی','اگر حتی مجبور شوم سوی هاروت بابل می‌روم تا با سحر و جادو تو را بیاورم.',NULL);
INSERT INTO "verses" VALUES(1936099,2220,3,1,'صد گونه جادویی بکنم تا بیارمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936100,2218,7,0,'حاشا که من از جور و جفای تو بنالم','از من دور بادا که روزی از جور و ستم تو گلایه و شکایت کنم زیرا ستم و جور زیبایان همه خود مهربانی و بخشش است.',NULL);
INSERT INTO "verses" VALUES(1936101,2218,6,0,'در خرقه زن آتش که خمِ ابرویِ ساقی','خرقه زهد را دور بیفکن زیرا ابروی یار بسیار از محراب نماز، زیبا‌تر و پرستیدنی‌تر است.',NULL);
INSERT INTO "verses" VALUES(1936102,2218,6,1,'بر می‌شکند گوشهٔ محراب امامت',NULL,NULL);
INSERT INTO "verses" VALUES(1936103,2218,5,0,'درویش مکن ناله ز شمشیرِ اَحِبّا','ای درویش از شمشیر و جور دلبران ناله و شکایت مکن زیرا این قوم، از کُشته، خون‌بها می‌ستانند!',NULL);
INSERT INTO "verses" VALUES(1936104,2218,5,1,'کاین طایفه از کشته ستانند غرامت',NULL,NULL);
INSERT INTO "verses" VALUES(1936105,2218,4,0,'ای آن که به تقریر و بیان دم زنی از عشق','ای کسی که درباره عشق فقط نوشته و سخنی دیده‌ای و گفته‌ای، ما با تو نسبتی نداریم شما را به‌خیر و ما را به‌سلامت!',NULL);
INSERT INTO "verses" VALUES(1936106,2218,4,1,'ما با تو نداریم سخن، خیر و سلامت',NULL,NULL);
INSERT INTO "verses" VALUES(1936107,2218,3,0,'امروز که در دستِ توام مرحمتی کن','امروز که من در دست تو و عاشق تو هستم، بیا زیرا فردا که بمیرم اشک پشیمانی سودی ندارد.',NULL);
INSERT INTO "verses" VALUES(1936108,2218,3,1,'فردا که شَوَم خاک چه سود اشکِ ندامت',NULL,NULL);
INSERT INTO "verses" VALUES(1936109,2218,2,0,'فریاد که از شش جهتم راه بِبَستند','فریاد و فغان که از هرسو که می‌روم نمی‌توانم او را فراموش کنم و هرلحظه به‌یاد او هستم.',NULL);
INSERT INTO "verses" VALUES(1936110,2218,2,1,'آن خال و خط و زلف و رخ و عارض و قامت',NULL,NULL);
INSERT INTO "verses" VALUES(1936111,2218,1,0,'خاکِ رهِ آن یارِ سفرکرده بیارید','خبری از یار سفر کرده بیاورید تا آنرا توتیای چشمانم کنم (یا از چه‌کسی بپرسم که یار سفرکرده‌ام کجاست!؟ تا چشمانم را خاک قدمش کنم)',NULL);
INSERT INTO "verses" VALUES(1936112,2218,1,1,'تا چشمِ جهان بین کُنَمَش جایِ اقامت',NULL,NULL);
INSERT INTO "verses" VALUES(1936113,2218,0,0,'یا رب سببی ساز که یارم به سلامت','خدایا کاری کن که یارم به‌سلامت برگردد و مرا از بند و درد غم رها کند.',NULL);
INSERT INTO "verses" VALUES(1936114,2218,0,1,'بازآید و بِرهانَدَم از بندِ مَلامت',NULL,NULL);
INSERT INTO "verses" VALUES(1936115,2217,9,0,'که گفت حافظ از اندیشهٔ تو آمد باز؟','چه کسی به تو گفته است که حافظ دست از غم عشق تو کشیده است و دیگر به تو فکر نمی­ کند؟ من چنین مطلبی را نگفته­ ام، هر کس گفته است دروغ گفته است.',NULL);
INSERT INTO "verses" VALUES(1936116,2217,9,1,'من این نگفته‌ام آن کس که گفت بُهتان گفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936117,2217,8,0,'مزن ز چون و چرا دم که بندهٔ مُقبِل','در برابر خواست و تقاضای معشوق، چون و چرا نکن ؛ چرا که بنده­ ی خوشبخت هر سخنی را که معشوق بیان می­ کند، از جان و دل می ­پذیرد',NULL);
INSERT INTO "verses" VALUES(1936118,2217,8,1,'قبول کرد به جان، هر سخن که جانان گفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936119,2217,7,0,'به مهلتی که سپهرت دهد ز راه مرو','به فرصت اندکی که آسمان در اختیار تو گذاشته است، فریفته نشو؛ چه کسی به تو گفت که این روزگار دیرینه سال، حیله­ گری را رها کرده است(ایهام تناسب: زال و دستان؛ معنای دیگر زال که پدر رستم است با کلمه دستان ایهام تناسب دارد)',NULL);
INSERT INTO "verses" VALUES(1936120,2217,7,1,'تو را که گفت که این زال تَرک دَستان گفت؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936121,2217,6,0,'گره به باد مزن گر چه بر مراد رود','باد این مَثَل را به سلیمان آموخت: که هرچند روزگار مطابق میل تو باشد و باد بر طبق میل تو بوزد اما هرگز کار بیهوده نکن و به آنچه ثبات ندارد اعتماد مکن',NULL);
INSERT INTO "verses" VALUES(1936122,2217,6,1,'که این سخن به مَثَل، باد با سلیمان گفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936123,2217,5,0,'غمِ کهن به میِ سال‌خورده دفع کنید','پیر دهقان گفت: غم دیرینه را با شراب کهنه از بین ببرید؛ چرا که تنها مایه­ ی خوشدلی همین است',NULL);
INSERT INTO "verses" VALUES(1936124,2217,5,1,'که تخم خوش‌دلی این است؛ پیرِ دهقان گفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936125,2217,4,0,'من و مقامِ رضا بعد از این و شُکرِ رقیب','گویی دل من دیگر به درد عشق تو عادت کرده و درمان را رها ساخته است، من نیز بعد از این به مقام رضا روی خواهم آورد و از رقیب شکرگزار خواهم بود',NULL);
INSERT INTO "verses" VALUES(1936126,2217,4,1,'که دل به دردِ تو خو کرد و ترکِ درمان گفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936127,2217,3,0,'فغان که آن مهِ نامهربانِ مِهرگُسِل','آه و فریاد از آن زیباروی نامهربان عهد شکن، که چقدر راحت و آسوده یاران خود را ترک کرد و رفت(ایهام تناسب: “مهر” در “نامهربان” و “مهرگسل” در معنای خورشید با “ماه” تناسب دارد)',NULL);
INSERT INTO "verses" VALUES(1936128,2217,3,1,'به تَرکِ صحبتِ یاران خود چه آسان گفت',NULL,NULL);
INSERT INTO "verses" VALUES(1936129,2218,7,1,'بیدادِ لطیفان همه لطف است و کرامت',NULL,NULL);
INSERT INTO "verses" VALUES(1936130,2218,8,0,'کوته نکند بحث سرِ زلف تو حافظ','حافظ، شعر گفتن درباره زلف بلند و زیبای تو را ترک نخواهد گفت؛ شعر او همانند زلف تو تا قیامت ادامه دارد.',NULL);
INSERT INTO "verses" VALUES(1936131,2218,8,1,'پیوسته شد این سلسله تا روزِ قیامت',NULL,NULL);
INSERT INTO "verses" VALUES(1936132,2219,0,0,'ای هدهد صبا به سبا می‌فرستمت','ای هدهد پیک صبا تو را به سوی سرزمین سبا می‌فرستم به‌هوش باش که از کجا به کجا می‌روی.',NULL);
INSERT INTO "verses" VALUES(1936133,2220,4,0,'خواهم که پیش میرمت ای بی‌وفا طبیب','می‌خواهم مثل بیماری که در نزد طبیب جان می‌سپارد در پیش تو بمیرم؛ از حال بیمار خود بپرس که در انتظار دیدن تو هستم.',NULL);
INSERT INTO "verses" VALUES(1936134,2220,4,1,'بیمار باز پرس که در انتظارمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936135,2220,5,0,'صد جوی آب بسته‌ام از دیده بر کنار','از اشک خود صد جوی در کنار روان کرده‌ام تا مگر دانه محبت خود را در دل تو بکارم و بپرورم.',NULL);
INSERT INTO "verses" VALUES(1936136,2220,5,1,'بر بویِ تخمِ مِهر که در دل بکارمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936137,2220,6,0,'خونم بریخت وز غمِ عشقم خلاص داد','مرا کشت و از این درد و غم عشق مرا رها کرد؛ آفرین بر آن خنجر غمزه که مرا نجات داد.',NULL);
INSERT INTO "verses" VALUES(1936138,2220,6,1,'مِنّت پذیرِ غمزهٔ خنجر گذارمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936139,2220,7,0,'می‌گریم و مرادم از این سیلِ اشک‌بار','با گریه‌های خود و سیل اشک خود، امید دارم که تخم مهر و دوستی خود را در دل تو بکارم و سبز کنم.',NULL);
INSERT INTO "verses" VALUES(1936140,2220,7,1,'تخمِ محبّت است که در دل بکارمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936141,2220,8,0,'بارم ده از کرم سویِ خود تا به سوزِ دل','از روی بخشش و کرم مرا به سوی خود راه بده تا هردم از اشک‌های خود گوهر و جواهر تقدیم قدمت کنم.',NULL);
INSERT INTO "verses" VALUES(1936142,2220,8,1,'در پای دم‌به‌دم گهر از دیده بارمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936143,2220,9,0,'حافظ شراب و شاهد و رندی نه وضعِ توست','ای حافظ‌، شراب و شاهد و رندی و عیش کار تو نیست، (با آنکه) همه این‌ها را انجام می‌دهی تو را می‌بخشم.',NULL);
INSERT INTO "verses" VALUES(1936144,2219,9,0,'حافظ، سرودِ مجلس ما ذکرِ خیرِ توست','ای حافظ ذکر خوبی‌های تو شادی‌بخش و سرود مجلس ماست؛ به مجلس ما بیا که برایت اسب و خلعت فرستاده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1936145,2219,9,1,'بشتاب هان که اسب و قبا می‌فرستمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936146,2219,8,0,'ساقی بیا که هاتفِ غیبم به مژده گفت','ای ساقی بیا که سروش غیبی خبری شادی‌آور برایم آورده و به من گفته‌است که با درد بساز که برای تو دوا و درمان می‌فرستم.',NULL);
INSERT INTO "verses" VALUES(1936147,2220,9,1,'فِی‌الجمله می‌کنی و فرو می‌گذارمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936148,2219,8,1,'با درد صبر کن که دوا می‌فرستمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936149,2219,7,0,'تا مطربان ز شوقِ مَنَت آگهی دهند','تا مطربان و خوانندگان با شوق و شور بتوانند عشق مرا برای تو بیان کنند این غزل را آهنگین و با نوا به تو تقدیم می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1936150,2219,6,0,'در رویِ خود تَفَرُّجِ صُنع خدای کن','به رخ زیبای خود بنگر و از آفریده شگفت خدا لذت ببر در این آیینه خدای‌نما که برایت می‌فرستم.',NULL);
INSERT INTO "verses" VALUES(1936151,2219,6,1,'کآیینهٔ خدای‌نما می‌فرستمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936152,2219,5,0,'ای غایب از نظر که شدی هم‌نشین دل','ای یار غایب از دیده که در دل جای داری، تو را دعای خیر می‌گویم و به‌تو آفرین می‌فرستم.',NULL);
INSERT INTO "verses" VALUES(1936153,2219,5,1,'می‌گویمت دعا و ثنا می‌فرستمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936154,2219,4,0,'تا لشکرِ غمت نکند مُلکِ دل خراب','تا لشکر غم و اندوه تو را غمگین و شکسته نکند جان عزیز خود را به نوا به تو تقدیم می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1936155,2219,4,1,'جانِ عزیزِ خود به نوا می‌فرستمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936156,2219,3,0,'هر صبح و شام قافله‌ای از دعای خیر','هر صبح و هر شامگاه کاروانی از دعای خیر و با گفتگو با باد شَمال و باد صبا بسوی تو روانه می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1936157,2219,3,1,'در صحبتِ شمال و صبا می‌فرستمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936158,2219,2,0,'در راهِ عشق مرحلهٔ قُرب و بُعد نیست','در راه و مسلک عشق‌، دوری و نزدیکی وجود ندارد هرجایی باشی تو را می‌بینم و تو را دعا می‌گویم.',NULL);
INSERT INTO "verses" VALUES(1936159,2219,2,1,'می‌بینمت عیان و دعا می‌فرستمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936160,2219,1,0,'حیف است طایری چو تو در خاک‌دانِ غم','حیف است پرنده‌ای مثل تو در این خاک‌دان غم بمانی‌؛ تو را به سرزمین مهر و وفا می‌فرستم.',NULL);
INSERT INTO "verses" VALUES(1936161,2219,1,1,'زین جا به آشیانِ وفا می‌فرستمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936162,2219,0,1,'بنگر که از کجا به کجا می‌فرستمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936163,2219,7,1,'قول و غزل به ساز و نوا می‌فرستمت',NULL,NULL);
INSERT INTO "verses" VALUES(1936164,2208,6,1,'که گر چه غرقِ گناه است، می‌رود به بهشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936165,2208,5,1,'که آگه است که تقدیر بر سرش چه نوشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936166,2208,6,0,'قدم دریغ مدار از جنازهٔ حافظ','از جنازه حافظ قدم دریغ مدار و به خاک‌سپاری او بیا؛ زیرا اگرچه غرق گناه است به بهشت می‌رود.',NULL);
INSERT INTO "verses" VALUES(1936167,2198,11,0,'ای چنگ فروبرده به خونِ دلِ حافظ','هوش مصنوعی: ای چنگی که به خون دل حافظ آغشته‌ای، آیا اندیشه‌ات جز از غیرت قرآن و خداست؟',NULL);
INSERT INTO "verses" VALUES(1936168,2198,10,0,'در صومعهٔ زاهد و در خلوتِ صوفی','هوش مصنوعی: در مکان‌های عبادت زاهدان و در تنهایی عارفان، تنها نشانه‌ای از درخواست و دعا وجود ندارد جز کناره‌ی ابروی تو.',NULL);
INSERT INTO "verses" VALUES(1936169,2198,10,1,'جز گوشهٔ ابروی تو محرابِ دعا نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936170,2198,9,0,'عاشق چه کُنَد گر نَکِشَد بارِ ملامت','هوش مصنوعی: عاشق چه کار می‌تواند بکند اگر بار سرزنش را تحمل نکند. هیچ قهرمانی هم نمی‌تواند در برابر تیرهای سرنوشت از خود دفاع کند.',NULL);
INSERT INTO "verses" VALUES(1936171,2198,9,1,'با هیچ دلاور سپرِ تیرِ قضا نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936172,2198,8,0,'گر پیر مغان مرشدِ من شد چه تفاوت','هوش مصنوعی: اگر راهنمای من، همان پیر و پیشوای مغان باشد، هیچ تفاوتی در هیچ چیزی وجود ندارد، چرا که هیچ رازی نیست که از خدا جدا باشد.',NULL);
INSERT INTO "verses" VALUES(1936173,2198,8,1,'در هیچ سری نیست که سِرّی ز خدا نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936174,2198,7,0,'دی می‌شد و گفتم صنما عهد به جای آر','دیشب به محبوبم گفتم که در این رابطه به عهد و پیمان وفا کن. او پاسخ داد که خواجه، در این زمانه، عهد وفا وجود ندارد و این حرف تو اشتباه است.',NULL);
INSERT INTO "verses" VALUES(1936175,2198,7,1,'گفتا غلطی خواجه در این عهد وفا نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936176,2198,6,0,'تیمارِ غریبان اثرِ ذکرِ جمیل است','هوش مصنوعی: مراقبت از بیگانگان نتیجه‌ی یادآوری زیبایی‌هاست، آیا این قانون در شهر شما وجود ندارد؟',NULL);
INSERT INTO "verses" VALUES(1936177,2198,6,1,'جانا مگر این قاعده در شهرِ شما نیست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936178,2198,5,0,'بازآی که بی روی تو ای شمعِ دل افروز','هوش مصنوعی: مرا به یاد بیاور، زیرا در حضور دوستان، بدون تو روشنایی و زیبایی وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1936179,2198,5,1,'در بزمِ حریفان، اثرِ نور و صفا نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936180,2198,4,0,'از بهرِ خدا زلف مَپیرای که ما را','برای خاطر خدا موهایت را پریشان مکن، چرا که ما شبی نداریم (که از روی حسادت) با باد صبا‌، عربده و جنگ نداشته‌باشیم.',NULL);
INSERT INTO "verses" VALUES(1936181,2198,4,1,'شب نیست که صد عربده با بادِ صبا نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936182,2198,3,0,'نرگس طلبد شیوهٔ چشمِ تو، زهی چشم','هوش مصنوعی: نرگس به دنبال روش نگاه تو است، وای بر چشمی که از حال او بی‌خبر است و در چشمانش شرم وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1936183,2198,3,1,'مسکین خبرش از سر و، در دیده حیا نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936184,2198,2,0,'روی تو مگر آینهٔ لطفِ الهیست','هوش مصنوعی: چهرهٔ تو حقیقتاً تجلی نعمت‌های الهی است، و واقعاً همین‌طور است که در این ظاهر و در این ظواهر هیچ چیز غیر از راستی وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1936185,2198,2,1,'حقا که چنین است و در این روی و ریا نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936186,2198,1,0,'چون چشمِ تو دل می‌برد از گوشه نشینان','هوش مصنوعی: چشم تو آن‌قدر زیباست که دل‌ها را می‌رباید و از این که ما در کنارت باشیم، هیچ تقصیری بر عهده ما نیست.',NULL);
INSERT INTO "verses" VALUES(1936187,2198,1,1,'همراهِ تو بودن گُنَه از جانب ما نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936188,2198,0,0,'کس نیست که افتادهٔ آن زلفِ دوتا نیست','هیچ‌کس نیست که زلف‌های دوتای او را ببیند و عاشق و گرفتارش نشود؛ همچون بلا که سر راه همه هست. (زلف دو تا‌: گیسوی بافته که بر طرفین گردن و سینه می‌افتد)',NULL);
INSERT INTO "verses" VALUES(1936189,2198,0,1,'در رهگذرِ کیست که دامی ز بلا نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936190,2197,6,0,'کوهِ اندوهِ فراقت به چه حالت بکِشد؟','بار غم سخت جدایی تورا چگونه به دوش بکشم؟؟ منی که تنم همچون نی از ناله، ناتوان و خسته هست.',NULL);
INSERT INTO "verses" VALUES(1936191,2197,6,1,'حافظِ خسته که از ناله تنش چون نالی‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936192,2197,5,0,'مژده دادند که بر ما گذری خواهی کرد','مژده دادند که می‌خواهی سری به ما بزنی. از این تصمیم خوبت پشیمان نشو که خوش‌یمن است.',NULL);
INSERT INTO "verses" VALUES(1936193,2197,5,1,'نیّتِ خیر مگردان که مبارک فالی‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936194,2197,4,0,'بعد از اینم نَبُوَد شائبه در جوهرِ فرد','هرچه از «گوهر یگانه» شنیدم (شک داشتم) تا آنکه دهان تو را دیدم و پس از آن برایم تردیدی در وجود آن باقی نماند.',NULL);
INSERT INTO "verses" VALUES(1936195,2197,4,1,'که دهانِ تو در این نکته خوش استدلالی‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936196,2198,11,1,'فکرت مگر از غیرتِ قرآن و خدا نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936197,2199,0,0,'مردم دیدهٔ ما جز به رُخَت ناظر نیست','چشمهای ما تنها به چهره تو می نگرند و دل سرگشته ما فقط به یاد تو هست',NULL);
INSERT INTO "verses" VALUES(1936198,2199,0,1,'دل سرگشتهٔ ما غیرِ تو را ذاکر نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936199,2199,1,0,'اشکم احرامِ طوافِ حَرَمَت می‌بندد','هوش مصنوعی: اشک‌هایم به مانند لباس احرامی برای طواف در حریم تو آماده می‌شوند، هرچند که از دل رنجور و خونین من، ذره‌ای پاکی وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1936200,2200,7,0,'بَر دَرِ مِیخانه رَفْتَن، کارِ یِکرَنْگان بُوَد','به میخانه رفتن کار آدم‌های یک‌رنگ و صادق است آدم‌های خود‌فروش در میان آدم‌های یکرنگ و صاف جایی ندارند.',NULL);
INSERT INTO "verses" VALUES(1936201,2200,6,0,'هَر کِه خواهد گو: «بیا!» و هَرچِه خواهد گو: «بِگو!»','هرکسی هرچه درباره ما می‌خواهد بگوید، بگوید؛ در درگاه ما غرور و ناز و نگهبان و خودپرستی جایی ندارد.',NULL);
INSERT INTO "verses" VALUES(1936202,2200,6,1,'کِبْر و ناز و حاجِب و دَرْبان، بدین دَرْگاه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936203,2200,5,0,'صاحِبِ دیوانِ ما گویی نمی‌دانَد حِساب','فرشته نویسنده دیوان اعمال ما گویی حساب و کتاب نمی‌داند کاندر این طُغرا نشانِ حِسبَةً لِلّه نیست.',NULL);
INSERT INTO "verses" VALUES(1936204,2200,5,1,'کاندر این طُغرا، نِشانِ حِسْبَةً لِلّٰه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936205,2200,4,0,'این چِه اِسْتِغْناست یا رَب؟ وین چه قادِرْ حِکْمَت است؟','یارب، این چه قدرت استغنا (از اصطلاحات طریقت است) مراست و این چه قادر حکمت است که این همه درد و زخم نهانی وجود دارد اما شکوه و گلایه‌ای نیست.',NULL);
INSERT INTO "verses" VALUES(1936206,2200,4,1,'کاین‌همه زَخْمِ نَهان است و مَجالِ آه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936207,2200,3,0,'چیست این سقفِ بلندِ سادهٔ بِسیارنقش؟','خدا می‌داند که این آسمان (و هستی) ساده و در عین حال پر نقش و نگار چیست! هیچ دانایی در جهان به راز چیستی آن آگاه نشده است.',NULL);
INSERT INTO "verses" VALUES(1936208,2200,3,1,'زین مُعَمّا، هیچ دانا در جَهان، آگاه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936209,2200,2,0,'تا چه بازی رُخ نُماید بِیْدَقی خواهیم رانْد','تا ببینیم در نهایت چه خواهد شد و تا آن‌زمان مهره کم‌ارزشی را در این بازی شطرنج جابجا می‌کنیم و به بازی ادامه می‌دهیم در شطرنج انسانهای رندوم زیرک، حتی شاه فرصتی برای خودنمایی نمی‌یابد. (رخ‌، بیذق (سرباز)، و شاه هرسه مهره‌های بازی شطرنج هستند)',NULL);
INSERT INTO "verses" VALUES(1936210,2200,2,1,'عَرْصِه‌یِ شَطْرَنْجِ رِنْدان را مَجالِ شاه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936211,2200,1,0,'دَر طَریقَت هَرچِه پیشِ سالک آید، خِیْرِ اوست','در آیین طریقت، چنین است که هرچه برای سالک پیش بیاید آن‌را خیر و صلاح خود می‌بیند؛ ای جان من، کسی که بر صراط مستقیم است گمراه نیست!',NULL);
INSERT INTO "verses" VALUES(1936212,2200,1,1,'دَر صِراطِ مُسْتَقیم، اِی دِل، کَسی گُمراه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936213,2200,0,0,'زاهِدِ ظاهِرپَرَست از حالِ ما، آگاه نیست','کسی که فقط به ظاهر عبادت، دین‌داری و رفتار آدم‌ها نگاه می‌کند، نمی‌تواند حال عاشقانه، عرفانی و باطنی ما را بفهمد. پس اگر ما را سرزنش کند یا درباره‌مان قضاوتی کند، مهم نیست؛ چون از حقیقت ما آگاه نیست.',NULL);
INSERT INTO "verses" VALUES(1936214,2197,3,0,'ای که انگشت‌نمایی به کرم در همه شهر','ای که در کل شهر به بذل و بخشش مشهوری، چرا در حق غریبان کوتاهی می‌کنی؟',NULL);
INSERT INTO "verses" VALUES(1936215,2200,0,1,'دَر حَقِ ما، هَرچِه گوید، جایِ هیچ اِکْراه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936216,2199,8,0,'سر پیوند تو تنها نه دلِ حافظ راست','هوش مصنوعی: دل حافظ تنها به خاطر پیوند توست، اما کیست که نام تو را در ذهنش به یاد داشته باشد و به او اشاره کند؟',NULL);
INSERT INTO "verses" VALUES(1936217,2199,7,0,'روز اول که سرِ زلفِ تو دیدم گفتم','هوش مصنوعی: در روز نخست که موهای تو را دیدم، به خودم گفتم که این بی‌نظمی و درهم‌ریختگی هیچ‌گاه پایان نمی‌یابد.',NULL);
INSERT INTO "verses" VALUES(1936218,2199,7,1,'که پریشانیِ این سلسله را آخر نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936219,2199,6,0,'من که در آتشِ سودای تو آهی نزنم','هوش مصنوعی: من در آتش عشق تو دلی پر از درد دارم و هیچ وقت صدایی از من درنمی‌آید. پس کی می‌توان گفت که دلم روی زخم‌ها و غم‌ها صبوری می‌کند؟',NULL);
INSERT INTO "verses" VALUES(1936220,2199,6,1,'کِی توان گفت که بر داغ، دلم صابر نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936221,2199,5,0,'از روان بخشی عیسی نزنم دَم هرگز','هوش مصنوعی: من هرگز از روح پاک عیسی در خود دم نمی‌زنم، زیرا در افزایش روح، زبانم به اندازه لبت ماهر نیست.',NULL);
INSERT INTO "verses" VALUES(1936222,2199,5,1,'زان که در روح فَزایی چو لبت ماهر نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936223,2199,4,0,'عاقبت دست بدان سروِ بلندش برسد','هوش مصنوعی: در نهایت، آن کسی که در جستجوی تو تلاشش کافی است، به آن درخت بلند (علامت عشق یا هدف) خواهد رسید.',NULL);
INSERT INTO "verses" VALUES(1936224,2199,4,1,'هر که را در طلبت همتِ او قاصر نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936225,2199,3,0,'عاشقِ مفلس اگر قلبِ دلش کرد نثار','هوش مصنوعی: اگر کسی که عاشق و بی‌پول است، دلش را برای کسی از جانش نثار کند، نباید او را سرزنش کرد، زیرا او توان ارائه چیزی بیش از عشقش را ندارد.',NULL);
INSERT INTO "verses" VALUES(1936226,2199,3,1,'مَکُنَش عیب که بر نقدِ روان قادر نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936227,2199,2,0,'بستهٔ دام و قفس باد چو مرغ وحشی','هوش مصنوعی: در این بیت به این نکته اشاره می‌شود که اگرچه ممکن است شرایط و محدودیت‌هایی وجود داشته باشد، اما هنوز هم در جستجوی چیزهای باارزش و دلخواه هستیم. مانند پرنده‌ای وحشی که با وجود قفس و دام‌ها، هنوز به دنبال آزادی و آرزوهایش است. در واقع، انسان‌ها همیشه به دنبال اهداف و آرزوهای خود هستند، حتی اگر در شرایط سختی قرار داشته باشند.',NULL);
INSERT INTO "verses" VALUES(1936228,2199,2,1,'طایر سِدره اگر در طلبت طایر نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936229,2199,1,1,'گرچه از خونِ دلِ ریش دمی طاهر نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936230,2199,8,1,'کیست آن کِش سَرِ پیوند تو در خاطر نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936231,2200,7,1,'خودفُروشان را به کویِ مِی‌فُروشان، راه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936232,2197,3,1,'وه که در کارِ غریبان، عَجَبَت اِهمالی‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936233,2197,2,0,'می‌چکد شیر هنوز از لبِ هم‌چون شکرش','آنقدر بچه است که هنوز از دهنش شیر می‌چکد اگر چه به قدر یک قاتل حرفه‌ای در کار دلبری حرفه‌ای است.',NULL);
INSERT INTO "verses" VALUES(1936234,2195,1,0,'در آن زمین که نسیمی وزد ز طُرِّهٔ دوست','در آن زمین که نسیمی از گیسوی دوست می‌وزد و عطر و بوی آن را با خود می‌آورد، دیگر جایی برای خودنمایی و عرض‌اندامِ مشک‌های خوش‌بوی تاتاری نیست؛ چراکه در برابر عطر گیسوی دوست، حتی مشک تاتاری نیز جلوه و اعتباری ندارد. (نافه، کیسه‌ای از مشک است که از ناف آهوی مُشکین به دست می‌آید و «نافه‌های تاتاری» اشاره به مشک و عطر خوش‌بوی سرزمین تاتار دارد که در شعر فارسی نماد عطری بسیار خوش و ارزشمند است.)',NULL);
INSERT INTO "verses" VALUES(1936235,2195,1,1,'چه جایِ دم زدنِ نافه‌های تاتاری‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936236,2195,0,0,'بنال بلبل اگر با مَنَت سرِ یاری‌ست','ای بلبل، اگر قصد یاری و همدلی با من را داری، ناله سر کن؛ زیرا ما هر دو عاشقانی درمانده و نالانیم و کارِ عاشق زاری کردن است. (بلبل در شعر فارسی نماد عاشق و ناله و آواز او نشانه‌ای از عشق و بی‌قراری است. بلبل عاشق گل است و شاعر عاشق معشوق خویش؛ از این رو شاعر به سبب این هم‌سرنوشتی، بلبل را به زاری و ناله دعوت می‌کند.)',NULL);
INSERT INTO "verses" VALUES(1936237,2195,0,1,'که ما دو عاشق زاریم و کارِ ما زاری‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936238,2194,7,0,'زاهد شرابِ کوثر و حافظ پیاله خواست','میان زهد خشک و عشق الهی، خداوند بیشتر دل عاشق و آگاه را می‌پسندد. حافظ در این بیت، به ما می‌آموزد که اصل طلب حقیقت و قرب الهی، در عشق و آگاهی است، نه در ظاهر دین و زهد خشک. پیاله حافظ نماد دل عاشق و روح آگاه است، که با جرعه‌ای از معرفت و حضور الهی، به حقیقت نزدیک می‌شود، در حالی که زهد ظاهری ممکن است تنها به شکل رعایت قواعد و ترس از عقوبت باقی بماند.',NULL);
INSERT INTO "verses" VALUES(1936239,2194,7,1,'تا در میانه خواستهٔ کردگار چیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936240,2194,6,0,'سهو و خطایِ بنده گَرَش اعتبار نیست','هوش مصنوعی: اگر اشتباهات من ارزشی ندارند، پس مفهوم عفو و بخشش از سوی رحمت‌کننده چیست؟',NULL);
INSERT INTO "verses" VALUES(1936241,2194,6,1,'معنیِ عفو و رحمتِ آمُرزگار چیست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936242,2194,5,0,'راز درونِ پرده چه داند فلک؟ خموش','هوش مصنوعی: فلک از رازهای پنهان در پرده بی‌خبر است. ای مدعی، چرا در مورد چیزی که به پرده‌دار ربط دارد دعوا می‌کنی؟ خاموش باش.',NULL);
INSERT INTO "verses" VALUES(1936243,2194,5,1,'ای مدعی! نزاعِ تو با پرده‌دار چیست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936244,2194,4,0,'مستور و مست هر دو چو از یک قبیله‌اند','هوش مصنوعی: مستور و مست هر دو از یک نوع هستند، پس تفاوتی در انتخاب معشوق وجود ندارد. ما باید ببینیم که به چه کسی دل بدهیم، چون هر دو در واقع یکی هستند.',NULL);
INSERT INTO "verses" VALUES(1936245,2194,4,1,'ما دل به عشوهٔ که دهیم؟ اختیار چیست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936246,2194,3,0,'معنیِ آبِ زندگی و روضهٔ ارم','هوش مصنوعی: آبِ زندگی و باغ بهشت تنها در کنار جویبار و شراب لذیذ معنا پیدا می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1936247,2194,3,1,'جز طَرفِ جویبار و میِ خوشگوار چیست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936248,2194,2,0,'پیوندِ عمر بسته به مویی‌ست، هوش دار','هوش مصنوعی: عمر انسان به یک رشته نازک وابسته است، بنابراین باید مراقب خودت باشی و برای مشکلات زندگی نگرانی نداشته باشی.',NULL);
INSERT INTO "verses" VALUES(1936249,2194,2,1,'غمخوارِ خویش باش، غمِ روزگار چیست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936250,2194,1,0,'هر وقتِ خوش که دست دهد، مغتنم شمار','هوش مصنوعی: هر زمانی که فرصت خوبی پیش آمد، آن را غنیمت بشمار؛ زیرا هیچ‌کس نمی‌داند سرانجام کار چطور خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1936251,2194,1,1,'کس را وقوف نیست که انجامِ کار چیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936252,2194,0,0,'خوش‌تر ز عیش و صحبت و باغ و بهار چیست؟','هوش مصنوعی: چیزی زیباتر از شادی، دور هم بودن، طبیعت و بهار وجود ندارد. اما ای ساقی، چرا هنوز زود نیامدی و ما منتظریم؟',NULL);
INSERT INTO "verses" VALUES(1936253,2194,0,1,'ساقی کجاست؟ گو سببِ انتظار چیست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936254,2193,7,0,'بیار می که چو حافظ هزارم استظهار','هوش مصنوعی: بیار می، چرا که مثل حافظ، هزار بار از آینده امید دارم و به گریه صبحگاهی و درخواست‌های شبانه نیازمندم.',NULL);
INSERT INTO "verses" VALUES(1936255,2193,7,1,'به گریهٔ سحری و نیازِ نیم‌شبی‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936256,2193,6,0,'هزار عقل و ادب داشتم من ای خواجه','هوش مصنوعی: من در گذشته هزاران عقل و ادب داشتم، اما اکنون که مست و خراب هستم، به نظر می‌رسد که بی‌ادبی بهترین کار است.',NULL);
INSERT INTO "verses" VALUES(1936257,2193,6,1,'کنون که مستِ خرابم، صلاح بی‌ادبی‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936258,2193,5,0,'جمالِ دختر رَز، نورِ چشمِ ماست مگر','بی‌شک زیبایی می روشنی بخش چشم ماست که در نقاب بلورین و پس پرده‌ای شفاف قرار گرفته',NULL);
INSERT INTO "verses" VALUES(1936259,2193,5,1,'که در نقابِ زُجاجی و پردهٔ عِنَبی‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936260,2193,4,0,'به نیم جو نخرم طاقِ خانقاه و رِباط','هوش مصنوعی: من برای نیم جو (مقدار بسیار کمی از پول) طاق خانقاه و رباط (محل‌های عبادت و زندگی صوفیان) خودم را نمی‌فروشم، چون در واقع صندلی ایوان و پای خم که نشیمنگاه من است، برایم با ارزش‌تر از آن است.',NULL);
INSERT INTO "verses" VALUES(1936261,2193,4,1,'مرا که مَصطَبه ایوان و پای خُم طَنَبی‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936262,2193,3,0,'سبب مپرس که چرخ از چه سِفله‌پرور شد','هوش مصنوعی: دلیل آن را نپرس که چرا گردش روزگار افرادی ناتوان و بی‌ارزش را پرورش می‌دهد؛ زیرا بزرگ‌منشی و موفقیت او هیچ دلیل خاصی ندارد و این یک امر تصادفی است.',NULL);
INSERT INTO "verses" VALUES(1936263,2195,2,0,'بیار باده که رنگین کنیم جامهٔ زرق','هوش مصنوعی: بیا شراب بیاور تا جام زرق و برق را رنگین کنیم، زیرا ما به قدری مست این جام خودخواهی هستیم که نام آن را هشیاری می‌گذاریم.',NULL);
INSERT INTO "verses" VALUES(1936264,2195,2,1,'که مستِ جامِ غروریم و نام هشیاری‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936265,2195,3,0,'خیالِ زلفِ تو پختن نه کارِ هر خامی‌ست','هوش مصنوعی: تصور کردن و دل بستن به زلف تو، کار هر کسی نیست؛ زیرا برای درک و درگیری با جذابیت‌های تو، نیاز به تجربه و هوشمندی خاصی دارد.',NULL);
INSERT INTO "verses" VALUES(1936266,2195,3,1,'که زیرِ سلسله رفتن طریقِ عیّاری‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936267,2197,1,0,'مردم دیده ز لطفِ رخِ او در رخِ او','رُخش چنان لطیف و زلال و پاک بود که مردمک دیده، تصویر خود را در آن دید و پنداشت که خالی مشکین و سیاه بر رخ او دیده است.',NULL);
INSERT INTO "verses" VALUES(1936268,2197,1,1,'عکس خود دید، گمان برد که مشکین خالی‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936269,2197,0,0,'ماهم این هفته برون رفت و به چشمم سالی‌ست','ماه من (دلبر من) فقط یک هفته است که رفته اما به چشمم سالی گذشت (معنای دوم: این ماه این هفته تمام شد و به نظرم رسید که این یک ماه یک سال طول کشید). تو چه می‌دانی که حال دوری از یار چه حالی است؟',NULL);
INSERT INTO "verses" VALUES(1936270,2197,0,1,'حالِ هجران تو چه دانی که چه مشکل حالی‌ست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936271,2196,6,0,'گفتم آه از دلِ دیوانهٔ حافظ بی‌تو','هوش مصنوعی: گفتم که دلِ دیوانه‌ام به خاطر تو ناله می‌کند، و او با لبخند گفت که دیوانهٔ کدام یک از انسان‌هاست؟',NULL);
INSERT INTO "verses" VALUES(1936272,2196,6,1,'زیرِ لب خنده‌زنان گفت که دیوانهٔ کیست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936273,2196,5,0,'یا رب آن شاه‌وَشِ ماه‌رخِ زهره‌جبین','ای خدا، آن پادشاه با چهره‌ی ماهی و پیشانی چون زهره، که همانند دُرّ گرانبهایی است، دردانه ی چه کسی است؟',NULL);
INSERT INTO "verses" VALUES(1936274,2196,5,1,'دُرِّ یکتایِ که و گوهر یک‌دانهٔ کیست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936275,2196,4,0,'می‌دهد هر کَسَش افسونی و معلوم نشد','هوش مصنوعی: هر شخصی جادویی به او می‌دهد و مشخص نیست که دل حساس او به افسانه‌ی کدامین فرد گرایش دارد!',NULL);
INSERT INTO "verses" VALUES(1936276,2196,4,1,'که دلِ نازکِ او مایلِ افسانهٔ کیست!',NULL,NULL);
INSERT INTO "verses" VALUES(1936277,2196,3,0,'دولتِ صحبتِ آن شمعِ سعادت‌پرتو','به خدا قسم‌ بپرسید که سعادت همنشینی با آن شمع نکو طالع نصیب کدام پروانه شده است.(شمع استعاره از معشوق و پروانه استعاره از عاشق است)',NULL);
INSERT INTO "verses" VALUES(1936278,2196,3,1,'باز پرسید خدا را که به پروانهٔ کیست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936279,2196,2,0,'بادهٔ لعلِ لبش کز لبِ من دور مباد','لب همچون شراب سرخ او که آرزو دارم از لب من دور نباشد، مایه نشاط و متعهد به چه کسی است؟ (پیمان‌ده پیمانه کنایه از وفادار و عهدبسته بودن)',NULL);
INSERT INTO "verses" VALUES(1936280,2196,2,1,'راحِ روحِ که و پیمان‌ده پیمانهٔ کیست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936281,2197,2,1,'گر چه در شیوه‌گری هر مژه‌اش قَتّالی‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936282,2196,1,0,'حالیا خانه‌براندازِ دل و دین من است','هوش مصنوعی: این لحظه، عشق و تعلقات من را تحت تأثیر قرار داده و در حال حاضر فقط به این فکر می‌کنم که با چه کسی در آغوش خوابیده است و در واقع هم‌خانه‌اش کیست؟',NULL);
INSERT INTO "verses" VALUES(1936283,2196,0,0,'یا رب این شمع دل‌افروز ز کاشانهٔ کیست؟','پروردگارا! این شمع شادی‌بخش، متعلق به کدام خانه است؟ جان ما در آتش عشق او سوخت، از او بپرسید که معشوقه‌‌ی کیست؟',NULL);
INSERT INTO "verses" VALUES(1936284,2196,0,1,'جانِ ما سوخت، بپرسید که جانانهٔ کیست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936285,2195,9,0,'دلش به ناله میازار و ختم کن حافظ','هوش مصنوعی: دل کسی را نرنجان و با آرامش تمام بکن، زیرا نجات ابدی در کم آزار دادن دیگران نهفته است.',NULL);
INSERT INTO "verses" VALUES(1936286,2195,9,1,'که رستگاریِ جاوید در کم آزاری‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936287,2195,8,0,'سحر کرشمهٔ چشمت به خواب می‌دیدم','هوش مصنوعی: در بامداد، زیبایی چشمانت را در خواب می‌دیدم و این خواب، به مراتب از بیداری خوشایندتر بود.',NULL);
INSERT INTO "verses" VALUES(1936288,2195,8,1,'زهی مراتب خوابی که بِه ز بیداری‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936289,2195,7,0,'بر آستان تو مشکل توان رسید آری','هوش مصنوعی: برای رسیدن به درگاه تو، کار آسانی نیست. صعود به اوج مقام و بزرگی نیز با سختی همراه است.',NULL);
INSERT INTO "verses" VALUES(1936290,2195,7,1,'عروج بر فلکِ سروری به دشواری‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936291,2195,6,0,'قلندرانِ حقیقت به نیم جو نخرند','هوش مصنوعی: درست مثل قلندران که برای حقیقت ارزش قائل هستند، از کسی که از هنر و دانایی بی‌بهره است، نه تنها ارزش و احترامی نمی‌طلبند بلکه به لباس و زرق و برق ظاهری او هم توجهی ندارند.',NULL);
INSERT INTO "verses" VALUES(1936292,2195,6,1,'قبایِ اطلس آن کس که از هنر عاری‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936293,2195,5,0,'جمالِ شخص، نه چشم است و زلف و عارض و خال','هوش مصنوعی: زیبایی یک فرد تنها به ویژگی‌های ظاهری مثل چشمانش، موهایش و خال‌هایش محدود نمی‌شود؛ بلکه در این مساله نکات و ظرافت‌های بسیاری در ارتباط با دلربایی و جذب دیگران وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1936294,2195,5,1,'هزار نکته در این کار و بارِ دلداری‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936295,2195,4,0,'لطیفه‌ای‌ست نهانی که عشق از او خیزد','رازی ظریف وجود دارد که عشق از آن سرچشمه می‌گیرد، و این راز به عبارت‌های معمولی مثل رنگ لب یا خط زیبایی اشاره نمی‌کند.',NULL);
INSERT INTO "verses" VALUES(1936296,2195,4,1,'که نام آن نه لبِ لعل و خطِ زنگاری‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936297,2196,1,1,'تا در آغوشِ که می‌خسبد و هم‌خانهٔ کیست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936298,2224,3,0,'تو گر خواهی که جاویدان جهان یکسر بیارایی','اگر می‌خواهی که تا ابد دنیا را آراسته و زیبا کنی به نسیم صبا بگو که یک لحظه برقع از رُخت بردارد.',NULL);
INSERT INTO "verses" VALUES(1936299,2200,8,0,'هرچه هست از قامَتِ ناسازِ بی‌اَنْدامِ ماست','هر ایرادی هست از ماست و از خود ماست وگرنه لطف تو به هیچ‌کس کوتاهی نکرده است.',NULL);
INSERT INTO "verses" VALUES(1936300,2200,9,0,'بَنْدِه‌یِ پیرِ خَراباتَم که لُطْفَش، دائِم است','بنده پیر می‌فروش خرابات هستم که لطف و مهربانی او دایمی است؛ لطف و مِهر شیخ و زاهد‌، اتفاقی و گذراست.',NULL);
INSERT INTO "verses" VALUES(1936301,2206,3,0,'درنمی‌گیرد نیاز و ناز ما با حُسن دوست','هوش مصنوعی: نیاز و زیبایی ما با لطف و زیبایی دوست به هماهنگی نمی‌رسد، چرا که از میان محبوبان، تنها کسی که سرنوشت خوشی را به دست آورد، درخشان و راضی است.',NULL);
INSERT INTO "verses" VALUES(1936302,2206,2,0,'یار اگر نَنشست با ما نیست جای اعتراض','هوش مصنوعی: اگر محبوب ما کنار ما نباشد، نباید از این موضوع شکایت کرد. زیرا پادشاهی که خوشبخت است، هرگز احساس خجالت از داشتن زندگی ساده و بی‌پناهی نمی‌کند.',NULL);
INSERT INTO "verses" VALUES(1936303,2206,2,1,'پادشاهی کامران بود، از گدایی عار داشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936304,2206,1,0,'گفتمش: در عینِ وصل‌، این نالِه و فریاد چیست؟','هوش مصنوعی: به او گفتم وقتی که در کنار هم هستیم، چرا این ناله و فریادها را می‌زنید؟ او پاسخ داد که این عکس‌العمل ما به زیبایی معشوق است که در این لحظه ما را تحت تأثیر قرار داده است.',NULL);
INSERT INTO "verses" VALUES(1936305,2206,1,1,'گفت ما را جلوه‌ی معشوق در این کار داشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936306,2206,0,0,'بلبلی، برگِ گُلی خوش‌رنگ در مِنقار داشت','هوش مصنوعی: یک بلبل، برگ گلی زیبا را در منقار داشت و در آن برگ، با صدای دلنشینی ناله‌های غمگینی سر می‌داد.',NULL);
INSERT INTO "verses" VALUES(1936307,2206,0,1,'و اندر آن برگ و نَوا، خوش ناله‌هایِ زار داشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936308,2205,8,0,'خزینهٔ دلِ «حافظ» به زلف و خال مده','هوش مصنوعی: دل حافظ را به زلف و خال نده، چون این کارها حد و مرزی برای سیاهی ندارند.',NULL);
INSERT INTO "verses" VALUES(1936309,2205,8,1,'که کارهای چنین، حدِّ هر سیاهی نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936310,2205,7,0,'چنین که از همه‌سو، دامِ راه می‌بینم','هوش مصنوعی: در اینجا شاعر بیان می‌کند که در شرایط دشواری قرار دارد و به راحتی متوجه می‌شود که از هر طرف خطراتی او را تهدید می‌کند. او احساس می‌کند که به غیر از زیبایی و لطف معشوقش، هیچ پشتیبانی و کمکی برایش وجود ندارد. این پشتیبانی، مانند حمایت زلف معشوق، تنها راه نجات او را نشان می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1936311,2205,7,1,'به از حمایتِ زلفش، مرا پناهی نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936312,2205,6,0,'عِنان‌کشیده رو ای پادشاهِ کشورِ حُسن','هوش مصنوعی: ای پادشاه زیبایی، سوار بر اسب خود باش، زیرا در راهی که می‌خواهی بروی، هیچ‌کس برای درخواست عدالت وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1936313,2205,6,1,'که نیست بر سر راهی که دادخواهی نیست!',NULL,NULL);
INSERT INTO "verses" VALUES(1936314,2205,5,0,'مباش در پیِ آزار و هرچه خواهی کن','هوش مصنوعی: دنبال آزار و اذیت دیگران نباش و هر چه می‌خواهی انجام بده، زیرا در اصول دین ما، غیر از این عمل، گناهی وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1936315,2205,5,1,'که در شریعتِ ما غیر از این، گناهی نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936316,2205,4,0,'غلامِ نرگسِ جَمّاشِ آن سَهی سروم','هوش مصنوعی: من بنده‌ی چشمان زیبا و دلربای او هستم که از شدت زیبایی و جذابیتش، نه به کسی توجهی دارد و نه به هیچ چیز دیگری. او در عالم خود غرق شده و از شراب عشقش مست است.',NULL);
INSERT INTO "verses" VALUES(1936317,2205,4,1,'که از شراب غرورش به کس، نگاهی نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936318,2205,3,0,'زمانه گَر بزند آتشم به خرمنِ عمر','هوش مصنوعی: اگر زمانه بر من سخت بگذرد و آتش بیفروزد و عمرم را بسوزاند، باید بگویم بسوزد، زیرا برای من هیچ چیز با ارزش‌تر از یک برگ کاهی وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1936319,2205,3,1,'بگو بسوز که بر من به برگِ کاهی نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936320,2205,2,0,'چرا زِ کویِ خرابات روی برتابم؟','هوش مصنوعی: چرا از محله خراباتی‌ها رویم کنار؟ چون در این دنیا هیچ اصول و راهی وجود ندارد که به نظر بیاید درست باشد.',NULL);
INSERT INTO "verses" VALUES(1936321,2205,2,1,'کز این بِهَم به جهان، هیچ رسم و راهی نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936322,2205,1,0,'عَدو چو تیغ کِشد، من سپر بیندازم','هوش مصنوعی: زمانی که دشمن شمشیر می‌کشد، من محافظتی نمی‌کنم و خود را در معرض خطر می‌گذارم، چرا که سلاح من تنها ناله و آه است و قدرتی بیشتر ندارم.',NULL);
INSERT INTO "verses" VALUES(1936323,2205,1,1,'که تیغِ ما، به ‌جز از ناله‌ای و آهی نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936324,2205,0,0,'جز آستان تواَم در جهان، پناهی نیست','هوش مصنوعی: جز درگاه تو در این دنیا هیچ پناهی ندارم و هیچ امیدی جز این در برای آرامش و دلجویی من نیست.',NULL);
INSERT INTO "verses" VALUES(1936325,2205,0,1,'سر مرا به ‌جز این در، حواله‌گاهی نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936326,2204,5,0,'دردِ عشق ار چه دل از خلق نهان می‌دارد','هوش مصنوعی: عشق اگرچه دردش را از دیگران پنهان می‌کند، اما چشمان گریان تو نشان می‌دهد که چیزی در درون وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1936327,2204,5,1,'حافظ این دیدهٔ گریانِ تو، بی‌چیزی نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936328,2204,4,0,'دوش، باد از سرِ کویش به گلستان بگذشت','هوش مصنوعی: دیشب، نسیم از کنار خانه‌ات گذشت. ای گل، این چاکی که در گریبان توست، بی‌دلیل نیست.',NULL);
INSERT INTO "verses" VALUES(1936329,2204,4,1,'ای گل! این چاکِ گریبانِ تو، بی‌چیزی نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936330,2206,3,1,'خُرَّم آن کز نازنینان‌، بخت برخوردار داشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936331,2206,4,0,'خیز تا بر کِلک آن نقاش‌، جان افشان کنیم','هوش مصنوعی: بیایید بیدار شویم و زندگی‌امان را به تصویر بکشیم، زیرا این همه نقش‌های شگفت‌انگیز نتیجه‌ی دقت و کار قدردانانه‌ای است که در دایره‌ی زندگی‌مان وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1936332,2206,4,1,'کاین همه نقش عجب در گردش پرگار داشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936333,2206,5,0,'گر مرید راه عشقی، فکر بدنامی مکن','اگر واقعاً سالک و پیرو راه عشق هستی، از بدنام شدن نترس. شیخ صنعان که پیر و مرشد بزرگی بود، آن‌قدر در راه عشق پیش رفت و بی توجه به حرف مردم بود که خرقهٔ لباس درویشان بود و همچنین نماد زهد و مقام معنوی ولی ان رابرای خرید شراب در میخانه گرو گذاشت .داستان شیخ صنعان در کتاب «منطق‌الطیر» عطار آمده است',NULL);
INSERT INTO "verses" VALUES(1936334,2208,4,1,'چو شمع صومعه افروزی از چراغِ کنشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936335,2208,5,0,'مَکُن به نامه سیاهی ملامتِ منِ مست','به گناهکاری و سیاه‌نامه بودن، مرا مؤاخذه و سرزنش مکن؛ که می‌داند که تقدیر بر سر او چه نوشته است؟',NULL);
INSERT INTO "verses" VALUES(1936336,2208,3,1,'بر آن سر است که از خاکِ ما بسازد خشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936337,2208,4,0,'وفا مجوی ز دشمن که پرتوی ندهد','از این دنیا که دشمن توست چشم وفا و مهر نداشته باش، زیرا شمع صومعه را اگر از چراغ کِنِشت بیفروزی، نور ندهد.',NULL);
INSERT INTO "verses" VALUES(1936338,2208,2,1,'نه عاقل است که نسیه خرید و نقد بِهِشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936339,2208,3,0,'به می عمارتِ دل کن که این جهانِ خراب','به می دل را خوش و آباد کن که این دنیای خراب‌بنیاد قصد آن دارد که از سرِ ما و خاک ما خشت بسازد.',NULL);
INSERT INTO "verses" VALUES(1936340,2208,1,1,'که خیمه، سایهٔ ابر است و بزمگه، لبِ کِشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936341,2208,2,0,'چمن حکایتِ اردیبهشت می‌گوید','چمن، داستان اردیبهشت را می‌گوید؛ عاقل نیست کسی که این بهشت نقد را گذاشت و به نسیه فریب خورد.',NULL);
INSERT INTO "verses" VALUES(1936342,2208,0,1,'من و شرابِ فرح‌بخش و یارِ حورسرشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936343,2208,1,0,'گدا چرا نزند لافِ سلطنت امروز؟','گدا و بی‌نوا چرا از شاهی و سلطنت دم نزند امروز که سایه ابر بهاری بر سبزه‌زار خیمه زده و لب کشت‌زار بزمگه اوست.',NULL);
INSERT INTO "verses" VALUES(1936344,2208,0,0,'کنون که می‌دمد از بوستان، نسیمِ بهشت','اکنون که فصل نسیم بهشتی است و بوی بوستان را می‌آورد زمان من و شراب شادی‌بخش است و من و یار حورصفت.',NULL);
INSERT INTO "verses" VALUES(1936345,2207,6,0,'«حافظ»! بِبَر تو گویِ فِصاحَت که مُدَّعی','حافظ، تو گوی فصاحت و سخن را ببر که مدعی و خصم نه‌تنها هیچ هنر نداشت بلکه حتی نمی‌دانست هنر و فصاحت چیست.',NULL);
INSERT INTO "verses" VALUES(1936346,2207,6,1,'هیچش هُنَر نَبود و خَبَر نیز هَم نَداشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936347,2207,5,0,'هَر راهرو که رَه به حَریمِ دَرَش نَبُرْد','هر راهرو که به حریم درِ او راه نیافت بی‌نوا و بی‌نصیب بیابان پیمود و سختی کشید و به اندرون حرم راه نیافت.',NULL);
INSERT INTO "verses" VALUES(1936348,2204,3,0,'مبتلایی به غمِ محنت و اندوهِ فراق','هوش مصنوعی: ای دل، تو درگیر غم و اندوه جدایی هستی و این گریه و آه تو، بی‌دلیل نیست.',NULL);
INSERT INTO "verses" VALUES(1936349,2207,5,1,'مِسْکین بُرید وادی و رَه دَر حَرَم نَداشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936350,2207,4,0,'ساقی بیار بادِه و با مُحْتَسِب بِگو','ساقی بیار باده و به شحنه چیزی مگو و ما را انکار و رد مکن که جامی که ما می‌گیریم جمشید نداشت.',NULL);
INSERT INTO "verses" VALUES(1936351,2207,3,0,'با این هَمِه، هَر آن‌که نَه خواری کَشید اَز او','با این‌همه‌، هر‌کسی را که او خوار نکرد، هرجا که رفت محترم نشد.',NULL);
INSERT INTO "verses" VALUES(1936352,2207,3,1,'هَر جا که رَفْت، هیچ کَسَش مُحْتَرَم نَداشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936353,2207,2,0,'بَر مَن، جَفا زِ بَخْتِ مَن آمَد وَگَرنَه یار','این جفا که بر من رفت از بخت بد من بود وگرنه یار اهل لطف بود و آیین و منش او از کرم دور نبود.',NULL);
INSERT INTO "verses" VALUES(1936354,2207,2,1,'حاشا که رَسْمِ لُطْف و طَریقِ کَرَم نَداشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936355,2207,1,0,'یا رَب مَگیرَش اَرْچِه دِلِ چون کَبوتَرَم','یارب مگیرش و مجازاتش مکن، اگرچه دل کبوتر بی‌پناه و بی‌گناه من را کشت و حرمت کبوتران حرم را نیز نگه نداشت.',NULL);
INSERT INTO "verses" VALUES(1936356,2207,1,1,'اَفْکَنْد و کُشْت و عِزَّتِ صِیْدِ حَرَم نَداشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936357,2207,0,0,'دیدی که یار، جُز سَرِ جور و سِتَم نَداشت','آخر دیدی که یار جز جور و ستم قصد دیگری نداشت؟ و دیدی که پیمان و عهد را شکست و به‌حال ما ترحمی نکرد؟',NULL);
INSERT INTO "verses" VALUES(1936358,2207,0,1,'بِشْکَسْت عَهْد، وَز غَمِ ما، هیچ غَم نَداشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936359,2206,7,0,'چشم حافظ زیر بام قصر آن حوری‌سرشت','هوش مصنوعی: چشم حافظ به زیر سقف کاخ آن حوری، زیبایی‌های بهشت را که نهرها زیر آن جاری است، نظاره می‌کند.',NULL);
INSERT INTO "verses" VALUES(1936360,2206,7,1,'شیوه‌ی جَنّاتُ تَجْری تَحْتِهَا الاَنهار داشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936361,2206,6,0,'وقت آن شیرین‌قلندر خوش که در اَطوارِ سِیر','هوش مصنوعی: زمانی است که آن قلندر شیرین، در حال سیر و سلوك، ذکر تسبیح فرشتگان را در حلقهٔ زنجیر به زبان می‌آورد.',NULL);
INSERT INTO "verses" VALUES(1936362,2206,6,1,'ذکر تسبیح ملک در حلقه‌ی زُنّار داشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936363,2206,5,1,'شِیخِ صَنعان، خِرقه رهن خانهٔ خَمّار داشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936364,2207,4,1,'اِنْکارِ ما مَکُن که چُنین جام، جَم نَداشت',NULL,NULL);
INSERT INTO "verses" VALUES(1936365,2200,8,1,'وَر نَه تَشْریفِ تو، بَر بالایِ کَس، کوتاه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936366,2204,3,1,'ای دل! این ناله و افغان تو، بی‌چیزی نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936367,2204,2,0,'جان درازیِ تو بادا که یقین می‌دانم','هوش مصنوعی: امیدوارم که عمر طولانی داشته باشی، زیرا می‌دانم که در تیرکمان زیبایی چشمانت، هیچ چیز کم و کاستی وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1936368,2202,5,0,'من از این طالع شوریده بِرَنجَم ور نی','اگر من از وصال تو محرومم دلیلی جز بخت و اقبال بد خودم ندارد، و الا همه از وصال تو بهره‌­مند و برخودار گشته‌­اند.',NULL);
INSERT INTO "verses" VALUES(1936369,2202,5,1,'بهره‌مند از سَرِ کویت دگری نیست که نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936370,2202,4,0,'تا دم از شامِ سرِ زلفِ تو هر جا نزنند','برای اینکه باد صبا، از سیاهی گیسوی همچون شب تو هر جا سخنی نگوید و در مورد آن صحبت نکند، هر سحر با آن مشغول مجادله و بحث و جدل هستم.',NULL);
INSERT INTO "verses" VALUES(1936371,2202,4,1,'با صبا گفت و شنیدم سحری نیست که نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936372,2202,3,0,'تا به دامن ننشیند ز نسیمش گَردی','اگر می‌­بینید تمام مسیرهای عبور و مرور از اشک­‌های سیل­‌خیز من خیس شده است، به خاطر این است که تا گرد و غباری از وزش نسیم بر دامن معشوق ننشیند.',NULL);
INSERT INTO "verses" VALUES(1936373,2202,3,1,'سیل خیز از نظرم ره‌گذری نیست که نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936374,2202,2,0,'اشکِ غَمّازِ من ار سرخ برآمد چه عجب؟','جای شگفتی نیست، اگر اشک سخن‌­چین من، سرخ و خونین فرو ریخت؛ زیرا هر کس راز دیگران را برملا سازد، از کرده­‌ی خود شرمسار و پشیمان خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1936375,2202,2,1,'خجل از کردهٔ خود پرده دری نیست که نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936376,2202,1,0,'ناظرِ روی تو صاحب نظرانند آری','تنها انسان­‌های اهل بصیرت و صاحب نظر به چهره‌­ی تو نگاه می­‌کنند؛ آری، رمز و راز وجود تو همچون گیسو در سر همه وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1936377,2202,1,1,'سِرِّ گیسوی تو در هیچ سَری نیست که نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936378,2202,0,0,'روشن از پرتوِ رویت نظری نیست که نیست','نور چهره‌­ی تو، تمام دیده‌­ها را روشن کرده است، احسان و نیکی خاک درگاه تو مانند توتیا شفابخش هر دیده­‌ای است.',NULL);
INSERT INTO "verses" VALUES(1936379,2202,0,1,'مِنَّت خاکِ درت بر بصری نیست که نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936380,2201,6,0,'نَگْرِفْت در تو، گِرْیِهٔ «حافِظ»، به هیچ رو','گریهٔ حافظ به هیچ وجه بر تو اثربخش نبود (نتوانست دل سخت تو را نرم کند). متحیّر و متعجّب مانده‌ام که چقدر تو سنگ‌دلی! (دل تو گویی که چیزی کم‌تر از سنگ خارا ندارد!)',NULL);
INSERT INTO "verses" VALUES(1936381,2201,6,1,'حِیْرانِ آن دِلَم که کَم از سَنْگِ خارِه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936382,2201,5,0,'فُرْصَت شِمُر طَریقِهٔ رِنْدی که این نِشان','مرام و مسلکِ رندی را مغتنم شمار (حُرمت آن را نگه دار)، چرا که این راه مثل نقشهٔ گنجی که هر کسی از آن خبر ندارد.',NULL);
INSERT INTO "verses" VALUES(1936383,2201,5,1,'چون راهِ گَنْج، بَر هَمِه‌کَس، آشْکارِه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936384,2201,4,0,'او را به چَشْمِ پاک، تَوان دید چون هِلال','برای دیدن معشوق باید چشمان پاکی داشت (او در چشم ناپاک نمی‌نشیند) مثل هلال عید [که برای دیدنش باید واجدِ شرایط بود]. هر چشمی شایستگی دیدن روی آن تکه‌ماه را ندارد.',NULL);
INSERT INTO "verses" VALUES(1936385,2201,4,1,'هَر دیده، جایِ جِلْوِهٔ آن ماه‌پارِه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936386,2201,3,0,'اَز چَشْمِ خود بِپُرس که ما را که می‌کُشَد؟','جادو و جاذبهٔ چشمان تو است که مرا را هلاک و از خود بی‌خود می‌کند. تقصیر سرنوشت و تاثیر ستارگان نیست [که مرا به این حال و روز مبتلا کرده است]. - یا: گناه قتل مرا به گردن طالع و سرنوشت مینداز؛ آنچه مرا می‌کشد چشمان زیبای توست.',NULL);
INSERT INTO "verses" VALUES(1936387,2201,3,1,'جانا، گُناهِ طالِع و جُرْمِ سِتارِه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936388,2201,2,0,'ما را زِ مَنْعِ عَقْل مَتَرْسان و مِی بیار!','ما عاشقان و رندان را از بازدارندگی عقل مترسان. چرا که آن پاسبان (شحنه) در شهر و دیار ما کاره‌ای نیست. در این‌جا شحنه (پاسبان) کنایه از عقل است.',NULL);
INSERT INTO "verses" VALUES(1936389,2201,2,1,'کآن شِحْنِه در وِلایَتِ ما، هیچ کارِه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936390,2201,1,0,'هر گَه که دِل به عِشْق دِهی، خوش دَمی بُوَد','هر گاه که عشق به تو روی می‌آورد خوب و نیکو است. دل بسپار و تردید مکن.',NULL);
INSERT INTO "verses" VALUES(1936391,2201,1,1,'در کارِ خِیْر، حاجَتِ هیچ اِسْتِخاره نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936392,2201,0,0,'راهی‌ست راهِ عِشْق که هیچَش کِنارِه نیست','راه عشق، راهی بی‌پایان و بیابانی بی‌انتهاست که مقصد این سفر جز جان باختن نیست. (کناره‌: نهایت‌، پایان)',NULL);
INSERT INTO "verses" VALUES(1936393,2201,0,1,'آن‌جا جُز آن‌که جان بِسِپارَنْد، چارِه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936394,2200,10,0,'«حافِظ»، اَر بَر صَدْر نَنْشینَد، زِ عالی‌مَشْرَبی‌ست','اگر حافظ در مجلس می‌گساری بر صدر نمی‌نشیند از آن است که بلند‌نظر است؛ عاشق دُردی‌کش به مال و مقام بی‌اعتناست.',NULL);
INSERT INTO "verses" VALUES(1936395,2200,10,1,'عاشِقِ دُرْدی‌کَش اَندَر بَنْدِ مال و جاه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936396,2200,9,1,'وَر نَه لُطْفِ شِیْخ و زاهِد، گاه هَسْت و گاه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936397,2202,6,0,'از حیایِ لبِ شیرینِ تو ای چشمهٔ نوش','ای معشوقی که همچون چشمه­ ای گوارا نوشیدنی هستی، اگر می­‌بینی شکر غرق آب و عرق می‌­شود و آب می­‌شود، بدین سبب است که شکر ، شیرینی خود را با لب شیرین تو مقایسه کرده است و اکنون از شدت شرمساری آب شده است.',NULL);
INSERT INTO "verses" VALUES(1936398,2202,6,1,'غرق آب و عرق اکنون شکری نیست که نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936399,2202,7,0,'مصلحت نیست که از پرده برون افتد راز','هر چند رندان بر همه­‌ی رازها آگاهند و تمام اسرار را می‌­دانند اما صلاح نمی­‌بینند که اسرار نهانی را آشکار کنند و پرده از حقیقت ماجرا کنار بزنند.',NULL);
INSERT INTO "verses" VALUES(1936400,2202,7,1,'ور نه در مجلسِ رندان خبری نیست که نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936401,2204,1,0,'از لبت شیر روان بود که من می‌گفتم','هوش مصنوعی: از لب‌هایت شیرین‌زبانی و لطافت می‌ریخت که من همیشه می‌گفتم این شکر، در کنار نمکدانت، بی دلیل نیست و به خاطر چیز خاصی است.',NULL);
INSERT INTO "verses" VALUES(1936402,2204,1,1,'«این شکر گِردِ نمکدانِ تو، بی‌چیزی نیست»',NULL,NULL);
INSERT INTO "verses" VALUES(1936403,2204,0,0,'خوابِ آن نرگسِ فَتّانِ تو، بی‌چیزی نیست','هوش مصنوعی: خواب آن نرگس جذاب تو، بدون دلیل نیست و زیبایی آن زلف‌های پریشان تو، بی علت نیست.',NULL);
INSERT INTO "verses" VALUES(1936404,2204,0,1,'تابِ آن زلفِ پریشانِ تو، بی‌چیزی نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936405,2203,8,0,'نام حافظ رقمِ نیک پذیرفت ولی','هوش مصنوعی: نام حافظ به عنوان یک شاعر معروف و نیکوکار شناخته شده است، اما در میان اهل علم و ادب، محاسبات و درک‌های متفاوتی درباره زندگی و مشکلات وجود دارد که به همین سادگی نیست و نمی‌توان تنها به نام او اکتفا کرد.',NULL);
INSERT INTO "verses" VALUES(1936406,2203,8,1,'پیش رندان رقمِ سود و زیان این همه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936407,2203,7,0,'دردمندیّ‌ِ منِ سوختهٔ زار و نَزار','هوش مصنوعی: درد و رنج من، که در وضعیت بسیار بدی قرار دارم، به نظر نمی‌رسد که نیازی به توضیح و بیان این همه مشکلات داشته باشد.',NULL);
INSERT INTO "verses" VALUES(1936408,2203,7,1,'ظاهرا حاجتِ تقریر و بیان این همه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936409,2203,6,0,'زاهد ایمن مشو از بازیِ غیرت، زنهار','هوش مصنوعی: ای زاهد، از بازی غیرت و فتنه‌ها غافل مشو، زیرا مسیر بین صومعه و میخانه به همین سادگی نیست.',NULL);
INSERT INTO "verses" VALUES(1936410,2203,6,1,'که ره از صومعه تا دیرِ مغان این همه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936411,2203,5,0,'بر لبِ بحرِ فنا منتظریم ای ساقی','هوش مصنوعی: ما در کنار دریا به انتظار نشسته‌ایم، ای ساقی! فرصتی را دریاب که از لب تا به دهان، این همه فاصله وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1936412,2203,5,1,'فرصتی دان که ز لب تا به دهان این همه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936413,2203,4,0,'پنج روزی که در این مرحله مهلت داری','هوش مصنوعی: پنج روزی که در این موقعیت فرصت داری، خوب آرامش کن و لذت ببر؛ چرا که زمانی که بگذرد، دیگر این آرامش و فرصت را نخواهی داشت.',NULL);
INSERT INTO "verses" VALUES(1936414,2203,4,1,'خوش بیاسای زمانی که زمان این همه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936415,2204,2,1,'در کمان ناوَک مژگانِ تو، بی‌چیزی نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936416,2203,3,0,'دولت آن است که بی خونِ دل آید به کنار','هوش مصنوعی: خوشبختی واقعی زمانی به دست می‌آید که بدون درد و رنج به دست آید، وگرنه با تلاش و کوشش تنها نمی‌توان به بهشت رسید.',NULL);
INSERT INTO "verses" VALUES(1936417,2203,2,0,'مِنَّتِ سِدره و طوبی ز پیِ سایه مکش','برای بدست آوردن سایه، منت درخت سدر و طوبی را مکش.',NULL);
INSERT INTO "verses" VALUES(1936418,2203,2,1,'که چو خوش بنگری ای سروِ روان، این همه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936419,2203,1,0,'از دل و جان شرفِ صحبتِ جانان غرض است','هوش مصنوعی: در اینجا شاعر بیان می‌کند که هدف اصلی‌اش از عشق و صحبت با معشوق، عشق و محبت اوست. او می‌گوید که ارزش دل و جانش به این ارتباط وابسته است و اگر این رابطه نبود، دل و جان او اهمیت چندانی نداشت.',NULL);
INSERT INTO "verses" VALUES(1936420,2203,1,1,'غرض این است، وگرنه دل و جان این همه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936421,2203,0,0,'حاصلِ کارگه کون و مکان این همه نیست','هوش مصنوعی: نتیجه‌ی تلاش‌ها و دنیای مادی این همه نیست، باده بیاور که وسایل و امکانات این جهان به اندازه‌ی این همه نیست.',NULL);
INSERT INTO "verses" VALUES(1936422,2203,0,1,'باده پیش آر که اسبابِ جهان این همه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936423,2202,11,0,'غیر از این نکته که حافظ ز تو ناخشنود است','ای معشوق سراپای وجودت سرشار از هنر و خوبی است و تنها یک هنر باقی مانده است و آن رضایت و خشنودی حافظ است؛ به عبارت دیگر: همه وجودت پر از کمال حسن و دلبری است، جز اینکه با من ناسازگاری و سر مهر نداری.',NULL);
INSERT INTO "verses" VALUES(1936424,2202,11,1,'در سراپای وجودت هنری نیست که نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936425,2202,10,0,'از وجودم قَدَری نام و نشان هست که هست','از وجودم آن اندازه نام و نشان باقی مانده است که بتوان ادعا کرد هنوز هستم و زنده‌­ام، و گرنه در این جسم نحیف و زار همه نوع ضعف و ناتوانی وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1936426,2202,10,1,'ور نه از ضعف در آن جا اثری نیست که نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936427,2202,9,0,'آب چشمم که بر او مِنَّت خاکِ درِ توست','چشمم که از خاک درگاه تو بسی منت دارد و آن را سرمه‌­ی خود می‌­کند، در آرزوی رسیدن به تو بر در هر آستانی گریسته است و خاک درگاهی نیست که زیر بار منت اشک چشمم نباشد.',NULL);
INSERT INTO "verses" VALUES(1936428,2202,9,1,'زیرِ صد مِنَّتِ او خاکِ دری نیست که نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936429,2202,8,0,'شیر در بادیهٔ عشق تو روباه شود','ای معشوق، شیر که نماد شجاعت و بی­باکی است در بیابان عشق تو همچون روباه ترسو و رمنده می­‌شود؛ آه از این راه عشق تو که بیمناک است و هر گونه خطری در آن وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1936430,2202,8,1,'آه از این راه که در وی خطری نیست که نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936431,2203,3,1,'ور نه با سعی و عمل باغِ جَنان این همه نیست',NULL,NULL);
INSERT INTO "verses" VALUES(1936432,2193,3,1,'که کام‌بخشی او را بهانه بی‌سببی‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1936433,2224,3,1,'صبا را گو که بردارد زمانی بُرقِع از رویت',NULL,NULL);
INSERT INTO "verses" VALUES(1936434,2224,4,0,'و گر رسمِ فنا خواهی که از عالم براندازی','اگر می‌خواهی که فنا و زوال را از جهان محو کنی، زلف را بپراکن و پریشان کن تا از هر تار گیسویت، جان‌ها ببخشی.',NULL);
INSERT INTO "verses" VALUES(1936435,2248,5,0,'ز سِرِّ غیب، کس آگاه نیست؛ قصّه مخوان','درباره سرّ غیب و رازهای غیب حرف مزن و قصه مگو؛ کیست که می‌تواند ادعا کند که بدان راز، آگاه گشته است؟',NULL);
INSERT INTO "verses" VALUES(1936436,2248,5,1,'کدام مَحرمِ دل ره در این حرم دارد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936437,2248,4,0,'زر از بهایِ می اکنون چو گل دریغ مدار','اگر از پول و زر برای خریدن باده دریغ کنی، آدم دانا و عاقل تو را به‌صد عیب متهم می‌کند.',NULL);
INSERT INTO "verses" VALUES(1936438,2248,4,1,'که عقلِ کل به صدت عیب متّهم دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936439,2248,3,0,'رسید موسمِ آن کز طرب چو نرگسِ مست','فصل باده‌نوشی رسید؛ فصلی که می‌گساران با چشم‌های خمار‌، سکه‌هایشان را در پای قدح باده می‌نهند. (شش‌درهم دارد: یعنی هرکس حداقل را دارد و می‌تواند باده بخرد)',NULL);
INSERT INTO "verses" VALUES(1936440,2248,3,1,'نهد به پایِ قدح هر که شش درم دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936441,2248,2,0,'نه هر درخت تحمّل کند جفایِ خزان','هر درختی نمی‌تواند سختی پاییز را تحمل کند؛ بندهٔ بلند‌نظری و همّت سرو هستم که رهرو این مرام است.',NULL);
INSERT INTO "verses" VALUES(1936442,2248,2,1,'غلامِ همتِ سروم که این قدم دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936443,2248,1,0,'به خَطُّ و خالِ گدایان مده خزینهٔ دل','گنج دل را به گدایان حیله‌گر مسپار؛ آن‌را به زیبا و شاه‌منشی بده که قدرش را بداند.',NULL);
INSERT INTO "verses" VALUES(1936444,2248,1,1,'به دستِ شاهوَشی دِه که محترم دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936445,2248,0,0,'دلی که غیب‌نمای است و جامِ جم دارد','دلی که آیینه شاهی گشته‌است و خود جام جم گشته، اگر زمانی خاتم شاهی از او گم شود؛ چه کم دارد و چه غم دارد؟',NULL);
INSERT INTO "verses" VALUES(1936446,2248,0,1,'ز خاتمی که دمی گم شود، چه غم دارد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936447,2247,8,0,'در چاهِ ذَقَن چو حافظ ای جان','زیبایی تو در یک قلم و فقط دویست غلام و چاکر همچون حافظ کشته‌مرده زیبایی چاه چانه دارد.',NULL);
INSERT INTO "verses" VALUES(1936448,2247,8,1,'حُسنِ تو دو صد غلام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936449,2247,7,0,'بر سینهٔ ریشِ دردمندان','آن لب‌های سرخ تو هر دم دل عاشقان و دردمندان را بیشتر می‌سوزاند.',NULL);
INSERT INTO "verses" VALUES(1936450,2247,7,1,'لعلت نمکی تمام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936451,2247,6,0,'ذکرِ رخ و زلف تو دلم را','وصف رخ زیبا و موی سیاه تو ورد زبان دل من است و دلم هر سپیده‌دم و شامگاه به یاد توست.',NULL);
INSERT INTO "verses" VALUES(1936452,2247,6,1,'وردی‌ست که صبح و شام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936453,2247,5,0,'نرگس، همه شیوه‌های مستی','گل نرگس و چشم‌های مست همگی یک گوشه و کرشمه از چشم‌های زیبای تو را به قرض گرفته‌اند.',NULL);
INSERT INTO "verses" VALUES(1936454,2247,5,1,'از چشمِ خوشت به وام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936455,2247,4,0,'بیرون ز لبِ تو ساقیا نیست','هر کس که مست است و خوش و شاد گشته است بجز از مستی و کرامت لب‌های تو نیست ای ساقی.',NULL);
INSERT INTO "verses" VALUES(1936456,2247,4,1,'در دور، کسی که کام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936457,2247,3,0,'ما و مِی و زاهدان و تقوا','قسمت ما می و باده شده است و قسمت زاهدها‌، تقوا و پرهیزگاری تا میل و انتخاب یار کدام باشد.',NULL);
INSERT INTO "verses" VALUES(1936458,2247,3,1,'تا یار، سرِ کدام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936459,2247,2,0,'سررشتهٔ جان به جام بگذار','کار و سر رشته جان را به می و باده بگذار زیرا جان بر مستی قوام یافته و از او آفریده شده است.',NULL);
INSERT INTO "verses" VALUES(1936460,2247,2,1,'کاین رشته از او نظام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936461,2247,1,0,'آبی که خِضِر حیات از او یافت','آن آب حیات که خضر از او زندگی جاودانه یافت را در می‌کده جستجو کن و آنرا از پیاله شراب بخواه.',NULL);
INSERT INTO "verses" VALUES(1936462,2247,1,1,'در میکده جو‌ که جام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936463,2247,0,0,'آن کس که به دست جام دارد','هر کس که مست است و باده می‌نوشد‌، سلطانی و شاهی جمشید را همیشگی دارد.',NULL);
INSERT INTO "verses" VALUES(1936464,2248,6,0,'دلم که لافِ تَجَرُّد زدی، کنون صد شغل','من که هزار لاف از «تجرّد» می‌زدم از وقتی که عطر زلف تو را شنیده‌ام، صد دلبستگی پیدا کرده‌ام. (تجرّد و شغل از اصطلاحات صوفیانه است)',NULL);
INSERT INTO "verses" VALUES(1936465,2247,0,1,'سلطانیِ جَم مُدام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936466,2248,6,1,'به بویِ زلفِ تو با بادِ صبحدم دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936467,2248,7,0,'مرادِ دل ز که پرسم؟ که نیست دلداری','از چه‌کسی آرزو و مراد دلم را بخواهم؟ زیرا دلدار و محرمی نیست که فهیم و آگاه باشد و سخاوتمند.',NULL);
INSERT INTO "verses" VALUES(1936468,2250,1,0,'حَریمِ عشق را دَرْگَه، بسی بالاتر از عَقْل است','هوش مصنوعی: حریم عشق بسیار بالاتر از عقل و درک انسان است؛ تنها کسی می‌تواند به آن درگاه نزدیک شود که روحش را در دست داشته باشد و از عشق واقعی برخوردار باشد.',NULL);
INSERT INTO "verses" VALUES(1936469,2250,0,0,'هر آن کاو خاطِرِ مَجموع و یارِ نازنین دارد','هوش مصنوعی: هر کسی که دلش در پی عشق و محبوب واقعی باشد، سعادت و خوشبختی همراه اوست و ثروت و نعمت در کنار او خواهند بود.',NULL);
INSERT INTO "verses" VALUES(1936470,2250,0,1,'سَعادَت، همدم او گشت و دولت، هم‌نشین دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936471,2249,11,1,'به تلخی کُشت حافظ را و شِکَّر در دهان دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936472,2249,10,1,'که از چشمِ بداندیشان خدایت در امان دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936473,2249,11,0,'چه عذرِ بختِ خود گویم؟ که آن عیّار شهرآشوب','راهنما_ اِریس : از بخت بد خودم چی بگم که ان دزد راهزن که دل رو بهم می ریزه ، ،باز این بار حافظ رو جذب خودش نکرد و حتی برای یک لحظه هم جذبش نشدم تا بوسه به بر آن لب شکر بزنم و یک لحظه شیرینی جاناها رو بچشم',NULL);
INSERT INTO "verses" VALUES(1936474,2249,9,1,'بدین سرچشمه‌اش بِنْشان که خوش آبی روان دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936475,2249,10,0,'ز خوفِ هجرم ایمن کن اگر امّیدِ آن داری','راهنما_ اِریس : از ترس اینکه تو ناپدید بشی و یا جذب تو نشم ، من رو ایمن کن و بهم اطمینان بده که این کارها رو نمی کنی تا از چشم اونهائی کها به رویت تو در دل و جذب شدن به تو شک دارند و ایمان ندارند ، حفظ بشی',NULL);
INSERT INTO "verses" VALUES(1936476,2249,8,1,'که آفت‌هاست در تأخیر و طالب را زیان دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936477,2249,9,0,'ز سروِ قَدِّ دلجویت مکن محروم چشمم را','راهنما_ اِریس : مرا از قد و بالای خودت که همچو سروی مقاوم و پایدار هست محروم نکن و آنچنان همچو سرو ، پایدار و مقاوم شو که من نتونم از جلوی تو تکون بخورم و در آخر من رو جذب خودت کن تا واردِ رودِ جانا بشم',NULL);
INSERT INTO "verses" VALUES(1936478,2249,7,1,'که می با دیگری خورده‌ست و با من سر گِران دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936479,2249,8,0,'به فِتراک ار همی‌بندی خدا را زود صیدم کن','راهنما_ اِریس : حتی شده اگر به بند طناب ببندی و من رو با درد و رنج دنبال خودت رو زمین بکشی ، باز من راضیم . چون اگر در جریان مشاهده گری و جذب شدن ، سالک به موقع جذب نشه آفاتی همچو خواب آلودگی و خستگی و بی رمقی و بی حوصلگی به سراغش میاد .',NULL);
INSERT INTO "verses" VALUES(1936480,2249,6,1,'که بر گُل اعتمادی نیست، گر حُسنِ جهان دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936481,2249,7,0,'خدا را، دادِ من بِسْتان از او ای شِحنهٔ مجلس','ای حاکم و مدیر مجلس به خاطر خدا داد من را از او بگیر زیرا شادی و می خوردنش را با دیگری انجام داده و سرسنگینی و خماریش را برای من آورده است.',NULL);
INSERT INTO "verses" VALUES(1936482,2249,5,1,'که از جمشید و کیخسرو، فراوان داستان دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936483,2249,6,0,'چو در رویت بخندد گُل، مشو در دامَش ای بلبل','زمانی که گل به روی تو می‌خندد و روی خوش نشان می دهد در دام زیبایی فریبنده آن نیفت زیرا اگر تمام زیبایی های جهان را هم داشته باشد نمی توان به آن اعتماد کرد چون هم این زیبایی ظاهری است و هم ناپایدار',NULL);
INSERT INTO "verses" VALUES(1936484,2249,4,1,'به غَمّازِ صبا گوید که راِزِ ما نهان دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936485,2249,5,0,'بیفشان جرعه‌ای بر خاک و حالِ اهلِ دل بشنو','هنگام نوشیدن شراب جرعه ای از آن را بر خاک به یاد اهل دل بریز و بی خودی خود را با خاک شریک شو زیرا این خاک داستان های فراوانی از سرگذشت صاحبان قدرت همانند جمشید و کیخسرو را داراست ( یعنی دنیا بی اعتبار است و خاک بهترین گواه این مدعا)',NULL);
INSERT INTO "verses" VALUES(1936486,2249,3,1,'کمین از گوشه‌ای کرده‌ست و تیر اندر کمان دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936487,2249,4,0,'چو دامِ طُرِّه افشاند ز گَردِ خاطرِ عشاق','زلف معشوق همانند دام و فکر و آنچه در دل عشاق می گذرد مثل گَردیست که در پیچ و خم زلف او گرفتار می شود و زمانی که موی خود را می افشاند این گرد پراکنده می شود به باد صبا که خبررسان است بگویید گَردِ رازِ عشق ما را پنهان کند و آن را فاش نکند.',NULL);
INSERT INTO "verses" VALUES(1936488,2249,2,1,'ندانستم که این دریا چه موجِ خون‌فشان دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936489,2249,3,0,'ز چشمت جان نشاید بُرد کز هر سو که می‌بینم','از گزند نگاه کشنده و افسونگر تو نمی توان جان سالم به در برد زیرا به هر طرف که نگاه میکنم میبینم که در گوشه ای کمین کرده و آماده ی پرتاب تیر نگاه از کمان ابروان است .',NULL);
INSERT INTO "verses" VALUES(1936490,2249,1,1,'بقایِ جاودانش ده، که حُسنِ جاودان دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936491,2249,2,0,'چو عاشق می‌شدم گفتم که بُردم گوهرِ مقصود','آن زمان که تازه پا به عرصه عاشقی میگذاشتم پنداشتم که گوهر مقصود ( وصال یا معشوق ) را به دست آورده ام( اطمینان کاذب ) اما دریای عشق در ظاهر آرام است اما باطنی طوفانی با موج هایی خون افشان ( رنج ها و بلایای راه عشق ) دارد ( که عشق آسان نمود اول ولی افتاد مشکل ها )',NULL);
INSERT INTO "verses" VALUES(1936492,2249,0,1,'بهارِ عارضش خطّی به خونِ ارغوان دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936493,2249,1,0,'غبارِ خط بپوشانید خورشیدِ رُخَش یا رب','این چهره درخشان آنچنان تابان و روشن است که آن خط ارغوانی ظریف ( که در بیت قبل از جلوه گر بودن آن گفته شده ) همانند غباری است که توانایی پوشاندن درخشندگی آن خورشید را ندارد و از خداوند می خواهد که به خاطر این زیبایی که لیاقت جاودانگی دارد به او عمر همیشگی دهد.',NULL);
INSERT INTO "verses" VALUES(1936494,2249,0,0,'بتی دارم که گِرد گل ز سُنبل سایه‌بان دارد','دلبر زیبارویی دارم که موهای مجعد و انبوهش همانند سنبل اطراف صورت همانند گل او را مثل سایه بانی احاطه کرده اند و چهره ی او که نوبهار است ( اشاره به نوجوان بودن ) یک خط نازک به رنگ ارغوانی ( قرمز تیره و بسیار جذاب) را داراست و یا بهار عارضش فرمانی برای ریختن خون شکوفه ارغوان دارد( صنعت ایهام : خط:خط سبزه و یا دست نوشته و فرمان همچنین مشخص است که معشوق نیز نوجوانی مذکر می باشد)',NULL);
INSERT INTO "verses" VALUES(1936495,2248,8,0,'ز جَیبِ خرقهٔ حافظ چه طَرف بِتوان بست','از حافظ چه سود می‌رسد؟ زیرا ما خدا طلبیدیم و او بتی زیبارو دارد!',NULL);
INSERT INTO "verses" VALUES(1936496,2248,8,1,'که ما صمد طلبیدیم و او صَنم دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936497,2248,7,1,'که جلوهٔ نظر و شیوهٔ کرم دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936498,2246,7,0,'سرِ درسِ عشق دارد دلِ دردمند حافظ','دل دردمند حافظ قصد و هوس آموختن درس عشق دارد و هوس گشت و گذار و رفتن به باغ را ندارد.',NULL);
INSERT INTO "verses" VALUES(1936499,2246,7,1,'که نه خاطرِ تماشا نه هوای باغ دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936500,2246,6,0,'سِزَدم چو ابرِ بهمن که بر این چمن بِگریَم','جای دارد که همچون ابر بهمنی فراوان بگریم زیرا در چمن‌، بجای بلبل خوش‌خوان‌، زاغ آشیانه کرده است.',NULL);
INSERT INTO "verses" VALUES(1936501,2244,4,0,'بهارِ عمر خواه ای دل! و گر نه این چمن هر سال','هوش مصنوعی: بهار زندگی را انسان باید غنیمت بشمارد، زیرا این باغ هر سال به زیبایی گل‌ها و پرندگان، روزهای شاداب و سرزنده‌ای به همراه می‌آورد.',NULL);
INSERT INTO "verses" VALUES(1936502,2244,3,0,'عَماری‌دارِ لیلی را که مَهدِ ماه در حکم است','خدایا در دل کجاوه دار یا ساروان لیلی که کجاوه اش مانند مهد ماه است بنداز که کجاوه را به سمت مجنون ببرد و سری به او بزند',NULL);
INSERT INTO "verses" VALUES(1936503,2244,3,1,'خدا را در دل اندازش که بر مجنون گذار آرد',NULL,NULL);
INSERT INTO "verses" VALUES(1936504,2244,2,0,'شبِ صحبت غنیمت دان که بعد از روزگارِ ما','هوش مصنوعی: شبِ گفتگو را فرصتی ارزشمند بشمار، زیرا پس از زمان ما، روزگار به شدت تغییر خواهد کرد و بسیاری از شب‌ها و روزها خواهد آمد.',NULL);
INSERT INTO "verses" VALUES(1936505,2244,2,1,'بسی گردش کُنَد گردون، بسی لیل و نهار آرد',NULL,NULL);
INSERT INTO "verses" VALUES(1936506,2244,1,0,'چو مهمانِ خراباتی به عزت باش با رندان','هنگامی که به میکده می روی با رندان که از بزرگان آنجا هستند با احترام برخورد کن که سر کشی کردن در مقابل آنها و دعوا با آنها باعث می شود اگر اکنون سرخوش و مست هستی ، مستی از سر تو می‌پرد و خمار بشوی',NULL);
INSERT INTO "verses" VALUES(1936507,2244,1,1,'که دردِ سر کشی جانا! گرت مستی خمار آرد',NULL,NULL);
INSERT INTO "verses" VALUES(1936508,2244,0,0,'درختِ دوستی بنشان که کامِ دل به بار آرد','هوش مصنوعی: دوستی و محبت را در زندگی خود ریشه‌دار کن تا شادی و خوشبختی به ارمغان آورد. اما دشمنی و کینه را از خود دور کن، زیرا تنها درد و رنج به همراه خواهد داشت.',NULL);
INSERT INTO "verses" VALUES(1936509,2244,0,1,'نهالِ دشمنی بَرکَن که رنج بی‌شمار آرد',NULL,NULL);
INSERT INTO "verses" VALUES(1936510,2243,7,0,'ز خاکِ کوی تو هر گَه که دَم زند حافظ','بیت شماره 3: [شبی که ماه مراد از افق بخت سر بزنذ]، شاید پرتو نوری بر بام ما بیافتد.',NULL);
INSERT INTO "verses" VALUES(1936511,2243,7,1,'نسیمِ گلشن جان در مشامِ ما افتد',NULL,NULL);
INSERT INTO "verses" VALUES(1936512,2243,6,0,'به ناامیدی از این در مرو، بزن فالی','هوش مصنوعی: از ناامیدی فاصله بگیر و به تلاش ادامه بده، چون ممکن است که شانست به تو روی آورد و به آرزوهایت برسی.',NULL);
INSERT INTO "verses" VALUES(1936513,2243,6,1,'بُوَد که قرعهٔ دولت به نامِ ما افتد',NULL,NULL);
INSERT INTO "verses" VALUES(1936514,2243,5,0,'خیالِ زلفِ تو گفتا که جان وسیله مساز','هوش مصنوعی: خیال زلف‌های تو می‌گوید که جان خود را قربانی نکن، زیرا از این شکار، بسیاری به دام ما خواهند افتاد.',NULL);
INSERT INTO "verses" VALUES(1936515,2243,5,1,'کز این شکار، فراوان به دامِ ما افتد',NULL,NULL);
INSERT INTO "verses" VALUES(1936516,2243,4,0,'چو جان فدای لبش شد خیال می‌بستم','هوش مصنوعی: وقتی که جانم را فدای لبانش کردم، در خیال خود می‌پروراندم که شاید قطره‌ای از آب زلال او به کام ما برسد.',NULL);
INSERT INTO "verses" VALUES(1936517,2243,4,1,'که قطره‌ای ز زلالش به کامِ ما افتد',NULL,NULL);
INSERT INTO "verses" VALUES(1936518,2243,3,0,'به بارگاهِ تو چون باد را نباشد بار','در حالی که حتی باد اجازه‌ی ورود به جایگاه بالای تو را ندارد، من( من ضعیف) چه جوری میتونم برای عرض سلام خدمت برسم.',NULL);
INSERT INTO "verses" VALUES(1936519,2243,3,1,'کی اتفاقِ مجالِ سلامِ ما افتد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936520,2243,2,0,'شبی که ماهِ مراد از افق شود طالع','هوش مصنوعی: در شبی که ماه مورد نظر از افق ظهور می‌کند، نورش به سقف خانه‌ی ما می‌تابد.',NULL);
INSERT INTO "verses" VALUES(1936521,2243,2,1,'بُوَد که پرتوِ نوری به بامِ ما افتد',NULL,NULL);
INSERT INTO "verses" VALUES(1936522,2243,1,0,'حباب‌وار براندازم از نشاط کلاه','از خوشحالی کلاه خود را به هوا می اندازم، اگر تصویری از چهره تو بر روی جام ما بیفتد.',NULL);
INSERT INTO "verses" VALUES(1936523,2243,1,1,'اگر ز رویِ تو عکسی به جامِ ما افتد',NULL,NULL);
INSERT INTO "verses" VALUES(1936524,2243,0,0,'همایِ اوجِ سعادت به دامِ ما افتد','هوش مصنوعی: اگر تو نگاهی به جایگاه ما بیندازی، ممکن است شانس بزرگی در زندگی ما رخ دهد و به اوج سعادت دست یابیم.',NULL);
INSERT INTO "verses" VALUES(1936525,2243,0,1,'اگر تو را گذری بر مقام ما افتد',NULL,NULL);
INSERT INTO "verses" VALUES(1936526,2242,5,0,'گذشت بر منِ مسکین و با رقیبان گفت','هوش مصنوعی: زمانی که من در رنج بودم و از رقبای خود می‌شنیدم که به من حسرت می‌خورند، متوجه شدم که حافظ، یعنی منِ فقیر، چه جان باختگی را تجربه کرده است.',NULL);
INSERT INTO "verses" VALUES(1936527,2242,5,1,'دریغ، حافظِ مسکینِ من، چه جانی داد',NULL,NULL);
INSERT INTO "verses" VALUES(1936528,2242,4,0,'برو معالجهٔ خود کن ای نصیحت‌گو','هوش مصنوعی: به دنبال درمان خود برو ای کسی که نصیحت می‌کنی، چرا که نوشیدنی و معشوقه‌های لذت‌بخش به کسی آسیب نزده‌اند؟',NULL);
INSERT INTO "verses" VALUES(1936529,2242,4,1,'شراب و شاهدِ شیرین، که را زیانی داد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936530,2244,4,1,'چو نسرین صد گل آرد بار و چون بلبل هِزار آرد',NULL,NULL);
INSERT INTO "verses" VALUES(1936531,2244,5,0,'خدا را چون دلِ ریشم قراری بست با زلفت','هوش مصنوعی: به خدا سوگند که دل شکسته‌ام آرام و قرار ندارد. با زلف‌های تو بگو تا لعل نوشین را به زودی آرامش ببخشد.',NULL);
INSERT INTO "verses" VALUES(1936532,2244,5,1,'بفرما لعلِ نوشین را که زودش با قرار آرد',NULL,NULL);
INSERT INTO "verses" VALUES(1936533,2244,6,0,'در این باغ از خدا خواهد دگر پیرانه‌سر، حافظ','هوش مصنوعی: در این باغ، خداوند می‌خواهد که حافظ با سن و سالی بالا بر لب جویی نشسته و در کنار او درخت سروی قرار بگیرد.',NULL);
INSERT INTO "verses" VALUES(1936534,2246,6,1,'طرب آشیانِ بلبل، بنگر که زاغ دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936535,2246,5,0,'من و شمعِ صبح‌گاهی سِزَد ار به هم بِگرییم','من و شمع سوخته صبح‌، شایسته است که برای همدیگر بگرییم و بر درد هم بسوزیم زیرا تمام شب را سوختیم و یار به ما توجهی نکرد. (در اینجا شمع‌، تصویری از شمع‌هایی که در پای بت‌ها می‌سوزند را نیز منعکس می‌کند)',NULL);
INSERT INTO "verses" VALUES(1936536,2246,5,1,'که بسوختیم و از ما بتِ ما فراغ دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936537,2246,4,0,'شبِ ظلمت و بیابان، به کجا توان رسیدن؟','این راه‌، همچون بیابان‌، بی‌انتهاست و همچون شب‌، تاریک‌؛ تنها شمع روی و چهره زیبای تو می‌تواند راه را برایم روشن کند و راه را به من بنماید.',NULL);
INSERT INTO "verses" VALUES(1936538,2246,4,1,'مگر آن که شمعِ روی‌ات به رَهَم چراغ دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936539,2246,3,0,'به چمن خرام و بنگر برِ تختِ گل که لاله','به طرف چمن و گلزار رو و در آنجا ببین که لاله همچون خدمتکار شاه‌‌، جام در دست گرفته است. (ایاغ یعنی جام و پیاله شراب‌خواری)',NULL);
INSERT INTO "verses" VALUES(1936540,2246,3,1,'به ندیمِ شاه مانَد که به کف ایاغ دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936541,2246,2,0,'ز بنفشه تاب دارم که ز زلفِ او زند دم','از دست بنفشه خشمگین هستم که زیبایی زلف خود را با زیبایی زلف تو مقایسه می‌کند‌، این سیاه‌روی گستاخ چه ادعاهایی دارد!؟ (تاب دارم‌: بر‌آشفته هستم)',NULL);
INSERT INTO "verses" VALUES(1936542,2246,2,1,'تو سیاهِ کم‌بها بین، که چه در دِماغ دارد‌!',NULL,NULL);
INSERT INTO "verses" VALUES(1936543,2246,1,0,'سرِ ما فرونیآید به کمانِ ابروی کَس','به زیبایی گوشه و اشاره ابروی کمان‌ابرویان توجه نمی‌کنیم تا در میان گوشه‌گیران و افتادگان تو، از جهان و کار جهان فارغ شده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1936544,2246,1,1,'که درون گوشه‌گیران، ز جهان فَراغ دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936545,2246,0,0,'دل ما به دور رویت ز چمن فَراغ دارد','تا دل ما به تو مشغول است هوای چمن و گلزار نمی‌کند زیرا همچون سرو که پای‌بسته است پایبند عشق تو است و همچون لاله که داغدار است هواخواه توست.',NULL);
INSERT INTO "verses" VALUES(1936546,2246,0,1,'که چو سرو پایبند است و چو لاله داغ دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936547,2245,7,0,'دل‌ِ شکستهٔ حافظ به خاک خواهد برد','حافظ‌، دل‌‌ِ شکسته و داغدارش را به خاک خواهد بُرد همچون لاله که بر دلش داغ هوا و آرزویی مانده است.',NULL);
INSERT INTO "verses" VALUES(1936548,2250,1,1,'کسی آن آسْتان بوسد، که جان در آستین دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936549,2245,7,1,'چو لاله، داغ هوایی‌، که بر جگر دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936550,2245,6,0,'کسی که از رهِ تقوا قدم برون ننهاد','کسی که همواره به تقوا و پرهیز‌گاری معروف بوده، اکنون قصد رفتن به میکده دارد.',NULL);
INSERT INTO "verses" VALUES(1936551,2245,5,0,'ز باده هیچت اگر نیست، این نه بس که تو را','هوش مصنوعی: اگر از شراب چیزی نصیبت نیست، آیا این کافی نیست که تو را مدتی از وسوسه‌های عقل دور نگه می‌دارد؟',NULL);
INSERT INTO "verses" VALUES(1936552,2245,5,1,'دمی ز وسوسهٔ عقل بی‌خبر دارد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936553,2245,4,0,'ز زهدِ خشک ملولم‌، کجاست بادهٔ ناب‌؟','هوش مصنوعی: از زهاد و عبادت‌های بی‌روح خسته‌ام، کاش باده‌ی ناب پیدا شود! چون بوی باده همیشه در بینی‌ام حس می‌شود.',NULL);
INSERT INTO "verses" VALUES(1936554,2245,4,1,'که بویِ باده مدامم دماغ تر دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936555,2245,3,0,'به پای‌بوس تو دستِ کسی رسید که او','کسی به حضور و به پای‌بوس تو می‌رسد که همچون آستانهٔ در‌، سر خود را در قدم تو بنهد. (آستانه ، در اینجا یعنی قسمت پایین چارچوب در )',NULL);
INSERT INTO "verses" VALUES(1936556,2245,3,1,'چو آستانه بدین در، همیشه سر دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936557,2245,2,0,'کسی به وصلِ تو چون شمع یافت پروانه','هوش مصنوعی: کسی که به وصالت همچون شمع نزدیک شده، مانند پروانه‌ای است که همیشه زیر تیغ توست و هر بار به شکلی جدید در خطر است.',NULL);
INSERT INTO "verses" VALUES(1936558,2245,2,1,'که زیرِ تیغِ تو هر دم سری دگر دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936559,2245,1,0,'چو خامه در رهِ فرمانِ او، سرِ طاعت','هوش مصنوعی: مانند قلمی که به فرمان او سرِ اطاعت فرود آورده‌ایم، امید داریم که او ما را با تیغ به چالش نکشد.',NULL);
INSERT INTO "verses" VALUES(1936560,2245,1,1,'نهاده‌ایم مگر او به تیغ بردارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936561,2245,0,0,'کسی که حُسن و خَطِ دوست در نظر دارد','هوش مصنوعی: کسی که زیبایی و طرز نوشتار دوست را می‌بیند، به واقع کسی است که درک و بینش صحیحی دارد.',NULL);
INSERT INTO "verses" VALUES(1936562,2245,0,1,'محقَق است که او حاصل بصر دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936563,2244,6,1,'نشیند بر لبِ جویی و سروی در کنار آرد',NULL,NULL);
INSERT INTO "verses" VALUES(1936564,2245,6,1,'به عزمِ میکده اکنون رهِ سفر دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936565,2250,2,0,'دهانِ تَنْگِ شیرینش، مگر مُلْکِ سلیمان است','هوش مصنوعی: دهان باریک و خوشگوار او، آیا به راستی مانند سرزمین سلیمان است که نشانه‌ی زیبا و درخشانش، دنیا را زیر سلطه و کنترل خود دارد؟',NULL);
INSERT INTO "verses" VALUES(1936566,2250,2,1,'که نَقْشِ خاتَمِ لَعْلَش، جهان، زیرِ نگین دارد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936567,2250,3,0,'لَبِ لَعْل و خَطِ مُشکین، چو آنش هست و اینش هست','هوش مصنوعی: لب‌های زیبایش به رنگ لعل و خطش به سیاهی مشک است. وجودش مانند آتش دل‌انگیز و دیگری جذاب است. من به معشوق خود می‌بالم که زیبایی‌اش هم این خصوصیات را دارد و هم آن‌ها را.',NULL);
INSERT INTO "verses" VALUES(1936568,2255,6,0,'احوالِ گنجِ قارون کَایّام داد بر باد','هوش مصنوعی: وضعیت ثروت و دارایی قارون، که روزگاری در اوج بود، اکنون به باد رفته است. این را برای دل خود به خاطر بسپار تا هیچ ثروتی در دل پنهان نکنم.',NULL);
INSERT INTO "verses" VALUES(1936569,2255,5,0,'ای دل طریقِ رندی از محتسب بیاموز','ای دل، زیرکی و رندی را از محتسب یاد بگیر که مست است اما هیچ کس در این مورد به او شک نمی‌کند.',NULL);
INSERT INTO "verses" VALUES(1936570,2255,5,1,'مست است و در حقِ او کس این گمان ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936571,2255,4,0,'چنگِ خمیده‌قامت می‌خوانَدَت به عشرت','هوش مصنوعی: آواز ساز خمیده تو را به خوشی دعوت می‌کند، پس به نصیحت‌های پیران گوش کن که هیچ ضرری برایت ندارد.',NULL);
INSERT INTO "verses" VALUES(1936572,2255,4,1,'بشنو که پندِ پیران هیچت زیان ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936573,2255,3,0,'سرمنزلِ فراغت نَتْوان ز دست دادن','هوش مصنوعی: ای راهنما، کاری نکن که موقعیت آرامش و راحتی را از دست بدهیم، چون این مسیر پایان و حدی ندارد و ادامه خواهد داشت.',NULL);
INSERT INTO "verses" VALUES(1936574,2255,3,1,'ای ساروان فروکش کاین ره کران ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936575,2255,2,0,'هر شبنمی در این ره صد بحرِ آتشین است','هوش مصنوعی: هر قطره‌ی شبنم در این مسیر، مانند دریایی از آتش و احساسات عمیق و سوزان است. افسوس که این راز و معما قابل توضیح و فهم نیست.',NULL);
INSERT INTO "verses" VALUES(1936576,2255,2,1,'دردا که این معما شرح و بیان ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936577,2255,1,0,'با هیچ کس نشانی زان دِلْسِتان ندیدم','هوش مصنوعی: من با هیچ‌کس نشانی از آن دلبر نداشته‌ام، یا من خبر ندارم یا او نشانه‌ای از خود ندارد.',NULL);
INSERT INTO "verses" VALUES(1936578,2255,1,1,'یا من خبر ندارم یا او نشان ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936579,2255,0,0,'جان، بی‌جمالِ جانان میلِ جهان ندارد','هوش مصنوعی: زندگی بدون زیبایی محبوب، هیچ جذابیتی برای کسی ندارد. هر کسی که این زیبایی را ندارد، واقعاً هیچ چیزی برای زندگی ندارد.',NULL);
INSERT INTO "verses" VALUES(1936580,2255,0,1,'هر کس که این ندارد حقّا که آن ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936581,2254,9,0,'مدعی گو لُغَز و نکته به حافظ مفروش','هوش مصنوعی: مدعی نگوید که حافظ تنها به زبانی خاص محدود است، چرا که قلم ما هم می‌تواند نکته‌ها و فنون ویژه‌ای را به تصویر بکشد.',NULL);
INSERT INTO "verses" VALUES(1936582,2254,9,1,'کِلکِ ما نیز زبانی و بیانی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936583,2254,8,0,'مرغِ زیرک نزند در چمنش پرده سرای','هوش مصنوعی: پرنده‌ی هوشمند در باغش کسی را نمی‌پذیرد، چرا که هر فصل زیبایی که می‌آید، پایانی تلخ به دنبال دارد.',NULL);
INSERT INTO "verses" VALUES(1936584,2254,8,1,'هر بهاری که به دنباله، خزانی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936585,2254,7,0,'با خرابات نشینان ز کَرامات مَلاف','هوش مصنوعی: در کنار کسانی که در میکده زندگی می‌کنند، هر حرف و نکته‌ای زمان و مکان خاصی دارد و نشانه‌ای از بزرگی و کرامت آن‌هاست.',NULL);
INSERT INTO "verses" VALUES(1936586,2254,7,1,'هر سخن وقتی و هر نکته مکانی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936587,2254,6,0,'در رَهِ عشق نشد کَس به یقین محرمِ راز','هوش مصنوعی: در مسیر عشق، هیچ‌کس به‌طور قطع به رازهای درونی دیگری دسترسی ندارد و هر فرد بر اساس افکار خودش، دربارهٔ دیگران نظر و گمانی دارد.',NULL);
INSERT INTO "verses" VALUES(1936588,2254,6,1,'هر کسی بر حَسَبِ فکر، گُمانی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936589,2254,5,0,'خَمِ ابرویِ تو در صنعتِ تیراندازی','هوش مصنوعی: زیر پلک و ابروی تو، زیبایی‌ای وجود دارد که باعث می‌شود حتی ماهرترین تیراندازان هم در تیرکشی خود شکست بخورند.',NULL);
INSERT INTO "verses" VALUES(1936590,2254,5,1,'بُرده از دستِ هر آن کس که کمانی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936591,2254,4,0,'دل نشان شد سخنم تا تو قبولش کردی','هوش مصنوعی: دل من به وضوح نشان داد که با جمله‌هایم تو را قانع کرده است. آری، سخن عشق نشانه‌ای دارد که آن را می‌توان به راحتی فهمید.',NULL);
INSERT INTO "verses" VALUES(1936592,2254,4,1,'آری آری سخنِ عشق نشانی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936593,2254,3,0,'گوی خوبی که بَرَد از تو؟ که خورشید آن جا','هوش مصنوعی: کسی که از تو خوب بگوید، چه کسی است؟ در آنجا که خورشید هم سوارکاری ندارد که افسار را در دست بگیرد.',NULL);
INSERT INTO "verses" VALUES(1936594,2254,3,1,'نه سواریست که در دست عِنانی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936595,2254,2,0,'چشمهٔ چشمِ مرا ای گلِ خندان دریاب','هوش مصنوعی: ای گل خندان، به من توجه کن و اشک‌های من را ببین، زیرا این اشک‌ها به خاطر امیدی است که به دیدار تو دارم و مانند جویبارِ زلالی است که به خاطر تو جریان دارد.',NULL);
INSERT INTO "verses" VALUES(1936596,2254,2,1,'که به امّیدِ تو خوش آبِ روانی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936597,2255,6,1,'در گوشِ دل فروخوان تا زر نهان ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936598,2255,7,0,'گر خود رقیب شمع است اسرار از او بپوشان','اگر‌ محافظِ تو ادعای عاشقی و دلبستگی به تو می کند، تو اسرار عشق و عاشقی ات را به او نگو، زیرا او رازهای تو را فاش میکند و به همه می گوید.',NULL);
INSERT INTO "verses" VALUES(1936599,2255,7,1,'کان شوخِ سربریده بندِ زبان ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936600,2255,8,0,'کس در جهان ندارد یک بنده همچو حافظ','هوش مصنوعی: هیچ کس در دنیا بنده‌ای مثل حافظ ندارد، چرا که تو شاهی و هیچ کس در جهان مثل تو نیست.',NULL);
INSERT INTO "verses" VALUES(1936601,2257,4,0,'در خیال، این هَمه لُعبَت به هَوَس می‌بازَم','در خیال خود و در شعر خود این همه لعبت زیبا به آرزو و هوس می‌آفرینم شاید صاحب‌نظری بیاید و این لعبت‌بازی را تماشا کند و بپسندد.',NULL);
INSERT INTO "verses" VALUES(1936602,2257,3,0,'رَهزنِ دَهر نَخفته‌ست، مَشو ایمن از او','راهزن روزگار هرگز خواب نیست، پس از او احساس امنیت نکن! اگر امروز تو را نبرده است، مطمئن باش که فردا خواهد برد.',NULL);
INSERT INTO "verses" VALUES(1936603,2257,3,1,'اگر امروز نَبُرده‌ست که فردا بِبَرَد',NULL,NULL);
INSERT INTO "verses" VALUES(1936604,2257,2,0,'باغبانا زِ خَزان، بی‌خَبَرَت می‌بینم','ای باغبان و صاحب باغ‌، تو را (مغرور‌) و بی‌خبر از قضا و تقدیر خزان می‌بینم‌، وای بر روزی که گل‌های رعنا و دلکش تو را باد پاییزی ببرد.',NULL);
INSERT INTO "verses" VALUES(1936605,2257,2,1,'آه از آن روز که بادَت گُلِ رَعنا بِبَرَد',NULL,NULL);
INSERT INTO "verses" VALUES(1936606,2257,1,0,'کو حریفی کَشِ سَرمَست که پیشِ کَرَمَش','کو یاری که او چنان سر‌مست و با کرم و بخشش باشد که یک عاشق سوخته‌دل (مهجور) از او درخواست و تمنایی (وصال) داشته باشد؟',NULL);
INSERT INTO "verses" VALUES(1936607,2257,1,1,'عاشقِ سوخته‌دل، نامِ تَمَنا بِبَرَد',NULL,NULL);
INSERT INTO "verses" VALUES(1936608,2257,0,0,'نیست دَر شهر نگاری که دلِ ما بِبَرَد','در این شهر زیبارویی نیست که دل ما را ببرد ، بخت اگر کمکم کند، من را از اینجا ببرد ( شاید در حالی دیگر چنین یاری پیدا کردم)',NULL);
INSERT INTO "verses" VALUES(1936609,2257,0,1,'بختم اَر یار شَوَد رَختَم از این جا بِبَرَد',NULL,NULL);
INSERT INTO "verses" VALUES(1936610,2256,9,0,'حافظ اگر سجدهٔ تو کرد مکن عیب','هوش مصنوعی: اگر حافظ برای تو سجده کند، به عشقش ایرادی نگیر، ای معشوق، زیرا او گناهی ندارد.',NULL);
INSERT INTO "verses" VALUES(1936611,2256,9,1,'کافرِ عشق ای صنم گناه ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936612,2256,8,0,'نی منِ تنها کشم تَطاولِ زلفت','تطاول‌: درازدستی‌، جور‌، بیداد.',NULL);
INSERT INTO "verses" VALUES(1936613,2256,8,1,'کیست که او داغِ آن سیاه ندارد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936614,2256,7,0,'گو برو و آستین به خونِ جگر شوی','هوش مصنوعی: برو و اگر دلت می‌خواهد برای اینجا تلاش کنی، باید با تمام وجود و سختی‌ها روبرو شوی. هر کسی که لایق ورود به این مکان نیست، بهتر است که نرود.',NULL);
INSERT INTO "verses" VALUES(1936615,2254,1,0,'شیوهٔ حور و پری گرچه لطیف است ولی','هوش مصنوعی: روش و زیبایی حور و پری هرچقدر هم که نرم و دلپذیر باشد، اما زیبایی و لطافت واقعی متعلق به فرد دیگری است که فراتر از آن‌هاست.',NULL);
INSERT INTO "verses" VALUES(1936616,2256,7,1,'هر که در این آستانه راه ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936617,2256,6,0,'خون خور و خامُش نشین که آن دلِ نازک','هوش مصنوعی: خاموش بمان و دردهایت را در دل نگه‌دار، زیرا آن دل حساس و لطیف تحمل شنیدن صدای فریاد تو را ندارد.',NULL);
INSERT INTO "verses" VALUES(1936618,2256,5,0,'رَطلِ گرانم ده ای مریدِ خرابات','رطل‌: جام و پیاله شراب.',NULL);
INSERT INTO "verses" VALUES(1936619,2256,5,1,'شادیِ شیخی که خانقاه ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936620,2256,4,0,'دیدم و آن چشمِ دلْ‌سیه که تو داری','هوش مصنوعی: دیدم که چشمان دل‌سیاهم به هیچ‌کس آشنا نگاه نمی‌کند و بی‌اعتناست.',NULL);
INSERT INTO "verses" VALUES(1936621,2256,4,1,'جانبِ هیچ آشنا نگاه ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936622,2256,3,0,'شوخیِ نرگس نگر که پیشِ تو بشکفت','هوش مصنوعی: نرگس با لطافت و زیبایی خود توجه تو را جلب کرده و حالا که به تو نزدیک شده، چشم‌های عاشقانه‌اش دیگر حوصلۀ ادب و احترام را ندارند.',NULL);
INSERT INTO "verses" VALUES(1936623,2256,3,1,'چشمْ دریده، ادب نگاه ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936624,2256,2,0,'تا چه کُنَد با رخِ تو دودِ دلِ من','هوش مصنوعی: تا چه اندازه زیبایی صورت تو می‌تواند با غم قلب من بازی کند، آیا تو نمی‌دانی که تحمل کردن ناله و آه برای من دشوار است؟',NULL);
INSERT INTO "verses" VALUES(1936625,2256,2,1,'آینه دانی که تابِ آه ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936626,2256,1,0,'گوشهٔ ابرویِ توست منزلِ جانم','هوش مصنوعی: منزل اصلی و مأمن وجود من در گوشه ابروی توست و هیچ‌جا برای من زیباتر و دلنشین‌تر از این مکان نیست، حتی در برترین جایگاه‌ها نیز چنین آرامشی وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1936627,2256,1,1,'خوشتر از این گوشه، پادْشاه ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936628,2256,0,0,'روشنیِ طلعتِ تو ماه ندارد','هوش مصنوعی: چهره‌ی تو آن‌قدر درخشان است که حتی نور ماه را تحت‌الشعاع قرار می‌دهد و زیبایی تو به قدری فوق‌العاده است که هیچ گلی نمی‌تواند با آن رقابت کند.',NULL);
INSERT INTO "verses" VALUES(1936629,2256,0,1,'پیشِ تو گُل، رونقِ گیاه ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936630,2255,8,1,'زیرا که چون تو شاهی کس در جهان ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936631,2256,6,1,'طاقتِ فریاد دادخواه ندارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936632,2242,3,0,'تنش درست و دلش شاد باد و خاطر خوش','هوش مصنوعی: او به خوبی زندگی می‌کند و دلش شاد است و خاطرش خوش است، چرا که به یاری کسی که به کمک نیاز داشته، شتافته است.',NULL);
INSERT INTO "verses" VALUES(1936633,2254,1,1,'خوبی آن است و لطافت که فُلانی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936634,2254,0,0,'شاهد آن نیست که موییّ و میانی دارد','هوش مصنوعی: در این بیت به زیبایی و جذابیت اشاره شده است. شخصی که بنده و عاشق زیبایی است، باید به زیبایی واقعی توجه کند، نه به ظواهر و مانند آنها. در واقع، او باید به درون و عمق وجود شخص یا چیز زیبایی که می‌بیند، توجه کند.',NULL);
INSERT INTO "verses" VALUES(1936635,2252,0,0,'مطربِ عشق عجب ساز و نوایی دارد','مطرب عشق‌، عجب خوش‌صدا و خنیاگر ماهری است که هر آهنگ که می‌زند به‌جایی راه دارد.',NULL);
INSERT INTO "verses" VALUES(1936636,2252,0,1,'نقشِ هر نغمه که زد راه به جایی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936637,2251,7,0,'غُبارِ راهگذارت کجاست تا «حافِظ»','هوش مصنوعی: چینِ غبار راهت کجاست تا حافظ یادگاری از نسیم صبحگاهی ثبت کند؟',NULL);
INSERT INTO "verses" VALUES(1936638,2251,7,1,'به یادگارِ نَسیمِ صَبا نگه دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936639,2251,6,0,'سَر و زَر و دل و جانم، فَدایِ آن یاری','تمام وجودم را [جان و مال و احساسات و قلبم] فدای آن کسی می کنم که به پیمان محبت و وفاداری بین یار پایبنده باشد.',NULL);
INSERT INTO "verses" VALUES(1936640,2251,6,1,'که حَقِّ صُحْبَتِ مِهْر و وَفا نگه دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936641,2251,5,0,'چو گفتمش که دلم را نگاه دار، چه گفت؟','هوش مصنوعی: وقتی از او خواستم که دل مرا مراقبت کند، چه پاسخی داد؟ از منِ ناتوان چه برمی‌آید؟ فقط خدا خودش نگه‌دارنده است.',NULL);
INSERT INTO "verses" VALUES(1936642,2251,5,1,'ز دَسْتِ بَنده چه خیزد؟ خُدا نگه دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936643,2251,4,0,'صَبا بر آن سَرِ زُلْف اَر دِلِ مرا بینی','هوش مصنوعی: سؤال می‌کنم که اگر نسیم برومند بر سر آن زلف بیفتد و دل مرا ببیند، از روی لطف به او بگوید که کجا باید بماند.',NULL);
INSERT INTO "verses" VALUES(1936644,2251,4,1,'ز رویِ لُطْف بگویش که جا نگه دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936645,2251,3,0,'گَرَت هَواست که مَعشوق نَگْسَلد پِیمان','اگر دوست داری معشوق به پیمان عشق وفادار باشد ، تو نیز رسم وفا را نگاه دار یا سر رشته عشق را رها نکند تا او هم نگه دارد . در ضمن استاد بهاالدین خرمشاهی در کتاب حافظ حافظه ماست معتقد است این بیت به آیه (فاذکرونی اذکرکم ۱۵۲ بقره) اشاره دارد',NULL);
INSERT INTO "verses" VALUES(1936646,2251,3,1,'نگاه دار سرِ رشته تا نگه دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936647,2251,2,0,'دلا، مَعاش چُنان کُن که گر بِلَغْزَد پای','ای دل، زندگی را به گونه‌ای بگذران که اگر روزی پایت لغزید و خطایی کردی، فرشته‌ای که مراقب توست برایت دعا کند و با همان دعا تو را از لغزش بازدارد',NULL);
INSERT INTO "verses" VALUES(1936648,2251,2,1,'فرشته‌ات به دو دستِ دُعا نگه دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936649,2251,1,0,'حَدیثِ دوست نگویم مَگَر به حَضْرَتِ دوست','هوش مصنوعی: من تنها با خدا از دوست سخن می‌گویم، چرا که او آشنای واقعی است و می‌تواند کلام آشنا را حفظ کند.',NULL);
INSERT INTO "verses" VALUES(1936650,2251,1,1,'که آشنا، سُخَنِ آشنا نگه دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936651,2251,0,0,'هر آن‌که جانِبِ اَهْلِ خُدا نگه دارد','هرکسی که از اهل ایمان [و دین خداوند و اعتقادات] طرفداری و حمایت کند [طرفشان را بگیرد]، خداوند او را در تمامی لحظات از بلا و درد محافظت و دور خواهد کرد.',NULL);
INSERT INTO "verses" VALUES(1936652,2251,0,1,'خُداش در همه حال از بَلا نگه دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936653,2250,8,0,'وگر گوید نمی‌خواهم، چو «حافِظ»، عاشِقِ مُفْلِس','اگر او بگوید که عاشق فقیری مقل حافظ نمی‌خواهد، به او بگویید که سلطان هم گدایی همنشین خود دارد.',NULL);
INSERT INTO "verses" VALUES(1936654,2250,8,1,'بگوییدش که سلطانی، گدایی هم‌نشین دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936655,2250,7,0,'صَبا از عِشقِ من، رَمزی بگو با آن شَهِ خوبان','هوش مصنوعی: باد Beauty از عشق من پیغامی به آن معشوق زیبا برسان و به او بگو که بزرگترین پادشاهان چون جمشید و کیخسرو، در برابر من همچون نوکر و خدمتگزارند.',NULL);
INSERT INTO "verses" VALUES(1936656,2250,7,1,'که صد جَمشید و کِیخُسرو، غُلامِ کم‌ترین دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936657,2250,6,0,'بَلاگردانِ جان و تن، دعایِ مُسْتْمَنْدان است','هوش مصنوعی: خیر و برکت زندگی و نعمت‌های آن ناشی از دعا و درخواست‌های افراد مستمند است. در واقع، آیا می‌توان انتظار داشت که کسی که از به دست آوردن نعمت‌ها شرم دارد، از این دعا و درخواست‌ها بهره‌ای ببرد؟',NULL);
INSERT INTO "verses" VALUES(1936658,2250,6,1,'که بیند خِیْر از آن خَرْمَن که نَنْگ از خوشه‌چین دارد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936659,2250,5,0,'چو بر رویِ زَمین باشی، توانایی، غَنیمت دان','هوش مصنوعی: وقتی بر روی زمین هستی و زندگی می‌کنی، از این فرصت استفاده کن؛ زیرا سختی‌ها و ناتوانی‌ها در زیر زمین و در اعماق زندگی بسیار وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1936660,2250,5,1,'که دوران، ناتوانی‌ها، بسی زیرِ زَمین دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936661,2250,4,0,'به خواری مَنْگَر ای مُنْعِم، ضَعیفان و نَحیفان را','هوش مصنوعی: به خاطر ضعف و نیازمندی من نگاه نکن، زیرا در کنار افراد ضعیف و بی‌چیز، کسانی هم هستند که در جشن و شادی‌ها، فقیرانی را به عنوان مهمان و رفیق خود دارند.',NULL);
INSERT INTO "verses" VALUES(1936662,2250,4,1,'که صَدْرِ مَجْلِسِ عِشْرَت، گدایِ ره‌نشین دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936663,2250,3,1,'بنازم دِلْبَرِ خود را، که حُسْنَش، آن و این دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936664,2252,1,0,'عالَم از نالهٔ عُشّاق مبادا خالی','(آرزو دارم) دنیا از عاشقان خالی نشود زیرا دنیا با عاشقان خوش و فرح‌بخش است.',NULL);
INSERT INTO "verses" VALUES(1936665,2252,1,1,'که خوش‌آهنگ و فرح‌بخش هوایی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936666,2252,2,0,'پیر دُردی‌کَش ما گرچه ندارد زر و زور','پیر و مرشد دائم‌الخمر ما اگرچه پول و مقام ندارد اما خدایی خطاپوش و بخشنده دارد.',NULL);
INSERT INTO "verses" VALUES(1936667,2252,2,1,'خوش عطابخش و خطاپوش خدایی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936668,2253,8,0,'کِی کُنَد سویِ دلِ خستهٔ حافظ نظری','چشم مست او کی به حافظ توجه می‌کند وقتی که در هر گوشه و غمزه‌ای عاشقی دارد؟',NULL);
INSERT INTO "verses" VALUES(1936669,2253,8,1,'چشمِ مستش که به هر گوشه خرابی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936670,2253,7,0,'جانِ بیمارِ مرا نیست ز تو روی سؤال','جان بیمار من از تو روی سؤال ندارد؛ خوشا بیماری که از یارش جوابی دارد.',NULL);
INSERT INTO "verses" VALUES(1936671,2253,7,1,'ای خوش آن خسته که از دوست جوابی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936672,2253,6,0,'چشمِ مخمورِ تو دارد ز دلم قصدِ جگر','چشم مستت قصد جگر مرا کرده، گویی ترک مستی‌است که میل کباب کرده‌است.',NULL);
INSERT INTO "verses" VALUES(1936673,2253,6,1,'تُرک مست است مگر میلِ کبابی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936674,2253,5,0,'آب حَیوان اگر این است که دارد لبِ دوست','در مقایسه با آب حیات که لب دوست دارد، بی‌شک خضر به سراب رسیده‌است.',NULL);
INSERT INTO "verses" VALUES(1936675,2253,5,1,'روشن است این که خِضِر بهره سرابی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936676,2253,4,0,'غمزهٔ شوخِ تو خونم به خطا می‌ریزد','غمزه گستاخ تو که خون مرا می‌ریزد پیروز بادا که فکر درستی در سر دارد.',NULL);
INSERT INTO "verses" VALUES(1936677,2253,4,1,'فرصتش باد که خوش فکر صوابی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936678,2253,3,0,'چشمِ من کرد به هر گوشه روان سیلِ سرشک','چشمم همچون جویی روان گشته تا سرو قامت زیبای تو را آبیاری کند.',NULL);
INSERT INTO "verses" VALUES(1936679,2253,3,1,'تا سَهی سَروِ تو را تازه‌تر آبی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936680,2253,2,0,'ماهِ خورشید نُمایَش ز پسِ پردهٔ زلف','ماه چهره‌ی او در کنار زلف سیاهش همچون خورشید در پیش ابر سیاه می‌درخشد',NULL);
INSERT INTO "verses" VALUES(1936681,2253,2,1,'آفتابیست که در پیش سَحابی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936682,2254,0,1,'بندهٔ طلعتِ آن باش که آنی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936683,2253,1,0,'از سَرِ کُشتهٔ خود می‌گذری همچون باد','به عاشق و کشته خود توجه نمی‌کنی و همچون باد می‌گذری؛ چه‌توان کرد؟ عمرم است و به‌شتاب می‌گذرد.',NULL);
INSERT INTO "verses" VALUES(1936684,2253,0,0,'آن که از سُنبُلِ او، غالیه تابی دارد','آن‌کسی که غالیهٔ خوش‌بو عاشق سنبل زلفش گشته، باز با عاشقانش ناز و عتاب آغاز کرد.',NULL);
INSERT INTO "verses" VALUES(1936685,2253,0,1,'باز با دلشدگان ناز و عِتابی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936686,2252,8,0,'خسروا حافظ درگاه‌نشین فاتحه خواند','پادشاها! حافظ درگاه‌نشین تو فاتحه خواند و از زبان تو دعای خیری طلب می‌کند.',NULL);
INSERT INTO "verses" VALUES(1936687,2252,8,1,'وز زبان تو تمنای دعایی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936688,2252,7,0,'نغز گفت آن بتِ ترسابچهٔ باده‌پرست','چه زیبا گفت آن زیباروی ترسازاده باده‌پرست وقتی‌که گفت: به‌شادی روی آدم‌های باصفا بنوش!',NULL);
INSERT INTO "verses" VALUES(1936689,2252,7,1,'شادیِ رویِ کسی خور که صفایی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936690,2252,6,0,'ستم از غمزه میاموز که در مذهبِ عشق','راه ستم غمزه را در پیش مگیر که هر کار خوب پاداشی و هر کرده بد مجازاتی دارد.',NULL);
INSERT INTO "verses" VALUES(1936691,2252,6,1,'هر عمل اجری و هر کرده جزایی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936692,2252,5,0,'اشکِ خونین بنمودم به طبیبان گفتند','اشک خونین خود را به پزشکان نشان دادم؛ گفتند: درد عاشقی است و دوای آن بسیار جگرسوز و دردآور است.',NULL);
INSERT INTO "verses" VALUES(1936693,2252,5,1,'دردِ عشق است و جگرسوز دوایی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936694,2252,4,0,'از عدالت نَبُوَد دور گَرَش پُرسد حال','اگر پادشاهی از همسایه گدای خود حالی بپرسد، از عدالتش دور نیست.',NULL);
INSERT INTO "verses" VALUES(1936695,2252,4,1,'پادشاهی که به همسایه گدایی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936696,2252,3,0,'محترم دار دلم کاین مگسِ قندپَرست','دل مرا گرامی بدار زیرا اگرچه یک مگس است که به‌هوای قند تو آمده‌، اما در اثر این عشق‌، همچون هما باشکوه گشته‌است.',NULL);
INSERT INTO "verses" VALUES(1936697,2252,3,1,'تا هواخواهِ تو شد فَرِّ هُمایی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936698,2253,1,1,'چه توان کرد؟ که عمر است و شتابی دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1936699,2242,3,1,'که دست دادش و یاریِ ناتوانی داد',NULL,NULL);
INSERT INTO "verses" VALUES(1936700,2242,2,0,'شکسته‌وار به درگاهت آمدم، که طبیب','هوش مصنوعی: با حالتی شکسته و ناامید به درگاه تو آمدم، چرا که تو همانی هستی که با لطف و مهربانی‌ات، نشانه‌ای را نشانم دادی تا به شفا برسم.',NULL);
INSERT INTO "verses" VALUES(1936701,2242,2,1,'به مومیاییِ لطفِ توام، نشانی داد',NULL,NULL);
INSERT INTO "verses" VALUES(1936704,2230,9,0,'قدح مگیر چو حافظ مگر به نالهٔ چنگ','همچون حافظ باش و بدون نوای مطرب و چنگ، باده‌گساری مکن و می منوش، زیرا دل شاد را با موسیقی و ساز شاد جفت کرده‌اند و بسته‌اند. (ابریشم در این بیت منظور تارها و سیم‌های برخی سازهاست که در گذشته از ابریشم می‌ساخته‌اند.)',NULL);
INSERT INTO "verses" VALUES(1936705,2230,9,1,'که بسته‌اند بر ابریشمِ طرب دلِ شاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936706,2230,8,0,'نمی‌دهند اجازت مرا به سِیرِ سفر','نسیم دل‌انگیز باد «مُصلّا» و زلالی و شیرینی آب «رکن‌آباد» مرا پایبند کرده و نمی‌گذارد که راه سفر در پیش بگیرم.',NULL);
INSERT INTO "verses" VALUES(1936707,2230,8,1,'نسیمِ بادِ مُصَلّا و آبِ رُکن آباد',NULL,NULL);
INSERT INTO "verses" VALUES(1936708,2230,7,0,'بیا بیا که زمانی ز می خراب شویم','بیا و بیا تا باده بنوشیم و شاد باشیم، شاید در این خراب‌آباد دنیا گنجی شایسته بیابیم.',NULL);
INSERT INTO "verses" VALUES(1936709,2230,7,1,'مگر رسیم به گنجی در این خراب آباد',NULL,NULL);
INSERT INTO "verses" VALUES(1936710,2230,6,0,'مگر که لاله بدانست بی‌وفاییِ دهر','شاید به‌این دلیل که لاله بی‌وفایی روزگار را می‌بیند، از روزی که متولد می‌شود تا روزی که می‌رود، جام می را از کف فرو نمی‌نهد.',NULL);
INSERT INTO "verses" VALUES(1936711,2230,6,1,'که تا بزاد و بِشُد، جامِ می ز کف نَنَهاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936712,2230,5,0,'ز حسرتِ لبِ شیرین هنوز می‌بینم','می‌بینم که از داغ لب‌های شیرین که فرهاد با خود به‌خاک برد، و اشک‌های خونین که ریخت‌، هنوز لاله‌ از دل خاک می‌روید.',NULL);
INSERT INTO "verses" VALUES(1936713,2230,5,1,'که لاله می‌دمد از خونِ دیدهٔ فرهاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936714,2230,4,0,'که آگه است که کاووس و کی کجا رفتند؟','چه‌کسی می‌داند که کاووس و کی کجا رفتند؟ و چه‌کسی آگاه است که تخت و فرمان‌روایی جمشید چگونه از بین رفت؟',NULL);
INSERT INTO "verses" VALUES(1936715,2230,4,1,'که واقف است که چون رفت تخت جم، بر باد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936716,2230,3,0,'قدح به شرطِ ادب گیر زان که ترکیبش','جام (سفالین) را با ادب و احترام به‌دست بگیر که ترکیب آن، از خاک بزرگان و شاهان کیانی و انسان‌های با شأن و عظمتی‌است.',NULL);
INSERT INTO "verses" VALUES(1936717,2230,3,1,'ز کاسهٔ سرِ جمشید و بهمن است و قباد',NULL,NULL);
INSERT INTO "verses" VALUES(1936718,2230,2,0,'ز انقلابِ زمانه عجب مدار که چرخ','از گردش روزگار و شگفتی‌های آن تعجب مکن که چرخ فلک و روزگار از این کارها و عجایب‌، هزاران‌هزار کرده و به‌یاد دارد.',NULL);
INSERT INTO "verses" VALUES(1936719,2230,2,1,'از این فسانه هزاران هزار دارد یاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936720,2230,1,0,'گره ز دل بگشا وز سپهر یاد مکن','غم مخور و از جور و ستم روزگار یاد مکن‌، که هیچ متفکر و مهندسی این راز را نگشوده و نگشاید.',NULL);
INSERT INTO "verses" VALUES(1936721,2230,1,1,'که فکر هیچ مهندس چنین گره نگشاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936722,2230,0,0,'شراب و عیش نهان چیست؟ کارِ بی‌بنیاد','شراب و عیش خاص و نهان که از آن سخن می‌گویند دانی که چیست؟ کار بی‌بنیاد کردن و شاد بودن؛ ما به رندان پیوستیم و هرچه شود، شود.',NULL);
INSERT INTO "verses" VALUES(1936723,2230,0,1,'زدیم بر صفِ رندان و هر چه بادا باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936724,2229,4,1,'کوته کنیم قصه، که عمرت دراز باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936725,2229,3,1,'در معرضی که تخت سلیمان رَوَد به باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936726,2229,4,0,'حافظ گرت ز پندِ حکیمان مَلالت است','ای حافظ، اگر پند خردمندان و دانایان تو را آزرده می‌کند، پس سخن را کوتاه می‌کنیم، عمرت دراز بادا!',NULL);
INSERT INTO "verses" VALUES(1936727,2229,2,1,'از بهر این معامله غمگین مباش و شاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936728,2229,3,0,'بادت به دست باشد اگر دل نهی به هیچ','اگر دل و مهر خود را به هیچ ببندی، در آخر هیچ نصیبت نمی‌شود؛ در جایی که فرمان‌روایی بی‌نظیر سلیمان بر باد می‌رود و هیچ می‌شود.',NULL);
INSERT INTO "verses" VALUES(1936729,2229,1,1,'گفتا قبول کن سخن و هر چه باد، باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936730,2229,2,0,'سود و زیان و مایه چو خواهد شدن ز دست','وقتی که از سود و از زیان و سرمایه و هرچه که هست رفتنی است؛ پس برای این معامله نه غمگین باش و نه شاد و اصلا به‌آن فکر نکن.',NULL);
INSERT INTO "verses" VALUES(1936735,2233,4,0,'بُتا چون غَمزه‌ات ناوَک فشاند','هوش مصنوعی: ای معشوق، وقتی که تو با ناز و غمزه‌ات دل من را جریحه‌دار می‌کنی، آرزو می‌کنم که دل مجروح من در برابر او، همچون سپری باشد.',NULL);
INSERT INTO "verses" VALUES(1936736,2233,4,1,'دلِ مجروحِ من پیشش سپر باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936737,2233,3,0,'دلی کو عاشقِ رویت نباشد','هوش مصنوعی: دل‌هایی که عاشق چهره تو نیستند، همیشه در اندوه و غم عمیق به سر می‌برند.',NULL);
INSERT INTO "verses" VALUES(1936738,2233,3,1,'همیشه غرقه در خونِ جگر باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936739,2233,2,0,'کسی کو بستهٔ زلفت نباشد','هوش مصنوعی: هرکس که اسیر زیبایی‌های تو نیست، وقتی ببندد زلفت را، باد آن را به هم می‌زند و بی‌نظم می‌کند.',NULL);
INSERT INTO "verses" VALUES(1936740,2233,2,1,'چو زلفت درهم و زیر و زبر باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936741,2233,1,0,'هُمای زلفِ شاهین شهپرت را','هوش مصنوعی: پرچم زیبای شاهین به زلف‌های او می‌ماند و دل‌های پادشاهان جهان را تحت تأثیر قرار داده است.',NULL);
INSERT INTO "verses" VALUES(1936742,2233,1,1,'دلِ شاهانِ عالم زیرِ پَر باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936743,2233,0,0,'جمالت آفتابِ هر نظر باد','هوش مصنوعی: زیبایی تو مانند آفتاب است و هر نگاه به تو باید از خوبی و زیبایی‌ات بهتر باشد.',NULL);
INSERT INTO "verses" VALUES(1936744,2233,0,1,'ز خوبی رویِ خوبت خوب‌تر باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936745,2232,5,0,'رازِ حافظ بعد از این ناگفته ماند','راز و سر حافظ شعر و غزل‌، همچنان ناگفته و پنهان ماند یاد آن محرمان راز و رازداران بخیر باد.',NULL);
INSERT INTO "verses" VALUES(1936746,2232,5,1,'ای دریغا رازداران یاد باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936747,2232,4,0,'گر چه صد رود است در چشمم مُدام','اگرچه صد جوی از اشک در کنار خود دارم اما همچنان به یاد زاینده رود و باغکاران ( یک باغ تاریخی در اصفهان در قرون گذشته) هستم .',NULL);
INSERT INTO "verses" VALUES(1936748,2232,4,1,'زنده رودِ باغ‌ِ کاران یاد باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936749,2229,0,1,'گفتا شراب نوش و غمِ دل بِبَر ز یاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936750,2232,3,0,'مبتلا گشتم در این بند و بلا','در این بند و بلاهای روزگار امروز گرفتار شده‌ام یاد خوبی‌های آن یاران باوفا بخیر.',NULL);
INSERT INTO "verses" VALUES(1936751,2232,2,0,'گر چه یاران فارِغَند از یادِ من','اگر‌چه دوستان و یاران مرا فراموش کرده‌اند اما من یاد آنها را هزاران بار به‌نیکی به خاطر می‌آورم.',NULL);
INSERT INTO "verses" VALUES(1936752,2232,2,1,'از من ایشان را هزاران یاد باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936753,2232,1,0,'کامم از تلخیِ غم چون زهر گشت','تلخی و نامردای‌های امروز‌، کامم را هم چون زهر تلخ کرده‌است‌؛ یاد روزهای می‌خواری و تلخی‌های باده بخیر و یاد بانگ‌های «نوشت باد!» مجلسی که به شادی می‌نوشیدیم.',NULL);
INSERT INTO "verses" VALUES(1936754,2232,1,1,'بانگِ نوشِ شادخواران یاد باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936755,2232,0,0,'روز وصلِ دوستداران یاد باد','یادش بخیر آن‌زمان که با محبوبان و دوستداران هم‌نشین بودم‌؛ باز هم یاد باد آن روزگار خوش.',NULL);
INSERT INTO "verses" VALUES(1936756,2232,0,1,'یاد باد آن روزگاران، یاد باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936765,2232,3,1,'کوشش آن حق‌گزاران یاد باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936766,2233,5,0,'چو لعل شکَّرینَت بوسه بخشد','هوش مصنوعی: چون لعل خوش‌رنگ و شیرین‌مزه‌ای دهانم را با بوسه می‌آراید، روح من از آن سرشار و شاداب گردد.',NULL);
INSERT INTO "verses" VALUES(1936767,2229,1,0,'گفتم به باد می‌دهدم باده نام و ننگ','به او گفتم که شراب و باده، آبروی مرا می‌برد، پاسخ داد: این سخن را بپذیر هرچه شود، شود.',NULL);
INSERT INTO "verses" VALUES(1936768,2228,8,0,'غلامِ همتِ آنم که باشد','هوش مصنوعی: من از کسانی هستم که در اراده و تلاش مثل حافظ، بنده و تسلیم در برابر کسی مثل هندو فرخ (یا خوشبخت) هستم.',NULL);
INSERT INTO "verses" VALUES(1936769,2226,7,0,'فِتاد در دلِ حافظ هوایِ چون تو شَهی','ای شاه خوبان، در دل حافظ هوس و هوای تو افتاد؛ ای کاش او کمترین خاک درِ تو بود. (کاج‌: کاش)',NULL);
INSERT INTO "verses" VALUES(1936770,2226,6,0,'لبِ تو خضر و دهانِ تو آبِ حیوان است','لب تو آب زندگانی است و دهان تو چشمه زندگی؛ قد تو همچون سرو خوش‌اندام و کمر باریک تو همچون مو‌؛ و سینه و گردن روشن تو مثل عاج فیل.',NULL);
INSERT INTO "verses" VALUES(1936771,2226,6,1,'قدِ تو سرو و میان‌موی و بَر، به هیئت عاج',NULL,NULL);
INSERT INTO "verses" VALUES(1936772,2226,5,0,'چرا همی شکنی جانِ من ز سنگ‌دلی؟','چرا جان و دل من را با بی‌رحمی و سنگدلی می‌شکنی؟ دل مرا که همچون شیشه‌، نازک است.',NULL);
INSERT INTO "verses" VALUES(1936773,2226,5,1,'دلِ ضعیف که باشد، به نازکی چو زُجاج',NULL,NULL);
INSERT INTO "verses" VALUES(1936774,2226,4,0,'از این مرض به حقیقت شفا نخواهم یافت','از این بیماری‌، شفا نخواهم یافت زیرا ای عزیز، داروی درد دلم از تو نمی‌رسد. (منظور نبات و قند است در بیت قبل)',NULL);
INSERT INTO "verses" VALUES(1936775,2226,4,1,'که از تو دردِ دل ای جان! نمی‌رسد به عِلاج',NULL,NULL);
INSERT INTO "verses" VALUES(1936776,2226,3,0,'دهانِ شهدِ تو داده رواج آب خِضِر','دهان شیرین و خوش تو آب حیات روان کرده است و لب همچون قند تو رونق نبات مصر را از بازار برده است.',NULL);
INSERT INTO "verses" VALUES(1936777,2226,3,1,'لبِ چو قندِ تو بُرد از نباتِ مصر رواج',NULL,NULL);
INSERT INTO "verses" VALUES(1936778,2226,2,0,'بیاضِ رویِ تو روشن چو عارِضِ رُخِ روز','روی سپید تو همچون خورشید است و سیاهی زلف تو همچون شب تاریک.',NULL);
INSERT INTO "verses" VALUES(1936779,2226,2,1,'سوادِ زلفِ سیاهِ تو هست ظلمت داج',NULL,NULL);
INSERT INTO "verses" VALUES(1936780,2226,1,0,'دو چشمِ شوخِ تو برهم زده خَطا و حَبَش','دو چشم بی‌رحم و بی‌پروای تو ختا و حبش را برهم زده (ختا و حبش یعنی نهایت سپیدی و نهایت سیاهی) و چین و ماچین و هند و تا سرزمین‌های دوردست به چین زلف بلند و سیاه تو خراج می‌پردازند. (هند در اینجا اشاره است به سیاهی زلف)',NULL);
INSERT INTO "verses" VALUES(1936781,2226,1,1,'به چینِ زلفِ تو ماچین و هند داده خراج',NULL,NULL);
INSERT INTO "verses" VALUES(1936782,2226,0,0,'تویی که بر سرِ خوبانِ کشوری چون تاج','تو از همه زیبایان این سرزمین زیباتر و سَرتر هستی؛ شایسته‌است که تاجدار و شاه آنها باشی و همه به‌تو باج بپردازند.',NULL);
INSERT INTO "verses" VALUES(1936783,2226,0,1,'سِزَد اگر همهٔ دلبران دَهَندَت باج',NULL,NULL);
INSERT INTO "verses" VALUES(1936784,2225,4,0,'هم‌چو حافظ روز و شب بی‌خویشتن','مانند حافظ، روز و شب از خود بی خود شده ام. میسوزم و گریانم، و کمک می‌طلبم.',NULL);
INSERT INTO "verses" VALUES(1936785,2225,4,1,'گَشته‌ام سوزان و گریان الغیاث',NULL,NULL);
INSERT INTO "verses" VALUES(1936786,2225,3,0,'خونِ ما خوردند این کافَردلان','هوش مصنوعی: ای مسلمانان، این کافران به ما ظلم می‌کنند و در حق ما خیانت می‌ورزند. در این وضعیت ناگوار، چه چاره‌ای داریم؟ فریاد کمک می‌زنیم.',NULL);
INSERT INTO "verses" VALUES(1936787,2225,3,1,'ای مسلمانان چه درمان؟ الغیاث',NULL,NULL);
INSERT INTO "verses" VALUES(1936788,2225,2,0,'در بهایِ بوسه‌ای جانی طلب','این دلبران برای یک بوسه جان را طلب می‌کنند. فریاد!',NULL);
INSERT INTO "verses" VALUES(1936789,2225,2,1,'می‌کنند این دلسِتانان الغیاث',NULL,NULL);
INSERT INTO "verses" VALUES(1936790,2225,1,0,'دین و دل بردند و قَصدِ جان کنند','هوش مصنوعی: دین و عشق را از ما گرفتند و قصد جان ما را دارند. ای نجات، از ظلم و ستم خوبان، ای نجات!',NULL);
INSERT INTO "verses" VALUES(1936791,2225,1,1,'الغیاث از جورِ خوبان، الغیاث',NULL,NULL);
INSERT INTO "verses" VALUES(1936792,2225,0,0,'دردِ ما را نیست درمان الغیاث','هوش مصنوعی: درد و رنج ما هیچ درمانی ندارد و جدایی ما هیچ پایانی نمی‌یابد.',NULL);
INSERT INTO "verses" VALUES(1936793,2225,0,1,'هجرِ ما را نیست پایان الغیاث',NULL,NULL);
INSERT INTO "verses" VALUES(1936794,2224,6,0,'زهی همت که حافظ راست از دنیی و از عقبی','آفرین بر نظر بلند و همّت حافظ که هیچ چیز از دنیا و آخرت را نمی‌بیند جز خاک سرِ کوی تو را.',NULL);
INSERT INTO "verses" VALUES(1936795,2224,6,1,'نیاید هیچ در چشمش به جز خاکِ سرِ کویت',NULL,NULL);
INSERT INTO "verses" VALUES(1936796,2224,5,0,'من و بادِ صبا مِسکین، دو سرگردانِ بی‌حاصل','من و نسیم صبا، دو آدم سرگردان و ناامید هستیم که مست و بی‌خود گشته‌ایم من از غمزه چشم تو مستم و او از عطر زلفت.',NULL);
INSERT INTO "verses" VALUES(1936797,2224,5,1,'من از افسونِ چشمت مست و او از بویِ گیسویت',NULL,NULL);
INSERT INTO "verses" VALUES(1936798,2226,7,1,'کمینه ذرهٔ خاکِ درِ تو بودی کاج',NULL,NULL);
INSERT INTO "verses" VALUES(1936799,2227,0,0,'اگر به مذهبِ تو خونِ عاشق است مُباح','هوش مصنوعی: اگر عشق تو برای عاشق مباح است، پس خیر و صلاح ما در همین است که آنچه به تو مربوط می‌شود، در واقع خیر ما هم هست.',NULL);
INSERT INTO "verses" VALUES(1936800,2227,0,1,'صلاحِ ما همه آن است کآن تو راست صلاح',NULL,NULL);
INSERT INTO "verses" VALUES(1936801,2227,1,0,'سوادِ زلفِ سیاهِ تو جاعِلُ الظُّلُمات','سیاهیِ مویِ سیاهِ تو پدیدآورندهٔ تاریکی‌هاست؛ سفیدیِ چهرهٔ مانندِ ماهِ تو (ماهِ شبِ چهاردهم [که کامل است])، شکافندهٔ (و گسترش‌دهندهٔ سپیدیِ) صبح است؛ (اقتباس از سورهٔ انعام، آیهٔ ۱: «... جَعَلَ الظُّلُمَاتِ وَالنُّورَ ...» و آیهٔ ۹۶: «فَالِقُ الْإِصْبَاحِ ...»)',NULL);
INSERT INTO "verses" VALUES(1936802,2228,8,1,'چو حافظ بنده و هندوی فرخ',NULL,NULL);
INSERT INTO "verses" VALUES(1936803,2228,7,0,'اگر میلِ دلِ هر کس به جایی‌ست','هوش مصنوعی: اگر هر کس بخواهد به جایی برود، دل من هم به سمت خوشی و خوشبختی میل دارد.',NULL);
INSERT INTO "verses" VALUES(1936804,2228,7,1,'بُوَد میلِ دلِ من سوی فرخ',NULL,NULL);
INSERT INTO "verses" VALUES(1936805,2228,6,0,'نسیم مُشک تاتاری خجل کرد','هوش مصنوعی: نسیم عطر تاتاری شرمنده شد از بوی خوش زلف‌های عطری فرخ.',NULL);
INSERT INTO "verses" VALUES(1936806,2228,6,1,'شمیم زلف عَنبربوی فرخ',NULL,NULL);
INSERT INTO "verses" VALUES(1936807,2228,5,0,'دو تا شد قامتم همچون کمانی','هوش مصنوعی: قامتم به اندازه یک کمان شده و از غم دائمی، شبیه به ابروی کسی که زیباست، خمیده و افتاده است.',NULL);
INSERT INTO "verses" VALUES(1936808,2228,5,1,'ز غم پیوسته چون ابروی فرخ',NULL,NULL);
INSERT INTO "verses" VALUES(1936809,2228,4,0,'بده ساقی شرابِ ارغوانی','هوش مصنوعی: به من شراب قرمز رنگی بده تا یادآور زیبایی چشم‌های نرگس enchanting باشد.',NULL);
INSERT INTO "verses" VALUES(1936810,2228,4,1,'به یادِ نرگسِ جادوی فَرُّخ',NULL,NULL);
INSERT INTO "verses" VALUES(1936811,2228,3,0,'شود چون بید لرزان سروِ آزاد','هوش مصنوعی: اگر بید نرم و لرزان، قامت روبه‌رو را ببیند، مانند سرو آزاد به لرزه می‌افتد.',NULL);
INSERT INTO "verses" VALUES(1936812,2228,3,1,'اگر بیند قدِ دلجویِ فَرُّخ',NULL,NULL);
INSERT INTO "verses" VALUES(1936813,2228,2,0,'سیاهی نیکبخت است آن که دائم','هوش مصنوعی: آن کسی که همیشه همراه و همدل انسان خوشبختی باشد، در واقع خوشبختی را به همراه خود می‌آورد.',NULL);
INSERT INTO "verses" VALUES(1936814,2228,2,1,'بُوَد هم‌راز و هم‌زانوی فرخ',NULL,NULL);
INSERT INTO "verses" VALUES(1936815,2228,1,0,'به جز هندویِ زلفش هیچ کس نیست','هوش مصنوعی: به جز معشوق با زلف‌های هندی‌اش، هیچ کس دیگر از زیبایی و نعمت‌های چهره‌ی شاداب و خرم برخوردار نیست.',NULL);
INSERT INTO "verses" VALUES(1936816,2229,0,0,'دی پیر می‌فروش که ذکرش به خیر باد','دیروز پیر خرابات که درود بر او باد، گفت‌: باده بنوش و غم را یاد مکن.',NULL);
INSERT INTO "verses" VALUES(1936817,2228,1,1,'که برخوردار شد از روی فرخ',NULL,NULL);
INSERT INTO "verses" VALUES(1936818,2228,0,0,'دلِ من در هوایِ روی فرخ','هوش مصنوعی: دل من به خاطر دیدن چهره زیبای فَرّخ به شدت ناآرام و پریشان است، مانند موی فَرّخ که به هم ریخته است.',NULL);
INSERT INTO "verses" VALUES(1936819,2227,7,0,'صَلاح و توبه و تقوی ز ما مجو حافظ','هوش مصنوعی: به دنبال اصلاح و توبه و تقوای ما نباش، زیرا حافظ می‌گوید از میان رندها و عاشقان و مجنون‌ها کسی را پیدا نکرده که به حقیقت رستگاری رسیده باشد.',NULL);
INSERT INTO "verses" VALUES(1936820,2227,7,1,'ز رند و عاشق و مجنون کسی نیافت صلاح',NULL,NULL);
INSERT INTO "verses" VALUES(1936821,2227,6,0,'دعای جانِ تو وردِ زبان مشتاقان','هوش مصنوعی: دعای جان تو همیشه بر زبان عاشقان جاری است تا اینکه به زیبایی و روشنی متصل شود.',NULL);
INSERT INTO "verses" VALUES(1936822,2227,6,1,'همیشه تا که بُوَد متّصل مَسا و صَباح',NULL,NULL);
INSERT INTO "verses" VALUES(1936823,2227,5,0,'بداد لعلِ لبت بوسه‌ای به صد زاری','هوش مصنوعی: لبان تو را با حسرت بوسیدم و با اشک و زاری خواستم که کام دلم را از عشق تو پر کنم.',NULL);
INSERT INTO "verses" VALUES(1936824,2227,5,1,'گرفت کام دلم زو به صد هزار اِلحاح',NULL,NULL);
INSERT INTO "verses" VALUES(1936825,2227,4,0,'لبِ چو آبِ حیاتِ تو هست قُوَّتِ جان','هوش مصنوعی: آبِ حیات تو باعث قوت و زندگی ماست، و ذکر تو روح و جان ما را تغذیه می‌کند.',NULL);
INSERT INTO "verses" VALUES(1936826,2227,4,1,'وجودِ خاکیِ ما را از اوست ذکرِ رَواح',NULL,NULL);
INSERT INTO "verses" VALUES(1936827,2227,3,0,'ز دیده‌ام شده یک چشمه در کنار روان','هوش مصنوعی: از چشمانم چشمه‌ای جاری شده است، اما این آب برای کسی آشنا نخواهد شد، مگر برای کشتی‌ران.',NULL);
INSERT INTO "verses" VALUES(1936828,2227,3,1,'که آشنا نکند در میان آن، مَلّاح',NULL,NULL);
INSERT INTO "verses" VALUES(1936829,2227,2,0,'ز چینِ زلفِ کمندت کسی نیافت خلاص','هوش مصنوعی: هیچ‌کس نتوانسته از دایرهٔ جذابیت موهای پیچ‌خورده‌ات فرار کند؛ زیرا ابروهایت همچون کمانچه و چشمانت مانند تیر، تاثیرگذار و مهاجم‌اند.',NULL);
INSERT INTO "verses" VALUES(1936830,2227,2,1,'از آن کمانچهٔ ابرو و تیرِ چشم، نَجاح',NULL,NULL);
INSERT INTO "verses" VALUES(1936831,2227,1,1,'بَیاضِ رویِ چو ماهِ تو، فالِقُ الأصباح',NULL,NULL);
INSERT INTO "verses" VALUES(1936832,2228,0,1,'بُوَد آشفته همچون مویِ فرخ',NULL,NULL);
INSERT INTO "verses" VALUES(1936833,2224,4,1,'برافشان تا فروریزد هزاران جان ز هر مویت',NULL,NULL);
INSERT INTO "verses" VALUES(1936834,2233,5,1,'مذاقِ جانِ من زو پُرشِکر باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936835,2233,6,0,'مرا از توست هر دم تازه عشقی','هوش مصنوعی: هر لحظه عشق و شوقی تازه از تو در دل من جوانه می‌زند و تو هم هر ساعت با زیبایی‌های جدیدی خود را به من معرفی می‌کنی.',NULL);
INSERT INTO "verses" VALUES(1936836,2240,2,0,'این همه عکسِ می و نقشِ نگارین که نمود','هوش مصنوعی: این همه تصویر از شراب و نقوش زیبا، نشانه‌ای از درخشندگی چهره‌ی ساقی است که در جام دیده می‌شود.',NULL);
INSERT INTO "verses" VALUES(1936837,2240,2,1,'یک فروغِ رخِ ساقی‌ست که در جام افتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936838,2240,1,0,'حُسن رویِ تو به یک جلوه که در آینه کرد','هوش مصنوعی: زیبایی چهره تو با یک لحظه که در آینه نمایان شد، این تصویرها در دنیای خیال به وجود آمدند.',NULL);
INSERT INTO "verses" VALUES(1936839,2240,1,1,'این همه نقش در آیینهٔ اوهام افتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936840,2240,0,0,'عکسِ رویِ تو چو در آینهٔ جام افتاد','هوش مصنوعی: چهرهٔ تو هنگامی که در آینهٔ شیشه‌ای انعکاس یافت، عارف از خوشحالی و شادی ناشی از شراب به آرزویی بی‌فایده گرفتار شد.',NULL);
INSERT INTO "verses" VALUES(1936841,2240,0,1,'عارف از خندهٔ مِی در طمعِ خام افتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936842,2239,7,0,'حافظ که سرِ زلفِ بتان دست‌کشش بود','هوش مصنوعی: حافظ به زیبایی و جذابیت زلف‌های معشوق اشاره می‌کند و می‌گوید که این زیبایی و دلربایی به قدری تأثیرگذار است که فردی که روزی بر آن تکیه داشت، حالا خود دچار غم و مشکلات شده است. این نشان‌دهنده تغییر حال و روز افراد و چگونگی تأثیر عشق و زیبایی بر زندگی انسان‌هاست.',NULL);
INSERT INTO "verses" VALUES(1936843,2239,7,1,'بس طُرفه حریفی‌ست کَش اکنون به سر افتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936844,2239,6,0,'گر جان بدهد سنگِ سیه، لعل نگردد','هوش مصنوعی: اگر جان سنگ سیاه هم فدای چیزی شود، باز هم با ذات اصلی‌اش تغییر نمی‌کند، چه‌بسا که ذات ناپاک، هرگز به چیزی خوب و با ارزش تبدیل نمی‌شود.',NULL);
INSERT INTO "verses" VALUES(1936845,2239,6,1,'با طینتِ اصلی چه کُند، بدگهر افتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936846,2239,5,0,'بس تجربه کردیم در این دِیرِ مکافات','هوش مصنوعی: ما در این مکان پرچالش به اندازه کافی تجربه کسب کرده‌ایم و می‌دانیم که هر کس که وارد برزخی از سختی‌ها شود، سرانجام به زمین می‌افتد.',NULL);
INSERT INTO "verses" VALUES(1936847,2239,5,1,'با دُردکشان هر که درافتاد برافتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936848,2239,4,0,'مژگانِ تو تا تیغِ جهانگیر برآورد','هوش مصنوعی: چشمان تو به قدری زیبا و تند است که باعث می‌شود دل‌های زیادی از عشق تو جان بسپارند و در کنار یکدیگر قرار بگیرند.',NULL);
INSERT INTO "verses" VALUES(1936849,2239,4,1,'بس کشتهٔ دل زنده که بر یکدگر افتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936850,2239,3,0,'از رهگذرِ خاکِ سرِ کویِ شما بود','هوش مصنوعی: هر نخی که در دست نسیم صبحگاهی افتاده، از مسیر خاکِ سرسوی کوی شما عبور کرده است.',NULL);
INSERT INTO "verses" VALUES(1936851,2239,3,1,'هر نافه که در دستِ نسیمِ سحر افتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936852,2239,2,0,'دردا که از آن آهوی مشکینِ سیه چشم','هوش مصنوعی: افسوس که از آهوی زیبا و دلربای سیاه چشمی، به خاطر عشق و دردش، خون دل بسیار به وجودم ریخته شده است.',NULL);
INSERT INTO "verses" VALUES(1936853,2239,2,1,'چون نافه بسی خونِ دلم در جگر افتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936854,2239,1,0,'از راهِ نظر مرغِ دلم گشت هواگیر','هوا‌گیر‌: پروازی‌ || هوسی‌، آرزوخواه.',NULL);
INSERT INTO "verses" VALUES(1936855,2239,1,1,'ای دیده نگه کن که به دامِ که درافتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936856,2239,0,0,'پیرانه سَرم عشقِ جوانی به سر افتاد','در سال‌های پیری، شور عشق دوران جوانی در سرم افتاد( یا عشق معشوق جوانی در سرم افتاد و عاشقش شدم) و آن رازی که در قلبم پنهان کرده بودم، آشکار شد.',NULL);
INSERT INTO "verses" VALUES(1936857,2239,0,1,'وآن راز که در دل بِنَهفتم به درافتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936858,2238,6,0,'حافظ به ادب باش که واخواست نباشد','هوش مصنوعی: به ادب رفتار کن، زیرا اگر شاه پیامی به خدمتگزارش هم نرساند، دلیلی بر سرزنش نیست.',NULL);
INSERT INTO "verses" VALUES(1936859,2238,6,1,'گر شاه پیامی به غلامی نفرستاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936860,2238,5,0,'چندان که زدم لافِ کرامات و مقامات','هوش مصنوعی: هر چه بیشتر از کرامات و مقامات خود سخن گفتم، باز هم هیچ خبری از هیچ مقام و مرتبه‌ای به من نرسید.',NULL);
INSERT INTO "verses" VALUES(1936861,2238,5,1,'هیچم خبر از هیچ مقامی نفرستاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936862,2238,4,0,'فریاد که آن ساقیِ شِکَّر لبِ سرمست','هوش مصنوعی: صدایی بلندی به گوش می‌رسد که می‌گوید آن نوشیدنی‌دهنده با لب‌های شیرین و خوش‌صدا متوجه شده که من مست هستم، اما هیچ جرعه‌ای به من نداد.',NULL);
INSERT INTO "verses" VALUES(1936863,2238,4,1,'دانست که مخمورم و جامی نفرستاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936864,2238,3,0,'دانست که خواهد شُدنم مرغِ دل از دست','هوش مصنوعی: او فهمید که دل من به پروازی آزاد تبدیل خواهد شد و از آن خط که مانند زنجیره‌ای است، هیچ دام و تله‌ای نفرستاد.',NULL);
INSERT INTO "verses" VALUES(1936865,2240,3,0,'غیرتِ عشق زبانِ همه خاصان بِبُرید','هوش مصنوعی: دغدغه و احساساتی که در عشق وجود دارد، باعث شده تا راز و درد آن عشق به زبان دیگران بیفتد و عمومی شود. این نشان می‌دهد که چقدر عشق می‌تواند حساس و خصوصی باشد و گاهی به طور ناخواسته، اسرار آن به دیگران منتقل می‌شود.',NULL);
INSERT INTO "verses" VALUES(1936866,2240,3,1,'کز کجا سِرِّ غمش در دهنِ عام افتاد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936867,2240,4,0,'من ز مسجد به خرابات نه خود افتادم','هوش مصنوعی: من خودم به خانه‌ی خراب‌ها نرسیدم، بلکه این سرنوشت و نتیجه‌ای است که از ابتدای زمان برای من مقدر شده بود.',NULL);
INSERT INTO "verses" VALUES(1936868,2240,4,1,'اینم از عهدِ ازل حاصلِ فرجام افتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936869,2242,1,0,'دلم خزانهٔ اسرار بود و دستِ قضا','هوش مصنوعی: دل من مثل یک گنجینه‌ی پر از رازها بود، اما تقدیر آن را بست و کلیدش را به افرادی سپرد که به دل‌ها اهمیت می‌دهند.',NULL);
INSERT INTO "verses" VALUES(1936870,2242,1,1,'درش بِبَست و کلیدش به دل‌سِتانی داد',NULL,NULL);
INSERT INTO "verses" VALUES(1936871,2242,0,0,'بنفشه دوش به گل گفت و خوش نشانی داد','هوش مصنوعی: بنفشه دیروز به گل گفت و با ناز و زیبایی اشاره کرد که زیبایی و جذابیت من به خاطر موهای آن شخص خاص است.',NULL);
INSERT INTO "verses" VALUES(1936872,2242,0,1,'که تابِ من به جهان، طُرِّهٔ فلانی داد',NULL,NULL);
INSERT INTO "verses" VALUES(1936873,2241,6,0,'در کفِ غصه دوران، دلِ حافظ خون شد','هوش مصنوعی: دل حافظ از درد دوری تو به شدت رنج می‌کشد و از غم روزگار به شدت خونین شده است، ای خواجه قوام‌الدین، این را به تو می‌گوید.',NULL);
INSERT INTO "verses" VALUES(1936874,2241,6,1,'از فراقِ رُخَت ای خواجه قوامُ الدین، داد',NULL,NULL);
INSERT INTO "verses" VALUES(1936875,2241,5,0,'بعد از این دستِ من و دامنِ سرو و لبِ جوی','هوش مصنوعی: از این به بعد، دست من و دامن سرو و لب آب، به ویژه حالا که نسیم بهاری خبر آمدن فروردین را آورده است.',NULL);
INSERT INTO "verses" VALUES(1936876,2241,5,1,'خاصه اکنون که صبا مژده فروردین داد',NULL,NULL);
INSERT INTO "verses" VALUES(1936877,2241,4,0,'خوش عروسیست جهان از رهِ صورت لیکن','هوش مصنوعی: جهان به خاطر زیبایی‌های ظاهری‌اش مانند یک عروسی شاد و پر زرق و برق به نظر می‌رسد، اما هر کسی که به این زیبایی‌ها وابسته شود، عمر و زندگی‌اش را برای آن صرف می‌کند.',NULL);
INSERT INTO "verses" VALUES(1936878,2241,4,1,'هر که پیوست بدو، عمرِ خودش کاوین داد',NULL,NULL);
INSERT INTO "verses" VALUES(1936879,2241,3,0,'گنجِ زر گر نَبُوَد، کُنجِ قناعت باقیست','هوش مصنوعی: اگرچه گنج و ثروت ممکن است وجود نداشته باشد، اما قناعت و بی‌نیازی همیشه باقی است. کسی که ثروت را به شاهان می‌بخشید، به نیازمندان هم کمک می‌کند.',NULL);
INSERT INTO "verses" VALUES(1936880,2241,3,1,'آن که آن داد به شاهان، به گدایان این داد',NULL,NULL);
INSERT INTO "verses" VALUES(1936881,2241,2,0,'من همان روز ز فرهاد طمع بُبریدم','هوش مصنوعی: من در همان روز که فرهاد از عشق شیرین مایوس شد و دل شیدای خود را به او سپرد، دیگر امیدی به عشق نداشتم.',NULL);
INSERT INTO "verses" VALUES(1936882,2241,2,1,'که عنانِ دلِ شیدا به لبِ شیرین داد',NULL,NULL);
INSERT INTO "verses" VALUES(1936883,2238,3,1,'وز آن خطِ چون سلسله دامی نفرستاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936884,2241,1,0,'وان که گیسویِ تو را رسمِ تَطاول آموخت','هوش مصنوعی: کسی که به تو یاد داده که چگونه موهایت را بلند کنی، می‌تواند به من که در غم هستم، هم لطف کند و یاری برساند.',NULL);
INSERT INTO "verses" VALUES(1936885,2241,0,0,'آن که رخسارِ تو را رنگِ گل و نسرین داد','هوش مصنوعی: کسی که به چهره‌ات زیبایی مانند گل و نسرین بخشید، می‌تواند برای منِ بیچاره صبر و آرامش به ارمغان آورد.',NULL);
INSERT INTO "verses" VALUES(1936886,2241,0,1,'صبر و آرام توانَد به منِ مسکین داد',NULL,NULL);
INSERT INTO "verses" VALUES(1936887,2240,10,0,'صوفیان جمله حریفند و نظرباز ولی','هوش مصنوعی: در محفل صوفیان که همه با هم رفیق و اهل تماشا هستند، تنها حافظِ دل‌شکسته است که به خاطر عشق و دردش، نام خود را در میان آنان نیکو نساخته و بدنام شده است.',NULL);
INSERT INTO "verses" VALUES(1936888,2240,10,1,'زین میان حافظِ دل‌سوخته بدنام افتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936889,2240,9,0,'هر دَمَش با منِ دل‌سوخته لطفی دگر است','هوش مصنوعی: هر لحظه‌ای که او با من، دل‌سوخته و ناتوان، صحبت می‌کند، لطف و محبت جدیدی دارد. به این گدا نگاه کن که چقدر شایسته‌ی پاداش و بخشش است.',NULL);
INSERT INTO "verses" VALUES(1936890,2240,9,1,'این گدا بین که چه شایستهٔ انعام افتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936891,2240,8,0,'زیرِ شمشیرِ غمش رقص‌کُنان باید رفت','هوش مصنوعی: در مقابل غم او باید با شادی و سر زندگی جلو رفت، زیرا کسی که به دست او کشته شده، در نهایت به سرنوشت نیک و خوبی می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1936892,2240,8,1,'کـ‌آن که شد کشتهٔ او نیک سرانجام افتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936893,2240,7,0,'آن شد ای خواجه که در صومعه بازم بینی','هوش مصنوعی: ای دوست، حالتی پیش آمده که در مکان مقدس صومعه، دوباره تو را می‌بینم و کار ما، به زیبایی چهره ساقی و لب جام، مرتبط شده است.',NULL);
INSERT INTO "verses" VALUES(1936894,2240,7,1,'کار ما با رخِ ساقیّ و لبِ جام افتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936895,2240,6,0,'در خَمِ زلفِ تو آویخت دل از چاهِ زَنَخ','هوش مصنوعی: دل من به خاطر زلف‌های تو به چاه اندوهی پیوسته و وقتی از آن چاه خارج شد، در دام عشق تو گرفتار شد.',NULL);
INSERT INTO "verses" VALUES(1936896,2240,6,1,'آه، کز چاه برون آمد و در دام افتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936897,2240,5,0,'چه کند کز پی دوران نرود چون پرگار؟','هوش مصنوعی: چه باید کرد اگر کسی نتواند از دایرهٔ زمان بیرون برود؟ هر کس که به دام گردش روزگار گرفتار شود، نمی‌تواند خود را آزاد کند.',NULL);
INSERT INTO "verses" VALUES(1936898,2240,5,1,'هر که در دایرهٔ گردشِ ایام افتاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936899,2241,1,1,'هم تواند کَرَمَش دادِ منِ غمگین داد',NULL,NULL);
INSERT INTO "verses" VALUES(1936900,2233,6,1,'تو را هر ساعتی حُسنی دگر باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936901,2238,2,0,'سویِ منِ وحشی‌صفتِ عقل‌رمیده','هوش مصنوعی: به سمت من که افرادی بی‌بند و بار و بی‌پروا هستم، هیچ آهو یا کبکی که با آرامش حرکت کند، فرستاده نشد.',NULL);
INSERT INTO "verses" VALUES(1936902,2238,1,0,'صد نامه فرستادم و آن شاهِ سواران','هوش مصنوعی: من صد نامه برای او فرستادم، اما آن پادشاه سواران هیچ پیامبری نداشت که پاسخی دهد و حتی سلامی نفرستاد.',NULL);
INSERT INTO "verses" VALUES(1936903,2235,5,0,'هر آن که رویِ چو ماهت به چشمِ بد بیند',': هر کسی که زیبایی تو را با نظر بد ببیند، امیدوارم که جانش مانند اسپند در آتش تو بسوزد',NULL);
INSERT INTO "verses" VALUES(1936904,2235,4,0,'در آن بساط که حُسن تو جلوه آغازد','در محفل عشق و زیبایی تو، جایی برای انتقاد و نظر منفی افراد بدبین وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1936905,2235,4,1,'مجالِ طعنهٔ بدبین و بدپسند مباد',NULL,NULL);
INSERT INTO "verses" VALUES(1936906,2235,3,0,'در این چمن چو درآید خزان به یغمایی','وقتی فصل خزان به این باغ وارد شود، امیدوارم که راهش به سوی سروهای بلند و زیبا نرود و آن‌ها را از آن خود نکند.',NULL);
INSERT INTO "verses" VALUES(1936907,2235,3,1,'رهش به سروِ سهی قامتِ بلند مباد',NULL,NULL);
INSERT INTO "verses" VALUES(1936908,2235,2,0,'جمالِ صورت و معنی ز امنِ صحتِ توست','زیبایی چهره و باطن تو از سلامت و آسودگی‌ات سرچشمه می‌گیرد، پس نگذار که ظاهرت غمگین و باطن‌ات ناخرسند باشد.',NULL);
INSERT INTO "verses" VALUES(1936909,2235,2,1,'که ظاهرت دُژَم و باطنت نَژَند مباد',NULL,NULL);
INSERT INTO "verses" VALUES(1936910,2235,1,0,'سلامتِ همه آفاق در سلامتِ توست',': سلامت و خوشبختی همه دنیا به سلامت و خوبی تو بستگی دارد ، امیدوارم هیچ مرضی تو را دردمند نکند',NULL);
INSERT INTO "verses" VALUES(1936911,2235,1,1,'به هیچ عارضه شخصِ تو دردمند مباد',NULL,NULL);
INSERT INTO "verses" VALUES(1936912,2235,0,0,'تَنَت به نازِ طبیبان نیازمند مباد','امیدوارم بدنت دچار بیماری نشود که محتاج طبیب شوی و وجودت از بیماری و گزند دور باشد',NULL);
INSERT INTO "verses" VALUES(1936913,2235,0,1,'وجود نازکت آزردهٔ گزند مباد',NULL,NULL);
INSERT INTO "verses" VALUES(1936914,2234,7,0,'به غلامیِ تو مشهورِ جهان شد حافظ','حافظ از بندگی تو و در بندگی تو در جهان معروف شد؛ همیشه او، عاشق زلفت بادا!',NULL);
INSERT INTO "verses" VALUES(1936915,2234,7,1,'حلقهٔ بندگیِ زلفِ تو در گوشش باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936916,2234,6,0,'نرگسِ مست نوازش‌کُنِ مردم‌دارَش','چشم خمار و مهربانش؛ اگر خون عاشق را بریزد و بنوشد نوشش بادا!',NULL);
INSERT INTO "verses" VALUES(1936917,2234,6,1,'خونِ عاشق به قدح گر بِخورد نوشش باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936918,2234,5,0,'چشمم از آینه‌دارانِ خط و خالش گشت','چشمم به آینه‌داری او رسید امیدوارم لبم نیز به بوسه‌ربایی بر و دوش او برسد.',NULL);
INSERT INTO "verses" VALUES(1936919,2234,5,1,'لبم از بوسه‌رُبایانِ بَر و دوشش باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936920,2234,4,0,'گر چه از کِبر، سخن با منِ درویش نگفت','اگرچه از غرور با من بیچاره حرف نزد؛ جانم فدای لب‌های شیرین و تنگ و ساکت او بادا!',NULL);
INSERT INTO "verses" VALUES(1936921,2234,4,1,'جان فدایِ شِکَرین‌پستهٔ خاموشش باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936922,2234,3,0,'شاهِ تُرکان، سخنِ مدعیان می‌شِنَوَد','هوش مصنوعی: سلطان ترک به سخنان مدعیان گوش می‌دهد، امیدوارم که از ظلمی که بر سیاوش رفته است، شرمسار باشد.',NULL);
INSERT INTO "verses" VALUES(1936923,2234,3,1,'شرمی از مَظلَمِهٔ خونِ سیاوشش باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936924,2234,2,0,'پیرِ ما گفت خطا بر قلم صُنع نرفت','پیر ما فرمود که هیچ اشتباهی در ساخت و آفرینش رخ نمی‌دهد و باید به نظر پاک و خطا پوشاننده او آفرین گفت.',NULL);
INSERT INTO "verses" VALUES(1936925,2234,2,1,'آفرین بر نظرِ پاکِ خطاپوشَش باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936926,2234,1,0,'آن که یک جرعه مِی از دست توانَد دادن','هوش مصنوعی: هر کس بتواند یک جرعه شراب را به کسی بدهد، خوشا به حالش که در آغوش معشوق خود باشد.',NULL);
INSERT INTO "verses" VALUES(1936927,2234,1,1,'دست با شاهدِ مقصود در آغوشش باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936928,2234,0,0,'صوفی ار باده به اندازه خورَد نوشش باد','هوش مصنوعی: اگر صوفی در خوردن باده، میانه‌روی کند، نوشیدنش مبارک باشد؛ وگرنه بهتر است که به فکر این کار نباشد.',NULL);
INSERT INTO "verses" VALUES(1936929,2234,0,1,'ور نه اندیشهٔ این کار فراموشش باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936930,2233,7,0,'به جان، مشتاق روی توست حافظ','هوش مصنوعی: دل من به شدت خواهان دیدن روی توست، ای حافظ! امیدوارم که تو نیز در حال نظر کردن به عاشقان باشی.',NULL);
INSERT INTO "verses" VALUES(1936931,2233,7,1,'تو را در حالِ مشتاقان نظر باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936932,2235,5,1,'بر آتشِ تو بجز جانِ او سپند مباد',NULL,NULL);
INSERT INTO "verses" VALUES(1936933,2235,6,0,'شفا ز گفتهٔ شِکَّرفِشانِ حافظ جوی','از سخنان شیرین و حکیمانه حافظ بهره‌مند شو که درمان‌های معمولی مانند گلاب و قند کارساز نیست',NULL);
INSERT INTO "verses" VALUES(1936934,2235,6,1,'که حاجتت به عِلاجِ گلاب و قند مباد',NULL,NULL);
INSERT INTO "verses" VALUES(1936935,2236,0,0,'حُسن تو همیشه در فزون باد','هوش مصنوعی: زیبایی تو همیشه در اوج است و چهره‌ات هر سال مانند گل لاله می‌درخشد.',NULL);
INSERT INTO "verses" VALUES(1936936,2238,1,1,'پیکی نَدوانید و سلامی نفرستاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936937,2238,0,0,'دیر است که دل‌دار پیامی نفرستاد','هوش مصنوعی: مدت زیادی است که معشوق هیچ پیامی نفرستاده و سلام و حرفی هم ننوشته است.',NULL);
INSERT INTO "verses" VALUES(1936938,2238,0,1,'ننوشت سلامی و کلامی نفرستاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936939,2237,4,0,'نه به تنها حَیَوانات و نَباتات و جَماد','هوش مصنوعی: نه تنها موجودات زنده و گیاهان، بلکه هر چیزی که در این دنیا وجود دارد، به فرمان توست.',NULL);
INSERT INTO "verses" VALUES(1936940,2237,4,1,'هر چه در عالمِ امر است به فرمانِ تو باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936941,2237,3,0,'طِیرهٔ جلوهٔ طوبی قدِ چون سروِ تو شد','هوش مصنوعی: زیبایی و جلوه‌های درخت طوبی، قد و قامت تو را به یاد می‌آورد و غیرت بهشت برین، در محیط باغ تو حاکم است.',NULL);
INSERT INTO "verses" VALUES(1936942,2237,3,1,'غیرتِ خُلدِ بَرین ساحتِ بُستانِ تو باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936943,2237,2,0,'ای که انشاءِ عطارد صفتِ شوکتِ توست','هوش مصنوعی: ای کسی که به مانند عطارد، شگفتی و بزرگی‌ات را به تصویر کشیده است، امیدوارم که عقل کل همیشه در خدمت نشان زیبای تو باشد.',NULL);
INSERT INTO "verses" VALUES(1936944,2237,2,1,'عقل کل چاکرِ طُغراکشِ دیوانِ تو باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936945,2237,1,0,'زلفِ خاتونِ ظفر شیفتهٔ پرچم توست','هوش مصنوعی: زلفِ بانوی پیروزی به پرچم تو علاقه‌مند است و چشم‌های نزدیک به پیروزی ابدی، عاشقِ حرکت و شکوه تو خواهند بود.',NULL);
INSERT INTO "verses" VALUES(1936946,2237,1,1,'دیدهٔ فتحِ ابد عاشقِ جولانِ تو باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936947,2237,0,0,'خسروا گویِ فلک در خَمِ چوگان تو باد','هوش مصنوعی: ای کاش گردونهٔ زمان در دست تو باشد و همهٔ عالم عرصه‌ای برای نمایش هنر و توانایی‌های تو گردد.',NULL);
INSERT INTO "verses" VALUES(1936948,2237,0,1,'ساحتِ کون و مکان عرصهٔ میدانِ تو باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936949,2236,8,0,'لعلِ تو که هست جانِ حافظ','هوش مصنوعی: عشق و زیبایی تو، جان و زندگی حافظ است و دوری تو از مردم پست و بی‌ارزش، به مانند حرکتی نیکوست.',NULL);
INSERT INTO "verses" VALUES(1936950,2238,2,1,'آهو رَوشی، کبک خرامی نفرستاد',NULL,NULL);
INSERT INTO "verses" VALUES(1936951,2236,8,1,'دور از لبِ مردمانِ دون باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936952,2236,7,0,'هر دل که ز عشقِ توست خالی','هوش مصنوعی: هر کسی که دلش از عشق تو خالی باشد، نباید حلقه‌ی ارتباط و پیوند با تو را داشته باشد.',NULL);
INSERT INTO "verses" VALUES(1936953,2236,6,0,'قَدِّ همه دلبرانِ عالم','هوش مصنوعی: هر کدام از زیباترین دلبران جهان، در مقایسه با زیبایی‌ات مثل نان در برابر باد است.',NULL);
INSERT INTO "verses" VALUES(1936954,2236,6,1,'پیشِ الفِ قَدَت چو نون باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936955,2236,5,0,'هر جا که دلیست در غمِ تو','هوش مصنوعی: هر جایی که دل‌های عاشق وجود دارد، به خاطر غم تو در حال بی‌قراری و ناآرامی هستند.',NULL);
INSERT INTO "verses" VALUES(1936956,2236,5,1,'بی صبر و قرار و بی سکون باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936957,2236,4,0,'چشمِ تو ز بهرِ دلربایی','هوش مصنوعی: چشم تو به خاطر دلربایی، همچون جادوگری مهارت دارد.',NULL);
INSERT INTO "verses" VALUES(1936958,2236,4,1,'در کردنِ سحر ذوفنون باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936959,2236,3,0,'چشمی که نه فتنهٔ تو باشد','هوش مصنوعی: چشمی که نتواند به زیبایی تو خیره شود، مثل اشکی است که از غم داغی در دل، غرق خون شده است.',NULL);
INSERT INTO "verses" VALUES(1936960,2236,3,1,'چون گوهرِ اشک غرقِ خون باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936961,2236,2,0,'هر سرو که در چمن درآید','هوش مصنوعی: هر درخت سروی که به چمن بیفتد، باید در برابر قامت تو سرنگون شود.',NULL);
INSERT INTO "verses" VALUES(1936962,2236,2,1,'در خدمتِ قامتت نگون باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936963,2236,1,0,'اندر سرِ ما خیالِ عشقت','هوش مصنوعی: در ذهنِ ما هر روز خیالِ عشق تو وزش دارد و مانند بادی که همیشه در حال افزایش است.',NULL);
INSERT INTO "verses" VALUES(1936964,2236,1,1,'هر روز که باد در فزون باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936965,2236,0,1,'رویت همه ساله لاله‌گون باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936966,2236,7,1,'از حلقهٔ وصلِ تو برون باد',NULL,NULL);
INSERT INTO "verses" VALUES(1936967,2257,4,1,'بو که صاحب‌نَظَری نامِ تماشا بِبَرَد',NULL,NULL);
INSERT INTO "verses" VALUES(1936968,2193,2,0,'در این چمن گلِ بی خار کس نچید، آری','هوش مصنوعی: در این گلزار، هیچ گلی که بدون خاری باشد نگفته شد، زیرا روشنایی محمد (ص) با آتشِ جهل و نادانی در تضاد است.',NULL);
INSERT INTO "verses" VALUES(1936969,2193,1,0,'پری نهفته رخ و دیو در کرشمهٔ حُسن','هوش مصنوعی: زیبایى مانند پری در دل خود پنهان است و موجودی پلید در شگفتی از زیبایی او می‌سوزد. چشمانش پر از حیرت است که این چه شگفتی‌ای است.',NULL);
INSERT INTO "verses" VALUES(1936970,2150,4,0,'مست بگذشتی و از خلوتیانِ ملکوت','هوش مصنوعی: تو با حالت مست و بی‌خبریت از کنار ما گذشتی و باعث شدی که اهل عالم بالا، به تماشای تو، اضطراب و شلوغی قیامت را حس کنند.',NULL);
INSERT INTO "verses" VALUES(1936971,2150,3,1,'به هواداریِ آن عارض و قامت برخاست',NULL,NULL);
INSERT INTO "verses" VALUES(1936972,2150,3,0,'در چمن، بادِ بهاری ز کنار گل و سرو','هوش مصنوعی: در باغ، نسیم بهار با حمایت از زیبایی و قامت گل و سرو، به آرامی وزید.',NULL);
INSERT INTO "verses" VALUES(1936973,2150,2,1,'پیشِ عشاقِ تو شب‌ها به غَرامت برخاست',NULL,NULL);
INSERT INTO "verses" VALUES(1936974,2150,2,0,'شمع اگر زان لبِ خندان به زبان، لافی زد','هوش مصنوعی: اگر شمع به خاطر لب‌های خندان تو، در شب‌ها برای عشاق تو از خود لاف بزند و ادعا کند که به قدری زیبا هستی که ارزشش را دارد، نشان می‌دهد که تا چه حد عشق تو بر سایرین تأثیر می‌گذارد.',NULL);
INSERT INTO "verses" VALUES(1936975,2150,1,1,'که نه در آخرِ صحبت به ندامت برخاست',NULL,NULL);
INSERT INTO "verses" VALUES(1936976,2150,1,0,'که شنیدی که در این بزم، دمی خوش بنشست؟','هوش مصنوعی: آیا شنیدی که در این مهمانی، لحظه‌ای خوش و شاد زندگی کرد؟ که در پایان گفتگو، پشیمانی به سراغش نیامد.',NULL);
INSERT INTO "verses" VALUES(1936977,2150,0,1,'گفت با ما منشین، کز تو سلامت برخاست',NULL,NULL);
INSERT INTO "verses" VALUES(1936978,2150,0,0,'دل و دینم شد و دلبر به ملامت برخاست','هوش مصنوعی: دل و ایمان من به خاطر معشوق دچار مشکلاتی شده است. معشوق به من ایراد می‌گیرد و می‌گوید با ما نباش، چون از تو آسایش به دست نیامد.',NULL);
INSERT INTO "verses" VALUES(1936979,2149,7,0,'این چه عیب است کز آن عیب، خلل خواهد بود؟','هوش مصنوعی: این چه اشکالی است که اگر وجود داشته باشد، نقصی به همراه خواهد داشت؟ اگر هم وجود داشته باشد، چه اهمیتی دارد؟ آدم‌های بدون عیب کجا هستند؟',NULL);
INSERT INTO "verses" VALUES(1936980,2149,6,0,'چه شود گر من و تو چند قدح باده خوریم؟','چه مشکلی دارد که من و تو چند قدح باده بخوریم، باده و شراب از درخت انگور گرفته میشود و چیزی از شما کم نمیشود و ضرری به شما نمیرسد',NULL);
INSERT INTO "verses" VALUES(1936981,2149,7,1,'ور بُوَد نیز چه شد؟ مردم بی‌عیب کجاست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936982,2149,5,0,'فرضِ ایزد بگزاریم و به کس بد نکنیم','هوش مصنوعی: باید فرض کنیم که خداوند را در نظر داریم و به هیچکس آسیب نرسانیم و آنچه که دیگران می‌گویند صحیح نیست، ما هم نباید بگوییم که صحیح است.',NULL);
INSERT INTO "verses" VALUES(1936983,2149,6,1,'باده از خونِ رزان است، نه از خون شماست',NULL,NULL);
INSERT INTO "verses" VALUES(1936984,2149,4,0,'ما نه رندانِ ریاییم و حریفانِ نفاق','هوش مصنوعی: ما از کسانی نیستیم که به تظاهر و نفاق روی بیاوریم؛ آن کسی که رازها را می‌داند، بر این حالت ما شاهد است.',NULL);
INSERT INTO "verses" VALUES(1936985,2149,5,1,'وان چه گویند روا نیست، نگوییم رواست',NULL,NULL);
INSERT INTO "verses" VALUES(1936986,2149,3,0,'باده‌نوشی که در او روی و ریایی نَبُوَد','باده خوری که در کارش ریا نداشته باشد بهتر و ارزشمند تر از زاهدی است که به دنبال ریا و خودنمایی است',NULL);
INSERT INTO "verses" VALUES(1936987,2149,4,1,'آن‌که او عالِم سِرّ است، بدین حال گواست',NULL,NULL);
INSERT INTO "verses" VALUES(1936988,2149,2,0,'چه ملامت بُوَد آن را که چنین باده خورَد؟','چه مشکلی دارد اگر کسی این‌گونه (برای عبادت واقعی) شراب بنوشد؟ چه اشکالی است در جامعه که از بی خردی نشعت می‌گیرد؟ و این چه اشتباهی است؟',NULL);
INSERT INTO "verses" VALUES(1936989,2149,3,1,'بهتر از زهدفروشی که در او روی و ریاست',NULL,NULL);
INSERT INTO "verses" VALUES(1936990,2149,1,0,'نوبهٔ زهدفروشانِ گران‌جان بگذشت','زمانه ی آدم های ظاهرنما و خالی از عبادت قلبی و واقعی، گذشت و زمانه ی عبادت واقعی از سوی مومنان قلبی و واقعی شروع شده.',NULL);
INSERT INTO "verses" VALUES(1936991,2149,2,1,'این چه عیب است بدین بی‌خردی؟ وین چه خطاست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1936992,2149,0,0,'روزه یک‌سو شد و عید آمد و دل‌ها برخاست','هوش مصنوعی: ماه روزه به پایان رسید و عید فرارسید و شادی و نشاط در دل‌ها شکل گرفت. شراب از خمره به جوش آمد و اکنون زمان نوشیدن آن فرا رسیده است.',NULL);
INSERT INTO "verses" VALUES(1936993,2149,1,1,'وقتِ رندی و طرب کردنِ رندان پیداست',NULL,NULL);
INSERT INTO "verses" VALUES(1936994,2149,0,1,'می ز خُم‌خانه به‌جوش آمد و می‌ باید خواست',NULL,NULL);
INSERT INTO "verses" VALUES(1936999,2150,4,1,'به تماشایِ تو آشوبِ قیامت برخاست',NULL,NULL);
INSERT INTO "verses" VALUES(1937001,2150,5,0,'پیشِ رفتار تو پا برنگرفت از خِجلت','هوش مصنوعی: به خاطر شرمی که داشت، سرو زیبای مغرور نتوانست به سمت تو حرکت کند و از زیبایی قد و قامت تو تحت تاثیر قرار گرفت.',NULL);
INSERT INTO "verses" VALUES(1937002,2150,6,0,'حافظ این خرقه بینداز مگر جان ببری','حافظ می‌گوید این لباس روحانی را رها کن، اگر میخواهی جانت را نجات دهی . چرا که شعله‌ آتش از این لباس ظاهری و فریبنده برخاسته است.',NULL);
INSERT INTO "verses" VALUES(1937003,2152,3,1,'گناهِ بختِ پریشان و دستِ کوتهِ ماست',NULL,NULL);
INSERT INTO "verses" VALUES(1937004,2152,2,1,'هزار یوسفِ مصری، فتاده در چَهِ ماست',NULL,NULL);
INSERT INTO "verses" VALUES(1937005,2152,3,0,'اگر به زلفِ درازِ تو، دستِ ما نرسد','هوش مصنوعی: اگر ما نتوانیم به زلف‌های بلندی که داری دست پیدا کنیم، تقصیر بدشانسی ما و کوتاهی دست ماست.',NULL);
INSERT INTO "verses" VALUES(1937006,2152,1,1,'جمالِ چهرهٔ تو، حجّتِ موجّهِ ماست',NULL,NULL);
INSERT INTO "verses" VALUES(1937007,2152,2,0,'ببین که سیبِ زنخدانِ تو چه می‌گوید','هوش مصنوعی: ببین که زیبایی و جذابیت تو چه پیامی دارد، مانند هزار یوسف مصری که در دام عشق ما گرفتار شده‌اند.',NULL);
INSERT INTO "verses" VALUES(1937008,2152,0,1,'نسیمِ مویِ تو، پیوندِ جانِ آگهِ ماست',NULL,NULL);
INSERT INTO "verses" VALUES(1937009,2152,1,0,'به رَغمِ مدّعیانی که منعِ عشق کنند','هوش مصنوعی: با وجود کسانی که با عشق مخالفت می‌کنند، زیبایی چهرهٔ تو دلیل محکمی برای عشق ورزیدن ماست.',NULL);
INSERT INTO "verses" VALUES(1937010,2152,0,0,'خیالِ رویِ تو در هر طریق همرهِ ماست','تصور چهره‌ی تو همیشه در کنار ماست، و نسیمی که از موی تو به ما می‌رسد مانند پیوند و چسبی است که وجود آگاه ما را یکپارچه نگه می‌دارد.',NULL);
INSERT INTO "verses" VALUES(1937011,2151,9,0,'ندای عشق تو دیشب در اندرون دادند','دیشب بانگی از سر عشق تو در درون من طنین‌انداز شد؛ هنوز بازتاب و انعکاس آن فریاد در تمام فضای سینه‌ی من لبریز است(دیشب: مترادف با دوش و مراد و منظور روز ازل و ابتدای خلقت است)(حافظ تصویر شگفتی خلق کرده است؛ گویی فضای سینه‌اش همچون گنبد یا هر چیز دیگری است که فریاد عشقی که خداوند در درون آن طنین‌انداز کرده است،تمام آن فضا را در برگرفته است و بازتاب و پژواک آن هنوز ادامه دارد)',NULL);
INSERT INTO "verses" VALUES(1937012,2151,9,1,'فضایِ سینهٔ حافظ هنوز پر ز صداست',NULL,NULL);
INSERT INTO "verses" VALUES(1937013,2151,8,0,'چه ساز بود که در پرده می‌زد آن مطرب','مطرب چه ساز و نغمه ای در پشت پرده می‌نواخت (مطرب با چه سازی چنین نغمه و آهنگ به هنجاری میزد ) که با وجود اینکه عمر و سالیان زیادی از آن گذشت ، هنوز اندیشهٔ من پر از آن آرزوست(در پرده زدن: ایهام دارد؛ ۱. پشت پرده نواختن، در مجالس معمولا پرده­ای کشیده می‌شد تا نوازندگان در پشت آن می‌‌نشستند تا اهل مجلس راحت‌تر باشند. ۲. بر طبق اصول و هنجار نواختن)',NULL);
INSERT INTO "verses" VALUES(1937014,2151,8,1,'که رفت عمر و هنوزم دماغ پُر ز هواست',NULL,NULL);
INSERT INTO "verses" VALUES(1937015,2151,7,0,'از آن به دیرِ مغانم عزیز می‌دارند','آتش و حرارتی در دل من است که هرگز خاموش نخواهد شد؛ از همین رو در دیر مغان مرا عزیز و محترم به حساب می‌آورند(دیر مغان: آتشکده و عبادتگاه زرتشتیان؛ مترادف با کوی مغان، سرای مغان، در شعر حافظ دیر مغان نقطه مقابل ریا و تظاهر است)',NULL);
INSERT INTO "verses" VALUES(1937016,2151,7,1,'که آتشی که نمیرد، همیشه در دلِ ماست',NULL,NULL);
INSERT INTO "verses" VALUES(1937017,2151,6,0,'چنین که صومعه آلوده شد ز خونِ دلم','از ریاکاری و تظاهر اهل صومعه چنان آزرده شدم که اشک خونین من فضای صومعه را آلوده ساخته است، اگر برای پاک کردن و تطهیر من مرا با شراب بشویید کار درستی انجام داده‌اید(حق به دست شماست: ایهام، ؛ ۱. حق با شماست، ۲. شرابی که در دستان شماست و مرا با آن خواهید شست، خود حق است؛ چرا که این باده دقیقا نقطه مقابل ریاکاری و تظاهر است. ۳. تنی که در دستان شماست و قصد شستنش را دارید خود حق است و حق با اوست)',NULL);
INSERT INTO "verses" VALUES(1937018,2151,6,1,'گَرَم به باده بشویید، حق به دستِ شماست',NULL,NULL);
INSERT INTO "verses" VALUES(1937019,2151,5,0,'نخفته‌ام ز خیالی که می‌پزد دلِ من','به سبب وجود خیالات فراوانی که دل من آرزو به وجود می‌آورد، نتوانسته‌­ام بخوابم؛ گرفتار خمار وحشتناکی به اندازه صد شب هستم، شراب­خانه کجاست؟ تا این خمار را اندکی فرو بنشانم(خمار: سردردی که پس از خوردن شراب پدیدار می­گردد و با نوشیدن جامی دیگر برطرف می‌گردد)',NULL);
INSERT INTO "verses" VALUES(1937020,2151,5,1,'خمارِ صد شبه دارم شراب‌خانه کجاست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937021,2151,4,0,'مرا به کارِ جهان هرگز التفات نبود','من هرگز به دنیا و وابستگی های آن هیچ گونه توجه ای نداشتم ، اما چهرهٔ زیبای تو این دنیا را برای من زیبا و مطلوب جلوه داده است',NULL);
INSERT INTO "verses" VALUES(1937022,2151,4,1,'رخِ تو در نظرِ من چنین خوشش آراست',NULL,NULL);
INSERT INTO "verses" VALUES(1937023,2151,3,0,'دلم ز پرده برون شد، کجایی ای مطرب؟','راز دلم آشکار و من رسوا گشتم و یا دل من آهنگ و نغمه‌ی حقیقی خود را فراموش کرد؛ هان ای مطرب کجایی؟ فریاد کن چرا که از نغمه توست که حال و کار ما به سامان می‌رسد(از پرده شدن دل: ایهام دارد؛ ۱. رسوا گشتن، ۲. از نغمه و آهنگ به هنجار خود خارج شدن)',NULL);
INSERT INTO "verses" VALUES(1937024,2151,3,1,'بنال، هان که از این پرده، کارِ ما به نواست',NULL,NULL);
INSERT INTO "verses" VALUES(1937025,2151,2,0,'در اندرونِ منِ خسته‌دل ندانم کیست!','نمی‌دانم در وجود من دل‌خسته چه کسی هست، چرا که باوجود خاموش بودن من او هنوز مشغول بانگ و فریاد و جوش و خروش است(نکته: در ذهن و باور قدما این اعتقاد وجود داشت که شاعر در سرودن شعر هیچ‌گونه اختیار و اراده‌­ای ندارد بلکه نیرویی درونی او را به سرودن شعر وا می‌­دارد؛ اعراب جاهلی باور داشتند جن و یا پری در درون آنها به آنها شعر تلقین می‌کنند و آن را تابعه می‌نامیدند)',NULL);
INSERT INTO "verses" VALUES(1937026,2151,2,1,'که من خموشم و او در فغان و در غوغاست',NULL,NULL);
INSERT INTO "verses" VALUES(1937027,2151,1,0,'سرم به دنیی و عقبی فرو نمی‌آید','چنان شور و فتنه‌های عجیب و شگفتی در سرم وجود دارد که حاضر نیستم تسلیم نعمت­‌های این­ جهانی و آن­ جهانی شوم',NULL);
INSERT INTO "verses" VALUES(1937028,2151,1,1,'تبارک الله ازین فتنه‌ها که در سرِ ماست',NULL,NULL);
INSERT INTO "verses" VALUES(1937029,2151,0,0,'چو بشنوی سخنِ اهلِ دل، مگو که خطاست','وقتی کلام و اندیشه‌ی عاشقان و عارفان را می‌شنوی مگو که سخن و اندیشه‌­ای اشتباه است؛ در واقع خطا و اشتباه اصلی اینجاست که تو هنوز سخن و اندیشه‌ی درست را تشخیص نداده‌­ای',NULL);
INSERT INTO "verses" VALUES(1937030,2151,0,1,'سخن‌شناس نه‌ای، جان من! خطا این جاست',NULL,NULL);
INSERT INTO "verses" VALUES(1937031,2150,6,1,'کآتش از خرقهٔ سالوس و کرامت برخاست',NULL,NULL);
INSERT INTO "verses" VALUES(1937032,2150,5,1,'سروِ سرکش که به ناز از قد و قامت برخاست',NULL,NULL);
INSERT INTO "verses" VALUES(1937040,2131,0,0,'صلاحِ کار کجا و منِ خراب کجا؟','فاصله‌ی زیادی میان ِ صلاح ِ کار و من ِ مست و خراب هست. ببین که تفاوت ِ ره (فاصله) از کجا به کجاست! من کجا و مصلحت‌اندیشی کجا؟',NULL);
INSERT INTO "verses" VALUES(1937041,2131,0,1,'ببین تفاوتِ رَه کز کجاست تا به کجا',NULL,NULL);
INSERT INTO "verses" VALUES(1937042,2131,1,0,'دلم ز صومعه بگرفت و خِرقِهٔ سالوس','از صومعه (عبادت‌گاه صوفیان) و خرقه‌ی فریبکاری ایشان دلم گرفت. به دنبال دیر مغان می‌گردم و شراب ناب که به آن‌جا پناه ببرم و این دل‌گیری و دل‌تنگی خود را آن‌جا فروشویم یا بازگویم.',NULL);
INSERT INTO "verses" VALUES(1937043,2131,1,1,'کجاست دِیرِ مُغان و شرابِ ناب کجا؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937044,2131,2,0,'چه نسبت است به‌ رِندی صَلاح و تقوا را؟','رندی چه نسبتی با صلاح و تقوا می‌تواند داشته باشد؟ تناسبی با هم ندارند! گوش دادن به موعظه کجا و آواز و آهنگ و آوایِ خوش ساز (رباب) کجا؟',NULL);
INSERT INTO "verses" VALUES(1937045,2131,2,1,'سماعِ وَعظ کجا نغمهٔ رَباب کجا؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937046,2131,3,0,'ز رویِ دوست دلِ دشمنان چه دریابد؟','دل ِ دشمنان چه ادراک و فهمی از رویِ دوست می‌تواند داشته باشد؟ چنان‌که چراغ خاموش نمی‌تواند شمع آفتاب را دریابد. دل دشمنان هم نمی‌تواند رویِ دوست را درک کند.',NULL);
INSERT INTO "verses" VALUES(1937047,2131,3,1,'چراغِ مُرده کجا؟ شمعِ آفتاب کجا؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937048,2131,4,0,'چو کُحلِ بینشِ ما خاکِ آستانِ شماست','خاک درگاه شما مانند همان سرمه‌ای است که به چشم می‌کشم تا نور چشمم زیاد شود. [دست‌کم] بفرمایید بگویید که از این جناب (آستانه‌ی خانه شما) به کجا برویم؟',NULL);
INSERT INTO "verses" VALUES(1937049,2131,4,1,'کجا رَویم بفرما ازین جناب، کجا؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937050,2131,5,0,'مَبین به سیبِ زَنَخدان که چاه در راه است','به طمع سیب زنخدان (اشاره به چانه‌ی یار) گمراه نشو که چاه در راه است (راه دشوار است). ای دل من، [که مرا همراهت می‌بری] با این شتاب به کجا می‌روی؟',NULL);
INSERT INTO "verses" VALUES(1937051,2131,5,1,'کجا همی‌ رَوی ای دل بدین شتاب کجا؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937052,2131,6,0,'بِشُد! که یادِ خوشش باد روزگارِ وصال','روزگار وصال گذشت و رفت! یادش به‌خیر! آن ناز و غمزه و کرشمه کجا رفت و آن سرزنش و عتاب کجا؟ دل شاعر برای روزگار وصال و هم کرشمه و هم عتاب معشوق تنگ شده است.',NULL);
INSERT INTO "verses" VALUES(1937053,2131,6,1,'خود آن کِرِشمه کجا رفت و آن عِتاب کجا؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937054,2131,7,0,'قرار و خواب ز حافظ طمع مدار ای دوست','از حافظ انتظار قرار و خواب نداشته باش. قرار چیست؟ صبوری کدام است و خواب کجاست؟ و در معنای دوگانه‌ی قرار، هم می‌توان گفت که انتظار آرامش و آسودگی و خواب نداشته باش. و هم تکرار قرار در مصراع دوم، معنای پیمان‌شکنی را به ذهن می‌آورد. یعنی انگار که حافظ عهد کرده بود که آرام باشد و بیاساید، اما اکنون می‌گوید که قرار چیست؟ یعنی زیر قرار و عهد خود می‌زند! می‌گوید کدام قرار؟ صبوری ندارم که بر عهدی که ببندم وفا کنم و بر آن صابر باشم.',NULL);
INSERT INTO "verses" VALUES(1937055,2131,7,1,'قرار چیست صبوری کدام و خواب کجا؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937056,2132,0,0,'اگر آن تُرکِ شیرازی به‌‌ دست‌ آرَد دلِ ما را','اگر آن ترک ِ شیرازی دل ِ ما (من) را به دست آورد، سمرقند و بخارا را به خال ِ سیاه ِ او خواهم بخشید.',NULL);
INSERT INTO "verses" VALUES(1937057,2132,0,1,'به خال هِندویَش بَخشَم سَمَرقند و بُخارا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937058,2132,1,0,'بده ساقی مِیِ باقی که در جَنَّت نخواهی یافت','ای ساقی! باقی‌مانده‌یِ می را هم بده که بنوشم. که در بهشت هم جایی به این خوبی برایِ می نوشیدن نخواهی یافت. می باقی را علاوه بر این معنا، می‌توان به می ِ جاودانی (باقی) تعبیر کرد و این تلقی با جنّت (بهشت) تناسب دارد. هم‌چنین با عنایت به این که در مصراع ِ دوم، کنار ِ آب ِ رکن‌آباد و گل‌گشت ِ مصلّا را با بهشت مقایسه کرده و از بهشت هم برتر دانسته، می‌توان برداشت کرد که از ساقی می‌خواهد که برای ِ او، می ِ باقی (می ِ جاودان، می ِ بهشتی) بیاورد. نوعی اغراق که یعنی می ِ این‌جهانی، در خور ِ این مکانی که از بهشت برتر است نیست! و باید از آن می نوشید که در بهشت هست. هم‌چنین می‌شود گفت شاعر می ِ ساقی را به می ِ باقی تشبیه کرده است.',NULL);
INSERT INTO "verses" VALUES(1937059,2132,1,1,'کنارِ آبِ رُکناباد و گُل‌گَشتِ مُصَلّا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937060,2132,2,0,'فَغان! کاین لولیانِ شوخِ شیرین‌کارِ شهرآشوب','ای فغان! که این لولیان شوخ و شیرین‌کار و شهر آشوب چنان صبر از دل بردند که انگاری ترکان خوان یغما را می برند (سفره را غارت می کنند.) این بیت، اشاره‌یِ ملیحی به غارت ِ ترکان و تصرّف سمرقند و بخارا هم می‌تواند باشد که در بیت پیشین به آن اشاره شده بود. لولیان شوخ شیرین کار شهرآشوب استعاره از زیبارویان است که دل حافظ را غارت کرده و به یغما برده‌اند. لولی یا کولی ؛ اینجا مجازاً زیبارویان ترک است.',NULL);
INSERT INTO "verses" VALUES(1937061,2132,2,1,'چُنان بُردند صبر از دل که تُرکان خوانِ یَغما را',NULL,NULL);
INSERT INTO "verses" VALUES(1937062,2132,3,0,'ز عشقِ ناتمامِ ما جمالِ یار مُستَغنی‌ است','همان‌طور که رویِ زیبا نیازی به آرایش و بَزَک (آب و رنگ و خال و خط) ندارد، جمال ِ یار، نیازی به عشق ِ بی‌کمال و بی‌ارزش ِ من ندارد. آب و رنگ و خال و خط، در اشاره به اسباب ِ آرایش‌گری آمده. سرخاب و سفیداب و رنگ و خط و خال. مشّاطه‌ها (هم برای زیبایی و هم برای این‌که مشک و مواد ِ خوش‌بو را به صورت ِ یار بنهند) روی صورت خال می‌کشیدند.',NULL);
INSERT INTO "verses" VALUES(1937063,2132,3,1,'به آب و رنگ و خال و خط چه حاجت رویِ زیبا را؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937064,2132,4,0,'مَن از آن حُسنِ روزاَفزون که یوسُف داشت دانستم','عشق باعث شد که زلیخا از پرده‌ی عصمت برون آید. من این را از زیبایی ِ روز‌افزون ِ یوسف دانستم (فهمیدم؛ متوجه شدم). پرده‌یِ عصمت می‌تواند «اضافه‌ی اقترانی» باشد. علاوه بر این که می توان «عصمت» را به «پرده» تشبیه کرد. نخست این که زنان در قصر و بارگاه پرده‌نشین بودند',NULL);
INSERT INTO "verses" VALUES(1937079,2147,6,0,'حافظ از دست مده دولت این کشتی نوح','ای حافظ، مصاحبت این کشتی نوح را از دست مده یعنی همنشینی باده‌نوشان را ترک مکن. وگرنه طوفان حوادث، بنیاد وجودت را از بین می‌برد. یعنی از باده جدا مشو ، وگرنه تمام غم ها و هموم بلیّات روزگار ، بنیاد وجودت را تلف می کند . (کشتی نوح= منظور قدحی است به شکل قایق که بعضی اشخاص آن را از نقره و بعضی از شاخ گاو و بعضی از چوب می‌سازند).',NULL);
INSERT INTO "verses" VALUES(1937080,2147,6,1,'ور نه طوفانِ حوادث بِبَرَد بُنیادت',NULL,NULL);
INSERT INTO "verses" VALUES(1937081,2147,5,0,'چشمِ بد دور کز آن تفرقه‌ات بازآورد','چشم بد از تو دور که طالع نیک و بخت بلندت، تو را از آن تفرقه و جدایی به پیش ما باز آورد.',NULL);
INSERT INTO "verses" VALUES(1937082,2147,5,1,'طالعِ ناموَر و دولتِ مادرزادت',NULL,NULL);
INSERT INTO "verses" VALUES(1937083,2152,4,0,'به حاجبِ درِ خلوت‌سرایِ خاص بگو','هوش مصنوعی: به نگهبان درِ کاخ مخصوص بگو که فلانی از میان کسانی است که در گوشه‌ای از خاکِ این درگاه نشسته‌اند.',NULL);
INSERT INTO "verses" VALUES(1937084,2147,4,0,'شکر ایزد که ز تاراجِ خزان رخنه نیافت','شکر خدا که بوستان سمن و سرو و گل و شمشاد تو از بادِ خزان در امان ماند (شاید مقصود از زیبایی و جوانی است که از تاراج سختی روزگار مدیری در امان مانده است).',NULL);
INSERT INTO "verses" VALUES(1937085,2147,3,0,'شادی مجلسیان در قدم و مقدم توست','شادی و سرور اهل مجلس، در قدوم مبارک توست. جای غم باشد هر آن دلی که تو را شاد نخواهد. یعنی غمگین باشد هر دلی که شادی و خندانی تو را نخواهد.',NULL);
INSERT INTO "verses" VALUES(1937086,2147,3,1,'جای غم باد، مَر آن دل که نخواهد شادت',NULL,NULL);
INSERT INTO "verses" VALUES(1937087,2147,2,0,'برسان بندگیِ دختر رَز، گو به درآی','ای ساقی! بندگی ما را خدمت دختر رز برسان و بگو که بیرون آی. یعنی اخنفاء را ترک کن که دَمِ همت ما تو را از غم آزاد کرد. حضرت خواجه این معنا را با کنایه تعبیر می‌فرمایند. (بندگی= خدمت . رَز= درخت انگور است و دختر رَز کنایه از شراب است ) (توضیح: ماه حرام ربطی به شراب ندارد و عید همایونی هم شاهدی در کلام حافظ ندارد. چنان که در پیغام اهل راز آمده است: از آمدن عيد و شادى و عيش حاصل از رو کردن بخت به محبوب يا ممدوح حکايت مى‌کند.)',NULL);
INSERT INTO "verses" VALUES(1937088,2147,2,1,'که دَم و همّت ما کرد ز بند، آزادت',NULL,NULL);
INSERT INTO "verses" VALUES(1937089,2147,1,0,'در شگفتم که در این مدّتِ ایّامِ فِراق','در تعجبم ه چگونه در این مدت فراق که از حریفان دل برگرفتی، این جدایی و روی‌گردانی را دلت هم قبول کرد. یعنی در این مدت که در حال اختفاء بودی و به حریفان، دیدار نشان نمی دادی، تعجب می‌کنم که چگونه دلت این را تحمل کرد. (شگفت= تعجب،‌ برگرفتی ز حریفان دل= از حریفان دل کندی، دل می‌دادت= دلت اجازه می‌داد)',NULL);
INSERT INTO "verses" VALUES(1937090,2147,1,1,'برگرفتی ز حریفان دل و دل می‌دادت',NULL,NULL);
INSERT INTO "verses" VALUES(1937091,2147,0,0,'ساقیا آمدنِ عید مبارک بادت','ای ساقی آمدن عید مبارکت باشد و آن وعده‌ها که به من داده از خاطرت نرود. (مواعید = جمع موعود به معنی چیزی که وعده داده شده)',NULL);
INSERT INTO "verses" VALUES(1937092,2147,0,1,'وان مَواعید که کردی مَرَوَد از یادت',NULL,NULL);
INSERT INTO "verses" VALUES(1937099,2147,4,1,'بوستانِ سمن و سرو و گل و شمشادت',NULL,NULL);
INSERT INTO "verses" VALUES(1937100,2152,4,1,'فُلان ز گوشه‌نشینانِ خاکِ درگهِ ماست',NULL,NULL);
INSERT INTO "verses" VALUES(1937101,2152,5,0,'به صورت از نظر ما اگر چه محجوب است','هوش مصنوعی: با این که او به خاطر ظاهرش از دید ما پنهان است، اما همیشه در خاطرات خوش و دلنشین ما حضور دارد.',NULL);
INSERT INTO "verses" VALUES(1937102,2152,5,1,'همیشه در نظرِ خاطرِ مرفّهِ ماست',NULL,NULL);
INSERT INTO "verses" VALUES(1937105,2158,8,0,'حافظ چه شد ار عاشق و رند است و نظرباز','چه ایرادی بر رندی و عاشقی و نظربازی حافظ هست؟ جوانی‌، این حالات را با خود دارد.',NULL);
INSERT INTO "verses" VALUES(1937106,2158,8,1,'بس طُورِ عجب لازمِ ایامِ شباب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937107,2158,7,0,'در کُنجِ دِماغم مطلب جای نصیحت','در مغز من جایی برای پند وجود ندارد چون پُر از نغمه شاد چنگ و رباب و آهنگ و ترانه است.',NULL);
INSERT INTO "verses" VALUES(1937108,2158,7,1,'کـ‌این گوشه پر از زمزمهٔ چنگ و رَباب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937109,2158,6,0,'سبز است در و دشت بیا تا نگذاریم','تا بهار و خرمی است بیا کنار جویبار را از دست ندهیم که دنیا خیال و سرابی بیش نیست.',NULL);
INSERT INTO "verses" VALUES(1937110,2158,6,1,'دست از سرِ آبی که جهان جمله سراب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937111,2158,5,0,'گل بر رخِ رنگین تو تا لطفِ عرق دید','وقتی‌که گل‌، زیبایی شبنم روی تو را دید از عشق تو دلش پر آتش گشت و غرق گلاب شد.',NULL);
INSERT INTO "verses" VALUES(1937112,2158,5,1,'در آتشِ شوق از غمِ دل، غرقِ گلاب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937113,2158,4,0,'معشوق عیان می‌گذرد بر تو، ولیکن','یار بر تو آشکارا می‌گذرد اما اغیار را دیده است و رخ نمی‌نماید.',NULL);
INSERT INTO "verses" VALUES(1937114,2158,4,1,'اغیار همی‌بیند از آن بسته نقاب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937115,2158,3,0,'بیدار شو ای دیده که ایمن نتوان بود','منظور از دیده: چشم. ای چشم من از خواب بیدار شو و مراد از سیل دمادم، اشک ریختن بسیار است.منزل خواب: چشم. ای چشم من بیدار شو که از اینهمه اشک ریزی امانی نیست',NULL);
INSERT INTO "verses" VALUES(1937116,2158,3,1,'زین سیلِ دمادم که در این منزلِ خواب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937117,2158,2,0,'افسوس که شُد دلبر و در دیدهٔ گریان','حیف که یارم رفت و خیال دیدن او بیهوده است.',NULL);
INSERT INTO "verses" VALUES(1937118,2158,2,1,'تحریرِ خیالِ خطِ او نقشِ بر آب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937119,2158,1,0,'گر خَمر بهشت است بریزید که بی دوست','حتی شراب بهشتی را نیز میاورید که بی محبوبم بهترین شراب هم لذتی ندارد. (عَذْب‌: گوارا)',NULL);
INSERT INTO "verses" VALUES(1937120,2158,1,1,'هر شَربَتِ عَذبَم که دهی، عینِ عذاب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937121,2158,0,0,'ما را زِ خیالِ تو چه پروایِ شراب است؟','ما با خیال تو مستیم و به‌شراب نیاز نداریم به خُم بگو که پی کار خود گیر و برو که خمخانه تو بی‌رونق شد.',NULL);
INSERT INTO "verses" VALUES(1937122,2158,0,1,'خُم گو سر خود گیر، که خُمخانه خراب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937123,2157,7,0,'مرنج حافظ و از دلبر‌ان حِفاظ مجوی','ای حافظ از دلبران توقع مهربانی نداشته‌باش؛ گناه باغ چیست وقتی‌که این گیاه نروید. (یا گیاه مهربانی دلبران از اول وجود نداشته‌است)',NULL);
INSERT INTO "verses" VALUES(1937124,2157,7,1,'گناه باغ چه باشد چو این گیاه نَرُست',NULL,NULL);
INSERT INTO "verses" VALUES(1937125,2157,6,0,'شدم ز دست تو شیدای کوه و دشت و هنوز','از عشق تو‌، دیوانه شده و سر به‌ بیابان نهاده‌ام اما تو هنوز رحم نمی‌کنی و زنجیری را که بر من نهاده‌ای‌، رها نمی‌کنی. (نطاق: یعنی قفل‌بند‌، سلسله‌: یعنی زنجیر و در شعر کنایه‌است از زلف بافته معشوق)',NULL);
INSERT INTO "verses" VALUES(1937126,2157,6,1,'نمی‌کنی به ترحم، نِطاق سلسله سست',NULL,NULL);
INSERT INTO "verses" VALUES(1937127,2157,5,0,'به صدق کوش، که خورشید زایَد از نَفَسَت','صداقت و یک‌رنگی را پیشه‌کن که از راستگویی تو‌، خورشید طلوع خواهد کرد؛ صبح اول از دروغ بود که بی‌آبرو شد.',NULL);
INSERT INTO "verses" VALUES(1937128,2157,5,1,'که از دروغ سیه‌روی گشت صبحِ نخست',NULL,NULL);
INSERT INTO "verses" VALUES(1937129,2157,4,0,'دلا طَمَع مَبُر از لطفِ بی‌نهایتِ دوست','ای دل غمگین من، از لطف دوست ناامید مشو؛ وقتی که لاف عشق زدی‌، به‌آسانی سر بباز.',NULL);
INSERT INTO "verses" VALUES(1937130,2157,4,1,'چو لافِ عشق زدی، سر بباز، چابک و چُست',NULL,NULL);
INSERT INTO "verses" VALUES(1937131,2157,3,0,'زبان مور به آصف دراز گشت و رواست','مورچه‌ای به آصف طعنه زد و بجاست که اگر یار، انگشتری جم را گم کرد و نیافت. (شاعر در اینجا خود را به موری تشبیه‌کرده که به سلیمان اعتراض کرد، و گم‌شدن انگشتر شاهی نیز اشاره به‌داستان سلیمان است.)',NULL);
INSERT INTO "verses" VALUES(1937136,2161,1,0,'مرا و سروِ چمن را به خاکِ راه نشاند','قصب نرگس قبا‌: لباس سپید و لطیف؛ کنایه است از لطافت و روشنی تن محبوب.',NULL);
INSERT INTO "verses" VALUES(1937137,2161,1,1,'زمانه تا قَصَبِ نرگسِ قبای تو بست',NULL,NULL);
INSERT INTO "verses" VALUES(1937138,2161,0,0,'خدا چو صورتِ ابرویِ دلگشای تو بست','آن روز که خدا ابروی زیبای تو را نقش زد و آفرید، در همان ازل، گشودن گره کار من را در کرشمه‌ها و نازهای تو نهاد.',NULL);
INSERT INTO "verses" VALUES(1937139,2161,0,1,'گشادِ کارِ من اندر کرشمه‌هایِ تو بست',NULL,NULL);
INSERT INTO "verses" VALUES(1937140,2160,8,0,'آبِ حیوانش ز منقارِ بلاغت می‌چکد','آب زندگانی و حیات جاودان از منقار زاغ سیه قلم بلاغت من می‌چکد، چشم بد از او دور بادا! چه عالی‌نظر است.',NULL);
INSERT INTO "verses" VALUES(1937141,2160,8,1,'زاغِ کِلکِ من بنامیزد چه عالی مشرب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937142,2160,7,0,'آن که ناوَک بر دلِ من زیرِ چشمی می‌زند','آنکه تیر و ناوک غمزه بر دل من پنهانی می‌زند، روزی و غذای جان حافظ را نیز با خنده‌های پنهانی می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1937143,2160,7,1,'قوتِ جانِ حافظش در خندهٔ زیر لب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937144,2160,6,0,'اندر آن ساعت که بر پشتِ صبا بندند زین','در آن ساعت و دم که بر پشت صبا و نسیم سوار می‌شوند چطور می‌توانم همراه سلیمان بتازم وقتی که موری مرکب من است؟',NULL);
INSERT INTO "verses" VALUES(1937145,2160,6,1,'با سلیمان چون برانم من که مورم مرکب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937146,2160,5,0,'من نخواهم کرد تَرکِ لعلِ یار و جام می','من هرگز بوسه لب یار و جام می و مستی را رها نخواهم کرد، ای زاهد مرا معذور بدار که مذهب و کیش من همین است.',NULL);
INSERT INTO "verses" VALUES(1937147,2160,5,1,'زاهدان معذور داریدم که اینَم مذهب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937148,2160,4,0,'عکسِ خِوی بر عارضَش بین کآفتابِ گرم رو','ببین قطره‌های عرق و شبنم که بر روی اوست چه زیباست که آفتاب در هوای چشیدن آن گلاب‌، تشنه است و هر روز تب می‌کند.',NULL);
INSERT INTO "verses" VALUES(1937149,2160,4,1,'در هوایِ آن عَرَق تا هست هر روزش تب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937150,2157,3,1,'که خواجه خاتَمِ جم، یاوه کرد و باز نَجُست',NULL,NULL);
INSERT INTO "verses" VALUES(1937151,2160,3,0,'شهسوارِ من که مه آیینه دارِ روی اوست','شهسوار و ماه یگانه من که غلام اوست تاج خورشید آسمان، خاک مرکب و اسب اوست.',NULL);
INSERT INTO "verses" VALUES(1937152,2160,2,0,'کشته چاه زنخدان توام کز هر طرف','کشته مرده زیبایی چانه و چاه زنخندان تو هستم که در گرد آن چاه و غبغب، هزاران عاشق اسیر گشته‌اند.',NULL);
INSERT INTO "verses" VALUES(1937153,2160,2,1,'صد هزارش گردنِ جان زیرِ طوقِ غَبغَب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937154,2160,1,0,'تا به گیسویِ تو دستِ ناسزایان کم رسد','برای آنکه دست نالایقان به وصال گیسوی تو نرسد، هر دلی در این شب و هرکس در هر محفل در ذکر یارب یارب است.',NULL);
INSERT INTO "verses" VALUES(1937155,2160,1,1,'هر دلی از حلقه‌ای در ذکرِ یارب یارب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937156,2160,0,0,'آن شبِ قدری که گویند اهلِ خلوت امشب است','آن شب قدر که اهل خلوت و عبادت از آن می‌گویند امشب است، خدایا این سعادت از تاثیر کدام کوکب و ستاره است؟',NULL);
INSERT INTO "verses" VALUES(1937157,2160,0,1,'یا رب این تأثیرِ دولت در کدامین کوکب است؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937166,2160,3,1,'تاجِ خورشیدِ بلندش خاکِ نعلِ مَرکَب است',NULL,NULL);
INSERT INTO "verses" VALUES(1937167,2132,4,1,'که عشق از پردهٔ عِصمت بُرون آرَد زُلِیخا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937168,2157,2,0,'بکن معامله‌ای، وین دل شکسته بخر','بیا و دل شکسته من را بخر که ارزش آن از صدهزار دل سالم و بی‌درد بیشتر است.',NULL);
INSERT INTO "verses" VALUES(1937169,2157,1,0,'سِرِشک من که ز طوفان نوح دست بَرَد','اشک‌های من که از طوفان نوح پیشی گرفت نیز نتوانسته‌است که یاد و مهر تو را از سینه‌ام بشوید.',NULL);
INSERT INTO "verses" VALUES(1937170,2154,6,0,'شکوهِ آصِفی و اسبِ باد و منطقِ طیر','شکوه و عظمت شاهی آصفی و سوار شدن بر باد و دانایی زبان پرندگان همه بر باد رفت، و خواجه از آن سودی نکرد.',NULL);
INSERT INTO "verses" VALUES(1937171,2154,5,1,'که نیستی‌ست سرانجامِ هر کمال که هست',NULL,NULL);
INSERT INTO "verses" VALUES(1937172,2154,4,1,'بلی به حکمِ بلا بسته‌اند عهدِ الست',NULL,NULL);
INSERT INTO "verses" VALUES(1937173,2154,5,0,'به هست و نیست مَرنجان ضمیر و خوش می‌باش','دل را در غم هست و نیست مرنجان و غمگین مشو‌، به جای این، سعی کن خوشحال باشی، زیرا در نهایت هر چیزی که به کمال می‌رسد، روزی نابود خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1937174,2154,3,1,'رِواق و طاقِ معیشت، چه سربلند و چه پست',NULL,NULL);
INSERT INTO "verses" VALUES(1937175,2154,4,0,'مقام عیش میسر نمی‌شود بی‌رنج','رسیدن به خوشی و کامروایی، بدون تحمل رنج و زحمت، ممکن نیست. بلا و سختی را از روز الست در تقدیر نهاده‌اند.',NULL);
INSERT INTO "verses" VALUES(1937176,2154,2,1,'چه پاسبان و چه سلطان، چه هوشیار و چه مست',NULL,NULL);
INSERT INTO "verses" VALUES(1937177,2154,3,0,'از این رِباط دو در، چون ضرورت است رَحیل','در این کاروان‌سرای دو در دنیا (مرگ و تولد) وقتی که همه موقتی و گذرا هستند چه دارا و چه بی‌چیز باشی.',NULL);
INSERT INTO "verses" VALUES(1937178,2154,1,1,'ببین که جامِ زُجاجی چه طُرفه‌اش بشکست',NULL,NULL);
INSERT INTO "verses" VALUES(1937179,2154,2,0,'بیار باده که در بارگاهِ استغنا','باده بیاور که در محفل بی‌نیازی، چه نگهبان و چه پادشاه، چه هوشیار و چه باده‌نوش همه یکی هستند.',NULL);
INSERT INTO "verses" VALUES(1937180,2154,0,1,'صَلایِ سرخوشی، ای صوفیانِ باده پرست',NULL,NULL);
INSERT INTO "verses" VALUES(1937181,2154,1,0,'اساسِ توبه که در محکمی چو سنگ نُمود','بنیاد توبه که مانند سنگی محکم است، ببین که چگونه یک لیوان شیشه‌ای به راحتی آن‌را می‌شکند.',NULL);
INSERT INTO "verses" VALUES(1937182,2154,0,0,'شکفته شد گل حَمرا و گشت بلبل مست','هوش مصنوعی: گل سرخ شکفته شده و بلبل در خوشحالی به سر می‌برد. ای صوفیانی که به شوق نوشیدن باده هستید!',NULL);
INSERT INTO "verses" VALUES(1937183,2153,6,0,'حافظ از دولت عشق تو سلیمانی شد','هوش مصنوعی: حافظ به خوشبختی و بزرگی خود به خاطر عشق تو اشاره می‌کند. او بیان می‌کند که هیچ گاه به جز آرامش و نسیم عشق تو به هیچ چیز دیگری نمی‌رسد. این عشق برای او مانند قدرت سلیمان است، اما آنچه که از وصال تو می‌یابد، تنها همان نسیم لطیف است.',NULL);
INSERT INTO "verses" VALUES(1937184,2153,6,1,'یعنی از وصل تواَش نیست بجز باد به دست',NULL,NULL);
INSERT INTO "verses" VALUES(1937185,2153,5,0,'جان فدای دهنش باد که در باغ نظر','هوش مصنوعی: جانم فدای لب او باد که در باغ احساس، زیباتر از این گل، چیزی وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1937186,2153,5,1,'چمن آرای جهان، خوشتر از این غنچه نبست',NULL,NULL);
INSERT INTO "verses" VALUES(1937187,2153,4,0,'بجز آن نرگس مستانه که چشمش مرساد','هوش مصنوعی: تنها نرگس مستانه‌ای که چشمش به من می‌افتد، زیر این درختان فیروزه‌ای هیچ‌کس دیگر به دل نمی‌نشیند.',NULL);
INSERT INTO "verses" VALUES(1937188,2153,4,1,'زیر این طارم فیروزه کسی خوش ننشست',NULL,NULL);
INSERT INTO "verses" VALUES(1937189,2153,3,0,'کمر کوه کم است از کمر مور اینجا','هوش مصنوعی: کمر کوه به اندازه کمر یک مور است، اینجا ناامید نشو و از در رحمت دور نمانید، ای عاشق شراب.',NULL);
INSERT INTO "verses" VALUES(1937190,2153,3,1,'ناامید از در رحمت مشو ای باده‌پرست',NULL,NULL);
INSERT INTO "verses" VALUES(1937191,2153,2,0,'می بده تا دهمت آگهی از سِرّ قضا','هوش مصنوعی: به من نوشیدنی بده تا بگویم به چه دلیلی عاشق شدم و از کدام بوی خوش مست و سرمست شدم.',NULL);
INSERT INTO "verses" VALUES(1937192,2153,2,1,'که به روی که شدم عاشق و از بوی که مست',NULL,NULL);
INSERT INTO "verses" VALUES(1937193,2153,1,0,'من همان دم که وضو ساختم از چشمهٔ عشق','زمانی که برای وصال خود را با عشق اماده و پاکیزه کردم؛ از هر چیزی غیر از عشق دست کشیدم و پاک شدم',NULL);
INSERT INTO "verses" VALUES(1937194,2153,1,1,'چار تکبیر زدم یکسره بر هرچه که هست',NULL,NULL);
INSERT INTO "verses" VALUES(1937195,2153,0,0,'مطلب طاعت و پیمان و صلاح از من مست','«از من انتظار نداشته باش مثل آدم‌های ظاهراً زاهد و مطیع رفتار کنم؛ من از همان ابتدا دل به عشق داده‌ام و راه خودم را رفته‌ام.»',NULL);
INSERT INTO "verses" VALUES(1937196,2153,0,1,'که به پیمانه‌کشی شهره شدم روز الست',NULL,NULL);
INSERT INTO "verses" VALUES(1937197,2152,6,1,'که سال‌هاست که مشتاقِ رویِ چون مهِ ماست',NULL,NULL);
INSERT INTO "verses" VALUES(1937198,2152,6,0,'اگر به سالی حافظ دری زَنَد، بگشای','هوش مصنوعی: اگر حافظ روزی به در ورودی بیاید، در را باز کن، زیرا سال‌هاست که او مشتاق چهره‌ای مانند چهره‌ی زیبا و ماهی توست.',NULL);
INSERT INTO "verses" VALUES(1937199,2154,6,1,'به باد رفت و از او خواجه هیچ طَرف نبست',NULL,NULL);
INSERT INTO "verses" VALUES(1937200,2154,7,0,'به بال و پَر مرو از ره که تیرِ پرتابی','همچون تیر پرتابی پرشتاب مباش و کمی آرام‌تر باش که تیر نیز، زمانی در اوج هوا می‌رود ولی در نهایت بر خاک می‌نشیند.',NULL);
INSERT INTO "verses" VALUES(1937201,2154,7,1,'هوا گرفت زمانی، ولی به خاک نشست',NULL,NULL);
INSERT INTO "verses" VALUES(1937202,2154,8,0,'زبانِ کِلکِ تو حافظ چه شُکرِ آن گوید','ای حافظ، قلم تو چطور می‌تواند شکر این نعمت را بگوید که شعرت را دست به‌دست به همه‌جا می‌برند.',NULL);
INSERT INTO "verses" VALUES(1937203,2157,1,1,'ز لوح سینه نیارَست نقشِ مهرِ تو شُست',NULL,NULL);
INSERT INTO "verses" VALUES(1937204,2157,0,0,'به جانِ خواجه و حقِ قدیم و عهدِ درست','به جان تو و به دوستی دیرینه ما قسم که هر صبح‌گاه برای نیکبختی تو دعا می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1937205,2157,0,1,'که مونسِ دمِ صبحم، دعایِ دولتِ توست',NULL,NULL);
INSERT INTO "verses" VALUES(1937206,2156,5,0,'بازآی که بازآید عمرِ شدهٔ حافظ','برگرد تا عمر تلف شده و از دست رفته حافظ برگردد هرچند میدانم تیری که رها بشود دیگر باز نمی‌گردد',NULL);
INSERT INTO "verses" VALUES(1937207,2156,5,1,'هرچند که ناید باز، تیری که بِشُد از شست',NULL,NULL);
INSERT INTO "verses" VALUES(1937208,2156,4,0,'گر غالیه خوش بو شد، در گیسویِ او پیچید','اگر مشک خوش بو است به این دلیل است که در گیسوی معشوق رفته است و اگر گیاه وسمه برای آرایش ابرو استفاده میشود به این دلیل است که بر ابروی معشوق برخورد کرد',NULL);
INSERT INTO "verses" VALUES(1937209,2156,4,1,'ور وَسمه کمانکَش گشت، در ابروی او پیوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937210,2156,3,0,'شمعِ دلِ دمسازم، بنشست چو او برخاست',': دل من مانند شمعی است که وقتی او نشسته،روشن است و وقتی او بلند می‌شود، من نیز خاموش می شوم.صدای فریاد و فغان نظربازان بلند است وقتی او می نشیند در کنارشان،',NULL);
INSERT INTO "verses" VALUES(1937211,2156,3,1,'و افغان ز نظربازان، برخاست چو او بنشست',NULL,NULL);
INSERT INTO "verses" VALUES(1937212,2156,2,0,'آخر به چه گویم هست از خود خبرم، چون نیست','چگونه می‌توانم بگویم که از حال خود خبر دارم ؟! وقتی که خبر ندارم ، چرا بگویم که معشوق رابطه‌ای ندارم ؟! درصورتی که دارم',NULL);
INSERT INTO "verses" VALUES(1937213,2156,2,1,'وز بَهرِ چه گویم نیست با وی نظرم، چون هست',NULL,NULL);
INSERT INTO "verses" VALUES(1937214,2156,1,0,'در نعلِ سمندِ او شکلِ مهِ نو پیدا','ماه به زیر نعل اسب او بود چ از قد بلند او، درخت صنوبر کوتاه‌تر به نظر می‌رسید',NULL);
INSERT INTO "verses" VALUES(1937215,2156,1,1,'وز قدِ بلندِ او بالایِ صنوبر، پست',NULL,NULL);
INSERT INTO "verses" VALUES(1937216,2156,0,0,'در دیرِ مغان آمد، یارم قدحی در دست','در ميخانه، معشوق من با جامی در دست به سراغم آمد، او از شراب مست بود و باقی می‌نوشان از چشم زیبای او مست بودند',NULL);
INSERT INTO "verses" VALUES(1937217,2157,2,1,'که با شکستگی ارزد به صد هزار درست',NULL,NULL);
INSERT INTO "verses" VALUES(1937218,2156,0,1,'مست از می و میخواران از نرگسِ مستش مست',NULL,NULL);
INSERT INTO "verses" VALUES(1937219,2155,6,0,'خندهٔ جامِ می و زلفِ گره‌گیرِ نگار','هوش مصنوعی: خندهٔ شراب و زلف پیچیدهٔ معشوق، باعث می‌شود که بسیاری از توبه‌ها مانند توبهٔ حافظ زیر پا قرار گیرد و شکسته شود.',NULL);
INSERT INTO "verses" VALUES(1937220,2155,5,0,'آن چه او ریخت به پیمانهٔ ما نوشیدیم','هوش مصنوعی: ما هر چه را که او به پیمانهٔ ما ریخت، نوشیدیم؛ خواه آن نوشیدنی از شراب بهشت باشد یا از شراب مستی.',NULL);
INSERT INTO "verses" VALUES(1937221,2155,5,1,'اگر از خَمرِ بهشت است وگر بادهٔ مست',NULL,NULL);
INSERT INTO "verses" VALUES(1937222,2155,4,0,'برو ای زاهد و بر دُردکشان خرده مگیر','هوش مصنوعی: ای زاهد، تو برو و به می‌نوشان ایراد نگیرید؛ زیرا در روز الست، تنها همین نعمت نصیب ما شد.',NULL);
INSERT INTO "verses" VALUES(1937223,2155,4,1,'که ندادند جز این تُحفه به ما روزِ الست',NULL,NULL);
INSERT INTO "verses" VALUES(1937224,2155,3,0,'عاشقی را که چنین بادهٔ شبگیر دهند','هوش مصنوعی: عاشقی که در دل شب چنین مشروبات خوشگوار و دلنشین به او بدهند، اگر به عشق و باده‌پرستی رو نیاورد و خود را غرق لذت‌ها نکند، ناخوشایند و بی‌خبر از عشق به حساب می‌آید.',NULL);
INSERT INTO "verses" VALUES(1937225,2155,3,1,'کافر عشق بُوَد گر نشود باده پرست',NULL,NULL);
INSERT INTO "verses" VALUES(1937226,2155,2,0,'سر فرا گوش من آورد به آوازِ حزین','هوش مصنوعی: به آرامی و با صدایی دلگیر، کسی نزدیک من آمد و گفت: ای عاشق قدیمی من، آیا خواب هستی؟',NULL);
INSERT INTO "verses" VALUES(1937227,2155,2,1,'گفت: ای عاشقِ دیرینهٔ من، خوابت هست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937228,2155,1,0,'نرگسش عَربده‌جوی و لبش افسوس‌کنان','با چشمانی غضبناک و لب گزیدنی از روی اندوه و غم که عاشق وخواب ای وای بر تو',NULL);
INSERT INTO "verses" VALUES(1937229,2155,1,1,'نیم شب، دوش به بالین من آمد، بنشست',NULL,NULL);
INSERT INTO "verses" VALUES(1937230,2155,0,0,'زلف‌آشفته و خِوی‌کرده و خندان‌لب و مست','هوش مصنوعی: زلف‌های پریشان و چهره‌ای سرخوش، لبخند بر لب، بی‌خیال و سرشار از شادی، با پیرهنی تکه‌دار و غزل‌خوانی در حال شادی و مشغول نوشیدن.',NULL);
INSERT INTO "verses" VALUES(1937231,2155,0,1,'پیرهن‌چاک و غزل‌خوان و صُراحی در دست',NULL,NULL);
INSERT INTO "verses" VALUES(1937232,2154,8,1,'که گفتهٔ سخنت می‌برند دست به دست',NULL,NULL);
INSERT INTO "verses" VALUES(1937233,2155,6,1,'ای بسا توبه که چون توبهٔ حافظ بشکست',NULL,NULL);
INSERT INTO "verses" VALUES(1937234,2132,5,0,'اگر دشنام فرمایی و گَر نفرین دعا گویم','اگر به من دشنام و نفرین هم بگویی باز هم من تو را دعا می‌گویم. تو جواب ِ تلخ هم به من بدهی، لب ِ لعل ِ شکرخای تو زیباتر هم می‌شود! شکرخا بمعنای طوطی شکر خوار است ، که به یار زیبا روی که اخلاق تند و سخنان تیز دارد تشبیه شده،',NULL);
INSERT INTO "verses" VALUES(1937235,2132,5,1,'جوابِ تلخ می‌زیبَد لبِ لَعلِ شِکرخا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937236,2132,6,0,'نصیحت گوش کن جانا که از جان دوست‌تر دارند','نصیحت ِ من ِ پیر مرد را گوش کن! چون که جوانان ِ سعادت‌مند، پند ِ پیر ِ دانا را ارج می‌نهند و بیش‌تر از جان دوست دارند! به شکلی که یعنی ببخشید ها نصیحت می‌کنم جانا! و سپس نصیحت‌اش را در بیت بعدی می‌گوید',NULL);
INSERT INTO "verses" VALUES(1937237,2141,8,0,'دور دار از خاک و خون دامن، چو بر ما بگذری','وقتی که بر ما می‌گذری، دامن ِ خودت را بالاتر بگیر تا به خاک و خون آلوده نشود. چون که در این راه، بسیاری کشته شده‌اند. قربان ِ شما. قربان را در هر یک از معناهایی که از لغت‌نامه‌ها آوردم می‌توان به کار برد. در معنایِ ندیم ِ شاه، می‌توان این معنا را گرفت که ندیمان و نزدیکان ِ بسیاری که داشتی در این راه کشته شده‌اند. این راه می‌تواند راهی باشد که یار به سویِ شاعر می‌آید تا بر او بگذرد، می‌تواند همان راهی باشد که برای نزدیکی و قِربان و ندیمی ِ شاه می‌بایست پیمود تا به آن مرتبت رسید. قربان به معنایِ تیردان و کمان‌دان و ترکش هم می‌تواند این تصویر را در ذهن بیاورد که انگاری خود ِ یار، آن اشخاص را کُشته و به خاک انداخته. قربان ِ شما به صورت ِ صوت مخفف ِ قربان ِ شما بشوم، می‌تواند معنایِ قربان صدقه رفتن و گفتار ِ احترام آمیز با مقام ِ عالی هم باشد. در معنایِ «قربانی» هم می‌تواند در بیت بنشیند به این شکل که بسیاری در این راه قربانی ِ شما شده‌اند. در هر کدام از این حالت‌ها، شاعر به یار می‌گوید چون که زمین ِ راهی که از آن طریق می‌خواهی بر ما بگذری، آکنده از جنازه‌هایِ بسیارانی است که در این راه کشته شده اند، دامن‌ات را از خاک و خون دور نگاه دار که مبادا دامنت کثیف شود؛ یا این خاک و خون، دامن‌ات را بگیرد. در این معنایِ آخر، می‌توان «دور دار از خاک و خون دامن» را طور ِ دیگری نیز تعبیر کرد: نوعی تحذیر که از این خون‌ریزی و کشتار جلوگیری کن! یا دامن ِ خودت را از این خاک و خون دور بدار! خودت را کنار بکش! چو بر ما بگذری نیز شکلی قدرت‌نمایی یا تهدید می‌تواند داشته باشد! که اگر بر ما بگذری، دامن‌ات را از خاک و خون دور بدار! چون در این راه، کسانی که دامن از خاک و خون دور نداشته‌اند، پیش از تو، بسیار کشته شده‌اند.',NULL);
INSERT INTO "verses" VALUES(1937238,2141,10,0,'ای صبا با ساکنانِ شهرِ یزد از ما بگو','ای صبا! از طرف ِ ما به ساکنان ِ شهر ِ یزد بگو که ای کسانی که بادا که سر ِ ناسپاسان و کسانی که حق ِ نعمت و خوبی که به ایشان کردید را نمی‌گزارند و نمی‌شناسند، مانند ِ گوی در پای ِ چوگان ِ شما باشد! (بقیه در بیت ِ بعدی)',NULL);
INSERT INTO "verses" VALUES(1937239,2141,10,1,'کِای سر حق‌ناشناسان گوی چوگان شما',NULL,NULL);
INSERT INTO "verses" VALUES(1937240,2141,11,0,'گرچه دوریم از بساط قُرب‌، همّت دور نیست','اگرچه که از بساط ِ نزدیکی دوریم و از هم‌جواری با شما محروم، اما اراده و عزم ِ ما دور نیست! بنده‌یِ شاه ِ شما و ستاینده و ثناخوان ِ شماییم. بساط ِ قُرب می‌تواند سفره‌ئی باشد که تنها نزدیکان و خویشان بر آن می‌نشینند و این معنا با «بزم ِ جم» که در بیت‌های پیشین ِ این غزل آمده، تناسبی دارد. همّت دور نیست می‌تواند هم به این معنا باشد که دعا و طلب ِ خیر ِ ما وابسته به بُعد ِ مکان نیست و اگرچه دوریم، اما دعایِ خیر ِ ما از شما دور نیست و همواره با شما است؛ هم می‌توان گفت: اگرچه از بساط ِ قرب دوریم، اما این عزم و اراده هست که به شما نزدیک شویم و به سمت ِ شما بیاییم.',NULL);
INSERT INTO "verses" VALUES(1937241,2141,11,1,'بندهٔ شاه شماییم و ثناخوان شما',NULL,NULL);
INSERT INTO "verses" VALUES(1937242,2141,12,0,'ای شَهنشاه بلند اختر‌، خدا را همّتی','ای شاهنشاه ِ بلند اقبال که ستاره‌یِ بخت‌ات بلند است. از خدا همّتی می‌طلبم که مانند ِ ستاره که خاک ِ ایوان ِ رفیع ِ تو را می‌بوسد، من هم بتوانم خاک ِ ایوان ِ شما را ببوسم.',NULL);
INSERT INTO "verses" VALUES(1937243,2141,12,1,'تا ببوسم همچو اختر خاک ایوان شما',NULL,NULL);
INSERT INTO "verses" VALUES(1937244,2142,0,0,'می‌دمد صبح و کِلِّه بست سحاب','صبح در حال ِ طلوع کردن است و ابرها، متراکم شده‌اند انگاری که پرده‌ئی خیمه‌طور و رقیق بر آسمان بسته‌اند. ای یاران! برخیزید که شراب ِ صبح‌گاهی بنوشیم. صبح و صبوح و اصحاب و سحاب جناس و هم‌آوایی دارند. برای دمیدن در معناهای دیگر، قرینه‌ئی نیافتم و همان دمیدن ِ صبح به معنایِ طلوع ِ آفتاب را در نظر گرفتم. هرچند دمیدن ِ صبح به تعبیر ِ دعا و فسون‌دمیدن نیز در شعر ِ حافظ به کار رفته.',NULL);
INSERT INTO "verses" VALUES(1937245,2142,0,1,'الصَبوح الصَبوح یا اصحاب',NULL,NULL);
INSERT INTO "verses" VALUES(1937246,2142,1,0,'می‌چکد ژاله بر رخِ لاله','ژاله بر رخ ِ لاله می‌چکد[۱] ای دوستان! برای نوشیدن ِ باده برخیزید! توصیفی از هوایِ مه‌آلود ِ دم ِ صبح می‌تواند باشد. اما در حقیقت، در هوایِ مه‌آلود ِ صبح، ژاله در معنایِ شبنم، بر رخ ِ لاله نمی‌چکد. از رخ ِ لاله می‌چکد. خاصه این‌که شاعر جایِ دیگر نیز گفته ژاله از ابر ِ بهمنی می‌چکد. و جایی نیز ژاله را به باده‌ئی تشبیه کرده که به درون ِ کاسه‌یِ قدح شکل ِ لاله چکیده‌است. با این اوصاف، می‌توان ژاله را باران معنی کرد. یا می‌توانم ادعا کنم که در آن زمان، تصور می‌کردند که قطره‌هایِ شبنم، بر برگ ِ گل می‌چکیده. اما امروز می‌دانیم که شبنم حاصل از رطوبت ِ صبحگاهی است نه چکّه‌هایِ باران. هرچند عرق بر صورت ِ یار را به شبنم تشبیه کرده باشند.',NULL);
INSERT INTO "verses" VALUES(1937247,2142,1,1,'المُدام المُدام یا احباب',NULL,NULL);
INSERT INTO "verses" VALUES(1937248,2142,2,0,'می‌وزد از چمن نسیمِ بهشت','از سبزه‌زار، بادی ملایم با عطر ِ خوش ِ بهشت می‌وزد، بشتابید و در هر نفس که از این نسیم استشمام می‌کنید، پی در پی و بسیار، می ِ ناب بنوشید. وزیدن ِ نسیم ِ بهشت و اشاره به نوشیدن ِ می ِ ناب، می‌تواند اشاره به آیاتی از قرآن باشد که در توصیف ِ بهشت، از نوشاندن ِ باده‌یِ ناب و طهور (رحیقٍ مختومٍ) خبر داده‌است. که چون نسیم ِ بهشت می‌وزد، می‌بایست باده‌یِ ناب نوشید. سوره مطففین آیه 25 تا 28: يُسْقَوْنَ مِنْ رَحِيقٍ مَخْتُومٍ ﴿٢٥﴾ خِتَامُهُ مِسْکٌ ۚ وَفِي ذَٰلِکَ فَلْيَتَنَافَسِ الْمُتَنَافِسُونَ ﴿٢٦﴾ وَمِزَاجُهُ مِنْ تَسْنِيمٍ ﴿٢٧﴾ عَيْنًا يَشْرَبُ بِهَا الْمُقَرَّبُونَ ﴿٢٨﴾',NULL);
INSERT INTO "verses" VALUES(1937249,2142,2,1,'هان، بنوشید دَم به دَم مِیِ ناب',NULL,NULL);
INSERT INTO "verses" VALUES(1937250,2142,3,0,'تخت زُمْرُد زده است گل به چمن','گل، مانند ِ شاهی، تخت ِ زمرد بر چمن و مَرغزار زده است. فرصت ِ شادمانی و نشاط را غنیمت بدان و باده‌یِ مانند ِ یاقوت ِ سرخ و آتشین را در نظر داشته باش. زمرد و لعل با هم تناسب دارند. دریاب نیز، واژه‌یِ دُر را در خود دارد که در تبادر، با زمرد و لعل تناسب می‌یابد. خاصه که شاعر، دَریافتن و دُر یافتن را در غزلی دیگر به صراحت کنار ِ هم نیز آورده. راح و راح ِ روح در معنایِ اصطلاحی ِ موسیقی با آتشین در معنایِ سوزناک نیز تناسبی می‌سازند و این فضا، به تصویر ِ مجلس ِ بزم ِ شاهانه در گوشه‌یِ چمن نیز می‌افزاید.',NULL);
INSERT INTO "verses" VALUES(1937251,2142,3,1,'راحِ چون لعلِ آتشین دریاب',NULL,NULL);
INSERT INTO "verses" VALUES(1937252,2142,4,0,'درِ میخانه بسته‌اند دگر','در ِ میخانه را دیگر بسته‌اند. به شکل ِ دعا، از خدا که گشاینده‌یِ هر دری است می‌خواهد که آن را بگشاید. دگر هم به معنایِ از این پس و هم در معنای دوباره و دیگربار در این بیت خوش می‌نشیند. دگر، به معنایِ باز و دوباره، می‌تواند به معنایِ بسته شدن ِ مجدّد ِ در ِ میخانه باشد و هم به شکل ِ قیدی. که: از این پس، در ِ میخانه را بسته‌اند. در نگاهی دیگر می‌توان گفت که عبارت ِ «دگر» در انتهای مصراع ِ نخست، مربوط به جمله‌یِ مصراع ِ دوم باشد. یعنی: در ِ می‌خانه را بسته‌اند. دیگربار آن را باز کن ای گشاینده‌یِ درها. در نسخه‌ی 801 به‌جایِ دگر، مگر آمده است.',NULL);
INSERT INTO "verses" VALUES(1937253,2142,4,1,'اِفتَتِح یا مُفَتِّح الاَبواب',NULL,NULL);
INSERT INTO "verses" VALUES(1937254,2142,5,0,'لب و دَندانْت را حقوق نمک','جان و سینه‌هایِ کباب، بر لب و دندان ِ تو بسی حقّ ِ نمک دارند. آن جان و سینه‌هایی که از عشق ِ تو کباب شده‌اند، حقی بر لب و دندان ِ تو دارند که آن‌ها را کباب کرده‌ای. انگاری که دل و جان ِ آن‌ها را به‌دندان کشیده‌ای و خورده‌ای! امروز نیز رسم است که کسی که در نزد ِ کسی نان و نمکی خورده‌است، به حرمت ِ آن نان و نمک، دین و وظیفه‌ئی اخلاقی نسبت به او بر گردن‌اش می‌افتد. به گمان ِ من، شاعر تصویری ساخته از دلبری که عاشقانی دارد که جان و دل و سینه‌یِ آن‌ها کباب شده و دلبر، آن کباب را به دندان کشیده و با لب ِ خود خورده‌است. سینه‌یِ کباب، دلی است که از عشق ِ یار، بر آتش افتاده و کباب شده؛ هم‌چنین سینه‌یِ مرغی که کباب می‌کنند و به آن نمک می‌زنند و می‌خورند. و می‌گوید که آن جان و سینه‌هایِ کباب از غم ِ عشق ِ تو، بر گردن ِ لب و دندان ِ تو حقّ ِ نمک دارند. و می‌بایست این حق را نگه‌داری و با آن‌ها به خوبی رفتار کنی. از طرفی خود ِ دندان ِ یار نیز می‌تواند به سنگ ِ نمک تشبیه شده باشد. درست برعکس ِ همین هم می‌توان معنا کرد: لب و دندان ِ نمکین ِ تو، بر گردن ِ جان و سینه‌هایِ کباب حقّ ِ نمک دارد. این دومین تعبیر از طرفی تشبیه ِ دندان ِ سفید به سنگ ِ نمک را هم در خود دارد. در این حال، معشوق را بر گردن ِ عاشقان محقّ می‌کند.',NULL);
INSERT INTO "verses" VALUES(1937255,2142,5,1,'هست بر جان و سینه‌هایِ کباب',NULL,NULL);
INSERT INTO "verses" VALUES(1937256,2142,6,0,'این چنین موسِمی عجب باشد','در این فصل و این زمان، عجیب است که با این سرعت و تعجیل، میکده را ببندند. به‌جز به‌شتاب (با تعجیل و بدون ِ درنگ و با عجله) می‌توان بشتاب (عجله کن) هم خواند؛ اما نظر به این‌که در ِ میخانه را بسته‌اند، تعجیل موردی ندارد! باز اگر در حال ِ بستن بود می‌شد تعبیر کرد که پیش از بسته شدن خود را به آن برسان!',NULL);
INSERT INTO "verses" VALUES(1937257,2142,6,1,'که ببندند میکده به شتاب',NULL,NULL);
INSERT INTO "verses" VALUES(1937258,2142,7,0,'بر رخِ ساقیِ پری پیکر','هم‌چو حافظ، تو نیز با نگاه کردن به رخ ِ ساقی ِ پری‌پیکر، می ِ ناب بنوش. می نوشیدن با نگاه کردن به چهره‌یِ نگار ِ خوب‌روی و به‌رویِ یار و بر رخ ِ ساقی، در شعر ِ حافظ کاری لذت‌بخش و متهوّرانه توصیف شده. هم‌چو حافظ که بر رخ ِ ساقی ِ خوش‌اندام می‌نگرد و با نگاه در رخ ِ او باده‌یِ ناب می‌نوشد، تو نیز این‌چنین بنوش.',NULL);
INSERT INTO "verses" VALUES(1937259,2142,7,1,'همچو حافظ بنوش بادهٔ ناب',NULL,NULL);
INSERT INTO "verses" VALUES(1937260,2143,0,0,'گفتم ای سلطانِ خوبان رحم کن بر این غریب','به او گفتم: ای سلطان ِ خوبان! بر این غریب و دور افتاده از وطن و مسکن رحمی کن! گفت: غریب ِ مسکین، وقتی که به دنبال ِ دل ِ خود بیفتد، راه ِ خود را گم خواهد کرد. شاعر با لحنی خضوع‌آمیز، از مخاطب ِ خود که او را سلطان ِ خوبان می‌نامد، می‌خواهد به رسم ِ این که سلطان است، به او به‌سان ِ غریب و مسافر و گم‌گشته، شفقت و ترحّم و مهربانی کند. و مخاطب‌اش، به او پاسخ می‌دهد. به نوعی شماتت‌اش می‌کند که تو به دنبال ِ دل ِ خود رفتی و راه را گم کردی. به شکلی که انگاری شایسته و لایق ِ ترحم و عطوفت ِ من نیستی. خود مقصّر بودی که راه را گم کردی. غریب در مصراع ِ دوّم بجز معنای مسافر و بی‌چاره و بی‌چیز و کسی که از وطن ِ خود دور مانده، با توجه به عبارت‌های راه گم کردن و به دنبال ِ چیزی رفتن، با در نظر داشتن ِ این حقیقت که مسافران راه را با استفاده از ستاره‌ها و صوَر ِ فلکی می‌یافته‌اند، می‌تواند معنایِ اصطلاحی ِ غریب در نجوم را هم به ذهن بیاورد.',NULL);
INSERT INTO "verses" VALUES(1937261,2143,0,1,'گفت در دنبالِ دل، رَه گُم کُنَد مسکین غریب',NULL,NULL);
INSERT INTO "verses" VALUES(1937262,2143,1,0,'گفتمش مَگذر زمانی، گفت معذورم بدار','به او گفتم که اندکی بمان و مرا ترک نکن و مرو، گفت: مرا ببخش! نمی‌توانم! یک خانه‌پرورد و نازپرورده، تاب و تحمّل ِ غریبی و غریبان را ندارد. گفتم‌اش: مگذر زمانی! به او گفتم که اندکی درنگ کن و از برابر ِ من مگذر و مرو و دور مشو. گفت: عذر ِ مرا بپذیر! (نمی‌توانم این خواسته‌یِ تو را اجابت کنم و نگذرم!) مصراع ِ دوم را هم می‌توان در ادامه‌یِ گفته‌یِ معشوق و مخاطب ِ شاعر دانست و هم می‌توان در نظر گرفت که معشوق فقط گفته‌است معذور م بدار و به راه ِ خود ادامه داده‌است. و مصراع ِ دوّم، گفت‌و‌گویِ شاعر با خود است. و من این دومی را دوست می‌دارم. انگاری که شما به کسی بگویی اندکی بنشین و از برابر ِ من و از نزد ِ من مگذر و مرو، او فقط بگویید ببخشید! نمی‌شود! و برود. و شما در ادامه، با خودتان توجیه‌وار بگویید: بعله دیگه! یک آدم ِ خانه‌پرورد و نازپرورده، تحمل و تاب ِ غم ِ غریبی چون من را ندارد. درکی از این درد و غم ِ من ندارد! بماند تا من برایِ او بگویم هم تاب و تحمّل ِ شنیدن‌اش را ندارد. به همین‌خاطر است که نماند و رفت. اما اگر مصراع ِ دوم را بخواهیم در ادامه‌یِ گفتار ِ معشوق در نظر بگیریم، می‌شود دلیلی که معشوق برایِ نماندن‌اش آورده. انگاری که بگوید من خانه‌پرورد ام و تاب و تحمّل ِ غریبی ندارم. می‌توان گفت که معشوق مهربانانه پوزش طلبیده و گفته که در این راه ِ غربت و سرگشتگی که تو داری، من تاب و یارایِ هم‌راهی ندارم و مرا معذور بدار! و می‌رود.',NULL);
INSERT INTO "verses" VALUES(1937263,2143,1,1,'خانه پروردی چه تاب آرد غم چندین غریب',NULL,NULL);
INSERT INTO "verses" VALUES(1937264,2143,2,0,'خفته بر سنجابِ شاهی نازنینی را چه غم؟','برداشت ِ من این است که این بیت هم ادامه‌یِ همان واگویه‌یِ درونی ِ شاعر است که از مصراع ِ دوم ِ بیت ِ پیشین آغاز شده. نازنین و لطیف ِ نازپرورده‌ئی که در رخت‌ِخواب ِ شاهانه‌ئی که از پوست ِ سنجاب ساخته شده خوابیده است، چه غم دارد اگر غریب و بی‌چاره‌ئی از بوته‌یِ خار برای خود بستر ساخته باشد و به‌جایِ بالش، سر بر سنگ ِ خارا بگذارد و بخوابد؟ میان ِ خار و خاره و بستر و بالین، لفّ و نشر ِ مرتّب هست. اصطلاح ِ امروزی ِ رویِ بالش ِ پر ِ قو خوابیدن، مشابه ِ خفته بر سنجاب ِ شاهی است.',NULL);
INSERT INTO "verses" VALUES(1937265,2143,2,1,'گر ز خار و خاره سازد بستر و بالین غریب',NULL,NULL);
INSERT INTO "verses" VALUES(1937266,2141,8,1,'کَاندَر این ره کشته بسیارند، قربان شما',NULL,NULL);
INSERT INTO "verses" VALUES(1937267,2141,9,0,'می‌کند حافظ دعایی، بشنو، آمینی بگو','حافظ دعایی می‌کند (من دعایی می‌کنم) بشنو و بگو آمین! دعای من این است: بادا که لعل ِ شکّر افشان ِ شما روزی و نصیب و قسمت ِ ما شود.',NULL);
INSERT INTO "verses" VALUES(1937268,2141,9,1,'روزی ما باد لعل شَکَّرافشان شما',NULL,NULL);
INSERT INTO "verses" VALUES(1937269,2141,7,0,'کی دهد دست این غرض یا رب که همدستان شوند‌؟','به شکل ِ حسرت یا آرزو عنوان می‌کند: چه زمانی این هدف و مقصود حاصل می‌شود و میسّر می‌شود که خیال و افکار ِ ما به دست ِ زلف ِ پریشان و در هم بر هم ِ شما آسوده و راحت شود. خاطر و اندیشه‌یِ شاعر پریشان است. و شاعر می‌خواهد که با قرین شدن با زلف ِ پریشان ِ محبوب، به آسودگی و جمعیّت برسد. هم‌دستان شوند را می‌توان دو هم‌دست در نظر گرفت. دو رفیق که با هم متّفق شده‌اند. تصویر ِ من، دو شخص که دست در دست ِ هم گذاشته‌اند. انگاری خاطر ِ شاعر، دست در زلف ِ پریشان ِ یار کرده و مجموع و آسوده‌است.',NULL);
INSERT INTO "verses" VALUES(1937270,2140,0,0,'ساقی به نورِ باده برافروز جامِ ما','غزل با لحنی شادمانه آغاز شده‌است. از ساقی می‌خواهد که جام را با نور ِ باده روشن و گلگون کند. و از مطرب می‌خواهد که غزلی بگوید؛ که جهان به کام ِ ما شده‌است. برافروختن ِ جام، در معنایِ روشن کردن، تشبیه ِ شراب به آتش است که در مشعل ِ جام قرار می‌گیرد و فروزان می‌شود. بگو در معنایِ سخن بگو، این معنا را می‌تواند برساند که از مطرب خواسته است، به همه بگوید و اطلاع دهد که کار ِ جهان به کام ِ ما شده‌است. بگو، معنایِ سرودن و آواز خواندن هم دارد. در این معنا، می‌توان گفت که از مطرب خواسته که نغمه‌ئی بخواند. به این دلیل که کار ِ جهان به کام ِ ما شده است. یعنی به شادباش ِ آن که کار ِ جهان به کام ِ ایشان شده، بزمی ترتیب داده و از ساقی می‌خواهد که آتش ِ جام را بر فروزد و از مطرب می‌خواهد که نغمه‌ئی طرب‌انگیز بخوانَد.',NULL);
INSERT INTO "verses" VALUES(1937271,2140,0,1,'مطرب بگو که کارِ جهان شُد به کامِ ما',NULL,NULL);
INSERT INTO "verses" VALUES(1937272,2140,1,0,'ما در پیاله عکس رخِ یار دیده‌ایم','ما در پیاله (جهان) چهره یار را دیده ایم، ای بی خبر از این لذت وصل همیشگی و. لذت رحظه لحظه ما از زندگی',NULL);
INSERT INTO "verses" VALUES(1937273,2140,1,1,'ای بی‌خبر ز لَذَّتِ شُربِ مُدامِ ما',NULL,NULL);
INSERT INTO "verses" VALUES(1937274,2140,2,0,'هرگز نمیرد آن که دلش زنده شد به عشق','آن کسی که دل‌اش به عشق زنده است، هرگز نخواهد مُرد. دوام و بقا و جاودانگی ِ ما در دفتر ِ روزنامه‌یِ عالَم ثبت شده‌است.',NULL);
INSERT INTO "verses" VALUES(1937275,2140,2,1,'ثبت است بر جَریدهٔ عالم دوامِ ما',NULL,NULL);
INSERT INTO "verses" VALUES(1937276,2140,3,0,'چندان بُوَد کرشمه و نازِ سَهی‌قدان','کرشمه و ناز ِ سهی‌قد ها تا جایی و تا زمانی است که سرو ِ صنوبرخرام ِ ما به جلوه در آید. یعنی تا زمانی جرئت و مجال ِ خودنمایی و عرض ِ اندام دارند که او خود را نشان نداده‌است. چندان بود، معنای دیگری هم دارد: «به اندازه‌ئی هست که...» در این حالت، می‌توان گفت که کرشمه و ناز ِ سهی‌قدان به آن اندازه‌ئی شده که سرو ِ صنوبرخرام ِ ما خود را نشان بدهد. یعنی زمان ِ آن فرا رسیده‌است. چون‌که سهی‌قدان کرشمه را از حد برده‌اند.',NULL);
INSERT INTO "verses" VALUES(1937277,2140,3,1,'کآید به جلوه سروِ صنوبرخَرامِ ما',NULL,NULL);
INSERT INTO "verses" VALUES(1937278,2140,4,0,'ای باد اگر به گُلشنِ اَحباب بُگذری','زنهار عرضه ده ... را به دو شکل می‌خوانم: ۱. زنهار! بر ِ جانان پیام ِ ما را عرضه کن. ۲. پیام ِ ما را مانند ِ زنهاری بر ِ جانان عرضه بده. در شکل ِ نخست، باد را زنهار می‌گوید. به باد می‌گوید که آگاه باش! مراقب باش! و به جانان پیام ِ ما را بگو. در شکل ِ دومی، از باد می‌خواهد که اگر به گلستان ِ یاران ِ شاعر گذر کرد، پیغام ِ شاعر را به شکل ِ زنهار و هشداری به آنان عرضه کند. یا عهد و پیمانی که پیش‌تر با شاعر بسته بودند را به ایشان یادآوری کند، یا از آن‌ها پناه و امان و مهلت بخواهد.',NULL);
INSERT INTO "verses" VALUES(1937279,2140,4,1,'زِنهار، عَرضه دِه بَرِ جانان پیامِ ما',NULL,NULL);
INSERT INTO "verses" VALUES(1937280,2140,5,0,'گو نامِ ما زِ یاد به عمدا چه می‌بری؟','در ادامه‌یِ بیت ِ پیش، به صبا می‌گوید پیغام ِ من را بگو! از او بپرس: چرا به عمد، نام ما را از یاد می‌بری؟ به‌هرحال، آن روزی که نام ِ ما به یادت نیاید، خواهد رسید. به عبارتی: بالاخره روزی خواهد رسید که نام ِ ما را به یاد نیاوری',NULL);
INSERT INTO "verses" VALUES(1937281,2140,5,1,'خود آید آن که یاد نیاری ز نامِ ما',NULL,NULL);
INSERT INTO "verses" VALUES(1937282,2140,6,0,'مستی به چشمِ شاهدِ دلبندِ ما خوش است','معناهایِ متفاوت ِ واژه را در پرانتز می‌آورم و این پرانتز به معنایِ مترادف بودن نیست. مستی (خماری ِ چشم، مست بودن، گلایه، اندوه) به چشم ِ شاهد ِ دلبند ِ ما خوش می‌نشیند (خوش‌آیند است). زآن‌رو (به همین خاطر است که، از آن چهره) اختیار ِ ما را (از آن روز که ما را از شیر گرفتند)، به مستی (مست بودن، یک مست، چشم ِ مست ِ یار) سپرده‌اند.',NULL);
INSERT INTO "verses" VALUES(1937283,2140,6,1,'زآن رو سپرده‌اند به مستی زمامِ ما',NULL,NULL);
INSERT INTO "verses" VALUES(1937284,2143,3,0,'ای که در زنجیرِ زلفت جایِ چندین آشناست',': ای کسی که در زلف ِ مانند ِ زنجیر ِ تو عاشقان و یاران ِ زیادی جای دارند، خال ِ سیاه ِ عطرآگین ِ تو بر آن چهره‌یِ زیبا و درخشنده‌یِ تو خیلی زیبا جای گرفته است و خوش نشسته‌است. زنجیر یا سلسله، ریسمان و بندی فلزی است که از حلقه‌هایِ تو در تو تشکیل شده. در شعر ِ حافظ، زنجیر و سلسله، بیش‌تر به زلف ِ یار تشبیه شده. در این بیت زلفی است که در زنجیر ِ آن، چندین عاشق جای گزیده‌اند. یار را شخصی خطاب می‌کند که دل ِ عاشقان ِ زیادی در زنجیر ِ زلف ِ او گرفتار است؛ و می‌افزاید که آن خال ِ مشکین هم بر رخ ِ درخشان ِ او خوش افتاده است. برای افتادن معناهای زیادی ضبط شده اما در این بیت، حسی که از خوش فتاد می‌گیرم، انگاری بگوید چه نیکو نشسته و چه برازنده‌است. و غریب در این بیت، قیدی است برای خوش افتادن. هم‌چنین خال ِ مشکین بر صورت تنها است. مانند ِ دل که در زنجیر ِ زلف جای دارد و انگاری احوال ِ او خوش است. خال ِ غریب و تنها هم جایِ خوش و خوبی افتاده‌است.',NULL);
INSERT INTO "verses" VALUES(1937285,2140,7,0,'ترسم که صَرفه‌ای نَبَرَد روزِ بازخواست','برایِ حال ِ شیخ نگران ام! می‌ترسم که در روز ِ قیامت، روزی که مردم را بابت ِ کارهای‌شان در این دنیا بازخواست می‌کنند، نان ِ حلال ِ شیخ، برتری و مزیتی به آب ِ حرام ِ ما نداشته باشد! نان ِ حلال و آب ِ حرام، کنایه‌هایی اند که از قول ِ شیخ و زاهد گفته. که گویا نانی که آن‌ها می‌خورند حلال است و آبی که شاعر و رندان می‌نوشند، حرام است. عبارت‌هایِ حرام و حلال هم اصطلاح‌های شرع است. آب ِ حرام هم اشاره به می است و هم اشاره به نگرش ِ شیخ به گروهی که شاعر خود را از آنان می‌داند که از دید ِ شیخ و واعظ، آبی هم که بنوشند، حرام است! به طعنه می‌گوید که می‌ترسم سر ِ آخر که روز ِ بازخواست است، نان ِ حلال ِ آن‌ها از اب ِ حرام ِ ما ارج و قرب ِ بیش‌تری نداشته باشد!',NULL);
INSERT INTO "verses" VALUES(1937286,2141,0,0,'ای فروغِ ماهِ حُسن‌، از روی رخشان شما','ای کسی که ماه ِ حُسن و زیبایی، فروغ و روشنی و پرتو ِ خود را از چهره‌یِ تابان ِ شما می‌گیرد و آبرو و اعتبار و ارج و قدر ِ خوبی، از چاه ِ زنخدان ِ شما است. آب ِ رو، جدا از معنای اعتبار و شرف و سرافرازی و عِرض و قدر، آبی است که بر روی است. و آب را از چاه در می‌آوردند. و به این تعبیر، چاه ِ زنخ‌دان، تناسبی با آب می‌یابد. یعنی اگر خوبی، آبی بر رویِ خود داشته باشد، آن آب ِ رو را از گودی ِ چانه‌یِ شما که مانند ِ چاه است، استخراج کرده است.',NULL);
INSERT INTO "verses" VALUES(1937287,2141,1,0,'عزم دیدار تو دارد جانِ بر لب آمده','این جان ِ من که بر لبم رسیده است، قصد دارد که تو را ببیند. دستور ِ شما چیست؟ باز گردد؟ یا برآید؟ در نگاه ِ اول به نظر ِ من می‌آمد که جان بر لب رسیدن و جان ِ بر لب آمده کنایه از سختی و تحمّل ِ رنج ِ بسیار و به ستوه آمدن و طاقت از دست دادن از بابت ِ این تحمّل ِ سختی و رنج است. و تصویری که بود، مشقّت و سختی ِ بسیار ِ شاعر در راه ِ رسیدن به دیدار و وصال ِ معشوق بود که در میانه‌یِ راه از او کسب ِ تکلیف می‌کند که چه کنم؟ بازگردم یا به سویِ تو بیایم؟ دیگر این است که این جان است که عزم ِ دیدار دارد. نه خود ِ شاعر! و این جان، جانی است که بر لب آمده. یعنی جان در حال ِ احتضار و مُشرِف بر مرگ است. در این تصویر، بازگشتن ِ جان به بدن، زندگی و نجات از مرگ است. و برآمدن ِ جان، مرگ و رفتن ِ جان از بدن. و این هر دو اتفاق، بسته به دستور و فرمان ِ معشوق است. که اگر فرمان دهد که به دیدار ِ یار نائل شود، جان ِ بر لب آمده به بدن ِ شاعر باز خواهد گشت؛ و اگر نه، جان ِ بر لب آمده از بدن بیرون خواهد آمد. و دیگر این که برآمدن ِ کام به معنایِ برآورده شدن ِ آرزو و خواسته هم در شعر ِ حافظ به کار رفته است.',NULL);
INSERT INTO "verses" VALUES(1937288,2141,1,1,'باز گردد یا برآید؟ چیست فرمان شما؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937289,2141,2,0,'کَس به دور نرگست طرفی نبست از عافیت','مستان هم در مَجاز اشاره به چشمان ِ یار است و هم در معنایِ واقعی، کسانی که مست اند. در این حالت، مستان ِ شما می‌تواند کسانی باشند که از چشمان ِ شما یا عشق ِ شما مست شده‌اند. دور ِ نرگس هم می‌تواند زمانه و دوره‌ئی باشد که نرگس می‌شکفد. اگر نرگس را استعاره از چشم ِ یار بگیریم، دور ِ نرگس می‌تواند پیرامون و گِرداگِرد ِ چشم باشد. هم‌چنین به دور ِ نرگس می‌تواند گردیدن و چرخیدن ِ عاشق به گِرد ِ چشم ِ یار باشد. مستوری، هم به معنایِ پارسایی و زهد و عفت آمده و هم پوشیدگی و در پرده نشستن. مستوری فروختن در معنایِ نخست می‌شود متکبّرانه پارسائی و عفت ِ خود را به رخ ِ کسی کشیدن. نوعی نشان دادن ِ چیزی است که دارند، با حالت ِ متکبّرانه و خودپسندانه. هیچ کس در گرداگرد ِ چشم ِ تو و در دور ِ نرگس ِ تو، بهره و نصیبی از عافیت و سلامت نبُرده است، یا به دلیل ِ پارسایی و ورَع، چشم ِ خودش را نبسته و از دور ِ نرگس ِ تو چشم‌پوشی نکرده است. بهتر است که کسی به جرگه‌یِ مستان تو و کسانی که مست ِ تو اند، فخر ِ پارسایی و پرده‌نشینی نفروشد. هر کسی در دور ِ نرگس ِ تو بود، از عافیت طرفی نمی‌بست. پس اگر مستور بوده‌ای و او را ندیده‌ای، بهتر است که به مستان ِ یار فخر فروشی نکنی. بهتر آن است که در مقابل ِ چشمان ِ مست ِ شما ادعایِ پاک‌دامنی نکنند.',NULL);
INSERT INTO "verses" VALUES(1937290,2141,2,1,'بِه که نفروشند مستوری به مستان شما',NULL,NULL);
INSERT INTO "verses" VALUES(1937291,2141,3,0,'بخت خواب‌آلود ما بیدار خواهد شد مگر','شاعر در این بیت، بخت ِ خود را خواب‌آلود دانسته و انتظار دارد که بخت ِ او بیدار شود. یک راه برایِ بیدار کردن ِ کسی که خوابیده‌است، این است که چند چکّه آب بر روی و حوالی ِ چشم ِ او بزنند. و امید دارد که رویِ درخشان ِ شاعر، که بر وی افتاده است، به سان ِ قطره‌هایِ آبی که بر صورت ِ شخصی خواب‌آلود می‌چکد، بخت ِ او را بیدار کند. انگاری که رویِ رخشان ِ یار، بر چشم ِ شاعر، آبی زده‌است.',NULL);
INSERT INTO "verses" VALUES(1937292,2141,3,1,'زان که زد بر دیده آبی، روی رخشان شما',NULL,NULL);
INSERT INTO "verses" VALUES(1937293,2141,4,0,'با صبا همراه بفرست از رخت گل دسته‌ای','انگاری رخ ِ یار به بوستانی تشبیه شده و شاعر از یار می‌خواهد که هنگامی که باد ِ صبا می‌وزد، گل‌دسته‌ئی از این بوستان ِ رخ‌اش همراه ِ این باد کُند و به سمت ِ شاعر بفرستد. به این امید که از خاک ِ بوستان ِ شما بویی بشنویم. خاک ِ بوستان، می‌تواند حسّ ِ دوری از وطن هم باشد. بو به معنایِ اثر و نشان از چیزی هم هست. مانند ِ اصطلاح ِ «از انسانیت بویی نبرده»! گل‌دسته، هدیه فرستادن را هم به یاد می‌آورَد.',NULL);
INSERT INTO "verses" VALUES(1937294,2141,4,1,'بو که بویی بشنویم از خاک بستان شما',NULL,NULL);
INSERT INTO "verses" VALUES(1937295,2141,5,0,'عمرتان باد و مراد ای ساقیانِ بزمِ جم','ای ساقیان ِ بزم ِ جم! الهی که عمر و مراد داشته باشید. اگرچه که جام ِ ما به دوران ِ ما از می پر نشد! می‌توان گفت که ساقیان ِ بزم ِ جم، اشاره به خود ِ جم ِ باستانی باشد خاصه آن که در مصراع ِ دوّم گفته که جام ِ ما به دوران ِ شما از می پُر نشد. اما در مصراع ِ نخست، برایِ این ساقیان، آرزویِ عمر و مراد کرده. و این، بیش‌تر به ذهن ِ من می‌آورد که این ساقیان زنده اند. می‌مانَد واژه‌یِ دوران که به معنایِ روزگار و عهد و زمان است. کسی که زنده است، دوران ِ او هنوز باقی است. و این عبارت که گرچه به دوران ِ شما جام ِ ما پر می نشد، برایِ شخص یا بزمی که معاصر است، دور از ذهن می‌نماید. مگر این که دوران را شکلی از «بزم ِ دور» در نظر بگیریم. یعنی دوران را در معنایِ گردش ِ جام در بزم در نظر بگیریم. و بگوییم در بزم ِ دور ِ شما، جام ِ ما پر از می نشد.',NULL);
INSERT INTO "verses" VALUES(1937296,2141,5,1,'گرچه جام ما نشد پُر مِی به دوران شما',NULL,NULL);
INSERT INTO "verses" VALUES(1937297,2141,6,0,'دل خرابی می‌کند، دلدار را آگه کنید','دل، بی‌تابی و ناشکیبی می‌کُنَد و حال و روز ِ خوبی ندارد. ای دوستان! به شما پناه می‌برم! شما را سوگند می‌دهم که دل‌دار را از این حال ِ خراب ِ دل ِ من آگاه کنید و به اطلاع ِ او برسانید.',NULL);
INSERT INTO "verses" VALUES(1937298,2141,6,1,'زینهار ای دوستان‌، جان من و جان شما',NULL,NULL);
INSERT INTO "verses" VALUES(1937299,2141,7,1,'خاطر مجموع ما، زلف پریشان شما',NULL,NULL);
INSERT INTO "verses" VALUES(1937300,2141,0,1,'آبِ‌روی خوبی از چاه زَنَخدان شما',NULL,NULL);
INSERT INTO "verses" VALUES(1937301,2140,7,1,'نانِ حلالِ شیخ ز آبِ حرامِ ما',NULL,NULL);
INSERT INTO "verses" VALUES(1937302,2143,3,1,'خوش فتاد آن خالِ مشکین بر رخِ رنگین غریب',NULL,NULL);
INSERT INTO "verses" VALUES(1937303,2143,4,0,'می‌نماید عکسِ مِی، در رنگِ رویِ مَه وَشَت','هوش مصنوعی: به نظر می‌رسد که تصویر می در رنگ چهره‌ی معشوقش، مانند برگ‌های ارغوانی بر روی گل نسرین، بسیار زیبا و دل‌انگیز است، اما در عین حال این زیبایی حس غریبی را نیز به همراه دارد.',NULL);
INSERT INTO "verses" VALUES(1937304,2145,4,0,'به بزمگاهِ چمن، دوش، مست، بگذشتم','دیشب از چمن به‌حالت مستی می‌گذشتم زیرا غنچه گل‌سرخ را با دهان تو اشتباهی‌گرفتم.',NULL);
INSERT INTO "verses" VALUES(1937305,2145,4,1,'چو از دهانِ تواَم غنچه در گُمان انداخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937306,2145,5,0,'بنفشه طُرِّهٔ مفتول خود گره می‌زد','بنفشه زلف پُرتاب خود را می‌بافت؛ صبا قصه زلف تو را گفت.',NULL);
INSERT INTO "verses" VALUES(1937307,2145,5,1,'صبا حکایتِ زلفِ تو در میان انداخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937308,2145,6,0,'ز شَرمِ آن که به روی تو نسبتش کردم','هوش مصنوعی: به خاطر شرمی که از تو دارم، هنگامی که نام سمن را به زبانی آوردم، نسیم صبح برایم خاک به دهان آورد.',NULL);
INSERT INTO "verses" VALUES(1937309,2145,6,1,'سمن به دستِ صبا، خاک در دهان انداخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937310,2145,7,0,'من از ورع، مِی و مطرب ندیدمی زین پیش','من در عمرم اهل میگساری و نشستن در مجلس مطربان نبودم، عشق مغبچگان مرا به این کارها انداخت. (وَرَع‌: پرهیزگاری)',NULL);
INSERT INTO "verses" VALUES(1937311,2145,7,1,'هوای مغبچگانم در این و آن انداخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937312,2145,8,0,'کنون به آبِ میِ لعل، خرقه می‌شویَم','اکنون خرقه زهد خود را با شراب سرخ می‌شویم؛ قسمت ازلی را نمی‌شود از خود دور کرد.',NULL);
INSERT INTO "verses" VALUES(1937313,2145,8,1,'نصیبهٔ ازل از خود نمی‌توان انداخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937314,2145,9,0,'مگر گشایشِ حافظ در این خرابی بود','مثل اینکه قسمت حافظ این بود که گشایش کارش در این خرابی و مستی باشد؛ که بخشش ازلی، او را در کار می مغان انداخت.',NULL);
INSERT INTO "verses" VALUES(1937315,2145,9,1,'که بخششِ ازلش، در میِ مغان انداخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937316,2145,10,0,'جهان به کامِ من اکنون شود که دورِ زمان','هوش مصنوعی: اکنون که زمان اجازه می‌دهد، همه چیز مطابق میل من خواهد شد و من در خدمت بزرگ‌ترین آقای عالم قرار گرفته‌ام.',NULL);
INSERT INTO "verses" VALUES(1937317,2145,10,1,'مرا به بندگیِ خواجهٔ جهان انداخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937318,2146,7,0,'ترک افسانه بگو حافظ و مِی نوش دمی','به افسانه بسوخت‌: به داستان (و شنیدن قصه ما) سوخت.',NULL);
INSERT INTO "verses" VALUES(1937319,2146,7,1,'که نَخُفتیم شب و شمع به افسانه بسوخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937320,2146,6,0,'ماجرا کم کن و بازآ که مرا مردمِ چشم','ماجرا و نزاع را پایان بده و باز آی، زیرا که مردم چشم من به شکرانهٔ دیدارت خرقه (زهد) مرا به‌در آورده و سوخته است (و منتظر دیدار دوبارهٔ توست)',NULL);
INSERT INTO "verses" VALUES(1937321,2146,6,1,'خرقه از سر به درآورد و به شکرانه بسوخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937322,2146,5,0,'چون پیاله دلم از توبه که کردم بشکست','هوش مصنوعی: وقتی که دلم از توبه‌ای که کردم شکست، حالتی شبیه به لاله پیدا کرد. در این حال، بدون شراب و جایی برای نوشیدن، دلم به شدت سوخت و نگران شدم.',NULL);
INSERT INTO "verses" VALUES(1937323,2146,5,1,'همچو لاله، جگرم بی می و خُمخانه بسوخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937324,2146,4,0,'خرقهٔ زهدِ مرا، آبِ خرابات ببُرد','مصرع اول‌: خرقه‌ زاهدی‌ام را به‌گرو در میخانه گذاشتم.',NULL);
INSERT INTO "verses" VALUES(1937325,2146,4,1,'خانهٔ عقلِ مرا، آتشِ میخانه بسوخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937326,2146,3,0,'آشنایی نه غریب است که دلسوزِ من است','هوش مصنوعی: این شخص آشنا و نزدیک به من است و می‌تواند به احساسات و دردم توجه کند. زیرا من از خودم دور شده‌ام و این احساسات باعث شده که کسی دیگر به خاطر من دچار ناراحتی و سوختن شود.',NULL);
INSERT INTO "verses" VALUES(1937327,2146,3,1,'چون من از خویش برفتم، دلِ بیگانه بسوخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937328,2146,2,0,'سوزِ دل بین که ز بس آتش اشکم، دلِ شمع','هوش مصنوعی: دلِ من به خاطر درد و رنجی که دارم، مثل شمعی است که در آتش اشک‌هایم می‌سوزد. دیشب، این شمع به خاطر محبتش به من، مشابه پروانه‌ای در آتش سوخت.',NULL);
INSERT INTO "verses" VALUES(1937329,2146,2,1,'دوش بر من ز سرِ مِهر، چو پروانه بسوخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937330,2146,1,0,'تنم از واسطهٔ دوریِ دلبر بگداخت','هوش مصنوعی: تنم به خاطر دوری محبوبم می‌سوزد و جانم از عشق چهره‌ی دلنشینش در آتش می‌سوزد.',NULL);
INSERT INTO "verses" VALUES(1937331,2146,1,1,'جانم از آتشِ مهرِ رخِ جانانه بسوخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937332,2146,0,1,'آتشی بود در این خانه که کاشانه بسوخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937333,2145,3,0,'شراب‌خورده و خِوی‌کرده می‌رَوی به چمن','مست و گرم و عرق‌کرده در چمن راه می‌روی و طراوت روی تو ارغوان را سرخ و تب‌دار کرد.',NULL);
INSERT INTO "verses" VALUES(1937334,2145,3,1,'که آبِ روی تو آتش در ارغوان انداخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937335,2145,2,0,'به یک کرشمه که نرگس به خودفروشی کرد','نرگس با کرشمه فقط خودنمایی کرد اما چشم تو با یک کرشمه صد غوغا و آشوب در جهان افکند.',NULL);
INSERT INTO "verses" VALUES(1937336,2145,2,1,'فریبِ چشمِ تو صد فتنه در جهان انداخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937337,2143,5,0,'بس غریب افتاده است آن مور خَط، گِردِ رُخَت','خطّ ِ عذار ِ تو در گرداگرد ِ چهره‌یِ تو تنها و غریب واقع شده و غریب افتاده‌است. هرچند که خط ِ مشکین در نگارستان غریب نیست. غریب افتادن ِ خط ِ سیاه یا سبز (تیره) در گرداگرد ِ رخ و چهره‌یِ سفید ِ یار می‌توانَد به دلیل ِ اندکی و در اقلّیت بودن ِ رنگ ِ تیره در صورت ِ یار باشد. که انگار قومی یا مسافری در جایی کم و غریب اند. و در ادامه می‌گوید که هم‌چنان که در یک نمایش‌گاه نقّاشی، از خط ِ سیاه و مشکین استفاده می‌شود، خط ِ مشکین در نگارستان ِ صورت ِ تو، خطّ ِ سیاه چیز ِ عجیبی نیست و هم‌چنین این خط در آن‌جا غریب نیست و از غریبی به‌رنج نیست. به‌عبارتی به‌جا نشسته‌است.',NULL);
INSERT INTO "verses" VALUES(1937338,2143,5,1,'گرچه نَبوَد در نگارستان، خطِ مشکین غریب',NULL,NULL);
INSERT INTO "verses" VALUES(1937339,2143,6,0,'گفتم ای شامِ غریبان طُرِّهٔ شبرنگِ تو','به او گفتم: ای کسی که مویِ سیاه و شب‌‌رنگ‌ات مانند ِ شام ِ غریبان تاریک است! از ناله و آه ِ هنگام ِ سحرگاه ِ این غریب بترس و بپرهیز. تاثیر ِ دعا و آه ِ سحرگاهی را به یار یادآور می‌شود و از او می‌خواهد که از آن بپرهیزد. می‌گوید ای کسی که طرّه‌یِ تو چون شام ِ غریبان سیاه است و به‌عبارتی از عشق ِ تو روزگارم چون شب ِ غریبان سیاه شده، این شب، سحری دارد و دوری کن از این که این غریب، در سحرگاهان، ناله‌ئی کُنَد.',NULL);
INSERT INTO "verses" VALUES(1937340,2143,6,1,'در سحرگاهان حذر کن چون بنالد این غریب',NULL,NULL);
INSERT INTO "verses" VALUES(1937341,2143,7,0,'گفت حافظ آشنایان در مقامِ حیرتند','به من پاسخ داد و گفت: ای حافظ! آشناها، سرگردان و متعجّب اند. غریب که جایِ خود دارد! هیچ بعید و دور نیست که غریب خسته و غم‌گین بنشیند. به عبارتی می‌گوید حال و روز ِ آشناها هم تعریفی ندارد و متحیر مانده‌اند. تو که غریبی هیچ استبعادی ندارد که مجروح و خسته و غم‌گین در جایی بنشینی. آشنا و غریب با هم تضاد دارند و دور نیز با غریب متناسب است. به‌عبارتی در پاسخ به درخواست ِ التفات ِ شاعر و تهدید ِ او به آه و ناله‌یِ سحری، می‌گوید که تو نباید برایِ خود جایگاه ِ خاصی قائل شوی. در جایی که آشنایان در مقام ِ حیرت اند، غریب اگر خسته و غمگین بنشیند، موضوع ِ عجیب و دور از انتظاری نیست.',NULL);
INSERT INTO "verses" VALUES(1937342,2143,7,1,'دور نَبوَد گر نشیند خسته و مسکین غریب',NULL,NULL);
INSERT INTO "verses" VALUES(1937343,2144,0,0,'ای شاهد قدسی، کِه کَشَد بند نقابت؟','ای محبوب ِ بهشتی! چه کسی بند ِ روبند ِ تو را می‌کشد؟ و ای مرغ ِ بهشتی! چه کسی دانه و آب به تو می‌دهد؟ بند ِ نقاب کشیدن، نزدیک بودن و محرم بودن را نشان می‌دهد و دانه و آب دادن نیز نوعی هم‌خانه بودن. از مخاطب ِ شعر ِ خود با لحنی شبیه ِ عتاب و آمیخته با حسادت پرسشی می‌کند. شاهد به معنایِ معشوق و محبوب و زیباروی آمده‌است. برخلاف ِ «قُدسی» که در ادبیات ِ کهن و به‌ویژه ادبیات ِ عرفانی، نوعی هاله‌یِ قداست و پاکی و الاهی با خود دارد، شاهد، عبارتی با بار ِ معنایی ِ زمینی و چه‌بسا مذموم دارد. با این برداشت‌ها، این ترکیب ِ شاهد ِ قدسی، تناقضی هم در خود دارد. با نوعی دلهره آمیخته با حسادت، یا در گفت و گویی خیالی میان ِ خود و معشوق، یا مستقیم، مورد ِ خطاب قرار می‌دهد که چه کسی به تو نزدیک است و می‌تواند بند ِ نقاب ِ تو را بکشد و چهره‌یِ بی روبند ِ تو را ببیند.',NULL);
INSERT INTO "verses" VALUES(1937344,2144,0,1,'وی مرغ بهشتی، که دهد دانه و آبت؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937345,2144,1,0,'خوابم بشد از دیده در این فکر جگرسوز','در این فکر ِ جگرسوز که آغوش ِ چه کسی منزل ِ آسایش و خواب ِ تو شده، خواب از دیده‌یِ من رفته‌است. در آغوش ِ چه کسی می‌آسایی و به خواب می‌روی؟',NULL);
INSERT INTO "verses" VALUES(1937346,2144,1,1,'کآغوشِ که شد منزل آسایش و خوابت؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937347,2144,2,0,'درویش نمی‌پرسی و ترسم که نباشد','حالی از تهی‌دست و درویش نمی‌پرسی! می‌ترسم که توجه و بیمی از این‌که خدا تو را بیامرزد نداشته باشی و اعتنا و میلی به انجام ِ ثواب نداشته باشی! معروف است که پرسیدن ِ درویش، یا به فکر ِ نیازمندان و مستمندان بودن، ثوابی است که نیکوکار، پاداش ِ انجام ِ این کار ِ خوب و پسندیده را در آخرت از خدا خواهد گرفت. انگاری شاعر در این بیت خود را درویش گفته و انتظار دارد که همان‌طور که اغنیا و نیکوکاران، برای ثواب، حالی از فقرا و نیازمندان می‌پرسند و دستی از او می‌گیرند، یار، جویایِ احوال ِ او شود که ثواب دارد! و چون می‌بیند که یار چنین التفاتی به او ندارد، به طنز ِ آمیخته به طعنه می‌گوید بیم دارم که هیچ به فکر ِ آخرت ِ خود نباشی! و ترس و فکر و واهمه‌ئی از بابت ِ آمرزش ِ حق نداری و انگار اعتنا و میل و رغبتی به انجام ِ کار ِ ثواب هم نداری!',NULL);
INSERT INTO "verses" VALUES(1937348,2144,2,1,'اندیشهٔ آمرزش و پروای ثوابت',NULL,NULL);
INSERT INTO "verses" VALUES(1937349,2144,3,0,'راه دل عشّاق زد آن چشم خماری','آن چشم ِ خماری ِ تو، دل ِ عاشقان را دزدیده‌است، یا: آن چشم ِ خمار، نغمه‌ئی باب ِ دل ِ عاشقان زده‌است. از این ناز و عشوه و وضعی که داری، مشخّص است که شراب ِ تو، مست است. «این شیوه»، شیوه‌یِ چشم ِ یار است که شرابی خوش نوشیده‌است و مست است و چنین راه ِ دل ِ عشاق می‌زند.',NULL);
INSERT INTO "verses" VALUES(1937350,2144,3,1,'پیداست از این شیوه که مست است شرابت',NULL,NULL);
INSERT INTO "verses" VALUES(1937351,2143,4,1,'همچو برگِ ارغوان بر صفحهٔ نسرین، غریب',NULL,NULL);
INSERT INTO "verses" VALUES(1937352,2144,4,0,'تیری که زدی بر دلم از غمزه خطا رفت','تیری که از غمزه بر دل ِ من زدی، خطا رفت. تا این بار ببینیم که اراده و عزم ِ درست ِ تو چه تدبیری خواهد اندیشید. تیری از غمزه، اگر غمزه در معنایِ مژه و در معنایِ برهم زدن ِ مژگان از ناز و کرشمه باشد، می‌توان گفت تیری که یار از غمزه به دل ِ یار زده، تیر ِ مژگان و تیر ِ نگاه و کرشمه است که بر دل ِ یار زده. از غمزه خطا رفت را هم اگر به این شکل معنی کنیم که با ناز و غمزه زدی، به همین خاطر که دقیق نشانه‌گیری نکردی، خطا رفت و درست به هدف نخورد. و باید ببینیم که این بار که به‌درستی و با دقت و با رایِ صواب و قصد و عزم ِ راست و درست تیر بزنی، چه خواهد شد. اندیشه و رای و صواب نیز در تناسبی، معنایِ دیگری ایجاد می‌کنند. رای ِ صواب را حکم و اراده و میل ِ درست و راست در نظر بگیریم. و اندیشه را هم به معنایِ تدبیر و تفکر و هم به معنای بیم می‌شود در نظر گرفت. تا حکم ِ صواب ِ تو این بار چه فکری خواهد کرد.',NULL);
INSERT INTO "verses" VALUES(1937353,2144,4,1,'تا باز چه اندیشه کند رأی صوابت',NULL,NULL);
INSERT INTO "verses" VALUES(1937354,2144,5,1,'پیداست نگارا که بلند است جَنابت',NULL,NULL);
INSERT INTO "verses" VALUES(1937355,2144,6,0,'دور است سر آب از این بادیه، هشدار','بسیار می‌باید راه بپیمایی تا به سر ِ آب برسی. مبادا غول ِ بیابان در میانه‌یِ راه تو را به سراب بفریبد. مخاطب ِ این هش‌دار، می‌تواند دل ِ خود ِ شاعر باشد نه مخاطب ِ شعر. و در بیت ِ بعدی نیز دل ِ خود را خطاب قرار داده.',NULL);
INSERT INTO "verses" VALUES(1937356,2144,6,1,'تا غول بیابان نفریبد به سرابت',NULL,NULL);
INSERT INTO "verses" VALUES(1937357,2144,7,0,'تا در ره پیری به چه آیین رَوی ای دل','حالا که دوران ِ جوانی ِ تو به غلط صرف شد. ببینیم در ره ِ پیری به چه طریق و روشی خواهی رفت. ره ِ پیری، مسیری را به ذهن ِ من می‌آورد که در پیری طی خواهد کرد. به آئینی رفتن یعنی به شیوه و سبکی زندگی کردن. به طعنه سخن می‌گوید: ببینیم زمان ِ پیری ِ خود را به چه آئین و طرز و روشی خواهی پیمود. حالا که ایّام ِ جوانی را به غلط و به نادرستی سپری کردی. حال مشخص نیست که منظور ِ شاعر از غلط چیست و آئین و روش کدام است! هم می‌توان گفت که در جوانی نتوانستی اندوخته‌ئی برای آخرت بیندوزی و در دوران ِ پیری جبران کن و به مذهب و آئینی برو که چنین اندوخته‌ئی با خود ببری؛ هم می‌توان برعکس ِ این را تلقی کرد. که در جوانی که نتوانستی به کام و آرزویِ دل برسی، ببینیم پیری چه می‌کنی!',NULL);
INSERT INTO "verses" VALUES(1937358,2144,7,1,'باری به غلط صرف شد ایّامِ شبابت',NULL,NULL);
INSERT INTO "verses" VALUES(1937359,2144,8,0,'ای قصرِ دل‌افروز که منزلگهِ انسی','ای قصر ِ دل‌افروز که خانه‌یِ امید و منزل ِ اُنس ِ مایی. از خدا می‌خواهم که آفت ِ ایّام، تو را خراب نکُنَد. به نظر ِ من، مخاطب ِ این بیت، همانا قصر و کاخ است. البته می‌توان استعاره از معشوق یا یار هم در نظر گرفت. اما حسی که من می‌گیرم، نوعی دعایِ خیر برای قصر ِ شخص ِ بزرگی است که این قصر ِ دل‌افروز، منزل‌گاه ِ اُنس است. و منزل‌گَه ِ اُنس، هم می‌تواند اشاره به جایی باشد که عاشق و معشوق در آن موانست و دیدار و وصال داشته‌اند؛ و هم می‌تواند اشاره به قصر و تالار و خانه‌یِ بزرگی باشد که عشاق و شاعران و اهل ِ دل را در آن، راهی بوده و در آن مجالس ِ انس، روزگاری خوش داشته‌اند.',NULL);
INSERT INTO "verses" VALUES(1937360,2144,8,1,'یا رب مَکُناد آفتِ ایّام، خرابت',NULL,NULL);
INSERT INTO "verses" VALUES(1937361,2144,9,0,'حافظ نه غلامیست که از خواجه گریزد','حافظ، آن غلامی نیست که از خواجه و ارباب ِ خود بگریزد و برود. من از خشم گرفتن ِ تو خراب ام. آشتی کن و برگرد. خواجه، سلطان و ارباب، گاهی بر بندگان ِ خود خشم می‌گیرد. در هر حال ِ حکم ِ او جاری و ساری است و جُرمی بر او نبود و بسته به کَرَم و عنایت و لطف ِ خواجه بود که بر بنده ببخشاید و مهربانی کند یا نه. گاهی غلامان از عتاب و خشم ِ اربابان ِ خود می‌نالیدند یا می‌گریختند، اما غلامانی با وجود ِ جور و جفا و خشم ِ خواجگان، هم‌چنان به او وفادار می‌ماندند',NULL);
INSERT INTO "verses" VALUES(1937362,2144,9,1,'صلحی کن و بازآ که خرابم ز عِتابت',NULL,NULL);
INSERT INTO "verses" VALUES(1937363,2145,0,0,'خَمی که ابرویِ شوخِ تو در کمان انداخت','آن خم زیبا که در ابرو انداختی همچون کمانی بود که کشیدی و به جان ناتوان من تیر زدی',NULL);
INSERT INTO "verses" VALUES(1937364,2145,0,1,'به قصد جانِ منِ زارِ ناتوان انداخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937365,2145,1,0,'نبود نقش دو عالَم، که رنگ الفت بود','هیچ چیزی وجود نداشت اما از ابتدا عشق وجود داشت؛ عمر و روزگار عشق خیلی کهن است و امروزی نیست.',NULL);
INSERT INTO "verses" VALUES(1937366,2145,1,1,'زمانه طرح محبّت، نه این زمان انداخت',NULL,NULL);
INSERT INTO "verses" VALUES(1937367,2144,5,0,'هر ناله و فریاد که کردم نشنیدی','هرچه‌قدر که ناله و فریاد کردم، تو نشنیدی. معلوم است و پیداست که درگاه و آستانه‌یِ قصری که در آن زندگی می‌کنی رفیع است. (که صدای من و ناله و فریاد ِ من به گوش ِ تو نمی‌رسد) حسی مثل ِ اختلاف ِ طبقاتی ِ امروز را به ذهن می‌آورد که ناله و فریاد ِ ضعفا به گوش ِ بلندمرتبه‌ها نمی‌رسد. و هم‌چنین این حس را از بیت می‌گیرم که شاعر به تضرّع یا گدایی یا عرض ِ نیاز و زاری به در ِ معشوق آمده و از آن‌جا سر و صدا و استغاثه کرده. اما معشوق صدایِ او را نشنیده و التفاتی نکرده. و شاعر به کنایه گفته پیداست و به نظر می‌رسد که جناب و آستانه‌یِ تو بسیار بلند است که صدای من را نشنیدی.',NULL);
INSERT INTO "verses" VALUES(1937368,2161,2,0,'ز کارِ ما و دلِ غنچه صد گره بگشود','از کار ما و دل بسته و غمگین غنچه، صد شادی آورد آنگاه که نسیم خوش‌عطر بهاری عاشق تو شد.',NULL);
INSERT INTO "verses" VALUES(1937369,2140,8,0,'حافظ ز دیده دانهٔ اشکی همی‌فشان','این‌جا شاعر، دانه‌یِ اشک (قطره‌یِ اشک) را به دانه‌ئی که پرندگان را ترغیب می‌کُنَد که به سویِ دام بیایند تشبیه کرده. و وصل را به پرنده. می‌گوید ای حافظ! دانه‌یِ اشکی از دیده بیفشان، به امید ِ این‌که وصل به دام ِ تو بیفتد! یار به‌خاطر ِ اشک ِ تو به وصال مایل شود و به سمت ِ تو بیاید.',NULL);
INSERT INTO "verses" VALUES(1937370,2140,8,1,'باشد که مُرغِ وصل کُند قصدِ دامِ ما',NULL,NULL);
INSERT INTO "verses" VALUES(1937371,2134,0,0,'دل می‌رود ز دستم صاحب‌دلان خدا را','ای صاحب‌دلان شما را به خدا قسم می‌دهم که کمکم کنید! نزدیک است که دلم از دست برود! (و عشقم را آشکار کنم) افسوس و دردا که راز ِ پنهان، آشکار خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1937372,2134,0,1,'دردا که راز پنهان خواهد شد آشکارا',NULL,NULL);
INSERT INTO "verses" VALUES(1937373,2134,1,0,'کشتی‌شکستگانیم ای بادِ شُرطِه برخیز','کشتی ِ ما شکسته است. (ما، درون ِ کشتی نشسته‌ایم) ای باد ِ موافق، برخیز و خبر ِ پایان ِ توفان را برای ما بیاور، به امید ِ این که بتوانم (بتوانیم) باز یار ِ آشنا را ببینم (ببینیم).',NULL);
INSERT INTO "verses" VALUES(1937374,2134,1,1,'باشد که باز بینم دیدارِ آشنا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937375,2134,2,0,'ده‌روزه مِهرِ گردون افسانه است و افسون','مدت کوتاه زندگی زود به پایان می‌رسد گویی که داستان و افسانه‌ای بیش نبوده است. آن را فرصتی بشمار که در حق ِ یاران خوبی کنی.',NULL);
INSERT INTO "verses" VALUES(1937376,2134,2,1,'نیکی به جای یاران فرصت شمار یارا',NULL,NULL);
INSERT INTO "verses" VALUES(1937377,2134,3,0,'در حلقهٔ گُل‌ و مُل خوش خواند دوش بلبل','در بزمی که با گل (معشوق بلبل) و شراب بود بلبل چه خوش آوازی خواند: می ِ صبح‌گاهی را بیاور و بیدار شوید ای باده نوشان!',NULL);
INSERT INTO "verses" VALUES(1937378,2134,3,1,'هاتِ الصَّبُوحَ هُبّوا یا ایُّها السُّکارا',NULL,NULL);
INSERT INTO "verses" VALUES(1937379,2134,4,0,'ای صاحبِ کرامت شُکرانهٔ سلامت','ای کسی که کرامتی داری، به شکرانه‌یِ سلامت و تن‌درستی، زمانی هم به درویش ِ بی‌نوا مهربانی کن. (اگر منظور از "روزی"، رزق و روزی باشد= به درویش بینوا کمک کن)',NULL);
INSERT INTO "verses" VALUES(1937380,2134,4,1,'روزی تَفَقُّدی کن درویشِ بی‌نوا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937381,2134,5,0,'آسایشِ دو گیتی تفسیرِ این دو حرف است','آسایش ِ دو گیتی (این جهان و جهان ِ آخرت) تفسیر ِ این دو عبارت است: ۱. با دوستان مروّت کردن ۲. با دشمنان مدارا کردن. جدا از معنایِ مستقل و کامل ِ این بیت که پندی در خور است که امروزه شکل ِ ضرب‌المثل هم گرفته، می‌توان در ادامه‌یِ گفته‌ی بیت ِ پیشین که از صاحب ِ کرامت، تفقّد می‌طلبد، این‌جا هم می‌گوید که اگر تو کریمی و من دوست ِ تو ام، برای این‌که به آسایش ِ دو گیتی دست یابی، با من مروّت، نرم‌دلی و انصاف و بزرگواری جوانمردی کن. و اگر دشمن هم باشم، با من مدارا و ملایمت کن.',NULL);
INSERT INTO "verses" VALUES(1937382,2134,5,1,'با دوستان مُرُوَّت با دشمنان مُدارا',NULL,NULL);
INSERT INTO "verses" VALUES(1937383,2134,6,0,'در کویِ نیک‌نامی ما را گذر ندادند','ما را در محلّه‌ی نیک‌نامی راه ندادند. سرنوشت ما این است که نیک‌نام نباشیم. و اگر تو این را نمی‌پسندی، برو و قضا را دگرگون کن.',NULL);
INSERT INTO "verses" VALUES(1937384,2135,0,0,'به مُلازِمانِ سلطان، که رساند این دعا را؟','چه‌کسی این دعا را به ملازمان ِ سلطان می‌رساند که: به شکرانه‌یِ پادشاهی، گدارا از نظر ِ خودت مَران! در راه ِ شکرگزاری برای رسیدن به نعمتی، چیزی به فقرا می‌دهند.',NULL);
INSERT INTO "verses" VALUES(1937385,2135,0,1,'که به شُکرِ پادشاهی، زِ نظر مَران گدا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937386,2135,1,0,'ز رقیبِ دیوسیرت، به خدای خود پناهم','از دست ِ رقیب ِ شیطان صفت، به خدایِ خود پناه می‌بَرَم. مگر این که شهاب ِ ثاقب، به خاطر ِ خدا، کمکی کند. جمله به شکلی است که در برابر ِ رقیب ِ دیوسیرت و شیطان صفت عاجز است. و از او به خدا می‌پناهد (پناه می‌بَرَد). کاری از دست ِ او بر نمی‌آید! مگر این که همان‌طور که در قرآن نوشته که خدا شیطان‌ها را با شهاب ِ ثاقب می‌رانَد و عذاب می‌دهد، شهاب ِ ثاقب، محض ِ رضایِ خدا، این بار بیاید به کمک ِ شاعر و رقیب ِ شیطان‌صفت را بزند.',NULL);
INSERT INTO "verses" VALUES(1937387,2135,1,1,'مَگَر آن شهابِ ثاقِب مددی دهد، خدا را!',NULL,NULL);
INSERT INTO "verses" VALUES(1937388,2135,2,0,'مُژِه‌یِ سیاهت اَرْ کرد به خونِ ما اشارت','نگارا! اگر مژه‌یِ سیاه ِ تو به تو توصیه کرد که خون ِ مرا بریزی؛ یا فرمان ِ قتل ِ ما را داد، از این واهمه کن که ممکن است تو را فریب بدهد. و کار ِ اشتباهی انجام نده! زِ فریب ِ او بیندیش: بترس که او فریب‌کار است؛ به این فکر کن که ممکن است که تو را با عشوه و مکر غافل کند. مبادا کار ِ اشتباهی کنی.',NULL);
INSERT INTO "verses" VALUES(1937389,2135,2,1,'ز فریبِ او بیندیش و غلط مکن، نگارا',NULL,NULL);
INSERT INTO "verses" VALUES(1937390,2135,3,0,'دلِ عالمی بِسوزی چُو عِذار بَرفُروزی','وقتی که چهره‌ات را برافروخته می‌کنی، دل ِ یک عالَم را می‌سوزی. مگر چه سودی از این کار می‌بری که مدارا نمی‌کنی؟ برافروخته کردن ِ رخسار، ناشی از خشم و غضب، یا دلبری و عشوه‌گری می‌تواند باشد. و برافروخته کردن به معنای شعله‌ور کردن، با سوزاندن ِ دل ِ مردم تناسب دارد. با آتش ِ رخساره‌ات، دل ِ عالَم را می‌سوزانی. دل‌سوخته، معنای عاشق هم می‌دهد. چهره‌یِ برافروخته‌یِ تو همه‌ی عالَمیان را عاشق و دل‌سوخته‌ی تو می‌کُنَد. و در مصراع ِ دوم، از معشوق می‌خواهد که با خلق ِ جهان مدارا کند و دل ِ ایشان را نسوزاند. و به طعنه می‌پرسد که مگر چه سودی عاید ِ تو می‌شود از سوختن ِ دل ِ خلق؟ نکُن!',NULL);
INSERT INTO "verses" VALUES(1937391,2135,3,1,'تو از این چه سود داری، که نمی‌کنی مدارا؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937392,2135,4,0,'همه‌شب در این اُمیدم که نسیمِ صبحگاهی','سرتاسر ِ شب (هر شب) امیدوار ام بر این امید که بویِ خوشی که از باد ِ ملایم ِ صبحگاهی می‌آید، با پیغامی آشنا (رایحه‌ئی که از یار می‌آید)، من (که آشنای او یَم) را نوازش کند. شاعران، باد ِ خوشی که می‌وزید را پیامی از یار می‌آوردند و باد ِ صبا را پیغام‌آور ِ یار؛ که از میان ِ گیسوان ِ او گذشته و عطر ِ خوش ِ زلف ِ یار را برای شاعر آورده‌است.',NULL);
INSERT INTO "verses" VALUES(1937393,2135,4,1,'به پیام آشنایان، بنوازد آشنا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937394,2135,5,0,'چه قیامت است جانا، که به عاشقان نمودی؟','این چه قیامت است که به عاشقان نشان دادی؟ ای دل و جان فدایِ رویِ تو، رخ بنما! چهره‌ات را به ما نشان بده! قیامت در لغت، برخاستن و ایستادن هم هست. شور و آشوب و غوغایی که در روز ِ رستاخیز به‌پا‌می‌خیزد نیز می‌تواند قیامت تلقّی شود. تصوّر کنید محبوبی را که چهره‌اش را پوشانده اما برمی‌خیزد و می‌ایستد یا را می‌رود. که قیامتی به عاشقان نموده است. و از او می‌خواهد که عذار و چهره‌ی خودش را نیز نشان دهد.',NULL);
INSERT INTO "verses" VALUES(1937395,2135,5,1,'دل و جان فدای رویت، بِنَما عِذار ما را',NULL,NULL);
INSERT INTO "verses" VALUES(1937396,2135,6,0,'به خدا، که جرعه‌ای دِه تو به حافظِ سحرخیز','تو را به خدا سوگند می‌دهم که جرعه‌ئی (شراب، پیمانه‌یِ شراب یا یک جرعه شراب) در هنگام ِ صبح به حافظ ِ سحرخیز بده. (که او با نوشیدن ِ آن تو را دعا کنَد). که دعای هنگام ِ صبح که تاثیر ِ زیادی دارد، بر شما اثر خواهد کرد. دعایِ خیر ِ من به دنبال ِ شما خواهد بود. جرعه نوشی در شعر ِ حافظ در معنایِ نوشیدن ِ ته‌مانده‌یِ ممدوح و یار به هدف ِ ابراز ِ خاک‌ساری یا تبرُّک یا قصد ِ قربت یا رسیدن به آمال هم آمده.',NULL);
INSERT INTO "verses" VALUES(1937397,2135,6,1,'که دعایِ صبحگاهی، اثری کند شما را',NULL,NULL);
INSERT INTO "verses" VALUES(1937398,2136,0,0,'صوفی بیا که آیِنِه، صافی‌ست جام را','ای صوفی بیا که آینه‌یِ جام، صافی است تا صفایِ می ِ سرخ را ببینی. صوفی و صافی و صفا، آرایه‌های جناس و اشتقاق دارند. «را» در مصراع ِ نخست، رایِ فکّ ِ اضافه است. جام در زلالی و صافی، به آینه تشبیه شده. غزل با صدا کردن و فراخواندن ِ صوفی شروع می‌شود که بیاید و چیزی را ببیند. انگار که در ادامه‌ی صحبتی پیشین، می‌خواهد چیزی را به کسی نشان دهد.',NULL);
INSERT INTO "verses" VALUES(1937399,2136,0,1,'تا بِنگَری صَفایِ مِیِ لَعل‌فام را',NULL,NULL);
INSERT INTO "verses" VALUES(1937400,2134,6,1,'گر تو نمی‌پسندی تغییر کن قضا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937401,2134,7,0,'آن تَلخ‌وَش که صوفی اُم‌ُّالخَبائِثَش خواند','آن شراب تلخ که صوفی آن را مادر ِ پلیدی‌ها خوانده‌است، برای من از بوسه بر رخسار (یا بوسه‌یِ دوشیزگان) لذت‌بخش‌تر و شیرین‌تر است.',NULL);
INSERT INTO "verses" VALUES(1937402,2134,7,1,'اَشهیٰ لَنا و اَحلیٰ مِن قُبلَةِ العَذارا',NULL,NULL);
INSERT INTO "verses" VALUES(1937403,2134,8,0,'هنگامِ تنگ‌دستی در عیش کوش و مستی','زمانی که تنگ‌دست بودی، در کار ِ خوش‌گذرانی و گذران ِ زندگی و مستی باش. چون که مستی و خوشی، کیمیایی است که گدا و بی‌نوا را تبدیل به ثروتمند و دارا می‌کند. در شعر ِ حافظ به این خاصیت ِ مستی بسیار اشاره شده‌است که گدا خود را ثروتمند می‌بیند و شاه و گدا در عالَم ِ مستی یک‌سان اند.',NULL);
INSERT INTO "verses" VALUES(1937404,2132,6,1,'جوانانِ سعادتمند پندِ پیرِ دانا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937405,2132,7,0,'حَدیث از مُطرب و مِی گو و رازِ دَهر کمتر جو','زیاد دنبال ِ راز ِ دهر نباش. خوش باش و در باره‌یِ مطرب و می حرف بزن. سخن ِ تازه بگو از مطرب و می. در باره‌ی اسرار و رازهای دنیا زیاد فکر نکن که نه تا حالا کسی با ابزار ِ خِرَد و دانش نتوانسته کلید ِ این معما را بگشاید و نه کسی بعد از این خواهد توانست! دَم را به شادی بگذران و حدیث از مطرب و می بگو.',NULL);
INSERT INTO "verses" VALUES(1937406,2132,7,1,'که کس نَگشود و نَگشاید به حکمت این مُعمّا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937407,2132,8,0,'غزل گفتی و دُر سُفتی بیا و خوش بخوان حافظ','غزل گفتی و [با این غزل گفتنت، انگار،] دُر (مروارید و اشاره به سخن زیبا) [برای ساخت گردنبند] سوراخ کردی. بیا و غزلت را بخوان (هنرت را ارائه بده؛ منظور گردنبندی که ساختی). چرا که در مقابل نظم (شعر) تو، فلک (آسمان) عقدِ ثریا را ( گردنبند ثریا؛ خوشه‌ی پروین که به شکل گردنبند است) می‌افشاند (نثار می کند).',NULL);
INSERT INTO "verses" VALUES(1937408,2132,8,1,'که بر نظمِ تو اَفشانَد فَلَک عِقد ثُریّا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937409,2133,0,0,'صبا به لُطف بگو آن غزالِ رَعنا را','ای بادِ صبا! لطفی کن (به ملایمت) به آن غزالِ رعنا بگو که تو باعث شده‌ای که ما سر به کوه و بیابان بگذاریم. تو ما را در کوه و بیابان رها کرده‌ای.',NULL);
INSERT INTO "verses" VALUES(1937410,2133,0,1,'که سَر به کوه و بیابان تو داده‌ای ما را',NULL,NULL);
INSERT INTO "verses" VALUES(1937411,2133,1,0,'شِکر فُروش که عُمرَش دراز باد چرا','چرا شکرفروش احوالی از طوطیِ شکرخا نمی‌پرسد و از او دل‌جویی نمی‌کند؟ چرا سراغی نمی‌گیرد که بداند او کجاست؟',NULL);
INSERT INTO "verses" VALUES(1937412,2133,1,1,'تَفَقُّدی نَکُنَد طوطیِ شِکرخا را؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937413,2133,2,0,'غرورِ حُسنت اجازَت مَگَر نداد اِی گُل','ای گُل! تکبّر و نخوتی که از زیبایی به تو دست داده باعث شده که احوالی از بلبلِ شیدایِ خودت نپرسی؟ یا به عبارتی: حتما زیبایی‌ات تو را مغرور کرده که از من سراغی نمی‌گیری.',NULL);
INSERT INTO "verses" VALUES(1937414,2133,2,1,'که پُرسِشی نکُنی عَندَلیب شیدا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937415,2133,3,0,'به خُلق و لطف توان کرد صیدِ اهلِ نظر','با اخلاقِ نیکو و ملاطفت و نرمی و مهربانی می‌توان اهلِ نظر را صید کرد. پرندهٔ دانا را نمی‌توان با به بند کشیدن و در دام انداختن گرفت.',NULL);
INSERT INTO "verses" VALUES(1937416,2133,3,1,'به بند و دام نگیرند مرغِ دانا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937417,2133,4,0,'ندانم از چه سبب رنگِ آشنایی نیست','نمی‌دانم که چرا آدم‌های بلند قد و سیاه چشم و ماه سیما، رسم و آئینِ دوستی ندارند.',NULL);
INSERT INTO "verses" VALUES(1937418,2136,1,0,'رازِ درونِ پَردِه زِ رِندانِ مَست پُرس','در ادامه‌ی خطاب‌اش به صوفی، پس از نشان دادن ِ صفایِ می ِ لعل‌فام، ادامه می‌دهد که اگر به دنبال ِ راز ِ درون ِ پرده ای، آن را از رندان ِ مست بپرس. که زاهد ِ عالی مقام، این حالت و این کیفیت را ندارد؛ و از این عشق و محبّت هم برخوردار نیست؛ که بتواند راز ِ درون ِ پرده را بداند یا اگر می‌داند، بتواند به پرسش ِ تو پاسخ بدهد. رند ِ مست و زاهد ِ عالی‌مقام در تقابل با هم آمده‌اند. و صوفی را کسی توصیف کرده که به دنبال ِ آگاهی از راز ِ درون ِ پرده، از زاهد ِ عالی‌مقام پرسان است. و شاعر، صفایِ می ِ لعل‌فام را و رندان ِ مست را آگاه‌تر و مهربان‌تر دانسته و به صوفی توصیه کرده که اگر راز ِ درون ِ پرده را می‌خواهد، آن را از رندان ِ مست (می‌تواند خود ِ شاعر باشد) بپرسد.',NULL);
INSERT INTO "verses" VALUES(1937419,2133,4,1,'سَهی‌قَدانِ سیَه‌‌چشمِ ماه‌سیما را',NULL,NULL);
INSERT INTO "verses" VALUES(1937420,2133,5,1,'به یاد دار مُحِبّانِ بادپیما را',NULL,NULL);
INSERT INTO "verses" VALUES(1937421,2133,6,0,'جُز این قَدَر نَتوان گفت در جَمالِ تو عیب','به‌جز این مقدار، نمی‌توان عیبی برای تو بر شمرد که برایِ رویِ زیبا، روشِ مهر و وفا نیست. مهر و وفا برای زیبارویان قرار داده نشده است. یا: در قضیهٔ جمالِ تو، به‌جز این (قَدَر و تقدیر) که مهر و وفا برای روی زیبا وضع نشده، به چیزِ دیگری نمی‌شود عیب گفت و ایراد گرفت. یعنی به قَدَر ایراد می‌گیرد نه به جمال.',NULL);
INSERT INTO "verses" VALUES(1937422,2133,6,1,'که وضع مِهر و وفا نیست رویِ زیبا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937423,2133,7,0,'در آسمان نه عجب گَر به گفتهٔ حافظ','عجیب نیست اگر نغمه‌ای که سیارهٔ زهره (معروف به مطرب و نوازنده فلک) بر روی شعر حافظ می‌نوازد، مسیحا را در آسمان به رقص بیاورَد.',NULL);
INSERT INTO "verses" VALUES(1937424,2133,7,1,'سُرودِ زُهره به رقص آورد مسیحا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937425,2134,8,1,'کاین کیمیایِ هستی قارون کند گدا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937426,2134,9,0,'سرکش مشو که چون شمع از غیرتت بسوزد','سرکش نشو. چون‌که دلبر از این سرکشی و نافرمانی ِ تو، غیرت خواهد کشید و خشمگین خواهد شد. و تو را مانند ِ شمعی که هرگاه سرکشی کند، آن را می‌کُشند، خواهد سوزاند. سنگ ِ خارا در کف ِ دلبر مانند ِ موم نرم و در اختیار ِ او است. تو که جایِ خود داری!',NULL);
INSERT INTO "verses" VALUES(1937427,2134,9,1,'دلبر که در کفِ او موم است سنگِ خارا',NULL,NULL);
INSERT INTO "verses" VALUES(1937428,2134,10,0,'آیینهٔ سِکَندر جامِ مِی است بنگر','اگر دنبال ِ آیینه‌یِ اسکندر برای آگاهی از احوال ِ جهان هستی، به تو بگویم که این آینه، همانا جام ِ می است. به آن نگاه کن تا احوال ِ مملکت ِ دارا را به تو عرضه کند. جام ِ می، خاصیتی داشته که از خط ِ ساغر و از می ِ درون ِ آن، به نوعی فال و فرجام و راه‌نمایی می‌گرفتند. آئینه‌ی اسکندر هم خاصیتی داشته که از درون ِ آن می‌شد مسافت ِ زیادی را تحت ِ نظر داشت. عبارت‌های جهان‌نما و جهان‌بین برای هر دو به کار رفته.',NULL);
INSERT INTO "verses" VALUES(1937429,2134,10,1,'تا بر تو عرضه دارد احوالِ مُلکِ دارا',NULL,NULL);
INSERT INTO "verses" VALUES(1937430,2134,11,0,'خوبان پارسی‌گو بخشندگانِ عمرند','خوبان ِ پارسی گو به آدم جان ِ تازه و عمر ِ دوباره‌ئی می‌بخشند. ای ساقی! این خبر ِ خوش را به رندان ِ پارسا (پیران ِ پارسا) بده!',NULL);
INSERT INTO "verses" VALUES(1937431,2134,11,1,'ساقی بده بشارت رندانِ پارسا را',NULL,NULL);
INSERT INTO "verses" VALUES(1937432,2134,12,0,'حافظ به خود نپوشید این خرقهٔ مِی‌ْآلود','مصراع نخست: ۱. حافظ این خرقه‌یِ می آلود را به اختیار ِ خود نپوشیده است. ۲. حافظ این خرقه‌یِ می آلوده را بر تن ِ خود نمی‌پوشد. (تصمیم گرفت که نپوشد) مصراع ِ دوم: ای شیخ که دامن‌ات پاک است، (خرقه‌ات می آلود نیست) ما را معاف بدار!',NULL);
INSERT INTO "verses" VALUES(1937433,2134,12,1,'ای شیخِ پاک‌دامن معذور دار ما را',NULL,NULL);
INSERT INTO "verses" VALUES(1937434,2133,5,0,'چو با حبیب نِشینی و باده پِیمایی','وقتی که با یارِ خودت می‌نشینی و باده می‌نوشی، دوست‌دارانت را در یاد داشته باش و فراموش نکن! که باد را در می‌نوردند. جز باد چیزی به دست ندارند.',NULL);
INSERT INTO "verses" VALUES(1937435,2140,9,0,'دریای اَخضَرِ فَلَک و کَشتی هِلال','آسمان و ماه ِ درون ِ آن، به‌مانند ِ دریا و کشتی ِ داخل ِ آن، همه غرق ِ نعمت ِ حاجی قوام ِ ما هستند. حاجی قوام یا قوام‌الدین حسن از رجال ِ معروف ِ آل ِ مظفّر بوده است که در دوران ِ جوانی ِ حافظ در شیراز حکم‌رانی می‌کرده‌اند. گویا حاجی قوام بزم‌ها و خوان ِ پر نعمتی نیز داشته‌است که شاعر نیز از میهمانان ِ او در این بزم‌ها بوده و شاعر در چند غزل نیز از او به نیکویی یاد کرده‌است.',NULL);
INSERT INTO "verses" VALUES(1937436,2136,1,1,'کاین حال نیست زاهِدِ عالی‌مَقام را',NULL,NULL);
INSERT INTO "verses" VALUES(1937437,2136,2,0,'عَنقا، شِکارِ کَس نَشَوَد، دام بازچین','کسی نمی‌تواند عنقا را شکار کند. تو نیز دامی که چیده‌ای را برچین! که آن‌جا (جایی که به قصد ِ شکار ِ عنقا دام گسترده‌اند) چیزی جز باد به دست ِ دام نیست. باد به دست بودن کنایه از دست خالی برگشتن و چیزی به دست نیاوردن است. عنقا شکار ِ کس نخواهد شد. و از این که بخواهی دامی بگستری و عنقا صید کنی منصرف شو! چون که آن‌جا و در آن کار، همیشه دام ِ تو چیزی صید نخواهد کرد جز باد!',NULL);
INSERT INTO "verses" VALUES(1937452,2139,0,0,'دوش از مسجد سویِ میخانه آمد پیرِ ما','شاعر انگاری برای دوستان‌اش تعریف می‌کند که: دیشب، پیر ِ ما، از مسجد به میخانه آمد. ای یاران ِ طریقت، ای هم مسلکان ِ اهل ِ سلوک! بعد از این ما چه کاری باید بکنیم؟ نکته‌ئی که در این بیت هست این که شاعر از فعل ِ آمد استفاده کرده! نگفته پیر ِ ما سویِ میخانه رفت! گفته سویِ میخانه آمد. یعنی انگاری خود ِ شاعر در میخانه بوده و آن‌جا حضور داشته که دیده!',NULL);
INSERT INTO "verses" VALUES(1937453,2139,0,1,'چیست یارانِ طریقت بعد از این تدبیرِ ما؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937454,2139,1,0,'ما مریدان روی سویِ قبله چون آریم؟ چون','در ادامه‌یِ بیت ِ پیشین که دنبال ِ تدبیری می‌گشت، می‌گوید: ما مریدان که می‌بایست پی‌رو ِ پیر باشیم، چگونه رو به سویِ قبله بیاوریم و نماز بخوانیم، وقتی که پیر ِ ما روی به سویِ خانه‌یِ باده‌فروش دارد؟',NULL);
INSERT INTO "verses" VALUES(1937455,2139,1,1,'روی سویِ خانهٔ خَمّار دارد پیرِ ما',NULL,NULL);
INSERT INTO "verses" VALUES(1937456,2139,2,0,'در خراباتِ طریقت ما به هم منزل شویم','ما مریدان، با پیر ِ طریقت، در خرابات ِ طریقت، با هم در یک‌جا هم منزل می‌شویم. زیرا که در عهد ِ ازل، تقدیر ِ ما این‌چنین رفته‌است. چاره‌ئی نیست!',NULL);
INSERT INTO "verses" VALUES(1937457,2139,2,1,'کاین‌چنین رفته‌ است در عهدِ ازل تقدیرِ ما',NULL,NULL);
INSERT INTO "verses" VALUES(1937458,2139,3,0,'عقل اگر داند که دل در بندِ زلفش چون خوش است','اگر عقل بداند که دل در بند ِ زلف ِ یار چه قدر خوش است، عاقلان، به دنبال ِ زنجیر ِ ما، مانند ِ دیوانه ها می‌گردند. عاقلان دیوانه گردند، اگر گشتن را به معنایِ شدن در نظر بگیریم، به‌سادگی می‌توان گفت: عاقلان از پی ِ زنجیر ِ ما دیوانه می‌شوند. زنجیر ِ ما در این معنا می‌تواند همان زلف ِ یار باشد که دل ِ ما در بند ِ آن است و حال ِ خوشی هم دارد.',NULL);
INSERT INTO "verses" VALUES(1937459,2139,3,1,'عاقلان دیوانه گردند از پیِ زنجیرِ ما',NULL,NULL);
INSERT INTO "verses" VALUES(1937460,2139,4,0,'رویِ خوبت آیتی از لطف بر ما کشف کرد','۱. رویِ خوب ِ تو نشانه‌یی از خوبی و زیبایی را بر ما آشکار ساخت، ۲. رویِ خوب ِ تو، لطف و بخششی به ما کرد و تفسیر ِ آیتی را بر ما آشکار ساخت که پیش از آن نمی‌دانستیم، از آن زمان به بعد، در بیان ِ ما و شرح ِ ما جز لطف و خوبی نمی‌آید. چیزی جز لطف و خوبی و آیتی که رویِ خوب ِ تو بر ما کشف کرده را نمی‌توانیم در تفسیر ِ آیات ِ قرآن بیان کنیم. به عبارتی دیگر، خوبی ِ رویِ تو، نشانه‌یی از لطف است. به همین سبب، از زمانی که رویِ تو را برهنه و آشکار دیده‌ایم، جز لطف و خوبی تفسیر ِ دیگری نمی‌توانیم از آیات ِ خدا کنیم.',NULL);
INSERT INTO "verses" VALUES(1937461,2139,4,1,'زان زمان جز لطف و خوبی نیست در تفسیرِ ما',NULL,NULL);
INSERT INTO "verses" VALUES(1937462,2139,5,0,'با دلِ سنگینت آیا هیچ درگیرد شبی','آیا آه ِ آتشین و سوز ِ ناله‌یِ سحرگاهی ِ ما در دل ِ سنگین ِ تو هیچ تاثیری دارد؟ آه و سوز ِ سینه‌یِ شب‌گیر را هم می‌توان آه و سوزی دانست که هنگام ِ شبگیر و سحرگاه از سینه‌یِ شاعر بر می‌آید. و هم می‌توان سینه‌یِ شاعر را به مرغی تشبیه کرد که هنگام ِ سحر، آه و ناله‌های حزین و سوزناک می‌کُنَد.',NULL);
INSERT INTO "verses" VALUES(1937463,2139,5,1,'آهِ آتشناک و سوزِ سینهٔ شبگیرِ ما؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937464,2139,6,0,'تیرِ آهِ ما ز گردون بگذرد حافظ خموش','هشدار و تحذیری می‌دهد که از تیر ِ آه ِ ما حذر کن و بر جان ِ خودت رحم کن. چون که تیر ِ آه ِ ما بسیار نافذ است و حتا از فلک هم می‌گذرد. اما این هشدار را سرراست به یار نمی‌گوید. خطاب به خود می‌گوید که خاموش باش حافظ و تیر ِ آهی به سویِ فلک پرتاب نکن. اما در مصراع ِ دوم، پرهیز کن از تیر ِ ما به نظر می‌رسد مخاطب‌اش یار باشد نه خود ِ حافظ ِ مصراع ِ اول!',NULL);
INSERT INTO "verses" VALUES(1937465,2139,6,1,'رحم کن بر جانِ خود پرهیز کن از تیرِ ما',NULL,NULL);
INSERT INTO "verses" VALUES(1937466,2140,9,1,'هستند غرقِ نعمتِ حاجی‌قوامِ ما',NULL,NULL);
INSERT INTO "verses" VALUES(1937471,2136,2,1,'کآنجا، همیشه، باد به دست است، دام را',NULL,NULL);
INSERT INTO "verses" VALUES(1937472,2136,3,0,'دَر بَزمِ دُور، یک‌دو قدح دَرکَش و برو','در بزمی که به هر کسی به نوبت پیمانه‌ئی شراب می‌چشانند، یکی دو قدح سربکش و برو. این به آن معنا است که امیدوار نباش که وصال، همیشگی باشد. تنها می‌توان یک دو قدح در کشید و رفت و انتظار ِ وصال ِ همیشگی داشتن، کاری عبث است. بزم ِ دور استعاره از زندگی باشد. مثل ِ مهمانی‌یی که چند مدتی هر کسی در آن ساکن است.',NULL);
INSERT INTO "verses" VALUES(1937473,2136,3,1,'یَعنی طَمَع مَدار وِصالِ مُدام را',NULL,NULL);
INSERT INTO "verses" VALUES(1937474,2136,4,0,'ای دل! شَباب رَفت و نَچیدی گُلی زِ عِیش','ای دل! روزگار ِ جوانی گذشت و در آن روزگار گلی از باغ ِ عیش نچیدی. اکنون که پیر شده‌ای، به خاطر ِ آبروی خودت هنری مکن! مکُن هنری، یا هنری مکن را من تعبیری طنزآلود و کنایه‌آلود می‌بینم! هنری نکن، کار ِ خارق‌العاده‌ئی نکن! کار ِ خطرناکی نکن! به عبارتی، آن زمان که جوان بودی و برای جوانان، عیش و چیدن ِ گل ِ عیش مُجاز تلقی می‌شود (به‌عبارتی قابل ِ توجیه است و بی‌آبرویی ِ کم‌تری بر آن هست) این کار را نکردی! حالا که پیر شده‌ای، سر ِ پیری به خاطر ِ حفظ ِ آبرویِ خودت دستکم شاهکار خلق نکن!',NULL);
INSERT INTO "verses" VALUES(1937475,2136,4,1,'پیرانه‌‌سر مَکُن هُنَری نَنگ و نام را',NULL,NULL);
INSERT INTO "verses" VALUES(1937476,2136,5,0,'در عِیشِ نَقد کوش که چون آبخَور نَمانْد','سعی کن تا عیش ِ نقد را در دست داشته‌باشی. به این دلیل که آدم هم روضه‌ی دارالسلام و باغی که در آن آسایش و سلامت داشت را رها کرد، چون که آبخور، نصیب، چشمه‌ی آب ِ کوثر یا چشمه‌یِ جاودانگی در آن باقی نمانده بود. به‌عبارتی بهشت هم جاودانی و ابدی نبود. پس بکوش تا از هر آن عیشی که در حال برای تو میسر است، بهره‌مند شوی. بهشت در اینجا، به عنوان فعل استفاده شده است؛ از «هشتن» به معنای «رها کردن» یا «پایین گذاشتن» که با واژه «بهشت» به معنای «پردیس»، «جنّت» یا «مینو» جناس تام دارد.',NULL);
INSERT INTO "verses" VALUES(1937477,2136,5,1,'آدَم بِهِشت، روضِهٔ دارُالسَّلام را',NULL,NULL);
INSERT INTO "verses" VALUES(1937478,2136,6,0,'ما را بَر آستانِ تو، بس حَقِّ خِدمَت است','من در درگاه و محضر ِ تو بسیار خدمت کرده‌ام و از این بابت، حقّ ِ خدمت بر گردن ِ تو دارم. ای خواجه! به پاس ِ این خدمت، به ملاطفت و ترحّم و بنده‌نوازی، اعتنا و توجهی به من که غلام و چاکر ِ تو ام بکن.',NULL);
INSERT INTO "verses" VALUES(1937479,2136,6,1,'ای خواجه! بازبین به تَرَحُّم غلام را',NULL,NULL);
INSERT INTO "verses" VALUES(1937480,2136,7,0,'«حافظ» مُریدِ جامِ مِی است، ای صبا! برو!','۱. حافظ خواهنده و خواستار ِ جام ِ می است. ای صبا برو و به شیخ ِ جام و دارنده‌یِ جام از طرف ِ من اظهار ِ ارادت و بندگی بکن و بگو که حافظ جام ِ می می‌خواهد. ۲. اگر تو مرید ِ شیخ و مراد ِ خودی، حافظ، مرید ِ جام ِ می است. ای صبا! برو و به شیخ ِ جام بندگی و ارادت مرا برسان. هر سالکی در طریقت، مرید ِ شیخی است. و شاعر اعلام می‌کند، که مرید ِ جام ِ می است و شیخ ِ او نیز، شیخ ِ جام است.',NULL);
INSERT INTO "verses" VALUES(1937485,2136,7,1,'وز بنده بندگی بِرَسان شِیخِ جام را!',NULL,NULL);
INSERT INTO "verses" VALUES(1937502,2193,2,1,'چراغِ مصطفوی با شرارِ بولَهَبی‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1937503,2161,2,1,'نسیمِ گل چو دل اندر پیِ هوایِ تو بست',NULL,NULL);
INSERT INTO "verses" VALUES(1937504,2161,3,0,'مرا به بندِ تو دورانِ چرخ راضی کرد','دست قضا مرا به بند تو راضی کرد اما افسوس که رهایی مرا نیز به رضای تو موکول کرد!',NULL);
INSERT INTO "verses" VALUES(1937517,2181,7,0,'«حافظ» از حشمتِ پرویز، دگر، قِصِّه مَخوان','حافظا از بزرگی و شوکت پرویز دیگر سخن مگو که لب او جرعه‌کش از خسرو شیرین من است.',NULL);
INSERT INTO "verses" VALUES(1937518,2181,7,1,'که لَبَش، جُرْعِه‌کَشِ خُسروِ شیرینِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(1937519,2181,6,0,'یا رب این کَعْبِه‌یِ مَقْصود، تَماشاگَهِ کیست؟','خدایا این کعبه، منظور و مقصد کیست؟ که خارهای راهش بر من همچون گل و نسرین لطیف و نرم گشته‌است.',NULL);
INSERT INTO "verses" VALUES(1937520,2181,6,1,'که مُغِیلانِ طَریقش، گُل و نَسْرینِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(1937521,2181,5,0,'واعِظِ شِحنه‌شناس، این عَظِمَت گو مَفُروش','ای واعظی که دوست شحنه هستی زیاد پررویی و گستاخی مکن، زیرا که دل مسکین و دردمند من منزل‌گه و سرای سلطان است.',NULL);
INSERT INTO "verses" VALUES(1937522,2181,5,1,'زان که مَنْزِلْگَهِ سُلطان، دِلِ مِسْکینِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(1937523,2181,4,0,'دولتِ فَقْر خدایا به من ارزانی دار','خدایا ثروت فقر را به من عطا فرما که‌این بزرگی مرا صاحب‌حشمت و دولتمند می‌گرداند.',NULL);
INSERT INTO "verses" VALUES(1937524,2181,4,1,'کاین کِرامت، سَبَبِ حِشْمَت و تَمکینِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(1937525,2181,3,0,'تا مرا عشقِ تو، تعلیمِ سُخَن‌گفتن کرد','از روزی که عشق تو شعر‌گفتن به من آموخت مردمان از تحسین و آفرین گفتن به‌من باز نمی‌ایستند.',NULL);
INSERT INTO "verses" VALUES(1937526,2181,3,1,'خَلق را وِردِ زبان، مَدْحَت و تَحسینِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(1937527,2181,2,0,'یارِ من باش که زیبِ فَلَک و زینتِ دَهْر','بیا یار من باش تا با هم فلک و روزگار را باهم زینت بخشیده و بیاراییم؛ از روی زیبای تو و اشک‌های چون اختران پروین من.',NULL);
INSERT INTO "verses" VALUES(1937528,2181,2,1,'از مَهِ رویِ تو و اَشْکِ چو پَروینِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(1937529,2181,1,0,'دیدنِ رویِ تو را دیده‌یِ جان‌بین باید','دیدن روی تو‌، چشمی جان‌بین لازم دارد، چشم جهان‌بین من کی می‌تواند؟ و کجا در آن مرتبه است؟',NULL);
INSERT INTO "verses" VALUES(1937530,2181,1,1,'وین کجا مَرْتَبِه‌یِ چَشْمِ جَهان‌بینِ من است؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937531,2181,0,0,'روزْگاری‌ست که سودایِ بُتان، دینِ من است','مدتی است که هوس وصل بتان و زیبا‌یان، کیش و آیین من شده و غم این جستجو، شادی دل غمگین من را فراهم کرده است.',NULL);
INSERT INTO "verses" VALUES(1937532,2181,0,1,'غَمِ این کار‌، نِشاطِ دِلِ غَمْگینِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(1937533,2180,7,1,'یارِ شیرین‌سخنِ نادره‌گفتارِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(1937535,2180,6,1,'نرگس او که طبیبِ دلِ بیمارِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(1937537,2183,0,0,'ز گریه مَردُمِ چشمم نشسته در خون است','هوش مصنوعی: از شدت گریه و اندوه، چشمانم پر از اشک و خون شده است. ببین که در جستجوی تو، حال و روز مردان چگونه است.',NULL);
INSERT INTO "verses" VALUES(1937538,2184,6,0,'مشو حافظ ز کیدِ زلفش ایمن','ای حافظ با این وجود از مکر و کید زلف او غافل مشو؛ تو را عاشق خود کرد و دلت را ربود و به‌این بسنده نخواهد کرد؛ دین تو را نیز خواهد ربود.',NULL);
INSERT INTO "verses" VALUES(1937539,2184,5,0,'تو پنداری که بدگو رفت و جان برد؟','مپندار که بدگو گریخت و جان سالم بدر برد وای بر حال او که حساب او با «کرام الکاتبین» است و بسیار بد سرنوشتی در انتظارش است.',NULL);
INSERT INTO "verses" VALUES(1937540,2184,5,1,'حسابش با کرام الکاتبین است',NULL,NULL);
INSERT INTO "verses" VALUES(1937541,2184,4,0,'عجب عِلمیست عِلم هیئت عشق','در میان علم‌ها «علم نجوم عشق» شگرف و عجیب است که چرخ هشتم در برابر او در هفت قعر زمین پست و بی‌مقدار است.',NULL);
INSERT INTO "verses" VALUES(1937542,2184,4,1,'که چرخِ هشتمش، هفتم زمین است',NULL,NULL);
INSERT INTO "verses" VALUES(1937543,2184,3,0,'بر آن چشمِ سیه صد آفرین باد','صدها آفرین بر آن چشم‌های سیاه که در کشتن عاشق بی‌رقیب و معجزه‌گر است.',NULL);
INSERT INTO "verses" VALUES(1937544,2184,3,1,'که در عاشق کُشی سِحرآفرین است',NULL,NULL);
INSERT INTO "verses" VALUES(1937545,2184,2,0,'ز چشمِ شوخِ تو جان کی توان برد؟','از چشم بی‌باک و بی‌شرم تو چون توان جان سالم بدر برد؟ که یک آن از تیر افکندن و غمزه باز نمی‌ایستد.',NULL);
INSERT INTO "verses" VALUES(1937546,2184,2,1,'که دایم با کمان اندر کمین است',NULL,NULL);
INSERT INTO "verses" VALUES(1937547,2184,1,0,'جمالت مُعجِزِ حُسن است لیکن','زیبایی تو معجزه‌آساست و اما وصف غمزه تو ممکن نیست زیرا آن‌یکی سحر و افسون آشکار است.',NULL);
INSERT INTO "verses" VALUES(1937548,2184,1,1,'حدیثِ غمزه‌ات سحرِ مبین است',NULL,NULL);
INSERT INTO "verses" VALUES(1937549,2184,0,0,'خَمِ زلفِ تو دامِ کفر و دین است','زلف معشوق چنان فریبنده است که هم می‌تواند عاشق را در دام عشق زمینی گرفتار کند (کفر) و هم می‌تواند او را به وادی حقیقت و عشق الهی برساند (دین). و این تنها یکی از هزاران جلوه و شگفتی‌های معشوق است.',NULL);
INSERT INTO "verses" VALUES(1937550,2184,0,1,'ز کارستانِ او یک شمه این است',NULL,NULL);
INSERT INTO "verses" VALUES(1937551,2183,8,0,'ز بیخودی طلبِ یار می‌کند حافظ','هوش مصنوعی: حافظ در اینجا بیان می‌کند که او از حالت بی‌خودی و نشئگی عشق، به دنبال محبوبش می‌گردد، مانند کسی که در فقر و نیاز، به دنبال ثروت و گنجینه‌ای عظیم است. در واقع، او احساس می‌کند که نیاز و طلب او از یار، به اندازه‌ی نیاز یک شخص مفلسی به دارایی و ثروت نجومی است.',NULL);
INSERT INTO "verses" VALUES(1937552,2183,8,1,'چو مفلسی که طلبکارِ گنجِ قارون است',NULL,NULL);
INSERT INTO "verses" VALUES(1937553,2183,7,0,'چگونه شاد شود اندرونِ غمگینم؟','هوش مصنوعی: چطور می‌توانم در درون غمگینم شاد باشم؟ این کار به انتخاب من نیست، زیرا از کنترل من خارج است.',NULL);
INSERT INTO "verses" VALUES(1937554,2183,7,1,'به اختیار، که از اختیار بیرون است',NULL,NULL);
INSERT INTO "verses" VALUES(1937555,2183,6,0,'از آن دمی که ز چشمم برفت رودِ عزیز','هوش مصنوعی: از وقتی که عزیزم از کنارم رفت، انگار اشک‌هایم به اندازه‌ی جیحون جاری شده‌اند.',NULL);
INSERT INTO "verses" VALUES(1937556,2183,6,1,'کنارِ دامنِ من همچو رودِ جیحون است',NULL,NULL);
INSERT INTO "verses" VALUES(1937557,2183,5,0,'ز دورِ باده به جان، راحتی رسان ساقی','هوش مصنوعی: از دوری شراب به جانم آرامش ببخش، ای ساقی، زیرا غم خاطرم از ظلم و سختی‌های زندگی بسیار است.',NULL);
INSERT INTO "verses" VALUES(1937558,2183,5,1,'که رنجِ خاطرم از جورِ دورِ گردون است',NULL,NULL);
INSERT INTO "verses" VALUES(1937559,2183,4,0,'دلم بجو که قدت همچو سرو دلجوی است','هوش مصنوعی: دل من را به جستجوی خود بکش، زیرا قامت تو زیبا و مشابه سروهای دل‌نواز است. صحبت کن که گفتارت نرم و هماهنگ است.',NULL);
INSERT INTO "verses" VALUES(1937560,2183,4,1,'سخن بگو که کلامت لطیف و موزون است',NULL,NULL);
INSERT INTO "verses" VALUES(1937561,2183,3,0,'حکایتِ لبِ شیرین، کلام فرهاد است','هوش مصنوعی: لب‌های شیرین به داستان فرهاد اشاره دارد و نشان می‌دهد که صحبت‌های او مانند یک قصه جذاب و دلنشین است. همچنین، زعفران و زیبایی‌های لیلی، مقام و حالت مجنون را به تصویر می‌کشد.',NULL);
INSERT INTO "verses" VALUES(1937562,2183,3,1,'شِکَنجِ طُرِّهٔ لیلی مقام مجنون است',NULL,NULL);
INSERT INTO "verses" VALUES(1937563,2183,2,0,'ز مشرقِ سرِ کو آفتابِ طلعتِ تو','هوش مصنوعی: اگر چهره‌ی زیبای تو از سوی مشرق سر کو طلوع کند، حتمی است که روزگارم پر از خوشبختی خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1937564,2183,2,1,'اگر طلوع کند، طالعم همایون است',NULL,NULL);
INSERT INTO "verses" VALUES(1937565,2183,1,0,'به یادِ لعلِ تو و چشمِ مستِ میگونت','هوش مصنوعی: این بیت به حسرت و یادی از زیبایی و جذابیت معشوق اشاره دارد. گوینده با یادآوری لب‌های زیبا و چشمان مست معشوق، در حال نوشیدن جامی از غم است. هر جرعه‌ای که می‌نوشد، به نوعی درد و رنجی عمیق را در دلش ایجاد می‌کند که طعمش مانند خون است. به نوعی این احساس ترکیبی از شوق و اندوه ناشی از فراق یار است.',NULL);
INSERT INTO "verses" VALUES(1937566,2183,1,1,'ز جامِ غم، می لعلی که می‌خورم خون است',NULL,NULL);
INSERT INTO "verses" VALUES(1937567,2183,0,1,'ببین که در طلبت حالِ مَردُمان چون است',NULL,NULL);
INSERT INTO "verses" VALUES(1937568,2180,7,0,'آن که در طرزِ غزل نکته به حافظ آموخت','کسی که نظم و طرز غزل‌آرایی را به حافظ آموخت یار و محبوبِ شیرین‌گفتار و نغزگوی بی‌همتای من است.',NULL);
INSERT INTO "verses" VALUES(1937569,2180,5,1,'کآبِ گلزارِ تو از اشکِ چو گلنارِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(1937570,2180,6,0,'شربتِ قند و گلاب از لبِ یارم فرمود','چشمان مستش که طبیب دل دردمند و عاشق من است، برای درمان من از لبانش شربت قند و گلاب نسخه‌کرد.',NULL);
INSERT INTO "verses" VALUES(1937571,2178,0,0,'روضهٔ خُلدِ برین خلوتِ درویشان است','محل آرامش و سکوت درویشان بهشت برین است و حضور در آن جا باعث عزت و احترام می‌شود و خدمت به درویشان موجب بزرگی و ارج‌مندی است.',NULL);
INSERT INTO "verses" VALUES(1937572,2178,0,1,'مایهٔ مُحتشمی، خدمتِ درویشان است',NULL,NULL);
INSERT INTO "verses" VALUES(1937573,2178,1,0,'گَنج عُزلت که طِلِسماتِ عجایب دارد','هوش مصنوعی: گنجی که در کنار تنهایی و دوری از دنیای پرهیاهو قرار دارد و دارای رمز و رازهای شگفت‌انگیزی است، تنها با نظر رحمت درویشان می‌توان به آن دست یافت.',NULL);
INSERT INTO "verses" VALUES(1937574,2178,1,1,'فتحِ آن در نظرِ رحمتِ درویشان است',NULL,NULL);
INSERT INTO "verses" VALUES(1937575,2178,2,0,'قصرِ فردوس که رضوانش به دَربانی رفت','هوش مصنوعی: بهشتی که در آن درختان و باغ‌ها به حفاظت بندگان خدا اختصاص دارد، تصویری از باغ و چمن‌زاری است که درویشان در آن به خوشی و آرامش می‌گذرانند.',NULL);
INSERT INTO "verses" VALUES(1937576,2178,2,1,'مَنظَری از چمنِ نُزهَتِ درویشان است',NULL,NULL);
INSERT INTO "verses" VALUES(1937577,2178,3,0,'آن چه زر می‌شود از پرتو آن، قلبِ سیاه','هوش مصنوعی: هر چیزی که ارزش و کیفیت پیدا می‌کند، ناشی از پرتو و تاثیر قلبی است که در کنار درویشان و اهل سلوک قرار دارد. این قلب، مانند کیمیایی است که به چیزها صفات ناب و با ارزش می‌بخشد.',NULL);
INSERT INTO "verses" VALUES(1937578,2178,3,1,'کیمیاییست که در صحبتِ درویشان است',NULL,NULL);
INSERT INTO "verses" VALUES(1937579,2178,4,0,'آن که پیشش بِنَهَد تاجِ تکبر، خورشید','هوش مصنوعی: کسی که بر خود تکبر می‌ورزد و تاج بزرگی می‌گذارد، در واقع مانند خورشید بزرگواری است که در کنار درویشان و افراد ساده‌دل حضور دارد.',NULL);
INSERT INTO "verses" VALUES(1937580,2178,4,1,'کبریاییست که در حِشمتِ درویشان است',NULL,NULL);
INSERT INTO "verses" VALUES(1937581,2178,5,0,'دولتی را که نباشد غم از آسیبِ زَوال','هوش مصنوعی: دولتی که نگرانی از آسیب و از بین رفتن ندارد، دولتی است که برای درویشان و افراد زاهد با معانی عمیق و واقعی است. این دولت بی‌دغدغه و بی‌تظاهر است و مشکلات دنیوی آن را تحت تأثیر قرار نمی‌دهد.',NULL);
INSERT INTO "verses" VALUES(1937582,2178,5,1,'بی‌تَکَلُف بشنو، دولتِ درویشان است',NULL,NULL);
INSERT INTO "verses" VALUES(1937583,2178,6,0,'خسروان، قبلهٔ حاجاتِ جهانند ولی','هوش مصنوعی: پادشاهان و بزرگان، مرکز درخواست‌های مردم هستند، اما دلیل این مقام و جایگاه، خدمت و بندگی آنان به درویشان و اهل معنویت است.',NULL);
INSERT INTO "verses" VALUES(1937584,2178,6,1,'سببش بندگیِ حضرتِ درویشان است',NULL,NULL);
INSERT INTO "verses" VALUES(1937585,2178,7,0,'رویِ مقصود که شاهان به دعا می‌طَلبند','هوش مصنوعی: هدف نهایی که پادشاهان به دعا و طلب آن می‌پردازند، در واقع در چهره و صورت درویش‌ها نمایان است.',NULL);
INSERT INTO "verses" VALUES(1937586,2178,7,1,'مَظهَرَش آینهٔ طَلعَتِ درویشان است',NULL,NULL);
INSERT INTO "verses" VALUES(1937587,2178,8,0,'از کران تا به کران، لشکر ظُلم است ولی','هوش مصنوعی: در سراسر این دنیا پر از ظلم و ستم است، اما همیشه برای درویشان و کسانی که دل پاک و ایمان دارند، فرصتی وجود دارد که می‌توانند از آن بهره‌برداری کنند.',NULL);
INSERT INTO "verses" VALUES(1937588,2177,8,0,'حافظ این گوهرِ مَنظوم که از طَبع اَنگیخت','هوش مصنوعی: حافظ این جواهر شعر را که با ذوق و استعداد خود سروده، نتیجه تربیت و آموزش آصف دومی می‌داند.',NULL);
INSERT INTO "verses" VALUES(1937589,2177,8,1,'زَ اثرِ تربیتِ آصِفِ ثانی دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937590,2177,7,0,'مِی بیاور که ننازد به گلِ باغِ جهان','شراب بیاور زیرا کسی که بداند چگونه باد خزان به باغ گل دنیا آسیب می‌زند، نباید به زیبایی‌های دنیا ببالد.',NULL);
INSERT INTO "verses" VALUES(1937591,2177,7,1,'هر که غارت‌گریِ بادِ خزانی دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937592,2177,6,0,'ای که از دفترِ عقل، آیت عشق آموزی','ای کسی که از دانش و فهم عقل، بدنبال آموختن حقیقت عشق هستی، می‌ترسم که این نکته را به‌درستی درنیابی.',NULL);
INSERT INTO "verses" VALUES(1937593,2177,6,1,'ترسم این نکته به تَحقیق ندانی دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937594,2177,5,0,'سنگ و گِل را کُنَد از یُمنِ نظر لعل و عقیق','هرکسی ارزش نسیم یمانی را بفهمد، از نیکی نظر خود می‌تواند سنگ و گل را به لعل و عقیق تبدیل کند.',NULL);
INSERT INTO "verses" VALUES(1937595,2177,5,1,'هر که قَدرِ نفسِ بادِ یمانی دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937596,2177,4,0,'دل‌بر، آسایش ما مَصلحتِ وقت ندید','یار ما، آسایش ما را به‌مصلحت ندید وگرنه حال ما را درک می‌کند.',NULL);
INSERT INTO "verses" VALUES(1937597,2177,4,1,'ور نه از جانبِ ما دل‌نگرانی دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937598,2177,3,0,'آن شد اکنون که ز اَبنایِ عَوام اندیشم','هوش مصنوعی: اکنون به جایی رسیده‌ام که حتی عده‌ای از افراد معمولی نیز متوجه این شادی پنهانی من شده‌اند.',NULL);
INSERT INTO "verses" VALUES(1937599,2177,3,1,'مُحتَسِب نیز در این عیشِ نهانی دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937600,2178,8,1,'از اَزَل تا به اَبَد، فرصتِ درویشان است',NULL,NULL);
INSERT INTO "verses" VALUES(1937601,2178,9,0,'ای توانگر مَفُروش این همه نِخوَت که تو را','هوش مصنوعی: ای ثروتمند، با این همه توانایی‌هایت، خود را در برابر درویشان کم‌اهمیت نکن؛ زیرا توان و دارایی واقعی در اختیار کسانی است که با اراده و همت خود به پیش می‌روند.',NULL);
INSERT INTO "verses" VALUES(1937602,2178,9,1,'سر و زر در کَنَفِ همتِ درویشان است',NULL,NULL);
INSERT INTO "verses" VALUES(1937603,2178,10,0,'گنجِ قارون که فرو می‌شود از قَهر هنوز','هوش مصنوعی: خزانه‌ی عظیم قارون، که به خاطر قهرش غرق می‌شود، باید بدانیم که این وضعیت به دلیل غیرت و درخشش روح درویشان است.',NULL);
INSERT INTO "verses" VALUES(1937604,2180,4,1,'فیضِ یک شَمِّه ز بوی خوشِ عطارِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(1937605,2180,5,0,'باغبان همچو نسیمم ز درِ خویش مران','ای باغبان چون (نسیم که به دزدی عطرهای باغت می‌آید) با من رفتار مکن و مرا از در مران‌، اشک چشمان من است که گل‌های باغت را تازه نگه‌می‌دارد و آبیاری می‌کند.',NULL);
INSERT INTO "verses" VALUES(1937606,2180,3,1,'عشق آن لولیِ سرمست‌، خریدار من است',NULL,NULL);
INSERT INTO "verses" VALUES(1937607,2180,4,0,'طَبلِهٔ عطرِ گل و زلفِ عبیر افشانش','بوستان گل و سنبل‌های خوش‌عطرش‌، یک رایحه از عطر عطار ( ومعشوق خوش‌عطر) من است.',NULL);
INSERT INTO "verses" VALUES(1937608,2180,2,1,'شاهراهی‌ست که منزلگهِ دلدارِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(1937609,2180,3,0,'بندهٔ طالعِ خویشم که در این قحطِ وفا','بنده و ممنون فال نیکوی خودم هستم که در این قحطی وفا و مهر، من مهر آن لولی سرمست را در دل دارم. (لولی یا کولی‌ها در رقص و شاد بودن معروف بوده‌اند در اینجا در معنایی سمبلیک و مجازی به‌کار رفته‌است.)',NULL);
INSERT INTO "verses" VALUES(1937610,2180,1,1,'هر که دل بردنِ او دید و در انکارِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(1937611,2180,2,0,'ساروان رَخت به دروازه مَبَر‌، کان سرِ کو','ای ساروان، به دروازه مرو و در آن محله توقف مکن که آنجا شاهراهی‌است که مأوا و منزل معشوق من است.',NULL);
INSERT INTO "verses" VALUES(1937612,2180,0,1,'وز پی دیدنِ او دادنِ جان کار من است',NULL,NULL);
INSERT INTO "verses" VALUES(1937613,2180,1,0,'شرم از آن چشمِ سیه بادش و مژگان دراز','شرم باد بر کسی که به‌آن چشمان سیاه و مژگان بلند می‌نگرد وقتی که دل‌بردن آنها را از من می‌بیند و مرا نادیده می‌گیرد.',NULL);
INSERT INTO "verses" VALUES(1937614,2180,0,0,'لعلِ سیرابِ به‌خون‌تشنه‌، لب یار من است','معشوق من لب‌هایی دارد سیراب از سرخی همچون لعل اما تشنه به خون، و در اشتیاق دیدن آن لب‌ها‌، جان دادن و جان‌بازی کار و پیشه من است.',NULL);
INSERT INTO "verses" VALUES(1937615,2179,6,0,'بسوخت حافظ و در شرطِ عشقبازی او','هوش مصنوعی: حافظ به شدت تحت تأثیر عشق قرار گرفته و با وجود تمام مشکلات و رنج‌هایی که کشیده، هنوز به عهد و وفای خود در ارتباط با عشق پایبند است.',NULL);
INSERT INTO "verses" VALUES(1937616,2179,5,0,'مرو به خانهٔ اربابِ بی‌مُروتِ دهر','به‌سوی این دنیای ناجوانمرد مرو و از او توقع چیزی نداشته‌باش زیرا گنج سلامت و آسایش تو در خانهٔ خود توست.',NULL);
INSERT INTO "verses" VALUES(1937617,2179,6,1,'هنوز بر سرِ عهد و وفایِ خویشتن است',NULL,NULL);
INSERT INTO "verses" VALUES(1937618,2184,6,1,'که دل برد و کنون در بندِ دین است',NULL,NULL);
INSERT INTO "verses" VALUES(1937619,2179,4,0,'به مُشکِ چین و چِگِل نیست بویِ گُل مُحتاج','هوش مصنوعی: بوی گل به عطر مشک و چرم نیاز ندارد، چون خود مشک و چرم از زیبایی و خاصیت وجودی خود بهره‌مندند.',NULL);
INSERT INTO "verses" VALUES(1937620,2179,4,1,'که نافه‌هاش ز بندِ قَبایِ خویشتن است',NULL,NULL);
INSERT INTO "verses" VALUES(1937621,2179,3,0,'چو رای عشق زدی با تو گفتم ای بلبل','هوش مصنوعی: وقتی که به عشق فکر کردم، با خودم گفتم، ای بلبل! چرا گل شاداب را به خواسته خود نخواهی؟',NULL);
INSERT INTO "verses" VALUES(1937622,2179,2,0,'به جانت ای بتِ شیرین دهن که همچون شمع','ای بت شیرین دهن به جانت سوگند که در شبهای تیره مرادم همچون شمع فنا کردن خویشتن است.',NULL);
INSERT INTO "verses" VALUES(1937623,2179,3,1,'مَکُن که آن گلِ خندان به رای خویشتن است',NULL,NULL);
INSERT INTO "verses" VALUES(1937624,2179,1,0,'گَرَت ز دست برآید مُرادِ خاطرِ ما','هوش مصنوعی: اگر خواسته‌های ما برآورده شود، بهتر است که آن را از طریق خودت به دست آوردی، زیرا این راه به نفع خودت خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1937625,2179,2,1,'شبانِ تیره، مُرادم فنایِ خویشتن است',NULL,NULL);
INSERT INTO "verses" VALUES(1937626,2179,0,0,'به دامِ زلفِ تو دل مبتلایِ خویشتن است','هوش مصنوعی: دل من به زلف‌های تو گرفتار شده است؛ با یک نگاه غمزه‌وار آن را بکش، زیرا این عذاب برای دل من سزاوار است.',NULL);
INSERT INTO "verses" VALUES(1937627,2179,1,1,'به دست باش که خیری به جایِ خویشتن است',NULL,NULL);
INSERT INTO "verses" VALUES(1937628,2179,0,1,'بکُش به غمزه که اینَش سزایِ خویشتن است',NULL,NULL);
INSERT INTO "verses" VALUES(1937629,2178,10,1,'خوانده باشی که هم از غِیرتِ درویشان است',NULL,NULL);
INSERT INTO "verses" VALUES(1937630,2178,11,0,'حافظ ار آبِ حیاتِ اَزَلی می‌خواهی','هوش مصنوعی: اگر می‌خواهی به آبِ حیات و جاودانگی دست یابی، سرچشمه‌اش در خاک درِ خلوتی است که درویشان در آن جا به عبادت و meditation می‌پردازند.',NULL);
INSERT INTO "verses" VALUES(1937631,2178,11,1,'مَنبَعَش خاکِ درِ خلوتِ درویشان است',NULL,NULL);
INSERT INTO "verses" VALUES(1937632,2178,12,0,'من غلامِ نظرِ آصِفِ عهدم کو را','هوش مصنوعی: من خدمتگزار نگاه آصف هستم، کسی که ظاهری چون اشراف و باطنی چون درویشان دارد.',NULL);
INSERT INTO "verses" VALUES(1937633,2178,12,1,'صورتِ خواجگی و سیرتِ درویشان است',NULL,NULL);
INSERT INTO "verses" VALUES(1937634,2179,5,1,'که گنجِ عافیتت در سرایِ خویشتن است',NULL,NULL);
INSERT INTO "verses" VALUES(1937635,2185,0,0,'دل سراپردهٔ محبتِ اوست','دل و قلب من سراپرده و اقامتگاه عشق اوست و چشم‌هایم مثل آیینه‌دار مدام در برابر رخ زیبای اوست.',NULL);
INSERT INTO "verses" VALUES(1937636,2185,0,1,'دیده آیینه‌دارِ طلعت اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937637,2185,1,0,'من که سر در نیاورم به دو کون','من که به دو عالم سر فرود نیاوردم از اینکه عشق او در قلبم و تصویرش در چشمانم است منت‌بار هستم و خود را مدیون او می‌دانم.',NULL);
INSERT INTO "verses" VALUES(1937638,2190,5,0,'اگر چه دوست به چیزی نمی‌خرد ما را','اگرچه دوست به ما کمترین نگاهی نمی‌کند اما مویی از سر او را به‌دنیا نمی‌فروشیم.',NULL);
INSERT INTO "verses" VALUES(1937639,2190,4,0,'دل صِنوبَری‌ام همچو بید لرزان است','قلبم در سینه همچون درخت بید لرزان و مضطرب است؛ از حسرت قد و بالای همچون درخت صنوبر یار.',NULL);
INSERT INTO "verses" VALUES(1937640,2190,4,1,'ز حسرتِ قد و بالای چون صنوبرِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937641,2190,3,0,'منِ گدا و تمنایِ وصلِ او هیهات','من گدا کجا و آرزوی وصال او کجا!؟ مگر در خواب روی زیبای او را ببینم.',NULL);
INSERT INTO "verses" VALUES(1937642,2190,3,1,'مگر به خواب ببینم خیالِ منظرِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937643,2190,2,0,'و گر چنان که در آن حضرتت نباشد بار','اگر نتوانستی به دیدارش بروی؛ برای چشمم از خاک درِ او غبار بیاور تا توتیای چشمم کنم.',NULL);
INSERT INTO "verses" VALUES(1937644,2190,2,1,'برایِ دیده بیاور غباری از درِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937645,2190,1,0,'به جانِ او که به شکرانه جان برافشانم','به جان عزیز او، اگر پیامی از او برایم بیاوری جان را به شکرانه می‌بخشم.',NULL);
INSERT INTO "verses" VALUES(1937646,2190,1,1,'اگر به سویِ من آری پیامی از برِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937647,2190,0,0,'صبا اگر گذری اُفتَدَت به کشور دوست','ای نسیم صبا، اگر از دیار یار گذر کردی، برایم عطری از گیسوی یار به‌ارمغان بیاور.',NULL);
INSERT INTO "verses" VALUES(1937648,2190,0,1,'بیار نَفحِه‌ای از گیسوی مُعَنبَر دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937649,2189,8,0,'دشمن به قصدِ حافظ اگر دم زند چه باک؟','هوش مصنوعی: اگر دشمن با نیت بد درباره حافظ سخن بگوید، چه اهمیتی دارد؟ خدا را شکر که من هرگز از دوست خود خجالت‌زده نیستم.',NULL);
INSERT INTO "verses" VALUES(1937650,2189,8,1,'مِنَّت خدای را که نیَم شرمسارِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937651,2189,7,0,'ماییم و آستانهٔ عشق و سرِ نیاز','هوش مصنوعی: ما در مقابل عشق و خواسته‌امان ایستاده‌ایم و منتظریم تا ببینیم که چه کسی در کنار دوست، خواب خوش را به همراه خواهد آورد.',NULL);
INSERT INTO "verses" VALUES(1937652,2189,7,1,'تا خوابِ خوش که را بَرَد اندر کنارِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937653,2189,6,0,'کُحلُ الجَواهری به من آر ای نسیمِ صبح','هوش مصنوعی: ای نسیم صبح، کحل گرانبهای زیور خود را به من عطا کن، از آن سرزمین خوشبخت که راهی به سوی دوست شده است.',NULL);
INSERT INTO "verses" VALUES(1937654,2189,6,1,'زان خاکِ نیکبخت که شد رهگذارِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937655,2189,5,0,'گر بادِ فتنه هر دو جهان را به هم زند','هوش مصنوعی: اگر طوفان فتنه تمام جهان را به هم بریزد، ما هنوز چراغ چشمان و راه انتظار دوست را داریم.',NULL);
INSERT INTO "verses" VALUES(1937656,2189,5,1,'ما و چراغِ چَشم و رهِ انتظارِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937657,2189,4,0,'سیرِ سپهر و دورِ قمر را چه اختیار؟','هوش مصنوعی: حرکت و چرخش آسمان و ماه در دست ما نیست، بلکه آن‌ها طبق اراده و خواست معشوق در گردش‌اند.',NULL);
INSERT INTO "verses" VALUES(1937658,2189,4,1,'در گردشند بر حَسَبِ اختیار دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937659,2189,3,0,'شکرِ خدا که از مددِ بختِ کارساز','هوش مصنوعی: خوشحالم که به لطف شانس و اقبال، تمام امور و خواسته‌هایم در زندگی به خوبی پیش می‌رود.',NULL);
INSERT INTO "verses" VALUES(1937660,2189,3,1,'بر حسبِ آرزوست همه کار و بارِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937661,2189,2,0,'دل دادمش به مژده و خِجلَت همی‌برم','هوش مصنوعی: دل خود را به خوشحالی و امید سپردم، اما اکنون شرم و خجالت را با خود به دوش می‌کشم، چرا که تمام احساساتم را برای محبوب نثار کرده‌ام.',NULL);
INSERT INTO "verses" VALUES(1937662,2189,2,1,'زین نقدِ قلبِ خویش که کردم نثارِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937663,2189,1,0,'خوش می‌دهد نشانِ جلال و جمالِ یار','هوش مصنوعی: این بیت به زیبایی و جذابیت معشوق اشاره دارد و بیان می‌کند که این زیبایی نه تنها جلوه‌ای خاص دارد، بلکه احساس عزت و وقار را نیز در دل دوست به وجود می‌آورد. در واقع، وجود این ویژگی‌ها در معشوق، جذبه و احترام خاصی را به همراه دارد.',NULL);
INSERT INTO "verses" VALUES(1937664,2189,1,1,'خوش می‌کند حکایتِ عِزّ و وقارِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937665,2189,0,0,'آن پیکِ ناموَر که رسید از دیارِ دوست','هوش مصنوعی: پیام‌آور مشهور که از سرزمین دوست آمد، جانِ حامی و محافظت‌کننده را از نامه‌ای خوشبو و معطر به مشامش رساند.',NULL);
INSERT INTO "verses" VALUES(1937666,2189,0,1,'آورد حِرزِ جان ز خطِ مُشکبارِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937667,2190,5,1,'به عالمی نفروشیم مویی از سرِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937668,2190,6,0,'چه باشد ار شود از بندِ غم دلش آزاد','چه می‌شود اگر روزی دل دردمند حافظ، که بنده یار است، از غم آزاد شود.',NULL);
INSERT INTO "verses" VALUES(1937669,2190,6,1,'چو هست حافظِ مسکین غلام و چاکر دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937670,2191,0,0,'مرحبا ای پیکِ مشتاقان بده پیغامِ دوست','هوش مصنوعی: سلام ای پیام‌آور عاشقان، پیام دوست را برسان تا با کمال میل و عشق، جانم را فدای نام دوست کنم.',NULL);
INSERT INTO "verses" VALUES(1937671,2193,1,1,'بسوخت دیده ز حیرت که این چه بوالعجبی‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1937672,2193,0,0,'اگر چه عرض هنر پیشِ یار بی‌ادبی‌ست','اگرچه بیان هنر در برابر یار دل ربا بی‌ادبی محسوب می‌شود پس بهتر است زبان را ببندیم،و این درحالیست که در زبان آوری هنرمند و ماهر هستیم و در دل احساسات و افکار واژه‌های زیبا و ادبی فراوان داریم.',NULL);
INSERT INTO "verses" VALUES(1937673,2193,0,1,'زبان خموش، ولیکن دهان پُر از عربی‌ست',NULL,NULL);
INSERT INTO "verses" VALUES(1937674,2192,5,0,'فریادِ حافظ این همه آخِر به هرزه نیست','هوش مصنوعی: حافظ می‌گوید که تمام این فریادها و ناله‌هایش بی‌دلیل نیست و در پس آن داستان‌های عجیب و غریب و روایت‌های جالبی نهفته است.',NULL);
INSERT INTO "verses" VALUES(1937675,2192,5,1,'هم قصه‌ای غریب و حدیثی عجیب هست',NULL,NULL);
INSERT INTO "verses" VALUES(1937676,2192,4,0,'عاشق که شد که یار به حالش نظر نکرد','هوش مصنوعی: عاشق شدن به این معناست که معشوق به او توجهی نکند. ای آقا، اگر درد و رنجی احساس نمی‌شود، پس طبیبی وجود دارد که می‌تواند درمان کند.',NULL);
INSERT INTO "verses" VALUES(1937677,2192,4,1,'ای خواجه درد نیست وگرنه طبیب هست',NULL,NULL);
INSERT INTO "verses" VALUES(1937678,2192,3,0,'آن جا که کارِ صومعه را جلوه می‌دهند','هوش مصنوعی: در آن مکان که به فعالیت‌های صومعه تاکید می‌شود، صدای ناقوس کلیسا و نشانه‌های مذهبی وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1937679,2192,3,1,'ناقوسِ دِیرِ راهب و نامِ صلیب هست',NULL,NULL);
INSERT INTO "verses" VALUES(1937680,2192,2,0,'در عشق، خانقاه و خرابات فرق نیست','هوش مصنوعی: در عشق، فرقی بین مکان‌های مقدس و مکان‌های عادی وجود ندارد؛ هر جا که نور چهره‌ محبوب باشد، همان مکان ارزشمند است.',NULL);
INSERT INTO "verses" VALUES(1937681,2192,2,1,'هر جا که هست پرتوِ رویِ حبیب هست',NULL,NULL);
INSERT INTO "verses" VALUES(1937682,2192,1,0,'گر آمدم به کوی تو چندان غریب نیست','هوش مصنوعی: اگر به کوی تو آمده‌ام، چندان غریب نیستم، زیرا در آن منطقه، هزاران نفر مثل من غریب هستند.',NULL);
INSERT INTO "verses" VALUES(1937683,2192,1,1,'چون من در آن دیار هزاران غریب هست',NULL,NULL);
INSERT INTO "verses" VALUES(1937684,2192,0,0,'رویِ تو کس ندید و هزارت رقیب هست','هوش مصنوعی: هیچ‌کس زیبایی تو را ندیده و با این حال هزاران رقیب در انتظار تو هستند، حتی در حالتی که هنوز در جوانی به گل نرسیده‌ای و صدها بلبل وجود دارند که به خاطر تو آواز می‌خوانند.',NULL);
INSERT INTO "verses" VALUES(1937685,2188,7,0,'حافظ بد است حالِ پریشانِ تو، ولی','هوش مصنوعی: حال خراب تو برای حافظ دل‌گیر است، اما بوی موی محبوب باعث می‌شود که این بی‌تابی تو زیبا به نظر برسد.',NULL);
INSERT INTO "verses" VALUES(1937686,2192,0,1,'در غنچه‌ای هنوز و صدت عندلیب هست',NULL,NULL);
INSERT INTO "verses" VALUES(1937687,2191,7,0,'حافظ اندر دَردِ او می‌سوز و بی‌درمان بساز','هوش مصنوعی: حافظ درگیر غم و اندوه اوست و این درد را می‌پذیرد، زیرا می‌داند برای این احساس عمیق و بی‌پایان که ناشی از عشق است، هیچ درمانی وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1937688,2191,6,0,'میل من سویِ وصال و قصد او سویِ فراق','هوش مصنوعی: من به دنبال یار خود هستم و او می‌خواهد از من دوری کند. به خاطر او از خواسته‌های خود دست کشیده‌ام تا بتوانم آرزوی او را برآورده کنم.',NULL);
INSERT INTO "verses" VALUES(1937689,2191,6,1,'تَرکِ کامِ خود گرفتم تا برآید کامِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937690,2191,5,0,'گر دهد دستم کشم در دیده همچون توتیا','هوش مصنوعی: اگر دستی از من بگیری، چشمانم را مانند پودر تِتیا پر می‌کنم از خاکی که به خاطر قدم‌های تو، در آنجا روشن و روشن‌تر می‌شود.',NULL);
INSERT INTO "verses" VALUES(1937691,2191,5,1,'خاک راهی کـ‌آن مشرف گردد از اَقدامِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937692,2191,4,0,'بس نگویم شِمِّه‌ای از شرحِ شوقِ خود از آنک','هوش مصنوعی: نمی‌خواهم در مورد احساس عشق و شوق خود زیاد صحبت کنم، زیرا در این زمینه توضیحات بیشتر ممکن است مشکل‌ساز شود و دوستی‌ام را تحت‌تأثیر قرار دهد.',NULL);
INSERT INTO "verses" VALUES(1937693,2191,4,1,'دردسر باشد نمودن بیش از این ابرامِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937694,2191,3,0,'سر ز مستی برنگیرد تا به صبحِ روزِ حشر','هوش مصنوعی: کسی که در آغاز وجود یک جرعه از زهر شیدایی دوست را نوشیده، تا روز حساب، به هوش نخواهد آمد و سرش را بر نخواهد گرداند.',NULL);
INSERT INTO "verses" VALUES(1937695,2191,3,1,'هر که چون من در ازل یک جرعه خورد از جامِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937696,2191,2,0,'زلفِ او دام است و خالش دانهٔ آن دام و من','هوش مصنوعی: موهای او مانند دام می‌باشد و گونه‌اش به عنوان طعمه در آن دام قرار دارد و من با امید به آن طعمه، در دام عشق او گرفتار شده‌ام.',NULL);
INSERT INTO "verses" VALUES(1937697,2191,2,1,'بر امیدِ دانه‌ای افتاده‌ام در دامِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937698,2191,1,0,'واله و شیداست دایم همچو بلبل در قفس','هوش مصنوعی: دل شیدا و حیران من همیشه مانند بلبلی است که در قفس به سر می‌برد. طبع من به خاطر عشق، شیرینی و خوشی‌های دوست شبیه به طوطی است.',NULL);
INSERT INTO "verses" VALUES(1937699,2191,1,1,'طوطی طبعم ز عشقِ شِکَّر و بادامِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937700,2191,0,1,'تا کُنم جان از سرِ رغبت فدای نامِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937701,2191,7,1,'زان که درمانی ندارد دَردِ بی‌آرامِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937702,2177,2,0,'عرضه کردم دو جهان بر دلِ کاراُفتاده','تمام دو جهان را به دل عاشق دادم، به‌جز عشق تو همه چیز را فانی و نابود دانست.',NULL);
INSERT INTO "verses" VALUES(1937703,2188,7,1,'بر بویِ زلفِ یار پریشانیَت نکوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937704,2188,6,0,'عمری‌ست تا ز زلفِ تو بویی شنیده‌ام','هوش مصنوعی: سال‌هاست که از عطری که از موهای تو می‌آید، چیزی نشنیده‌ام، اما هنوز آن بو در دل من باقی‌مانده است.',NULL);
INSERT INTO "verses" VALUES(1937705,2186,4,0,'دلبرم، عَزْمِ سَفَر کَرْد خُدا را یاران','دلبر و محبوبم قصد سفر کرده است با این دل مجروح و زخم‌دیده چه کنم‌؟ که مرهم و داروی آن دیدار اوست؟',NULL);
INSERT INTO "verses" VALUES(1937706,2186,4,1,'چه کُنَم با دِلِ مجروح؟ که مَرْهَم با اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937707,2186,3,0,'خالِ مُشْکین که بدان عارِضِ گَنْدُمگون است','سرّ و راز آن دانه که آدم را در بهشت فریفت در آن خال سیاه است که بر چهره سبزه و گندمگون اوست.',NULL);
INSERT INTO "verses" VALUES(1937708,2186,3,1,'سِرِّ آن دانه که شُد رَهْزَنِ آدَم با اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937709,2186,2,0,'روی خوب است و کمالِ هنر و دامن پاک','زیبا روی و پاکدامن و هنرمند است و به همین خاطر‌، همّت و دعای همه پاکان دو عالم همراه و یاور اوست.',NULL);
INSERT INTO "verses" VALUES(1937710,2186,2,1,'لاجَرَم، هِمَّتِ پاکانِ دو عالَم با اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937711,2186,1,0,'گرچه شیرین‌‌دَهَنان پادشهان‌اند ولی','اگر‌چه خوش‌دهنان روزگار در حکم پادشاهان هستند اما لب‌های زیبای او چنان است که حکم خاتم سلیمان را دارد.',NULL);
INSERT INTO "verses" VALUES(1937712,2186,1,1,'او سلیمانِ زمان است که خاتَم با اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937713,2186,0,0,'آن سیه‌چَرده که شیرینیِ عالَم با اوست','آن زیباروی سبزه (تیره‌گون) که شیرینی دو عالم را در خود جمع کرده و چشمان پر می و مست دارد و چهره خندان دارد‌‌؛',NULL);
INSERT INTO "verses" VALUES(1937714,2186,0,1,'چَشْمِ مِیگون، لبِ خَندان، دِلِ خُرَّم با اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937715,2185,10,0,'فقرِ ظاهر مبین که حافظ را','به فقر و تهی‌دستی ظاهری حافظ منگر‌؛ او گنج محبت او را در سینه دارد.',NULL);
INSERT INTO "verses" VALUES(1937716,2185,10,1,'سینه گنجینهٔ محبتِ اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937717,2185,9,0,'من و دل گر فدا شدیم چه باک؟','اگر من و دل هر دو در این راه فدا شویم باکی نیست؛ غرض‌ و آرزوی ما، سلامت اوست.',NULL);
INSERT INTO "verses" VALUES(1937718,2185,9,1,'غرض اندر میان سلامتِ اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937719,2185,8,0,'مُلکَتِ عاشقیّ و گنجِ طرب','پادشایی عاشقی و این گنج شادی که دارم همه از یمن و سعادت همّت و خواست یار است.',NULL);
INSERT INTO "verses" VALUES(1937720,2185,8,1,'هر چه دارم ز یُمنِ همتِ اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937721,2185,7,0,'دورِ مجنون گذشت و نوبتِ ماست','دور و نوبت داستان‌های مجنون به‌پایان رسید و اکنون نوبت داستان عشق ماست آری نوبت هرکس بیش از پنج روز نیست.',NULL);
INSERT INTO "verses" VALUES(1937722,2185,7,1,'هر کسی پنج روز، نوبتِ اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937723,2185,6,0,'هر گلِ نو که شد چمن‌آرای','هر گل تازه و شکفته و خوش‌رنگ و بو که زینت چمن است آن‌را از هم‌نشینی با یار من بدست آورده است.',NULL);
INSERT INTO "verses" VALUES(1937724,2185,6,1,'زَ اثر رنگ و بویِ صحبتِ اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937725,2185,5,0,'بی خیالش مباد منظرِ چشم','چشمان من از خیال و تصویر او خالی و تهی مبادا زیرا بهترین جا برای خلوت اوست و جز او کسی دیگر در چشم من جایی ندارد.',NULL);
INSERT INTO "verses" VALUES(1937726,2185,5,1,'زآن که این گوشه جایِ خلوتِ اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937727,2185,4,0,'من که باشم در آن حرم که صبا','در جایی که باد صبا پرده‌دار و پیام‌آور سراپرده یار است من کی باشم که ادعای پرده‌داری او را داشته باشم‌؟',NULL);
INSERT INTO "verses" VALUES(1937728,2185,4,1,'پرده‌دارِ حریمِ حُرمتِ اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937729,2185,3,0,'گر من آلوده‌دامنم چه عجب','اگر من گناهکار و تر‌دامن و بدنام هستم خیالی نیست تمام دنیا می‌داند که او پاک و باعصمت است.',NULL);
INSERT INTO "verses" VALUES(1937730,2185,3,1,'همه عالم گواهِ عصمتِ اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937731,2185,2,0,'تو و طوبی و ما و قامتِ یار','تو و آنانکه هوس درخت بهشت کرده‌اید همان برای شما و من به قامت یار راضی هستم بلی اندیشه و خواست هرکس به بلندی همّت اوست.',NULL);
INSERT INTO "verses" VALUES(1937732,2185,2,1,'فکرِ هر کس به قدرِ همتِ اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937733,2185,1,1,'گردنم زیرِ بارِ منتِ اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937734,2186,5,0,'با که این نکته توان گفت که آن سنگین‌‌دِل','این نکته را برای که بگویم و چه کسی آن‌را درک می‌کند که آن بی‌رحم و سنگین‌دل مرا کشته و هم‌صحبتی با او تنها زندگی‌بخش من است.',NULL);
INSERT INTO "verses" VALUES(1937735,2186,5,1,'کُشْت ما را و دَمِ عیسیِ مَریم با اوست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937736,2186,6,0,'«حافظ» از مُعْتَقِدان است گرامی دارَش!','حافظ را بی‌دین مشمار و او را گرامی بدار زیرا که بخشایش و لطف بسی روح مکرّم و گرانقدر با اوست.',NULL);
INSERT INTO "verses" VALUES(1937737,2186,6,1,'زان که بخشایشِ بس روحِ مُکَرَّم با اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937738,2188,5,0,'بی گفت و گوی زلفِ تو دل را همی کُشد','دل بدون گفت و گو با زیبایی موهای تو کُشته میشود. چه کسی میتواند با زلف های دلفریب تو صحبت کند؟',NULL);
INSERT INTO "verses" VALUES(1937739,2188,5,1,'با زلف دلکَش تو که را روی گفت و گوست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937740,2188,4,0,'دارم عجب ز نقشِ خیالش که چون نرفت','هوش مصنوعی: من از تصویر خیالش شگفت‌زده‌ام، چرا که وقتی دیگر از نظرم دور شد، انگار که دم به دم در حال پاک کردن و شست‌وشوی خاطراتم بوده است.',NULL);
INSERT INTO "verses" VALUES(1937741,2188,4,1,'از دیده‌ام که دَم به دَمش کار شُست و شوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937742,2188,3,0,'هیچ است آن دهان و نبینم از او نشان','هوش مصنوعی: این جمله به نوعی به تصویر کشیدن زیبایی و جذابیت فردی است که گوینده نسبت به او احساس عمیق و تمایل دارد. گوینده به نوعی در حال توصیف حالت گیج و جذاب خود است که با وجود عدم دیدن آن شخص، به زیبایی او و موهایش اشاره می‌کند. به عبارت دیگر، این احساس به سادگی نمی‌تواند درک شود، اما جذابیت و زیبایی آن فرد به قدری قوی است که گوینده حتی بدون دیدن او، احساساتی عمیق را تجربه می‌کند.',NULL);
INSERT INTO "verses" VALUES(1937743,2188,3,1,'موی است آن میان و ندانم که آن چه موست',NULL,NULL);
INSERT INTO "verses" VALUES(1937744,2188,2,0,'چندان گریستیم که هر کس که برگذشت','هوش مصنوعی: ما آن‌قدر گریستیم که هر کسی که از کنار ما عبور کرد، وقتی اشک‌های ما را دید، با تعجب گفت: این چه حالی است؟',NULL);
INSERT INTO "verses" VALUES(1937745,2188,2,1,'در اشکِ ما چو دید روان گفت «کاین چه جوست؟»',NULL,NULL);
INSERT INTO "verses" VALUES(1937746,2188,1,0,'دانم که بُگذرد ز سرِ جرمِ من که او','هوش مصنوعی: می‌دانم که گناه من در نهایت فراموش خواهد شد، زیرا او هرچند زیبایی دارد، اما درونش از نیکی و پاکی سرشار است.',NULL);
INSERT INTO "verses" VALUES(1937747,2188,1,1,'گر چه پریوش است ولیکن فرشته‌خوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937748,2188,0,0,'دارم امید عاطفتی از جناب دوست','هوش مصنوعی: من به محبت دوستانه‌ای از طرف دوستم امیدوارم، ولی در عین حال کاری کرده‌ام که باعث شده به نوعی دل او را بشکنم و اکنون امیدوارم که او مرا ببخشد.',NULL);
INSERT INTO "verses" VALUES(1937749,2188,0,1,'کردم جنایتی و امیدم به عفو اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937750,2187,8,0,'نه این زمان دلِ حافظ در آتشِ هوس است','عشق و سوز دل حافظ مربوط به امروز و دیروز نیست، بلکه این سوز و داغ دل‌، ازلی است همچون داغ لاله صحرا.',NULL);
INSERT INTO "verses" VALUES(1937751,2187,8,1,'که داغدار ازل همچو لالهٔ خودروست',NULL,NULL);
INSERT INTO "verses" VALUES(1937752,2188,6,1,'زان بوی در مشامِ دلِ من هنوز بوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937753,2187,7,0,'رخِ تو در دلم آمد مراد خواهم یافت','چهره تو در خاطر و یاد من آمد پس به‌آرزویم خواهم رسید زیرا بخت و حال مطلوب و سعادت‌بار از پی فال نکو و خوب می‌آید.',NULL);
INSERT INTO "verses" VALUES(1937754,2187,6,0,'زبانِ ناطقه در وصفِ شوق نالان است','وقتی که زبان (که گویاست) از وصف عشق‌، نالان و ناتوان شده‌است قلم زبان‌بریده چطور می‌تواند عشق را وصف کند. (تشبیهی است از این‌رو که زبانه قلم‌نی را برای نوشتن می‌برند)',NULL);
INSERT INTO "verses" VALUES(1937755,2187,6,1,'چه جای کِلکِ بریده‌زبانِ بیهُده‌گوست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937756,2187,5,0,'نثارِ رویِ تو هر برگِ گل که در چمن است','تک‌تک برگ گل‌های زیبای چمن فدای رخ زیبای تو باد‌‌، و تک‌تک سروهای خوش‌قامت که بر لب جوی هستند فدای قد و بالای خوش تو.',NULL);
INSERT INTO "verses" VALUES(1937757,2187,5,1,'فدای قَدِّ تو هر سروبُن که بر لبِ جوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937758,2187,4,0,'مگر تو شانه زدی زلفِ عنبرافشان را؟','گویا تو زلف و مویت را شانه زده‌ای که اینچنین نسیم‌، خوش‌عطر شده و خاک خوشبو شده است.',NULL);
INSERT INTO "verses" VALUES(1937759,2187,4,1,'که بادْ غالیه‌سا گشت و خاکْ عنبربوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937760,2187,3,0,'نه من سَبوکش این دیرِ رندسوزم و بس','فقط من در این دیر که بسیار زرنگ‌ها و رندها را اسیر خود کرده‌است میخواره نیستم بسیار افراد و سرهاست که «سبوی سر» آنها بر سنگ‌های این دیر شکسته است.',NULL);
INSERT INTO "verses" VALUES(1937761,2187,3,1,'بسا سَرا که در این کارخانه سنگ و سبوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937762,2187,2,0,'صبا ز حالِ دلِ تنگِ ما چه شرح دهد؟','صبا چگونه می‌تواند شرح حال ما را بازگوید وقتی که دل ما همچون غنچه در هم فرورفته و گلبرگ‌های آن بسته است.',NULL);
INSERT INTO "verses" VALUES(1937763,2187,2,1,'که چون شِکَنجِ ورق‌هایِ غنچه تو بر توست',NULL,NULL);
INSERT INTO "verses" VALUES(1937764,2187,1,0,'نظیرِ دوست ندیدم، اگر چه از مَه و مِهر','همچون یار خود زیبا ندیده‌ام اگرچه ماه و خورشید را آینه روی دوست خود کردم.',NULL);
INSERT INTO "verses" VALUES(1937765,2187,1,1,'نهادم آینه‌ها در مقابلِ رخِ دوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937766,2187,0,0,'سرِ ارادتِ ما و آستانِ حضرت دوست','سر و غرور ما بر درگاه و آستان حضرت دوست فرود آید و تسلیم است چون هرچه می‌رود و رخ می‌دهد میل و خواست اوست.',NULL);
INSERT INTO "verses" VALUES(1937767,2187,0,1,'که هر چه بر سرِ ما می‌رود ارادتِ اوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937768,2187,7,1,'چرا که حالِ نکو در قَفایِ فالِ نکوست',NULL,NULL);
INSERT INTO "verses" VALUES(1937769,2177,2,1,'به جز از عشقِ تو باقی همه فانی دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937770,2177,1,0,'قدر مجموعهٔ گل، مرغِ سَحَر داند و بس','ارزش گل‌ها را فقط بلبل می‌داند، نه‌هر کسی که صفحه‌ای بخواند بدان معنی‌است که آن‌را فهمیده است.',NULL);
INSERT INTO "verses" VALUES(1937771,2177,1,1,'که نه هر کو ورقی خواند، معانی دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937772,2166,9,1,'بنال بلبل بی‌دل که جای فریادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937773,2166,8,1,'که این عجوز، عروسِ هزاردامادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937774,2166,9,0,'نشان عهد و وفا نیست در تبسّمِ گل','در لبخند گل نشانی از عهد و وفا نمی‌بینم؛ ای بلبل‌، فغان برآور که جای فریاد و فغان است.',NULL);
INSERT INTO "verses" VALUES(1937775,2166,7,1,'که بر من و تو دَرِ اختیار نگشادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937776,2166,8,0,'مجو درستیِ عهد از جهانِ سست‌نهاد','به وفای جهان سست‌بنیاد اعتماد مکن؛ که این پیرزن زشت هزار شوهر است.',NULL);
INSERT INTO "verses" VALUES(1937777,2166,6,1,'که این لطیفهٔ عشقم ز رهروی یادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937778,2166,7,0,'رضا به داده بده وز جبین گره بگشای','به هرچه داری قناعت کن و شاد باش؛ که درِ اختیار بر ما گشوده نیست.',NULL);
INSERT INTO "verses" VALUES(1937779,2166,5,1,'که این حدیث، ز پیرِ طریقتم یادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937780,2166,6,0,'غمِ جهان مخور و پندِ من مَبَر از یاد','غم دنیا را مخور و این پند را فراموش مکن که این نکته عشق را از رهروی به‌یاد دارم',NULL);
INSERT INTO "verses" VALUES(1937781,2166,4,1,'ندانمت که در این دامگه چه افتادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937782,2166,5,0,'نصیحتی کنمت یاد گیر و در عمل آر','پندی ارزشمند را از من بشنو و بدان عمل کن؛ که آن‌را از پیر طریقت آموخته‌ام',NULL);
INSERT INTO "verses" VALUES(1937783,2166,3,1,'نشیمن تو نه این کُنجِ محنت‌آبادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937784,2166,4,0,'تو را ز کنگرهٔ عرش می‌زنند صفیر','تو را از عرش والا، دعوت می‌کنند، شان و جای تو آنجاست؛ چرا در این جای پرخطر گرفتار شده‌ای؟',NULL);
INSERT INTO "verses" VALUES(1937785,2166,2,1,'سروشِ عالَمِ غیبم چه مژده‌ها دادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937786,2166,3,0,'که ای بلندنظر شاهبازِ سِدره‌نشین','(به من گفت) ای شاهباز بلند‌پرواز! جای تو این ویرانه و محنت‌کده نیست؛ جای تو بر اوج درخت سدره است. (سدره یعنی درخت بهشتی که بالای آسمان هفتم قرار دارد)',NULL);
INSERT INTO "verses" VALUES(1937787,2166,1,1,'ز هر چه رنگِ تعلّق پذیرد آزادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937788,2166,2,0,'چه گویمت که به میخانه دوش مست و خراب','زبانم نمی‌تواند شرح دهد که دیشب در میخانه و در حال مستی، چه مژده‌هایی از سروش عالم غیب شنیده‌ام.',NULL);
INSERT INTO "verses" VALUES(1937789,2166,0,1,'بیار باده که بنیادِ عمر بر بادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937790,2166,1,0,'غلامِ همّتِ آنم که زیرِ چرخِ کبود','بنده آزادگی و همّت کسی هستم که از هر تعلّق و وابستگی رهاست.',NULL);
INSERT INTO "verses" VALUES(1937791,2166,0,0,'بیا که قصرِ اَمَل سخت سست‌بنیادست','(ساقی) بیا که کاخ آرزوهای ما سست و بی‌بنیاد است؛ باده بریز که عمر ما به‌سرعت باد می‌گذرد.',NULL);
INSERT INTO "verses" VALUES(1937792,2165,8,0,'حافظِ گمشده را با غمت ای یارِ عزیز','هوش مصنوعی: دوست عزیز، غم تو و حافظ گمشده‌ای که به او تعلق دارد، رابطه‌ای عمیق و کهن دارد که از گذشته‌های دور برقرار بوده است.',NULL);
INSERT INTO "verses" VALUES(1937793,2165,8,1,'اتحادیست که در عهدِ قدیم افتادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937794,2165,7,0,'آن که جز کعبه مُقامش نَبُد از یادِ لبت','هوش مصنوعی: کسی که جایگاهی جز کعبه ندارد، در درب میخانه به یاد لب‌های تو نشسته و مقیم شده است.',NULL);
INSERT INTO "verses" VALUES(1937795,2165,7,1,'بر درِ میکده دیدم که مُقیم افتادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937796,2165,6,0,'سایهٔ قَدِّ تو بر قالبم ای عیسی دم','هوش مصنوعی: سایه قد تو بر جسم من، ای عیسی، همانند روحی است که بر جسم بی‌روح و فاسد قرار گرفته است.',NULL);
INSERT INTO "verses" VALUES(1937797,2165,6,1,'عکسِ روحیست که بر عَظمِ رَمیم افتادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937798,2165,5,0,'همچو گَرد این تنِ خاکی نتوانَد برخاست','هوش مصنوعی: مانند گردی که بر روی این بدن خاکی نشسته، نمی‌تواند از کنار کوی تو بلند شود، زیرا بزرگی و عظمت تو بر او سایه افکنده است.',NULL);
INSERT INTO "verses" VALUES(1937799,2165,5,1,'از سرِ کویِ تو زان رو که عظیم افتادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937800,2165,4,0,'دلِ من در هوسِ رویِ تو ای مونس جان','هوش مصنوعی: دل من به یاد روی تو، ای همدم جانم، چون خاکی در جاده‌ای است که نسیم بر آن می‌وزد.',NULL);
INSERT INTO "verses" VALUES(1937801,2166,10,0,'حسد چه می‌بری ای سست‌نظم بر حافظ؟','چت جی پی تی: در این بیت، حافظ به حسودانی که بر او رشک می‌برند، می‌گوید که استعداد شاعری و مقبولیت سخن او، موهبتی الهی است و حسادت بر این نعمت بی‌ثمر است.',NULL);
INSERT INTO "verses" VALUES(1937802,2166,10,1,'قبولِ خاطر و لطفِ سخن خدادادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937803,2167,0,0,'بی مِهرِ رُخَت روزِ مرا نور نماندست','هوش مصنوعی: بدون عشق و زیبایی تو، روز من دیگر نوری ندارد و از عمر من جز شب تیره و تار باقی نمانده است.',NULL);
INSERT INTO "verses" VALUES(1937804,2167,0,1,'وز عمر، مرا جز شبِ دیجور نماندست',NULL,NULL);
INSERT INTO "verses" VALUES(1937805,2168,7,0,'فرق است از آبِ خِضر که ظُلمات جای او است','آبی که حضرت خضر (ع) از آن نوشید و عمر جاودانه گرفت در سرزمین تاریکی‌ها قرار داشت؛ حال ببین آب حیات ما که از خداوند بزرگ نشأت می‌گیرد چقدر ما را می‌تواند متعال کند.',NULL);
INSERT INTO "verses" VALUES(1937806,2168,7,1,'تا آبِ ما که مَنبَعش الله اکبر است',NULL,NULL);
INSERT INTO "verses" VALUES(1937807,2168,6,0,'شیراز و آبِ رکنی و این بادِ خوش نسیم','از شیراز و چشمه آب رکنی و باد خوشی که می‌وزد عیب نگیر که مانند خالِ صورت به زیبایی کل جهان افزوده است.',NULL);
INSERT INTO "verses" VALUES(1937808,2168,6,1,'عیبش مکن که خالِ رُخِ هفت کشور است',NULL,NULL);
INSERT INTO "verses" VALUES(1937809,2168,5,0,'دی وعده داد وصلم و در سر شراب داشت','دیروز در حالت مستی بود و به من وعده‌ی وصال داد. باید دید امروز در چه حالتی چه می‌گوید. (و چه نقشه‌ای دارد)',NULL);
INSERT INTO "verses" VALUES(1937810,2168,5,1,'امروز تا چه گوید و بازش چه در سر است',NULL,NULL);
INSERT INTO "verses" VALUES(1937811,2168,4,0,'یک قِصّه بیش نیست غمِ عشق، وین عجب','شگفت‌آور است که قصه غم عشق‌، یکی بیش نیست اما هر بار و هرکس که آن‌را تعریف می‌کند‌، تازه است و تکراری نیست.',NULL);
INSERT INTO "verses" VALUES(1937812,2168,4,1,'کز هر زبان که می‌شنوم، نامکرّر است',NULL,NULL);
INSERT INTO "verses" VALUES(1937813,2168,3,0,'از آستانِ پیرِ مغان، سر چرا کشیم؟','چرا از آستان پیر مغان سر بر تابیم؟ وقتی‌که بخت و گشایش از سرای اوست.',NULL);
INSERT INTO "verses" VALUES(1937814,2168,3,1,'دولت در آن سرا و گشایش در آن در است',NULL,NULL);
INSERT INTO "verses" VALUES(1937815,2168,2,0,'چون نقشِ غم ز دور بِبینی شراب خواه','وقتی که غم را از دور می‌بینی (پیش از آنکه نزدیک بیاید) شراب بنوش؛ داروی دفع آن‌را چنین تشخیص داده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1937816,2168,2,1,'تشخیص کرده‌ایم و مداوا مقرّر است',NULL,NULL);
INSERT INTO "verses" VALUES(1937817,2168,1,0,'ای نازنین‌پسر، تو چه مذهب گرفته‌ای؟','ای نازنین‌پسر، تو چه دین داری که ریختن خون ما بر تو، حلال‌ است؟',NULL);
INSERT INTO "verses" VALUES(1937818,2168,1,1,'کِت خونِ ما حلال‌تر از شیرِ مادر است',NULL,NULL);
INSERT INTO "verses" VALUES(1937819,2165,4,1,'خاکِ راهیست که در دستِ نسیم افتادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937820,2168,0,0,'باغِ مرا چه حاجتِ سرو و صنوبر است؟','در باغم چه نیازی به صنوبر و سرو دارم وقتی که شمشاد‌قدی در خانه دارم؟',NULL);
INSERT INTO "verses" VALUES(1937821,2167,7,0,'حافظ، ز غم از گریه نپرداخت به خنده','هوش مصنوعی: حافظ به دلیل غم و اندوه، نتوانسته است از گریه و زاری دست بردارد و دیگر نمی‌تواند به شادی روی بیاورد، چرا که درد و عزاداری او همچنان پابرجاست.',NULL);
INSERT INTO "verses" VALUES(1937822,2167,7,1,'ماتم زده را داعیهٔ سور نماندست',NULL,NULL);
INSERT INTO "verses" VALUES(1937823,2167,6,0,'در هِجرِ تو گر چشمِ مرا آبِ روان است','هوش مصنوعی: اگر در دوری تو چشمان من مانند آبِ روان باشد، پس بگذار که خون جگرم بریزد، چرا که عذری برای بی‌تابی من وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1937824,2167,6,1,'گو خونِ جگر ریز که معذور نماندست',NULL,NULL);
INSERT INTO "verses" VALUES(1937825,2167,5,0,'صبر است مرا چارهٔ هجرانِ تو لیکن','صبر تنها راه حل دوری تو برای من است، اما چطور می‌توانم صبر کنم وقتی که صبر من هم به اندازه‌ای نیست که بتواند ادامه پیدا کند؟',NULL);
INSERT INTO "verses" VALUES(1937826,2167,5,1,'چون صبر توان کرد که مقدور نماندست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937827,2167,4,0,'نزدیک شد آن دم که رقیب تو بگوید','زمانی نزدیک است که بشنوی که این عاشق رنجور و خسته، دیگر زنده نیست.',NULL);
INSERT INTO "verses" VALUES(1937828,2167,4,1,'دور از رُخَت این خستهٔ رنجور نماندست',NULL,NULL);
INSERT INTO "verses" VALUES(1937829,2167,3,0,'وصلِ تو اَجَل را ز سرم دور همی‌داشت','بخاطر وصال تو، مرگ از ذهنم دور بود، اما حالا که از تو دورم، مرگ از من دور نیست.',NULL);
INSERT INTO "verses" VALUES(1937830,2167,3,1,'از دولتِ هجرِ تو کنون دور نماندست',NULL,NULL);
INSERT INTO "verses" VALUES(1937831,2167,2,0,'می‌رفت خیالِ تو ز چشمِ من و می‌گفت','تصور تو از مقابل چشمانم دور می‌شد و به من می‌گفت که ای وای از این چشم که آبادان [به دیدن تو] نمانده است.',NULL);
INSERT INTO "verses" VALUES(1937832,2167,2,1,'هیهات از این گوشه که معمور نماندست',NULL,NULL);
INSERT INTO "verses" VALUES(1937833,2167,1,0,'هنگامِ وداعِ تو ز بس گریه که کردم','زمانی که از تو خداحافظی کردم، آنقدر گریه کردم که دیگر نوری در چشمانم باقی نمانده است',NULL);
INSERT INTO "verses" VALUES(1937834,2167,1,1,'دور از رخِ تو، چشمِ مرا نور نماندست',NULL,NULL);
INSERT INTO "verses" VALUES(1937835,2168,0,1,'شمشادِ خانه‌پرورِ ما از که کمتر است؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937836,2168,8,0,'ما آبرویِ فقر و قناعت نمی‌بریم','ما مفهوم قناعت و فقر را با تعبیراتِ مادی ضایع نمی‌کنیم. به پادشاه بگو که خداوند روزی معنوی ما را از پیش تعیین کرده است.',NULL);
INSERT INTO "verses" VALUES(1937837,2165,3,0,'زلفِ مشکینِ تو در گلشنِ فردوسِ عِذار','هوش مصنوعی: زلف‌های سیاه تو در باغ بهشتی چه معنایی دارد؟ مثل طاووسی که در باغ بهشت نشسته است.',NULL);
INSERT INTO "verses" VALUES(1937838,2165,2,0,'در خَمِ زلف تو آن خالِ سیه دانی چیست؟','هوش مصنوعی: در پیچ‌های زلف تو، آن نقطهٔ سیاه چیست؟ همان لکه‌ای که در حلقهٔ حرف «ج» افتاده است.',NULL);
INSERT INTO "verses" VALUES(1937839,2163,0,0,'رَواقِ منظرِ چشمِ من آشیانهٔ توست','ایوان خانه چشم من برای تو آماده پذیرایی است ای دلبرم؛ بیا و مهمان من باش که این خانه، خانهٔ توست. (رواق‌: یعنی بخش ورودی یک سرا و خانه که گاهی ایوان نیز گفته می‌شود)',NULL);
INSERT INTO "verses" VALUES(1937840,2163,0,1,'کَرَم نما و فرود آ که خانه، خانهٔ توست',NULL,NULL);
INSERT INTO "verses" VALUES(1937841,2163,1,0,'به لطفِ خال و خط از عارفان ربودی دل','به لطف و زیبایی خط و خال خود، عارفان پاکدامن را عاشق خود کردی؛ چه لطیفه‌هایی در زیر دام زلف و دانه خال تو که هست.',NULL);
INSERT INTO "verses" VALUES(1937842,2162,9,0,'حافظ! تو خَتم کن که هنر خود عَیان شود','هوش مصنوعی: حافظ! تو هنر خود را به نمایش بگذار، زیرا با دعوا و جدل با رقیب، نیازی به اثبات و نمایش آن نیست.',NULL);
INSERT INTO "verses" VALUES(1937843,2162,9,1,'با مدعی نزاع و مُحاکا چه حاجت است',NULL,NULL);
INSERT INTO "verses" VALUES(1937844,2162,8,0,'ای عاشقِ گدا چو لبِ روح‌بخشِ یار','هوش مصنوعی: ای عاشق بی‌چیز، وقتی که محبوبی چون او مایه‌ی زندگی و نشاط تو را می‌شناسد، دیگر چه نیازی به درخواست و خواهش داری؟',NULL);
INSERT INTO "verses" VALUES(1937845,2162,8,1,'می‌داندت وظیفه، تقاضا چه حاجت است',NULL,NULL);
INSERT INTO "verses" VALUES(1937846,2162,7,0,'ای مدعی برو که مرا با تو کار نیست','هوش مصنوعی: ای ادعا کننده، برو! من کاری با تو ندارم. دوستانم در کنارم هستند و به دشمنان نیازی ندارم.',NULL);
INSERT INTO "verses" VALUES(1937847,2162,7,1,'اَحباب حاضرند، به اَعدا چه حاجت است',NULL,NULL);
INSERT INTO "verses" VALUES(1937848,2162,6,0,'آن شد که بارِ منتِ مَلّاح بردمی','آن روزگار رفت و گذشت که منت کشتی‌بان را می‌کشیدم، حال که گوهر را به دست آورده‌ام به (سفر به) دریا نیازی ندارم.(آن شد: آن زمان گذشت.)',NULL);
INSERT INTO "verses" VALUES(1937849,2162,6,1,'گوهر چو دست داد به دریا چه حاجت است',NULL,NULL);
INSERT INTO "verses" VALUES(1937850,2162,5,0,'جامِ جهان نماست ضمیرِ منیرِ دوست','هوش مصنوعی: دل من آینه‌ای است که تصویر دوست در آن منعکس شده است. این دل، بیانگر نیاز و خواسته‌های من است؛ اما در خود آنجا، دیگر نیازی وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1937851,2162,5,1,'اظهارِ احتیاج، خود آن جا چه حاجت است',NULL,NULL);
INSERT INTO "verses" VALUES(1937852,2162,4,0,'محتاج قِصه نیست گَرَت قصدِ خون ماست','هوش مصنوعی: اگر می‌خواهی ما را نابود کنی، نیازی نیست به داستان و بهانه بیاوری، چون ما از خود تو هستیم. پس چه نیازی به فریب و دزدی است؟',NULL);
INSERT INTO "verses" VALUES(1937853,2162,4,1,'چون رَخت از آن توست، به یغما چه حاجت است',NULL,NULL);
INSERT INTO "verses" VALUES(1937854,2162,3,0,'اربابِ حاجتیم و زبانِ سؤال نیست','صاحب‌نیاز هستیم و زبان و توان گفتن نیاز خود را نداریم در درگاه بخشندگان چه نیازی به خواهش و درخواست هست؟',NULL);
INSERT INTO "verses" VALUES(1937855,2162,3,1,'در حضرتِ کریم، تمنا چه حاجت است',NULL,NULL);
INSERT INTO "verses" VALUES(1937856,2162,2,0,'ای پادشاهِ حُسن خدا را بسوختیم','هوش مصنوعی: ای پادشاه زیبایی، ما دل خود را به عشق تو سوختیم؛ حالا از ما بپرس که یک نیازمند چه چیزی می‌خواهد.',NULL);
INSERT INTO "verses" VALUES(1937857,2162,2,1,'آخِر سؤال کن که گدا را چه حاجت است',NULL,NULL);
INSERT INTO "verses" VALUES(1937858,2162,1,0,'جانا به حاجتی که تو را هست با خدا','ای عزیز‌، تو را قسم می‌دهم به آن نیاز که به خدا می‌بری یک بار از ما بپرس که ما چه نیاز داریم.',NULL);
INSERT INTO "verses" VALUES(1937859,2162,1,1,'کآخِر دمی بپرس که ما را چه حاجت است',NULL,NULL);
INSERT INTO "verses" VALUES(1937860,2162,0,0,'خلوت گُزیده را به تماشا چه حاجت است','کسی که خلوت را گزیده و انتخاب کرده است چه نیازی به گردش و تماشا دارد؟ وقتی که او در کوی دوست اقامت دارد چه نیاز دارد به صحرا و گلزار برود؟',NULL);
INSERT INTO "verses" VALUES(1937861,2162,0,1,'چون کوی دوست هست به صحرا چه حاجت است',NULL,NULL);
INSERT INTO "verses" VALUES(1937862,2161,6,0,'ز دستِ جورِ تو گفتم زِ شهر خواهم رفت','از دست ستم و بی‌رحمی تو گفتم تو را ترک خواهم گفت و از این شهر خواهم رفت؛ به خنده به من گفت: برو حافظ، راه باز است! چه‌کسی پای تو را بسته‌است؟',NULL);
INSERT INTO "verses" VALUES(1937863,2161,6,1,'به خنده گفت که حافظ برو، که پایِ تو بست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937864,2161,5,0,'تو خود وصالِ دگر بودی ای نسیمِ وصال','ای نسیم خنک و دل‌انگیز شَمال! تو لذت وصال را به من هدیه کردی، مرا بنگر که به وفای که امید بستم!',NULL);
INSERT INTO "verses" VALUES(1937865,2161,5,1,'خطا نِگر که دل امید در وفایِ تو بست',NULL,NULL);
INSERT INTO "verses" VALUES(1937866,2161,4,0,'چو نافه بر دلِ مسکینِ من گره مَفِکن','با گره زلفت که همچون نافه مِشکین‌ است کار را بر دلِ مسکین من سخت نکن زیرا سر زلفت به دلم قول داده است که گره‌گشا باشد. (منظور از سر ِزلفِ گره‌گشا، انتهای زلف بافته شده است که باز است. گره افکندن کنایه است از سخت‌کردن کاری.)',NULL);
INSERT INTO "verses" VALUES(1937867,2161,4,1,'که عهد با سرِ زلفِ گره‌گشایِ تو بست',NULL,NULL);
INSERT INTO "verses" VALUES(1937868,2163,1,1,'لطیفه‌های عَجَب زیرِ دام و دانهٔ توست',NULL,NULL);
INSERT INTO "verses" VALUES(1937869,2163,2,0,'دلت به وصلِ گل ای بلبلِ صبا خوش باد','ای بلبل خوش‌خوان بهاری، برای تو در کنار گل آرزوی شادی می‌نمایم زیرا با آواز عاشقانه خود چمن و بوستان را زیباتر کرده‌ای.',NULL);
INSERT INTO "verses" VALUES(1937870,2163,2,1,'که در چمن همه گلبانگِ عاشقانهٔ توست',NULL,NULL);
INSERT INTO "verses" VALUES(1937871,2163,3,0,'عِلاجِ ضعفِ دلِ ما به لب حوالت کن','مفرح یعنی نوشیدنی‌یی که از گلاب و قند و زعفران و ... برای شادی‌ و علاج ضعف دل می‌ساخته‌اند. اگر در آن یاقوت انداخته می‌شد «مفرح یاقوت‌» و اگر زر «مفرح زر» و ...‌؛ قدما بر این باور بودند که گوهر‌ِ آن سنگ‌های ارزشمند در شربت اثر می‌کند.',NULL);
INSERT INTO "verses" VALUES(1937872,2165,2,1,'نقطهٔ دوده که در حلقه جیم افتادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937873,2165,1,0,'چَشمِ جادویِ تو خود عینِ سَوادِ سِحْر است','هوش مصنوعی: چشم جادوی تو به اندازه سحر و جادو تاثیرگذار است، اما این نکته وجود دارد که این جادو در واقع دچار نقص و مشکل شده است.',NULL);
INSERT INTO "verses" VALUES(1937874,2165,1,1,'لیکن این هست که این نُسخه سَقیم اُفتادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937875,2165,0,0,'تا سرِ زلفِ تو در دستِ نسیم افتادست','هوش مصنوعی: زمانی که زلف‌های تو در دست نسیم قرار گرفت، دل دل‌باخته و پر غصه‌ام از شدت غم، به دو نیم تبدیل شد.',NULL);
INSERT INTO "verses" VALUES(1937876,2165,0,1,'دلِ سودازده از غُصه دو نیم افتادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937877,2164,6,0,'برو فَسانه مخوان و فُسون مدم حافظ','هوش مصنوعی: بهتر است که از قصه‌ها و جادوها فاصله بگیری، زیرا من از این داستان‌ها و جادوها تجربیات زیادی دارم.',NULL);
INSERT INTO "verses" VALUES(1937878,2164,6,1,'کز این فسانه و افسون مرا بسی یادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937879,2164,5,0,'دلا مَنال ز بیداد و جورِ یار که یار','هوش مصنوعی: دلبر تو با ستم و بی‌عدالتی‌اش، نباید تو را آزار دهد، زیرا خودش سبب این وضعیت شده و همین که به تو این جفا را کرده، نشانه‌ای است از آنچه که به تو داده است.',NULL);
INSERT INTO "verses" VALUES(1937880,2164,5,1,'تو را نصیب همین کرد و این از آن دادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937881,2164,4,0,'اگر چه مستیِ عشقم خراب کرد ولی','هوش مصنوعی: هر چند که عشق مرا به حالت ناهنجاری کشاند، اما از همان ناهنجاری، بنیاد زندگی و وجود من به وجود آمده است.',NULL);
INSERT INTO "verses" VALUES(1937882,2164,4,1,'اساسِ هستیِ من زآن خراب، آبادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937883,2164,3,0,'گدایِ کویِ تو از هشت خُلد، مستغنی‌ست','هوش مصنوعی: فقیر در کوی تو از بهشت هم بی‌نیاز است و عاشق تو از هر دو دنیا آزاد و رهاست.',NULL);
INSERT INTO "verses" VALUES(1937884,2164,3,1,'اسیرِ عشقِ تو از هر دو عالم آزادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937885,2164,2,0,'به کام تا نرساند مرا لبش، چون نای','هوش مصنوعی: تا زمانی که لبش مرا به کام نرساند، مثل نای نصیحتی که همه دنیا برای من می‌زنند، تنها به گوش من می‌وزد.',NULL);
INSERT INTO "verses" VALUES(1937886,2165,3,1,'چیست؟ طاووس که در باغِ نعیم افتادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937887,2164,2,1,'نصیحتِ همه عالم به گوشِ من بادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937888,2164,1,0,'میان او که خدا آفریده است از هیچ','هوش مصنوعی: در میان موجودات که خداوند آفریده، هیچ چیز کوچک یا بی‌اهمیتی وجود ندارد که به آن بی‌توجهی شده باشد. هر چیزی در آفرینش خود دارای اهمیت و معنایی خاص است.',NULL);
INSERT INTO "verses" VALUES(1937889,2164,0,0,'برو به کارِ خود ای واعظ این چه فریادست؟','هوش مصنوعی: ای واعظ، به کار خود بپرداز و نه اینکه به من فریاد بزنی. چرا دل من از مسیرش منحرف شده است و تو چه چیزی به تو آسیب زده که اینگونه می‌کنی؟',NULL);
INSERT INTO "verses" VALUES(1937890,2164,0,1,'مرا فِتاد دل از ره، تو را چه اُفتادست؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937891,2163,3,1,'که این مُفَرّح یاقوت در خزانهٔ توست',NULL,NULL);
INSERT INTO "verses" VALUES(1937892,2163,4,0,'به تن مُقصرم از دولتِ ملازمتت','تن من در خدمت تو کوتاهی کرده است (دور از تو هستم) ولی این را بدان که دل و جان من، خاک آستانه توست.',NULL);
INSERT INTO "verses" VALUES(1937893,2163,4,1,'ولی خلاصهٔ جان، خاکِ آستانهٔ توست',NULL,NULL);
INSERT INTO "verses" VALUES(1937894,2163,5,0,'من آن نیَم که دَهَم نقدِ دل به هر شوخی','دل را به هر شوخ و شیرینی نمی‌سپارم گنجی که از عشق تو در سینه دارم به‌همان مُهر باقی است.',NULL);
INSERT INTO "verses" VALUES(1937895,2163,5,1,'دَرِ خزانه، به مُهر تو و نشانهٔ توست',NULL,NULL);
INSERT INTO "verses" VALUES(1937896,2163,6,0,'تو خود چه لعبتی ای شهسوارِ شیرین کار','عجب زیبا بُتی هستی تو ای تک‌سوار ماهر که اسب سرکش فلک را رام تازیانه خود کرده‌ای.',NULL);
INSERT INTO "verses" VALUES(1937897,2163,6,1,'که توسَنی چو فلک، رامِ تازیانهٔ توست',NULL,NULL);
INSERT INTO "verses" VALUES(1937898,2163,7,0,'چه جای من، که بِلَغزَد سپهرِ شعبده‌باز','من که چیزی نیستم تو حتی روزگار پُرفن و شعبده‌باز را نیز با بهانه‌‌های بی‌پایانت دست به سر ‌می‌کنی. (انبانه یعنی کیسه چرمی بزرگ که بر دوش حمل می‌کنند، در اینجا بطور خاص مقصود کیسه همراه شعبده‌بازان و تردستان است. لغزیدن کنایه است از فریب خوردن)',NULL);
INSERT INTO "verses" VALUES(1937899,2163,7,1,'از این حیَل که در انبانهٔ بهانهٔ توست',NULL,NULL);
INSERT INTO "verses" VALUES(1937900,2163,8,0,'سرودِ مجلست اکنون فلک به رقص آرَد','آسمان و آسمانیان به‌رقص و پایکوبی می‌افتند وقتی‌که غزل حافظ در مجلس تو به‌سرود خوانده‌شود.',NULL);
INSERT INTO "verses" VALUES(1937901,2163,8,1,'که شعرِ حافظِ شیرین سخن ترانهٔ توست',NULL,NULL);
INSERT INTO "verses" VALUES(1937902,2164,1,1,'دقیقه‌ای‌ست که هیچ آفریده نَگشادست',NULL,NULL);
INSERT INTO "verses" VALUES(1937903,2161,3,1,'ولی چه سود که سررشته در رضای تو بست',NULL,NULL);
INSERT INTO "verses" VALUES(1937904,2168,8,1,'با پادشه بگوی که روزی مقدّر است',NULL,NULL);
INSERT INTO "verses" VALUES(1937905,2168,9,0,'حافظ چه طُرفه شاخ نباتیست کِلکِ تو','ای حافظ قلمِ تو چه شاخه درخت شگفت‌آورِ شیرینی است که میوه‌اش (شعر) حتی دلپذیرتر از شهد و شکر است.',NULL);
INSERT INTO "verses" VALUES(1937906,2175,2,0,'در مذهبِ ما، باده، حلال است ولیکن','در آئین ما نوشیدن شراب مجاز است، اما در غیاب تو، ای خوش‌چهره و زیبا، این کار ناپسند و منع شده است.',NULL);
INSERT INTO "verses" VALUES(1937907,2175,2,1,'بی‌رویِ تو ای سَروِ گُل‌اندام، حرام است',NULL,NULL);
INSERT INTO "verses" VALUES(1937908,2175,3,0,'گوشم همه بر قولِ نی و نغمهٔ چنگ است','گوشم به صدای نی و موسیقی چنگ توجه دارد و چشمانم به لبان سرخ و حرکت جام خیره است.',NULL);
INSERT INTO "verses" VALUES(1937909,2175,3,1,'چشمم، همه، بر لعلِ لب و گَردشِ جام است',NULL,NULL);
INSERT INTO "verses" VALUES(1937910,2175,1,0,'گو شمع میارید در این جمع که امشب','هوش مصنوعی: شما نیازی به آوردن شمع در این محفل ندارید چون امشب در جمع ما، زیبایی چهره دوست به اندازه‌ای است که نورانی‌تر از هر شمعی است.',NULL);
INSERT INTO "verses" VALUES(1937911,2175,1,1,'در مجلسِ ما، ماهِ رخِ دوست، تمام است',NULL,NULL);
INSERT INTO "verses" VALUES(1937912,2175,0,0,'گُل در بَر و مِی در کَف و معشوق به کام است','با گل در دستانم و جام می در اختیار، و محبوبم در کنارم، احساس می‌کنم که در این لحظه آنقدر سرافراز و بلند جایگاهم که گویی سلطان عالم به خوشبختی ،در نظرم غلامی بیش نیست.',NULL);
INSERT INTO "verses" VALUES(1937913,2175,0,1,'سلطانِ جهانم به چُنین روز، غلام است',NULL,NULL);
INSERT INTO "verses" VALUES(1937914,2174,6,0,'به هیچ دور نخواهند یافت هُشیارش','هوش مصنوعی: هیچ‌کس به این سادگی و روشنی که حافظ ما در حال مستی از بادهٔ جاودان است، نخواهد توانست به آگاهی و درک درست دست یابد.',NULL);
INSERT INTO "verses" VALUES(1937915,2174,6,1,'چُنین که «حافظِ» ما، مَسْتِ بادهٔ اَزَل است',NULL,NULL);
INSERT INTO "verses" VALUES(1937916,2174,5,0,'دلم، امیدِ فراوان به وَصْلِ رویِ تو داشت','هوش مصنوعی: دل من امید زیادی به دیدار تو داشت، اما با این حال، مرگ در راه زندگی مانع تحقق این آرزو شد.',NULL);
INSERT INTO "verses" VALUES(1937917,2174,5,1,'ولی اَجَل به رَهِ عمر، رَهْزَنِ اَمَل است',NULL,NULL);
INSERT INTO "verses" VALUES(1937918,2174,4,0,'بگیر طُرِّهٔ مه‌چهره‌ای و قِصِّه مَخوان','هوش مصنوعی: این شعر اشاره به زیبایی و جذابیت چهره‌های دلنشین دارد و بیان می‌کند که برای توصیف این زیبایی، نیازی به صحبت دربارهٔ سرنوشت و بدی‌ها نیست. زیبایی‌ها و تأثیرات نجومی یا موقعیت‌های زندگی انسان‌ها، مانند زحل و زهره، جایگاهی در این توصیف نخواهند داشت.',NULL);
INSERT INTO "verses" VALUES(1937919,2174,4,1,'که سَعْد و نَحْس ز تأثیرِ زُهْرِه و زُحَل است',NULL,NULL);
INSERT INTO "verses" VALUES(1937920,2174,3,0,'به چَشْمِ عَقْل در این رَهْگُذارِ پُرآشوب','هوش مصنوعی: از دید عقل، در این مسیر پرچالش و آشفته زندگی، جهان و فعالیت‌های آن ناپایدار و بی‌ثبات به نظر می‌رسند.',NULL);
INSERT INTO "verses" VALUES(1937921,2174,3,1,'جهان و کارِ جهان، بی‌ثُبات و بی‌مَحَل است',NULL,NULL);
INSERT INTO "verses" VALUES(1937922,2174,2,0,'نه من ز بی‌عَمَلی، در جهان، مَلولَم و بَس','نه اینکه فقط من از بی‌عملی در این دنیا خسته‌ام؛ بلکه ناراحتی علمای بزرگ هم ناشی از علمی است که به عمل نمی‌انجامد.',NULL);
INSERT INTO "verses" VALUES(1937923,2174,2,1,'مَلالَتِ عُلما هم ز عِلْمِ بی‌عَمَل است',NULL,NULL);
INSERT INTO "verses" VALUES(1937924,2174,1,0,'جَریده رُو که گُذَرگاهِ عافیت، تَنْگ است','هوش مصنوعی: در این دنیا، مسیر آرامش و راحتی بسیار باریک و دشوار است. بنابراین، از فرصت‌های خوشی و لذت‌بردن استفاده کن، زیرا عمر باارزش و بی‌بدیل است و نباید آن را نادیده گرفت.',NULL);
INSERT INTO "verses" VALUES(1937925,2174,1,1,'پیاله گیر که عُمرِ عزیز، بی‌بَدَل است',NULL,NULL);
INSERT INTO "verses" VALUES(1937926,2174,0,0,'در این زمانه، رفیقی که خالی از خَلَل است','در این دوره از زمان ، دوستی که بدون نقص و عیب باشد، پیاله‌ ی شراب ناب و مجموعه ای گزیده از غزل است.',NULL);
INSERT INTO "verses" VALUES(1937927,2174,0,1,'صُراحیِ مِیِ ناب و سَفینهٔ غزل است',NULL,NULL);
INSERT INTO "verses" VALUES(1937928,2173,6,0,'خموش «حافظ» و این نکته‌هایِ چونِ زَرِ سُرخ','هوش مصنوعی: سکوت کن حافظ و این نکات ارزشمند را که مانند طلا قرمز است، حفظ کن؛ چراکه در این شهر، تبهکاران و کلاهبرداران وجود دارند.',NULL);
INSERT INTO "verses" VALUES(1937929,2173,6,1,'نگاه دار که قَلّابِ شهر، صَرّاف است',NULL,NULL);
INSERT INTO "verses" VALUES(1937930,2173,5,0,'حَدیثِ مُدّعیان و خیالِ همکاران','هوش مصنوعی: داستان کسانی که ادعای دانش و کارایی دارند و خیال همکارانشان، مشابه حکایت زردوز و بوریاباف است. این به این معناست که هر یک از آن‌ها در عالم خود مشغولند و تنها در خیال و سخن خود به هم مرتبط‌اند، بدون آنکه واقعا یکدیگر را درک کنند یا در عمل همکاری داشته باشند.',NULL);
INSERT INTO "verses" VALUES(1937931,2173,5,1,'همان حکایتِ زَردوز و بوریاباف است',NULL,NULL);
INSERT INTO "verses" VALUES(1937932,2173,4,0,'بِبُر ز خَلق و چو عَنقا، قیاسِ کار بگیر','هوش مصنوعی: از میان مردم فاصله بگیر و مانند پرنده‌ افسانه‌ای عَنقا، کار خود را بسنج. زیرا شهرت و آوازه‌ی کسانی که گوشه‌نشین هستند، از یکی تا آخری جهان پراکنده است.',NULL);
INSERT INTO "verses" VALUES(1937933,2173,4,1,'که صیتِ گوشه‌نشینان، زِ قاف تا قاف است',NULL,NULL);
INSERT INTO "verses" VALUES(1937934,2173,3,0,'به دُرد و صاف، تو را حُکْم نیست خوش دَرکَش','هوش مصنوعی: در اینجا بیان می‌شود که تو نمی‌توانی در مورد نوشیدنی‌های مختلف قضاوت کنی، زیرا هر چیزی که ساقی ما ارائه می‌دهد، به نوعی لطف و نیکی است. به عبارتی، هر آنچه در این باره تجربه می‌کنی، باید با نگاهی مثبت و با درک دقیق‌تری پذیرش کنی.',NULL);
INSERT INTO "verses" VALUES(1937935,2175,4,0,'در مجلسِ ما، عِطر میامیز که ما را','هوش مصنوعی: در جمع ما عطر خوشی پراکنده نکن، زیرا هر لحظه به خاطر بوی گیسوی تو، بوها و رایحه‌ها برای ما دلپذیر است.',NULL);
INSERT INTO "verses" VALUES(1937936,2175,4,1,'هر لحظه، زِ گیسو‌یِ تو، خوش‌بوی مشام است',NULL,NULL);
INSERT INTO "verses" VALUES(1937937,2175,5,0,'از چاشنیِ قند مگو هیچ و زِ شِکَّر','هوش مصنوعی: به هیچ عنوان درباره‌ی شیرینی قند صحبت نکن، زیرا من از لب‌های شیرین تو لذت می‌برم.',NULL);
INSERT INTO "verses" VALUES(1937938,2175,5,1,'زآن رو که مرا از لبِ شیرینِ تو، کام است',NULL,NULL);
INSERT INTO "verses" VALUES(1937939,2177,0,0,'صوفی از پرتو مِی رازِ نهانی دانست','صوفی با نور و درخشش می راز بزرگی را فهمید؛ اصل هرکس را از این لعل سرخ می‌توانی بشناسی.',NULL);
INSERT INTO "verses" VALUES(1937940,2177,0,1,'گوهرِ هر کس از این لعل، توانی دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937941,2176,8,0,'بلندمرتبه شاهی که نُه رِواقِ سِپِهر','هوش مصنوعی: شاهی با مقام و مرتبه‌ی بلند، چون نُه آسمان، نشانه‌ای از زیبایی و شکوه را در کجای گنبد آسمان فراموش نکند.',NULL);
INSERT INTO "verses" VALUES(1937942,2176,8,1,'نمونه‌ای ز خَمِ طاقِ بارگَه دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937943,2176,7,0,'حدیثِ حافظ و ساغر که می‌زند پنهان','هوش مصنوعی: حافظ درباره‌ی داستان خود و شراب‌نوشی‌اش سخن می‌گوید و به این نکته اشاره دارد که وقتی ماجرا به عشق و شیدایی مربوط می‌شود، دیگر جایی برای نظارت و کنترل نیست. در این عالم، حتی قدرت‌مندان نیز نمی‌توانند به حقیقت عشق و شادی دست‌اندازی کنند.',NULL);
INSERT INTO "verses" VALUES(1937944,2176,7,1,'چه جایِ محتسب و شِحنه، پادشَه دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937945,2176,6,0,'ز جورِ کوکبِ طالع ،سَحَرگَهان چشمم','هوش مصنوعی: به خاطر تأثیرات بدی که ستاره‌ها بر سرنوشت من دارند، در سحرگاه چشمانم آن‌قدر اشک ریخت که ونوس (ناهید) آن را دید و ماه هم متوجه شد.',NULL);
INSERT INTO "verses" VALUES(1937946,2176,6,1,'چنان گریست که ناهید دید و مَه دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937947,2176,5,0,'دلم ز نرگسِ ساقی اَمان نخواست به جان','هوش مصنوعی: دل من از نرگس ساقی هیچ در امان نیست، زیرا می‌دانم که آن معشوق سیاه دل چه شیوه‌ای دارد.',NULL);
INSERT INTO "verses" VALUES(1937948,2176,5,1,'چرا که شیوهٔ آن تُرکِ دل سیه دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937949,2176,4,0,'ورایِ طاعتِ دیوانگان ز ما مَطَلَب','هوش مصنوعی: از ما چیزی فراتر از تسلیم‌گری دیوانگان نخواهید، چون مذهب‌مان این است که شیخ ما، عاقل را به گناه متهم می‌داند.',NULL);
INSERT INTO "verses" VALUES(1937950,2176,4,1,'که شیخِ مذهبِ ما عاقلی گُنَه دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937951,2176,3,0,'هر آن که رازِ دو عالم ز خطِ ساغَر خواند','هوش مصنوعی: هر کسی که توانسته باشد اسرار دو جهان را از طریق خط ساغر ببیند و آشنایی با رموز جام جم را از نشانه‌های خاک راه به دست آورد، به درکی عمیق و بصیرتی خاص دست یافته است.',NULL);
INSERT INTO "verses" VALUES(1937952,2176,3,1,'رُموزِ جامِ جم از نقشِ خاکِ ره دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937953,2173,3,1,'که هرچه ساقیِ ما کَرْد عِیْنِ اَلطاف است',NULL,NULL);
INSERT INTO "verses" VALUES(1937954,2176,2,0,'بر آستانهٔ میخانه هر که یافت رَهی','هوش مصنوعی: هر کسی که در آستانهٔ میخانه راهی پیدا کند و از پرباری شراب بهره‌مند شود، به راز و رمزهای صومعه و مذهب پی می‌برد.',NULL);
INSERT INTO "verses" VALUES(1937955,2176,1,0,'زمانه افسر رندی نداد جز به کسی','هوش مصنوعی: دنیا فقط به افرادی که عظمت و بزرگی خود را در زیر این کلاه (نماد علم و معرفت) می‌شناسند، مقام و اعتبار می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1937956,2176,1,1,'که سرفرازیِ عالَم در این کُلَه دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937957,2176,0,0,'به کویِ میکده هر سالِکی که رَه دانست','هوش مصنوعی: هر سال که به میکده می‌روم، اگر راهی جدید پیدا کنم، به خوبی می‌دانم که باید از فکر و اندیشه‌ی بی‌فایده دوری کنم.',NULL);
INSERT INTO "verses" VALUES(1937958,2176,0,1,'دری دگر زدن اندیشهٔ تَبَه دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937959,2175,9,0,'با محتسبم، عیب مگویید که او نیز','نقص‌ها و عیب‌های من را پیش مُحتسب بیان نکنید، زیرا او هم مانند ما همیشه در جستجوی لذت و شادی پایدار و نوشیدن دائمی شراب است.',NULL);
INSERT INTO "verses" VALUES(1937960,2175,9,1,'پیوسته، چو ما در طلبِ عیشِ مدام است',NULL,NULL);
INSERT INTO "verses" VALUES(1937961,2175,10,0,'حافظ! منشین بی‌مِی و معشوق، زمانی','هوش مصنوعی: حافظ می‌گوید که در زمانه‌ای که بهار و گل‌ها و عید آمده‌اند، نباید از می و عشق دور بمانی. این ایام فرصتی است که باید از لذت‌ها و زیبایی‌های زندگی بهره‌مند شد.',NULL);
INSERT INTO "verses" VALUES(1937962,2175,10,1,'کایَّامِ گُل و یاسمن و عیدِ صیام است',NULL,NULL);
INSERT INTO "verses" VALUES(1937963,2175,8,0,'مِی‌خواره و سرگشته و رندیم و نظرباز','ما شراب نوش، سرگشته و آزاد و بی‌پروا هستیم درست! اما کسی را که بر خلاف ما در این شهر باشد، نمی‌شناسیم. (یعنی همه‌ در دنیا میخواره و سرگشته و ... هستند ولی به رو و زبان نمیارند)',NULL);
INSERT INTO "verses" VALUES(1937964,2175,8,1,'وآن کس که چو ما نیست در این شهر، کدام است؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937965,2175,7,0,'از ننگ چه گویی که مرا نام ز ننگ است؟','هوش مصنوعی: ننگ من چنان عمیق است که دیگر نمی‌توانم درباره‌اش صحبت کنم و وقتی از نامم می‌پرسی، می‌بینی که خود نامم نیز یادآور همان ننگ است.',NULL);
INSERT INTO "verses" VALUES(1937966,2175,7,1,'وز نام چه پرسی که مرا ننگ ز نام است؟',NULL,NULL);
INSERT INTO "verses" VALUES(1937967,2175,6,0,'تا گنجِ غمت در دِلِ ویرانه‌، مقیم است','هوش مصنوعی: تا وقتی که درد و غم تو در دل من جا دارد، همیشه برای من همین محل و این مکان بی‌سر و سامان، جایگاه و مقام است.',NULL);
INSERT INTO "verses" VALUES(1937968,2175,6,1,'همواره مرا کویِ خرابات، مقام است',NULL,NULL);
INSERT INTO "verses" VALUES(1937969,2176,2,1,'ز فیضِ جامِ مِی اَسرار خانقَه دانست',NULL,NULL);
INSERT INTO "verses" VALUES(1937970,2168,9,1,'کِش میوه دلپذیرتر از شهد و شکّر است',NULL,NULL);
INSERT INTO "verses" VALUES(1937971,2173,2,0,'فقیهِ مدرسه، دی، مَسْت بود و فَتوی داد','هوش مصنوعی: فقیهی که در مدرسه درس می‌خواند به خمر مست شده بود و فتوا داد که نوشیدن شراب حرام است، اما بهتر از استفاده از اموال وقف است.',NULL);
INSERT INTO "verses" VALUES(1937972,2173,1,0,'بخواه دَفْتَرِ اَشعار و راهِ صَحرا گیر','هوش مصنوعی: بیایید دفتر اشعار را بگیریم و به دشت برویم؛ چون اکنون زمان درس و بررسی های عمیق و دشوار است.',NULL);
INSERT INTO "verses" VALUES(1937973,2170,5,0,'سپهرِ بَر شده پرویزنی‌ست خون افشان','هوش مصنوعی: آسمان بر فراز، گویی در حال جشن و شادی است و خون‌هایی که ریخته می‌شود، تکه‌هایی از تاج و نشانه‌های بزرگی و شکوه پادشاهی پرویز را به یاد می‌آورد.',NULL);
INSERT INTO "verses" VALUES(1937974,2170,4,0,'مجوی عیشِ خوش از دورِ باژگونِ سِپِهر','{استاد محمدزاده} در زیر آسمان واژگون به دنبال خوشی نباش زیرا حتی شراب گوارا هم طعم شراب ناخالص میدهد',NULL);
INSERT INTO "verses" VALUES(1937975,2170,4,1,'که صاف این سر خُم جمله دُردی آمیز است',NULL,NULL);
INSERT INTO "verses" VALUES(1937976,2170,3,0,'به آبِ دیده بشوییم خِرقه‌ها از می','هوش مصنوعی: بیا بگذاریم که با اشک‌هایمان لباس‌هایمان را از شراب بشوییم، چون اکنون زمان پرهیز و احتیاط است.',NULL);
INSERT INTO "verses" VALUES(1937977,2170,3,1,'که موسمِ وَرَع و روزگارِ پرهیز است',NULL,NULL);
INSERT INTO "verses" VALUES(1937978,2170,2,0,'در آستینِ مُرَقَع پیاله پنهان کن','هوش مصنوعی: پیاله را در آستینِ پر زرق و برق خود پنهان کن، زیرا همچون چشمی که در ظرف شراب وجود دارد، دنیای کنونی خطرناک و خونریز است.',NULL);
INSERT INTO "verses" VALUES(1937979,2170,2,1,'که همچو چشمِ صُراحی، زمانه خونریز است',NULL,NULL);
INSERT INTO "verses" VALUES(1937980,2170,1,0,'صُراحی‌ای و حریفی گَرَت به چَنگ افتد','هوش مصنوعی: اگر دوست و همصحبتی پیدا کردی، از او بهره ببر و عقل را در نظر داشته باش، زیرا زمانه پر از فتنه و آشفتگی است.',NULL);
INSERT INTO "verses" VALUES(1937981,2170,1,1,'به عقل نوش که ایام فتنه‌ انگیز است',NULL,NULL);
INSERT INTO "verses" VALUES(1937982,2170,0,0,'اگر چه باده فَرَح بخش و باد گُل‌بیز است','هوش مصنوعی: اگرچه نوشیدن شراب خوشحالی می‌آورد و بادی که عطر گل را به همراه دارد دلپذیر است، اما به صدای ساز نباید شراب نوشید چون مأموران و نگهبانان سخت‌گیر هستند.',NULL);
INSERT INTO "verses" VALUES(1937983,2170,0,1,'به بانگِ چَنگ مخور مِی که مُحتَسِب تیز است',NULL,NULL);
INSERT INTO "verses" VALUES(1937984,2169,8,0,'ای مجلسیان، سوزِ دلِ «حافظِ» مسکین','هوش مصنوعی: ای کسانی که در مجلس هستید، از شمع بپرسید که دلِ دردکشیده و رنجور حافظ چه سوز و گدازی دارد.',NULL);
INSERT INTO "verses" VALUES(1937985,2169,7,0,'در کعبهٔ کویِ تو، هر آن‌کس که بیاید','هوش مصنوعی: هر کس که به کعبهٔ تو بیاید، در واقع در حال عبادت و نماز است، چون نگاهش به ابروی توست که به نوعی قبلهٔ او شده.',NULL);
INSERT INTO "verses" VALUES(1937986,2169,8,1,'از شمع بپرسید که در سوز و گداز است',NULL,NULL);
INSERT INTO "verses" VALUES(1937987,2169,6,0,'بردوخته‌ام دیده چو باز از همه عالَم','این بیت، شاعر با استفاده از دو معنای متفاوت برای واژه «باز»، معنای عمیقی را آفریده است:۱. باز (پرنده): که نگاهی تیزبین و متمرکز دارد و چشمانش را از غیرِ شکار (در اینجا غیرِ معشوق) می‌بندد.۲. باز (گشاده/در حالِ نگاه کردن): که در مصرع دوم به معنای گشوده ماندن چشم برای تماشای رخ محبوب است.تضاد «دوختن» (بستن) و «باز» (گشودن) در کنار تشبیه به «باز» (پرنده)، یک تصویرسازی کلاسیک و در عین حال دلنشین است که نشان می‌دهد عاشق برای رسیدن به آن یگانه دیدن (دیدار معشوق)، باید چشم بر تمام کثرت‌های عالم ببندد.',NULL);
INSERT INTO "verses" VALUES(1937988,2169,7,1,'از قبلهٔ ابرویِ تو در عِیْنِ نماز است',NULL,NULL);
INSERT INTO "verses" VALUES(1937989,2169,5,0,'بارِ دِلِ مَجْنون و خَمِ طُرِّهٔ لیلی','هوش مصنوعی: دل رنجور و غم‌زده مجنون به عشق لیلی است و زیبایی چهره محمود و نازکی کف پای ایاز به زیبایی و جذابیت او اشاره دارد.',NULL);
INSERT INTO "verses" VALUES(1937990,2169,6,1,'تا دیدهٔ من بر رُخِ زیبایِ تو، باز است',NULL,NULL);
INSERT INTO "verses" VALUES(1937991,2169,4,0,'شَرْحِ شِکَنِ زُلْفِ خَم اندر خَمِ جانان','هوش مصنوعی: توضیح درباره‌ی زلف‌های پیچیده و زیبای محبوبم را نمی‌توان به آسانی انجام داد، زیرا این داستان بسیار طولانی و پیچیده است.',NULL);
INSERT INTO "verses" VALUES(1937992,2169,5,1,'رُخسارهٔ مَحمود و کَفِ پایِ اَیاز است',NULL,NULL);
INSERT INTO "verses" VALUES(1937993,2169,3,0,'رازی که بَرِ غیر نگفتیم و نگوییم','هوش مصنوعی: رازهایی که نتوانستیم به دیگران بگوییم و نمی‌گوییم، باید با دوستی شریک شویم که او مایه‌ی اعتماد و امانت است.',NULL);
INSERT INTO "verses" VALUES(1937994,2169,4,1,'کوتَه نَتَوان کرد که این قِصِّه، دراز است',NULL,NULL);
INSERT INTO "verses" VALUES(1937995,2169,2,0,'از وی، همه، مَسْتی و غُرور است و تَکَبُّر','هوش مصنوعی: او همه چیزش سرشار از مستی و خودبزرگ بینی است، در حالی که ما جز ضعف، ناتوانی و نیاز چیزی نداریم.',NULL);
INSERT INTO "verses" VALUES(1937996,2169,3,1,'با دوست بگوییم که او مَحْرَمِ راز است',NULL,NULL);
INSERT INTO "verses" VALUES(1937997,2169,1,0,'خُم‌ها، همه در جوش و خُروش‌اند ز مَسْتی','هوش مصنوعی: تمام خُم‌ها در حال تلاطم و جنب و جوش هستند، زیرا درون آن‌ها شرابی است که سرمستی به ارمغان می‌آورد و این حالتی که در آن قرار داریم، واقعیت است و نه خیال و توهم.',NULL);
INSERT INTO "verses" VALUES(1937998,2169,2,1,'وز ما همه بیچارگی و عَجْز و نیاز است',NULL,NULL);
INSERT INTO "verses" VALUES(1937999,2169,0,0,'اَلْمِنَّةُ لِلَّه که درِ میکده، باز است','هوش مصنوعی: نعمت خداوند این است که درِ میکده به روی من باز است، زیرا من با دل و جان به سوی او نیاز دارم.',NULL);
INSERT INTO "verses" VALUES(1938000,2169,1,1,'وان می که در آن‌جاست، حقیقت، نه مَجاز است',NULL,NULL);
INSERT INTO "verses" VALUES(1938001,2169,0,1,'زان رو که مرا بر در او، رویِ نیاز است',NULL,NULL);
INSERT INTO "verses" VALUES(1938002,2170,5,1,'که ریزه‌اش سر کَسری و تاجِ پرویز است',NULL,NULL);
INSERT INTO "verses" VALUES(1938003,2170,6,0,'عراق و فارس گرفتی به شعرِ خوش حافظ','هوش مصنوعی: عراق و فارس را با شعر زیبا و دلنشین حافظ به دست آوردی، حالا زمان آن رسیده که به بغداد بیایی و تبریز را نیز ببینی.',NULL);
INSERT INTO "verses" VALUES(1938004,2170,6,1,'بیا که نوبتِ بغداد و وقتِ تبریز است',NULL,NULL);
INSERT INTO "verses" VALUES(1938005,2171,0,0,'حالِ دل با تو گفتنم، هوس است','هوش مصنوعی: دلم می‌خواهد با تو از حال و احوالم بگویم، اما تمایل دارم که از احوالات قلبم هم باخبر شوی، که این نیز خواسته‌ای است.',NULL);
INSERT INTO "verses" VALUES(1938006,2173,1,1,'چه وَقْتِ مدرسه و بَحْثِ کَشْفِ کَشّاف است؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938007,2173,0,0,'کُنون که بر کفِ گُل، جامِ بادهٔ صاف است','هوش مصنوعی: اکنون که لیوانی پر از شراب صاف بر گل قرار دارد، بلبل به هزار زبان درباره زیبایی‌های آن صحبت می‌کند.',NULL);
INSERT INTO "verses" VALUES(1938008,2173,0,1,'به صد هزار زبان، بلبلش در اوصاف است',NULL,NULL);
INSERT INTO "verses" VALUES(1938009,2172,6,0,'حافظا! تَرکِ جهان گفتن طریقِ خوشدلیست','هوش مصنوعی: حافظ! اگر بخواهی خوشدل باشند، بهتر است از دنیا و دلمشغولی‌های آن دل ببری، تا این‌که فکر کنی وضع دنیاپرستان خوب است.',NULL);
INSERT INTO "verses" VALUES(1938010,2172,6,1,'تا نپنداری که احوالِ جهان‌داران خوش است',NULL,NULL);
INSERT INTO "verses" VALUES(1938011,2172,5,0,'از زبانِ سوسنِ آزاده‌ام آمد به گوش','هوش مصنوعی: از زبان گل سوسن آزاد، این پیام به گوش می‌رسد که در این مکان باستانی، زندگی ساده و بی‌دغدغه بسیار دلپذیر است.',NULL);
INSERT INTO "verses" VALUES(1938012,2172,5,1,'کاندر این دِیرِ کهن، کارِ سبکباران خوش است',NULL,NULL);
INSERT INTO "verses" VALUES(1938013,2172,4,0,'نیست در بازارِ عالَم خوشدلی ور زان که هست','هوش مصنوعی: در دنیای واقعی، خوش‌دل بودن به راحتی پیدا نمی‌شود. اما اگر هم این حالت وجود داشته باشد، باید با شیوه‌های خاص و رفتارهای زیرکانه و مکارانه در کنار آن زندگی کرد.',NULL);
INSERT INTO "verses" VALUES(1938014,2172,4,1,'شیوهٔ رندی و خوش‌باشیِ عیاران خوش است',NULL,NULL);
INSERT INTO "verses" VALUES(1938015,2172,3,0,'مرغِ خوشخوان را بشارت باد کاندر راهِ عشق','هوش مصنوعی: مرغی که زیبا می‌خواند، خوش خبر باشد زیرا در مسیر عشق به محبوب، ناله‌های شب‌های بدون خواب، لذتبخش است.',NULL);
INSERT INTO "verses" VALUES(1938016,2172,3,1,'دوست را با نالهٔ شب‌های بیداران خوش است',NULL,NULL);
INSERT INTO "verses" VALUES(1938017,2172,2,0,'ناگشوده گُل نِقاب، آهنگِ رحلت ساز کرد','هوش مصنوعی: راز گلی که هنوز باز نشده است، به آهنگ وداع فرا می‌خواند. ای بلبل، ناله کن که صدای دل‌انگیز افکار عالی و زیباست.',NULL);
INSERT INTO "verses" VALUES(1938018,2172,2,1,'ناله‌ کن بلبل که گلبانگِ دل‌اَفکاران خوش است',NULL,NULL);
INSERT INTO "verses" VALUES(1938019,2172,1,0,'از صبا هر دم مشامِ جانِ ما خوش می‌شود','هوش مصنوعی: نسیم صبحگاهی هر لحظه جان ما را خوشبو می‌کند، آری، نفس‌های دل‌باختگان خوشایند و دل‌انگیز است.',NULL);
INSERT INTO "verses" VALUES(1938020,2173,2,1,'که مِی، حَرام ولی بِهْ ز مالِ اوقاف است',NULL,NULL);
INSERT INTO "verses" VALUES(1938021,2172,1,1,'آری آری طیبِ اَنفاسِ هواداران خوش است',NULL,NULL);
INSERT INTO "verses" VALUES(1938022,2172,0,0,'صَحنِ بُستان ذوق‌بخش و صحبتِ یاران خوش است','هوش مصنوعی: محیط باغ خوشایند و گفتگو با دوستان دل‌نشین است. زمان گل خوش می‌گذرد، زیرا در این زمان، لحظات توام با نوشیدن شراب نیز لذتبخش است.',NULL);
INSERT INTO "verses" VALUES(1938023,2171,6,1,'شعرِ رندانه گفتنم، هوس است',NULL,NULL);
INSERT INTO "verses" VALUES(1938024,2171,5,1,'خاکِ راهِ تو رفتنم، هوس است',NULL,NULL);
INSERT INTO "verses" VALUES(1938025,2171,6,0,'همچو حافظ به رَغمِ مُدَعیان','هوش مصنوعی: مانند حافظ، با وجود تمام دشمنان و مدعیانی که از شعر من انتقاد می‌کنند، هنوز هم به سرودن شعر رندانه تمایل دارم.',NULL);
INSERT INTO "verses" VALUES(1938026,2171,4,1,'که سحرگه شکفتنم، هوس است',NULL,NULL);
INSERT INTO "verses" VALUES(1938027,2171,5,0,'از برای شَرَف به نوُکِ مژه','برای احترام و ارزشمندی به تو، حتی اگر فقط با نوک مژه‌ام خاک راهت را جارو کنم ، به دنبال آن می‌روم. این احساس، هوس و آرزوست.',NULL);
INSERT INTO "verses" VALUES(1938028,2171,3,1,'در شبِ تار سُفتنم، هوس است',NULL,NULL);
INSERT INTO "verses" VALUES(1938029,2171,4,0,'ای صبا امشبَم مَدَد فرمای','هوش مصنوعی: ای باد صبا، امشب به من کمک کن تا صبحگاهان شکوفا شوم، زیرا در دل من هوس و آرزو وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1938030,2171,2,1,'با تو تا روز خُفتنم، هوس است',NULL,NULL);
INSERT INTO "verses" VALUES(1938031,2171,3,0,'وه که دُردانه‌ای چنین نازک','هوش مصنوعی: ای کاش این گل نازک و دلربا را در شب تار نگه دارم، اما این تنها یک آرزوست.',NULL);
INSERT INTO "verses" VALUES(1938032,2171,1,1,'از رقیبان نَهُفتَنَم، هوس است',NULL,NULL);
INSERT INTO "verses" VALUES(1938033,2171,2,0,'شبِ قدری چنین عزیزِ شریف','در شب قدری این چنین عزیز و محترم هوس دارم تا روزهنگام در کنار تو بخوابم',NULL);
INSERT INTO "verses" VALUES(1938034,2171,0,1,'خبرِ دل شِنُفتَنَم، هوس است',NULL,NULL);
INSERT INTO "verses" VALUES(1938035,2171,1,0,'طَمَعِ خام بین که قِصهٔ فاش','هوش مصنوعی: به طمع خام خود نگاه کن که نمی‌توانم داستان آشکار از رقیبان را پنهان کنم، این فقط یک اشتیاق است.',NULL);
INSERT INTO "verses" VALUES(1938036,2172,0,1,'وقتِ گل خوش باد کز وی وقتِ می‌خواران خوش است',NULL,NULL);
INSERT INTO "verses" VALUES(1938038,2257,5,0,'عِلم و فَضلی که به چِل سال دلَم جمع آورد','دانش و بزرگی که در چهل سال بدین آورده ام را می‌ترسم که آن چشمان مست ببرد و غارت کند.',NULL);
INSERT INTO "verses" VALUES(1938039,2257,6,0,'بانگِ گاوی، چه صدا باز دَهَد؟ عِشوه مَخَر','بانگ گاو چه صدایی دارد؟ فریب مخور! سامری نیرنگ‌باز کیست که بر ید بیضا پیروز شود؟ (اشاره است به داستان گوساله‌ای که سامری از زر (سمبل پول) ساخت و صدایی از او بر‌می‌خواست (سمبل جادو و نیرنگ) و به بنی‌اسراییل گفت «خدای شما و موسی این است» در حالیکه دروغ می‌گفت و آن خدای موسی نبود.)',NULL);
INSERT INTO "verses" VALUES(1938040,2343,6,0,'بر طَرْفِ گلشنم گذر افتاد وقتِ صبح','هوش مصنوعی: در صبحگاه که زمان آواز خواندن و ناله کردن مرغ سحر است، به باغ گل دلم گذر کردم.',NULL);
INSERT INTO "verses" VALUES(1938041,2343,5,1,'در رهگذارِ باد نگهبانِ لاله بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938042,2343,5,0,'هر کو نکاشت مِهر و ز خوبی گُلی نچید','هوش مصنوعی: هرکس که عشق و محبت را در دل نکارد و از زیبایی‌ها بهره‌ای نبرد، در مسیر زندگی تنها نظاره‌گر fragility یا آسیب‌پذیری گل‌ها خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1938043,2343,4,1,'روزیِّ ما ز خوانِ قَدَر این نَواله بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938044,2343,4,0,'بر آستانِ میکده خون می‌خورم مدام','هوش مصنوعی: در جلوی درِ میکده دائماً در حال نوشیدن خون هستم، چرا که روزی ما از سفره‌ی قَدَر این لقمه است.',NULL);
INSERT INTO "verses" VALUES(1938045,2343,3,1,'دولت مساعد آمد و مِی در پیاله بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938046,2343,3,0,'از دست برده بود خمارِ غمم سحر','از غمگساری تا سحر به خماری افتاده بودم که شرایط که شرایط به کام من شد و پیاله‌ام پر می بود',NULL);
INSERT INTO "verses" VALUES(1938047,2343,2,1,'در چینِ زلفِ آن بتِ مشکین کُلاله بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938048,2343,2,0,'آن نافهٔ مراد که می‌خواستم ز بخت','ان مقصود خوشبو که از سرنوشت می‌خواستم، در پیچ و خم همان گیسوی مجعد مشکی معشوق بود',NULL);
INSERT INTO "verses" VALUES(1938049,2343,1,1,'تدبیرِ ما به دستِ شرابِ دوساله بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938050,2343,1,0,'چل سال رنج و غصّه کشیدیم و عاقبت','ما چهل سال زحمت و غم متحمل شدیم، و در نهایت، چاره‌ ما در یک شیشه شراب دوساله است.',NULL);
INSERT INTO "verses" VALUES(1938051,2343,0,1,'تعبیر رفت و کار به دولت حواله بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938052,2343,0,0,'دیدم به خوابِ خوش که به دستم پیاله بود','در خواب خوشی دیدم که پیاله‌ای در دستم بود، آن خواب تعبیر شد و در آن سرنوشت من به قضا و قدر سپرده شد.',NULL);
INSERT INTO "verses" VALUES(1938053,2342,7,1,'که بر این چشمه همان آبِ روان است که بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938054,2342,7,0,'حافظا بازنما قصه خونابهٔ چشم','هوش مصنوعی: ای حافظ، دوباره بگو داستان اشک‌هایی را که از چشمانم می‌ریزد، چرا که این چشمه همان آبی است که همیشه جاری بوده است.',NULL);
INSERT INTO "verses" VALUES(1938055,2342,6,1,'سال‌ها رفت و بدان سیرت و سان است که بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938056,2342,6,0,'زلفِ هندویِ تو گفتم که دگر رَه نزند','هوش مصنوعی: زلف‌های زیبای تو را گفتم که دیگر نمی‌توانم به آن فکر کنم. سال‌ها گذشته و آن‌چه در تو بود همچنان باقی مانده است.',NULL);
INSERT INTO "verses" VALUES(1938057,2342,5,1,'همچنان در لبِ لعلِ تو عیان است که بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938058,2342,5,0,'رنگِ خونِ دلِ ما را که نهان می‌داری','هوش مصنوعی: رنگ غم و اندوه ما را که پنهان می‌کنی، اما در لب‌های سرخ تو به وضوح دیده می‌شود که این احساس وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1938059,2342,4,1,'زانکه بیچاره همان دل‌نگران است که بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938060,2342,4,0,'کشتهٔ غمزهٔ خود را به زیارت دریاب','هوش مصنوعی: کسی که بر اثر زیبایی معشوقه‌اش به شدت دچار درد و رنج شده است، حالا به دیدن او بیاید. زیرا این دل نگران و پریشان، همان دل‌مشغولی است که همیشه بوده است.',NULL);
INSERT INTO "verses" VALUES(1938061,2342,3,1,'هم‌چُنان در عملِ معدن و کان است که بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938062,2342,3,0,'طالب لعل و گهر نیست وگرنه خورشید','هوش مصنوعی: در جستجوی جواهرات و سنگ‌های قیمتی نیستم، زیرا خورشید هنوز هم همانند گذشته به کار در معدن و استخراج معادن ادامه می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1938063,2342,2,1,'بویِ زلفِ تو همان مونسِ جان است که بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938064,2342,2,0,'از صبا پرس که ما را همه شب تا دمِ صبح','هوش مصنوعی: از نسیم صبح بخواه که به من بگوید، در تمام شب تا سپیده دم، رایحه موهای تو تنها همدم جانم بوده است که همیشه کنارم بوده.',NULL);
INSERT INTO "verses" VALUES(1938065,2342,1,1,'لاجرم چشمِ گهربار همان است که بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938066,2342,1,0,'عاشقان زُمرهٔ اربابِ امانت باشند','هوش مصنوعی: عاشقان افرادی هستند که به عهد و امانت وفادارند و بنابراین، چشم‌های پر از محبت و شفاف آن‌ها باید همان باشد که هست.',NULL);
INSERT INTO "verses" VALUES(1938067,2342,0,1,'حُقِّهٔ مِهر بدان مُهر و نشان است که بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938068,2342,0,0,'گوهرِ مخزنِ اسرار همان است که بود','هوش مصنوعی: گوهر نهفته در رازها همان چیزی است که در ظرف عشق و محبت با نشانه و علامت خاصی وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1938069,2343,6,1,'آن دَم که کارِ مرغِ سحر آه و ناله بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938070,2341,7,1,'طایرِ فکرش به دامِ اشتیاق افتاده بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938071,2343,7,0,'دیدیم شعرِ دلکش حافظ به مدحِ شاه','هوش مصنوعی: شعر زیبا و دلنشین حافظ در ستایش شاه، از یک بیت این قصیده ارزشمندتر از صد متن علمی و رسمی است.',NULL);
INSERT INTO "verses" VALUES(1938072,2343,8,0,'آن شاهِ تندحمله که خورشیدِ شیرگیر','هوش مصنوعی: آن پادشاه شجاع و تندخو که در میدان جنگ، نور خورشید که گویی مظهر زیبایی است، در برابرش به اندازه یک غزال کوچک و کم‌اهمیت می‌نماید.',NULL);
INSERT INTO "verses" VALUES(1938073,2345,5,1,'در مملکتِ حُسن سَرِ تاجْوَری بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938074,2345,5,0,'عُذری بِنِه ای دل، که تو درویشی و او را','هوش مصنوعی: ای دل، بهانه‌ای بساز که تو در حالتی ساده و بی‌خود هستی و او در دنیای زیبایی مثل تاجی در مقام و منزلت است.',NULL);
INSERT INTO "verses" VALUES(1938075,2345,4,1,'آری چه کنم؟ دولتِ دورِ قمری بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938076,2345,4,0,'از چنگِ مَنَش اختر بَدمِهر به در برد','هوش مصنوعی: ستاره‌ی بدشگون در زندگی‌ام از چنگ من فرار کرد، حالا چه کنم؟ این یک دوری و جدایی شبیه به سرنوشت یک ماهِ کامل است.',NULL);
INSERT INTO "verses" VALUES(1938077,2345,3,1,'با حُسنِ ادب شیوهٔ صاحب‌نظری بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938078,2345,3,0,'منظورِ خردمندِ من آن ماه که او را','هوش مصنوعی: منظور من از آن ماه، شخصی است که به زیبایی و ادب شناخته شده و دارای دیدگاه‌هایی عمیق و خردمندانه است.',NULL);
INSERT INTO "verses" VALUES(1938079,2345,2,1,'تا بود فلک، شیوهٔ او پرده‌دری بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938080,2345,2,0,'تنها نه ز رازِ دلِ من پرده برافتاد','هوش مصنوعی: تنها پرده از راز دل من کنار نرفت، بلکه تا وقتی آسمان باشد، شیوه او همیشه این است که پرده‌ها را کنار می‌زند.',NULL);
INSERT INTO "verses" VALUES(1938081,2345,1,1,'بیچاره ندانست که یارش سفری بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938082,2345,1,0,'دل گفت فروکش کنم این شهر به بویش','دل گفت که باید به خاطر وجود معشوق، در این شهر بمانم و جایی نروم، اما بیچاره متوجه نبود که عشقش در سفر است. (فروکش کنم یعنی بمانم. به بویش یعنی به آرزویش)',NULL);
INSERT INTO "verses" VALUES(1938083,2345,0,1,'سر تا قدمش چون پَری از عیب بَری بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938084,2345,0,0,'آن یار کز او خانهٔ ما جایِ پَری بود','هوش مصنوعی: آن معشوق که خانه‌مان به خاطر او پر از جمال و زیبایی بود، از سر تا پایش هیچ عیبی وجود نداشت و همچون پریان بی‌نقص بود.',NULL);
INSERT INTO "verses" VALUES(1938085,2344,7,1,'فغان که وقتِ مُرُوَّت چه تنگ حوصله بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938086,2344,7,0,'دهانِ یار که درمانِ دردِ حافظ داشت','هوش مصنوعی: دهان معشوق که می‌توانست به دردهای حافظ پاسخ دهد، آه و افسوس که زمان کوتاهی برای لطف و مهربانی وجود داشت.',NULL);
INSERT INTO "verses" VALUES(1938087,2344,6,1,'میان ماه و رخِ یارِ من مُقابله بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938088,2344,6,0,'ز اخترم نظری سعد در رَه است که دوش','هوش مصنوعی: درخشش ستاره‌ای خوش‌یمن بر سر راه من وجود دارد، زیرا دیشب میان چهره‌ی زیبا و ماه درخشان، دیداری اتفاق افتاد.',NULL);
INSERT INTO "verses" VALUES(1938089,2344,5,1,'به خنده گفت کِی‌ات با من این معامله بود؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938090,2344,5,0,'بگفتمش به لبم بوسه‌ای حوالت کن','هوش مصنوعی: به او گفتم که یک بوسه به من بده، اما او با خنده جواب داد: از کی این معامله بین ما بوده است؟',NULL);
INSERT INTO "verses" VALUES(1938091,2344,4,1,'هزار ساحر چون سامریش در گَله بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938092,2344,4,0,'قیاس کردم و آن چشمِ جادوانهٔ مست','هوش مصنوعی: چشمان جذاب و فریبنده‌اش را با هزار جادوگر مقایسه کردم، که مانند سامری در میان گله‌ای از جادوها قرار داشت.',NULL);
INSERT INTO "verses" VALUES(1938093,2344,3,1,'ز نامساعدیِ بختش اندکی گِلِه بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938094,2344,3,0,'دل از کرشمهٔ ساقی به شُکر بود ولی','هوش مصنوعی: دل به لطف و محبت ساقی خوش بود، اما به خاطر بدشانسی کمی ناراحت بود.',NULL);
INSERT INTO "verses" VALUES(1938095,2344,2,1,'وَرایِ مدرسه و قال و قیلِ مسأله بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938096,2344,2,0,'مباحثی که در آن مجلسِ جنون می‌رفت','هوش مصنوعی: در آن جلسه که به جنون می‌کشید، صحبت‌هایی مطرح می‌شد که فراتر از مباحث علمی و جدل‌های معمول بود.',NULL);
INSERT INTO "verses" VALUES(1938097,2344,1,1,'به نالهٔ دف و نی در خروش و ولوله بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938098,2344,1,0,'حدیثِ عشق که از حرف و صوت مُستَغنیست','هوش مصنوعی: داستان عشق نیازی به کلمات و صداها ندارد، بلکه با ناله و صدای دف و نی به خوبی بیان می‌شود و درونش شور و ولوله‌ای عمیق نهفته است.',NULL);
INSERT INTO "verses" VALUES(1938099,2344,0,1,'که جوشِ شاهد و ساقی و شمع و مشعله بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938100,2344,0,0,'به کویِ میکده یا رب سحر چه مشغله بود؟','هوش مصنوعی: در محلی که میخانه است، ای خدا، چه کار و مشغله‌ای وجود دارد؟ که در آنجا فقط حال و هوای عشق، شراب، باده‌فروشی و نور شمع‌ها به پا است.',NULL);
INSERT INTO "verses" VALUES(1938101,2343,8,1,'پیشش به روزِ معرکه کمتر غزاله بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938102,2343,7,1,'یک بیت از این قصیده به از صد رساله بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938103,2341,7,0,'حافظ آن ساعت که این نظمِ پریشان می‌نوشت','هوش مصنوعی: حافظ در زمانی که این اشعار آشفته را می‌نوشت، پرنده‌ی اندیشه‌اش در تله‌ی عشق گرفتار شده بود.',NULL);
INSERT INTO "verses" VALUES(1938104,2341,6,1,'کار مُلک و دین ز نظم و اِتِّساق افتاده بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938105,2341,6,0,'گر نکردی نصرتِ دین، شاه یحیی، از کَرَم','هوش مصنوعی: اگر به یاری دین نپرداختی، شاه یحیی، به خاطر لطف تو کار پادشاهی و دین از نظم و هماهنگی خارج شده بود.',NULL);
INSERT INTO "verses" VALUES(1938106,2339,3,0,'عالَم از شور و شرِ عشق خبر هیچ نداشت','هوش مصنوعی: جهان هیچ اطلاعی از هیجان و آشفتگی عشق نداشت، و این تحریک‌کننده و دلسوزی تو بود که با نگاهی افسونگر، همه چیز را تحت تأثیر قرار داد.',NULL);
INSERT INTO "verses" VALUES(1938107,2339,3,1,'فتنه‌انگیزِ جهان غمزهٔ جادویِ تو بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938108,2339,2,0,'هم عَفَاالله صبا کز تو پیامی می‌داد','هوش مصنوعی: باد صبا از طرف تو پیامی آورد، اما اگر او نبود، هیچ‌کس نبود که از خیابان تو خبری به ما بدهد.',NULL);
INSERT INTO "verses" VALUES(1938109,2339,2,1,'ور نه در کس نرسیدیم که از کویِ تو بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938110,2339,1,0,'دل که از ناوَکِ مژگانِ تو در خون می‌گشت','هوش مصنوعی: دل که از زیبایی و رفتار تو غمگین و دلتنگ بود، دوباره عاشق و مشتاقِ زیبایی و جاذبهٔ ابروی تو شد.',NULL);
INSERT INTO "verses" VALUES(1938111,2339,1,1,'باز مشتاقِ کمان‌خانهٔ ابرویِ تو بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938112,2339,0,0,'دوش در حلقهٔ ما قصّهٔ گیسویِ تو بود','هوش مصنوعی: شب گذشته در جمع دوستان، دربارهٔ زیبایی موهای تو صحبت می‌کردیم و تا دیروقت در مورد جذابیت و ریزه‌کاری‌های آن گفتمان داشتیم.',NULL);
INSERT INTO "verses" VALUES(1938113,2339,0,1,'تا دلِ شب سخن از سلسلهٔ مویِ تو بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938114,2338,7,0,'آیتی بود عذابْ اَنْدُهِ حافظ بی تو','معنی بیت بر اساس نسخی که این گونه ضبط کرده اند آیتی بُد ز عذاب اندوه حافظ ... چنین می شود: اندوه حافظ در دوری تو چنان شدید بود که نشانه ای از عذاب الهی است و چنان آشکار که نزد هیچکس نیاز به شرح و تفسیر ندارد',NULL);
INSERT INTO "verses" VALUES(1938115,2338,7,1,'که بَرِ هیچ کَسَش حاجتِ تفسیر نبود',NULL,NULL);
INSERT INTO "verses" VALUES(1938116,2338,6,0,'آن کشیدم ز تو ای آتشِ هجران که چو شمع','هوش مصنوعی: من از دوری تو آنقدر رنج کشیدم که مانند شمع، تنها توانایی من برای درخشش، از بین رفتن خودم است و نمی‌توانم از تو هیچ راه حلی جستجو کنم.',NULL);
INSERT INTO "verses" VALUES(1938117,2338,6,1,'جز فنای خودم از دستِ تو تدبیر نبود',NULL,NULL);
INSERT INTO "verses" VALUES(1938118,2338,5,0,'تا مگر همچو صبا باز به کویِ تو رَسَم','هوش مصنوعی: من همچنان در تلاش هستم تا به کوی تو برسم، اما شب گذشته تنها چیزی که نصیبم شد ناله‌ای در دل شب بود.',NULL);
INSERT INTO "verses" VALUES(1938119,2338,5,1,'حاصلم دوش به جز نالهٔ شبگیر نبود',NULL,NULL);
INSERT INTO "verses" VALUES(1938120,2338,4,0,'نازنین‌تر ز قَدَت در چمنِ ناز نَرُست','هوش مصنوعی: هیچ موجودی در چمنزار به زیبایی قامت تو وجود ندارد و هیچ تصویری در عالم به زیبایی نقش تو نیست.',NULL);
INSERT INTO "verses" VALUES(1938121,2338,4,1,'خوش‌تر از نقشِ تو در عالمِ تصویر نبود',NULL,NULL);
INSERT INTO "verses" VALUES(1938122,2338,3,0,'سر ز حسرت به درِ میکده‌ها بَرکردم','هوش مصنوعی: از روی حسرت به درِ میکده‌ها نگاه کردم، زیرا در آنجا کسی نبود که تو را بشناسد و در صومعه هم از نظر من یک پیرسالار وجود نداشت.',NULL);
INSERT INTO "verses" VALUES(1938123,2338,3,1,'چون شناسایِ تو در صومعه یک پیر نبود',NULL,NULL);
INSERT INTO "verses" VALUES(1938124,2338,2,0,'یا رب این آینهٔ حُسن چه جوهر دارد؟','هوش مصنوعی: ای خدای من، این آئینه‌ی زیبایی چه گوهری در خود دارد که حتی آه من در آن تأثیری ندارد؟',NULL);
INSERT INTO "verses" VALUES(1938125,2338,2,1,'که در او آهِ مرا قُوَّتِ تأثیر نبود',NULL,NULL);
INSERT INTO "verses" VALUES(1938126,2338,1,0,'منِ دیوانه چو زلفِ تو رها می‌کردم','هوش مصنوعی: من دیوانه، وقتی زلف تو را رها می‌کردم، هیچ چیزی لایق‌تر از زنجیر برای من نبود.',NULL);
INSERT INTO "verses" VALUES(1938127,2338,1,1,'هیچ لایق‌ترم از حلقهٔ زنجیر نبود',NULL,NULL);
INSERT INTO "verses" VALUES(1938128,2338,0,0,'قتلِ این خسته به شمشیرِ تو تقدیر نبود','هوش مصنوعی: کشتن این فرد خسته به خاطر تو سرنوشت نبوده است، وگرنه از دل بی‌رحم تو کمترین قصوری وجود نداشته است.',NULL);
INSERT INTO "verses" VALUES(1938129,2338,0,1,'ور نه هیچ از دلِ بی‌رحمِ تو تقصیر نبود',NULL,NULL);
INSERT INTO "verses" VALUES(1938130,2337,6,0,'حافظا علم و ادب ورز که در مجلسِ شاه','هوش مصنوعی: ای حافظ، علم و ادب را فراگیر، زیرا در محفل شاه، کسی که شایستگی گفت و گو را ندارد، مورد توجه قرار نمی‌گیرد.',NULL);
INSERT INTO "verses" VALUES(1938131,2337,6,1,'هر که را نیست ادب لایقِ صحبت نبود',NULL,NULL);
INSERT INTO "verses" VALUES(1938132,2337,5,0,'چون طهارت نَبُوَد کعبه و بتخانه یکیست','هوش مصنوعی: اگر پاکی و پاکیزگی نباشد، خانه‌ی کعبه و خانه‌ی بت‌ها هیچ فرقی ندارند. اگر در آن خانه، معصومیت و پاکی وجود نداشته باشد، هیچ خیر و نیکویی هم در آن نیست.',NULL);
INSERT INTO "verses" VALUES(1938133,2337,5,1,'نَبُوَد خیر در آن خانه که عصمت نبود',NULL,NULL);
INSERT INTO "verses" VALUES(1938134,2337,4,0,'گر مدد خواستم از پیرِ مُغان عیب مکن','هوش مصنوعی: اگر از حکیمان و بزرگ‌ترها یاری خواستم، ایرادی نگیر؛ زیرا شیخ ما گفته که در زهد و عبادت، اراده و تلاش کافی نیست.',NULL);
INSERT INTO "verses" VALUES(1938135,2339,4,0,'منِ سرگشته هم از اهلِ سلامت بودم','هوش مصنوعی: من که در گرداب گم‌شدگی به سر می‌برم، از جنس افرادی بودم که در مسیر زندگی سالم و درست حرکت می‌کردند. اما اکنون، گرفتار دام زیبایی‌های تو شدم که مرا به انحراف کشانده است.',NULL);
INSERT INTO "verses" VALUES(1938136,2339,4,1,'دامِ راهم شِکَنِ طُرِّهٔ هندویِ تو بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938137,2339,5,0,'بگشا بندِ قبا تا بگشاید دلِ من','هوش مصنوعی: لباس خود را کمی باز کن تا دل من نیز باز شود، زیرا که دل من به خاطر تو و در کنار تو به آغوش آمده است.',NULL);
INSERT INTO "verses" VALUES(1938138,2339,5,1,'که گشادی که مرا بود ز پهلویِ تو بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938139,2341,5,1,'طاقت و صبر از خَمِ ابروش طاق افتاده بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938140,2341,5,0,'نقش می‌بستم که گیرم گوشه‌ای زان چشمِ مست','هوش مصنوعی: من نقشی از عشق و شوق می‌کشیدم تا شاید گوشه‌ای از آن چشم مست را ببینم، اما طاقت و صبرم از کمان ابرویش به تنگی افتاد و شکست.',NULL);
INSERT INTO "verses" VALUES(1938141,2341,4,1,'در شکرخوابِ صبوحی هم وثاق افتاده بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938142,2341,4,0,'ای مُعَبِّر مژده‌ای فرما که دوشم آفتاب','هوش مصنوعی: ای تعبیرگر، خبر خوشی بده که دیشب در خواب شیرین صبحگاهی، آفتاب نیز به هم آمیزش و همراهی آمده بود.',NULL);
INSERT INTO "verses" VALUES(1938143,2341,3,1,'هر که عاشق‌وَش نیامد در نفاق افتاده بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938144,2341,3,0,'ساقیا جامِ دَمادَم ده که در سِیرِ طریق','هوش مصنوعی: ای ساقی، هر لحظه برایم جامی بیاور که در مسیر عشق، هر کسی که به عشق واقعی نرسیده باشد، در آزمون و دوگانگی قرار گرفته است.',NULL);
INSERT INTO "verses" VALUES(1938145,2341,2,1,'عافیت را با نظربازی فِراق افتاده بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938146,2341,2,0,'در مقاماتِ طریقت هر کجا کردیم سِیر','هوش مصنوعی: در مراحل سیر و سلوک، هر جا که راه عافیت را پیمودیم، جدایی و دوری او به چشم می‌خورد.',NULL);
INSERT INTO "verses" VALUES(1938147,2341,1,1,'رجعتی می‌خواستم لیکن طلاق افتاده بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938148,2341,1,0,'از سرِ مستی دگر با شاهدِ عهدِ شباب','هوش مصنوعی: در حالتی از شادی و شادابی، آرزو داشتم دوباره به جوانی و عشق گذشته‌ام برگردم، اما متوجه شدم که این امکان دیگر وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1938149,2341,0,1,'وز لبِ ساقی شرابم در مَذاق افتاده بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938150,2341,0,0,'یک دو جامم دی سحرگه اتفاق افتاده بود','هوش مصنوعی: در یکی از صبح‌های زود، دو جام نوشیدنی در هنگام صبحانه فراهم شده بود و طعم شراب آن با لب‌های ساقی روی زبانم حس شده بود.',NULL);
INSERT INTO "verses" VALUES(1938151,2340,7,1,'یا رب این قلب‌شناسی ز که آموخته بود؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938152,2340,7,0,'گفت و خوش گفت برو خرقه بسوزان حافظ','چه زیبا گفت که برو و این خرقه (نوعی ردا و همزمان درجه‌ی معنوی مانند مقامات حوزوی امروزی فرضا) را بسوزان. خداوندا این شناخت تقلبی و اصلی را از کجا آموخته بود؟',NULL);
INSERT INTO "verses" VALUES(1938153,2345,6,0,'اوقاتِ خوش آن بود که با دوست به سر رفت','هوش مصنوعی: لحظات خوش، زمانی است که با دوست سپری شود؛ باقی زمان‌ها همه بی‌فایده و دور از آگاهی هستند.',NULL);
INSERT INTO "verses" VALUES(1938154,2340,6,1,'آن که یوسف به زَرِ ناسره بفروخته بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938155,2340,5,1,'الله الله، که تلف کرد و که اندوخته بود؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938156,2340,5,0,'دل بسی خون به کف آورد ولی دیده بریخت','چه بسیار که دلم خون شد و از دیده خون گریستم. خدا میداند که کدام یکی اتلاف شد و کدام اندوخته شد؟ (دل خون شدن توشه‌ی آخرت شد یا به بی‌حاصلی خودم را آزار دادم. و همچنین برای اشکی خونین ریختن. )',NULL);
INSERT INTO "verses" VALUES(1938157,2340,4,1,'در پِی‌اش مشعلی از چهره برافروخته بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938158,2340,4,0,'کفرِ زلفش رَهِ دین می‌زد و آن سنگین‌ دل','هوش مصنوعی: زلف‌های او باعث گمراهی و انحراف از راه حقیقت می‌شد و آن دل سنگین، در جستجوی او شعله‌ای از چهره‌ی درخشانش بر افروخته بود.',NULL);
INSERT INTO "verses" VALUES(1938159,2340,3,1,'که نهانش نظری با منِ دلسوخته بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938160,2340,3,0,'گر‌چه می‌گفت که زارَت بِکُشم می‌دیدم','هوش مصنوعی: اگرچه او می‌گفت که من را به دردسر می‌اندازد، اما می‌دیدم که در دلش نگاهی به منِ دلسوخته داشت.',NULL);
INSERT INTO "verses" VALUES(1938161,2340,2,1,'و آتشِ چهره بدین کار برافروخته بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938162,2340,2,0,'جانِ عُشّاق سپندِ رخِ خود می‌دانست','هوش مصنوعی: عاشقان، زندگی و روح خود را در زیبایی و جذابیت چهره محبوب می‌بینند و چهرهٔ زیبای او به شوق و هیجان آنها دامن می‌زند.',NULL);
INSERT INTO "verses" VALUES(1938163,2340,1,1,'جامه‌ای بود که بر قامتِ او دوخته بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938164,2340,1,0,'رسم عاشق‌کُشی و شیوهٔ شهرآشوبی','فتانه بود. انگار برای آشوبگری و عاشق کشی زاده شده بود.',NULL);
INSERT INTO "verses" VALUES(1938165,2340,0,1,'تا کجا باز دلِ غمزده‌ای سوخته بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938166,2340,0,0,'دوش می‌آمد و رخساره برافروخته بود','دیشب می‌آمد و چهره‌اش برافروخته بود. معلوم نبود کجا دل چه کسی را به آتش زده. (خوشحالی از سوزاندن دل کسی چهره اش را درخشان کرده. تشبیه شده به آتش واقعی)',NULL);
INSERT INTO "verses" VALUES(1938167,2339,6,0,'به وفایِ تو که بر تربتِ حافظ بگذر','هوش مصنوعی: به خاطر وفاداری تو که بر مزار حافظ می‌گذری، او از دنیای فانی می‌گذشت و تنها آرزو و آرزویش تو بودی.',NULL);
INSERT INTO "verses" VALUES(1938168,2339,6,1,'کز جهان می‌شد و در آرزویِ رویِ تو بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938169,2340,6,0,'یار مَفروش به دنیا که بسی سود نکرد','هوش مصنوعی: دوست خود را به دنیا نفروش، چرا که کسی که یوسف را به قیمت ناچیزی فروخت، به سودی نرسید.',NULL);
INSERT INTO "verses" VALUES(1938170,2345,6,1,'باقی همه بی‌حاصلی و بی‌خبری بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938171,2345,7,0,'خوش بود لبِ آب و گل و سبزه و نسرین','هوش مصنوعی: در کنار آب و گل و سبزه و گل نسرین اینجا زیبا و دل‌انگیز است، اما افسوس که این زیبایی فقط گذرایی و موقتی است.',NULL);
INSERT INTO "verses" VALUES(1938172,2345,7,1,'افسوس که آن گنجِ روان رهگذری بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938173,2351,3,1,'حیفِ اوقات که یک سر به بطالت برود',NULL,NULL);
INSERT INTO "verses" VALUES(1938174,2351,3,0,'کامِ خود آخرِ عمر از مِی و معشوق بگیر','هوش مصنوعی: در پایان عمر، از شراب و عشق لذت ببر و مواظب باش که زمانت بیهوده تلف نشود.',NULL);
INSERT INTO "verses" VALUES(1938175,2351,2,1,'که به جایی نرسد گر به ضَلالت برود',NULL,NULL);
INSERT INTO "verses" VALUES(1938176,2351,2,0,'سالک از نورِ هدایت بِبَرَد راه به دوست','هوش مصنوعی: رهرو با استفاده از نور هدایت، به سوی دوست می‌رود، زیرا اگر در مسیر گمراهی قدم بگذارد، به مقصد نخواهد رسید.',NULL);
INSERT INTO "verses" VALUES(1938177,2351,1,1,'به تَجَمُّل بنشیند، به جَلالت برود',NULL,NULL);
INSERT INTO "verses" VALUES(1938178,2351,1,0,'کاروانی که بُوَد بدرقه‌اش حفظِ خدا','هوش مصنوعی: کاروانی که خداوند از آن حفاظت کند، با آرامش و وقار حرکت خواهد کرد و به عظمت و شکوه خواهد رسید.',NULL);
INSERT INTO "verses" VALUES(1938179,2351,0,1,'نرود کارش و آخِر به خجالت برود',NULL,NULL);
INSERT INTO "verses" VALUES(1938180,2351,0,0,'از سرِ کویِ تو هر کو به ملالت برود','هوش مصنوعی: هر کس که از گذرگاه تو به دل‌خوری و ناراحتی برود، کارش به سامان نمی‌رسد و در نهایت به شرمندگی و ندامت دچار می‌شود.',NULL);
INSERT INTO "verses" VALUES(1938181,2350,7,1,'خوشا کسی که در این راه بی‌حجاب رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938182,2350,7,0,'حجابِ راه تویی حافظ از میان برخیز','هوش مصنوعی: ای حافظ، تو خود مانع راهی و باید از میان برداشته شوی. خوشا به حال کسی که بتواند بدون مانع و با آزادی در این مسیر گام بگذارد.',NULL);
INSERT INTO "verses" VALUES(1938183,2350,6,1,'کلاه داریَش اندر سرِ شراب رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938184,2350,6,0,'حباب را چو فِتَد بادِ نخوت اندر سر','هوش مصنوعی: وقتی که حباب به خاطر باد مغروری که به آن吹یده می‌شود می‌ترکد، نشان‌دهنده این است که شراب درون کلاه (یا ظرف) به سمت خارج سرازیر می‌شود.',NULL);
INSERT INTO "verses" VALUES(1938185,2350,5,1,'بَیاض کم نَشَوَد گر صد انتخاب رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938186,2350,5,0,'سوادِ نامهٔ مویِ سیاه چون طی شد','هوش مصنوعی: اگر نامه‌ای با موهای سیاه نوشته شود و متن آن به پایان برسد، هرگز در آن نقطه‌چینی که به رنگ سفید است، تغییری ایجاد نخواهد شد، حتی اگر انتخاب‌های زیادی هم مطرح شود.',NULL);
INSERT INTO "verses" VALUES(1938187,2350,4,1,'کسی ز سایهٔ این در به آفتاب رود؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938188,2350,4,0,'گدایی درِ جانان به سلطنت مفروش','هوش مصنوعی: کسی که به درگاه معشوق خود توسل جسته و خود را به مقام سلطنت نمی‌فروشد، آیا از سایه‌ی این در هم به زیر آفتاب نمی‌رود؟',NULL);
INSERT INTO "verses" VALUES(1938189,2350,3,1,'بیفتد آن که در این راه با شتاب رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938190,2350,3,0,'طریقِ عشق پرآشوب و فتنه است ای دل','هوش مصنوعی: راه عشق پر از آشفتگی و دردسر است، ای دل! بیفتد بر کسی که با شتاب و عجله در این مسیر گام می‌گذارد.',NULL);
INSERT INTO "verses" VALUES(1938191,2350,2,1,'وگر به روز شکایت کنم به خواب رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938192,2350,2,0,'شبِ شراب خرابم کُنَد به بیداری','هوش مصنوعی: شبْ شراب باعث مستی و گیجی من می‌شود و اگر در روز از این حالتی که دارم شکایت کنم، خواب به سراغم می‌آید و خواب‌آلود می‌شوم.',NULL);
INSERT INTO "verses" VALUES(1938193,2350,1,1,'زَنَد به گوشهٔ ابرو و در نقاب رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938194,2350,1,0,'چو ماهِ نو رَهِ بیچارگانِ نَظّاره','هوش مصنوعی: مانند ماه نو که به آرامی بر دل‌های بیچاره نگاهی می‌اندازد و در زیر پوششی پنهان می‌شود.',NULL);
INSERT INTO "verses" VALUES(1938195,2350,0,1,'ور آشتی طلبم با سرِ عِتاب رَوَد',NULL,NULL);
INSERT INTO "verses" VALUES(1938196,2350,0,0,'چو دست بر سرِ زلفش زنم به تاب رَوَد','هوش مصنوعی: وقتی که دستم را بر روی مویش می‌گذارم، او به آرامش می‌رود؛ و اگر بخواهم با قهر و تندی صحبت کنم، او نیز با همان لحن پاسخ می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1938197,2349,6,1,'چون صوفیانِ صومعه دار از صفا رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938198,2349,6,0,'حافظ به کوی میکده دایم به صدقِ دل','هوش مصنوعی: حافظ در اینجا می‌گوید که او با تمام صداقت و خلوص دلش، همانند صوفیان که با صفا و پاکی به عبادت و معنویت می‌پردازند، به میکده می‌رود و در آنجا حضور دارد.',NULL);
INSERT INTO "verses" VALUES(1938199,2349,5,1,'زان رهگذر که بر سرِ کویش چرا رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938200,2349,5,0,'ما را به آبِ دیده شب و روز ماجراست','هوش مصنوعی: ما به خاطر خاطرات تلخ و لحظات سخت هر روز و شب اشک می‌ریزیم، زیرا در این مسیر، کسی را می‌بینیم که به سراغ محبوبش می‌رود.',NULL);
INSERT INTO "verses" VALUES(1938201,2349,4,1,'گر خود دلش ز سنگ بُوَد هم ز جا رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938202,2351,4,0,'ای دلیلِ دلِ گم‌گشته! خدا را مددی','هوش مصنوعی: ای دلیل و رهنمای دلِ سرگشته، از خدا کمک می‌خواهم که اگر غریبی نتواند راه را پیدا کند، با هدایت تو به مقصد برسد.',NULL);
INSERT INTO "verses" VALUES(1938203,2351,4,1,'که غریب اَر نَبَرَد رَه، به دلالت برود',NULL,NULL);
INSERT INTO "verses" VALUES(1938204,2351,5,0,'حکمِ مستوری و مستی همه بر خاتِمَت است','هوش مصنوعی: سرنوشت انسان‌ها در نهایت به خودشان وابسته است و هیچ‌کس نمی‌داند که در پایان زندگی در چه حالتی خواهند بود.',NULL);
INSERT INTO "verses" VALUES(1938205,2351,5,1,'کس ندانست که آخِر به چه حالت برود',NULL,NULL);
INSERT INTO "verses" VALUES(1938206,2353,6,1,'که دست در کمرش جز به سیم و زر نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938207,2353,6,0,'منِ گدا هوس سروقامتی دارم','من ِ بی مال و گدا، در هوسِ داشتنِ شخصِ سروقامتی ام که برای این که بتوان دست به کمرش برد باید سیم و زر داشت. و من از آن بی بهره ام. معنای دیگر: او بسیار ثروتمند است و تنها وقتی دست خود را به کمربند و شالِ خود می برد که سیم و زری از آن خارج کند. و منِ گدا نمی توانم به او برسم و هوس بیهوده ای دارم',NULL);
INSERT INTO "verses" VALUES(1938208,2353,5,1,'که آبرویِ شریعت بدین قَدَر نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938209,2353,5,0,'مکن به چشمِ حقارت نگاه در منِ مست','به چشمِ حقارت به منِ مست نگاه نکن! آبروی شریعت با این مقدار و با این تقدیر نخواهد رفت.',NULL);
INSERT INTO "verses" VALUES(1938210,2353,4,1,'که هیچ کار ز پیشت بدین هنر نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938211,2353,4,0,'دلا مباش چنین هرزه گَرد و هرجایی','به دلِ خودش نهیب می‌ زند. ای دل! به این شیوه، هرزه‌گرد و هرجایی مباش. چون که با این روش، هیچ کاری از پیش نمی‌توانی ببری',NULL);
INSERT INTO "verses" VALUES(1938212,2353,3,1,'چرا که بی سرِ زلفِ توام به سر نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938213,2353,3,0,'ز من چو بادِ صبا بویِ خود دریغ مدار','مثلِ بادِ صبا که از بویِ زلفِ تو نصیب دارد، بوی زلفِ خودت را از من دریغ مکن. چون که بدونِ سرِ زلفِ تو، روزگار بر من نمی‌گذرد. (چرا بادِ صبا داشته باشد من نداشته باشم؟)',NULL);
INSERT INTO "verses" VALUES(1938214,2353,2,1,'که نقشِ خالِ توام هرگز از نظر نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938215,2353,2,0,'سوادِ دیدهٔ غمدیده‌ام به اشک مشوی','با اشک نمی‌توانی سوادِ دیده (سیاهیِ چشم، مردمکِ چشمِ) من را پاک کنی و بشویی. چون که این سیاهیِ چشمِ غمدیده‌یِ من، نقشِ خالِ تو است در چشمانِ من و این سیاهی هرگز از چشمِ من نخواهد ر',NULL);
INSERT INTO "verses" VALUES(1938216,2353,1,1,'ولی چگونه مگس از پِی شکر نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938217,2353,1,0,'طمع در آن لبِ شیرین نکردَنَم اولی','البته که بهتر است که من در آن لبِ شیرین طمع نکنم. اما امکان‌پذیر نیست. مگر می‌شود که مگس به دنبالِ شکر نرود؟',NULL);
INSERT INTO "verses" VALUES(1938218,2353,0,1,'به هر دَرَش که بخوانند بی‌خبر نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938219,2353,0,0,'خوشا دلی که مدام از پِی نظر نرود','ای خوش آن دل که هر دم به دنبالِ تماشای معشوق و نظر کردن نرود. و بدون این که خبردار شود که جایی که او را فرا می‌خوانند و دعوت می‌کنند، به آن‌جا نرود. هرجایی نباشد',NULL);
INSERT INTO "verses" VALUES(1938220,2349,4,0,'سیل است آبِ دیده و هر کس که بگذرد','هوش مصنوعی: اشک‌ها همچون سیلابی هستند و هر کسی که از کنار آن بگذرد، حتی اگر دلش از جنس سنگ باشد، تحت تأثیر قرار می‌گیرد و حرکت می‌کند.',NULL);
INSERT INTO "verses" VALUES(1938221,2352,6,1,'دل به خوبان ندهد وز پِی ایشان نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938222,2352,5,1,'درد دارد چه کُنَد کز پِی درمان نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938223,2352,5,0,'گر رَوَد از پِی خوبان دلِ من معذور است','اگه دلم دنبال خوش روها باشه عذر موجهی داره، چون چاره ای جز این برای تسکین درد عشق نداره',NULL);
INSERT INTO "verses" VALUES(1938224,2352,4,1,'که اگر سر برود، از دل و از جان نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938225,2352,4,0,'آن چُنان مِهر توام در دل و جان جای گرفت','مهر تو چنان جایگاهی در دل و وجودم پیدا کرده، که اگه جونم رو هم از دست بدم مهرت از دل و جونم نخواهد رفت',NULL);
INSERT INTO "verses" VALUES(1938226,2352,3,1,'برود از دلِ من وز دلِ من آن نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938227,2352,3,0,'هر چه جز بارِ غمت بر دلِ مسکینِ من است','هر چیزی که به غیر از غم و غصه هات توی دل بینوای من هست، همشون از دلم بیرون میره اما غم عشقت از دلم بیرون نمیره.',NULL);
INSERT INTO "verses" VALUES(1938228,2352,2,1,'تا ابد سر نَکشَد، وز سرِ پیمان نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938229,2352,2,0,'در ازل بست دلم با سرِ زلفت پیوند','در سرآغاز آفرینش عشق و مهر تو در دلم جوونه زد، تا ابد هم ازت دل نخواهم بُرید و رهات نخواهم کرد',NULL);
INSERT INTO "verses" VALUES(1938230,2352,1,1,'به جفایِ فلک و غُصهٔ دوران نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938231,2352,1,0,'از دِماغِ مَنِ سرگشته خیالِ دَهَنَت','در ذهن آشفته من فکر تو، با غم وناملایمات و فراز و نشیب روزگار هم از ذهنم بیرون نمیره.',NULL);
INSERT INTO "verses" VALUES(1938232,2352,0,1,'هرگز از یادِ من آن سروِ خرامان نَرَوَد',NULL,NULL);
INSERT INTO "verses" VALUES(1938233,2352,0,0,'هرگزم نقشِ تو از لوحِ دل و جان نَرَوَد','هيچ وقتم چهره تو از دل و روح و روانم بیرون نخواهد رفت ، هیچوقت از خاطرم اون یار خوش قد و قامتِ نجیب نخواهد رفت',NULL);
INSERT INTO "verses" VALUES(1938234,2351,6,1,'بو که از لوحِ دلت نقشِ جهالت برود',NULL,NULL);
INSERT INTO "verses" VALUES(1938235,2351,6,0,'حافظ از چشمهٔ حکمت به کف آور جامی','هوش مصنوعی: حافظ می‌گوید از چشمهٔ دانایی جامی بگیر تا نقش نادانی که بر دل تو نقش بسته پاک شود.',NULL);
INSERT INTO "verses" VALUES(1938236,2352,6,0,'هر که خواهد که چو حافظ نشود سرگردان','هر کسی که میخواد مثل حافظ شوریده و سرگشته نشه، پا روی دلش بذاره و دل نده و دل نسپره.',NULL);
INSERT INTO "verses" VALUES(1938237,2337,4,1,'شیخ ما گفت که در صومعه همّت نبود',NULL,NULL);
INSERT INTO "verses" VALUES(1938238,2349,3,1,'بر رویِ ما رواست اگر آشنا رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938239,2349,2,1,'گر ماهِ مِهرپرورِ من در قبا رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938240,2347,4,0,'همتِ عالی طلب جامِ مُرَصَّع گو مباش','هوش مصنوعی: اگر خواهان دستیابی به چیزهای ارزشمند و باارزش هستی، به دنبال شلختگی و بی‌خیالی نباش. زیرا برای کسی که با دید والایی به زندگی نگاه می‌کند، لذت‌های ساده و معمولی مانند شراب، خیلی کم‌ارزش می‌شوند.',NULL);
INSERT INTO "verses" VALUES(1938241,2347,3,1,'زان که کُنجِ اهلِ دل باید که نورانی بُوَد',NULL,NULL);
INSERT INTO "verses" VALUES(1938242,2347,3,0,'بی چراغِ جام در خلوت نمی‌یارم نشست','هوش مصنوعی: بدون نور و روشنایی جام در تنهایی نمی‌نشینم، زیرا که گوشه و مکانی که اهل دل گرد هم می‌آیند، باید روشن و نورانی باشد.',NULL);
INSERT INTO "verses" VALUES(1938243,2347,2,1,'همچو گُل بر خِرقه رنگِ مِی مسلمانی بُوَد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938244,2347,2,0,'خود گرفتم کَافکَنَم سجاده چون سوسن به دوش','هوش مصنوعی: خودم را مانند گلی زیبا در سجاده‌ای قرار دادم؛ به‌گونه‌ای که رنگ می‌خوردن در خرقه‌ام، نشانه‌ای از مسلمانی من است.',NULL);
INSERT INTO "verses" VALUES(1938245,2347,1,1,'گفتم این شاخ ار دهد باری، پشیمانی بُوَد',NULL,NULL);
INSERT INTO "verses" VALUES(1938246,2347,1,0,'من همان ساعت که از مِی خواستم شد توبه کار','هوش مصنوعی: من در همان لحظه‌ای که از شراب خواستم، تصمیم گرفتم که توبه کنم. اگر این شاخ، بار یا میوه‌ای به من بدهد، احساس پشیمانی خواهم داشت.',NULL);
INSERT INTO "verses" VALUES(1938247,2347,0,1,'تا ابد جامِ مرادش همدمِ جانی بُوَد',NULL,NULL);
INSERT INTO "verses" VALUES(1938248,2347,0,0,'در ازل هر کو به فیضِ دولت ارزانی بُوَد','هوش مصنوعی: در آغاز، هر کسی که به نعمت و برکت خداوندی دست یابد، تا همیشه آرزویش در کنار جانش خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1938249,2346,7,1,'که ما دیدیم و محکم جاهلی بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938250,2346,7,0,'مگو دیگر که حافظ نکته‌دان است','هوش مصنوعی: نگو که حافظ شخص بافرهنگ و آگاهی است، چون ما شاهد بودیم که او از جهالت هم دور نبوده است.',NULL);
INSERT INTO "verses" VALUES(1938251,2346,6,1,'حدیثم نکتهٔ هر محفلی بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938252,2346,6,0,'مرا تا عشق تعلیمِ سخن کرد','هوش مصنوعی: عشق به من آموخت چگونه سخن بگویم و من در هر جمع و محفلی به عنوان یک نکتهٔ مهم و قابل توجه مطرح بودم.',NULL);
INSERT INTO "verses" VALUES(1938253,2346,5,1,'که وقتی کاردانی کاملی بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938254,2346,5,0,'بر این جانِ پریشان رحمت آرید','هوش مصنوعی: بر این روح ناآرام، رحمت نازل کنید، زیرا زمانی که عقل و تدبیر به کمال رسیده بود، چنین حالتی داشت.',NULL);
INSERT INTO "verses" VALUES(1938255,2346,4,1,'ز من محروم‌تر کِی سائلی بود؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938256,2346,4,0,'هنر بی‌عیبِ حِرمان نیست لیکن','هوش مصنوعی: هنر نقص ندارد و کسی نیست که مانند من از آن بی‌بهره باشد.',NULL);
INSERT INTO "verses" VALUES(1938257,2346,3,1,'چه دامنگیر یا رب منزلی بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938258,2346,3,0,'ز من ضایع شد اندر کویِ جانان','هوش مصنوعی: به خاطر عشق و محبت‌ام در کوی معشوق، از دست رفته‌ام. چه حسرت‌انگیز است که آنجا جا و مکانی داشتم.',NULL);
INSERT INTO "verses" VALUES(1938259,2346,2,1,'که اِستِظهارِ هر اهلِ دلی بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938260,2346,2,0,'دلی همدرد و یاری مصلحت بین','هوش مصنوعی: دل کسی را پیدا کن که همدرد و یار باشد و در عین حال مصلحت‌ها را هم بسنجد، چرا که این ویژگی از ضروریات هر کسی است که دلش به درد دیگران می‌سوزد.',NULL);
INSERT INTO "verses" VALUES(1938261,2346,1,1,'به تدبیرش امیدِ ساحلی بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938262,2346,1,0,'به گِردابی چو می‌افتادم از غم','هوش مصنوعی: در زمانی که در مشکلات و ناراحتی‌ها غرق می‌شدم، امیدم به پیدا کردن راهی برای نجات و رسیدن به ساحل آرامش بود.',NULL);
INSERT INTO "verses" VALUES(1938263,2346,0,1,'که با وی گفتمی گر مشکلی بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938264,2346,0,0,'مسلمانان مرا وقتی دلی بود','ای مسلمانان، من زمانی دلی (یاری) داشتم، اگر مشکلی داشتم با‌ او میگفتم',NULL);
INSERT INTO "verses" VALUES(1938265,2345,9,1,'از یُمنِ دعایِ شب و وِردِ سَحَری بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938266,2345,9,0,'هر گنجِ سعادت که خدا داد به حافظ','هوش مصنوعی: هر خوشبختی و نعمت که خداوند به حافظ عطا کرده، ناشی از دعاهای شب و ذکرهای سحرگاه اوست.',NULL);
INSERT INTO "verses" VALUES(1938267,2345,8,1,'با بادِ صبا وقتِ سحر جلوه‌گری بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938268,2345,8,0,'خود را بکش ای بلبل از این رشک که گُل را','هوش مصنوعی: ای بلبل، خودت را از حسرتی که به خاطر زیبایی گل به تو دست داده، رها کن؛ زیرا در زمان صبحگاهی، گل با نسیم صبح خود را به نمایش می‌گذارد و زیبایی‌اش از آنِ اوست.',NULL);
INSERT INTO "verses" VALUES(1938269,2347,4,1,'رند را آبِ عِنَب یاقوتِ رُمّانی بُوَد',NULL,NULL);
INSERT INTO "verses" VALUES(1938270,2347,5,0,'گرچه بی‌سامان نماید کارِ ما، سهلش مبین','هوش مصنوعی: اگرچه کارهای ما ممکن است بی‌نظم و آشفته به نظر برسد، اما نباید این را آسان بگیری. زیرا در این دیار، وضعیت کسانی که به دنبال چیزهای کوچک و ناچیز هستند، حسرت برانگیز و قابل توجه است.',NULL);
INSERT INTO "verses" VALUES(1938271,2347,5,1,'کاندر این کشور گدایی، رَشکِ سلطانی بُوَد',NULL,NULL);
INSERT INTO "verses" VALUES(1938272,2347,6,0,'نیک نامی خواهی ای دل با بَدان صحبت مدار','هوش مصنوعی: اگر می‌خواهی انسان نیک ‌نامی باشی، با افراد بد صحبت نکن. خودپسندی و تکبر نشانه‌های نادانی و ناتوانی هستند.',NULL);
INSERT INTO "verses" VALUES(1938273,2349,2,0,'خورشیدِ خاوری کُنَد از رَشک جامه چاک','هوش مصنوعی: خورشید شرق از حسادت جامه‌اش را می‌دراند که اگر ماهی که محبوب من است، به قبا (لباس ظاهری) برود.',NULL);
INSERT INTO "verses" VALUES(1938274,2349,1,1,'بر باد اگر رَوَد دلِ ما زان هوا رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938275,2349,1,0,'ما در درونِ سینه هوایی نهفته‌ایم','هوش مصنوعی: ما در اعماق وجودمان آرزوها و احساساتی داریم که اگر این احساسات به آزادی برسند، دل و روح ما نیز با آن‌ها پرواز خواهد کرد.',NULL);
INSERT INTO "verses" VALUES(1938276,2349,0,1,'بر رویِ ما ز دیده چه گویم چه‌ها رَوَد',NULL,NULL);
INSERT INTO "verses" VALUES(1938277,2349,0,0,'از دیده خونِ دل همه بر رویِ ما رَوَد','هوش مصنوعی: از چشمان پر از درد و اندوه مردم، هر چه بر چهره‌ی ما می‌افتد، دیده می‌شود. حالا دربارهٔ چهره‌ام چه بگویم که اندوه و غم چقدر بر آن تأثیر گذاشته است؟',NULL);
INSERT INTO "verses" VALUES(1938278,2348,9,1,'هر آن چه می‌طلبد جمله باشدش موجود',NULL,NULL);
INSERT INTO "verses" VALUES(1938279,2348,9,0,'بُوَد که مجلس حافظ به یمن تربیتش','هوش مصنوعی: مجلس حافظ به لطف تربیت و تعلیمش، هر چیزی که انسان بخواهد و آرزو کند، در دسترس و موجود خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1938280,2348,8,1,'وزیرِ مُلکِ سلیمان، عمادِ دین، محمود',NULL,NULL);
INSERT INTO "verses" VALUES(1938281,2348,8,0,'بخواه جامِ صَبوحی به یادِ آصفِ عهد','هوش مصنوعی: از یک لیوان شراب صبحگاهی بخواه تا به یاد آصف، وزیر بزرگ ملک سلیمان، که پشتیبان دین و محمود بود، نقش ببندد.',NULL);
INSERT INTO "verses" VALUES(1938282,2348,7,1,'کنون که لاله برافروخت آتشِ نمرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938283,2348,7,0,'به باغ، تازه کن آیینِ دینِ زردشتی','به باغ برو و راه و رسم دین زرتشتی را تازه کن، زیرا که لاله‌ها چنان شکوفه زده‌اند که گویی آتش نمرود را مجددا شعله‌ور ساخته‌اند.',NULL);
INSERT INTO "verses" VALUES(1938284,2348,6,1,'سحر که مرغ درآید به نغمهٔ داوود',NULL,NULL);
INSERT INTO "verses" VALUES(1938285,2348,6,0,'چو گل سوار شَوَد بر هوا سلیمان‌وار','هوش مصنوعی: وقتی که گل مانند سلیمان بر فراز هوا پرواز کند و صبح فرابرسد، پرنده با صدای دلنشین خود به آواز داوود خواهد خواند.',NULL);
INSERT INTO "verses" VALUES(1938286,2348,5,1,'ولی چه سود که در وِی نه ممکن است خُلُود',NULL,NULL);
INSERT INTO "verses" VALUES(1938287,2349,3,0,'بر خاکِ راهِ یار نهادیم رویِ خویش','هوش مصنوعی: ما سر خود را بر زمین راه محبوب گذاشته‌ایم و اگر آشنا از این کار ما ناراحت شود، ایرادی ندارد.',NULL);
INSERT INTO "verses" VALUES(1938288,2348,5,0,'جهان چو خُلدِ بَرین شد به دورِ سوسن و گل','هوش مصنوعی: جهان مثل بهشتی زیبا و پر از گل و گیاه شده است، اما چه فایده که در این بهشت امکان ماندن و آرامش واقعی وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1938289,2348,4,0,'ز دستِ شاهدِ نازک‌عِذار عیسی‌دَم','هوش مصنوعی: از دست معشوق نازک‌چهره‌ام شراب بنوش و داستان قوم عاد و ثمود را فراموش کن.',NULL);
INSERT INTO "verses" VALUES(1938290,2348,3,1,'زمین، به اخترِ میمون و طالعِ مسعود',NULL,NULL);
INSERT INTO "verses" VALUES(1938291,2348,3,0,'شد از خروجِ رِیاحین چو آسمان روشن','هوش مصنوعی: با وزش ریاحین، آسمان روشن شد و زمین، به ستاره‌ی خوش یمن و سرنوشت نیک دچار گشت.',NULL);
INSERT INTO "verses" VALUES(1938292,2348,2,1,'که همچو روزِ بقا هفته‌ای بُوَد معدود',NULL,NULL);
INSERT INTO "verses" VALUES(1938293,2348,2,0,'به دورِ گُل منشین بی‌شراب و شاهد و چنگ','هوش مصنوعی: به دور گل ننشین که بدون شراب و معشوق و موسیقی است، زیرا مانند روزهای زندگی، فقط یک هفته دوام می‌آورد.',NULL);
INSERT INTO "verses" VALUES(1938294,2348,1,1,'ببوس غَبغَب ساقی به نغمهٔ نی و عود',NULL,NULL);
INSERT INTO "verses" VALUES(1938295,2348,1,0,'بنوش جامِ صبوحی به نالهٔ دَف و چنگ','هوش مصنوعی: جامی از شراب بنوش و با صدای دف و چنگ لذت ببر. ساقی را ببوس و به آهنگ نی و عود گوش کن.',NULL);
INSERT INTO "verses" VALUES(1938296,2348,0,1,'بنفشه در قدمِ او نهاد سر به سجود',NULL,NULL);
INSERT INTO "verses" VALUES(1938297,2348,0,0,'کنون که در چمن آمد گُل از عَدَم به وجود','هوش مصنوعی: اکنون که گل در باغ شکفته است و از هیچ به وجود آمده، بنفشه به احترام او سر به زمین می‌گذارد.',NULL);
INSERT INTO "verses" VALUES(1938298,2347,8,1,'ای عزیزِ من! نه عیب آن بِه که پنهانی بود؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938299,2347,8,0,'دی عزیزی گفت حافظ می‌خورد پنهان شراب','هوش مصنوعی: دیگری به حافظ می‌گوید: «ای عزیز من! او در خفا شراب می‌نوشد. مگر عیب آن این نیست که پنهانی باشد؟»',NULL);
INSERT INTO "verses" VALUES(1938300,2347,7,1,'نَستَدَن جامِ مِی از جانان گران جانی بُوَد',NULL,NULL);
INSERT INTO "verses" VALUES(1938301,2347,7,0,'مجلسِ اُنس و بهار و بحثِ شعر اندر میان','هوش مصنوعی: در جمع دوستان و در فضایی دل‌چسب که بهار و شعر در آن صحبت می‌شود، نوشیدن جام می از معشوق بسیار ارزشمند و دلپذیر است.',NULL);
INSERT INTO "verses" VALUES(1938302,2347,6,1,'خودپسندی جانِ من بُرهانِ نادانی بُوَد',NULL,NULL);
INSERT INTO "verses" VALUES(1938303,2348,4,1,'شراب نوش و رها کن حدیثِ عاد و ثمود',NULL,NULL);
INSERT INTO "verses" VALUES(1938304,2337,3,0,'دولت از مرغِ همایون طلب و سایهٔ او','هوش مصنوعی: از خوشبختی و سعادت بپرس و به این واقعیت توجه کن که سایهٔ آن خوشبختی، بر اساس ارتباط و نزدیکی به موجودات کوچک و بی‌ارزش مثل زاغ و زغن (پرندگان معمولی و کم‌ارزش) نمی‌تواند پابرجا بماند. در حقیقت، برای دست‌یابی به سعادت واقعی، باید به چیزهای ارزشمند و بزرگتر توجه کرد.',NULL);
INSERT INTO "verses" VALUES(1938305,2337,3,1,'زان که با زاغ و زَغَن شَهپَرِ دولت نبود',NULL,NULL);
INSERT INTO "verses" VALUES(1938306,2337,2,0,'خیره آن دیده که آبش نَبَرَد گریهٔ عشق','هوش مصنوعی: چشمی که نتواند برای عشق بگرید، نابینا و بی‌فایده است و دلی که در آن محبت وجود ندارد، به تاریکی مبتلاست.',NULL);
INSERT INTO "verses" VALUES(1938307,2327,5,0,'گفتم شراب و خِرقه نه آیینِ مذهب است','هوش مصنوعی: گفتم نوشیدن شراب و پوشیدن لباس عابدان، خود نشانه‌ای از دین و آیین نیست. او پاسخ داد که این کارها به طریقه و سنت پیشوایان مغان انجام می‌شود.',NULL);
INSERT INTO "verses" VALUES(1938308,2327,4,0,'گفتم هوایِ میکده غم می‌بَرَد ز دل','هوش مصنوعی: گفتم که محیطِ میکده، غم را از دل می‌زداید. او پاسخ داد که خوشا به حال کسانی که دل را شاد می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1938309,2327,4,1,'گفتا خوش آن کَسان که دلی شادمان کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938310,2327,3,0,'گفتم صَنم‌پَرست مشو با صَمَد نشین','هوش مصنوعی: گفتم ای محبوب من، به پرستش چیزهای بی‌تفاوت مشغول نشو و تنها به دنبال خداوند باش. ولی او گفت در کوی عشق، همه چیز مجاز است و هم به این و هم به آن می‌پردازند.',NULL);
INSERT INTO "verses" VALUES(1938311,2327,3,1,'گفتا به کویِ عشق هم این و هم آن کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938312,2327,2,0,'گفتم به نقطهٔ دهنت خود که بُرد راه؟','از او پرسیدم که چه‌کسی به بوسه‌ی دهان کوچک تو می‌رسد؟ گفت این داستانی است که نکته‌دان‌ها به آن می‌رسند.',NULL);
INSERT INTO "verses" VALUES(1938313,2327,2,1,'گفت این حکایتیست که با نکته‌دان کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938314,2327,1,0,'گفتم خَراجِ مصر طلب می‌کند لبت','به او گفتم: لب‌ تو آنقدر باارزش‌است که با خراج مُلک مصر برابری می‌کند گفت که ارزش آن‌را دارد.',NULL);
INSERT INTO "verses" VALUES(1938315,2327,1,1,'گفتا در این معامله کمتر زیان کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938316,2327,0,0,'گفتم کِی ام دهان و لبت کامران کنند؟','هوش مصنوعی: به او گفتم که کی زبان و لب من را راضی می‌کند؟ او پاسخ داد که هرچه تو بخواهی، با چشم‌هایت انجام می‌دهند.',NULL);
INSERT INTO "verses" VALUES(1938317,2327,0,1,'گفتا به چشم هر چه تو گویی چُنان کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938318,2326,8,0,'سر مکش حافظ ز آهِ نیم‌شب','هوش مصنوعی: سر خود را از غم شبانه بردار، زیرا در سپیده‌دم، چهره‌ای درخشان ترسیم خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1938319,2326,8,1,'تا چو صبحت، آینه رخشان کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938320,2326,7,0,'خوش برآ با غصه، ای دل! کاَهلِ راز','هوش مصنوعی: عشق و شادی را با غم و اندوه همراه کن، زیرا انسان‌های بی‌خیال از خوشی‌ها در درد جدایی به سر می‌برند.',NULL);
INSERT INTO "verses" VALUES(1938321,2326,7,1,'عیشِ خوش در بوتهٔ هجران کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938322,2326,6,0,'مردمِ چشمم به خون آغشته شد','هوش مصنوعی: مردم چشمم در خون غوطه‌ور شده‌اند. کاش کسی بگوید در کجا این ظلم‌ها بر انسان‌ها روا می‌دارند؟',NULL);
INSERT INTO "verses" VALUES(1938323,2326,6,1,'در کجا این ظلم بر انسان کنند؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938324,2326,5,0,'یارِ ما چون گیرد آغازِ سَماع','هوش مصنوعی: دوست ما وقتی که شروع به جشن و سرور می‌کند، فرشتگان در بلندای آسمان به شادی دست‌ها را به نشانهٔ خوشحالی می‌افشانند.',NULL);
INSERT INTO "verses" VALUES(1938325,2326,5,1,'قُدسیان بر عرش دست‌افشان کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938326,2326,4,0,'پیشِ چشمم کمتر است از قطره‌ای','هوش مصنوعی: این داستان‌ها که از طوفان‌ها و مشکلات می‌گویند، در مقایسه با آنچه که در چشم من می‌بینم، بسیار ناچیز و کم‌اهمیت است.',NULL);
INSERT INTO "verses" VALUES(1938327,2326,4,1,'این حکایت‌ها که از طوفان کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938328,2326,3,0,'عاشقان را بر سرِ خود حُکم نیست','هوش مصنوعی: عاشقان هیچ قانونی بر سر خود ندارند و هر چه تو دستور بدهی، همان را انجام می‌دهند.',NULL);
INSERT INTO "verses" VALUES(1938329,2326,3,1,'هر چه فرمانِ تو باشد آن کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938330,2326,2,0,'ای جوانِ سَروقَد! گویی بِبَر','ای جوان بلند قامت، گویی (منظور گوی چوگان )ببر و تلاش کن تا برنده باشی قبل از اینکه پیر شوی و قامتت مانند چوگان خمیده شود',NULL);
INSERT INTO "verses" VALUES(1938331,2326,2,1,'پیش از آن کز قامتت چوگان کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938332,2326,1,0,'هر کجا آن شاخِ نرگس بِشْکُفد','هوش مصنوعی: هر جا که آن گل نرگس شکفته شود، زیبایی‌اش را به چشمان دیگران نشان می‌دهد و آنها نیز آن را درک می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1938333,2326,1,1,'گُل‌رُخانَش دیده نرگس‌دان کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938334,2326,0,0,'شاهدان گر دلبری زین سان کنند','هوش مصنوعی: اگر کسانی با دلربایی و زیبایی خود این‌گونه رفتار کنند، ایمان زاهدان و پارسایان دچار تزلزل می‌شود.',NULL);
INSERT INTO "verses" VALUES(1938335,2326,0,1,'زاهدان را رخنه در ایمان کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938336,2327,5,1,'گفت این عمل به مذهبِ پیرِ مغان کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938337,2327,6,0,'گفتم ز لَعلِ نوش‌ْلبان پیر را چه سود؟','هوش مصنوعی: از پیر جوانی پرسیدم که محاسن او مانند لعل سرخ و لبانش شیرین است، چه فایده‌ای دارد؟ او در پاسخ گفت که بوسه‌های شیرینش می‌تواند جوانان را دوباره به جوانی برساند.',NULL);
INSERT INTO "verses" VALUES(1938338,2327,6,1,'گفتا به بوسهٔ شِکَرینَش جوان کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938339,2327,7,0,'گفتم که خواجه کِی به سرِ حجله می‌رود؟','هوش مصنوعی: پرسیدم که آقا کی به خانه عروسی می‌رود؟ پاسخ داد وقتی که مشتری و ماه در کنار هم بیایند.',NULL);
INSERT INTO "verses" VALUES(1938340,2329,5,0,'تشویشِ وقتِ پیرِ مغان می‌دهند باز','آنان زرتشت را نیز پریشان می‌کنند،به این افراد گستاخ بنگر که با یک بزرگ(پیر :رهبر،دانا)چه بد رفتارمی‌کنند.',NULL);
INSERT INTO "verses" VALUES(1938341,2329,4,0,'ما از برونِ در شده مغرورِ صد فریب','ما از دنیای بیرون و ظواهر فریبنده مغرور شده‌ایم، اما در باطن و در عمق وجود چه کارهایی در حال انجام است و چه تدبیری در حال چیده شدن است.',NULL);
INSERT INTO "verses" VALUES(1938342,2329,4,1,'تا خود درونِ پرده چه تدبیر می‌کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938343,2329,3,0,'گویند رمزِ عشق مگویید و مشنوید','می‌گویند درباره عشق صحبت نکنید و نشنوید، زیرا این داستانی است پیچیده که به سختی قابل بیان است.',NULL);
INSERT INTO "verses" VALUES(1938344,2329,3,1,'مشکل حکایتیست که تَقریر می‌کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938345,2329,2,0,'جز قلبِ تیره هیچ نشد حاصل و هنوز','(برخی از کسانی که به دنبال کیمیاگری بودند متوسل به سحر و جادو میشدند و این امر قلبشان را سیاه میکرد.) مانند برخی از کیمیاگران که فکر میکنند دارند مس رو طلا میکنند رفتار ظاهربینان صرفاً قلبشان را تیره و سیاه کرده است. (کنایه به اینکه با برخورد سطحی خودشان را از فهم عرفان محروم کرده اند.)',NULL);
INSERT INTO "verses" VALUES(1938346,2329,2,1,'باطل در این خیال که اِکسیر می‌کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938347,2329,1,0,'ناموسِ عشق و رونقِ عُشّاق می‌بَرند','با عشق و عشق بازی مخالفند و اون را گناه میدونند و جوانی که عاشق بشود را عیب دار میکنند و پیر ها را هم سرزنش میکنند',NULL);
INSERT INTO "verses" VALUES(1938348,2329,1,1,'عیبِ جوان و سرزنشِ پیر می‌کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938349,2329,0,0,'دانی که چنگ و عود چه تَقریر می‌کنند؟','می دانی که چنگ و عود(بربط و در کل منظور موسیقی )چی میگن.مشروب را در خفا و خلوت بخورید که اگر شما را با مشروب بگیرند شلاقت میزنند.',NULL);
INSERT INTO "verses" VALUES(1938350,2329,0,1,'پنهان خورید باده که تَعزیر می‌کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938351,2328,7,0,'صبح‌دم از عرش می‌آمد خروشی، عقل گفت','هنگام صبح از عرش الهی بانگ و فریادی می آمد جبرییل گفت: مثل اینکه فرشتگان مشغول حفظ کردن شعر حافظ هستند.',NULL);
INSERT INTO "verses" VALUES(1938352,2328,7,1,'«قُدسیان گویی که شعرِ حافظ از بَر می‌کنند»',NULL,NULL);
INSERT INTO "verses" VALUES(1938353,2328,6,0,'بر درِ می‌خانهٔ عشق ای مَلَک، تسبیح گوی','ای فرشتگان به سراغ میخانه عشق بروید و در آنجا خداوند را به پاکی ستایش کنید چرا که در آنجا گل وجود آدمی را ورز می دهند(نکته: بیت فوق از لحاظ معنایی یادآور بیت زیر است:دوش دیدم که ملایک در میخانه زدند گل آدم بسرشتند و به پیمانه زدند.)',NULL);
INSERT INTO "verses" VALUES(1938354,2325,11,0,'حافظ دوامِ وصل میسر نمی‌شود','هوش مصنوعی: دائم بودن ارتباط و وصال آسان نیست، چراکه پادشاهان کمتر به حال فقیر و کسانی که در نیاز هستند توجه دارند.',NULL);
INSERT INTO "verses" VALUES(1938355,2328,6,1,'کاَندر آنجا، طینَتِ آدم مُخَمَّر می‌کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938356,2328,5,0,'حُسنِ بی‌پایان او، چندان که عاشق می‌کُشد','زیبایی نامتناهی خداوند هر چند که عاشقان خود را می­‌کشد اما باز گروهی دیگر از عالم غیب آشکار می‌­شوند و عاشقانه آماده جان‌فشانی در راه او می­‌شوند',NULL);
INSERT INTO "verses" VALUES(1938357,2328,4,0,'ای گدای خانِقَه، بَرْجَه که در دِیرِ مُغان','ای کسی که در خانقاه به گدایی رسیده ای از آن جا برخیز و به سمت دیر مغان برو و ببین که در آنجا به تو شرابی می دهند که به واسطه خوردن آن دل تو ثروتمند و غنی خواهد شد',NULL);
INSERT INTO "verses" VALUES(1938358,2328,4,1,'می‌دهند آبی و دل‌ها را توانگر می‌کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938359,2328,3,0,'یا رب این نُودولَتان را با خَرِ خودْشان نشان','خداوندا این تازه به دوران رسیده ها را به جایگاه قبلی خودشان بازگردان چرا که امروزه به واسه داشتن چند غلام ترک و چند چارپا به همه فخر می فروشند و خود را برتر از همه می دانند',NULL);
INSERT INTO "verses" VALUES(1938360,2328,3,1,'کاین همه ناز از غلامِ تُرک و اَسْتَر می‌کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938361,2328,2,0,'گوییا باور نمی‌دارند روزِ داوری','مثل اینکه هرگز به روز قیامت اعتقادی ندارند چرا که مشغول این همه نیرنگ و تقلب در کار خداوند هستند',NULL);
INSERT INTO "verses" VALUES(1938362,2328,2,1,'کاین همه قَلب و دَغَل در کارِ داور می‌کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938363,2328,1,0,'مشکلی دارم، زِ دانشمندِ مجلس بازپرس','سوالی دارم از دانشمند مجلس این نکته را بپرس: چرا کسانی که مردم را وادار به توبه و پرهیزگاری می­‌کنند خود هرگز توبه نمی­‌کنند(نکته: مصراع دوم احتمالا اشاره به آیه‌­ی ۴۴ سوره بقره دارد: أَتَأْمُرُونَ النَّاسَ بِالْبِرِّ وَتَنْسَوْنَ أَنْفُسَکُمْ وَأَنْتُمْ تَتْلُونَ الْکِتَابَ ۚأَفَلَا تَعْقِلُونَ)',NULL);
INSERT INTO "verses" VALUES(1938364,2328,1,1,'توبه‌فرمایان، چرا خود توبه کم‌تر می‌کنند؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938365,2328,0,0,'واعظان کاین جلوه در محراب و منبر می‌کنند','نصیحت­‌گویان که چنین خود را پاک و مطهر در محراب و منبر نشان می­‌دهند در خلوت کاری بر خلاف گفته‌­های خود انجام می­‌دهند(نکته: یکی از رندانه ترین ناسزاهایی که در طول تاریخ زبان و ادبیات فارسی به ریاکاران گفته شده است این بیت حافظ است و تمام زیبایی این ناسزا نیز از آنجا شروع می­‌شود که حافظ هیچ ناسزایی نگفته است. اجازه بدهید واضح­تر این مطلب را بیان کنم حافظ در مصراع دوم تنها به این گفته بسنده می کند “آن کار دیگر می­‌کنند” چنانچه می بینید حافظ عملا هیچ حرف خاصی نزده است اما در واقع عبارت “آن کار دیگر” گویی همانند “نقطه چین” عمل می‌­کند چرا که ذهن خواننده به طور ناخودآگاه آن نقطه چین را پُر می کند در حالی که در واقعیت حافظ هیچ ناسزایی نگفته است)',NULL);
INSERT INTO "verses" VALUES(1938366,2328,0,1,'چون به خلوت می‌روند آن کارِ دیگر می‌کنند!',NULL,NULL);
INSERT INTO "verses" VALUES(1938367,2327,8,0,'گفتم دعایِ دولت او وِردِ حافظ است','هوش مصنوعی: گفتم دعای ثروت و موفقیت او، همیشه ذکر و یاد حافظ است. او پاسخ داد که این دعا را فرشتگان آسمان‌های هفتگانه بر زبان می‌آورند.',NULL);
INSERT INTO "verses" VALUES(1938368,2327,8,1,'گفت این دعا ملایکِ هفت آسمان کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938369,2327,7,1,'گفت آن زمان که مشتری و مَه قِران کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938370,2328,5,1,'زمرهٔ دیگر به عشق از غیب سَر بَر می‌کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938371,2329,5,1,'این سالِکان نگر که چه با پیر می‌کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938372,2325,11,1,'شاهان کم التفات به حالِ گدا کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938373,2325,10,0,'پنهان ز حاسدان به خودم خوان که مُنعِمان','پنهانی و دور از چشم حسودان مرا نزد خود بخوان، زیرا افراد نیکوکار برای رضای خدا کارهای خیر را پنهانی انجام می‌دهند.',NULL);
INSERT INTO "verses" VALUES(1938374,2324,1,0,'تو را صَبا و مَرا آبِ دیدِه شُد غَمّاز','هوش مصنوعی: تو نسیم وصالی و من هم در حال گریه و اندوه، تو به من اشاره می‌کنی و اگر نه، عاشق و معشوق هر دو رازدار هستند.',NULL);
INSERT INTO "verses" VALUES(1938375,2324,1,1,'وَگَرنَه عاشِق و مَعْشوق، رازداران‌اَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1938376,2324,0,0,'غُلَامِ نَرْگِسِ مَسْتِ تو، تاجداران‌اَنْد','شاهانِ تاجدار با همه بزرگی به غلامیِ چشم مست و زیبای تو مشغول اند و آنان که که از باده وجود تو نوشیده اند از مستی هوشیاری یافته اند',NULL);
INSERT INTO "verses" VALUES(1938377,2324,0,1,'خَرابِ بادِهٔ لَعْلِ تو، هوشیاران‌اَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1938378,2323,7,0,'دَر این حَضْرَت چو مُشْتاقان نیاز آرَنْد، ناز آرَنْد','زمانی که عاشقان و مشتاقان با نیاز به این درگاه روی می­‌آورند، با ناز و بی­مهری معشوق رو به رو می­‌شوند، کسانی که به دنبال درمان درد عشق می­‌گردند نیز ، مطمئنا درمانده و ناتوان خواهند شد',NULL);
INSERT INTO "verses" VALUES(1938379,2323,7,1,'کِه با این دَرْد اگر دربند درمانند، در مانند',NULL,NULL);
INSERT INTO "verses" VALUES(1938380,2323,6,0,'چو مَنْصور از مُراد آنان که بردارند، بر دارند','کسانی که همانند منصور حلاج در راه عشق به دار آویخته می­‌شوند، تنها می­‌توانند به آرزو و مراد خود برسند؛ اما در این درگاه زمانی که حافظ را فرا می­‌خوانند، بلافاصله او را از آنجا می‌­رانند و طرد می‌­کنند( منصور: منصور حلاج؛ از عارفان مشهور ایران که به جرم اناالحق گفتن در سال ۳۰۹ ه.ق. در زمان عباسیان به دار آویخته شد)',NULL);
INSERT INTO "verses" VALUES(1938381,2323,6,1,'بدین درگاه، «حافِظ» را چو می‌خوانَنْد؛ می‌رانَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1938382,2323,5,0,'دَوایِ دَرْدِ عاشِق را کسی کاو سَهْل پِنْدارَد','هر کس درمان درد عشق را آسان تصور کند، سخت در اشتباه است، و آن کسانی هم که می­‌خواهند با عقل و تدبیر مشکل عشق را درمان کنند، در این کار عاجز و ناتوان باقی خواهند ماند',NULL);
INSERT INTO "verses" VALUES(1938383,2323,5,1,'زِ فِکْر، آنان کِه دَر تَدْبیر درمانند، در مانند',NULL,NULL);
INSERT INTO "verses" VALUES(1938384,2323,4,0,'زِ چَشْمَم، لَعْلِ رُمّانی چو می‌خَنْدَنْد، می‌بارَنْد','زمانی که زیبارویان می­‌خندند، چشمان مرا وادار می­‌کنند تا اشکی سرخگون از آن جاری شود، و هنگامی که به چهره­‌ی من نگاه می­‌کنند تمام رازهای پنهانی (عشق) مرا، متوجه می­‌شوند',NULL);
INSERT INTO "verses" VALUES(1938385,2323,4,1,'زِ رویَم، رازِ پِنْهانی چو می‌بینَنْد؛ می‌خوانَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1938386,2323,3,0,'سِرِشْکِ گوشِه‌گیران را چو دَریابَنْد، دُر یابَنٔد','اگر به قطرات اشک گوشه گیران و عزلت نشینان توجه کنند، خواهند دانست که آن اشک‌­ها همچون دُر و گوهر با ارزش هستند، همچنین اگر اهل معرفت باشند و بدانند، هرگز با بی‌­مهری از سحرخیزان و شب زنده داران روی خود را بر نمی­‌گردانند',NULL);
INSERT INTO "verses" VALUES(1938387,2323,3,1,'رُخِ مِهْر از سَحَرخیزان نَگَردانَنْد، اَگَر دانند',NULL,NULL);
INSERT INTO "verses" VALUES(1938388,2323,2,0,'بِه عُمْری، یِک نَفَس با ما چو بِنْشینَنْد؛ بَرخیزَنْد','وقتی پس از روزگاری طولانی و چشم انتظاری، لحظه­‌ای در کنار ما می­‌نشینند، سریع برمی­‌خیزند و می­‌روند، هنگام برخاستن و بلند شدن نیز، شور و شوق را همچون نهالی در دل ما قرار می‌­دهند.(دل ما را پر از آرزوی خواستن می­‌کند)',NULL);
INSERT INTO "verses" VALUES(1938389,2323,2,1,'نَهالِ شوق در خاطِر چو بَرخیزَنْد، بِنْشانَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1938390,2323,1,0,'بِه فِتْراکِ جَفا، دِل‌ها چو بَربَنْدَنْد؛ بَربَنْدَنْد','وقتی زیبارویان دل­‌ها را اسیر خود می­کنند و به دام می‌­اندازند، آنها را تا همیشه گرفتار خود می­‌سازند، و هنگامی که گره زلف عطرآگین خود را باز می‌­کنند، جان­های بسیاری را که در پیچ و تاب زلف ایشان اسیر هستند، فرو می‌­ریزد',NULL);
INSERT INTO "verses" VALUES(1938391,2323,1,1,'زِ زُلْفِ عَنْبَرین، جان‌ها چو بُگشایَنْد؛ بِفْشانَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1938392,2323,0,0,'سَمَن‌بویان، غُبارِ غَم چو بِنْشینَنْد؛ بِنْشانَنْد','زمانی که زیبارویانِ خوشبو در مجلسی می­‌نشینند، غبار غم و اندوه نیز در مجلس فرو می­‌نشیند، و زمانی که زیبارویان ناسازگاری می­‌کنند، آرام و قرار را از دل می­‌برند',NULL);
INSERT INTO "verses" VALUES(1938393,2323,0,1,'پَری‌رویان، قَرار از دِل چو بِسْتیزَنْد؛ بِسْتانَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1938394,2322,10,0,'گَر شَوَنْد آگَه از اَندیشِهٔ ما، مُغ‌بَچِگان','اگر مغبچگان از اندیشه ما آگاه شوند، بعد از این‌، صوفی را در خرابات نمی‌پذیرند.',NULL);
INSERT INTO "verses" VALUES(1938395,2322,10,1,'بَعْد اَز این، خِرْقِهٔ صوفی بِه گِرو نَسْتانَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1938396,2322,9,0,'زاهِد اَر رِنْدیِ «حافِظ» نَکُنَد فَهْم، چِه شُد؟','زاهد اگر رندی و نکته‌های حافظ را نمی‌فهمد (و او را سرزنش می‌کند) غیر از این نیست که دیوها نیز از آنان‌که قرآن می‌خوانند، می‌گریزند.',NULL);
INSERT INTO "verses" VALUES(1938397,2322,9,1,'دیو بُگْریزَد اَز آن قوم که قُرآن خوانَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1938398,2322,8,0,'گَر بِه نُزهَتْگَهِ اَرواح بَرَد بویِ تو، باد','اگر عطر خوش تو را باد به بهشت برساند در آنجا عقل و جان خود را به‌شکرانه می‌بخشند.',NULL);
INSERT INTO "verses" VALUES(1938399,2322,8,1,'عَقْل و جان، گوهَرِ هَسْتی به نِثار اَفشانَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1938400,2322,7,0,'مَگَرَم چَشْمِ سیاهِ تو بیاموزَد کار','مگر چشمان سیاه تو راهش را به‌من بیاموزد وگرنه نمی‌توانم مستی خود را پنهان کنم.',NULL);
INSERT INTO "verses" VALUES(1938401,2322,7,1,'وَرنَه مَسْتوری و مَسْتی، هَمِه‌کَس نَتْوانَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1938402,2322,6,0,'لافِ عِشْق و گِلِه از یار؟ زِهی لافِ دُروغ!','لاف عاشقی زدن و شکایت از جور یار‌، دو چیز با هم ناساز هستند کسانی‌که این‌چنین هستند لایق وصال نیستند.',NULL);
INSERT INTO "verses" VALUES(1938403,2324,2,0,'زِ زیرِ زُلْفِ دوتا چون گُذَر کُنی، بِنْگر','هوش مصنوعی: هرگاه از زیر دو زلف بگذری، نگاه کن که از سمت راست و چپ تو چه افرادی با دل‌سوزی و غم به تو چشم دوخته‌اند.',NULL);
INSERT INTO "verses" VALUES(1938404,2324,2,1,'کِه اَز یَمین و یَسارت چِه سوگواران‌اَنْد!',NULL,NULL);
INSERT INTO "verses" VALUES(1938405,2324,3,0,'گُذار کُن چو صَبا بَر بَنَفْشِه‌زار! و بِبین','هوش مصنوعی: با نرمی و لطافت مانند نسیم از کنار گل بنفشه عبور کن و تماشا کن که چقدر بی‌تابی و اضطراب به خاطر زیبایی و گیسوانت در دل‌ها ایجاد شده است.',NULL);
INSERT INTO "verses" VALUES(1938406,2324,3,1,'کِه اَز تَطاوُلِ زُلْفَت چِه بی‌قَراران‌اَنْد!',NULL,NULL);
INSERT INTO "verses" VALUES(1938407,2325,9,0,'بگذر به کویِ میکده تا زُمرِهٔ حضور','هوش مصنوعی: به محلهٔ میکده برو تا گروهی از مردم به خاطر تو دعا و آرزو کنند.',NULL);
INSERT INTO "verses" VALUES(1938408,2325,9,1,'اوقاتِ خود ز بهر تو صرفِ دعا کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938409,2325,8,0,'پیراهنی که آید از او بویِ یوسفم','پیراهنی که از آن بوی یوسف می‌آید، نگرانم که برادران حسودش آن [پیراهن] را پاره کنند.',NULL);
INSERT INTO "verses" VALUES(1938410,2325,8,1,'ترسم برادران غَیورش قَبا کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938411,2325,7,0,'مِی خور که صد گناه ز اغیار در حجاب','هوش مصنوعی: از شراب بنوش که اشتباهات و گناهان دیگران در پس پرده بهتر است از عبادتی که به خاطر نمایش و ریا انجام شود.',NULL);
INSERT INTO "verses" VALUES(1938412,2325,7,1,'بهتر ز طاعتی که به روی و ریا کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938413,2325,6,0,'گر سنگ از این حدیث بنالد عجب مدار','اگر سنگ هم از این داستان ناراحت شود، شگفت‌زده نشو، زیرا صاحبدلان داستان دل را به زیبایی بیان می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1938414,2325,6,1,'صاحبدلان حکایتِ دل خوش ادا کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938415,2325,5,0,'حالی درونِ پرده بسی فتنه می‌رود','هوش مصنوعی: وضعیت درونی پر از آشوب و ناآرامی است و تا زمانی که پرده افکنده نشده، نمی‌توان فهمید که چه مسائل و حوادثی پیش خواهد آمد.',NULL);
INSERT INTO "verses" VALUES(1938416,2325,5,1,'تا آن زمان که پرده برافتد چه‌ها کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938417,2325,4,0,'بی معرفت مباش که در من‌یزیدِ عشق','بی معرفت نباش چون در مزایده عشق، اهل نظر فقط با آشنایان معامله می کنند',NULL);
INSERT INTO "verses" VALUES(1938418,2325,4,1,'اهلِ نظر معامله با آشنا کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938419,2325,3,0,'چون حُسنِ عاقبت نه به رندی و زاهدی‌ست','هوش مصنوعی: زیبایی پایانی کار نه به تلاش‌های رندانه یا زاهدانه بستگی دارد؛ بلکه بهتر است که انسان کارهای خود را به دست لطف و رحمت الهی بسپارد و از آن آزاد بگذارد.',NULL);
INSERT INTO "verses" VALUES(1938420,2325,3,1,'آن بِه که کارِ خود به عنایت رها کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938421,2325,10,1,'خیرِ نهان برایِ رضایِ خدا کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938422,2325,2,0,'معشوق چون نقاب ز رخ درنمی‌کشد','هوش مصنوعی: وقتی معشوق چهره‌اش را نمایان نمی‌کند، چرا هر کسی داستانی برای خود تصور کند؟',NULL);
INSERT INTO "verses" VALUES(1938423,2325,1,0,'دَردَم نهفته بِه ز طبیبانِ مدعی','درد من پنهان بماند بهتر از این است که به پزشک‌هایی رجوع کنم که فقط ادعا دارند؛ امید است که مرا از عالم غیب درمان کنند.',NULL);
INSERT INTO "verses" VALUES(1938424,2325,1,1,'باشد که از خزانهٔ غیبم دوا کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938425,2325,0,0,'آنان که خاک را به نظر کیمیا کنند','آنان که خاک را با نگاهی به طلا تبدیل می‌کنند، آیا ممکن است نگاهی هم به ما بیندازند؟',NULL);
INSERT INTO "verses" VALUES(1938426,2325,0,1,'آیا بُوَد که گوشهٔ چشمی به ما کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938427,2324,8,0,'خَلاصِ «حافِظ» از آن زُلْفِ تابدار مَباد!','هوش مصنوعی: حافظ از دست زلف‌های پیچیده و جذاب تو رهایی نمی‌خواهد، زیرا آن افرادی که در دام تو افتاده‌اند، افراد نیکوکار و رستگار هستند.',NULL);
INSERT INTO "verses" VALUES(1938428,2324,8,1,'کِه بَسْتِگانِ کَمَنْدِ تو، رَسْتگاران‌اَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1938429,2324,7,0,'بیا به مِیکَدِه! و چِهْرِه، اَرغَوانی کُن!','هوش مصنوعی: بیایید به میکده برویم و از زیبایی لذت ببریم، زیرا در صومعه تنها افرادی هستند که پیوندی با سیاهی و بدی دارند.',NULL);
INSERT INTO "verses" VALUES(1938430,2324,7,1,'مَرو بِه صومَعِه کآنجا سیاه‌کاران‌اَنْد!',NULL,NULL);
INSERT INTO "verses" VALUES(1938431,2324,6,0,'تو دَسْتگیر شو! اِی خِضْرِ پِی‌خُجَسْتِه! کِه مَن','هوش مصنوعی: ای خضرِ خوش‌قدم، تو به من کمک کن، چرا که من پیاده می‌روم و همراهانم سوار بر اسب‌ها هستند.',NULL);
INSERT INTO "verses" VALUES(1938432,2324,6,1,'پیادِه می‌رَوَم و هَمْرَهان، سَواران‌اَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1938433,2324,5,0,'نَه مَن بر آن گُلِ عارِض، غَزَل سُرایم و بَس','هوش مصنوعی: من فقط برای زیبایی چهره‌ات شعر می‌گویم، چرا که پرندگان عاشق تو از هر سو بسیارند.',NULL);
INSERT INTO "verses" VALUES(1938434,2324,5,1,'که عَنْدَلیبِ تو اَز هَر طَرَف، هزاران‌اَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1938435,2324,4,0,'نَصیبِ ماست بِهِشْت، اِی خُداشِناس! بُرو!','هوش مصنوعی: ای خداشناس، بهشت نصیب ماست، زیرا ما هم گناهکارانی هستیم که سزاوار بخشش و کرامت تو هستیم.',NULL);
INSERT INTO "verses" VALUES(1938436,2324,4,1,'کِه مُستَحَقِّ کِرامَت، گُناهکاران‌اَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1938437,2325,2,1,'هر کس حکایتی به تَصوّر چرا کنند؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938438,2353,7,0,'تو کز مکارمِ اخلاق عالَمی دگری','تو که کریم و بخشنده و با اخلاقی و از کرامت های اخلاقی بهره مندی، لطفا فراموش نکن که به عهدی که با من بستی وفا کنی',NULL);
INSERT INTO "verses" VALUES(1938439,2329,6,0,'صد مُلکِ دل به نیم نظر می‌توان خرید','با یک نگاه کوتاه می‌توانیم قلب‌ها را به دست آوریم. در این معامله، زیبایی‌ها به نحوی کوتاهی می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1938440,2329,7,0,'قومی به جِدّ و جهد نهادند وصلِ دوست','گروهی با تلاش و کوشش به دنبال رسیدن به دوستی و ارتباط نزدیک هستند، در حالی که گروه دیگری به سرنوشت و تقدیر خود بسنده کرده و اوضاع را به حال خود رها کرده‌اند.',NULL);
INSERT INTO "verses" VALUES(1938450,2334,6,0,'بختِ حافظ گر از این گونه مدد خواهد کرد','هوش مصنوعی: اگر بخت حافظ به این شکل یاری کند، موهای محبوب در اختیار دیگران خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1938451,2334,6,1,'زلفِ معشوقه به دستِ دگران خواهد بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938452,2334,5,0,'چشمم آن دَم که ز شوقِ تو نَهَد سر به لَحَد','هوش مصنوعی: چشمانم در آن لحظه که از عشق تو سر بر خاک می‌گذارم، تا روز قیامت، بی‌وقفه نگران تو خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1938453,2334,5,1,'تا دَمِ صبحِ قیامت نگران خواهد بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938454,2334,4,0,'تُرکِ عاشق‌کُشِ من مست برون رفت امروز','معشوق من، امروز مست (و مستانه) به بیرون از خانه (به کوی و گذر و میان مردم) رفت. یعنی چشمان چند نفر با دیدن زیبایی و دل‌فریبی او خون بار خواهد شد؟',NULL);
INSERT INTO "verses" VALUES(1938455,2334,4,1,'تا دگر خونِ که از دیده روان خواهد بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938456,2334,3,0,'برو ای زاهدِ خودبین که ز چشمِ من و تو','هوش مصنوعی: ای زاهد خودپسند، دور شو. چرا که راز این پرده از نظر من و تو پنهان است و همیشه پنهان خواهد ماند.',NULL);
INSERT INTO "verses" VALUES(1938457,2334,3,1,'رازِ این پرده نهان است و نهان خواهد بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938458,2334,2,0,'بر سرِ تربتِ ما چون گذری همّت خواه','هوش مصنوعی: وقتی از کنار قبر ما عبور می‌کنی، با اراده و نیت درست عبور کن، زیرا این مکان در آینده مورد توجه و زیارت اهل دل و عاشقان دنیا قرار خواهد گرفت.',NULL);
INSERT INTO "verses" VALUES(1938459,2334,2,1,'که زیارتگَهِ رِندانِ جهان خواهد بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938460,2334,1,0,'حلقهٔ پیرِ مغان از ازلم در گوش است','پیروی از زرتشت کامل از ابتدا در ضمیر من بوده و همچنان خواهد بود. این پیر فرزانه می تواند حضرت زرتشت باشد که در واژه هم پیشوا و رهنمای موبدان زرتشتی ست.',NULL);
INSERT INTO "verses" VALUES(1938461,2334,1,1,'بر همانیم که بودیم و همان خواهد بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938462,2334,0,0,'تا ز میخانه و مِی نام و نشان خواهد بود','تا وقتی که از میخانه و نوشیدن شراب خبری باشد، سرنوشت ما مانند خاکی خواهد بود که در راه زرتشت افتاده است.',NULL);
INSERT INTO "verses" VALUES(1938463,2334,0,1,'سرِ ما خاکِ رَهِ پیرِ مُغان خواهد بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938464,2333,8,0,'یاد باد آن که به اصلاحِ شما می‌شد راست','هوش مصنوعی: به یاد بیاورید که در زمانی، کسی بود که به کمک شما، نظم و ترتیب می‌بخشید به هر گوهری که هنوز کشف نشده بود و حافظ به او تعلق داشت.',NULL);
INSERT INTO "verses" VALUES(1938465,2333,8,1,'نظمِ هر گوهرِ ناسُفته که حافظ را بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938466,2333,7,0,'یاد باد آن که خرابات نشین بودم و مست','هوش مصنوعی: به یاد می‌آورم روزهایی را که در میخانه نشسته و سرمست بودم و همه چیزهایی که اکنون در مسجد من کم است، در آنجا وجود داشت.',NULL);
INSERT INTO "verses" VALUES(1938467,2333,7,1,'وآنچه در مسجدم امروز کم است آنجا بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938468,2333,6,0,'یاد باد آن که نگارم چو کمر بَربَستی','هوش مصنوعی: به یاد می‌آورم زمانی را که معشوقم همچون کمر بسته‌ای، در کنار خود ستاره‌ای درخشان و نو را داشتم که همچون راهنمایی در جهان حرکت می‌کرد.',NULL);
INSERT INTO "verses" VALUES(1938469,2333,6,1,'در رکابش مَهِ نو پیکِ جهان پیما بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938474,2337,2,1,'تیره آن دل که در او شمعِ محبت نبود',NULL,NULL);
INSERT INTO "verses" VALUES(1938475,2337,1,0,'ما جفا از تو ندیدیم و تو خود نَپْسَندی','هوش مصنوعی: ما از تو هیچ بدی ندیدیم، و تو خود آنچه که در مسیر پیشوایان طریقت پسندیده نیست را نمی‌پسندی.',NULL);
INSERT INTO "verses" VALUES(1938476,2337,1,1,'آنچه در مذهبِ اربابِ طریقت نبود',NULL,NULL);
INSERT INTO "verses" VALUES(1938477,2337,0,0,'خستگان را چو طلب باشد و قُوَّت نَبُوَد','هوش مصنوعی: اگر افرادی خسته و درمانده، خواسته‌ای داشته باشند اما قدرت انجام آن را نداشته باشند، تو اگر ظلم و ستم کنی، دیگر نشانه‌ای از جوانمردی در تو نخواهد بود.',NULL);
INSERT INTO "verses" VALUES(1938478,2337,0,1,'گر تو بیداد کنی شرطِ مُروَّت نَبُوَد',NULL,NULL);
INSERT INTO "verses" VALUES(1938479,2336,8,0,'دیدی آن قهقههٔ کبکِ خِرامان حافظ؟','دیدی آن صدای شاد و خوش کبک‌های زیبا را که از سرنوشت و خطرات ناآگاه بودند؟',NULL);
INSERT INTO "verses" VALUES(1938480,2336,8,1,'که ز سرپنجهٔ شاهینِ قضا غافل بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938481,2336,7,0,'راستی خاتمِ فیروزهٔ بواسحاقی','هوش مصنوعی: واقعاً انگشتر فیروزه‌ای بواسحاقی زیبا و درخشان بود، اما بخت و اقبال، زودگذری داشت.',NULL);
INSERT INTO "verses" VALUES(1938482,2336,7,1,'خوش درخشید ولی دولتِ مُستَعجِل بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938483,2336,6,0,'بس بِگَشتَم که بپرسم سببِ دردِ فِراق','هوش مصنوعی: من به دنبال پاسخ برای دلیل درد جدایی گشتم، اما عقل در این موضوع نتوانست چیزی بگوید.',NULL);
INSERT INTO "verses" VALUES(1938484,2336,6,1,'مفتیِ عقل در این مسأله لایَعْقِل بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938485,2336,5,0,'دوش بر یادِ حریفان به خرابات شدم','شب گذشته به یاد دوستانم به میخانه رفتم. در آنجا ظرف شراب را دیدم که دل پر خون داشت (کنایه از این است که خمره پر از شراب بود) و پایش در گل فرو رفته بود',NULL);
INSERT INTO "verses" VALUES(1938486,2336,5,1,'خُمِ مِی دیدم، خون در دل و پا در گل بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938487,2336,4,0,'در دلم بود که بی‌دوست نباشم هرگز','هوش مصنوعی: در دل داشتم که هرگز بدون دوست نباشم، اما چه کار می‌توانم بکنم؟ که تلاش و آرزوی من بی‌ثمر بود.',NULL);
INSERT INTO "verses" VALUES(1938488,2333,5,0,'یاد باد آن که چو یاقوتِ قدح خنده زدی','هوش مصنوعی: به خاطر می‌آورم وقتی که تو همچون یاقوتی در میان من و لب‌های زیبات حکایت‌هایی را با خنده گفتی.',NULL);
INSERT INTO "verses" VALUES(1938489,2336,4,1,'چه توان کرد؟ که سعیِ من و دل باطل بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938490,2336,3,0,'آه از آن جور و تَطاول که در این دامگَه است','هوش مصنوعی: آه، از آن ظلم و بی‌رحمی که در این مکان وجود دارد. آه، از آن درد و نیازی که در آن محفل به چشم می‌خورد.',NULL);
INSERT INTO "verses" VALUES(1938491,2336,2,0,'دل چو از پیرِ خِرَد نَقلِ مَعانی می‌کرد','هوش مصنوعی: وقتی دل از تجربه‌های حکیمانه صحبت می‌کرد، عشق هم به بیان احساسی می‌پرداخت که برای او دشوار بود.',NULL);
INSERT INTO "verses" VALUES(1938492,2336,2,1,'عشق می‌گفت به شرح آن‌چه بر او مشکل بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938493,2336,1,0,'راست چون سوسن و گل از اثرِ صحبتِ پاک','هوش مصنوعی: گفتار من مثل سوسن و گل زیباست، زیرا که صحبت پاکی داشتم. آن‌چه در دل توست، در کلام من نمایان شده است.',NULL);
INSERT INTO "verses" VALUES(1938494,2336,1,1,'بر زبان بود مرا آن‌چه تو را در دل بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938495,2336,0,0,'یاد باد آن که سرِ کویِ توام منزل بود','هوش مصنوعی: یاد آن روزها به خیر که در کوی تو زندگی می‌کردم و چشمم روشنی‌اش را از خاک درگاه تو می‌گرفت.',NULL);
INSERT INTO "verses" VALUES(1938496,2336,0,1,'دیده را روشنی از خاکِ درت حاصل بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938504,2336,3,1,'آه از آن سوز و نیازی که در آن محفل بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938505,2329,6,1,'خوبان در این معامله تقصیر می‌کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938506,2333,5,1,'در میانِ من و لعلِ تو حکایت‌ها بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938507,2333,4,0,'یاد باد آن که در آن بزمگَهِ خُلق و ادب','هوش مصنوعی: به یاد آید آن زمان که در مهمانی آراستگی و اخلاق، تو با لبخند شاداب و مستانه‌ات، همچون کسی که مست از شراب است، حضورت را به یاد می‌آورم.',NULL);
INSERT INTO "verses" VALUES(1938508,2331,2,0,'به صفایِ دلِ رندانِ صَبوحی‌زدگان','هوش مصنوعی: رندان سالخورده و خوش‌ذوق با پاکی دل خود، درهای بسته را با دعا و نیایش به روی خود باز می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1938509,2331,2,1,'بس درِ بسته به مِفْتاحِ دعا بگشایند',NULL,NULL);
INSERT INTO "verses" VALUES(1938510,2331,1,0,'اگر از بهرِ دلِ زاهدِ خودبین بستند','اگر به خاطر خودخواهی زاهد در میخانه را بستند، خیالت راحت باشد زیرا به خاطر خدا آن را باز خواهند کرد.',NULL);
INSERT INTO "verses" VALUES(1938511,2331,1,1,'دل قوی دار که از بهرِ خدا بگشایند',NULL,NULL);
INSERT INTO "verses" VALUES(1938512,2331,0,0,'بُوَد آیا که درِ میکده‌ها بگشایند؟','هوش مصنوعی: آیا ممکن است درهای میکده‌ها را برای ما باز کنند و مشکلات و سختی‌های ما را حل کنند؟',NULL);
INSERT INTO "verses" VALUES(1938513,2331,0,1,'گره از کارِ فروبستهٔ ما بگشایند؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938514,2330,8,0,'جنابِ عشق بلند است همّتی حافظ','هوش مصنوعی: عشق مقام و ارادت بلندی دارد و حافظ می‌گوید که عاشقان واقعی نباید به مسیری بروند که دیگران در آن نیستند و از همت خود دست برندارند.',NULL);
INSERT INTO "verses" VALUES(1938515,2330,8,1,'که عاشقان، رَه بی‌همّتان به خود ندهند',NULL,NULL);
INSERT INTO "verses" VALUES(1938516,2330,7,0,'قدم مَنِه به خرابات جز به شرطِ ادب','هوش مصنوعی: به این مکان خراب و بی‌نظم نرو مگر اینکه آداب و رسوم را رعایت کنی، زیرا کسانی که در اینجا حضور دارند، افرادی نزدیک به پادشاهی هستند و باید با احترام و ادب برخورد شود.',NULL);
INSERT INTO "verses" VALUES(1938517,2330,7,1,'که سالکانِ درش محرمانِ پادشهند',NULL,NULL);
INSERT INTO "verses" VALUES(1938518,2330,6,0,'غلامِ همَّتِ دُردی کشانِ یک رنگم','هوش مصنوعی: من به خدمت‌گزاران اهل همت و تلاش علاقه‌مندم، نه به آن دسته از افرادی که ظاهرشان زیباست اما درونشان تاریک و بدخواه است.',NULL);
INSERT INTO "verses" VALUES(1938519,2330,6,1,'نه آن گروه که اَزْرَق لباس و دل سیَهَند',NULL,NULL);
INSERT INTO "verses" VALUES(1938520,2330,5,0,'مَکُن که کوکبهٔ دلبری شکسته شود','هوش مصنوعی: نگران نباش که محبوبی که دل‌ها را می‌رباید از بین برود، چون وقتی که مردم از او دور شوند و خدمتکارانش فرار کنند، دیگر هیچ چیزی از زیبایی و جذابیت او باقی نخواهد ماند.',NULL);
INSERT INTO "verses" VALUES(1938521,2330,5,1,'چو بندگان بِگُریزند و چاکران بِجَهَند',NULL,NULL);
INSERT INTO "verses" VALUES(1938522,2330,4,0,'به هوش باش که هنگامِ بادِ اِستغنا','هوش مصنوعی: مواظب باش که در زمان بی‌نیازی و خودکفایی، ممکن است همه زحمت‌ها و عبادت‌هایت بی‌ارزش شود و به قیمتی بسیار ناچیز تبدیل گردد.',NULL);
INSERT INTO "verses" VALUES(1938523,2330,4,1,'هزار خرمنِ طاعت به نیمْ جو ننهند',NULL,NULL);
INSERT INTO "verses" VALUES(1938524,2330,3,0,'مَبین حقیر، گدایانِ عشق را کاین قوم','هوش مصنوعی: نشان نده که من انسان کوچکی هستم، چرا که عاشقان، کم‌عرض و بی‌قدرت هستند و این افراد کسانی هستند که بدون اقتدار و اصل و نسب، خود را به شاهان نزدیک می‌دانند.',NULL);
INSERT INTO "verses" VALUES(1938525,2330,3,1,'شَهانِ بی کمر و خسروانِ بی کُلَهند',NULL,NULL);
INSERT INTO "verses" VALUES(1938526,2330,2,0,'جفا نه پیشهٔ درویشیَست و راهرُوی','هوش مصنوعی: آسیب و درد به سبک زندگی درویشی مناسب نیست و مدعیان سیر و سلوک نیاز به شراب حقیقت دارند، زیرا این عابدان واقعی در مسیر خود قرار ندارند.',NULL);
INSERT INTO "verses" VALUES(1938527,2330,2,1,'بیار باده که این سالکان نَه مردِ رهند',NULL,NULL);
INSERT INTO "verses" VALUES(1938528,2330,1,0,'من ار چه عاشقم و رند و مست و نامه سیاه','هوش مصنوعی: با وجود اینکه من عاشق، بازیگوش و شیدا هستم و در دل زخم‌هایی دارم، اما هزاران بار شکرگزارم که دوستان این شهر بی‌گناه و پاک‌اند.',NULL);
INSERT INTO "verses" VALUES(1938529,2330,1,1,'هزار شُکر که یارانِ شهر بی‌گنهند',NULL,NULL);
INSERT INTO "verses" VALUES(1938530,2330,0,0,'شرابِ بی‌غَش و ساقیِّ خوش دو دامِ رهند','هوش مصنوعی: شراب خالص و ساقی دل‌نشین دو فریبنده هستند که افراد زیرک و هوشمند جهان نمی‌توانند از چنگال آن‌ها فرار کنند.',NULL);
INSERT INTO "verses" VALUES(1938531,2330,0,1,'که زیرکانِ جهان از کمندشان نَرَهَند',NULL,NULL);
INSERT INTO "verses" VALUES(1938532,2329,9,0,'مِی خور که شیخ و حافظ و مفتی و محتسب','نوشیدن شراب را تجربه کن، زیرا اگر به دقت نگاه کنی، می‌بینی که روحانیان، حافظان قرآن و مسئولان دینی همگی در رفتارهای خود فریبکاری و دوگانگی دارند.',NULL);
INSERT INTO "verses" VALUES(1938533,2329,9,1,'چون نیک بنگری همه تزویر می‌کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938534,2329,8,0,'فِی‌الجُمله اعتماد مکُن بر ثباتِ دهر','به طور کلی به ثبات و پایداری روزگار اتکا نکن، زیرا این دنیا مانند کارگاهی است که دائماً دستخوش تغییرات می‌شود.',NULL);
INSERT INTO "verses" VALUES(1938535,2329,8,1,'کـ‌این کارخانه‌ایست که تغییر می‌کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938536,2329,7,1,'قومی دگر حواله به تقدیر می‌کنند',NULL,NULL);
INSERT INTO "verses" VALUES(1938537,2331,3,0,'نامهٔ تَعزیَتِ دختر رَز بِنْویسید','مرگِ دخترِ رَز(شراب) کنایه از بسته شدن میخانه و محروم شدن از شراب است؛ شاعر با اغراق می‌گوید این فقدان چنان سنگین است که مغبچگان نیز به رسم سوگواری زلف‌های خود را می‌گشایند.».',NULL);
INSERT INTO "verses" VALUES(1938538,2331,3,1,'تا همه مُغبَچِگان زلفِ دوتا بگشایند',NULL,NULL);
INSERT INTO "verses" VALUES(1938539,2331,4,0,'گیسوی چنگ بِبُرّید به مرگِ مِیِ ناب','به مناسبتِ مرگِ شرابِ ناب، سازِ چنگ را به نوای عزا درآورید،تا یاران از شدت اندوه، چون عزاداران، اشکِ خون‌گون بریزند.',NULL);
INSERT INTO "verses" VALUES(1938540,2331,4,1,'تا حریفان همه خون از مژه‌ها بگشایند',NULL,NULL);
INSERT INTO "verses" VALUES(1938541,2333,3,0,'یاد باد آن که رُخَت شمعِ طَرَب می‌افروخت','هوش مصنوعی: یاد آن روزها بخیر که روی تو مانند شمعی نور می‌افشاند و این دل سوخته هم مانند پروانه‌ای بی‌پروا به دور آن می‌چرخید.',NULL);
INSERT INTO "verses" VALUES(1938542,2333,3,1,'وین دلِ سوخته پروانهٔ ناپروا بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938543,2333,2,0,'یاد باد آن که صَبوحی زده در مجلسِ انس','هوش مصنوعی: به یاد می‌آورم آن لحظه‌ای را که صبحی در محفل دوستان گذراندم و تنها من و معشوق بودیم و خدا نیز در کنارمان حضور داشت.',NULL);
INSERT INTO "verses" VALUES(1938544,2333,2,1,'جز من و یار نبودیم و خدا با ما بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938545,2333,1,0,'یاد باد آن که چو چَشمت به عِتابم می‌کُشت','هوش مصنوعی: به یاد بیاور آن زمانی که نگاه پرعاطفه‌ات با خشم و غضب جانم را به لب مرگ می‌رساند، همان‌طور که معجزه عیسی مسیح در لب شکری و زیبایی حضور داشت.',NULL);
INSERT INTO "verses" VALUES(1938546,2333,1,1,'مُعْجِزِ عیسَویَت در لبِ شِکَّرخا بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938547,2333,0,0,'یاد باد آن که نَهانَت نظری با ما بود','هوش مصنوعی: به یاد دارم که زمانی نگاه پنهانی تو به ما بود و محبت تو بر چهره‌ ما نمایان بود.',NULL);
INSERT INTO "verses" VALUES(1938548,2333,0,1,'رَقَمِ مِهرِ تو بر چهرهٔ ما پیدا بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938549,2332,8,0,'قلبِ اندودهٔ حافظ بَرِ او خرج نشد','هوش مصنوعی: قلب حافظ که پر از احساس و عشق بود، بی‌فایده خرج نشد، چون این معامله‌گر همه‌ی نواقص را می‌دید و به خوبی آگاه بود.',NULL);
INSERT INTO "verses" VALUES(1938550,2332,8,1,'کاین مُعامِل به همه عیبِ نهان بینا بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938551,2332,7,0,'پیرِ گلرنگِ من اندر حقِ اَزْرَق‌پوشان','هوش مصنوعی: دلاور و با تجربه‌ی من اجازه نداد تا به کسانی که لباس‌های آبی می‌پوشند، بدی را روا بدارم، هرچند که داستان‌هایی در این‌باره وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1938552,2332,7,1,'رخصتِ خُبث نداد ار نه حکایت‌ها بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938553,2332,6,0,'می‌شکفتم ز طرب زان که چو گُل بر لبِ جوی','هوش مصنوعی: من از شادی و خوشی می‌بالیدم، زیرا مثل گلی که بر لبه‌ی جوی آب رشد می‌کند، سایه‌ی آن سرو بلند بالای زیبا بر سرم بود.',NULL);
INSERT INTO "verses" VALUES(1938554,2332,6,1,'بر سرم سایهٔ آن سروِ سَهی بالا بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938555,2333,4,1,'آن که او خندهٔ مستانه زدی صَهبا بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938556,2332,5,0,'مُطرب از دَردِ محبت عملی می‌پرداخت','هوش مصنوعی: مُطرب از احساسات عاطفی و عشق، کاری انجام می‌داد که حتی دانشمندان و حکما را تحت تأثیر قرار می‌داد و به حالت حیرت و شگفتی می‌انداخت.',NULL);
INSERT INTO "verses" VALUES(1938557,2332,4,0,'دل چو پرگار به هر سو دَوَرانی می‌کرد','هوش مصنوعی: دل مانند پرگاری بود که به هر سمت در حرکت بود و در درون دایره‌ای ثابت، سرگردان و بی‌قرار به نظر می‌رسید.',NULL);
INSERT INTO "verses" VALUES(1938558,2332,4,1,'و اندر آن دایره سرگشتهٔ پابرجا بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938559,2332,3,0,'از بتان آن طلب ار حسن شناسی ای دل','هوش مصنوعی: اگر می‌خواهی زیبایی را بشناسی و درک کنی، باید از بت‌ها (عشق‌ها و معشوق‌ها) طلب کنی؛ زیرا کسی گفت که در دانش و بینش، بینا و آگاه است.',NULL);
INSERT INTO "verses" VALUES(1938560,2332,3,1,'کاین کسی گفت که در علمِ نظر بینا بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938561,2332,2,0,'دفترِ دانش ما جمله بشویید به مِی','هوش مصنوعی: همه‌ی مطالب علمی و دانش‌های خود را با شادی و شادی بخشیدن به‌صورت نوشیدنی و لذت بخش پاک کنید، زیرا من آسمان را دیدم و می‌خواستم به دل حکیمی نزدیک شوم.',NULL);
INSERT INTO "verses" VALUES(1938562,2332,2,1,'که فلک دیدم و در قصدِ دلِ دانا بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938563,2332,1,0,'نیکیِ پیرِ مغان بین که چو ما بدمستان','هوش مصنوعی: نیکی مرد دانا را ببین، که او همواره ما را به چشم مهربانی می‌نگرد و همه کارهایی که انجام داده‌ایم، در نظر او زیبا و پسندیده است.',NULL);
INSERT INTO "verses" VALUES(1938564,2332,1,1,'هر چه کردیم به چشمِ کَرَمَش زیبا بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938565,2332,0,0,'سال‌ها دفترِ ما در گرو صَهبا بود','سال‌ها دفتر زندگی ما به شراب وابسته بود و رونق میکده به سبب نیایش ها و دعاهای ما شکل می‌گرفت.',NULL);
INSERT INTO "verses" VALUES(1938566,2332,0,1,'رونقِ می‌کده از درس و دعایِ ما بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938567,2331,6,0,'حافظ این خرقه که داری تو ببینی فردا','ای حافظ، این خرقه‌ی زهدی که بر تن داری، فردا خواهی دید که زیر آن چه زنّارِ (کمربند غیر مسلمانان، بخصوص زرتشتیان و مسیحیان) کفرآمیزی را با فریب و نیرنگ پنهان کرده‌اند.',NULL);
INSERT INTO "verses" VALUES(1938568,2331,6,1,'که چه زُنّار ز زیرش به دَغا بگشایند',NULL,NULL);
INSERT INTO "verses" VALUES(1938569,2331,5,0,'درِ میخانه ببستند خدایا مپسند','خدایا، روا مدار که درِ میخانه را ببندندو در عوض، درِ خانه‌های ریا و دورویی را باز بگذارند.',NULL);
INSERT INTO "verses" VALUES(1938570,2331,5,1,'که درِ خانهٔ تزویر و ریا بگشایند',NULL,NULL);
INSERT INTO "verses" VALUES(1938571,2332,5,1,'که حکیمانِ جهان را مژه خون پالا بود',NULL,NULL);
INSERT INTO "verses" VALUES(1938572,2322,6,1,'عِشْق‌بازانِ چُنین، مُسْتَحَقِ هِجْران‌اَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1938573,2353,7,1,'وفایِ عهدِ من از خاطرت به در نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938574,2353,8,1,'چگونه چون قلمم دودِ دل به سر نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938575,2375,3,1,'کان نیز بر کرشمهٔ ساقی کُنم نثار',NULL,NULL);
INSERT INTO "verses" VALUES(1938576,2375,3,0,'جز نقدِ جان به دست ندارم شراب کو؟','هوش مصنوعی: جز جانم چیزی برای دادن ندارم، شراب کجاست؟ زیرا من هم آماده‌ام تا جانم را به خاطر زیبایی‌های ساقی نثار کنم.',NULL);
INSERT INTO "verses" VALUES(1938577,2375,2,1,'از فیض جام و قصهٔ جمشیدِ کامگار',NULL,NULL);
INSERT INTO "verses" VALUES(1938578,2375,2,0,'دل در جهان مَبَند و به مستی سؤال کن','به دنیا دل مبند و خوش باش و در حال خوشی و مستی‌، از لطف جام جهان‌بین بپرس و حکایت جمشید فیروزمند و کامگار را بشنو.',NULL);
INSERT INTO "verses" VALUES(1938579,2375,1,1,'کاری بِکَرد همّت پاکانِ روزه دار',NULL,NULL);
INSERT INTO "verses" VALUES(1938580,2375,1,0,'دل برگرفته بودم از ایّام گُل، ولی','از باده‌نوشی در فصل گل و بهار ناامید شده بودم اما همّت و دعای پاکان روزه‌دار کاری کرد. (احتمالا سرودن این غزل در سالی بوده که ماه رمضان مصادف با اواخر فصل بهار بوده است)',NULL);
INSERT INTO "verses" VALUES(1938581,2375,0,1,'ساقی به رویِ شاه ببین ماه و مِی بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1938582,2375,0,0,'عید است و آخِرِ گُل و یاران در انتظار','عید (روزه‌گشایی است) و آخر فصل بهار است و یاران در انتظار مجلس باده‌نوشی و عیش پس ای ساقی به روی ماه و زیبای شاه بنگر (عید را اعلام کن) و باده بیاور.',NULL);
INSERT INTO "verses" VALUES(1938583,2374,11,1,'خداوندا ز آفاتش نگه دار',NULL,NULL);
INSERT INTO "verses" VALUES(1938584,2374,11,0,'خداوندی به جایِ بندگان کرد','هوش مصنوعی: خداوند به جای بندگان خود، برتری و مقام بالایی قرار داده است. ای خدا، آن‌ها را از آسیب‌ها و خطرات محفوظ بدار.',NULL);
INSERT INTO "verses" VALUES(1938585,2374,10,1,'عَلَم شد حافظ اندر نظمِ اشعار',NULL,NULL);
INSERT INTO "verses" VALUES(1938586,2374,10,0,'به یُمنِ دولتِ منصور شاهی','هوش مصنوعی: به برکت و لطف حکومت منصور، حافظ در سرایش شعرها نامدار و مشهور شد.',NULL);
INSERT INTO "verses" VALUES(1938587,2374,9,1,'حدیثِ جان مگو با نقشِ دیوار',NULL,NULL);
INSERT INTO "verses" VALUES(1938588,2374,9,0,'به مستور‌ان مگو اسرارِ مستی','هوش مصنوعی: به پنهان‌کاران از رازهای مستی نگو، و داستان جان را بر دیوار نگذارش.',NULL);
INSERT INTO "verses" VALUES(1938589,2374,8,1,'خداوندا دل و دینم نگه دار',NULL,NULL);
INSERT INTO "verses" VALUES(1938590,2374,8,0,'بُتِ چینی عدویِ دین و دل‌هاست','هوش مصنوعی: مجسمه‌های چینی دشمن دین و احساسات انسانی هستند. خداوندا، از تو می‌خواهم که دل و عقیده‌ام را حفظ کنی.',NULL);
INSERT INTO "verses" VALUES(1938591,2374,7,1,'به لفظِ اندک و معنیِ بسیار',NULL,NULL);
INSERT INTO "verses" VALUES(1938592,2374,7,0,'بیا و حالِ اهلِ درد بشنو','هوش مصنوعی: بیایید و حال کسانی را که در درد و رنج هستند بشنوید، با کلماتی کم اما معنایی عمیق.',NULL);
INSERT INTO "verses" VALUES(1938593,2374,6,1,'به زور و زر مُیَسَّر نیست این کار',NULL,NULL);
INSERT INTO "verses" VALUES(1938594,2374,6,0,'سِکَندَر را نمی‌بخشند آبی','هوش مصنوعی: سکندر به خاطر داشتن قدرت و ثروت نمی‌تواند همه چیز را به دست آورد، زیرا دستیابی به برخی چیزها آسان نیست و نمی‌توان با زور و پول همه چیز را خرید.',NULL);
INSERT INTO "verses" VALUES(1938595,2374,5,1,'حریفان را نه سَر مانَد، نه دَستار',NULL,NULL);
INSERT INTO "verses" VALUES(1938596,2374,5,0,'از آن افیون که ساقی در مِی افکند','هوش مصنوعی: از آن شرابی که ساقی در لیوان می‌ریزد، حریفان نه سَر دارند و نه دستار.',NULL);
INSERT INTO "verses" VALUES(1938597,2374,4,1,'که می‌رقصند با هم مست و هشیار',NULL,NULL);
INSERT INTO "verses" VALUES(1938598,2374,4,0,'چه رَه بود این که زد در پرده مطرب؟','هوش مصنوعی: چه رازی در این است که مطرب پرده را کنار زده است؟ که در آن حال، مست و هشیار به هم می‌رقصند.',NULL);
INSERT INTO "verses" VALUES(1938599,2374,3,1,'که خواب‌آلوده‌ایم، ای بختِ بیدار!',NULL,NULL);
INSERT INTO "verses" VALUES(1938600,2374,3,0,'به رویِ ما زن از ساغر گلابی','هوش مصنوعی: برای ما از جام گلاب بریز، ما در رویای شیرین و خواب‌آلودیم، ای خوب بخت بیدار.',NULL);
INSERT INTO "verses" VALUES(1938601,2374,2,1,'خدا را زین معما پرده بردار',NULL,NULL);
INSERT INTO "verses" VALUES(1938602,2374,2,0,'سخن سربسته گفتی با حریفان','هوش مصنوعی: با دوستانت به طرز اشاره‌آمیز سخن گفتی، حالا از خدا بخواه تا این راز را برایت روشن کند.',NULL);
INSERT INTO "verses" VALUES(1938603,2374,1,1,'که خوش نقشی نمودی از خطِ یار',NULL,NULL);
INSERT INTO "verses" VALUES(1938604,2375,4,0,'خوش دولتیست خرّم و خوش خسروی کریم','هوش مصنوعی: خوشبختی و زیبایی به سراغ کسی آمده است و او خوش‌دل و با شخصیت است. ای خدا، از گزند حوادث روزگار او را حفظ کن.',NULL);
INSERT INTO "verses" VALUES(1938605,2374,1,0,'سَرَت سبز و دلت خوش باد، جاوید','هوش مصنوعی: سر تو سبز و دل تو شاد باد همیشه که نشان زیبا و خوشی از محبت یار را به نمایش گذاشته‌ای.',NULL);
INSERT INTO "verses" VALUES(1938606,2375,4,1,'یا رب ز چشمْ زخمِ زمانش نگاه دار',NULL,NULL);
INSERT INTO "verses" VALUES(1938607,2375,5,1,'جامِ مُرَصَّعِ تو بدین دُرِّ شاهوار',NULL,NULL);
INSERT INTO "verses" VALUES(1938608,2377,2,0,'در کمینگاه نظر با دلِ خویشم جنگ است','دل من به‌دشمنی من برخاسته و با من در جنگ است؛ تیر و کمانی از غمزه و ابروی یار برایم بیاور.',NULL);
INSERT INTO "verses" VALUES(1938609,2377,1,1,'یعنی از خاکِ درِ دوست نشانی به من آر',NULL,NULL);
INSERT INTO "verses" VALUES(1938610,2377,1,0,'قلب بی‌حاصلِ ما را بزن اکسیرِ مراد','سکّه تقلبی و سیاه ما را با آن کیمیا، زر کن یعنی با کیمیای خاک کوی یار.',NULL);
INSERT INTO "verses" VALUES(1938611,2377,0,1,'زار و بیمارِ غَمَم راحتِ جانی به من آر',NULL,NULL);
INSERT INTO "verses" VALUES(1938612,2377,0,0,'ای صبا نَکهَتی از کویِ فُلانی به من آر','ای نسیم‌، پیامی از آن‌یار (که خود می‌دانی) بیاور و من‌ِ بیمار را درمان کن و جان‌ببخش. (نکهت: بوی‌خوش)',NULL);
INSERT INTO "verses" VALUES(1938613,2376,7,1,'تو آبِ دیده از این ره‌گذر دریغ مدار',NULL,NULL);
INSERT INTO "verses" VALUES(1938614,2376,7,0,'غبارِ غم بِرَوَد، حال خوش شود حافظ','هوش مصنوعی: اگر غبار غم برطرف شود، حال انسان بهتر خواهد شد. حافظ، تو نباید از این درد و اندوه، اشک بریزی و از آن دریغ نکنی.',NULL);
INSERT INTO "verses" VALUES(1938615,2376,6,1,'که در بهایِ سخن سیم و زر دریغ مدار',NULL,NULL);
INSERT INTO "verses" VALUES(1938616,2376,6,0,'چو ذکرِ خیر طلب می‌کنی سخن این است','هوش مصنوعی: وقتی از دیگران خوبی و نیکی یاد می‌کنی، باید بدان که در مقابل تعریف و تمجیدها، باید از مال و دارایی خود نیز دریغ نکنی.',NULL);
INSERT INTO "verses" VALUES(1938617,2376,5,1,'از او وظیفه و زادِ سفر دریغ مدار',NULL,NULL);
INSERT INTO "verses" VALUES(1938618,2376,5,0,'مکارمِ تو به آفاق می‌بَرَد شاعر','هوش مصنوعی: نیکویی‌ها و ویژگی‌های تو دامن‌گیر جهانیان است، پس شاعر را در انجام وظایفش و آماده کردن وسایل سفرش تنها نگذار.',NULL);
INSERT INTO "verses" VALUES(1938619,2376,4,1,'سخن بگوی و ز طوطی، شِکَر دریغ مدار',NULL,NULL);
INSERT INTO "verses" VALUES(1938620,2376,4,0,'کنون که چشمهٔ قند است لعلِ نوشین‌ات','هوش مصنوعی: اکنون که لب‌های شیرین تو همچون چشمه‌ای از قند هستند، سخن بگو و در بیان شیرینی‌ات مانند طوطی، دریغ نکن.',NULL);
INSERT INTO "verses" VALUES(1938621,2376,3,1,'ز اهلِ معرفت این مختصر دریغ مدار',NULL,NULL);
INSERT INTO "verses" VALUES(1938622,2376,3,0,'جهان و هر چه در او هست سهل و مختصر است','هوش مصنوعی: دنیا و هر آنچه در آن وجود دارد، چیزی ساده و کوچک است؛ اما از اهل دانش و معرفت نباید به سادگی گذشت و باید به آن اهمیت داد.',NULL);
INSERT INTO "verses" VALUES(1938623,2376,2,1,'کنون که ماهِ تمامی نظر دریغ مدار',NULL,NULL);
INSERT INTO "verses" VALUES(1938624,2376,2,0,'حریفِ عشقِ تو بودم چو ماهِ نو بودی','هوش مصنوعی: من در عشق تو مانند ماه نو بودم و اکنون که به کمال خود رسیده‌ای، برای تو بزرگ‌تر از آنچه هستی، ننگر.',NULL);
INSERT INTO "verses" VALUES(1938625,2376,1,1,'نسیمِ وصل ز مرغِ سحر دریغ مدار',NULL,NULL);
INSERT INTO "verses" VALUES(1938626,2376,1,0,'به شُکرِ آن که شِکُفتی به کامِ بخت ای گل','هوش مصنوعی: به خاطر شکرگزاری از اینکه تو، ای گل، به خوشبختی شکفته‌ای، از نسیم وصال و آواز مرغ سحر دریغ نزن.',NULL);
INSERT INTO "verses" VALUES(1938627,2376,0,1,'وز او به عاشقِ بی‌دل خبر دریغ مدار',NULL,NULL);
INSERT INTO "verses" VALUES(1938628,2376,0,0,'صبا ز منزلِ جانان گذر دریغ مدار','هوش مصنوعی: باد صبا را که از سوی معشوق می‌آید، نباید از دست بدهی و باید به او که عاشق بی‌دل است، خبر برسانی.',NULL);
INSERT INTO "verses" VALUES(1938629,2375,9,1,'ناچار باده نوش که از دستْ رفتْ کار',NULL,NULL);
INSERT INTO "verses" VALUES(1938630,2375,9,0,'حافظ چو رفت روزه و گل نیز می‌رود','هوش مصنوعی: حافظ می‌گوید وقتی روز به پایان می‌رسد و گل هم می‌سپارد، نمی‌توانیم از نوشیدن شراب پرهیز کنیم، چرا که زمان به سرعت سپری می‌شود و فرصت‌ها از دست می‌روند.',NULL);
INSERT INTO "verses" VALUES(1938631,2375,8,1,'تسبیحِ شیخ و خرقهٔ رندِ شرابخوار',NULL,NULL);
INSERT INTO "verses" VALUES(1938632,2375,8,0,'ترسم که روزِ حشر عِنان بر عِنان رَوَد','هوش مصنوعی: نگرانی دارم که در روز قیامت، حساب و کتاب به گونه‌ای شود که تسبیح فرد پرهیزکار و لباس مذهب‌پوش کسی که به دنیا و خوشی‌ها دل بسته، یکی شود.',NULL);
INSERT INTO "verses" VALUES(1938633,2375,7,1,'بر قلب ما ببخش که نقدیست کم عیار',NULL,NULL);
INSERT INTO "verses" VALUES(1938634,2375,7,0,'زانجا که پرده پوشیِ عفوِ کریمِ توست','هوش مصنوعی: با توجه به رحمت و بزرگواری تو که بر دل‌های ما سایه افکنده، خواهش می‌کنم ما را ببخش، زیرا ارزش اعمال ما چندان زیاد نیست.',NULL);
INSERT INTO "verses" VALUES(1938635,2375,6,1,'از مِی کنند روزه گشا طالبانِ یار',NULL,NULL);
INSERT INTO "verses" VALUES(1938636,2375,6,0,'گر فوت شد سَحور چه نقصان صَبوح هست','اگر سحری نتوانستی بخوری،مشکلی نیست شراب هست. زیرا آنهایی که به عشق معشوق می‌پردازند، روزه خود را با شراب می‌شکنند.',NULL);
INSERT INTO "verses" VALUES(1938637,2375,5,0,'مِی خور به شعرِ بنده که زیبی دگر دهد','هوش مصنوعی: نوشیدن می به شعر من طعمی تازه می‌بخشد، زیرا جام زینتی تو با این مرواریدهای گرانبها زیباتر می‌شود.',NULL);
INSERT INTO "verses" VALUES(1938638,2374,0,1,'مبادا خالیَت شَکَّر ز مِنقار',NULL,NULL);
INSERT INTO "verses" VALUES(1938639,2374,0,0,'الا ای طوطیِ گویا‌یِ اسرار!','هوش مصنوعی: ای طوطی باهوش و سخنگو، مواظب باش که زبانت هرگز از شیرینی حرف خالی نشود.',NULL);
INSERT INTO "verses" VALUES(1938640,2373,7,1,'حَوالَتَش به لبِ یارِ دل‌نواز کنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938641,2372,2,0,'خوش می‌کنم به بادهٔ مُشکین مَشامِ جان','من با بوی بادهٔ مُشکین گوش جان را شاد می‌کنم، زیرا از پشمینه پوش صومعه بوی دورویی شنیده‌ام.',NULL);
INSERT INTO "verses" VALUES(1938642,2372,1,1,'کـاین گوش بس حکایتِ شاه و گدا شنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938643,2372,1,0,'ای شاهِ حُسن، چَشم به حالِ گدا فِکَن','ای شاه زیبایی! نگاهی به حال گدا بینداز؛ زیرا این گوش، داستان‌های بسیاری از شاه و گدا شنیده است.',NULL);
INSERT INTO "verses" VALUES(1938644,2372,0,1,'از یارِ آشنا سخنِ آشنا شنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938645,2372,0,0,'بویِ خوشِ تو هر که ز بادِ صبا شنید','هر کس که بوی خوش تو را از نسیم بامدادی بشنود، انگار از آشنا سخن آشنا شنیده باشد.',NULL);
INSERT INTO "verses" VALUES(1938646,2371,8,1,'ز وِردِ نیمْ شب و درسِ صبحگاه رسید',NULL,NULL);
INSERT INTO "verses" VALUES(1938647,2371,8,0,'مرو به خواب که حافظ به بارگاهِ قبول','به خواب نرو، زیرا حافظ با نیایش نیمه‌شب و درس صبحگاه در درگاه پذیرفته شد.',NULL);
INSERT INTO "verses" VALUES(1938648,2371,7,1,'همان رسید کز آتش به برگِ کاه رسید',NULL,NULL);
INSERT INTO "verses" VALUES(1938649,2371,7,0,'ز شوقِ رویِ تو شاها بدین اسیرِ فراق','شاها! از شوق روی تو بر این اسیر جدایی، همان آمد که آتش به [خرمن] کاه افتاده باشد.',NULL);
INSERT INTO "verses" VALUES(1938650,2371,6,1,'ز آتشِ دلِ سوزان و دودِ آه رسید',NULL,NULL);
INSERT INTO "verses" VALUES(1938651,2371,6,0,'صبا بگو که چه‌ها بر سرم در این غمِ عشق','صبا بگو که در این غم عشق، از آتش دل سوزان و دود آهم چه‌ها به سرم آمد.',NULL);
INSERT INTO "verses" VALUES(1938652,2371,5,1,'بگو بسوز، که مهدیِّ دین پناه رسید',NULL,NULL);
INSERT INTO "verses" VALUES(1938653,2371,5,0,'کجاست صوفیِ دَجّال فِعلِ مُلحِدشکل','کجاست آن صوفیِ دجّال رفتارِ بی دین که به او بگویید بسوزد، چون مهدی دین‌پناه آمد.',NULL);
INSERT INTO "verses" VALUES(1938654,2371,4,1,'ز قعرِ چاه برآمد به اوجِ ماه رسید',NULL,NULL);
INSERT INTO "verses" VALUES(1938655,2371,4,0,'عزیزِ مصر به رغمِ برادران غیور','عزیز مصر، با وجود تعصب برادران، از ته چاه بیرون آمد و به اوج بزرگی دست یافت.',NULL);
INSERT INTO "verses" VALUES(1938656,2371,3,1,'قوافلِ دل و دانش که مَرد راه رسید',NULL,NULL);
INSERT INTO "verses" VALUES(1938657,2371,3,0,'ز قاطعانِ طریق این زمان شوند ایمن','مژده دهید که اکنون قافله‌های دل و دانش، از راهزنان در امان خواهند بود.',NULL);
INSERT INTO "verses" VALUES(1938658,2371,2,1,'جهان به کامِ دل اکنون رسد که شاه رسید',NULL,NULL);
INSERT INTO "verses" VALUES(1938659,2371,2,0,'سپهر، دور خوش اکنون کُنَد که ماه آمد','گردش آسمان، از آمدن ماه سامان گرفت و اکنون جهان از رسیدن شاه، به کام دل می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1938660,2371,1,1,'کمالِ عدل به فریادِ دادخواه رسید',NULL,NULL);
INSERT INTO "verses" VALUES(1938661,2371,1,0,'جمالِ بخت ز رویِ ظفر نقاب انداخت','هوش مصنوعی: خوشبختی با ظاهری زیبا از پیروزی پرده‌برداری کرد و کمالِ عدالت به کمکِ دادخواهی آمد.',NULL);
INSERT INTO "verses" VALUES(1938662,2371,0,1,'نویدِ فتح و بشارت به مِهر و ماه رسید',NULL,NULL);
INSERT INTO "verses" VALUES(1938663,2371,0,0,'بیا که رایتِ منصورِ پادشاه رسید','هوش مصنوعی: بیا که پرچم پادشاه منصور به اهتزاز درآمد و خبر پیروزی و خوشحالی به آفتاب و ماه رسید.',NULL);
INSERT INTO "verses" VALUES(1938664,2370,6,1,'ز رویِ حافظ و این آستانه یاد آرید',NULL,NULL);
INSERT INTO "verses" VALUES(1938665,2370,6,0,'به وَجهِ مرحمت ای ساکنانِ صدرِ جلال','هوش مصنوعی: ای ساکنان موطن بلندمرتبه و بزرگوار، به خاطر لطف و مهربانی شما، از چهره حافظ و این درگاه یاد کنید.',NULL);
INSERT INTO "verses" VALUES(1938666,2370,5,1,'ز بی‌وفاییِ دورِ زمانه یاد آرید',NULL,NULL);
INSERT INTO "verses" VALUES(1938667,2370,5,0,'نمی‌خورید زمانی غمِ وفاداران','هوش مصنوعی: هرگز غم وفاداران را نخورید و به یاد داشته باشید که وفاداری در برابر بی‌وفایی‌هایی که زمانه به ما تقدیم می‌کند، ارزش دارد.',NULL);
INSERT INTO "verses" VALUES(1938668,2370,4,1,'ز همرهان به سرِ تازیانه یاد آرید',NULL,NULL);
INSERT INTO "verses" VALUES(1938669,2370,4,0,'سمندِ دولت اگر چند سرکشیده رَوَد','هوش مصنوعی: اگرچه اسب دولت ممکن است گاهی سرکشی کند و از همراهان خود فاصله بگیرد، اما باید به یاد داشته باشیم که با تازیانه می‌توان آن را به راه راست هدایت کرد.',NULL);
INSERT INTO "verses" VALUES(1938670,2372,2,1,'کز دلق‌پوشِ صومعه بویِ ریا شنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938671,2372,3,0,'سِرِّ خدا که عارفِ سالِک به کَس نگفت','من در شگفتم راز خداوند را که عارفِ سالک به کسی نگفته بود، باده‌فروش از کجا شنیده است!',NULL);
INSERT INTO "verses" VALUES(1938672,2372,3,1,'در حیرتم که باده‌فروش از کجا شنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938673,2372,4,0,'یا رب کجاست محرمِ رازی که یک زمان','خدایا آن محرم راز کجاست که دل بتواند یک بار دل شرح دهد که چه گفته و چه‌ها شنیده است.',NULL);
INSERT INTO "verses" VALUES(1938674,2373,7,0,'وگر طلب کند انعامی از شما حافظ','هوش مصنوعی: اگر کسی از شما خواسته‌ای داشته باشد، توصیه کنید که آن را به نزد محبوب دلنشین ببرند.',NULL);
INSERT INTO "verses" VALUES(1938675,2373,6,1,'بر او نَمُرده، به فتوای من نماز کنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938676,2373,6,0,'هر آن کسی که در این حلقه نیست زنده به عشق',':هر کسی که در این جهان با عشق زندگی نمیکند، مرده است و به فتوای من بر او نماز میت بخوانید(زندگی انسان با عشق معنا میگیرد)',NULL);
INSERT INTO "verses" VALUES(1938677,2373,5,1,'که «از مُصاحبِ ناجِنس اِحتِراز کنید»',NULL,NULL);
INSERT INTO "verses" VALUES(1938678,2373,5,0,'نخست موعظهٔ پیرِ صحبت این حرف است','هوش مصنوعی: اولین نصیحت پیر و بزرگ این است که از همراهی با افراد نامناسب و مضر پرهیز کنید.',NULL);
INSERT INTO "verses" VALUES(1938679,2373,4,1,'چو یار ناز نماید، شما نیاز کنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938680,2373,4,0,'میانِ عاشق و معشوق فَرق بسیار است','هوش مصنوعی: جایگاه عاشق و معشوق با هم تفاوت زیادی دارد. وقتی معشوق رفتارهای دلربا و محبت‌آمیز از خود نشان می‌دهد، عاشق باید با عشق و نیاز خود به او پاسخ دهد.',NULL);
INSERT INTO "verses" VALUES(1938681,2373,3,1,'گر اعتماد بر الطافِ کارساز کنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938682,2373,3,0,'به جانِ دوست که غم پرده بر شما نَدَرَد','هوش مصنوعی: به خاطر دوستی که غم و غصه نتواند بر شما بیفتد، اگر به مهربانی‌های توانای او اعتماد کنید.',NULL);
INSERT INTO "verses" VALUES(1938683,2373,2,1,'«که گوشِ هوش به پیغامِ اهلِ راز کنید»',NULL,NULL);
INSERT INTO "verses" VALUES(1938684,2373,2,0,'رَباب و چنگ به بانگِ بلند می‌گویند','هوش مصنوعی: رباب و چنگ با صدای بلند می‌گویند که توجه و دقت خود را به پیام‌های کسانی که در وادی عرفان و راز و رمز هستند، معطوف کنید.',NULL);
INSERT INTO "verses" VALUES(1938685,2373,1,1,'وَ اِنْ یَکاد بخوانید و در فَراز کنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938686,2373,1,0,'حضورِ خلوتِ اُنس است و دوستان جمعند','هوش مصنوعی: حضور دوستان در یک جمع صمیمی و خودمانی است و اگرچه این لحظه به سرعت در حال گذر است، اما می‌توانید با هم از آن لذت ببرید و خاطراتی بسازید.',NULL);
INSERT INTO "verses" VALUES(1938687,2373,0,1,'شبی خوش‌ است بدین قصه‌اش دراز کنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938688,2377,2,1,'ز ابرو و غمزهٔ او تیر و کمانی به من آر',NULL,NULL);
INSERT INTO "verses" VALUES(1938689,2373,0,0,'معاشران! گره از زلفِ یار باز کنید','ای دوستان گره‌های زلف معشوق را باز کنید (کنایه از ایجاد فضای عاشقانه و صمیمی) امشب شب خوشی است، با این داستان عاشقانه آن را طولانی کنید (یعنی با صحبت و لذت بردن از این لحظه، شب را به خوشی ادامه دهید).',NULL);
INSERT INTO "verses" VALUES(1938690,2372,11,0,'حافظ، وظیفهٔ تو دعا گفتن است و بس','وظیفهٔ تو فقط دعا کردن است , خودت را درگیر این نکته نکن که آیا دعایت شنیده می‌شود یا نه.',NULL);
INSERT INTO "verses" VALUES(1938691,2372,10,1,'فرخنده آن کسی که به سَمعِ رضا شنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938692,2372,10,0,'پندِ حکیمْ محضِ صَواب است و عینِ خیر','هوش مصنوعی: نصیحت خردمند همیشه درست و خیری خالص است. خوشبخت کسی است که این نصیحت را با دل‌پذیری می‌شنود.',NULL);
INSERT INTO "verses" VALUES(1938693,2372,9,1,'بس دور شد که گنبدِ چرخ این صدا شنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938694,2372,9,0,'ما مِی به بانگِ چنگ نه امروز می‌کشیم','هوش مصنوعی: ما امروز با صدای چنگ مشغول نوشیدن شراب هستیم، زیرا زمان زیادی گذشته که این صدا به گوش چرخ فلک رسیده است.',NULL);
INSERT INTO "verses" VALUES(1938695,2372,8,1,'صد بار پیرِ میکده این ماجرا شنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938696,2372,8,0,'ما باده زیرِ خرقه نه امروز می‌خوریم','تنها امروز نیست که زیر خرقه [پنهانی] باده می‌خوریم؛ پیر میکده این ماجرا را بارها شنیده است.',NULL);
INSERT INTO "verses" VALUES(1938697,2372,7,1,'کان کس که گفت قصهٔ ما هم ز ما شنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938698,2372,7,0,'ساقی بیا که عشق ندا می‌کند بلند','ساقی بیا که عشق فریاد می‌زند: کسی که داستان ما را گفت، از خودِ ما شنیده استاینجا می خواد بگهآنچه بنیادی است خود عشق است و عاشق و معشوق هم برآیندی از عشقند!"ما"یعنی عشق که همه چیز است دربرگیرنده هم عاشق است هم معشوق.خود عشق است که یک حقیقت است عاشق و معشوق تنها نمودی و جلوه‌ای از عشقند.به زبان دیگر باید پیش و بیش از شناخت عاشق و معشوق خود عشق را شناخت و دریافت که این عشق چه رازی است که عاشق و معشوق را به عشقبازی وا می دارد!فرمانروا نه عاشق است نه معشوق که عشق است.پس به جای شناسایی خسرو و شیرین باید توانمان را بگذاریم عشق را بشناسیم،چرا که خسروها و شیرین‌ها تنها دو تن از هزاران بازیگر آنند.این عشق آن اندازه ژرف و گسترده است که توانایی ان را دارد که در میان هر عاشق و معشوق بازتابی دیگر داشته باشد.از این رو ندای عشق بسی بلندتر از صدای عاشق و معشوق است،چون می‌تواند در میان هر عاشق و معشوقی به رنگی دیگر درآید.پس اینجاست که حافظ که خود عاشقی است هم اینجا خود را کنار می نهد و ساقی را به کمک فرامی‌خواند و می‌گوید بیا که اکنون نیاز شتاب‌آلود به توست .می بده چون می‌خواهم رازی را بگویم که هر کس را یارای شنیدن نباشد.باید مست شود تا دریابد چه می‌گویم.در اینجا به گونه‌ای من نویسنده‌ای این نوشته هم به کناری نهاده می‌شویم چرا که می ساقی نخورده داریم این سخن را وامی‌کاویم!پس هر آنچه اکنون می‌گویمم در هنگام مستی نیست و در هوشیاری آن را بر زبان می‌آریم...به گونه‌ای مست باید بود تا این سخن را دریافت.پس هر آنچه را من تا اینجا گفتم چون مست نبودم و نمی‌تواند راستینه‌ی خواست آنچه این نوشته می‌خواسته باشد!چون ما خویمان این اسا که از عاشق یا معشوق چیزی را بشنویم،عشق که زبان ندارد که ما ازو سخنی بشنویم...ازین رو ساقی را فراخوانده که بگویم یک چیز ناخویمند(غیر عادی) را می‌خواهم بگویم که تنها در خوی ناخویمندی یارای شنیدن و دریافت آن است!',NULL);
INSERT INTO "verses" VALUES(1938699,2372,6,1,'از گلشنِ زمانه که بویِ وفا شنید؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938700,2372,6,0,'محروم اگر شدم ز سرِ کویِ او چه شد؟','اگر از کوی او محروم شدم، چیزی نشده است. [مگر] چه کسی از گلشن زمانه بوی وفا شنیده است؟',NULL);
INSERT INTO "verses" VALUES(1938701,2372,5,1,'کز غمگسارِ خود سخنِ ناسزا شنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938702,2372,5,0,'اینَش سزا نبود دلِ حق‌گُزارِ من','دلِ پایبند به حق من، سزاوار این نبود که از همدم خود سخن ناشایست بشنود.',NULL);
INSERT INTO "verses" VALUES(1938703,2372,4,1,'دل شرحِ آن دهد که چه گفت و چه‌ها شنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938704,2372,11,1,'در بَندِ آن مباش که نشنید یا شنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938705,2377,3,0,'در غریبی و فِراق و غمِ دل پیر شدم','در غربت و دوری از یار، پیر و ناتوان گشته‌ام با جامی‌باده از دست یک‌ساقی جوان مرا شاد و جوان گردان.',NULL);
INSERT INTO "verses" VALUES(1938706,2377,3,1,'ساغرِ مِی ز کفِ تازه جوانی به من آر',NULL,NULL);
INSERT INTO "verses" VALUES(1938707,2377,4,0,'منکران را هم از این مِی دو سه ساغر بچشان','برای مخالفان می‌گساری چند جام باده بریز، اگر ننوشند بی‌وقفه برای من بیاور.',NULL);
INSERT INTO "verses" VALUES(1938708,2383,2,0,'از دستِ غیبتِ تو شکایت نمی‌کنم','هوش مصنوعی: من از دوری تو گله‌ای ندارم، زیرا تا زمانی که غیبتی وجود ندارد، لذت حضور هم حس می‌شود.',NULL);
INSERT INTO "verses" VALUES(1938709,2383,1,1,'با بلبلانِ بی‌دلِ شیدا مَکُن غرور',NULL,NULL);
INSERT INTO "verses" VALUES(1938710,2383,1,0,'ای گُل به شُکرِ آن که تویی پادشاهِ حُسن','هوش مصنوعی: ای گل، به خاطر اینکه تو سلطان زیبایی هستی، با بلبلان عاشق و بی‌دل، مغرور نخواهی شد.',NULL);
INSERT INTO "verses" VALUES(1938711,2383,0,1,'گلبانگ زد که چشمِ بد از رویِ گُل به دور',NULL,NULL);
INSERT INTO "verses" VALUES(1938712,2383,0,0,'دیگر ز شاخِ سروِ سَهی بلبلِ صبور','هوش مصنوعی: بلبلِ صبور که در کنار سروهای زیبا نشسته است، با آواز خود به همه اعلام می‌کند که نگاهِ بد از زیبایی گل دور باشد و به آن آسیب نرساند.',NULL);
INSERT INTO "verses" VALUES(1938713,2382,8,1,'این نقش مانَد از قَلَمَت یادگارِ عمر',NULL,NULL);
INSERT INTO "verses" VALUES(1938714,2382,8,0,'حافظ سخن بگوی که بر صفحهٔ جهان','هوش مصنوعی: حافظ، صحبت کن تا کلامت بر صفحات دنیا باقی بماند و نشانی از عمرت را به یادگار بگذارد.',NULL);
INSERT INTO "verses" VALUES(1938715,2382,7,1,'روز فِراق را که نَهَد در شمارِ عمر',NULL,NULL);
INSERT INTO "verses" VALUES(1938716,2382,7,0,'بی عمر زنده‌ام من و این بس عجب مدار','هوش مصنوعی: من عمری کوتاه دارم و در این وضعیت عجیب است که روز جدایی را نیز در شمار عمر خود بدانم.',NULL);
INSERT INTO "verses" VALUES(1938717,2382,6,1,'زان رو عِنان‌گسسته دَوانَد سوارِ عمر',NULL,NULL);
INSERT INTO "verses" VALUES(1938718,2382,6,0,'در هر طرف ز خیلِ حوادث کمین‌گهیست','هوش مصنوعی: در هر سو، از انبوه اتفاقات و مشکلات، خطرهایی lurking وجود دارد. به همین دلیل، سوار زندگی، افسار خود را رها کرده و با شتاب پیش می‌رود.',NULL);
INSERT INTO "verses" VALUES(1938719,2382,5,1,'بر نقطهٔ دهانِ تو باشد مدارِ عمر',NULL,NULL);
INSERT INTO "verses" VALUES(1938720,2382,5,0,'اندیشه از محیطِ فنا نیست هر که را','هوش مصنوعی: اندیشه و تفکر از دنیای زوال و فنا نشأت نمی‌گیرد. هر کسی که زندگی‌اش به تو و کلام تو وابسته باشد، عمرش تحت تأثیر آن قرار می‌گیرد.',NULL);
INSERT INTO "verses" VALUES(1938721,2382,4,1,'بیچاره دل که هیچ ندید از گذارِ عمر',NULL,NULL);
INSERT INTO "verses" VALUES(1938722,2382,4,0,'دی در گذار بود و نظر سویِ ما نکرد','هوش مصنوعی: دیروز گذشت و نتوانستیم جلب توجه کنیم، دل بدبخت که در این گذر عمر هیچ چیزی نتوانست ببیند.',NULL);
INSERT INTO "verses" VALUES(1938723,2382,3,1,'هشیار گَرد، هان که گذشت اختیارِ عمر',NULL,NULL);
INSERT INTO "verses" VALUES(1938724,2382,3,0,'تا کی مِی صَبوح و شِکرخوابِ بامداد','هوش مصنوعی: تا کی باید در نشئهٔ صبحگاهی و خواب شیرین بامداد بگذرانیم؟ بیدار شو و به یاد بیاور که عمر فرصتی است که دیگر برنمی‌گردد.',NULL);
INSERT INTO "verses" VALUES(1938725,2382,2,1,'دریاب کارِ ما که نه پیداست کارِ عمر',NULL,NULL);
INSERT INTO "verses" VALUES(1938726,2382,2,0,'این یک دو دَم که مهلتِ دیدار ممکن است','هوش مصنوعی: این دو لحظه‌ای که فرصت دیدار به دست آمده، ارزش لحظه‌های عمر ما را درک کن، زیرا کارهای ما نه تنها مشخص نیستند، بلکه زمان نیز بسیار محدود است.',NULL);
INSERT INTO "verses" VALUES(1938727,2382,1,1,'کاندر غمت چو برق بِشُد روزگارِ عمر',NULL,NULL);
INSERT INTO "verses" VALUES(1938728,2382,1,0,'از دیده گر سرشک چو باران چِکَد رواست','هوش مصنوعی: اگر اشکی از چشمم مانند باران بریزد، ایرادی ندارد؛ زیرا در غم تو، عمرم همچون برق برق می‌زند و سریع می‌گذرد.',NULL);
INSERT INTO "verses" VALUES(1938729,2382,0,1,'بازآ که ریخت بی گُلِ رویت بهارِ عمر',NULL,NULL);
INSERT INTO "verses" VALUES(1938730,2382,0,0,'ای خُرَّم از فروغِ رُخَت لاله زارِ عمر','هوش مصنوعی: ای خوشحال، با نور چهره‌ات، زندگی‌ام را زنده کن. برگرد که بدونِ گلِ روی تو، بهار زندگی‌ام سپری شده است.',NULL);
INSERT INTO "verses" VALUES(1938731,2381,8,1,'غرقه گشتند در این بادیه بسیارِ دگر',NULL,NULL);
INSERT INTO "verses" VALUES(1938732,2381,8,0,'بازگویم نه در این واقعه حافظ تنهاست','هوش مصنوعی: می‌خواهم بگویم که در این ماجرا حافظ تنها نیست، بلکه افراد زیادی در این مسیر گم شده‌اند و دچار سختی شده‌‌اند.',NULL);
INSERT INTO "verses" VALUES(1938733,2381,7,1,'کُنَدَم قصدِ دلِ ریش به آزارِ دگر',NULL,NULL);
INSERT INTO "verses" VALUES(1938734,2381,7,0,'هر دم از درد بنالم که فلک هر ساعت','هوش مصنوعی: هر لحظه از درد خود شکایت می‌کنم، زیرا آسمان هر ساعت به دل شکسته‌ی من آسیب می‌زند و به من آزار می‌رساند.',NULL);
INSERT INTO "verses" VALUES(1938735,2381,6,1,'هر زمان با دف و نی بر سرِ بازارِ دگر',NULL,NULL);
INSERT INTO "verses" VALUES(1938736,2381,6,0,'راز سربستهٔ ما بین که به دستان گفتند','هوش مصنوعی: راز پنهانی که ما داریم، در هر زمانی به دستان گفته می‌شود. در هر بازار جدید با دف و نی، این راز را بیان می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1938737,2383,2,1,'تا نیست غیبتی نَبُوَد لذّتِ حضور',NULL,NULL);
INSERT INTO "verses" VALUES(1938738,2383,3,0,'گر دیگران به عیش و طَرَب خُرَّمَند و شاد','هوش مصنوعی: اگر دیگران در شادی و خوشی هستند، غم عشق معشوق ما باعث شادی و سرور ماست.',NULL);
INSERT INTO "verses" VALUES(1938739,2383,3,1,'ما را غمِ نگار بُوَد مایهٔ سُرور',NULL,NULL);
INSERT INTO "verses" VALUES(1938740,2383,4,0,'زاهد اگر به حور و قصور است امیدوار','هوش مصنوعی: زاهد اگر به بهشت و مکان‌های زیبا امید دارد، ما برای شادی و خوشی خود به میخانه و همراهی یارانی زیبا دل خوش کرده‌ایم.',NULL);
INSERT INTO "verses" VALUES(1938741,2385,2,0,'نَعیم هر دو جهان پیش عاشقان بجوی','اگر نعمت و خوشبختی دو دنیا را می‌خواهی آنرا در نزد عاشقان خواهی یافت، که این یکی ناچیز است و آن یکی خیلی زیاد.',NULL);
INSERT INTO "verses" VALUES(1938742,2385,1,1,'که در کمینگهِ عمر است مَکرِ عالَمِ پیر',NULL,NULL);
INSERT INTO "verses" VALUES(1938743,2385,1,0,'ز وصلِ رویِ جوانان تَمَتُّعی بردار','از معاشرت و حضور جوانان لذت ببر، زیرا بدی‌ها و مکرهای این دنیای کهنه و پُرفن در کمین توست.',NULL);
INSERT INTO "verses" VALUES(1938744,2385,0,1,'هر آنچه ناصِحِ مُشْفِق بگویَدَت بپذیر',NULL,NULL);
INSERT INTO "verses" VALUES(1938745,2385,0,0,'نصیحتی کُنَمَت بشنو و بهانه مَگیر','به تو پندی می‌دهم، گوش کن و بهانه میاور؛ هرچه آدم پندگوی مهربان به تو می‌گوید، عمل کن.',NULL);
INSERT INTO "verses" VALUES(1938746,2384,9,0,'حافظا در کُنجِ فقر و خلوتِ شب‌هایِ تار','حافظ، تا وقتی در گوشه­‌ی نیاز و در میان شب­‌های تاریک و خلوت، ذکر لبت دعا و درس قرآن است، اندوهگین مباش.',NULL);
INSERT INTO "verses" VALUES(1938747,2384,9,1,'تا بُوَد وِردَت دعا و درس قرآن غم مخور',NULL,NULL);
INSERT INTO "verses" VALUES(1938748,2384,8,0,'حال ما در فُرقت جانان و اِبرامِ رقیب','اندوهگین مباش؛ چرا که خدایی که اوضاع و احوال را دگرگون می­‌سازد و تغییر می‌­دهد، از حال و روز ما که دچار دوری از معشوق هستیم و رقیب آزارمان می‌­دهد به طور کامل خبر دارد.',NULL);
INSERT INTO "verses" VALUES(1938749,2384,8,1,'جمله می‌داند خدایِ حالْ‌گردان غم مخور',NULL,NULL);
INSERT INTO "verses" VALUES(1938750,2384,7,0,'گرچه منزل بس خطرناک است و مقصد بس بعید','اگر چه محل فرود کاروان جای بسیار سهمناکی است و مقصد بسیار دور، اما این را بدان که هیچ راهی نیست که بالاخره انتها نداشته باشد، بالاخره تمام راه­ها جایی به پایان می‌­رسند.',NULL);
INSERT INTO "verses" VALUES(1938751,2384,7,1,'هیچ راهی نیست کآن را نیست پایان، غم مخور',NULL,NULL);
INSERT INTO "verses" VALUES(1938752,2384,6,0,'در بیابان گر به شوقِ کعبه خواهی زد قدم','شوق رسیدن به کعبه تو را راهی بیابان‌­ها کرده است، بنابراین اگر در این مسیر خارهای بیابان شروع به ملامت و سرزنش تو کردند، اندوهی به دلت راه مده و صبور باش.',NULL);
INSERT INTO "verses" VALUES(1938753,2384,6,1,'سرزنش‌ها گر کُنَد خارِ مُغیلان غم مخور',NULL,NULL);
INSERT INTO "verses" VALUES(1938754,2384,5,0,'ای دل اَر سیلِ فنا بنیادِ هستی بَرکَنَد','ای دل اگر مرگ و نابودی بخواهد چونان سیلی تمام هستی تو را از بین ببرد، بدان که تو ناخدایی چون نوح داری، پس از طوفان مترس و اندوهگین مشو.',NULL);
INSERT INTO "verses" VALUES(1938755,2381,5,1,'غمزهٔ شوخَش و آن طرهٔ طَرّارِ دگر',NULL,NULL);
INSERT INTO "verses" VALUES(1938756,2384,5,1,'چون تو را نوح است کشتیبان، ز طوفان غم مخور',NULL,NULL);
INSERT INTO "verses" VALUES(1938757,2384,4,0,'هان مَشو نومید چون واقِف نِه‌ای از سِرِّ غیب','از آنجا که از اسرار نهانی آگاه نیستی، پس آگاه باش که مبادا ناامید شوی، بدان که در پشت پرده­‌ی عالم غیب، نقش­‌ها و بازی­‌های بسیاری وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1938758,2384,3,0,'دورِ گردون گر دو روزی بر مرادِ ما نرفت','اگر طوفانی بیاد و سیلی راه بیفتد که همه چیز و همه کس را از بین ببرد اگر راننده و کشتیبان کشتی تو حضرت نوح باشد هیچ ترسی نداشته باش',NULL);
INSERT INTO "verses" VALUES(1938759,2384,3,1,'دائماً یکسان نباشد حالِ دوران غم مخور',NULL,NULL);
INSERT INTO "verses" VALUES(1938760,2384,2,0,'گر بهارِ عمر باشد باز بر تختِ چمن','ای پرنده‌­ی خوش­‌آواز، اندوهگین مباش؛ چرا که اگر بهار دیگری از عمرت باقی مانده باشد، دوباره چونان پادشاهی بر تختگاه چمن خواهی نشست و گل نیز وجود خود را چونان چتری در بالای سر تو نگاه خواهد داشت.',NULL);
INSERT INTO "verses" VALUES(1938761,2384,2,1,'چتر گل در سر کَشی، ای مرغِ خوشخوان غم مخور',NULL,NULL);
INSERT INTO "verses" VALUES(1938762,2384,1,0,'ای دل غمدیده، حالت بِه شود، دل بَد مکن','ای دل اندوهگین، بد به خود راه مده و فکر و اندیشه­‌ی بد نکن؛ چرا که حالت خوب و روبراه خواهد شد، و این سر پریشان احوال، آرام و قرار خواهد گرفت.',NULL);
INSERT INTO "verses" VALUES(1938763,2384,1,1,'وین سرِ شوریده باز آید به سامان غم مخور',NULL,NULL);
INSERT INTO "verses" VALUES(1938764,2384,0,0,'یوسفِ گم‌گشته بازآید به کنعان، غم مخور','غمگین مباش؛ چرا که سرانجام یار زیبارو به منزل باز خواهد گشت و آن جایگاه که محل غم و اندوه است، روزی تبدیل به جایگاه شادی و شور و نشاط می­‌شود.',NULL);
INSERT INTO "verses" VALUES(1938765,2384,0,1,'کلبهٔ احزان شَوَد روزی گلستان، غم مخور',NULL,NULL);
INSERT INTO "verses" VALUES(1938766,2383,6,1,'در هِجر وصل باشد و در ظلمت است نور',NULL,NULL);
INSERT INTO "verses" VALUES(1938767,2383,6,0,'حافظ شکایت از غمِ هجران چه می‌کنی؟','هوش مصنوعی: حافظ می‌گوید که چرا از درد جدایی شکایت می‌کنی؟ در حالتی که در جدایی، وصل هم وجود دارد و در تاریکی، نور نهفته است.',NULL);
INSERT INTO "verses" VALUES(1938768,2383,5,1,'گوید تو را که باده مخور گو هُوَالْغَفُور',NULL,NULL);
INSERT INTO "verses" VALUES(1938769,2383,5,0,'مِی خور به بانگِ چنگ و مخور غصه ور کسی','هوش مصنوعی: شراب بنوش و با صدای چنگ لذت ببر، نگران چیزی نباش؛ اگر کسی به تو گفت که شراب ننوش، بگو خداوند بخشنده است.',NULL);
INSERT INTO "verses" VALUES(1938770,2383,4,1,'ما را شرابخانه قصور است و یار حور',NULL,NULL);
INSERT INTO "verses" VALUES(1938771,2384,4,1,'باشد اندر پرده بازی‌هایِ پنهان غم مخور',NULL,NULL);
INSERT INTO "verses" VALUES(1938772,2370,3,1,'ز عهدِ صحبت ما در میانه یاد آرید',NULL,NULL);
INSERT INTO "verses" VALUES(1938773,2381,5,0,'عافیت می‌طلبد خاطرم ار بگذارند','هوش مصنوعی: اگر قرار باشد که خاطرم آرامش بیابد، باید از اغواگری‌ها و زیبایی‌های او دست بردارد و به آرامش واقعی فکر کند.',NULL);
INSERT INTO "verses" VALUES(1938774,2381,4,0,'گر مساعد شَوَدَم دایرهٔ چرخِ کبود','هوش مصنوعی: اگر حالتی پیش بیاید که من مناسب و آماده باشم، حتی ممکن است دایره‌ی آسمانی را هم با یک ابزار دیگر به‌دست آورم.',NULL);
INSERT INTO "verses" VALUES(1938775,2379,1,1,'گو «بیا سیلِ غم و خانه ز بنیاد بِبَر»',NULL,NULL);
INSERT INTO "verses" VALUES(1938776,2379,1,0,'ما چو دادیم دل و دیده به طوفانِ بلا','هوش مصنوعی: وقتی که دل و چشمان‌مان را در میان سختی‌ها و مشکلات تقدیم کردیم، دیگر چه اهمیتی دارد که تو هم بیایی و غم و اندوه خانه‌مان را به کلی ویران کند؟',NULL);
INSERT INTO "verses" VALUES(1938777,2379,0,1,'خَرمنِ سوختگان را همه گو باد بِبَر',NULL,NULL);
INSERT INTO "verses" VALUES(1938778,2379,0,0,'روی بِنْمای و وجودِ خودم از یاد بِبَر','هوش مصنوعی: فراموش کن که من چه کسی هستم و به وجود خودم فکر نکن، تنها اجازه بده تا غم و اندوه سوختگان را بباد بسپارم.',NULL);
INSERT INTO "verses" VALUES(1938779,2378,9,0,'دلقِ حافظ به چه ارزد؟ به مِی‌اش رنگین کن','هوش مصنوعی: لباس و ظاهر حافظ چه ارزشی دارد؟ بهتر است آن را با شراب رنگین کنیم و سپس او را مست و خراب از وسط بازار بیاوریم.',NULL);
INSERT INTO "verses" VALUES(1938780,2378,9,1,'وان گَه‌اش مست و خراب از سَرِ بازار بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1938781,2378,8,0,'روزگاریست که دل چهرهٔ مقصود ندید','هوش مصنوعی: زمانی است که دل به چهرهٔ محبوب دسترسی ندارد، ای ساقی، آن جامی را بیاور که مانند آینه است و خود را در آن ببینم.',NULL);
INSERT INTO "verses" VALUES(1938782,2378,8,1,'ساقیا آن قدحِ آینه‌کردار بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1938783,2378,7,0,'کامِ جان تلخ شد از صبر که کردم بی‌دوست','هوش مصنوعی: جانم از صبر و انتظار بی‌دوست تلخ شده است؛ زیرا که از لبان شیرین و دل‌ربای او شکر و نعمت می‌خواهم.',NULL);
INSERT INTO "verses" VALUES(1938784,2378,7,1,'عشوه‌ای زان لبِ شیرین شِکربار بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1938785,2378,6,0,'شُکرِ آن را که تو در عِشرتی ای مرغِ چمن','هوش مصنوعی: این بیت به ستایش و قدردانی از کسی می‌پردازد که در خوشی و سرزندگی به سر می‌برد. شاعر از این شخص می‌خواهد که خبر خوش از زیبایی‌های گل‌زار را به افرادی که در قفس هستند، برساند. به بیان دیگر، این شعر از حس شادی و زیبایی طبیعت در مقایسه با محدودیت‌ها و رنج‌های دیگران سخن می‌گوید.',NULL);
INSERT INTO "verses" VALUES(1938786,2378,6,1,'به اسیرانِ قفس، مژدهٔ گل‌زار بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1938787,2378,5,0,'خامی و ساده‌دلی شیوهٔ جانبازان نیست','هوش مصنوعی: سادگی و بی‌تجربگی ویژگی رزمندگان نیست؛ باید از جفا و ناپایداری دلبر فریبنده آگاهی داشته باشی.',NULL);
INSERT INTO "verses" VALUES(1938788,2378,5,1,'خبری از بَرِ آن دل‌بر عیّار بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1938789,2378,4,0,'گَردی از ره‌گذرِ دوست به کوریِّ رقیب','هوش مصنوعی: گردی از طرف دوست به چشم رقیب بپاش تا این چشم خونین من آرام بگیرد.',NULL);
INSERT INTO "verses" VALUES(1938790,2378,4,1,'بهرِ آسایش این دیدهٔ خون‌بار بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1938791,2378,3,0,'به وفایِ تو که خاکِ رَهِ آن یارِ عزیز','هوش مصنوعی: به خاطر وفای تو، که خاک راه آن یار عزیز است، بی‌غبار و پاکی که از ناپاکی‌های دیگران ایجاد می‌شود.',NULL);
INSERT INTO "verses" VALUES(1938792,2378,3,1,'بی‌غباری که پدید آید از اغیار بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1938793,2378,2,0,'تا مُعَطَّر کُنَم از لطفِ نسیمِ تو مَشام','هوش مصنوعی: برای اینکه عطر عشق تو را در جانم بپاشم، یک بوی خوش از نفس محبوب بیاور.',NULL);
INSERT INTO "verses" VALUES(1938794,2378,2,1,'شَمِّه‌ای از نَفَحاتِ نفسِ یار بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1938795,2378,1,0,'نکته‌ای روح‌فَزا از دهنِ دوست بگو','هوش مصنوعی: دوستت چیزی شگفت‌انگیز و دلنشین بگوید و خبری خوش از دنیای رازها بیاورد.',NULL);
INSERT INTO "verses" VALUES(1938796,2378,1,1,'نامه‌ای خوش خبر از عالَمِ اسرار بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1938797,2378,0,0,'ای صبا نَکهَتی از خاکِ رَهِ یار بیار','هوش مصنوعی: ای نسیم، کمی از خاک راه محبوبم بیاور تا اندوه دل را برطرف کنی و خبر خوش محبوب را به من برسانی.',NULL);
INSERT INTO "verses" VALUES(1938798,2378,0,1,'بِبَر اندوهِ دل و مژدهٔ دل‌دار بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1938799,2377,6,1,'کای صَبا نَکهَتی از کویِ فلانی به من آر',NULL,NULL);
INSERT INTO "verses" VALUES(1938800,2377,6,0,'دلم از دست بِشُد دوش چو حافظ می‌گفت','دیشب بسیار غمگین‌شدم وقتی‌که حافظ را دیدم که از نسیم، پیامی از یارش طلب‌می‌کرد.',NULL);
INSERT INTO "verses" VALUES(1938801,2377,5,1,'یا ز دیوانِ قضا خطِّ امانی به من آر',NULL,NULL);
INSERT INTO "verses" VALUES(1938802,2377,5,0,'ساقیا عشرتِ امروز به فردا مَفِکَن','ای ساقی، وعده بزم و می‌گساری فردا به‌من مده؛ زیرا تضمینی برای «فردا» وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1938803,2377,4,1,'وگر ایشان نَستانند روانی به من آر',NULL,NULL);
INSERT INTO "verses" VALUES(1938804,2379,2,0,'زلفِ چون عَنبَرِ خامَش که ببوید؟ هیهات','هوش مصنوعی: زلفی که مانند عطرِ خوشبوی عَنْبَر خام است، چه کسی آن را استشمام می‌کند؟ ای دلِ بی‌خبر، این آرزو را فراموش کن.',NULL);
INSERT INTO "verses" VALUES(1938805,2379,2,1,'ای دلِ خام‌طمع! این سخن از یاد بِبَر',NULL,NULL);
INSERT INTO "verses" VALUES(1938806,2379,3,0,'سینه گو «شعلهٔ آتشکدهٔ فارس بِکُش»','هوش مصنوعی: دل را به یاد شعله‌های آتشکده‌های باستانی فارس گرم کن و چشم را به زیبایی آب‌های دجله در بغداد خیره کن.',NULL);
INSERT INTO "verses" VALUES(1938807,2379,3,1,'دیده گو «آبِ رخِ دجلهٔ بغداد بِبَر»',NULL,NULL);
INSERT INTO "verses" VALUES(1938808,2381,3,1,'حاشَ لِلَّه که رَوَم من ز پِیِ یارِ دگر',NULL,NULL);
INSERT INTO "verses" VALUES(1938809,2381,3,0,'یار اگر رفت و حقِ صحبتِ دیرین نشناخت','هوش مصنوعی: اگر دوست رفت و یاد رابطه‌ قدیمی‌اش را فراموش کرد، به خدا قسم که من هرگز به دنبال دوست دیگری نمی‌روم.',NULL);
INSERT INTO "verses" VALUES(1938810,2381,2,1,'تا بَرَم گوهرِ خود را به خریدارِ دگر',NULL,NULL);
INSERT INTO "verses" VALUES(1938811,2381,2,0,'معرفت نیست در این قوم خدا را سَبَبی','هوش مصنوعی: در این جمع خداشناسی وجود ندارد، بنابراین از کسی نخواهم که عطف توجه کند و ارزش واقعی‌ام را به دیگری بفروشد.',NULL);
INSERT INTO "verses" VALUES(1938812,2381,1,1,'تا زنم آب درِ میکده یک بارِ دگر',NULL,NULL);
INSERT INTO "verses" VALUES(1938813,2381,1,0,'خُرَّم آن روز که با دیدهٔ گریان بِرَوَم','هوش مصنوعی: روز خوشی است که با چشمان پر از اشک به میکده بروم و دوباره از نوشیدنی آنجا بهره‌مند شوم.',NULL);
INSERT INTO "verses" VALUES(1938814,2381,0,1,'بجز از خدمتِ رندان نکنم کارِ دِگَر',NULL,NULL);
INSERT INTO "verses" VALUES(1938815,2381,0,0,'گر بُوَد عمر، به میخانه رَسَم بارِ دِگَر','هوش مصنوعی: اگر عمری باقی باشد، به میخانه برمی‌گردم و جز خدمت به دوستان قدیمی‌ام کار دیگری نخواهم کرد.',NULL);
INSERT INTO "verses" VALUES(1938816,2380,5,1,'فَاِنَّ الرِّبْحَ و الْخُسرانَ فِي التَّجْر',NULL,NULL);
INSERT INTO "verses" VALUES(1938817,2380,5,0,'وفا خواهی، جفاکَش باش حافظ','هوش مصنوعی: اگر به دنبال وفاداری هستی، باید سختی‌ها را تحمل کنی چرا که در این مسیر، سود و زیان به هم وابسته‌اند.',NULL);
INSERT INTO "verses" VALUES(1938818,2380,4,1,'فَغان از این تَطاول، آه از این زَجر',NULL,NULL);
INSERT INTO "verses" VALUES(1938819,2380,4,0,'دلم رفت و ندیدم رویِ دل‌دار','هوش مصنوعی: دل من رفت و نتوانستم چهره معشوقم را ببینم. از این بی‌محلی بسیار ناراحتم و آه، از این رنج و سختی.',NULL);
INSERT INTO "verses" VALUES(1938820,2380,3,1,'که بس تاریک می‌بینم شبِ هَجر',NULL,NULL);
INSERT INTO "verses" VALUES(1938821,2380,3,0,'برآی ای صبحِ روشن‌دل خدا را','هوش مصنوعی: ای صبح روشن و دلشاد، به یاد خدا برآی، چرا که شب جدايي بسیار تاریک و غم‌انگیز است و من در این تاریکی به سر می‌برم.',NULL);
INSERT INTO "verses" VALUES(1938822,2381,4,1,'هم به دست آورمش باز به پرگارِ دگر',NULL,NULL);
INSERT INTO "verses" VALUES(1938823,2380,2,1,'و لو آذَیْتَني بِالْهَجرِ و الْحَجر',NULL,NULL);
INSERT INTO "verses" VALUES(1938824,2380,1,1,'که در این رَه نباشد کار بی‌اجر',NULL,NULL);
INSERT INTO "verses" VALUES(1938825,2380,1,0,'دلا در عاشقی ثابت‌قدم باش','هوش مصنوعی: ای دل، در عشق ثابت‌قدم و استوار باش، زیرا در این مسیر هیچ کاری بی‌پاداش نیست.',NULL);
INSERT INTO "verses" VALUES(1938826,2380,0,1,'«سلامٌ فیهِ حَتّی مَطْلَعِ الفَجْر»',NULL,NULL);
INSERT INTO "verses" VALUES(1938827,2380,0,0,'شبِ وصل است و طی شد نامهٔ هَجر','هوش مصنوعی: امشب شب وصال است و دوران جدایی به پایان رسیده است. تا زمان طلوع سپیده دم، سلام و خوش آمدگویی برقرار است.',NULL);
INSERT INTO "verses" VALUES(1938828,2379,8,1,'برو از دَرگَهَش این ناله و فریاد بِبَر',NULL,NULL);
INSERT INTO "verses" VALUES(1938829,2379,8,0,'حافظ اندیشه کن از نازکیِ خاطرِ یار','هوش مصنوعی: به حساسیت و ظرافت احساسات یار توجه کن و از درگاه او این ناله و فریاد را دور کن.',NULL);
INSERT INTO "verses" VALUES(1938830,2379,7,1,'یا رب از خاطرش اندیشهٔ بیداد بِبَر',NULL,NULL);
INSERT INTO "verses" VALUES(1938831,2379,7,0,'دوش می‌گفت «به مژگانِ درازت بِکُشم»','هوش مصنوعی: دیروز کسی با چشمان درازش به من گفت که ای کاش می‌توانستم او را بکشم، یا خداوند، از دلش هر فکر و اندیشهٔ ناپسند را دور کن.',NULL);
INSERT INTO "verses" VALUES(1938832,2379,6,1,'وآن گَهَم تا به لَحَد فارغ و آزاد بِبَر',NULL,NULL);
INSERT INTO "verses" VALUES(1938833,2379,6,0,'روزِ مرگم نفسی وعدهٔ دیدار بده','هوش مصنوعی: در روز مرگم به من قول بده که بار دیگر همدیگر را ملاقات خواهیم کرد و در آن لحظه من را با آرامش و آزادی به آخرین آرامگاهم ببر.',NULL);
INSERT INTO "verses" VALUES(1938834,2379,5,1,'مزد اگر می‌طلبی، طاعتِ استاد بِبَر',NULL,NULL);
INSERT INTO "verses" VALUES(1938835,2379,5,0,'سعی‌نابرده در این راه به جایی نرسی','هوش مصنوعی: اگر در مسیر تحقیق و یادگیری تلاش نکنی، به هدف نخواهی رسید. اگر به دنبال پاداش و سودی هستی، باید از علم و تجربه استاد تبعیت کنی.',NULL);
INSERT INTO "verses" VALUES(1938836,2379,4,1,'دیگری گو «برو و نامِ من از یاد بِبَر»',NULL,NULL);
INSERT INTO "verses" VALUES(1938837,2379,4,0,'دولتِ پیرِ مُغان باد که باقی سهل است','هوش مصنوعی: خوشا به حال کسی که در سایه‌ی محبت و مشایخ پیر و دانا است، زیرا به دست آوردن نعمت‌های دیگر آسان است. برو و نام من را فراموش کن.',NULL);
INSERT INTO "verses" VALUES(1938838,2380,2,0,'من از رندی نخواهم کرد توبه','هوش مصنوعی: من هرگز از سر بازیگوشی و شیطنت توبه نخواهم کرد، حتی اگر با جدایی و بی‌اعتنایی‌ات به من آسیب برسانی.',NULL);
INSERT INTO "verses" VALUES(1938839,2370,3,0,'چو در میانِ مراد آورید دستِ امید','هوش مصنوعی: اگر در طلب مرادتان، دست به امید بیاورید، از دوستی و صحبت ما یادتان نرود.',NULL);
INSERT INTO "verses" VALUES(1938840,2370,2,1,'ز عاشقان به سرود و ترانه یاد آرید',NULL,NULL);
INSERT INTO "verses" VALUES(1938841,2370,2,0,'چو لطفِ باده کُنَد جلوه در رخِ ساقی','هوش مصنوعی: وقتی که زیبایی شراب در چهره ساقی جلوه‌گری می‌کند، یاد عاشقان را با آواز و ترانه زنده کنید.',NULL);
INSERT INTO "verses" VALUES(1938842,2359,5,1,'کنون به جز دلِ خوش هیچ در نمی‌باید',NULL,NULL);
INSERT INTO "verses" VALUES(1938843,2359,5,0,'چمن خوش است و هوا دلکَش است و مِی بی‌غَش','چمن خوش است و مفرّح و زیباست و هوا دلپذیر و شراب هم خالص است، پس در این لحظه، جز خوشی دل هیچ چیز دیگری ارزش ندارد. دنبالِ چیزی جز دلِ خوش نباش.',NULL);
INSERT INTO "verses" VALUES(1938844,2359,4,1,'چه حاجت است که مَشّاطِه‌ات بیاراید',NULL,NULL);
INSERT INTO "verses" VALUES(1938845,2359,4,0,'تو را که حُسنِ خداداده هست و حجلهٔ بخت','تو که خود زیبایی طبیعی و خدادادی داری و بختِ تو باز است، نیازی به آرایش و پیرایش دیگران نداری.',NULL);
INSERT INTO "verses" VALUES(1938846,2359,3,1,'که حلقه‌ای ز سرِ زلفِ یار بگشاید',NULL,NULL);
INSERT INTO "verses" VALUES(1938847,2359,3,0,'مقیمِ حلقهٔ ذکر است دل بدان امّید','دل در میانِ حلقه‌ی ذاکران و جمعِ عبادت کنندگان مقیم شده و اقامت گزیده (در زلفِ یار) به این امید که بتواند از سَرِ زلفِ یار، حلقه‌ئی بگشاید',NULL);
INSERT INTO "verses" VALUES(1938848,2359,2,1,'گنه ببخشد و بر عاشقان بِبَخشاید',NULL,NULL);
INSERT INTO "verses" VALUES(1938849,2359,2,0,'طمع ز فیضِ کرامت مَبُر که خُلقِ کریم','از فیض و جوششِ بخشندگی و کرامت، قطعِ امید مکُن و طمَع مَبُر! زیرا که اخلاقِ کریم و بزرگوارانه، گناهان را می‌بخشد و بر عاشقان آمرزش و بخشایش دارد',NULL);
INSERT INTO "verses" VALUES(1938850,2359,1,1,'من آن کنم که خداوندگار فرماید',NULL,NULL);
INSERT INTO "verses" VALUES(1938851,2359,1,0,'جهانیان همه گر منعِ من کنند از عشق','اگر تمام مردم مرا از عشق باز دارند، من به آنچه خداوندگار (خدا، دلدار) فرمان داده عمل می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1938852,2359,0,1,'که بویِ خیر ز زهدِ ریا نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(1938853,2359,0,0,'اگر به بادهٔ مُشکین دلم کشد، شاید','اگر دلِ من به باده‌یِ مشکین می‌کَشَد و هوسِ باده‌یِ مشکین می‌کنم، حق دارد. سزاوار است. شایسته است. چون که از زهدِ ریایی، بویِ خیر نمی‌آید. امیدی به خیر و صلاح از زهدِ ریایی نیست. (اما بویِ باده خوش و دلکش است)',NULL);
INSERT INTO "verses" VALUES(1938854,2358,6,1,'حافظ ز آه و ناله امانم نمی‌دهد',NULL,NULL);
INSERT INTO "verses" VALUES(1938855,2358,6,0,'گفتم رَوَم به خواب و ببینم جمالِ دوست','با خود گفتم که بخوابم و به خواب بروم، مگر در خواب بتوانم زیباییِ یار را ببینم. اما این حافظ از بس آه و ناله کرد، نگذاشت بخوابم که لااقل در خواب یارم را ببینم',NULL);
INSERT INTO "verses" VALUES(1938856,2358,5,1,'بدعهدیِ زمانه زمانم نمی‌دهد',NULL,NULL);
INSERT INTO "verses" VALUES(1938857,2358,5,0,'شِکَّر به صبر دست دهد عاقبت ولی','می‌دانم که سرانجام بر اثرِ صبر، می‌توان به شکَر دست یافت. اما بدعهدیِ زمانه، زمانی به من نمی‌دهد که بخواهم صبر کنم تا سرانجام به شکَر دست یابم',NULL);
INSERT INTO "verses" VALUES(1938858,2358,4,1,'دوران چو نقطه رَه به میانم نمی‌دهد',NULL,NULL);
INSERT INTO "verses" VALUES(1938859,2358,4,0,'چندان که بر کنار چو پرگار می‌شدم','هر چقدر که مانندِ پرگار، بر کنار و محیطِ دایره می‌چرخم، دوران و روزگار، حتا مانندِ نقطه‌ئی که در میانه‌یِ دایره است، راهی نمی‌دهد تا به میان (کمر)ِ معشوق دست بیابم.',NULL);
INSERT INTO "verses" VALUES(1938860,2358,3,1,'کانجا مجالِ بادِ وَزانَم نمی‌دهد',NULL,NULL);
INSERT INTO "verses" VALUES(1938861,2358,3,0,'زلفش کشید بادِ صبا چرخِ سِفله بین','بادِ صبا توانست زلفِ یار را بکَشَد! ای لعنت به این چرخِ سِفله! که آنجا و در نزدیکیِ یار و زلفِ یار، حتا اندازه‌یِ بادی که می‌وزد هم به من مجال و فرصت نمی‌دهد.',NULL);
INSERT INTO "verses" VALUES(1938862,2358,2,1,'یا هست و پرده دار نشانم نمی‌دهد',NULL,NULL);
INSERT INTO "verses" VALUES(1938863,2358,2,0,'مُردم در این فِراق و در آن پرده راه نیست','در این فراق مُردم. اما در آن پرده (خلوتِ یار) راه ندارم. انگاری که راهی در آن پرده برای من نیست. شاید هم راهی هست و پرده‌دار آن را به من نشان نمی‌دهد.',NULL);
INSERT INTO "verses" VALUES(1938864,2358,1,1,'اینم همی‌سِتانَد و آنم نمی‌دهد',NULL,NULL);
INSERT INTO "verses" VALUES(1938865,2358,1,0,'از بهرِ بوسه‌ای ز لبش جان همی‌دهم','حاضرم برای بوسه‌ئی از لبِ او، جانِ خودم را بدهم. اما او این (جان) را از من می‌ستانَد، اما آن (بوسه) را به من نمی‌دهد',NULL);
INSERT INTO "verses" VALUES(1938866,2358,0,1,'دولت خبر ز رازِ نهانم نمی‌دهد',NULL,NULL);
INSERT INTO "verses" VALUES(1938867,2358,0,0,'بخت از دهانِ دوست نشانم نمی‌دهد','بخت و اقبال من، نشانه‌ئی نمی دهد که بتوانم به وصل دهان دوست امیدوار باشم. دولت و طالع من نیز خبری برای من ندارد که رازی نهانی در آن باش',NULL);
INSERT INTO "verses" VALUES(1938868,2357,6,1,'حافظ ار نیز بداند که چُنینم چه شود؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938869,2357,6,0,'خواجه دانست که من عاشقم و هیچ نگفت','خواجه فهمید که من عاشق او هستم و چیزی نگفت. اگر حافظ هم بداند که من این گونه هستم، چه اتفاقی خواهد افتاد؟',NULL);
INSERT INTO "verses" VALUES(1938870,2357,5,1,'تا از آنم چه به پیش آید، از اینم چه شود؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938871,2359,6,0,'جمیله‌ایست عروسِ جهان، ولی هُش دار','جهان، مانندِ عروسِ زیبایی است. اما آگاه باش و مراقب باش که این عروسِ زیبا، در عقدِ کسی در نخواهد آمد. یعنی به وصالِ او نخواهی رسید',NULL);
INSERT INTO "verses" VALUES(1938872,2359,6,1,'که این مُخَدَّره در عقدِ کس نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(1938873,2359,7,0,'به لابه گفتمش ای ماهرُخ چه باشد اگر','با زاری و لابه به او گفتم: ای زیباروی! چه ایرادی دارد اگر با یک شکَر از تو (کنایه از بوسه‌ئی از چهره‌یِ یار)، کسی که دلِ آزرده و مجروحی دارد، به آسایش و راحتی برسد؟',NULL);
INSERT INTO "verses" VALUES(1938874,2359,7,1,'به یک شِکَر ز تو دلخسته‌ای بیاساید',NULL,NULL);
INSERT INTO "verses" VALUES(1938875,2361,5,1,'تا که قبول افتد و که در نظر آید',NULL,NULL);
INSERT INTO "verses" VALUES(1938876,2361,5,0,'صالح و طالِح مَتاعِ خویش نمودند','افراد نیکوکار و بدکار کالای خود را عرضه کردند تا کالای چه کسی مورد قبول واقع شود',NULL);
INSERT INTO "verses" VALUES(1938877,2361,4,1,'از نظرِ رهرُوی که در گذر آید',NULL,NULL);
INSERT INTO "verses" VALUES(1938878,2361,4,0,'تَرکِ گدایی مکن که گنج بیابی','اگر خواستار گنج (واقعی) هستی درویشی و فقر و گدایی پیشه‌کن تا از یک نگاه سالکان آن کوی، به این گنج برسی.',NULL);
INSERT INTO "verses" VALUES(1938879,2361,3,1,'چند نشینی که خواجه کی به درآید',NULL,NULL);
INSERT INTO "verses" VALUES(1938880,2361,3,0,'بر درِ اربابِ بی‌مروّتِ دنیا','چرا این‌قدر چشم تو به دست صاحبان دنیا است؟ چرا اینقدر به دنیا طمع بسته‌ای که چه‌وقت به تو روی بنماید؟',NULL);
INSERT INTO "verses" VALUES(1938881,2361,2,1,'نور ز خورشید جوی بو که برآید',NULL,NULL);
INSERT INTO "verses" VALUES(1938882,2361,2,0,'صحبت حُکّام ظلمتِ شبِ یلداست','همنشینی با حاکمان مانند شبی دراز و سرد مثل یلداست؛ به‌دنبال خورشید باش تا نور و گرمی بیابی.',NULL);
INSERT INTO "verses" VALUES(1938883,2361,1,1,'دیو چو بیرون رود فرشته درآید',NULL,NULL);
INSERT INTO "verses" VALUES(1938884,2361,1,0,'خلوتِ دل نیست جایِ صحبتِ اَضداد','خلوت دل جای چیزهای ضد هم نیست؛ وقتی که (محبت و علاقه تو) به دیو از بین برود آنوقت است که دل تو شایسته و جایگاه فرشتگان می‌شود.',NULL);
INSERT INTO "verses" VALUES(1938885,2361,0,1,'دست به‌کاری زنم که غصّه سرآید',NULL,NULL);
INSERT INTO "verses" VALUES(1938886,2361,0,0,'بر سرِ آنم که گر ز دست برآید','تصمیم دارم اگر بتوانم کاری کنم تا غم و غصه‌ها به پایان برسد',NULL);
INSERT INTO "verses" VALUES(1938887,2360,7,1,'گفتا خموش حافظ کـاین غصّه هم سر آید',NULL,NULL);
INSERT INTO "verses" VALUES(1938888,2360,7,0,'گفتم زمانِ عِشرَت دیدی که چون سر آمد؟','به او گفتم: دیدی که چگونه روزگار شادی و خوش­گذرانی به پایان رسید. محبوبم پاسخ داد: حافظ خاموش باش و شکوه نکن چرا که این غم و انده نیز به پایان خواهد رسید.',NULL);
INSERT INTO "verses" VALUES(1938889,2357,5,0,'صرف شد عمرِ گرانمایه به معشوقه و مِی','عمر ارزشمندم را صرف عشق و میگساری کردم، حالا نمی‌دانم چه بهره‌ای از این کار به دست می‌آورم و چه بر سرم خواهد آمد.',NULL);
INSERT INTO "verses" VALUES(1938890,2360,6,1,'گفتا مگوی با کس تا وقتِ آن درآید',NULL,NULL);
INSERT INTO "verses" VALUES(1938891,2360,5,1,'گفتا تو بندگی کن کاو بنده‌پرور آید',NULL,NULL);
INSERT INTO "verses" VALUES(1938892,2360,5,0,'گفتم که نوشِ لَعلَت ما را به آرزو کشت','به معشوقم گفتم: لب گوارا و سرخ تو ما را در حسرت یک بوسه کُشت. پاسخ داد: تو راه و رسم بندگی را درست به جا بیاور او خود می‌داند چگونه بنده خود را پرورش دهد و مورد لطف و عنایت قرار دهد.',NULL);
INSERT INTO "verses" VALUES(1938893,2360,4,1,'گفتا خُنُک نسیمی کز کویِ دلبر آید',NULL,NULL);
INSERT INTO "verses" VALUES(1938894,2360,4,0,'گفتم خوشا هوایی کز بادِ صبح خیزد','به او گفتم: هوایی که در هنگام صبح می‌وزد، چه اندازه خوش و نیکوست! پاسخم داد: خوشا نسیمی که از محله و کوی معشوق می‌آید.',NULL);
INSERT INTO "verses" VALUES(1938895,2360,3,1,'گفتا اگر بدانی هم اوت رهبر آید',NULL,NULL);
INSERT INTO "verses" VALUES(1938896,2360,3,0,'گفتم که بویِ زلفت گمراهِ عالَمَم کرد','به دلبندم گفتم: عطر گیسویت سبب گمراهی و رسوایی من در جهان شد، پاسخ داد: اگر نیک بدانی و آگاه باشی، همین عطر و بوی خوش سبب هدایت و راهبری تو خواهد شد.(هم اوت رهبر آید: او رهبر تو خواهد شد.)',NULL);
INSERT INTO "verses" VALUES(1938897,2360,2,1,'گفتا که شب‌رو است او از راهِ دیگر آید',NULL,NULL);
INSERT INTO "verses" VALUES(1938898,2360,2,0,'گفتم که بر خیالت راهِ نظر ببندم','به معشوقم گفتم: چشمانم را می‌بندم تا راه ورود خیال تو را بسته باشم، پاسخ داد: خیال من شبگردی چالاک و رند است و از راه دیگری وارد خواهد شد.(نکته: نکته فوق‌العاده در این بیت هوشمندی حضرت حافظ در رعایت ارتباط و تناسب بین بستن نظر و شب­رو بودن خیال معشوق است؛ چرا که وقتی چشم‌ها را ببندیم همه جا تاریک و ظلمانی می‌شود، به زیبایی هر چه تمامتر خیال معشوق به شب­رو تشبیه شده است؛ زیرا انسان شبگرد در شب بهتر راه خود را می‌یابد.)',NULL);
INSERT INTO "verses" VALUES(1938899,2360,1,1,'گفتا ز خوب‌رویان این کار کمتر آید',NULL,NULL);
INSERT INTO "verses" VALUES(1938900,2360,1,0,'گفتم ز مِهروَرزان رسمِ وفا بیاموز','به او گفتم از مهربانان راه و رسم وفاداری و مهربانی را یاد بگیر، پاسخ داد: زیبارویان هرگز وفادار و مهربان نیستند.(کم‌گرفت: این کار کمتر آید؛ آرایه کم‌‌گرفت دارد، شاعر به جای اینکه بگوید هرگز از واژه کمتر بهره برده است.)',NULL);
INSERT INTO "verses" VALUES(1938901,2360,0,1,'گفتم که ماهِ من شو گفتا اگر برآید',NULL,NULL);
INSERT INTO "verses" VALUES(1938902,2360,0,0,'گفتم غمِ تو دارم گفتا غمَت سرآید','به معشوقم گفتم: غم رسیدن به تو را دارم، پاسخ داد: روزی غمت به پایان خواهد رسید، به او گفتم بیا و ماه تابان زندگی من باش(معشوق من باش)، پاسخ داد: اگر امکان­پذیر باشد.',NULL);
INSERT INTO "verses" VALUES(1938903,2359,8,1,'که بوسهٔ تو رخِ ماه را بیالاید',NULL,NULL);
INSERT INTO "verses" VALUES(1938904,2359,8,0,'به خنده گفت که حافظ خدای را مَپسَند','با خنده گفت (پاسخ داد) که: ای حافظ! تو را به خدا قسم می‌دهم که راضی نشو و نخواه که بوسه‌یِ تو صورتِ ماه را آلوده کند.',NULL);
INSERT INTO "verses" VALUES(1938905,2360,6,0,'گفتم دلِ رحیمت کِی عزمِ صلح دارد؟','به او گفتم: دل مهربان تو چه زمانی تصمیم دارد با من آشتی کند؟ پاسخ داد: بین خودمان باشد و این راز را به کسی نگو: هر زمان وقتش شد.(نکته: نکته جالب توجه در مصراع اول پارادوکس زیبایی است که حافظ در ارتباط با دل رحیم و قهر بودن معشوق مطرح کرده است!!!)',NULL);
INSERT INTO "verses" VALUES(1938906,2361,6,0,'بلبلِ عاشق تو عمر خواه که آخِر','ای بلبل که عاشق گلستان و گل‌های زیبا هستی؛ صبر کن و عمری بخواه تا بهار و فصل شاخه‌های سرسبز و گل‌ها را ببینی.',NULL);
INSERT INTO "verses" VALUES(1938907,2357,4,1,'دیدم از پیش که در خانهٔ دینم چه شود',NULL,NULL);
INSERT INTO "verses" VALUES(1938908,2357,3,1,'من اگر مِهرِ نگاری بِگُزینم چه شود؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938909,2355,4,0,'ای جانْ حَدیثِ ما بَرِ دِلدار بازگو','ای جان، ماجرای عشق و دلم را برای محبوب بگو، اما طوری نگو که نسیم صبح از آن باخبر شود.',NULL);
INSERT INTO "verses" VALUES(1938910,2355,3,1,'باشَد کَز آن میانه یکی کارگر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1938911,2355,3,0,'از هَر کَرانه تیرِ دُعا کَرده‌ام رَوان','من از هر سو دعایم را روانه کرده‌ام. امیدوارم که یکی از آن‌ها کارساز باشد و یکی از تیرهای دعا که فرستاده‌ام، اثر کند',NULL);
INSERT INTO "verses" VALUES(1938912,2355,2,1,'کَز دستِ غَم خلاصِ مَن، آنجا مَگَر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1938913,2355,2,0,'خواهَم شُدَن به میکده گریان و دادخواه','می‌خواهم گریان و دادخواه به میکده بروم. گریه کنم و طلبِ عدالت و دادرسی کنم. شاید در آنجا از غم و اندوه من رهایی یابم.',NULL);
INSERT INTO "verses" VALUES(1938914,2355,1,1,'آری شود، وَلیکْ به خونِ جِگِر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1938915,2355,1,0,'گویند سنگْ لَعل شود، در مقامِ صبر','می‌گویند که اگر صبر و استقامت داشته باشی، می‌توان سنگ را به لعل تبدیل کرد، اما این کار فقط با تحمل درد و رنج عمیق امکان‌پذیر است. بله. سنگ لعل می‌شود. اما باید در خونِ جگر بخوابد تا لعل شود. صبر با خونِ جگر همراه است.',NULL);
INSERT INTO "verses" VALUES(1938916,2355,0,1,'وین رازِ سر به مُهر به عالَم سَمَر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1938917,2355,0,0,'تَرسَم که اشک، در غمِ ما پرده‌دَر شود','می‌ترسم که اشک‌های من، پرده‌دری کند و رازِ ما را آشکار کند. (مردم اشک‌های من را ببینند و پی به غم و غصه‌ی من ببرند و و این راز پنهان به کل جهان معروف گردد. و مردم برای قصه‌های شب، آن را تعریف کنند.',NULL);
INSERT INTO "verses" VALUES(1938918,2354,7,1,'غافل مشو که کارِ تو از ناله می‌رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938919,2354,7,0,'حافظ ز شوقِ مجلس سلطان غیاثِ دین','هوش مصنوعی: از شوق حضور در محفل سلطان غیاثِ دین غافل نباش، زیرا کار تو با ناله و گریه به نتیجه می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1938920,2354,6,1,'وز ژاله باده در قدحِ لاله می‌رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938921,2354,6,0,'بادِ بهار می‌وزد از گُلْسِتانِ شاه','هوش مصنوعی: نسیم بهاری از گلزار پادشاه می‌گذرد و باران صبحگاهی در لیوان لاله جاری می‌شود.',NULL);
INSERT INTO "verses" VALUES(1938922,2354,5,1,'مکّاره می‌نشیند و مُحتاله می‌رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938923,2354,5,0,'از رَه مَرو به عشوهٔ دنیا که این عجوز','هوش مصنوعی: از راه وجود خودش به فریب‌های دنیا نرو؛ چون این دنیا مانند زنی پیر و فریبنده است که همیشه در حال فریب دادن دیگران است.',NULL);
INSERT INTO "verses" VALUES(1938924,2354,4,1,'کش کاروانِ سِحْر ز دنباله می‌رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938925,2354,4,0,'آن چشمِ جادوانهٔ عابدفریب بین','هوش مصنوعی: چشمان فریبندهٔ آن عابد، مانند جادو، کاروانی از سحر و جادو را دنبال می‌کند.',NULL);
INSERT INTO "verses" VALUES(1938926,2354,3,1,'کاین طفل یک شبه رَهِ یک ساله می‌رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938927,2354,3,0,'طِیِّ مکان ببین و زمان در سلوکِ شعر','هوش مصنوعی: به مکان و زمان دقت کن، زیرا این شعر به تو نشان می‌دهد که چگونه این کودک با استعداد، به سرعت و در مدت کوتاهی، مسیری را طی می‌کند که دیگران در یک سال طی می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1938928,2354,2,1,'زین قندِ پارسی که به بَنگاله می‌رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938929,2354,2,0,'شِکَّرشِکن شَوَند همه طوطیانِ هند','هوش مصنوعی: همه طوطیان هند به خاطر این کلام شیرین و دل‌نشین که از زبان پارسی به بنگاله می‌رود، شاد و خوشحال می‌شوند.',NULL);
INSERT INTO "verses" VALUES(1938930,2354,1,1,'کار این زمان ز صنعتِ دَلّاله می‌رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938931,2354,1,0,'مِی ده که نوعروسِ چمن حَدِّ حُسن یافت','هوش مصنوعی: به من شرابی بده که معشوقه جوانِ باغ به نهایت زیبایی دست یافته و حالا خاطرش از مهارت آراستگی و زیبایی به سمت عشق می‌کشد.',NULL);
INSERT INTO "verses" VALUES(1938932,2354,0,1,'وین بحث با ثَلاثهٔ غَسّاله می‌رود',NULL,NULL);
INSERT INTO "verses" VALUES(1938933,2354,0,0,'ساقی حدیثِ سرو و گل و لاله می‌رود','ساقی صحبت از فصل بهار و سایه سرو و لاله و گلهای بستان آمده و زمان آنست که به آیین زردشتیان سه جام شراب برای صفای روح سر بکشیم',NULL);
INSERT INTO "verses" VALUES(1938934,2353,10,1,'به شرطِ آن که ز مجلس سخن به در نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938935,2353,10,0,'بیار باده و اول به دستِ حافظ ده','بیار باده و آن را نخست به دست حافظ بده. به شرط این که این سخن و این راز از این مجلس بیرون نرود.',NULL);
INSERT INTO "verses" VALUES(1938936,2353,9,1,'چو باشه در پِی هر صیدِ مختصر نرود',NULL,NULL);
INSERT INTO "verses" VALUES(1938937,2353,9,0,'به تاجِ هدهدم از رَه مَبَر که بازِ سفید','سعی نکن که من را با تاجِ هدهد بفریبی و از راه ببری. چون که بازِ سفید پرنده ای است که مانندِ باشه که مرغِ کوچکی است، به دنبالِ صیدِ کوچک نمی رود. تاجِ هدهد در شان من نیست و برای من مختصر است. من هدف بزرگتری دارم.',NULL);
INSERT INTO "verses" VALUES(1938938,2355,4,1,'لیکن چنان مَگو که صَبا را خَبَر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1938939,2355,5,0,'از کیمیایِ مِهرِ تو زَر گَشت رویِ مَن','عشقِ تو چهره من را زرد کرده‌است. واقعاً با مهربانی‌های شما، حتی خاک هم می‌تواند به طلا تبدیل شود. (انسان و چهره انسان از خاک ساخته شده و طلا نیز رنگ زرد دارد) به کنایه گفته است که من از غم عشق تو زردرو و رنجور شده‌ام. همرنگ طلا!',NULL);
INSERT INTO "verses" VALUES(1938940,2355,5,1,'آری به یُمْنِ لطفِ شُما خاک، زَر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1938941,2355,6,0,'دَر تنگنایِ حِیرتَم از نِخوتِ رَقیب','این نخوت و غرور و تکبر مراقب و نگهبانِ تو، من را به حیرت انداخته‌است. ای پروردگارا، نگذار که شخص بی‌ارزشی موقعیت و اعتبار پیدا کند.',NULL);
INSERT INTO "verses" VALUES(1938942,2357,3,0,'واعظِ شهر چو مِهرِ مَلِک و شَحنه گُزید','وقتی واعظ شهر، مهر و محبتِ شاه و پاسبان را برگزیده است، اگر من محبت و عشق یک معشوق را انتخاب کنم، چه عیبی دارد؟',NULL);
INSERT INTO "verses" VALUES(1938943,2357,2,1,'گر فِتَد عکسِ تو بر نقشِ نگینم چه شود؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938944,2357,2,0,'آخِر ای خاتَمِ جمشیدِ همایون آثار','ای انگشتریِ جمشیدِ همایون آثار! چه می‌شود اگر تصویر تو بر نقشِ نگین من بیافتد',NULL);
INSERT INTO "verses" VALUES(1938945,2357,1,1,'گر منِ سوخته یک دَم بنشینم چه شود؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938946,2357,1,0,'یا رب اندر کَنَفِ سایهٔ آن سروِ بلند','ای خدا! اگر منی که از گرما سوخته ام، یک لحظه در زیر سایه آن سرو بلند استراحت کنم، چه اتفاقی خواهد افتاد؟',NULL);
INSERT INTO "verses" VALUES(1938947,2357,0,1,'پیش پایی به چراغِ تو ببینم چه شود؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938948,2357,0,0,'گر من از باغِ تو یک میوه بچینم چه شود؟','چه اشکالی دارد اگر من از باغ تو یک میوه بچینم؟ اگر بخواهم با چراغِ تو جلویِ پای خودم را نگاه کنم، مگر چه اتفاقی می‌افتد؟',NULL);
INSERT INTO "verses" VALUES(1938949,2356,7,0,'ذره را تا نَبوَد همّتِ عالی حافظ','ذرّه و گرد و غبار هم به بالا می‌روند و می‌کوشند خود را به سمتِ چشمه‌ی خورشید برسانند. این از همّتِ عالیِ این ذره‌های کوچک است. پس تو نیز ای حافظ همّت کن. هرچند کوچکی و هدفت بزرگ است',NULL);
INSERT INTO "verses" VALUES(1938950,2356,7,1,'طالبِ چشمهٔ خورشیدِ درخشان نشود',NULL,NULL);
INSERT INTO "verses" VALUES(1938951,2356,6,0,'حُسنِ خُلقی زِ خدا می‌طلبم خویِ تو را','از خدا می‌طلبم که اخلاقِ خوب به تو بدهد و خوی تو خوب شود تا دیگر خاطر من از تو پریشان نشود و از تو نرنجم',NULL);
INSERT INTO "verses" VALUES(1938952,2356,6,1,'تا دگر خاطرِ ما از تو پریشان نشود',NULL,NULL);
INSERT INTO "verses" VALUES(1938953,2356,5,0,'دوش می‌گفت که «فردا بدهم کامِ دلت»','دیشب به من گفت که فردا کام و آرزوی تو را برآورده می‌کنم و تو را در آغوش خواهم کشید. خدایا! کارسازی کن که از انجامِ وعده‌ئی که داده پشیمان نشود.',NULL);
INSERT INTO "verses" VALUES(1938954,2356,5,1,'سببی ساز خدایا که پشیمان نشود',NULL,NULL);
INSERT INTO "verses" VALUES(1938955,2356,4,0,'عشق می‌ورزم و امّید که این فَنِّ شریف','من به عشق ورزیدن مشغولم و ادامه می‌دهم و امیدوارم که این هنر والا، همانند دیگر هنرها، موجب پشیمانی و محرومیت و حسرت نشود.',NULL);
INSERT INTO "verses" VALUES(1938956,2357,4,0,'عقلم از خانه به در رفت، وَگَر مِی این است','عقل و شعور من از ذهنم خارج شده است، و اگر شراب این است و این خاصیت را دارد، از قبل دیدم که در خانه ایمان و دینم چه بلایی خواهد آمد.',NULL);
INSERT INTO "verses" VALUES(1938957,2356,4,1,'چون هنرهایِ دگر، موجب حِرمان نشود',NULL,NULL);
INSERT INTO "verses" VALUES(1938958,2356,3,0,'اسمِ اعظم بِکُنَد کارِ خود ای دل! خوش باش','اشاره به داستان دیو و سلیمان. خاتَم و نگینِ انگشتری سلیمان نبی، مدتی به دستِ دیو افتاد و دیو با تلبیس و حیله، لباس سلیمان پوشید و خود را جایِ او جا زد. اما سلیمان با کمک اسم اعظم که دیو از آن بی بهره بود، جایگاه خود را باز یافت. شاعر می گوید که با حیله و تلبیس، دیو نمی‌تواند پیروز شود و اسم اعظم کار خود را خواهد کرد',NULL);
INSERT INTO "verses" VALUES(1938959,2356,2,0,'گوهرِ پاک بِباید که شود قابلِ فیض','لازمه‌ی توانایی و قابلیتِ جوشش و فیض یافتن، این است که گوهرِ پاک داشته باشی. وگرنه هر سنگ و گِلی تبدیل به لولو و مرجان نمی‌شود. در اصل باید این قابلیت را داشت',NULL);
INSERT INTO "verses" VALUES(1938960,2356,2,1,'وَر نه هر سنگ و گِلی، لؤلؤ و مرجان نشود',NULL,NULL);
INSERT INTO "verses" VALUES(1938961,2356,1,0,'رِندی آموز و کَرَم کُن که نه چندان هنر است','شاید در ادامه صحبتش به واعظ شهر: رندی بیاموز و بخشش و کرَم کن! که این که مانند چارپایان زندگی کنی هنری نیست! باید می بنوشی تا از مرحله‌ی حیوانیت به مرحله انسانیت برسی!',NULL);
INSERT INTO "verses" VALUES(1938962,2356,1,1,'حَیَوانی که ننوشد مِی و انسان نشود',NULL,NULL);
INSERT INTO "verses" VALUES(1938963,2356,0,0,'گر چه بر واعظِ شهر این سخن آسان نشود','هرچند می‌دانم که شنیدنِ این حرف برای واعظ شهر راحت نیست اما می‌گویم: تا زمانی که ریا و سالوس ورزد، مسلمان نخواهد شد.',NULL);
INSERT INTO "verses" VALUES(1938964,2356,0,1,'تا ریا وَرزَد و سالوس مسلمان نشود',NULL,NULL);
INSERT INTO "verses" VALUES(1938965,2355,9,1,'دَمْ دَرکَش اَر نِه بادِ صبا را خبر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1938966,2355,9,0,'حافظ چو نافهٔ سَرِ زُلفش به دَستِ توست','ای حافظ! اگر سَرِ زلفِ خوش عطرِ یار در دستِ تو است، حرفی نزن و سکوت کن و حتی نفَس‌ات را هم بیرون نده. وگرنه باد صبا باخبر خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1938967,2355,8,1,'سَرها بر آستانهٔ او خاکِ دَر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1938968,2355,8,0,'این سَرکشی که کنگرهٔ کاخِ وَصلْ راست','این دیوارهای بلند و زهوار و سرکشی روی طاق‌های کاخِ وصل، باعث می‌شود که همهٔ سرها در برابرِ آستانه و ورودیِ این کاخ، به خاک بیفتند و تسلیم شوند.',NULL);
INSERT INTO "verses" VALUES(1938969,2355,7,1,'مَقبولِ طبعِ مردمِ صاحب‌نظر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1938970,2355,7,0,'بَس نکته غیرحُسن بِباید که تا کَسی','برای جلب توجه و پسند افراد با سلیقه و فرهیخته، باید نکات زیادی را در نظر داشت و به آن‌ها توجه کرد. تنها زیبایی کافی نیست.',NULL);
INSERT INTO "verses" VALUES(1938971,2355,6,1,'یا رَب مَبادْ آن که گدا معتبر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1938972,2356,3,1,'که به تَلبیس و حِیَل، دیو مسلمان نشود',NULL,NULL);
INSERT INTO "verses" VALUES(1938973,2353,8,0,'سیاه نامه‌تر از خود کسی نمی‌بینم','از خودم گناهکار تر و کسی که نامه اعمالش سیاهتر از من باشد، نمی بینم. حق بده که دودِ دلِ من و آهِ من و کدورتِ من به سرِ من بیاید. مانندِ قلم که دوده بر سر دارد',NULL);
INSERT INTO "verses" VALUES(1938974,2361,6,1,'باغ شود سبز و شاخِ گُل به بر‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(1938975,2361,7,1,'هر که به میخانه رفت بی‌خبر آید',NULL,NULL);
INSERT INTO "verses" VALUES(1938976,2368,1,1,'فَغان فتاد به بلبل، نقابِ گُل که کشید؟',NULL,NULL);
INSERT INTO "verses" VALUES(1938977,2368,1,0,'صَفیرِ مرغ برآمد، بَطِ شراب کجاست؟','صدای خوشی از مرغ به گوش می‌رسد، بگو کجاست آن صراحی پر از شراب؟ بلبل در حال ناله و فریاد است، چه کسی نقاب گل را برداشت؟',NULL);
INSERT INTO "verses" VALUES(1938978,2368,0,1,'وظیفه گر برسد، مصرفش گُل است و نَبید',NULL,NULL);
INSERT INTO "verses" VALUES(1938979,2368,0,0,'رسید مژده که آمد بهار و سبزه دمید','خبر رسید که بهار فرا رسیده و سبزه‌ها جوانه زده‌اند. اگر مقرری و مستمری برسد، باید هزینه گل و نوشیدنی‌های خوشمزه شود.',NULL);
INSERT INTO "verses" VALUES(1938980,2367,8,1,'بخوان ز نظمش و در گوش کن چو مروارید',NULL,NULL);
INSERT INTO "verses" VALUES(1938981,2367,8,0,'ز شوقِ رویِ تو حافظ نوشت حرفی چند','هوش مصنوعی: حافظ از شدت شوق برای دیدن چهره‌ات چند کلمه‌ای نوشته است. آن‌چه او سروده را بخوان و با دقت گوش کن، زیرا کلماتش همچون مروارید گرانبها هستند.',NULL);
INSERT INTO "verses" VALUES(1938982,2367,7,1,'به سر رسید امید و طلب به سر نرسید',NULL,NULL);
INSERT INTO "verses" VALUES(1938983,2367,7,0,'به لب رسید مرا جان و برنیامد کام','هوش مصنوعی: به لب‌های من جان نزدیک شده، اما خواسته‌ام برآورده نشده است. امید و آرزو به پایان رسیده، ولی به دست نیاوردم.',NULL);
INSERT INTO "verses" VALUES(1938984,2367,6,1,'شبم به رویِ تو روشن چو روز می‌گردید',NULL,NULL);
INSERT INTO "verses" VALUES(1938985,2367,6,0,'چو ماهِ روی تو در شامِ زلف می‌دیدم','هوش مصنوعی: وقتی که چهره‌ات را در شب تاریک موهایت می‌دیدم، شب من همچون روز روشن می‌شد.',NULL);
INSERT INTO "verses" VALUES(1938986,2367,5,1,'که جنسِ خوب مُبَصِّر به هر چه دید خرید',NULL,NULL);
INSERT INTO "verses" VALUES(1938987,2367,5,0,'بهایِ وصلِ تو گر جان بُوَد خریدارم','هوش مصنوعی: اگر قیمت رسیدن به تو جان من باشد، من با کمال میل آن را می‌خرم، زیرا من به خوبی می‌دانم که ارزش واقعی را می‌توان با هر چیزی که می‌بینم به دست آورد.',NULL);
INSERT INTO "verses" VALUES(1938988,2367,4,1,'چرا که بی تو ندارم مَجالِ گفت و شَنید',NULL,NULL);
INSERT INTO "verses" VALUES(1938989,2367,4,0,'بیا که با تو بگویم غمِ ملالتِ دل','هوش مصنوعی: بیا تا درباره درد و رنج دل تو صحبت کنم، زیرا وقتی تو نیستی، فرصتی برای گفت و گو و شنیدن ندارم.',NULL);
INSERT INTO "verses" VALUES(1938990,2367,3,1,'گِلِ وجودِ من آغشتهٔ گلاب و نَبید',NULL,NULL);
INSERT INTO "verses" VALUES(1938991,2367,3,0,'نبود چنگ و رَباب و نَبید و عود، که بود','هوش مصنوعی: در اینجا به نوعی از خلوص و زیبایی درونی اشاره شده است. شاعر در این بیت بیان می‌کند که اگرچه در زندگی خود لذتی مانند موسیقی یا شراب ندارد، اما وجود او با عطر گلاب و نبیذ، یعنی با زیبایی و طراوت آمیخته شده است. این نشان‌دهنده‌ی احساساتی عمیق و معنوی است که فراتر از مسائل مادی و زودگذران می‌باشد.',NULL);
INSERT INTO "verses" VALUES(1938992,2367,2,1,'که گُل به بویِ تو بر تن چو صبح جامه درید',NULL,NULL);
INSERT INTO "verses" VALUES(1938993,2367,2,0,'مگر نسیمِ خَطَت صبح در چمن بگذشت','هوش مصنوعی: آیا نسیم صبحگاهی که بر چمن می‌وزد، از خط زیبای تو گذر کرده است که گل‌ها به بوی تو، مانند صبح که لباس‌هایش را می‌درد، شکوفا شده‌اند؟',NULL);
INSERT INTO "verses" VALUES(1938994,2367,1,1,'کمانِ ابرویِ یارم چو وَسمه بازکشید',NULL,NULL);
INSERT INTO "verses" VALUES(1938995,2367,1,0,'شکسته گشت چو پشتِ هلال قامتِ من','هوش مصنوعی: زمانی که قامت من مانند هلالی شکسته شد، کمان ابروی محبوبم به مانند خطی تیز و زیبا به شکل نما درآمد.',NULL);
INSERT INTO "verses" VALUES(1938996,2367,0,1,'هِلال عید در ابرویِ یار باید دید',NULL,NULL);
INSERT INTO "verses" VALUES(1938997,2367,0,0,'جهان بر ابرویِ عید از هِلال وَسمه کشید','هوش مصنوعی: جهان به زیبایی ابروهای معشوق به مانند هلال عید زینت یافته است. باید در ابروی یار، هلال عید را مشاهده کرد.',NULL);
INSERT INTO "verses" VALUES(1938998,2366,8,1,'کنون ز حلقهٔ زلفت به در نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(1938999,2366,8,0,'ز بس که شد دلِ حافظ رمیده از همه کس','دل حافظ از بس که از همه گریزان و رمنده شده است، اکنون دیگر نمی‌خواهد از حلقه‌ی زلف تو بیرون بیاید. (مقیم زلف تو شد دل که خوش سوادی دید)',NULL);
INSERT INTO "verses" VALUES(1939000,2366,7,1,'بلایِ زلفِ سیاهت به سر نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(1939001,2366,7,0,'در این خیال به سر شد زمانِ عمر و هنوز','عمر من در این خیال گذشت که روزی رنج و بلای هجران که همچون زلف تو سیاه و بلند است به پایان می‌رسد اما هنوز این بلا همچون زلف تو ادامه دارد.(نکته: خواجه در این بیت بلای طولانی روزگار هجران را به زلف بلند معشوق تشبیه کرده است.)',NULL);
INSERT INTO "verses" VALUES(1939002,2366,6,1,'ولی به بختِ من امشب سحر نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(1939003,2366,6,0,'بسم حکایتِ دل هست با نسیمِ سحر','حرف‌ها و گفته‌های بسیاری دارم که امشب باید به باد سحرگاهان بزنم، اما امشب از اقبال من هنگام سحر نمی‌رسد.(شب عاشقان بیدل چه شبی دراز باشد)',NULL);
INSERT INTO "verses" VALUES(1939004,2366,5,1,'ولی چه سود یکی کارگر نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(1939005,2368,2,0,'ز میوه‌های بهشتی چه ذوق دریابد','هوش مصنوعی: هر کس که سیب زَنَخدانِ محبوب را نچشیده باشد، نمی‌تواند از طعم و لذت میوه‌های بهشتی باخبر شود.',NULL);
INSERT INTO "verses" VALUES(1939006,2368,2,1,'هر آن که سیبِ زَنَخدانِ شاهدی نَگَزید',NULL,NULL);
INSERT INTO "verses" VALUES(1939007,2368,3,0,'مَکُن ز غُصّه شکایت که در طریقِ طلب','هوش مصنوعی: نگران نباش و از غم و اندوه نگو، زیرا کسی که بدون زحمت تلاش نکرده، هرگز به راحتی به هدفش نخواهد رسید.',NULL);
INSERT INTO "verses" VALUES(1939008,2368,3,1,'به راحتی نرسید آن که زحمتی نکشید',NULL,NULL);
INSERT INTO "verses" VALUES(1939009,2370,1,1,'به صوت و نغمهٔ چنگ و چَغانه یاد آرید',NULL,NULL);
INSERT INTO "verses" VALUES(1939010,2370,1,0,'به وقتِ سرخوشی از آه و ناله عُشّاق','هوش مصنوعی: در زمان‌های شادمانی، به یاد عاشقانی باشید که به خاطر درد و غمشان صدا و نغمهٔ خوش را سر می‌دهند.',NULL);
INSERT INTO "verses" VALUES(1939011,2370,0,1,'حقوقِ بندگیِ مخلصانه یاد آرید',NULL,NULL);
INSERT INTO "verses" VALUES(1939012,2370,0,0,'معاشران ز حریفِ شبانه یاد آرید','هوش مصنوعی: ای دوستان، یادآور باشید که در محافل شبانه، به حقوق و وظایف بندگی و خدمتگزاری صمیمانه فکر کنید.',NULL);
INSERT INTO "verses" VALUES(1939013,2369,8,1,'این قَدَر دانم که از شعرِ تَرَش خون می‌چکید',NULL,NULL);
INSERT INTO "verses" VALUES(1939014,2369,8,0,'تیرِ عاشق‌کُش ندانم بر دلِ حافظ که زد','هوش مصنوعی: نمی‌دانم تیر عشق که دل حافظ را هدف قرار داده، چه اندازه قوی بوده است، اما می‌دانم که از شعرهای او، غمی عمیق و خونین به دل می‌نشیند.',NULL);
INSERT INTO "verses" VALUES(1939015,2369,7,1,'گوشه‌گیران را ز آسایش طمع باید بُرید',NULL,NULL);
INSERT INTO "verses" VALUES(1939016,2369,7,0,'عدلِ سلطان گر نپرسد حالِ مظلومانِ عشق','هوش مصنوعی: اگر حاکم به حال بی‌نواها و عاشقان گوشه‌نشین توجه نکند، باید به آسایش و راحتی که به خاطر طمع به دست آمده، پایان داد.',NULL);
INSERT INTO "verses" VALUES(1939017,2369,6,1,'وین تَطاول کز سرِ زلفِ تو من دیدم، که دید؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939018,2369,6,0,'این لطایف کز لبِ لَعلِ تو من گفتم، که گفت؟','هوش مصنوعی: من از زیبایی‌ها و نکته‌های شیرین لب‌های تو گفتم، اما چه کسی به این گفته‌ها توجه کرد؟ و من از بلندی و زیبایی موهای تو حیرت کردم، اما چه کسی آن را دید؟',NULL);
INSERT INTO "verses" VALUES(1939019,2369,5,1,'جامه‌ای در نیکنامی نیز می‌باید درید',NULL,NULL);
INSERT INTO "verses" VALUES(1939020,2369,5,0,'دامنی گر چاک شد در عالمِ رندی چه باک','هوش مصنوعی: اگر دامن شخصی در دنیای رندی چاک شود، جای نگرانی نیست؛ زیرا برای بدست آوردن نیک‌نامی، گاه باید جامه‌ای را پاره کرد.',NULL);
INSERT INTO "verses" VALUES(1939021,2369,4,1,'از کریمی گوییا در گوشه‌ای بویی شنید',NULL,NULL);
INSERT INTO "verses" VALUES(1939022,2369,4,0,'با لبی و صد هزاران خنده آمد گل به باغ','هوش مصنوعی: با لبخند و شادمانی، گل به باغ آمد، گویی از یک شخص نیکوکار در گوشه‌ای بویی به مشامش رسیده بود.',NULL);
INSERT INTO "verses" VALUES(1939023,2366,5,0,'ز شَستِ صدق گشادم هزار تیرِ دعا','از شست راستی و صداقت هزار گونه تیر دعا پرتاب کرده‌­ام؛ ولی چه سود که یکی به هدف برخورد نمی‌کند.',NULL);
INSERT INTO "verses" VALUES(1939024,2369,3,1,'من همی‌کردم دعا و صبحِ صادق می‌دمید',NULL,NULL);
INSERT INTO "verses" VALUES(1939025,2369,2,1,'باده و گُل از بهایِ خرقه می‌باید خرید',NULL,NULL);
INSERT INTO "verses" VALUES(1939026,2369,2,0,'قَحطِ جُود است آبروی خود نمی‌باید فروخت','هوش مصنوعی: در زمانی که generosity یا بخشش کمیاب است، نباید آبروی خود را به خطر انداخت. برای دست یافتن به لذت‌های دنیوی مانند شراب و گل، باید هزینهٔ مهمی مثل مقام و شخصیت واقعی خود را پرداخت کرد.',NULL);
INSERT INTO "verses" VALUES(1939027,2369,1,1,'بارِ عشق و مُفلسی صَعب است، می‌باید کشید',NULL,NULL);
INSERT INTO "verses" VALUES(1939028,2369,1,0,'شاهدان در جلوه و من شرمسارِ کیسه‌ام','هوش مصنوعی: در اینجا شاعر به زیبایی و جذابیت شاهدان اشاره می‌کند و خود را در مقابل آن‌ها شرمنده می‌بیند. او از بار سنگین عشق و فقر صحبت می‌کند و بیان می‌کند که این وضعیت دشوار را باید تحمل کرد.',NULL);
INSERT INTO "verses" VALUES(1939029,2369,0,1,'وَجهِ مِی می‌خواهم و مُطرب، که می‌گوید رسید؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939030,2369,0,0,'ابرِ آذاری برآمد بادِ نوروزی وزید','هوش مصنوعی: ابرهای آذری در آسمان ظاهر شده‌اند و نسیم نوروزی شروع به وزیدن کرده است. من خواستار نوشیدنی هستم و دنبال آوازخوانی می‌گردم که بگوید: چه وقت می‌رسد؟',NULL);
INSERT INTO "verses" VALUES(1939031,2368,7,1,'که رفت موسم و حافظ هنوز مِی نچشید',NULL,NULL);
INSERT INTO "verses" VALUES(1939032,2368,7,0,'بهار می‌گذرد دادگسترا دریاب','بهار در حال گذشتن است، ای دادگستر[باده فروش]! توجه کن که زمان به پایان رسیده و حافظ هنوز طعم شراب را نچشیده است.',NULL);
INSERT INTO "verses" VALUES(1939033,2368,6,1,'که پیرِ باده‌فروشش به جُرعه‌ای نخرید',NULL,NULL);
INSERT INTO "verses" VALUES(1939034,2368,6,0,'من این مُرَقَّعِ رنگین چو گُل، بخواهم سوخت','هوش مصنوعی: من این پارچه‌ی رنگارنگ مثل گل را می‌خواهم بسوزانم، زیرا پیر مرد باده‌فروش تنها با یک جرعه از آن خریداری نکرد.',NULL);
INSERT INTO "verses" VALUES(1939035,2368,5,1,'که با کسی دِگَرَم نیست برگِ گفت و شَنید',NULL,NULL);
INSERT INTO "verses" VALUES(1939036,2368,5,0,'چُنان کرشمهٔ ساقی دلم ز دست بِبُرد','هوش مصنوعی: چنان جذبه و دلربایی از ساقی وجود دارد که تمام توجه و احساسات مرا به خود مشغول کرده است و دیگر هیچ کس را نمی‌توانم حتی بشنوم یا با او صحبت کنم.',NULL);
INSERT INTO "verses" VALUES(1939037,2368,4,1,'که گِردِ عارضِ بُستان خطِ بنفشه دمید',NULL,NULL);
INSERT INTO "verses" VALUES(1939038,2368,4,0,'ز رویِ ساقی مَه‌وَش گلی بچین امروز','هوش مصنوعی: امروز از چهره‌ی ساقی زیبا گلی بچین، زیرا در کنار صورت معشوق، خطی از گل بنفشه رشد کرده است.',NULL);
INSERT INTO "verses" VALUES(1939039,2369,3,0,'گوییا خواهد گشود از دولتم کاری که دوش','هوش مصنوعی: به نظر می‌رسد که به زودی دستانم را بر روی کاری قرار خواهد داد که شب گذشته با دعا کردن مشغول آن بودم و صبح روشنی در حال طلوع است.',NULL);
INSERT INTO "verses" VALUES(1939040,2361,7,0,'غفلتِ حافظ در این سراچه عجب نیست','غفلت و ناهشیاری حافظ در این دنیا چیز عجیبی نیست؛ هرکسی به میخانه می‌رود مست می‌شود.',NULL);
INSERT INTO "verses" VALUES(1939041,2366,4,1,'وز آن غریبِ بلاکش خبر نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(1939042,2366,3,1,'به هیچ وجه دگر کار بر نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(1939043,2364,1,0,'به پیشِ خیلِ خیالش کشیدم اَبلقِ چشم','هوش مصنوعی: به جمع خیال‌های آن معشوق شیرین‌چشم آمدم با این امید که آن جوان مرد دوباره برگردد.',NULL);
INSERT INTO "verses" VALUES(1939044,2364,0,1,'به کامِ غمزدگان غمگُسار بازآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939045,2364,0,0,'زهی خجسته زمانی که یار بازآید','هوش مصنوعی: زمانی خوش و مبارک است که معشوق دوباره برگردد و به دل‌های غمگین و غم‌زده آرامش و شادابی بخشد.',NULL);
INSERT INTO "verses" VALUES(1939046,2363,6,1,'ز خاکِ کالبدش صد هزار لاله برآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939047,2363,6,0,'نسیمِ زلفِ تو چون بگذرد به تربتِ حافظ','هوش مصنوعی: وقتی نسیم موهای تو می‌گذرد، از خاک قبر حافظ، صد هزار لاله می‌روید.',NULL);
INSERT INTO "verses" VALUES(1939048,2363,5,1,'بلا بگردد و کامِ هزارساله برآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939049,2363,5,0,'گرت چو نوحِ نبی صبر هست در غمِ طوفان','هوش مصنوعی: اگر مانند نوح پیامبر صبر داشته باشی، در سختی‌ها و مشکلات زندگی، ممکن است آن روزهای دشوار بسر بیاید و در پایان، به چیزی ارزشمند و شیرین دست یابی.',NULL);
INSERT INTO "verses" VALUES(1939050,2363,4,1,'خیال باشد کاین کار بی حواله برآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939051,2363,4,0,'به سعیِ خود نتوان بُرد پِی به گوهرِ مقصود','هوش مصنوعی: با تلاش خود نمی‌توان به حقیقت یا هدف اصلی دست یافت، زیرا این کار بدون اجازه و مقدمه‌ای مشخص انجام می‌شود.',NULL);
INSERT INTO "verses" VALUES(1939052,2363,3,1,'که بی مَلالتِ صد غُصه، یک نَواله برآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939053,2363,3,0,'ز گِردِ خوانِ نگونِ فلک طمع نتوان داشت','هوش مصنوعی: به خاطر شرایط دشوار زندگی و سختی‌های موجود، نمی‌توان امیدوار بود که بدون غم و اندوه، چیزی به راحتی به دست آید.',NULL);
INSERT INTO "verses" VALUES(1939054,2363,2,1,'که شَمِّه‌ای ز بَیانش به صد رساله برآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939055,2363,2,0,'حکایتِ شبِ هجران نه آن حکایتِ حالیست','هوش مصنوعی: داستان شب جدایی به آن اندازه گویای حال و احوال نیست که یک توضیح کوچک از آن بتواند به اندازه صد کتاب درک و بیانش کند.',NULL);
INSERT INTO "verses" VALUES(1939056,2363,1,1,'چو از میانِ چمن بویِ آن کُلاله برآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939057,2363,1,0,'نسیم در سرِ گُل بشکند کُلالهٔ سنبل','هوش مصنوعی: نسیم در سر گل کلاهی از سنبل را می‌شکند و وقتی که بوی آن کلاه از میان چمن بلند می‌شود.',NULL);
INSERT INTO "verses" VALUES(1939058,2363,0,1,'ز باغِ عارِضِ ساقی هزار لاله برآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939059,2363,0,0,'چو آفتاب مِی از مشرقِ پیاله برآید','هوش مصنوعی: زمانی که آفتابِ می، از سمت مشرق پیاله طلوع کند، از باغِ زیبایی ساقی هزاران لاله خواهد رویید.',NULL);
INSERT INTO "verses" VALUES(1939060,2362,5,1,'هر جا که نامِ حافظ در انجمن برآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939061,2362,5,0,'گویند ذکرِ خیرش در خیلِ عشقبازان','هوش مصنوعی: می‌گویند زمانی که نام حافظ در محافل عشق و عاشقی بر زبان می‌آید، همه از خوبی‌ها و یاد او صحبت می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1939062,2362,4,1,'خود کامِ تنگدستان کی زان دهن برآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939063,2362,4,0,'از حسرتِ دهانش آمد به تنگ جانم','هوش مصنوعی: از حسرت نسبت به سخنانی که او می‌تواند بگوید، روح و جانم به شدت درگیر و پریشان شده است. این افراد که دل و دماغی ندارند، چگونه می‌توانند از این گفته‌ها بهره‌مند شوند؟',NULL);
INSERT INTO "verses" VALUES(1939064,2362,3,1,'نگرفته هیچ کامی جان از بدن برآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939065,2362,3,0,'جان بر لب است و حسرت در دل که از لبانش','هوش مصنوعی: جان به لب رسیده و در دل حسرتی سنگین است، زیرا از لبانش هیچ لذتی نصیبش نشده است. در چنین حالتی، جانش به زودی از بدنش جدا خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1939066,2362,2,1,'بگشای لب که فریاد از مرد و زن برآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939067,2362,2,0,'بنمای رخ که خَلقی والِه شَوَند و حیران','هوش مصنوعی: رویت را نشان بده تا مردم شیفته و متعجب شوند، و لب‌هایت را بگشا تا صداهای شادی و ناامیدی از مردان و زنان به گوش برسد.',NULL);
INSERT INTO "verses" VALUES(1939068,2362,1,1,'کز آتش درونم دود از کفن برآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939069,2362,1,0,'بگشای تربتم را بعد از وفات و بنگر','پس از مرگم، قبرم را باز کن و ببین هنوز آتش عشق درونم شعله ور است و هرگز خاموش نخواهد شد و این آتش نمایان است',NULL);
INSERT INTO "verses" VALUES(1939070,2362,0,1,'یا تن رسد به جانان یا جان ز تن برآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939071,2362,0,0,'دست از طلب ندارم تا کامِ من برآید','هوش مصنوعی: هرگز از خواسته‌ام دست نمی‌کشم تا زمانی که به آرزوهایم برسم. یا به محبوبم خواهم رسید، یا اینکه جانم از بدنم جدا خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1939072,2364,1,1,'بدان امید که آن شهسوار بازآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939073,2364,2,0,'اگر نه در خمِ چوگان او رَوَد سَرِ من','هوش مصنوعی: اگر سر من به دست او بیفتد و در بازی چوگان او قرار بگیرد، دیگر از من نخواهید شنید که سر من چه سرنوشتی خواهد داشت.',NULL);
INSERT INTO "verses" VALUES(1939074,2364,2,1,'ز سر نگویم و سر خود چه کار بازآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939075,2364,3,0,'مقیم بر سرِ راهش نشسته‌ام چون گرد','هوش مصنوعی: من در کنار راهی که او می‌رود نشسته‌ام، چون امیدوارم که او دوباره به این مسیر برگردد.',NULL);
INSERT INTO "verses" VALUES(1939076,2366,3,0,'مگر به رویِ دلارایِ یارِ ما ور نی','همانا تنها با چهره‌‌ی زیبا و دل­آرای معشوق ما کارها به سامان می‌رسد وگرنه به هچ طریق دیگری کارها به انجام نمی‌رسد.(وجه: ایهام: ۱. شیوه ۲. رو، چهره.)',NULL);
INSERT INTO "verses" VALUES(1939077,2366,2,1,'درختِ کام و مرادم به بَر نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(1939078,2366,2,0,'قدِ بلندِ تو را تا به بَر نمی‌گیرم','تا زمانی که قامت بلند تو را در آغوش نگیرم، درخت آرزوهایم به ثمر نخواهد نشست و میوه‌ای نخواهد داد.',NULL);
INSERT INTO "verses" VALUES(1939079,2366,1,1,'که آبِ زندگیم در نظر نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(1939080,2366,1,0,'صبا به چشمِ من انداخت خاکی از کویش','باد صبا خاکی از محله‌ی معشوق در چشم من ریخت که به دنبال آن، آب حیات در نظرم بی‌ارزش شده است.',NULL);
INSERT INTO "verses" VALUES(1939081,2366,0,1,'فغان که بختِ من از خواب در نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(1939082,2366,0,0,'نفس برآمد و کام از تو بر نمی‌آید','جانم به لبم رسید و به هیچ آرزویی از تو نرسیدم، فریاد که این بخت به خواب رفته‌‌ی من قصد بیدار شدن ندارد.',NULL);
INSERT INTO "verses" VALUES(1939083,2365,7,1,'همتی تا به سلامت ز درم بازآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939084,2365,7,0,'آرزومندِ رخِ شاهِ چو ماهم حافظ','هوش مصنوعی: من به زیبایی و چهره دل‌فریب آن شاه مانند ماه آرزو دارم و از خدا می‌خواهم که همت و قدرتی به من بدهد تا او به سلامت و با خوشحالی به سراغ من بیاید.',NULL);
INSERT INTO "verses" VALUES(1939085,2365,6,1,'ور نه گر بشنود آهِ سحرم بازآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939086,2365,6,0,'مانِعَش غلغلِ چنگ است و شکرخوابِ صَبوح','هوش مصنوعی: مانع برگشت او صدای چنگ و شب‌نشینی شیرین است و اگر صدای آه صبح را بشنود، دوباره برمی‌گردد.',NULL);
INSERT INTO "verses" VALUES(1939087,2365,5,1,'گر ببینم که مَهِ نوسفرم بازآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939088,2365,5,0,'کوسِ نو دولتی از بامِ سعادت بزنم','بر بلندای بام سعادت، طبل خوشبختی می زنم اگر ببینم که معشوق تازه سفرکرده ام بازمی گردد.',NULL);
INSERT INTO "verses" VALUES(1939089,2365,4,1,'گوهرِ جان به چه کار دگرم بازآید؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939090,2366,4,0,'مقیمِ زلفِ تو شد دل که خوش سَوادی دید','از زمانی که دل غریب و بلا دیده‌ی من حلقه زلف سیاه و خوش­بوی تو را دید و در آن ساکن شد، از آن پس دیگر از دل عاشق من خبری به گوش نمی‌رسد.(نکته: در ادبیات فارسی دل در دو جا مسکن و مأوی دارد: ۱. زلف معشوق ۲. چاه زنخدان یا در محل فرو رفتگی چانه معشوق.)',NULL);
INSERT INTO "verses" VALUES(1939091,2365,4,0,'گر نثارِ قدمِ یارِ گرامی نکنم','هوش مصنوعی: اگر برای قدم‌های محبوب عزیزم نثار نکنم، پس جانم به چه کار دیگری می‌آید؟',NULL);
INSERT INTO "verses" VALUES(1939092,2365,3,0,'خواهم اندر عقبش رفت به یاران عزیز','هوش مصنوعی: من در پی او خواهم رفت و اگر خبر از او به دستم نرسد، دوباره به سمت دوستان عزیزم برمی‌گردم.',NULL);
INSERT INTO "verses" VALUES(1939093,2365,2,1,'از خدا می‌طلبم تا به سرم بازآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939094,2365,2,0,'آن که تاجِ سرِ من خاکِ کفِ پایش بود','هوش مصنوعی: من از خدا می‌خواهم که دوباره کسی که برای من همچون تاجی ارزشمند بوده و در پایین پایش قرار داشته، به سرم بازگردد.',NULL);
INSERT INTO "verses" VALUES(1939095,2365,1,1,'برقِ دولت که بِرَفت از نظرم بازآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939096,2365,1,0,'دارم امّید بر این اشکِ چو باران که دگر','هوش مصنوعی: من به این اشک‌ها که مانند باران می‌بارند، امید دارم که شاید دوباره خوشبختی که از پیشم رفته، بازگردد.',NULL);
INSERT INTO "verses" VALUES(1939097,2365,0,1,'عمرِ بگذشته به پیرانه سرم بازآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939098,2365,0,0,'اگر آن طایرِ قدسی ز دَرَم بازآید','هوش مصنوعی: اگر آن پرنده‌ی معنوی به سراغ من بیاید، زندگی از دست رفته‌ام دوباره در سال‌های پیری به من بازخواهد گشت.',NULL);
INSERT INTO "verses" VALUES(1939099,2364,6,1,'که همچو سرو به دستم نگار بازآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939100,2364,6,0,'ز نقش بندِ قضا هست امید آن حافظ','هوش مصنوعی: امید دارم که معشوقم دوباره به سوی من بازگردد، چون سروی است استوار که از طرف تقدیر به من هدیه شده است.',NULL);
INSERT INTO "verses" VALUES(1939101,2364,5,1,'به بویِ آن که دگر نوبهار بازآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939102,2364,5,0,'چه جورها که کشیدند بلبلان از دی','هوش مصنوعی: بلبلان برای بوی خوب بهاران چه سختی‌ها که تحمل کرده‌اند، تا دوباره بهار بیاید.',NULL);
INSERT INTO "verses" VALUES(1939103,2364,4,1,'گمان مَبَر که بدان دل قرار بازآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939104,2364,4,0,'دلی که با سرِ زلفین او قراری داد','هوش مصنوعی: دلی که به خاطر زیبایی و جذابیت زلف‌های او آرامش یافته، نباید تصور کنی که آن دل دوباره به آرامش خواهد رسید.',NULL);
INSERT INTO "verses" VALUES(1939105,2364,3,1,'بدان هوس که بدین رهگذار بازآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939106,2365,3,1,'شخصم ار بازنیاید خبرم بازآید',NULL,NULL);
INSERT INTO "verses" VALUES(1939107,2257,5,1,'تَرسَم آن نَرگسِ مَستانه به یَغما بِبَرَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939108,2322,5,0,'وَصْلِ خورشید بِه شَب‌پَرِّهٔ اَعْمیٰ نَرِسَد','خفاش کور نمی‌تواند به وصل خورشید برسد؛ حتی صاحب‌نظران نیز در آن دیدار، حیران می‌شوند (چه رسد به خفاش کور)',NULL);
INSERT INTO "verses" VALUES(1939109,2322,4,0,'مُفْلِسانیم و هَوایِ مِی و مُطْرِب داریم','مفلس و بی‌پول هستیم و برای می و موسیقی می‌خواهیم به خرابات برویم؛ وای بر ما اگر خرقه پشمین ما را به‌گرو قبول نکنند.',NULL);
INSERT INTO "verses" VALUES(1939110,2279,7,0,'حافظا سر ز کُلَه گوشهٔ خورشید برآر','حافظ! اگر بخت قرعهٔ آن ماه شب چهارده را به نام تو زد، بر خود ببال (سر از گوشهٔ کلاه خورشید بیرون بیاور).',NULL);
INSERT INTO "verses" VALUES(1939111,2279,6,0,'باده با محتسبِ شهر ننوشی زنهار','هشدار که باده با محتسب شهر ننوشی! زیرا باده‌ات را می‌خورد و جامت را می‌شکند.',NULL);
INSERT INTO "verses" VALUES(1939112,2279,6,1,'بخورد باده‌ات و سنگ به جام اندازد',NULL,NULL);
INSERT INTO "verses" VALUES(1939113,2279,5,0,'آن زمان وقتِ میِ صبح فروغ است که شب','آن زمان وقت نوشیدن بادهٔ روشنی بخش بامداد است که شب، پردهٔ سیاه گرداگرد اردوگاه افق می‌کشد.',NULL);
INSERT INTO "verses" VALUES(1939114,2279,5,1,'گِردِ خَرگاهِ افق پردهٔ شام اندازد',NULL,NULL);
INSERT INTO "verses" VALUES(1939115,2279,4,0,'روز در کسبِ هنر کوش که مِی خوردنِ روز','روز در آموختن هنر بکوش زیرا باده خوردن در روز، دلی را که چون آینه است دچار زنگار سیاه می‌کند',NULL);
INSERT INTO "verses" VALUES(1939116,2279,4,1,'دلِ چون آینه، در زنگِ ظَلام اندازد',NULL,NULL);
INSERT INTO "verses" VALUES(1939117,2279,3,0,'زاهدِ خام که انکارِ مِی و جام کند','اگر زاهد ناپخته [و ناسازگار]–که می و جام را انکار می‌کند–اندکی از باده تازه بنوشد، از خامی درمی‌آید [رستگار می‌شود].',NULL);
INSERT INTO "verses" VALUES(1939118,2279,3,1,'پخته گردد چو نظر بر میِ خام اندازد',NULL,NULL);
INSERT INTO "verses" VALUES(1939119,2279,2,0,'ای خوشا دولتِ آن مست که در پایِ حریف','خوش به حال مستی که نمی‌داند در پای جانان سر ببازد یا دستار!',NULL);
INSERT INTO "verses" VALUES(1939120,2279,2,1,'سر و دستار نداند که کدام اندازد',NULL,NULL);
INSERT INTO "verses" VALUES(1939121,2279,1,0,'ور چُنین زیرِ خَم زلف نهد دانهٔ خال','و اگر خال را چنین زیر شکن زلف پنهان کند، بسیاری از لاف‌زنانِ خرد را نیز به دام می‌اندازد.',NULL);
INSERT INTO "verses" VALUES(1939122,2279,1,1,'ای بسا مرغِ خِرَد را که به دام اندازد',NULL,NULL);
INSERT INTO "verses" VALUES(1939123,2279,0,0,'ساقی ار باده از این دست به جام اندازد','اگر ساقی از چنین باده‌ای در جام بریزد، همه عارفان به باده‌گساری پیوسته خواهند پرداخت.',NULL);
INSERT INTO "verses" VALUES(1939124,2279,0,1,'عارفان را همه در شُربِ مُدام اندازد',NULL,NULL);
INSERT INTO "verses" VALUES(1939125,2278,13,0,'بدین شعرِ ترِ شیرین‌، ز شاهنشَه عجب دارم','با این شعر تازه و لطیف که حافظ سرود، تعجب می‌کنم که چرا شاهنشاه سراپای او را پر از زر و جواهر نمی‌کند و قدر او را نمی‌داند؟',NULL);
INSERT INTO "verses" VALUES(1939126,2278,13,1,'که سر تا پایِ حافظ را، چرا در زر نمی‌گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939127,2278,12,0,'خدا را رحمی ای مُنْعِم‌، که درویشِ سرِ کویت','تو را به‌خدا ای صاحب توانگر، به فریاد و کمک نیازمند سر کویت برس زیرا او جز تو به دری دیگر نمی‌رود و جز تو کسی را نمی‌شناسد و به‌راه دیگر نمی‌رود.',NULL);
INSERT INTO "verses" VALUES(1939128,2278,12,1,'دری دیگر نمی‌داند، رهی دیگر نمی‌گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939129,2278,11,0,'من آن آیینه را روزی، به دست آرَم سِکَنْدَر‌وار','من روزی آن آیینه را همچون اسکندر جهاندار به‌دست خواهم آورد؛ چه آنکه این آتش زمانی درمی‌گیرد و گاهی در نمی‌گیرد.',NULL);
INSERT INTO "verses" VALUES(1939130,2278,11,1,'اگر می‌گیرد این آتش زمانی‌، ور نمی‌گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939131,2278,10,0,'سخن در احتیاجِ ما و اِسْتِغنا‌یِ معشوق است','حرف‌هایی که زده می‌شود همه از نیاز ما و ناز معشوق است؛ حیله و فن و افسون چه سود دارد وقتی که همه بر او بی‌اثر است؟',NULL);
INSERT INTO "verses" VALUES(1939132,2278,10,1,'چه سود افسونگر‌ی ای دل؟ که در دلبر نمی‌گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939133,2278,9,0,'چه خوش صیدِ دلم کردی، بنازم چَشمِ مستت را','کسی نتوانست دل مرا برباید جز تو؛ آفرین بر چشمان خمار و مست تو که هیچکس پرنده وحشی ( یا در بعضی نسخه‌ها «آهوی وحشی») را بهتر از این نمی‌تواند صید کند.',NULL);
INSERT INTO "verses" VALUES(1939134,2278,9,1,'که کَس مُرغانِ وحشی را، از این خوش‌تر نمی‌گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939135,2278,8,0,'میانِ گریه می‌خندم‌، که چون شمع اندر این مجلس','در میان گریه و در اوج غم می‌خندم زیرا همچون شمع که در مجلس می‌سوزد و خاموش است من هم زبانی گویا و آتشین دارم اما خموش هستم.',NULL);
INSERT INTO "verses" VALUES(1939136,2278,8,1,'زبانِ آتشینم هست، لیکن در نمی‌گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939137,2278,7,0,'نصیحتگو‌‌یِ رندان را، که با حکمِ قضا جنگ است','آن نصیحت‌گو که رندان مست را پند می‌دهد؛ کار او در حکم جنگ با قضا و قدر است؛ او را بسیار افسرده و غمگین می‌بینم، آیا باده نمی‌نوشد؟',NULL);
INSERT INTO "verses" VALUES(1939138,2278,7,1,'دلش بس تنگ می‌بینم، مگر ساغر نمی‌گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939139,2279,7,1,'بختت ار قرعه بدان ماهِ تمام اندازد',NULL,NULL);
INSERT INTO "verses" VALUES(1939140,2278,6,0,'سر و چَشمی چُنین دلکَش، تو گویی چشم از او بردوز؟','رخی چنین زیبا و چشمی این چنین خوش و دلکش، آنوقت تو به من می‌گویی به او نگاه مکن!؟ مرا به‌حال خود بگذار که پند بی‌معنی تو بر من بی‌اثر است.',NULL);
INSERT INTO "verses" VALUES(1939141,2280,0,0,'دَمی با غم به سر بردن، جهان یک سر نمی‌ارزد','یک لحظه زندگی با غم و اندوه، به اندازه‌ی کل جهان نمی‌ارزد. لباس درویشی من را در قبال یک جام شراب بفروش که این بهترین معامله است.',NULL);
INSERT INTO "verses" VALUES(1939142,2280,1,0,'به کویِ می فروشانش، به جامی بر نمی‌گیرند','چه بسیار سجاده ی (جانماز) انسان های به ظاهر با تقوا، که در بازار می فروشان حتی به اندازه ی یک جام شراب هم ارزش ندارد.',NULL);
INSERT INTO "verses" VALUES(1939143,2282,0,0,'سحر چون خسرو خاور، عَلَم بر کوهساران زد','بامدادان که خورشید بر کوهساران تابید، یارم از سرِ مهر درِ خانهٔ امیدواران را کوبید',NULL);
INSERT INTO "verses" VALUES(1939144,2282,1,0,'چو پیشِ صبح روشن شد که حالِ مِهر گردون چیست','هوش مصنوعی: وقتی که صبح روشن شد و مشخص شد که وضعیت خورشید چگونه است، خنده‌ای شاداب بر چهره‌ی مغرور کامیابان نشاند.',NULL);
INSERT INTO "verses" VALUES(1939145,2282,0,1,'به دستِ مرحمت، یارم، درِ امیدواران زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939146,2282,1,1,'برآمد خنده‌ای خوش بر غرورِ کامگاران زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939147,2281,6,0,'حافظ آن روز طربنامهٔ عشق تو نوشت','هوش مصنوعی: حافظ روزی را به یاد می‌آرد که دربارهٔ عشق تو شعری شاد و زیبا نوشت و قلمش با شادی و عشق بر دل خوشش نقش زد.',NULL);
INSERT INTO "verses" VALUES(1939148,2281,6,1,'که قلم بر سرِ اسبابِ دلِ خُرَّم زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939149,2281,5,0,'جانِ عِلْوی هوسِ چاهِ زنخدان تو داشت','هوش مصنوعی: جان علوی به شدت شوق و اشتیاق داشت که در چاه جادو و زیبایی‌های تو فرو رود و دستش را در حلقهٔ آن زلف‌های پیچ در پیچ تو بگذارد.',NULL);
INSERT INTO "verses" VALUES(1939150,2281,5,1,'دست در حلقهٔ آن زلفِ خَم اندر خَم زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939151,2281,4,0,'دیگران قرعهٔ قسمت همه بر عیش زدند','هوش مصنوعی: دیگران خوشی و لذت را انتخاب کردند، اما دل ما که پر از غم است، تنها به غم‌گینی ادامه داد.',NULL);
INSERT INTO "verses" VALUES(1939152,2281,4,1,'دل غمدیدهٔ ما بود که هم بر غم زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939153,2281,3,0,'مدعی خواست که آید به تماشاگَهِ راز','هوش مصنوعی: مدعی خواست رازها را ببیند، اما دست غیب به ناگاه بر سینه‌ی کسی که نباید، ضربه زد.',NULL);
INSERT INTO "verses" VALUES(1939154,2281,3,1,'دست غیب آمد و بر سینهٔ نامحرم زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939155,2281,2,0,'عقل می‌خواست کز آن شعله چراغ افروزد','عقل مصلحت اندیش می خواست از شعله ی عشق چراغ راه خودش را روشن کند و از این رهگذر سودی ببرد اما عشق مانع چراغ افروزی عقل از شعله ی عشق شد.',NULL);
INSERT INTO "verses" VALUES(1939156,2281,2,1,'برق غیرت بدرخشید و جهان برهم زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939157,2281,1,0,'جلوه‌ای کرد رُخَت دید مَلَک عشق نداشت','زمانی که جلوه ی جمال و حسن تو درخشید ٬ ابلیس آن را مشاهده کرد و چون در سرشت و فطرت او عشق وجود نداشت از شدت حسادت همچون آتش سوزان شد و خود را بر دل آدم زد تا او را از این عشق گمراه کند.',NULL);
INSERT INTO "verses" VALUES(1939158,2281,1,1,'عینِ آتش شد از این غیرت و بر آدم زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939159,2281,0,0,'در ازل پرتوِ حُسنت ز تجلی دَم زد','در عالم ابداع و پیش از آفرینش نوری از جمال الهی پدیدار گشت ؛ اشاره به حدیث قدسی (کُنتُ کَنزاً مخفیاً فاَحبَبتُ اَن اُعرَف فَخَلَقتُ الخَلقَ لِکَی اُعرَف) : گنجی پنهان بودم خواستم شناخته شوم پس خلائق را آفریدم . عشق به عنوان قوه ی محرکه که از تجلی خداوند سرچشمه می گیرد پدید آمد و منجر به ایجاد شور و شوق و تحول و حرکت در تمامی ذرات عالم گشت.',NULL);
INSERT INTO "verses" VALUES(1939160,2281,0,1,'عشق پیدا شد و آتش به همه عالم زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939161,2280,6,1,'که یک جو مِنَّتِ دونان دو صد من زر نمی‌ارزد',NULL,NULL);
INSERT INTO "verses" VALUES(1939162,2280,5,1,'که شادیِّ جهانگیری، غمِ لشکر نمی‌ارزد',NULL,NULL);
INSERT INTO "verses" VALUES(1939163,2280,6,0,'چو حافظ در قناعت کوش و از دنیایِ دون بگذر','مثل حافظ قانع باش که در قناعت گنجی هست که تورو از منت نان رها میکنه',NULL);
INSERT INTO "verses" VALUES(1939164,2280,4,1,'غلط کردم که این طوفان به صد گوهر نمی‌ارزد',NULL,NULL);
INSERT INTO "verses" VALUES(1939165,2280,5,0,'تو را آن بِهْ که رویِ خود ز مشتاقان بپوشانی','تو مثل یوسف گم گشته ای اگه بیای همه از غم میمیرن دوباره نباشی',NULL);
INSERT INTO "verses" VALUES(1939166,2280,3,1,'کلاهی دلکش است اما به تَرکِ سر نمی‌ارزد',NULL,NULL);
INSERT INTO "verses" VALUES(1939167,2280,4,0,'چه آسان می‌نمود اول غمِ دریا به بوی سود','در ابتدا فکر میکردم که تحمل سختی نوردیدن دریای طوفانی زندگی، به خاطر سود مادی اش، خیلی ساده است. واقعا اشتباه تصور میکردم زیرا صد گوهر گران بها هم به تن دادن به این طوفان نمی ارزد.',NULL);
INSERT INTO "verses" VALUES(1939168,2280,2,1,'چه افتاد این سر ما را که خاکِ در نمی‌ارزد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939169,2280,3,0,'شکوهِ تاجِ سلطانی که بیمِ جان در او دَرج است','تاج با شکوه سلطان، که در اصل ترس جانش در آن درج شده است. گرچه کلاهی زیباست، اما داشتنش به از دست دادن حضور و شرف انسانی نمی ارزد.',NULL);
INSERT INTO "verses" VALUES(1939170,2280,1,1,'زهی سجادهٔ تقوا که یک ساغر نمی‌ارزد',NULL,NULL);
INSERT INTO "verses" VALUES(1939171,2280,2,0,'رقیبم سرزنش‌ها کرد کز این باب رُخ برتاب','رغیب نادانم مرا سرزنش میکند که از رفتن به میخانه منصرف شوم. چه تصوری در ذهن ما انسان ها افتاده است که حتی سرمان از خاک در میخانه با ارزش تر است.',NULL);
INSERT INTO "verses" VALUES(1939172,2280,0,1,'به می بفروش دلقِ ما، کز این بهتر نمی‌ارزد',NULL,NULL);
INSERT INTO "verses" VALUES(1939173,2278,6,1,'برو کاین وعظ بی‌معنی‌، مرا در سر نمی‌گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939174,2278,5,0,'از آن رو هست یاران را، صفا‌ها با مِی لَعلَش','یاران و دوستان ما از آن‌جهت از باده سرخ او سرمست و سرخوش هستند که غیر از راستی و یک‌رنگی نقشی در آن گوهر ناب نمی‌گیرد و پذیرفته نمی‌شود!',NULL);
INSERT INTO "verses" VALUES(1939175,2278,5,1,'که غیر از راستی نقشی، در آن جوهر نمی‌گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939176,2275,7,0,'عجب می‌داشتم دیشب ز حافظ جام و پیمانه','دیشب در عجب بودم از حافظ و میگساری؛ اما نمی‌توانستم منعش کنم چون‌که صوفی‌وار و پاک‌باز و سخاوتمندانه می‌آورد.',NULL);
INSERT INTO "verses" VALUES(1939177,2275,7,1,'ولی مَنعَش نمی‌کردم که صوفی‌وار می‌آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939178,2275,6,0,'عَفَاالله چینِ ابرویَش اگر چه ناتوانم کرد','خدا ببخشد بر چین و اخم ابروانش‌، اگرچه مرا بیمار و غمگین کرد؛ و ناز همان ابروان درمان بیماری من بود.',NULL);
INSERT INTO "verses" VALUES(1939179,2275,6,1,'به عشوه هم پیامی بر سرِ بیمار می‌آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939180,2275,5,0,'سراسر بخششِ جانان، طریقِ لطف و احسان بود','محبوب من هرچه می‌کرد سراسر و تماما احسان و لطف بود اگر تسبیح دین دستور می‌داد و اگر زُنار بی‌دینی می‌آورد.',NULL);
INSERT INTO "verses" VALUES(1939181,2275,5,1,'اگر تسبیح می‌فرمود، اگر زُنّار می‌آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939182,2275,4,0,'به قولِ مطرب و ساقی، برون رفتم گَه و بی‌گَه','برای شنیدن ساز و آواز مطرب و نوشیدن می ساقی‌، می‌رفتم که پیغام او توسط قاصد به من نمی‌رسید (و پیام‌های او را از ساقی و مطرب می‌شنیدم)(راه گران هم به معنی راه دشوار است و هم اصطلاح موسیقی است)',NULL);
INSERT INTO "verses" VALUES(1939183,2275,4,1,'کز آن راهِ گران، قاصد، خبر، دشوار می‌آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939184,2275,3,0,'ز بیمِ غارتِ عشقش، دلِ پُرخون رها کردم','از بیم غارتگری عشق او دل غمگین و پردرد را رها کردم اما خون گریه می‌کرد و مرا دوباره به راه عشقش می‌کشاند.',NULL);
INSERT INTO "verses" VALUES(1939185,2275,3,1,'ولی می‌ریخت خون و رَه بِدان هنجار می‌آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939186,2275,2,0,'فروغِ ماه می‌دیدم ز بامِ قصر او روشن','زیبایی ماه رخ او چنان بود که تابش و درخشش آن‌، خورشید خجالت‌زده می‌شد و روی به دیوار می‌کرد.',NULL);
INSERT INTO "verses" VALUES(1939187,2275,2,1,'که رو از شرمِ آن خورشید در دیوار می‌آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939188,2275,1,0,'من آن شکلِ صِنوبر را ز باغِ دیده بَرکَندَم','منظور از صنوبر غده صنوبری یا چشم سوم هست که سد راه سالک می‌باشد و حافظ میگوید من آن بسته ام چون باعث سختی در مسیرم بود چون مسیر را باید با دید دیگری پیمود',NULL);
INSERT INTO "verses" VALUES(1939189,2275,1,1,'که هر گُل کز غمش بِشْکُفت مِحنت، بار می‌آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939190,2275,0,0,'صبا وقتِ سحر بویی ز زلفِ یار می‌آورد','بامدادان، صبا بویی از زلف یار آورد و دل شوریده را دوباره شاد کرد.',NULL);
INSERT INTO "verses" VALUES(1939191,2275,0,1,'دل شوریدهٔ ما را به نو، در کار می‌آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939192,2274,8,0,'به تنگ‌چشمیِ آن تُرکِ لشکری نازم','هوش مصنوعی: آسمان اکنون با خوشحالی به حافظ خدمت می‌کند، زیرا او به درگاه شما پناه آورده است.',NULL);
INSERT INTO "verses" VALUES(1939193,2274,8,1,'که حمله بر منِ درویشِ یک قبا آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939194,2274,7,0,'مریدِ پیرِ مُغانم ز من مرنج ای شیخ','هوش مصنوعی: من به تنگ‌چشمی آن ترک لشکری افتخار می‌کنم که به من، درویشِ ساده‌پوش، حمله کرده است.',NULL);
INSERT INTO "verses" VALUES(1939195,2274,7,1,'چرا که وعده تو کردیّ و او به جا آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939196,2274,6,0,'علاج ضعف دل ما کرشمهٔ ساقیست','ای شیخ،از من رنجیده نشو که به پیر مغان دلبسته‌ام، چون که تو وعده‌هایی دادی ولی او به آن وعده‌ها عمل کرد',NULL);
INSERT INTO "verses" VALUES(1939197,2274,6,1,'برآر سر که طبیب آمد و دوا آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939198,2274,5,0,'صبا به خوش‌خبری هُدهُدِ سلیمان است','هوش مصنوعی: درمان دل شکسستهٔ ما، ناز و کرشمهٔ ساقی است. سر خود را بلند کن، که پزشک آمده و دارویی آورده است.',NULL);
INSERT INTO "verses" VALUES(1939199,2274,5,1,'که مژدهٔ طرب از گلشنِ سبا آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939200,2274,4,0,'رسیدن گل نسرین به خیر و خوبی باد','هوش مصنوعی: نسیم بهار مانند هدهد سلیمان است که خبر خوشی از باغ‌های سرسبز و خوشبو به ارمغان می‌آورد.',NULL);
INSERT INTO "verses" VALUES(1939201,2274,4,1,'بنفشه شاد و کَش آمد، سمن صفا آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939202,2274,3,0,'دلا چو غُنچه شکایت ز کارِ بسته مکن','هوش مصنوعی: بهار با شکوفه‌های گل و نسرین خوش آمد، بنفشه‌ها شاداب و خرامان‌اند و گل‌های خوشبو صفا و آرامش را به ارمغان آورده‌اند.',NULL);
INSERT INTO "verses" VALUES(1939203,2274,3,1,'که بادِ صبح، نسیمِ گره‌گُشا آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939204,2274,2,0,'تو نیز باده به چنگ آر و راهِ صحرا گیر','هوش مصنوعی: ای دل، مثل غنچه‌ای که شکایتی از بسته بودن خود ندارد، نکن؛ زیرا که صبح، نسیمی نازک و باز کننده‌ای به همراه دارد.',NULL);
INSERT INTO "verses" VALUES(1939205,2276,0,0,'بریدِ بادِ صبا دوشم آگهی آورد','هوش مصنوعی: باد صبا دیشب خبری خوش آورد که دوران سختی و غم به پایان نزدیک می‌شود.',NULL);
INSERT INTO "verses" VALUES(1939206,2276,0,1,'که روزِ محنت و غم رو به کوتهی آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939207,2276,1,0,'به مُطربانِ صَبوحی دهیم جامهٔ چاک','هوش مصنوعی: به نوازندگان صبحگاهی، لباس پاره‌ای بدهیم تا به آن‌ها بگوییم که صبح زود، نسیمی خوش به همراه خواهد آورد.',NULL);
INSERT INTO "verses" VALUES(1939208,2276,1,1,'بدین نوید که بادِ سحرگهی آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939209,2278,4,0,'من این دَلقِ مُرَقَّع را، بخواهم سوختن روزی','روزی این جامه ریا را خواهم سوخت زیرا هرچه کردم پیر می‌فروش آن‌را به یک جام باده نخرید!',NULL);
INSERT INTO "verses" VALUES(1939210,2278,4,1,'که پیرِ مِی فروشانش‌، به جامی بر نمی‌گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939211,2278,3,0,'صُراحی می‌کشم پنهان و مردم دفتر انگارند','من باده ناب سر می‌کشم و مست هستم و مردم فکر می‌کنند که مشغول عبادت و خواندن دفتر هستم؛ شگفتا که آتش گناه این ریاکاری من در دفتر در‌نمی‌گیرد!',NULL);
INSERT INTO "verses" VALUES(1939212,2278,3,1,'عجب‌! گر آتشِ این زَرْق در دفتر نمی‌گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939213,2278,2,0,'بیا ای ساقی گُل‌رُخ‌، بیاور بادهٔ رنگین','ای ساقی لطیف‌چهره و زیبا، باده‌ای سرخ بیاور که چیزی بهتر از این نمی‌شناسیم.',NULL);
INSERT INTO "verses" VALUES(1939214,2278,2,1,'که فکری در درونِ ما، از این بهتر نمی‌گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939215,2278,1,0,'خدا را ای نصیحت‌گو، حدیثِ ساغر و مِی گو','تو را به خدا ای آدم نصیحت‌گو و خیرخواه‌، برای ما حرف از ساغر و باده بیشتر بزن که در فکر و خیال ما جز این حرف، حرف دیگری تاثیر ندارد.',NULL);
INSERT INTO "verses" VALUES(1939216,2278,1,1,'که نقشی در خیالِ ما، از این خوش‌تر نمی‌گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939217,2278,0,0,'دلم جز مِهرِ مَه‌رویان، طریقی بر نمی‌گیرد','دل من جز مهر و محبت زیبارویان به‌راه دیگری نمی‌رود و هرچه او را پند می‌دهم که از این کار دست بردارد، سودی ندارد.',NULL);
INSERT INTO "verses" VALUES(1939218,2278,0,1,'ز هر در می‌دهم پندش، ولیکن در نمی‌گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939219,2277,4,0,'خُرَّم دلِ آن که همچو حافظ','خوشا به‌حال کسی که همچون حافظ جامی از باده الست نوشید.',NULL);
INSERT INTO "verses" VALUES(1939220,2277,4,1,'جامی ز مِیِ اَلَست گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939221,2277,3,0,'در پاش فتاده‌ام به زاری','در پای او به‌زاری افتاده‌ام تا شاید مرا نجات دهد.',NULL);
INSERT INTO "verses" VALUES(1939222,2277,3,1,'آیا بوَد آن که دست گیرد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939223,2282,2,0,'نگارم دوش در مجلس، به عزمِ رقص چون برخاست','نگارم که دیشب در مجلس به قصد رقص برخاست، گره از گیسو گشود و آنرا کمند دل یاران کرد.',NULL);
INSERT INTO "verses" VALUES(1939224,2277,2,0,'در بحر فتاده‌ام چو ماهی','همچون ماهی در دریایی افتاده‌ام تا یار، مرا صید کند.',NULL);
INSERT INTO "verses" VALUES(1939225,2277,1,0,'هر کس که بدید چشم او گفت','هرکس که چشم بی‌رحم و مست او را دید فریاد برآورد که : کجاست شحنه و محتسب تا این مست را بگیرد؟',NULL);
INSERT INTO "verses" VALUES(1939226,2277,1,1,'«کو محتسبی که مست گیرد؟»',NULL,NULL);
INSERT INTO "verses" VALUES(1939227,2277,0,0,'یارم چو قدح به دست گیرد','وقتی که چشمان یار من مست می‌شود‌، تمام زیبارویان و بت‌ها در برابر زیبایی او بی‌رونق می‌شوند.',NULL);
INSERT INTO "verses" VALUES(1939228,2277,0,1,'بازارِ بتان شکست گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939229,2276,6,0,'رساند رایتِ منصور بر فلک حافظ','هوش مصنوعی: بالاخره پرچم منصور به آسمان رسید و حافظ به درگاه شاه پناه آورد.',NULL);
INSERT INTO "verses" VALUES(1939230,2276,6,1,'که اِلتِجا به جنابِ شهنشهی آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939231,2276,5,0,'چه ناله‌ها که رسید از دلم به خرمنِ ماه','هوش مصنوعی: از دل من ناله‌های زیادی به سمت جمال ماه فرستاده شد، وقتی یاد آن چهره‌ی زیبا و دلربا به خاطرم آمد.',NULL);
INSERT INTO "verses" VALUES(1939232,2276,5,1,'چو یادِ عارضِ آن ماهِ خرگهی آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939233,2276,4,0,'به جبرِ خاطرِ ما کوش کـ‌این کلاهِ نمد','در خوشحالی ما بکوش زیرا، این کلاه نمد، چه بسیار تاج شاهی را که شکست داده است!',NULL);
INSERT INTO "verses" VALUES(1939234,2276,4,1,'بسا شکست که با افسرِ شهی آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939235,2276,3,0,'همی‌رویم به شیراز با عنایتِ دوست','هوش مصنوعی: من در حال رفتن به شیراز هستم و خوشحالم که بخت و اقبالم در این سفر به من کمک کرده است. همچنین از اینکه همراهی دارم که این مسیر را با من می‌گذارد، خوشبختم.',NULL);
INSERT INTO "verses" VALUES(1939236,2276,3,1,'زهی رفیق که بختم به همرهی آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939237,2276,2,0,'بیا بیا که تو حورِ بهشت را رضوان','هوش مصنوعی: بیا که رضوان، حوری بهشت را به خاطر دلِ عاشقانه‌ات به این دنیا آورده است.',NULL);
INSERT INTO "verses" VALUES(1939238,2276,2,1,'در این جهان ز برایِ دلِ رهی آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939239,2277,2,1,'تا یار مرا به شَست گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939240,2282,2,1,'گره بگشود از گیسو و بر دل‌های یاران زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939241,2282,3,0,'من از رنگِ صلاح آن دَم، به خونِ دل بِشُستم دست','هوش مصنوعی: من در لحظه‌ای که از مقام نیکویی و صلاح جدا شدم، با دل شکسته‌ام دستم را شستم، زیرا چشمان دختری که به من اشاره کرد، به آگاهان و هوشیاران پیام عشق را رساند.',NULL);
INSERT INTO "verses" VALUES(1939242,2282,3,1,'که چشم باده پیمایش صلا بر هوشیاران زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939243,2287,5,0,'بندهٔ پیرِ مغانم که ز جهلم بِرَهانْد','هوش مصنوعی: من غلام پیر می فروشان هستم که از نادانی‌ام نکوهش می‌کنند. هر آنچه که او انجام می‌دهد، نشان از لطف و توجه او بر من است.',NULL);
INSERT INTO "verses" VALUES(1939244,2287,5,1,'پیرِ ما هر چه کُنَد عینِ عنایت باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939245,2287,4,0,'من که شب‌ها رهِ تقوا زده‌ام با دف و چنگ','من که شب‌ها با نواختن دف و چنگ تقوا را زیر پا گذاشته‌ام، چه داستانی است که ناگهان سر به راه شوم!',NULL);
INSERT INTO "verses" VALUES(1939246,2287,4,1,'این زمان سر به ره آرَم؟ چه حکایت باشد! ',NULL,NULL);
INSERT INTO "verses" VALUES(1939247,2287,3,0,'زاهد ار راه به رندی نَبَرَد معذور است','اگر زاهد راه رندی نپیماید، عذرش پذیرفته است. (زیرا) عشق کاری است که به هدایت (خداوند) نیاز دارد.',NULL);
INSERT INTO "verses" VALUES(1939248,2287,3,1,'عشق کاری‌ست که موقوف هدایت باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939249,2287,2,0,'زاهد و عجب و نماز و من و مستی و نیاز','زاهد است و خودبینی و نماز؛ منم و مستی و نیاز. تا ببینیم کدامیک را می‌پسندی.',NULL);
INSERT INTO "verses" VALUES(1939250,2287,2,1,'تا تو را خود ز میان با که عنایت باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939251,2287,1,0,'تا به غایت رهِ میخانه نمی‌دانستم','تا اخر، راه میخانه را نمی‌دانستم وگرنه، پارسایی (پرده پوشی) ما هم اندازه‌ای دارد.',NULL);
INSERT INTO "verses" VALUES(1939252,2287,1,1,'ور نه مستوری ما تا به چه غایت باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939253,2287,0,0,'من و انکارِ شراب! این چه حکایت باشد؟','من و انکار شراب؟ این چه داستانی است؟ بی شک تا این اندازه عقل و هوش دارم (که این کار را نکنم).',NULL);
INSERT INTO "verses" VALUES(1939254,2287,0,1,'غالباً این قَدَرَم عقل و کِفایت باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939255,2286,6,0,'چشمت از ناز به حافظ نکند میل آری','چشم تو به خاطر ناز توجهی به حافظ نمی‌کند؛ این سر سنگینی، صفت نرگس رعنا می‌باشد. [به استناد لغتنامهٔ دهخدا، «گل رعنا» گلی است دو رنگ.]',NULL);
INSERT INTO "verses" VALUES(1939256,2286,6,1,'سرگرانی صفتِ نرگسِ رعنا باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939257,2286,5,0,'ظِلِّ مَمدودِ خَمِ زلفِ توام بر سر باد','هوش مصنوعی: سایه‌ی بلند و گسترده‌ی موهای تو بر روی من است، مثل اینکه در این سایه، آرامش و قرار دل عاشق وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1939258,2286,5,1,'کاندر این سایه قرارِ دلِ شیدا باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939259,2286,4,0,'چون گل و مِی دمی از پرده برون آی و درآ','هوش مصنوعی: به مانند گل و شراب، برای یک لحظه از پرده بیرون بیا و در جمع ما بشتاب، زیرا ممکن نیست که دوباره فرصتی برای دیدار پیدا کنیم.',NULL);
INSERT INTO "verses" VALUES(1939260,2286,4,1,'که دگرباره ملاقات نه پیدا باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939261,2286,3,0,'از بُنِ هر مژه‌ام آب روان است بیا','هوش مصنوعی: هر کدام از مژه‌هایم مانند جویباری پرآب است. اگر دوست داری لب جوی را ببینی و تماشا کنی، بیا.',NULL);
INSERT INTO "verses" VALUES(1939262,2286,3,1,'اگرت میلِ لبِ جوی و تماشا باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939263,2286,2,0,'تو خود ای گوهرِ یک‌دانه کجایی آخِر','تو ای گوهر بی‌همتا، کجایی؛ که به خاطر غم فراق تو، چشمان مردم دریای اشک شده است.',NULL);
INSERT INTO "verses" VALUES(1939264,2286,2,1,'کز غمت دیدهٔ مردم همه دریا باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939265,2286,1,0,'من چو از خاکِ لحد لاله‌صفت برخیزم','زمانی که از خاک گور برخیزم، داغ عشق تو بر دلم، همچون راز لکهٔ سیاه خواهد بود. [«سویدا» یا همان «لکه سیاه» اشاره دارد به حدیثی که در آن خداوند بر دل گناهکار لکه‌ای سیاه به وجود می‌آورد.]',NULL);
INSERT INTO "verses" VALUES(1939266,2286,1,1,'داغِ سودای توام سِرِّ سُویدا باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939267,2286,0,0,'هر که را با خطِ سبزت سرِ سودا باشد','هرکسی روی پرطراوت تو را دید، تا روزی‌که زنده‌است عاشق تو خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1939268,2286,0,1,'پای از این دایره بیرون نَنِهَد تا باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939269,2285,8,0,'بسوخت حافظ و ترسم که شرحِ قصهٔ او','هوش مصنوعی: دوست من حافظ به شدت نگران است که داستان غم‌انگیز او هرگز به گوش پادشاهای خوشبخت نرسد.',NULL);
INSERT INTO "verses" VALUES(1939270,2285,8,1,'به سمعِ پادشهِ کامگارِ ما نرسد',NULL,NULL);
INSERT INTO "verses" VALUES(1939271,2285,7,0,'چنان بِزی که اگر خاکِ ره شوی کس را','چنان زندگی کن که اگر روزی مُردی و اجزای وجودت جزو خاک شد و در راهی ریخته شد ، حتی غباری که از آن خاک بلند میشود ، دل کسی را آزرده نکند',NULL);
INSERT INTO "verses" VALUES(1939272,2287,6,0,'دوش از این غصه نَخُفتَم که رفیقی می‌گفت','هوش مصنوعی: دیشب به خاطر این ناراحتی نتوانستم بخوابم، زیرا دوستی می‌گفت اگر حافظ مست باشد، دیگر جایی برای شکایت وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1939273,2287,6,1,'«حافظ ار مست بُوَد جایِ شکایت باشد»',NULL,NULL);
INSERT INTO "verses" VALUES(1939274,2288,0,0,'نقدِ صوفی نه همه صافیِ بی‌غَش باشد','دارایی صوفی صرفا شراب پاک و پالوده نیست؛ بلکه خرقه‌ای نیز دارند که لایق سوزاندن است.',NULL);
INSERT INTO "verses" VALUES(1939275,2288,0,1,'ای بسا خرقه که مُستوجبِ آتش باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939276,2290,1,0,'از لعلِ تو گر یابم انگشتریِ زنهار','ای خدا، ای کاش بوسه ای به نگین انگشترم می زدی تا از خاتم سلیمان هم قدرتش بیشتر می شد و فرمانروایی دنیا به دست من می افتاد (اگر امان و اختیار ویژه ای از طرف خدا برای شاعر ایجاد می شد، این نظام جبری دنیا را به هم می زد و خیلی از سرنوشت های ناخوشایند مردم را تغییر می داد). لعل: لب یار که مانند نگینی از گوهر لعل سرخ و فریبنده است و اگر انگشتری را ببوسد، نگین آن انگشتر هم لعل می شود.',NULL);
INSERT INTO "verses" VALUES(1939277,2290,1,1,'صد مُلکِ سلیمانم در زیرِ نگین باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939278,2290,0,0,'کِی شعر تر انگیزد خاطر که حزین باشد','دلی که غمگین باشد هرگز نمیتواند شعر تازه و شاداب بسراید . این موضوع ابعاد متعددی دارد که من یکی از آن ابعاد را گفتم .',NULL);
INSERT INTO "verses" VALUES(1939279,2290,0,1,'یک نکته از این معنی گفتیم و همین باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939280,2289,6,0,'به سانِ سوسن اگر دَه‌زبان شود حافظ','هوش مصنوعی: اگر حافظ مانند سوسن هزار زبان داشته باشد، همچنان مثل غنچه در مقابل تو، حرفی نخواهد زد و سکوت خواهد کرد.',NULL);
INSERT INTO "verses" VALUES(1939281,2289,6,1,'چو غنچه پیشِ تواش مُهر بر دهن باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939282,2289,5,0,'هوایِ کویِ تو از سر نمی‌رود آری','هوش مصنوعی: دلِ سرگشته و غریب هرگز از یاد تو و زیبایی‌های دیارت غافل نمی‌شود، حتی اگر دور باشم، همیشه در دل و جانم یاد تو زنده است.',NULL);
INSERT INTO "verses" VALUES(1939283,2289,5,1,'غریب را دلِ سرگشته با وطن باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939284,2289,4,0,'بیانِ شوق چه حاجت؟ که سوز آتش دل','هوش مصنوعی: نیازی به بیان عشق و شوق نیست، زیرا آتش دل را می‌توان از شدت سوزش آن فهمید، نه از کلماتی که در بیان باشد.',NULL);
INSERT INTO "verses" VALUES(1939285,2289,4,1,'توان شناخت ز سوزی که در سخن باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939286,2289,3,0,'هُمای گو مَفِکَن سایهٔ شرف هرگز','به همایِ سعادت بگو که سایه یِ لطفِ خود را بر سرزمینی که انسانهای فهیم و اندیشمند کمتر از افراد بیخرد و نادان موردِ توجه قرار می‌گیرند ، هرگز نَگُستَرانَد.',NULL);
INSERT INTO "verses" VALUES(1939287,2289,3,1,'در آن دیار که طوطی کم از زَغَن باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939288,2289,2,0,'روا مدار خدایا که در حریمِ وصال','خدایا، اجازه نده که در عرصه عشق و وصال، کسی که رقیب من است به او محرم باشد و دسترسی داشته باشد و من از آن نعمت محروم باشم و نامحرم باشم.',NULL);
INSERT INTO "verses" VALUES(1939289,2289,2,1,'رقیب محرم و حِرمان نصیبِ من باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939290,2285,7,1,'غبارِ خاطری از رهگذارِ ما نرسد',NULL,NULL);
INSERT INTO "verses" VALUES(1939291,2289,1,0,'من آن نگینِ سلیمان به هیچ نَسْتانَم','من حتی اون نگین سلیمانی رو به کمترین قیمت هم نگیرم اگر فقط قرار باشه بعضی اوقات دست اهریمن و شیطان باشه',NULL);
INSERT INTO "verses" VALUES(1939292,2289,0,0,'خوش است خلوت اگر یار یارِ من باشد','هوش مصنوعی: اگر در تنهایی با یارم باشم خوشحالم، نه اینکه من بسوزم و او مرکز جمع باشد.',NULL);
INSERT INTO "verses" VALUES(1939293,2289,0,1,'نه من بسوزم و او شمعِ انجمن باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939294,2288,6,0,'دلق و سجادهٔ حافظ ببَرَد باده‌فروش','هوش مصنوعی: اگر باده‌فروش، شرابش را از دست ساقی زیبا بگیرد، دلق و سجاده‌ی حافظ را خواهد برد.',NULL);
INSERT INTO "verses" VALUES(1939295,2288,6,1,'گر شرابش ز کفِ ساقی مَه‌وَش باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939296,2288,5,0,'غمِ دنیای دَنی چند خوری؟ باده بخور','هوش مصنوعی: چرا خود را در غم و اندوه دنیای بی‌ارزش غرق کنی؟ بهتر است به شادی بپردازی چون دل روشن و باهوش نباید گرفتار نگرانی باشد.',NULL);
INSERT INTO "verses" VALUES(1939297,2288,5,1,'حیف باشد دلِ دانا که مُشَوَّش باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939298,2288,4,0,'ناز‌پروردِ تَنَعُّم نبَرَد راه به دوست','هوش مصنوعی: کسیکه در ناز و نعمت بزرگ شده باشد، نمی‌تواند به دوست واقعی خود نزدیک شود. عشق واقعی به شیوه و راهی نیاز دارد که ویژه دل‌باختگان و عاشقان سختی‌کشیده است.',NULL);
INSERT INTO "verses" VALUES(1939299,2288,4,1,'عاشقی شیوهٔ رندانِ بلاکش باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939300,2288,3,0,'خَطِّ ساقی گر از این گونه زند نقش بر آب','اگر چنین، خط سبز ساقی، تصویر او را در آب بیاندازد، چه بسیار چهره‌هایی که در حون غوطه می‌خورند. [احتمالا منظور شاعر، افتادن تصویر زیبای ساقی در شراب سرخ باشد که تصویرش در آن شناور است و باعث شیفتگی عاشقان می‌شود.]',NULL);
INSERT INTO "verses" VALUES(1939301,2288,3,1,'ای بسا رُخ که به خونآبه مُنَقَّش باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939302,2288,2,0,'خوش بُوَد گر محکِ تجربه آید به میان','هوش مصنوعی: خوشایند است که تجربه به ما کمک کند تا افرادی را که درونشان نادرست است، شناسایی کنیم و پلیدی‌هایشان نمایان شود.',NULL);
INSERT INTO "verses" VALUES(1939303,2288,2,1,'تا سیه‌روی شود هر که در او غَش باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939304,2288,1,0,'صوفیِ ما که ز وِردِ سحری مست شدی','این صوفی ما که با دعای صبحگاهی به حالت مستی درآمده، در زمان غروب به او بنگر که از شراب انگور مست می‌شود.',NULL);
INSERT INTO "verses" VALUES(1939305,2288,1,1,'شامگاهش نگران باش که سرخوش باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939306,2289,1,1,'که گاه گاه بر او دستِ اهرمن باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939307,2274,2,1,'که مرغ نغمه‌سُرا سازِ خوش‌نوا آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939308,2285,6,0,'دلا ز رنجِ حسودان مرنج و واثق باش','هوش مصنوعی: ای دل، از رنج و آزار حسودان ناراحت نباش و با دلگرمی زندگی کن، زیرا بدی به خاطر امید ما به سراغ‌مان نخواهد آمد.',NULL);
INSERT INTO "verses" VALUES(1939309,2285,5,0,'دریغ قافله عمر کآنچنان رفتند','هوش مصنوعی: افسوس بر عمر ما که به سرعت سپری شد و طوری رفتند که حتی نشانی از آنها به دیار ما نرسید.',NULL);
INSERT INTO "verses" VALUES(1939310,2283,5,0,'اهلِ نظر دو عالم در یک نظر ببازند','عاشقانی که به عمق مسائل فکر می‌کنند، یا صاحب نظران با یک نگاه می‌توانند بی‌نهایت چیزها ی دو عالم را ببازن و از آنها بگذرند. عشق بمانند یک صحنه قمار است که در آن دست اول بازی را بر سر جان باید بازی کرد! کسانی که صاحب نظر هستند، دو عالم را با یک نگاه می‌توانند ببازند. چرا که عشق بمانند یک صحنه قمار است که در آن دست اول بازی را بر سر جان میشود بازی کرد!داو = نوبتِ بازی در قمارداوطلب = کسی که خودش نوبت را مطالبه میکند.داو = دَو : فلانی دو به دستش افتاده ... یعنی الآن نوبت او هست که دو همان داو هست...',NULL);
INSERT INTO "verses" VALUES(1939311,2283,4,1,'ماییم و کهنه دلقی کآتش در آن توان زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939312,2283,3,1,'جامِ میِ مُغانه هم با مُغان توان زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939313,2283,4,0,'درویش را نباشد برگِ سرایِ سلطان','هوش مصنوعی: درویش به درباریان و اهل سلطنت نیازی ندارد و خود را در اوج سادگی و تهیدستی می‌بیند. او با توجه به زندگی ساده‌اش، نگهداری از لباس کهنه‌اش را هم کمال می‌داند و در مورد آتش زدن، از آن به عنوان نمادی از تغییر و تحول یاد می‌کند.',NULL);
INSERT INTO "verses" VALUES(1939314,2283,2,1,'بر چشمِ دشمنان تیر، از این کمان توان زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939315,2283,3,0,'در خانقه نگنجد اسرارِ عشقبازی','در خانقاه و محل عبادت عشقبازی مجاز نیست و حتی نمی‌توان در کنار عارفان، جام می را به دست گرفت و برای این کار باید به سرای مغان رفت',NULL);
INSERT INTO "verses" VALUES(1939316,2283,1,1,'گلبانگِ سربلندی بر آسمان توان زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939317,2283,2,0,'قَدِّ خمیدهٔ ما سهلت نماید اما','ظاهراً ما متواضع، نرم، یا ضعیف به نظر می‌رسیم (قد خمیده، خمیده بودن)، یعنی ظاهر ما کسی را گول می‌زند که فکر کند ما قدرتی نداریم. اما واقعیت این است که همین ظاهر ضعیف و متواضع، می‌تواند برای دشمن خطرناک باشد؛ یعنی از همین "کمان خمیده" می‌توان تیرهای کشنده پرتاب کرد و دشمن را هدف گرفت.',NULL);
INSERT INTO "verses" VALUES(1939318,2283,0,1,'شعری بخوان که با او رَطلِ گران توان زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939319,2283,1,0,'بر آستانِ جانان گر سر توان نهادن','اگر بتوان به درگاه معشوق و محبوب جهت بندگی رسید باید از شادی و سربلندی فریاد کشید',NULL);
INSERT INTO "verses" VALUES(1939320,2283,0,0,'راهی بزن که آهی بر سازِ آن توان زد','نغمه‌ای بخوان که با ساز و آواز آن بتوان از درد آه کشید و احساسات را بیان کرد ، شعری را بخوان که بتوان همراه آن جام پر از شراب را نوشید',NULL);
INSERT INTO "verses" VALUES(1939321,2282,11,0,'ز شمشیرِ سرافشانش، ظفر آن روز بِدْرَخشید','آن روز از شمشیر سراَفشان او (شاه منصور)، پیروزی نمایان شد که مانند خورشیدِ ستاره سوز، به تنهایی بر هزاران [تن از دشمنان] تاخت.',NULL);
INSERT INTO "verses" VALUES(1939322,2282,11,1,'که چون خورشیدِ انجم‌سوز تنها بر هِزاران زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939323,2282,12,0,'دوامِ عمر و مُلکِ او، بخواه از لطف حق ای دل!','هوش مصنوعی: از خدا بخواه که عمر و قدرت او پایدار بماند، ای دل؛ زیرا سرنوشت و موفقیت او مانند سکه‌ای است که در چرخ روزگار می‌چرخد.',NULL);
INSERT INTO "verses" VALUES(1939324,2282,12,1,'که چرخ، این سکهٔ دولت به دورِ روزگاران زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939325,2282,10,0,'از آن ساعت که جامِ می به دستِ او مُشَرَّف شد','هوش مصنوعی: از آن زمانی که او با جام شراب آغشته شد، دنیا مانند ساغری پر از شادی برای میگساران به نشانه خوشحالی به گردش درآمد.',NULL);
INSERT INTO "verses" VALUES(1939326,2282,10,1,'زمانه ساغرِ شادی به یادِ می‌گساران زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939327,2282,9,0,'شهنشاهِ مظفر فر، شجاعِ مُلک و دین منصور','هوش مصنوعی: شاه پیروزمند و دلیر، منصور، که خداوندگار ملک و دین است، بخشش بی‌دریغ او به حدی است که باعث شادی و سرور بهاریان شده است.',NULL);
INSERT INTO "verses" VALUES(1939328,2282,9,1,'که جودِ بی‌دریغش خنده بر ابر بهاران زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939329,2282,8,0,'نظر بر قرعهٔ توفیق و یُمنِ دولتِ شاه است','هوش مصنوعی: نگاهی به شانس و خوشبختی توفیق و سعادت پادشاه دارم، به حافظ اجازه بده تا به خواسته‌اش برسد، چون نشانه‌ای از خوش‌شانسی برای او رقم خورده است.',NULL);
INSERT INTO "verses" VALUES(1939330,2282,8,1,'بده کامِ دلِ حافظ که فالِ بختیاران زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939331,2282,7,0,'منش با خرقهٔ پشمین، کجا اندر کمند آرم؟','من با این خرقه‌ی پشمی و آدمی ضعیف مثل من چطور می‌تواند او را به‌چنگ بیاورد؛ کسی که او با موی‌ زنجیری و حلقه‌حلقه زره‌مانند و مژگان همچون خنجرش بسیار تیغ‌بدستان را اسیر کرده‌است.',NULL);
INSERT INTO "verses" VALUES(1939332,2282,7,1,'زره‌مویی که مژگانش رهِ خنجرگزاران زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939333,2282,6,0,'در آب و رنگِ رخسارش، چه جان دادیم و خون خوردیم','هوش مصنوعی: ما برای زیبایی و جلوه چهره‌اش جان خود را فدای کردیم و رنج و سختی کشیدیم. هنگامی که اولین بار تصویرش را دیدیم، یادگار عشق بر دل عاشقان نقش بست.',NULL);
INSERT INTO "verses" VALUES(1939334,2282,6,1,'چو نقشش دست داد اول، رقم بر جان‌سپاران زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939335,2282,5,0,'خیالِ شهسواری پخت و شد ناگَه دلِ مسکین','هوش مصنوعی: در دل یک فرد عادی، ناگهان خیال یک شبان بزرگ و شجاع شکل می‌گیرد. ای خدا، او را حفظ کن، چرا که این اندیشه بر دل جوانان دلیر و سواران اثر می‌گذارد.',NULL);
INSERT INTO "verses" VALUES(1939336,2282,5,1,'خداوندا! نگه دارش که بر قلبِ سواران زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939337,2282,4,0,'کدام آهن‌دلش آموخت این آیین عیّاری؟','هوش مصنوعی: هر کسی از کجا یاد گرفته که مانند افراد شجاع و قهرمانان رفتار کند، در حالی که از ابتدا، وقتی که از تاریکی‌ها و زمان‌های بیداری بیرون آمده، چنین نشان از خود نشان داده است.',NULL);
INSERT INTO "verses" VALUES(1939338,2282,4,1,'کز اول چون برون آمد، رهِ شب‌زنده‌داران زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939339,2283,5,1,'عشق است و داوِ اول بر نقدِ جان توان زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939340,2283,6,0,'گر دولتِ وصالت خواهد دری گشودن','هوش مصنوعی: اگر کسی بخواهد به خوشبختی و دوستی تو برسد، باید با اعتماد و خیال خوب، به دروازه عشق مراجعه کند.',NULL);
INSERT INTO "verses" VALUES(1939341,2283,6,1,'سرها بدین تَخَیُّل بر آستان توان زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939342,2283,7,0,'عشق و شباب و رندی مجموعهٔ مراد است','عشق، جوانی و رندی، همه خواسته‌های ما هستند. 1-همه شرایط که فراهم باشد، می‌توان ابراز خوشنودی کرد. 2-دانش واژگان‌شناسی که باشد، می‌توان به سخنوری پرداخت. [مصرع دوم معنی دوگانه دارد]',NULL);
INSERT INTO "verses" VALUES(1939343,2285,5,1,'که گَردشان به هوایِ دیارِ ما نرسد',NULL,NULL);
INSERT INTO "verses" VALUES(1939344,2285,4,0,'هزار نقد به بازارِ کائنات آرند','هوش مصنوعی: در بازار موجودات و دنیا، هزاران چیز ارزشمند و قابل خرید و فروش وجود دارد، اما هیچکدام به ارزش و اعتبار وجودی معشوق ما نمی‌رسند.',NULL);
INSERT INTO "verses" VALUES(1939345,2285,4,1,'یکی به سکهٔ صاحب عیارِ ما نرسد',NULL,NULL);
INSERT INTO "verses" VALUES(1939346,2285,3,0,'هزار نقش برآید ز کِلکِ صُنع و یکی','هوش مصنوعی: هزاران تصویر و نقش زیبا می‌تواند از هنر و خلاقیت دیگران ایجاد شود، اما هیچ کدام به زیبایی و دلنشینی تصویر محبوب ما نخواهد بود.',NULL);
INSERT INTO "verses" VALUES(1939347,2285,3,1,'به دلپذیری نقشِ نگارِ ما نرسد',NULL,NULL);
INSERT INTO "verses" VALUES(1939348,2285,2,0,'به حق صحبت دیرین که هیچ محرمِ راز','هوش مصنوعی: به خاطر عهدی که از گذشته داریم، هیچ‌کس نمی‌تواند به یار وفادار و راستین ما نزدیک شود و رازهای ما را درک کند.',NULL);
INSERT INTO "verses" VALUES(1939349,2285,2,1,'به یارِ یک جهت حق‌گزارِ ما نرسد',NULL,NULL);
INSERT INTO "verses" VALUES(1939350,2285,1,0,'اگرچه حُسن‌فروشان به جلوه آمده‌اند','هوش مصنوعی: هرچند افرادی زیبا و جذاب در حال جلب توجه هستند، اما هیچ‌کس به زیبایی و دلربایی محبوب ما نخواهد رسید.',NULL);
INSERT INTO "verses" VALUES(1939351,2285,1,1,'کسی به حُسن و ملاحت به یارِ ما نرسد',NULL,NULL);
INSERT INTO "verses" VALUES(1939352,2285,0,0,'به حسن و خُلق و وفا کس به یارِ ما نرسد','هوش مصنوعی: هیچ‌کس به زیبایی، اخلاق خوب و وفای ما مثل یار ما نمی‌رسد و در این گفته، نمی‌توانی کار و ویژگی‌های ما را انکار کنی.',NULL);
INSERT INTO "verses" VALUES(1939353,2285,0,1,'تو را در این سخن، انکارِ کارِ ما نرسد',NULL,NULL);
INSERT INTO "verses" VALUES(1939354,2284,6,1,'که گر ستیزه کنی، روزگار بستیزد',NULL,NULL);
INSERT INTO "verses" VALUES(1939355,2284,5,1,'هزار بازی از این طُرفه‌تر برانگیزد',NULL,NULL);
INSERT INTO "verses" VALUES(1939356,2284,6,0,'بر آستانهٔ تسلیم سر بِنِه حافظ','هوش مصنوعی: سرت را به درگاه تسلیم بگذار و تسلیم شو، حافظ، زیرا اگر با روزگار در بیفتی، آن وقت زمانه هم با تو سر جنگ خواهد داشت.',NULL);
INSERT INTO "verses" VALUES(1939357,2285,6,1,'که بد به خاطرِ امیدوارِ ما نرسد',NULL,NULL);
INSERT INTO "verses" VALUES(1939358,2284,4,0,'فراز و شیب بیابان عشق، دامِ بلاست','هوش مصنوعی: عشق پر از چالش‌ها و خطرات است و در این راه، کسی لازم است که شجاع و دلیر باشد و از مشکلات نترسد.',NULL);
INSERT INTO "verses" VALUES(1939359,2284,4,1,'کجاست شیردلی کز بلا نپرهیزد',NULL,NULL);
INSERT INTO "verses" VALUES(1939360,2284,3,1,'بس آبروی که با خاک ره برآمیزد',NULL,NULL);
INSERT INTO "verses" VALUES(1939361,2284,2,1,'ز حُقِّهٔ دهنش چون شکر فرو ریزد',NULL,NULL);
INSERT INTO "verses" VALUES(1939362,2284,3,0,'من آن فریب که در نرگسِ تو می‌بینم','من زیبایی و فریبی را که در چشمان تو می‌بینم، می‌دانم که آبروهای زیادی را به خاک می‌کِشد و خوار می‌گرداند.',NULL);
INSERT INTO "verses" VALUES(1939363,2284,1,1,'چو گَرد در پِی‌اش افتم چو باد بُگْریزد',NULL,NULL);
INSERT INTO "verses" VALUES(1939364,2284,2,0,'و گر کنم طلبِ نیم بوسه صد افسوس','اگر نیم بوسه از او بخواهم، از حُقّهٔ دهانش، صد تمسخُرِ شیرین نثارم می‌کند. [1-«حُقّه» عبارت است از: الف-جعبه جادویی شعبده‌بازان؛ ب-جای جواهر. 2-«حقه مینا»، اشاره دارد به آسمان. 3-به استناد لغتنامه دهخدا، «افسوس ریختن» یعنی «تمسخر کردن».]',NULL);
INSERT INTO "verses" VALUES(1939365,2284,0,1,'ور از طلب بنشینم به کینه برخیزد',NULL,NULL);
INSERT INTO "verses" VALUES(1939366,2284,1,0,'و گر به رهگذری یک دَم از وفاداری','و اگر در رهگذاری یک دم از روی وفاداری به پایش بیفتم، چون باد می‌گریزد.',NULL);
INSERT INTO "verses" VALUES(1939367,2284,0,0,'اگر روم ز پِی‌اش فتنه‌ها برانگیزد','اگر در پی او بروم، آشوب‌ها به پا می‌کند؛ و اگر دست از جست و جوی او بکشم، به دنبال کینه‌جویی می‌افتد.',NULL);
INSERT INTO "verses" VALUES(1939368,2283,9,1,'باشد که گویِ عیشی در این جهان توان زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939369,2283,8,1,'گر راهزن تو باشی صد کاروان توان زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939370,2283,9,0,'حافظ به حَقِّ قرآن کز شِید و زرق بازآی','حافظ به حقانیت قرآن قسم که باید از فریب و مکر دور شد تا بتوان در این جهان به زندگی پرداخت',NULL);
INSERT INTO "verses" VALUES(1939371,2283,7,1,'چون جمع شد معانی گویِ بیان توان زد',NULL,NULL);
INSERT INTO "verses" VALUES(1939372,2283,8,0,'شد رهزنِ سلامت زلفِ تو وین عجب نیست','زلف تو (که به نوعی نماد زیبایی و فریبندگی است) از فرط دلربایی سلامت و راحتی من را ربوده است. و این جای تعجبی ندارد، که حتی اگر راهزن کاروان ها تو باشی به اندازه‌ای تاثیرگذار هستی که می‌توانی صد ها کاروان را متوقف کنی.',NULL);
INSERT INTO "verses" VALUES(1939373,2284,5,0,'تو عمر خواه و صبوری که چرخِ شعبده باز','هوش مصنوعی: نسبت به زندگی و زمان صبر داشته باش، زیرا زندگی همچون یک شعبده‌باز هزاران شگفتی و ماجرا برای تو در پیش دارد.',NULL);
INSERT INTO "verses" VALUES(1939374,2274,1,0,'چه راه می‌زند این مطربِ مقام شناس','هوش مصنوعی: باده را در دستانت بگیر و به سمت دشت برو، چرا که پرنده‌ای که آواز دلنشین می‌خواند، به زودی به تو خواهد رسید.',NULL);
INSERT INTO "verses" VALUES(1939375,2274,1,1,'که در میان غزل قول آشنا آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939376,2274,0,0,'چه مستی است ندانم که رو به ما آورد','هوش مصنوعی: این چه حالتی است که من در آن هستم؟ نمی‌دانم چرا کسی به سمت ما آمد، آن شخص کیست و این نوشیدنی را از کجا آورده است؟',NULL);
INSERT INTO "verses" VALUES(1939377,2263,4,0,'رویِ خاکی و نمِ چشمِ مرا خوار مدار','هوش مصنوعی: ای زمین، مرا به خاطر نمِ اشک‌های چشمانم خوار نکن، زیرا این آسمان فیروزه‌ای، خانه‌ی شادی و نشاط را از این کثیفی پر کرده است.',NULL);
INSERT INTO "verses" VALUES(1939378,2263,3,0,'ساروان! بارِ من افتاد، خدا را مددی','هوش مصنوعی: راهنما، بار من بر زمین افتاد. ای خدا، به من کمک کن که امید لطف و کرم تو همراه این وسایل سفرم باشد.',NULL);
INSERT INTO "verses" VALUES(1939379,2263,3,1,'که امیدِ کَرَمَم همرهِ این مَحمِل کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939380,2263,2,0,'قُرَّةُ الْعینِ من، آن میوهٔ دل، یادش باد','هوش مصنوعی: عزیزم، ای میوهٔ دل، یاد تو بخیر که چقدر راحت به دست آمدی، اما درعوض کار من را بسیار دشوار کردی.',NULL);
INSERT INTO "verses" VALUES(1939381,2263,2,1,'که چه آسان بشد و کارِ مرا مشکل کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939382,2263,1,0,'طوطیی را به خیالِ شکری، دل‌خوش بود','هوش مصنوعی: طوطی به خیال شیرینی و خوشی دلخوش بود، اما ناگهان طوفان نابودی آرزوهایش را از بین برد.',NULL);
INSERT INTO "verses" VALUES(1939383,2263,1,1,'ناگَهَش سیلِ فنا نقشِ اَمَل، باطل کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939384,2263,0,0,'بلبلی خونِ دلی خورد و گلی حاصل کرد','هوش مصنوعی: پرنده‌ای عاشقانه دلی می‌سوزاند و از گل‌ها بهره می‌گیرد، اما باد غیرت و حسادت دل او را با خارهایی پراکنده و آشفته پر می‌کند.',NULL);
INSERT INTO "verses" VALUES(1939385,2263,0,1,'بادِ غیرت به صدش خار، پریشان‌دل کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939386,2262,8,0,'«حافِظ»! مَکُن مَلامَتِ رِنْدان! که دَر اَزَل','هوش مصنوعی: حافظ، از سرزنش و ملامت مردان دل‌شکسته دست بردار، زیرا خدا در آغاز وجود ما را از ریا و تظاهر در دین بی‌نیاز کرده است.',NULL);
INSERT INTO "verses" VALUES(1939387,2262,8,1,'ما را خُدا زِ زُهْدِ ریا، بی‌نیاز کَرْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939388,2262,7,0,'اِی کَبْکِ خوش‌خُرام! کُجا می‌رَوی؟ بِایست!','هوش مصنوعی: ای کبک زیبا و خوشحال، کجا می‌روی؟ نایست، فریفته نشو که گربه‌ٔ زاهد در حال نماز است.',NULL);
INSERT INTO "verses" VALUES(1939389,2262,7,1,'غَرِّه مَشو! که گُرْبِهٔ زاهِد، نَماز کَرْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939390,2262,6,0,'فَرْدا که پیشگاهِ حَقیقَت شَوَد پَدید','هوش مصنوعی: روز موعود که حقیقت نمایان شود، رهگذر گناهکار شرمنده خواهد بود، زیرا اعمالش بر پایه‌ی فریب و نادرستی بوده است.',NULL);
INSERT INTO "verses" VALUES(1939391,2262,6,1,'شَرْمَنْدِه رَهْرُوی کِه عَمَل بَر مَجاز کَرْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939392,2262,5,0,'صَنْعَت مَکُن که هَرکِه مُحَبَّت، نَه راسْت باخْت','صنعت‌: در اینجا یعنی مکر‌. فراز کرد‌: بَست‌. در کار عاشقی هیچ حیله و مکری به کار نبر چرا که قلب او عشق غیر حقیقی را به درون راه نمی دهد(در را به روی آن می بندد)',NULL);
INSERT INTO "verses" VALUES(1939393,2262,5,1,'عِشْقَش به رویِ دِل، دَرِ مَعْنی، فَراز کَرْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939394,2262,4,0,'ای دِل! بیا! که ما بِه پَناهِ خُدا رَویم','آستین کوته‌: کنایه است از کسی که دست از دنیا کوتاه کرده و‌یا ادعای این عمل را دارد. دست‌‌ِ دراز‌: کنایه است از حرص‌، دست ظلم.',NULL);
INSERT INTO "verses" VALUES(1939395,2262,4,1,'زآنْچ آسْتینِ کوتَه و دَسْتِ دِراز کَرْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939396,2262,3,0,'این مُطْرِب اَز کُجاست که سازِ عِراق ساخت؟','عراق و حجاز علاوه بر نام مکان، نام‌های مایه‌های موسیقایی هستند.',NULL);
INSERT INTO "verses" VALUES(1939397,2262,3,1,'وآهَنْگِ بازْگَشْت به راهِ حِجاز کَرْد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939398,2262,2,0,'ساقی! بیا! که شاهِدِ رَعْنایِ صوفیان','دیگر‌: باز هم‌.',NULL);
INSERT INTO "verses" VALUES(1939399,2262,2,1,'دیگَر به جِلْوِه آمد و آغازِ ناز کَرْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939400,2262,1,0,'بازیِّ چَرْخ بِشْکَنَدَش بِیْضِه دَر کُلاه','«بیضه و تخم‌پرنده، در کلاه شکستن» منظور لو رفتن و بی‌اثر شدن کلک‌ها و حیله‌های یک شعبده‌باز است.',NULL);
INSERT INTO "verses" VALUES(1939401,2262,1,1,'زیرا که عَرْضِ شُعْبَدِه با اَهْلِ راز کَرْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939402,2262,0,0,'صوفی نَهاد دام و سَرِ حُقِّه، باز کَرْد','حُقه‌: یعنی کیسه. در اینجا کیسه شعبده‌بازان منظور است.',NULL);
INSERT INTO "verses" VALUES(1939403,2262,0,1,'بُنْیادِ مَکْر با فَلَکِ حُقِّه‌باز کَرْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939404,2261,5,0,'اگر امامِ جماعت طلب کند امروز','هوش مصنوعی: اگر امام جماعت بخواهد، امروز به او بگویید که حافظ به نوشیدن شراب پاک و زلال پرداخته است.',NULL);
INSERT INTO "verses" VALUES(1939405,2261,5,1,'خبر دهید که حافظ به می طهارت کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939406,2263,4,1,'چرخ فیروزه طرب‌خانه از این کَهگِل کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939407,2263,5,0,'آه و فریاد که از چشمِ حسودِ مهِ چرخ','هوش مصنوعی: آه و ناله که به خاطر حسادت آسمان، چهره زیبای من در خاک آرام گرفت.',NULL);
INSERT INTO "verses" VALUES(1939408,2263,5,1,'در لحد ماهِ کمان‌ابرویِ من منزل کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939409,2263,6,0,'نزدی شاه‌رخ و فوت شد امکان حافظ','هوش مصنوعی: وقتی به چهره زیبای معشوق نگریستم، همه چیز را فراموش کردم. چه باید بکنم؟ روزگار من را غافل کرده است.',NULL);
INSERT INTO "verses" VALUES(1939410,2265,7,0,'غیرتم کُشت که محبوبِ جهانی، لیکن','هوش مصنوعی: غیرت من باعث شد که محبوب دنیا را ترک کنم، اما نمی‌توانم روز و شب با مردم عادی سر و صدا و جنجال راه بیاندازم.',NULL);
INSERT INTO "verses" VALUES(1939411,2265,6,0,'مشکلِ عشق نه در حوصلهٔ دانشِ ماست','هوش مصنوعی: عشق مسئله‌ای عمیق‌تر از آن است که بتوان با دانش و آگاهی ما آن را حل کرد. این موضوع را نمی‌توان با تفکر نادرست و سطحی روشن کرد.',NULL);
INSERT INTO "verses" VALUES(1939412,2265,6,1,'حلّ‌ِ این نکته بدین فکرِ خطا نتوان کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939413,2265,5,0,'نظرِ پاک توانَد رخِ جانان دیدن','هوش مصنوعی: چشم پاک و دل خالص می‌تواند چهره محبوب را دیده و در آینه فقط زیبایی را مشاهده کند.',NULL);
INSERT INTO "verses" VALUES(1939414,2265,5,1,'که در آیینه نظر جز به صفا نتوان کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939415,2265,4,0,'سروبالایِ من آنگه که درآید به سَماع','هوش مصنوعی: زمانی که چهره‌ی زیبا و دل‌انگیز من در مراسمی حاضر می‌شود، دیگر چه اهمیتی دارد که لباس جان را چه‌گونه بر تن کنیم؟',NULL);
INSERT INTO "verses" VALUES(1939416,2265,4,1,'چه محل جامهٔ جان را که قبا نتوان کرد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939417,2265,3,0,'عارضش را به مَثَل ماهِ فلک نتوان گفت','هوش مصنوعی: زیبایی و شکوه او را نمی‌توان به ماه آسمان تشبیه کرد، زیرا رابطه و محبت او با دوستانش را نمی‌توان به هر کسی که بی‌معنا و بی‌ارزش است، مرتبط کرد.',NULL);
INSERT INTO "verses" VALUES(1939418,2265,3,1,'نسبتِ دوست به هر بی سر و پا نتوان کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939419,2265,2,0,'دامنِ دوست به صد خونِ دل افتاد به دست','هوش مصنوعی: دامن دوست با سختی و مشکلات فراوانی آغشته شده و به دست کسی افتاده است که می‌تواند به آن آسیب برساند، اما نمی‌توان آن را رها کرد.',NULL);
INSERT INTO "verses" VALUES(1939420,2265,2,1,'به فُسوسی که کُنَد خصم، رها نتوان کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939421,2265,1,0,'آن‌چه سعی است، من اندر طلبت بنمایم','هوش مصنوعی: هرچه که در تلاش هستم برای جستجوی تو، بدان که فقط همین اندازه است که نمی‌توانم سرنوشت را تغییر دهم.',NULL);
INSERT INTO "verses" VALUES(1939422,2265,1,1,'این قَدَر هست که تغییرِ قضا نتوان کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939423,2265,0,0,'دست در حلقهٔ آن زلفِ دوتا نتوان کرد','هوش مصنوعی: به خاطر زیبایی و پیچیدگی خویش، نمی‌توان به زلف‌های تو تکیه کرد، و نمی‌توان به وعده‌های تو و ناآرامی‌های نسیم صبح اطمینان کرد.',NULL);
INSERT INTO "verses" VALUES(1939424,2261,4,0,'دلم ز حلقهٔ زلفش به جان خرید آشوب','دلم از حلقه‌‌ی زلفش آشفتگی را به بهای جان خرید، در این تجارت چه سودی دید، نمی‌دانم.',NULL);
INSERT INTO "verses" VALUES(1939425,2265,0,1,'تکیه بر عهدِ تو و بادِ صبا نتوان کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939426,2264,6,0,'نفاق و زَرق نبخشد صفایِ دل حافظ','هوش مصنوعی: حافظ می‌گوید که هیچ‌وقت در پی پنهان‌کاری و دوگانه‌گی نخواهد بود و نمی‌خواهد دلش را با نفاق آلوده کند. او تمام تلاشش را می‌کند تا راه رندی و عشق را در پیش بگيرد و به زندگی‌اش زيبایی ببخشد.',NULL);
INSERT INTO "verses" VALUES(1939427,2264,5,0,'صبا کجاست؟ که این جانِ خون گرفته چو گُل','هوش مصنوعی: باد صبا کجاست؟ که من این جان آزرده‌ام را چون گلی فدای عطر موهای یار کنم.',NULL);
INSERT INTO "verses" VALUES(1939428,2264,5,1,'فدای نَکهَتِ گیسویِ یار خواهم کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939429,2264,4,0,'به یادِ چشم تو خود را خراب خواهم ساخت','هوش مصنوعی: برای یادآوری چشم‌های تو، خود را به نابودی می‌کشانم و عزمم بر این است که پیمان قدیم را به خوبی حفظ کنم.',NULL);
INSERT INTO "verses" VALUES(1939430,2264,4,1,'بنایِ عهدِ قدیم استوار خواهم کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939431,2264,3,0,'چو شمعِ صبحدمم شد ز مهر او روشن','هوش مصنوعی: به مانند شمعی که با نور صبح روشن می‌شود، عشق او باعث روشنی و شادی‌ام شده است، و من تصمیم دارم که تمام عمرم را صرف این عشق و تلاش برای آن کنم.',NULL);
INSERT INTO "verses" VALUES(1939432,2264,3,1,'که عمر در سر این کار و بار خواهم کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939433,2264,2,0,'هر آبروی که اندوختم ز دانش و دین','هوش مصنوعی: هر احترامی که از علم و دین به دست آورده‌ام، تقدیم خاک راه آن معشوق خواهم کرد.',NULL);
INSERT INTO "verses" VALUES(1939434,2264,2,1,'نثارِ خاکِ رهِ آن نگار خواهم کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939435,2264,1,0,'به هرزه بی می و معشوق عمر می‌گذرد','هوش مصنوعی: به هرز و بدون هدف، در حالی که نه باده‌ای دارم و نه محبوبی، عمرم می‌گذرد. امروز تصمیم گرفتم که دیگر بی‌کاری نکنم و به کار مشغول شوم.',NULL);
INSERT INTO "verses" VALUES(1939436,2264,1,1,'بِطالتم بس از امروز کار خواهم کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939437,2264,0,0,'چو باد، عزمِ سرِ کویِ یار خواهم کرد','هوش مصنوعی: مانند باد، به سوی خانه معشوق می‌روم و با بویی خوش که مانند مشکی خوش‌عطر است، نفس می‌کشم.',NULL);
INSERT INTO "verses" VALUES(1939438,2264,0,1,'نفس به بویِ خوشش مُشکبار خواهم کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939439,2263,6,1,'چه کنم؟ بازی ایام مرا غافل کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939440,2264,6,1,'طریقِ رندی و عشق اختیار خواهم کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939441,2265,7,1,'روز و شب عربده با خلقِ خدا نتوان کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939442,2261,4,1,'چه سود دید؟ ندانم، که این تجارت کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939443,2261,3,0,'امام خواجه، که بودش سرِ نمازِ دراز','هوش مصنوعی: امام خواجه که در مزاج و حالاتی خاص به نماز می‌ایستاد، به خاطر خون دختر رز، پوشش خود را به حالت کوتاه و مختصر درآورد.',NULL);
INSERT INTO "verses" VALUES(1939444,2259,3,0,'من از بیگانگان دیگر ننالم','آموختم که دیگر از دست بیگانگان و دشمنان گله نکنم و ننالم چونکه هر چه با من کرد‌، آن آشنا کرد.',NULL);
INSERT INTO "verses" VALUES(1939445,2259,3,1,'که با من هرچه کرد آن آشنا کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939446,2259,2,0,'غلامِ همتِ آن نازنینم','من بنده و غلام‌، کسی هستم که کار خیر را بدون چشمداشت و بدون خودنمایی انجام داد و به‌دیگران کمک کرد.',NULL);
INSERT INTO "verses" VALUES(1939447,2259,2,1,'که کار خیر بی روی و ریا کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939448,2259,1,0,'از آن رنگِ رُخَم، خون در دل افتاد','از آن رنگ رخ و زیبایی گل‌، دلم پرخون و پر‌حسرت شد و در بستان مرا به خار مبتلا کرد و دردمند کرد.',NULL);
INSERT INTO "verses" VALUES(1939449,2259,1,1,'وز آن گلشن، به خارم مبتلا کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939450,2259,0,0,'سحر بلبل حکایت با صبا کرد','سحری بلبل به آواز برای نسیم صبا حکایت کرد که عشق و مهر روی گل چه کارها که با ما نکرد.',NULL);
INSERT INTO "verses" VALUES(1939451,2259,0,1,'که عشقِ رویِ گل با ما چه‌ها کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939452,2258,6,0,'بسوخت حافظ و کس حالِ او به یار نگفت','حافظ از ندیدن یار سوخت و کسی از حال او به یارش نگفت، شاید نسیم‌، برای رضای خدا از او‌، پیامی ببرد.',NULL);
INSERT INTO "verses" VALUES(1939453,2258,6,1,'مگر نسیم پیامی خدای را ببرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939454,2258,5,0,'طبیبِ عشق منم باده دِه که این معجون','طبیب و حکیم بیماری عشق منم‌؛ پس پند بشنو که علاجش، باده و مستی و از خود‌بی‌خودی است و «معجون می» آسایش می‌آورد و اندیشه خطا و گناه را از تو دور می‌کند.',NULL);
INSERT INTO "verses" VALUES(1939455,2258,5,1,'فَراغت آرد و اندیشهٔ خطا ببرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939456,2258,4,0,'دل ضعیفم از آن می‌کَشَد به طَرْفِ چمن','دل ضعیف و هوس‌پیشه من از آن‌رو مرا به‌سوی چمن و بستان می‌کشاند که شاید صبا بتواند او را زنده کند.',NULL);
INSERT INTO "verses" VALUES(1939457,2258,4,1,'که جان ز مرگ به بیماریِ صبا ببرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939458,2258,3,0,'گذار بر ظلمات است، خِضْرِ راهی کو؟','مسیر و راه بر ظلمات و تاریکی‌هاست خضر و راهنمای راهی کجاست؟ مباد هوس محرومی و تشنگی‌، آبروی ما را ببرد. (یا به چشمه نرسیم و محروم بمانیم)',NULL);
INSERT INTO "verses" VALUES(1939459,2258,3,1,'مباد کآتش محرومی آبِ ما ببرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939460,2258,2,0,'فغان که با همه کس غایبانه باخت فلک','فریاد و داد که فلک با همگان‌، نهانی و در پنهان بازی‌کرد و کسی نتوانست یکبار از این دغل‌باز ببرد.',NULL);
INSERT INTO "verses" VALUES(1939461,2258,2,1,'که کس نبود که دستی از این دَغا ببرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939462,2258,1,0,'اگر نه عقل به مستی فروکَشَد لنگر','اگر عقل‌، مست نشود، در این طوفان و گرداب بلا چطور می‌تواند لنگر بکشد و جان سالم به‌در ببرد؟',NULL);
INSERT INTO "verses" VALUES(1939463,2258,1,1,'چگونه کَشتی از این وَرطِهٔ بلا ببرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939464,2258,0,0,'اگر نه باده غمِ دل ز یادِ ما بِبَرَد','اگر مستی و باده نباشد و غم دل ما را بکاهد هجوم حوادث‌، بنیاد ما را از جای ببَرَد.',NULL);
INSERT INTO "verses" VALUES(1939465,2258,0,1,'نهیبِ حادثه بنیادِ ما ز جا بِبَرَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939466,2257,9,0,'حافظ! اَر جان طَلَبَد غَمزهٔ مَستانهٔ یار','حافظا.. اگر چشم شوخ یار از تو جانت را خواست، تردید مکن و خانه دل را از هرچه غیر اوست پاک کن و بگذار تا ببرد.',NULL);
INSERT INTO "verses" VALUES(1939467,2257,9,1,'خانه از غیر بِپَرداز و بِهِل تا بِبَرَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939468,2257,8,0,'راهِ عشق اَر چه کمینگاهِ کَمانداران اَست','راه و جاده عشق اگر‌چه پر‌خطر و پر از کمان‌دار است؛ ‌(شجاع باش و برو) زیرا هر کسی که با دانایی این راه را بپیماید بر دشمنان پیروز خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1939469,2257,8,1,'هر که دانسته رَوَد صَرفه زِ اعدا بِبَرَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939470,2257,7,0,'جامِ میناییِ مِی، سَدِ رَهِ تَنگ‌دِلی‌ست','جام مینایی و زلال‌ می، از دلتنگی و انده جلوگیری می‌کند آن‌را یک لحظه از دست فرو مگذار وگر نه سیل غم تو را با خود می‌برد',NULL);
INSERT INTO "verses" VALUES(1939471,2257,7,1,'مَنِه از دَست که سیلِ غَمَت از جا بِبَرَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939472,2257,6,1,'سامری کیست که دَست از یَدِ بیضا بِبَرَد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939473,2259,4,0,'گر از سلطان طمع کردم، خطا بود','اگر از سلطان‌، امید و طمع در دل داشتم، امیدی خطا و بی‌جا بود و اگر از دلبر‌، چشم مهر و وفا داشتم ستم و جفا دیدم',NULL);
INSERT INTO "verses" VALUES(1939474,2259,4,1,'ور از دلبر وفا جُستَم، جفا کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939475,2259,5,0,'خوشش باد آن نسیمِ صبحگاهی','نسیم صبح‌گاهی شاد بادا زیراکه فقط او بود که درد شب‌نشینان و بیداران‌ِ دردمند را دوا و درمان کرد.',NULL);
INSERT INTO "verses" VALUES(1939476,2259,5,1,'که دردِ شب نشینان را دوا کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939477,2261,2,0,'خوشا نماز و نیازِ کسی که از سرِ درد','هوش مصنوعی: کسی که از روی درد و رنج به درگاه خداوند نماز می‌گذارد و با اشک‌ها و احساسات عمیقش، خود را پاک می‌کند، حتماً در جایگاه والایی قرار دارد.',NULL);
INSERT INTO "verses" VALUES(1939478,2261,2,1,'به آبِ دیده و خونِ جگر طهارت کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939479,2261,1,0,'همین که ساغرِ زَرّینِ خور، نهان گردید','هوش مصنوعی: به محض آنکه جام زرقون خورشید غروب کرد، هلال عید با دقت به دور آن جام اشاره کرد.',NULL);
INSERT INTO "verses" VALUES(1939480,2261,1,1,'هِلال عید به دورِ قدح اشارت کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939481,2261,0,0,'به آبِ روشنِ می، عارفی طهارت کرد','هوش مصنوعی: در صبح زود، عارفی با آب زلال می، خود را پاکیزه کرد و به میخانه رفت تا آنجا را زیارت کند.',NULL);
INSERT INTO "verses" VALUES(1939482,2261,0,1,'عَلَی الصَّباح، که میخانه را زیارت کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939483,2260,7,0,'حدیثِ عشق ز حافظ شنو نه از واعظ','اگر داستان عشق را می‌خواهی بشنوی آن‌را از حافظ بشنو نه از واعظ و شیخ، اگر چه کلام و زبان پر هیاهو و پر فنی دارد.',NULL);
INSERT INTO "verses" VALUES(1939484,2260,7,1,'اگر چه صنعتِ بسیار در عبارت کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939485,2260,6,0,'به رویِ یار نظر کن ز دیده مِنّت دار','به روی یار نگاه کن و از دیده و روی یار ممنون و سپاسگزار باش که آدم پخته و کاردیده‌، از روی بینش و بصیرت نگاه می‌کند.',NULL);
INSERT INTO "verses" VALUES(1939486,2260,6,1,'که کاردیده، نظر از سرِ بِصارت کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939487,2260,5,0,'فغان که نرگس جَمّاشِ شیخِ شهر امروز','فریاد از دست چشمان فضول شیخ و زاهد شهر که امروز با دیده مذمت و حقارت به دُردکشان و می‌گساران نگاه‌کرد.',NULL);
INSERT INTO "verses" VALUES(1939488,2260,5,1,'نظر به دُردکشان از سرِ حقارت کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939489,2260,4,0,'نماز در خَمِ آن ابروانِ محرابی','کسی می‌تواند در خم و طاق محراب آن ابروان کمانی نماز کند که با خون جگر طهارت کرد.',NULL);
INSERT INTO "verses" VALUES(1939490,2260,4,1,'کسی کُنَد که به خونِ جگر طهارت کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939491,2261,3,1,'به خونِ دخترِ رَز، خرقه را قِصارت کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939492,2260,3,0,'بهایِ بادهٔ چون لعل چیست؟ جوهرِ عقل','بهای باده ناب و لعل‌گون را چطور و با چه باید پرداخت؟ با جوهر عقل. کسی که این معامله را انجام داد‌، سود بُرد.',NULL);
INSERT INTO "verses" VALUES(1939493,2260,2,0,'مُقامِ اصلیِ ما گوشهٔ خرابات است','جای و جایگاه اصلی و سزاوار ما گوشه میکده و خرابات است خدا خیرش دهاد کسی را که این بنا و عمارت را ساخت. (کرد‌‌: ساخت)',NULL);
INSERT INTO "verses" VALUES(1939494,2260,2,1,'خداش خیر دهاد آن که این عمارت کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939495,2260,1,0,'ثوابِ روزه و حجِّ قبول آن کس بُرد','ثواب روزه و حج را کسی می‌برد که خاک میکده عشق را زیارت می‌کند. (میکده در شعر حافظ، محل دوری از خودپرستی و رها شدن از خود و دوری از ریا است.)',NULL);
INSERT INTO "verses" VALUES(1939496,2260,1,1,'که خاکِ میکدهٔ عشق را زیارت کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939497,2260,0,0,'بیا که تُرکِ فلک خوانِ روزه غارت کرد','هشیار باش که روز جشن است و دست تقدیر‌، خوان و سفره روزه را برچید و هلال روز عید به‌ زبان حال‌، قدح باده را به تو نشان می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1939498,2260,0,1,'هلالِ عید به دورِ قدح اشارت کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939499,2259,9,0,'وفا از خواجگانِ شهر با من','در میان بزرگان شهر‌، کسی که با من مهر و وفا ورزید خواجه ابوالوفا، صاحب کمال و دولت بود.',NULL);
INSERT INTO "verses" VALUES(1939500,2259,9,1,'کمالِ دولت و دین بوالوفا کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939501,2259,8,0,'بشارت بَر به کویِ می فروشان','به کوی می‌فروشان مژده ببر که حافظ از زهد ریایی و دروغین توبه کرد و پشیمان شد.',NULL);
INSERT INTO "verses" VALUES(1939502,2259,8,1,'که حافظ توبه از زهدِ ریا کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939503,2259,7,0,'به هر سو بلبلِ عاشق در افغان','و بلبل عاشق در هر سوی گلشن‌، فغان برآورد که در این‌میان باد صبا تنها کسی بود که اهل نعمت بود. (تنعم‌: در لغت یعنی در ناز و آسایش زیستن)',NULL);
INSERT INTO "verses" VALUES(1939504,2259,7,1,'تَنَعُّم از میان، بادِ صبا کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939505,2259,6,0,'نقابِ گل کَشید و زلفِ سُنبل','(نسیم صبح‌گاهی بود که) که نقاب از روی زیبای گل و زلف ناز سنبل کنار زد و بندهای جامه غنچه را گشود.',NULL);
INSERT INTO "verses" VALUES(1939506,2259,6,1,'گره بندِ قبای غنچه وا کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939507,2260,3,1,'بیا که سود کسی بُرد، کاین تجارت کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939508,2290,2,0,'غمناک نباید بود از طعنِ حسود ای دل','هوش مصنوعی: دل عزیز، نباید از بدگویی‌های حسودان ناراحت شوی، زیرا ممکن است که در این کار خیری برای تو نهفته باشد که خود را نبیند.',NULL);
INSERT INTO "verses" VALUES(1939509,2265,8,0,'من چه گویم؟ که تو را نازکیِ طبعِ لطیف','هوش مصنوعی: من چه بگویم؟ که لطافت و ظرافت روح تو به حدی است که حتی نمی‌توان با صدای آرام دعا کرد.',NULL);
INSERT INTO "verses" VALUES(1939510,2265,9,0,'بجز ابرویِ تو محرابِ دل حافظ نیست','هوش مصنوعی: غیر از ابرو و زیبایی تو، هیچ چیز دیگری در دل حافظ ارزش عبادت ندارد. در مذهب ما، بندگی و پرستش کسی غیر از تو امکان‌پذیر نیست.',NULL);
INSERT INTO "verses" VALUES(1939511,2272,4,0,'گفتم این جامِ جهان‌بین به تو کِی داد حکیم؟','هوش مصنوعی: گفتم این پیمانه‌ای که به تو بینش درباره جهان می‌دهد، چه زمانی از حکیم به تو داده شده است؟ او پاسخ داد: آن زمانی که این آسمان آبی رنگ را می‌ساخت.',NULL);
INSERT INTO "verses" VALUES(1939512,2272,1,1,'طلب از گمشدگانِ لبِ دریا می‌کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939513,2272,2,1,'کاو به تأییدِ نظر حلّ‌ِ معمّا می‌کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939514,2272,3,0,'دیدمش خُرَّم و خندان قدحِ باده به دست','هوش مصنوعی: او را دیدم که خوشحال و خندان بود و جام می را در دست داشت. در آینه، انواع جلوه‌ها و زیبایی‌ها را می‌نگریست.',NULL);
INSERT INTO "verses" VALUES(1939515,2272,3,1,'واندر آن آینه صد گونه تماشا می‌کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939516,2272,0,0,'سال‌ها دل طلبِ جامِ جم از ما می‌کرد','هوش مصنوعی: سال‌ها دل به دنبال جام جمشید بود و در عوض، آنچه را که خود داشت از دیگران خواسته و از آن‌ها انتظار داشت.',NULL);
INSERT INTO "verses" VALUES(1939517,2272,2,0,'مشکلِ خویش بَرِ پیرِ مُغان بُردم دوش','هوش مصنوعی: دیشب مسئله و مشکل خود را به جوانمردی از اهل عرفان که پیر مغان نامیده می‌شود، بردم. او با نگاه عمیق و بصیرتی که داشت، به من کمک کرد تا راز و معمای من را حل کند.',NULL);
INSERT INTO "verses" VALUES(1939518,2272,0,1,'وآنچه خود داشت ز بیگانه تمنّا می‌کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939519,2272,1,0,'گوهری کز صدفِ کون و مکان بیرون است','آن گوهر ارزشمندی (علم و معرفت حقّانی) که در زمان و مکان یا همان عالم خاکی نبود، آن را از سرگشتگانِ همین عالم دنیا می‌خواست و می‌جویید',NULL);
INSERT INTO "verses" VALUES(1939520,2271,5,0,'حافظ افتادگی از دست مده زان که حسود','هوش مصنوعی: افتادگی خود را از دست نده، چون حسودان در دل خود بر سر کسانی که متکبر هستند، حسادت می‌ورزند و نسبت به مال، مقام و حتی باورهایشان بدخواهی می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1939521,2271,5,1,'عِرض و مال و دل و دین در سرِ مغروری کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939522,2271,4,0,'غنچهٔ گُلبُنِ وصلم ز نسیمش بِشِکُفت','هوش مصنوعی: غنچهٔ گل سرخی که از نسیم به شوق آمده، با صدای خوش و دلنواز مرغی که در حال شادی و سرور است، شکوفا شد.',NULL);
INSERT INTO "verses" VALUES(1939523,2271,4,1,'مرغ خوشخوان طرب از برگِ گلِ سوری کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939524,2271,3,0,'نه به هفت آب، که رنگش به صد آتش نرود','هوش مصنوعی: آنچه که در دل تجربه و حقیقت نهفته است، نمی‌تواند با هیچ آب و آتشی تغییر یابد؛ زیرا آنچه با درک عمیق و روحانی همراه است، چیزی نیست که به سادگی از بین برود.',NULL);
INSERT INTO "verses" VALUES(1939525,2271,3,1,'آن چه با خرقهٔ زاهد، مِی انگوری کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939526,2271,2,0,'مژدگانی بده ای دل که دگر مطربِ عشق','هوش مصنوعی: به خودت بشارت بده، ای دل، زیرا که دیگر بار مطرب عشق نغمه‌ای شاداب سر داده و راهی برای درمان مستی ما فراهم کرده است.',NULL);
INSERT INTO "verses" VALUES(1939527,2271,2,1,'راهِ مستانه زد و چارهٔ مخموری کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939528,2271,1,0,'آمد از پرده به مجلس عَرَقَش پاک کنید','هوش مصنوعی: از پرده بیرون آمده و به مجلس آمده است، عرق او را پاک کنید تا حریفان نگویند که چرا از جمع دوری کرده است.',NULL);
INSERT INTO "verses" VALUES(1939529,2271,1,1,'تا نگویند حریفان که چرا دوری کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939530,2271,0,0,'دوستان دخترِ رَز توبه ز مستوری کرد','هوش مصنوعی: دوستان دختر راز را فاش کردند و او به سمت محتسب رفت و دستوری را اجرا کرد.',NULL);
INSERT INTO "verses" VALUES(1939531,2271,0,1,'شد سویِ محتسب و کار به دستوری کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939532,2270,6,0,'فکرِ عشق آتشِ غم در دلِ حافظ زد و سوخت','رویای عاشقی در دل حافظ غم را بمانند آتش شعله‌ور کرد و باعث از بین رفتن او گردید. حالا بیایید ببینیم عاشقش با او چه کرده است.',NULL);
INSERT INTO "verses" VALUES(1939533,2270,6,1,'یارِ دیرینه ببینید که با یار چه کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939534,2270,5,0,'آن که پُرنقش زد این دایرهٔ مینایی','کسی نمیداند خداوندی که این جهان را بنا کرده‌است چه اسرار و رموزی در آن قرار داده و کسی به اسرار عالم غیب آگاه نیست',NULL);
INSERT INTO "verses" VALUES(1939535,2270,5,1,'کس ندانست که در گردشِ پرگار چه کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939536,2270,4,0,'ساقیا جامِ مِی‌ام دِه که نگارندهٔ غیب','ای ساقی، لیوان شرابم را به من بده؛ زیرا معلوم نیست که خداوند دانا بر عالم غیب چه تدبیر کرده و من از اسرار جهان آگاه نیستم',NULL);
INSERT INTO "verses" VALUES(1939537,2270,4,1,'نیست معلوم که در پردهٔ اسرار چه کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939538,2270,3,0,'برقی از منزلِ لیلی بدرخشید سحر','در صبحگاهان نوری از خانه لیلی درخشید و افسوس که چه بلایی بر سر دل مجروح مجنون آورد.',NULL);
INSERT INTO "verses" VALUES(1939539,2270,3,1,'وَه که با خرمنِ مجنونِ دل‌افگار چه کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939540,2272,4,1,'گفت آن روز که این گنبدِ مینا می‌کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939541,2272,5,0,'بی‌دلی در همه‌احوال خدا با او بود','وارسته‌ای که در هر شرایطی خدا با او بود، چون نمی‌توانست او را ببیند فکر می‌کرد خدا از او جداست و به دنبال او می‌گشت. (خدارا می‌کرد یعنی سوگند به خدا؛ خدا را به کمک طلبیدن)',NULL);
INSERT INTO "verses" VALUES(1939542,2272,5,1,'او نمی‌دیدش و از دور خدارا می‌کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939543,2272,6,0,'این‌همه شعبدهٔ خویش که می‌کرد اینجا','هوش مصنوعی: این همه ترفند و حیله‌ای که سامری در مقابل عصا و معجزه‌ی موسی به کار می‌بست، در اینجا دیده می‌شود.',NULL);
INSERT INTO "verses" VALUES(1939544,2274,0,1,'که بود ساقی و این باده از کجا آورد',NULL,NULL);
INSERT INTO "verses" VALUES(1939545,2273,10,0,'گر این نصیحتِ شاهانه بشنوی حافظ','اگر نصیحت پادشاه را بپذیری، حافظ، می‌توانی به مسیر حقیقت راه یابی.',NULL);
INSERT INTO "verses" VALUES(1939546,2273,10,1,'به شاهراهِ حقیقت گذر توانی کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939547,2273,9,0,'دلا ز نورِ هدایت گر آگهی یابی','ای دل، اگر نور هدایت در تو روشن شود همچون شمع که با خنده برای روشنایی بخشیدن می‌سوزد تو هم میتوانی سر در راه روشنی و حقیقت ببازی',NULL);
INSERT INTO "verses" VALUES(1939548,2273,9,1,'چو شمع، خنده‌زنان تَرکِ سر توانی کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939549,2273,8,0,'ولی تو تا لبِ معشوق و جامِ مِی خواهی','تا زمانی که به عشق و خوشی‌های زندگی فکر می‌کنی، نباید انتظار داشته باشی که بتوانی کار دیگری انجام دهی.',NULL);
INSERT INTO "verses" VALUES(1939550,2273,8,1,'طمع مدار که کارِ دگر توانی کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939551,2273,7,0,'بیا که چارهٔ ذوقِ حضور و نظم امور','برای داشتن شوق زندگی و نظم بخشیدن به امور ، باید از افراد فرهیخته و اهل نظر کسب فیض کنی',NULL);
INSERT INTO "verses" VALUES(1939552,2273,7,1,'به فیض‌بخشیِ اهلِ نظر توانی کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939553,2273,6,0,'جمالِ یار ندارد نقاب و پرده ولی','زیبایی محبوب هیچ پوشش و پرده‌ای ندارد، بلکه باید به صبور باشی تا آن زیبایی ها خود را به تو نشان بدهند',NULL);
INSERT INTO "verses" VALUES(1939554,2273,6,1,'غبارِ رَه بِنِشان تا نظر توانی کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939555,2273,5,0,'تو کز سرایِ طبیعت نمی‌روی بیرون','تو که هنوز مشغول غرایز و امیال طبیعی و مادی هستی، چگونه می‌توانی به راه معنوی و واقعیت‌های عمیق‌تر دسترسی پیدا کنی؟',NULL);
INSERT INTO "verses" VALUES(1939556,2273,5,1,'کجا به کویِ طریقت گذر توانی کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939557,2273,4,0,'به عزمِ مرحلهٔ عشق پیش نِه قدمی','با اراده‌ی رسیدن به مرحله‌ی عشق، قدمی بردار که اگر بتوانی، در این سفر به سودهای بزرگی دست یابی.',NULL);
INSERT INTO "verses" VALUES(1939558,2270,2,0,'اشکِ من رنگِ شفق یافت ز بی‌مِهری یار','اشک‌های من همانند لحظه غروب از خون سرخ شده‌اند به خاطر بی‌محبتی و سردی معشوق. ببین چگونه سرنوشت بی‌رحم عمل کرده است.',NULL);
INSERT INTO "verses" VALUES(1939559,2273,4,1,'که سودها کنی ار این سفر توانی کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939560,2273,3,0,'گدایی درِ میخانه طُرفه اِکسیریست','خدمت به میخانه مثل کیمیاست ، زیرا اگر این عمل را انجام دهی، می‌توانی خاک را به طلا تبدیل کنی.',NULL);
INSERT INTO "verses" VALUES(1939561,2273,2,0,'گُلِ مرادِ تو آنگه نقاب بُگْشاید','مراد و مقصود تو زمانی خود را آشکار میکند و زیبایی‌اش را نشان می‌دهد که تو بتوانی همچون نسیم صبحگاه، به او خدمت کنی و او را نوازش کنی.',NULL);
INSERT INTO "verses" VALUES(1939562,2273,2,1,'که خدمتش چو نسیمِ سحر توانی کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939563,2273,1,0,'مباش بی می و مُطرب که زیرِ طاقِ سپهر','در این دنیا هرگز بدون شادی و طرب زندگی نکن. زیرا تنها با شادی و طرب میتوانی بر غم ها فائق شوی',NULL);
INSERT INTO "verses" VALUES(1939564,2273,1,1,'بدین ترانه غم از دل به در توانی کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939565,2273,0,0,'به سِرِّ جامِ جم آنگه نظر توانی کرد','برای پی بردن به راز های هستی می‌بایست خاک پای سالکان حقیقت و محافل حقیقت طلبی(میخانه) باشی',NULL);
INSERT INTO "verses" VALUES(1939566,2273,0,1,'که خاکِ میکده کُحلِ بَصَر توانی کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939567,2272,7,1,'جُرمش این بود که اسرار هویدا می‌کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939568,2272,8,1,'دیگران هم بکنند آن‌چه مسیحا می‌کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939569,2272,9,0,'گفتمش سلسلهٔ زلفِ بُتان از پیِ چیست؟','هوش مصنوعی: به او گفتم که علت زلف‌های پیچیده‌ی معشوقان چیست، او پاسخ داد که حافظ دل شیدا گله‌ای دارد.',NULL);
INSERT INTO "verses" VALUES(1939570,2272,9,1,'گفت حافظ گله‌ای از دلِ شیدا می‌کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939571,2272,6,1,'سامری پیشِ عصا و یدِ بیضا می‌کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939572,2272,8,0,'فیضِ روحُ‌القُدُس ار باز مدد فرماید','هوش مصنوعی: اگر روح‌القدس دوباره کمک کند، دیگران نیز می‌توانند کارهایی را انجام دهند که عیسی (مسیحا) انجام می‌داد.',NULL);
INSERT INTO "verses" VALUES(1939573,2272,7,0,'گفت آن یار کز او گشت سرِ دار بلند','آن بزرگ (پیر مغان) گفت آن کسی که (منصور حلاج) که به واسطه بر دار شدنش ، دار به بزرگی رسید. جرمش این بود که وقتی اسرار الهی را دریافت میکرد و به شهود می رسید آنها را برای دیگران هم بیان میکرد.',NULL);
INSERT INTO "verses" VALUES(1939574,2273,3,1,'گر این عمل بِکُنی، خاکْ زر توانی کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939575,2265,8,1,'تا به حَدّیست که آهسته دعا نتوان کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939576,2270,2,1,'طالعِ بی‌شفقت بین که در این کار چه کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939577,2270,1,0,'آه از آن نرگسِ جادو که چه بازی انگیخت','آه که چشم زیبا و سحر آمیز او چگونه من را به بازی گرفت ، آه از آن دلبر که با حالت مست ما مردم هشیار را به بازی گرفت',NULL);
INSERT INTO "verses" VALUES(1939578,2267,5,0,'شاید ار پیکِ صبا، از تو بیاموزد کار','هوش مصنوعی: شاید اگر نسیم صبح به تو نزدیک شود، کارهای تو را یاد بگیرد. زیرا هیچ چیز نمی‌تواند به اندازه‌ی این حرکت تند و چابک باد، سریع و پرانرژی باشد.',NULL);
INSERT INTO "verses" VALUES(1939579,2267,5,1,'زآن که چالاک‌تر از این حرکت، باد نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939580,2267,4,0,'سایه تا بازگرفتی ز چمن مرغِ سحر','هوش مصنوعی: سایه را تا زمانی که از چمن برداشت کردی، پرنده سحر نتوانست برای لانه‌اش در شاخۀ شمشاد جا بگیرد.',NULL);
INSERT INTO "verses" VALUES(1939581,2267,4,1,'آشیان در شِکَنِ طُرِّهٔ شمشاد نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939582,2267,3,0,'دل به امّیدِ صدایی که مگر در تو رسد','هوش مصنوعی: دل به امید شنیدن صدایی از تو، برای اینکه شاید صدای ناله‌ها به تو برسد، در این کوه ناله کرد، همان‌طور که فرهاد ناله نکرد.',NULL);
INSERT INTO "verses" VALUES(1939583,2267,3,1,'ناله‌ها کرد در این کوه که فرهاد نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939584,2267,2,0,'کاغذین جامه به خونآب بشویم که فلک','می‌خواهم لباس کاغذی و نازک خود را با خون دیده بشویم و آنقدر گریه کنم تا رنگ خون شود، زیرا چرخ و زمان (فلک) مرا به سمت علم داد هدایت نکرد. (علم داد علمی در نقطه ای از شهر بود که مظلومان و دادخواهان جهت دادخواهی با لباس کاغذی کنار علم ایستاده و شکایت خود را با نوشتن روی جامه کاغذی بیان می کردند)',NULL);
INSERT INTO "verses" VALUES(1939585,2267,2,1,'رهنمونیم به پایِ عَلَمِ داد نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939586,2267,1,0,'آن جوان‌بخت که می‌زد رقمِ خیر و قبول','در اینجا "خیر: به معنی "نه" میباشد،در زمان قدیم لیستی از بندگان را جهت آزاد کردن به شاه میدادند و شاه در جلوی هر یک با نوشتن خیر و قبول آزادی بنده را رد و یا قبول میکرد. معنی شعر: آن جوان بخت که قدرت رد و یا قبول آزاد کردن بندگان را داشت، نمیدانم چرا این بنده پیر را آزاد نکرد',NULL);
INSERT INTO "verses" VALUES(1939587,2267,1,1,'بندهٔ پیر ندانم ز چه آزاد نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939588,2267,0,0,'یاد باد آن که ز ما وقتِ سفر یاد نکرد','هوش مصنوعی: به یاد بیاور آن کسی را که هنگام رفتن، ما را فراموش کرد و با خداحافظی، دل غمگین ما را شاد نکرد.',NULL);
INSERT INTO "verses" VALUES(1939589,2267,0,1,'به وداعی دلِ غم‌دیدهٔ ما شاد نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939590,2266,7,0,'عدو با جانِ حافظ آن نکردی','هوش مصنوعی: دشمن با جان حافظ چنین عملی نکرد که تیر چشمان آن معشوق کم‌حرفی کرد.',NULL);
INSERT INTO "verses" VALUES(1939591,2266,7,1,'که تیرِ چشمِ آن ابروکمان کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939592,2266,6,0,'میان مهربانان کی توان گفت؟','هوش مصنوعی: در جمع افراد مهربان، چه کسی می‌تواند بگوید که دوست ما چگونه سخن گفته و چه کارهایی انجام داده است؟',NULL);
INSERT INTO "verses" VALUES(1939593,2266,6,1,'که یارِ ما چُنین گفت و چُنان کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939594,2266,5,0,'صبا گر چاره داری وقت وقت است','هوش مصنوعی: ای باد صبا، اگر راه حلی داری، وقت آن است که اشتیاق و درد من به جانم رسیده است.',NULL);
INSERT INTO "verses" VALUES(1939595,2266,5,1,'که دردِ اشتیاقم قصدِ جان کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939596,2266,4,0,'بدانسان سوخت چون شمعم که بر من','هوش مصنوعی: من مانند شمعی می‌سوزم، در حالی که بر من شرابی ریخته شده و موسیقی غمگینی نواخته می‌شود.',NULL);
INSERT INTO "verses" VALUES(1939597,2266,4,1,'صُراحی گریه و بَربَط فغان کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939598,2266,3,0,'که را گویم که با این دردِ جان‌سوز','هوش مصنوعی: به چه کسی بگویم که این درد عمیق و سوزناک را تجربه می‌کنم؟ پزشک قصد دارد جانم را بگیرد.',NULL);
INSERT INTO "verses" VALUES(1939599,2266,3,1,'طبیبم قصدِ جانِ ناتوان کرد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939600,2266,2,0,'چرا چون لاله خونین دل نباشم؟','هوش مصنوعی: چرا باید مانند لاله‌ای با دل شکسته نباشم؟ وقتی که نرگس زیبایش سرش را به خاطر ما بالا کرده است.',NULL);
INSERT INTO "verses" VALUES(1939601,2266,2,1,'که با ما نرگسِ او سر گران کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939602,2266,1,0,'شب تنهاییَم در قصدِ جان بود','هوش مصنوعی: در شب تنهایی‌ام، در حالی که قصد داشتم جان خود را از دست بدهم، یاد او به من آرامش و احترام بی‌پایانی بخشید.',NULL);
INSERT INTO "verses" VALUES(1939603,2266,1,1,'خیالش لطف‌هایِ بی‌کران کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939604,2266,0,0,'دل از من بُرد و روی از من نهان کرد','هوش مصنوعی: دل مرا تارت کرده و رویش را از من پنهان کرده است. خدایا، با که می‌توان این بازی را تحمل کرد؟',NULL);
INSERT INTO "verses" VALUES(1939605,2266,0,1,'خدا را با که این بازی توان کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939606,2265,9,1,'طاعتِ غیر تو در مذهبِ ما نتوان کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939607,2267,6,0,'کِلْکِ مَشّاطِهٔ صُنعَش نَکِشد نقشِ مراد','هوش مصنوعی: هر کسی که به زیبایی‌های خداوند اعتراف نکند، نمی‌تواند به خواسته‌هایش دست پیدا کند. این نکته را یادآوری می‌کند که هنر و زیبایی‌های طبیعی نیاز به شناخت و تقدیر دارند تا نتیجه مطلوب به دست آید.',NULL);
INSERT INTO "verses" VALUES(1939608,2267,6,1,'هر که اقرار بدین حُسنِ خداداد نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939609,2267,7,0,'مطربا! پرده بگردان و بزن راهِ عراق','هوش مصنوعی: ای هنرمند، بزن موسیقی و پرده را تغییر بده و به سمت عراق برو. زیرا آن کسی که دوستش داشتم، از این راه عبور کرد و به یاد ما نیفتاد.',NULL);
INSERT INTO "verses" VALUES(1939610,2267,7,1,'که بدین راه بشد یار و ز ما یاد نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939611,2270,0,0,'دیدی ای دل که غمِ عشق دگربار چه کرد؟','ای دل! دیدی که غم عشق دوباره چه بر سرم آورد؟ دیدی دلبر چگونه شد و با من یار وفادارش چکار کرد؟',NULL);
INSERT INTO "verses" VALUES(1939612,2270,0,1,'چون بشد دلبر و با یارِ وفادار چه کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939613,2269,5,0,'من ایستاده تا کُنَمَش جان فدا چو شمع','هوش مصنوعی: من در انتظار ایستاده‌ام تا جانم را فدای او کنم، اما او همچون شمعی است که خود را فدای ما نمی‌کند، مانند نسیم صبح که به آرامی عبور می‌کند.',NULL);
INSERT INTO "verses" VALUES(1939614,2269,5,1,'او خود گذر به ما چو نسیمِ سحر نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939615,2269,4,0,'هر کس که دید رویِ تو بوسید چشمِ من','هوش مصنوعی: هر کسی که روی تو را ببیند، چشمان من را می‌بوسد؛ ولی چشمان من که بی‌نظر است، کاری نکرد که با تو کرده است.',NULL);
INSERT INTO "verses" VALUES(1939616,2269,4,1,'کاری که کرد دیدهٔ من، بی‌نظر نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939617,2269,3,0,'شوخی مکن که مرغِ دلِ بی‌قرارِ من','هوش مصنوعی: ملاحظه نکن که با من شوخی می‌کنی، زیرا دل بی‌قرار من همیشه در فکرِ عشق و دلبستگی است و نمی‌تواند از آن دور شود.',NULL);
INSERT INTO "verses" VALUES(1939618,2269,3,1,'سودایِ دامِ عاشقی از سر به درنکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939619,2269,2,0,'گفتم مگر به گریه دلش مهربان کنم','هوش مصنوعی: گفتم شاید با اشک‌های من بتوانم دل او را مهربان کنم، اما چون دلش به مانند سنگ سخت بود، تأثیری نداشت.',NULL);
INSERT INTO "verses" VALUES(1939620,2269,2,1,'چون سخت بود در دلِ سنگش اثر نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939621,2269,1,0,'یا بختِ من طریقِ مروت فروگذاشت','هوش مصنوعی: یا بخت من به من کمک نکرد و راه درست را نشان نداد، یا او هم به مسیر درست نرفت و از آن عبور نکرد.',NULL);
INSERT INTO "verses" VALUES(1939622,2269,1,1,'یا او به شاهراهِ طریقت گذر نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939623,2269,0,0,'دلبر بِرَفت و دلشدگان را خبر نکرد','هوش مصنوعی: محبوب از پیش رفت و اهل دل را آگاه نکرد، یاد رفیق شهر و همراه سفر را نیز فراموش کرد.',NULL);
INSERT INTO "verses" VALUES(1939624,2269,0,1,'یادِ حریفِ شهر و رفیقِ سفر نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939625,2270,1,1,'آه از آن مست که با مردمِ هشیار چه کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939626,2268,6,0,'کِلکِ زبان‌بریدهٔ حافظ در انجمن','هوش مصنوعی: حافظ در جمع دیگران هیچ‌گاه راز تو را فاش نکرد و فقط وقتی به دردسر افتاد، زبانش به اعتراف باز شد.',NULL);
INSERT INTO "verses" VALUES(1939627,2268,5,0,'جانا کدام سنگدلِ بی‌کفایت است','هوش مصنوعی: عزیزم، چه کسی می‌تواند سنگدل و ناکارآمد باشد که در برابر درد و آسیب تو جانش را دفاع نکند؟',NULL);
INSERT INTO "verses" VALUES(1939628,2268,5,1,'کاو پیشِ زخمِ تیغِ تو جان را سپر نکرد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939629,2268,4,0,'می‌خواستم که میرَمَش اندر قدم چو شمع','هوش مصنوعی: خواستم مانند شمعی باشم که در کنار او می‌افتم، اما او مثل نسیمی در صبح زود از کنار ما گذشت و ما را نادیده گرفت.',NULL);
INSERT INTO "verses" VALUES(1939630,2268,4,1,'او خود گذر به ما چو نسیمِ سحر نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939631,2268,3,0,'ماهی و مرغْ دوش ز افغانِ من نَخُفت','هوش مصنوعی: ماهی و پرنده شب گذشته از صدای ناله من بیدار نشدند و آن دلبر بازیگوش هنوز از خواب بیدار نشده است.',NULL);
INSERT INTO "verses" VALUES(1939632,2268,3,1,'وان شوخْ‌دیده بین که سر از خواب برنکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939633,2268,2,0,'یا رب تو آن جوانِ دلاور نگاه‌دار','هوش مصنوعی: خدایار، تو آن جوان شجاع را حفظ کن که از تیرهای حسرت و ناامیدی افرادی که کناره‌نشینند، نمی‌ترسد و به مبارزه ادامه می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1939634,2268,2,1,'کز تیرِ آهِ گوشه‌نشینان حذر نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939635,2268,1,0,'سیلِ سرشک ما ز دلش کین به در نَبُرد','هوش مصنوعی: اشک‌های ما مانند سیل از دل به راه افتاده، اما این کینه و درد را از دل برنمی‌دارد. حتی قطرهٔ باران هم بر سنگ‌های سخت تأثیری نمی‌گذارد.',NULL);
INSERT INTO "verses" VALUES(1939636,2268,1,1,'در سنگِ خاره قطرهٔ باران اثر نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939637,2268,0,0,'رو بر رَهَش نهادم و بر من گذر نکرد','هوش مصنوعی: من در راه او قرار گرفتم و او هیچ توجهی به من نکرد. با اینکه امید به لطف و نگاهش داشتم، هیچ نگاهی از او دریافت نکردم.',NULL);
INSERT INTO "verses" VALUES(1939638,2268,0,1,'صد لطف چشم داشتم و یک نظر نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939639,2267,8,0,'غزلیاتِ عراقی‌ست سرودِ حافظ','هوش مصنوعی: این متن به نظر می‌آید به توصیف شعرهای حافظ می‌پردازد، که با احساسات عمیق و دلسوزی همراه است. در اینجا شاعر به تأثیر کلمات و مرثیه‌های عاشقانه اشاره می‌کند و از این می‌گوید که حافظ درباره‌ی غم و اندوه عشق سخن گفته است، بدون آنکه خود را برانگیخته یا فریاد زده باشد. این بیان نشان از عمق احساسات و قدرت بیان حافظ در شعرهایش دارد.',NULL);
INSERT INTO "verses" VALUES(1939640,2267,8,1,'که شنید این رهِ دل‌سوز که فریاد نکرد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939641,2268,6,1,'با کس نگفت رازِ تو تا تَرکِ سر نکرد',NULL,NULL);
INSERT INTO "verses" VALUES(1939642,2322,5,1,'کِه دَر آن آیِنِه، صاحِب‌نَظَران، حِیْران‌اَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939643,2290,2,1,'شاید که چو وابینی خیرِ تو در این باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939644,2290,3,0,'هر کو نَکُنَد فهمی زین کِلکِ خیال‌انگیز','از نظر شاعر، مهمترین عامل زندگی، شانس، تقدیر و سرنوشت است که از پیش نوشته شده و این اصل چنان مسلم است که اگر کسی آن درک نکرده باشد، هیچ چیز از دنیا نفهمیده و زندگی اش پوچ و بی ثمر است، حتی اگر خیلی هم ادعا داشته باشد.کلک خیال انگیز: قلم سرنوشت و تقدیر الهی است که چنان نقاشی پیچیده و وهم انگیزی را می نگارد که بعضی را به قضاوت های خیالی و توهمی راجع به دنیا و خدا می کشاند.صورتگر چین: نقاش زبردستنقشش به حرام: یعنی نقاشی بی معنا و مفهوم که جز تلف کردن رنگ و وقت و ... ثمری ندارد.',NULL);
INSERT INTO "verses" VALUES(1939645,2312,0,0,'دوش وقتِ سَحَر، از غُصّه نجاتم دادند','دیشب در هنگام صبحدم از غصه آزادم کردند، و در آن تاریکی شب، آب زندگانی به‌من نوشاندند.',NULL);
INSERT INTO "verses" VALUES(1939646,2312,0,1,'واندر آن ظلمتِ شب، آبِ حیاتم دادند',NULL,NULL);
INSERT INTO "verses" VALUES(1939647,2311,8,0,'حافظ از شوقِ رخِ مِهر‌فروغِ تو بسوخت','هوش مصنوعی: حافظ از عشق و زیبایی تو به شدت دلتنگ و آشفته است. ای کاش لحظه‌ای نگاهی به ناکامی‌ها و غم‌های او بیندازی.',NULL);
INSERT INTO "verses" VALUES(1939648,2311,8,1,'کامگارا نظری کن سویِ ناکامی چند',NULL,NULL);
INSERT INTO "verses" VALUES(1939649,2311,7,0,'پیرِ میخانه چه خوش گفت به دُردی‌کشِ خویش','هوش مصنوعی: پیر مغان به همراهانش گفت که حال دل سوخته‌ات را به کسی که از درد خبر ندارد، نگو.',NULL);
INSERT INTO "verses" VALUES(1939650,2311,7,1,'که مگو حالِ دلِ سوخته با خامی چند',NULL,NULL);
INSERT INTO "verses" VALUES(1939651,2311,6,0,'ای گدایانِ خرابات خدا یارِ شماست','هوش مصنوعی: ای فقرای ویرانه‌ها، خدا از شما حمایت می‌کند. چشم‌تان به نعمت‌های دنیوی نباشد، چرا که چندین نعمت از آن دیگری است.',NULL);
INSERT INTO "verses" VALUES(1939652,2311,6,1,'چشمِ اِنعام مدارید ز اَنعامی چند',NULL,NULL);
INSERT INTO "verses" VALUES(1939653,2311,5,0,'عیبِ مِی جمله چو گفتی، هنرش نیز بگو','هوش مصنوعی: وقتی عیب‌های شراب را گفتی، لطفاً خوبی‌های آن را هم بگو. از این جهت، به خاطر دل‌های نادان، حکمت را نفی نکن.',NULL);
INSERT INTO "verses" VALUES(1939654,2311,5,1,'نفیِ حکمت مکن از بهرِ دلِ عامی چند',NULL,NULL);
INSERT INTO "verses" VALUES(1939655,2311,4,0,'زاهد از کوچهٔ رندان به سلامت بگذر','هوش مصنوعی: زاهد، از کوچه‌ای که مردم آن رند و خوش‌گذران هستند به آرامی عبور کن، تا صحبت‌های بد نامی چند نفر تو را از راه به در نکند.',NULL);
INSERT INTO "verses" VALUES(1939656,2311,4,1,'تا خرابت نکند صحبتِ بدنامی چند',NULL,NULL);
INSERT INTO "verses" VALUES(1939657,2311,3,0,'قندِ آمیخته با گُل نه علاجِ دلِ ماست','هوش مصنوعی: شکر و گل هرگز نمی‌توانند درد دل ما را درمان کنند. بوسه‌های محبت را با چند کلمه تند و ناگواری در هم بیامیز.',NULL);
INSERT INTO "verses" VALUES(1939658,2311,3,1,'بوسه‌ای چند برآمیز به دشنامی چند',NULL,NULL);
INSERT INTO "verses" VALUES(1939659,2311,2,0,'چون مِی از خُم به سبو رفت و گُل افکند نقاب','هوش مصنوعی: وقتی که شراب از خمره به لیوان ریخته شد و گل‌ها زیبایی خود را به نمایش گذاشتند، لحظه‌ی لذت را غنیمت شمار و چند جام نوشیدنی بنوش.',NULL);
INSERT INTO "verses" VALUES(1939660,2311,2,1,'فرصتِ عیش نگه دار و بزن جامی چند',NULL,NULL);
INSERT INTO "verses" VALUES(1939661,2311,1,0,'ما بدان مقصدِ عالی نتوانیم رسید','ما که نمی‌توانیم به آن هدف بلند دست پیدا کنیم، مگر اینکه لطف شما چند گام به جلو (سمت ما) بردارد.',NULL);
INSERT INTO "verses" VALUES(1939662,2311,1,1,'هم مگر پیش نَهَد لطفِ شما گامی چند',NULL,NULL);
INSERT INTO "verses" VALUES(1939663,2311,0,0,'حَسْبِ حالی نَنِوِشتی و شد ایّامی چند','هوش مصنوعی: طبق وضعیت کنونی من، مدتی است که نتوانسته‌ام نامه‌ای برایت بفرستم. حالا که چندین روز از این شرایط گذشته، حسرت می‌زنم که چرا پیامی به تو نداشته‌ام.',NULL);
INSERT INTO "verses" VALUES(1939664,2311,0,1,'مَحرمی کو که فرستم به تو پیغامی چند؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939665,2310,6,0,'بازمَستان دل از آن گیسویِ مُشکین حافظ','هوش مصنوعی: دل دوباره با موهای مشکی زیبای او درگیر شده است، زیرا دیوانگی بهتر است که فرد همچنان در این حالت باقی بماند تا از قید و بند خود رها نشود.',NULL);
INSERT INTO "verses" VALUES(1939666,2310,6,1,'زان که دیوانه همان به که بُوَد اندر بند',NULL,NULL);
INSERT INTO "verses" VALUES(1939667,2310,5,0,'منِ خاکی که از این در نَتَوانَم برخاست','هوش مصنوعی: من که از خاک هستم و نمی‌توانم از این در بلند شوم، چگونه می‌توانم بر لب آن قصر بلند بوسه بزنم؟',NULL);
INSERT INTO "verses" VALUES(1939668,2310,5,1,'از کجا بوسه زنم بر لبِ آن قصرِ بلند؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939669,2310,4,0,'مَکُش آن آهویِ مُشکینِ مرا ای صیّاد','هوش مصنوعی: ای صیاد، آهوی معصوم و زیباي مرا نکش. از آن چشمان سیاه و نافذش شرم کن و او را به دام نینداز.',NULL);
INSERT INTO "verses" VALUES(1939670,2310,4,1,'شرم از آن چشمِ سیه دار و مَبَندَش به کمند',NULL,NULL);
INSERT INTO "verses" VALUES(1939671,2310,3,0,'گفتم اسرارِ غمت هر چه بُوَد گو می‌باش','هوش مصنوعی: به او گفتم هر چه راز و رازهای غم تو هست، به من بگو. اما دیگر طاقت این درد را ندارم. چه کار باید بکنم و تا کی باید این وضعیت را تحمل کنم؟',NULL);
INSERT INTO "verses" VALUES(1939672,2310,3,1,'صبر از این بیش ندارم چه کنم تا کی و چند؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939673,2310,2,0,'هیچ رویی نشود آینهٔ حجلهٔ بخت','هوش مصنوعی: هیچگونه چهره‌ای نمی‌تواند خوشبختی را منعکس کند جز چهره‌ای که در آن زیبایی و جذابیت وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1939674,2312,1,0,'بی‌خود از شَعْشَعِهٔ پرتوِ ذاتم کردند','مرا از نور و پرتو «ذات» مست و بی‌خود کردند، مرا باده‌ای از جام و قدح «تجلّی صفات» دادند.',NULL);
INSERT INTO "verses" VALUES(1939675,2310,2,1,'مگر آن روی که مالَند در آن سُمِّ سمند',NULL,NULL);
INSERT INTO "verses" VALUES(1939676,2312,1,1,'باده از جامِ تَجَلّیِّ صفاتم دادند',NULL,NULL);
INSERT INTO "verses" VALUES(1939677,2312,2,0,'چه مبارک‌سَحَری بود و چه فرخنده‌شبی','چه سحر فرخنده و بی‌نظیری بود، آن «شب قدر» که این مژده و هدیه نو را به‌من دادند.',NULL);
INSERT INTO "verses" VALUES(1939678,2314,2,0,'خوش گِرِفْتَنْد حَریفان، سَرِ زُلْفِ ساقی','هوش مصنوعی: دوستان و رقبای من به زیبایی و دلرباییِ موهای ساقی دل بسته‌اند و اگر زمان به آن‌ها اجازه دهد، ممکن است به توافقی برسند.',NULL);
INSERT INTO "verses" VALUES(1939679,2314,1,0,'مَصْلِحَت‌دیدِ من، آن است که یاران، هَمِه، کار','هوش مصنوعی: به نظرم بهترین کار این است که دوستان همه چیز را کنار بگذارند و از راه دوستی و یاری به هم کمک کنند.',NULL);
INSERT INTO "verses" VALUES(1939680,2314,1,1,'بِگُذارَند و خَمِ طُرِّهٔ یاری گیرَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939681,2314,0,0,'نَقْدها را بُوَد آیا که عَیاری گیرَنْد؟','هوش مصنوعی: آیا ممکن است که منتقدان، به طور جدی و با دقت روی مسائل تمرکز کنند؟ تا این که همه کسانی که در راه باورهای خود هستند، به دنبال هدفی مشخص بروند.',NULL);
INSERT INTO "verses" VALUES(1939682,2314,0,1,'تا همه صومِعِه‌داران، پِیِ کاری گیرَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939697,2312,7,0,'همّتِ حافظ و انفاسِ سحرخیزان بود','از بلند‌نظری و دعای حافظ و عابدان سحرخیز بود که از بند غم ایّام مرا نجات دادند.',NULL);
INSERT INTO "verses" VALUES(1939698,2312,7,1,'که ز بندِ غمِ ایّام نجاتم دادند',NULL,NULL);
INSERT INTO "verses" VALUES(1939699,2312,6,0,'این همه شهد و شِکر کز سخنم می‌ریزد','این همه لطافت و زیبایی که در سخن و شعر من هست؛ اجر و پاداش صبری‌ست که‌ از آن شاخ‌نبات به‌من بخشیدند.',NULL);
INSERT INTO "verses" VALUES(1939700,2312,6,1,'اَجرِ صبری‌ست کز آن شاخِ نباتم دادند',NULL,NULL);
INSERT INTO "verses" VALUES(1939701,2312,5,0,'هاتف آن روز به من مژدهٔ این دولت داد','هاتف و آواز غیب، آن‌روز به من مژده این پیروزی و نیکبختی را داد که در آن جور و سختی‌، به‌من صبر و ثبات داده‌بود.',NULL);
INSERT INTO "verses" VALUES(1939702,2312,5,1,'که بِدان جور و جفا صبر و ثباتم دادند',NULL,NULL);
INSERT INTO "verses" VALUES(1939703,2312,4,0,'من اگر کامروا گشتم و خوش‌دل چه عجب؟','اگر من به‌آرزو رسیدم و شاد گشتم عجب نیست؛ زیرا مستحق و نیازمند بودم و این‌ها را به زکات به‌من دادند.',NULL);
INSERT INTO "verses" VALUES(1939704,2312,4,1,'مستحق بودم و این‌ها به زکاتم دادند',NULL,NULL);
INSERT INTO "verses" VALUES(1939705,2312,3,0,'بعد از این رویِ من و آینهٔ وصفِ جمال','از این پس، رخ من و آینه وصف جمال و زیبایی است؛ زیرا درآنجا خبر از «جلوه ذات» به‌من دادند.',NULL);
INSERT INTO "verses" VALUES(1939706,2312,3,1,'که در آن جا خبر از جلوهٔ ذاتم دادند',NULL,NULL);
INSERT INTO "verses" VALUES(1939707,2312,2,1,'آن شبِ قدر که این تازه‌براتم دادند',NULL,NULL);
INSERT INTO "verses" VALUES(1939708,2310,1,0,'حاجتِ مطرب و مِی نیست تو بُرقَع بِگُشا','هوش مصنوعی: نیازی به آهنگ و شراب نیست، فقط پرده را کنار بزن تا با زیبایی چهره‌ات، دلم را به رقص درآوری مانند آتشی که به شمع می‌زند.',NULL);
INSERT INTO "verses" VALUES(1939709,2310,1,1,'که به رقص آوَرَدَم آتشِ رویت چو سپند',NULL,NULL);
INSERT INTO "verses" VALUES(1939710,2310,0,0,'بعد از این دستِ من و دامنِ آن سروِ بلند','هوش مصنوعی: پس از این، دست من و دامن آن سرو بلند که به ارتفاع چمان از ریشه‌اش جدا کرد.',NULL);
INSERT INTO "verses" VALUES(1939711,2308,0,0,'رسید مژده که ایّامِ غم نخواهد ماند','هوش مصنوعی: خبر خوش این است که روزهای غم و اندوه پایان خواهند یافت، همچنان که این وضعیت نخواهد ماند و تغییر خواهد کرد.',NULL);
INSERT INTO "verses" VALUES(1939712,2307,10,0,'به تماشاگَهِ زلفش دلِ حافظ روزی','دل حافظ روزی رفت که زیبایی زلف معشوق را ببیند و برگردد اما برای همیشه در آنجا گرفتار باقی ماند.',NULL);
INSERT INTO "verses" VALUES(1939713,2307,10,1,'شد که بازآید و جاوید گرفتار بِمانْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939714,2307,9,0,'بر جمالِ تو چنان صورتِ چین حیران شد','صورت چین در برابر جمال و زیبایی تو چنان حیران شد که بر دیوار نقش بست و داستان آن در همه جا پیچید؛ و یا، صورتگر چین که همه را به شگفتی وا می داشت با دیدن چهره ی زیبای تو غرق در حیرت شد و خشک و مبهوت بر در و دیوار باقی ماند(صورت چین: صورتگر و نقاش چین؛ در ادبیات و فرهنگ گذشته ما مردمان چین به صورتگری و نقاشی مشهور بوده اند)',NULL);
INSERT INTO "verses" VALUES(1939715,2307,9,1,'که حدیثش همه‌جا در در و دیوار بِمانْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939716,2307,8,0,'داشتم دلقی و صد عیبِ مرا می‌پوشید','تا اکنون خرقه ای داشتم که به واسطه ی پوشیدن آن عیب و نشان کفر خود را پنهان می کردم اما حال که خرقه خود را برای گرفتن شراب و گوش دادن به صدای مطرب در گرو میخانه گذاشته ام تمام عیوب و نشان کفر من آشکار شده است',NULL);
INSERT INTO "verses" VALUES(1939717,2307,8,1,'خرقه رهنِ مِی و مطرب شد و زُنّار بِمانْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939718,2307,7,0,'از صدایِ سخنِ عشق ندیدم خوشتر','هیچ چیزی خوشتر و دلنشین تر از بازتاب سخن عشق در این عالم وجود ندارد و تنها یادگاری است که در این آسمان گردنده باقی خواهد ماند(نکته: چنانچه به سمت گنبدی فریاد زده شود، بازتاب و پژواک آن را خواهیم شنید، حافظ نیز با دیدی هنری، از این پدیده سود جسته است و ماندگاری عشق را درعالم نشان داده است)',NULL);
INSERT INTO "verses" VALUES(1939719,2307,7,1,'یادگاری که در این گنبدِ دَوّار بِمانْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939720,2307,6,0,'گشت بیمار که چون چشمِ تو گردد نرگس','گل نرگس نیز بیمار گشت تا شاید بتواند مانند چشمِ مستِ تو در عین خماری، زیبا و دلنشین شود، اما نه تنها ناز و کرشمه ی چشم تو را بدست نیاورد بلکه بیمار و معیوب باقی ماند',NULL);
INSERT INTO "verses" VALUES(1939721,2307,6,1,'شیوهٔ تو نَشُدَش حاصل و بیمار بِمانْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939722,2307,5,0,'جز دلِ من کز ازل تا به ابد عاشق رفت','تنها دل خود را می شناسم که از روز ابتدای آفرینش تا ابد عاشق باقی ماند وگرنه کس دیگری را نمیشناسم که در عشق و عاشقی پایدار و ثابت قدم مانده باشد',NULL);
INSERT INTO "verses" VALUES(1939723,2307,5,1,'جاودان کس نشنیدیم که در کار بِمانْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939724,2307,4,0,'هر مِیِ لعل کز آن دستِ بلورین سِتَدیم','هر جام شراب سرخ رنگی که از دست سپید و زیبا و بلورین یار گرفتیم تبدیل به اشک خونین شد و در چشم اشکبار باقی ماند',NULL);
INSERT INTO "verses" VALUES(1939725,2307,4,1,'آبِ حسرت شد و در چشمِ گهربار بِمانْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939726,2307,3,0,'محتسب شیخ شد و فِسقِ خود از یاد بِبُرد','محتسب به یکباره زاهد شد و تمام فسق و فجور خود را فراموش کرد، و تنها داستان عشق ماست که هنوز بر سر هر بازار گفته می شود و نقل محافل بازار است(محتسب: مأمور اجرای احکام شرعی، که همواره در اشعار حافظ بار معنایی منفی دارد.)',NULL);
INSERT INTO "verses" VALUES(1939727,2307,3,1,'قصّهٔ ماست که در هر سرِ بازار بِمانْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939728,2307,2,0,'صوفیان واسِتَدَنْد از گروِ مِی همه رَخْت','صوفیان همه رخت و لباس خود را از گرو باده درآوردند و تنها خرقه ی من است که هنوز در رهن باده و در میخانه باقی مانده است',NULL);
INSERT INTO "verses" VALUES(1939729,2307,2,1,'دلقِ ما بود که در خانهٔ خَمّار بِمانْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939730,2307,1,0,'اگر از پرده برون شد دلِ من عیب مکن','اگر دل من ازمسیر خود خارج گشت و رسوا شد بر او عیب و ایرادی نگیر و او را سرزنش نکن، خدا را شکر که دل من در حجاب گمان و شک باقی نماند و از آن خارج شد',NULL);
INSERT INTO "verses" VALUES(1939731,2307,1,1,'شُکرِ ایزد که نه در پردهٔ پندار بِمانْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939732,2307,0,0,'هر که شد مَحرمِ دل در حرمِ یار بِمانْد','هر کس رازدار و از آشنایان دل شد در حرم یار (معشوق) باقی خواهد ماند، اما آنکس که به این مرحله نرسید و نتوانست آن را درک کند، در مقام انکار باقی خواهد ماند و تمام این مراحل را انکار خواهد کرد',NULL);
INSERT INTO "verses" VALUES(1939733,2307,0,1,'وان که این کار ندانست در انکار بِمانْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939734,2306,9,0,'ز شعرِ دلکَشِ حافظ کسی بُوَد آگاه','تنها کسی می‌تواند از لطف و ظرافت های شعرهای حافظ آگاه شود که که توانایی درک لطافت و زبان پارسی دری را داشته باشد و بداند.',NULL);
INSERT INTO "verses" VALUES(1939735,2306,9,1,'که لطفِ طبع و سخن گفتنِ دَری داند',NULL,NULL);
INSERT INTO "verses" VALUES(1939736,2306,8,0,'به قَدّ و چهره هر آن کس که شاهِ خوبان شد','اگر کسی شرایط آن را داشت که به مقامی برسد تنها به شرط آنکه فهم و درک صحیح و رفتار درستی داشته باشد می تواند رشد کند به پادشاهی برسد',NULL);
INSERT INTO "verses" VALUES(1939737,2306,8,1,'جهان بگیرد اگر دادگستری داند',NULL,NULL);
INSERT INTO "verses" VALUES(1939738,2306,7,0,'مدارِ نقطهٔ بینش ز خالِ توست مرا','توان دید و درک من به خاطر عنایت وجود توست، چرا که فقط یک گوهرشناس می‌تواند ارزش گوهر را بشناسد. و به لطف تو می توان به اسرار و بینش صحیح پی برد.',NULL);
INSERT INTO "verses" VALUES(1939739,2306,7,1,'که قدرِ گوهرِ یک‌دانه جوهری داند',NULL,NULL);
INSERT INTO "verses" VALUES(1939740,2308,0,1,'چنان نماند، چنین نیز هم نخواهد ماند',NULL,NULL);
INSERT INTO "verses" VALUES(1939741,2308,1,0,'من ار چه در نظرِ یار خاک‌سار شدم','هوش مصنوعی: اگرچه من در نظر محبوبم به درجهٔ خاک‌ساری رسیده‌ام، اما رقیب هم به همین شکل به احترام نخواهد ماند.',NULL);
INSERT INTO "verses" VALUES(1939742,2308,1,1,'رقیب نیز چنین محترم نخواهد ماند',NULL,NULL);
INSERT INTO "verses" VALUES(1939743,2308,2,0,'چو پرده‌دار به شمشیر می‌زند همه را','هوش مصنوعی: وقتی که نگهبان با شمشیر حمله می‌کند، هیچ‌کس در حریم امن و مقدس باقی نخواهد ماند.',NULL);
INSERT INTO "verses" VALUES(1939744,2310,0,1,'که به بالای چَمان از بُن و بیخَم بَرکَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939745,2309,7,0,'حافظ چو تَرکِ غمزهٔ تُرکان نمی‌کنی','هوش مصنوعی: حافظ می‌گوید: اگر از حسادت و زخم زبان ترک‌ها رنج می‌بری، می‌دانی که جای تو کجاست؟ آیا در خوارزم هستی یا در خُجَند؟',NULL);
INSERT INTO "verses" VALUES(1939746,2309,7,1,'دانی کجاست جای تو؟ خوارزم یا خُجَند',NULL,NULL);
INSERT INTO "verses" VALUES(1939747,2309,6,0,'جایی که یارِ ما به شِکَرخنده دَم زند','هوش مصنوعی: در جایی که معشوق ما با شوق و خنده حرف می‌زند، ای پسته، تو کیستی که بخواهی به خودت بخندانی؟',NULL);
INSERT INTO "verses" VALUES(1939748,2309,6,1,'ای پسته کیستی تو، خدا را به خود مخند',NULL,NULL);
INSERT INTO "verses" VALUES(1939749,2309,5,0,'بازارِ شوق گرم شد آن سروْقد کجاست؟','هوش مصنوعی: بازار عشق و هیجان پر رونق شده است، آن درخت زیبای کجایست؟ من آماده‌ام تا برای زیبایی‌اش جانم را در آتش شوق بگذارم.',NULL);
INSERT INTO "verses" VALUES(1939750,2309,5,1,'تا جانِ خود بر آتش رویش کُنم سپند',NULL,NULL);
INSERT INTO "verses" VALUES(1939751,2309,4,0,'ز آشفتگیِ حالِ من آگاه کِی شود؟','هوش مصنوعی: کسی که دل به عشق دچار نشده باشد، هرگز از حال آشفته من باخبر نخواهد شد.',NULL);
INSERT INTO "verses" VALUES(1939752,2309,4,1,'آن را که دل نگشت گرفتارِ این کمند',NULL,NULL);
INSERT INTO "verses" VALUES(1939753,2309,3,0,'گر جلوه می‌نمایی و گر طعنه می‌زنی','هوش مصنوعی: اگر خود را نشان می‌دهی یا به ما کنایه می‌زنی، ما به نظریات شخص مغرور و خودپسند خود اعتقاد نداریم.',NULL);
INSERT INTO "verses" VALUES(1939754,2309,3,1,'ما نیستیم معتقدِ شیخِ خودپسند',NULL,NULL);
INSERT INTO "verses" VALUES(1939755,2309,2,0,'خواهی که برنخیزدت از دیده رودِ خون','هوش مصنوعی: اگر می‌خواهی از چشمانت اشک نریزد و دلت نمی‌خواهد در وفای محبت دیگران دچار مشکل شوی، نباید آنها را ترک کنی و از آنها فاصله بگیری.',NULL);
INSERT INTO "verses" VALUES(1939756,2309,2,1,'دل در وفایِ صحبتِ رودِ کسان مَبَند',NULL,NULL);
INSERT INTO "verses" VALUES(1939757,2309,1,0,'طوبی ز قامتِ تو نیارد که دَم زند','هوش مصنوعی: تو به قدری زیبا و برجسته‌ای که درخت طوبی نمی‌تواند به پای تو برسد. از این داستان و موضوع فراتر می‌روم، زیرا صحبت به اینجا ختم نمی‌شود و نیاز به بحث بیشتری دارد.',NULL);
INSERT INTO "verses" VALUES(1939758,2314,2,1,'گَر فَلَکْشان بِگُذارَد کِه قَراری گیرَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939759,2309,1,1,'زین قصّه بگذرم که سخن می‌شود بلند',NULL,NULL);
INSERT INTO "verses" VALUES(1939760,2309,0,0,'ای پستهٔ تو خنده زده بر حدیثِ قند','هوش مصنوعی: ای پستهٔ شیرین تو با لبخندت به داستان شیرینی اشاره می‌کنی، من به خاطر خدا یک بار دیگر انتظار دارم که شکر بگذاری و بخندی.',NULL);
INSERT INTO "verses" VALUES(1939761,2308,8,0,'ز مهربانیِ جانان طمع مَبر حافظ','هوش مصنوعی: به علت مهربانی و محبت معشوق، نباید به چیزی جز عشق و دوستی دل ببندی، حافظ؛ زیرا نخواهند ماند آثار ظلم و ستم.',NULL);
INSERT INTO "verses" VALUES(1939762,2308,8,1,'که نقشِ جور و نشانِ ستم نخواهد ماند',NULL,NULL);
INSERT INTO "verses" VALUES(1939763,2308,7,0,'بدین رَواقِ زَبَرجَد نوشته‌اند به زر','هوش مصنوعی: در اینجا به زیبایی و با خط طلا نوشته شده است که تنها خوبی و نیکی افراد با سخاوت و کرامت باقی خواهد ماند.',NULL);
INSERT INTO "verses" VALUES(1939764,2308,7,1,'که «جز نکوییِ اهلِ کرم نخواهد ماند»',NULL,NULL);
INSERT INTO "verses" VALUES(1939765,2308,6,0,'توانگرا! دلِ درویشِ خود به دست آور','هوش مصنوعی: ای توانگر! دل درویش را به دست آور، چرا که ثروت و دارایی‌هایت همچنان که هستند، پایدار نخواهند ماند.',NULL);
INSERT INTO "verses" VALUES(1939766,2308,6,1,'که مخزنِ زَر و گنجِ دِرَم نخواهد ماند',NULL,NULL);
INSERT INTO "verses" VALUES(1939767,2308,5,0,'غنیمتی شِمُر ای شمع وصلِ پروانه!','هوش مصنوعی: ای شمع، ارزش این لحظه را بدان و از وصال پروانه بهره‌مند شو، چون این وضعیت تا صبح ادامه نخواهد داشت.',NULL);
INSERT INTO "verses" VALUES(1939768,2308,5,1,'که این معامله تا صبح‌دم نخواهد ماند',NULL,NULL);
INSERT INTO "verses" VALUES(1939769,2308,4,0,'سرودِ مجلسِ جمشید گفته‌اند این بود','هوش مصنوعی: در اینجا در مورد جشنی صحبت می‌شود که به زمان جمشید برمی‌گردد. گفته شده که در این مجلس از همه خواسته می‌شود تا جامی پر از نوشیدنی بیاورند، زیرا زندگی و زیبایی‌ها پایدار نیستند و زمانی که به پایان برسند، چیزی از آن‌ها باقی نخواهد ماند.',NULL);
INSERT INTO "verses" VALUES(1939770,2308,4,1,'که «جامِ باده بیاور که جم نخواهد ماند»',NULL,NULL);
INSERT INTO "verses" VALUES(1939771,2308,3,0,'چه جایِ شُکر و شکایت ز نقشِ نیک و بد است؟','هوش مصنوعی: در زندگی، جایی برای سپاسگزاری یا گلایه از خوبی‌ها و بدی‌ها وجود ندارد، زیرا هر چیزی که در این دنیا وجود دارد، در نهایت پایدار نخواهد ماند و نقش آن بر صفحهٔ هستی محو خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1939772,2308,3,1,'چو بر صحیفهٔ هستی رقم نخواهد ماند',NULL,NULL);
INSERT INTO "verses" VALUES(1939773,2308,2,1,'کسی مُقیمِ حریمِ حَرَم نخواهد ماند',NULL,NULL);
INSERT INTO "verses" VALUES(1939774,2309,0,1,'مشتاقم از برای خدا یک شِکَر بخند',NULL,NULL);
INSERT INTO "verses" VALUES(1939775,2314,3,0,'قُوَّتِ بازویِ پَرْهیز به خوبان مَفُروش!','هوش مصنوعی: بازوی پرهیزکاران را به راحتی نخر، زیرا در این جمع، افراد خوب و شایسته‌ای هستند که از آنها بهره‌مند خواهند شد.',NULL);
INSERT INTO "verses" VALUES(1939776,2314,3,1,'کِه در این خِیْل، حِصاری به سَواری گیرَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939777,2314,4,0,'یا‌ رَب! این بَچِّهٔ تُرکان چه دِلیرَنْد بِه خون','هوش مصنوعی: ای خدا، این جوانان ترک چه شجاع هستند که به کمک تیرکمان خود هر لحظه شکار می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1939778,2320,6,0,'زآن طُرّهٔ پرپیچ و خم،
INSERT INTO "verses" VALUES(1939779,2320,5,0,'چون من گدای بی‌نشان،
INSERT INTO "verses" VALUES(1939780,2320,5,1,'سلطان کجا عیشِ نهان،
INSERT INTO "verses" VALUES(1939781,2320,4,0,'پشمینه‌پوش تندخو، از
INSERT INTO "verses" VALUES(1939782,2320,4,1,'با مستی‌اش، رمزی بگو!
INSERT INTO "verses" VALUES(1939783,2320,3,0,'گفتم: «گره نگْشوده‌ام،
INSERT INTO "verses" VALUES(1939784,2320,3,1,'گفتا: «مَنَش فرموده‌ام،
INSERT INTO "verses" VALUES(1939785,2320,2,0,'دلبر که جان فرسود از
INSERT INTO "verses" VALUES(1939786,2320,2,1,'نومید نتْوان بود از
INSERT INTO "verses" VALUES(1939787,2320,1,0,'اول، بِه بانگِ نای و
INSERT INTO "verses" VALUES(1939788,2320,1,1,'وآن‌گه به یک پیمانه
INSERT INTO "verses" VALUES(1939789,2320,0,0,'آن، کیست کز روی
INSERT INTO "verses" VALUES(1939790,2320,0,1,'بر جای بدکاری چو من،
INSERT INTO "verses" VALUES(1939791,2319,7,0,'رَه نَبُرْدیم بِه مَقْصودِ خود اَنْدَر شیراز','هوش مصنوعی: ما در راه رسیدن به هدف خود در شیراز موفق نبودیم، اما آن روز که حافظ به سمت بغداد برود، خوشحال خواهیم بود.',NULL);
INSERT INTO "verses" VALUES(1939792,2319,7,1,'خُرَّم آن روز که «حافِظ»، رَهِ بَغْداد کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939793,2319,6,0,'گوهَرِ پاکِ تو از مِدْحَتِ ما مُسْتَغْنی‌ست','هوش مصنوعی: قیمت واقعی و ارزش تو از تعریف و ستایش ما بی‌نیاز است. تلاش کسی که می‌خواهد تو را آرایش کند، در برابر زیبایی طبیعی و خدادادی‌ات چه معنایی دارد؟',NULL);
INSERT INTO "verses" VALUES(1939794,2319,6,1,'فِکْرِ مَشّاطِه، چِه با حُسْنِ خُداداد کُنَد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939795,2319,5,0,'حالیا، عِشْوِهٔ نازِ تو، زِ بُنْیادَم بُرْد','هوش مصنوعی: این روزها، زیبایی و ناز تو مرا از اساس و بنیاد خود دور کرده است و حالا نمی‌دانم چگونه دوباره باید بر اساس حکمت و عقل زندگی را بسازم.',NULL);
INSERT INTO "verses" VALUES(1939796,2319,5,1,'تا دِگَربارِه، حَکیمانِه، چِه بُنْیاد کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939797,2319,4,0,'شاه را بِهْ بُوَد اَز طاعَتِ صَدسالِه و زُهْد','هوش مصنوعی: برتری شاه در پیروی و عبادت در مدتی طولانی است، اما زهد و پارسایی یک ساعت ممکن است ارزش بیشتری داشته باشد، اگر در آن زمان، حقیقتی را بیان کند و عدالت را برقرار کند.',NULL);
INSERT INTO "verses" VALUES(1939798,2319,4,1,'قَدْرِ یک ساعَتِه عُمْری کِه دَر او، داد کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939799,2319,3,0,'یا رَب! اَنْدَر دِلِ آن خُسْروِ شیرین اَنْداز','هوش مصنوعی: ای خدای مهربان، در دل آن پادشاه عزیز و محبوب، رحمت و محبت را بگذر که به لطف خود، بر روح فرهاد نیکویی کند.',NULL);
INSERT INTO "verses" VALUES(1939800,2319,3,1,'کِه بِه رَحْمَت، گُذَری بَر سَرِ فَرْهاد کُنَد!',NULL,NULL);
INSERT INTO "verses" VALUES(1939801,2319,2,0,'اِمْتِحان کُن! کِه بَسی گَنْجِ مُرادَت بِدَهَنْد','هوش مصنوعی: اگر تو هم مانند من در حال و روز بدی هستی، امتحان کن که آیا بخشش و محبت تو می‌تواند به کسی کمک کند و آرزوهای او را برآورده سازد.',NULL);
INSERT INTO "verses" VALUES(1939802,2319,2,1,'گَر خَرابی چو مَرا، لُطْفِ تو، آباد کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939803,2319,1,0,'قاصِدِ مَنْزِلِ سَلْمیٰ که سَلامَت بادَش','چه می‌شود اگر پیام‌آور خانهٔ معشوق، که برایش آرزوی سلامتی می‌کنم، با آوردن یک سلام (پیامی کوتاه و مختصر) دل ما را شاد کند؟',NULL);
INSERT INTO "verses" VALUES(1939804,2319,1,1,'چِه شَوَد، گَر بِه سَلامی، دِلِ ما، شاد کُنَد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939805,2319,0,0,'کِلْکِ مُشْکینِ تو، روزی که زِ ما یاد کُنَد','هوش مصنوعی: وقتی که موهای خوشبو و مشکی تو به یاد ما بیفتد، پاداش آزاد شدن دو صد بنده را می‌برد.',NULL);
INSERT INTO "verses" VALUES(1939806,2319,0,1,'بِبَرَد اَجْرِ دو صَد بَنْدِه کِه آزاد کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939807,2320,6,1,'از بند و زنجیرش چه غم،
INSERT INTO "verses" VALUES(1939808,2320,7,0,'شد لشکر غم بی‌عدد، از
INSERT INTO "verses" VALUES(1939809,2320,7,1,'تا فخرِ دین عبدالصّمد،
INSERT INTO "verses" VALUES(1939810,2320,8,0,'با چشم پر نیرنگ او،
INSERT INTO "verses" VALUES(1939811,2322,4,1,'آه اگر خِرْقِهٔ پَشْمین بِه گِرو نَسْتانَنْد!',NULL,NULL);
INSERT INTO "verses" VALUES(1939812,2322,3,0,'عَهْدِ ما با لَبِ شیرین‌دَهَنان بَسْت خُدا','ما از ازل پیمان عشق خود را با شیرین‌دهنان بسته‌ایم؛ ما بندگان هستیم و آنها پادشاهان هستند.',NULL);
INSERT INTO "verses" VALUES(1939813,2322,3,1,'ما، هَمِه، بَنْده و این قوم، خُداوَنْدان‌اَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939814,2322,2,0,'جِلْوِه‌گاهِ رُخِ او، دیدِهٔ مَن، تَنْها نیست','فقط من نیستم که پیوسته به‌او می‌نگرم و عاشق او هستم، بلکه ماه و خورشید نیز همین‌کار را می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1939815,2322,2,1,'ماه و خورشید، هَمین آیِنِه می‌گَردانَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939816,2322,1,0,'عاقِلان، نُقْطِهٔ پَرْگارِ وُجودَنْد وَلی','عاقلان و آنها که از عشق بی‌خبر هستند گرامی و گرانقدر هستند اما عشق‌، بها و ارزشی برای آنها قائل نیست.',NULL);
INSERT INTO "verses" VALUES(1939817,2322,1,1,'عِشْق دانَد کِه دَر این دایِرِه، سَرگَرْدان‌اند',NULL,NULL);
INSERT INTO "verses" VALUES(1939818,2322,0,0,'دَر نَظَربازیِ ما، بی‌خَبَران، حِیْران‌اَنْد','آدم‌های نادان معنی نظربازی ما را نمی‌دانند؛ من همان هستم که به‌آنها نمودم‌، حالا خود می‌دانند که چه برداشت کنند.',NULL);
INSERT INTO "verses" VALUES(1939819,2322,0,1,'مَن، چُنینم که نِمودَم؛ دِگَر ایشان دانَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939820,2321,9,0,'کُشتهٔ غمزهٔ تو شد، حافظِ ناشنیده‌پند','هوش مصنوعی: حافظ در این بیت به تاثیری که زیبایی و دلربایی معشوق بر او گذاشته اشاره می‌کند. او می‌گوید که به خاطر غمزه و ناز معشوق، دلش شکسته و گرفتار شده است. همچنین اشاره به این دارد که افرادی که از دردها و مشکلات حرف نمی‌زنند، سزاوار آسیب و سختی هستند. در واقع، اعتراف به درد و رنج انسان را از سرنوشت تلخ نجات می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1939821,2321,9,1,'تیغ سزاست هر که را، دَرد، سخن نمی‌کند',NULL,NULL);
INSERT INTO "verses" VALUES(1939822,2321,8,0,'دستخوشِ جفا مَکُن، آبِ رُخَم که فیضِ ابر','هوش مصنوعی: مرا آزاری نده که زیبایی چهره‌ام تنها با عشق و محبت تو به شکوفایی می‌رسد و بدون آن، زیبایی‌ام به درختی بی‌ثمر تبدیل می‌شود.',NULL);
INSERT INTO "verses" VALUES(1939823,2321,8,1,'بی‌مددِ سِرشکِ من، دُرِ عَدَن نمی‌کند',NULL,NULL);
INSERT INTO "verses" VALUES(1939824,2321,7,0,'ساقیِ سیم‌ساقِ من، گر همه دُرد می‌دهد','اگر ساقی یا معشوق به من تماما درد و اندوه میدهد، چه کسی هست که، همانطور که جام می برای بلعیدن شراب دهان باز میکند، تنش را برای پذیرفتن آن دَرد باز نکند.( استعاره از پذیرا بودن عاشق نسبت به هر دَرد و غمی که از معشوق میرسد)',NULL);
INSERT INTO "verses" VALUES(1939825,2318,8,0,'«حافِظا»! گَر نَرَوی از دَرِ او، هَم روزی','هوش مصنوعی: ای حافظ، اگر از آستان او دور شوی، روزی حتماً از یک طرف به تو سر می‌زند و گذرت را می‌بیند.',NULL);
INSERT INTO "verses" VALUES(1939826,2321,7,1,'کیست که تن چو جامِ مِی، جمله دهن نمی‌کند؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939827,2321,6,0,'دل به امیدِ رویِ او، همدمِ جان نمی‌شود','هوش مصنوعی: دل، به امید دیدن چهره او، به آرامش نمی‌رسد و جان هم به خاطر عشق و علاقه به محله او، به کار و تلاش نمی‌پردازد.',NULL);
INSERT INTO "verses" VALUES(1939828,2321,5,0,'چون ز نسیم می‌شود، زلفِ بنفشه پُرشِکَن','هوش مصنوعی: زمانی که نسیم به زلف‌های بنفشه وزیده و آن‌ها را پریشان می‌کند، یاد من از عهدی که با او داشتم، همچنان در دل من زنده نیست و فراموش نمی‌شود.',NULL);
INSERT INTO "verses" VALUES(1939829,2321,5,1,'وه که دلم چه یاد از آن، عهدشکن نمی‌کند',NULL,NULL);
INSERT INTO "verses" VALUES(1939830,2321,4,0,'با همه عطفِ دامنت، آیدم از صبا عجب','با آن همه عاطفه و محبتی که از وجود و دامان تو سر ریز می شود از باد صبا تعجب میکنم که چگونه هنگام گذر تو بر روی خاک ، آنرا مانند عطر مشکی که در سرزمین ختن است خوشبو نمی کند؟',NULL);
INSERT INTO "verses" VALUES(1939831,2321,4,1,'کز گذرِ تو، خاک را، مُشکِ خُتَن نمی‌کند',NULL,NULL);
INSERT INTO "verses" VALUES(1939832,2321,3,0,'پیشِ کمانِ ابرویش، لابه همی کنم ولی','هوش مصنوعی: من با تمام وجود و التماس‌های خود، به زیبایی ابروی او نگاه می‌کنم، اما او توجهی به من ندارد و گوشش را از من دور کرده است.',NULL);
INSERT INTO "verses" VALUES(1939833,2321,3,1,'گوش کشیده است از آن، گوش به من نمی‌کند',NULL,NULL);
INSERT INTO "verses" VALUES(1939834,2321,2,0,'تا دلِ هرزه‌گَردِ من، رفت به چینِ زلفِ او','هوش مصنوعی: زمانی که دل بی‌پروا و سرگردان من به زیبایی‌های گیسوان او وابسته شد، از آن سفر طولانی که کرده‌ام، هیچ تمایلی به بازگشت به وطن ندارم.',NULL);
INSERT INTO "verses" VALUES(1939835,2321,2,1,'زان سفرِ درازِ خود، عزمِ وطن نمی‌کند',NULL,NULL);
INSERT INTO "verses" VALUES(1939836,2321,1,0,'دی گِلِه‌ای ز طُرِّه‌اش، کردم و از سرِ فُسوس','هوش مصنوعی: روزی با موهای او بازی می‌کردم و از نابسامانی او این گونه گفتم که این فرد سیاه‌چرده و لائی، به حرف من توجهی ندارد.',NULL);
INSERT INTO "verses" VALUES(1939837,2321,1,1,'گفت که «این سیاه‌کج، گوش به من نمی‌کند»',NULL,NULL);
INSERT INTO "verses" VALUES(1939838,2321,0,0,'سروِ چَمانِ من چرا میلِ چمن نمی‌کند؟','چرا همسر قد بلند من که همچون سرو است به خانه نمیاید ?همدم من که مانند گل هستم نمی شود و از بچه هایمان که مانند سمن هستند یاد نمی کند?',NULL);
INSERT INTO "verses" VALUES(1939839,2321,0,1,'همدمِ گل نمی‌شود، یادِ سَمَن نمی‌کند',NULL,NULL);
INSERT INTO "verses" VALUES(1939840,2320,8,1,'کآن طُرِّهٔ شبرنگِ
INSERT INTO "verses" VALUES(1939841,2321,6,1,'جان به هوایِ کویِ او، خدمتِ تن نمی‌کند',NULL,NULL);
INSERT INTO "verses" VALUES(1939842,2306,6,0,'هزار نکتهٔ باریک‌تر ز مو این جاست','در زندگی و ظرایف و نکات بسیاری وجود دارد که تنها عده کمی از آن‌ها آگاهند. و هر کسی با تظاهر به دانایی توان فهم آن نکات موضوعات را ندارند',NULL);
INSERT INTO "verses" VALUES(1939843,2318,8,1,'گُذَری بَر سَرَت از گوشِه کِناری بِکُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939844,2318,7,0,'یا وَفا، یا خَبَرِ وَصْلِ تو، یا مَرْگِ رَقیب','هوش مصنوعی: آیا برای من وفا خواهد بود، یا خبری از وصال تو به دست خواهد آمد، یا اینکه مرگ رقیب خواهد بود؟ آیا آسمان از میان این دو یا سه کار، اقدامی انجام خواهد داد؟',NULL);
INSERT INTO "verses" VALUES(1939845,2316,3,0,'طَبیبِ عِشْق، مَسیحا‌دَم است و مُشْفِق، لیک','عشق، طبیبی است که هم دلسوز است و هم نفسش شفابخش، اما وقتی هیچگونه درد و نیازی در تو نمی­بیند چگونه تو را درمان کند.',NULL);
INSERT INTO "verses" VALUES(1939846,2316,3,1,'چو دَرد، دَر تو نَبینَد؛ کِه را دَوا بِکُنَد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939847,2316,2,0,'زِ مُلْک تا مَلَکوتَش، حِجاب بَردارَنْد','هرکس خدمت­گزار جام جهان نما باشد تمام حجاب­ها _ از عالم ماده تا عالم الهی _ برای او برداشته خواهد شد و اسرار الهی را مشاهده خواهد کرد.(جام جهان نما: جام جمشید، دل عارف)',NULL);
INSERT INTO "verses" VALUES(1939848,2316,2,1,'هَر آن‌کِه خِدْمَتِ جامِ جَهان‌نَما بِکُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939849,2316,1,0,'عِتابِ یارِ پَری‌چِهْرِه، عاشِقانِه بِکَش!','خشم و ملامت آمیخته با ناز معشوق را عاشقانه تحمل کن، زیرا یک نگاه عاشقانه از جانب معشوق جبران صدها جور و جفا را خواهد کرد.',NULL);
INSERT INTO "verses" VALUES(1939850,2316,1,1,'کِه یِک کِرِشْمِه، تَلافیِّ صَد جَفا بِکُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939851,2316,0,0,'دِلا! بِسوز! که سوزِ تو، کارها بِکُنَد','ای دل رنج و سختی را تحمل کن و شکسته باش که همین دل شکستگی گره­گشا و کارساز تو خواهد بود، و راز نیاز نیم­شبی صدها بلا و گرفتاری را از تو دور خواهد کرد.',NULL);
INSERT INTO "verses" VALUES(1939852,2316,0,1,'نیازِ نیم‌شَبی، دَفْعِ صَد بَلا بِکُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939853,2315,7,0,'جان رَفْت دَر سَرِ مِی و «حافِظ»، بِه عِشْق سوخت','هوش مصنوعی: حیات و وجود حافظ به عشق و شوق می‌گذرد و او در دلش آرزوی تجدید حیات دارد. او به درستی می‌خواهد بگوید که آیا عیسی، که می‌تواند جان ما را زنده کند، کجاست تا به ما دیوانه‌گی عشق را ببخشد؟',NULL);
INSERT INTO "verses" VALUES(1939854,2315,7,1,'عیسی‌دَمی کُجاست کِه اِحْیایِ ما کُنَد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939855,2315,6,0,'ما را که دَرْدِ عِشْق و بَلایِ خُمار کُشْت','هوش مصنوعی: ما را که درد عشق و مشکلات ناشی از نشئگی کشت، یا وصال دوست یا شراب خالص می‌تواند درمان کند.',NULL);
INSERT INTO "verses" VALUES(1939856,2315,6,1,'یا وَصْلِ دوست یا مِیِ صافی، دَوا کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939857,2315,5,0,'مُطْرِب بِساز پَرْدِه! کِه کَس، بی‌اَجَل نَمُرْد','هوش مصنوعی: بشنوید و لذت ببرید، زیرا هیچ‌کس بدون سرنوشت خود نمی‌میرد و کسی که این آهنگ را نمی‌خواند، به اشتباه می‌افتد.',NULL);
INSERT INTO "verses" VALUES(1939858,2315,5,1,'وان کاو نَه این تَرانِه سُرایَد، خَطا کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939859,2315,4,0,'دَر کارخانِه‌ای که رَهِ عَقْل و فَضْل نیست','در کارگاه هستی که عقل و فضل هم به عمق آن راه پیدا نمی‌کنند چرا باید انتظار داشت که فهم ناتوان یک فضول (نادان) به آن راه پیدا کند؟',NULL);
INSERT INTO "verses" VALUES(1939860,2315,4,1,'فَهْمِ ضعیف‌رای‌، فُضولی چِرا کُنَد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939861,2315,3,0,'گر رَنْج، پیشَت آیَد و گَر راحَت، ای حکیم!','هوش مصنوعی: اگر در زندگی سختی پیش بیاید یا راحتی بیابی، ای حکیم، نمی‌توانی نسبت به دیگران برخورد کنی، چون این‌ها همگی از خداوند ناشی می‌شوند.',NULL);
INSERT INTO "verses" VALUES(1939862,2315,3,1,'نِسْبَت مَکُن بِه غِیْر! کِه این‌ها خُدا کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939863,2315,2,0,'حَقّا کَز این غَمان بِرِسَد مُژْدِهٔ اَمان','هوش مصنوعی: به درستی اگر کسی با وفا به وعده‌هایش عمل کند، می‌تواند نوید آزادی و رهایی از غم‌ها را به ارمغان آورد.',NULL);
INSERT INTO "verses" VALUES(1939864,2315,2,1,'گَر سالِکی، بِه عَهْدِ اَمانَت، وَفا کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939865,2315,1,0,'ساقی، به جامِ عَدْل بِدِه بادِه! تا گِدا','هوش مصنوعی: ای ساقی، نوشیدنی را در جام انصاف بریز تا گدا و نیازمندان غیرت و شرف را از یاد نبرند، زیرا زندگی پر از مشکلات و بلاهاست.',NULL);
INSERT INTO "verses" VALUES(1939866,2315,1,1,'غِیْرَت نَیاوَرَد، کِه جَهان پُر‌بَلا کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939867,2315,0,0,'گَر مِی‌فُروش، حاجَتِ رِنْدان رَوا کُنَد','هوش مصنوعی: اگر می‌فروش نیازهای حاضران را برآورده کند، خداوند گناهان را می‌بخشد و calamities را دور می‌کند.',NULL);
INSERT INTO "verses" VALUES(1939868,2315,0,1,'ایزَد، گُنَه بِبَخْشَد و دَفْعِ وبا کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939869,2314,6,0,'«حافِظ»! اَبْنایِ زَمان را غَمِ مِسْکینان نیست','هوش مصنوعی: حافظ می‌گوید: فرزندان زمانه، دل‌نگرانی افراد بیچاره را ندارند و اگر ممکن باشد، باید با کسانی که در این دردها نمی‌باشند، هم‌نشینی کرد.',NULL);
INSERT INTO "verses" VALUES(1939870,2314,6,1,'زین میان گَر بِتَوان بِهْ کِه کِناری گیرَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939871,2314,5,0,'رَقْص بَر شِعْرِ تَر و نالهٔ نِی خوش باشَد','هوش مصنوعی: رقص بر روی شعر زیبا و صدای نی لذتی خاص دارد، به ویژه رقصی که در آن دست هنرمندی را به همراه داشته باشند.',NULL);
INSERT INTO "verses" VALUES(1939872,2314,5,1,'خاصِه، رَقْصی کِه دَر آن، دَسْتِ نِگاری گیرَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939873,2314,4,1,'کِه بِه تیرِ مُژه، هَر لَحْظِه، شِکاری گیرَنْد',NULL,NULL);
INSERT INTO "verses" VALUES(1939874,2316,4,0,'تو با خدایِ خود اَنداز کار! و دِل، خوش دار!','تو کارها را به خدا واگذار کن و دلت خوش باشد؛ چرا که اگر مدعی لاف زن به تو رحم نکند، خداوند قطعا رحیم و مهربان است.',NULL);
INSERT INTO "verses" VALUES(1939875,2316,4,1,'کِه رَحْم اَگَر نَکُنَد مُدَّعی‌، خُدا بِکُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939876,2316,5,0,'زِ بَخْتِ خُفْتِه مَلولَم، بُوَد که بیداری','از بخت و اقبال نامساعد آزرده ­ام، امید است که انسان بیدار دل شب زنده داری در هنگام صبح دعایی در حق من بکند.',NULL);
INSERT INTO "verses" VALUES(1939877,2316,5,1,'بِه وَقْتِ فاتِحِهٔ صُبْح، یک دُعا بِکُنَد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939878,2318,6,0,'کو کَریمی که ز بَزْمِ طَرَبَش، غَم‌زَدِه‌ای','هوش مصنوعی: آیا کسی هست که از جشن و شادی‌اش، دل‌شکسته‌ای را بنوشاند و غم و ناخوشی‌اش را بزداید؟',NULL);
INSERT INTO "verses" VALUES(1939879,2318,6,1,'جُرعِه‌ای دَرکَشَد و دَفْعِ خُماری بِکُنَد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939880,2318,5,0,'شَهْر، خالی‌ست زِ عُشّاق؛ بُوَد کَز طَرَفی','هوش مصنوعی: شهر از عشق و عاشقان خالی است، زیرا اگر مردی از سمت خود برخیزد و اقدامی انجام دهد، وضعیت تغییر خواهد کرد.',NULL);
INSERT INTO "verses" VALUES(1939881,2318,5,1,'مَرْدی اَز خویش بُرون آید و کاری بِکُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939882,2318,4,0,'دادِه‌اَم بازِ نَظَر را به تَذَرْوی، پرواز','هوش مصنوعی: من نگاهی را دوباره به پروازی پیشکش کرده‌ام، تا شاید بتواند نقشی را به تصویر بکشد و صیدی را به دام اندازد.',NULL);
INSERT INTO "verses" VALUES(1939883,2318,4,1,'بازخوانَد مَگَرَش نَقْش و شِکاری بِکُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939884,2318,3,0,'کَس نیارَد برِ او دَم زنَد از قِصِّهٔ ما','هوش مصنوعی: هیچ‌کس نمی‌تواند برای او در بارهٔ داستان ما سخن بگوید، مگر اینکه نسیم سحرگاهی به او خبر دهد.',NULL);
INSERT INTO "verses" VALUES(1939885,2318,3,1,'مَگَرَش بادِ صَبا گوش، گُذاری بِکُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939886,2318,2,0,'دوش گُفْتَم: «بِکُنَد لَعْلِ لَبَش، چارِهٔ مَن؟»','هوش مصنوعی: دیشب به لب‌های زیبای او اشاره کردم که مشکل من را حل کند، ناگاه صدای الهی به من گفت که بله، او می‌تواند مشکل مرا برطرف کند.',NULL);
INSERT INTO "verses" VALUES(1939887,2318,2,1,'هاتِفِ غِیْب، نِدا داد کِه: «آری! بِکُنَد»',NULL,NULL);
INSERT INTO "verses" VALUES(1939888,2318,1,0,'دیدِه را دَسْتگَهِ دُرّ و گُهَر، گَرچِه نَمانْد','هوش مصنوعی: چشمانت اگرچه دستاوردهای ارزشمندی ندارند، باز هم می‌توانند از غم و اندوهی که در دل دارند، فریاد بزنند و تدبیر و برنامه‌ریزی کنند.',NULL);
INSERT INTO "verses" VALUES(1939889,2318,1,1,'بِخورَد خونی و تَدْبیرِ نِثاری بکُند',NULL,NULL);
INSERT INTO "verses" VALUES(1939890,2318,0,0,'طایِرِ دولَت اَگَر باز گُذاری بِکُنَد','هوش مصنوعی: اگر به من یاری برگردد و فرصت مناسب فراهم شود، دوباره یکدیگر را خواهیم دید و ارتباطی برقرار خواهیم کرد.',NULL);
INSERT INTO "verses" VALUES(1939891,2318,0,1,'یار بازآیَد و با وَصْل، قَراری بِکُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939892,2318,7,1,'بُوَد آیا که فَلَک، زین دو سِه، کاری بِکُنَد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939893,2317,6,0,'زِ دیدِه، خون بِچِکانَد فَسانِهٔ «حافِظ»','هنگامی که حافظ یادی از سرگذشت و داستان زندگی خود چه در زمان پیری چه جوانی کند باعث خون گریستنِ دیدگان می شود( حکایتگر آن است که در تمام عمر سختی ها و تلخ کامی های فراوانی را پشت سر گذاشته است.)',NULL);
INSERT INTO "verses" VALUES(1939894,2317,5,0,'شُبانِ وادیِ اَیْمَن، گَهی رَسَد بِه مُراد','وادی اَیمن: بیابانی که حضرت موسی در آن چوپانی می کرد٬ موسی زمانی به هدف خود ( کلیم اللهی) می رسد که چند سال با جان و دل خدمتگزازی حضرت شعیب را کرده باشد.( اشاره به لزوم سلوک عملی در طریقت برای رسیدن به حقیقت)',NULL);
INSERT INTO "verses" VALUES(1939895,2317,5,1,'کِه چَنْد سال، به جان، خِدْمَتِ شُعِیْب کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939896,2317,4,0,'کِلیدِ گَنْجِ سَعادَت، قَبولِ اَهْلِ دِل اَسْت','رَیب: شک و تردید٬ رستگاری همانند گنجی است که کلید آن در گرو پذیرش و مقبول واقع شدن در پیشگاه اهل دل ( آنان که دل هایشان از تعلقات دنیوی پاک و آیینه وار شده) می باشد مبادا کسی در این مسأله دقیق تردیدی داشته باشد.',NULL);
INSERT INTO "verses" VALUES(1939897,2317,4,1,'مَباد آن‌که در این نکته، شَکّ و رِیْب کُنَد!',NULL,NULL);
INSERT INTO "verses" VALUES(1939898,2317,3,0,'چُنان زَنَد رَهِ اِسْلام، غَمْزِهٔ ساقی','صهیب: از صحابه رسول اکرم که به تقوا و پارسایی مشهور است.ناز و کرشمه ی ساقی آنچنان دل انگیز است که همانند راهزنی بر قافله ی اسلام می تازد( و ما را به نوشیدن وادار می کند) شاید تنها صهیب در( چنین شرایطی )قادر باشد از نوشیدن بپرهیزد.',NULL);
INSERT INTO "verses" VALUES(1939899,2317,3,1,'کِه اِجْتِناب زِ صَهْبا، مَگَر صُهِیْب کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939900,2317,2,0,'زِ عِطْرِ حورِ بِهِشْت، آن نَفَس بَرآیَد بوی','شامه و بویایی از جمله حواسی است که نزد اهل کشف از اهمیت ویژه ای برخوردار است همانطور که ترکیب (بوی حق ) پر کاربرد بوده و نیز در حدیث نبوی ( رائحه الرحمن ) را مشاهده می کنیم؛ آن زمانی عطر حوری بهشتی بوی حق می دهد که خاک میخانه ی ما ( اهل حقیقت ) را مانند عبیر در گریبان خود بگذارد.',NULL);
INSERT INTO "verses" VALUES(1939901,2317,2,1,'که خاکِ مِیْکَدِهٔ ما، عَبیرِ جِیب کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939902,2317,1,0,'کَمالِ سِرِّ مُحَبَّت بِبین، نَه نَقْصِ گُناه','محبت همان شور و شوق بسیار سالک برای رسیدن به خداوند است و همانند رازی است که با سیر انفسی ( سفر به درون خویش ) به کمال آن می توان پی برد؛ این کمال را ببین نه کاستی های حاصل از گناه را زیرا انسان بی هنر ( فاقد کمال و فضل ) توان پی بردن به گوهر محبت را ندارد پس ناچار توجه خود را معطوف عیوب می کند.',NULL);
INSERT INTO "verses" VALUES(1939903,2317,1,1,'کِه هَرکِه بی‌هُنَر اُفْتَد، نَظَر به عِیْب کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939904,2317,0,0,'مَرا به رِنْدی و عِشْق، آن فُضول، عِیْب کُنَد','شخصی که توانایی فهمیدن حکمت اسرار الهی را ندارد به حقیقت رندی و عشق من نیز پی نمی برد و به همین سبب از آن ایراد می گیرد.فضول شخص کارنادان و دهن بین و عیب جو است در حقیقت چنین شخصی به هر آنچه که فراتر از فهم اوست اعتراض می کند.',NULL);
INSERT INTO "verses" VALUES(1939905,2317,0,1,'کِه اِعْتِراض بَر اَسْرارِ عِلْمِ غِیْب کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939906,2316,6,0,'بِسوخْت «حافِظ» و بویی به زُلْفِ یار نَبُرْد','در غم دوری معشوق سوخت و هیچگونه نشانی از معشوق پیدا نکرد، شاید باد صبا او را به این بخت و اقبال( بوییدن عطر دلاویز معشوق) برساند.',NULL);
INSERT INTO "verses" VALUES(1939907,2316,6,1,'مَگَر دِلالَتِ این دولَتَش، صَبا بِکُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939908,2317,6,1,'چو یادِ وَقْتِ زَمانِ شَباب و شِیْب کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(1939909,2306,6,1,'نه هر که سر بتراشد قلندری داند',NULL,NULL);
INSERT INTO "verses" VALUES(1939910,2306,5,0,'بباختم دلِ دیوانه و ندانستم','دل سرگشته ی خود را باختم و نمی دانستم که کسی چگونه می‌تواند به شیوه‌ای چنین جذاب و فریبنده رفتار کنند.',NULL);
INSERT INTO "verses" VALUES(1939911,2306,5,1,'که آدمی‌بچه‌ای، شیوهٔ پری داند',NULL,NULL);
INSERT INTO "verses" VALUES(1939912,2296,3,0,'به صدرِ مَصطَبه‌ام می‌نِشانَد اکنون دوست','اکنون یار من، مرا در صدر مجلس طرب و می‌خواری می‌نشاند؛ بخت نیک مرا بنگر که چگونه گدای شهر، سرور مجلس شد.',NULL);
INSERT INTO "verses" VALUES(1939913,2296,2,0,'به بویِ او دلِ بیمارِ عاشقان چو صبا','همچون باد صبا که عاشق و فدای روی زیبای نسرین و چشم مست نرگس می‌شود، دل بیمار و عاشق من نیز عاشق روی و چشم او گشت.',NULL);
INSERT INTO "verses" VALUES(1939914,2296,3,1,'گدایِ شهر نِگَه کُن که میرِ مجلس شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939915,2296,1,0,'نگارِ من که به مکتب نرفت و خط ننوشت','یار و بت زیبای من که به مکتب نرفت و چیزی ننوشت با یک غمزه هزار درس به‌من آموخت و استاد صد مدرّس و استاد شد.',NULL);
INSERT INTO "verses" VALUES(1939916,2296,2,1,'فدایِ عارضِ نسرین و چشمِ نرگس شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939917,2296,0,0,'ستاره‌ای بدرخشید و ماهِ مجلس شد','ستاره‌ای در آسمان پیدا گشت که از بس زیباست ماه مجلس شد و بر صدر نشست و در دل و جان ما نشست.',NULL);
INSERT INTO "verses" VALUES(1939918,2296,1,1,'به غمزه مسأله‌آموزِ صد مُدَرِّس شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939919,2296,0,1,'دل رمیدهٔ ما را رفیق و مونس شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939920,2295,7,0,'در شمار ار چه نیاورد کسی حافظ را','هوش مصنوعی: اگرچه هیچ‌کس حافظ را در رده‌های بالای شاعران قرار نداد، اما او از این بابت شکرگزار است، زیرا رنج‌ها و مشکلات بی‌حد و شماره‌اش در نهایت به نتیجه‌ای خوش ختم شد.',NULL);
INSERT INTO "verses" VALUES(1939921,2295,7,1,'شُکرْ کان محنتِ بی‌حدّ و شمار آخر شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939922,2295,6,0,'ساقیا لطف نمودی قدحت پُر مِی باد','هوش مصنوعی: ای ساقی، تو با محبت خود، جامی پر از شراب به من دادی. امیدوارم با تدبیر و هنر تو، نگرانی و بی‌قراری من در اثر مستی به پایان برسد.',NULL);
INSERT INTO "verses" VALUES(1939923,2295,6,1,'که به تدبیرِ تو تشویشِ خُمار آخر شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939924,2295,5,0,'باورم نیست ز بدعهدی ایام هنوز','هوش مصنوعی: نمی‌توانم باور کنم که هنوز داستان غم و اندوهی که در دوران خوشی با محبوبم به پایان رسید، وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1939925,2295,5,1,'قصهٔ غصه که در دولتِ یار آخر شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939926,2295,4,0,'آن پریشانیِ شب‌هایِ دراز و غمِ دل','هوش مصنوعی: غم و بی‌قراری‌های شب‌های طولانی و درد دل همه به لطف زیبایی و وجود معشوق پایان یافت.',NULL);
INSERT INTO "verses" VALUES(1939927,2295,4,1,'همه در سایهٔ گیسویِ نگار آخر شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939928,2295,3,0,'صبحِ امّید که بُد معتکفِ پردهٔ غیب','هوش مصنوعی: صبح امیدی که در حال اعتکاف در پرده غیب بود، اکنون زمان آن رسیده که خارج شود، زیرا کار شب تار پایان یافته است.',NULL);
INSERT INTO "verses" VALUES(1939929,2295,3,1,'گو برون آی که کارِ شبِ تار آخر شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939930,2295,2,0,'شُکرِ ایزد که به اقبالِ کُلَه گوشهٔ گُل','هوش مصنوعی: شکر خدا که با خوشبینی و دستاوردهای جدید، دیگر نه از باد سرد دی خبری هست و نه از سختی‌های خار.',NULL);
INSERT INTO "verses" VALUES(1939931,2295,2,1,'نَخوَتِ بادِ دی و شوکتِ خار آخر شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939932,2295,1,0,'آن همه ناز و تَنَعُّم که خزان می‌فرمود','همه شکوه و جلالی که از پاییز سراغ داریم، در برابر باد جان افزای بهار نه حرفی برای گفتن دارد و نه یارای ماندن دارد',NULL);
INSERT INTO "verses" VALUES(1939933,2295,1,1,'عاقبت در قدمِ بادِ بهار آخر شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939934,2295,0,0,'روزِ هجران و شبِ فُرقَتِ یار آخر شد','هوش مصنوعی: روز جدایی و شب فراق یار به پایان رسید. من این فال را زدم و زمان و امور نیز گذشتند.',NULL);
INSERT INTO "verses" VALUES(1939935,2295,0,1,'زدم این فال و گذشت اختر و کار آخر شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939936,2294,6,0,'مشوی ای دیده نقشِ غم ز لوحِ سینهٔ حافظ','ای چشم، غم را از دل‌ نوشته‌های حافظ پاک مکن و مشوی، زیرا این درد‌، از زخم عشق است و رنگ خون شسته نمی‌شود و می‌ماند.',NULL);
INSERT INTO "verses" VALUES(1939937,2294,6,1,'که زخمِ تیغِ دلدار است و رنگِ خون نخواهد شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939938,2294,5,0,'شرابِ لعل و جایِ امن و یارِ مهربان ساقی','شراب سرخ و جایی خلوت و در کنار ساقی مهربان؛ ای دل اگر امروز به آرزویت نرسی، کی خواهی رسید؟',NULL);
INSERT INTO "verses" VALUES(1939939,2294,5,1,'دلا کی بِه شود کارت اگر اکنون نخواهد شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939940,2294,4,0,'مجالِ من همین باشد که پنهان عشقِ او ورزم','فرصت و بهره من فقط این است که پنهانی به او عشق بورزم، درباره کنار او بودن و بوسیدن و در آغوش گرفتن او چه بگویم وقتی که هرگز اتفاق نخواهند افتاد.',NULL);
INSERT INTO "verses" VALUES(1939941,2296,4,0,'خیالِ آبِ خِضِر بست و جامِ اسکندر','قصد نوشیدن از چشمه حیات و جام اسکندر کرد تا به جرعه‌نوشی سلطان ابوالفوارس رسید.',NULL);
INSERT INTO "verses" VALUES(1939942,2296,4,1,'به جرعه‌نوشیِ سلطان ابوالفَوارِس شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939943,2296,5,0,'طرب‌سرایِ محبت کنون شود مَعمور','باغ شادی و خانه نشاط عشق، آباد خواهد شد زیرا اکنون ابروی یار من مهندس طاق اوست.',NULL);
INSERT INTO "verses" VALUES(1939944,2296,5,1,'که طاقِ اَبرویِ یارِ مَنَش مهندس شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939945,2298,1,0,'آب حیوان تیره‌گون شد، خضر فرخ‌پِی کجاست؟','حافظ می‌گوید حتی آب حیات نیز تیره شده است. خضر که نماد راهبری و حیات بود، دیگر دیده نمی‌شود. گل که باید نشانه زندگی باشد، خون می‌چکاند. این تصویر، وارونگی طبیعت است. بهار که زمان شکوفایی است، غایب شده است. شاعر از به‌هم‌ریختگی نظم طبیعی سخن می‌گوید. جهان دیگر آن‌گونه که باید، کار نمی‌کند. تصاویر بیت تلخ و متضادند. زندگی به جای طراوت، زخم دارد. حافظ از فقدان هدایت می‌گوید. هدایت بیرونی و درونی. در تفسیر کنایی، آب حیات می‌تواند نماد امید باشد. تیره شدن آن یعنی ناامیدی فراگیر. خضر نماد رهبران اخلاقی یا فکری است. غیبت او یعنی بی‌راهنمایی جامعه. خون از شاخ گل یعنی رنج در دل زیبایی. حافظ می‌گوید حتی چیزهای خوب هم آسیب‌دیده‌اند. بهار نماد زمان مناسب اصلاح است. نبود آن یعنی تعویق درمان. این بیت تصویری از بحران عمیق است. بحرانی که به ظاهر و باطن نفوذ کرده است. شاعر به علائم توجه می‌دهد، نه فقط علت‌ها.',NULL);
INSERT INTO "verses" VALUES(1939946,2298,1,1,'خون چکید از شاخِ گل، بادِ بهار‌ان را چه شد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939947,2298,0,0,'یاری اندر کس نمی‌بینیم، یاران را چه شد؟','حافظ می‌گوید دیگر در هیچ‌کس نشانی از یاری نمی‌بیند. گویی اصل همراهی از میان رفته است. او می‌پرسد دوستی از چه زمانی به پایان رسید. این پرسش ناظر به یک تغییر تدریجی است، نه حادثه‌ای ناگهانی. شاعر وضعیت اکنون را با گذشته مقایسه می‌کند. یاران در نگاه او کسانی بودند که در سختی کنار هم می‌ایستادند. حالا این حضور غایب است. پرسش او سرزنش مستقیم ندارد. بیشتر حیرت‌زده است. گویی نمی‌داند این دگرگونی چگونه رخ داده است. بیت، فضای کلی غزل را مشخص می‌کند. در تفسیر کنایی، یاری می‌تواند نماد تعهد انسانی باشد. دوست‌داران نماد کسانی‌اند که روزی ارزش رابطه را می‌دانستند. حافظ می‌گوید روابط به پوسته تبدیل شده‌اند. پیوندها هست، اما وفا نیست. این بیت نقدی است بر مناسبات سطحی. شاعر از نبود مسئولیت عاطفی شکایت دارد. پرسش او متوجه فرد خاصی نیست. متوجه یک فضاست. فضایی که در آن، دوستی مصرفی شده است. این نگاه اجتماعی حافظ است. نگاهی که هنوز هم قابل لمس است.',NULL);
INSERT INTO "verses" VALUES(1939948,2298,0,1,'دوستی کِی آخر آمد؟ دوست‌دار‌ان را چه شد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1939949,2297,8,0,'هزار حیله برانگیخت حافظ از سرِ فکر','حافظ از سر ناچاری، هزار ترفند اندیشید، به آن امید که یار کنار بیاید؛ و نشد. [به استناد لغتنامه دهخدا، واژهٔ «فکر» (ترجیحاً با تلفظ fakr) به معنی «نیاز» نیز می‌باشد. از اینرو، «از سرِ فکر»، به معنی «از سرِ ناچاری» است.]',NULL);
INSERT INTO "verses" VALUES(1939950,2297,8,1,'در آن هوس که شود آن نگار رام و نشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939951,2297,7,0,'دریغ و درد که در جست و جوی گنجِ حضور','افسوس که در جست‌وجوی وصال معشوق خود بسی گدایی و طلب از اهالی کرامت و صاحبان معرفت کردم اما همچنان وصلی اتفاق نیفتاد',NULL);
INSERT INTO "verses" VALUES(1939952,2297,7,1,'بسی شدم به گدایی بَرِ کِرام و نشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939953,2297,6,0,'فغان که در طلبِ گنج نامهٔ مقصود','فریاد که در یافتن راه وصال به معشوق در همه عالم از غم بد نام شدم و هیچ راه نیافتم',NULL);
INSERT INTO "verses" VALUES(1939954,2297,6,1,'شدم خرابِ جهانی ز غم تمام و نشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939955,2297,5,0,'به کویِ عشق مَنِه بی دلیلِ راه، قدم','راه عشق را کاروان‌سالار و راهنماییست که بدون آن‌ها نمی‌توان این راه را پیمود چون من بسیار تلاش کردم که خود با درایت خود این راه را طی کنم ولیکن به مقصد نرسیدم',NULL);
INSERT INTO "verses" VALUES(1939956,2297,5,1,'که من به خویش نمودم صد اهتمام و نشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939957,2297,4,0,'بدان هوس که به مستی ببوسم آن لبِ لعل','در آرزوی بوسیدنش در مستی و بی‌خودی خون در دل من( مانند شراب در جام باده) افتاد اما این خواسته هم برآورده نشد',NULL);
INSERT INTO "verses" VALUES(1939958,2297,4,1,'چه خون که در دلم افتاد همچو جام و نشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939959,2294,4,1,'کنار و بوس و آغوشش چه گویم چون نخواهد شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939960,2297,3,0,'رواست در بَر اگر می‌تَپَد کبوترِ دل','اگر کبوتر دلم شوق پرواز دارد و می‌خواهد که پرواز را دوباره در آسمان عشق تو پرواز کند شایسته است زیرا که در راه خود نشانی از تاب زلفت تو را دید و ندانست دام اوست',NULL);
INSERT INTO "verses" VALUES(1939961,2297,2,0,'پیام داد که خواهم نشست با رندان','بمن گفت که با شراب‌خواران و افراد لاابالی همنشین خواهم شد به هوای راه یافتن در دل او چه بسیاری مرا لاابالی و شراب‌خوار میخوانند اما باز هم این امر اثری در دل او نداشت',NULL);
INSERT INTO "verses" VALUES(1939962,2297,2,1,'بشد به رندی و دُردی کشیم نام و نشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939963,2297,1,0,'به لابه گفت شبی میرِ مجلسِ تو شوم','به لابه گفت: "شبی میر مجلس تو می‌شوم". در پی خواسته‌اش، کمترین غلامش شدم، ولی چنان نشد.',NULL);
INSERT INTO "verses" VALUES(1939964,2297,1,1,'شدم به رغبتِ خویشش کمین غلام و نشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939965,2297,0,0,'گداخت جان که شود کارِ دل تمام و نشد','جان گداخت که شاید مشکل دل حل شود، ولی نشد. در همین آرزوی خام سوختم، که نشد. [در لغتنامه دهخدا، «کار» به معنی «مسئله» یا «مشکل» هم آمده است]',NULL);
INSERT INTO "verses" VALUES(1939966,2297,0,1,'بسوختیم در این آرزویِ خام و نشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939967,2296,9,0,'ز راهِ میکده یاران عِنان بگردانید','دوستان، از رفتن به میکده بپرهیزید، زیرا حافظ بدانجا رفت و تنگدست و بی‌پول شد.',NULL);
INSERT INTO "verses" VALUES(1939968,2296,8,0,'چو زر عزیزِ وجود است نظمِ من، آری','نظم و شعر من همچون زر و جواهر ارزشمند است؛ زیرا نظر قبول نیک‌بختان بدان افتاد و همچون کیمیا این‌مس را به زر کرد.',NULL);
INSERT INTO "verses" VALUES(1939969,2296,9,1,'چرا که حافظ از این راه رفت و مفلس شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939970,2296,7,0,'کرشمهٔ تو شرابی به عاشقان پیمود','یک کرشمه و غمزه تو شراب و باده‌ای به عاشقان نوشاند که دانایی از یاد رفت و عقل‌، بی‌خود گشت.',NULL);
INSERT INTO "verses" VALUES(1939971,2296,8,1,'قبولِ دولتیان کیمیایِ این مس شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939972,2296,6,0,'لب از تَرَشُّحِ مِی پاک کن برایِ خدا','برای رضای خدا، لب‌های خود را از می پاک کن زیرا خاطر من را به هزاران گناه، وسوسه می‌کند.',NULL);
INSERT INTO "verses" VALUES(1939973,2296,7,1,'که عِلم بی‌خبر افتاد و عقل بی‌حس شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939974,2296,6,1,'که خاطرم به هزاران گُنَه مُوَسوِس شد',NULL,NULL);
INSERT INTO "verses" VALUES(1939975,2297,3,1,'که دید در رهِ خود تاب و پیچِ دام و نشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939976,2298,2,0,'کس نمی‌گوید که «یاری داشت حقِّ دوستی»','کسی نمی‌گوید که دوست هم حق دوستی داشت. بر سرِ حق‌شناسان چه آمد؟ برای دوستان چه رُخ داد؟',NULL);
INSERT INTO "verses" VALUES(1939977,2294,3,0,'خدا را محتسب ما را به فریادِ دَف و نِی بخش','تو را به خدا ای داروغه، ما را به صدای دَف و نِی ببخش؛ زیرا قانون شرع از این آواز آسیبی نخواهد دید.',NULL);
INSERT INTO "verses" VALUES(1939978,2294,2,0,'مرا روزِ ازل کاری به جز رندی نفرمودند','در آغاز آفرینش، کاری جز رندی برای من تعیین نکردند؛ بیش از آن‌چیزی که در آنجا مقدر شده، نخواهد شد.',NULL);
INSERT INTO "verses" VALUES(1939979,2292,0,0,'گل بی‌رخِ یار خوش نباشد','هوش مصنوعی: گل بدون چهره محبوب زیبا نیست و بهار بدون شراب هم خوشایند نیست.',NULL);
INSERT INTO "verses" VALUES(1939980,2291,10,0,'کسی گیرد خطا بر نظمِ حافظ','کسی به شعر حافظ ایراد می‌گیرد که در ذات او لطفی نیست.',NULL);
INSERT INTO "verses" VALUES(1939981,2291,10,1,'که هیچش لطف در گوهر نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939982,2291,9,0,'به تاجِ عالم آرایش که خورشید','به تاج جهان‌آرای او سوگند که خورشید نیز، چنین زیبندهٔ تاج نیست.',NULL);
INSERT INTO "verses" VALUES(1939983,2291,9,1,'چنین زیبندهٔ افسر نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939984,2291,8,0,'من از جان بندهٔ سلطان اویسم','من از صمیم قلب‌، تسلیم و خدمت‌گزار سلطان اویس هستم، هرچند او ممکن است مرا فراموش کرده باشد.',NULL);
INSERT INTO "verses" VALUES(1939985,2291,8,1,'اگر چه یادش از چاکر نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939986,2291,7,0,'شرابی بی‌خمارم بخش یا رب','خدایا شراب بی‌خماری به من بده که سر درد نیاورد. [شراب بی‌خمار، شرابی است که نوشیدنش، پی‌آور سردرد نیست. چنین شرابی، عملا دارای کمترین مقدار قند و نیز هیستامین است.]',NULL);
INSERT INTO "verses" VALUES(1939987,2291,7,1,'که با وی هیچ دردِ سر نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939988,2291,6,0,'ز من بنیوش و دل در شاهدی بند','بنیوش‌: بشنو.',NULL);
INSERT INTO "verses" VALUES(1939989,2291,6,1,'که حُسنش بستهٔ زیور نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939990,2291,5,0,'بشوی اوراق اگر هم‌درسِ مایی','و تو اگر هم‌درس ما هستی و با ما موافق؛ اوراق و کتاب‌ها را به فراموشی سپار زیرا عشق چیزی نیست که از کتاب و مکتب بیاموزی.',NULL);
INSERT INTO "verses" VALUES(1939991,2291,5,1,'که عِلمِ عشق در دفتر نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939992,2291,4,0,'بیا ای شیخ و از خُم‌خانهٔ ما','ای شیخی ‌(که شادی و مستی را نمی‌پسندی‌ و آن‌را به بهشت وعده می‌کنی) بیا از این خُم‌خانه و انبار شراب ما‌، شرابی بنوش که آن‌را در بهشت نیز نخواهی یافت.',NULL);
INSERT INTO "verses" VALUES(1939993,2291,4,1,'شرابی خور که در کوثر نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939994,2291,3,0,'ایا پُرلعل کرده جامِ زَرّین','و وقتی که شاد و دارا هستی دیگران را نیز شاد بگردان و از مال خود به شکرانه ببخش.',NULL);
INSERT INTO "verses" VALUES(1939995,2291,3,1,'ببخشا بر کسی کش زر نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939996,2291,2,0,'غنیمت دان و مِی خور در گلستان','شادی را غنیمت شمر و در میان گل‌ها باش زیرا عمر این گل‌ها و لحظات‌، همیشگی و تا ابد نیست و شاید دیگر به‌دست نیاید.',NULL);
INSERT INTO "verses" VALUES(1939997,2291,2,1,'که گُل تا هفتهٔ دیگر نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1939998,2291,1,0,'زمانِ خوش‌دلی دریاب و دُر یاب','قدر لحظات خوش و نیک‌دلی را دریاب و آن‌را از دست مده زیرا همیشه اینچنین در صدف‌ لحظه‌‌ها، دُر و گوهر نیست.',NULL);
INSERT INTO "verses" VALUES(1939999,2291,1,1,'که دایم در صدف گوهر نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1940000,2291,0,0,'خوش آمد گُل وز آن خوش‌تر نباشد','فصل گل و بهار و زیبایی است و چیزی بهتر از این نیست که مست و شاد باشی.',NULL);
INSERT INTO "verses" VALUES(1940001,2291,0,1,'که در دستت بجز ساغر نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1940002,2290,6,0,'آن نیست که حافظ را رِندی بِشُد از خاطر','ین نکته دانی و صداقت جسارت آمیز حافظ هم یکی از نعمت های ازلی است که در سرنوشت او نوشته شده و این ویژگی در روز اول خلقت به او اعطا شده و تا قیامت هم باقی خواهد ماند. رندی: آزادگی، صداقت، جسارت، هوش و نکته بینی عارف،سابقه پیشین: مربوط به روز اول خلقت،روز پسین: روز قیامت',NULL);
INSERT INTO "verses" VALUES(1940003,2290,6,1,'که‌این سابقهٔ پیشین تا روزِ پَسین باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1940004,2290,5,0,'در کارِ گلاب و گل حکمِ ازلی این بود','در نظر شاعر، قسمت و تقدیر است که سرنوشت آدم ها را مشخص می کند، تا زیبا روئی مجبور به زیبایی فروشی همگانی باشد و زیبا رویی دیگر در اندرونی، مستور و به دور از فشارهای زندگی، به او رسیدگی شده و با آسایش زندگی کند. (گلاب در واقع همان گل است که تحت فشارهای زندگی او را فشرده اند و پخته اند و از او عرق گرفته اند و در سر هر بازاری فروخته اند.)',NULL);
INSERT INTO "verses" VALUES(1940005,2290,5,1,'کاین شاهدِ بازاری وآن پرده‌نشین باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1940006,2290,4,0,'جامِ میْ و خونِ دل هر یک به کسی دادند','شاعر چگونگی تقسیم سرنوشت را این طور تصویر کرده: ما در یک میهمانی ای نشسته بودیم که نامش دایره قسمت بوده است و در آن میهمانی افراد می نشسته اند و سرنوشتشان را به شکل یک شراب سرخ در پیاله هایشان می ریخته اند. ولی برای بعضی، به صورت کاملاً اتفاقی شراب سرخوش کننده ریخته نمی شود، بلکه خون دل در پیاله هایشان ریخته می شود و آن ها مجبورند آن را در طول زندگی سر بکشند.',NULL);
INSERT INTO "verses" VALUES(1940007,2290,4,1,'در دایرهٔ قسمت اوضاع چنین باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1940008,2292,0,1,'بی‌باده بهار خوش نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1940009,2292,1,0,'طَرفِ چمن و طوافِ بستان','هوش مصنوعی: چمن و باغی که در آن گل‌های زیبا نباشد، خوشحال‌کننده نخواهد بود.',NULL);
INSERT INTO "verses" VALUES(1940010,2292,1,1,'بی‌لاله‌عذار خوش نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1940011,2292,2,0,'رقصیدن سرو و حالتِ گُل','هوش مصنوعی: رقصیدن درخت و زیبایی گل، بدون صدای هزاران خوشی، دل‌انگیز و لذت‌بخش نخواهد بود.',NULL);
INSERT INTO "verses" VALUES(1940012,2294,2,1,'هر آن قسمت که آن جا رفت از آن افزون نخواهد شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940013,2294,1,0,'رقیب آزارها فرمود و جایِ آشتی نگذاشت','رقیب آزارها رساند آنقدر که جای آشتی نگذاشت؛ آیا آه سحرخیزان بی‌پاسخ خواهد ماند؟',NULL);
INSERT INTO "verses" VALUES(1940014,2294,1,1,'مگر آهِ سحرخیزان سویِ گردون نخواهد شد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940015,2294,0,0,'مرا مِهر سیَه چشمان ز سر بیرون نخواهد شد','عشق زیبارویانِ سیاه‌چشم از فکر و دل و جان من بیرون نخواهد رفت، این بخشی از تقدیر آسمانی من است و تغییر نخواهد کرد.',NULL);
INSERT INTO "verses" VALUES(1940016,2294,0,1,'قضای آسمان است این و دیگرگون نخواهد شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940017,2293,8,0,'حافظ از بهر تو آمد سویِ اقلیمِ وجود','هوش مصنوعی: حافظ به خاطر تو به این دنیا آمده است، پس با یک وداع ساده او را ترک نکن که به زودی روحش خواهد رفت.',NULL);
INSERT INTO "verses" VALUES(1940018,2293,8,1,'قدمی نِه به وداعش که روان خواهد شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940019,2293,7,0,'مطربا مجلسِ انس است غزل خوان و سرود','هوش مصنوعی: ای مطرب، اینجا مجلسی است پر از انس و صمیمیت؛ بیا و چند غزل و سرود بخوان. چرا درباره رویدادهای گذشته و آینده صحبت می‌کنی؟',NULL);
INSERT INTO "verses" VALUES(1940020,2293,7,1,'چند گویی که چنین رفت و چنان خواهد شد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940021,2293,6,0,'گل عزیز است غنیمت شِمُریدَش صحبت','علی زارع:یار خوب مثل گل دوست داشتنی است پس لحظاتی که با یار هستی را غنیمت بشمار، زیرا همواره زیبایی‌های زندگی مثل گل به این باغ می‌آیند و از راه‌های مختلف به ما می‌رسند.',NULL);
INSERT INTO "verses" VALUES(1940022,2293,6,1,'که به باغ آمد از این راه و از آن خواهد شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940023,2293,5,0,'ماه شعبان مَنِه از دست قدح، کاین خورشید','هوش مصنوعی: ماه شعبان را از دست نده، زیرا این نور آفتاب تا شب عید رمضان ناپدید خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1940024,2293,5,1,'از نظر تا شبِ عیدِ رمضان خواهد شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940025,2293,4,0,'ای دل ار عشرتِ امروز به فردا فکنی','ای دل، اگر لذت امروز را کنار بگذاری و به فردا بگزاری، چه چیزی می‌تواند ضامن بقا و ادامه زندگی‌ات باشد؟',NULL);
INSERT INTO "verses" VALUES(1940026,2294,3,1,'که سازِ شرع از این افسانه بی‌قانون نخواهد شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940027,2293,4,1,'مایهٔ نقدِ بقا را که ضَمان خواهد شد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940028,2293,3,0,'گر ز مسجد به خرابات شدم خرده مگیر','اگر از مسجد به میخانه رفتم، ایرادی نگیر؛ چون مجلس وعظ طولانی است و زمان زیادی از دستم خواهد رفت.',NULL);
INSERT INTO "verses" VALUES(1940029,2293,2,0,'این تَطاول که کشید از غمِ هجران بلبل','هوش مصنوعی: اینکه بلبل به خاطر غم جدایی از گل، تا جایی که گل در آن قرار دارد با صدای بلند ناله و فریاد می‌کند، نشان‌دهنده‌ی شدت احساس اوست.',NULL);
INSERT INTO "verses" VALUES(1940030,2293,2,1,'تا سراپردهٔ گل نعره‌زنان خواهد شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940031,2293,1,0,'ارغوان جامِ عقیقی به سمن خواهد داد','هوش مصنوعی: گل‌های ارغوان به زودی در جامی از سنگ عقیق می‌ریزد و چشمان نرگس به گل شقایق توجه خواهند کرد.',NULL);
INSERT INTO "verses" VALUES(1940032,2293,1,1,'چشمِ نرگس به شقایق نگران خواهد شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940033,2293,0,0,'نفسِ بادِ صبا مُشک‌فشان خواهد شد','باد صبحگاهی عطری دل‌انگیز به همراه خواهد داشت ، دنیا کهن دوباره جوان و سرزنده خواهد گردید.',NULL);
INSERT INTO "verses" VALUES(1940034,2293,0,1,'عالَمِ پیر دگرباره جوان خواهد شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940035,2292,5,0,'جان نقدِ مُحَقَّر است حافظ','هوش مصنوعی: حافظ می‌گوید که جان، ارزشی کم‌اهمیت و ناچیز دارد و برای فدای آن در راه چیزهایی که واقعا با ارزش نیستند، نباید تلاش کرد.',NULL);
INSERT INTO "verses" VALUES(1940036,2292,5,1,'از بهرِ نثار خوش نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1940037,2292,4,0,'هر نقش که دستِ عقل بندد','هوش مصنوعی: هر چه که به دست عقل و تفکر طراحی شود، جز زیبایی‌های حقیقی، ارزش چندانی ندارد.',NULL);
INSERT INTO "verses" VALUES(1940038,2292,4,1,'جز نقشِ نگار، خوش نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1940039,2292,3,0,'با یارِ شکرلبِ گل‌اندام','هوش مصنوعی: با محبوب شیرین‌لب و زیبا بدون بوسه و در آغوشی، حال خوشی نخواهد بود.',NULL);
INSERT INTO "verses" VALUES(1940040,2292,3,1,'بی‌بوس و کنار خوش نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1940041,2292,2,1,'بی‌صوتِ هَزار خوش نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1940042,2293,3,1,'مجلس وعظ دراز است و زمان خواهد شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940043,2290,3,1,'نقشش به حرام اَر خود صورتگر چین باشد',NULL,NULL);
INSERT INTO "verses" VALUES(1940044,2298,2,1,'حق‌شناسان را چه حال افتاد؟ یاران را چه شد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940045,2298,3,0,'لعلی از کانِ مُروّت برنیامد سال‌هاست','حافظ می‌گوید سال‌هاست از معدن مروت، گوهری بیرون نیامده است. یعنی جوانمردی دیگر ثمر نمی‌دهد. او می‌پرسد خورشید و باد و باران چه شدند. این‌ها عوامل طبیعی رویش‌اند. اگر گوهر نمی‌روید، یا زمین مرده است یا عوامل غایب‌اند. شاعر به توقف فضیلت اشاره می‌کند. فضیلتی که نیاز به پرورش دارد. بیت لحنی تحلیلی دارد. حافظ دنبال ریشه‌هاست. چرا مروت خشکیده است. این پرسش اجتماعی عمیق است. در تفسیر کنایی، لعل نماد رفتار بزرگوارانه است. کان مروت جامعه است. خورشید و باران نماد آموزش، الگو و شرایط سالم‌اند. حافظ می‌گوید وقتی این‌ها نباشند، فضیلت زاده نمی‌شود. این بیت نقد ساختارهاست، نه افراد. شاعر می‌گوید نباید فقط از نبود اخلاق شکایت کرد. باید دید چه چیزی آن را پرورش می‌دهد. این نگاه سیستماتیک حافظ است. او فقط ناله نمی‌کند. به چرایی فکر می‌کند. همین ویژگی شعر را زنده نگه می‌دارد.',NULL);
INSERT INTO "verses" VALUES(1940046,2304,3,0,'به گوشِ هوش نیوش از من و به عشرت کوش','سخن مرا با گوش جان بشنو و به کامرانی بپرداز؛ زیرا این سخن را بامدادان از پیام آوری شنیده‌ام که دیده نمی‌شود.',NULL);
INSERT INTO "verses" VALUES(1940047,2304,3,1,'که این سخن سَحَر از هاتفم به گوش آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940048,2304,2,0,'تنورِ لاله چنان برفروخت بادِ بهار','باد بهاری چنان در تنور لاله (آتش عشق) دمید که غنچه‌ غرق عرق شد و گل‌، ناآرام گردید.',NULL);
INSERT INTO "verses" VALUES(1940049,2304,2,1,'که غنچه غرقِ عرق گشت و گل به جوش آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940050,2304,1,0,'هوا مسیح‌نفس گشت و باد نافه‌گشای','هوا چون دم مسیح (زندگی بخش) شد و باد مشک پراکند. درخت جوانه زد و پرنده، آواز سر داد.',NULL);
INSERT INTO "verses" VALUES(1940051,2304,1,1,'درخت سبز شد و مرغ دَر خروش آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940052,2304,0,0,'صبا به تهنیتِ پیرِ مِی‌فروش آمد','باد صبا به پیرِ مِی‌فروش مژده داد که زمان شادی، خوشی و کامرانی کامل فرارسیده است.',NULL);
INSERT INTO "verses" VALUES(1940053,2304,0,1,'که موسمِ طرب و عیش و ناز و نوش آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940054,2303,6,1,'لطفِ او بین که به لطف از درِ ما بازآمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940055,2303,5,1,'تا به گوشِ دلم آوازِ دَرا بازآمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940056,2303,6,0,'گرچه حافظ دَرِ رَنجِش زد و پیمان بِشکست','اگرچه حافظ رنجیده‌خاطر گشت و قول خود را شکست؛ لطف یار او را ببین که با مهربانی و لطف به‌نزد او بازگشت.',NULL);
INSERT INTO "verses" VALUES(1940057,2303,4,1,'داغ‌دل بود، به امّیدِ دوا بازآمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940058,2303,5,0,'چشمِ من در رهِ این قافلهٔ راه بماند','چشم به راه کاروانی بودم که قرار بود برسد. تا آنکه به گوش دل، صدای زنگ شتر را شنیدم.',NULL);
INSERT INTO "verses" VALUES(1940059,2303,3,1,'کـ‌آن بتِ ماه‌رخ از راهِ وفا بازآمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940060,2303,4,0,'لاله بویِ میِ نوشین بشنید از دمِ صبح','لاله، بوی بادهٔ شیرین از نسیم صبح شنید؛ داغ بر دل داشت، برای درمان آمد. [به استناد لغتنامهٔ دهخدا، «نوشین» یعنی «شیرین»]',NULL);
INSERT INTO "verses" VALUES(1940061,2303,2,1,'تا بپرسد که چرا رفت و چرا بازآمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940062,2303,3,0,'مردمی کرد و کرم لطفِ خداداد به من','یار زیبا و ماهرخ من، بسیار در حق من نیکویی و کرم کرد که با من آشتی کرد و مهربان شد.',NULL);
INSERT INTO "verses" VALUES(1940063,2303,1,1,'که سلیمانِ گل از بادِ هوا بازآمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940064,2303,2,0,'عارفی کو که کُنَد فَهْم زبانِ سوسن','عارف و دانای پاکیزه‌ای کجاست تا زبان گل سوسن را بفهمد و از او بپرسد که چرا ما را ترک کرد و چرا بازآمد؟',NULL);
INSERT INTO "verses" VALUES(1940065,2303,0,1,'هدهد خوش‌خبر از طَرْفِ سبا بازآمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940066,2303,1,0,'برکش ای مرغِ سحر نغمهٔ داوودی باز','ای بلبل، دوباره نغمه داوودی سر بده، زیرا گل زیبا همراه باد باز آمده است. [نغمهٔ داوودی، آوازی بوده که داوود در ستایش خدا می‌خوانده است. احتمالا منظور از «سلیمانِ گل»، گل بسیار زیبای «سوسن» باشد. به این دلیل که حافظ در همین غزل آشکارا از آن نام می‌برد و نیز اینکه گفته می‌شود داوود در نامه‌ای عاشقانه‌، از «گل سوسن» یاد کرده است.]',NULL);
INSERT INTO "verses" VALUES(1940067,2303,0,0,'مژده ای دل که دگر بادِ صبا بازآمد','ای دل مژده بده که که سرانجام باد صبا برگشت؛ و پوپک پیام‌آورِ دیار سبا از راه رسید. [در اینجا–و به استناد لغتنامهٔ دهخدا–«دگر» یعنی سرانجام]',NULL);
INSERT INTO "verses" VALUES(1940068,2302,7,1,'تا بگویم که ز عهدِ طربم یاد آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940069,2302,6,1,'ای خوشا سرو که از بارِ غم آزاد آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940070,2302,7,0,'مطرب از گفتهٔ حافظ غزلی نَغز بخوان','ای مطرب! غزلی نو و تازه از حافظ بخوان؛ تا مرا به‌یاد نشاط و روز خوش جوانی بیندازد.',NULL);
INSERT INTO "verses" VALUES(1940071,2302,5,1,'دلبرِ ماست که با حُسنِ خداداد آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940072,2302,6,0,'زیرِ بارند درختان که تعلّق دارند','درختانی که میوه و تعلّقی دارند همه در زحمت هستند؛ سرو را می‌پسندم که از بار غم آزاد است.',NULL);
INSERT INTO "verses" VALUES(1940073,2302,4,1,'حجلهٔ حُسن بیارای که داماد آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940074,2302,5,0,'دلفریبانِ نباتی همه زیور بستند','تمام مهرویان شیرین (یا گل‌های بوستان) همگی زیور و زینت بسته‌اند؛ تنها دلبر و یار من است که زیبایی و حسن او خداداد است.',NULL);
INSERT INTO "verses" VALUES(1940075,2304,4,0,'ز فکرِ تفرقه بازآی تا شوی مجموع','از اندیشهٔ تفرقه بیرون بیا تا مجموع شوی؛ زیرا پس از رفتن اهرمن، سروش می‌آید. [تفرقه و جمع همیشه در کنار هم هستند! به استناد لغتنامه دهخدا (نقل از عطار نیشابوری)، «جمع» عین حق است و «تفرقه» صفت حق.]',NULL);
INSERT INTO "verses" VALUES(1940076,2304,4,1,'به حکمِ آنکه چو شد اهرمن سروش آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940077,2304,5,0,'ز مرغِ صبح ندانم که سوسنِ آزاد','نمیدانم سوسن آزاد از مرغ صبح چه شنید که با داشتنِ دَه زبان، خاموشی گزید.',NULL);
INSERT INTO "verses" VALUES(1940078,2304,5,1,'چه گوش کرد که با دَه زبان خموش آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940079,2306,4,0,'وفا و عهد نکو باشد ار بیاموزی','اگر وفاداری و عمل به عهد را یاد بگیری، نیکو و پسندیده هست؛ وگرنه هر کسی را که ببینی، راه و رسم ظلم و ستمگری را می‌شناسد.',NULL);
INSERT INTO "verses" VALUES(1940080,2306,4,1,'وگر نه هر که تو بینی ستمگری داند',NULL,NULL);
INSERT INTO "verses" VALUES(1940081,2306,3,0,'غلامِ همّتِ آن رندِ عافیت‌سوزم','من بنده‌ی همت و تلاش آن زیرکی هستم که در حالتی ظاهری شبیه به فقر و ناداری، توانایی تبدیل اوضاع را به بهترین شکل دارد.',NULL);
INSERT INTO "verses" VALUES(1940082,2306,3,1,'که در گداصفتی کیمیاگری داند',NULL,NULL);
INSERT INTO "verses" VALUES(1940083,2306,2,0,'تو بندگی چو گدایان به شرطِ مزد مکن','همچون مزدوران و به خاطر مزد و پاداش عمل نکن، زیرا دوست (خدا) خود روش و شیوه‌ ی جبران تلاش شما را با محبت و رحمت نسبت به بندگانش می داند. و حواسش به همه چیز هست.',NULL);
INSERT INTO "verses" VALUES(1940084,2306,2,1,'که دوست، خود روشِ بنده‌پروری داند',NULL,NULL);
INSERT INTO "verses" VALUES(1940085,2306,1,0,'نه هر که طَرْفِ کُلَه کج نهاد و تُند نشست','هر کسی که کلاهش را به شکل پادشاهان بر روی سرش بگذارد و تندی کرده و دیگران را امر و نهی کند، لزوماً نمی‌تواند از عهده مسئولیت‌ها و ویژگی‌های رهبری و بزرگ‌منشی برآید.',NULL);
INSERT INTO "verses" VALUES(1940086,2306,1,1,'کلاه‌داری و آیینِ سروری داند',NULL,NULL);
INSERT INTO "verses" VALUES(1940087,2306,0,0,'نه هر که چهره برافروخت دلبری داند','هر کس که چهره ی خود را برافروخته و گلگون سازد شیوه ی دلربایی و دلبری را بلد نیست و هرکه آینه بسازد اسکندر نیست و شیوهٔ او (پادشاهی عالم‌گستر) را بلد نیست! / اشاره به ، آینهٔ سترگ مشهوری دارد که اسکندر ساخت و بخشی از ساختمان «فانوس دریایی» معروف اوست',NULL);
INSERT INTO "verses" VALUES(1940088,2306,0,1,'نه هر که آینه سازد سِکندری داند',NULL,NULL);
INSERT INTO "verses" VALUES(1940089,2305,7,0,'چون صبا گفتهٔ حافظ بشنید از بلبل','هوش مصنوعی: وقتی که نسیم به حرف‌های حافظ گوش داد، بلبل با شادی و آوازش به تماشای گل‌ها و باغ‌ها آمد.',NULL);
INSERT INTO "verses" VALUES(1940090,2305,7,1,'عَنبرافشان به تماشایِ ریاحین آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940091,2305,6,0,'رسمِ بدعهدیِ ایّام چو دید ابرِ بهار','هوش مصنوعی: وقتی ابر بهاری بدعهدی روزگار را مشاهده کرد، به خاطر گل‌ها و گیاهان معطر سمن، سنبل و نسرین اشک‌هایش ریخت.',NULL);
INSERT INTO "verses" VALUES(1940092,2305,6,1,'گریه‌اش بر سمن و سنبل و نسرین آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940093,2302,3,1,'شادی آورد گل و بادِ صبا شاد آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940094,2305,5,0,'ساقیا می بده و غم مخور از دشمن و دوست','هوش مصنوعی: ای ساقی، باده بده و نگران نباش از دشمن و دوست؛ زیرا یکی از آن‌ها خواسته ما را برآورده کرد و دیگری به سراغ ما آمد.',NULL);
INSERT INTO "verses" VALUES(1940095,2305,4,0,'مرغِ دل باز هوادارِ کمان‌ابروییست','هوش مصنوعی: دل شاد و امیدوار به عشق کسی است که چهره‌ای زیبا و جذاب دارد، اما ای کبوتر، احتیاط کن؛ خطر در کمین است و ممکن است دشمنی قوی و بی‌رحم نزدیک شده باشد.',NULL);
INSERT INTO "verses" VALUES(1940096,2305,4,1,'ای کبوتر نگران باش که شاهین آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940097,2305,3,0,'گریه آبی به رخِ سوختگان بازآورد','هوش مصنوعی: گریه مانند آبی است که به چهره سوختگان زندگی می‌خورد و ناله‌ای که به گوش عاشق بی‌نوا می‌رسد، در واقع فریاد و مطالبه‌ای است از دل پرآشوب او.',NULL);
INSERT INTO "verses" VALUES(1940098,2305,3,1,'ناله فریادرَسِ عاشقِ مسکین آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940099,2305,2,0,'مژدگانی بده ای خلوتیِ نافه‌گشای','هوش مصنوعی: ای کسی که در انزوا و آرامش خود معطّر کرده‌ای، خوش خبر باش که آهوی خوشبو و زیبا از دشت ختن به سوی تو آمده است.',NULL);
INSERT INTO "verses" VALUES(1940100,2305,2,1,'که ز صحرایِ خُتَن آهویِ مُشکین آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940101,2305,1,0,'قدحی درکش و سرخوش به تماشا بخرام','هوش مصنوعی: یک جام بردار و با نشاط و خوشحالی به تماشا بپرداز تا ببینی که چقدر زیبایی تو جذاب و دلنشین است.',NULL);
INSERT INTO "verses" VALUES(1940102,2305,1,1,'تا ببینی که نگارت به چه آیین آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940103,2305,0,0,'سَحَرم دولتِ بیدار به بالین آمد','در صبح گاهی، سعادت و نیک بختی به من روی آورد و گفت: بلند شو، چون آن دلبر و یار محبوب و دلنشین نزدیک شده است.',NULL);
INSERT INTO "verses" VALUES(1940104,2305,0,1,'گفت برخیز که آن خسرو شیرین آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940105,2304,7,0,'ز خانقاه به میخانه می‌رود حافظ','حافظ از خانقاه به میخانه می‌رود؛ گویا مستی زهدِ ریایی از سر او پریده است.',NULL);
INSERT INTO "verses" VALUES(1940106,2304,7,1,'مگر ز مستیِ زهدِ ریا به هوش آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940107,2304,6,0,'چه جایِ صحبتِ نامحرم است مجلسِ انس؟','هوش مصنوعی: در اینجا تأکید بر این است که در شرایطی که نباید صحبت‌های نامناسب مطرح شود، بهتر است که از گفتگوهای نا مناسب اجتناب کنیم. همچنین، اشاره به این است که وقتی فردی با ویژگی‌های خاص و مذهبی وارد جمع می‌شود، باید رفتار و گفتار خود را متناسب با آن شرایط تغییر دهیم و محتاطانه عمل کنیم.',NULL);
INSERT INTO "verses" VALUES(1940108,2304,6,1,'سرِ پیاله بپوشان که خرقه‌پوش آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940109,2305,5,1,'که به کامِ دلِ ما آن بشد و این آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940110,2298,3,1,'تابش خورشید و سعی باد و باران را چه شد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940111,2302,4,0,'ای عروسِ هنر از بخت شکایت مَنِما','ای عروس هنر! از بخت گلایه نکن. حجله زیبایی را بیارا؛ زیرا که داماد آمد. [در اینجا، «عروس هنر» و «داماد» به ترتیب یعنی «شعر» و «خریدار شعر»]',NULL);
INSERT INTO "verses" VALUES(1940112,2302,2,1,'موسمِ عاشقی و کار به بنیاد آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940113,2300,1,0,'خاکِ وجود ما را، از آبِ دیده گِل کن','با اشک‌، از خاک وجود ما گِل درست کن؛ (زیرا) زمان آبادنی خانهٔ ویران دل فرا رسیده است. [به یاد داشته باشیم که تا همین 60-50 سال گذشته از گِل و کاهگِل برای ساختن خانه استفاده می‌شد.]',NULL);
INSERT INTO "verses" VALUES(1940114,2300,0,0,'دوش از جنابِ آصف، پیکِ بشارت آمد','دیشب پیام مژده‌ای از جناب آصف رسید که حضرت سلیمان فرمان کامرانی صادر کرده است. [منظور حافظ از آصف (وزیر سلیمان) و سلیمان به ترتیب عبارت است از خواجه قوام‌الدین صاحب عیار (وزیر شاه شجاع) و شاه شجاع.]',NULL);
INSERT INTO "verses" VALUES(1940115,2300,0,1,'کز حضرتِ سلیمان، عشرت اشارت آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940116,2299,7,0,'منزلِ حافظ کنون، بارگهِ پادشاست','خانهٔ حافظ‌ اکنون بارگاه پادشاه است [و عدلالت برقرار شد]؛ دل به دلدار رسید و جان به معشوق پیوست.',NULL);
INSERT INTO "verses" VALUES(1940117,2299,7,1,'دل بَرِ دل‌دار رفت، جان بَرِ جانانه شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940118,2299,6,0,'نرگسِ ساقی بِخوانْد، آیتِ افسون‌گری','چشمِ ساقی، وردِ افسونگری خواند و حلقهٔ ذکرگویی ما تبدیل به مجلس آوازخوانی شد. [در لغتنامهٔ دهخدا، «افسانه» به معنی «ترانه» نیز آمده است]',NULL);
INSERT INTO "verses" VALUES(1940119,2299,6,1,'حلقهٔ اورادِ ما، مجلسِ افسانه شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940120,2299,5,0,'گریهٔ شام و سحر، شُکر که ضایع نگشت','شکر و سپاس که دعا و گریه‌های شام و سحر، نتیجه‌داد و قطره باران ما مروارید ناب گشت.',NULL);
INSERT INTO "verses" VALUES(1940121,2299,5,1,'قطرهٔ بارانِ ما، گوهرِ یک‌دانه شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940122,2299,4,0,'آتشِ رخسارِ گُل، خرمنِ بلبل بسوخت','تاب و گرمی رخسار گل، خرمن بلبل عاشق را سوخت؛ چهره خندان معشوق، آفت جان عاشق شد.',NULL);
INSERT INTO "verses" VALUES(1940123,2299,4,1,'چهرهٔ خندانِ شمع، آفتِ پروانه شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940124,2299,3,0,'مُغْ‌بَچه‌ای می‌گذشت، راهزنِ دین و دل','مغبچه‌ای زیبا می‌گذشت؛ و (زاهد خلوت‌نشین) با دیدن آن آشنا، همه را فراموش کرد.',NULL);
INSERT INTO "verses" VALUES(1940125,2299,3,1,'در پِیِ آن آشنا، از همه بیگانه شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940126,2299,2,0,'شاهدِ عهدِ شباب، آمده بودش به خواب','معشوق دوره جوانی‌اش به‌ خواب او آمده‌بود؛ دوباره در پیری، عاشق و دیوانه شد.',NULL);
INSERT INTO "verses" VALUES(1940127,2299,2,1,'باز به پیرانه‌سر‌، عاشق و دیوانه شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940128,2299,1,0,'صوفیِ مجلس که دی، جام و قدح می‌شکست','صوفیِ ما که تا دیروز جام و قدح را می‌شکست، با نوشیدن یک جرعه می، دوباره خردمند و فرزانه شد.',NULL);
INSERT INTO "verses" VALUES(1940129,2299,1,1,'باز به یک جرعه می، عاقل و فرزانه شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940130,2299,0,0,'زاهدِ خلوت‌نشین، دوش به مِیخانه شد','دیشب، زاهد گوشه نشین به میخانه رفت؛ پیمان شکست و جام می به‌ دست گرفت.',NULL);
INSERT INTO "verses" VALUES(1940131,2299,0,1,'از سرِ پیمان بِرَفت، با سرِ پیمانه شد',NULL,NULL);
INSERT INTO "verses" VALUES(1940132,2298,8,0,'حافظ اسرارِ الهی کَس نمی‌داند، خموش','در بیت پایانی، حافظ خود را خطاب قرار می‌دهد. می‌گوید اسرار الهی را کسی نمی‌داند، پس خاموش باش. این پرسش‌ها پاسخی روشن ندارند. گردش روزگار تابع منطق ساده نیست. شاعر پس از همه پرسش‌ها، به سکوت می‌رسد. سکوتی آگاهانه، نه از سر ناتوانی. او می‌داند که برخی دگرگونی‌ها فراتر از فهم انسانی‌اند. این بیت پایان‌بندی حکیمانه دارد. حافظ از پرسش به پذیرش می‌رسد. نه پذیرش منفعل، بلکه پذیرش واقع‌بینانه. این سکوت، نتیجه اندیشیدن است. در تفسیر کنایی، اسرار الهی می‌تواند پیچیدگی‌های تاریخ و جامعه باشد. حافظ می‌گوید همه چیز توضیح‌پذیر نیست. پرسش بی‌پایان، آرامش نمی‌آورد. گاهی باید پذیرفت که پاسخ در دسترس نیست. این بیت دعوت به تعادل است. تعادل میان پرسش و رها کردن. شاعر پس از نقد، به سکوت می‌رسد. این سکوت پایان گفت‌وگو نیست. بلکه احترام به مرز فهم است. حافظ خودآگاهانه این مرز را می‌پذیرد.',NULL);
INSERT INTO "verses" VALUES(1940133,2298,8,1,'از که می‌پرسی که دورِ روزگار‌ان را چه شد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940134,2298,7,0,'زهره سازی خوش نمی‌سازد، مگر عود‌ش بسوخت؟','حافظ می‌گوید زهره دیگر نوای خوش نمی‌نوازد. شاید سازش سوخته است. سپس می‌پرسد چرا هیچ‌کس ذوق مستی ندارد. می‌گساران کجا رفته‌اند. این بیت از خاموشی شادی سخن می‌گوید. موسیقی و مستی هر دو نماد طرب‌اند. وقتی این‌ها خاموش شوند، فضا سرد می‌شود. شاعر به دلایل احتمالی اشاره می‌کند. شاید ابزار از کار افتاده است. شاید ذوق از میان رفته است. حافظ از نابودی شور می‌نالد. شوری که جان مجلس بود. در تفسیر کنایی، زهره می‌تواند نماد هنرمند باشد. عود ابزار بیان است. سوختن آن یعنی محدودیت یا سرکوب. می‌گساران نماد کسانی‌اند که شجاعت شادی دارند. حافظ می‌گوید این شجاعت از میان رفته است. جامعه دیگر جرأت طرب ندارد. این بیت نقد فضای خفقان‌آور است. فضایی که شادی را خاموش می‌کند. شاعر به پیامدهای آن اشاره می‌کند. وقتی ذوق نباشد، زندگی تهی می‌شود. این پرسش، پرسش از علت افسردگی جمعی است.',NULL);
INSERT INTO "verses" VALUES(1940135,2298,7,1,'کس ندارد ذوقِ مستی، مِی‌گسار‌ان را چه شد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940136,2298,6,0,'صدهزاران گل شکفت و بانگِ مرغی برنخاست','حافظ می‌گوید هزاران گل شکوفا شدند. اما هیچ آواز پرنده‌ای شنیده نشد. این سکوت غیرطبیعی است. گل بدون آواز ناقص است. شاعر می‌پرسد بلبلان چه شدند. هزاران نماد آواز و شور است. این بیت از خاموشی اهل ذوق سخن می‌گوید. زیبایی هست، اما واکنش نیست. طبیعت به کمال نرسیده است. حافظ سکوت را نشانه بحران می‌داند. وقتی پاسخ به زیبایی خاموش شود، چیزی از کار افتاده است. این تصویر بسیار تأثیرگذار است. در تفسیر کنایی، گل نماد فرصت یا زیبایی است. بلبل نماد هنرمند یا انسان حساس است. حافظ می‌گوید زیبایی عرضه شده، اما اهل ذوق خاموش‌اند. این خاموشی می‌تواند از ترس یا بی‌انگیزگی باشد. شاعر از مرگ واکنش انسانی می‌نالد. جامعه‌ای که زیبایی را می‌بیند، اما پاسخ نمی‌دهد. این بیت نقد بی‌تفاوتی فرهنگی است. حافظ از نبود صدا شکایت دارد. صداهایی که باید فضا را زنده کنند. سکوت در اینجا، فقدان حیات است.',NULL);
INSERT INTO "verses" VALUES(1940137,2298,6,1,'عندلیبان را چه پیش آمد؟ هَزاران را چه شد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940138,2298,5,0,'گویِ توفیق و کرامت، در میان افکنده‌اند','حافظ می‌گوید میدان موفقیت و بزرگواری آماده است. گوی در وسط میدان افتاده است. اما هیچ‌کس وارد میدان نمی‌شود. او می‌پرسد سواران کجا رفته‌اند. سواران کسانی بودند که جرأت پیش‌قدم شدن داشتند. اکنون میدان خالی است. این بیت تصویر رکود اراده را نشان می‌دهد. فرصت هست، اما همت نیست. شاعر غیبت جسارت را فریاد می‌زند. حافظ از نبود پیشگامان می‌نالد. کسانی که مسئولیت بپذیرند. این بیت لحنی انتقادی اما اندوهناک دارد. در تفسیر کنایی، گوی توفیق می‌تواند فرصت‌های اجتماعی یا اخلاقی باشد. میدان آماده است، اما داوطلبی نیست. سواران نماد انسان‌های شجاع و مسئول‌اند. حافظ می‌گوید جامعه از پیشگام خالی شده است. همه منتظرند، اما کسی آغاز نمی‌کند. این بیت نقد محافظه‌کاری است. محافظه‌کاری‌ای که فرصت‌ها را می‌سوزاند. شاعر نشان می‌دهد که نبود عمل، به اندازه نبود امکان خطرناک است. این پرسش هنوز هم تازه است. چه شد که کسی پیش نمی‌رود. حافظ این خلأ را برجسته می‌کند.',NULL);
INSERT INTO "verses" VALUES(1940139,2298,5,1,'کس به میدان در نمی‌آید، سوار‌ان را چه شد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940140,2298,4,0,'شهرِ یاران بود و خاکِ مهر‌بانان این دیار','این دیار، شهرِ یاران و سرزمین مهربانان بود. مهربانی، کیْ به پایان رسید؟ چه بر سرِ شهرِ یاران آمد؟',NULL);
INSERT INTO "verses" VALUES(1940141,2298,4,1,'مهربانی کِی سر آمد؟ شهرِ یار‌ان را چه شد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940142,2300,1,1,'ویران‌سرایِ دل را، گاهِ عمارت آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940143,2300,2,0,'این شرحِ بی‌نهایت، کز زلفِ یار گفتند','این شرح بی‌پایان که در بارهٔ زلف یار گفتند، تنها یکی از هزاران حرفی است که به زبان آمد.',NULL);
INSERT INTO "verses" VALUES(1940144,2300,2,1,'حرفی‌ست از هزاران، کاَندر عبارت آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940145,2300,3,0,'عیبم بپوش زنهار، ای خرقهٔ مِی‌آلود','زنهار ای خرقهٔ آلوده به می، عیبم را بپوشان؛ که شخصی کاملا پاکدامن برای دیدار آمده است. [به استناد لغتنامه دهخدا (ستون اول، صفحه 5366، چاپ انتشارات دانشگاه تهران، سال 1377)، «پاک» به معنی «کاملا» یا «تماما» می‌باشد. بررسی اسناد نشان می‌دهد که مفهوم «پاک ویران» (به معنی «کاملا ویران») از سوی فردوسی 7 بار و از سوی ملک‌الشعرا بهار 1 بار به کار رفته است. گذشته از آن، «پاک شوید» (به معنی «کاملا بشوید») در اشعار شیخ محمود شبستری، شاه نعمت‌الله ولی و علیشیر نوایی به کار رفته است. مفهوم «پاک شُست» نیز تا کنون 11 بار در متون دیده شده است. درخور یادآوری است که واژهٔ «پاک» هم اکنون نیز در سراسر ایران به همان معنی «کاملا» به کار می‌رود (نمونه: «پاک دیوانه شده است!»).]',NULL);
INSERT INTO "verses" VALUES(1940146,2302,1,1,'کان تحمّل که تو دیدی همه بر باد آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940147,2302,2,0,'باده صافی شد و مرغانِ چمن مست شدند','باده، رسیده و صاف گشته و فصل نغمه‌سرایی بلبلان فرارسیده‌است؛ فصل عاشقی‌ و کار درست و حسابی رسید.',NULL);
INSERT INTO "verses" VALUES(1940148,2302,0,1,'حالتی رفت که محراب به فریاد آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940149,2302,1,0,'از من اکنون طمعِ صبر و دل و هوش مدار','اکنون از من توقع شکیبایی، خرد و هوش نداشته‌ باش. زیرا همهٔ آن بردباری که تو (پیش از این) دیدی، بر باد رفت!',NULL);
INSERT INTO "verses" VALUES(1940150,2302,0,0,'در نمازم خَمِ ابرویِ تو با یاد آمد','سرِ نماز به‌یاد خم ابروی تو افتادم. چنان به وجد آمدم که صدا در محراب پیچید. [به استناد لغتنامه دهخدا، «حالت» از اصطلاح‌های صوفیان است به معنی «ذوق، وجد، شور».]',NULL);
INSERT INTO "verses" VALUES(1940151,2301,0,0,'عشقِ تو نهالِ حیرت آمد','هوش مصنوعی: عشق تو مانند درختی است که شگفتی و حیرت به وجود می‌آورد، و پیوستن به تو اوج و حداکثر شگفتی است.',NULL);
INSERT INTO "verses" VALUES(1940152,2301,0,1,'وصلِ تو کمالِ حیرت آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940153,2301,1,0,'بس غرقهٔ حالِ وصل کآخر','هوش مصنوعی: بسیار در حال وصالی غرق شدم تا اینکه در پایان، دوباره به حالت حیرت و سردرگمی رسیدم.',NULL);
INSERT INTO "verses" VALUES(1940154,2301,1,1,'هم بر سرِ حالِ حیرت آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940155,2301,2,0,'یک دل بنما که در رَهِ او','هوش مصنوعی: یک دل نشان بده که در راه او، بر چهره‌اش نشانه‌ای از حیرت دیده نشود.',NULL);
INSERT INTO "verses" VALUES(1940156,2301,2,1,'بر چهره نه خالِ حیرت آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940157,2301,3,0,'نه وصل بِمانَد و نه واصل','هوش مصنوعی: نه پیوندی باقی می‌ماند و نه کسی به آنجا می‌رسد، وقتی که فکر حیرت و شگفتی سراسر وجود را فرا بگیرد.',NULL);
INSERT INTO "verses" VALUES(1940158,2301,3,1,'آنجا که خیالِ حیرت آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940159,2301,4,0,'از هر طرفی که گوش کردم','هوش مصنوعی: از هر سو که توجه کردم، صدای پرسش‌های شگفت‌انگیز به گوش رسید.',NULL);
INSERT INTO "verses" VALUES(1940160,2302,3,0,'بویِ بهبود ز اوضاعِ جهان می‌شنوم','از آنچه که در گوشه و کنار می‌گذرد، بوی بهبود می‌شنوم؛ گل، با خود شادی آورد و باد شادمان گشت. [1-اصطلاح زیبای «شنیدن بو» در ادبیات سراسر ایران فرهنگی ثبت شده و هم اکنون نیز، به طور گسترده به کار می‌رود. 2-به استناد لغتنامه دهخدا، «آمدن» به معنی «شدن» و «گردیدن» نیز می‌باشد.]',NULL);
INSERT INTO "verses" VALUES(1940161,2301,4,1,'آوازِ سؤالِ حیرت آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940162,2301,5,0,'شد مُنهَزِم از کمالِ عزّت','هوش مصنوعی: کسی که به اوج عزت و بزرگ‌منشی دست یافته است به شدت تحت تأثیر شگفتی و عظمت قرار می‌گیرد.',NULL);
INSERT INTO "verses" VALUES(1940163,2301,5,1,'آن را که جلالِ حیرت آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940164,2301,6,0,'سر تا قدمِ وجودِ حافظ','هوش مصنوعی: وجود حافظ در عشق، به اندازه‌ای شگفت‌انگیز و حیرت‌انگیز است که تمام وجودش را در بر می‌گیرد و مثل نهالی پر از عشق، حیرت را به نمایش می‌گذارد.',NULL);
INSERT INTO "verses" VALUES(1940165,2300,8,0,'دریاست مجلسِ او، دَریاب وقت و دُر یاب','محفل او دریاست؛ زمان را غنیمت بشمار و از آن بهره برگیر . ای زیان دیده! زمان بده-بِستان فرا رسیده است.',NULL);
INSERT INTO "verses" VALUES(1940166,2300,8,1,'هان ای زیان‌رسیده وقتِ تجارت آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940167,2300,7,0,'آلوده‌ای تو حافظ، فیضی ز شاه درخواه','حافظ! تو آلوده‌ای، از شاه شجاع لطفی بخواه. زیرا این عنصر بخشندگی، برای پاکی آمده است.',NULL);
INSERT INTO "verses" VALUES(1940168,2300,7,1,'کآن عنصرِ سَماحت، بهرِ طهارت آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940169,2300,6,0,'از چشمِ شوخش ای دل! ایمانِ خود نگه دار','هوش مصنوعی: به خاطر زیبایی و جذابیت چشمان او، ای دل، ایمان خود را حفظ کن، زیرا آن جذبه و سحری که در کمان او نهفته است، می‌تواند همه چیز را ببرد و تو را نیز درگیر کند.',NULL);
INSERT INTO "verses" VALUES(1940170,2300,6,1,'کآن جادویِ کمانکش، بر عزمِ غارت آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940171,2300,5,0,'بر تختِ جم که تاجش، معراجِ آسمان است','هوش مصنوعی: در تخت شاهانه‌ای که تاج آن نماد بلندی آسمان است، توجه کن که موری (مورچه‌ای) با آن کوچکی و حقارتش به آنجا آمده است.',NULL);
INSERT INTO "verses" VALUES(1940172,2300,5,1,'همّت نگر که موری، با آن حقارت آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940173,2300,4,0,'امروز جایِ هر کس، پیدا شود ز خوبان','هوش مصنوعی: امروز هر کس در جایگاه خود مشخص می‌شود، چون آن معشوق دلربا که مجلس را روشن می‌کند، در مقام رهبری و اداره امور آمده است.',NULL);
INSERT INTO "verses" VALUES(1940174,2300,4,1,'کآن ماهِ مجلس‌افروز، اندر صدارت آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940175,2300,3,1,'کآن پاکْ پاک‌دامن، بهرِ زیارت آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940176,2301,6,1,'در عشق، نهالِ حیرت آمد',NULL,NULL);
INSERT INTO "verses" VALUES(1940178,78326,1,0,'دانى که ز روشناس عشق است آنکو','آیا می‌دانی که کسی‌که جانش آزرده و ملامت‌دیده است، شهره و نامدار عشق است. (روشناس: معروف و مشهور)',NULL);
INSERT INTO "verses" VALUES(1940179,33186,0,0,'ای در چمن خوبی رویت چو گل خودرو','هوش مصنوعی: ای زیبای چمنی، چهره‌ات مانند گلی وحشی است و موهایت همچون گردنبند خوشبوی چینی است که به زیبایی تاب خورده‌اند.',NULL);
INSERT INTO "verses" VALUES(1940180,33186,0,1,'چین شکن زلفت چون نافهٔ چین خوش بو',NULL,NULL);
INSERT INTO "verses" VALUES(1940181,33185,6,1,'سالخورده میی امروز به از صد پیرم',NULL,NULL);
INSERT INTO "verses" VALUES(1940182,33185,6,0,'خلق گویند که حافظ سخن پیر نیوش','هوش مصنوعی: مردم می‌گویند که حافظ از بزرگترها سخن می‌گوید، اما من امروز می‌فهمم که یک جرعه از می بهتر از صد سال نصیحت از سالخوردگان است.',NULL);
INSERT INTO "verses" VALUES(1940183,33185,5,1,'آه اگر خلق شوند آگه از این تزویرم ',NULL,NULL);
INSERT INTO "verses" VALUES(1940184,33185,5,0,'می به زیر کش و سجادهٔ تقوی بر دوش','هوش مصنوعی: شراب را بنوش و در عین حال ظاهر تقوا و دیانت را حفظ کن. ای کاش مردم از این ظاهرسازی من باخبر شوند!',NULL);
INSERT INTO "verses" VALUES(1940185,33185,4,1,'تا نهم در قدم او سر و پیشش میرم ',NULL,NULL);
INSERT INTO "verses" VALUES(1940186,33185,4,0,'آن که بر خاک در میکده جان داد کجاست','هوش مصنوعی: کسی که جانش را در میکده و در برابر عشق فدای می‌کند، کجاست تا من سرم را در برابر او بگذارم و به او احترام کنم؟',NULL);
INSERT INTO "verses" VALUES(1940187,33185,3,1,'من نه آنم که دگر پند کسی بپذیرم ',NULL,NULL);
INSERT INTO "verses" VALUES(1940188,33186,1,0,'ماه است رخت یا روز؟ مشک است خطت یا شب؟','هوش مصنوعی: آیا چهره‌ات مانند ماه درخشان است یا به زیبایی روز؟ خط و نشان‌هایت آیا همانند مشک خوشبو هستند یا به تیرگی شب؟ آیا پوستت مثل نقره است یا شبیه عاج؟ آیا دلت مانند سنگ سخت است یا نرم و لطیف؟',NULL);
INSERT INTO "verses" VALUES(1940189,33185,3,0,'پند پیرانه دهد واعظ شهرم لیکن','هوش مصنوعی: واعظ شهرم نصیحت‌های بزرگان را می‌کند، اما من کسی نیستم که حرف‌های دیگران را بپذیرم.',NULL);
INSERT INTO "verses" VALUES(1940190,33185,2,0,'من به خلوت ننشینم پس از این، ور به مثل','هوش مصنوعی: من دیگر در تنهایی نمی‌نشینم، حتی اگر مثل یک زاهد در صومعه زنجیر به پا کنم.',NULL);
INSERT INTO "verses" VALUES(1940191,33185,1,1,'بس خجالت که به روی آمد ازین تقصیرم ',NULL,NULL);
INSERT INTO "verses" VALUES(1940192,33185,1,0,'چند روزیست که دورم ز رخ ساقی و جام','هوش مصنوعی: مدتی است که از چهره‌ی ساقی و جام دور هستم و از این که به خاطر اشتباهاتم خجالت زده‌ام، دلم نمی‌آید به او نگاه کنم.',NULL);
INSERT INTO "verses" VALUES(1940193,33185,0,1,'که دهم حاصل سی‌روزه و ساغر گیرم ',NULL,NULL);
INSERT INTO "verses" VALUES(1940194,33185,0,0,'روز عید است و من امروز در آن تدبیرم','هوش مصنوعی: امروز روز عید است و من تصمیم دارم که نتیجه‌ی سی روز تلاش و عبادت خود را به دست بیاورم و از خوشی‌ها بهره‌مند شوم.',NULL);
INSERT INTO "verses" VALUES(1940195,33184,8,1,'ورنه دعوی نیست غیر از قال و قیل',NULL,NULL);
INSERT INTO "verses" VALUES(1940196,33184,8,0,'حافظا گر معنیی داری بیار','هوش مصنوعی: اگر حافظ جان، حقیقتی در دلت هست، آن را برملا کن؛ وگرنه تنها سخن گفتن و تظاهرات بی‌محتوا هیچ ارزشی ندارد.',NULL);
INSERT INTO "verses" VALUES(1940197,33184,7,1,'یا فرو بر جامهٔ تقوی به نیل ',NULL,NULL);
INSERT INTO "verses" VALUES(1940198,33184,7,0,'یا مکش بر چهره نیل عاشقی','هوش مصنوعی: این بیت به مفهوم این است که یا از عشق و شوق خود به طور واضح و آشکار بگو، یا اینکه در ظاهر خود، به گونه‌ای رفتار کن که نشان‌دهندهٔ تقوا و دیانت باشد. در واقع، دو راه برای ابراز احساسات وجود دارد: یکی ابراز آزادانه و بی‌پرده، و دیگری حفظ وقار و دیانت در رفتار.',NULL);
INSERT INTO "verses" VALUES(1940199,33185,2,1,'زاهد صومعه بر پای نهد زنجیرم ',NULL,NULL);
INSERT INTO "verses" VALUES(1940200,33186,1,1,'سیم است برت یا عاج؟ سنگ است دلت یا رو؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940201,33186,2,0,'لعلت به در دندان بشکست لب پسته','هوش مصنوعی: دندان تو مانند یاقوتی دلنشین است که لبانم را می‌شکند و زلفت به شکل خمیده‌ای در میدان بازی قلبم را به تسخیر درآورده است. دل من چه گفتنی دارد!',NULL);
INSERT INTO "verses" VALUES(1940202,33186,2,1,'زلفت به خم چوگان بربود دلم چون گو',NULL,NULL);
INSERT INTO "verses" VALUES(1940203,33187,5,0,'تا کی کبوتر دل باشد چو مرغ بسمل','هوش مصنوعی: تا چه زمانی دل مثل کبوتر خواهد بود، همچنان که مرغی زخمی از تیر زخم تو در خاک و خون غوطه‌ور است؟',NULL);
INSERT INTO "verses" VALUES(1940204,33187,4,1,'گاه این کمین گشاده گاه آن کمان کشیده',NULL,NULL);
INSERT INTO "verses" VALUES(1940205,33187,4,0,'بر قصد خون عشاق ابرو و چشم شوخش','هوش مصنوعی: چشمان و ابروی معشوق دامی برای عاشقان است که گاهی نمایان و آماده صیدند و گاهی در حال کشیدن تیر.',NULL);
INSERT INTO "verses" VALUES(1940206,33187,3,1,'هر دم و ان یکادی ز اخلاص بردمیده',NULL,NULL);
INSERT INTO "verses" VALUES(1940207,33187,3,0,'بر چهره بخت نیکت تعویذ چشم زخم است','هوش مصنوعی: شما به لطف بخت خوبتان همیشه زیر نظر آسیب‌های احتمالی و حسادت دیگران هستید و این موضوع باعث می‌شود که شما آرامش و خوشبختی خود را حفظ کنید.',NULL);
INSERT INTO "verses" VALUES(1940208,33187,2,1,'سجاده ترک کرده پیمانه در کشیده',NULL,NULL);
INSERT INTO "verses" VALUES(1940209,33187,2,0,'هر زاهدی که دیده یاقوت جان فزایش','هوش مصنوعی: هر زاهدی که زیبایی و ارزش روح را درک کرده، از دنیا و مادیات فاصله گرفته و به سویی دیگر رفته است تا از خوشی‌های زندگی بهره‌مند شود.',NULL);
INSERT INTO "verses" VALUES(1940210,33187,1,1,'گیتی نشان نداده ایزد نیافریده',NULL,NULL);
INSERT INTO "verses" VALUES(1940211,33187,1,0,'همچون تو نازنینی سر تا قدم لطافت','هوش مصنوعی: تو همچون زیباترین و لطیف‌ترین موجودات هستی که خداوند مانند تو را نیافریده است.',NULL);
INSERT INTO "verses" VALUES(1940212,33187,0,1,'خوش‌تر ز چشم مستت چشم جهان ندیده',NULL,NULL);
INSERT INTO "verses" VALUES(1940213,33187,0,0,'ای از فروغ رویت روشن چراغ دیده','هوش مصنوعی: ای کسی که نور چهره‌ات روشنی‌بخش چشمان من است، چشمان دیوانه‌ات زیباتر از چشمان هر کسی است که در این دنیا دیده‌ام.',NULL);
INSERT INTO "verses" VALUES(1940214,33186,3,0,'آن رایحهٔ زلف است یا لخلخهٔ عنبر؟','هوش مصنوعی: آیا این عطر ناشی از زلف اوست یا بو و عطری که از عطر عنبر به مشام می‌رسد؟ یا این بوی خوش حاصل از دلربایی‌های او در باغچه زیباییش است؟',NULL);
INSERT INTO "verses" VALUES(1940215,33186,3,1,'یا غالیه می‌ساید در باغچه حسن او؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940216,33186,4,0,'گفتی سخن خود را با یار بباید گفت','هوش مصنوعی: گفتی باید با کسی که دوستش داری حرف بزنی، ای کاش می‌توانستی با او صحبت کنی.',NULL);
INSERT INTO "verses" VALUES(1940217,33186,4,1,'ای کاش توانستی گفتن سخنی با او',NULL,NULL);
INSERT INTO "verses" VALUES(1940218,33186,5,0,'بدگوی تو آن باشد کز یار کند منعت','هوش مصنوعی: اگر کسی درباره‌ی تو بد بگوید، آن زمانی است که یار تو مانع شود. پس اگر یار تو فردی خوب و نیکو باشد، به سخنان بدگویان توجه نکن.',NULL);
INSERT INTO "verses" VALUES(1940219,33186,5,1,'گر یار نکو باشد مشنو سخن بدگو',NULL,NULL);
INSERT INTO "verses" VALUES(1940220,33186,6,0,'با ما به از این می‌باش تا راز نگردد فاش','هوش مصنوعی: با ما بمان و از این راز نگهداری کن تا آشکار نشود؛ اگر در کنار دلباختگان نیکو باشی، چیز بدی نخواهد بود.',NULL);
INSERT INTO "verses" VALUES(1940221,33186,6,1,'نبود بد اگر باشی با دلشدگان نیکو',NULL,NULL);
INSERT INTO "verses" VALUES(1940222,33186,7,0,'استاد سخن سعدیست پیش همه کس اما','هوش مصنوعی: سعدی به عنوان استاد زبانی شناخته‌ شده است و در بین همگان محبوبیت دارد، اما شعر حافظ هم سبک خاص و زیبایی دارد که به خواجو نسبت داده می‌شود.',NULL);
INSERT INTO "verses" VALUES(1940223,33186,7,1,'دارد سخن حافظ طرز سخن خواجو',NULL,NULL);
INSERT INTO "verses" VALUES(1940224,33184,6,1,'یا مده هندوستان را یاد پیل ',NULL,NULL);
INSERT INTO "verses" VALUES(1940225,33187,5,1,'از زخم ناوک تو در خاک و خون تپیده',NULL,NULL);
INSERT INTO "verses" VALUES(1940226,33184,6,0,'یا رسوم پیلبانی یاد گیر','هوش مصنوعی: یا باید فنون پَیلبانی را یاد بگیری، یا هندوستان را به یاد نیاور.',NULL);
INSERT INTO "verses" VALUES(1940227,33184,5,0,'یا بنه بر خود که مقصد گم کنی','هوش مصنوعی: یا بر خودت مسلط باش و هدف را فراموش نکن، یا پاهایت را بی‌دلیل در این مسیر نگذار.',NULL);
INSERT INTO "verses" VALUES(1940228,33183,0,0,'به جد و جهد چو کاری نمی‌رود از پیش','هوش مصنوعی: اگر با تلاش و کوشش هم کاری پیش نمی‌رود، پس بهتر است به خداوند بسپاریم و به کارهای خود ادامه دهیم.',NULL);
INSERT INTO "verses" VALUES(1940229,33182,8,1,'دریاب نقد وقت و ز چون و چرا مپرس',NULL,NULL);
INSERT INTO "verses" VALUES(1940230,33182,8,0,'حافظ رسید موسم گل معرفت مگوی','هوش مصنوعی: حافظ می‌گوید: اکنون زمانی است که باید از زیبایی‌ها و نعمت‌های شناخت بهره‌برداری کنیم. در این لحظه مهم، به جای نگرانی درباره جزئیات یا مسائل دیگر، بهتر است به ارزش موقعیت کنونی توجه کنیم و از آن بهره‌مند شویم.',NULL);
INSERT INTO "verses" VALUES(1940231,33182,7,1,'از ما به جز حکایت مهر و وفا مپرس ',NULL,NULL);
INSERT INTO "verses" VALUES(1940232,33182,7,0,'ما قصهٔ سکندر و دارا نخوانده‌ایم','هوش مصنوعی: ما داستان‌های تاریخی و بزرگ مانند سکندر و دارا را نمی‌دانیم، پس از ما درباره‌ی عشق و وفاداری چیزی نپرس.',NULL);
INSERT INTO "verses" VALUES(1940233,33182,6,1,'ای دل به درد خو کن و نام دوا مپرس ',NULL,NULL);
INSERT INTO "verses" VALUES(1940234,33182,6,0,'در دفتر طبیب خرد باب عشق نیست','هوش مصنوعی: ای دل، در دفتر طبیب دانا، موضوع عشق وجود ندارد. پس به درد عشقت عادت کن و از درمان آن سوال نپرس.',NULL);
INSERT INTO "verses" VALUES(1940235,33182,5,1,'یعنی ز مفلسان سخن کیمیا مپرس ',NULL,NULL);
INSERT INTO "verses" VALUES(1940236,33182,5,0,'از دلق‌پوش صومعه نقد طلب مجوی','هوش مصنوعی: از کسی که فقط در ظاهر زهد و تقوی را نمایش می‌دهد، چیزی نخواهی یافت. پس از افراد بی‌نوا و فقیری که به نظر می‌رسند، در مورد معجزات و معانی عمیق سوال نکن.',NULL);
INSERT INTO "verses" VALUES(1940237,33183,0,1,'به کردگار رها کرده به مصالح خویش',NULL,NULL);
INSERT INTO "verses" VALUES(1940238,33182,4,1,'آن کس که با تو گفت که درویش را مپرس ',NULL,NULL);
INSERT INTO "verses" VALUES(1940239,33182,3,1,'آنکس که با تو گفت که درویش را مپرس',NULL,NULL);
INSERT INTO "verses" VALUES(1940240,33182,3,0,'من ذوق سوز عشق تو دانم نه مدعی','هوش مصنوعی: من احساس شوق و سوز عشق تو را خوب می‌دانم؛ نه اینکه از کسی بپرسی، مثل این که از شمع بخواهی داستانش را تعریف کند یا از باد صبا چیزی بپرسی.',NULL);
INSERT INTO "verses" VALUES(1940241,33182,2,1,'از شمع پرس قصه ز باد هوا مپرس ',NULL,NULL);
INSERT INTO "verses" VALUES(1940242,33182,2,0,'خواهی که روشنت شود اسرار درد عشق','هوش مصنوعی: اگر می‌خواهی از حال و هوای پُرزرد ما باخبر شوی، به دانه‌ای که در باد می‌رقصد نگاه کن و از وزش باد چیزی نپرس.',NULL);
INSERT INTO "verses" VALUES(1940243,33182,1,1,'جرم نکرده عفو کن و ماجرا مپرس ',NULL,NULL);
INSERT INTO "verses" VALUES(1940244,33182,1,0,'ز آنجا که لطف شامل و خلق کریم توست','هوش مصنوعی: به خاطر مهربانی و کرامت تو، که اینها شامل حال ما شده است، ما را ببخش و از ماجرای خطاهایمان نپرس.',NULL);
INSERT INTO "verses" VALUES(1940245,33182,0,1,'بیگانه گرد و قصهٔ هیچ آشنا مپرس ',NULL,NULL);
INSERT INTO "verses" VALUES(1940246,33182,0,0,'جانا تو را که گفت که احوال ما مپرس','هوش مصنوعی: عزیز من، کیست که به تو بگوید احوال ما را نپرس؛ به بیگانگان بپیوند و از داستان هیچ آشنایی چیزی نپرس.',NULL);
INSERT INTO "verses" VALUES(1940247,33181,8,1,'تو رخ به خاک نه ای حافظ و بر آر نماز',NULL,NULL);
INSERT INTO "verses" VALUES(1940248,33182,4,0,'هیچ آگهی ز عالم درویشیش نبود','هوش مصنوعی: هیچ اطلاعاتی درباره زندگی درویش وجود نداشت، آن کسی که به تو گفت در مورد درویش سوال نکن، خودش از حال او چیزی نمی‌داند.',NULL);
INSERT INTO "verses" VALUES(1940249,33183,1,0,'به پادشاهی عالم فرو نیارد سر','هوش مصنوعی: اگر درویش به راز قناعت پی ببرد، حتی اگر سلطنت جهان را هم به او بدهند، سرش را پایین نخواهد آورد.',NULL);
INSERT INTO "verses" VALUES(1940250,33183,1,1,'اگر ز سِرِّ قناعت خبر شود درویش',NULL,NULL);
INSERT INTO "verses" VALUES(1940251,33183,2,0,'بنوش باده که قَسّام صُنع قسمت کرد','هوش مصنوعی: بنوش باده که خداوند قسمت، در آفرینش انواع نوشیدنی‌ها را برای انسان مقرر کرده است.',NULL);
INSERT INTO "verses" VALUES(1940252,33184,4,1,'ور نه در آتش گذر کن چون خلیل ',NULL,NULL);
INSERT INTO "verses" VALUES(1940253,33184,4,0,'آتش روی بتان در خود مزن','هوش مصنوعی: در این بیت، شاعر به کسی هشدار می‌دهد که به معشوق خود (بتان) آسیبی نرساند وگرنه باید عواقب سختی را که شبیه آزمون‌های سختی است تحمل کند، مانند ابراهیم خلیل که در آتش امتحان شد. به عبارت دیگر، بهتر است به جای برانگیختن خشم معشوق، با آرامش و احتیاط رفتار کند تا از مشکلات دوری کند.',NULL);
INSERT INTO "verses" VALUES(1940254,33184,3,1,'ضلنی فی العشق من یهدی السبیل ',NULL,NULL);
INSERT INTO "verses" VALUES(1940255,33184,3,0,'اختیاری نیست بدنامی من','هوش مصنوعی: من در عشق گمراه شده‌ام و به همین خاطر نمی‌توانم در برابر بدنامی‌ام گزینه‌ای انتخاب کنم یا بر روی آن تأثیر بگذارم.',NULL);
INSERT INTO "verses" VALUES(1940256,33184,2,1,'راحتی فی الراح لا فی السلسبیل ',NULL,NULL);
INSERT INTO "verses" VALUES(1940257,33184,2,0,'بی می و مطرب به فردوسم مخوان','هوش مصنوعی: این ابیات به این معناست که بدون شراب و نوازنده، مرا به بهشت نخوانید؛ زیرا آرامش و راحتی را در لذت‌های دنیوی نمی‌یابم.',NULL);
INSERT INTO "verses" VALUES(1940258,33184,1,1,'آن که کشتی راند بر خون قتیل ',NULL,NULL);
INSERT INTO "verses" VALUES(1940259,33184,1,0,'موج اشک ما کی آرد در حساب','هوش مصنوعی: اشک‌های ما هیچ تاثیری بر فردی که بر خون شهیدان کشتی راند، ندارد و او به فکر غم ما نیست.',NULL);
INSERT INTO "verses" VALUES(1940260,33184,0,1,'آب چشم اندر رهش کردم سبیل ',NULL,NULL);
INSERT INTO "verses" VALUES(1940261,33184,0,0,'رهروان را عشق بس باشد دلیل','هوش مصنوعی: عاشقان برای ادامه مسیر زندگی خود به عشق احتیاج دارند و اشک و احساساتشان نشان‌دهنده عواطف و تعهدشان به این راه است.',NULL);
INSERT INTO "verses" VALUES(1940262,33183,7,1,'به جان بُوَد خطرم زین دل محال‌اندیش',NULL,NULL);
INSERT INTO "verses" VALUES(1940263,33183,7,0,'دهان نیک تو دلخواه جان حافظ شد','هوش مصنوعی: لب‌های نیکو و دلنشین تو برای روح حافظ دلپسند است، اما جانم به خاطر داشتن این دل پر از خیالات پوچ در خطر است.',NULL);
INSERT INTO "verses" VALUES(1940264,33183,6,1,'که نور حُسن تو بود از اساس عالم پیش',NULL,NULL);
INSERT INTO "verses" VALUES(1940265,33183,6,0,'به دلربائی اگر خود سرآمدی چه عجب','هوش مصنوعی: اگر تو خود سبب جلب توجه دیگران باشی، جای شگفتی نیست؛ زیرا زیبایی و نوری که در وجود توست، از ابتدا باعث روشنایی و جذابیت این جهان بوده است.',NULL);
INSERT INTO "verses" VALUES(1940266,33183,5,1,'قدح بیار و بنه مرهمی بر این دل ریش',NULL,NULL);
INSERT INTO "verses" VALUES(1940267,33183,5,0,'ریای زاهد سالوس جان من فرسود','هوش مصنوعی: زهد و ریاکاری زاهد و عابد، روح و جان مرا پژمرده کرده است. پس بی‌زحمت، جامی بیاور و دارویی برای این دل زخم‌خورده‌ام بگذار.',NULL);
INSERT INTO "verses" VALUES(1940268,33183,4,1,'زهی طریقت و ملت زهی شریعت و کیش',NULL,NULL);
INSERT INTO "verses" VALUES(1940269,33183,4,0,'ریا حلال شمارند و جام باده حرام','هوش مصنوعی: عده‌ای ریا را مجاز می‌دانند و نوشیدنی الکلی را ممنوع. ای پدیده‌های مذهبی و دینی، چقدر عجیب و متناقض هستند!',NULL);
INSERT INTO "verses" VALUES(1940270,33183,3,1,'مشو بسان ترازو تو در پی کم و بیش',NULL,NULL);
INSERT INTO "verses" VALUES(1940271,33183,3,0,'ز سنگ تفرقه خواهی که منحنی نشوی','هوش مصنوعی: اگر می‌خواهی از سنگ تفرقه دور بمانی و تحت تاثیر آن قرار نگیری، مانند ترازویی نباش که همیشه در پی اندازه‌گیری کم و زیاد است.',NULL);
INSERT INTO "verses" VALUES(1940272,33183,2,1,'در آفرینش از انواعِ نوشدارو نیش',NULL,NULL);
INSERT INTO "verses" VALUES(1940273,33184,5,1,'یا منه پای اندرین ره بی‌دلیل ',NULL,NULL);
INSERT INTO "verses" VALUES(1940274,33181,8,0,'غبار خاطر ما چشم خصم کور کند','دل‌آزردگی ما، چشم خصم را کور کند، تو رخ بر خاک نه ای حافظ و بر آر نماز.',NULL);
INSERT INTO "verses" VALUES(1940275,33187,6,0,'از سوز سینه هر دم دودم به سر درآید','هوش مصنوعی: از دل شکسته‌ام هر لحظه دودی به آسمان بلند می‌شود. من مانند عود، چندین بار در آتش سوزانده می‌شوم.',NULL);
INSERT INTO "verses" VALUES(1940276,33187,7,0,'گر زآنک رام گردد بخت رمیده با من','هوش مصنوعی: اگر خوش‌بختی که از من دور شده، دوباره به من روی آورد، من نیز از همان جا که دل‌تنگم، خواسته‌هایم را برآورده می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1940277,77000,0,0,'من ار زآن که گردم به مستی هلاک','هوش مصنوعی: اگر به خاطر مستی و خوشی از پای در آیم، به روش و سیرت مستان خودم را به خاک می‌زنم و از زندگی جدا می‌شوم.',NULL);
INSERT INTO "verses" VALUES(1940278,77000,0,1,'به آیین مستان بریدم به خاک',NULL,NULL);
INSERT INTO "verses" VALUES(1940279,71237,7,1,'به راحت دل و جان کوش در صباح و رواح',NULL,NULL);
INSERT INTO "verses" VALUES(1940280,71237,7,0,'زمان شاه شجاع است و دور حکمت و شرع','هوش مصنوعی: در زمان شاه شجاع، دور از حکمت و قوانین شرعی، در آسایش خاطر و روح، در صبح و عصر تلاش کن.',NULL);
INSERT INTO "verses" VALUES(1940281,71237,6,1,'که بشکفد گل بختت ز جانبِ فتّاح',NULL,NULL);
INSERT INTO "verses" VALUES(1940282,71237,6,0,'به بوی وصل چو حافظ شبی به روز آور','هوش مصنوعی: در زمان وصال، مانند حافظ، شب را به روز مبدل کن تا بخت تو مانند گلی که شکوفا می‌شود، از جانب کسی خوش‌قسمت بگشاید.',NULL);
INSERT INTO "verses" VALUES(1940283,71237,5,1,'که کس درت نگشاید چو گم کنی مفتاح',NULL,NULL);
INSERT INTO "verses" VALUES(1940284,71237,5,0,'دلا تو غافلی از کار خویش و می‌ترسم','هوش مصنوعی: ای دل، تو از کارهای خود غافلی و می‌ترسم که اگر راهی را گم کنی، هیچ‌کس به تو کمک نکند و در را به رویت نگیرد.',NULL);
INSERT INTO "verses" VALUES(1940285,71237,4,1,'که بانگِ شام ندانم ز فالق الاصباح',NULL,NULL);
INSERT INTO "verses" VALUES(1940286,77000,1,0,'به تابوتی از چوب تاکم کنید','هوش مصنوعی: مرا در تابوت چوبی قرار دهید و به سمت مکان‌های فساد و نابودی ببرید.',NULL);
INSERT INTO "verses" VALUES(1940287,71237,4,0,'کدام طاعتِ شایسته آید از من مست','هوش مصنوعی: کدام عبادت و فرمانبرداری می‌تواند از من دیوانه سر بزند، در حالی که من حتی صدای شب را از صبح متفاوت نمی‌توانم تشخیص دهم.',NULL);
INSERT INTO "verses" VALUES(1940288,71237,3,0,'بیار باده که روزش به خیر خواهد بود','هوش مصنوعی: باده بیاور که روز خوبی خواهد داشت، هر کسی که صبح زود لیوان شراب بنوشد و صبح را روشن کند.',NULL);
INSERT INTO "verses" VALUES(1940289,71237,2,1,'مقابلِ شبِ‌قدر است و روزِ اِستِفتاح',NULL,NULL);
INSERT INTO "verses" VALUES(1940290,71237,2,0,'عزیز دار زمانِ وصال را، کـ‌آن دَم','هوش مصنوعی: دوست داشته باش زمانِ دیدار را، چرا که آن لحظه برابر با شبِ قدر و روزِ آغازین و با ارزش است.',NULL);
INSERT INTO "verses" VALUES(1940291,71237,1,1,'به پادشه بِنه ای نور دیده کوی فلاح',NULL,NULL);
INSERT INTO "verses" VALUES(1940292,71237,1,0,'نزاع بر سر دنیای دون گدا نکند','هوش مصنوعی: کسی که در پی موفقیت‌های بزرگ و دنیای بهتر است، می‌داند که دعوا و جدل بر سر چیزهای کم‌ارزش و ناچیز، نه تنها ارزش ندارد بلکه او را از اهداف اصلی‌اش دور می‌کند. تلاش برای رسیدن به بالاترین قله‌ها و فلاح واقعی، نیازمند تمرکز و دوری از حواشی و مشاجرات بی‌هدف است.',NULL);
INSERT INTO "verses" VALUES(1940293,71237,0,1,'که ماه اَمن و اَمان است و سال صلح و صلاح',NULL,NULL);
INSERT INTO "verses" VALUES(1940294,71237,0,0,'ببین هلالِ محرّم بخواه ساغر راح','هوش مصنوعی: هلال ماه محرم را ببین و از آن داشته‌های خوش را طلب کن، زیرا این ماه نشانه‌ امنیت و آرامش است و زمان صلح و رفاه به حساب می‌آید.',NULL);
INSERT INTO "verses" VALUES(1940295,68778,6,1,'چون عاشق سرگردان کز دوست جدا افتد',NULL,NULL);
INSERT INTO "verses" VALUES(1940296,68778,6,0,'احوال دل حافظ از دست غم هجران','هوش مصنوعی: حافظ در این بیت به وضع دل خود اشاره می‌کند و می‌گوید که او مانند عاشق سرگشته‌ای است که به خاطر درد جدایی از معشوقش، در رنج و غم به سر می‌برد. احساسات و اندوه او ناشی از دوری از کسی است که به او محبت و عشق ورزیده است.',NULL);
INSERT INTO "verses" VALUES(1940297,71237,3,1,'هر آن که جام صبوحی نهد چراغ صباح',NULL,NULL);
INSERT INTO "verses" VALUES(1940298,77000,1,1,'به راه خرابات خاکم کنید',NULL,NULL);
INSERT INTO "verses" VALUES(1940299,77000,2,0,'به آب خرابات غسلم دهید','هوش مصنوعی: مرا به آب خمره‌های میخانه بشویید و سپس بر دوش من مستی را بنشانید.',NULL);
INSERT INTO "verses" VALUES(1940300,77000,2,1,'پس آنگاه بر دوش مستم نهید',NULL,NULL);
INSERT INTO "verses" VALUES(1940301,77986,0,0,'ای ز شرم عارضت گل کرده خوی','هوش مصنوعی: ای زیبایی چهره‌ات باعث شده است که گل‌ها به حیای تو غبطه بخورند و عرق بر پیشانی حقیقت جام شراب نمایان شود.',NULL);
INSERT INTO "verses" VALUES(1940302,77986,0,1,'بر عرق پیش عقیقت جام می',NULL,NULL);
INSERT INTO "verses" VALUES(1940303,77986,1,0,'ژاله بر لاله است یا بر گل گلاب','هوش مصنوعی: باران شبنم بر روی گل‌ها نشسته یا بر گل سرخ یا بر گل گلاب، یا حتی بر روی آتش، آب می‌ریزد.',NULL);
INSERT INTO "verses" VALUES(1940304,77986,1,1,'یا بر آتش آب یا بر روت خوی',NULL,NULL);
INSERT INTO "verses" VALUES(1940305,77986,2,0,'میشد از چشم آن کمان ابرو و دل','هوش مصنوعی: شخصی می‌تواند به خاطر زیبایی و جذابیت چشمان کسی، به شدت تحت تأثیر قرار گرفته و در پی او گم شود. او به گونه‌ای دل باخته می‌شود که نمی‌تواند راهش را پیدا کند و فقط در تلاش است تا به آن محبوب نزدیک‌تر شود.',NULL);
INSERT INTO "verses" VALUES(1940306,77986,2,1,'از پی اش می رفت و گم می کرد پی',NULL,NULL);
INSERT INTO "verses" VALUES(1940307,77986,3,0,'امشب از زلفت نخواهم داشت دست','هوش مصنوعی: امشب نمی‌خواهم از زلف تو دست بزنم، ای موذن، صدا بزن که وقت نماز است.',NULL);
INSERT INTO "verses" VALUES(1940308,77986,3,1,'رو موذن بانگ می زن گو که حی',NULL,NULL);
INSERT INTO "verses" VALUES(1940309,77986,4,0,'چون بنی عامر بسی مجنون شوند','هوش مصنوعی: وقتی که افراد بنی عامر دچار جنون و دیوانگی شوند، اگر یک شب لیلی از خانه بیرون بیاید...',NULL);
INSERT INTO "verses" VALUES(1940310,77986,4,1,'گر برون آید شبی لیلی زحی',NULL,NULL);
INSERT INTO "verses" VALUES(1940311,77986,5,0,'نی دمی لب بر لب مطرب نهاد','هوش مصنوعی: یک نی به نوازنده نزدیک شد و به او گفت که چنگ را زیر ناخن خود پنهان کرده است.',NULL);
INSERT INTO "verses" VALUES(1940312,77986,5,1,'چنگ را در زیر ناخن کرد پی',NULL,NULL);
INSERT INTO "verses" VALUES(1940313,77986,6,0,'چنگ را بر دست مطرب نه دمی','هوش مصنوعی: چنگ را به دست نوازنده بسپار و لحظه‌ای دستش را بزن، تا صدای دلنشینی ایجاد کند و او را وادار به نواختن کن.',NULL);
INSERT INTO "verses" VALUES(1940314,77986,6,1,'گو رگش بخراش و بخروشش ز پی',NULL,NULL);
INSERT INTO "verses" VALUES(1940315,77000,6,-1,'این شعر در کتاب سفینهٔ حافظ به سعی و اهتمام سرتیپ مسعود جنتی عطایی در زمرهٔ ساقی‌نامه‌های منتسب به حافظ آمده است. هر چند لحن و زبان شعر نشان می‌دهد که این شعر به احتمال بالا از حافظ نیست.','هوش مصنوعی: این شعر در کتابی به نام "سفینهٔ حافظ" که توسط سرتیپ مسعود جنتی عطایی گردآوری شده، قرار دارد. با این حال، شیوه بیان و زبان شعر نشان می‌دهد که احتمالاً این شعر از حافظ نیست.',NULL);
INSERT INTO "verses" VALUES(1940316,77000,5,0,'تو خود حافظا سر ز مستی متاب','هوش مصنوعی: ای حافظ، از خوشی و نشئه خود چشم نپوش، زیرا که پادشاهی از کسی که در حال سرخوشی است، مالیات نخواهد گرفت.',NULL);
INSERT INTO "verses" VALUES(1940317,77000,5,1,'که سلطان نخواهد خراج از خراب',NULL,NULL);
INSERT INTO "verses" VALUES(1940318,77000,4,0,'ولیکن به شرطی که در مرگ من','هوش مصنوعی: اما تنها به این شرط که در مرگ من هیچ‌کس جز نوازندگان و کسانی که چنگ می‌زنند، نگران و غمگین نشوند.',NULL);
INSERT INTO "verses" VALUES(1940319,77000,4,1,'ننالد به جز مطرب و چنگ زن',NULL,NULL);
INSERT INTO "verses" VALUES(1940320,77000,3,0,'مریزید بر گور من جز شراب','هوش مصنوعی: بر سر مزار من فقط شراب بریزید و در مراسم خاکسپاری‌ام جز موسیقی رباب نیاورید.',NULL);
INSERT INTO "verses" VALUES(1940321,77000,3,1,'میارید در ماتمم جز رباب',NULL,NULL);
INSERT INTO "verses" VALUES(1940322,68778,5,1,'پر خون جگر گردد چون دور به ما افتد',NULL,NULL);
INSERT INTO "verses" VALUES(1940323,33187,6,1,'چون عود چند باشم در آتش رمیده',NULL,NULL);
INSERT INTO "verses" VALUES(1940324,68778,5,0,'آن باده که دل‌ها را از غم دهد آزادی','هوش مصنوعی: آن شرابی که دل‌ها را از غم رها می‌سازد، وقتی به ما می‌رسد، دلی پر از درد و غم به همراه می‌آورد.',NULL);
INSERT INTO "verses" VALUES(1940325,68778,4,0,'آخر چه زیان افتد سلطان ممالک را','هوش مصنوعی: برای سلطانی که در حکومت خود به حال تهیدستان نگاهی می اندازد، چه خسارتی ممکن است پیش آید؟',NULL);
INSERT INTO "verses" VALUES(1940326,59307,3,0,'یک نیمه نرگس باز کرد از خواب جنبانید سر','هوش مصنوعی: نیمه‌ای از گل نرگس به آرامی از خواب بیدار شد و سرش را تکان داد. بر صورتش همچون ماه، موهای پریشان و زیبا نمایان گشت.',NULL);
INSERT INTO "verses" VALUES(1940327,59307,2,1,'برداشتم برقع به ناز از ماه تابان سنگنک',NULL,NULL);
INSERT INTO "verses" VALUES(1940328,59307,2,0,'کردم دو انگشتان دراز آهستهک آهستهک','هوش مصنوعی: به آرامی دو انگشت خود را دراز کردم و با احتیاط برقع را از چهره ماه تابان کنار زدم.',NULL);
INSERT INTO "verses" VALUES(1940329,59307,1,1,'من از نهیب بیم او چون بید لرزان سنگنک',NULL,NULL);
INSERT INTO "verses" VALUES(1940330,59307,1,0,'دیدم نگار نازنین بر تخت زر در خواب خوش','هوش مصنوعی: دیدم که معشوقه‌ی عزیزم بر تخت زرین خوابیده است. خواب خوش او باعث ترس و نگرانی من شده و من مانند سنگی که در برابر زلزله می‌لرزد، مضطرب و لرزان شدم.',NULL);
INSERT INTO "verses" VALUES(1940331,59307,0,1,'نرمک نهادم پای را رفتم به ایوان سنگنک',NULL,NULL);
INSERT INTO "verses" VALUES(1940332,59307,0,0,'من دوش پنهان می‌شدم تا قصر جانان سنگنک','هوش مصنوعی: دیشب مخفیانه به قصر محبوب رفتم و به آرامی پایم را بر روی زمین گذاشتم و به سمت ایوان آنجا حرکت کردم.',NULL);
INSERT INTO "verses" VALUES(1940333,33187,13,1,'درهای شعر حافظ بنویس بر جریده',NULL,NULL);
INSERT INTO "verses" VALUES(1940334,33187,13,0,'ما را بضاعت این است گر در مذاقت افتد','هوش مصنوعی: همین که ما توانایی محدودی داریم، اگر تو در خلق شعر به مزاج ما بیفتی، می‌توانی اشعار حافظ را بر روی کاغذ بنویسی.',NULL);
INSERT INTO "verses" VALUES(1940335,59307,3,1,'شد بر رخ همچون مهش زلف پریشان سنگنک',NULL,NULL);
INSERT INTO "verses" VALUES(1940336,33187,12,1,'کز عاشقان بیدل دل می برد دو دیده',NULL,NULL);
INSERT INTO "verses" VALUES(1940337,33187,11,1,'وز گلبن وصالت هرگز گلی نچیده',NULL,NULL);
INSERT INTO "verses" VALUES(1940338,33187,11,0,'در پای خار هجران افتاده در کشاکش','هوش مصنوعی: در برابر مشکلات جدایی به زانو درآمده‌ام و هیچگاه از باغ وصال تو گلی نچیده‌ام.',NULL);
INSERT INTO "verses" VALUES(1940339,33187,10,1,'سرگشته و پریشان ای نور هر دودیده',NULL,NULL);
INSERT INTO "verses" VALUES(1940340,33187,10,0,'تا کی فرو گذاری چون زلف خود دلم را','هوش مصنوعی: تا کی می‌خواهی به من بی‌توجهی کنی و دلم را به خاطر خودت آشفته و سرگردان نگه‌داری، ای نور چشمان من؟',NULL);
INSERT INTO "verses" VALUES(1940341,33187,9,1,'آن دم که جان شیرین باشد به لب رسیده',NULL,NULL);
INSERT INTO "verses" VALUES(1940342,33187,9,0,'گر بر لبم نهی لب یابم حیات باقی','هوش مصنوعی: اگر لب‌های تو را بر لب‌های خود بگذارم، زندگی جاودانی را به دست می‌آورم؛ زمانی که جان شیرینم به لب‌هایم نزدیک شده است.',NULL);
INSERT INTO "verses" VALUES(1940343,33187,8,1,'پیوسته از چه باشد چون قد من خمیده',NULL,NULL);
INSERT INTO "verses" VALUES(1940344,33187,8,0,'میلی اگر ندارد با عارض تو ابرو','هوش مصنوعی: اگر ابروهایت با چهره‌ات هماهنگ نیستند، دلیلش چیست وقتی که قامت من خمیده و نازک است؟',NULL);
INSERT INTO "verses" VALUES(1940345,33187,7,1,'هم زان دهن برآرم کام دل رمیده',NULL,NULL);
INSERT INTO "verses" VALUES(1940346,33187,12,0,'گر دست من نگیری با خواجه بازگویم','هوش مصنوعی: اگر تو دست من را نگیری، با آقا به سادگی می‌گویم که چشم‌های عاشق بی‌خیال، دل‌ها را می‌رباید.',NULL);
INSERT INTO "verses" VALUES(1940347,59307,4,0,'گفتا به من ای باهنر گفتم منم مسکین تو','هوش مصنوعی: شخصی به من گفت: ای کسی که به خوبی‌ها آگاهی، من هم در تلاش هستم و در شرایط سختی قرار دارم. اگر کسی خبری از من به تو برساند، بدان که تو برای من ارزشمندی و همچون آرامش جانم هستی.',NULL);
INSERT INTO "verses" VALUES(1940348,59307,4,1,'تا گر کسی یابد خبر ای راحت جان سنگنک',NULL,NULL);
INSERT INTO "verses" VALUES(1940349,59307,5,0,'باری به کام خویشتن آوردمش در بر دمی','هوش مصنوعی: در اینجا شاعر به لحظه‌ای اشاره می‌کند که پرنده‌ای به نام مرغ سحرخوان، با آواز خود فضایی دل‌نشین و زیبایی را به وجود می‌آورد. او در این حال به خود می‌گوید که در زندگی خود چه لذتی را به دست آورده و به یادگیری نسل قبل از خود افتخار می‌کند. این لحظه را به یک وقت خوشایند و تاثیرگذار تشبیه کرده که صدای آن پرنده، روح انسان را نوازش می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1940350,68778,3,1,'در تاب مشو جانا در گفته خطا افتد',NULL,NULL);
INSERT INTO "verses" VALUES(1940351,68778,3,0,'گر زلف سیاهت را من مشک ختا گفتم','هوش مصنوعی: اگر من زلف سیاه تو را مشک ختا نامیدم، در این حال عزیزم، در گفته‌ام خطا می‌کند.',NULL);
INSERT INTO "verses" VALUES(1940352,68778,2,1,'بر تخته فیروزی تا قرعه کرا افتد',NULL,NULL);
INSERT INTO "verses" VALUES(1940353,68778,2,0,'هر کس به تمنائی فال از رخ او گیرد','هوش مصنوعی: هر کسی که به امیدی از چهره او سراغی بگیرد، بر تخته شانس و خوشبختی می‌نشیند تا ببیند قرعه نصیب چه کسی می‌شود.',NULL);
INSERT INTO "verses" VALUES(1940354,68778,1,1,'تا آخر از این طوفان هر تخته کجا افتد',NULL,NULL);
INSERT INTO "verses" VALUES(1940355,68778,1,0,'ما کشتی صبر خود در بحر غم افکندیم','هوش مصنوعی: ما تحمل خود را در دریاى غم گذاشته‌ایم و تا پایان این طوفان، هر بخش از زندگی‌مان به کجا برود، می‌پذیریم.',NULL);
INSERT INTO "verses" VALUES(1940356,68778,0,1,'هر جا که دلی باشد در دام بلا افتد',NULL,NULL);
INSERT INTO "verses" VALUES(1940357,68778,0,0,'گر زلف پریشانت در دست صبا افتد','هوش مصنوعی: اگر زلف آشفته تو به دست باد بیفتد، هر جایی که دلی وجود داشته باشد، در دام مشکلات گرفتار می‌شود.',NULL);
INSERT INTO "verses" VALUES(1940358,59308,4,0,'باد صبا چو بگذری بر سر کوی آن پری','هوش مصنوعی: وقتی باد صبحگاهی از آنجا می‌گذرد، پیام‌های تازه و دلکش متعلق به آن معشوق را برای ما بیاورد.',NULL);
INSERT INTO "verses" VALUES(1940359,59308,4,1,'قصه حافظش بگو تازه به تازه نو به نو',NULL,NULL);
INSERT INTO "verses" VALUES(1940360,59308,3,0,'شاهد دلربای من می‌کند از برای من','هوش مصنوعی: عشق و زیبایی معشوق من به طور مداوم برای من تغییر می‌کند و هر روز جلوه‌های جدیدی از زیبایی و عطر را به من نشان می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1940361,59308,3,1,'نقش و نگار و رنگ و بو تازه به تازه نو به نو',NULL,NULL);
INSERT INTO "verses" VALUES(1940362,59308,2,0,'بر ز حیات کی خوری گر نه مدام می خوری','هوش مصنوعی: اگر از زندگی لذت نمی‌بری، چرا مدام به خود زحمت می‌دهی؟ از نوشیدن شراب لذت ببر و به یاد او تازه و نو بمان.',NULL);
INSERT INTO "verses" VALUES(1940363,59308,2,1,'باده بخور به یاد او تازه به تازه نو به نو',NULL,NULL);
INSERT INTO "verses" VALUES(1940364,59308,1,0,'با صنمی چو لعبتی خوش بنشین به خلوتی','هوش مصنوعی: با یک معشوقی مانند یک بازی دلپذیر، در تنهایی بنشین و بوسه بگیر. هر بار با آرزویی نو و تازگی به تازگی این لحظات را تجربه کن.',NULL);
INSERT INTO "verses" VALUES(1940365,59308,1,1,'بوسه ستان به آرزو تازه به تازه نو به نو',NULL,NULL);
INSERT INTO "verses" VALUES(1940366,59308,0,0,'مطرب خوش‌نوا بگو تازه به تازه نو به نو','هوش مصنوعی: بخشنده خوش صدا، به ما بگویید که همیشه و پیوسته نوشیدنی خوشایند و تازه‌ای را به ما ارائه دهید.',NULL);
INSERT INTO "verses" VALUES(1940367,59308,0,1,'باده دلگشا بجو تازه به تازه نو به نو',NULL,NULL);
INSERT INTO "verses" VALUES(1940368,59307,6,1,'بر شاه خوان این قصه را از خلق پنهان سنگنک',NULL,NULL);
INSERT INTO "verses" VALUES(1940369,59307,6,0,'گفتا که حافظ خیز و رو صبح است بر ایوان شاه','هوش مصنوعی: گفت: حافظ بیدار شو و به سوی صبح برو، بر ایوان شاه نشسته و این داستان را از مردم مخفی نگه‌دار.',NULL);
INSERT INTO "verses" VALUES(1940370,59307,5,1,'بانگ نوا زد آن زمان مرغ سحرخوان سنگنک',NULL,NULL);
INSERT INTO "verses" VALUES(1940371,68778,4,1,'کو را نظری روزی بر حال گدا افتد',NULL,NULL);
INSERT INTO "verses" VALUES(1940372,33181,7,1,'نسیم زلف تو می‌خواستم ز عمر دراز',NULL,NULL);
INSERT INTO "verses" VALUES(1940373,33181,7,0,'امید قد تو می‌داشتم ز بخت بلند','از بخت، امید رسیدن به قامت نیک و بلند تو را داشتم و از عمر، رسیدن به عطر زلف لطیف و دراز تو را.',NULL);
INSERT INTO "verses" VALUES(1940374,33181,6,1,'نظر به روی کسی بر نمی‌کنی از ناز',NULL,NULL);
INSERT INTO "verses" VALUES(1940375,33173,5,0,'راه ما غمزهٔ آن ترک‌کمان ابرو زد','هوش مصنوعی: راه ما به زیبایی و ناز آن دختر ترک وابسته است و آن سرو بلند قامت، زیبایی و دلربایی ما را به نمایش می‌گذارد.',NULL);
INSERT INTO "verses" VALUES(1940376,33173,4,1,'پای خیل خردم لشکر غم از جا برد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940377,33173,4,0,'دوش دست طربم سلسلهٔ شوق تو بست','هوش مصنوعی: شب گذشته احساس خوشحالی و شوق تو مرا به صفی از شادی‌ها وارد کرد و در عوض، غم و اندوه را از جای خود برکند و دور کرد.',NULL);
INSERT INTO "verses" VALUES(1940378,33173,3,1,' سنگ را سیل تواند به لب دریا برد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940379,33173,3,0,'دل سنگین ترا اشک من آورد به راه','هوش مصنوعی: دل سنگین و ناراحتی تو را اشک‌های من به مسیر آورد. مثل اینکه سیل می‌تواند سنگ‌ها را به سمت دریا ببرد.',NULL);
INSERT INTO "verses" VALUES(1940380,33173,2,1,'زر به زر داد کسی کامد و این کالا برد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940381,33173,2,0,'آمد و گرم ببرد آب رخم اشک چو سیم','هوش مصنوعی: او آمد و با داغ دل، اشک‌های من را مانند نقره به صورتش جاری ساخت. کسی آمد و این موقعیت را برداشت و به من چیزی نداد.',NULL);
INSERT INTO "verses" VALUES(1940382,33173,1,1,'نه دل خسته بیمار مرا تنها برد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940383,33173,1,0,'هرکجا بود دلی چشم تو برد از راهش','هوش مصنوعی: هر جا که دل کسی به تو نظر کند، نگاه تو آن دل را از راهش منحرف می‌کند. دل خسته و بیمار من نیز از این تاثیر دور نمانده و مرا رها کرده است.',NULL);
INSERT INTO "verses" VALUES(1940384,33173,5,1,' رخت ما هندوی آن سرو سهی بالا برد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940385,33173,0,1,'باد بوی تو بیاورد و قرار از ما برد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940386,33172,7,1,'به وصف قد تو بالا گرفته است',NULL,NULL);
INSERT INTO "verses" VALUES(1940387,33172,7,0,'حدیث حافظ ای سرو سمن‌بوی','هوش مصنوعی: حافظ در اینجا می‌گوید که داستان و سخن درباره تو، ای درخت زیبا و خوشبو، به قد و قامت تو عظمتی خاص داده است.',NULL);
INSERT INTO "verses" VALUES(1940388,33172,6,1,'جهان در لؤلؤ لالا گرفته است',NULL,NULL);
INSERT INTO "verses" VALUES(1940389,33172,6,0,'ز دریای دو چشمم گوهر اشک','هوش مصنوعی: از چشمانم مانند دو دریا، گوهری به نام اشک به وجود آمده که در لؤلؤی خواب کودکانه، پنهان شده است.',NULL);
INSERT INTO "verses" VALUES(1940390,33172,5,1,'مگر یارم ره صحرا گرفته است؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940391,33172,5,0,'نسیم صبح، عنبر بوست امروز','هوش مصنوعی: امروز بوی خوشی چون عطر خوش عنبر در هوا پیچیده است، آیا ممکن است که محبوبم به سمت بیابان رفته باشد؟',NULL);
INSERT INTO "verses" VALUES(1940392,33172,4,1,'چرا او سایه از ما وا گرفته است؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940393,33172,4,0,'چو ما در سایهٔ الطاف اوییم','هوش مصنوعی: وقتی ما تحت حمایت و مهربانی او هستیم، چرا او از ما فاصله گرفته است؟',NULL);
INSERT INTO "verses" VALUES(1940394,33172,3,1,'که کار عاشقان بالا گرفته است',NULL,NULL);
INSERT INTO "verses" VALUES(1940395,33173,0,0,'هوس باد بهارم به سوی صحرا برد','هوش مصنوعی: هوس و آرزوی رفتن به دشت و صحرا مرا به سفر می‌برد. بادی که می‌وزد، بوی تو را برایم می‌آورد و آرامش را از من می‌گیرد.',NULL);
INSERT INTO "verses" VALUES(1940396,33173,6,0,'جام می پیش لبت دم ز روان‌بخشی زد','هوش مصنوعی: جام می را به سمت لبت ببر و از خاصیت شادی‌بخشی‌اش صحبت کن، که آب آن لب، جان را تازه می‌کند و روح را سرزنده می‌سازد.',NULL);
INSERT INTO "verses" VALUES(1940397,33173,6,1,' آب وی آن لب جان‌بخش روان‌افزا برد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940398,33173,7,0,'بحث بلبل بر حافظ مکن از خوش سخنی','هوش مصنوعی: بهتر است درباره سخنان شیرین بلبل با حافظ صحبت نکنی، چرا که در مقایسه با طوطی، هیچ‌گاه نمی‌توان به زیبایی صدای او اشاره کرد.',NULL);
INSERT INTO "verses" VALUES(1940399,33175,0,1,'که کَس به رِندِ خرابات، ظَنِّ آن نَبَرَد',NULL,NULL);
INSERT INTO "verses" VALUES(1940400,33175,0,0,'من و صلاح و سلامت؟ کَس این گمان نَبَرَد','هوش مصنوعی: من و خوبی و سلامتی؟ هیچکس به این فکر نمی‌کند که کسی به رندی که در میخانه به سر می‌برد، شک کند.',NULL);
INSERT INTO "verses" VALUES(1940401,33174,8,1,'هر آن کـ‌او چو حافظ می صاف خورد',NULL,NULL);
INSERT INTO "verses" VALUES(1940402,33174,8,0,'شود مست وحدت زجام الست','هوش مصنوعی: هر کس که مانند حافظ از جام عشق و معرفت بنوشد، در حالتی خاص و غنی از وحدت و یگانگی مست خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1940403,33174,7,1,'که چون مرده باشی نگویند مرد',NULL,NULL);
INSERT INTO "verses" VALUES(1940404,33174,7,0,'چنان زندگانی کن اندر جهان','هوش مصنوعی: زندگی‌ات را به‌گونه‌ای بگذران که وقتی از دنیا رفتی، کسی نگویند تو مردی یا تو را فراموش کنند.',NULL);
INSERT INTO "verses" VALUES(1940405,33174,6,1,'قناعت کن ار نیست اطلس چو برد',NULL,NULL);
INSERT INTO "verses" VALUES(1940406,33174,6,0,'مکش رنج بیهوده خرسند باش','هوش مصنوعی: خودت را در زحمت بیهوده نینداز و شاد باش. اگرچه ممکن است چیزهایی که می‌خواهی را نداشته باشی، ولی با همان چیزهایی که داری راضی باش.',NULL);
INSERT INTO "verses" VALUES(1940407,33174,5,1,'ارسطو دهد جان، چو بیچاره کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1940408,33174,5,0,'مزن دم ز حکمت که در وقت مرگ','هوش مصنوعی: در این بیت به این موضوع اشاره می‌شود که نباید دربارهٔ حکمت و دانایی در زمان مرگ صحبت کرد، چرا که حتی بزرگانی مانند ارسطو نیز در چنین مواقعی دچار درد و رنج می‌شوند و به نوعی در وضعیت تأسف‌آوری قرار می‌گیرند. به عبارت دیگر، در لحظات پایانی زندگی، دانایی و حکمت نمی‌توانند مانع از رنج و دشواری‌های زندگی شوند.',NULL);
INSERT INTO "verses" VALUES(1940409,33174,4,1,'قضای نوشته نشاید سترد',NULL,NULL);
INSERT INTO "verses" VALUES(1940410,33174,4,0,'مرا از ازل عشق شد سرنوشت','هوش مصنوعی: عشق برای من از ابتدای آفرینش تقدیر و سرنوشت نوشته شده است و هیچ‌چیز نمی‌تواند آن را تغییر دهد.',NULL);
INSERT INTO "verses" VALUES(1940411,33174,3,1,'که کار خدایی نه کاریست خرد',NULL,NULL);
INSERT INTO "verses" VALUES(1940412,33174,3,0,'برو زاهدا خورده بر ما مگیر','هوش مصنوعی: به زاهد بگو که از ما دور شود و به ما نپردازد، زیرا کار خداوند به کارهای کوچک و ناچیز مرتبط نیست.',NULL);
INSERT INTO "verses" VALUES(1940413,33174,2,1,'مریزاد پایی که در هم فشرد',NULL,NULL);
INSERT INTO "verses" VALUES(1940414,33174,2,0,'بنازیم دستی که انگور چید','هوش مصنوعی: بیا تا به جمال دستی افتخار کنیم که انگور چیده و به یاد اهمیت پایی که زمین را فشرده، ارج بگذاریم.',NULL);
INSERT INTO "verses" VALUES(1940415,33174,1,1,'که از روی ما رنگ زردی ببرد',NULL,NULL);
INSERT INTO "verses" VALUES(1940416,33174,1,0,'هزار آفرین بر می سرخ باد','هوش مصنوعی: هزار بار به بادِ خوشی که رنگ زرد را از چهره‌ام می‌برد و می‌دمد، تحسین و ستایش می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1940417,33174,0,1,'به من باز بنمود می دستبرد',NULL,NULL);
INSERT INTO "verses" VALUES(1940418,33174,0,0,'صراحی دگر بارم از دست برد','هوش مصنوعی: جام جدیدی از شراب به من نشان دادند و دوباره انگار که دست از من برداشتند و شربت را به من دادند.',NULL);
INSERT INTO "verses" VALUES(1940419,33173,7,1,'پیش طوطی نتوان نام هزارآوا برد',NULL,NULL);
INSERT INTO "verses" VALUES(1940420,33172,3,0,'شدم عاشق به بالای بلندش','هوش مصنوعی: به خاطر زیبایی و جذابیت او به عشقش دلبسته شدم، زیرا عشق و علاقه به او در دل عاشقان شدت یافته است.',NULL);
INSERT INTO "verses" VALUES(1940421,33175,1,0,'من این مُرَقَّعِ دیرینه، بَهرِ آن دارم','هوش مصنوعی: این اثر قدیمی را به خاطر این دارم که در زیر این لباس مذهب، بتوانم شراب بنوشم، بدون آنکه کسی شک کند.',NULL);
INSERT INTO "verses" VALUES(1940422,33172,2,1,'هوای آن قد و بالا گرفته است',NULL,NULL);
INSERT INTO "verses" VALUES(1940423,33172,1,1,'از آن آب آتشی در ما گرفته است',NULL,NULL);
INSERT INTO "verses" VALUES(1940424,33170,1,1,'موسم عیش است و دور ساغر و عهد شباب ',NULL,NULL);
INSERT INTO "verses" VALUES(1940425,33170,1,0,'خانه بی‌تشویش و ساقی یار و مطرب نکته‌گوی','هوش مصنوعی: اینجا به فضایی آرام و دلپذیر اشاره شده که در آن وجود محبوب، معشوق، و نوازنده‌ای که سخنان دلنشین می‌گوید، فضایی مناسب برای لذت‌بردن و خوش‌گذرانی در دوران جوانی را فراهم می‌آورد. دور ساغر به معنای نوشیدن شراب و لذت بردن از خوشی‌های زندگی است.',NULL);
INSERT INTO "verses" VALUES(1940426,33170,0,1,'فرصتی زین به کجا باشد بده جام شراب',NULL,NULL);
INSERT INTO "verses" VALUES(1940427,33170,0,0,'صبح دولت می‌دمد کو جام همچون آفتاب','هوش مصنوعی: صبح که نور و روشنایی می‌آید، مانند خورشید، یادآور می‌شود که فرصتی برای شادمانی و لذت بردن از زندگی وجود دارد. این لحظه‌ی خاص و بی‌نظیر، فرصتی است که نباید آن را از دست داد. بنابراین، بیایید لیوان شراب را پر کنیم و از این لحظه بهره‌مند شویم.',NULL);
INSERT INTO "verses" VALUES(1940428,33169,8,1,'گو به زاری سفری کرد و برفت از بر ما',NULL,NULL);
INSERT INTO "verses" VALUES(1940429,33169,8,0,'هر که گوید که کجا رفت خدا را حافظ','هوش مصنوعی: هر کس بپرسد که خدا کجا رفته است، به او بگو که حافظ به زاری و غم، سفری کرده و از کنار ما رفته است.',NULL);
INSERT INTO "verses" VALUES(1940430,33169,7,1,'ورق گل خجل است از ورق دفتر ما',NULL,NULL);
INSERT INTO "verses" VALUES(1940431,33169,7,0,'تا ز وصف رخ زیبای تو ما، دم زده‌ایم','هوش مصنوعی: ما زمانی که از زیبایی چهره تو صحبت می‌کنیم، گل‌ها به خاطر کم‌تری که دارند، شرمنده و خجالت‌زده هستند.',NULL);
INSERT INTO "verses" VALUES(1940432,33169,6,1,'نتوان برد هوای تو برون از سر ما',NULL,NULL);
INSERT INTO "verses" VALUES(1940433,33170,2,0,'از پی تفریح طبع و زیور حسن طرب','هوش مصنوعی: برای لذت بردن از زیبایی‌ها و شادابی زندگی، ترکیب زیبا و دلنشین جام طلایی با لعل مذاب (سنگ قیمتی) بسیار خوشایند و دل‌انگیز است.',NULL);
INSERT INTO "verses" VALUES(1940434,33169,6,0,'به سرت گر همه آفاق به هم جمع شوند','هوش مصنوعی: اگر همه جهان هم جمع شوند، باز هم نمی‌توانیم آرزوی تو را از ذهنمان دور کنیم.',NULL);
INSERT INTO "verses" VALUES(1940435,33169,5,0,'روز باشد که بیاید به سلامت بازم','هوش مصنوعی: روزی خواهد آمد که به خوبی و سلامت به دیدارم بیابی، و ای کاش آن روزی که با سلام و خوش‌آمدی بر ما وارد می‌شوی، زودتر فرا برسد.',NULL);
INSERT INTO "verses" VALUES(1940436,33169,4,1,'بکشد از همه انصاف ستم داور ما',NULL,NULL);
INSERT INTO "verses" VALUES(1940437,33169,4,0,'گر همه خلق جهان بر من و تو حیف برند','هوش مصنوعی: اگر همه افراد دنیا بخواهند نسبت به من و تو ظلم کنند، باز هم انصاف داور ما از سایرین بیشتر است و ما را حمایت می‌کند.',NULL);
INSERT INTO "verses" VALUES(1940438,33169,3,1,'رشک می‌آیدش از صحبت جان پرور ما',NULL,NULL);
INSERT INTO "verses" VALUES(1940439,33169,3,0,'فلک آواره به هر سو کندم می‌دانی؟','هوش مصنوعی: آسمان را به هر طرف می‌گردانم و می‌دانی چرا؟ زیرا از گفت‌وگو و محاوره‌ای که با هم داریم، حسرت می‌خورد.',NULL);
INSERT INTO "verses" VALUES(1940440,33169,2,1,'که وفا با تو قرین باد و خدا یاور ما',NULL,NULL);
INSERT INTO "verses" VALUES(1940441,33169,2,0,'به دعا آمده‌ام هم به دعا دست بر آر','هوش مصنوعی: من به دعا آمده‌ام، پس لطفاً دعا را فراموش نکن. امیدوارم که وفاداری تو همیشه در کنار ما باشد و خداوند در این راه یاریمان کند.',NULL);
INSERT INTO "verses" VALUES(1940442,33169,1,1,'قاصدی کز تو سلامی برساند بر ما',NULL,NULL);
INSERT INTO "verses" VALUES(1940443,33169,1,0,'از نثار مژه چون زلف تو در زر گیرم','هوش مصنوعی: از نگاه زیبای تو مانند زنجیری طلایی، من پیامبری می‌خواهم که پیامی از تو برای من بیاورد.',NULL);
INSERT INTO "verses" VALUES(1940444,33169,5,1,'ای خوش آن روز که آید به سلامی بر ما',NULL,NULL);
INSERT INTO "verses" VALUES(1940445,33170,2,1,'خوش بود ترکیب زرین جام با لعل مذاب ',NULL,NULL);
INSERT INTO "verses" VALUES(1940446,33170,3,0,'از خیال لطف می مشاطهٔ چالاک طبع','هوش مصنوعی: از خیال محبت و نیکی، آرایشگر چابک به طور نهانی در دل برگ گل، گلاب خوشبو می‌سازد.',NULL);
INSERT INTO "verses" VALUES(1940447,33170,3,1,'در ضمیر برگ گل خوش می‌کند پنهان گلاب ',NULL,NULL);
INSERT INTO "verses" VALUES(1940448,33172,1,0,'لب چون آتشش آب حیات است','هوش مصنوعی: لب مانند شعله‌ای از آتش است که حیات را به ارمغان می‌آورد و از آن آتش، آبی در وجود ما جاری شده است.',NULL);
INSERT INTO "verses" VALUES(1940449,33172,0,1,'سرم چون زلف او سودا گرفته است',NULL,NULL);
INSERT INTO "verses" VALUES(1940450,33172,0,0,'غمش تا در دلم مَأوا گرفته است','هوش مصنوعی: غم او در دل من جا گرفته و فکری شبیه زلف او در سر من وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1940451,33171,6,1,'همان حدیث هُما و طریق خطّاف است',NULL,NULL);
INSERT INTO "verses" VALUES(1940452,33171,6,0,'عدو که منطق حافظ طمع کند در شعر','هوش مصنوعی: هر کس که با نیت بد به اشعار حافظ دست می‌زند، سرنوشتی مشابه داستان هُما و پرندگان خواهد داشت.',NULL);
INSERT INTO "verses" VALUES(1940453,33171,5,1,'که آن بیان مقامات کشف کشّاف است',NULL,NULL);
INSERT INTO "verses" VALUES(1940454,33171,5,0,'ز مُصحَف رخ دلدار آیتی بر خوان','هوش مصنوعی: از نوشته‌های قلب محبوب آیه‌ای برملا کن که آن سخن، بیانگر درجات و مراتب شهود و آگاهی‌های عمیق است.',NULL);
INSERT INTO "verses" VALUES(1940455,33171,4,1,'از این مثال گزینم روان در اطراف است',NULL,NULL);
INSERT INTO "verses" VALUES(1940456,33171,4,0,'تو را که مایهٔ خلد است نیاز همتا نیست','هوش مصنوعی: تو را که مایهٔ بهشت هستی، نیازی به همتای دیگری نداری. من از این مثال‌ها استفاده می‌کنم، زیرا روح در اطراف این موضوع در جریان است.',NULL);
INSERT INTO "verses" VALUES(1940457,33171,3,1,'چه چشم‌هاست که از روی تو بر اطراف است',NULL,NULL);
INSERT INTO "verses" VALUES(1940458,33171,3,0,'چو سرو سرکشی ای یار سنگدل با ما','هوش مصنوعی: ای دوست سنگدل، تو مانند سروی نافرمان هستی. چرا باید نگران نگاه‌ها باشیم وقتی که زیبایی‌ات همه جا را پر کرده است؟',NULL);
INSERT INTO "verses" VALUES(1940459,33171,2,1,'که نور دیدهٔ عاشق ز قاف تا قاف است',NULL,NULL);
INSERT INTO "verses" VALUES(1940460,33171,2,0,'ز چشم عشق توان دید روی شاهد غیب','هوش مصنوعی: از چشمان عشق می‌توان چهره‌ی معشوق پنهانی را دید، چون نور دیدگان عاشق در تمام جهان گسترده است.',NULL);
INSERT INTO "verses" VALUES(1940461,33171,1,1,'چرا که وصف تو بیرون ز حد اوصاف است',NULL,NULL);
INSERT INTO "verses" VALUES(1940462,33171,1,0,'بیان وصف تو گفتن نه حد امکان است','هوش مصنوعی: بیان ویژگی‌های تو فراتر از توانایی‌های انسانی است، زیرا تو دارای صفاتی هستی که نمی‌توان آنها را به درستی توصیف کرد.',NULL);
INSERT INTO "verses" VALUES(1940463,33171,0,1,'وگر به قهر برانی درون ما صاف است',NULL,NULL);
INSERT INTO "verses" VALUES(1940464,33171,0,0,'اگر به لطف بخوانی مَزید الطاف است','هوش مصنوعی: اگر با مهربانی و لطف به ما نگاه کنی، محبت و نعمتت بیشتر خواهد بود، و اگر با خشم از ما دور شوی، درون ما پاک و بی‌خبر از کینه باقی می‌ماند.',NULL);
INSERT INTO "verses" VALUES(1940465,33170,5,1,'می‌رسد هر دم به گوش زهره گلبانگ رباب',NULL,NULL);
INSERT INTO "verses" VALUES(1940466,33170,5,0,'تا شد آن مه مشتری درهای حافظ را به نقد','هوش مصنوعی: هنگامی که آن معشوق زیبا در دل حافظ حضور پیدا می‌کند، هر لحظه صدای خوش ساز رباب به گوش زهره می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1940467,33170,4,1,'غمزهٔ ساقی ز چشم می‌پرستان برده خواب ',NULL,NULL);
INSERT INTO "verses" VALUES(1940468,33170,4,0,'شاهد و مطرب به دست‌افشان و مستان پایکوب','هوش مصنوعی: در اینجا توصیف صحنه‌ای شاداب و پرانرژی از می‌نوشی و شادی است. محبوب و نوازنده‌ای در حال رقص و خوش‌گذرانی هستند، و در این میان، نگاهی از طرف ساقی به می‌نوشان احساسات عمیقی را بیدار می‌کند و آن‌ها را در دنیای خواب و رویا غوطه‌ور می‌سازد. این تصویر نمایانگر حالتی از دل‌باختگی و سرمستی است که در حضور زیبایی و موسیقی ایجاد می‌شود.',NULL);
INSERT INTO "verses" VALUES(1940469,33172,2,0,'هُمای همتم عمری است کز جان','هوش مصنوعی: پرنده‌ای به نام هما که نماد آرزوها و امیدهاست، همیشه در دل من جای خاصی دارد و من سال‌هاست که به خاطر زیبایی و جذابیت آن شخص خاص، زندگی‌ام را به سوی او سوق داده‌ام.',NULL);
INSERT INTO "verses" VALUES(1940470,33175,1,1,'که زیرِ خِرقه کِشَم مِی، کسی گمان نَبَرَد',NULL,NULL);
INSERT INTO "verses" VALUES(1940471,33175,2,0,'مَباش غَرّه به عِلم و عمل، فقیه! مُدام','هوش مصنوعی: ای فقیه! به دانش و اعمال خود مغرور نباش، زیرا هیچ‌کس نمی‌تواند از قضا و قدر خداوند جان سالم به در ببرد.',NULL);
INSERT INTO "verses" VALUES(1940472,33175,2,1,'که هیچ‌کَس زِ قضای خدای، جان نَبَرَد',NULL,NULL);
INSERT INTO "verses" VALUES(1940473,33180,0,1,'تو نیز ای دیده خوابی کن، مراد دل بر آر آخر',NULL,NULL);
INSERT INTO "verses" VALUES(1940474,33180,0,0,'دلا چندَم بریزی خون؟ ز دیده شرم دار آخر','هوش مصنوعی: ای جان، تا کی باید از چشمانت اشک بریزی؟ باید از خودت شرمنده شوی. حال که اینگونه است، ای چشم، کمی بخواب و بگذار آرزوی دل برآورده شود.',NULL);
INSERT INTO "verses" VALUES(1940475,33179,8,1,'شاهبازی به شکار مگسی می‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(1940476,33179,8,0,'یار دارد سر صید دل حافظ یاران','هوش مصنوعی: محبوبی که حافظ به آن اشاره می‌کند، مانند یک شکارچی ماهر است که قلب او را به راحتی به دام می‌اندازد. در این میان، او دوستانی دارد که به خوبی از مهارت‌هایش آگاهند و به نظاره این صحنه می‌نشینند. در عین حال، به نظر می‌رسد که در این گیرودار، یک مگس ناچیز نیز به عنوان شکار کوچک‌تری به سوژه تبدیل می‌شود.',NULL);
INSERT INTO "verses" VALUES(1940477,33179,7,1,'ناله‌ای می‌شنوم کز قفسی می‌آید ',NULL,NULL);
INSERT INTO "verses" VALUES(1940478,33179,7,0,'خبر بلبل این باغ بپرسید که من','از بلبل این باغ خبر بگیرید چرا که من صدای ناله‌ای را می‌شنوم که از قفسی به گوش می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1940479,33179,6,1,'گو بران خوش که هنوزش نفسی می‌آید ',NULL,NULL);
INSERT INTO "verses" VALUES(1940480,33179,6,0,'دوست را گر سر پرسیدن بیمار غم است','هوش مصنوعی: اگر دوستت حالش خوش نیست و غمگین است، بهتر است به او سر بزنی و احوالش را بپرسی؛ چرا که هنوز نفس می‌کشد و امیدی برای بهبود وجود دارد.',NULL);
INSERT INTO "verses" VALUES(1940481,33179,5,1,'هر حریفی ز پی ملتمسی می‌آید ',NULL,NULL);
INSERT INTO "verses" VALUES(1940482,33180,1,0,'منم یا رب که جانان را ز ساعد بوسه می‌چینم','هوش مصنوعی: من همان کسی هستم که صبح به صبح با بوسه‌ای از دست محبوبم دعا می‌کنم. آیا دیدی که در نهایت چه پیش آمد؟',NULL);
INSERT INTO "verses" VALUES(1940483,33179,5,0,'جرعه‌ای دِه که به میخانهٔ ارباب کرم','هوش مصنوعی: به من یک نوشیدنی بده که در میخانهٔ پر از بخشش، هر شخصی برای دعا و درخواست خود به آنجا می‌آید.',NULL);
INSERT INTO "verses" VALUES(1940484,33179,4,0,'کس ندانست که منزلگه معشوق کجاست','هوش مصنوعی: هیچ‌کس نمی‌دانست که محل زندگی محبوب کجاست، اما این شواهد کافی است که صدای او به گوش می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1940485,33179,3,1,'هرکس آنجا به طریق هوسی می‌آید ',NULL,NULL);
INSERT INTO "verses" VALUES(1940486,33179,3,0,'هیچ کس نیست که در کوی تواش کاری نیست','هوش مصنوعی: در هیچ جا هیچ‌کس وجود ندارد که در خیابان تو مشغول کار باشد. هر کسی که آنجا می‌آید، به خاطر تمایلات و خواسته‌های خود می‌آید.',NULL);
INSERT INTO "verses" VALUES(1940487,33179,2,1,'موسی آنجا به امید قبسی می‌آید ',NULL,NULL);
INSERT INTO "verses" VALUES(1940488,33179,2,0,'زآتش وادی ایمن نه منم خُرّم و بس','هوش مصنوعی: من از آتش سرزمین ایمن نیستم که خوشحال باشم، فقط موسی در آنجا با امید شعله‌ای می‌آید.',NULL);
INSERT INTO "verses" VALUES(1940489,33179,1,1,'زده‌ام فالی و فریادرسی می‌آید ',NULL,NULL);
INSERT INTO "verses" VALUES(1940490,33179,1,0,'از غم هجر مکن ناله و فریاد که دوش','از غم جدایی ناله و فریاد نزن، زیرا شب گذشته فال گرفتم و کسی برای کمک می‌آید.',NULL);
INSERT INTO "verses" VALUES(1940491,33179,0,1,'که ز انفاس خوشش بوی کسی می‌آید ',NULL,NULL);
INSERT INTO "verses" VALUES(1940492,33179,0,0,'مژده ای دل که مسیحا نفسی می‌آید','هوش مصنوعی: ای دل، خوشحالی کن که یک روح بزرگ و نیکو به زودی می‌آید و از نفس‌های خوشش عطر شخصی خاص به مشام می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1940493,33179,4,1,'این قدر هست که بانگ جرسی می‌آید ',NULL,NULL);
INSERT INTO "verses" VALUES(1940494,33180,1,1,'دعای صبحدم دیدی که چون آمد به کار آخر؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940495,33180,2,0,'مراد دنییٖ و عُقبیٖ به من بخشید روزی‌بخش','هوش مصنوعی: دنیا و آخرت را به من عطا کرد، روزی‌دهنده‌ای که وعده‌اش در گوشم طنین‌انداز است، در حالی که در دستم زلف معشوقه‌ام است.',NULL);
INSERT INTO "verses" VALUES(1940496,33180,2,1,'به گوشم قول چنگ اولی، به دستم زلف یار آخر ',NULL,NULL);
INSERT INTO "verses" VALUES(1940497,33181,6,0,'هزار دیده به روی تو ناظرند و تو خود','همه در زیبایی تو مبهوت و حیران شده‌اند و تو از روی کبر و ناز به‌هیچ کس نگاه نمی‌کنی.',NULL);
INSERT INTO "verses" VALUES(1940498,33181,5,1,'ز مشک نیست غریب آری ار بود غماز',NULL,NULL);
INSERT INTO "verses" VALUES(1940499,33181,5,0,'ز طرهٔ تو پریشانی دلم شد فاش','از موی پریشان تو، دلم فاش و رسوا شد. از مشک عجب نیست که پراکنده و افشاگر است.',NULL);
INSERT INTO "verses" VALUES(1940500,33181,4,1,'چو کعبه یافتم آیم ز بت‌پرستی باز',NULL,NULL);
INSERT INTO "verses" VALUES(1940501,33181,4,0,'به هیچ در نروم بعد از این ز حضرت دوست','پس از این جایی نخواهم رفت چونکه کعبه را یافتم از بت‌پرستی روی می‌گردانم.',NULL);
INSERT INTO "verses" VALUES(1940502,33181,3,1,'که با تو شرح سرانجام خود کنم آغاز',NULL,NULL);
INSERT INTO "verses" VALUES(1940503,33181,3,0,'شبی وصال سحرگه ز بخت خواسته‌ام','شبی وصال سحرگاه را از بخت و اقبال خواسته‌ام که قصه سرانجام خود را با تو بگویم.',NULL);
INSERT INTO "verses" VALUES(1940504,33181,2,1,'غم است و شادی و خار و گل و نشیب و فراز',NULL,NULL);
INSERT INTO "verses" VALUES(1940505,33181,2,0,'دلا! ز هجر مکن ناله، زان که در عالم','ای دل، از دوری یار گله مکن زیرا که بنای زندگی و عالم این‌گونه است که هم غم است و شادی و هم خار و گل.',NULL);
INSERT INTO "verses" VALUES(1940506,33181,1,1,'به بوی روز وصال تو در شبان دراز',NULL,NULL);
INSERT INTO "verses" VALUES(1940507,33181,1,0,'چه حلقه‌ها که زدم بر در دل از سر سوز','چه شب‌ها که غمناک و از درد به در تو منتظر ماندم و در زدم باشد که خورشید وصال طلوع کند.',NULL);
INSERT INTO "verses" VALUES(1940508,33181,0,1,'کجاست بلبل خوشگوی؟ گو برآر آواز!',NULL,NULL);
INSERT INTO "verses" VALUES(1940509,33181,0,0,'صبا به مقدم گل راح روح بخشد باز','صبا باز هم گلستان را خوش‌عطر خواهد کرد، کجاست بلبل که با نوای خوش بسراید؟',NULL);
INSERT INTO "verses" VALUES(1940510,33180,6,1,'تو گویی تائبم حافظ، ز ساقی شرم دار آخر',NULL,NULL);
INSERT INTO "verses" VALUES(1940511,33180,6,0,'بُتی چون ماه زانو زد، میی چون لعل پیش آورد','هوش مصنوعی: دختری زیبا مانند ماه در برابر من زانو زده و جامی از شراب شفاف مانند لعل را به من پیشکش می‌کند. به نظر می‌رسد که من توبه‌کار شده‌ام، ای ساقی، کمی شرم کن و مرا با این شراب سرگرم نکن.',NULL);
INSERT INTO "verses" VALUES(1940512,33180,5,1,'دَم صُبحت بشارتها، بیارَد ز آن دیار آخر ',NULL,NULL);
INSERT INTO "verses" VALUES(1940513,33180,5,0,'دلا در مُلک شبخیزی، گر از اندوه نگریزی','هوش مصنوعی: ای دل، در سرزمین شبانگاه، اگر از غم فرار کنی، صبحگاه بشارت‌هایی خواهد آورد از آن دیار آخر.',NULL);
INSERT INTO "verses" VALUES(1940514,33180,4,1,'به نوکِ کِلکِ رنگ‌آمیز، نقشی می‌نگار آخر ',NULL,NULL);
INSERT INTO "verses" VALUES(1940515,33180,4,0,'نگارستان چین دانم، نخواهد شد سَرایت لیک','هوش مصنوعی: من می‌دانم که زیبایی و جذابیت چینی وجود دارد، اما نمی‌توان به آن دست پیدا کرد. با این حال، قلم رنگ‌آمیز من می‌تواند تصویری از آن را خلق کند و به تصویر بکشم.',NULL);
INSERT INTO "verses" VALUES(1940516,33180,3,1,'ز همت توشه‌ای بردار و خود تخمی بکار آخر ',NULL,NULL);
INSERT INTO "verses" VALUES(1940517,33180,3,0,'چو باد از خرمنِ دونان، ربودن خوشه‌ای تا چند؟','هوش مصنوعی: چرا باید به هر چیز ناچیزی بها بدهیم و از آن خوشه‌ای برباییم؟ بهتر است که کمر همت را بربندیم و خودمان تلاشی کنیم و محصولی بکاریم تا به نتیجه برسیم.',NULL);
INSERT INTO "verses" VALUES(1940518,33178,6,1,'غیر از این گویی خیالاتی به تخمین بسته‌اند',NULL,NULL);
INSERT INTO "verses" VALUES(1940519,33178,6,0,'حافظا محض حقیقت گوی یعنی سر عشق','هوش مصنوعی: ای حافظ، تو حقیقت را بگو؛ زیرا عشق واقعیتی جز این ندارد و دیگرانی که جز این می‌گویند، به خیال بافی و تخمین پرداخته‌اند.',NULL);
INSERT INTO "verses" VALUES(1940520,33178,5,1,'آن حکایتها که بر فرهاد و شیرین بسته‌اند',NULL,NULL);
INSERT INTO "verses" VALUES(1940521,33178,5,0,'جمله وصف عشق من بودست و حسن روی تو','هوش مصنوعی: تمام توصیف‌های عشق من به زیبایی روی تو مربوط می‌شود، همانند داستان‌هایی که درباره فرهاد و شیرین روایت شده است.',NULL);
INSERT INTO "verses" VALUES(1940522,33176,8,0,'حافظ صبور باش که در راه عاشقی','هوش مصنوعی: صبور باش، زیرا در مسیر عشق، تنها کسی به معشوق نمی‌رسد که جانش را برای او ندهد.',NULL);
INSERT INTO "verses" VALUES(1940523,33176,7,1,'این غصه بس که دست سوی جان نمی‌ رسد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940524,33176,7,0,'از دستبرد جور زمان اهل فضل را','هوش مصنوعی: زمانه به قدری نامناسب و سخت شده است که حتی فرزندان علم و فضل نیز از دستبرد آن در امان نیستند. این غم و اندوه برای آن‌ها بسیار سنگین است، به طوری که نمی‌توانند به جان خود دسترسی پیدا کنند و از آن محافظت کنند.',NULL);
INSERT INTO "verses" VALUES(1940525,33176,6,1,'جز آه اهل فضل به کیوان نمی‌رسد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940526,33176,6,0,'از حشمت اهل جهل به کیوان رسیده‌اند','هوش مصنوعی: کسانی که نادانی دارند و فقط به ظاهر و تجملات توجه می‌کنند، به اوج نمی‌رسند. تنها کسانی که درک و دانش دارند، می‌توانند به عمق واقعی ارزش‌ها و فضیلت‌ها دست یابند و این دستاورد از راه سعی و تلاش به دست می‌آید.',NULL);
INSERT INTO "verses" VALUES(1940527,33176,5,1,'وآوازه‌ای ز مصر به کنعان نمی‌رسد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940528,33176,5,0,'یعقوب را دو دیده ز حسرت سپید گشت','هوش مصنوعی: یعقوب به قدری دلتنگ فرزندش یوسف بود که چشمانش از غم و حسرت سفید شد و خبر و آوازه‌ای از مصر به سرزمین کنعان نمی‌رسید.',NULL);
INSERT INTO "verses" VALUES(1940529,33176,4,1,'آوخ که آرزوی من ارزان نمی‌رسد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940530,33176,4,0,'از آرزوست گشته گرانبار غم دلم','هوش مصنوعی: آرزوی من باعث شده که دل‌ام پر از غم شود. افسوس که به آرزوهایم به راحتی نمی‌توانم برسم.',NULL);
INSERT INTO "verses" VALUES(1940531,33176,3,1,'بیچاره را چه چاره چو فرمان نمی‌رسد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940532,33176,3,0,'سیرم ز جان خود به سر راستان ولی','هوش مصنوعی: من به دنبال راه راست هستم و جانم در این مسیر در حال پرواز است، اما بیچاره، وقتی که دستوری نرسد، چه می‌تواند بکند؟',NULL);
INSERT INTO "verses" VALUES(1940533,33176,2,1,'تا صدهزار زخم به دندان نمی‌رسد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940534,33176,2,0,'پی‌پاره‌ای نمی‌کنم از هیچ استخوان','هوش مصنوعی: من برای چیزهای کم‌اهمیت و بی‌ارزش تازگی نمی‌زنم و آسیب نمی‌رسانم، زیرا در برابر صدهزار زخم و درد بزرگ، این زخم‌های کوچک هیچ اعتباری ندارند.',NULL);
INSERT INTO "verses" VALUES(1940535,33176,1,1,'آب رخم همی‌رود و نان نمی‌رسد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940536,33176,1,0,'با خاک ره ز روی مذلت برابرم','هوش مصنوعی: در این بیت، سخن از حالت ذلت و فقر بیان شده است. راوی با حالتی از ناتوانی و نیاز، در کنار خاک راه ایستاده و احساس می‌کند که از چهره‌اش آب می‌افتد، اما حتی نانی برای خوردن ندارد. زندگی او به شدت دچار کمبود و دشواری است.',NULL);
INSERT INTO "verses" VALUES(1940537,33176,0,1,'خون شد دلم ز درد، به درمان نمی‌رسد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940538,33176,0,0,'کارم ز دور چرخ به سامان نمی‌رسد','هوش مصنوعی: کار من تحت تاثیر چرخ فلک به نتیجه نمی‌رسد و دل من از درد پر شده است، ولی به درمان نمی‌رسد.',NULL);
INSERT INTO "verses" VALUES(1940539,33175,4,1,'که تحفه، کَس، دُروگوهر، به بَحر و کان نَبَرَد',NULL,NULL);
INSERT INTO "verses" VALUES(1940540,33175,4,0,'سخن به نزدِ سخن‌دان، اَدا مَکُن حافظ','هوش مصنوعی: حرف‌هایت را نزد کسانی که به سخن آگاه هستند نزن، حافظ، زیرا که این کلام ارزشمند به کسی نمی‌رسد که در دریا و معادن، گوهری نداشته باشد.',NULL);
INSERT INTO "verses" VALUES(1940541,33175,3,1,'به‌هوش باش، که نقدِ تو، پاس‌بان نَبَرَد',NULL,NULL);
INSERT INTO "verses" VALUES(1940542,33175,3,0,'اگرچه دیده بُوَد پاس‌بانِ تو، ای دل','هوش مصنوعی: هرچند که چشمانت تا حدی از تو محافظت می‌کنند، اما ای دل، حواست جمع باشد که هیچ چیز گرانبها و واقعی تو را نمی‌توان به سادگی حفظ کرد.',NULL);
INSERT INTO "verses" VALUES(1940543,33176,8,1,'هر کس که جان نداد به جانان نمی‌رسد',NULL,NULL);
INSERT INTO "verses" VALUES(1940544,77986,7,0,'عود بر آتش نه و منقل بسوز','هوش مصنوعی: به آتش عود بزن و منقل را بسوزان. نگران غم و غصه نباش که سرمای دی ماه خیلی سخت و طاقت‌فرساست.',NULL);
INSERT INTO "verses" VALUES(1940545,33177,0,0,'در هر هوا که جز برق اندر طلب نباشد','هوش مصنوعی: در هر زمانی که جز جستجوی روشنی و آگاهی نباشد، اگر به اندازه‌ی زیادی از چیزهای بی‌ارزش نابود شود، جای تعجبی ندارد.',NULL);
INSERT INTO "verses" VALUES(1940546,33177,1,0,'مرغی که با غم دل شد الفتیش حاصل','پرنده ای که با غم و وغصه همنشین باشد در طول عمرش روی شادی را نمیبیند .',NULL);
INSERT INTO "verses" VALUES(1940547,33178,4,1,'سایبان از عنبر تر گرد نسرین بسته‌اند',NULL,NULL);
INSERT INTO "verses" VALUES(1940548,33178,4,0,'خط سبز و عارضت را نقش بندان خطا','هوش مصنوعی: چشم‌های زیبا و سبز تو را نقاشان با اشتباه در رنگ‌های مختلف طراحی کرده‌اند و سایه‌ای از عطر عنبر بر روی گل‌های نسرین گذاشته‌اند.',NULL);
INSERT INTO "verses" VALUES(1940549,33178,3,1,'یا به گرد ماه تابان عقد پروین بسته‌اند',NULL,NULL);
INSERT INTO "verses" VALUES(1940550,33178,3,0,'یارب آن روی است و در پیرامنش بند کلاه','هوش مصنوعی: ای خدا، آن چهره زیباست و دور آن، یا بر گرد ماه درخشان، با زنجیر ستاره‌های پروین احاطه شده است.',NULL);
INSERT INTO "verses" VALUES(1940551,33178,2,1,'مصلحت را تهمتی بر نافهٔ چین بسته‌اند',NULL,NULL);
INSERT INTO "verses" VALUES(1940552,33178,2,0,'کار زلف توست مشک‌افشانی و نظارگان','هوش مصنوعی: زلف‌های تو باعث خوشبو شدن فضا هستند و کسانی که به تماشا نشسته‌اند بر این باورند که زیبایی تو تنها به خاطر وقوف و تدبیر آن‌هاست.',NULL);
INSERT INTO "verses" VALUES(1940553,33178,1,1,'زاشک رنگین در دیار دیده آیین بسته‌اند',NULL,NULL);
INSERT INTO "verses" VALUES(1940554,33178,1,0,'از برای مقدم خیل و خیالت مردمان','هوش مصنوعی: مردم به خاطر ظاهر نیروی تو و خیالت، اشک‌های رنگین را در سرزمین خود به نمایش گذاشته‌اند.',NULL);
INSERT INTO "verses" VALUES(1940555,33178,0,1,'گوییا نقش لبت از جان شیرین بسته‌اند',NULL,NULL);
INSERT INTO "verses" VALUES(1940556,33178,0,0,'صورت خوبت نگارا خوش به آیین بسته‌اند','هوش مصنوعی: زیبایی تو، ای نگار، به قدری دل‌ربا و جذاب است که انگار به‌خاطر آن، زیبایی‌های دنیا را به هم آمیخته‌اند. همچنین، گویا لب‌هایت به قدری شیرین و دلنشین هستند که به آن‌ها جان و زندگی بخشیده‌اند.',NULL);
INSERT INTO "verses" VALUES(1940557,33177,6,1,'روزی شود که با آن پیوند شب نباشد',NULL,NULL);
INSERT INTO "verses" VALUES(1940558,33177,6,0,'حافظ وصال جانان با چون تو تنگدستی','هوش مصنوعی: روزی می‌آید که عشق و وصال محبوبی چون تو به دست خواهد آمد، زمانی که مشکلات و سختی‌های زندگی وجود نداشته باشد و دیگر شب‌های تنهایی تمام شده باشد.',NULL);
INSERT INTO "verses" VALUES(1940559,33177,5,1,'جز بادهٔ بهشتی هیچش سبب نباشد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940560,33177,5,0,'می خور که عمر سرمد گر درجهان توان یافت','هوش مصنوعی: بنوش که اگر عمر جاودان هم پیدا کنی، تنها دلیل وجودی‌اش جز شراب بهشتی نخواهد بود.',NULL);
INSERT INTO "verses" VALUES(1940561,33177,4,1,'خود را بزرگ دیدن شرط ادب نباشد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940562,33177,4,0,'در محفلی که خورشید اندر شمار ذره‌ست','هوش مصنوعی: در جمعی که خورشید در آنجا به تعداد ذرات کوچک دیده می‌شود، بزرگ‌نمایی از خود نشانه‌ی بی‌ادبی است.',NULL);
INSERT INTO "verses" VALUES(1940563,33177,3,1,'اینجا نسب نگنجد آنجا حسب نباشد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940564,33177,3,0,'در کیش جان‌فروشان فضل و شرف به رندیست','هوش مصنوعی: در جامعه‌ای که افراد خود را بفروشند، دانش و فضیلت مهم است و جایگاه اجتماعی براساس رندی و تردید می‌شود. در این فضا، نسب و اعتبار خانوادگی معنایی ندارد و به هیج وجه نمی‌تواند نشانه‌ای برای ارزش انسانی باشد.',NULL);
INSERT INTO "verses" VALUES(1940565,33177,2,1,'آتش که را بسوزد گر بولهب نباشد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940566,33177,2,0,'در کارخانهٔ عشق ازکفر ناگزیر است','هوش مصنوعی: در دنیای عشق، اگر آتش وجود نداشته باشد، همه چیز به وسوسه و کفر دچار می‌شود و در این وضعیت، عشق نمی‌تواند به درستی شکل بگیرد.',NULL);
INSERT INTO "verses" VALUES(1940567,33177,1,1,'بر شاخسار عمرش برگ طرب نباشد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940568,33177,0,1,'گر خرمنی بسوزد چندان عجب نباشد ',NULL,NULL);
INSERT INTO "verses" VALUES(1940569,33169,0,1,'بخت بد تا به کجا می برد آبشخور ما',NULL,NULL);
INSERT INTO "verses" VALUES(1940570,77986,7,1,'غم مدار از شدت سرمای دی',NULL,NULL);
INSERT INTO "verses" VALUES(1940571,77986,8,0,'آنکه بهر جرعه ای جان می دهد','هوش مصنوعی: کسی که برای یک جرعه آب زندگی‌اش را فدای می‌کند، از او لباسی بگیر و به او یک جام بنوشان.',NULL);
INSERT INTO "verses" VALUES(1940572,78315,2,1,'رای من رای بتان است مبارک رایی',NULL,NULL);
INSERT INTO "verses" VALUES(1940573,78315,2,0,'جای من دیر مغان است مروح وطنی','هوش مصنوعی: جای من در کنار اهل عیش و زندگی است و وطن من همان جاست. نظر من هم نظر معبودها و محبوب‌هاست که همواره خوشبخت و مطلوب است.',NULL);
INSERT INTO "verses" VALUES(1940574,78315,1,1,'شیشهٔ باده و طلعت خوش زیبایی',NULL,NULL);
INSERT INTO "verses" VALUES(1940575,78315,1,0,'آرزو می‌کندم از تو چه پنهان دارم','هوش مصنوعی: آرزو می‌کنم از تو چه چیزهایی را پنهان کنم؛ شیشه‌ی شراب و چهره‌ی زیبای تو.',NULL);
INSERT INTO "verses" VALUES(1940576,78315,0,1,'که به پیرانه سرم دست دهد ماوایی',NULL,NULL);
INSERT INTO "verses" VALUES(1940577,78315,0,0,'خوشتر از کوی خرابات نباشد جایی','هوش مصنوعی: هیچ جایی بهتر از محله‌ی خراباتی‌ها نیست که در سن پیری بتوانم در آنجا پناه بگیرم.',NULL);
INSERT INTO "verses" VALUES(1940578,78314,4,1,'یافتى در هر دو عالم رتبت عز و علا',NULL,NULL);
INSERT INTO "verses" VALUES(1940579,78314,4,0,'حافظا گر پای‌بوس شاه دستت مى‌دهد','هوش مصنوعی: حافظ، اگر دستانت را به عنوان سوگند به شاه بگذاری، در هر دو جهان، مقام بلند و عزت و عظمت را به دست می‌آوری.',NULL);
INSERT INTO "verses" VALUES(1940580,78314,3,1,'پنج‌روز ایّام عشرت را غنیمت دان دلا',NULL,NULL);
INSERT INTO "verses" VALUES(1940581,78315,3,0,'چه کنی نوش که در دیر چو من شیدا نیست','هوش مصنوعی: چه کار می‌توانی بکنی وقتی در میخانه کسی مانند من دیوانه وجود ندارد؟ این تنها سخن بازیگوشی است.',NULL);
INSERT INTO "verses" VALUES(1940582,78314,3,0,'وقت عیش و موسم شادى و هنگام طرب','هوش مصنوعی: در زمان خوشی و شادی و لذت، به مدت پنج روز، از ایام شادابی و خوشگذرانی بهره‌مند شو، ای دل.',NULL);
INSERT INTO "verses" VALUES(1940583,78314,2,0,'ترک ما گر مى‌کند رندى و مستى جان من','هوش مصنوعی: اگر محبوب من با می‌نوشی و رندی از من دور شود، جان من باید ابتدا زهد و تقوای خود را کنار بگذارد.',NULL);
INSERT INTO "verses" VALUES(1940584,78314,1,1,'کس ندیده در جهان جز کشتگان کربلا',NULL,NULL);
INSERT INTO "verses" VALUES(1940585,78314,1,0,'آنچه جان عاشقان از دست هجرت مى‌کشد','هوش مصنوعی: عاشقانی که به خاطر دوری از معشوق رنج می‌برند، هیچ‌کس جز شهدای کربلا چنین درد و رنجی را تجربه نکرده است.',NULL);
INSERT INTO "verses" VALUES(1940586,78314,0,1,'جان و دل افتاده‌ اندر زلف و خالت در بلا',NULL,NULL);
INSERT INTO "verses" VALUES(1940587,78314,0,0,'تا جمالت عاشقان را زد به وصل خود صلا','هوش مصنوعی: چهره زیبای تو عاشقان را به عشق و وصال می‌کشد و جان و دل آنها در زلف و زیبایی تو گرفتار شده است.',NULL);
INSERT INTO "verses" VALUES(1940588,78313,4,0,'تا به کى با تلخى هجر تو سازد اى صنم','هوش مصنوعی: ای معشوق، تا کی باید با تلخی جدایی تو زندگی کنم؟ به من نگاه کن تا حافظ، چهره زیبای تو را ببیند.',NULL);
INSERT INTO "verses" VALUES(1940589,78313,4,1,'روى بنما تا ببیند حافظ ما، روت را',NULL,NULL);
INSERT INTO "verses" VALUES(1940590,78313,3,0,'بوى گل برخاست گویى در چمن‌ها، روت بود','هوش مصنوعی: عطر گل‌ها در هوا پیچیده و گویی در باغ‌ها بوی خوشی حس می‌شود. بلبلان را می‌بینیم که به خاطر زیبایی تو، سرمست و شاداب هستند. گویی آن‌ها نیز مانند ما به تماشای چهره‌ات مشغولند و تحت تأثیر زیبایی‌ات قرار گرفته‌اند.',NULL);
INSERT INTO "verses" VALUES(1940591,78313,3,1,'بلبلان مستند گویى دیده چون ما، روت را',NULL,NULL);
INSERT INTO "verses" VALUES(1940592,78314,2,1,'ترک مستورى و زهدت کرد باید اولا',NULL,NULL);
INSERT INTO "verses" VALUES(1940593,78315,3,1,'نیست این جز سخن بوالهوس رعنایی',NULL,NULL);
INSERT INTO "verses" VALUES(1940594,78315,4,0,'به ادب باش که هر کس نتواند گفتن','مؤدب و متواضع باش زیرا هرکس سخن پیر را نمی‌تواند نقل کند مگر برهمن یا را باشد.',NULL);
INSERT INTO "verses" VALUES(1940595,78315,4,1,'سخن پیر مگر برهمنی یا رایی',NULL,NULL);
INSERT INTO "verses" VALUES(1940596,78316,8,0,'ما بنده‌ایم و عاجز تو حاکمی و قادر','هوش مصنوعی: ما در برابر تو بندگان درمانده‌ایم و تو حاکم و توانمند هستی. اگر بخواهی با قدرت می‌کشی ما را و اگر بخواهی با ناله و زاری.',NULL);
INSERT INTO "verses" VALUES(1940597,78316,7,1,'تا زنده‌ام نورزم آیین هوشیاری',NULL,NULL);
INSERT INTO "verses" VALUES(1940598,78316,7,0,'از بادهٔ وصالت گر جرعه‌ای بنوشم','هوش مصنوعی: اگر از خوشی و وصال تو جرعه‌ای بنوشم، تا زمانی که زنده‌ام، به هوشیاری و آگاهی خود ادامه می‌دهم.',NULL);
INSERT INTO "verses" VALUES(1940599,78316,6,1,'سر بر نیارم از خاک از روی شرمساری',NULL,NULL);
INSERT INTO "verses" VALUES(1940600,78316,6,0,'گرچه به بوی وصلت در حشر زنده گردم','هوش مصنوعی: با اینکه در روز قیامت با بوی وصال تو زنده می‌شوم، از روی شرم سرم را از خاک برنمی‌دارم.',NULL);
INSERT INTO "verses" VALUES(1940601,78316,5,1,'از بوستان وصلت بوی امیدواری',NULL,NULL);
INSERT INTO "verses" VALUES(1940602,78316,5,0,'در هجر مانده بودم باد صبا رسانید','هوش مصنوعی: در دوری تو به سر می‌بردم که باد صبا، بویی از بوستان عشق و امید را به من رساند.',NULL);
INSERT INTO "verses" VALUES(1940603,78316,4,1,'دلهای همچو آتش چشمان رود باری',NULL,NULL);
INSERT INTO "verses" VALUES(1940604,78316,4,0,'اسباب عاشقی را بسیار مایه باید','هوش مصنوعی: برای عاشق شدن، انسان نیاز به عوامل و شرایط زیادی دارد، زیرا دل‌هایی که مانند آتش می‌سوزند، بسیار شایسته و مستحق عشق هستند.',NULL);
INSERT INTO "verses" VALUES(1940605,78316,3,1,'گر شمه‌ای بدانی دانم که رحمت آری',NULL,NULL);
INSERT INTO "verses" VALUES(1940606,78316,3,0,'دردی که از تو دارم جوری که از تو بینم','هوش مصنوعی: دردی که از تو دارم به گونه‌ای است که اگر تو کمترین خبری از آن داشته باشی، متوجه می‌شوم که مهر و محبتت نثار می‌شود.',NULL);
INSERT INTO "verses" VALUES(1940607,78316,2,1,'تا چند همچو زلفت در تاب و بی قراری',NULL,NULL);
INSERT INTO "verses" VALUES(1940608,78316,2,0,'تا چند همچو چشمت در عین ناتوانی','هوش مصنوعی: چقدر دیگر باید در برابر چشمان ناتوانت تسلیم باشم؟ چقدر دیگر باید از پیچ و تاب موهایت آشفته و بی‌قرار بمانم؟',NULL);
INSERT INTO "verses" VALUES(1940609,78316,1,1,'بر بیدلان مسکین تا کی جفا و خواری',NULL,NULL);
INSERT INTO "verses" VALUES(1940610,78316,1,0,'با عاشقان بیدل تا چند ناز و عشوه','هوش مصنوعی: تا کی می‌خواهی با عاشقان بی‌خبر ناز و عشوه کنی و به بیدلان بیچاره ظلم و بی‌رحمی را ادامه بدهی؟',NULL);
INSERT INTO "verses" VALUES(1940611,78316,0,1,'شاید که عاشقان را کامی ز لب بر آری',NULL,NULL);
INSERT INTO "verses" VALUES(1940612,78316,0,0,'چون در جهان خوبی امروز کامکاری','هوش مصنوعی: امروز در دنیای خوب و خوش، ممکن است که عشق ورزیدن موجب خوشحالی عاشقان شود و این عشق لبخند و شادی را برای آن‌ها به ارمغان آورد.',NULL);
INSERT INTO "verses" VALUES(1940613,78315,6,1,'زآن که هست از پی امروز یقین فردایی',NULL,NULL);
INSERT INTO "verses" VALUES(1940614,78315,6,0,'رحم کن بر دل مجروح خراب حافظ','هوش مصنوعی: به دل شکسته و آسیب‌دیده حافظ رحم کن، زیرا امروز هر چه که باشد، بدون تردید فردایی در پیش است.',NULL);
INSERT INTO "verses" VALUES(1940615,78315,5,1,'که مرا نیست به غیر از تو به کس پروایی',NULL,NULL);
INSERT INTO "verses" VALUES(1940616,78315,5,0,'صنما غیر تو در خاطر ما کی گنجد','هوش مصنوعی: ما هیچ کسی را جز تو در ذهن نداریم و هیچ توجهی به دیگران نمی‌کنیم.',NULL);
INSERT INTO "verses" VALUES(1940617,78313,2,0,'کى شدى هاروت در چاه زنخدانش اسیر','هوش مصنوعی: چه زمانی هاروت در چاه زنخدانش گرفتار شد؟ اگر از زیبایی او چیزی نمی‌گفتی، ماروت نیز به چنین حالتی نمی‌افتاد.',NULL);
INSERT INTO "verses" VALUES(1940618,78316,8,1,'گر می‌کشی به زورم ور می‌کشی به زاری',NULL,NULL);
INSERT INTO "verses" VALUES(1940619,78313,2,1,'گر نگفتى شمه‌اى از حسن او ماروت را',NULL,NULL);
INSERT INTO "verses" VALUES(1940620,78313,1,0,'همچو هاروتیم دایم در بلاى عشق زار','هوش مصنوعی: مانند هاروت و ماروت، دائماً در درد و رنج عشق به سر می‌برم. ای کاش هرگز چشمان تو را نمی‌دیدم و روی تو را نمی‌دیدم.',NULL);
INSERT INTO "verses" VALUES(1940621,78311,1,0,'ای کاخ دولتی ز چه خاکی؟ که مدرج است','هوش مصنوعی: این کاخ حکومتی از چه چیزی ساخته شده است که در میان گل‌ها قرار دارد و سایه‌ای از شکوه بر آن می‌افتد؟',NULL);
INSERT INTO "verses" VALUES(1940622,78311,0,1,'زین در به شادمانی و عیش و طرب در آی',NULL,NULL);
INSERT INTO "verses" VALUES(1940623,78311,0,0,'جای حضور و گلشن امن است این سرای','هوش مصنوعی: این خانه مکانی امن و خوشبو است؛ از این در وارد شو و به شادی و خوشی در آن بپرداز.',NULL);
INSERT INTO "verses" VALUES(1940624,78310,7,1,'چرا عمری به غفلت می گذاری',NULL,NULL);
INSERT INTO "verses" VALUES(1940625,78310,7,0,'بیا حافظ به پند تلخ کن نوش','هوش مصنوعی: بیا حافظ، به خاطر پند تلخی که هست، از نوشی که میخوری بگذر. چرا در تمام عمرت غافل و بی‌توجه بوده‌ای؟',NULL);
INSERT INTO "verses" VALUES(1940626,78310,6,1,'چو بر طرف چمن باد بهاری',NULL,NULL);
INSERT INTO "verses" VALUES(1940627,78310,6,0,'عزیزا نوبهار عمر بگذشت','هوش مصنوعی: عزیذ، بهار زندگی‌ات سپری شده است، مانند بادی که بهاری می‌وزد و برگ‌های چمن را به حرکت درمی‌آورد.',NULL);
INSERT INTO "verses" VALUES(1940628,78310,5,1,'که عهد گل ندارد استواری',NULL,NULL);
INSERT INTO "verses" VALUES(1940629,78310,5,0,'به دور گل خدا را توبه بشکن','هوش مصنوعی: به دور گل، توبه‌ات را بشکن، زیرا که گل به عهد و پیمان خود پایبند نیست.',NULL);
INSERT INTO "verses" VALUES(1940630,78311,1,1,'در شاخسار گلشن تو سایهٔ همای',NULL,NULL);
INSERT INTO "verses" VALUES(1940631,78310,4,1,'اگر خواهی خلاصی رستگاری',NULL,NULL);
INSERT INTO "verses" VALUES(1940632,78310,3,1,'که کردم توبه از پرهیزکاری',NULL,NULL);
INSERT INTO "verses" VALUES(1940633,78310,3,0,'بپرهیز از من ای صوفی بپرهیز','هوش مصنوعی: ای صوفی، از من دوری کن که من از پرهیزکاری توبه کرده‌ام.',NULL);
INSERT INTO "verses" VALUES(1940634,78310,2,1,'که مستی خوشتر است از هوشیاری',NULL,NULL);
INSERT INTO "verses" VALUES(1940635,78310,2,0,'مرا در رسته دیوانگان کش','هوش مصنوعی: مرا به جمع دیوانگان ببر زیرا حال مستی بهتر از حالت هوشیاری است.',NULL);
INSERT INTO "verses" VALUES(1940636,78310,1,1,'بیا ساقی بیاور آنچه داری',NULL,NULL);
INSERT INTO "verses" VALUES(1940637,78310,1,0,'به جز ساغر چه دارد لاله در دست','هوش مصنوعی: لاله فقط ساغر را در دست دارد، بیا ای ساقی، هرچه را که داری بیاور.',NULL);
INSERT INTO "verses" VALUES(1940638,78310,0,1,'که دارم همچو تو امیدواری',NULL,NULL);
INSERT INTO "verses" VALUES(1940639,78310,0,0,'برو زاهد به امیدی که داری','هوش مصنوعی: ای زاهد، با امیدی که برای خود داری برو؛ اما بدان که من هم همچون تو امیدوارم.',NULL);
INSERT INTO "verses" VALUES(1940640,78309,7,1,'گر طاقت انتظار داری!',NULL,NULL);
INSERT INTO "verses" VALUES(1940641,78310,4,0,'بیا دل در خم گیسوی او بند','هوش مصنوعی: در اینجا گفته می‌شود که اگر می‌خواهی به آرامش و رستگاری دست یابی، باید به عشق و زیبایی او توجه کنی و دل خود را به او بسپاری.',NULL);
INSERT INTO "verses" VALUES(1940642,78311,2,0,'هر صبح در هوای درت می‌کند صبوح','هوش مصنوعی: هر روز صبح، در هوای درگاه تو، جمشید با شادابی و نشئگی، تخت‌های آسمان را به یادگار می‌آورد و با نگاهی به جامی که جهان را نشان می‌دهد، به تماشا می‌نشیند.',NULL);
INSERT INTO "verses" VALUES(1940643,78311,2,1,'جمشید تخت چرخ به جام جهان‌نمای',NULL,NULL);
INSERT INTO "verses" VALUES(1940644,78311,3,0,'فرخنده نوگل تو چمن را حیات‌ده','هوش مصنوعی: گل زیبای تو زندگی به باغ می‌بخشد و موهای بنفشه‌گون تو، بادی را که می‌وزد به آرامش و سامان می‌آورد.',NULL);
INSERT INTO "verses" VALUES(1940645,78313,0,0,'لطف باشد گر نپوشى از گداها، روت را','هوش مصنوعی: اگر بر گداها و نیازمندان بگذری و روی زیبا تو را ببینند، برای ما هم این لطف بزرگی است.',NULL);
INSERT INTO "verses" VALUES(1940646,78313,0,1,'تا به کام دل ببیند دیدهٔ ما، روت را',NULL,NULL);
INSERT INTO "verses" VALUES(1940647,78312,6,1,'به یک جو ملکت کاووس کى را',NULL,NULL);
INSERT INTO "verses" VALUES(1940648,78312,6,0,'چو بی‌خود گشت حافظ کى شمارد','هوش مصنوعی: وقتی حافظ در حال بی‌خود شدن است، چگونه می‌تواند یک لحظه را به اندازهٔ یک ملک وسیع و بزرگ مانند ملک کاووس ارزش‌گذاری کند؟',NULL);
INSERT INTO "verses" VALUES(1940649,78312,5,1,'جزاک الله فى الدّارین خیرا',NULL,NULL);
INSERT INTO "verses" VALUES(1940650,78312,5,0,'حماک الله عن شرّ النوائب','هوش مصنوعی: خداوند تو را از بدی‌های سختی‌ها حفظ کند و در دو جهان، پاداش نیکو به تو عطا کند.',NULL);
INSERT INTO "verses" VALUES(1940651,78312,4,1,'چو پیمودى پیاپى جام مى را',NULL,NULL);
INSERT INTO "verses" VALUES(1940652,78312,4,0,'رهانیدى مرا از قید هستى','هوش مصنوعی: مرا از بند زندگی آزاد کردی، همان‌طور که با نوشیدن پشت سر هم جام شراب، به حالتی دیگر منتقل می‌شوم.',NULL);
INSERT INTO "verses" VALUES(1940653,78312,3,1,'بگفتم ساقى فرخنده پى را',NULL,NULL);
INSERT INTO "verses" VALUES(1940654,78312,3,0,'چو شوقم دید در ساغر مى‌ افزود','هوش مصنوعی: وقتی شوق و اشتیاق من را دید، شروع به ریختن بیشتر می کرد. به او گفتم که ای ساقی، این کارت مایه خوشبختی است.',NULL);
INSERT INTO "verses" VALUES(1940655,78312,2,1,'ز زلف و رخ نمودى شمس و فى را',NULL,NULL);
INSERT INTO "verses" VALUES(1940656,78312,2,0,'حریفى بد مرا ساقى که در شب','هوش مصنوعی: دوست من، ساقی، در شبی که با زلف و چهره‌ات روشنایی را به تصویر کشیدی، حریفی بد برای من شدی.',NULL);
INSERT INTO "verses" VALUES(1940657,78312,1,1,'که بى‌رقّت ندیدم هیچ شی را',NULL,NULL);
INSERT INTO "verses" VALUES(1940658,78312,1,0,'چنان در سوز من سازش اثر کرد','هوش مصنوعی: آن‌چنان تأثیر سوز و گداز در دل من گذاشت که دیگر هیچ چیز را بی‌احساس و بی‌تفاوت ندیدم.',NULL);
INSERT INTO "verses" VALUES(1940659,78312,0,1,'شنیدم نالهٔ جانسوز نى را',NULL,NULL);
INSERT INTO "verses" VALUES(1940660,78312,0,0,'شب از مطرب که دل خوش باد وی را','هوش مصنوعی: شب هنگام، از خواننده‌ای که دل را شاد می‌کرد، ناله‌ای غم‌انگیز از نی را شنیدم.',NULL);
INSERT INTO "verses" VALUES(1940661,78311,5,1,'کاندر بهشت بهتر از این گوشه نیست جای',NULL,NULL);
INSERT INTO "verses" VALUES(1940662,78311,5,0,'حافظ مقیم درگه او باش و عیش کن','هوش مصنوعی: در خانه‌ی او بمان و خوش بگذران، چون در بهشت جایی بهتر از این گوشه وجود ندارد.',NULL);
INSERT INTO "verses" VALUES(1940663,78311,4,1,'جمشید در حریم تو چون بندگان بپای',NULL,NULL);
INSERT INTO "verses" VALUES(1940664,78311,4,0,'خورشید در هوای تو چون ذره پای‌کوب','هوش مصنوعی: خورشید در حضور تو مانند ذره‌ای است که به پای جمشید می‌رقصید و در آستانه تو، مانند بندگانی که در خدمت هستند، سر تعظیم فرود آورده‌اند.',NULL);
INSERT INTO "verses" VALUES(1940665,78311,3,1,'جعد بنفشهٔ تو صبا را گره‌گشای',NULL,NULL);
INSERT INTO "verses" VALUES(1940666,78313,1,1,'کاشکى هرگز ندیدى دیدهٔ ما، روت را',NULL,NULL);
INSERT INTO "verses" VALUES(1940667,78309,7,0,'روزی برسی به وصل! حافظ','هوش مصنوعی: اگر صبر و استقامت داشته باشی، روزی به وصال محبوب خواهی رسید!',NULL);
INSERT INTO "verses" VALUES(1940668,78316,9,0,'آخر ترحمی کن بر حال زار حافظ','هوش مصنوعی: لطفاً بر حال بد حافظ رحم کن، دیگر چه مدت باید ناامید و خوار باشد؟',NULL);
INSERT INTO "verses" VALUES(1940669,78317,0,0,'ساقی اگرت هوای ما هی،','هوش مصنوعی: ای ساقی، اگر هرگز به یاد ما هستی، جز شراب هیچ چیزی در پیش ما قبول نکن!',NULL);
INSERT INTO "verses" VALUES(1940670,78322,1,1,'بشنو که چنین گفت مرا پاک سرشتی',NULL,NULL);
INSERT INTO "verses" VALUES(1940671,78322,1,0,'زنگ غمت از دل می خون‌رنگ برد پاک','این را بشنو زیرا از آدمی پاک و پاکیزه‌سرشت شنیده‌ام که گفت: زنگ و کدورت غم را می و شراب سرخ از دل می‌شوید.',NULL);
INSERT INTO "verses" VALUES(1940672,78322,0,1,'ساقی می گلرنگ طلب بر لب کشتی',NULL,NULL);
INSERT INTO "verses" VALUES(1940673,78322,0,0,'اکنون که ز گل باز چمن شد چو بهشتی','هوش مصنوعی: اکنون که گل‌ها از باغ بیرون آمده‌اند و بهشتی شده‌اند، ای ساقی! شراب گل‌رنگ را بیاور و بر لبان کشتی بگذار.',NULL);
INSERT INTO "verses" VALUES(1940674,78321,1,1,'من دانم و آن که آفریده‌ست مرا',NULL,NULL);
INSERT INTO "verses" VALUES(1940675,78321,1,0,'چندان غم هجران تو بر دل دارم','هوش مصنوعی: من از دوری تو غم و اندوه زیادی دارم و خودم این احساس را می‌شناسم، همچنین خالق من نیز از این وضعیت آگاه است.',NULL);
INSERT INTO "verses" VALUES(1940676,78321,0,1,'کس با لب پر خنده ندیده‌ست مرا',NULL,NULL);
INSERT INTO "verses" VALUES(1940677,78321,0,0,'روزی که فلک از تو بریده‌ست مرا','هوش مصنوعی: در روزی که آسمان از من دور شده و به تو بی‌توجه است، هیچ‌کس مرا در حالتی شاد و با لبخند ندیده است.',NULL);
INSERT INTO "verses" VALUES(1940678,78320,6,1,'از طرز شعر حافظ در بزم شاهزاده',NULL,NULL);
INSERT INTO "verses" VALUES(1940679,78322,2,0,'گر محتسبت بر کدوی باده زند سنگ','هوش مصنوعی: اگر نگهبان شراب بر کدو سنگ پرتاب کند، تو هم بر کدوی او سنگ بزن.',NULL);
INSERT INTO "verses" VALUES(1940680,78320,6,0,'مطرب چو پرده سازد شاید اگر بخواهند','هوش مصنوعی: هنگامی که نوازنده ساز را به صدا درآورد، ممکن است اگر بخواهند، از سبک شعر حافظ در محفل شاهزاده استفاده کنند.',NULL);
INSERT INTO "verses" VALUES(1940681,78320,5,0,'در مجلس صبوحی دانی چه خوش نماید','هوش مصنوعی: در مجلس صبحانه، چهره زیبا و دل‌انگیز ساقی هنگامیکه در جام شراب منعکس می‌شود، چه حالی به دل می‌بخشد.',NULL);
INSERT INTO "verses" VALUES(1940682,78320,4,1,'بی­ بانگ رود و چنگ و بی یار و جام باده',NULL,NULL);
INSERT INTO "verses" VALUES(1940683,78320,4,0,'گل رفت ای حریفان غافل چرا نشینید','هوش مصنوعی: ای دوستان، گل رفته است و شما غافل نشسته‌اید، چرا به دور از صدای رود، نواهای چنگ، دوستان و باده وقتتان را تلف می‌کنید؟',NULL);
INSERT INTO "verses" VALUES(1940684,78320,3,1,'گر عاشقی طرب جوی، با ساقیان ساده',NULL,NULL);
INSERT INTO "verses" VALUES(1940685,78320,3,0,'این یک دو روز دیگر گل را غنیمتی دان','هوش مصنوعی: در این دو روز آینده، از زیبایی گل بهره‌مند شو؛ اگر عاشق هستی و به شادی می‌اندیشی، با دوستانی بی‌غل و غش همراه باش.',NULL);
INSERT INTO "verses" VALUES(1940686,78320,2,1,'امروز دیدمش مست، تقوا به باد داده',NULL,NULL);
INSERT INTO "verses" VALUES(1940687,78320,2,0,'صوفی که دی نصیحت می­کرد عاشقان را','هوش مصنوعی: دیدم صوفی‌ای که دیروز عاشقان را نصیحت می‌کرد، امروز در حال مستی به سر می‌برد و دیگر به تقوا اهمیتی نمی‌دهد.',NULL);
INSERT INTO "verses" VALUES(1940688,78320,1,1,'ساقی بده شرابی تا دل شود گشاده',NULL,NULL);
INSERT INTO "verses" VALUES(1940689,78320,1,0,'زین زهد و پارسایی بگرفت خاطر من','هوش مصنوعی: به‌خاطر زهد و پارسایی، دل من گرفته شده است. ای ساقی، شرابی به من بده تا دلم باز و شاد شود.',NULL);
INSERT INTO "verses" VALUES(1940690,78320,5,1,'عکس عذار ساقی در جام می فتاده',NULL,NULL);
INSERT INTO "verses" VALUES(1940691,78322,2,1,'بشکن تو کدوی سر او نیز به خشتی',NULL,NULL);
INSERT INTO "verses" VALUES(1940692,78322,3,0,'آمرزش نقد است کسی را که در اینجا','هوش مصنوعی: کسی که در این دنیا به دیگران کمک و یاری می‌رساند، مانند موجودی است تماشایی و جذاب، که بهشت و نعمت‌های آن را به یاد می‌آورد.',NULL);
INSERT INTO "verses" VALUES(1940693,78322,3,1,'یاریست چو حوری و سرایی چو بهشتی',NULL,NULL);
INSERT INTO "verses" VALUES(1940694,78326,1,1,'بر چهرهٔ جان داغ ستم‌ها دارد',NULL,NULL);
INSERT INTO "verses" VALUES(1940695,78326,0,0,'راه طلب تو خار غم‌ها دارد','هوش مصنوعی: راه رسیدن به تو پر از غم‌ها و سختی‌هاست. آیا کسی هست که با این همه رنج و زحمت به این مسیر ادامه دهد؟',NULL);
INSERT INTO "verses" VALUES(1940696,78326,0,1,'کو راهروى که این قدم‌ها دارد؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940697,78325,1,1,'کابواب سعادت همه مفتوح شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940698,78325,1,0,'امید من آن است به درگاه خدا','از درگاه خدا می‌خواهم که درهای نیکبختی همگی باز شوند.',NULL);
INSERT INTO "verses" VALUES(1940699,78325,0,1,'یا ملک دلم بی ملک روح شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940700,78325,0,0,'یا کار به کام دل مجروح شود','یا به مطلوب دلم می‌رسم و یا جانم را در این راه می‌بازم',NULL);
INSERT INTO "verses" VALUES(1940701,78324,1,1,'المنة لله که حکایت باقیست',NULL,NULL);
INSERT INTO "verses" VALUES(1940702,78324,1,0,'گستاخی ما ز حد برون رفت ولی','هوش مصنوعی: بدخلقانی ما به میزان زیادی فراتر از حد خود رفته‌است، اما سپاس خدا را که این داستان هنوز ادامه دارد.',NULL);
INSERT INTO "verses" VALUES(1940703,78324,0,1,'شکر تو نگفتیم و شکایت باقیست',NULL,NULL);
INSERT INTO "verses" VALUES(1940704,78324,0,0,'شب رفت به پایان و حکایت باقیست','هوش مصنوعی: شب به پایان رسیده و داستان هنوز ادامه دارد. ما از تو سپاس نگفتیم و دلخوری‌ها و شکایت‌ها هنوز باقی است.',NULL);
INSERT INTO "verses" VALUES(1940705,78323,1,1,'تا سر جهان بگویمت ای سره مرد',NULL,NULL);
INSERT INTO "verses" VALUES(1940706,78323,1,0,'مستم کن و بی خبر ز احوال جهان','هوش مصنوعی: مرا به حال خود مشغول کن و از وضعیت دنیا بی‌خبر بگذار تا زمانی که به انتهای دنیا برسم، با تو صحبت کنم، ای مرد باکمال.',NULL);
INSERT INTO "verses" VALUES(1940707,78323,0,1,'در ده که تراز عمر نو خواهم کرد',NULL,NULL);
INSERT INTO "verses" VALUES(1940708,78323,0,0,'زآن بادهٔ دیرینهٔ دهقان پرورد','هوش مصنوعی: من از آن نوشیدنی سنتی و قدیمی که توسط دهقانان تهیه شده در دهکده می‌نوشم، تا به‌نوعی عمر تازه‌ای برای خود به دست بیاورم.',NULL);
INSERT INTO "verses" VALUES(1940709,78322,6,1,'حیف است که هر دم کند آهنگ کنشتی',NULL,NULL);
INSERT INTO "verses" VALUES(1940710,78322,6,0,'ترسا بچه‌ای دوش همی‌گفت که حافظ','هوش مصنوعی: دیروز فردی از اهل دین می‌گفت که خیلی حیف است حافظ هر لحظه بخواهد به سمت می‌خانه برود و آواز بخواند.',NULL);
INSERT INTO "verses" VALUES(1940711,78322,5,1,'گر بالش زر نیست بسازیم به خشتی',NULL,NULL);
INSERT INTO "verses" VALUES(1940712,78322,5,0,'بر خاک در خواجه که ایوان جلال‌است','هوش مصنوعی: در زمین آن بزرگوار که زیر سایه‌اش عظمت و شکوه وجود دارد، اگر بالشت طلا نداریم، با خشت هم می‌توانیم چیزی بسازیم تا سر بر زمین او بگذاریم.',NULL);
INSERT INTO "verses" VALUES(1940713,78322,4,1,'آنجا که بصر نیست چه خوبی و چه زشتی',NULL,NULL);
INSERT INTO "verses" VALUES(1940714,78322,4,0,'جهل من و علم تو فلک را چه تفاوت','هوش مصنوعی: نا آگاهی من و دانش تو برای آسمان اهمیتی ندارد، زیرا وقتی که ناظر یا نگاهی وجود ندارد، نه زیبایی مشخص است و نه زشتی.',NULL);
INSERT INTO "verses" VALUES(1940715,78320,0,1,'هنگام گل که دیده بی می قدح نهاده',NULL,NULL);
INSERT INTO "verses" VALUES(1940716,78316,9,1,'تا چند ناامیدی تا چند خاکساری',NULL,NULL);
INSERT INTO "verses" VALUES(1940717,78320,0,0,'عید است و موسم گل، ساقی بیار باده','هوش مصنوعی: عید و فصل شکوفایی گل‌ها فرارسیده است، ای ساقی، برایم شراب بیاور تا در این وقت زیبا با چشم‌هایی که جام در دست دارند، از آن بنوشیم.',NULL);
INSERT INTO "verses" VALUES(1940718,78319,6,0,'حافظ خوشخوان من نقد کمال غیاث','هوش مصنوعی: این بیت به توانایی و مهارت حافظ در شعر و ادبیات اشاره دارد. شاعر به وصف و ستایش حافظ می‌پردازد و او را به عنوان نمونه‌ای برتر از کمال و زیبایی در شعر معرفی می‌کند. به عبارتی، این بیان‌یادآور این است که آثار حافظ در اوج زیبایی و فصاحت قرار دارد.',NULL);
INSERT INTO "verses" VALUES(1940719,78318,0,0,'برو ای طبیبم از سر که خبر ز سر ندارم','ای طبیب‌، زحمت را کم کن که از خود بی‌خبرم و از بیماری و صحت خود آگاه نیستم؛ جان مرا به‌دست خدا بسپار و برو که از مرگ و زندگی خود نیز خبر ندارم.',NULL);
INSERT INTO "verses" VALUES(1940720,78317,9,3,'جان در سرو کار عشق بازم',NULL,NULL);
INSERT INTO "verses" VALUES(1940721,78317,9,2,'بنشینم و با غم تو سازم','هوش مصنوعی: من در کنار تو می‌نشینم و با غم و اندوهت کنار می‌آیم و زندگی‌ام را در عشق بازسازی می‌کنم.',NULL);
INSERT INTO "verses" VALUES(1940722,78317,8,1,'آخر من دلشکسته تا کی',NULL,NULL);
INSERT INTO "verses" VALUES(1940723,78317,8,0,'حافظ ز غم تو چند نالد','هوش مصنوعی: حافظ از شدت غم تو چقدر باید ناله کند؟ آخر من با دل شکسته‌ام، اما این وضعیت تا کی ادامه خواهد داشت؟',NULL);
INSERT INTO "verses" VALUES(1940724,78317,7,1,'وز شرم گرفته عارضش خوی',NULL,NULL);
INSERT INTO "verses" VALUES(1940725,78317,7,0,'مردم نگران به روی خوبش','هوش مصنوعی: مردم نگران زیبایی چهره او هستند و از شرمی که بر چهره‌اش نشسته، بهت‌زده‌اند.',NULL);
INSERT INTO "verses" VALUES(1940726,78317,6,1,'می آمد و خلق شهر در پی',NULL,NULL);
INSERT INTO "verses" VALUES(1940727,78317,6,0,'سلطان صفت آن بت پری روی','هوش مصنوعی: یک فرد با زیبایی و جذبه‌ای مانند سلطان، از دور می‌آمد و مردم شهر به دنبال او بودند.',NULL);
INSERT INTO "verses" VALUES(1940728,78318,0,1,'به خدا رها کنم جان که ز جان خبر ندارم',NULL,NULL);
INSERT INTO "verses" VALUES(1940729,78317,5,1,'بهتر ز هزار حاتم طی',NULL,NULL);
INSERT INTO "verses" VALUES(1940730,78317,4,1,'آواز سماع و نالهٔ نی',NULL,NULL);
INSERT INTO "verses" VALUES(1940731,78317,4,0,'اسرار دل است در ره عشق','هوش مصنوعی: در عشق، دل پر از رازهایی است که با نغمه‌های خوش و صدای نی به گوش می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1940732,78317,3,1,'کونین نگر ز عشق لاشی',NULL,NULL);
INSERT INTO "verses" VALUES(1940733,78317,3,0,'با درد درآ به بوی درمان','هوش مصنوعی: با درد خود به جستجوی درمان بیا، زیرا عشق مانند دارویی کشنده است که به تو کمک می‌کند.',NULL);
INSERT INTO "verses" VALUES(1940734,78317,2,1,'در گلشن جان ندای یا حی',NULL,NULL);
INSERT INTO "verses" VALUES(1940735,78317,2,0,'گر زنده دلی شنو ز مستان','هوش مصنوعی: اگر دل زنده و زنده‌ای داری، صدای خوش و شاداب مستان را در گلشن جان بشنو که ندا می‌دهد: ای زندگی!',NULL);
INSERT INTO "verses" VALUES(1940736,78317,1,1,'بفروش و بیار جرعه ای می',NULL,NULL);
INSERT INTO "verses" VALUES(1940737,78317,1,0,'سجّاده و خرقه در خرابات','هوش مصنوعی: فرش و لباس ریا را در مکان‌های خراب و ناپسند بفروش و یک جرعه شراب بیاور.',NULL);
INSERT INTO "verses" VALUES(1940738,78317,0,1,'جز باده مباد نزد ما هی!',NULL,NULL);
INSERT INTO "verses" VALUES(1940739,78317,5,0,'یک مفلس پاک باز در عشق','هوش مصنوعی: یک فرد بی‌پول و صادق در عشق، از هزاران شخص ثروتمند و بخشنده برتر است.',NULL);
INSERT INTO "verses" VALUES(1940740,78318,1,0,'به عیادتم قدم نه که ز بی‌خودی شوم به','(ای محبوب من) تو برای دیدار و عیادت من بیا تا از این بی‌خودی و گم‌گشتگی رها شوم؛ برایم باده بریز و خود نیز بنوش که جز این چیزی نمی‌خواهم.',NULL);
INSERT INTO "verses" VALUES(1940741,78318,1,1,'می ناب نوش و هم ده که غم دگر ندارم',NULL,NULL);
INSERT INTO "verses" VALUES(1940742,78318,2,0,'غمم ار خوری از این پس نکنم ز غم خوری بس','اگر به من توجه کنی و با من باشی‌، از این پس هیچ غمی نخواهم داشت؛ به‌جز تو میل به دیگری ندارم.',NULL);
INSERT INTO "verses" VALUES(1940743,78319,5,1,'قامت دلجوی توست سرو گلستان من',NULL,NULL);
INSERT INTO "verses" VALUES(1940744,78319,5,0,'سرو گلستان من قامت دلجوی توست','هوش مصنوعی: درخت سرو در باغ من، نماد زیبایی و قامت دلبر تو است.',NULL);
INSERT INTO "verses" VALUES(1940745,78319,4,1,'مصر ملاحت تر است یوسف کنعان من',NULL,NULL);
INSERT INTO "verses" VALUES(1940746,78319,4,0,'یوسف کنعان من مصر ملاحت تر است','هوش مصنوعی: یوسف اهل کنعان من، در مصر جذاب‌تر و دلنشین‌تر است.',NULL);
INSERT INTO "verses" VALUES(1940747,78319,3,1,'واله و شیدای تست این دل حیران من',NULL,NULL);
INSERT INTO "verses" VALUES(1940748,78319,3,0,'این دل حیران من واله شیدای تست','هوش مصنوعی: دل بی‌خبر من به شدت تحت تاثیر تو است و کاملاً شیدا و مجنون تو شده است.',NULL);
INSERT INTO "verses" VALUES(1940749,78319,2,1,'خاک سر کوی دوست روضه ی رضوان من',NULL,NULL);
INSERT INTO "verses" VALUES(1940750,78319,2,0,'روضه ی رضوان من خاک سر کوی دوست','هوش مصنوعی: بهشت من و خوشبختی‌ام در خاک خیابان دوست قرار دارد و عشق به او برای من همانند بهشت است.',NULL);
INSERT INTO "verses" VALUES(1940751,78319,1,1,'زنده شود جان من از لب جانان من',NULL,NULL);
INSERT INTO "verses" VALUES(1940752,78319,1,0,'از لب جانان من زنده شود جان من','هوش مصنوعی: از لب محبوبم زندگی دوباره به من باز می‌گردد و جانم از آن لب‌های او زنده می‌شود.',NULL);
INSERT INTO "verses" VALUES(1940753,78319,0,1,'برد دل و جان من دلبر و جانان من',NULL,NULL);
INSERT INTO "verses" VALUES(1940754,78319,0,0,'دلبر و جانان من برد دل و جان من','هوش مصنوعی: عزیز و محبوب من، هم دل مرا برد و هم جانم را. محبوب من، هم دل را گرفت و هم جان را.',NULL);
INSERT INTO "verses" VALUES(1940755,78318,6,0,'دل حافظ ار بجویی غم دل ز تندخویی','اگر به‌دنبال شاد کردن حافظ باشی و من غم دل آتشینم را با تو بگویم؛ (از بس فراوان است که) خواهی گفت حوصله دردسر ندارم!',NULL);
INSERT INTO "verses" VALUES(1940756,78318,6,1,'چو بگویمت،  بگویی سر دردسر ندارم',NULL,NULL);
INSERT INTO "verses" VALUES(1940757,78318,5,0,'به من ار چه میْ ‌پرستم مدهید می به دستم','اگرچه من آدم میخواره‌ای هستم؛ با این وجود به من می ندهید که بی‌دل (بی‌قرار) می‌شوم و دل (یار) دیگری ندارم.',NULL);
INSERT INTO "verses" VALUES(1940758,78318,5,1,'مبرید دل ز دستم که دل دگر ندارم',NULL,NULL);
INSERT INTO "verses" VALUES(1940759,78318,4,0,'دگرم مگو که خواهم که ز درگهت برانم','دیگر به‌من مگو که مرا از خود خواهی راند؛ تو این را می‌خواهی و من می‌خواهم که دل از تو برندارم.',NULL);
INSERT INTO "verses" VALUES(1940760,78318,4,1,'تو بر این و من بر آنم که دل از تو برندارم',NULL,NULL);
INSERT INTO "verses" VALUES(1940761,78318,3,0,'ز زَرت کنند زیور به زرت کشند در بر','تو را با زر می‌آرایند و تو را با زر به‌آغوش می‌کشند؛ من بی‌نوای بی‌چاره چه کنم که زر ندارم؟',NULL);
INSERT INTO "verses" VALUES(1940762,78318,3,1,'من بی‌نوای مضطر چه کنم که زر ندارم',NULL,NULL);
INSERT INTO "verses" VALUES(1940763,78318,2,1,'نظری به جز تو با کس به کسی دگر ندارم',NULL,NULL);
INSERT INTO "verses" VALUES(1940764,78319,6,1,'نقد کمال غیاث حافظ خوشخوان من',NULL,NULL);
INSERT INTO "verses" VALUES(1940765,78309,6,1,'در دست چه اختیار داری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940766,78309,6,0,'ای عقل! تو با وجود عشقش','هوش مصنوعی: ای عقل! وقتی عشق او را در دل داری، چه قدرتی برای تصمیم‌گیری و کنترل داری؟',NULL);
INSERT INTO "verses" VALUES(1940767,78309,5,1,'در باغ چه اعتبار داری',NULL,NULL);
INSERT INTO "verses" VALUES(1940768,78303,3,0,'تا تو از چشم من سوخته دل دور شدی','هوش مصنوعی: زمانی که تو از دیده من دور شدی، چه بسیار چشمه‌های خونینی که از دل به چشم ریخته شد.',NULL);
INSERT INTO "verses" VALUES(1940769,78303,2,1,'چون ز دیدار تو دورم به چه باشم دلشاد',NULL,NULL);
INSERT INTO "verses" VALUES(1940770,78303,2,0,'روز و شب غصه و خون می‌خورم و چون نخورم','هوش مصنوعی: روز و شب در غم و اندوه به سر می‌برم و نمی‌توانم شاد باشم، چرا که از دیدار تو دورم.',NULL);
INSERT INTO "verses" VALUES(1940771,78303,1,1,'در فراق تو چنانم که بداندیش مباد',NULL,NULL);
INSERT INTO "verses" VALUES(1940772,78303,1,0,'چه کنم گر نکنم ناله و فریاد و فغان','هوش مصنوعی: چه کار کنم اگر در غم دوری تو، ناله و فریاد نزنم؟ حالت من به‌گونه‌ای است که هیچ‌کس به جز تو نباید از آن باخبر باشد.',NULL);
INSERT INTO "verses" VALUES(1940773,78303,0,1,'آه اگر نالهٔ زارم نرساند به تو باد',NULL,NULL);
INSERT INTO "verses" VALUES(1940774,78303,0,0,'می‌زنم هر نفس از دست فراقت فریاد','هوش مصنوعی: هر لحظه از غم جدایی‌ات فریاد می‌زنم و آه می‌کشم، اما اگر ناله و زاری من به تو نرسد، باد به گوش تو برساند.',NULL);
INSERT INTO "verses" VALUES(1940775,78302,6,1,'باش فارغ ز غم دوزخ و ایمن ز بهشت',NULL,NULL);
INSERT INTO "verses" VALUES(1940776,78302,6,0,'حافظا لطف حق ار با تو عنایت دارد','هوش مصنوعی: حافظ، اگر لطف و رحمت خداوند با تو همراه باشد، نگران عذاب جهنم نباش و از بهشت نیز احساس ناامنی نکن.',NULL);
INSERT INTO "verses" VALUES(1940777,78303,3,1,'ای بسا چشمهٔ خونین که دل از دیده گشاد',NULL,NULL);
INSERT INTO "verses" VALUES(1940778,78302,5,1,'خرقه در میکده‌ها در گرو باده نهشت',NULL,NULL);
INSERT INTO "verses" VALUES(1940779,78302,4,1,'هر که او دامن دلدار خود از دست بهشت',NULL,NULL);
INSERT INTO "verses" VALUES(1940780,78302,4,0,'راحت از عیش بهشت و لب حورش نبود','هوش مصنوعی: هرکس که از عشق و محبت معشوقش بهره‌مند باشد، دیگر نیازی به لذات بهشت ندارد و از آن لذت نمی‌برد.',NULL);
INSERT INTO "verses" VALUES(1940781,78302,3,1,'در ازل طینت ما را به می ناب سرشت',NULL,NULL);
INSERT INTO "verses" VALUES(1940782,78302,3,0,'منعم از می مکن ای صوفی صافی که حکیم','هوش مصنوعی: ای صوفی پاک، نگذار که از شراب منع شوی، چرا که حکیم در آغاز آفرینش، وجود ما را با شراب ناب شکل داده است.',NULL);
INSERT INTO "verses" VALUES(1940783,78302,2,1,'من و میخانه و زٌنار و ره دِیر و کنشت',NULL,NULL);
INSERT INTO "verses" VALUES(1940784,78302,2,0,'تو و تسبیح و مصلا و ره زٌهد و صلاح','هوش مصنوعی: تو در حال عبادت و پارسایی هستی با تسبیح و محل نماز، اما من در حال لذت و خوش‌گذرانی هستم با میخانه و زینت و راهی که به کلیسا می‌برد.',NULL);
INSERT INTO "verses" VALUES(1940785,78302,1,1,'هر که در کوی فنا در ره حق دانه نَکشت',NULL,NULL);
INSERT INTO "verses" VALUES(1940786,78302,1,0,'یک جو از خرمن هستی نتواند برداشت','هوش مصنوعی: هر کس که در مسیر حق به دنبال حقیقت نرود و زحمت نخواهد، نمی‌تواند حتی اندکی از گوهر زندگی را به دست آورد.',NULL);
INSERT INTO "verses" VALUES(1940787,78302,0,1,'که خدا در ازل از اهل بهشتم بسرشت',NULL,NULL);
INSERT INTO "verses" VALUES(1940788,78302,5,0,'صوفی صاف بهشتی نبود زآنکه چو من','هوش مصنوعی: صوفی واقعی و اهل بهشت نبود، زیرا او مانند من، لباس عرفانی خود را در میکده‌ها برای نوشیدن شراب می‌گذارد و در این حال در دام عشق و لذت گرفتار است.',NULL);
INSERT INTO "verses" VALUES(1940789,78303,4,0,'حافظ دلشده مستغرق یادت شب و روز','هوش مصنوعی: حافظ تمام روز و شب در یاد تو غرق شده است و از این بنده‌ای که به او دل داده، به طور کامل رها شده است.',NULL);
INSERT INTO "verses" VALUES(1940790,78303,4,1,'تو از این بندهٔ دل رفته به کلی آزاد',NULL,NULL);
INSERT INTO "verses" VALUES(1940791,78304,0,0,'عشقت نه سرسری‌ست که از دل به در شود','هوش مصنوعی: عشق تو به گونه‌ای نیست که به راحتی فراموش شود و احساس تو در دل من جایی دیگر نخواهد رفت.',NULL);
INSERT INTO "verses" VALUES(1940792,78304,10,1,'یک شب به لطف همره باد سحر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940793,78304,10,0,'گل مشک ریز باشد اگر بوی زلف تو','هوش مصنوعی: اگر بوی زلف تو یک شب به لطافت با نسیم سحر همرا باشد، گل مشک هم کوچک و ناچیز خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1940794,78304,9,1,'گردد مدام شهد و قلم نیشکر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940795,78304,9,0,'یاد لب تو گر برود بر زبان کلک','هوش مصنوعی: اگر یاد لب تو بر زبان جاری شود، نوشیندۀ دلپذیری از آن برخواهد خاست و قلم مثل نیشکر شیرین خواهد بود.',NULL);
INSERT INTO "verses" VALUES(1940796,78304,8,1,'گاهی که همچو حلقه به گردت کمر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940797,78304,8,0,'نتوان شناخت موی میانت ز موی زلف','هوش مصنوعی: گاهی اوقات، تشخیص موی وسط تو از موی زلفت سخت است، زمانی که همچون حلقه‌ای دور کمرت بیفتد.',NULL);
INSERT INTO "verses" VALUES(1940798,78304,7,1,'تا هر نفس به بادی زیر و زبر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940799,78304,7,0,'مِنَّت خدایْ را که دل من نه زلف توست','هوش مصنوعی: خداوند را شکر که دل من به زلف تو وابسته نیست، زیرا هرلحظه ممکن است زندگیم دچار تغییر و بی‌ثباتی شود.',NULL);
INSERT INTO "verses" VALUES(1940800,78304,6,1,'با دست، بگذرد به لبانت شکر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940801,78304,6,0,'تلخ است پاسخ تو ولیکن مرا چه غم','هوش مصنوعی: پاسخ تو برایم تلخ است، اما من نگران نیستم؛ با لبانت که شکرین باشد، همه چیز فراموش خواهد شد.',NULL);
INSERT INTO "verses" VALUES(1940802,78304,5,1,'گر دستگیر دیده نه خون جگر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940803,78304,5,0,'روزی به خرج غم نکند اشک من وفا','هوش مصنوعی: روزی اشک‌های من به خاطر غم دیگر خرج نمی‌شود، اگر چشمم را درک کند، خون جگر من هم به حال خود باقی می‌ماند.',NULL);
INSERT INTO "verses" VALUES(1940804,78304,4,1,'کشت عراق جمله به یک روز تر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940805,78304,4,0,'با آنکه گر سرشک فشانم به زنده‌رود','هوش مصنوعی: اگرچه اگر اشک‌هایم را بر بستر زنده‌رود بریزم، تمام کشتزارهای عراق در یک روز سرسبز و تازه خواهند شد.',NULL);
INSERT INTO "verses" VALUES(1940806,78304,3,1,'فریاد من ز ذَروهٔ افلاک بر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940807,78304,3,0,'اینک یکی منم که در این شهر هر شبی','هوش مصنوعی: من در این شهر، هر شب فریاد می‌زنم که صدایم از بلندای آسمان به گوش می‌رسد.',NULL);
INSERT INTO "verses" VALUES(1940808,78304,2,1,'هرچند سعی بیش نمایی بَتَر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940809,78304,2,0,'دردی‌ست درد عشق که اندر علاج آن','هوش مصنوعی: درد عشق به قدری عمیق و سخت است که هرچه بیشتر تلاش کنی تا آن را درمان کنی، اوضاع بدتر و دردناک‌تر می‌شود.',NULL);
INSERT INTO "verses" VALUES(1940810,78304,1,1,'با شیر اندر آمد و با جان به در شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940811,78304,1,0,'عشق تو در درونم و مهر تو در دلم','هوش مصنوعی: عشق تو در قلب من است و محبت تو در دل من برقرار است، همانطور که شیر در درون می‌آید و جانم را از خود جدا می‌کند.',NULL);
INSERT INTO "verses" VALUES(1940812,78304,0,1,'مهرت نه عارضی‌ست که جای دگر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940813,78302,0,0,'برو ای زاهد و دعوت مکنم سوی بهشت','هوش مصنوعی: ای زاهد، برو و مرا به بهشت دعوت نکن، زیرا خداوند در ابتدا از من، کسی را ساخت که بهشتی باشد.',NULL);
INSERT INTO "verses" VALUES(1940814,78304,11,0,'دی در میان زلف بدیدم رخ نگار','هوش مصنوعی: دیروز در میان زلف‌هایش، چهره‌ای از محبوب را دیدم که به گونه‌ای بود که می‌توانست زیبایی‌های ماه را تحت الشعاع قرار دهد.',NULL);
INSERT INTO "verses" VALUES(1940815,77990,4,0,'حافظ عاشق، به رَغمِ زاهدِ دنیاپرست','هوش مصنوعی: حافظ، با وجود اینکه زاهدان دنیاپرست او را سرزنش می‌کنند، همچنان به عشق و شادمانی می‌پردازد و به محبوب زیبایش شراب نوشین می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1940816,77990,3,0,'محتسب، با ساغرِ رندان شکستن، روز و شب','هوش مصنوعی: محافظ، هر لحظه با دوستانش از جام‌ها می‌نوشد و به طور مداوم شراب سرخ را از ظرف‌های زیبا و زینتی می‌ریزد.',NULL);
INSERT INTO "verses" VALUES(1940817,77987,6,1,'بساز رود و غزل خوان که می روم به سماع',NULL,NULL);
INSERT INTO "verses" VALUES(1940818,77987,6,0,'ز زهد حافظ و طامات او ملول شدم','هوش مصنوعی: از زهد و پیچیدگی‌های حافظ خسته شدم، بیا تا با هم به شادی و شادابی بپردازیم و غزل بخوانیم، چون من در حال رفتن به یک حال و هوای جدید هستم.',NULL);
INSERT INTO "verses" VALUES(1940819,77987,5,1,'کجا روم به تجارت بدین کساد متاع',NULL,NULL);
INSERT INTO "verses" VALUES(1940820,77987,5,0,'هنر نمی خرد ایام غیر از اینم نیست','هوش مصنوعی: هنر را نمی‌توان خرید و زمانه غیر از این نیست؛ کجا می‌توانم بروم که در این بازار کساد، کالای خود را بفروشم؟',NULL);
INSERT INTO "verses" VALUES(1940821,77987,4,1,'حریف باده رسید ای رفیق توبه وداع',NULL,NULL);
INSERT INTO "verses" VALUES(1940822,77987,4,0,'ز مسجدم به خرابات می‌فرستد عشق','هوش مصنوعی: عشق مرا از مسجد به میخانه فرستاد، دوست. نوشیدن شراب در حال حاضر رسیده است و ای رفیق، زمان توبه و خداحافظی است.',NULL);
INSERT INTO "verses" VALUES(1940823,77987,3,1,'که من غلام مطیعم نه پادشاه مطاع',NULL,NULL);
INSERT INTO "verses" VALUES(1940824,77987,3,0,'برو ادیب به جامی بدل کن این شفقت','هوش مصنوعی: به یک انسان فرهیخته بگو که این محبت و مهربانی را به نوعی دیگر درآورد، چون من خدمتگزار و بنده‌ام و نه مانند یک پادشاه که از دیگران اطاعت می‌شود.',NULL);
INSERT INTO "verses" VALUES(1940825,77987,2,1,'که غیر از این همه اسباب تفرقست و صداع',NULL,NULL);
INSERT INTO "verses" VALUES(1940826,77988,0,0,'نور خدا نمایدت آینهٔ مجردی','هوش مصنوعی: در آینه‌ای که نشان‌دهندهٔ نور خداست، ببین که می‌توانی به حقیقتی ناب و خالص دست پیدا کنی. اگر عاشق عشق بی‌پایان هستی، در آن دروازه به سراغ ما بیا.',NULL);
INSERT INTO "verses" VALUES(1940827,77987,2,0,'صراحتی و حریفی خوشم زدنیا بس','هوش مصنوعی: من از دنیا و جهالت آن خوشم نمی‌آید، زیرا جز این که باعث جدایی و پریشانی بین افراد می‌شود، چیز دیگری ندارد.',NULL);
INSERT INTO "verses" VALUES(1940828,77987,1,0,'بیار می که چه خورشید مشغل افروزد','هوش مصنوعی: می‌خواهم می بیاوری که روشنایی خورشید چگونه شعله می‌افروزد و حتی به کلبه درویش هم نور و فیض خود را می‌رساند.',NULL);
INSERT INTO "verses" VALUES(1940829,77987,0,1,'که با کسم نبود بهر مال و جاه نزاع',NULL,NULL);
INSERT INTO "verses" VALUES(1940830,77987,0,0,'به فر دولت گیتی فروز شاه شجاع','هوش مصنوعی: در این بیت به شاه شجاع اشاره شده که در سایه‌ی قدرت و حکمرانی‌اش، در دنیا درخشان است. او به خاطر مال و مقام با کسی درگیر نمی‌شود و درستی و صداقت را بر بهتر شدن اوضاع ترجیح می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1940831,77986,8,1,'جامه زو بستان و جامی ده به وی',NULL,NULL);
INSERT INTO "verses" VALUES(1940832,77986,9,0,'با تو زین پس گر فلک خواری کند','هوش مصنوعی: اگر از این به بعد آسمان به من بی‌احترامی کند، دوباره بگو در حضور خداوند که من هیچ چیزی ندارم.',NULL);
INSERT INTO "verses" VALUES(1940833,77986,9,1,'باز گو در حضرت دارای ری',NULL,NULL);
INSERT INTO "verses" VALUES(1940834,77986,10,0,'خسرو آفاق بخش آن کز سخاش','هوش مصنوعی: خسرو، نیکوکار و بخشنده‌ای است که به خاطر سخاوتش، نام حاتم طائی را تحت تأثیر قرار داده و باعث شهرت او شده است.',NULL);
INSERT INTO "verses" VALUES(1940835,77986,10,1,'نامه حاتم ز نامش گشت طی',NULL,NULL);
INSERT INTO "verses" VALUES(1940836,77986,11,0,'جام می پیش آرو چون حافظ مخور','هوش مصنوعی: باده را به دست بیاور و از غم دوری کن، زیرا که جمشید یا کاووس، چه کسانی بودند که به ما ناامیدی دهند؟',NULL);
INSERT INTO "verses" VALUES(1940837,77987,1,1,'رسد به کلبه درویش نیز فیض شعاع',NULL,NULL);
INSERT INTO "verses" VALUES(1940838,77988,0,1,'از در ما در آ اگر طالب عشق سرمدی',NULL,NULL);
INSERT INTO "verses" VALUES(1940839,77988,1,0,'باده بده که دوزخ ار نام گناه ما برد','هوش مصنوعی: به من شراب بده که اگر دوزخ به خاطر گناهان ما نامی ببرد، آب معجزه‌ی محمدی بر آتش دوزخ بریزد و آن را خاموش کند.',NULL);
INSERT INTO "verses" VALUES(1940840,77988,1,1,'آب زند بر آتشش معجزهٔ محمدی',NULL,NULL);
INSERT INTO "verses" VALUES(1940841,77990,3,1,'بادهٔ سرخ از صراحیّ منقّش می‌زند',NULL,NULL);
INSERT INTO "verses" VALUES(1940842,77990,2,0,'ناخوشی‌ها دیده‌ام از زاهدِ پشمینه‌پوش','هوش مصنوعی: من مشکلات زیادی را از عابدی که لباس پشمین می‌پوشد، دیده‌ام، اما من نوکر نوازنده‌ای هستم که با ساز خوش می‌نوازد.',NULL);
INSERT INTO "verses" VALUES(1940843,77990,2,1,'من غلامِ مطربم کابریشمِ خوش می‌زند',NULL,NULL);
INSERT INTO "verses" VALUES(1940844,77990,1,0,'زاهدا، از تیرِ مژگانش حذر کردن چه سود؟','هوش مصنوعی: ای زاهد، چه فایده‌ای دارد که از تیر نگاهش دوری کنی؟ درد پنهان من به زیبایی ابروی کمانکش اشاره می‌کند.',NULL);
INSERT INTO "verses" VALUES(1940845,77990,1,1,'زخمِ پنهانم به ابروی کَمانکش می‌زند',NULL,NULL);
INSERT INTO "verses" VALUES(1940846,77990,0,0,'بلبل اندر ناله و، گُل خندهٔ خوش می‌زند','هوش مصنوعی: پرنده‌ای در حال ناله است و گل با شادی می‌خندد. چطور ممکن است دل به آتش عشق معشوق نسوزد در حالی که این همه شور و حال در اطرافش جاری است؟',NULL);
INSERT INTO "verses" VALUES(1940847,77990,0,1,'چون نسوزد دل که دلبر در وِی آتش می‌زند؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940848,77989,3,1,'لعمر ابیک الا الفرقدان',NULL,NULL);
INSERT INTO "verses" VALUES(1940849,77989,3,0,'و کل اخ یفارقه اخوه','هوش مصنوعی: هر برادری به خاطر شرایط مختلف از برادرش جدا می‌شود، اما همیشه دو ستاره (فرقدان) در آسمان باقی می‌مانند.',NULL);
INSERT INTO "verses" VALUES(1940850,77989,2,1,'چنین رفته است حکم آسمانی',NULL,NULL);
INSERT INTO "verses" VALUES(1940851,77989,2,0,'همی باید برید از خویش و پیوند','هوش مصنوعی: انسان باید از خودخواهی و دلبستگی‌هایش فاصله بگیرد، چرا که این امر جزو سرنوشت و قانون‌های الهی است.',NULL);
INSERT INTO "verses" VALUES(1940852,77989,1,1,'نخواهد رفت آب زندگانی',NULL,NULL);
INSERT INTO "verses" VALUES(1940853,77989,1,0,'دریغا حسرتا دردا کزین جوی','هوش مصنوعی: متأسفانه آب حیات از این جوی نخواهد رفت و حسرت و درد ناشی از آن باقی خواهد ماند.',NULL);
INSERT INTO "verses" VALUES(1940854,77989,0,1,'گرش بودی طراز جاودانی',NULL,NULL);
INSERT INTO "verses" VALUES(1940855,77989,0,0,'دریغا خلعت حسن جوانی','هوش مصنوعی: ای کاش زیبایی جوانی همیشه و به طور جاودانه بماند.',NULL);
INSERT INTO "verses" VALUES(1940856,77988,4,1,'ای متعلق خجل دم مزن از مجردی',NULL,NULL);
INSERT INTO "verses" VALUES(1940857,77988,4,0,'مرغ دل تو حافظا بستهٔ دام آرزوست','هوش مصنوعی: دل تو مانند پرنده‌ای است که در دام آرزوها گرفتار شده، ای کسی که به حافظ تعلق داری، نگران مجردی نباش و سخن از آن نران.',NULL);
INSERT INTO "verses" VALUES(1940858,77988,3,1,'سوسن و سرو و گل به تو جمله شوند مقتدی',NULL,NULL);
INSERT INTO "verses" VALUES(1940859,77988,3,0,'گر تو بدین جمال و فر، سوی چمن کنی گذر','هوش مصنوعی: اگر با این زیبایی و وقار خود به سمت باغ حرکت کنی، تمامی گل‌ها و درختان به تو اقتدا خواهند کرد.',NULL);
INSERT INTO "verses" VALUES(1940860,77988,2,1,'قال رسول ربنا ما انا قط من ددی',NULL,NULL);
INSERT INTO "verses" VALUES(1940861,77988,2,0,'شعبده باز می کنی هر دم و نیست این روا','هوش مصنوعی: هر لحظه تظاهر به کارهایی می‌کنی که واقعیت ندارند و این کار درست نیست. پروردگار ما فرمود که من هرگز از بندگان او نیستم.',NULL);
INSERT INTO "verses" VALUES(1940862,77990,4,1,'بادهٔ نوشین به روی یارِ مهوش می‌زند',NULL,NULL);
INSERT INTO "verses" VALUES(1940863,78304,11,1,'بر هیئتی که عقده محیط قمر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940864,78304,12,0,'گفتم که ابتدا کنم از بوسه؟ گفت نه','هوش مصنوعی: گفتم که با بوسه‌ای آغاز کنم؟ گفت نه، صبر کن تا که ماه از زیر سایه‌ی عقرب بیرون بیاید.',NULL);
INSERT INTO "verses" VALUES(1940865,78304,12,1,'بگذار تا که ماه ز عقرب به در شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940866,78308,0,1,'که هم به باده توان کرد دفع رنجوری',NULL,NULL);
INSERT INTO "verses" VALUES(1940867,78308,0,0,'بیار باده و بازم رهان ز مخموری','هوش مصنوعی: باده بیاور و من را از حال مستی آزاد کن، زیرا فقط با نوشیدن باده می‌توانم رنج و درد را از خود دور کنم.',NULL);
INSERT INTO "verses" VALUES(1940868,78307,8,1,'که گر از پا درافتی با سر آیی',NULL,NULL);
INSERT INTO "verses" VALUES(1940869,78307,8,0,'بیا حافظ به جان این پند بشنو','هوش مصنوعی: به تو می‌گویم که ای حافظ، به خاطر این نصیحت گوش بده. اگر نتوانی سرپا بایستی و زمین بخوری، با سر و رویی تازه و با انرژی دوباره به جلو خواهی آمد.',NULL);
INSERT INTO "verses" VALUES(1940870,78307,7,1,'در این درد و عنا چون بی‌نوایی',NULL,NULL);
INSERT INTO "verses" VALUES(1940871,78307,7,0,'قناعت را بضاعت ساز و می‌سوز','هوش مصنوعی: در زندگی، آنچه داری را بپذیر و بر اساس همین امکانات، زندگی‌ات را بساز. در این مسیر با مشکلات و دردها روبه‌رو خواهی شد، اما باید با آن مواجه شوی و زندگی‌ات را به خوبی بگذرانید، حتی اگر در موقعیت دشواری به سر ببری.',NULL);
INSERT INTO "verses" VALUES(1940872,78307,6,1,'برو صبری بکن در بینوایی',NULL,NULL);
INSERT INTO "verses" VALUES(1940873,78307,6,0,'خرد در گوش هوشم دی همی گفت','هوش مصنوعی: در دل من صدای خرد به گوش می‌رسد که به من می‌گوید: در این شرایط سخت و فقر، صبر کن و استقامت داشته باش.',NULL);
INSERT INTO "verses" VALUES(1940874,78307,5,1,'اگر خود فی المثل باشد سنایی',NULL,NULL);
INSERT INTO "verses" VALUES(1940875,78308,1,0,'به هیچ وجه نیابد چراغ مجلس انس','هوش مصنوعی: هیچ چیز دیگری نمی‌تواند نور و روشنی مجلس دوستان را تامین کند مگر چهره زیبای معشوق و شراب خوشمزه.',NULL);
INSERT INTO "verses" VALUES(1940876,78307,5,0,'نبخشندش جویی از بخل و امساک','هوش مصنوعی: اگر کسی مانند سنایی بخیل و دست و دل تنگ باشد، دیگران هم به او رحم نمی‌کنند و از او انتقاد می‌کنند.',NULL);
INSERT INTO "verses" VALUES(1940877,78307,4,0,'وگر شاعر بگوید شعر چون آب','هوش مصنوعی: اگر شاعر بگوید که شعر مانند آبی است که دل را روشن و زنده می‌کند، اشاره به این دارد که شعر می‌تواند روح انسان را شفاف و پرانرژی کند.',NULL);
INSERT INTO "verses" VALUES(1940878,78307,3,1,'متاع او چو هست این دم بهایی',NULL,NULL);
INSERT INTO "verses" VALUES(1940879,78307,3,0,'ولیکن جاهل است اندر تنعم','هوش مصنوعی: اما او در خوشی و لذت‌ها نادان است؛ چرا که آنچه دارد فقط در این لحظه ارزش دارد.',NULL);
INSERT INTO "verses" VALUES(1940880,78307,2,1,'نمی بیند زغم یک دم رهایی',NULL,NULL);
INSERT INTO "verses" VALUES(1940881,78307,2,0,'کسی کـ‌او فاضل است امروز در دهر','هوش مصنوعی: انسانی که در زمانه کنونی دانشمند و فرهیخته است، به هیچ وجه نمی‌تواند از اندوه و غم لحظه‌ای آسوده باشد.',NULL);
INSERT INTO "verses" VALUES(1940882,78307,1,1,'کنون اهل هنر دست گدایی',NULL,NULL);
INSERT INTO "verses" VALUES(1940883,78307,1,0,'برند از فاقه نزد هر خسیسی','هوش مصنوعی: افراد بی‌هنر اکنون به خاطر دشواری‌های مالی، هنرآموزان را تحقیر کرده و به آنها نگاه نمی‌کنند.',NULL);
INSERT INTO "verses" VALUES(1940884,78307,0,1,'نماند از کس نشان آشنایی',NULL,NULL);
INSERT INTO "verses" VALUES(1940885,78307,0,0,'پدید آمد رسوم بی وفایی','هوش مصنوعی: رسوم بی‌وفایی به وجود آمده و دیگر هیچ نشانه‌ای از آشنایی و دوستی باقی نمانده است.',NULL);
INSERT INTO "verses" VALUES(1940886,78307,4,1,'که دل را زآن فزاید روشنایی',NULL,NULL);
INSERT INTO "verses" VALUES(1940887,78308,1,1,'مگر به روی نگار و شراب انگوری',NULL,NULL);
INSERT INTO "verses" VALUES(1940888,78308,2,0,'به سحر غمزه فتان هیچ غره مباش','هوش مصنوعی: به زیبایی و ناز چشمک‌های دلربا اعتماد نکن، چون من تجربه کردم و دیدم که به آدم مغرور هیچ سودی نمی‌رساند.',NULL);
INSERT INTO "verses" VALUES(1940889,78308,2,1,'که آزمودم و سودی نداشت مغروری',NULL,NULL);
INSERT INTO "verses" VALUES(1940890,78309,5,0,'ای سرو! تو با قد بلندش','هوش مصنوعی: ای سرو! با وجود اینکه قد تو بلند است، در باغ چه ارزشی داری؟',NULL);
INSERT INTO "verses" VALUES(1940891,78309,4,1,'او تازه و تو غبار داری',NULL,NULL);
INSERT INTO "verses" VALUES(1940892,78309,4,0,'ریحان! تو کجا و خط سبزش','هوش مصنوعی: ریحان! تو کجا و آن خط سبز، که تازگی و شادابی دارد، کجا؟ تو چقدر غبارآلود و خسته به نظر می‌رسی.',NULL);
INSERT INTO "verses" VALUES(1940893,78309,3,1,'او سرخوش و تو خمار داری',NULL,NULL);
INSERT INTO "verses" VALUES(1940894,78309,3,0,'نرگس! تو کجا و چشم مستش','هوش مصنوعی: ای نرگس! تو به کجا رفته‌ای؟ در حالی که او با چشمی مست و سرخوش در کنار توست و تو در حال کم‌حالی و خمار به سر می‌بری.',NULL);
INSERT INTO "verses" VALUES(1940895,78309,2,1,'او مشک و تو بار خار داری',NULL,NULL);
INSERT INTO "verses" VALUES(1940896,78309,2,0,'ای گل! تو کجا و روی زیباش','هوش مصنوعی: ای گل! تو کجا و زیبایی او کجا، او همچون مشک است و تو به مانند خاری.',NULL);
INSERT INTO "verses" VALUES(1940897,78309,1,1,'با طرهٔ او چه کار داری؟',NULL,NULL);
INSERT INTO "verses" VALUES(1940898,78309,1,0,'زنهار! مکن درازدستی','هوش مصنوعی: مواظب باش! دست درازی نکن به موهای او، چه کار به او داری؟',NULL);
INSERT INTO "verses" VALUES(1940899,78309,0,1,'زآن نفحهٔ مشکبار داری',NULL,NULL);
INSERT INTO "verses" VALUES(1940900,78309,0,0,'ای باد نسیم یار داری','هوش مصنوعی: ای نسیم ملایم، تو بویی دلپذیر و خوش از معشوقه‌ی خود داری.',NULL);
INSERT INTO "verses" VALUES(1940901,78308,7,1,'بدان بگو که کشیده‌ست محنت دوری',NULL,NULL);
INSERT INTO "verses" VALUES(1940902,78308,7,0,'به هر کسی نتوان گفت درد او حافظ','هوش مصنوعی: هر کس نمی‌تواند به راحتی احساس درد و رنج خود را بیان کند، ولی حافظ، به تو بگوید که او در سختی ناشی از جدایی به سر می‌برد.',NULL);
INSERT INTO "verses" VALUES(1940903,78308,6,1,'نهاد کشور دل باز رو به معموری',NULL,NULL);
INSERT INTO "verses" VALUES(1940904,78308,6,0,'رسید دولت وصل و گذشت محنت هجر','هوش مصنوعی: زمانی که خوشبختی و وصال محبوب فرارسید، و درد دوری و جدایی تمام شد، دل من به آرامش و سرزندگی رسید و به حالتی شاداب و سعادتمند دست یافت.',NULL);
INSERT INTO "verses" VALUES(1940905,78308,5,1,'دریغ آن همه زهد و صلاح مستوری',NULL,NULL);
INSERT INTO "verses" VALUES(1940906,78308,5,0,'به یک فریب نهادم صلاح خویش از دست','هوش مصنوعی: به خاطر یک فریب، بهترین امکانات و کارهای خوبم را از دست دادم. افسوس که تمام تلاش‌هایم برای زهد و پنهان‌کاری به هدر رفت.',NULL);
INSERT INTO "verses" VALUES(1940907,78308,4,1,'اگر تو عشق نداری برو که معذوری',NULL,NULL);
INSERT INTO "verses" VALUES(1940908,78308,4,0,'به عشق زنده بود جان مرد صاحبدل','هوش مصنوعی: اگر دل نیک‌نهاد و عاشق باشد، زندگی‌اش پر از عشق و شور است. اما اگر تو این احساس را نداری، بهتر است که بروی، چون اینجا جایی برای تو نیست.',NULL);
INSERT INTO "verses" VALUES(1940909,78308,3,1,'که هیچ نیست ادیب این سخن به دستوری',NULL,NULL);
INSERT INTO "verses" VALUES(1940910,78308,3,0,'ادیب چند نصیحت کنی که عشق مباز','هوش مصنوعی: چند بار می‌خواهی نصیحت کنی که عشق بی‌فایده است؟ این حرف را چه کسی به تو گفته است؟',NULL);
INSERT INTO "verses" VALUES(1940911,78306,7,1,'زند به روز و شبان خون فشان نوای فراق',NULL,NULL);
INSERT INTO "verses" VALUES(1940912,78306,7,0,'به داغ عشق تو حافظ چو بلبل سحری','هوش مصنوعی: حافظ به عشق تو مانند بلبل سحر در هر روز و شب با اندوه و نوای جدایی، ناله می‌زند و خون می‌گرید.',NULL);
INSERT INTO "verses" VALUES(1940913,78306,6,1,'مگر که زاد مرا مادر از برای فراق',NULL,NULL);
INSERT INTO "verses" VALUES(1940914,78306,6,0,'من از کجا و فراق از کجا و غم ز کجا','هوش مصنوعی: من نمی‌دانم من از کجا آمده‌ام و فاصله و جدایی از کجا نشأت می‌گیرد و غم و اندوه از کجا ناشی شده است، مگر اینکه مادر من به خاطر جدایی و فراق مرا به دنیا آورده باشد.',NULL);
INSERT INTO "verses" VALUES(1940915,78305,4,0,'بزن این آتش مرا آبی','هوش مصنوعی: مرا به این آتش بسوزان و مانند آب بر من بگذار.',NULL);
INSERT INTO "verses" VALUES(1940916,78305,3,1,'گردنش را ز می طناب بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1940917,78305,3,0,'می‌کند عقل سرکشی تمام','هوش مصنوعی: عقل انسان ممکن است گاهی طغیان و سرکشی کند و در چنین حالتی، با نوشیدن شراب، می‌توان این شورش را کنترل کرد و آن را آرام کرد.',NULL);
INSERT INTO "verses" VALUES(1940918,78305,2,1,'در میان مه آفتاب بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1940919,78305,2,0,'آفتاب است و ماه باده و جام','هوش مصنوعی: خورشید و ماه در کنار هم هستند و باده و جام در میان آن‌ها قرار دارد. از شما می‌خواهم که این خورشید و ماه را بیاورید.',NULL);
INSERT INTO "verses" VALUES(1940920,78305,1,1,'کاوست درمان شیخ و شاب بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1940921,78305,1,0,'داروی درد عشق یعنی می','هوش مصنوعی: داروی درد عشق همان نوشیدنی است، پس برای درمان این درد، شیخ را بخوان و جوانی را بیاور.',NULL);
INSERT INTO "verses" VALUES(1940922,78305,0,1,'یک دو جام شراب ناب بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1940923,78305,0,0,'ساقیا ساغر شراب بیار','هوش مصنوعی: ای ساقی، ظرف شراب را بیاور و دو جام از شراب خالص و ناب به من بده.',NULL);
INSERT INTO "verses" VALUES(1940924,78304,18,1,'کز بندگیش کار فلک معتبر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940925,78304,18,0,'جان جهان جهانِ کرم میر عزّ دین','هوش مصنوعی: روح عالم، جهان مهربانی است، که میر عزّ دین با بندگی او، کارهای آسمان را معتبر و با اعتبار می‌سازد.',NULL);
INSERT INTO "verses" VALUES(1940926,78304,17,1,'چندان بود که صدر جهان را خبر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940927,78304,17,0,'احوال بی‌نوایی بنده بر این نسق','هوش مصنوعی: حال و روز بی‌پناهی من به اندازه‌ای است که حتی بزرگترین و محترم‌ترین افراد جهان از آن مطلع شوند.',NULL);
INSERT INTO "verses" VALUES(1940928,78304,16,1,'این هم به طالع تو همانا اگر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940929,78304,16,0,'زر باشد آنکه کار تو چون زر کند ولی','هوش مصنوعی: این بیت به این معناست که کسی که به خوبی و مهارت کار می‌کند، ارزشمند و گرانبهاست، مانند طلا. اما در عین حال، نتیجه و سرنوشت نهایی کار او بستگی به تقدیر و شانسش دارد.',NULL);
INSERT INTO "verses" VALUES(1940930,78304,15,1,'خود مرد کی بود که بدین گونه خر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940931,78304,15,0,'فضل و هنر به تحفهٔ معشوق می‌بری','هوش مصنوعی: تو هنر و فضیلت خودت را به محبوب هدیه می‌کنی، اما این چه مردی است که به این شکل خوار و ذلیل شود؟',NULL);
INSERT INTO "verses" VALUES(1940932,78304,14,1,'از هرزه گفتن تو مرا درد سر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940933,78304,14,0,'گفت این چه عادت است که هرروز تا به شب','هوش مصنوعی: این چه عادت بدی است که هر روز تا شب از حرف‌های بی‌فایده تو مجبور به تحمل دردسر می‌شوم؟',NULL);
INSERT INTO "verses" VALUES(1940934,78304,13,1,'گر میل خاطر تو به فضل و هنر شود',NULL,NULL);
INSERT INTO "verses" VALUES(1940935,78304,13,0,'گفتم که چند گونه به پیشت بیان کنم','هوش مصنوعی: گفتم چند راه را برای ابراز احساساتم به تو امتحان کنم، اگر تو به لطف و هنر من علاقه‌مند شوی.',NULL);
INSERT INTO "verses" VALUES(1940936,78305,4,1,'یعنی آن آتش چو آب بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1940937,77986,11,1,'غم که جم کی بود یا کاووس کی',NULL,NULL);
INSERT INTO "verses" VALUES(1940938,78305,5,0,'گل اگر رفت گو به شادی رو','هوش مصنوعی: اگر گل را از دست دادی، با شادی بنوش و باده‌ی خالص بیاور که مثل گلاب خوش‌بوست.',NULL);
INSERT INTO "verses" VALUES(1940939,78305,6,0,'غلغل بلبل ار نماند چه غم','هوش مصنوعی: اگر صدای بلبل دیگر نشنویم، نگران چه چیزی هستیم؟ بیایید شیشه شراب را ببریم و از طعم آن لذت ببریم.',NULL);
INSERT INTO "verses" VALUES(1940940,78306,5,1,'چنان که خون بچکانم ز دیده‌های فراق',NULL,NULL);
INSERT INTO "verses" VALUES(1940941,78306,5,0,'فراق را به فراق تو مبتلا سازم','هوش مصنوعی: من آنقدر دلتنگ تو هستم که انگار دردی عمیق در دل دارم و در این حال، اشک‌هایم مانند خون از چشمانم جاری می‌شود.',NULL);
INSERT INTO "verses" VALUES(1940942,78306,4,1,'خدای را بستان داد و ده سزای فراق',NULL,NULL);
INSERT INTO "verses" VALUES(1940943,78306,4,0,'ز درد هجر فراقم دمی خلاصی نیست','هوش مصنوعی: از درد جدایی و فراق، لحظه‌ای آرامش ندارم. ای خدا، از تو می‌خواهم که داد و ستد کنم و برای این جدایی به من پاداشی بدهی.',NULL);
INSERT INTO "verses" VALUES(1940944,78306,3,1,'که داد من بستاند دهد جزای فراق',NULL,NULL);
INSERT INTO "verses" VALUES(1940945,78306,3,0,'کجا روم؟ چه کنم؟ حال دل که را گویم؟','هوش مصنوعی: نمی‌دانم به کجا بروم و چه کار کنم. حال دلم را به که بگویم؟ کسی که حق من را گرفته و جزای دوری را به من می‌دهد.',NULL);
INSERT INTO "verses" VALUES(1940946,78306,2,1,'به آب دیده دهم باز خونبهای فراق',NULL,NULL);
INSERT INTO "verses" VALUES(1940947,78306,2,0,'اگر به دست من افتد فراق را بکشم','هوش مصنوعی: اگر فراق به دست من بیفتد، آن را با اشک‌هایم می‌کشم و به عنوان این فراق، خونبهایی خواهم داد.',NULL);
INSERT INTO "verses" VALUES(1940948,78306,1,1,'کشیده محنت ایام و داغهای فراق',NULL,NULL);
INSERT INTO "verses" VALUES(1940949,78306,1,0,'غریب و عاشق و بیدل غریب و سرگردان','هوش مصنوعی: این شخص احساس تنهایی و عشق می‌کند و در شرایطی سخت و پر از درد و جدایی به سر می‌برد. او در واقعیت زندگی خود با مشکلاتی مواجه است که موجب آزار و رنجش او شده است. احساس سردرگمی و دلتنگی او نیز گواهی بر عمق عواطفش دارد.',NULL);
INSERT INTO "verses" VALUES(1940950,78306,0,1,'که عمر من همه بگذشت در بلای فراق',NULL,NULL);
INSERT INTO "verses" VALUES(1940951,78306,0,0,'مباد کس چو من خسته مبتلای فراق','هوش مصنوعی: هیچ‌کس را در غم و اندوه جدایی من نرساند که عمر من تمام شده و تنها در این درد و رنج فراق سپری شده است.',NULL);
INSERT INTO "verses" VALUES(1940952,78305,10,1,'گرگناه است و گر ثواب بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1940953,78305,10,0,'یک دو رطل گران به حافظ ده','هوش مصنوعی: اگر بر من گناهی رفته، یک یا دو رطل از نگرانی آن کم کن و اگر هم کار نیکو و پاداشی داری، بیاور تا از آن بهره‌مند شوم.',NULL);
INSERT INTO "verses" VALUES(1940954,78305,9,1,'تا به کلی شوم خراب بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1940955,78305,9,0,'گرچه مستم سه چار جام دگر','هوش مصنوعی: هرچند مست هستم و چند جام دیگر می‌نوشم، اما آرزو دارم که به طور کامل خراب شوم.',NULL);
INSERT INTO "verses" VALUES(1940956,78305,8,1,'دارویی کاوست اصل خواب بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1940957,78305,8,0,'وصل او جز به خواب نتوان دید','هوش مصنوعی: تنها در خواب می‌توان به وصال او دست یافت و هیچ دارویی نمی‌تواند خواب را به حقیقت تبدیل کند، زیرا او خود اصل و منبع خواب است.',NULL);
INSERT INTO "verses" VALUES(1940958,78305,7,1,'نغمه بر بط و رباب بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1940959,78305,7,0,'غم دوران مخور که رفت به باد','هوش مصنوعی: از نگرانی‌ها و افکار منفی درباره گذشته یا آینده پرهیز کن، زیرا زمان به سرعت می‌گذرد. به جای آن، لحظات خوشی چون نغمه خوانی و شادی را با سازها و عشق به زندگی تجربه کن.',NULL);
INSERT INTO "verses" VALUES(1940960,78305,6,1,'قلقل شیشه شراب بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1940961,78305,5,1,'باده ناب چون گلاب بیار',NULL,NULL);
INSERT INTO "verses" VALUES(1940962,33169,0,0,'ما برفتیم، تو دانی و دل غمخور ما','هوش مصنوعی: ما رفتیم و تو می‌دانی که دل‌مان چقدر نگران است. سرنوشت بد ما به کجا می‌کشد و این دشواری‌ها به چه سرنوشتی منجر می‌شود.',NULL);
INSERT INTO "verses" VALUES(3763604,2524,7,0,'حافظ وِصال می‌طَلَبَد از رهِ دُعا','هوش مصنوعی: حافظ از خدا می‌خواهد که به خاطر دل‌های خسته و غمزده، دعاهای آن‌ها را مستجاب کند و راه وصال را برایش هموار سازد.',NULL);
INSERT INTO "verses" VALUES(3763605,2524,6,1,'وین خانه را قیاسِ اساس از حُباب کُن',NULL,NULL);
INSERT INTO "verses" VALUES(3763606,2524,6,0,'همچون حُباب، دیده به رویِ قَدَح گُشای','هوش مصنوعی: مانند حبابی که بر روی لیوان ظاهر می‌شود، چشم‌هایت را به سمت آن بگشای و این خانه را با توجه به حبابش بسنج.',NULL);
INSERT INTO "verses" VALUES(3763607,2524,5,1,'با دشمنان، قَدَح کَش و با ما عِتاب کُن',NULL,NULL);
INSERT INTO "verses" VALUES(3763608,2524,5,0,'زآن جا که رسم و عادتِ عاشق‌کشی توست','هوش مصنوعی: از آنجا که تو عادت داری به کشتن عاشقان، با دشمنانت بنوش و با ما به تندی حرف بزن.',NULL);
INSERT INTO "verses" VALUES(3763609,2524,4,1,'بِنْگَر به رنگِ لاله و عَزْمِ شراب کُن',NULL,NULL);
INSERT INTO "verses" VALUES(3763610,2524,4,0,'بویِ بنفشه بشنو و زُلْفِ نگار گیر','هوش مصنوعی: عطر بنفشه را استشمام کن و به موهای زیبای محبوبه‌ات نگاه کن. به رنگ گل لاله توجه کن و تصمیم به نوشیدن شراب بگیر.',NULL);
INSERT INTO "verses" VALUES(3763611,2524,3,1,'وز رَشک، چَشمِ نرگسِ رَعنا به خواب کن',NULL,NULL);
INSERT INTO "verses" VALUES(3763612,2524,3,0,'بُگْشا به شیوه، نرگسِ پُرخوابِ مست را','هوش مصنوعی: چشمان خواب آلود نرگس را باز کن تا بی‌خبر از حسادت آن، مستی و شوق را در دل بیدار کند و خواب را بر او چیره سازد.',NULL);
INSERT INTO "verses" VALUES(3763613,2524,2,1,'ساقی به دورِ بادهٔ گلگون، شتاب کُن',NULL,NULL);
INSERT INTO "verses" VALUES(3763614,2524,2,0,'اَیّامِ گُل، چو عمر به رفتن شتاب کرد','هوش مصنوعی: زمانی که گل‌ها در حال پژمرده شدن و عمر به پایان می‌رسد، ای ساقی، تو هم در خدمت بادهٔ قرمز و خوشگوار، سریع‌تر عمل کن.',NULL);
INSERT INTO "verses" VALUES(3763615,2524,1,1,'چون شیشه‌هایِ دیدهٔ ما پُرگُلاب کُن',NULL,NULL);
INSERT INTO "verses" VALUES(3763616,2524,1,0,'بِفْشان عَرَق ز چهره و اطرافِ باغ را','هوش مصنوعی: عرق خود را بر روی چهره‌ات بریز و اطراف باغ را مانند شیشه‌های چشم ما با گل خوشبو پر کنید.',NULL);
INSERT INTO "verses" VALUES(3763617,2524,0,1,'یعنی که رُخ بپوش و جهانی، خراب کُن',NULL,NULL);
INSERT INTO "verses" VALUES(3763618,2524,7,1,'یا رب! دعایِ خسته‌دلان، مُسْتَجاب کُن',NULL,NULL);
INSERT INTO "verses" VALUES(3763619,2524,0,0,'گُلبرگ را ز سُنْبُلِ مُشکین، نِقاب کُن','هوش مصنوعی: گلبرگ را با عطر گل سنبل بپوشان، یعنی چهره‌ات را بپوشان و به دل‌های مردم آسیب برسان.',NULL);
INSERT INTO "verses" VALUES(3777170,2313,6,0,'کس چو حافظ نَگُشاد، از رخِ اندیشه نقاب','هوش مصنوعی: هیچ‌کس مانند حافظ پرده از چهره‌ی اندیشه برنداشت تا بتواند به نرمی و لطافت، کلمات را آرایش کند و آنها را به زیبایی بیان کند.',NULL);
INSERT INTO "verses" VALUES(3777171,2313,5,0,'آتش آن نیست که از شعلهٔ او خندد شمع','هوش مصنوعی: آتش تنها به خاطر شعله‌اش نیست که شمع را روشن می‌کند؛ آتش واقعی آن است که در دل یک دسته پروانه افتاده و آن‌ها را به آتش می‌کشد.',NULL);
INSERT INTO "verses" VALUES(3777172,2313,5,1,'آتش آن است که در خرمنِ پروانه زدند',NULL,NULL);
INSERT INTO "verses" VALUES(3777173,2313,4,0,'شُکرِ ایزد که میانِ من و او صلح افتاد','هوش مصنوعی: سپاس خداوند را که میان من و او آشتی برقرار شد، و در این جشن، صوفیان شادمانه به رقص درآمدند و جام شکرانه را به دست گرفتند.',NULL);
INSERT INTO "verses" VALUES(3777174,2313,4,1,'صوفیان، رقص‌کنان، ساغرِ شکرانه زدند',NULL,NULL);
INSERT INTO "verses" VALUES(3777175,2313,3,0,'جنگِ هفتاد و دو ملت همه را عذر بِنه','بیشترِ قیل‌‌وقال‌ها، سخت‌گیرها و رنج‌های بشر با این اندیشه قابلِ فهمیدن است که، آدم‌ها واقعیت‌های موجود را فدایِ کمال‌گرایی‌ها، آرمان‌گراییها و حقیقت‌ها (یی که هرگز وجود نداشتند و ندارند) کردند!',NULL);
INSERT INTO "verses" VALUES(3777176,2313,3,1,'چون ندیدند حقیقت، رهِ افسانه زدند',NULL,NULL);
INSERT INTO "verses" VALUES(3777177,2313,2,0,'آسمان بارِ امانت نتوانست کشید','گویا، آن‌ شیوه‌‌ها و آموزه‌ها که از ابتدای خلقِ جهان، اصلِ وجودیِ این‌دنیا را 《در جست‌وجوی حقیقت بودن و رفتن》 می‌نمایاند، به بی‌ثمریِ خودش اقرار کرد؛ و وظیفه‌ی هدایتِ انسان‌ها را به 《واقعیت》‌ها واگذار کرد!',NULL);
INSERT INTO "verses" VALUES(3777178,2313,2,1,'قرعهٔ کار به نامِ منِ دیوانه زدند',NULL,NULL);
INSERT INTO "verses" VALUES(3777179,2313,1,0,'ساکنانِ حرمِ سِتر و عفافِ ملکوت','هوش مصنوعی: اهل حریم پاکی و عفاف آسمانی با من که در این راه قدم می‌زنم، به شادی و نوشیدن شراب مسحورکننده پرداخته‌اند.',NULL);
INSERT INTO "verses" VALUES(3777180,2313,1,1,'با منِ راه‌نشین، بادهٔ مستانه زدند',NULL,NULL);
INSERT INTO "verses" VALUES(3777181,2313,0,0,'دوش دیدم که ملائک درِ میخانه زدند','هوش مصنوعی: دیشب دیدم که فرشتگان درِ میخانه را زدند و از خاک آدمی چیزی برداشتند و در پیمانه ریختند.',NULL);
INSERT INTO "verses" VALUES(3777182,2313,6,1,'تا سرِ زلفِ سخن را، به قلم شانه زدند',NULL,NULL);
INSERT INTO "verses" VALUES(3777183,2313,0,1,'گِلِ آدم بسرشتَند و به پیمانه زدند',NULL,NULL);
INSERT INTO "verses" VALUES(3794229,2138,9,0,'حافظا می خور و رندی کن و خوش باش ولی','ای حافظ! می بخور! رندی بکن! و خوش باش! اما مانند ِ دیگران، قرآن را دامی برای مکر و فریب دادن و به دروغ زیور کردن ِ کارهای خودت قرار نده. واژه‌یِ «قرآن» در این غزل آمده‌است. و در بیت‌های این غزل تلمیح‌هایی از آیه‌ها و قصّه‌های قرآنی نیز آمده. به نوعی شاعر در بیت ِ آخر، به صراحت این موضوع را یادآوری کرده است. به شکلی که یعنی از قرآن نیز می‌توان به درستی استفاده کرد و آن را دام ِ تزویر نکرد.',NULL);
INSERT INTO "verses" VALUES(3794230,2138,0,0,'رونق عهد شباب است دگر بُستان را','دوباره نیکویی و گرمی ِ بازار ِ دوران ِ جوانی به بستان برگشته است. و به بلبل ِ خوش آواز، مژده‌یِ آمدن ِ گل می‌رسد. به‌جز این، می‌توان گفت که بستان باعث شده است که روزگار ِ جوانی ِ ما رونق بگیرد و بازار ِ آن گرم شود. در این حالت می‌توان بلبل ِ خوش‌الحان ِ مصراع ِ دوم را خود ِ شاعر در نظر گرفت که به او مژده‌یِ گُل (دیدار و وصل ِ یار) رسیده است.',NULL);
INSERT INTO "verses" VALUES(3794231,2138,1,0,'ای صبا گر به جوانان چمن باز رَسی','ای باد ِ صبا! اگر به ِ چمن های تازه سبز شده رسیدی، سلام و ارادت ِ ما را به سرو و گل و ریحان برسان. از این جمله به نظر می‌رسد که خود ِ شاعر از چمن و بوستان دور است. و از دور و به واسطه‌یِ باد ِ صبا، سلام و عرض ِ چاکری و ارادت ِ خود را به جوانان ِ چمن می‌رسانَد. جوانان ِ چمن هم می‌تواند همان درخت ِ سرو و گُل ِ سرخ و گیاهان ِ سبز و خوش‌بویِ سبزه‌زار باشد که پس از زمستان به تازگی روییده‌اند؛ و هم جوانانی که با رونق ِ عهد ِ شباب، در بوستان و چمن به تماشا و عیش و نوش مشغول اند.',NULL);
INSERT INTO "verses" VALUES(3794232,2138,1,1,'خدمت ما برسان سرو و گل و ریحان را',NULL,NULL);
INSERT INTO "verses" VALUES(3794233,2138,2,0,'گر چنین جلوه کند مغبچهٔ باده‌فروش','اگر مغبچه‌یِ باده‌فروش، این‌چنین خود را نشان بدهد و ناز و کرشمه و دلبری کند، مژه‌های خودم را جارویِ در ِ می خانه خواهم کرد. اگر مغبچه‌یِ باده‌فروش چنین به چشم ِ من در آید و دل از من ببَرَد، حاضر ام برایِ آن که مقیم ِ میخانه باشم، در هیئت ِ یک خدمت‌کار، در ِ میخانه را جارو بزنم. آن هم با مژه‌هایِ خودم.',NULL);
INSERT INTO "verses" VALUES(3794234,2138,2,1,'خاک‌روبِ درِ میخانه کنم مژگان را',NULL,NULL);
INSERT INTO "verses" VALUES(3794235,2138,3,0,'ای که بر مه کشی از عَنبرِ سارا چوگان','ای معشوقی که زلف ِ مشکین و تاب‌دار ِ خود را مانند ِ چوب ِ چوگان بر صورت‌ات افکنده‌ای (که انگار در بازی ِ چوگان گوی را به سمت ماه پرت کرده‌ای!)، من ِ آشفته را با دیدن ِ ماه ِ رخ‌ات و حرکت زلف‌ات به این سو و آن سو پریشان و مضطرب‌حال نکن!',NULL);
INSERT INTO "verses" VALUES(3794236,2138,3,1,'مضطرب‌حال مگردان، من سرگردان را',NULL,NULL);
INSERT INTO "verses" VALUES(3794237,2138,4,0,'ترسم این قوم که بر دُردکشان می‌خندند','با حالتی طعنه‌آمیز می‌گوید: می‌ترسم که آن گروه و دسته‌ئی که به شراب‌خواران می‌خندند و آن‌ها را مسخره می‌کنند، خودشان سرانجام ایمان ِ خودشان را در سر ِ کار ِ خرابات و کارهای عیاشی و فسق، دربازند و بدهند!',NULL);
INSERT INTO "verses" VALUES(3794238,2138,4,1,'در سر کار خرابات کنند ایمان را',NULL,NULL);
INSERT INTO "verses" VALUES(3794239,2138,5,0,'یار مردان خدا باش که در کشتی نوح','مفهومی که شاعر در این بیت بی نظیر در پی رساندن آن است همان خودداری از لذتی است که تورا ممکن است درگیر توفان کند! شاعر در مصراع اول مخاطب را دعوت به همراهی با یاران خدا می‌کند و در ادامه و مصراع دوم توضیح می‌دهد که اگر می‌خواهی در کشتی نوح سوار شوی و از توفان و بلا به دور باشی باید همچون خاکی (یا موجود خاکی یا همان انسان) که در کشتی نوح، بی آبی را به جان می‌خرد تا مگر نکند که طلب و دعای او توفانی را باعث شود، خوددار باشی. مردان خدا از بیم توفان آگاهند و با لذت‌های گذرا خود را به خطرِ پیاده شدن از کشتی نوح و از دست دادن هم‌نشینی با یارانِ خدا نمی‌اندازند.',NULL);
INSERT INTO "verses" VALUES(3794240,2138,5,1,'هست خاکی که به آبی نخرد طوفان را',NULL,NULL);
INSERT INTO "verses" VALUES(3794241,2138,6,0,'برو از خانهٔ گردون به در و نان مطلب','اگر به طلب ِ نان به در ِ خانه‌یِ گردون آمده‌ای، از آن خارج شو و از او طلب ِ نان مکُن! چون که این بخیل ِ رذل، سرانجام مهمان را خواهد کُشت. می گوید این گردون، مثل ِ شخص ِ سیاه‌کاسه‌ئی است که نه تنها نان به تو نخواهد داد، بلکه در آخر تو را خواهد کشت! فرار کن!',NULL);
INSERT INTO "verses" VALUES(3794242,2138,6,1,'کآن سیه‌کاسه در آخر بِکُشد مهمان را',NULL,NULL);
INSERT INTO "verses" VALUES(3794243,2138,7,0,'هر که را خوابگه آخر مشتی خاک است','خوابگاه ِ پایانی ِ هر کسی، یک مشت خاک است. بگو چه نیازی است و چه فایده دارد که خانه و عمارت و کاخ ِ خود را به آسمان برسانی و ایوان و قصر ِ بلند بسازی؟ همه سرانجام در زیر ِ مشتی خاک خواهیم خوابید.',NULL);
INSERT INTO "verses" VALUES(3794244,2138,7,1,'گو چه حاجت که به افلاک کشی ایوان را',NULL,NULL);
INSERT INTO "verses" VALUES(3794245,2138,8,0,'ماه کنعانی من! مسند مصر آنِ تو شد','ای یوسف کنعانی من (باستعاره مقصود جان پاک)کرسی فرمانروایی ملک مصر(به استعاره مقصود عالم معنی)تراست،هنگام آنست که زندان (باستعاره مقصود قفس تن یا زندان دنیا )را وداع کنی و عزیز و فرمانروا در ملک معنی شوی',NULL);
INSERT INTO "verses" VALUES(3794246,2138,8,1,'وقت آن است که بدرود کنی زندان را',NULL,NULL);
INSERT INTO "verses" VALUES(3794247,2138,9,1,'دام تزویر مکن چون دگران قرآن را',NULL,NULL);
INSERT INTO "verses" VALUES(3794248,2138,0,1,'می‌رسد مژدهٔ گل بلبل خوش‌الحان را',NULL,NULL);
INSERT INTO "verses" VALUES(3794577,2130,6,0,'حضوری گر همی خواهی از او غایب مشو حافظ','حافظ، اگر خواستار حضور در پیشگاه معشوق هستی، هرگز برای لحظه­ای از او غایب مشو؛ هرگاه به کسی که او را دوست داری، رسیدی، دنیا را رها کن و واگذار',NULL);
INSERT INTO "verses" VALUES(3794578,2130,4,0,'شبِ تاریک و بیمِ موج و گِردابی چنین هایل','ما در شبی تاریک و ظلمانی گرفتار شده‌ایم و از طرفی در گردابی سهمناک افتاده‌ایم و نگران خیزش موج‌های سهمگین هستیم؛ کسانی که با فراغ بال، آسوده خاطر بر ساحل آرمیده‌اند چگونه امکان دارد که حال ما را درک ­کنند',NULL);
INSERT INTO "verses" VALUES(3794579,2130,4,1,'کجا دانند حالِ ما سبک‌بارانِ ساحل‌ها؟',NULL,NULL);
INSERT INTO "verses" VALUES(3794580,2130,5,0,'همهْ کارم ز خودکامی به بدنامی کشید آخر','از بس گرفتار برآوردن آرزوی خود می‌باشم، بالاخره رسوا و بدنام شدم؛ چگونه امکان دارد رازی که می توان درباره اش محفل ها برگزار کرد را پنهان نمود.',NULL);
INSERT INTO "verses" VALUES(3794581,2130,5,1,'نهان کِی مانَد آن رازی کَزو سازند مَحفل‌ها؟',NULL,NULL);
INSERT INTO "verses" VALUES(3794582,2130,3,0,'به مِی سجّاده رنگین کُن گَرَت پیرِ مُغان گوید','اگر پیرمغان به تو گوید که سجاده‌ات را با شراب بیارای، بپذیر و انجام بده؛ چرا که رهرو راه خدا از آداب و رسوم مراحل طریقت به خوبی آگاه هست(نکته ۱: استفاده از فعل رنگین کردن سجاده با شراب طنز آمیز و هوشمندانه است؛ چرا که قاعدتا باید از فعل آلوده کردن یا حداقل آغشتن استفاده می‌شد اما خافظ به زیرکی از رنگین کردن بهره برده است نکته ۲: بیت به اطاعت محض و بی‌چون و چرا از پیر در طریقت اشاره دارد)',NULL);
INSERT INTO "verses" VALUES(3794583,2130,3,1,'که سالِک بی‌خبر نَبْوَد ز راه و رسمِ منزل‌ها',NULL,NULL);
INSERT INTO "verses" VALUES(3794584,2130,2,0,'مرا در منزلِ جانان چه امنِ عیش، چون هر دَم','من چگونه می‌توانم در منزل معشوق(دنیا) با امنیت به عیش و عشرت بپردازم؛ چرا که هردم بانگی بر می‌­آید و می‌گوید که برای رفتن و کوچ کردن خود را آماده کنید',NULL);
INSERT INTO "verses" VALUES(3794585,2130,2,1,'جَرَس فریاد می‌دارد که بَربندید مَحمِل‌ها',NULL,NULL);
INSERT INTO "verses" VALUES(3794586,2130,1,0,'به بویِ نافه‌ای کآخِر صبا زان طُرّه بُگشاید','به امید آنکه بالاخره باد صبا بتواند از زلف پر پیچ و تاب و مشک‌آلود معشوق عطر خوشی همچون نافه بیاورد چه خون‌ها که در دل‌ها افتاد',NULL);
INSERT INTO "verses" VALUES(3794587,2130,1,1,'ز تابِ جَعدِ مشکینش چه خون افتاد در دل‌ها',NULL,NULL);
INSERT INTO "verses" VALUES(3794588,2130,0,0,'اَلا یا اَیُّهَا السّاقی اَدِرْ کَأساً و ناوِلْها','هان ای ساقی جام شراب را به گردش درآور و به من بده؛ چرا که عشق در ابتدا آسان در نظرم جلوه‌گر شد اما در پایان دشوار و سخت شد(نکته: نکته قابل توجه و برجسته که در سرتاسر این غزل وجود دارد و دوست دارم همین ابتدا آن را خدمت شما عرض کنم، استفاده هوشمندانه و شگفت خواجه از “ها” در انتهای بیت‌ها می‌باشد؛ چرا که با این کار (استفاده از مصوت بلند آ ) حافظ گویی می‌خواهد نشانی از “آه کشیدن” در ذهن مخاطب برجا بگذارد، و چقدر تناسب شگفتی دارد با معنای مصراع دوم)',NULL);
INSERT INTO "verses" VALUES(3794589,2130,6,1,'مَتیٰ ما تَلْقَ مَنْ تَهْویٰ دَعِ الدُّنْیا وَ اَهْمِلْها',NULL,NULL);
INSERT INTO "verses" VALUES(3794590,2130,0,1,'که عشق آسان نمود اوّل ولی افتاد مشکل‌ها',NULL,NULL);
INSERT INTO "verses" VALUES(3795266,2127,39,0,'هم کام من به خدمت تو گشته منتظم','هوش مصنوعی: به خاطر محبت و مهربانی تو، هم لذت من به خدمت کردن تو سامان یافته و هم نام من با ستایش تو همیشه در یادها خواهد ماند.',NULL);
INSERT INTO "verses" VALUES(3795267,2127,10,1,'وی طلعت تو جان جهان و جهان جان',NULL,NULL);
INSERT INTO "verses" VALUES(3795268,2127,11,0,'تخت تو رشک مسند جمشید و کیقباد','هوش مصنوعی: تخت تو باعث envy تخت جمشید و کیقباد است و تاج تو نشان‌دهنده‌ی برتری بر افسر دارا و اردوان می‌باشد.',NULL);
INSERT INTO "verses" VALUES(3795269,2127,11,1,'تاج تو غبن افسر دارا و اردوان',NULL,NULL);
INSERT INTO "verses" VALUES(3795270,2127,12,0,'تو آفتاب ملکی و هر جا که می‌روی','هوش مصنوعی: تو مانند آفتاب هستی و هر جا که قدم می‌گذاری، مانند سایه‌ای، قدرت و رونق به دنبالت می‌آید.',NULL);
INSERT INTO "verses" VALUES(3795271,2127,12,1,'چون سایه از قفای تو دولت بود دوان',NULL,NULL);
INSERT INTO "verses" VALUES(3795272,2127,13,0,'ارکان نپرورد چو تو گوهر به هیچ قرن','هوش مصنوعی: هیچ کس مانند تو، جواهرات را پرورش نداده است و هیچ ستاره‌ای نیز به این زیبایی در هیچ زمانی نمی‌درخشد.',NULL);
INSERT INTO "verses" VALUES(3795273,2127,13,1,'گردون نیاورد چو تو اختر به صد قران',NULL,NULL);
INSERT INTO "verses" VALUES(3795274,2127,10,0,'ای صورت تو ملک جمال و جمال ملک','هوش مصنوعی: صورت تو مظهر زیبایی و زیبایی مظهر ذات خداوند است. چهره تو روح جهان و جهان هم روح توست.',NULL);
INSERT INTO "verses" VALUES(3795275,2127,14,0,'بی‌طلعت تو جان نگراید به کالبد','هوش مصنوعی: بدون چهره و درخشش تو، جان به بدن بی‌فایده نمی‌چسبد و مغز در استخوان نمی‌تواند جا بگیرد.',NULL);
INSERT INTO "verses" VALUES(3795276,2127,15,0,'هر دانشی که در دل دفتر نیامده‌ست','هوش مصنوعی: هر دانشی که به صورت نوشته در نیامده، در واقع مانند آبی است که بر سر زبان تو جاری است.',NULL);
INSERT INTO "verses" VALUES(3795277,2127,15,1,'دارد چو آب خامهٔ تو بر سر زبان',NULL,NULL);
INSERT INTO "verses" VALUES(3795278,2127,16,0,'دست تو را به ابر که یارد شبیه کرد‌‌؟','هوش مصنوعی: کسی نمی‌تواند مانند ابر دست تو را به آسمان بزند؛ چرا که شکاف‌های ابر به شکل‌های مختلفی ریخته می‌شود و در نهایت تنها قطرات باران از آن می‌بارند.',NULL);
INSERT INTO "verses" VALUES(3795279,2127,16,1,'چون بدره بدره این دهد و قطره قطره آن',NULL,NULL);
INSERT INTO "verses" VALUES(3795280,2127,17,0,'با پایهٔ جلال تو افلاک پایمال','هوش مصنوعی: با عظمت تو آسمان‌ها تحت تأثیر قرار گرفته‌اند و داستان‌ها در زمان، به برکت سخاوت تو شکل می‌گیرند.',NULL);
INSERT INTO "verses" VALUES(3795281,2127,17,1,'وز دست بحر جود تو در دهر داستان',NULL,NULL);
INSERT INTO "verses" VALUES(3795282,2127,18,0,'بر چرخ علم ماهی و بر فرق ملک تاج','هوش مصنوعی: در دنیای علم و دانش، تو مانند ماهی می‌درخشی و تاج حکومت به رهبری توست. شرع و دین به کمک تو و در امنیت قرار دارند.',NULL);
INSERT INTO "verses" VALUES(3795283,2127,14,1,'بی‌نعمت تو مغز نبندد در استخوان',NULL,NULL);
INSERT INTO "verses" VALUES(3795284,2127,18,1,'شرع از تو در حمایت و دین از تو در امان',NULL,NULL);
INSERT INTO "verses" VALUES(3795285,2127,9,1,'مهرش نهان چو روح در اعضای انس و جان',NULL,NULL);
INSERT INTO "verses" VALUES(3795286,2127,8,1,'از یکدگر جدا شود اجزای توأمان',NULL,NULL);
INSERT INTO "verses" VALUES(3795287,2127,0,1,'از پرتو سعادت شاه جهان‌ستان',NULL,NULL);
INSERT INTO "verses" VALUES(3795288,2127,1,0,'خاقان شرق و غرب که در شرق و غرب، اوست','هوش مصنوعی: سلطانی که در شرق و غرب فرمانروایی می‌کند، هم اوست که در دست دارد جایگاه بزرگ و افتخاری همچون سلطنت و پادشاهی در بین خدایان.',NULL);
INSERT INTO "verses" VALUES(3795289,2127,1,1,'صاحب‌قران خسرو و شاه خدایگان',NULL,NULL);
INSERT INTO "verses" VALUES(3795290,2127,2,0,'خورشید ملک‌پرور و سلطان دادگر','هوش مصنوعی: خورشید که نماد آبادانی و قدرت است، در کنار پادشاهی عادل و بخشنده قرار دارد که به عدالت و فرمانروایی خوب مشهور است.',NULL);
INSERT INTO "verses" VALUES(3795291,2127,2,1,'دارای دادگستر و کسرای کی‌نشان',NULL,NULL);
INSERT INTO "verses" VALUES(3795292,2127,3,0,'سلطان‌نشان عرصهٔ اقلیم سلطنت','هوش مصنوعی: شخصی با جلال و اقتدار در جایگاه رفیع و مرتبط با حکومت در جایی فراتر از مکان‌های معمولی نشسته است.',NULL);
INSERT INTO "verses" VALUES(3795293,2127,3,1,'بالانشین مسند ایوان لامکان',NULL,NULL);
INSERT INTO "verses" VALUES(3795294,2127,9,0,'حکمش روان چو باد در اطراف بر و بحر','هوش مصنوعی: حکم او همچون باد در حرکت است و در تمام جهان پراکنده می‌شود، در حالی که مهر و محبتش به صورت نهفته‌ای در وجود انسان‌ها و روح‌هایشان جای دارد.',NULL);
INSERT INTO "verses" VALUES(3795295,2127,4,0,'اعظم جلال دولت و دین آنکه رفعتش','هوش مصنوعی: بزرگترین جلال و شکوه دولت و دین، آن کسی است که موقعیت و مقامش همواره بر شانه‌های زمان قرار دارد.',NULL);
INSERT INTO "verses" VALUES(3795296,2127,5,0,'دارای دهر شاه شجاع آفتاب ملک','هوش مصنوعی: این جمله به توصیف شخصی می‌پردازد که در دوران خودش به عنوان فردی شجاع و با قدرت شناخته می‌شود. او به مانند آفتابی درخشان، در مقام شاهی و رهبری درخشان و موفق است. همچنین از جوانی‌اش به عنوان ویژگی مثبت او یاد شده و بر توانمندی‌هایش تأکید شده است.',NULL);
INSERT INTO "verses" VALUES(3795297,2127,5,1,'خاقان کامگار و شهنشاه نوجوان',NULL,NULL);
INSERT INTO "verses" VALUES(3795298,2127,6,0,'ماهی که شد به طلعتش افروخته زمین','هوش مصنوعی: ماهی که به زیبایی‌اش روشنایی بخشید و زمین را درخشان کرد، مانند پادشاهی است که با اراده و همّت خود، زمان را شکوه و عظمت می‌بخشد.',NULL);
INSERT INTO "verses" VALUES(3795299,2127,6,1,'شاهی که شد به همّتش افراخته زمان',NULL,NULL);
INSERT INTO "verses" VALUES(3795300,2127,7,0,'سیمرغ وهم را نبود قوّت عروج','هوش مصنوعی: در مکانی که پرنده‌ای با اراده و تلاش خود منزلگاهی می‌سازد، سیمرغ و خیالات نمی‌توانند به آن ارتفاع برسند.',NULL);
INSERT INTO "verses" VALUES(3795301,2127,7,1,'آنجا که بازِ همّت او سازد آشیان',NULL,NULL);
INSERT INTO "verses" VALUES(3795302,2127,8,0,'گر در خیال چرخ فتد عکس تیغ او','هوش مصنوعی: اگر در تصور، تصویر تیغ او در آسمان بیفتد، اجزای همزاد تو از یکدیگر جدا خواهند شد.',NULL);
INSERT INTO "verses" VALUES(3795303,2127,4,1,'دارد همیشه توسن ایام زیر ران',NULL,NULL);
INSERT INTO "verses" VALUES(3795304,2127,19,0,'ای خسرو منیع جناب رفیع قدر','هوش مصنوعی: ای بزرگ والامقام و محترم، تو دارای ارزش و منزلت بسیار بالایی هستی و همچون داور بزرگ و قدرتمند، در جایگاه والایی قرار داری.',NULL);
INSERT INTO "verses" VALUES(3795305,2127,19,1,'وی داور عظیم مثال رفیع‌ شان',NULL,NULL);
INSERT INTO "verses" VALUES(3795306,2127,20,0,'علم از تو در حمایت و عقل از تو با شکوه','هوش مصنوعی: دانش به خاطر تو در حال حمایت است و خرد با زیبایی‌اش در چشمان فضیلت درخشش دارد، تو همچون روحی در جسم ملک قرار داری.',NULL);
INSERT INTO "verses" VALUES(3795307,2127,31,0,'سال دگر ز قیصرت از روم باج سر','هوش مصنوعی: سال آینده از قیصر روم مالیات و از چین خراج جان تو را به درگاه خواهند آورد.',NULL);
INSERT INTO "verses" VALUES(3795308,2127,31,1,'وز چینت آورند به درگه خراج جان',NULL,NULL);
INSERT INTO "verses" VALUES(3795309,2127,32,0,'تو شاکری ز خالق و خلق از تو شاکرند','هوش مصنوعی: تو در شکرگزاری از خالق، و مردم هم از تو سپاسگزارند. تو به خاطر نعمت‌ها و حکومتت شادمان هستی و مردم نیز به خاطر تو خوشحالند.',NULL);
INSERT INTO "verses" VALUES(3795310,2127,32,1,'تو شادمان به دولت و ملک از تو شادمان',NULL,NULL);
INSERT INTO "verses" VALUES(3795311,2127,33,0,'اینک به طرف گلشن و بستان همی‌روی','هوش مصنوعی: اکنون به سوی باغ و گلزار می‌روی، در کنار بندگان خدا، و اسب خوشبختی را زیر پای خود داری.',NULL);
INSERT INTO "verses" VALUES(3795312,2127,33,1,'با بندگان‌، سمند سعادت به زیر ران',NULL,NULL);
INSERT INTO "verses" VALUES(3795313,2127,34,0,'ای ملهمی که در صف کروبیان قدس','هوش مصنوعی: ای الهام‌بخش، تو که به صف فرشتگان نزدیک هستی و از پاکی ذهنت فیض و نور به وجد می‌آید، لحظه لحظه زمان را مملو از برکت می‌کنی.',NULL);
INSERT INTO "verses" VALUES(3795314,2127,30,1,'از مصر تا به روم و ز چین تا به قیروان‌؟',NULL,NULL);
INSERT INTO "verses" VALUES(3795315,2127,34,1,'فیضی رسد به خاطر پاکت زمان زمان',NULL,NULL);
INSERT INTO "verses" VALUES(3795316,2127,35,1,'دارد همی به پردهٔ غیب اندرون نهان',NULL,NULL);
INSERT INTO "verses" VALUES(3795317,2127,36,0,'داده فلک عنان‌ِ ارادت به دست تو','هوش مصنوعی: آسمان اختیار و خواسته‌ام را به دست تو سپرده است، به این معنا که تو می‌توانی سرنوشت من را بر اساس میل و اراده‌ام هدایت کنی.',NULL);
INSERT INTO "verses" VALUES(3795318,2127,36,1,'یعنی که مرکبم به مراد خودم بران',NULL,NULL);
INSERT INTO "verses" VALUES(3795319,2127,37,0,'گر کوششیت افتد‌، پر داده‌ام به تیر','هوش مصنوعی: اگر تلاش و کوشش تو کم شود، من به تو بال و پر داده‌ام که بتوانی اوج بگیری. و اگر شایستگی و جود و بخشش تو نمایان باشد، به تو ثروت و نعمت داده‌ام که از آن بهره‌مند شوی.',NULL);
INSERT INTO "verses" VALUES(3795320,2127,37,1,'ور بخششیت باید‌، زر داده‌ام به کان',NULL,NULL);
INSERT INTO "verses" VALUES(3795321,2127,38,0,'خصمت کجاست‌؟ در کف پای خودش فکن','هوش مصنوعی: دشمنت کجاست؟ آن را به پای خودش بینداز. یار تو کیست؟ او را بر روی دیده‌ام نشان بده.',NULL);
INSERT INTO "verses" VALUES(3795322,2127,38,1,'یار تو کیست‌؟ بر سر چشم منش نشان',NULL,NULL);
INSERT INTO "verses" VALUES(3795323,2127,35,0,'ای آشکار پیش دلت هر چه کردگار','هوش مصنوعی: ای آنکه در دل تو هر چه خداوند اراده کرده است، به طرز پنهانی در پرده غیب نهفته است.',NULL);
INSERT INTO "verses" VALUES(3795324,2127,30,0,'آن کیست کاو به مُلک کند با تو همسری‌؟','هوش مصنوعی: این بیت به جستجوی همراه و همسری اشاره دارد که بتواند با تو در هر نقطه‌ای از دنیا همراه باشد. از سرزمین مصر تا روم و از چین تا قیروان، به دنبال کسی هستی که در این گستردگی سرزمین‌ها بتوانی با او زندگی کنید و ارتباط برقرار کنید.',NULL);
INSERT INTO "verses" VALUES(3795325,2127,29,1,'در قصرهای قیصر و در خانهای خان',NULL,NULL);
INSERT INTO "verses" VALUES(3795326,2127,29,0,'تا قصر زرد تاختی و لرزه اوفتاد','هوش مصنوعی: تا زمانی که طلاها را به دست آوردی و لرزشی در قصرهای قدرتمندان و در خانه‌های بزرگان ایجاد شد.',NULL);
INSERT INTO "verses" VALUES(3795327,2127,20,1,'در چشم فضل نوری و در جسم ملک جان',NULL,NULL);
INSERT INTO "verses" VALUES(3795328,2127,21,0,'ای آفتاب ملک که در جنب همّتت','هوش مصنوعی: ای خورشید پادشاهی که در کنار اراده و تلاشت، مانند ذره‌ای کوچک و ناچیز به حساب می‌آید، گنجینه‌ای ارزشمند وجود دارد.',NULL);
INSERT INTO "verses" VALUES(3795329,2127,21,1,'چون ذرهٔ حقیر بود گنج شایگان',NULL,NULL);
INSERT INTO "verses" VALUES(3795330,2127,22,0,'در جنب بحر جود تو از ذره کمتر است','هوش مصنوعی: بخشیدن نعمت‌ها و ثروت‌های زیادی که ارزشمند و همگان را شایسته است، در کنار بخشندگی و کرم تو مانند ذره‌ای در مقابل دریا به نظر می‌رسد.',NULL);
INSERT INTO "verses" VALUES(3795331,2127,22,1,'صد گنج شایگان که ببخشی به رایگان',NULL,NULL);
INSERT INTO "verses" VALUES(3795332,2127,23,0,'عصمت نهفته رخ به سراپرده‌ات مقیم','هوش مصنوعی: عصمت و پاکی پنهان در چهره تو است و در سایه‌سار تو آرامش و نعمت به جریان افتاده است. لباس جاودانگی به دور تو پیچیده شده است و خوشبختی در گوشه و کنار زندگی تو قابل مشاهده است.',NULL);
INSERT INTO "verses" VALUES(3795333,2127,23,1,'دولت گشاده‌رخت بقا زیر کندلان',NULL,NULL);
INSERT INTO "verses" VALUES(3795334,2127,24,0,'گردون برای خیمه خورشید فلکه‌ات','هوش مصنوعی: هوا و فضا برای خیمه‌ خورشید، از کوه‌ها و ابرها تزیین شده و به نوعی سایه‌بان آن شده است.',NULL);
INSERT INTO "verses" VALUES(3795335,2127,24,1,'از کوه و ابر ساخته پازیر و سایه‌بان',NULL,NULL);
INSERT INTO "verses" VALUES(3795336,2127,25,0,'وین اطلس مقرنس زردوز زرنگار','هوش مصنوعی: این بیت به توصیف یک چتر بزرگ و زیبای زرد و رنگارنگ اشاره دارد که به شکل اطلس و با تزئینات زیادی ظاهر شده است و می‌توان آن را بر روی خرگاه یا محلی که شخص در آن زندگی می‌کند، تصور کرد. این چتر نه تنها به عنوان یک پوشش عمل می‌کند بلکه زیبایی و شکوه خاصی را نیز به محیط اطرافش می‌بخشد.',NULL);
INSERT INTO "verses" VALUES(3795337,2127,25,1,'چتری بلند بر سر خرگاه خویش دان',NULL,NULL);
INSERT INTO "verses" VALUES(3795338,2127,26,0,'بعد از کیان به ملک سلیمان نداد کس','هوش مصنوعی: پس از دوران کیان، هیچ‌کس مانند سلیمان چنین ساز و برگی همراه با این خزانه و این لشکر بزرگ نداشته است.',NULL);
INSERT INTO "verses" VALUES(3795339,2127,26,1,'این ساز و این خزینه و این لشکر گران',NULL,NULL);
INSERT INTO "verses" VALUES(3795340,2127,27,0,'بودی درون گلشن و از پردلان تو','هوش مصنوعی: تو در دل گلستان بودی و در هند، صدای خوشی از پردلان به گوش می‌رسید و صدای ناله و فریاد نیز شنیده می‌شد.',NULL);
INSERT INTO "verses" VALUES(3795341,2127,27,1,'در هند بود غلغل و در زنگ بُد فغان',NULL,NULL);
INSERT INTO "verses" VALUES(3795342,2127,28,0,'در دشت روم خیمه زدی و غریو کوس','هوش مصنوعی: در دشت روم خیمه بر پا کرده‌ای و صدای طبل از دشت روم به دشت سیستان شنیده می‌شود.',NULL);
INSERT INTO "verses" VALUES(3795343,2127,28,1,'از دشت روم رفت به صحرای سیستان',NULL,NULL);
INSERT INTO "verses" VALUES(3795344,2127,39,1,'هم نام من به مدحت تو گشته جاودان',NULL,NULL);
INSERT INTO "verses" VALUES(3795345,2127,0,0,'شد عرصهٔ زمین چو بساط ارم جوان','هوش مصنوعی: زمین مانند مکانی دل‌انگیز و زیبا شده است، همچون بهشت که با نور و خوشبختی پادشاه جهان پر شده است.',NULL);
INSERT INTO "verses" VALUES(3796739,2335,9,0,'شعرِ حافظ در زمانِ آدم اندر باغِ خُلد','شعر حافظ در زمان آدم در باغ بهشت، زینت بخش برگ های نسرین و گل سرخ بود',NULL);
INSERT INTO "verses" VALUES(3796740,2335,0,0,'پیش از اینَت بیش از این اندیشهٔ عُشّاق بود','پیش از این، بیشتر به فکر عاشقانت بودی _ مهرورزی تو با ما در همه جا مشهور بود',NULL);
INSERT INTO "verses" VALUES(3796741,2335,1,0,'یاد باد آن صحبتِ شب‌ها که با نوشین لبان','هوش مصنوعی: به یاد می‌آورم گفتگوهای شبانه‌ای که با لب‌های شیرین، درباره‌ی رازهای عشق و ذکر حلقه‌ی عاشقان داشتیم.',NULL);
INSERT INTO "verses" VALUES(3796742,2335,1,1,'بحثِ سِرِّ عشق و ذکرِ حلقهٔ عُشّاق بود',NULL,NULL);
INSERT INTO "verses" VALUES(3796743,2335,2,0,'پیش از این کاین سقفِ سبز و طاقِ مینا بَرکِشند','پیش از این که سقف سبز و مینائی (آبی) آسمان را برافرازند (پیش از خلقت زمین و آسمان) - طاق ایوان من ابروی جانان (معشوق) بود',NULL);
INSERT INTO "verses" VALUES(3796744,2335,2,1,'مَنظَرِ چشمِ مرا ابرویِ جانان طاق بود',NULL,NULL);
INSERT INTO "verses" VALUES(3796745,2335,3,0,'از دَمِ صبحِ ازل تا آخرِ شامِ ابد','هوش مصنوعی: از شروع خلقت تا پایان زمان، دوستی و محبت همیشه پایدار و بر اساس یک پیمان بوده است.',NULL);
INSERT INTO "verses" VALUES(3796746,2335,3,1,'دوستی و مِهر بر یک عهد و یک میثاق بود',NULL,NULL);
INSERT INTO "verses" VALUES(3796747,2335,4,0,'سایهٔ معشوق اگر افتاد بر عاشق چه شد؟','هوش مصنوعی: اگر سایهٔ محبوب بر عاشق بیافتد، چه اتفاقی می‌افتد؟ ما به او نیاز داشتیم و او به ما علاقه‌مند بود.',NULL);
INSERT INTO "verses" VALUES(3796748,2335,4,1,'ما به او محتاج بودیم او به ما مشتاق بود',NULL,NULL);
INSERT INTO "verses" VALUES(3796749,2335,5,0,'حُسنِ مَه رویانِ مجلس گرچه دل می‌بُرد و دین','هوش مصنوعی: زیبایی چهره‌های دل‌فریب مجلس هرچند دل را می‌رباید، اما بحث ما درباره‌ی نیک‌سیرتی و خوبی‌رفتار است.',NULL);
INSERT INTO "verses" VALUES(3796750,2335,5,1,'بحثِ ما در لطفِ طبع و خوبیِ اخلاق بود',NULL,NULL);
INSERT INTO "verses" VALUES(3796751,2335,6,0,'بر درِ شاهم گدایی نکته‌ای در کار کرد','هوش مصنوعی: در درگاه شاه، گدایی نکته‌ای جالب گفت: وقتی بر هر سفره نشستم، خداوند روزی‌دهنده است.',NULL);
INSERT INTO "verses" VALUES(3796752,2335,6,1,'گفت بر هر خوان که بِنْشَستَم خدا رزّاق بود',NULL,NULL);
INSERT INTO "verses" VALUES(3796753,2335,7,0,'رشتهٔ تسبیح اگر بُگْسَست معذورم بدار','هوش مصنوعی: اگر رشتهٔ تسبیح من پاره شد، مرا ببخش که دستم به دامن ساقی با ساق‌های نقره‌ای افتاده است.',NULL);
INSERT INTO "verses" VALUES(3796754,2335,7,1,'دستم اندر دامنِ ساقیِ سیمین ساق بود',NULL,NULL);
INSERT INTO "verses" VALUES(3796755,2335,8,0,'در شبِ قدر ار صَبوحی کرده‌ام، عیبم مکن','اگر در شب قدر شراب صبوحی خورده ام، بر من خرده مگیر _ یار شادمان آمد و جام می هم بر طاقچه بود',NULL);
INSERT INTO "verses" VALUES(3796756,2335,8,1,'سرخوش آمد یار و جامی بر کنارِ طاق بود',NULL,NULL);
INSERT INTO "verses" VALUES(3796757,2335,9,1,'دفترِ نسرین و گُل را زینتِ اوراق بود',NULL,NULL);
INSERT INTO "verses" VALUES(3796758,2335,0,1,'مِهرورزیِ تو با ما شُهرهٔ آفاق بود',NULL,NULL);
INSERT INTO "verses" VALUES(3796759,2446,8,0,'پاک کن چهرهٔ حافظ به سَرِ زُلف زِ اَشک','اشک روی صورت حافظ را با نوک موهایت پاک کن و اگر این‌کار را نکنی، این اشک‌ها تبدیل به سیل پی‌درپی می‌شود و بنیاد و پایهٔ زندگی‌ام را نابود می‌کند.',NULL);
INSERT INTO "verses" VALUES(3796760,2446,0,0,'فاش می‌گویم و از گفتهٔ خود دلشادَم','هوش مصنوعی: من به صراحت می‌گویم و از این حرف خوشحالم که عاشق هستم و از هر دو دنیای مادی و معنوی آزاد بوده و دل‌مشغولی ندارم.',NULL);
INSERT INTO "verses" VALUES(3796761,2446,1,0,'طایرِ گلشنِ قُدسم چه دَهَم شَرحِ فِراق؟','پرنده‌ای هستم که به باغ بهشت تعلق دارد، چطور می‌توانم داستان جدایی‌ام را بگویم که چگونه به این دنیای پر از حادثه آمده‌ام.',NULL);
INSERT INTO "verses" VALUES(3796762,2446,1,1,'که در این دامگَهِ حادثه چون اُفتادم',NULL,NULL);
INSERT INTO "verses" VALUES(3796763,2446,2,0,'من مَلَک بودم و فردوسِ بَرین جایَم بود','هوش مصنوعی: در ابتدا، من موجودی آسمانی و متمایز بودم و در بهشت زندگی می‌کردم، ولی حالا به خاطر آدم، در این دنیا ویران و خالی از معنا ساکن شده‌ام.',NULL);
INSERT INTO "verses" VALUES(3796764,2446,2,1,'آدَم آوَرد دَر این دِیرِ خَراب‌آبادَم',NULL,NULL);
INSERT INTO "verses" VALUES(3796765,2446,3,0,'سایهٔ طوبی و دلجوییِ حور و لبِ حوض','لذت بودن زیر سایهٔ درخت طوبی و در آغوش حوری‌ها و آرامش نشستن لب حوض بهشتی را به‌خاطر لذت بودن در کوی تو (نزدیک تو) فراموش کرده‌ام.',NULL);
INSERT INTO "verses" VALUES(3796766,2446,3,1,'به هوایِ سَرِ کویِ تو بِرَفت از یادم',NULL,NULL);
INSERT INTO "verses" VALUES(3796767,2446,4,0,'نیست بر لوحِ دِلَم جُز اَلفِ قامَتِ دوست','هوش مصنوعی: در دل من هیچ‌چیز جز زیبایی قد و قامت محبوب وجود ندارد. چه کار می‌توانم بکنم؟ استاد به من نیاموخته هیچ حرف دیگری را.',NULL);
INSERT INTO "verses" VALUES(3796768,2446,4,1,'چه کُنَم حَرفِ دِگَر یاد نداد اُستادم',NULL,NULL);
INSERT INTO "verses" VALUES(3796769,2446,5,0,'کوکَبِ بَختِ مَرا هیچ مُنَجِّم نَشِناخت','هیچ ستاره‌شناسی نتوانست بخت و سرنوشت مرا بشناسد. ای خدای بزرگ، نمی‌دانم با چه بخت و سرنوشتی پا به این دنیا گذاشته‌ام.',NULL);
INSERT INTO "verses" VALUES(3796770,2446,5,1,'یا رَب از مادرِ گیتی به چه طالع زادم؟',NULL,NULL);
INSERT INTO "verses" VALUES(3796771,2446,6,0,'تا شُدم حَلقه به گوشِ دَرِ میخانهٔ عشق','هوش مصنوعی: وقتی به عشق و میخانه وصل شدم، هر لحظه غمی تازه به سراغم می‌آید که آن را به خوبی و خوشی تبریک می‌گویم.',NULL);
INSERT INTO "verses" VALUES(3796772,2446,6,1,'هَر دَم آیَد غَمی اَز نو به مُبارَکبادَم',NULL,NULL);
INSERT INTO "verses" VALUES(3796773,2446,7,0,'می‌خورَد خونِ دِلَم مَردُمکِ دیده، سِزاست','شایسته است که از چشمانم خون به‌جای اشک ببارد زیرا عاشق فرزند عزیز مردم شده‌ام.',NULL);
INSERT INTO "verses" VALUES(3796774,2446,7,1,'که چرا دِل به جِگرگوشهٔ مَردُم دادَم',NULL,NULL);
INSERT INTO "verses" VALUES(3796775,2446,8,1,'وَر نَه این سیلِ دَمادَم بِبَرَد بُنیادَم',NULL,NULL);
INSERT INTO "verses" VALUES(3796776,2446,0,1,'بندهٔ عشقم و از هر دو جهان آزادم',NULL,NULL);
INSERT INTO "verses" VALUES(3798723,2129,35,1,'نخست بنگرد آنگه طریق آن گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798724,2129,11,0,'من اندر آن که دم کیست این مبارک دم','هوش مصنوعی: من در فکر این هستم که چه کسی این دم مبارک را می‌داند، دم‌زدنی که در صبح زود در این خاک تیره و تار به وجود می‌آید.',NULL);
INSERT INTO "verses" VALUES(3798725,2129,12,0,'چه حالت است که گل در سحر نماید روی؟','هوش مصنوعی: چه حالتی است که گل در صبح زود چهره می‌نماید؟ چه شعله‌ای است که در پرنده صبح‌خوان به وجود می‌آید؟',NULL);
INSERT INTO "verses" VALUES(3798726,2129,12,1,'چه آتش است که در مرغ صبح‌خوان گیرد؟',NULL,NULL);
INSERT INTO "verses" VALUES(3798727,2129,14,0,'چرا به صد غم و حسرت سپهر دایره‌شکل','هوش مصنوعی: چرا زندگی‌ام پر از اندوه و حسرت شده است و من مانند نقطه‌ای در وسط دایره‌، در این نظم بی‌پایان گرفتار هستم؟',NULL);
INSERT INTO "verses" VALUES(3798728,2129,14,1,'مرا چو نقطهٔ پرگار در میان گیرد؟',NULL,NULL);
INSERT INTO "verses" VALUES(3798729,2129,15,0,'ضمیر دل نگشایم به کس مرا آن به','هوش مصنوعی: بهتر است که احساسات و درون‌دلم را به کسی نگویم، زیرا زندگی به شدت و با ناگهانی می‌تواند تغییر کند و انسان را غافل‌گیر کند.',NULL);
INSERT INTO "verses" VALUES(3798730,2129,15,1,'که روزگار غیور است و ناگهان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798731,2129,16,0,'چو شمع هر که به افشای راز شد مشغول','هوش مصنوعی: هر کسی که در فاش کردن رازها مشغول باشد، مانند شمع می‌سوزد و به محض اینکه وارد این کار شود، زمانه و دنیا مانند قیچی به زبان او آسیب می‌زند.',NULL);
INSERT INTO "verses" VALUES(3798732,2129,16,1,'بسش زمانه چو مقراض در زبان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798733,2129,17,0,'کجاست ساقی مه‌روی من که  از سر مهر','هوش مصنوعی: کجاست معشوق زیبای من که از روی محبت و عشق، مثل چشمان خمار خودش، جام پر از می را با محبت به دست بگیرد؟',NULL);
INSERT INTO "verses" VALUES(3798734,2129,17,1,'چو چشم مست خودش ساغر گران گیرد؟',NULL,NULL);
INSERT INTO "verses" VALUES(3798735,2129,18,0,'پیامی آورد از یار و در پی‌اش جامی','هوش مصنوعی: پیام خوشی از دوست رسید و به دنبال آن، جامی پر از شادی و سرور که نماد زیبایی آن دوست مهربان باشد، آماده شد.',NULL);
INSERT INTO "verses" VALUES(3798736,2129,18,1,'به شادی رخ آن یار مهربان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798737,2129,19,0,'نوای مجلس ما را چو برکشد مطرب','هوش مصنوعی: صدای ساز در مجلس ما آن‌قدر زیباست که گاهی ما را به یاد عراق و گاهی به یاد اصفهان می‌اندازد.',NULL);
INSERT INTO "verses" VALUES(3798738,2129,19,1,'گهی عراق زند گاهی اصفهان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798739,2129,20,0,'فرشته‌ای به حقیقت سروش عالم غیب','هوش مصنوعی: فرشته‌ای از دنیای نامرئی، حقیقتی را به ما می‌آورد که در آن، باغ‌های بهشت از رحمت او بهره‌مند می‌شوند.',NULL);
INSERT INTO "verses" VALUES(3798740,2129,20,1,'که روضهٔ کرمش نکته بر جنان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798741,2129,11,1,'که وقت صبح در این تیره خاکدان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798742,2129,10,0,'ز اتحاد هیولا و اختلاف صور','هوش مصنوعی: از یکسو ترکیب ماده اولیه و از سوی دیگر تنوع شکل‌ها و صورت‌ها، از هر گل جدید، تصاویری از صد بت به وجود می‌آید.',NULL);
INSERT INTO "verses" VALUES(3798743,2129,10,1,'خرد ز هر گل نو، نقش صد بتان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798744,2129,9,0,'صبا نگر که دمادم چو رند شاهدباز','هوش مصنوعی: ای نسیم، نگاه کن که هر لحظه همچون رند عاشق، گاهی به گل‌ها می‌نگرد و گاهی در زلف محبوبش حوصله و شوق می‌یابد.',NULL);
INSERT INTO "verses" VALUES(3798745,2129,0,0,'سپیده‌دم که صبا بوی لطف جان گیرد','هوش مصنوعی: در سپیده‌دم، زمانی که نسیم صبحگاهی بوی خوشی می‌آورد، باغ و چمن از زیبایی و لطافت هوا شگفت‌زده و مسحور می‌شوند.',NULL);
INSERT INTO "verses" VALUES(3798746,2129,1,0,'هوا ز نکهت گل در چمن تتق بندد','هوش مصنوعی: نسیم ملایم از عطر گل‌ها در چمن می‌وزد و افق به خاطر انعکاس رنگ شفق، رنگ و بوی گلستان را به خود می‌گیرد.',NULL);
INSERT INTO "verses" VALUES(3798747,2129,1,1,'افق ز عکس شفق رنگ گلستان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798748,2129,2,0,'نوای چنگ بدان‌سان زند صلای صبوح','هوش مصنوعی: صدای چنگ به گونه‌ای در دل می‌نوازد که مانند ندای صبح زود است و آن‌قدر دلنشین است که حتی پیر مغان، که معمولاً در سبکی خاص زندگی می‌کند، مجذوب آن شده و راهی به سوی مغان پیدا می‌کند.',NULL);
INSERT INTO "verses" VALUES(3798749,2129,2,1,'که پیر صومعه راه در مغان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798750,2129,3,0,'نکال شب که کند در قدح سیاهی مشک','هوش مصنوعی: هنگامی که شب به پایان می‌رسد و لحظات سپیده دم فرامی‌رسد، سیاهی‌های شب در ظرفی به مانند مشک جمع می‌شود و جرقه‌های روشنی از چراغ صبحگاهی در آن ظاهر می‌شود.',NULL);
INSERT INTO "verses" VALUES(3798751,2129,3,1,'در او شرار چراغ سحرگهان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798752,2129,4,0,'شه سپهر چو زرین سپر کشد در روی','هوش مصنوعی: در زمانی که خورشید مانند سپری طلایی در آسمان ظاهر می‌شود و با اولین پرتوهای صبحینش افق را روشن می‌کند، جهان را در برگرفته است.',NULL);
INSERT INTO "verses" VALUES(3798753,2129,21,0,'سکندری که مقیم حریم او چون خضر','هوش مصنوعی: کسی که در حوزه حضور او زندگی می‌کند، مانند خضر که از نعمت خاک درب او بهره‌مند می‌شود، عمری ابدی خواهد داشت.',NULL);
INSERT INTO "verses" VALUES(3798754,2129,4,1,'به تیغ صبح و عمود افق جهان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798755,2129,5,0,'به رغم زال سیه شاهباز زرین بال','هوش مصنوعی: علیرغم اینکه زال، که فرمانروای سیاه‌چهره است، در جایگاه خود قرار دارد، یک شاهباز با بال‌های طلایی در این محل زنگ‌آلود و کهنه، جا خواهد گرفت.',NULL);
INSERT INTO "verses" VALUES(3798756,2129,6,0,'به بزم‌گاه چمن رو که خوش تماشایی است','هوش مصنوعی: به میهمانی گلستان برو که مناظر آن بسیار زیباست، مانند لاله که کاسه‌های نسرین و گل ارغوان را در آغوش گرفته است.',NULL);
INSERT INTO "verses" VALUES(3798757,2129,6,1,'چو لاله کاسهٔ نسرین و ارغوان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798758,2129,7,0,'چو شهسوار فلک بنگرد به جام صبوح','هوش مصنوعی: وقتی که ستاره‌ای درخشان به آسمان نگاه می‌کند و نور صبحگاهی را در جام خود می‌بیند، متوجه می‌شود که چگونه خورشید نخستین نور خود را از سمت شرق می‌تاباند.',NULL);
INSERT INTO "verses" VALUES(3798759,2129,7,1,'که چون به شعشعهٔ مهر خاوران گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798760,2129,8,0,'محیط شمس کشد سوی خویش در خوشآب','هوش مصنوعی: محیط شمس به خاطر زیبایی و دل‌نشینی‌اش افراد را به سوی خود می‌کشاند تا آنها را به تسلط و اختیار خود درآورد.',NULL);
INSERT INTO "verses" VALUES(3798761,2129,8,1,'که تا به قبضهٔ شمشیر زرفشان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798762,2129,9,1,'گهی لب گل و گه زلف ضیمران گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798763,2129,5,1,'در این مقرنس زنگاری آشیان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798764,2129,21,1,'ز فیض خاک درش عمر جاودان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798765,2129,22,0,'جمال چهرهٔ اسلام شیخ ابو اسحاق','هوش مصنوعی: زیبایی چهرهٔ اسلام شیخ ابو اسحاق به قدری است که اگر در کنار او پادشاهی باشد، مانند گل در باغچه‌های زیبا جلوه‌گری کند.',NULL);
INSERT INTO "verses" VALUES(3798766,2129,22,1,'که ملک در قدمش زیب بوستان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798767,2129,34,0,'مذاق جانش ز تلخی غم شود ایمن','هوش مصنوعی: کسی که طعم شیرینی تو را بچشد، از تلخی‌های زندگی و غم‌ها در امان خواهد بود.',NULL);
INSERT INTO "verses" VALUES(3798768,2129,34,1,'کسی که شکر شکر تو در دهان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798769,2129,35,0,'ز عمر برخورد آن کس که در جمیع صفات','هوش مصنوعی: زندگی کسی ارزشمند است که ابتدا به ویژگی‌ها و صفات آدم‌ها توجه کند و بعد از آن راه خود را انتخاب کند.',NULL);
INSERT INTO "verses" VALUES(3798770,2129,36,0,'چو جای جنگ نبیند به جام یازد دست','هوش مصنوعی: هرگاه در نبرد نشود، چنین شخصی از جام می‌نوشد، اما زمانی که وقت کار است، تیغ را برای گرفتن جان به دست می‌گیرد.',NULL);
INSERT INTO "verses" VALUES(3798771,2129,36,1,'چو وقت کار بود تیغ جان‌ستان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798772,2129,37,0,'ز لطف غیب به سختی رخ از امید متاب','هوش مصنوعی: از رحمت الهی ناامید نشو، حتی در سخت‌ترین شرایط، زیرا ممکن است در باطن وضعیت برایت خوب شود و مقام و جایگاه باارزشی به دست آوری.',NULL);
INSERT INTO "verses" VALUES(3798773,2129,37,1,'که مغز نغز مقام اندر استخوان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798774,2129,38,0,'شکر کمال حلاوت پس از ریاضت یافت','هوش مصنوعی: بعد از سختی‌ها و تلاش‌های بسیار، شیرینی واقعی به دست می‌آید و انسان متوجه می‌شود که اگر از مکان‌های تنگ و دشوار عبور کند، می‌تواند به لذت و خوشی دست یابد.',NULL);
INSERT INTO "verses" VALUES(3798775,2129,33,0,'وگرنه پایهٔ عزت از آن بلندتر است','هوش مصنوعی: اگر نه، پایهٔ عزت آن‌چنان بلند است که زمان نمی‌تواند آن را محک بزند.',NULL);
INSERT INTO "verses" VALUES(3798776,2129,38,1,'نخست در شکن تنگ از آن مکان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798777,2129,39,0,'در آن مقام که سیل حوادث از چپ و راست','هوش مصنوعی: در موقعیتی که حوادث ناگوار از هر سو به شدت به انسان حمله‌ور می‌شوند و او از هیچ‌یک از راه‌های فرار و نجات خود نمی‌تواند استفاده کند.',NULL);
INSERT INTO "verses" VALUES(3798778,2129,39,1,'چنان رسد که امان از میان کران گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798779,2129,40,0,'چه غم بود به همه حال کوه ثابت را','هوش مصنوعی: چه غمی است برای کوه استوار وقتی که امواج سنگین دریا به او برخورد می‌کنند؟',NULL);
INSERT INTO "verses" VALUES(3798780,2129,40,1,'که موجهای چنان قلزم گران گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798781,2129,41,0,'اگرچه خصم تو گستاخ می‌رود حالی','هوش مصنوعی: اگرچه دشمنت بی‌پروا و جسورانه به جلو می‌رود، اما تو باید خوشحال باشی زیرا این بی‌احترامی او به خودش آسیب خواهد زد.',NULL);
INSERT INTO "verses" VALUES(3798782,2129,41,1,'تو شاد باش که گستاخی‌اش چنان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798783,2129,42,0,'که هر چه در حق این خاندان دولت کرد','هوش مصنوعی: هر کسی که نسبت به این خاندان نیکی کند، پاداش آن را به خانواده و فرزندانش خواهد دید.',NULL);
INSERT INTO "verses" VALUES(3798784,2129,42,1,'جزاش در زن و فرزند و خان و مان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798785,2129,43,0,'زمان عمر تو پاینده باد کـ‌این نعمت','هوش مصنوعی: امیدوارم زمان عمر تو همیشه پایدار باشد، زیرا این نعمت، برکت و هدیه‌ای است که در زندگی و روح انسان تأثیر می‌گذارد.',NULL);
INSERT INTO "verses" VALUES(3798786,2129,43,1,'عطیه‌ای است که در کار انس و جان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798787,2129,33,1,'که روزگار بر او حرف امتحان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798788,2129,32,0,'از امتحان تو ایام را غرض آن است','هوش مصنوعی: هدف از آزمایش تو این است که از خالصی و پاکی دل تو در زمان‌های مختلف نمایان شود.',NULL);
INSERT INTO "verses" VALUES(3798789,2129,23,0,'گهی که بر فلک سروری عروج کند','هوش مصنوعی: زمانی که فردی به مقام و مرتبه‌ای بلند در آسمان‌ها دست یابد، اولین نشانه این تعالی و سروری، تغییر و بهترین خوی در وجود او خواهد بود.',NULL);
INSERT INTO "verses" VALUES(3798790,2129,23,1,'نخست پایهٔ خود فرق فرقدان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798791,2129,24,0,'چراغ دیدهٔ محمود آن که دشمن را','هوش مصنوعی: چشمان محمود به قدری درخشان است که می‌تواند با تیغ آتشینش، دشمنان را به شدت بترساند و نابود کند.',NULL);
INSERT INTO "verses" VALUES(3798792,2129,24,1,'ز برق تیغ وی آتش به دودمان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798793,2129,25,0,'به اوج ماه رسد موج خون چو تیغ کشد','هوش مصنوعی: وقتی خون به اوج ماه می‌رسد، گویی که به تیغی آماده برای جنگ تبدیل شده است و همچون کمانی که تیر را به سمت هدف نشانه می‌گیرد، به سوی آسمان حمله‌ور می‌شود.',NULL);
INSERT INTO "verses" VALUES(3798794,2129,25,1,'به تیر چرخ برد حمله چون کمان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798795,2129,26,0,'عروس خاوری از شرم رأی انور او','هوش مصنوعی: عروس روز را به خاطر زیبایی خاص خود نمی‌توان به راحتی نادیده گرفت و او بدون شک در جایگاه خودش قرار دارد، حتی اگر راهی به دوری و سختی برود.',NULL);
INSERT INTO "verses" VALUES(3798796,2129,26,1,'به جای خود بود ار راه قیروان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798797,2129,32,1,'که از صفای ریاضت دلت نشان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798798,2129,27,0,'ایا عظیم وقاری که هر که بندهٔ توست','هوش مصنوعی: ای بزرگ و والامقام، کسی که به تو وابسته است، به خاطر ارادتش به تو، از عظمت و بزرگی تو بهره‌مند می‌شود.',NULL);
INSERT INTO "verses" VALUES(3798799,2129,28,0,'رسد ز چرخ عطارد هزار تهنیتت','هوش مصنوعی: از آسمان سیاره عطارد هزاران تبریک به تو می‌رسد، همان‌طور که تفکر تو دستور می‌دهد و همه چیز به تحقق می‌پیوندد.',NULL);
INSERT INTO "verses" VALUES(3798800,2129,28,1,'چو فکرتت صفت امر کن فکان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798801,2129,29,0,'مدام در پی طعن است بر حسود و عدوت','هوش مصنوعی: همیشه در جستجوی انتقاد از حسودان و دشمنان است، زیرا از آن روز تا شب، تیرهای خود را نشانه‌گیری می‌کند.',NULL);
INSERT INTO "verses" VALUES(3798802,2129,29,1,'سماک رامح از آن روز و شب سنان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798803,2129,30,0,'فلک چو جلوه‌کنان بنگرد سمند تو را','هوش مصنوعی: وقتی آسمان با زیبایی به تو نگاه کند، اسب تو به قدری عالی است که می‌تواند در بالاترین نقطه کهکشان قرار گیرد.',NULL);
INSERT INTO "verses" VALUES(3798804,2129,30,1,'کمینه پایگهش اوج کهکشان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798805,2129,31,0,'ملالتی که کشیدی سعادتی دهدت','هوش مصنوعی: غم و اندوهی که تحمل کردی، در نهایت به تو سعادت و خوشبختی می‌بخشد، به گونه‌ای که به تو فرصتی می‌دهد تا از کار و تلاش خود بهره‌مند شوی.',NULL);
INSERT INTO "verses" VALUES(3798806,2129,31,1,'که مشتری نسق کار خود از آن گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798807,2129,27,1,'ز رفع قدر کمربند توأمان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3798808,2129,0,1,'چمن ز لطف هوا نکته بر جنان گیرد',NULL,NULL);
INSERT INTO "verses" VALUES(3840629,2094,0,0,'سرای مدرسه و بحثِ عِلم و طاق و رَواق','هوش مصنوعی: مدرسه و محیط علمی و بحث و گفتگو درباره علم چه فایده‌ای دارد، وقتی دل آدم‌های دانا و چشم‌های بینای واقعی وجود ندارد؟',NULL);
INSERT INTO "verses" VALUES(3840630,2094,0,1,'چه سود، چون دلِ دانا و چشمِ بینا نیست؟',NULL,NULL);
INSERT INTO "verses" VALUES(3840631,2094,1,0,'سرای قاضی یزد اَرچه منبعِ فضل است','هوش مصنوعی: خانه قاضی یزد اگرچه منبعی از دانش و فضیلت است، ولی در آن‌جا خبری از علم و تفکر عمیق نیست.',NULL);
INSERT INTO "verses" VALUES(3840632,2094,1,1,'خلاف نیست که عِلمِ نظر در آن‌جا نیست',NULL,NULL);
INSERT INTO "verses" VALUES(3841377,2148,8,0,'حافظ از بادِ خزان در چمنِ دَهر مَرَنج','کاربر: حافظ می‌گوید که از سختی های روزگار در مسیر مقصودت رنجیده خاطر نشو همان طور عقل حکم میکند هیچ مقصودی بدون سختی و رنج بدست نمی آید.',NULL);
INSERT INTO "verses" VALUES(3841378,2148,0,1,'منزلِ آن مَهِ عاشق‌کُشِ عَیّار کجاست؟',NULL,NULL);
INSERT INTO "verses" VALUES(3841379,2148,1,0,'شبِ تار است و رَهِ وادیِ اَیمَن در پیش','هوش مصنوعی: در شب تاریک، راهی که به سرزمین امن و آرامش می‌رسد پیش رو است، اما مکان ملاقات در آتش کوه طور کجاست؟',NULL);
INSERT INTO "verses" VALUES(3841380,2148,1,1,'آتشِ طور کجا موعدِ دیدار کجاست؟',NULL,NULL);
INSERT INTO "verses" VALUES(3841381,2148,2,0,'هر که آمد به جهان نقشِ خرابی دارد','آمدن به جهان همراه است با وارد شدن در چرخه‌ی فنا و ناپایداری ، در خرابات، همه مستِ حقیقت‌اند و آنچه «هوشیاری» دنیوی نامیده می‌شود (حسابگری، سود و زیان، ترس و امید معمولی) دیگر جایی ندارد.',NULL);
INSERT INTO "verses" VALUES(3841382,2148,2,1,'در خرابات بگویید که هُشیار کجاست؟',NULL,NULL);
INSERT INTO "verses" VALUES(3841383,2148,3,0,'آن‌کس است اهلِ بشارت که اشارت داند','هوش مصنوعی: کسی که می‌تواند به دیگران خوش‌خبری بدهد، باید به رمز و رازها آشنا باشد. حالا این نکته‌های پنهان، که رازها را در بر دارند، در کجا می‌توان یافت؟',NULL);
INSERT INTO "verses" VALUES(3841384,2148,3,1,'نکته‌ها هست بسی مَحرمِ اسرار کجاست؟',NULL,NULL);
INSERT INTO "verses" VALUES(3841385,2148,4,0,'هر سرِ مویِ مرا با تو هزاران کار است','هوش مصنوعی: هر یک از تارهای موی من با تو ارتباطات و مسائل بسیاری دارد. ما در کجا و کسانی که بی‌دلیل ما را سرزنش می‌کنند در کجا هستند؟',NULL);
INSERT INTO "verses" VALUES(3841386,2148,4,1,'ما کجاییم و مَلامت‌گرِ بی‌کار کجاست؟',NULL,NULL);
INSERT INTO "verses" VALUES(3841387,2148,5,0,'باز پرسید ز گیسویِ شِکَن در شِکَنَش','اگر می‌خواهید بدانید که دل عاشق من کجا گرفتار شده بروید از گیسویِ مجعد و پیچیده‌اش بپرسید.',NULL);
INSERT INTO "verses" VALUES(3841388,2148,5,1,'کاین دلِ غم‌زده سرگشته گرفتار کجاست؟',NULL,NULL);
INSERT INTO "verses" VALUES(3841389,2148,6,0,'عقل دیوانه شد آن سلسلهٔ مُشکین کو؟','عقل ما دیوانه شد آن زنجیر خوشبو (زلف یار) کجاست؟ دل با ما قهر کرد، (گوشه و اشاره) ابروی دلدار کجاست؟ (تا دل با ما آشتی کند)',NULL);
INSERT INTO "verses" VALUES(3841390,2148,6,1,'دل ز ما گوشه گرفت ابرویِ دلدار کجاست؟',NULL,NULL);
INSERT INTO "verses" VALUES(3841391,2148,7,0,'ساقی و مُطرب و مِی جمله مُهَیّاست ولی','هوش مصنوعی: بیا ساقی، ساز و شراب همه فراهم است، اما خوشی و لذت بدون حضور یار کامل نمی‌شود. پس یار کجاست؟',NULL);
INSERT INTO "verses" VALUES(3841392,2148,7,1,'عیش بی‌یار مُهیّا نشود یار کجاست؟',NULL,NULL);
INSERT INTO "verses" VALUES(3841393,2148,8,1,'فکرِ معقول بفرما گُلِ بی‌خار کجاست؟',NULL,NULL);
INSERT INTO "verses" VALUES(3841394,2148,0,0,'ای نسیمِ سحر آرامگَهِ یار کجاست؟','ای باد سحر (صبا: باد سحرگاهی که در نزد شعرا معروف هست بر اینکه نامه‌ی عاشق را به معشوق میبرد و بو و نسیم یار را به عاشق میرساند) تو که خبر داری بگو محل آرامش و خواب یار کجاست؟ منزل آن ماهِ زیبای عاشق کش چالاک (همگی توصیف کننده‌ی یار هست) کجاست؟',NULL);
INSERT INTO "verses" VALUES(3842821,2231,6,0,'حافظ نهادِ نیکِ تو کامت بر آورد','حافظ، سرشت نیکوی تو، آرزویت را برآورده کرد، جان‌ها فدای مردم نیکو سرشت باد. ( حافظ در این بیت، به نیکوکاری و خوش‌قلبی خود اشاره می‌کند و می‌گوید که این صفات، باعث رسیدن او به آرزوهایش شده است. او در پایان، برای همه نیکوکاران دعا می‌کند. )',NULL);
INSERT INTO "verses" VALUES(3842822,2231,5,0,'از دست رفته بود وجودِ ضعیفِ من','وجود ضعیف من در حال نابودی بود، که باد صبحگاهی با بوی وصال تو به من جان دوباره بخشید. ( حافظ در این بیت، به امید و اشتیاق خود برای وصال معشوق اشاره می‌کند. او می‌گوید که بوی وصال معشوق، مانند اکسیری شفابخش، جان تازه‌ای به او بخشیده است. )',NULL);
INSERT INTO "verses" VALUES(3842823,2231,5,1,'صبحم به بویِ وصلِ تو جان باز داد، باد',NULL,NULL);
INSERT INTO "verses" VALUES(3842824,2231,4,0,'خون شد دلم به یادِ تو هر گَه که در چمن','هرگاه که باد، بند قبای غنچه گل را در چمن باز می‌کرد ( غنچه گل می‌شکفت )، دلم به یاد تو خون می‌شد. ( حافظ در این بیت، از یادآوری معشوق در هر لحظه سخن می‌گوید. او می‌گوید که حتی وزش باد و باز شدن غنچه‌ها نیز او را به یاد معشوق می‌اندازد و دلش را خون می‌کند. )',NULL);
INSERT INTO "verses" VALUES(3842825,2231,4,1,'بندِ قبایِ غنچهٔ گل می‌گشاد باد',NULL,NULL);
INSERT INTO "verses" VALUES(3842826,2231,3,0,'امروز قدرِ پندِ عزیزان شناختم','امروز ارزش نصیحت عزیزان را فهمیدم، خدایا روح نصیحت‌کننده ما را شاد کن. ( حافظ در این بیت، به اهمیت نصیحت و راهنمایی دوستان اشاره می‌کند. او که در گذشته شاید به نصیحت‌ها بی‌توجه بوده، اکنون قدر آن‌ها را می‌داند و برای نصیحت‌کنندگان دعا می‌کند. باتوجه به فضای حاکم بر غزلیات خواجه شیراز این نصیحت ها وابسته به دید خواننده است. این نصیحت می‌تواند عشق ورزی، بی توجهی به مادیات، تفکر نکردن درباره پیچیدگی های هستی،‌ دوری از زرق و ریا، و یا هرچیز دیگری بسته به دید شخصی خواننده باشد )',NULL);
INSERT INTO "verses" VALUES(3842827,2231,3,1,'یا رب روانِ ناصحِ ما از تو شاد باد',NULL,NULL);
INSERT INTO "verses" VALUES(3842828,2231,2,0,'در چینِ طرهٔ تو دل بی حِفاظِ من','دل بی‌حفاظ من در پیچ و خم زلف تو، هرگز یاد خانه و مسکن همیشگی خود را نکرد. ( حافظ در این بیت، به عشق بی‌قید و شرط خود به معشوق اشاره می‌کند. او می‌گوید که دلش چنان درگیر زلف زیبای معشوق شده که حتی یاد خانه و آرامش خود را هم فراموش کرده است. )',NULL);
INSERT INTO "verses" VALUES(3842829,2231,2,1,'هرگز نگفت مسکنِ مألوف یاد باد',NULL,NULL);
INSERT INTO "verses" VALUES(3842830,2231,1,0,'کارم بدان رسید که همرازِ خود کنم','کارم به جایی رسیده که ( از تنهایی ) برق درخشان شب ( عبارت برق درخشان شب در این بیت دارای معانی متعددی است. مثل آذرخش درخشان، نور ستارگان، شعله آتش عشق درون عاشق) و باد صبحگاهی را همراز خود می‌کنم. ( حافظ در این بیت، تنهایی و انزوای خود را نشان می‌دهد. او که از هجران یار در رنج است، با عناصر طبیعت هم‌صحبت می‌شود و آن‌ها را همراز خود قرار می‌دهد. )',NULL);
INSERT INTO "verses" VALUES(3842831,2231,1,1,'هر شام برق لامِع و هر بامداد باد',NULL,NULL);
INSERT INTO "verses" VALUES(3842832,2231,0,0,'دوش آگهی ز یارِ سفر کرده داد باد','دیشب باد خبری از یار سفر کرده‌ام آورد، من نیز دلم را به باد می‌دهم، هر چه می‌خواهد بشود. ( حافظ در این بیت، از خبری که باد از معشوق سفر کرده‌اش آورده، سخن می‌گوید. او که دلتنگ و بی‌قرار است، تصمیم می‌گیرد دلش را به دست باد بسپارد و تسلیم سرنوشت شود. عبارت "هر چه باد باد" نشان‌دهنده تسلیم و رضا به تقدیر است. )',NULL);
INSERT INTO "verses" VALUES(3842833,2231,6,1,'جان‌ها فدایِ مردمِ نیکو نهاد باد',NULL,NULL);
INSERT INTO "verses" VALUES(3842834,2231,0,1,'من نیز دل به باد دهم، هر چه باد باد',NULL,NULL);
INSERT INTO "verses" VALUES(3844600,2448,9,0,'گر به دیوانِ غزل صدرنشینم چه عجب؟','هوش مصنوعی: اگر در میان غزل‌ها مقام بلندی دارم، جای تعجبی نیست؛ زیرا سال‌ها در خدمت صاحب اثر بوده‌ام.',NULL);
INSERT INTO "verses" VALUES(3844601,2448,0,1,'تا به فتویّ خِرَد حرص به زندان کردم',NULL,NULL);
INSERT INTO "verses" VALUES(3844602,2448,1,0,'من به سرمنزلِ عَنْقا نه به خود بُردم راه','من به سرمنزل عنقا که مرحله نهایی ورسیدن به کمال است بخودی خود نرسیدم قطعا وقطع بیقین اینکاررابا کمک وهمراهی هدهد که جانان .میباشد به اینجا رسیدم',NULL);
INSERT INTO "verses" VALUES(3844603,2448,1,1,'قطعِ این مرحله با مرغِ سلیمان کردم',NULL,NULL);
INSERT INTO "verses" VALUES(3844604,2448,2,0,'سایه‌ای بر دلِ ریشم فِکَن ای گنجِ روان','هوش مصنوعی: ای گنجینهٔ گران‌بهاء، سایه‌ای بر دل زخمی‌ام بینداز، چرا که من به خاطر تو این خانه را به ویرانی کشانده‌ام.',NULL);
INSERT INTO "verses" VALUES(3844605,2448,2,1,'که من این خانه به سودایِ تو ویران کردم',NULL,NULL);
INSERT INTO "verses" VALUES(3844606,2448,3,0,'توبه کردم که نبوسم لبِ ساقی و کنون','هوش مصنوعی: تصمیم گرفته بودم که دیگر لبِ ساقی را نبوسم، اما حالا خودم را سرزنش می‌کنم که چرا به حرف‌های نادان گوش کردم و این کار را انجام دادم.',NULL);
INSERT INTO "verses" VALUES(3844607,2448,3,1,'می‌گَزَم لب که چرا گوش به نادان کردم',NULL,NULL);
INSERT INTO "verses" VALUES(3844608,2448,4,0,'در خِلاف‌آمدِ عادت بطلب کام! که من','بر خلاف عادت عمل کردن و تنوع طلبی مایه کامجویی است. اگر ازین مسیر دنبال کام خود باشی در همه چیز آثار خالق را می بینی و دلت به وجود او قرص شده، خاطرت جمع خواهد شد.',NULL);
INSERT INTO "verses" VALUES(3844609,2448,4,1,'کسب جمعیت از آن زلفِ پریشان کردم',NULL,NULL);
INSERT INTO "verses" VALUES(3844610,2448,5,0,'نقش مستوری و مستی نه به دستِ من و توست','هوش مصنوعی: بازی و جلوه‌گری و حالاتی که داریم، به اراده و اختیار ما نیست. آنچه که خداوند از ابتدا مقدر کرده است، من هم همان را انجام داده‌ام.',NULL);
INSERT INTO "verses" VALUES(3844611,2448,5,1,'آن چه سلطانِ ازل گفت بکن، آن کردم',NULL,NULL);
INSERT INTO "verses" VALUES(3844612,2448,6,0,'دارم از لطفِ ازل جنَّتِ فردوس طمع','هوش مصنوعی: من از نعمت‌های خداوند در بهشت جاویدان امید دارم، هرچند که در راه رسیدن به این هدف، به بسیار نوشیدن در میخانه پرداختم.',NULL);
INSERT INTO "verses" VALUES(3844613,2448,6,1,'گرچه دربانی میخانه فراوان کردم',NULL,NULL);
INSERT INTO "verses" VALUES(3844614,2448,7,0,'این که پیرانه‌سَرَم صحبتِ یوسف بنواخت','هوش مصنوعی: اینکه در سال‌های پیری‌ام، از جانب یوسف به من توجهی شده، پاداش صبر و تحملی است که در روزهای سخت و ناامیدی کشیده‌ام.',NULL);
INSERT INTO "verses" VALUES(3844615,2448,7,1,'اجر صبریست که در کلبهٔ احزان کردم',NULL,NULL);
INSERT INTO "verses" VALUES(3844616,2448,8,0,'صبح‌خیزی و سلامت طلبی چون حافظ','هوش مصنوعی: صبح زود بلند شدن و سلامت و خوشحالی را طلب کردن، مانند حافظ، من هر کاری که انجام دادم، به برکت نعمت‌های قرآن بوده است.',NULL);
INSERT INTO "verses" VALUES(3844617,2448,8,1,'هر چه کردم همه از دولتِ قرآن کردم',NULL,NULL);
INSERT INTO "verses" VALUES(3844618,2448,9,1,'سال‌ها بندگیِ صاحبِ دیوان کردم',NULL,NULL);
INSERT INTO "verses" VALUES(3844619,2448,0,0,'سال‌ها پیرُویِ مذهبِ رندان کردم','هوش مصنوعی: سال‌ها پیرو مذهب و طرز تفکر آزاداندیشان بوده‌ام، تا اینکه به نتیجه‌گیری عقلانی رسیدم و آرزوهای بی‌جا را به بند کشیدم.',NULL);
INSERT INTO "verses" VALUES(3845876,2182,6,0,'گُناه اگرچه نبود اختیارِ ما، «حافظ»!','گناه اگر چه در اختیار آدمی نیست اما باید مؤدب و باحیا باشد و بگوید که گناه من است.',NULL);
INSERT INTO "verses" VALUES(3845877,2182,5,0,'از آن زَمان که بر این آسْتان نَهادم روی','از روزی که بر این آستان دولت و سعادت روی آورده‌ام بر بالای جایگاه خورشید تکیه زده‌ام.',NULL);
INSERT INTO "verses" VALUES(3845878,2182,5,1,'فَرازِ مَسْنَدِ خورشید، تِکْیِه‌گاهِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(3845879,2182,4,0,'مَگَر به تیغِ اَجَل، خیمه بَرکَنَم ور نی','این دیدارهای سعادت‌بار را رسم و راه خود کرده‌ام و از آن دست بر نمی‌دارم مگر مرگ مرا باز‌دارد.',NULL);
INSERT INTO "verses" VALUES(3845880,2182,4,1,'رَمیدن از دَرِ دولت، نه رَسْم و راهِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(3845881,2182,3,0,'غَرَض زِ مَسْجِد و مِیخانه‌ام، وِصالِ شماست','هدف از رفتن به مسجد و میخانه‌، دیدن شماست و بجز این قصدی ندارم خدا بر این گواه است.',NULL);
INSERT INTO "verses" VALUES(3845882,2182,3,1,'جُز این خیال ندارم، خُدا، گُواهِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(3845883,2182,2,0,'ز پادشاه و گِدا، فارِغم بِحَمْدِالله','خدا را شکر می‌گویم که نه بندهٔ کسی هستم و نه کسی مرا بنده است اما بندهٔ گدای کوی یار هستم.',NULL);
INSERT INTO "verses" VALUES(3845884,2182,2,1,'گِدایِ خاکِ دَرِ دوست، پادشاهِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(3845885,2182,1,0,'گَرَم ترانهٔ چنگ صَبوح نیست چه باک','اگرچه نوای خوش چنگ در سحرگاه در دسترس من نیست اما آه سحرگاه من به‌همان مقدار نوای چنگ خوش‌نواست.',NULL);
INSERT INTO "verses" VALUES(3845886,2182,1,1,'نوایِ من به سَحَر، آهِ عُذْرخواهِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(3845887,2182,0,0,'منم که گوشهٔ میخانه، خانقاهِ من است','آنکه مقیم گوشه میخانه است منم و آن‌را به‌چشم خانقاه خود می‌نگرم و سحرگاهان پیر خرابات را دعای خیر می‌گویم.',NULL);
INSERT INTO "verses" VALUES(3845888,2182,6,1,'تو در طریقِ اَدَب باش، گو گُناهِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(3845889,2182,0,1,'دعایِ پیرِ مُغان، وِرْدِ صُبْحگاهِ من است',NULL,NULL);
INSERT INTO "verses" VALUES(3845890,2540,7,0,'خوش چمنیست عارضت خاصه که در بهار حسن','هوش مصنوعی: چهره زیبای تو در واقع بهاری است که باعث می‌شود شعرهای دلنشین حافظ به زندگی بیایند و صدای شاعرانه تو را زنده کند.',NULL);
INSERT INTO "verses" VALUES(3845891,2540,6,1,'جای دعاست شاه من بی‌تو مباد جای تو',NULL,NULL);
INSERT INTO "verses" VALUES(3845892,2540,6,0,'شاه‌نشین چشم من تکیه‌گه خیال توست','هوش مصنوعی: چشم من مانند یک کاخ مجلل است که خیال تو در آن جا دارد. اینجا محل دعا کردن است و ای پادشاه من، بدون تو هیچ‌چیز نمی‌شود.',NULL);
INSERT INTO "verses" VALUES(3845893,2540,5,1,'کاین سر پُر هوس شود خاک در سرای تو',NULL,NULL);
INSERT INTO "verses" VALUES(3845894,2540,5,0,'شور شراب عشق تو آن نفسم رود ز سر','هوش مصنوعی: عشق تو به قدری شور و شوق دارد که نفسم از سرم می‌رود، زیرا این سر پر از هوس به خاک سرای تو تبدیل می‌شود.',NULL);
INSERT INTO "verses" VALUES(3845895,2540,4,1,'این همه نقش می‌زنم از جهت رضای تو',NULL,NULL);
INSERT INTO "verses" VALUES(3845896,2540,4,0,'خرقهٔ زهد و جام مِی گرچه نه درخور همند','حافظ به ظاهر متناقض «زهد» و «مِی» اشاره می‌کند؛ اما در عرفان، «مِی» نماد شور و جذبهٔ الهی‌ست، و «زهد» نماد تلاش انسان برای کنترل نفس. حافظ می‌گوید اگرچه این دو در ظاهر سازگار نیستند، اما من همهٔ این بازی‌ها را برای رضایت تو – یعنی محبوب حقیقی – انجام می‌دهم. این همان جمع اضداد است که در عرفان اسلامی جایگاه بلندی دارد.',NULL);
INSERT INTO "verses" VALUES(3845897,2540,3,1,'گوشهٔ تاج سلطنت می‌شکند گدای تو',NULL,NULL);
INSERT INTO "verses" VALUES(3845898,2540,3,0,'دولت عشق بین که چون از سر فقر و افتخار','این بیت، فقر عاشقانه را از سلطنت دنیوی بالاتر می‌داند، و گدای عاشق را بر تخت عزت می‌نشاند.',NULL);
INSERT INTO "verses" VALUES(3845899,2540,2,1,'قال و مقال عالَمی می‌کشم از برای تو',NULL,NULL);
INSERT INTO "verses" VALUES(3845900,2540,2,0,'من که ملول گشتمی از نفس فرشتگان','حافظ می‌گوید حتی از «نَفَس فرشتگان» که نماد پاکی و عاری بودن از شهوت‌اند، خسته شده‌ام، و اکنون «قال و مقال» یعنی کشمکش‌های عاشقانه و دنیایی را تنها برای تو، ای معشوق الهی، تحمل می‌کنم. این نشانگر عبور از مقام ملَکوت به جبروت است؛ همان‌جا که عارف برای قرب به حق، از خلوت فرشتگان نیز می‌گذرد و به میان آتش و خون عاشقی می‌زند.',NULL);
INSERT INTO "verses" VALUES(3845901,2540,1,1,'کز سر صدق می‌کند شب همه شب دعای تو',NULL,NULL);
INSERT INTO "verses" VALUES(3845902,2540,1,0,'ای گل خوش‌نسیمِ من بلبلِ خویش را مسوز','«بلبل» نمایندهٔ سالک عاشق است و «گل خوش‌نسیم» اشاره به ذات محبوب است که به جهان حیات و طراوت می‌بخشد. حافظ خود را این بلبل می‌داند و از معشوق می‌خواهد که این عاشق صادق را که با صدق و خلوص در شب‌های تاریک به دعا و مناجات مشغول است، نسوزاند. این اشاره‌ای‌ست به مرحلهٔ توبه و انابه در سلوک، جایی که سالک با اخلاص کامل رو به معشوق دارد.',NULL);
INSERT INTO "verses" VALUES(3845903,2540,0,1,'پردهٔ غنچه می‌درد خندهٔ دلگشای تو',NULL,NULL);
INSERT INTO "verses" VALUES(3845904,2540,7,1,'حافظِ خوش‌کلام شد مرغِ سخن‌سرایِ تو',NULL,NULL);
INSERT INTO "verses" VALUES(3845905,2540,0,0,'تاب بنفشه می‌دهد طرّهٔ مشک‌سای تو','حافظ در این بیت با زبانی نمادین به زیبایی مطلق معشوق اشاره می‌کند. «طرهٔ مشک‌سای» نمادی از زلف الهی است که مشک را شرمنده می‌کند، یعنی بوی خوشش از هر عطر طبیعی برتر است. «خنده دلگشا» نماد تجلیات جمال الهی است که همچون نوری، حجاب‌های طبیعت (پردهٔ غنچه) را می‌درد. این بیت آغازی‌ست بر شهود جمال محبوب حقیقی.',NULL);
INSERT INTO "verses" VALUES(3845954,2137,8,0,'صبر کن حافظ به سختی روز و شب','ای حافظ، روز و شب در برابرِ سختی و دشواری و رنج و فقر و تنگ‌دستی صبور باش! سرانجام روزی به کام و خواستهٔ دل و لذّت و بهره‌مندی و معشوق دست خواهی‌ یافت. میانِ معنیِ فقر و تنگ‌دستی برای سختی، با بهره‌مندی و خوشی برای کام تناسب هست.',NULL);
INSERT INTO "verses" VALUES(3845955,2137,0,1,'خاک بر سر کن غمِ ایّام را',NULL,NULL);
INSERT INTO "verses" VALUES(3845956,2137,1,0,'ساغرِ مِی بر کَفَم نِه تا ز بَر','از ساقی می‌خواهد که جامِ می به او بدهد تا او بنوشد و لباسِ صوفیانه و زاهدانهٔ خود را از تن دربیاورد. دلق و خرقه، لباسی بوده که آن را از سر به تن می‌کردند و از سر نیز بیرون می‌آوردند. از بر برکشم، جدا از جناس میانِ برها، بالاکشیدن و بیرون‌آوردنِ لباس از بالا را نشان می‌دهد. این حسِّ از سر بیرون آوردن، به‌نوعی شکلِ انزجار و اعتراض‌آمیز را هم به تصوّر می‌‌آورد. این برکشیدنِ دلقِ ازرق‌فام، نشان می‌دهد که شاعر، چنین دلقی را به تن داشته و این‌چنین، قصد و ادّعای خود برای درآوردنِ این قماش جامه از تنِ خود را اعلام کرده‌است.',NULL);
INSERT INTO "verses" VALUES(3845957,2137,1,1,'بَرکِشَم این دلقِ اَزرَق‌فام را',NULL,NULL);
INSERT INTO "verses" VALUES(3845958,2137,2,0,'گرچه بدنامی‌ست نزد عاقلان','در ادامهٔ بیتِ پیشین که گفت ساغرِ می بر کفِ من بنه تا دلقِ ازرق‌فام را از سر بیرون آورم، ادامه می‌دهد که: گرچه این کار نزدِ عاقلان رسوایی و بی‌آبرویی و بدنامی محسوب می‌شود، ولی ما قیدِ آبرو و اعتبار و خوش‌نامی خود را زده‌ایم و دیگر ننگ و نام را نمی‌خواهیم و به‌دنبالِ آن هم نیستیم.',NULL);
INSERT INTO "verses" VALUES(3845959,2137,2,1,'ما نمی‌خواهیم ننگ و نام را',NULL,NULL);
INSERT INTO "verses" VALUES(3845960,2137,3,0,'باده دَردِه چند از این بادِ غرور','باده را بده! تا کی می‌خواهیم در بادِ کِبر و نِخوَتِ خود بمانیم و فریفتهٔ آن شویم؟ الهی که خاک بر سرِ این نفسِ ملامت‌گرِ بی‌فایده شود! هم‌چنین می‌توان گفت: باده را بده! تا کی قرار است این نفسِ نافرجامِ خاک بر سر، درگیرِ بادِ غرورِ خودش باشد! هم‌چنین اگر نفس را به معنای تن و کالبد و جسد و شخصِ انسان در نظر بگیریم، عبارتِ خاک بر سر، می‌تواند اشاره‌ای به این باشد که این نفسِ نافرجام و این جسمی که ابدی نیست و فرجامی ندارد، در نهایت بر سرش خاک خواهد آمد و در زیرِ خاک مدفون خواهد شد. لذا باده بده! چه‌قدر بادِ غرور می‌خواهد داشته باشد این تنِ نافرجامی که خاک بر سرِ آن خواهد آمد!',NULL);
INSERT INTO "verses" VALUES(3845961,2137,3,1,'خاک بر سر، نفسِ نافرجام را',NULL,NULL);
INSERT INTO "verses" VALUES(3845962,2137,4,0,'دودِ آهِ سینهٔ نالانِ من','دودِ آهِ دلِ سوزانِ من، این خامانِ سرد و منجمد را سوزاند. خام در معنای آدمِ ناپخته و بی‌تجربه و ناآزموده، می‌تواند با محتوای کلّی غزل سازگار باشد. خاصه که در بیت‌های پیشین، درباره‌ی قضاوتِ عاقلان دربارهٔ اقدامِ شاعر در از تن بیرون‌کردنِ دلقِ ازرق‌فام گفته‌است. به‌عبارتی می‌گوید، این دودِ آهِ سینهٔ نالانِ من، این آدم‌های ناپخته و منفعل و سرد و فسرده را هم سوزانده‌است.',NULL);
INSERT INTO "verses" VALUES(3845963,2137,4,1,'سوخت این افسردگانِ خام را',NULL,NULL);
INSERT INTO "verses" VALUES(3845964,2137,5,0,'محرمِ رازِ دلِ شیدایِ خود','از خاصّ و عام (چه آدم‌های نزدیک و آشنا و دوست و محرم و چه آدم‌‌های دور و غریبه و نامحرم) هیچ‌کس را نمی‌بینم که بتوانم رازِ دلِ شیدای خودم را با او در میان بگذارم. جدا از معنای دوست و غریبه بودن اشخاص، عبارت‌های خَواصّ و عوام، خاصّان و عامیان و خاصّ و عام، نوعی دسته‌بندی مردم است به افرادی که برگزیده‌اند و به‌عبارتی شناخت و دانش و علم و اخلاقِ برگزیده دارند؛ و عوام‌النّاس کسانی که برگزیده نیستند و در آن طبقهٔ فاضل‌ها قرار نمی‌گیرند.',NULL);
INSERT INTO "verses" VALUES(3845965,2137,5,1,'کس نمی‌بینم ز خاص و عام را',NULL,NULL);
INSERT INTO "verses" VALUES(3845966,2137,6,0,'با دلارامی مرا خاطر خوش است','خاطر و ضمیر و قلبِ من با دلارام و معشوقی خوش است که از دلِ من، به ناگهان و به‌کلّی آرام را بُرد. آرایهٔ متناقض‌نما میانِ دل‌آرامی که آرام را از دل می‌بَرَد و با این کار، خاطر را خوش می‌کند، هست. اگر این بیت را در ادامهٔ بیتِ پیشین در نظر بگیریم، می‌شود گفت رازی که به خاصّ و عام نمی‌تواند بگوید، شاید به همین خاطر بوده که کسی باور نمی‌کرده که دل‌آرامی که از دل، آرام را برده، مایهٔ خوشیِ خاطرِ شاعر است.',NULL);
INSERT INTO "verses" VALUES(3845967,2137,6,1,'کز دلم یک باره بُرد آرام را',NULL,NULL);
INSERT INTO "verses" VALUES(3845968,2137,7,0,'ننگرد دیگر به سرو اندر چمن','هرکسی‌که آن یارِ سروقد با اندامی سفید و درخشان را ببیند، دیگر رغبتی ندارد که به درختِ سروی که در چمن و سبزه‌زار هست، نگاه کند.',NULL);
INSERT INTO "verses" VALUES(3845969,2137,7,1,'هرکه دید آن سروِ سیم‌اندام را',NULL,NULL);
INSERT INTO "verses" VALUES(3845970,2137,8,1,'عاقبت روزی بیابی کام را',NULL,NULL);
INSERT INTO "verses" VALUES(3845971,2137,0,0,'ساقیا برخیز و دَردِه جام را','ای ساقی! برخیز و جام را عطا کن. و خاک بر سرِ غمِ ایّام کُن. برخیز! عبارتی است مانندِ خواهش و امرِ مهرآمیز که امروز هم بزرگ‌ترها به کوچک‌ترها می‌گویند. مثلِ «پا شو فلان کار را بکن» هم‌چنین برخیز می‌تواند نشان از این باشد که صبح است و شاعر از ساقی درخواست می‌کند که از خواب بیدار شود و جامِ باده‌ای به او بدهد و با این کار، خاک بر سرِ غمِ زمانه کُنَد. هم‌‌چنین حسِّ سردردِ خمارِ سحرگاهی، در خاک بر سر کردن به ذهن می‌آید. مضمونِ فراموش‌کردنِ غمِ ایّام با شراب در شعرهای حافظ بسیار به‌کار رفته‌است. خاک بر سر کردن، به نوعی کُشتن و مدفون‌کردنِ غمِ روزگار را هم در خود دارد.',NULL);
INSERT INTO "verses" VALUES(3846486,2159,6,0,'حافظ! هر آن که عشق نَورزید و وصل خواست','هوش مصنوعی: هر کسی که در عشق ورزیدن کوتاهی کرد و به وصال نرسید، در حقیقت بدون آمادگی و خلوص، سفر معنوی به دلش را آغاز کرده است.',NULL);
INSERT INTO "verses" VALUES(3846487,2159,5,0,'مطرب چه پرده ساخت که در پردهٔ سماع','هوش مصنوعی: موسیقی‌دان چه نغمه‌ای نواخته که در حال رقص و شادی، فریاد و غوغا را بر جمعیتی که در حالت وجد و شادی هستند، خاموش کرده است.',NULL);
INSERT INTO "verses" VALUES(3846488,2159,5,1,'بر اهل وجد و حال، درِ های‌وهو ببست',NULL,NULL);
INSERT INTO "verses" VALUES(3846489,2159,4,0,'یا رب چه غمزه کرد صُراحی که خون خُم','هوش مصنوعی: ای خدا، عجب ناز و کرشمه‌ای دارد این شراب، که با صدای غزل و نعره‌اش، خون جام را در گلویم محبوس کرده است.',NULL);
INSERT INTO "verses" VALUES(3846490,2159,4,1,'با نعره‌های قُلقُلش اندر گلو ببست',NULL,NULL);
INSERT INTO "verses" VALUES(3846491,2159,3,0,'ساقی به چند رنگ، می اندر پیاله ریخت','هوش مصنوعی: بیا ساقی، می را با رنگ‌های زیبا در جام بریز و به این نقش‌های زیبا نگاه کن که چقدر خوب در کدو بسته شده‌اند.',NULL);
INSERT INTO "verses" VALUES(3846492,2159,3,1,'این نقش‌ها نگر که چه خوش در کدو ببست',NULL,NULL);
INSERT INTO "verses" VALUES(3846493,2159,2,0,'شیدا از آن شدم که نگارم چو ماه نو','هوش مصنوعی: من به خاطر زیبایی‌های معشوقم مجنون شده‌ام، چون او با ابروانش چون هلال ماه درخشید و با جلوه‌گری‌اش، پرده‌ای از زیبایی بر چهره‌اش کشید.',NULL);
INSERT INTO "verses" VALUES(3846494,2159,2,1,'ابرو نُمود و جلوه‌گری کرد و رو ببست',NULL,NULL);
INSERT INTO "verses" VALUES(3846495,2159,1,0,'تا عاشقان به بوی نسیمش دهند جان','هوش مصنوعی: عاشقانی که به عطر نسیم جان می‌دهند، با بوی نافه‌ای زندگی را آغاز کردند و درهای آرزو بسته شد.',NULL);
INSERT INTO "verses" VALUES(3846496,2159,1,1,'بگشود نافه‌ایّ و دَرِ آرزو ببست',NULL,NULL);
INSERT INTO "verses" VALUES(3846497,2159,0,0,'زلفت هزار دل به یکی تار مو ببست','هوش مصنوعی: زیبایی و جاذبه‌های موهایت به قدری زیاد است که هزاران دل را به خود مشغول کرده و تمام راه‌حل‌های عاشقانه را در اطراف خود بسته‌ای.',NULL);
INSERT INTO "verses" VALUES(3846498,2159,6,1,'احرامِ طوفِ کعبهٔ دل، بی‌وضو ببست',NULL,NULL);
INSERT INTO "verses" VALUES(3846499,2159,0,1,'راه هزار چاره‌گر از چارسو ببست',NULL,NULL);
INSERT INTO "verses" VALUES(5075334,2129,13,0,'چه پرتو است که نور چراغ صبح دهد','هوش مصنوعی: این عبارت به زیبایی از نوری سخن می‌گوید که صبح را روشن می‌کند و آسمان را با شعله‌ای زیبا پر می‌کند. به نوعی، به قدرت و تاثیر منبع نوری اشاره دارد که باعث بروز روشنایی و زندگی می‌شود. این نور می‌تواند به عنوان نماد امید و شروعی تازه در نظر گرفته شود.',NULL);
INSERT INTO "verses" VALUES(5075335,2129,13,1,'چه شعله است که در شمع آسمان گیرد؟',NULL,NULL);
INSERT INTO "verses" VALUES(5078822,141013,0,0,'گفتم که خطا کردی و تدبیر نه این بود','هوش مصنوعی: به او گفتم که اشتباه کرده‌ای و راه درست این نیست. او پاسخ داد که چه کار می‌توان کرد وقتی سرنوشت این‌گونه رقم خورده است.',NULL);
INSERT INTO "verses" VALUES(5078823,141013,0,1,'گفتا چه توان کرد که تقدیر چنین بود',NULL,NULL);
INSERT INTO "verses" VALUES(5078824,141013,1,0,'گفتم که بسی خط خطا بر تو کشیدند','هوش مصنوعی: گفتم که خیلی از اشتباهات و اتهامات به تو نسبت داده‌اند. او پاسخ داد که همه آن‌ها همان‌طور که بر پیشانی‌ام نوشته شده بود، قدر و سرنوشت من بودند.',NULL);
INSERT INTO "verses" VALUES(5078825,141013,1,1,'گفتا همه آن بود که بر لوح جبین بود',NULL,NULL);
INSERT INTO "verses" VALUES(5078826,141013,2,0,'گفتم که چرا مهر تو را ماه بگردید؟','هوش مصنوعی: گفتم چرا عشق تو مانند ماه تغییر کرد و به دور افتاد؟ پاسخ داد که آسمان بر من به خاطر حسد بدرفتاری کرده است.',NULL);
INSERT INTO "verses" VALUES(5078827,141013,2,1,'گفتا که فلک بر من بد مهر به کین بود',NULL,NULL);
INSERT INTO "verses" VALUES(5078828,141013,3,0,'گفتم که قرین بدت افکند بدین روز','هوش مصنوعی: گفتم که بدی تو را به این روز انداخت، او گفت که بدی‌های من به خاطر بدشانسی خودم است.',NULL);
INSERT INTO "verses" VALUES(5078829,141013,3,1,'گفتا که مرا بخت بد خویش قرین بود',NULL,NULL);
INSERT INTO "verses" VALUES(5078830,141013,4,0,'گفتم که بسی جام تعب خوردی ازین پیش','هوش مصنوعی: به او گفتم که قبل از این خیلی در زندگی درد و رنج کشیده‌ای، اما او پاسخ داد که درمان و آرامش در جام آخرین است.',NULL);
INSERT INTO "verses" VALUES(5078831,141013,4,1,'گفتا که شفا در قدح باز پسین بود',NULL,NULL);
INSERT INTO "verses" VALUES(5078832,141013,5,0,'گفتم که تو ای عمر مرا زود برفتی','هوش مصنوعی: به او گفتم که ای عمر، چرا به سرعت سپری شدی؟ او پاسخ داد که چه کار می‌توانم بکنم، عمر همین‌گونه است.',NULL);
INSERT INTO "verses" VALUES(5078833,141013,5,1,'گفتا که فلانی چه کنم عمر همین بود؟',NULL,NULL);
INSERT INTO "verses" VALUES(5078834,141013,6,0,'گفتم که نه وقت سفرت بود چو رفتی','هوش مصنوعی: به او گفتم که الان زمان سفر تو نیست، اما او پاسخ داد که شاید حکمتی در این زمان سفر کردن نهفته باشد.',NULL);
INSERT INTO "verses" VALUES(5078835,141013,6,1,'گفتا که مگر مصلحت وقت درین بود',NULL,NULL);
INSERT INTO "verses" VALUES(5253521,145450,0,0,'آفتاب از روی او شد در حجاب',NULL,NULL);
INSERT INTO "verses" VALUES(5253522,145450,0,1,'سایه را باشد حجاب از آفتاب',NULL,NULL);
INSERT INTO "verses" VALUES(5253523,145450,1,0,'دست ماه و مهر بربندد به حسن',NULL,NULL);
INSERT INTO "verses" VALUES(5253524,145450,1,1,'ماه بی‌مهرم چو بردارد نقاب',NULL,NULL);
INSERT INTO "verses" VALUES(5253525,145450,2,0,'از خیالم باز نشناسد کسی',NULL,NULL);
INSERT INTO "verses" VALUES(5253526,145450,2,1,'گر در آغوشت نبینم شب به خواب',NULL,NULL);
INSERT INTO "verses" VALUES(5253527,145450,3,0,'خون دل در جام دیدیم از سرشک',NULL,NULL);
INSERT INTO "verses" VALUES(5253528,145450,3,1,'آب رو بر باد دادیم از شراب',NULL,NULL);
INSERT INTO "verses" VALUES(5253529,145450,4,0,'شاهدان مستور و مستان بی‌شکیب',NULL,NULL);
INSERT INTO "verses" VALUES(5253530,145450,4,1,'خانقه معمور است و درویشان خراب',NULL,NULL);
INSERT INTO "verses" VALUES(5253531,145450,5,0,'سوز مستان گر بداند محتسب',NULL,NULL);
INSERT INTO "verses" VALUES(5253532,145450,5,1,'در دم از می‌شان زند بر آتش آب',NULL,NULL);
INSERT INTO "verses" VALUES(5253533,145450,6,0,'هر که را از دیده باران بینی اشک',NULL,NULL);
INSERT INTO "verses" VALUES(5253534,145450,6,1,'زیر دامن باده دارد چون سحاب',NULL,NULL);
INSERT INTO "verses" VALUES(5253535,145450,7,0,'از برای باده می‌باید زدن',NULL,NULL);
INSERT INTO "verses" VALUES(5253536,145450,7,1,'محتسب را حد بی حد و حساب',NULL,NULL);
INSERT INTO "verses" VALUES(5253537,145450,8,0,'حافظا واعظ نصیحت گو مکن',NULL,NULL);
INSERT INTO "verses" VALUES(5253538,145450,8,1,'تَرک ترکان ختا نبود صواب',NULL,NULL);
INSERT INTO "verses" VALUES(5253539,145451,0,0,'مدتی شد کآتش سودای تو در جان ماست',NULL,NULL);
INSERT INTO "verses" VALUES(5253540,145451,0,1,'زآن تمنایی که دایم در دل ویران ماست',NULL,NULL);
INSERT INTO "verses" VALUES(5253541,145451,1,0,'مردم چشمم به خوناب جگر غرقند از آن',NULL,NULL);
INSERT INTO "verses" VALUES(5253542,145451,1,1,'چشمهٔ مهر رخش در سینهٔ نالان ماست',NULL,NULL);
INSERT INTO "verses" VALUES(5253543,145451,2,0,'آب حیوان قطره‌ای زآن لعل همچون شکر است',NULL,NULL);
INSERT INTO "verses" VALUES(5253544,145451,2,1,'قرص خور عکسی ز روی آن مه تابان ماست',NULL,NULL);
INSERT INTO "verses" VALUES(5253545,145451,3,0,'تا نفحت فیه من روحی شنیدم شد یقین',NULL,NULL);
INSERT INTO "verses" VALUES(5253546,145451,3,1,'بر من این معنی که ما زآن وی و او زان ماست',NULL,NULL);
INSERT INTO "verses" VALUES(5253547,145451,4,0,'حافظا تا روز آخر شکر این نعمت گزار',NULL,NULL);
INSERT INTO "verses" VALUES(5253548,145451,4,1,'کآن صنم از روز اول مونس و مهمان ماست',NULL,NULL);
INSERT INTO "verses" VALUES(5253549,145455,0,0,'آن کیست تا به حضرت سلطان ادا کند',NULL,NULL);
INSERT INTO "verses" VALUES(5253550,145455,0,1,'کز جور چرخ گشت شتر گربه‌ها پدید',NULL,NULL);
INSERT INTO "verses" VALUES(5253551,145455,1,0,'رندی نشست بر سر سجّادۀ قضا',NULL,NULL);
INSERT INTO "verses" VALUES(5253552,145455,1,1,'حیزی دگر به مرتبۀ سروری رسید',NULL,NULL);
INSERT INTO "verses" VALUES(5253553,145455,2,0,'آن رند گفت چشم و چراغ انس منم',NULL,NULL);
INSERT INTO "verses" VALUES(5253554,145455,2,1,'وآن حیز گفت نطفۀ داودم و فرید',NULL,NULL);
INSERT INTO "verses" VALUES(5253555,145455,3,0,'ای آصف زمانه ز بهر خدا بگو',NULL,NULL);
INSERT INTO "verses" VALUES(5253556,145455,3,1,'با خسروی که دولت او هست برمزید',NULL,NULL);
INSERT INTO "verses" VALUES(5253557,145455,4,0,'شاها روا مدار که مفعول من یراد',NULL,NULL);
INSERT INTO "verses" VALUES(5253558,145455,4,1,'گردد به روزگار تو فعّال من یرید',NULL,NULL);
INSERT INTO "verses" VALUES(5253559,145456,0,0,'دل مبند ای مرد بخرد بر سخای عمر و زید',NULL,NULL);
INSERT INTO "verses" VALUES(5253560,145456,0,1,'کس نمی‌داند که کارش از کجا خواهد گشاد',NULL,NULL);
INSERT INTO "verses" VALUES(5253561,145456,1,0,'رو توکل کن نمی‌دانی که نوک کلک من',NULL,NULL);
INSERT INTO "verses" VALUES(5253562,145456,1,1,'نقش هر صورت که زد رنگی دگر بیرون فتاد',NULL,NULL);
INSERT INTO "verses" VALUES(5253563,145456,2,0,'شاه هرموزم ندید و بی سخن صد لطف کرد',NULL,NULL);
INSERT INTO "verses" VALUES(5253564,145456,2,1,'شاه یزدم دید و مدحش کردم و هیچم نداد',NULL,NULL);
INSERT INTO "verses" VALUES(5253565,145456,3,0,'کار شاهان این چنین باشد تو ای حافظ مرنج',NULL,NULL);
INSERT INTO "verses" VALUES(5253566,145456,3,1,'داور و روزی‌رسان توفیق و نصرتْشان دهاد',NULL,NULL);
INSERT INTO "verses" VALUES(5253567,145457,0,0,'تنم ز رنج فراوان همی نیاساید',NULL,NULL);
INSERT INTO "verses" VALUES(5253568,145457,0,1,'دلم از انده بی حد همی بفرساید',NULL,NULL);
INSERT INTO "verses" VALUES(5253569,145457,1,0,'ز بس غمان که بدیدم چنان شدم که مرا',NULL,NULL);
INSERT INTO "verses" VALUES(5253570,145457,1,1,'از این و آنچه غمی پیش چشم نگراید',NULL,NULL);
INSERT INTO "verses" VALUES(5253571,145457,2,0,'که گر ببیند بدخواه من مرا روزی',NULL,NULL);
INSERT INTO "verses" VALUES(5253572,145457,2,1,'به چشم او رخ من زردنگ ننماید',NULL,NULL);
INSERT INTO "verses" VALUES(5253573,145457,3,0,'چو من به مهر دل خویش اندر این بندم',NULL,NULL);
INSERT INTO "verses" VALUES(5253574,145457,3,1,'حجاب دور کند فتنه‌ای پدید آید',NULL,NULL);
INSERT INTO "verses" VALUES(5253575,145458,0,0,'صباح جمعه بُد و سادس ربیع نخست',NULL,NULL);
INSERT INTO "verses" VALUES(5253576,145458,0,1,'که از دلم رخ آن ماهروی شد زائل',NULL,NULL);
INSERT INTO "verses" VALUES(5253577,145458,1,0,'به سال هفتصد و شصت و چهار از هجرت',NULL,NULL);
INSERT INTO "verses" VALUES(5253578,145458,1,1,'چو آب گشت به‌من حل حکایت مشکل',NULL,NULL);
INSERT INTO "verses" VALUES(5253579,145458,2,0,'دریغ و درد و تأسف کجا دهد سودی',NULL,NULL);
INSERT INTO "verses" VALUES(5253580,145458,2,1,'کنون که عمر به بازیچه رفت بی‌حاصل',NULL,NULL);
INSERT INTO "verses" VALUES(5253581,145459,0,0,'درین وادی به بانگ سیل بشنو',NULL,NULL);
INSERT INTO "verses" VALUES(5253582,145459,0,1,'که صد من خون مظلومان به یک جو',NULL,NULL);
INSERT INTO "verses" VALUES(5253583,145459,1,0,'پر جبریل را اینجا بسوزند',NULL,NULL);
INSERT INTO "verses" VALUES(5253584,145459,1,1,'بدان تا کودکان آتش فروزند',NULL,NULL);
INSERT INTO "verses" VALUES(5253585,145459,2,0,'سخن گفتن که‌را یاراست اینجا؟',NULL,NULL);
INSERT INTO "verses" VALUES(5253586,145459,2,1,'تعالی اله چه استغناست اینجا',NULL,NULL);
INSERT INTO "verses" VALUES(5253587,145459,3,0,'برو حافظ درین معرض مزن دم',NULL,NULL);
INSERT INTO "verses" VALUES(5253588,145459,3,1,'سخن کوتاه کن والله اعلم',NULL,NULL);
INSERT INTO "verses" VALUES(5253840,145497,0,0,'دل شوق لبت مدام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(5253841,145497,0,1,'یا رب ز لبت چه کام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(5253842,145497,1,0,'جان عشرت مهر و باده شوق‌',NULL,NULL);
INSERT INTO "verses" VALUES(5253843,145497,1,1,'در ساغر دل مدام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(5253844,145497,2,0,'شوریدهٔ زلف یار دایم‌',NULL,NULL);
INSERT INTO "verses" VALUES(5253845,145497,2,1,'در دام بلا مقام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(5253846,145497,3,0,'آخر نرسد که باز پرسیم‌',NULL,NULL);
INSERT INTO "verses" VALUES(5253847,145497,3,1,'کآن دلبر ما چه نام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(5253848,145497,4,0,'با یار کجا نشیند آن کاو',NULL,NULL);
INSERT INTO "verses" VALUES(5253849,145497,4,1,'اندیشه خاص و عام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(5253850,145497,5,0,'خرّم دل آن کسی که صحبت‌',NULL,NULL);
INSERT INTO "verses" VALUES(5253851,145497,5,1,'با یار علی‌الدّوام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(5253852,145497,6,0,'تا صید کند دلی بشوخی‌',NULL,NULL);
INSERT INTO "verses" VALUES(5253853,145497,6,1,'بر گل ز بنفشه دام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(5253854,145497,7,0,'حافظ چو دمی خوش است مجلس‌',NULL,NULL);
INSERT INTO "verses" VALUES(5253855,145497,7,1,'اسباب طرب تمام دارد',NULL,NULL);
INSERT INTO "verses" VALUES(5253856,145498,0,0,'ز دل بر آمدم و کار بر نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(5253857,145498,0,1,'ز خود برون شدم یار در نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(5253858,145498,1,0,'در این خیال به سر شد زمان عمر و هنوز',NULL,NULL);
INSERT INTO "verses" VALUES(5253859,145498,1,1,'بلای زلف درازت به سر نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(5253860,145498,2,0,'بَسَم حکایت دل هست با نسیم سحر',NULL,NULL);
INSERT INTO "verses" VALUES(5253861,145498,2,1,'ولی به بخت من امشب سحر نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(5253862,145498,3,0,'فدای دوست نکردیم عمر و مال و دریغ',NULL,NULL);
INSERT INTO "verses" VALUES(5253863,145498,3,1,'که کار عشق ز ما این قدر نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(5253864,145498,4,0,'همیشه آه سحرگاه من خطا نشدی',NULL,NULL);
INSERT INTO "verses" VALUES(5253865,145498,4,1,'کنون چه شد که یکی کارگر نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(5253866,145498,5,0,'ز بس که شد دل حافظ رمیده از همه کس',NULL,NULL);
INSERT INTO "verses" VALUES(5253867,145498,5,1,'کنون ز حلقهٔ زلفت به در نمی‌آید',NULL,NULL);
INSERT INTO "verses" VALUES(5253868,145499,0,0,'سر ِ سودای تو اندر سر ما می‌گردد',NULL,NULL);
INSERT INTO "verses" VALUES(5253869,145499,0,1,'تو ببین در سر شوریده چها می‌گردد',NULL,NULL);
INSERT INTO "verses" VALUES(5253870,145499,1,0,'هر که دل در خم ِ چوگانِ سرِ زلفِ تو بست',NULL,NULL);
INSERT INTO "verses" VALUES(5253871,145499,1,1,'لاجرم گوی صفت بی سر و پا می‌گردد',NULL,NULL);
INSERT INTO "verses" VALUES(5253872,145499,2,0,'هرچه بیداد و جفا میکند آن دلبرِ ما',NULL,NULL);
INSERT INTO "verses" VALUES(5253873,145499,2,1,'همچنان در پی او دل به وفا می‌گردد',NULL,NULL);
INSERT INTO "verses" VALUES(5253874,145499,3,0,'از جفای فلک و غصه دوران صد بار',NULL,NULL);
INSERT INTO "verses" VALUES(5253875,145499,3,1,'بر تنم پیرهن صبر قبا می‌گردد',NULL,NULL);
INSERT INTO "verses" VALUES(5253876,145499,4,0,'از نحیفی و نزاری، تن ِ بیچاره ء من',NULL,NULL);
INSERT INTO "verses" VALUES(5253877,145499,4,1,'چون هلالیست که انگشت نما می‌گردد',NULL,NULL);
INSERT INTO "verses" VALUES(5253878,145499,5,0,'بلبلِ طبعِ من از فرقت ِ گلزارِ رخش',NULL,NULL);
INSERT INTO "verses" VALUES(5253879,145499,5,1,'دیرگاهیست که بی برگ و نوا می‌گردد',NULL,NULL);
INSERT INTO "verses" VALUES(5253880,145499,6,0,'بهوا داریِ آن سرو قدِ لاله عِذار',NULL,NULL);
INSERT INTO "verses" VALUES(5253881,145499,6,1,'بسی آشفته و سرگشته چو ما می‌گردد',NULL,NULL);
INSERT INTO "verses" VALUES(5253882,145499,7,0,'چند گویم مرو ای دل زِ پِی نفس و هوی',NULL,NULL);
INSERT INTO "verses" VALUES(5253883,145499,7,1,'کاین هوا نیست که در عین ِ خطا می‌گردد',NULL,NULL);
INSERT INTO "verses" VALUES(5253884,145499,8,0,'دلِ حافظ چو صبا بر سرِ کوی تو مقیم',NULL,NULL);
INSERT INTO "verses" VALUES(5253885,145499,8,1,'درد مندیست باُمّیدِ دوا می‌گردد',NULL,NULL);
INSERT INTO "verses" VALUES(5253886,145500,0,0,'ساقی اندر قدحم باز می گلگون کرد',NULL,NULL);
INSERT INTO "verses" VALUES(5253887,145500,0,1,'در مَی کهنه دیرینهء ما افیون کرد',NULL,NULL);
INSERT INTO "verses" VALUES(5253888,145500,1,0,'دیگران را َمی دیرینه برابر می داد',NULL,NULL);
INSERT INTO "verses" VALUES(5253889,145500,1,1,'چون به این دلشده خسته رسید افزون کرد',NULL,NULL);
INSERT INTO "verses" VALUES(5253890,145500,2,0,'این قدح هوش مراجمله به یکبار ببُرد',NULL,NULL);
INSERT INTO "verses" VALUES(5253891,145500,2,1,'این مَی این بار مرا پاک زخود بیرون کرد',NULL,NULL);
INSERT INTO "verses" VALUES(5253892,145500,3,0,'تو مپندار که در ساغر وپیمانه ما',NULL,NULL);
INSERT INTO "verses" VALUES(5253893,145500,3,1,'بت سنگین دل من خون جگر اکنون کرد',NULL,NULL);
INSERT INTO "verses" VALUES(5253894,145500,4,0,'انچه در سینه مجروح من َاش دل خوانی',NULL,NULL);
INSERT INTO "verses" VALUES(5253895,145500,4,1,'خاک عشق است که با خون جگر معجون کرد',NULL,NULL);
INSERT INTO "verses" VALUES(5253896,145500,5,0,'روز اول که به استاد سپردند مرا',NULL,NULL);
INSERT INTO "verses" VALUES(5253897,145500,5,1,'دیگران راخِرد آموخت مرا مجنون کرد',NULL,NULL);
INSERT INTO "verses" VALUES(5253898,145500,6,0,'دل حافظ که ز افسون لبت بی خود بود',NULL,NULL);
INSERT INTO "verses" VALUES(5253899,145500,6,1,'چشم جادوی تو اش بار دگر افسون کرد',NULL,NULL);
INSERT INTO "verses" VALUES(5253900,145502,0,0,'من خرابم زغم یار خراباتی خویش',NULL,NULL);
INSERT INTO "verses" VALUES(5253901,145502,0,1,'می زند غمزه او ناوک غم بر دل ریش',NULL,NULL);
INSERT INTO "verses" VALUES(5253902,145502,1,0,'با تو پیوستم و از غیر تو دل بگسستم',NULL,NULL);
INSERT INTO "verses" VALUES(5253903,145502,1,1,'آشنای تو ندارد سر بیگانه و خویش',NULL,NULL);
INSERT INTO "verses" VALUES(5253904,145502,2,0,'به عنایت نظری کن که من دل شده را',NULL,NULL);
INSERT INTO "verses" VALUES(5253905,145502,2,1,'نرود بی مدد لطف تو کاری از پیش',NULL,NULL);
INSERT INTO "verses" VALUES(5253906,145502,3,0,'آخرای پادشه ملک و ملاحت چه شود',NULL,NULL);
INSERT INTO "verses" VALUES(5253907,145502,3,1,'که لب لعل تو ریزد نمکی بر دل ریش',NULL,NULL);
INSERT INTO "verses" VALUES(5253908,145502,4,0,'خرمن صبر من سوخته دل داد به باد',NULL,NULL);
INSERT INTO "verses" VALUES(5253909,145502,4,1,'چشم مست تو که بگشاد کمین از پس و پیش',NULL,NULL);
INSERT INTO "verses" VALUES(5253910,145502,5,0,'گر چلیپای سر زلف ز هم بگشاید',NULL,NULL);
INSERT INTO "verses" VALUES(5253911,145502,5,1,'بس مسلمان که شود کشته آن کافرکیش',NULL,NULL);
INSERT INTO "verses" VALUES(5253912,145502,6,0,'پسِ زانو منشین و غمِ بیهوده مخور',NULL,NULL);
INSERT INTO "verses" VALUES(5253913,145502,6,1,'که ز غم خوردن تو رزق نگردد کم و بیش',NULL,NULL);
INSERT INTO "verses" VALUES(5253914,145502,7,0,'پرسش حافظ دل سوخته کن بهر خدا',NULL,NULL);
INSERT INTO "verses" VALUES(5253915,145502,7,1,'نیست از شاه عجب، گر بنوازد درویش',NULL,NULL);
INSERT INTO "verses" VALUES(5253916,145502,8,0,'حافظ از نوش لب لعل تو کامی کی یافت',NULL,NULL);
INSERT INTO "verses" VALUES(5253917,145502,8,1,'که نزد بر دل ریشش دو هزاران سر نیش',NULL,NULL);
INSERT INTO "verses" VALUES(5253918,145503,0,0,'نیست کس را ز کمند سر زلف تو خلاص',NULL,NULL);
INSERT INTO "verses" VALUES(5253919,145503,0,1,'میکشی عاشق مسکین و نترسی ز قصاص',NULL,NULL);
INSERT INTO "verses" VALUES(5253920,145503,1,0,'عاشق سوخته دل تا به بیابان فنا',NULL,NULL);
INSERT INTO "verses" VALUES(5253921,145503,1,1,'نرود در حرم جان نشود خاص الخاص',NULL,NULL);
INSERT INTO "verses" VALUES(5253922,145503,2,0,'ناوک غمزه تو دست ببرد از رستم',NULL,NULL);
INSERT INTO "verses" VALUES(5253923,145503,2,1,'حاجب ابروی تو برده گرو از وقاص',NULL,NULL);
INSERT INTO "verses" VALUES(5253924,145503,3,0,'جان نهادم به میان شمع صفت از سر صدق',NULL,NULL);
INSERT INTO "verses" VALUES(5253925,145503,3,1,'کردم ایثار تن خویش زروی اخلاص',NULL,NULL);
INSERT INTO "verses" VALUES(5253926,145503,4,0,'به هواداری و اخلاص چو پروانه زشوق',NULL,NULL);
INSERT INTO "verses" VALUES(5253927,145503,4,1,'تا نسوزی تو نیابی ز غم عشق خلاص',NULL,NULL);
INSERT INTO "verses" VALUES(5253928,145503,5,0,'آتشی در دل پروانه ما افکندی',NULL,NULL);
INSERT INTO "verses" VALUES(5253929,145503,5,1,'گرچه بودیم همیشه به هوایت رقاص',NULL,NULL);
INSERT INTO "verses" VALUES(5253930,145503,6,0,'کیمیای غم عشق تو تن خاکی ما',NULL,NULL);
INSERT INTO "verses" VALUES(5253931,145503,6,1,'زر خالص کند ار چند بود همچو رصاص',NULL,NULL);
INSERT INTO "verses" VALUES(5253932,145503,7,0,'قیمت در گرانمایه چه داند عوام',NULL,NULL);
INSERT INTO "verses" VALUES(5253933,145503,7,1,'حافظا گوهر یکدانه مده جز به خواص',NULL,NULL);
INSERT INTO "verses" VALUES(5253934,145504,0,0,'حسن و جمال تو جهان جمله گرفت طول و عرض',NULL,NULL);
INSERT INTO "verses" VALUES(5253935,145504,0,1,'شمس و فلک خجل شده از رخ خوب ماه ارض',NULL,NULL);
INSERT INTO "verses" VALUES(5253936,145504,1,0,'دیدن حسن و خوبیت بر همه خلق واجبست',NULL,NULL);
INSERT INTO "verses" VALUES(5253937,145504,1,1,'رویت روت بلکه بر جمله ملایک است فرض',NULL,NULL);
INSERT INTO "verses" VALUES(5253938,145504,2,0,'از رخ تست مقتبس خور زچهارم آسمان',NULL,NULL);
INSERT INTO "verses" VALUES(5253939,145504,2,1,'همچو زمین هفتمین مانده بزیر بار قرض',NULL,NULL);
INSERT INTO "verses" VALUES(5253940,145504,3,0,'جان که فدای او نشد مرده جاودان بماند',NULL,NULL);
INSERT INTO "verses" VALUES(5253941,145504,3,1,'تن که اسیر او نشد لایق اوست قطع و برض',NULL,NULL);
INSERT INTO "verses" VALUES(5253942,145504,4,0,'بوسه به خاک پای او دست کجا دهد تو را',NULL,NULL);
INSERT INTO "verses" VALUES(5253943,145504,4,1,'قصه شوق حافظا باد رساندت به عرض',NULL,NULL);
INSERT INTO "verses" VALUES(5253944,145505,0,0,'گرد عذار یار من تا بنوشت گرد خط',NULL,NULL);
INSERT INTO "verses" VALUES(5253945,145505,0,1,'ماه ز حسن روی او راست فتاد در غلط',NULL,NULL);
INSERT INTO "verses" VALUES(5253946,145505,1,0,'از هوس لبش که آن ز آب حیات خوشتر است',NULL,NULL);
INSERT INTO "verses" VALUES(5253947,145505,1,1,'گشته روان ز دیدام چشمه آب همچو شط',NULL,NULL);
INSERT INTO "verses" VALUES(5253948,145505,2,0,'گر به غلامی خودم شاه قبول می کند',NULL,NULL);
INSERT INTO "verses" VALUES(5253949,145505,2,1,'تا به مبارکی دهم بنده به بندگیش خط',NULL,NULL);
INSERT INTO "verses" VALUES(5253950,145505,3,0,'گر به هوات می دهم گر مثال جان ودل',NULL,NULL);
INSERT INTO "verses" VALUES(5253951,145505,3,1,'گاه به آب می کشم آتش عشق تو چو بط',NULL,NULL);
INSERT INTO "verses" VALUES(5253952,145505,4,0,'آب حیات حافظا گشته خجل ز طبع تو',NULL,NULL);
INSERT INTO "verses" VALUES(5253953,145505,4,1,'کس به هوای عشق او شعر نگفت از این نمط',NULL,NULL);
INSERT INTO "verses" VALUES(5253954,145506,0,0,'ز چشم بد رخ خوب تو را خدا حافظ',NULL,NULL);
INSERT INTO "verses" VALUES(5253955,145506,0,1,'که کرد جمله نکویی به جای ما حافظ',NULL,NULL);
INSERT INTO "verses" VALUES(5253956,145506,1,0,'بیا که نوبت صلح است و دوستی و صفا',NULL,NULL);
INSERT INTO "verses" VALUES(5253957,145506,1,1,'که با تو نیست مرا جنگ و ماجرا، حافظ',NULL,NULL);
INSERT INTO "verses" VALUES(5253958,145506,2,0,'به زلف و خال بتان دل مبند دیگربار',NULL,NULL);
INSERT INTO "verses" VALUES(5253959,145506,2,1,'اگر بجستی از این بند و این بلا، حافظ',NULL,NULL);
INSERT INTO "verses" VALUES(5253960,145506,3,0,'اگرچه خون دلت خورد لعل من، بستان',NULL,NULL);
INSERT INTO "verses" VALUES(5253961,145506,3,1,'به کام دل ز لبم بوسه خون‌بها، حافظ',NULL,NULL);
INSERT INTO "verses" VALUES(5253962,145506,4,0,'بیا بخوان غزلی تازه‌تر ز آب حیات',NULL,NULL);
INSERT INTO "verses" VALUES(5253963,145506,4,1,'که شعر توست فرح‌بخش و جان‌فزا، حافظ',NULL,NULL);
INSERT INTO "verses" VALUES(5253964,145506,5,0,'سحرگهی که چو رندان بنالی از سر درد',NULL,NULL);
INSERT INTO "verses" VALUES(5253965,145506,5,1,'به کار من کنی آن‌دم یکی دعا، حافظ',NULL,NULL);
INSERT INTO "verses" VALUES(5253966,145506,6,0,'تو از کجا و امید وصال او ز کجا',NULL,NULL);
INSERT INTO "verses" VALUES(5253967,145506,6,1,'به دامنش نرسد دست هر گدا، حافظ',NULL,NULL);
INSERT INTO "verses" VALUES(5253968,145506,7,0,'چو ذوق یافت دل من به ذکر آن محبوب',NULL,NULL);
INSERT INTO "verses" VALUES(5253969,145506,7,1,'مراست تحفه‌ی جان‌بخش و غم‌زدا، حافظ',NULL,NULL);
INSERT INTO "verses" VALUES(5253970,145507,0,0,'ای برده دلم را تو بدین شکل و شمایل',NULL,NULL);
INSERT INTO "verses" VALUES(5253971,145507,0,1,'پروای کست نیست جهانی به تو مایل',NULL,NULL);
INSERT INTO "verses" VALUES(5253972,145507,1,0,'گه آه کشم از دل و گه تیر تو ای جان',NULL,NULL);
INSERT INTO "verses" VALUES(5253973,145507,1,1,'پیش تو چه گویم که چه‌ها می کشم از دل',NULL,NULL);
INSERT INTO "verses" VALUES(5253974,145507,2,0,'وصف لب لعل تو چه گویم به رقیبان',NULL,NULL);
INSERT INTO "verses" VALUES(5253975,145507,2,1,'نیکو نبود معنی رنگین بر جاهل',NULL,NULL);
INSERT INTO "verses" VALUES(5253976,145507,3,0,'هر روز چو حسنت ز دگر روز فزون است',NULL,NULL);
INSERT INTO "verses" VALUES(5253977,145507,3,1,'مه را نتوان کرد به روی تو مقابل',NULL,NULL);
INSERT INTO "verses" VALUES(5253978,145507,4,0,'دل بردی و جان می‌دهمت غم چه فرستی',NULL,NULL);
INSERT INTO "verses" VALUES(5253979,145507,4,1,'چون نیک غمینیم چه حاجت به محصل',NULL,NULL);
INSERT INTO "verses" VALUES(5253980,145507,5,0,'حافظ چو تو پا در حرم عشق نهادی',NULL,NULL);
INSERT INTO "verses" VALUES(5253981,145507,5,1,'در دامن او دست زن و از همه بگسل',NULL,NULL);
INSERT INTO "verses" VALUES(5253982,145508,0,0,'الم یأن للحباب أن یترحموا','آیا وقت آن نرسیده است که یاران مهربانی‏ کنند و عهدشکنان پشیمان شوند؟',NULL);
INSERT INTO "verses" VALUES(5253983,145508,0,1,'و للنّاقضین العهد أن یتندّموا',NULL,NULL);
INSERT INTO "verses" VALUES(5253984,145508,1,0,'الم یأتهم انباء من فات عهدهم‌','خبر کسی که عهد و پیمان او شکسته و آتش اندوه در دلش بر افروخته، به گوش‏ آنان نرسیده است؟',NULL);
INSERT INTO "verses" VALUES(5253985,145508,1,1,'و فی صدره نار الاسی تتضرّم',NULL,NULL);
INSERT INTO "verses" VALUES(5253986,145508,2,0,'فیالیت قومی یعلمون بما جری‌ علی','ای کاش خویشان و یاران بر آنچه بدین/امید بسته به آنان، گذشته است، می‌‏دانستند و عفو و ترحم‏ می‏کردند.',NULL);
INSERT INTO "verses" VALUES(5253987,145508,2,1,'مرتج منهم فیعفوا و یرحموا',NULL,NULL);
INSERT INTO "verses" VALUES(5253988,145508,3,0,'حکی الدّمع منّی و الجوارح','اشک و جوارح من از اندوه‏ دلم حکایت دارد، شگفتا که بی‏‌زبان سخن‏ می‏گوید؟!',NULL);
INSERT INTO "verses" VALUES(5253989,145508,3,1,'و اضمرت‌ فیا عجبا من صامت یتکلّم',NULL,NULL);
INSERT INTO "verses" VALUES(5253990,145508,4,0,'اتی موسم النیّروز و اخضرّت الرّبی‌','موسم نوروز فرا رسید و دشت و دمن سبز شد. باده صاف و زلال‏ گردید و مستان به ترنم آمدند.',NULL);
INSERT INTO "verses" VALUES(5253991,145508,4,1,'و راوق مر و النّدامی ترنّموا',NULL,NULL);
INSERT INTO "verses" VALUES(5253992,145508,5,0,'و یا من علا کلّ السّلاطین سطوه','ای که‏ در شکوه برتر از شاهانی! پاداش تو با خدا، به ترنم در آی و نیکی را مغتنم شمار!',NULL);
INSERT INTO "verses" VALUES(5253993,145508,5,1,'ترنّم جزاک اللّه و الخیر تغنم',NULL,NULL);
INSERT INTO "verses" VALUES(5253994,145508,6,0,'بنوا عمّنا حبّوا علینا بجرعه','یاران (پسر عموها)!جرعه‏‌ای به ما بنوشانید (به جرعه‏‌ای مهربانی کنید) که‏ می‏‌شود با اسباب به فضل و بزرگی‏ رسید.',NULL);
INSERT INTO "verses" VALUES(5253995,145508,6,1,'و للفضل اسباب بها یتوسّم',NULL,NULL);
INSERT INTO "verses" VALUES(5253996,145508,7,0,'شهور بها الاوطار تقضی من القضا','ماه‏هایی هست که آرزومندان در آن‏ها به آرزوی خود می‏‌رسند، امّا عیش و نوش بهار بر ما حرام است!',NULL);
INSERT INTO "verses" VALUES(5253997,145508,7,1,'و فی شأننا عیش الرّبیع محّرم',NULL,NULL);
INSERT INTO "verses" VALUES(5253998,145508,8,0,'لکلّ من الخّلان ذخر و نعمه‌','همهٔ دوستان گنج و نعمتی دارند، حافظ بیچاره‏ مستمند و زیان‏دیده است.',NULL);
INSERT INTO "verses" VALUES(5253999,145508,8,1,'و للحافظ المسکین فقر و مغرم',NULL,NULL);
INSERT INTO "verses" VALUES(5254000,145509,0,0,'خیر مقدم مرحبا ای طایر میمون قدم',NULL,NULL);
INSERT INTO "verses" VALUES(5254001,145509,0,1,'تا چه داری مژدهٔ اقبال آن صاحب کرم',NULL,NULL);
INSERT INTO "verses" VALUES(5254002,145509,1,0,'دور تا با دور گردون همعنان باد آنچنان',NULL,NULL);
INSERT INTO "verses" VALUES(5254003,145509,1,1,'گر محاسب بشمرد حرفی نیابد بیش و کم',NULL,NULL);
INSERT INTO "verses" VALUES(5254004,145510,0,0,'نصیبِ من چو خرابات کرده است اِله',NULL,NULL);
INSERT INTO "verses" VALUES(5254005,145510,0,1,'در این میانه بگو، زاهدا! مرا چه گناه‌؟',NULL,NULL);
INSERT INTO "verses" VALUES(5254006,145510,1,0,'کسی که در ازلش، جام مِیْ نصیب افتاد',NULL,NULL);
INSERT INTO "verses" VALUES(5254007,145510,1,1,'چرا به حشر کنند، این گناه از او در خواه‌؟',NULL,NULL);
INSERT INTO "verses" VALUES(5254008,145510,2,0,'بگو به زاهدِ سالوسِ خرقهْ پوشِ دو رُوی:',NULL,NULL);
INSERT INTO "verses" VALUES(5254009,145510,2,1,'که دستِ زرق دراز است و آستین کوتاه',NULL,NULL);
INSERT INTO "verses" VALUES(5254010,145510,3,0,'تو خرقه را، ز برای ریا همی پوشی',NULL,NULL);
INSERT INTO "verses" VALUES(5254011,145510,3,1,'که تا به زرق بری، بندگانِ حق از راه',NULL,NULL);
INSERT INTO "verses" VALUES(5254012,145510,4,0,'غلامِ همّتِ رندانِ بی‌سروپایم!',NULL,NULL);
INSERT INTO "verses" VALUES(5254013,145510,4,1,'که هر دو کَوْن نیارزد به پیششان یک کاه',NULL,NULL);
INSERT INTO "verses" VALUES(5254014,145510,5,0,'مراد من ز خرابات، چون که حاصل شد',NULL,NULL);
INSERT INTO "verses" VALUES(5254015,145510,5,1,'دلم ز مدرسه و خانقاه گشت سیاه',NULL,NULL);
INSERT INTO "verses" VALUES(5254016,145510,6,0,'برو گدای دَرِ هر گدای شو حافظ!',NULL,NULL);
INSERT INTO "verses" VALUES(5254017,145510,6,1,'تو این مراد نیابی، مگر به شیءِ اللّٰه',NULL,NULL);
INSERT INTO "verses" VALUES(5254018,145511,0,0,'هر که آمد در جهان پر ز شور',NULL,NULL);
INSERT INTO "verses" VALUES(5254019,145511,0,1,'عاقبت رفتن می باید به گور',NULL,NULL);
INSERT INTO "verses" VALUES(5254020,145512,0,0,'در این وادی به بانگ سیل بشنو',NULL,NULL);
INSERT INTO "verses" VALUES(5254021,145512,0,1,'که صد من خون مظلومان به یک جو',NULL,NULL);
INSERT INTO "verses" VALUES(5254022,145512,1,0,'پر جبریل را اینجا بسوزند',NULL,NULL);
INSERT INTO "verses" VALUES(5254023,145512,1,1,'بدان تا کودکان آتش فروزند',NULL,NULL);
INSERT INTO "verses" VALUES(5254024,145512,2,0,'سخن گفتن که را یاراست اینجا',NULL,NULL);
INSERT INTO "verses" VALUES(5254025,145512,2,1,'تعالی الله چه استغناست اینجا',NULL,NULL);
INSERT INTO "verses" VALUES(5254026,145512,3,0,'برو حافظ در این معرض مزن دم',NULL,NULL);
INSERT INTO "verses" VALUES(5254027,145512,3,1,'سخن کوتاه کن والله اعلم',NULL,NULL);
INSERT INTO "verses" VALUES(5254028,145513,0,0,'ای داده بیاد دوستداری',NULL,NULL);
INSERT INTO "verses" VALUES(5254029,145513,0,1,'این بود وفا و عهد و یاری',NULL,NULL);
INSERT INTO "verses" VALUES(5254030,145513,1,0,'آخر دل ریش دردمندم',NULL,NULL);
INSERT INTO "verses" VALUES(5254031,145513,1,1,'تا چند بدست غم سپاری',NULL,NULL);
INSERT INTO "verses" VALUES(5254032,145513,2,0,'از زلف تو حاصلی ندیدم',NULL,NULL);
INSERT INTO "verses" VALUES(5254033,145513,2,1,'جز شیفتگی و بیقراری',NULL,NULL);
INSERT INTO "verses" VALUES(5254034,145513,3,0,'ای جان عزیز بر ضعیفان',NULL,NULL);
INSERT INTO "verses" VALUES(5254035,145513,3,1,'تا چند کنی جفا و خواری',NULL,NULL);
INSERT INTO "verses" VALUES(5254036,145513,4,0,'هر چند که سوختی به جور',NULL,NULL);
INSERT INTO "verses" VALUES(5254037,145513,4,1,'کردم من خسته سازگاری',NULL,NULL);
INSERT INTO "verses" VALUES(5254038,145513,5,0,'گفتم مگر از سر ترحم',NULL,NULL);
INSERT INTO "verses" VALUES(5254039,145513,5,1,'دست از ستم و جفا بداری',NULL,NULL);
INSERT INTO "verses" VALUES(5254040,145513,6,0,'چون نیست امید آنکه روزی',NULL,NULL);
INSERT INTO "verses" VALUES(5254041,145513,6,1,'بر عاشق خسته رحم آری',NULL,NULL);
INSERT INTO "verses" VALUES(5254042,145513,7,2,'آن به که ز صبر رخ نتابم',NULL,NULL);
INSERT INTO "verses" VALUES(5254043,145513,7,3,'باشد که مراد دل بیابم',NULL,NULL);
INSERT INTO "verses" VALUES(5254044,145513,8,0,'در سختی عشق گر بمیرم',NULL,NULL);
INSERT INTO "verses" VALUES(5254045,145513,8,1,'من دل ز غم تو برنگیرم',NULL,NULL);
INSERT INTO "verses" VALUES(5254046,145513,9,0,'بی شک دل ماه خور بگیرد',NULL,NULL);
INSERT INTO "verses" VALUES(5254047,145513,9,1,'گر سوی فلک رسد نفیرم',NULL,NULL);
INSERT INTO "verses" VALUES(5254048,145513,10,0,'پیوسته کمان ابروانش',NULL,NULL);
INSERT INTO "verses" VALUES(5254049,145513,10,1,'از غمزه همی زند به تیرم',NULL,NULL);
INSERT INTO "verses" VALUES(5254050,145513,11,0,'نتوان بقلم نوشت شوقش',NULL,NULL);
INSERT INTO "verses" VALUES(5254051,145513,11,1,'گر پیر فلک شود دبیرم',NULL,NULL);
INSERT INTO "verses" VALUES(5254052,145513,12,0,'پیر غم عشقم ار چه طفلم',NULL,NULL);
INSERT INTO "verses" VALUES(5254053,145513,12,1,'طفل غم عشقم ار چه پیرم',NULL,NULL);
INSERT INTO "verses" VALUES(5254054,145513,13,0,'دارم سر انکه همچو سعدی',NULL,NULL);
INSERT INTO "verses" VALUES(5254055,145513,13,1,'بنشینم و صبر پیش گیرم',NULL,NULL);
INSERT INTO "verses" VALUES(5254056,145513,14,0,'چون کرد زمانه ی ستمگار',NULL,NULL);
INSERT INTO "verses" VALUES(5254057,145513,14,1,'دور از تو به بند غم اسیرم',NULL,NULL);
INSERT INTO "verses" VALUES(5254058,145513,15,2,'آن به که ز صبر رخ نتابم',NULL,NULL);
INSERT INTO "verses" VALUES(5254059,145513,15,3,'باشد که مراد دل بیابم',NULL,NULL);
INSERT INTO "verses" VALUES(5254060,145513,16,0,'ای راحت جان بیقرارم',NULL,NULL);
INSERT INTO "verses" VALUES(5254061,145513,16,1,'امید دل امید دارم',NULL,NULL);
INSERT INTO "verses" VALUES(5254062,145513,17,0,'شادم بغمت که در همه',NULL,NULL);
INSERT INTO "verses" VALUES(5254063,145513,17,1,'سوز غم توست سازگارم',NULL,NULL);
INSERT INTO "verses" VALUES(5254064,145513,18,0,'تا رفته ی از کنارم ایدوست',NULL,NULL);
INSERT INTO "verses" VALUES(5254065,145513,18,1,'یکباره ز خویش بر کنارم',NULL,NULL);
INSERT INTO "verses" VALUES(5254066,145513,19,0,'در آرزوی وصال حالی',NULL,NULL);
INSERT INTO "verses" VALUES(5254067,145513,19,1,'عمری بفراق میگذارم',NULL,NULL);
INSERT INTO "verses" VALUES(5254068,145513,20,0,'تا مرگ نگیردم گریبان',NULL,NULL);
INSERT INTO "verses" VALUES(5254069,145513,20,1,'من دست زدامنت ندارم',NULL,NULL);
INSERT INTO "verses" VALUES(5254070,145513,21,0,'چون هیچ نشد بسعی',NULL,NULL);
INSERT INTO "verses" VALUES(5254071,145513,21,1,'کام خسته ی فگارم',NULL,NULL);
INSERT INTO "verses" VALUES(5254072,145513,22,2,'آن به که ز صبر رخ نتابم',NULL,NULL);
INSERT INTO "verses" VALUES(5254073,145513,22,3,'باشد که مراد دل بیابم',NULL,NULL);
INSERT INTO "verses" VALUES(5254074,145513,23,0,'ای زخم غم تو مرهم دل',NULL,NULL);
INSERT INTO "verses" VALUES(5254075,145513,23,1,'عشق تو انیس و محرم دل',NULL,NULL);
INSERT INTO "verses" VALUES(5254076,145513,24,0,'زلف تو کمند گردن جان',NULL,NULL);
INSERT INTO "verses" VALUES(5254077,145513,24,1,'لعل تو نگین خاتم دل',NULL,NULL);
INSERT INTO "verses" VALUES(5254078,145513,25,0,'ابروی تو بود شحنه ی جان',NULL,NULL);
INSERT INTO "verses" VALUES(5254079,145513,25,1,'چون چشم تو گشت حاکم دل',NULL,NULL);
INSERT INTO "verses" VALUES(5254080,145513,26,0,'او در دل ما و ما در آتش',NULL,NULL);
INSERT INTO "verses" VALUES(5254081,145513,26,1,'ما را غم اوست نی غم دل',NULL,NULL);
INSERT INTO "verses" VALUES(5254082,145513,27,0,'نزدیک شد آنکه من بدوری',NULL,NULL);
INSERT INTO "verses" VALUES(5254083,145513,27,1,'گیرم سر خویش یا کم دل',NULL,NULL);
INSERT INTO "verses" VALUES(5254084,145513,28,0,'حافظ چو شود اگر بیابی',NULL,NULL);
INSERT INTO "verses" VALUES(5254085,145513,28,1,'نوری ز حضور عالم دل',NULL,NULL);
INSERT INTO "verses" VALUES(5254086,145513,29,0,'چون ملک وصال او نگردد',NULL,NULL);
INSERT INTO "verses" VALUES(5254087,145513,29,1,'آسان آسان مسلم دل',NULL,NULL);
INSERT INTO "verses" VALUES(5254088,145513,30,2,'آن به که ز صبر رخ نتابم',NULL,NULL);
INSERT INTO "verses" VALUES(5254089,145513,30,3,'باشد که مراد دل بیابم',NULL,NULL);
INSERT INTO "verses" VALUES(5254090,145514,0,0,'فساد چرخ نبینیم و نشنویم همی',NULL,NULL);
INSERT INTO "verses" VALUES(5254091,145514,0,1,'که چشمها همه کور است و گوشها همه کر',NULL,NULL);
INSERT INTO "verses" VALUES(5254092,145514,1,0,'بسا کسا که مه و مهر باشدش بالین',NULL,NULL);
INSERT INTO "verses" VALUES(5254093,145514,1,1,'به عاقبت ز گل و خشت باشدش بستر',NULL,NULL);
INSERT INTO "verses" VALUES(5254094,145515,0,0,'ز خواب مستی دوشین چو دیده بگشودم',NULL,NULL);
INSERT INTO "verses" VALUES(5254095,145515,0,1,'سفیده‌دم که شدم محرم سرای سرور',NULL,NULL);
INSERT INTO "verses" VALUES(5254096,145515,1,0,'به عزم آن که کنم توبه از محبت غیر',NULL,NULL);
INSERT INTO "verses" VALUES(5254097,145515,1,1,'شنیدم آیت توبوا الی الله از لب حور',NULL,NULL);
INSERT INTO "verses" VALUES(5254098,145516,0,0,'حسن این نظم از بیان مستغنی است‌',NULL,NULL);
INSERT INTO "verses" VALUES(5254099,145516,0,1,'بر فروغ خور کسی جوید دلیل',NULL,NULL);
INSERT INTO "verses" VALUES(5254100,145516,1,0,'آفرین بر کلک نقاشی که داد',NULL,NULL);
INSERT INTO "verses" VALUES(5254101,145516,1,1,'بکر معنی را چنین حسن جمیل',NULL,NULL);
INSERT INTO "verses" VALUES(5254102,145517,0,0,'کل قند شعر من ز بنفشه شکر رباست',NULL,NULL);
INSERT INTO "verses" VALUES(5254103,145517,0,1,'زان غیرت طبرزد و کعب‌الغزال شد',NULL,NULL);
INSERT INTO "verses" VALUES(5254104,145517,1,0,'بادا دهانش تلخ که عیب نبات کرد',NULL,NULL);
INSERT INTO "verses" VALUES(5254105,145517,1,1,'خاکش به سر که منکر آب زلال شد',NULL,NULL);
INSERT INTO "verses" VALUES(5254106,145517,2,0,'هر کس که کور زاد ز مادر به عمر خویش',NULL,NULL);
INSERT INTO "verses" VALUES(5254107,145517,2,1,'کی مشتری شاهد صاحب‌جمال شد',NULL,NULL);
INSERT INTO "verses" VALUES(5254108,145518,0,0,'شاها مبشری ز بهشتم رسیده است',NULL,NULL);
INSERT INTO "verses" VALUES(5254109,145518,0,1,'رضوان سریر و حوروش و سلسبیل موی',NULL,NULL);
INSERT INTO "verses" VALUES(5254110,145518,1,0,'خوش لفظ و پاک معنی و موزون و دلپذیر',NULL,NULL);
INSERT INTO "verses" VALUES(5254111,145518,1,1,'صاحب کمال و نازک و دیگر لطیفه‌گوی',NULL,NULL);
INSERT INTO "verses" VALUES(5254112,145519,0,0,'دل منه ای جان من بر خواجه و شاه و وزیر',NULL,NULL);
INSERT INTO "verses" VALUES(5254113,145519,0,1,'کس نمی‌داند که کارش از کجا خواهد گشاد',NULL,NULL);
INSERT INTO "verses" VALUES(5254114,145519,1,0,'کار شاهان اینچنین باشد تو ای حافظ مرنج',NULL,NULL);
INSERT INTO "verses" VALUES(5254115,145519,1,1,'داور روزی‌رسان توفیق و نصرتشان دهاد',NULL,NULL);
INSERT INTO "verses" VALUES(5254116,145520,0,0,'بگذشتن فرصت ای برادر',NULL,NULL);
INSERT INTO "verses" VALUES(5254117,145520,0,1,'در گرم‌روی چو میغ باشد',NULL,NULL);
INSERT INTO "verses" VALUES(5254118,145520,1,0,'دریاب که عمر بس عزیز است',NULL,NULL);
INSERT INTO "verses" VALUES(5254119,145520,1,1,'گر فوت شود دریغ باشد',NULL,NULL);
INSERT INTO "verses" VALUES(5254120,145521,0,0,'هنگام بهار است گل لاله و نسرین',NULL,NULL);
INSERT INTO "verses" VALUES(5254121,145521,0,1,'از خاک در آیند و تو در خاک چرایی؟',NULL,NULL);
INSERT INTO "verses" VALUES(5254122,145521,1,0,'چندان به سر خاک تو بنشینم و گریم',NULL,NULL);
INSERT INTO "verses" VALUES(5254123,145521,1,1,'شاید که بهار آید و از خاک در آیی',NULL,NULL);
INSERT INTO "verses" VALUES(5254124,145522,0,0,'ای دل مجوی منصب دنیا که هیچ نیست',NULL,NULL);
INSERT INTO "verses" VALUES(5254125,145522,0,1,'نقصان بود ز عزل کمالت نه از عمل',NULL,NULL);
INSERT INTO "verses" VALUES(5254126,145522,1,0,'چیزی مگو که از تو پریشان شود دلی',NULL,NULL);
INSERT INTO "verses" VALUES(5254127,145522,1,1,'کاری مکن که از تو به نفسی رسد خلل',NULL,NULL);
INSERT INTO "verses" VALUES(5254128,145523,0,0,'از بد دهر اگر همی رنجی',NULL,NULL);
INSERT INTO "verses" VALUES(5254129,145523,0,1,'رنجش از روزگار سهل بود',NULL,NULL);
INSERT INTO "verses" VALUES(5254130,145523,1,0,'رنج و راحت ورای طالع نیست',NULL,NULL);
INSERT INTO "verses" VALUES(5254131,145523,1,1,'وآن که دانست مرد اهل بود',NULL,NULL);
INSERT INTO "verses" VALUES(5254132,145524,0,0,'حکیم فکر من از عقل کرد دوش سؤال',NULL,NULL);
INSERT INTO "verses" VALUES(5254133,145524,0,1,'که ای یگانهٔ الطاف خالق رحمان',NULL,NULL);
INSERT INTO "verses" VALUES(5254134,145524,1,0,'کدام گوهر نظم است در جهان که از او',NULL,NULL);
INSERT INTO "verses" VALUES(5254135,145524,1,1,'شکست قیمت بازار لؤلؤ عمان',NULL,NULL);
INSERT INTO "verses" VALUES(5254136,145525,0,0,'به روز کاف و الف، از جمادی الاولی',NULL,NULL);
INSERT INTO "verses" VALUES(5254137,145525,0,1,'به سال ذال و دگر نون و حا، علی‌الاطلاق',NULL,NULL);
INSERT INTO "verses" VALUES(5254138,145525,1,0,'خدایگان سلاطین مشرق و مغرب',NULL,NULL);
INSERT INTO "verses" VALUES(5254139,145525,1,1,'خدیو کشور عفو و کرم به استحقاق',NULL,NULL);
INSERT INTO "verses" VALUES(5254140,145525,2,0,'سپهر حلم و حیا، آفتاب جاه و جلال',NULL,NULL);
INSERT INTO "verses" VALUES(5254141,145525,2,1,'جمال دنیی و دین، شاه شیخ ابواسحق',NULL,NULL);
INSERT INTO "verses" VALUES(5254142,145525,3,0,'میان عرصه میدان خود، به تیغ عدو',NULL,NULL);
INSERT INTO "verses" VALUES(5254143,145525,3,1,'نهاد بر دل احباب خویش، داغ فراق',NULL,NULL);
INSERT INTO "verses" VALUES(5254144,145526,0,0,'با دوست نشین و باده و جام طلب',NULL,NULL);
INSERT INTO "verses" VALUES(5254145,145526,0,1,'نوش از لب آن سرو گل‌اندام طلب',NULL,NULL);
INSERT INTO "verses" VALUES(5254146,145526,1,0,'مجروح چو راحت جراحت طلبد',NULL,NULL);
INSERT INTO "verses" VALUES(5254147,145526,1,1,'گو از سر نیش زین حجام طلب',NULL,NULL);
INSERT INTO "verses" VALUES(5254148,145527,0,0,'در خوبی و دلبری بت من طاق است',NULL,NULL);
INSERT INTO "verses" VALUES(5254149,145527,0,1,'بیچاره دلم به وصل او مشتاق است',NULL,NULL);
INSERT INTO "verses" VALUES(5254150,145527,1,0,'نازک بدن و لاله رخ و سنگین دل',NULL,NULL);
INSERT INTO "verses" VALUES(5254151,145527,1,1,'شیرین سخن و لطیف و سیمین ساق است',NULL,NULL);
INSERT INTO "verses" VALUES(5254152,145528,0,0,'نوباوهٔ گلبن جوانی عشق است',NULL,NULL);
INSERT INTO "verses" VALUES(5254153,145528,0,1,'سرمایهٔ عمر جاودانی عشق است',NULL,NULL);
INSERT INTO "verses" VALUES(5254154,145528,1,0,'چون خضر گر آب زندگانی طلبی',NULL,NULL);
INSERT INTO "verses" VALUES(5254155,145528,1,1,'سرچشمهٔ آب زندگانی عشق است',NULL,NULL);
INSERT INTO "verses" VALUES(5254156,145529,0,0,'نه جان تو با سر الهی پرداخت',NULL,NULL);
INSERT INTO "verses" VALUES(5254157,145529,0,1,'نه در طلب لایتناهی پرداخت',NULL,NULL);
INSERT INTO "verses" VALUES(5254158,145529,1,0,'دردا که چنان به نقش مشغول شدی',NULL,NULL);
INSERT INTO "verses" VALUES(5254159,145529,1,1,'کز نقش به نقاش نخواهی پرداخت',NULL,NULL);
INSERT INTO "verses" VALUES(5254160,145530,0,0,'نام بت من که مه ز رویش خجل است',NULL,NULL);
INSERT INTO "verses" VALUES(5254161,145530,0,1,'ده حرف ز نظم حافظ مرتحل است',NULL,NULL);
INSERT INTO "verses" VALUES(5254162,145530,1,0,'اول ششم هجی و قلبش روشن',NULL,NULL);
INSERT INTO "verses" VALUES(5254163,145530,1,1,'لیکن عجب آن که جمله اجزاش دل است',NULL,NULL);
INSERT INTO "verses" VALUES(5254164,145531,0,0,'بردار دل از مادر دهر ای فرزند',NULL,NULL);
INSERT INTO "verses" VALUES(5254165,145531,0,1,'با نصف اخیر شوهرش در پیوند',NULL,NULL);
INSERT INTO "verses" VALUES(5254166,145531,1,0,'بی قلب ندانی که چنین نقادی',NULL,NULL);
INSERT INTO "verses" VALUES(5254167,145531,1,1,'چون حافظ اگر شوی به رویش خرسند',NULL,NULL);
INSERT INTO "verses" VALUES(5254168,145532,0,0,'تا حکم قضای آسمانی باشد',NULL,NULL);
INSERT INTO "verses" VALUES(5254169,145532,0,1,'کار تو همیشه کامرانی باشد',NULL,NULL);
INSERT INTO "verses" VALUES(5254170,145532,1,0,'جامی که ز دست یاد خود نوش کنی',NULL,NULL);
INSERT INTO "verses" VALUES(5254171,145532,1,1,'سرمایهٔ عیش جاودانی باشد',NULL,NULL);
INSERT INTO "verses" VALUES(5254172,145533,0,0,'باز آی که جانم به جمالت نگران است',NULL,NULL);
INSERT INTO "verses" VALUES(5254173,145533,0,1,'باز آی که دل در غم هجرت به فغان است',NULL,NULL);
INSERT INTO "verses" VALUES(5254174,145533,1,0,'باز آی که بی روی تو ای نور دو دیده',NULL,NULL);
INSERT INTO "verses" VALUES(5254175,145533,1,1,'سیلاب سرشک از من سرگشته روان است',NULL,NULL);
INSERT INTO "verses" VALUES(5254176,145535,0,0,'با مردم نیک بد نمی‌باید بود',NULL,NULL);
INSERT INTO "verses" VALUES(5254177,145535,0,1,'در سایهٔ دیو و دد نمی‌باید بود',NULL,NULL);
INSERT INTO "verses" VALUES(5254178,145535,1,0,'مفتون معاش خود نمی‌باید بود',NULL,NULL);
INSERT INTO "verses" VALUES(5254179,145535,1,1,'مغرور به فضل خود نمی‌باید بود',NULL,NULL);
INSERT INTO "verses" VALUES(5254180,145536,0,0,'شیرین‌دهنان عهد به پایان نبرند',NULL,NULL);
INSERT INTO "verses" VALUES(5254181,145536,0,1,'صاحب‌نظران ز عاشقی جان نبرند',NULL,NULL);
INSERT INTO "verses" VALUES(5254182,145536,1,0,'معشوق چو بر مراد و رای تو بود',NULL,NULL);
INSERT INTO "verses" VALUES(5254183,145536,1,1,'نام تو میان عشقباران نبرند',NULL,NULL);
INSERT INTO "verses" VALUES(5254184,145537,0,0,'یاران چو به هم دست در آغوش کنید',NULL,NULL);
INSERT INTO "verses" VALUES(5254185,145537,0,1,'این گردش چرخ را فراموش کنید',NULL,NULL);
INSERT INTO "verses" VALUES(5254186,145537,1,0,'چون دور به من رسد نباشم بر جای',NULL,NULL);
INSERT INTO "verses" VALUES(5254187,145537,1,1,'بر یاد من این دور مرا نوش کنید',NULL,NULL);
INSERT INTO "verses" VALUES(5254188,145538,0,0,'عشق آتش غم در دل ویرانه نهاد',NULL,NULL);
INSERT INTO "verses" VALUES(5254189,145538,0,1,'زنجیر بلا بر من دیوانه نهاد',NULL,NULL);
INSERT INTO "verses" VALUES(5254190,145538,1,0,'بر من نگذشت هیچ نیکی و بدی',NULL,NULL);
INSERT INTO "verses" VALUES(5254191,145538,1,1,'تا پای مبارک اندر آن خانه نهاد',NULL,NULL);
INSERT INTO "verses" VALUES(5254192,145539,0,0,'ای هر نفسی نهاده بر کف ساغر',NULL,NULL);
INSERT INTO "verses" VALUES(5254193,145539,0,1,'عیبی نبود ز دوستان یاد آور',NULL,NULL);
INSERT INTO "verses" VALUES(5254194,145539,1,0,'ما را می لعل نیست جز در دیده',NULL,NULL);
INSERT INTO "verses" VALUES(5254195,145539,1,1,'می را که تو در پیاله داری می‌خور',NULL,NULL);
INSERT INTO "verses" VALUES(5254196,145540,0,0,'بنگر به چمن جمال فرخندهٔ گل',NULL,NULL);
INSERT INTO "verses" VALUES(5254197,145540,0,1,'گه گریهٔ ابر بین و گه خندهٔ گل',NULL,NULL);
INSERT INTO "verses" VALUES(5254198,145540,1,0,'سرو ار چه به آزادی خود می‌نازد',NULL,NULL);
INSERT INTO "verses" VALUES(5254199,145540,1,1,'از راستیی که داشت شد بندهٔ گل',NULL,NULL);
INSERT INTO "verses" VALUES(5254200,145541,0,0,'هرگز نکنم سوز تو ای شمع چگل',NULL,NULL);
INSERT INTO "verses" VALUES(5254201,145541,0,1,'پیدا من اگر چه هست کار مشکل',NULL,NULL);
INSERT INTO "verses" VALUES(5254202,145541,1,0,'دردی که من از عشق تو دارم حاصل',NULL,NULL);
INSERT INTO "verses" VALUES(5254203,145541,1,1,'دل داند و من دانم و من دانم و دل',NULL,NULL);
INSERT INTO "verses" VALUES(5254204,145543,0,0,'جانا چو شبی با تو به روز آوردم',NULL,NULL);
INSERT INTO "verses" VALUES(5254205,145543,0,1,'گر بی تو دمی برآورم نامردم',NULL,NULL);
INSERT INTO "verses" VALUES(5254206,145543,1,0,'از مرگ نترسم پس از این کآب حیات',NULL,NULL);
INSERT INTO "verses" VALUES(5254207,145543,1,1,'از چشمهٔ نوش لب لعلت خوردم',NULL,NULL);
INSERT INTO "verses" VALUES(5254208,145544,0,0,'من ترک تو ای نگار آسان ندهم',NULL,NULL);
INSERT INTO "verses" VALUES(5254209,145544,0,1,'تا پیش زمرد خطت جان ندهم',NULL,NULL);
INSERT INTO "verses" VALUES(5254210,145544,1,0,'یاقوت لبت که قوت جان است مرا',NULL,NULL);
INSERT INTO "verses" VALUES(5254211,145544,1,1,'آن را به دو صد هزار مرجان ندهم',NULL,NULL);
INSERT INTO "verses" VALUES(5254212,145545,0,0,'آن به که بجامِ باده دل شاد کنیم',NULL,NULL);
INSERT INTO "verses" VALUES(5254213,145545,0,1,'وز نآمده و گذشته کم یاد کنیم',NULL,NULL);
INSERT INTO "verses" VALUES(5254214,145545,1,0,'وین عاریتی روانِ زندانی را',NULL,NULL);
INSERT INTO "verses" VALUES(5254215,145545,1,1,'یک لحظه ز بندِ عقل آزاد کنیم',NULL,NULL);
INSERT INTO "verses" VALUES(5254216,145546,0,0,'ای آن که نهند مهر و ماه از تمکین',NULL,NULL);
INSERT INTO "verses" VALUES(5254217,145546,0,1,'بر خاک جناب تو شب و روز جبین',NULL,NULL);
INSERT INTO "verses" VALUES(5254218,145546,1,0,'با دست زبان و دل تنگم منشان',NULL,NULL);
INSERT INTO "verses" VALUES(5254219,145546,1,1,'بر آتش انتظار و فارغ منشین',NULL,NULL);
INSERT INTO "verses" VALUES(5254220,145547,0,0,'گر مست نیی مست نمایی می‌کن',NULL,NULL);
INSERT INTO "verses" VALUES(5254221,145547,0,1,'دیوانه نیی کاله ربایی می‌کن',NULL,NULL);
INSERT INTO "verses" VALUES(5254222,145547,1,0,'تا خلق ز اسرار تو واقف نشوند',NULL,NULL);
INSERT INTO "verses" VALUES(5254223,145547,1,1,'رندی بنمای و پارسایی می‌کن',NULL,NULL);
INSERT INTO "verses" VALUES(5254224,145548,0,0,'ای رای تو صحرای امل پیمودن',NULL,NULL);
INSERT INTO "verses" VALUES(5254225,145548,0,1,'تا چند بر آفتاب گل اندودن',NULL,NULL);
INSERT INTO "verses" VALUES(5254226,145548,1,0,'گر در دهن شیر شوی بهر طمع',NULL,NULL);
INSERT INTO "verses" VALUES(5254227,145548,1,1,'آخر نه شکار کور خواهی بودن',NULL,NULL);
INSERT INTO "verses" VALUES(5254228,145549,0,0,'حافظ ورق سخن‌گذاری طی کن',NULL,NULL);
INSERT INTO "verses" VALUES(5254229,145549,0,1,'وین خامهٔ تزویر و ریا را پی کن',NULL,NULL);
INSERT INTO "verses" VALUES(5254230,145549,1,0,'خاموش نشین که وقت خاموشی توست',NULL,NULL);
INSERT INTO "verses" VALUES(5254231,145549,1,1,'دم در کش و جام عشق را پر می کن',NULL,NULL);
INSERT INTO "verses" VALUES(5254232,145550,0,0,'آنم که پدید گشتم از قدرتِ تو',NULL,NULL);
INSERT INTO "verses" VALUES(5254233,145550,0,1,'پرورده شدم به ناز در نعمت تو',NULL,NULL);
INSERT INTO "verses" VALUES(5254234,145550,1,0,'صد سال به امتحان گنه خواهم کرد',NULL,NULL);
INSERT INTO "verses" VALUES(5254235,145550,1,1,'یا جرم من است بیش یا رحمت تو',NULL,NULL);
INSERT INTO "verses" VALUES(5254236,145551,0,0,'تا کی بود این جور و جفا کردن تو',NULL,NULL);
INSERT INTO "verses" VALUES(5254237,145551,0,1,'بیهوده دل خلایق آزردن تو',NULL,NULL);
INSERT INTO "verses" VALUES(5254238,145551,1,0,'تیغی است به دست اهل دل خون آلود',NULL,NULL);
INSERT INTO "verses" VALUES(5254239,145551,1,1,'گر در تو رسد خون تو در گردن تو',NULL,NULL);
INSERT INTO "verses" VALUES(5254240,145552,0,0,'گل را دیدم نشسته بر تخت شهی',NULL,NULL);
INSERT INTO "verses" VALUES(5254241,145552,0,1,'گفتا بشنو راستی از مرد رهی',NULL,NULL);
INSERT INTO "verses" VALUES(5254242,145552,1,0,'من طفلم و بی گنه مرا می‌سوزند',NULL,NULL);
INSERT INTO "verses" VALUES(5254243,145552,1,1,'ای وای به تو که پیری و پر گنهی',NULL,NULL);
INSERT INTO "verses" VALUES(5254244,145553,0,0,'گل گفت اگر دستگهی داشتمی',NULL,NULL);
INSERT INTO "verses" VALUES(5254245,145553,0,1,'بگریختمی اگر رهی داشتمی',NULL,NULL);
INSERT INTO "verses" VALUES(5254246,145553,1,0,'با بی گنهی مرا چنین می‌سوزند',NULL,NULL);
INSERT INTO "verses" VALUES(5254247,145553,1,1,'ای وای به من گر گنهی داشتمی',NULL,NULL);
INSERT INTO "verses" VALUES(5254248,145554,0,0,'کم گوی به جز مصلحت خویش مگوی',NULL,NULL);
INSERT INTO "verses" VALUES(5254249,145554,0,1,'چیزی که نپرسند تو خود پیش مگوی',NULL,NULL);
INSERT INTO "verses" VALUES(5254250,145554,1,0,'گوشِ تو دو دادند و زبانِ تو یکی',NULL,NULL);
INSERT INTO "verses" VALUES(5254251,145554,1,1,'یعنی که دو بشنو و یکی بیش مگوی',NULL,NULL);
INSERT INTO "verses" VALUES(5255368,145726,0,0,'اگر ز کوی تو بویی به من رساند باد','اگر از نشان تو بویی به من برساند باد / به مژدگانی جان و جهان را به باد خواهم داد',NULL);
INSERT INTO "verses" VALUES(5255369,145726,0,1,'به مژده جان و جهان را به باد خواهم داد',NULL,NULL);
INSERT INTO "verses" VALUES(5255370,145726,1,0,'اگر چه گرد برانگیختی ز هستی من','اگر چه هستی وجود مرا به خاک (گرد) کشیدی / از این گرد و خاک هیچی دامن تو را نگیرد',NULL);
INSERT INTO "verses" VALUES(5255371,145726,1,1,'غباری از من خاکی به دامنت مرساد',NULL,NULL);
INSERT INTO "verses" VALUES(5255372,145726,2,0,'چو در به روی من ای نور دیده در بستی','چون در به روی من ای نور چشمانم ، چشم خود بستی / دگر جهان در خوشی به روی من نمی گشاید',NULL);
INSERT INTO "verses" VALUES(5255373,145726,2,1,'دگر جهان در شادی به روی من نگشاد',NULL,NULL);
INSERT INTO "verses" VALUES(5255374,145726,3,0,'خیال روی توام دیده می‌کند پُر خون','به تو فکر میکنم چشمانم میشود پر خون / به هوای گیسوی تو عمرم را داده ام بر باد',NULL);
INSERT INTO "verses" VALUES(5255375,145726,3,1,'هوای زلف توام عمر می‌دهد بر باد',NULL,NULL);
INSERT INTO "verses" VALUES(5255376,145726,4,0,'نه در برابر چشمی نه غایب از نظرم','نه در مقابل چشمان من هستی و نه پنهان از نظر من / نه یادی از من میکنی و نه میروی از یادم',NULL);
INSERT INTO "verses" VALUES(5255377,145726,4,1,'نه یاد می‌کنی از من، نه می‌روی از یاد',NULL,NULL);
INSERT INTO "verses" VALUES(5255378,145726,5,0,'به جای طعنه اگر تیغ می‌زند دشمن','به جای زخم زبان اگر تیغ می زند دشمن / از دوست دست نداریم ، دگر هر چه بادا باد',NULL);
INSERT INTO "verses" VALUES(5255379,145726,5,1,'ز دوست دست نداریم، هر چه باداباد',NULL,NULL);
INSERT INTO "verses" VALUES(5255380,145726,6,0,'ز دست عشق تو عبدالمجید جان نبرد','از دست عشق تو عبدالمجید دگر جانی ندارد / که جان از رنج شیرین نمیخواهد فرهاد',NULL);
INSERT INTO "verses" VALUES(5255381,145726,6,1,'که جان ز محنت شیرین نمی‌برد فرهاد',NULL,NULL);
INSERT INTO "verses" VALUES(5306175,2274,9,0,'فلک غلامی حافظ کنون به طوع کُنَد',NULL,NULL);
INSERT INTO "verses" VALUES(5306176,2274,9,1,'که اِلتِجا به درِ دولت شما آورد',NULL,NULL);
