BEGIN TRANSACTION;
CREATE TABLE categories (id INTEGER PRIMARY KEY, slug TEXT NOT NULL, title TEXT NOT NULL);
CREATE TABLE poems (
  id INTEGER PRIMARY KEY,            -- ganjoor poem id
  category_id INTEGER NOT NULL REFERENCES categories(id),
  number INTEGER NOT NULL,           -- order within category
  title TEXT NOT NULL,
  plain_text TEXT NOT NULL,          -- hemistichs one per line, no diacritics
  summary_fa TEXT,
  summary_en TEXT,
  source TEXT,
  UNIQUE(category_id, number)
);
جز کوی تو رهگذر نیامد ما را
خواب ار چه خوش آمد همه را در عهدت
حقا که به چشم در نیامد ما را','هوش مصنوعی: در این ابیات، شاعر بیان می‌کند که هیچ چیز جز عشق و وجود محبوب برای او معنا ندارد. او می‌گوید که حتی اگر خواب‌ها و آرزوها خوشایند باشند، همچنان از حقیقت و واقعیت دورند و تنها عشق محبوب است که در زندگی‌اش جلوه‌گر است. به عبارتی، همه چیز در سایه محبوبش به بی‌معنی می‌رسد.',NULL,'ویکی‌درج');
پنهان ز رقیب سفله بستیز و بیا
مشنو سخن خصم که بنشین و مرو
بشنو ز من این نکته که برخیز و بیا','هوش مصنوعی: در این شعر شاعر از مخاطب دعوت می‌کند که شراب شادی‌بخش را بیفکند و با او بیاید. او همچنین تاکید می‌کند که به سخن دشمنان گوش نکند و به جای نشستن و انتظار، باید حرکت کند و به جمع آنها بپیوندد.',NULL,'ویکی‌درج');
گفتم دهنت گفت زهی حب نبات
گفتم سخن تو گفت حافظ گفتا
شادی همه لطیفه گویان صلوات','هوش مصنوعی: در این شعر، شاعر به زیبایی و طراوت معشوق اشاره می‌کند. او از لبه معشوق به آب حیات و از دهانش به شیرینی نبات می‌گوید. همچنین، اشاره‌ای به سخنان حافظ دارد و در پایان با بیان اینکه شادی در گفتار لطیفه‌گویان است، به دعا و صلوات ختم می‌کند. به طور کلی، شعر به عشق و زیبایی معشوق می‌پردازد و فضایی شاداب و معنوی ایجاد می‌کند.',NULL,'ویکی‌درج');
آیینه به دست و روی خود می آراست
دستارچه ای پیشکشش کردم گفت
وصلم طلبی زهی خیالی که تو راست','هوش مصنوعی: در این بیت، شاعر به توصیف ماهی می‌پردازد که به زیبایی و قامت بلندی شبیه سرو است. این ماهی آیینه‌ای در دست دارد و به زیبایی خود می‌رسد. وقتی شاعر هدایتی به او می‌کند، ماهی به طعنه می‌گوید که شما فقط در خیال وصال من هستید و این آرزو محال است.',NULL,'ویکی‌درج');
پنداشتمش که در میان چیزی هست
پیداست از آن میان چو بربست کمر
تا من ز کمر چه طرف خواهم بربست','هوش مصنوعی: در این بیت شاعر به احساسی اشاره دارد که هنگام در آغوش گرفتن معشوق به او دست زده است و در ذهنش فکر کرده که در این آغوش چیزی وجود دارد. اما وقتی متوجه می‌شود که عشق و ارتباط واقعی میان آنها وجود ندارد، دچار سردرگمی می‌شود و نمی‌داند باید در این ارتباط چه قدمی بردارد. این شعر به عمق احساسات و نااطمینانی در روابط عاشقانه پرداخته است.',NULL,'ویکی‌درج');
تا بنده تو شده ست تابنده شده ست
زان روی که از شعاع نور رخ تو
خورشید منیر و ماه تابنده شده ست','هوش مصنوعی: در این بیت‌ها به زیبایی و درخشش چهره فردی اشاره شده است. شاعر می‌گوید که خورشید به خاطر تابش نور او به خدمتش درآمده و به نوعی به او تمدن و روشنایی بخشیده است. همچنین از این نکته اشاره می‌شود که نور چهره او باعث درخشش ماه و خورشید شده است. به طور کلی، این اشعار بر زیبایی و شکوه شخصیتی متمرکز هستند که نورش، دیگران را نیز درخشان کرده است.',NULL,'ویکی‌درج');
در دیده من ز هجر خاری دگر است
من جهد همی کنم قضا می گوید
بیرون ز کفایت تو کاری دگر است','هوش مصنوعی: در این ابیات شاعر از احساس سنگینی و غم ناشی از جدایی سخن می‌گوید. او هر روز با بار سنگینی از درد و حسرت مواجه است و در چشمش نشانه‌های جدایی نمایان است. تلاش او برای مقابله با این درد بی‌نتیجه است و قضا و قدر نشان می‌دهد که کاری فراتر از توان او وجود دارد.',NULL,'ویکی‌درج');
گرد خط او چشمه کوثر بگرفت
دل ها همه در چاه زنخدان انداخت
وآنگه سر چاه را به عنبر بگرفت','هوش مصنوعی: در این ابیات، شاعر به زیبایی و نورانیّت معشوقش اشاره می‌کند. او می‌گوید که چون چهره معشوق مانند خورشید درخشنده است، دل‌ها در زیبایی‌های او غرق شده و به نوعی به دام افتاده‌اند. همچنین، شاعر با ذکر چاه و عنبر، به عمق عشق و عطری که از معشوق به مشام می‌رسد اشاره می‌کند و این تصاویری از جذابیت و جاذبه عشق را به تصویر می‌کشد.',NULL,'ویکی‌درج');
وز بستر عافیت برون خواهم خفت
باور نکنی خیال خود را بفرست
تا درنگرد که بی  تو چون خواهم خفت','هوش مصنوعی: در این شعر، شاعر از غم و اندوه عمیق خود صحبت می‌کند و به این فکر می‌کند که امشب در شرایطی دشوار و دردناک بخوابد. او تصمیم دارد از زندگی راحت و آسوده خود فاصله بگیرد و به حالت ناراحتی و پریشانی برود. در انتها، به کسی که دوستش دارد اشاره می‌کند و می‌خواهد بگوید که بدون او نمی‌تواند راحت بخوابد و به خواب عمیق برود.',NULL,'ویکی‌درج');
نی حال دل سوخته دل بتوان گفت
غم در دل تنگ من از آن است که نیست
یک دوست که با او غم دل بتوان گفت','هوش مصنوعی: در این شعر، شاعر از احساس درد و غم خود سخن می‌گوید و می‌گوید که نمی‌توان تمامی احساسات و حال خود را به خوبی بیان کرد. او اشاره می‌کند که غم درونش به خاطر نبودن دوستی است که بتواند با او درد دل کند و با او از غم‌هایش صحبت کند.',NULL,'ویکی‌درج');
چون مست شدم جام جفا را سرداد
پر آب دو دیده و پر از آتش دل
خاک ره او شدم به بادم برداد','هوش مصنوعی: در این شعر، شاعر به وفا و محبت اشاره می‌کند که ابتدا به او بهره‌مند شده است. اما بعد از آن، به حالتی مبتلا می‌شود که دچار غم و جفا می‌گردد. او با چشمانی پر از اشک و دلی پر از آتش، نهایتاً خود را در مسیر محبوبش، مانند خاکی می‌بیند که به باد سپرده شده است.',NULL,'ویکی‌درج');
نی لذت مستی اش الم می ارزد
نه هفت هزار ساله شادی جهان
این محنت هفت روزه غم می ارزد','هوش مصنوعی: این اشعار به نقد دنیا و زیبایی‌های ظاهری آن می‌پردازد. شاعر تأکید می‌کند که خوشی‌ها و لذت‌های دنیوی با درد و رنجی که ممکن است به همراه داشته باشند، ارزش کمتری دارند. او همچنین بیان می‌کند که حتی شادی‌های طولانی مدت دنیا به اندازه‌ی درد و محنت‌های کوتاه‌مدت ارزشمند نیستند. به طور کلی، شاعر به بی‌امیدی و ناپایداری لذت‌های دنیوی اشاره می‌کند.',NULL,'ویکی‌درج');
هر پاک روی که بود تردامن شد
گویند شب آبستن و این است عجب
کـ او مرد ندید از چه آبستن شد','هوش مصنوعی: در این اشعار، شاعر به این نکته اشاره می‌کند که هر دوستی که از وفا صحبت می‌کند، ممکن است به عنوان یک دشمن ظاهر شود. همچنین، هر کسی که به نظر پاک و معصوم می‌رسد، ممکن است به دلیل طمع و خیانت ناپاک باشد. در انتها، شاعر با اشاره به شب آبستن، از عجیب بودن وضعیتی سخن می‌گوید که در آن مردی وجود ندارد، در حالی که وضعیت بارداری به وجود آمده است. این ابیات به تضادها و مشکلات در روابط انسانی اشاره دارد.',NULL,'ویکی‌درج');
نرگس به هوای می قدح ساز شود
فارغ دل آن کسی که مانند حباب
هم در سر میخانه سرانداز شود','این شعر در وصف بهار و شادی و میخانه و پایکوبی است. شاعر در آن می‌گوید خوشبخت کسی است که در فصل بهار و در کنار زیبایان، غرور و باد خود را کنار گذاشته و در مستی و شوق به پایکوبی و رقص بپردازد.',NULL,'ویکی‌درج');
وز غصه کناره جوی می باید بود
این مدت عمر ما چو گل ده روز است
خندان لب و تازه روی می باید بود','هوش مصنوعی: این شعر به اهمیت لذت بردن از زندگی اشاره دارد. شاعر می‌گوید باید در کنار شادی‌ها و لذت‌ها (مثل می) بود و از غم‌ها دوری جست. عمر ما کوتاه و همانند یک گل است که به زودی پژمرده می‌شود، پس باید با لبخند و تازگی زندگی کرد و از لحظات استفاده کرد.',NULL,'ویکی‌درج');
شادی به دلم از او بسی می آید
پیوسته از آن روی کنم همدمی اش
کز رنگ وی ام بوی کسی می آید','هوش مصنوعی: این شعر درباره شادی و زیبایی است که از دوستی و همصحبتی با کسی ناشی می‌شود. شاعر احساس خوشحالی و آرامش می‌کند و معتقد است که این شادی ناشی از وجود شخص محبوبش است که جاذبه و عطر خاصی دارد. او از طریق تماس با آن شخص، احساسات مثبت و تازه‌ای را تجربه می‌کند.',NULL,'ویکی‌درج');
وز گردش روزگار می لرز چو بید
گفتی که پس از سیاه رنگی نبود
پس موی سیاه من چرا گشت سفید','هوش مصنوعی: در این ابیات شاعر از ناامیدی و ناپایداری زندگی می‌گوید. او به چرخ فلک و تغییرات زندگی اشاره دارد و احساس می‌کند که با گذر زمان دچار لرزش و تزلزل می‌شود. همچنین، از سیاه بودن موی خود در گذشته یاد می‌کند و تعجب می‌کند که چرا اکنون رنگ مویش سفید شده است، به نوعی از گذر عمر و تغییرات طبیعی آن شکایت دارد.',NULL,'ویکی‌درج');
با سبزخطان باده ناب اولاتر
عالم همه سر به سر رباطی ست خراب
در جای خراب هم خراب اولاتر','هوش مصنوعی: این اشعار به این موضوع اشاره دارند که در دوران جوانی، نوشیدن شراب بهترین انتخاب است، و لذت بردن از شراب ناب در کنار زندگی سبز و زیبا از هر چیز دیگری بهتر است. همچنین، زندگی دنیا به گونه‌ای است که همه در حال گذران روزگار هستند و حتی در مکان‌های خراب، زندگی و لذت‌بردن از آن اهمیت بیشتری دارد.',NULL,'ویکی‌درج');
خوش خوش بر از ایشان بتوان خورد به زر
نرگس که کله دار جهان است ببین
کاو نیز چگونه سر درآورد به زر','هوش مصنوعی: این ابیات از شعر به زیبایی اشاره به ارزشمندی و زیبایی "خوبان" یا انسان‌های زیبا دارند. بیان می‌کند که این خوبان می‌توانند دیگران را به دام خود بکشانند و از آنها بهره‌مند شوند. همچنین به نرگس، که نماد زیبایی و جذابیت است، اشاره می‌کند و می‌گوید که حتی او نیز تحت تأثیر این زیبایی و ثروت قرار می‌گیرد. در کل، این شعر به قدرت و تأثیر زیبایی در جهان اشاره دارد.',NULL,'ویکی‌درج');
و آغاز پری نهاد پیمانه عمر
بیدار شو ای خواجه که خوش خوش بکشد
حمال زمانه رخت از خانه عمر','هوش مصنوعی: این شعر به مفهوم گذر زمان و ناپایداری زندگی اشاره دارد. شاعر از بیداری و آگاهی نسبت به عمر و زمانه صحبت می‌کند و به خواننده توصیه می‌کند که از خواب غفلت بیرون بیاید و به حقیقت گذران عمر خود پی ببرد. زندگی مانند یک پیمانه‌ای است که از آن می‌کاهد و افراد باید به این واقعیت توجه کنند.',NULL,'ویکی‌درج');
بر خسته دلان رند خمار مگیر
صوفی چو تو رسم رهروان می دانی
بر مردم رند نکته بسیار مگیر','هوش مصنوعی: این شعر به بیان احساسات عاشقانه و درد دل می‌پردازد. شاعر از یار خود می‌خواهد که او را نرنجاند و به خستگی‌های دل عاشقان توجه کند. او از صوفی نیز می‌خواهد که با دانایی خود درباره‌ی راه‌رفتگان، از رندان نکته‌ای بیشتر بیان نکند و به احساسات آن‌ها احترام بگذارد. در کل، شعر بر اهمیت توجه به دل شکسته‌ها و حساسیت‌های عاشقی تأکید دارد.',NULL,'ویکی‌درج');
گفتم من سودازده را کار بساز
گفتا که لبم بگیر و زلفم بگذار
در عیش خوش  آویز نه در عمر دراز','هوش مصنوعی: شاعر به عشق و نیاز خود اشاره می‌کند و از محبوبش می‌خواهد که در لحظه‌های خوش زندگی همراهش باشد. او از محبوب می‌خواهد که لبش را بگیرد و زلفش را بر سر بگذارد، تا از زندگی لذت ببرد و به جای نگرانی برای عمر طولانی، در لحظات شاد زیست کند.',NULL,'ویکی‌درج');
اسرار کرم ز خواجه قنبر پرس
گر طالب فیض حق به صدقی حافظ
سر چشمه آن ز ساقی کوثر پرس','هوش مصنوعی: این شعر به اهمیت جستجوی دانش و فیض الهی اشاره دارد. شاعر به مردی توصیه می‌کند که به جای پرسیدن از دیگران، به سراغ منبع اصلی و حقیقت برود. در اینجا، از "ساقی کوثر" به عنوان نماینده فیض و معنویت یاد می‌شود و بر لزوم سوال از منبع اصلی تاکید می‌شود. به طور کلی، این شعر بر ارزش حقایق و دانش عمیق تاکید دارد.',NULL,'ویکی‌درج');
یا رب که فسون ها برواد از یادش
آن گوش که حلقه کرد در گوش جمال
آویزه در ز نظم حافظ بادش','هوش مصنوعی: در این ابیات شاعر به زیبایی چشم و گوش معشوقه‌اش اشاره می‌کند. او چشم معشوق را به سحر بابل تشبیه کرده و از خداوند می‌خواهد که جادوی آن را از یاد نبرد. همچنین گوش معشوق را که در زیبایی معشوق حلقه کرده، به حافظ تعلق می‌دهد و امیدوار است این زیبایی در اشعار حافظ جاویدان بماند.',NULL,'ویکی‌درج');
با روی نکو شراب روشن درکش
با اهل هنر گوی گریبان بگشای
وز نااهلان تمام دامن درکش','هوش مصنوعی: در این شعر، شاعر از دوستش می‌خواهد که با استفاده از زیبایی‌های زندگی و هنر، از ناپاکی‌های دشمنان و نااهلان فاصله بگیرد و به زندگی خوشگذرانی بپردازد. او تاکید دارد که با روی زیبا و نوشیدن شراب روشن، به شادی بپردازد و در کنار هنرمندان، از مشکلات دور بماند.',NULL,'ویکی‌درج');
چون جامه ز تن برکشد آن مشکین خال
در سینه دلش ز نازکی بتوان دید
ماننده سنگ خاره در آب زلال','شاعر در این رباعی از زیبایی بی‌نظیر محبوب خود می‌گوید که تن روشن و لطیف او همچون ماه است و وقتی که عریان می‌شود در تن او که مانند آب، زلال است دلی بی‌رحم از سنگ خارا را می‌توان دید.',NULL,'ویکی‌درج');
بربست مشاطه وار پیرایه گل
از سایه به خورشید اگرت هست امان
خورشیدرخی طلب کن و سایه گل','هوش مصنوعی: در این شعر، شاعر به زیبایی و لطافت گل اشاره می‌کند که با وزش باد بهاری (باد صبا) شکوفا می‌شود. مشاطه (آرایشگر) به زیبایی گل پرداخته و آن را آراسته می‌کند. شاعر همچنین به تضاد سایه و خورشید می‌پردازد و می‌گوید اگر می‌خواهی از نور خورشید بهره‌مند شوی، باید به دنبال روشنایی و زیبایی خورشید باشی، نه در سایه گل.',NULL,'ویکی‌درج');
تا بستانی کام جهان از لب جام
در جام جهان چو تلخ و شیرین به هم است
این از لب یار خواه و آن از لب جام','در این شعر، شاعر از غنیمت شمردن شادی و مستی و لذت بردن از معشوق گفته است. او می‌گوید که تلخی و شیرینی همواره در زندگی وجود دارد و این دو همیشه همراه هم هستند پس باید تلخی را از جام می گرفت و شیرینی را از لب معشوق.',NULL,'ویکی‌درج');
وز حسرت لعل آبدارت مردم
قصه نکنم دراز کوتاه کنم
بازآ بازآ کز انتظارت مردم','هوش مصنوعی: این اشعار بیانگر longing و آرزوی عمیق شاعر برای نزدیکی و ارتباط با محبوبش است. شاعر از خواسته‌ها و احساسات خود می‌گوید و به شدت به انتظار محبوبش دلبسته است. او همچنین به حسرت و آرزوهایش اشاره می‌کند و از تکرار این احساسات سخن می‌گوید. در نهایت، او از محبوبش می‌خواهد که بازگردد.',NULL,'ویکی‌درج');
وز دور فلک چیست که نافع دارم
با هر که بگفتم که تو را دوست شدم
شد دشمن من وه که چه طالع دارم','هوش مصنوعی: این شعر بیانگر احساس ناامیدی و حسرت شاعر است. او سال ها برای دستیابی به آرزوهایش تلاش کرده، اما از دوری زمانه و نفعی که نمی‌بیند، دلسرد شده است. در نهایت، او با گفتن محبتش به دیگران، دشمنی و سوء تفاهم را تجربه کرده و از سرنوشتش غمگین است.',NULL,'ویکی‌درج');
در عشق ز نیک و بد ندارم جز غم
یک همدم باوفا ندیدم جز درد
یک مونس نامزد ندارم جز غم','هوش مصنوعی: در این شعر، شاعر از زندگی خود و احساساتش سخن می‌گوید و به این نکته اشاره می‌کند که تمام عمرش پر از غم بوده است. او در عشق خود نه تنها به نیکی بر نمی‌خورد، بلکه فقط غم را تجربه کرده و هیچ دوست وفاداری جز درد نداشته است. در نهایت، تنها مونس او همچنان غم است.',NULL,'ویکی‌درج');
با لشگر غم چه بایدت کوشیدن
سبز است لبت ساغر از او دور مدار
می بر لب سبزه خوش بود نوشیدن','هوش مصنوعی: در این اشعار، شاعر به این نکته اشاره می‌کند که در برابر غم و مشکلات، نوشیدن باده می‌تواند راهی برای فراموشی و تسکین باشد. او همچنین به زیبایی لبان محبوبش اشاره می‌کند و می‌گوید که با در دست داشتن ساغر، به دور از غم، بهتر است از این می نوشید. در کل، متن به تمایل انسان به لذت و شادی در برابر اندوه اشاره دارد.',NULL,'ویکی‌درج');
حیران و خجل نرگس مخمور از تو
گل با تو برابری کجا یارد کرد
کـ او نور ز مه دارد و مه نور از تو','هوش مصنوعی: در این شعر، غنچه‌ای شرمنده و نرگسی حیران از زیبایی و جذابیت محبوب سخن می‌گوید. شاعر به این نکته اشاره می‌کند که هیچ گلی نمی‌تواند با محبوب مقایسه شود، زیرا او زیبایی و درخششی دارد که از نور ماه نشأت می‌گیرد.',NULL,'ویکی‌درج');
افسوس که تیر جنگ می بارد از او
بس زود ملول گشتی از هم نفسان
آه از دل تو که سنگ می بارد از او','هوش مصنوعی: در این شعر، شاعر از جذابیت و فریبندگی چشم معشوق صحبت می‌کند که دل را می‌برد، اما در عین حال، درد و زخم جنگ و جدایی از او را نیز احساس می‌کند. او به زودی از ناپایداری و دل‌زدگی دوستانش ناراحت می‌شود و به دل خود افسوس می‌خورد که همچون سنگی سرد شده است.',NULL,'ویکی‌درج');
سر دل من به صد زبانش می گو
می گو نه بدان سان که ملالش گیرد
می گو سخنی و در میانش می گو','هوش مصنوعی: در این ابیات، شاعر از باد درخواست می‌کند که رازهای درونش را به کسانی بگوید. او می‌خواهد که این صحبت‌ها به گونه‌ای باشد که احساس ناخرسندی نکند و بین سخن‌ها، معانی عمیق‌تری نهفته باشد. شاعر به نوعی دلتنگی و نیاز به بیان احساساتش اشاره دارد.',NULL,'ویکی‌درج');
یاقوت لبت در عدن پرورده
همچون لب خود مدام جان می پرور
زان راح که روحیست به تن پرورده','هوش مصنوعی: این شعر به زیبایی و جذابیت محبوبی اشاره دارد که به مانند سایه‌اش همواره در زندگی‌اش حضور دارد. او دارای لبی جذاب و دلربا است که گویی در بهشتی مانند عدن پرورش یافته است. شاعر احساس می‌کند که این زیبایی و جذابیت جان او را زنده نگه‌داشته و روحش را در بدنش پرورش می‌دهد.',NULL,'ویکی‌درج');
دل خوش کن و بر صبر گمار اندیشه
کو صبر و چه دل کآنچه دلش می خوانند
یک قطره خون است و هزار اندیشه','هوش مصنوعی: در این شعر، شاعر به اندیشه و تفکر اشاره می‌کند و می‌گوید که نباید زیاد به افکار منفی اهمیت داد. او تأکید می‌کند که باید به دل خود آرامش بدهیم و بر صبر تکیه کنیم. همچنین، او اشاره می‌کند که صبر و دل، همچون خون و اندیشه، بسیار نازک و شکننده هستند و نباید به راحتی فراموش شوند. در نهایت، شاعر تشویق می‌کند که از افکار منفی دوری کنیم و به خوشبختی و آرامش دل بپردازیم.',NULL,'ویکی‌درج');
وان ساغر چون نگار بر دستم نه
آن می که چو زنجیر بپیچد بر خود
دیوانه شدم بیار بر دستم نه','هوش مصنوعی: در این ابیات شاعر از نوشیدن شراب و لذت‌های آن صحبت می‌کند. او اشاره دارد که جام و ساغر را در دست ندارد و می‌خواهد می‌ای را بیاورند که او را به وجد آورده و دیوانه‌اش کند. به طور کلی، این اشعار بیان‌گر اشتیاق به شادی و رهایی از قید و بندهاست.',NULL,'ویکی‌درج');
کنجی و فراغتی و یک شیشه می
چون گرم شود ز باده ما را رگ و پی
منت نبریم یک جو از حاتم طی','هوش مصنوعی: در این شعر، شاعر به لذتی که با دوستان و نوشیدنی‌ها به دست می‌آید، اشاره می‌کند. او دعوت می‌کند که با خوشحالی و موسیقی، در کنار یکدیگر زمان بگذرانند و در فضایی آرام و بدون دغدغه، از لحظات زندگی بهره‌مند شوند. همچنین تأکید دارد که نیازی به منت‌گذاری و بزرگ‌منشی ندارد و اهمیت بر لذت و شادی است.',NULL,'ویکی‌درج');
ما را نگذارد که درآییم ز پای
تا کی بود این گرگ ربایی بنمای
سرپنجه دشمن افکن ای شیر خدای','این شعر درباره امید به رهایی و نجات از ظلم، توسط شخصی عدالت‌پیشه و بسیار قدرتمند است. شاعر در این شعر می‌گوید که او محافظ ماست و در این شعر او را خطاب قرار داده و از او در برابر ظلم، یاری می‌طلبد.',NULL,'ویکی‌درج');
با جور زمانه یار یاری کردی
از دست جوانی ام چو بربود عنان
پیری چو رکاب پایداری کردی','این شعر درباره شکایت از روزگار از دست رفته جوانی‌است که در آن شاعر آرزو می‌کند که کاش دست تقدیر و یار در این روز سختی پیری به‌او کمک می‌کردند تا بتواند سختی‌ها را تحمل کند.',NULL,'ویکی‌درج');
ای بس که خراب باده و جام شوی
ما عاشق و رند و مست و عالم سوزیم
با ما منشین اگر نه بدنام شوی','هوش مصنوعی: این بیت‌ها به احوال عاشقان و مستی آنها اشاره دارد. شاعر از تجربه‌ی افتادن در دام عشق و مستی سخن می‌گوید و می‌گوید اگر کسی مانند او در این دام بیفتد، ممکن است به شهرت و بدنامی دچار شود. او تاکید می‌کند که عاشقان باید با یکدیگر در این حالت مستی و عشق همراه شوند.',NULL,'ویکی‌درج');
چرا بایدت دیگری محتسب
و من یتق الله یجعل له
و یرزقه من حیث لا یحتسب','هوش مصنوعی: در این شعر از شاعر، به فرد توصیه می‌شود که ابتدا خود را بررسی کند و از خود بپرسد که نیک و بد او چیست. به او یادآوری می‌شود که نیازی به شخص دیگری برای قضاوت ندارد. همچنین به اهمیت تقوای الهی اشاره می‌شود و اینکه هر که تقوای خدا را پیشه کند، خداوند روزی‌اش را از جایی که انتظار ندارد، فراهم می‌کند.',NULL,'ویکی‌درج');
چه سود چون دل دانا و چشم بینا نیست
سرای قاضی یزد ارچه منبع فضل است
خلاف نیست که علم نظر در آن جا نیست','هوش مصنوعی: این شعر به این نکته اشاره دارد که صرف وجود مکان‌های علمی و فرهنگی مانند مدرسه یا قاضی‌خانه‌ها، وقتی که دل و چشم افراد بینا و آگاه نباشد، فاقد ارزش واقعی است. به عبارت دیگر، علم و فضل باید در دل و ذهن افراد وجود داشته باشد تا به حقیقت و معنای واقعی خود برسد.',NULL,'ویکی‌درج');
آصف عهد زمان جان جهان تورانشاه
